import { useState } from "react";
import { Rocket } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";

interface BoostButtonProps {
  userId: string;
  targetType: "post" | "profile";
  targetId: string;
  isBoosted?: boolean;
  onBoosted?: () => void;
  variant?: "icon" | "full";
}

export function BoostButton({ userId, targetType, targetId, isBoosted, onBoosted, variant = "icon" }: BoostButtonProps) {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  const cost = targetType === "post" ? 5 : 10;
  const label = targetType === "post" ? "Post Boost" : "Profil Boost";

  const handleBoost = async () => {
    setLoading(true);
    const { data, error } = await supabase.rpc("purchase_boost", {
      _user_id: userId,
      _target_type: targetType,
      _target_id: targetId,
      _hours: 24,
    });
    setLoading(false);

    if (error) {
      toast.error("Boost başarısız: " + error.message);
      return;
    }

    const result = data as any;
    if (!result?.success) {
      toast.error(result?.error || "Boost başarısız");
      return;
    }

    toast.success(`🚀 ${label} aktif! (${cost} DC, 24 saat)`);
    setOpen(false);
    onBoosted?.();
  };

  if (isBoosted) {
    return (
      <div className="flex items-center gap-1 text-[10px] font-semibold text-neon">
        <Rocket className="h-3 w-3" /> Boost Aktif
      </div>
    );
  }

  if (variant === "full") {
    return (
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogTrigger asChild>
          <Button variant="outline" size="default" className="border-neon/30 text-neon hover:bg-neon/10">
            <Rocket className="h-4 w-4" /> Boost ({cost} DC)
          </Button>
        </DialogTrigger>
        <BoostDialogContent label={label} cost={cost} loading={loading} onConfirm={handleBoost} />
      </Dialog>
    );
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <button
          className="text-muted-foreground hover:text-neon transition-colors px-2 py-1.5 rounded-md hover:bg-neon/10 text-xs"
          title={`${label} (${cost} DC)`}
        >
          <Rocket className="h-4 w-4" />
        </button>
      </DialogTrigger>
      <BoostDialogContent label={label} cost={cost} loading={loading} onConfirm={handleBoost} />
    </Dialog>
  );
}

function BoostDialogContent({ label, cost, loading, onConfirm }: { label: string; cost: number; loading: boolean; onConfirm: () => void }) {
  return (
    <DialogContent className="max-w-sm">
      <DialogHeader>
        <DialogTitle className="flex items-center gap-2">
          <Rocket className="h-5 w-5 text-neon" /> {label}
        </DialogTitle>
        <DialogDescription>
          {cost} DC karşılığında 24 saat boyunca öne çıkarılır. Feed'de üst sıralarda görünür ve 🚀 etiketi alır.
        </DialogDescription>
      </DialogHeader>
      <DialogFooter>
        <Button variant="neon" onClick={onConfirm} disabled={loading} className="w-full">
          {loading ? "İşleniyor..." : `🚀 Boost Et (${cost} DC)`}
        </Button>
      </DialogFooter>
    </DialogContent>
  );
}

