import type { AnchorHTMLAttributes, MouseEvent, ReactNode } from "react";
import { openExternal } from "@/lib/native";

interface Props extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "onClick" | "href"> {
  href: string;
  children: ReactNode;
}

/**
 * Harici link wrapper — Native (Android APK) içinde Capacitor Browser ile
 * uygulamadan ÇIKMADAN açar. Web'de yeni sekme.
 *
 * Rudaw / ANF / K24 gibi tüm harici linkler için kullanılmalı.
 */
export function ExternalLink({ href, children, onAuxClick, rel, target, ...rest }: Props) {
  const handleClick = (e: MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    openExternal(href);
  };
  return (
    <a
      {...rest}
      href={href}
      onClick={handleClick}
      target={target ?? "_blank"}
      rel={rel ?? "noopener noreferrer"}
    >
      {children}
    </a>
  );
}

