import { RefreshCw } from "lucide-react";

interface Props {
  pullDistance: number;
  refreshing: boolean;
  threshold: number;
}

/**
 * Sticky overlay görsel — sayfa üstüne yerleştirilir.
 * Pull mesafesine göre opacity ve rotate uygular.
 */
export function PullToRefreshIndicator({ pullDistance, refreshing, threshold }: Props) {
  if (pullDistance <= 0 && !refreshing) return null;

  const progress = Math.min(pullDistance / threshold, 1);
  const rotate = progress * 180;
  const opacity = Math.min(progress + 0.2, 1);

  return (
    <div
      className="fixed left-1/2 top-0 z-[60] flex h-12 w-12 -translate-x-1/2 items-center justify-center rounded-full bg-black/80 backdrop-blur-md border border-amber-400/40 shadow-lg shadow-amber-500/20 transition-transform"
      style={{
        transform: `translate(-50%, ${Math.max(pullDistance - 20, 12)}px)`,
        opacity,
      }}
      aria-live="polite"
    >
      <RefreshCw
        className={`h-5 w-5 text-amber-400 ${refreshing ? "animate-spin" : ""}`}
        style={{ transform: refreshing ? undefined : `rotate(${rotate}deg)` }}
      />
    </div>
  );
}

