import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from "@/components/ui/dialog";
import { AlertTriangle, ShieldX, Coins, Fingerprint } from "lucide-react";
import { toast } from "sonner";

export function DeleteAccountDialog() {
  const { user, signOut } = useAuth();
  const [open, setOpen] = useState(false);
  const [confirmText, setConfirmText] = useState("");
  const [loading, setLoading] = useState(false);
  const [scheduledAt, setScheduledAt] = useState<string | null>(null);

  useEffect(() => {
    if (!user) return;
    supabase.from("profiles").select("deletion_scheduled_at").eq("user_id", user.id).maybeSingle()
      .then(({ data }) => setScheduledAt((data as any)?.deletion_scheduled_at ?? null));
  }, [user, open]);

  const isPending = !!scheduledAt;

  const handleDelete = async () => {
    if (confirmText !== "SİL") {
      toast.error("Onay için 'SİL' yazın");
      return;
    }
    setLoading(true);
    try {
      const { error } = await supabase.rpc("request_account_deletion");
      if (error) throw error;
      toast.success("Hesap silme talebi alındı. 30 gün içinde iptal edebilirsiniz.");
      setOpen(false);
      setTimeout(async () => { await signOut(); }, 1500);
    } catch (err: any) {
      toast.error(err.message || "İşlem başarısız");
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async () => {
    setLoading(true);
    try {
      const { error } = await supabase.rpc("cancel_account_deletion");
      if (error) throw error;
      toast.success("Silme talebi iptal edildi. Hesabınız aktif.");
      setScheduledAt(null);
    } catch (err: any) {
      toast.error(err.message || "İptal başarısız");
    } finally {
      setLoading(false);
    }
  };

  if (isPending) {
    const date = new Date(scheduledAt!);
    return (
      <div className="rounded-xl border border-destructive/30 bg-destructive/5 p-4">
        <div className="flex items-start gap-3">
          <AlertTriangle className="h-5 w-5 text-destructive mt-0.5" />
          <div className="flex-1">
            <p className="text-sm font-semibold text-destructive">Hesap Silme Beklemede</p>
            <p className="text-xs text-muted-foreground mt-1">
              Hesabınız <strong>{date.toLocaleDateString("tr-TR")}</strong> tarihinde kalıcı olarak silinecek.
            </p>
            <Button onClick={handleCancel} disabled={loading} variant="outline" size="sm" className="mt-3">
              {loading ? "İşleniyor..." : "Silme Talebini İptal Et"}
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="flex w-full items-center gap-3 rounded-xl border border-destructive/20 px-3 py-3 hover:bg-destructive/10 transition-all"
      >
        <ShieldX className="h-4 w-4 text-destructive" />
        <span className="text-sm font-medium text-destructive">Hesabımı ve Verilerimi Sil</span>
      </button>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10 mb-2">
              <AlertTriangle className="h-6 w-6 text-destructive" />
            </div>
            <DialogTitle>Hesabınızı silmek istediğinize emin misiniz?</DialogTitle>
            <DialogDescription className="pt-2">
              Bu işlem geri alınabilir ancak <strong>30 gün içinde</strong> iptal etmezseniz tüm
              verileriniz kalıcı olarak silinir.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-2 my-2">
            <DataRow icon={<Coins className="h-4 w-4 text-amber-400" />} text="Tüm DiravCash bakiyeniz silinir" />
            <DataRow icon={<Fingerprint className="h-4 w-4 text-blue-400" />} text="KurdID numaranız iptal edilir ve geri alınamaz" />
            <DataRow icon={<ShieldX className="h-4 w-4 text-destructive" />} text="Sohbet, gönderi, hikaye ve tüm içerikleriniz silinir" />
          </div>

          <div className="mt-2">
            <label className="text-xs font-medium text-muted-foreground">
              Onaylamak için <strong className="text-destructive">SİL</strong> yazın:
            </label>
            <input
              type="text"
              value={confirmText}
              onChange={(e) => setConfirmText(e.target.value.toUpperCase())}
              placeholder="SİL"
              className="mt-1 h-10 w-full rounded-lg border border-border bg-background px-3 text-sm focus:border-destructive focus:outline-none"
            />
          </div>

          <DialogFooter className="flex-col-reverse sm:flex-row gap-2">
            <Button variant="outline" onClick={() => setOpen(false)} disabled={loading} className="flex-1">
              Vazgeç
            </Button>
            <Button
              variant="destructive"
              onClick={handleDelete}
              disabled={loading || confirmText !== "SİL"}
              className="flex-1"
            >
              {loading ? "İşleniyor..." : "30 Gün Sonra Sil"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

function DataRow({ icon, text }: { icon: React.ReactNode; text: string }) {
  return (
    <div className="flex items-start gap-2 rounded-lg bg-muted/30 px-3 py-2">
      <div className="mt-0.5">{icon}</div>
      <p className="text-xs text-foreground">{text}</p>
    </div>
  );
}

