import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Megaphone, Send, Trash2, AlertCircle, AlertTriangle, Info, Loader2 } from "lucide-react";
import { toast } from "sonner";

interface Announcement {
  id: string;
  title: string;
  body: string;
  severity: string;
  is_active: boolean;
  created_at: string;
}

const SEVERITIES = [
  { key: "info", label: "Info", icon: Info, color: "from-blue-500/30 to-blue-700/30 border-blue-400/40 text-blue-200" },
  { key: "warning", label: "Warning", icon: AlertTriangle, color: "from-amber-500/30 to-amber-700/30 border-amber-400/40 text-amber-200" },
  { key: "critical", label: "Critical", icon: AlertCircle, color: "from-red-500/30 to-red-700/30 border-red-400/40 text-red-200" },
] as const;

export function AnnouncementPushTool({ adminId }: { adminId: string }) {
  const [list, setList] = useState<Announcement[]>([]);
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [severity, setSeverity] = useState<"info" | "warning" | "critical">("info");
  const [pushing, setPushing] = useState(false);

  const load = useCallback(async () => {
    const { data } = await supabase
      .from("global_announcements")
      .select("id,title,body,severity,is_active,created_at")
      .order("created_at", { ascending: false })
      .limit(20);
    setList((data as any) || []);
  }, []);

  useEffect(() => { load(); }, [load]);

  const push = async () => {
    if (!title.trim() || !body.trim()) {
      toast.error("Title and body required");
      return;
    }
    setPushing(true);
    const { error } = await supabase.from("global_announcements").insert({
      title: title.trim(),
      body: body.trim(),
      severity,
      is_active: true,
      created_by: adminId,
    });
    if (error) { toast.error("Push failed"); setPushing(false); return; }
    toast.success("📡 Announcement pushed to all citizens");
    setTitle(""); setBody(""); setSeverity("info");
    setPushing(false);
    load();
  };

  const toggleActive = async (id: string, current: boolean) => {
    await supabase.from("global_announcements").update({ is_active: !current }).eq("id", id);
    load();
  };

  const remove = async (id: string) => {
    await supabase.from("global_announcements").delete().eq("id", id);
    setList((l) => l.filter((a) => a.id !== id));
    toast.success("Removed");
  };

  return (
    <div className="space-y-3 px-2 pb-4">
      {/* Composer */}
      <div className="rounded-2xl bg-gradient-to-br from-blue-500/10 to-indigo-700/10 border border-blue-400/30 p-3 space-y-2.5">
        <div className="flex items-center gap-2">
          <Megaphone className="w-4 h-4 text-blue-300" />
          <h3 className="text-xs font-semibold">Global Announcement</h3>
          <Badge variant="outline" className="ml-auto text-[9px] border-blue-400/40 text-blue-200">Diplomatic Push</Badge>
        </div>

        <Input
          placeholder="Announcement title…"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          maxLength={80}
          className="h-9 text-xs bg-white/5 border-white/10"
        />
        <Textarea
          placeholder="Body — broadcast to every citizen on the platform…"
          value={body}
          onChange={(e) => setBody(e.target.value)}
          maxLength={400}
          rows={3}
          className="text-xs bg-white/5 border-white/10 resize-none"
        />

        <div className="grid grid-cols-3 gap-1.5">
          {SEVERITIES.map((s) => {
            const Icon = s.icon;
            const active = severity === s.key;
            return (
              <button
                key={s.key}
                onClick={() => setSeverity(s.key)}
                className={`relative rounded-xl border p-2 text-[10px] font-semibold transition-all ${active ? `bg-gradient-to-br ${s.color}` : "bg-white/[0.03] border-white/10 text-white/50"}`}
              >
                <Icon className="w-3.5 h-3.5 mx-auto mb-0.5" />
                {s.label}
              </button>
            );
          })}
        </div>

        <Button
          onClick={push}
          disabled={pushing || !title.trim() || !body.trim()}
          className="w-full h-9 text-xs bg-gradient-to-r from-blue-500 to-indigo-600 hover:from-blue-600 hover:to-indigo-700 text-white font-bold"
        >
          {pushing ? <Loader2 className="w-3.5 h-3.5 mr-1.5 animate-spin" /> : <Send className="w-3.5 h-3.5 mr-1.5" />}
          Broadcast to All Citizens
        </Button>
      </div>

      {/* History */}
      <div className="space-y-2">
        <div className="text-[10px] uppercase tracking-widest opacity-50 px-1">Recent Broadcasts</div>
        {list.length === 0 && (
          <div className="text-center text-xs opacity-50 py-6">No announcements yet</div>
        )}
        {list.map((a) => {
          const sev = SEVERITIES.find((s) => s.key === a.severity) || SEVERITIES[0];
          const Icon = sev.icon;
          return (
            <div key={a.id} className={`rounded-xl border p-2.5 bg-gradient-to-r ${sev.color} ${!a.is_active && "opacity-50"}`}>
              <div className="flex items-start gap-2">
                <Icon className="w-4 h-4 mt-0.5 shrink-0" />
                <div className="flex-1 min-w-0">
                  <div className="text-xs font-bold truncate">{a.title}</div>
                  <div className="text-[10px] opacity-80 line-clamp-2 mt-0.5">{a.body}</div>
                  <div className="text-[9px] opacity-60 mt-1">{new Date(a.created_at).toLocaleString("nl-NL")}</div>
                </div>
                <div className="flex flex-col gap-1">
                  <button
                    onClick={() => toggleActive(a.id, a.is_active)}
                    className={`text-[9px] px-1.5 py-0.5 rounded ${a.is_active ? "bg-white/20" : "bg-white/5"}`}
                  >
                    {a.is_active ? "ON" : "OFF"}
                  </button>
                  <button onClick={() => remove(a.id)} className="text-[9px] px-1.5 py-0.5 rounded bg-rose-500/30 hover:bg-rose-500/50">
                    <Trash2 className="w-2.5 h-2.5" />
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

