    const candidateIds = Array.from(
      new Set([
        ...((activeCreatorsRes.data || []).map((r: any) => r.user_id)),
        ...((verifiedRes.data || []).map((r: any) => r.user_id)),
      ]),
    );

    if (candidateIds.length === 0) { setRows([]); setLoading(false); return; }

    const [profilesRes, followsRes, viewsRes] = await Promise.all([
      supabase
        .from("profiles")
        .select("user_id, display_name, avatar_url, kurd_id, is_verified_creator, is_premium")
        .in("user_id", candidateIds),
      supabase
        .from("follows")
        .select("following_id")
        .in("following_id", candidateIds),
      supabase
        .from("keka_videos")
        .select("user_id, view_count")
        .in("user_id", candidateIds)
        .gte("created_at", since),
    ]);

    const followerMap = new Map<string, number>();
    (followsRes.data || []).forEach((r: any) => {
      followerMap.set(r.following_id, (followerMap.get(r.following_id) || 0) + 1);
    });

    const viewMap = new Map<string, number>();
    (viewsRes.data || []).forEach((r: any) => {
      viewMap.set(r.user_id, (viewMap.get(r.user_id) || 0) + (r.view_count || 0));
    });

    const merged: CreatorRow[] = (profilesRes.data || []).map((p: any) => ({
      user_id: p.user_id,
      display_name: p.display_name,
      avatar_url: p.avatar_url,
      kurd_id: p.kurd_id,
      is_verified_creator: !!p.is_verified_creator,
      is_premium: !!p.is_premium,
      followers: followerMap.get(p.user_id) || 0,
      views30d: viewMap.get(p.user_id) || 0,
    }));

    merged.sort((a, b) => b.followers + b.views30d / 10 - (a.followers + a.views30d / 10));
    setRows(merged);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const toggleVerify = async (row: CreatorRow) => {
    setActing(row.user_id);
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ is_verified_creator: !row.is_verified_creator })
        .eq("user_id", row.user_id);
      if (error) throw error;
      toast.success(row.is_verified_creator ? "Doğrulama kaldırıldı" : "Altın Yaratıcı verildi 👑");
      setRows((prev) => prev.map((r) => r.user_id === row.user_id
        ? { ...r, is_verified_creator: !r.is_verified_creator } : r));
    } catch (e: any) {
      toast.error(e.message || "İşlem başarısız");
    } finally {
      setActing(null);
    }
  };

  const filtered = rows.filter((r) => {
    if (filter === "verified" && !r.is_verified_creator) return false;
    if (filter === "eligible" && !(r.followers >= FOLLOWER_TARGET && r.views30d >= VIEWS_TARGET)) return false;
    if (search.trim()) {
      const q = search.toLowerCase();
      return (r.display_name || "").toLowerCase().includes(q) || (r.kurd_id || "").includes(q);
    }
    return true;
  });

  return (
    <div className="space-y-3">
      <div className="flex gap-2">
        <div className="flex-1 relative">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="İsim veya Kurd-ID ara…"
            className="h-9 pl-8 text-xs bg-white/[0.03] border-white/10"
          />
        </div>
        <Button size="sm" variant="outline" className="h-9 text-xs" onClick={load}>
          Yenile
        </Button>
      </div>

      <div className="flex gap-1.5 text-[11px]">
        {(["eligible", "verified", "all"] as const).map((f) => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={`px-2.5 py-1 rounded-full border transition-all ${
              filter === f
                ? "bg-amber-400/20 border-amber-400/40 text-amber-200"
                : "border-white/10 text-muted-foreground hover:text-foreground"
            }`}
          >
            {f === "eligible" ? "Uygun" : f === "verified" ? "Doğrulanmış" : "Tümü"}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="py-10 text-center"><Loader2 className="h-5 w-5 animate-spin inline" /></div>
      ) : filtered.length === 0 ? (
        <div className="py-10 text-center text-xs text-muted-foreground">Sonuç yok.</div>
      ) : (
        <div className="space-y-1.5">
          {filtered.map((r) => {
            const meets = r.followers >= FOLLOWER_TARGET && r.views30d >= VIEWS_TARGET;
            return (
              <div
                key={r.user_id}
                className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.03] p-2.5"
              >
                <Avatar className="h-9 w-9">
                  <AvatarImage src={r.avatar_url || undefined} />
                  <AvatarFallback>{(r.display_name || "?").slice(0, 1)}</AvatarFallback>
                </Avatar>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1">
                    <span className="text-xs font-semibold truncate">{r.display_name || "—"}</span>
                    {r.is_verified_creator && <BadgeCheck className="h-3 w-3 text-amber-300" />}
                    {r.is_premium && <Crown className="h-3 w-3 text-amber-400" />}
                  </div>
                  <div className="flex items-center gap-2 text-[10px] text-muted-foreground mt-0.5">
                    <span className="flex items-center gap-0.5"><Users className="h-2.5 w-2.5" /> {r.followers.toLocaleString("tr-TR")}</span>
                    <span className="flex items-center gap-0.5"><Eye className="h-2.5 w-2.5" /> {r.views30d.toLocaleString("tr-TR")}</span>
                    {meets && <Badge variant="outline" className="h-4 text-[9px] px-1 border-amber-400/40 text-amber-300">UYGUN</Badge>}
                  </div>
                </div>
                <Button
                  size="sm"
                  variant={r.is_verified_creator ? "outline" : "default"}
                  className={`h-8 text-[11px] ${r.is_verified_creator ? "" : "bg-amber-400 text-black hover:bg-amber-300"}`}
                  disabled={acting === r.user_id}
                  onClick={() => toggleVerify(r)}
                >
                  {acting === r.user_id ? <Loader2 className="h-3 w-3 animate-spin" /> : r.is_verified_creator ? "Kaldır" : "Doğrula"}
                </Button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

