import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Users, Wallet, Vote, ShieldCheck } from "lucide-react";
import { StatCard } from "./StatCard";
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  BarChart,
  Bar,
} from "recharts";

interface DayPoint {
  day: string;
  users: number;
  treasury: number;
  voters: number;
}

interface TreasuryRpcRow {
  total_treasury_dc: number;
  locked_dc: number;
  circulating_dc: number;
  total_citizens: number;
  verified_citizens: number;
  avg_keka: number;
  active_roles: number;
}

function formatDay(d: Date) {
  return d.toLocaleDateString("en-US", { day: "2-digit", month: "short" });
}

function dateOnly(s: string) {
  return new Date(s).toISOString().slice(0, 10);
}

export function ExecutiveOverview() {
  const [series, setSeries] = useState<DayPoint[]>([]);
  const [stats, setStats] = useState({ users: 0, treasury: 0, voters: 0, verified: 0, totalProfiles: 0, lockedDc: 0, circulating: 0, activeRoles: 0, avgKeka: 0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const since = new Date();
    since.setDate(since.getDate() - 13);
    const sinceIso = since.toISOString();

    Promise.all([
      supabase.from("profiles").select("created_at,is_verified", { count: "exact" }),
      supabase.from("wallet_ledger").select("amount,type,created_at").gte("created_at", sinceIso),
      supabase.from("referendum_votes").select("created_at").gte("created_at", sinceIso),
      supabase.rpc("admin_get_treasury_stats"),
    ]).then(([profilesRes, ledgerRes, votesRes, treasuryRes]) => {
      const profiles = profilesRes.data || [];
      const ledger = ledgerRes.data || [];
      const votes = votesRes.data || [];

      // Build 14-day buckets
      const buckets: Record<string, DayPoint> = {};
      for (let i = 13; i >= 0; i--) {
        const d = new Date();
        d.setDate(d.getDate() - i);
        const key = d.toISOString().slice(0, 10);
        buckets[key] = { day: formatDay(d), users: 0, treasury: 0, voters: 0 };
      }

      // Cumulative user growth across buckets
      const sortedProfiles = [...profiles].sort((a: any, b: any) => a.created_at.localeCompare(b.created_at));
      let cumulative = 0;
      const startCount = sortedProfiles.filter((p: any) => p.created_at < Object.keys(buckets)[0]).length;
      cumulative = startCount;
      const profileByDay: Record<string, number> = {};
      sortedProfiles.forEach((p: any) => {
        const k = dateOnly(p.created_at);
        profileByDay[k] = (profileByDay[k] || 0) + 1;
      });
      Object.keys(buckets).forEach((k) => {
        cumulative += profileByDay[k] || 0;
        buckets[k].users = cumulative;
      });

      // Treasury liquidity (running net: topup - withdraw)
      let treasury = 0;
      ledger.forEach((l: any) => {
        const k = dateOnly(l.created_at);
        if (!buckets[k]) return;
        const amt = Number(l.amount) || 0;
        const sign = ["topup", "deposit", "earn", "credit"].includes(l.type) ? 1 : -1;
        buckets[k].treasury += sign * amt;
      });
      Object.keys(buckets).forEach((k) => {
        treasury += buckets[k].treasury;
        buckets[k].treasury = Math.max(0, treasury);
      });

      // Active voters per day
      votes.forEach((v: any) => {
        const k = dateOnly(v.created_at);
        if (buckets[k]) buckets[k].voters += 1;
      });

      const arr = Object.values(buckets);
      setSeries(arr);

      // Live treasury stats from RPC (includes vault, locked, circulating, roles)
      const t = (treasuryRes.data as TreasuryRpcRow[] | null)?.[0];
      const liveTreasury = Number(t?.total_treasury_dc ?? 0);

      // Backfill the chart's last bucket with live treasury so the visual matches the headline number
      if (arr.length > 0) {
        arr[arr.length - 1].treasury = liveTreasury || arr[arr.length - 1].treasury;
      }

      setStats({
        users: t?.total_citizens ?? profilesRes.count ?? profiles.length,
        treasury: liveTreasury,
        voters: arr.reduce((s, p) => s + p.voters, 0),
        verified: t?.verified_citizens ?? profiles.filter((p: any) => p.is_verified).length,
        totalProfiles: profiles.length,
        lockedDc: Number(t?.locked_dc ?? 0),
        circulating: Number(t?.circulating_dc ?? 0),
        activeRoles: Number(t?.active_roles ?? 0),
        avgKeka: Number(t?.avg_keka ?? 0),
      });
      setLoading(false);
    });
  }, []);

  const verificationRate = stats.totalProfiles ? Math.round((stats.verified / stats.totalProfiles) * 100) : 0;

  return (
    <div className="space-y-4 px-2 pb-4">
      {/* Stats grid */}
      <div className="grid grid-cols-2 gap-2.5">
        <StatCard icon={Users} label="Total Citizens" value={stats.users.toLocaleString()} delta={12} iconColor="text-blue-400" iconBg="bg-blue-500/15" glow="rgba(59,130,246,0.4)" />
        <StatCard icon={Wallet} label="Hazine (DC)" value={stats.treasury.toLocaleString()} delta={8} iconColor="text-amber-400" iconBg="bg-amber-500/15" glow="rgba(251,191,36,0.4)" />
        <StatCard icon={Vote} label="Active Voters (14d)" value={stats.voters.toLocaleString()} delta={24} iconColor="text-purple-400" iconBg="bg-purple-500/15" glow="rgba(168,85,247,0.4)" />
        <StatCard icon={ShieldCheck} label="KYC Rate" value={`${verificationRate}%`} delta={3} iconColor="text-emerald-400" iconBg="bg-emerald-500/15" glow="rgba(16,185,129,0.4)" />
      </div>

      {/* Treasury breakdown */}
      {!loading && stats.treasury > 0 && (
        <div className="rounded-2xl border border-amber-400/20 bg-gradient-to-br from-amber-500/[0.06] to-transparent p-3">
          <div className="flex items-center justify-between mb-2">
            <div>
              <div className="text-[10px] uppercase tracking-widest text-amber-300/70">Vakıf Hazinesi</div>
              <div className="text-[9px] opacity-50">Foundation-controlled community fund</div>
            </div>
            <Wallet className="h-4 w-4 text-amber-300" />
          </div>
          <div className="grid grid-cols-3 gap-2 text-center">
            <div className="rounded-lg bg-white/[0.03] border border-white/5 p-2">
              <div className="text-[9px] uppercase tracking-widest opacity-50">Kilitli</div>
