import { HUB_ICON_NAMES, GRADIENT_PRESETS, getHubIcon } from "@/lib/hubIcons";

type BannerForm = Partial<HubBanner> & { title: string; link_url: string };
type AppForm = Partial<HubApp> & { label: string; link_url: string };

const EMPTY_BANNER: BannerForm = {
  title: "", subtitle: "", app_name: "", app_tag: "", cta_label: "Aç",
  link_url: "/", link_type: "internal", icon_name: "Sparkles",
  gradient: GRADIENT_PRESETS[0], icon_gradient: GRADIENT_PRESETS[0],
  sort_order: 0, is_active: true,
};

const EMPTY_APP: AppForm = {
  label: "", description: "", category: "global", icon_name: "Sparkles",
  icon_gradient: GRADIENT_PRESETS[0], icon_color: "text-white",
  link_url: "/", link_type: "internal", badge: "", sort_order: 0, is_active: true,
};

export function HubManager() {
  return (
    <div className="space-y-4">
      <Tabs defaultValue="banners">
        <TabsList className="w-full grid grid-cols-2 bg-white/[0.03] border border-white/10">
          <TabsTrigger value="banners" className="text-xs gap-1"><ImageIcon className="h-3 w-3" /> Banners</TabsTrigger>
          <TabsTrigger value="apps" className="text-xs gap-1"><Grid3x3 className="h-3 w-3" /> Apps</TabsTrigger>
        </TabsList>
        <TabsContent value="banners"><BannersTab /></TabsContent>
        <TabsContent value="apps"><AppsTab /></TabsContent>
