// =================================================================
// BANNERS
// =================================================================
function BannersTab() {
  const { data, isLoading, refetch } = useHubBanners(true);
  const { upsertBanner, deleteBanner, toggleBanner } = useHubMutations(refetch);
  const [editing, setEditing] = useState<BannerForm | null>(null);
  const [pendingDelete, setPendingDelete] = useState<HubBanner | null>(null);

  if (isLoading) return <div className="flex justify-center py-8"><Loader2 className="h-5 w-5 animate-spin" /></div>;

  const move = async (b: HubBanner, dir: -1 | 1) => {
    await upsertBanner({ id: b.id, title: b.title, link_url: b.link_url, sort_order: (b.sort_order ?? 0) + dir });
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between px-1">
        <p className="text-xs text-muted-foreground">{data?.length ?? 0} banner</p>
        <Button size="sm" onClick={() => setEditing({ ...EMPTY_BANNER, sort_order: (data?.length ?? 0) + 1 })}>
          <Plus className="h-3.5 w-3.5 mr-1" /> Yeni Banner
        </Button>
      </div>

      <div className="space-y-2">
        {data?.map((b) => {
          const Icon = getHubIcon(b.icon_name);
          return (
            <Card key={b.id} className="p-3 bg-card/60 border-white/10">
              <div className="flex items-center gap-3">
                <div className={`flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-xl ${b.gradient}`}>
                  <Icon className="h-5 w-5 text-white" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-semibold truncate">{b.title}</p>
                    {!b.is_active && <Badge variant="outline" className="text-[9px]">Kapalı</Badge>}
                  </div>
                  <p className="text-[11px] text-muted-foreground truncate">{b.subtitle || b.link_url}</p>
                  <p className="text-[10px] text-muted-foreground/70 mt-0.5">#{b.sort_order} · {b.link_type}</p>
                </div>
                <div className="flex flex-col gap-1">
                  <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => move(b, -1)}><ArrowUp className="h-3 w-3" /></Button>
                  <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => move(b, 1)}><ArrowDown className="h-3 w-3" /></Button>
                </div>
                <Switch checked={b.is_active} onCheckedChange={(v) => toggleBanner({ id: b.id, is_active: v })} />
                <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => setEditing(b)}><Pencil className="h-3.5 w-3.5" /></Button>
                <Button size="icon" variant="ghost" className="h-7 w-7 text-destructive" onClick={() => setPendingDelete(b)}><Trash2 className="h-3.5 w-3.5" /></Button>
              </div>
            </Card>
          );
        })}
      </div>

      <BannerEditor
        banner={editing}
        onClose={() => setEditing(null)}
        onSave={async (b) => {
          try {
            await upsertBanner(b);
            toast.success("Banner kaydedildi");
            setEditing(null);
          } catch (e: any) { toast.error(e.message); }
        }}
      />

      <SovereignSealConfirm
        open={!!pendingDelete}
        onOpenChange={(o) => !o && setPendingDelete(null)}
        title="Banner Sil"
        description="Bu banner kalıcı olarak silinecek. Eylem audit log'a kaydedilir."
        target={pendingDelete?.title}
        requireReason
        reasonLabel="Silme gerekçesi"
        destructive
        actionLabel="Sil"
        onConfirm={async () => {
          if (!pendingDelete) return;
          try {
            await deleteBanner(pendingDelete.id);
            toast.success("Banner silindi (mühürlü)");
            setPendingDelete(null);
          } catch (e: any) {
            toast.error(e.message);
            throw e;
          }
        }}
      />
    </div>
  );
}

function BannerEditor({ banner, onClose, onSave }: { banner: BannerForm | null; onClose: () => void; onSave: (b: BannerForm) => void }) {
  const [form, setForm] = useState<BannerForm | null>(banner);

  // Sync form whenever the dialog opens with a different banner
  useEffect(() => {
    if (banner) setForm(banner);
  }, [banner]);

  if (!banner || !form) return null;

  const update = (patch: Partial<BannerForm>) => setForm({ ...form, ...patch });

  return (
    <Dialog open={!!banner} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-h-[85vh] overflow-y-auto">
        <DialogHeader><DialogTitle>{form.id ? "Banner Düzenle" : "Yeni Banner"}</DialogTitle></DialogHeader>

