          </div>
          <Field label="Buton Metni"><Input value={form.cta_label ?? "Aç"} onChange={(e) => update({ cta_label: e.target.value })} /></Field>
          <div className="grid grid-cols-3 gap-2">
            <div className="col-span-2">
              <Field label="Link URL *"><Input value={form.link_url} onChange={(e) => update({ link_url: e.target.value })} placeholder="/wallet veya https://..." /></Field>
            </div>
            <Field label="Tip">
              <Select value={form.link_type ?? "internal"} onValueChange={(v) => update({ link_type: v as any })}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="internal">Dahili</SelectItem>
                  <SelectItem value="external">Harici</SelectItem>
                </SelectContent>
              </Select>
            </Field>
          </div>
          <Field label="İkon">
            <IconPicker value={form.icon_name ?? "Sparkles"} onChange={(v) => update({ icon_name: v })} />
          </Field>
          <Field label="Kart Gradient">
            <GradientPicker value={form.gradient ?? GRADIENT_PRESETS[0]} onChange={(v) => update({ gradient: v })} />
          </Field>
          <Field label="İkon Gradient">
            <GradientPicker value={form.icon_gradient ?? GRADIENT_PRESETS[0]} onChange={(v) => update({ icon_gradient: v })} />
          </Field>
          <div className="grid grid-cols-2 gap-2 items-end">
            <Field label="Sıra"><Input type="number" value={form.sort_order ?? 0} onChange={(e) => update({ sort_order: Number(e.target.value) })} /></Field>
            <div className="flex items-center gap-2 pb-2">
              <Switch checked={form.is_active ?? true} onCheckedChange={(v) => update({ is_active: v })} />
              <Label className="text-xs">Aktif</Label>
            </div>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>İptal</Button>
          <Button onClick={() => onSave(form)} disabled={!form.title || !form.link_url}>Kaydet</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

