import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Loader2, ShieldCheck, ShieldX, Clock, Search, BadgeCheck, FileText, Camera } from "lucide-react";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";

interface KycRequest {
  id: string;
  user_id: string;
  full_name: string;
  date_of_birth: string;
  document_type: string;
  document_url: string;
  selfie_url: string;
  submitted_at: string;
  profile?: {
    display_name: string;
    avatar_url: string | null;
    kurd_id: string | null;
    kurd_id_tier: string;
    city: string;
  };
}

export function KycVerificationQueue() {
  const [pending, setPending] = useState<KycRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [acting, setActing] = useState<string | null>(null);
  const [signedUrls, setSignedUrls] = useState<Record<string, { doc?: string; selfie?: string }>>({});

  const load = useCallback(async () => {
    setLoading(true);
    const { data: reqs } = await supabase
      .from("kyc_requests")
      .select("id,user_id,full_name,date_of_birth,document_type,document_url,selfie_url,submitted_at")
      .eq("status", "pending")
      .order("submitted_at", { ascending: false })
      .limit(50);

    const list = (reqs as KycRequest[]) || [];
    if (list.length > 0) {
      const userIds = list.map((r) => r.user_id);
      const { data: profiles } = await supabase
        .from("profiles")
        .select("user_id,display_name,avatar_url,kurd_id,kurd_id_tier,city")
        .in("user_id", userIds);
      const byId: Record<string, any> = {};
      (profiles || []).forEach((p: any) => { byId[p.user_id] = p; });
      list.forEach((r) => { r.profile = byId[r.user_id]; });
    }
    setPending(list);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const getSignedUrl = async (path: string) => {
    const { data } = await supabase.storage.from("kyc-documents").createSignedUrl(path, 300);
    return data?.signedUrl;
  };

  const loadDocs = async (req: KycRequest) => {
    if (signedUrls[req.id]) return;
    const [doc, selfie] = await Promise.all([
      getSignedUrl(req.document_url),
      getSignedUrl(req.selfie_url),
    ]);
    setSignedUrls((s) => ({ ...s, [req.id]: { doc, selfie } }));
  };

  const decide = async (id: string, decision: "approved" | "rejected") => {
    setActing(id);
    let reason: string | null = null;
    if (decision === "rejected") {
      reason = window.prompt("Red sebebi (opsiyonel):") || null;
    }
    const { data, error } = await supabase.rpc("review_kyc_request", {
      _request_id: id,
      _decision: decision,
      _reason: reason ?? undefined,
    });
    if (error || !(data as any)?.success) {
      toast.error((data as any)?.error || error?.message || "İşlem başarısız");
      setActing(null);
      return;
    }
    setPending((p) => p.filter((r) => r.id !== id));
    toast.success(decision === "approved" ? "Vatandaş doğrulandı ✓" : "Talep reddedildi");
    setActing(null);
  };

  const filtered = pending.filter((p) =>
    !search ||
    p.full_name?.toLowerCase().includes(search.toLowerCase()) ||
    p.profile?.display_name?.toLowerCase().includes(search.toLowerCase()) ||
    p.profile?.kurd_id?.includes(search)
  );

  return (
    <div className="space-y-3 px-2 pb-4">
      <div className="rounded-2xl bg-white/[0.03] border border-white/10 p-3">
        <div className="flex items-center gap-2 mb-2">
          <ShieldCheck className="w-4 h-4 text-emerald-400" />
          <h3 className="text-xs font-semibold">KYC Verification Queue</h3>
          <Badge variant="outline" className="ml-auto text-[10px] border-emerald-400/40 text-emerald-300">{pending.length} pending</Badge>
        </div>
        <div className="relative">
          <Search className="absolute left-2.5 top-2 h-3.5 w-3.5 text-muted-foreground" />
          <Input
            placeholder="Search by name or Kurd-ID…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="h-8 text-xs pl-8 bg-white/5 border-white/10"
          />
        </div>
      </div>

      {loading && (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-5 h-5 animate-spin opacity-50" />
        </div>
      )}

      {!loading && filtered.length === 0 && (
        <div className="text-center py-12 opacity-60">
          <BadgeCheck className="w-10 h-10 mx-auto mb-2 text-emerald-400/60" />
          <div className="text-xs">All caught up — no pending verifications.</div>
        </div>
      )}

      {!loading && filtered.map((req) => {
        const p = req.profile;
        const urls = signedUrls[req.id];
        return (
          <div key={req.id} className="rounded-2xl bg-white/[0.03] border border-white/10 p-3">
            <div className="flex items-center gap-3 mb-2">
              <Avatar className="w-10 h-10 border border-white/10">
                <AvatarImage src={p?.avatar_url || ""} />
                <AvatarFallback className="bg-blue-500/20 text-blue-200 text-xs">
                  {(p?.display_name || req.full_name)?.charAt(0)?.toUpperCase() || "?"}
                </AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5">
                  <span className="text-sm font-semibold truncate">{req.full_name}</span>
                </div>
                <div className="flex items-center gap-2 text-[10px] opacity-60">
                  <span className="font-mono">{p?.kurd_id || "—"}</span>
                  <span>·</span>
                  <span className="capitalize">{req.document_type.replace("_"," ")}</span>
                  <span>·</span>
                  <span className="flex items-center gap-0.5"><Clock className="w-2.5 h-2.5" />{timeAgo(req.submitted_at)}</span>
                </div>
              </div>
              <Badge variant="outline" className="text-[9px] border-white/15 capitalize">{p?.kurd_id_tier || "normal"}</Badge>
            </div>

            <div className="text-[10px] opacity-70 mb-2">
              DOB: <span className="font-mono">{req.date_of_birth}</span> · {p?.city}
            </div>

            {!urls ? (
              <Button
                size="sm"
                variant="outline"
                className="w-full h-7 text-[10px] mb-2 border-white/15"
                onClick={() => loadDocs(req)}
              >
                <FileText className="w-3 h-3 mr-1" /> Belgeleri görüntüle
              </Button>
            ) : (
              <div className="grid grid-cols-2 gap-2 mb-2">
                <a href={urls.doc} target="_blank" rel="noopener noreferrer" className="block rounded-lg border border-white/10 overflow-hidden bg-black/40 aspect-[3/2] relative">
                  {urls.doc?.toLowerCase().includes(".pdf") ? (
                    <div className="flex flex-col items-center justify-center h-full text-[10px] gap-1">
                      <FileText className="w-5 h-5" /> PDF
                    </div>
                  ) : (
                    <img src={urls.doc} alt="Doc" className="w-full h-full object-cover" />
                  )}
                  <div className="absolute bottom-0 left-0 right-0 bg-black/60 text-[9px] px-1.5 py-0.5 flex items-center gap-1">
                    <FileText className="w-2.5 h-2.5" /> Belge
                  </div>
                </a>
                <a href={urls.selfie} target="_blank" rel="noopener noreferrer" className="block rounded-lg border border-white/10 overflow-hidden bg-black/40 aspect-[3/2] relative">
                  <img src={urls.selfie} alt="Selfie" className="w-full h-full object-cover" />
                  <div className="absolute bottom-0 left-0 right-0 bg-black/60 text-[9px] px-1.5 py-0.5 flex items-center gap-1">
                    <Camera className="w-2.5 h-2.5" /> Selfie
                  </div>
                </a>
              </div>
            )}

            <div className="flex gap-2">
              <Button
                size="sm"
                className="flex-1 h-8 text-xs bg-emerald-500/15 hover:bg-emerald-500/25 text-emerald-200 border border-emerald-400/30"
                onClick={() => decide(req.id, "approved")}
                disabled={acting === req.id}
              >
                {acting === req.id ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <ShieldCheck className="w-3 h-3 mr-1" />}
                Approve
              </Button>
              <Button
                size="sm"
                variant="outline"
                className="flex-1 h-8 text-xs border-rose-400/30 text-rose-200 hover:bg-rose-500/10"
                onClick={() => decide(req.id, "rejected")}
                disabled={acting === req.id}
              >
                <ShieldX className="w-3 h-3 mr-1" />
                Reject
              </Button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function timeAgo(date: string) {
  const diff = Date.now() - new Date(date).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 60) return `${mins}m`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h`;
  return `${Math.floor(hrs / 24)}d`;
}

