function CitizenRolePanel({ citizen, onClear }: { citizen: CitizenRow; onClear: () => void }) {
  const { roles, refresh, loading } = useUserRoles(citizen.user_id);
  const [newRole, setNewRole] = useState<AppRole>("moderator");
  const [district, setDistrict] = useState("");
  const [notes, setNotes] = useState("");
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [revoking, setRevoking] = useState<{ id: string; role: AppRole } | null>(null);

  const handleAssign = async (reason?: string) => {
    const result = await adminAssignRole({
      targetUser: citizen.user_id,
      role: newRole,
      district: district.trim() || undefined,
      notes: (reason ?? notes).trim() || undefined,
    });
    if (result.ok) {
      toast.success(`${ROLE_META[newRole].label} rolü atandı (mühürlü)`);
      setDistrict("");
      setNotes("");
      refresh();
    } else {
      toast.error(result.error ?? "Atama başarısız");
      throw new Error(result.error);
    }
  };

  const handleRevoke = async (reason?: string) => {
    if (!revoking) return;
    const result = await adminRevokeRole(revoking.id, reason);
    if (result.ok) {
      toast.success(`${ROLE_META[revoking.role].label} rolü iptal edildi`);
      refresh();
    } else {
      toast.error(result.error ?? "İptal başarısız");
      throw new Error(result.error);
    }
  };

  return (
    <div className="space-y-3">
      {/* Selected citizen */}
      <div className="flex items-center gap-3 rounded-xl border border-amber-400/30 bg-amber-500/5 p-3">
        <Avatar className="h-10 w-10 border border-amber-400/40">
          <AvatarImage src={citizen.avatar_url ?? ""} />
          <AvatarFallback className="bg-amber-500/10 text-amber-200">
            {citizen.display_name?.charAt(0) ?? "?"}
          </AvatarFallback>
        </Avatar>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-semibold truncate">{citizen.display_name ?? "—"}</p>
          <p className="text-[11px] font-mono text-amber-200">{citizen.kurd_id ?? "—"}</p>
        </div>
        <Button size="icon" variant="ghost" className="h-7 w-7" onClick={onClear}>
          <X className="h-3.5 w-3.5" />
        </Button>
      </div>

      {/* Active roles */}
      <div className="space-y-1.5">
        <p className="text-[10px] uppercase tracking-widest opacity-50 px-1">Mevcut Roller</p>
        {loading ? (
          <Loader2 className="h-4 w-4 animate-spin text-muted-foreground mx-auto" />
        ) : roles.length === 0 ? (
          <p className="text-[11px] text-muted-foreground px-1">Atanmış rol yok.</p>
        ) : (
          <div className="space-y-1">
            {roles.map((r) => {
              const meta = ROLE_META[r.role];
              return (
                <div key={r.id} className={`flex items-center gap-2 rounded-lg border px-2.5 py-1.5 ${meta.chipClass}`}>
                  <span className="text-base">{meta.icon}</span>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-semibold">{meta.label}</p>
                    <p className="text-[10px] opacity-70 truncate">
                      {r.district ? `${r.district} · ` : ""}{new Date(r.assigned_at).toLocaleDateString("tr-TR")}
                    </p>
                  </div>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-6 w-6 opacity-70 hover:opacity-100"
                    onClick={() => setRevoking({ id: r.id, role: r.role })}
                  >
                    <X className="h-3 w-3" />
                  </Button>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Assign new */}
      <div className="space-y-2 rounded-xl border border-white/10 bg-white/[0.02] p-3">
        <p className="text-[10px] uppercase tracking-widest opacity-50">Yeni Rol Ata</p>

        <div>
          <Label className="text-xs">Rol</Label>
          <Select value={newRole} onValueChange={(v) => setNewRole(v as AppRole)}>
            <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
            <SelectContent>
              {ASSIGNABLE_ROLES.map((r) => (
                <SelectItem key={r} value={r}>
                  <span className="flex items-center gap-2">
                    <span>{ROLE_META[r].icon}</span> {ROLE_META[r].label}
                  </span>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-[10px] text-muted-foreground mt-1">{ROLE_META[newRole].description}</p>
        </div>

        <div>
          <Label className="text-xs">Bölge / Şehir (opsiyonel)</Label>
          <Input
            value={district}
            onChange={(e) => setDistrict(e.target.value)}
            placeholder={newRole === "district_guardian" ? "Diyarbakır, Berlin…" : "—"}
            className="h-8 text-xs"
          />
        </div>

        <div>
          <Label className="text-xs">Not</Label>
          <Input
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            placeholder="Atama notu…"
