        target={`${citizen.kurd_id} → ${ROLE_META[newRole].icon} ${ROLE_META[newRole].short}`}
        requireReason
        reasonLabel="Atama gerekçesi"
        actionLabel="Rolü Mühürle"
        onConfirm={handleAssign}
      />

      <SovereignSealConfirm
        open={!!revoking}
        onOpenChange={(o) => !o && setRevoking(null)}
        title="Rol İptali"
        description={`${revoking ? ROLE_META[revoking.role].label : ""} rolü kaldırılacak. Bu eylem geri alınabilir.`}
        target={citizen.kurd_id ?? citizen.display_name ?? citizen.user_id}
        requireReason
        destructive
        actionLabel="İptal Et"
        onConfirm={handleRevoke}
      />
    </div>
  );
}

