/**
 * Admin-only audit view of sensitive profile fields (phone, latitude, longitude).
 * Every fetch writes a row to security_audit_log via the underlying RPC.
 */
import { useEffect, useState, useCallback } from "react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, Phone, MapPin, Eye, EyeOff, ShieldAlert, RefreshCw, Search } from "lucide-react";
import { toast } from "sonner";

interface SensitiveRow {
  user_id: string;
  display_name: string | null;
  username: string | null;
  kurd_id: string | null;
  phone_number: string | null;
  latitude: number | null;
  longitude: number | null;
  location_updated_at: string | null;
  city: string | null;
  is_verified: boolean;
  created_at: string;
  has_phone: boolean;
  has_location: boolean;
}

interface Stats {
  total_profiles: number;
  with_phone: number;
  with_location: number;
  with_both: number;
  recent_location_updates: number;
}

function maskPhone(p: string | null): string {
  if (!p) return "—";
  if (p.length <= 4) return "••••";
  return p.slice(0, 3) + "•••••" + p.slice(-2);
}

function maskCoord(n: number | null): string {
  if (n == null) return "—";
  // Show only 1 decimal for privacy when masked
  return n.toFixed(1) + "•••";
}

export function SensitiveProfileAudit() {
  const [rows, setRows] = useState<SensitiveRow[]>([]);
  const [stats, setStats] = useState<Stats | null>(null);
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [revealed, setRevealed] = useState<Set<string>>(new Set());

  const fetchAll = useCallback(async (q: string) => {
    setLoading(true);
    setError(null);
    const [rowsRes, statsRes] = await Promise.all([
      supabase.rpc("admin_view_sensitive_profiles", {
        _query: q || undefined,
        _limit: 50,
        _offset: 0,
      }),
      supabase.rpc("admin_sensitive_profile_stats"),
    ]);
    if (rowsRes.error) {
      setError(rowsRes.error.message);
      setRows([]);
    } else {
      setRows((rowsRes.data as SensitiveRow[]) ?? []);
    }
    if (!statsRes.error && statsRes.data) {
      const row = (statsRes.data as Stats[])?.[0] ?? null;
      setStats(row);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    const t = setTimeout(() => fetchAll(query), 300);
    return () => clearTimeout(t);
  }, [query, fetchAll]);

  const toggleReveal = (userId: string) => {
    setRevealed((prev) => {
      const next = new Set(prev);
      if (next.has(userId)) {
        next.delete(userId);
      } else {
        next.add(userId);
