/**
 * SovereignCitizenDB — searchable list of every registered citizen with
 * KYC status, +777 ID, KEKA score, and a Manage drawer.
 *
 * Manage drawer lets the admin:
 *  - View full sovereign profile snapshot
 *  - Toggle KYC status (with mühür confirm + reason)
 *  - Open the role assignment hub for that user
 */
import { useState } from "react";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
