import {
  useCitizenSearch,
  useUserRoles,
  adminOverrideKyc,
  type CitizenRow,
} from "@/hooks/useSovereignAdmin";
import { SovereignSealConfirm } from "./SovereignSealConfirm";
import { Link } from "@tanstack/react-router";
import { ROLE_META } from "@/lib/roleMeta";

interface Props {
  /** when true (KYC tab), only show pending verifications */
  pendingOnly?: boolean;
  onOpenRoleHub?: (citizen: CitizenRow) => void;
}

export function SovereignCitizenDB({ pendingOnly = false, onOpenRoleHub }: Props) {
