/* ---------------------------------------------------------------- */
/* Manage drawer                                                     */
/* ---------------------------------------------------------------- */
function CitizenManageSheet({
  citizen,
  onClose,
  onChange,
  onOpenRoleHub,
}: {
  citizen: CitizenRow | null;
  onClose: () => void;
  onChange: () => void;
  onOpenRoleHub: (c: CitizenRow) => void;
}) {
  const { roles, loading: rolesLoading } = useUserRoles(citizen?.user_id ?? null);
  const [confirm, setConfirm] = useState<null | { mode: "verify" | "revoke" }>(null);

  if (!citizen) return null;

  const handleKycToggle = async (reason?: string) => {
    if (!confirm) return;
    const newState = confirm.mode === "verify";
    const result = await adminOverrideKyc(citizen.user_id, newState, reason);
    if (result.ok) {
      toast.success(newState ? "KYC onaylandı (mühürlü)" : "KYC iptal edildi");
      onChange();
      onClose();
    } else {
      toast.error(result.error ?? "İşlem başarısız");
      throw new Error(result.error);
    }
  };

  return (
    <Sheet open={!!citizen} onOpenChange={(o) => !o && onClose()}>
      <SheetContent side="bottom" className="bg-[#050505] border-white/10 max-h-[88vh] overflow-y-auto">
        <SheetHeader className="text-left">
          <div className="flex items-center gap-3">
            <Avatar className="h-12 w-12 border border-amber-400/30">
              <AvatarImage src={citizen.avatar_url ?? ""} />
              <AvatarFallback className="bg-amber-500/10 text-amber-200">
                {citizen.display_name?.charAt(0) ?? "?"}
              </AvatarFallback>
            </Avatar>
            <div className="flex-1 min-w-0">
              <SheetTitle className="text-base">{citizen.display_name ?? "—"}</SheetTitle>
              <p className="text-[11px] font-mono text-amber-200">{citizen.kurd_id ?? "—"}</p>
              <p className="text-[10px] text-muted-foreground">
                {citizen.username ? `@${citizen.username}` : ""} {citizen.city ? `· ${citizen.city}` : ""}
              </p>
            </div>
          </div>
        </SheetHeader>

        <div className="grid grid-cols-3 gap-2 mt-4">
          <Stat
            label="KYC"
            value={citizen.is_verified ? "Onaylı" : "Bekliyor"}
            tone={citizen.is_verified ? "emerald" : "amber"}
          />
          <Stat label="KEKA" value={citizen.keka_points.toLocaleString()} tone="amber" />
          <Stat label="Roller" value={citizen.role_count.toString()} tone="indigo" />
        </div>

        {/* Active roles */}
        <div className="mt-4 space-y-1.5">
          <p className="text-[10px] uppercase tracking-widest opacity-50">Aktif Roller</p>
          {rolesLoading ? (
            <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
          ) : roles.length === 0 ? (
            <p className="text-[11px] text-muted-foreground">Atanmış rol yok.</p>
          ) : (
            <div className="space-y-1">
              {roles.map((r) => {
                const meta = ROLE_META[r.role];
                return (
                  <div key={r.id} className="flex items-center gap-2 rounded-lg border border-white/5 bg-white/[0.02] px-2.5 py-1.5">
                    <span className="text-base">{meta.icon}</span>
                    <div className="flex-1 min-w-0">
                      <p className="text-xs font-semibold">{meta.label}</p>
                      <p className="text-[10px] text-muted-foreground truncate">
                        {r.district ? `${r.district} · ` : ""}
                        {new Date(r.assigned_at).toLocaleDateString("tr-TR")}
                        {r.assigned_by_name ? ` · ${r.assigned_by_name}` : ""}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Actions */}
        <div className="mt-5 space-y-2">
          {citizen.is_verified ? (
            <Button
              variant="outline"
              className="w-full border-red-400/30 text-red-300 hover:bg-red-500/10"
              onClick={() => setConfirm({ mode: "revoke" })}
            >
              <ShieldX className="h-3.5 w-3.5 mr-2" />
              KYC Onayını Geri Al
            </Button>
          ) : (
            <Button
              className="w-full bg-emerald-500/15 border border-emerald-400/30 text-emerald-200 hover:bg-emerald-500/25"
              onClick={() => setConfirm({ mode: "verify" })}
            >
              <ShieldCheck className="h-3.5 w-3.5 mr-2" />
              Manuel KYC Onayı (Mühürle)
            </Button>
          )}

          <Button
            variant="outline"
            className="w-full border-amber-400/30 text-amber-200 hover:bg-amber-500/10"
