          >
            <UserCog className="h-3.5 w-3.5 mr-2" />
            Rol Ata / Yönet (Nûner)
          </Button>

          <Link
            to="/sovereign-profile"
            className="flex items-center justify-center gap-2 w-full rounded-md border border-white/10 px-3 py-2 text-xs text-muted-foreground hover:text-foreground hover:bg-white/5"
