              : "Bu kullanıcının KYC onayı kaldırılacak. Tüm Sovereign hakları askıya alınır."
          }
          target={citizen.kurd_id ?? citizen.display_name ?? citizen.user_id}
          requireReason
          reasonLabel={confirm?.mode === "verify" ? "Onay gerekçesi" : "İptal gerekçesi"}
          destructive={confirm?.mode === "revoke"}
          actionLabel={confirm?.mode === "verify" ? "Onayla" : "İptal Et"}
          onConfirm={handleKycToggle}
        />
      </SheetContent>
    </Sheet>
