/**
 * SovereignSealConfirm — golden mühür confirmation dialog for destructive admin actions.
 *
 * Hold-to-seal interaction (1.2s) prevents accidental clicks. Used for:
 *   - Role assign/revoke
 *   - KYC override
 *   - App / banner deletion
 */
import { useEffect, useRef, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { ShieldAlert, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

interface SovereignSealConfirmProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description: string;
  actionLabel?: string;
  /** target identifier shown to the admin (kurd_id, app name, etc.) */
  target?: string;
  /** require admin to type a reason (recommended for revoke / KYC reject) */
  requireReason?: boolean;
  reasonLabel?: string;
  destructive?: boolean;
  onConfirm: (reason?: string) => Promise<void> | void;
}

export function SovereignSealConfirm({
  open,
  onOpenChange,
  title,
  description,
  actionLabel = "Mühürle",
  target,
  requireReason = false,
  reasonLabel = "Gerekçe",
  destructive = false,
  onConfirm,
}: SovereignSealConfirmProps) {
  const [reason, setReason] = useState("");
  const [holding, setHolding] = useState(false);
  const [progress, setProgress] = useState(0);
  const [submitting, setSubmitting] = useState(false);
  const rafRef = useRef<number | null>(null);
  const startRef = useRef<number>(0);

  useEffect(() => {
    if (!open) {
      setReason("");
      setProgress(0);
      setHolding(false);
      setSubmitting(false);
    }
  }, [open]);

  const stopHold = () => {
    if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    rafRef.current = null;
    setHolding(false);
    if (!submitting) setProgress(0);
  };

  const startHold = () => {
    if (submitting) return;
    if (requireReason && !reason.trim()) return;
    setHolding(true);
    startRef.current = performance.now();
    const tick = (now: number) => {
      const pct = Math.min(1, (now - startRef.current) / 1200);
      setProgress(pct);
      if (pct < 1) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        rafRef.current = null;
        setHolding(false);
        void runConfirm();
      }
    };
    rafRef.current = requestAnimationFrame(tick);
  };

  const runConfirm = async () => {
    setSubmitting(true);
    try {
      await onConfirm(requireReason ? reason.trim() : undefined);
      onOpenChange(false);
    } catch {
      // caller handles toast
    } finally {
      setSubmitting(false);
      setProgress(0);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="border-amber-500/30 bg-[#0a0905] max-w-sm">
        <DialogHeader>
          <div className="flex items-center gap-2">
            <div className={cn(
              "h-9 w-9 rounded-full flex items-center justify-center border",
              destructive
                ? "bg-red-500/10 border-red-400/40 text-red-300"
                : "bg-amber-500/10 border-amber-400/40 text-amber-300"
            )}>
              <ShieldAlert className="h-4 w-4" />
            </div>
            <DialogTitle className="text-base">{title}</DialogTitle>
          </div>
          <DialogDescription className="text-xs text-muted-foreground">{description}</DialogDescription>
        </DialogHeader>

        {target && (
          <div className="rounded-lg border border-white/10 bg-white/[0.03] px-3 py-2">
            <div className="text-[10px] uppercase tracking-widest opacity-50">Hedef</div>
            <div className="text-sm font-mono text-amber-200 truncate">{target}</div>
          </div>
        )}

        {requireReason && (
          <div className="space-y-1">
            <Label className="text-xs">{reasonLabel}</Label>
            <Textarea
              rows={2}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="Bu eylemin gerekçesini yazın…"
              className="text-xs"
            />
          </div>
        )}

        <div className="space-y-2">
          <button
            type="button"
            disabled={submitting || (requireReason && !reason.trim())}
            onPointerDown={startHold}
            onPointerUp={stopHold}
            onPointerLeave={stopHold}
            onPointerCancel={stopHold}
            className={cn(
              "relative w-full overflow-hidden rounded-xl border h-12 font-semibold text-sm transition-all select-none",
              destructive
                ? "border-red-400/40 bg-red-500/5 text-red-200 hover:bg-red-500/10"
                : "border-amber-400/40 bg-amber-500/5 text-amber-100 hover:bg-amber-500/10",
              holding && "scale-[0.98]",
              (submitting || (requireReason && !reason.trim())) && "opacity-50 cursor-not-allowed"
            )}
          >
            <div
              className={cn(
                "absolute inset-y-0 left-0 transition-[width]",
                destructive
                  ? "bg-gradient-to-r from-red-500/40 to-red-400/30"
                  : "bg-gradient-to-r from-amber-500/40 to-yellow-400/30"
              )}
              style={{ width: `${progress * 100}%` }}
            />
            <div className="relative flex items-center justify-center gap-2">
              {submitting ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Mühür uygulanıyor…
                </>
              ) : holding ? (
                <>Basılı tut · {Math.round(progress * 100)}%</>
              ) : (
                <>🔱 {actionLabel} · Mührü basılı tut</>
              )}
            </div>
          </button>
          <p className="text-[10px] text-center text-muted-foreground">
            Bu eylem audit log'a kaydedilecek.
          </p>
        </div>
      </DialogContent>
    </Dialog>
  );
}

