import { LucideIcon, TrendingUp, TrendingDown } from "lucide-react";

interface StatCardProps {
  icon: LucideIcon;
  label: string;
  value: string | number;
  delta?: number;
  iconColor?: string;
  iconBg?: string;
  glow?: string;
}

export function StatCard({ icon: Icon, label, value, delta, iconColor = "text-blue-400", iconBg = "bg-blue-500/15", glow = "rgba(59,130,246,0.35)" }: StatCardProps) {
  const positive = (delta ?? 0) >= 0;
  return (
    <div
      className="relative overflow-hidden rounded-2xl bg-white/[0.03] backdrop-blur-xl border border-white/10 p-3"
      style={{ boxShadow: `inset 0 0 30px -20px ${glow}` }}
    >
      <div className="absolute -top-10 -right-10 w-20 h-20 rounded-full blur-2xl opacity-40" style={{ background: glow }} />
      <div className="relative flex items-start justify-between mb-2">
        <div className={`w-9 h-9 rounded-xl ${iconBg} flex items-center justify-center`}>
          <Icon className={`w-4 h-4 ${iconColor}`} style={{ filter: "drop-shadow(0 0 6px currentColor)" }} />
        </div>
        {delta !== undefined && (
          <div className={`text-[10px] font-bold flex items-center gap-0.5 px-1.5 py-0.5 rounded-md ${positive ? "text-emerald-300 bg-emerald-500/10" : "text-rose-300 bg-rose-500/10"}`}>
            {positive ? <TrendingUp className="w-2.5 h-2.5" /> : <TrendingDown className="w-2.5 h-2.5" />}
            {Math.abs(delta)}%
          </div>
        )}
      </div>
      <div className="relative">
        <div className="text-[10px] uppercase tracking-widest opacity-50">{label}</div>
        <div className="text-lg font-bold tabular-nums mt-0.5">{value}</div>
      </div>
    </div>
  );
}

