import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Tv, Radio, Loader2, Trash2, Plus, Pin, PinOff } from "lucide-react";
import { toast } from "sonner";

interface Broadcast {
  id: string;
  youtube_id: string;
  title: string;
  is_active: boolean;
  is_live: boolean;
  created_at: string;
  stream_url: string | null;
  stream_type: "youtube" | "hls";
}

interface Channel {
  id: string;
  name: string;
  youtube_id: string;
  avatar_url: string | null;
  category: string;
  sort_order: number;
  is_active: boolean;
  stream_url: string | null;
  stream_type: "youtube" | "hls";
  is_pinned: boolean;
}

function extractYouTubeId(input: string): string {
  const trimmed = input.trim();
  if (!trimmed) return "";
  try {
    const url = new URL(trimmed);
    if (url.hostname.includes("youtu.be")) return url.pathname.slice(1);
    const v = url.searchParams.get("v");
    if (v) return v;
    const parts = url.pathname.split("/").filter(Boolean);
    const last = parts[parts.length - 1];
    if (last && last.length >= 8) return last;
  } catch {
    // Not a URL — assume it's already an ID
  }
  return trimmed;
}

function looksLikeHls(input: string): boolean {
  return /\.m3u8(\?|$)/i.test(input.trim());
}

export function TVBroadcastManager({ adminId }: { adminId: string }) {
  const [broadcasts, setBroadcasts] = useState<Broadcast[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // One smart input — accepts m3u8 URL, YouTube URL, or YouTube ID.
  const [bForm, setBForm] = useState({ source: "", title: "Jiyan TV Live" });
  const [cForm, setCForm] = useState({ name: "", source: "", avatar_url: "", category: "news" });

  const fetchAll = async () => {
    const [b, c] = await Promise.all([
      supabase.from("tv_broadcasts").select("*").order("created_at", { ascending: false }).limit(20),
      supabase
        .from("tv_channels")
        .select("*")
        .order("is_pinned", { ascending: false })
        .order("sort_order"),
    ]);
    if (b.data) setBroadcasts(b.data as Broadcast[]);
    if (c.data) setChannels(c.data as Channel[]);
    setLoading(false);
  };

  useEffect(() => {
    fetchAll();
  }, []);

  const pushBroadcast = async () => {
    const raw = bForm.source.trim();
    if (!raw) {
      toast.error("Stream URL veya YouTube ID gerekli");
      return;
    }
    const isHls = looksLikeHls(raw);
    const payload: any = {
      title: bForm.title || "Jiyan TV Live",
      is_active: true,
      is_live: true,
      created_by: adminId,
      stream_type: isHls ? "hls" : "youtube",
    };
    if (isHls) {
      payload.stream_url = raw;
      payload.youtube_id = "hls";
    } else {
      payload.youtube_id = extractYouTubeId(raw);
      payload.stream_url = null;
      if (!payload.youtube_id) {
        toast.error("Geçerli YouTube ID/URL girin");
        return;
      }
    }
    setSaving(true);
    const { error } = await supabase.from("tv_broadcasts").insert(payload);
    setSaving(false);
    if (error) {
      toast.error(error.message);
    } else {
      toast.success("📡 WKO Resmi Yayını push'landı — tüm kullanıcılarda #1 sırada");
      setBForm({ source: "", title: "Jiyan TV Live" });
      fetchAll();
    }
  };

  const setActive = async (id: string) => {
    const { error } = await supabase.from("tv_broadcasts").update({ is_active: true }).eq("id", id);
    if (error) toast.error(error.message);
    else {
      toast.success("Yayın aktifleştirildi");
      fetchAll();
    }
  };

  const stopAll = async () => {
    const { error } = await supabase.from("tv_broadcasts").update({ is_active: false }).eq("is_active", true);
    if (error) toast.error(error.message);
    else {
      toast.success("Tüm yayınlar durduruldu");
      fetchAll();
    }
  };

  const deleteBroadcast = async (id: string) => {
    await supabase.from("tv_broadcasts").delete().eq("id", id);
    fetchAll();
  };

  const addChannel = async () => {
    const raw = cForm.source.trim();
    if (!cForm.name.trim() || !raw) {
      toast.error("Kanal adı ve stream URL/YouTube ID gerekli");
      return;
    }
    const isHls = looksLikeHls(raw);
    const payload: any = {
      name: cForm.name.trim(),
      avatar_url: cForm.avatar_url.trim() || null,
      category: cForm.category,
      sort_order: channels.length,
      is_active: true,
      stream_type: isHls ? "hls" : "youtube",
    };
    if (isHls) {
      payload.stream_url = raw;
      payload.youtube_id = "hls";
    } else {
      payload.youtube_id = extractYouTubeId(raw);
      payload.stream_url = null;
      if (!payload.youtube_id) {
        toast.error("Geçerli YouTube ID/URL girin");
        return;
      }
    }
    const { error } = await supabase.from("tv_channels").insert(payload);
    if (error) toast.error(error.message);
    else {
      toast.success("Kanal eklendi");
      setCForm({ name: "", source: "", avatar_url: "", category: "news" });
      fetchAll();
    }
  };

  const removeChannel = async (id: string) => {
    await supabase.from("tv_channels").delete().eq("id", id);
    fetchAll();
  };

  const togglePin = async (c: Channel) => {
    const { error } = await supabase
      .from("tv_channels")
      .update({ is_pinned: !c.is_pinned })
      .eq("id", c.id);
    if (error) toast.error(error.message);
    else {
      toast.success(!c.is_pinned ? "Kanal sabitlendi" : "Sabitleme kaldırıldı");
      fetchAll();
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-5 w-5 animate-spin text-amber-400" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Push live broadcast */}
      <Card className="p-4 bg-gradient-to-br from-amber-500/10 to-orange-500/5 border-amber-500/30">
        <div className="flex items-center gap-2 mb-3">
          <Radio className="h-4 w-4 text-amber-400" />
          <h3 className="font-bold text-sm">WKO Official Broadcast — Push to All</h3>
        </div>
        <div className="space-y-2">
          <div>
            <Label className="text-xs">Stream URL (.m3u8) veya YouTube ID/URL</Label>
            <Input
              value={bForm.source}
              onChange={(e) => setBForm({ ...bForm, source: e.target.value })}
              placeholder="https://… .m3u8  veya  dQw4w9WgXcQ"
              className="bg-white/5 border-white/10 text-sm font-mono"
            />
            <p className="mt-1 text-[10px] text-muted-foreground">
              <span className="font-semibold text-amber-400">Auto-detect:</span> .m3u8 → HLS, başka → YouTube
            </p>
          </div>
          <div>
            <Label className="text-xs">Başlık</Label>
            <Input
              value={bForm.title}
              onChange={(e) => setBForm({ ...bForm, title: e.target.value })}
              placeholder="Jiyan TV Live"
              className="bg-white/5 border-white/10 text-sm"
            />
          </div>
          <div className="flex gap-2">
            <Button
              onClick={pushBroadcast}
              disabled={saving}
              className="flex-1 bg-amber-500 hover:bg-amber-600 text-black font-semibold"
            >
              {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Tv className="h-4 w-4 mr-1" />}
              Push to All Users (#1)
            </Button>
            <Button onClick={stopAll} variant="outline" className="border-white/10">
              Stop
            </Button>
          </div>
        </div>
      </Card>

      {/* History */}
      {broadcasts.length > 0 && (
        <Card className="p-3 bg-white/[0.02] border-white/10">
          <h4 className="text-xs font-semibold mb-2 uppercase tracking-wide text-muted-foreground">Geçmiş Yayınlar</h4>
          <div className="space-y-1">
            {broadcasts.map((b) => (
              <div key={b.id} className="flex items-center gap-2 text-xs p-2 rounded bg-white/[0.02]">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5 flex-wrap">
                    <span className="font-medium truncate">{b.title}</span>
                    {b.is_active && <Badge className="bg-red-500/20 text-red-300 text-[9px] px-1.5 py-0">LIVE</Badge>}
                    <Badge className="bg-amber-500/15 text-amber-300 text-[9px] px-1.5 py-0">
                      {b.stream_type === "hls" ? "HLS" : "YouTube"}
                    </Badge>
                  </div>
                  <p className="text-[10px] text-muted-foreground font-mono truncate">
                    {b.stream_type === "hls" ? b.stream_url : b.youtube_id}
                  </p>
                </div>
                {!b.is_active && (
                  <Button size="sm" variant="ghost" className="h-7 px-2 text-[10px]" onClick={() => setActive(b.id)}>
                    Aktif Et
                  </Button>
                )}
                <button onClick={() => deleteBroadcast(b.id)} className="p-1 text-red-400 hover:bg-red-500/10 rounded">
                  <Trash2 className="h-3 w-3" />
                </button>
              </div>
            ))}
          </div>
        </Card>
      )}

      {/* Channels */}
      <Card className="p-4 bg-white/[0.02] border-white/10">
        <h3 className="font-bold text-sm mb-3 flex items-center gap-2">
          <Plus className="h-4 w-4 text-amber-400" /> Kanal Ekle
        </h3>
        <div className="grid grid-cols-2 gap-2">
          <Input
            placeholder="Kanal adı (Rudaw)"
            value={cForm.name}
            onChange={(e) => setCForm({ ...cForm, name: e.target.value })}
            className="bg-white/5 border-white/10 text-sm"
          />
          <Input
            placeholder=".m3u8 URL veya YouTube ID"
            value={cForm.source}
            onChange={(e) => setCForm({ ...cForm, source: e.target.value })}
            className="bg-white/5 border-white/10 text-sm font-mono"
          />
          <Input
            placeholder="Avatar URL (opsiyonel)"
            value={cForm.avatar_url}
            onChange={(e) => setCForm({ ...cForm, avatar_url: e.target.value })}
            className="bg-white/5 border-white/10 text-sm col-span-2"
          />
        </div>
        <Button onClick={addChannel} className="w-full mt-2 bg-amber-500/90 hover:bg-amber-500 text-black">
          Kanal Ekle
        </Button>

        <div className="mt-3 space-y-1">
          {channels.map((c) => (
            <div key={c.id} className="flex items-center gap-2 p-2 rounded bg-white/[0.02] text-xs">
              {c.avatar_url ? (
                <img src={c.avatar_url} alt={c.name} className="h-7 w-7 rounded-full object-cover" />
              ) : (
                <div className="h-7 w-7 rounded-full bg-amber-500/20 flex items-center justify-center text-amber-300 font-bold text-[10px]">
                  {c.name[0]}
                </div>
              )}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5">
                  <p className="font-medium truncate">{c.name}</p>
                  <Badge className="bg-amber-500/15 text-amber-300 text-[9px] px-1.5 py-0">
                    {c.stream_type === "hls" ? "HLS" : "YT"}
                  </Badge>
                  {c.is_pinned && (
                    <Badge className="bg-purple-500/20 text-purple-200 text-[9px] px-1.5 py-0">Pinned</Badge>
                  )}
                </div>
                <p className="text-[10px] text-muted-foreground font-mono truncate">
                  {c.stream_type === "hls" ? c.stream_url : c.youtube_id}
                </p>
              </div>
              <button
                onClick={() => togglePin(c)}
                className={`p-1 rounded ${c.is_pinned ? "text-purple-300 hover:bg-purple-500/10" : "text-white/50 hover:bg-white/5"}`}
                title={c.is_pinned ? "Sabitlemeyi kaldır" : "Üste sabitle"}
              >
                {c.is_pinned ? <PinOff className="h-3 w-3" /> : <Pin className="h-3 w-3" />}
              </button>
              <button onClick={() => removeChannel(c.id)} className="p-1 text-red-400 hover:bg-red-500/10 rounded">
                <Trash2 className="h-3 w-3" />
              </button>
            </div>
          ))}
          {channels.length === 0 && (
            <p className="text-center text-muted-foreground text-xs py-3">Henüz kanal yok</p>
          )}
        </div>
      </Card>
    </div>
  );
}

