/**
 * EmailAuthFlow — Gmail-style 2-step e-posta giriş/kayıt akışı.
 *
 * Akış:
 *   • Step 1 (email): kullanıcı adını gir → Sonraki
 *   • Step 2 (password): şifreyi gir → Giriş Yap / Hesap Oluştur
 *   • forgot:  reset link gönder
 *
 * Tüm hesaplar dahili olarak `<username>@jiyan.world` adresine map edilir;
 * arayüzde bu suffix sadece bilgi olarak gösterilir. Üst seviye `login.tsx`
 * sayfası bu modal'ı `showEmailAuth` flag'i ile açar — sayfayı dağıtmaz,
 * Apple-temiz 3 buton kalır.
 */
import { useEffect, useRef, useState } from "react";
import { ArrowLeft, ArrowRight, Eye, EyeOff, Loader2, Mail, ShieldCheck, Sparkles, X } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";

type Mode = "signin" | "signup";
type Step = "email" | "password" | "forgot" | "sent";

interface Props {
  open: boolean;
  initialMode?: Mode;
  onClose: () => void;
  onSuccess: (userId: string, mode: Mode) => void;
}

const usernameOf = (raw: string) =>
  raw.trim().toLowerCase().replace(/^@+/, "").replace(/@jiyan\.world$/i, "").replace(/[^a-z0-9._-]/g, "");

// ── Client-side login throttle ────────────────────────────────────────────
// 5 başarısız denemeden sonra geçici kilit. Süreler: 60s → 5dk → 15dk → 1sa.
const MAX_ATTEMPTS = 5;
const LOCK_LADDER_SEC = [60, 300, 900, 3600];
const lockKey = (u: string) => `jiyan.loginLock:${u}`;
type LockState = { fails: number; lockUntil: number; tier: number };
const readLock = (u: string): LockState => {
  try {
    const raw = typeof window !== "undefined" ? localStorage.getItem(lockKey(u)) : null;
    return raw ? (JSON.parse(raw) as LockState) : { fails: 0, lockUntil: 0, tier: 0 };
  } catch {
    return { fails: 0, lockUntil: 0, tier: 0 };
  }
};
const writeLock = (u: string, s: LockState) => {
  try { localStorage.setItem(lockKey(u), JSON.stringify(s)); } catch {}
};
const clearLock = (u: string) => {
  try { localStorage.removeItem(lockKey(u)); } catch {}
};

export function EmailAuthFlow({ open, initialMode = "signin", onClose, onSuccess }: Props) {
  const [mode, setMode] = useState<Mode>(initialMode);
  const [step, setStep] = useState<Step>("email");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [accepted, setAccepted] = useState(false);
  const [resendIn, setResendIn] = useState(0);
  const [resendCount, setResendCount] = useState(0);
  const [statusMsg, setStatusMsg] = useState("");
  const [lockLeft, setLockLeft] = useState(0); // seconds remaining for active login lock

  const emailRef = useRef<HTMLInputElement>(null);
  const pwRef = useRef<HTMLInputElement>(null);

  // Cooldown timer for resend
  useEffect(() => {
    if (resendIn <= 0) return;
    const t = setInterval(() => setResendIn((n) => Math.max(0, n - 1)), 1000);
    return () => clearInterval(t);
  }, [resendIn]);

  // Live lock countdown — recomputes from storage so it survives reloads
  useEffect(() => {
    const u = usernameOf(username);
    if (!u) { setLockLeft(0); return; }
    const tick = () => {
      const s = readLock(u);
      const left = Math.max(0, Math.ceil((s.lockUntil - Date.now()) / 1000));
      setLockLeft(left);
    };
    tick();
    const t = setInterval(tick, 1000);
    return () => clearInterval(t);
  }, [username, step]);

  // Reset on open / mode-change
  useEffect(() => {
    if (!open) return;
    setMode(initialMode);
    setStep("email");
    setError("");
    setPassword("");
    setShowPw(false);
    setTimeout(() => emailRef.current?.focus(), 80);
  }, [open, initialMode]);

  // Auto-focus password on step change
  useEffect(() => {
    if (step === "password") setTimeout(() => pwRef.current?.focus(), 80);
  }, [step]);

  // ESC closes
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  if (!open) return null;

  const email = username ? `${usernameOf(username)}@jiyan.world` : "";

  const handleNext = (e?: React.FormEvent) => {
    e?.preventDefault();
    setError("");
    const u = usernameOf(username);
    if (!u || u.length < 3) {
      setError("En az 3 karakterli bir kullanıcı adı gir");
      return;
    }
    setStep("password");
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    if (password.length < 6) {
      setError("Şifre en az 6 karakter olmalı");
      return;
    }
    if (mode === "signup" && !accepted) {
      setError("Devam etmek için Kullanım Koşulları ve Gizlilik Politikası onayı gerekli");
      return;
    }

    const u = usernameOf(username);
    // Enforce lockout for sign-in only
    if (mode === "signin") {
      const s = readLock(u);
      const left = Math.max(0, Math.ceil((s.lockUntil - Date.now()) / 1000));
      if (left > 0) {
        setLockLeft(left);
        setError(`Çok fazla başarısız deneme. ${formatLeft(left)} sonra tekrar dene.`);
        return;
      }
    }

    setLoading(true);
    try {
      if (mode === "signup") {
        const { data, error: err } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: { display_name: displayName.trim() || usernameOf(username) },
            emailRedirectTo: typeof window !== "undefined" ? window.location.origin : undefined,
          },
        });
        if (err) throw err;
        const uid = data.user?.id;
        if (uid) {
          try {
            await supabase.from("terms_acceptances").insert([
              { user_id: uid, document_type: "terms" },
              { user_id: uid, document_type: "privacy" },
            ]);
          } catch {}
          onSuccess(uid, "signup");
        }
      } else {
        const { data, error: err } = await supabase.auth.signInWithPassword({ email, password });
        if (err) throw err;
        const uid = data.user?.id;
        if (uid) {
          clearLock(u);
          setLockLeft(0);
          onSuccess(uid, "signin");
        }
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Bir hata oluştu";
      const isCreds = msg.toLowerCase().includes("invalid login") || msg.toLowerCase().includes("invalid credentials");

      if (mode === "signin" && isCreds) {
        const s = readLock(u);
        const fails = s.fails + 1;
        if (fails >= MAX_ATTEMPTS) {
          const tier = Math.min(s.tier, LOCK_LADDER_SEC.length - 1);
          const lockSec = LOCK_LADDER_SEC[tier];
          const next: LockState = { fails: 0, lockUntil: Date.now() + lockSec * 1000, tier: tier + 1 };
          writeLock(u, next);
          setLockLeft(lockSec);
          setError(`Çok fazla başarısız deneme. Hesap ${formatLeft(lockSec)} kilitlendi.`);
        } else {
          writeLock(u, { ...s, fails });
          const remaining = MAX_ATTEMPTS - fails;
          setError(`Kullanıcı adı veya şifre hatalı. ${remaining} deneme hakkın kaldı.`);
        }
      } else if (msg.toLowerCase().includes("already registered")) {
        setError("Bu kullanıcı adı zaten kayıtlı — Giriş Yap");
      } else {
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  const formatLeft = (s: number) => {
    if (s >= 3600) return `${Math.ceil(s / 3600)} sa`;
    if (s >= 60) return `${Math.ceil(s / 60)} dk`;
    return `${s} sn`;
  };

  const handleForgot = async () => {
    setError("");
    setStatusMsg("");
    if (!email) {
      setError("Önce kullanıcı adını gir");
      setStep("email");
      return;
    }
    if (resendIn > 0) {
      setStatusMsg(`Tekrar göndermek için ${resendIn} sn bekle.`);
      return;
    }
    setLoading(true);
    try {
      const { error: err } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: `${window.location.origin}/reset-password`,
      });
      if (err) throw err;
      const next = resendCount + 1;
      setResendCount(next);
      // Backoff: 30s → 60s → 120s
      setResendIn(next === 1 ? 30 : next === 2 ? 60 : 120);
      setStatusMsg(
        next === 1
          ? "Bağlantı gönderildi. Posta kutunu kontrol et."
          : `Bağlantı yeniden gönderildi (${next}. kez).`,
      );
      setStep("sent");
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Bağlantı gönderilemedi";
      if (msg.toLowerCase().includes("rate") || msg.toLowerCase().includes("seconds")) {
        setError("Çok sık denedin — lütfen biraz bekle.");
        setResendIn(60);
      } else {
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={mode === "signup" ? "Hesap oluştur" : "Giriş yap"}
      className="fixed inset-0 z-[80] flex items-stretch sm:items-center justify-center bg-black/85 backdrop-blur-md animate-in fade-in"
      onClick={onClose}
    >
      <div
        className="relative w-full sm:max-w-md sm:rounded-3xl bg-gradient-to-b from-[#1a1305] to-[#050300] border border-amber-400/25 shadow-[0_30px_80px_-20px_rgba(0,0,0,0.9)] p-6 sm:p-8 overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between mb-5">
          {step === "email" ? (
            <button
              type="button"
              onClick={onClose}
              aria-label="Kapat"
              className="h-9 w-9 rounded-full flex items-center justify-center text-amber-200/60 hover:text-amber-100 hover:bg-amber-400/10 transition-colors"
            >
              <X className="h-4.5 w-4.5" />
            </button>
          ) : (
            <button
              type="button"
              onClick={() => {
                setError("");
                setStep("email");
              }}
              aria-label="Geri"
              className="h-9 w-9 rounded-full flex items-center justify-center text-amber-200/60 hover:text-amber-100 hover:bg-amber-400/10 transition-colors"
            >
              <ArrowLeft className="h-4.5 w-4.5" />
            </button>
          )}

          <div className="flex items-center gap-1.5 text-[10px] font-medium uppercase tracking-[0.32em] text-amber-200/50">
            <ShieldCheck className="h-3 w-3" />
            +777 ID
          </div>
          <span className="w-9" />
        </div>

        {/* Step content */}
        {step === "email" && (
          <form onSubmit={handleNext} className="space-y-5">
            <div>
              <h1 className="text-[26px] leading-tight font-light text-amber-50 tracking-tight">
                {mode === "signup" ? "Hesap oluştur" : "Giriş yap"}
              </h1>
              <p className="mt-1.5 text-[13px] text-amber-200/60">
                Devam etmek için Jiyan kullanıcı adınla başla.
              </p>
            </div>

            {mode === "signup" && (
              <div>
                <label className="text-[11px] font-medium uppercase tracking-wider text-amber-200/60">
                  Ad Soyad
                </label>
                <input
                  type="text"
                  autoComplete="name"
                  value={displayName}
                  onChange={(e) => setDisplayName(e.target.value)}
                  placeholder="Adınız"
                  className="mt-1.5 h-12 w-full rounded-xl border border-amber-400/20 bg-black/40 px-4 text-sm text-amber-50 placeholder:text-amber-200/30 focus:border-amber-300 focus:outline-none focus:ring-1 focus:ring-amber-300/40"
                />
              </div>
            )}

            <div>
              <label className="text-[11px] font-medium uppercase tracking-wider text-amber-200/60">
                Kullanıcı Adı
              </label>
              <div className="relative mt-1.5">
                <input
                  ref={emailRef}
                  type="text"
                  autoComplete="username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="kullaniciadi"
                  className="h-12 w-full rounded-xl border border-amber-400/30 bg-black/40 px-4 pr-[120px] text-sm text-amber-50 placeholder:text-amber-200/30 focus:border-amber-300 focus:outline-none focus:ring-1 focus:ring-amber-300/40"
                  required
                />
                <span className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-xs font-medium text-amber-300/80">
                  @jiyan.world
                </span>
              </div>
            </div>

            {error && (
              <p role="alert" className="rounded-lg bg-red-500/10 border border-red-500/30 px-3 py-2 text-xs text-red-300">
                {error}
              </p>
            )}

            <button
              type="submit"
              className="flex h-12 w-full items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-amber-300 via-yellow-200 to-amber-400 text-sm font-bold text-black shadow-[0_8px_24px_-8px_rgba(255,200,60,0.55)] active:scale-[0.985] transition-transform"
            >
              Sonraki
              <ArrowRight className="h-4 w-4" />
            </button>

            <div className="pt-2 text-center text-[12.5px] text-amber-200/60">
              {mode === "signup" ? "Zaten hesabın var mı? " : "Hesabın yok mu? "}
              <button
                type="button"
                onClick={() => {
                  setMode(mode === "signup" ? "signin" : "signup");
                  setError("");
                }}
                className="font-semibold text-amber-300 hover:text-amber-200"
              >
                {mode === "signup" ? "Giriş yap" : "Hesap oluştur"}
              </button>
            </div>

            {mode === "signin" && (
              <div className="text-center">
                <button
                  type="button"
                  onClick={handleForgot}
                  disabled={loading}
                  className="text-[12px] font-medium text-amber-300/80 hover:text-amber-200"
                >
                  Şifremi unuttum
                </button>
              </div>
            )}
          </form>
        )}

        {step === "password" && (
          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <button
                type="button"
                onClick={() => setStep("email")}
                className="inline-flex items-center gap-1.5 rounded-full border border-amber-400/25 bg-amber-400/5 pl-1 pr-3 py-1 text-[12px] text-amber-100 hover:bg-amber-400/15 transition-colors"
              >
                <span className="h-6 w-6 rounded-full bg-amber-300/20 flex items-center justify-center">
                  <Mail className="h-3 w-3 text-amber-200" />
                </span>
                <span className="font-mono">{email}</span>
              </button>
              <h2 className="mt-4 text-[22px] leading-tight font-light text-amber-50 tracking-tight">
                {mode === "signup" ? "Bir şifre oluştur" : "Hoş geldin"}
              </h2>
              <p className="mt-1.5 text-[13px] text-amber-200/60">
                {mode === "signup"
                  ? "En az 6 karakter — sayı + harf önerilir."
                  : "Devam etmek için şifreni gir."}
              </p>
            </div>

            <div>
