/**
 * GuestGateContext — lets any nested component (HubAppIcon, drawer tiles)
 * trigger the Sovereign Glass login overlay when a guest taps a restricted
 * Mini-App. Provided once at the HubScreen root.
 */
import { createContext, useContext, useState, useCallback, type ReactNode } from "react";
import { useAuth } from "@/hooks/useAuth";
import { isGuestAllowedAppId } from "@/lib/guestMode";
import { SovereignGlassLogin } from "@/components/auth/SovereignGlassLogin";

interface GuestGateValue {
  isGuest: boolean;
  /** Returns true if navigation should be blocked. Side-effect: opens overlay. */
  challenge: (appId: string, label: string, path: string) => boolean;
}

const Ctx = createContext<GuestGateValue>({ isGuest: false, challenge: () => false });

export function GuestGateProvider({ children }: { children: ReactNode }) {
  const { user, loading } = useAuth();
  const isGuest = !loading && !user;
  const [overlay, setOverlay] = useState<{ label: string; path: string } | null>(null);

  const challenge = useCallback(
    (appId: string, label: string, path: string) => {
      if (!isGuest) return false;
      if (isGuestAllowedAppId(appId)) return false;
      setOverlay({ label, path });
      return true;
    },
    [isGuest],
  );

  return (
    <Ctx.Provider value={{ isGuest, challenge }}>
      {children}
      <SovereignGlassLogin
        open={!!overlay}
        onClose={() => setOverlay(null)}
        intendedPath={overlay?.path}
        appLabel={overlay?.label}
      />
    </Ctx.Provider>
  );
}

export function useGuestGate() {
  return useContext(Ctx);
}

