/**
 * KycCompletePrompt
 *
 * Sticky banner shown after sign-in when the citizen has not yet completed
 * KYC. Dismissible per-session. Hidden if already approved or on /kyc.
 */
import { useEffect, useState } from "react";
import { Link, useLocation } from "@tanstack/react-router";
import { ShieldCheck, X } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";

const SESSION_KEY = "jiyan_kyc_prompt_dismissed";

export function KycCompletePrompt() {
  const { user } = useAuth();
  const location = useLocation();
  const [needsKyc, setNeedsKyc] = useState(false);
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined") return;
    setDismissed(sessionStorage.getItem(SESSION_KEY) === "1");
  }, []);

  useEffect(() => {
    let cancelled = false;
    if (!user) {
      setNeedsKyc(false);
      return;
    }
    (async () => {
      const { data } = await supabase.rpc("get_my_kyc_status");
      if (cancelled) return;
      const row = Array.isArray(data) && data.length > 0 ? data[0] : null;
      const approved = row?.kyc_status === "approved";
      setNeedsKyc(!approved);

      // Hard redirect: if a post-login intent (e.g. SSO authorize URL) is stashed
      // and KYC is not approved, force the citizen into the KYC flow first.
      if (!approved && typeof window !== "undefined") {
        const pending = sessionStorage.getItem("jiyan_post_kyc_redirect");
        const path = window.location.pathname;
        const isSafePage = path.startsWith("/kyc") || path.startsWith("/login") || path.startsWith("/manifesto");
        if (pending && !isSafePage) {
          window.location.replace("/kyc");
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [user]);

  const handleDismiss = () => {
    if (typeof window !== "undefined") sessionStorage.setItem(SESSION_KEY, "1");
    setDismissed(true);
  };

  if (!user || !needsKyc || dismissed) return null;
  const path = location.pathname;
  if (path.startsWith("/kyc") || path.startsWith("/login") || path.startsWith("/manifesto")) {
    return null;
  }

  return (
    <div className="fixed inset-x-3 bottom-[88px] z-40 mx-auto max-w-md">
      <div className="relative overflow-hidden rounded-2xl border border-primary/30 bg-gradient-to-br from-primary/15 via-primary/8 to-card/95 p-3 shadow-[0_8px_30px_rgba(0,0,0,0.4)] backdrop-blur-md">
        <button
          aria-label="Kapat"
          onClick={handleDismiss}
          className="absolute right-2 top-2 rounded-full p-1 text-muted-foreground hover:bg-muted hover:text-foreground"
        >
          <X className="h-3.5 w-3.5" />
        </button>

        <div className="flex items-start gap-3 pr-5">
          <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-xl bg-primary/15">
            <ShieldCheck className="h-5 w-5 text-primary" />
          </div>
          <div className="min-w-0 flex-1">
            <p className="text-sm font-semibold text-foreground">
              Sovereign kimliğini tamamla
            </p>
            <p className="mt-0.5 text-xs text-muted-foreground">
              KYC doğrulaması ile altın taç, ödeme alma ve tüm Egemenlik haklarını aç.
            </p>
            <Link
              to="/kyc"
              className="mt-2 inline-flex items-center gap-1 rounded-lg bg-primary px-3 py-1.5 text-xs font-semibold text-primary-foreground active:scale-95"
            >
              Şimdi doğrula →
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

