import { useEffect } from "react";
import { useNavigate } from "@tanstack/react-router";
import { ShieldCheck, X, Sparkles } from "lucide-react";
import { hapticTap } from "@/lib/native";

interface Props {
  open: boolean;
  onClose: () => void;
  /** Where the user wanted to go — preserved as `?redirect=` for post-login. */
  intendedPath?: string;
  /** Optional override for the hero copy. */
  appLabel?: string;
}

export function SovereignGlassLogin({ open, onClose, intendedPath, appLabel }: Props) {
  const navigate = useNavigate();

  useEffect(() => {
    if (!open) return;
    const onEsc = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    document.addEventListener("keydown", onEsc);
    return () => document.removeEventListener("keydown", onEsc);
  }, [open, onClose]);

  if (!open) return null;

  const goLogin = () => {
    hapticTap();
    onClose();
    navigate({
      to: "/login",
      search: intendedPath ? { redirect: intendedPath } : undefined,
    });
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label="Egemen Kimlik gerekli"
