      {/* Glass card */}
      <div
        className="relative w-full max-w-sm rounded-[28px] p-7 text-center"
        style={{
          background:
            "linear-gradient(165deg, rgba(40,28,5,0.85), rgba(8,5,0,0.96))",
          border: "1px solid rgba(212,175,55,0.45)",
          boxShadow:
            "0 30px 80px -20px rgba(0,0,0,0.9), inset 0 1px 0 rgba(253,230,138,0.25), 0 0 60px -20px rgba(245,205,83,0.4)",
          animation: "scale-in 280ms cubic-bezier(0.34,1.56,0.64,1) both",
        }}
      >
        <button
          type="button"
          onClick={onClose}
          aria-label="Kapat"
          className="absolute right-3 top-3 rounded-full p-1.5 text-amber-200/70 hover:text-amber-100 hover:bg-amber-400/10 transition-colors"
        >
          <X className="h-4 w-4" />
        </button>

        {/* Crest */}
        <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-2xl"
          style={{
            background:
              "radial-gradient(120% 100% at 0% 0%, rgba(212,175,55,0.45), rgba(8,5,0,0.95) 70%)",
            border: "1px solid rgba(212,175,55,0.55)",
            boxShadow: "inset 0 1px 0 rgba(255,234,170,0.3), 0 8px 24px -8px rgba(0,0,0,0.8)",
          }}
        >
          <ShieldCheck className="h-8 w-8" style={{ color: "#F5CD53", filter: "drop-shadow(0 0 8px rgba(245,205,83,0.6))" }} />
        </div>

        <div className="text-[10px] uppercase tracking-[0.32em] mb-1.5" style={{ color: "#D4AF37" }}>
          Sovereign Wall
        </div>
        <h2 className="text-xl font-semibold tracking-tight" style={{ color: "#FFE9A8" }}>
          {appLabel ? `${appLabel} kilitli` : "Egemen Mühür Gerekli"}
