/**
 * StarRingProgress — 21-ray Stêrka Geş progress ring used by the
 * Authenticator. The radial rays shorten/extend as the 30-second TOTP
 * window winds down; a soft gold halo pulses while > 5 s remain and
 * shifts to amber-rose under 5 s as a "rotate now" hint.
 *
 * Pure SVG — no canvas, no rAF beyond CSS, safe inside route trees.
 */
interface StarRingProgressProps {
  /** 0–1 progress (1 = full window remaining, 0 = expired). */
  progress: number;
  /** The TOTP code to render in the centre. */
  code: string;
  /** Seconds left, shown as small label under the code. */
  seconds: number;
  size?: number;
}

const RAYS = 21;

export function StarRingProgress({
  progress,
  code,
  seconds,
  size = 220,
}: StarRingProgressProps) {
  const safe = Math.max(0, Math.min(1, progress));
  const cx = size / 2;
  const cy = size / 2;
  const innerR = size * 0.34;
  const outerRMax = size * 0.46;
  const urgent = seconds <= 5;

  const rays = Array.from({ length: RAYS }, (_, i) => {
    const angle = (i / RAYS) * Math.PI * 2 - Math.PI / 2;
    const isLit = i / RAYS < safe;
    const length = isLit ? outerRMax : innerR + (outerRMax - innerR) * 0.25;
    const x1 = cx + Math.cos(angle) * innerR;
    const y1 = cy + Math.sin(angle) * innerR;
    const x2 = cx + Math.cos(angle) * length;
    const y2 = cy + Math.sin(angle) * length;
    return { x1, y1, x2, y2, isLit };
  });

  const formatted = code.length === 6 ? `${code.slice(0, 3)} ${code.slice(3)}` : code;

  return (
    <div className="relative inline-flex items-center justify-center" style={{ width: size, height: size }}>
      <svg viewBox={`0 0 ${size} ${size}`} width={size} height={size} aria-hidden="true">
        <defs>
          <radialGradient id="star-ring-core" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor={urgent ? "rgba(248, 113, 113, 0.28)" : "rgba(253, 230, 138, 0.30)"} />
            <stop offset="70%" stopColor="rgba(0,0,0,0)" />
          </radialGradient>
          <linearGradient id="star-ring-ray" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor={urgent ? "#fca5a5" : "#fde68a"} />
            <stop offset="100%" stopColor={urgent ? "#b91c1c" : "#b8860b"} />
          </linearGradient>
          <linearGradient id="star-ring-dim" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="rgba(245, 200, 80, 0.22)" />
            <stop offset="100%" stopColor="rgba(184, 134, 11, 0.10)" />
          </linearGradient>
        </defs>

        {/* Soft halo */}
        <circle cx={cx} cy={cy} r={outerRMax + 4} fill="url(#star-ring-core)" />

        {/* Rays */}
        {rays.map((r, i) => (
          <line
            key={i}
            x1={r.x1}
            y1={r.y1}
            x2={r.x2}
            y2={r.y2}
            stroke={r.isLit ? "url(#star-ring-ray)" : "url(#star-ring-dim)"}
            strokeWidth={r.isLit ? 3.2 : 1.8}
            strokeLinecap="round"
            style={{ transition: "all 300ms cubic-bezier(0.22,1,0.36,1)" }}
          />
        ))}

        {/* Inner gold rim */}
        <circle
          cx={cx}
          cy={cy}
          r={innerR - 3}
          fill="none"
          stroke="rgba(245, 200, 80, 0.45)"
          strokeWidth="1"
        />
      </svg>

      {/* Centre code */}
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span
          className={`font-mono tabular-nums tracking-[0.35em] text-3xl font-semibold ${
            urgent ? "text-rose-300" : "text-amber-100"
          }`}
          style={{ textShadow: urgent ? "0 0 14px rgba(248,113,113,0.45)" : "0 0 14px rgba(253,230,138,0.35)" }}
        >
          {formatted}
        </span>
        <span className="mt-1 text-[10px] uppercase tracking-[0.25em] text-amber-200/55">
          {seconds}s · Egemen Kod
        </span>
      </div>
    </div>
  );
}

