/**
 * BootSplash — Apple-style cold boot screen for Jiyan.world.
 *
 * Mounted once at app launch (per session). Shows the Sovereign Star
 * (Keka logo) on pure obsidian, then fades away. SSR-safe: gated to
 * the client and to a `sessionStorage` flag so subsequent route
 * navigations never re-trigger the boot animation.
 *
 * Behaviour:
 *   • Visible for ~1100ms then fade-out (300ms).
 *   • Tap anywhere to skip immediately.
 *   • Skipped entirely on iframes (Lovable preview never blocks).
 */
import { useEffect, useState } from "react";
import { SovereignStar } from "@/components/keka/SovereignStar";
import { playBootChime } from "@/lib/systemSounds";

const SESSION_KEY = "jiyan_boot_splash_seen_v1";

export function BootSplash() {
  const [phase, setPhase] = useState<"hidden" | "visible" | "fading">("hidden");

  useEffect(() => {
    if (typeof window === "undefined") return;

    // Skip in Lovable iframe preview to avoid covering hot-reloads.
    let inIframe = false;
    try {
      inIframe = window.self !== window.top;
    } catch {
      inIframe = true;
    }
    if (inIframe) return;

    try {
      if (sessionStorage.getItem(SESSION_KEY)) return;
      sessionStorage.setItem(SESSION_KEY, "1");
    } catch {
      /* storage blocked → still show once */
    }

    setPhase("visible");
    // Fire the Apple-style 1.5s shimmer chime in sync with the star pulse.
    // (No-op silently if the browser blocks autoplay before any gesture.)
    try { playBootChime(); } catch {}
    const fade = window.setTimeout(() => setPhase("fading"), 1500);
    const done = window.setTimeout(() => setPhase("hidden"), 1850);
    return () => {
      window.clearTimeout(fade);
      window.clearTimeout(done);
    };
  }, []);

  if (phase === "hidden") return null;

  return (
    <div
      role="presentation"
      aria-hidden
      onClick={() => setPhase("hidden")}
      className="fixed inset-0 z-[9999] flex flex-col items-center justify-center"
      style={{
        background:
          "radial-gradient(120% 90% at 50% 45%, #0a0700 0%, #050300 55%, #000 100%)",
        opacity: phase === "fading" ? 0 : 1,
        transition: "opacity 320ms cubic-bezier(0.4, 0, 0.2, 1)",
        pointerEvents: phase === "fading" ? "none" : "auto",
      }}
    >
      {/* Soft golden halo */}
      <div
        className="absolute"
        style={{
          width: 380,
          height: 380,
          borderRadius: "50%",
          background:
            "radial-gradient(circle, rgba(212,175,55,0.22) 0%, rgba(212,175,55,0.05) 45%, transparent 70%)",
          filter: "blur(8px)",
          animation: "boot-halo-pulse 2.4s ease-in-out infinite",
        }}
      />

      {/* The Star */}
      <div
        className="relative"
        style={{
          animation: "boot-star-rise 900ms cubic-bezier(0.22, 1, 0.36, 1) both",
        }}
      >
        <SovereignStar size={120} glow />
      </div>

      {/* Wordmark */}
      <div
        className="mt-9 text-center"
        style={{
          animation: "boot-word-rise 900ms 200ms cubic-bezier(0.22, 1, 0.36, 1) both",
        }}
      >
        <div
          className="text-[10px] uppercase font-semibold"
          style={{
            letterSpacing: "0.5em",
            color: "#D4AF37",
            textShadow: "0 0 14px rgba(212,175,55,0.45)",
          }}
        >
          Jiyan
        </div>
        <div
          className="mt-1.5 text-[9px] uppercase"
          style={{
            letterSpacing: "0.4em",
            color: "rgba(245, 222, 179, 0.55)",
          }}
        >
          Sovereign OS
        </div>
      </div>

      {/* Bottom progress hairline */}
      <div
        className="absolute"
        style={{
          bottom: "9%",
          width: 64,
          height: 2,
          borderRadius: 999,
          background:
            "linear-gradient(90deg, transparent, #D4AF37, transparent)",
          animation: "boot-bar-shimmer 1.4s linear infinite",
          opacity: 0.6,
        }}
      />

      <style>{`
        @keyframes boot-star-rise {
          0% { opacity: 0; transform: scale(0.6) translateY(8px); filter: blur(6px); }
          60% { opacity: 1; filter: blur(0); }
          100% { opacity: 1; transform: scale(1) translateY(0); filter: blur(0); }
        }
        @keyframes boot-word-rise {
          0% { opacity: 0; transform: translateY(10px); }
          100% { opacity: 1; transform: translateY(0); }
        }
        @keyframes boot-halo-pulse {
          0%, 100% { opacity: 0.55; transform: scale(1); }
          50% { opacity: 0.9; transform: scale(1.08); }
        }
        @keyframes boot-bar-shimmer {
          0% { transform: translateX(-30px); opacity: 0.2; }
          50% { opacity: 0.8; }
          100% { transform: translateX(30px); opacity: 0.2; }
        }
      `}</style>
    </div>
  );
}

