const ACTION_BADGE: Record<string, string> = {
  role_change: "bg-amber-400/15 text-amber-200 border-amber-400/30",
  member_added: "bg-emerald-400/15 text-emerald-300 border-emerald-400/30",
  member_removed: "bg-red-500/15 text-red-300 border-red-500/30",
