import { useState, useEffect } from "react";
import { Lock, Delete } from "lucide-react";

interface ChatLockScreenProps {
  onUnlock: () => void;
}

export function ChatLockScreen({ onUnlock }: ChatLockScreenProps) {
  const [pin, setPin] = useState("");
  const [error, setError] = useState(false);
  const [isSetup, setIsSetup] = useState(false);
  const [confirmPin, setConfirmPin] = useState("");
  const [step, setStep] = useState<"enter" | "confirm">("enter");

  useEffect(() => {
    const storedPin = localStorage.getItem("jiyan_chat_pin");
    setIsSetup(!!storedPin);
  }, []);

  const handleDigit = (digit: string) => {
    if (pin.length >= 4) return;
    const newPin = pin + digit;
    setPin(newPin);
    setError(false);

    if (newPin.length === 4) {
      if (!isSetup) {
        if (step === "enter") {
          setConfirmPin(newPin);
          setStep("confirm");
          setPin("");
        } else {
          if (newPin === confirmPin) {
            localStorage.setItem("jiyan_chat_pin", newPin);
            onUnlock();
          } else {
            setError(true);
            setPin("");
            setStep("enter");
            setConfirmPin("");
          }
        }
      } else {
        const storedPin = localStorage.getItem("jiyan_chat_pin");
        if (newPin === storedPin) {
          onUnlock();
        } else {
          setError(true);
          setTimeout(() => setPin(""), 300);
        }
      }
    }
  };

  const handleDelete = () => {
    setPin((p) => p.slice(0, -1));
    setError(false);
  };

  const title = !isSetup
    ? step === "enter"
      ? "PIN Oluştur"
      : "PIN'i Tekrarla"
    : "Sohbet Kilidi";

  return (
    <div className="flex h-screen flex-col items-center justify-center bg-background px-8">
      <div className="mb-8 flex h-16 w-16 items-center justify-center rounded-2xl bg-neon/10">
        <Lock className="h-8 w-8 text-neon" />
      </div>
      <h2 className="text-lg font-bold text-foreground mb-2">{title}</h2>
      <p className="text-xs text-muted-foreground mb-8">
        {!isSetup ? "4 haneli PIN belirleyin" : "Sohbetlere erişmek için PIN girin"}
      </p>

      {/* PIN dots */}
      <div className="flex gap-3 mb-10">
        {[0, 1, 2, 3].map((i) => (
          <div
            key={i}
            className={`h-3.5 w-3.5 rounded-full transition-all duration-200 ${
              i < pin.length
                ? error
                  ? "bg-destructive scale-110"
                  : "bg-neon scale-110"
                : "bg-border"
            } ${error ? "animate-shake" : ""}`}
          />
        ))}
      </div>

      {error && (
        <p className="text-xs text-destructive mb-4 animate-in fade-in">
          {!isSetup ? "PIN'ler eşleşmedi" : "Yanlış PIN"}
        </p>
      )}

      {/* Keypad */}
      <div className="grid grid-cols-3 gap-4">
        {["1", "2", "3", "4", "5", "6", "7", "8", "9", "", "0", "del"].map((key) =>
          key === "" ? (
            <div key="empty" />
          ) : key === "del" ? (
            <button
              key="del"
              onClick={handleDelete}
              className="flex h-16 w-16 items-center justify-center rounded-full text-muted-foreground active:bg-accent transition-colors"
            >
              <Delete className="h-5 w-5" />
            </button>
          ) : (
            <button
              key={key}
              onClick={() => handleDigit(key)}
              className="flex h-16 w-16 items-center justify-center rounded-full bg-surface text-xl font-medium text-foreground active:bg-neon/20 active:scale-95 transition-all"
            >
              {key}
            </button>
          )
        )}
      </div>
    </div>
  );
}

