import { useState, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Image, Video, FileText, MapPin, X, Loader2 } from "lucide-react";

interface ChatMediaUploadProps {
  userId: string;
  roomId: string;
  onMediaSent: (mediaUrl: string, messageType: string, fileName: string, fileSize: number) => void;
  onClose: () => void;
}

const ACCEPT_MAP: Record<string, string> = {
  image: "image/*",
  video: "video/*",
  file: ".pdf,.doc,.docx,.xls,.xlsx,.txt,.zip,.rar",
};

export function ChatMediaUpload({ userId, roomId, onMediaSent, onClose }: ChatMediaUploadProps) {
  const [uploading, setUploading] = useState(false);
  const [preview, setPreview] = useState<{ url: string; type: string; file: File } | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const handlePick = (type: string) => {
    if (fileRef.current) {
      fileRef.current.accept = ACCEPT_MAP[type] || "*/*";
      fileRef.current.dataset.type = type;
      fileRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const type = e.target.dataset.type || "file";

    if (type === "image" || type === "video") {
      const url = URL.createObjectURL(file);
      setPreview({ url, type, file });
    } else {
      uploadAndSend(file, "file");
    }
  };

  const uploadAndSend = async (file: File, type: string) => {
    setUploading(true);
    const ext = file.name.split(".").pop();
    const path = `${userId}/${roomId}/${Date.now()}.${ext}`;

    const { error } = await supabase.storage.from("chat-media").upload(path, file, {
      cacheControl: "3600",
      upsert: false,
    });

    if (error) {
      console.error("Upload error:", error);
      setUploading(false);
      return;
    }

    const { data: urlData } = supabase.storage.from("chat-media").getPublicUrl(path);
    onMediaSent(urlData.publicUrl, type, file.name, file.size);
    setPreview(null);
    setUploading(false);
    onClose();
  };

  const handleShareLocation = () => {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords;
        const mapUrl = `https://www.google.com/maps?q=${latitude},${longitude}`;
        onMediaSent(mapUrl, "location", "Konum", 0);
        onClose();
      },
      () => alert("Konum alınamadı")
    );
  };

  return (
    <>
      <input ref={fileRef} type="file" className="hidden" onChange={handleFileChange} />

      {/* Preview overlay */}
      {preview && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4">
          <div className="relative w-full max-w-sm rounded-2xl bg-surface p-4 space-y-3">
            <button onClick={() => { setPreview(null); URL.revokeObjectURL(preview.url); }} className="absolute top-3 right-3 text-muted-foreground hover:text-foreground">
              <X className="h-5 w-5" />
            </button>
            {preview.type === "image" ? (
              <img src={preview.url} alt="preview" className="w-full rounded-xl max-h-64 object-contain" />
            ) : (
              <video src={preview.url} controls className="w-full rounded-xl max-h-64" />
            )}
            <p className="text-xs text-muted-foreground truncate">{preview.file.name}</p>
            <button
              onClick={() => uploadAndSend(preview.file, preview.type)}
              disabled={uploading}
              className="w-full rounded-xl bg-neon py-2.5 text-sm font-semibold text-neon-foreground disabled:opacity-50 flex items-center justify-center gap-2"
            >
              {uploading ? <><Loader2 className="h-4 w-4 animate-spin" /> Yükleniyor...</> : "Gönder"}
            </button>
          </div>
        </div>
      )}

      {/* Media picker buttons */}
      <div className="flex items-center gap-1 rounded-xl border border-border bg-surface p-1.5 animate-in fade-in">
        <button onClick={() => handlePick("image")} className="flex flex-col items-center gap-0.5 rounded-lg px-3 py-2 hover:bg-accent transition-colors">
          <Image className="h-5 w-5 text-blue-400" />
          <span className="text-[9px] text-muted-foreground">Resim</span>
        </button>
        <button onClick={() => handlePick("video")} className="flex flex-col items-center gap-0.5 rounded-lg px-3 py-2 hover:bg-accent transition-colors">
          <Video className="h-5 w-5 text-red-400" />
          <span className="text-[9px] text-muted-foreground">Video</span>
        </button>
        <button onClick={() => handlePick("file")} className="flex flex-col items-center gap-0.5 rounded-lg px-3 py-2 hover:bg-accent transition-colors">
          <FileText className="h-5 w-5 text-amber-400" />
          <span className="text-[9px] text-muted-foreground">Dosya</span>
        </button>
        <button onClick={handleShareLocation} className="flex flex-col items-center gap-0.5 rounded-lg px-3 py-2 hover:bg-accent transition-colors">
          <MapPin className="h-5 w-5 text-emerald-400" />
          <span className="text-[9px] text-muted-foreground">Konum</span>
        </button>
      </div>
    </>
  );
}

