import { useState } from "react";
import { Link } from "@tanstack/react-router";
import { toast } from "sonner";
import { Ban, MicOff, Mic, Loader2, ShieldAlert, Undo2 } from "lucide-react";
import { StarAvatar } from "@/components/sovereign/StarAvatar";
import { resolveHandle } from "@/lib/handle";
import { chatAdmin, useChatBans } from "@/hooks/useChatModeration";

export interface ModerationMember {
  user_id: string;
  display_name: string;
  avatar_url: string | null;
  is_premium: boolean;
  username: string | null;
  kurd_id: string | null;
  role: string;
  is_muted?: boolean;
}

interface ChatModerationPanelProps {
  roomId: string;
  selfUserId: string;
  members: ModerationMember[];
  onChanged: () => void;
}

export function ChatModerationPanel({
  roomId,
  selfUserId,
  members,
  onChanged,
}: ChatModerationPanelProps) {
  const { bans, loading: bansLoading } = useChatBans(roomId);
  const [busy, setBusy] = useState<string | null>(null);

  const targetable = members.filter((m) => m.user_id !== selfUserId);

  const wrap = async (key: string, fn: () => Promise<{ ok: boolean; error?: string }>, ok: string) => {
    setBusy(key);
    try {
      const r = await fn();
      if (!r.ok) toast.error(r.error || "İşlem başarısız");
      else {
        toast.success(ok);
        onChanged();
      }
    } finally {
      setBusy(null);
    }
  };

  const handleMute = (m: ModerationMember) =>
    wrap(
      `mute-${m.user_id}`,
      () => chatAdmin.setMute(roomId, m.user_id, !m.is_muted),
      m.is_muted ? "Susturma kaldırıldı" : "Susturuldu"
    );

  const handleBan = (m: ModerationMember) => {
    const reason = window.prompt(`${m.display_name} kullanıcısını neden banlıyorsun? (opsiyonel)`) ?? undefined;
    if (reason === undefined) return;
    return wrap(`ban-${m.user_id}`, () => chatAdmin.banUser(roomId, m.user_id, reason || undefined), "Banlandı");
  };

  const handleUnban = (userId: string) =>
    wrap(`unban-${userId}`, () => chatAdmin.unbanUser(roomId, userId), "Ban kaldırıldı");

  return (
    <div className="space-y-5 px-4 py-3">
      {/* Active members → mute / ban */}
      <section>
        <div className="mb-2 flex items-center gap-2">
          <ShieldAlert className="h-4 w-4 text-amber-300" />
          <h4 className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
            Moderasyon — Aktif Üyeler ({targetable.length})
          </h4>
        </div>

        {targetable.length === 0 ? (
          <p className="rounded-xl border border-dashed border-border/60 bg-black/30 px-4 py-5 text-center text-[11px] text-muted-foreground">
            Yönetilecek başka üye yok.
          </p>
        ) : (
          <ul className="space-y-1">
            {targetable.map((m) => {
              const handle = resolveHandle({
                username: m.username,
                kurd_id: m.kurd_id,
                display_name: null,
              });
              const muteKey = `mute-${m.user_id}`;
              const banKey = `ban-${m.user_id}`;
              return (
                <li
                  key={m.user_id}
                  className="flex items-center gap-3 rounded-xl border border-border/40 bg-surface/40 p-2"
                >
                  <Link to="/sovereign-profile" search={{ u: m.user_id }} className="shrink-0">
                    <StarAvatar
                      src={m.avatar_url}
                      name={m.display_name}
                      size={36}
                      premium={m.is_premium}
                      tone={m.role === "admin" ? "amber" : "gold"}
                    />
                  </Link>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-xs font-semibold text-foreground">
                      {m.display_name}
                      {m.is_muted && (
                        <span className="ml-1.5 rounded-full border border-orange-400/30 bg-orange-400/10 px-1.5 py-0 text-[9px] font-medium text-orange-300">
                          sustur
                        </span>
                      )}
                    </p>
                    <p className="truncate text-[10px] text-muted-foreground">{handle}</p>
                  </div>
                  <button
                    onClick={() => handleMute(m)}
                    disabled={busy === muteKey}
                    aria-label={m.is_muted ? "Susturmayı kaldır" : "Sustur"}
                    title={m.is_muted ? "Susturmayı kaldır" : "Mesaj atmasını engelle"}
                    className={`flex h-8 w-8 items-center justify-center rounded-lg border transition ${
                      m.is_muted
                        ? "border-emerald-400/40 bg-emerald-400/10 text-emerald-300 hover:bg-emerald-400/20"
                        : "border-orange-400/40 bg-orange-400/10 text-orange-300 hover:bg-orange-400/20"
                    } disabled:opacity-50`}
                  >
                    {busy === muteKey ? (
                      <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    ) : m.is_muted ? (
                      <Mic className="h-3.5 w-3.5" />
                    ) : (
                      <MicOff className="h-3.5 w-3.5" />
                    )}
                  </button>
                  <button
                    onClick={() => handleBan(m)}
                    disabled={busy === banKey}
                    aria-label="Banla"
                    title="Bu odadan banla (yeniden katılamaz)"
                    className="flex h-8 w-8 items-center justify-center rounded-lg border border-red-500/40 bg-red-500/10 text-red-300 transition hover:bg-red-500/20 disabled:opacity-50"
                  >
                    {busy === banKey ? (
                      <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    ) : (
                      <Ban className="h-3.5 w-3.5" />
                    )}
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </section>

      {/* Banned list → unban */}
      <section>
        <div className="mb-2 flex items-center gap-2">
          <Ban className="h-4 w-4 text-red-400" />
          <h4 className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
            Banlı Kullanıcılar ({bans.length})
          </h4>
        </div>
        {bansLoading ? (
          <div className="flex items-center justify-center py-6">
            <Loader2 className="h-4 w-4 animate-spin text-amber-300" />
          </div>
        ) : bans.length === 0 ? (
          <p className="rounded-xl border border-dashed border-border/60 bg-black/30 px-4 py-5 text-center text-[11px] text-muted-foreground">
            Bu odada hiç banlı kullanıcı yok.
          </p>
        ) : (
          <ul className="space-y-1">
            {bans.map((b) => {
              const handle = resolveHandle({
                username: b.username,
                kurd_id: b.kurd_id,
                display_name: null,
              });
              const key = `unban-${b.user_id}`;
              return (
                <li
                  key={b.id}
                  className="flex items-center gap-3 rounded-xl border border-red-500/20 bg-red-500/5 p-2"
                >
                  <Link to="/sovereign-profile" search={{ u: b.user_id }} className="shrink-0">
                    <StarAvatar
                      src={b.avatar_url}
                      name={b.display_name || "Sovereign"}
                      size={36}
                      tone="gold"
                    />
                  </Link>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-xs font-semibold text-foreground">
                      {b.display_name || "Sovereign"}
                    </p>
                    <p className="truncate text-[10px] text-muted-foreground">
                      {handle}
                      {b.reason ? ` · ${b.reason}` : ""}
                    </p>
                  </div>
                  <button
                    onClick={() => handleUnban(b.user_id)}
                    disabled={busy === key}
                    className="flex items-center gap-1 rounded-lg border border-emerald-400/40 bg-emerald-400/10 px-2.5 py-1 text-[10px] font-semibold text-emerald-300 hover:bg-emerald-400/20 disabled:opacity-50"
                  >
                    {busy === key ? (
                      <Loader2 className="h-3 w-3 animate-spin" />
                    ) : (
                      <Undo2 className="h-3 w-3" />
                    )}
                    Banı kaldır
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </section>
    </div>
  );
}

