import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Megaphone, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";

interface CreateChannelFormProps {
  userId: string;
  onCreated: () => void;
  onCancel: () => void;
}

export function CreateChannelForm({ userId, onCreated, onCancel }: CreateChannelFormProps) {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [creating, setCreating] = useState(false);

  const handleCreate = async () => {
    if (!name.trim()) return;
    setCreating(true);

    const { data: room } = await supabase
      .from("chat_rooms")
      .insert({
        type: "channel",
        name: name.trim(),
        description: description.trim() || null,
        created_by: userId,
      })
      .select()
      .single();

    if (room) {
      await supabase.from("chat_members").insert({
        room_id: room.id,
        user_id: userId,
        role: "admin",
      });
    }

    setCreating(false);
    onCreated();
  };

  return (
    <div className="rounded-xl border border-border bg-surface p-4 space-y-3">
      <div className="flex items-center gap-2">
        <Megaphone className="h-4 w-4 text-neon" />
        <h3 className="text-sm font-semibold text-foreground">Yeni Kanal Oluştur</h3>
      </div>
      <p className="text-[10px] text-muted-foreground">
        Kanallar tek yönlü yayın içindir. Yalnızca yöneticiler gönderi paylaşabilir.
      </p>
      <input
        type="text"
        placeholder="Kanal adı..."
        value={name}
        onChange={(e) => setName(e.target.value)}
        className="h-10 w-full rounded-lg border border-border bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:border-neon"
      />
      <textarea
        placeholder="Kanal açıklaması (opsiyonel)..."
        value={description}
        onChange={(e) => setDescription(e.target.value)}
        rows={2}
        className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground resize-none focus:outline-none focus:border-neon"
      />
      <div className="flex gap-2">
        <Button variant="outline" size="sm" className="flex-1" onClick={onCancel}>
          İptal
        </Button>
        <Button variant="neon" size="sm" className="flex-1" onClick={handleCreate} disabled={!name.trim() || creating}>
