/**
 * Deng3DBubble — parallax-tilting 3D bubble shell.
 *
 * Wraps the existing message body. On pointer move we tilt the bubble along
 * X/Y based on cursor position relative to the bubble's bounding rect. Pure
 * CSS transforms — no JS animation runtime.
 */
import { ReactNode, useRef } from "react";

interface Deng3DBubbleProps {
  isMe: boolean;
  isChannel?: boolean;
  isGhost?: boolean;
  children: ReactNode;
}

export function Deng3DBubble({ isMe, isChannel, isGhost, children }: Deng3DBubbleProps) {
  const ref = useRef<HTMLDivElement>(null);

  const handleMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const el = ref.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const dx = (e.clientX - rect.left) / rect.width - 0.5; // -0.5..0.5
    const dy = (e.clientY - rect.top) / rect.height - 0.5;
    // Subtle — overshooting feels gimmicky on tiny chat bubbles.
    el.style.transform = `perspective(600px) rotateX(${(-dy * 8).toFixed(2)}deg) rotateY(${(dx * 8).toFixed(2)}deg) translateZ(2px)`;
  };

  const handleLeave = () => {
    const el = ref.current;
    if (!el) return;
    el.style.transform = "perspective(600px) rotateX(0) rotateY(0) translateZ(0)";
  };

  // Channel posts use a flat slab to keep the long-form layout legible.
  if (isChannel) {
    return (
      <div className="w-full max-w-full px-3 py-2 rounded-lg deng3d-bubble-you">
        {children}
      </div>
    );
  }

  if (isGhost) {
    return (
      <div
        className={`max-w-[78%] px-3 py-2 ${isMe ? "rounded-2xl rounded-br-sm" : "rounded-2xl rounded-bl-sm"}`}
        style={{
          background: "linear-gradient(180deg, rgba(168,85,247,0.25), rgba(76,29,149,0.4))",
          color: isMe ? "#fff" : "#E9D5FF",
          border: "1px solid rgba(168,85,247,0.35)",
          boxShadow:
            "inset 0 1px 0 rgba(216,180,254,0.3), 0 4px 12px rgba(76,29,149,0.4), 0 0 18px rgba(168,85,247,0.2)",
        }}
      >
        {children}
      </div>
    );
  }

  return (
    <div
      ref={ref}
      onPointerMove={handleMove}
      onPointerLeave={handleLeave}
      className={`max-w-[78%] px-3 py-2 ${
        isMe
          ? "rounded-2xl rounded-br-sm deng3d-bubble-me"
          : "rounded-2xl rounded-bl-sm deng3d-bubble-you"
      }`}
      style={{ transition: "transform 220ms cubic-bezier(0.34, 1.56, 0.64, 1)" }}
    >
      {children}
    </div>
  );
}

