/**
 * Deng3DTabs — floating gold pill segmented tabs with extruded depth.
 *
 * Replaces the flat underline tab strip. Each tab is a 3D capsule that
 * "lifts" when active, with a sliding gold lozenge that morphs underneath
 * (FLIP-style via measured rects). Pure CSS transforms.
 */
import { useEffect, useLayoutEffect, useRef, useState } from "react";

export interface Deng3DTabsProps<K extends string> {
  tabs: { key: K; label: string }[];
  active: K;
  onChange: (key: K) => void;
}

export function Deng3DTabs<K extends string>({ tabs, active, onChange }: Deng3DTabsProps<K>) {
  const containerRef = useRef<HTMLDivElement>(null);
  const btnRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const [pill, setPill] = useState<{ x: number; w: number } | null>(null);

  const measure = () => {
    const c = containerRef.current;
    const el = btnRefs.current[active];
    if (!c || !el) return;
    const cRect = c.getBoundingClientRect();
    const eRect = el.getBoundingClientRect();
    setPill({ x: eRect.left - cRect.left, w: eRect.width });
  };

  useLayoutEffect(measure, [active, tabs.length]);
  useEffect(() => {
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active]);

  return (
    <div
      ref={containerRef}
      className="relative mx-3 my-2 flex gap-1 overflow-x-auto scrollbar-none rounded-full p-1"
      style={{
        background:
          "linear-gradient(180deg, rgba(20,14,4,0.85) 0%, rgba(8,6,2,0.95) 100%)",
        border: "1px solid rgba(212,175,55,0.18)",
        boxShadow:
          "inset 0 1px 0 rgba(255,233,168,0.08), inset 0 -2px 6px rgba(0,0,0,0.6), 0 4px 14px rgba(0,0,0,0.55)",
      }}
    >
      {/* Sliding gold pill */}
      {pill && (
        <span
          aria-hidden
          className="absolute top-1 bottom-1 rounded-full pointer-events-none"
          style={{
            transform: `translate3d(${pill.x}px, 0, 0)`,
            width: pill.w,
            transition:
              "transform 380ms cubic-bezier(0.34, 1.56, 0.64, 1), width 380ms cubic-bezier(0.34, 1.56, 0.64, 1)",
            background:
              "linear-gradient(180deg, #FFE9A8 0%, #D4AF37 55%, #8C6A1B 100%)",
            boxShadow:
              "0 2px 0 #5a4413, 0 6px 14px rgba(212,175,55,0.45), inset 0 1px 0 rgba(255,255,255,0.55), inset 0 -2px 0 rgba(80,60,10,0.6)",
          }}
        />
      )}

      {tabs.map((t) => {
        const isActive = t.key === active;
        return (
          <button
            key={t.key}
            ref={(el) => { btnRefs.current[t.key] = el; }}
            onClick={() => onChange(t.key)}
            className="relative z-10 shrink-0 px-4 py-1.5 text-[12.5px] font-semibold tracking-tight transition-colors"
            style={{
              color: isActive ? "#1a1003" : "rgba(245,240,220,0.55)",
              textShadow: isActive
                ? "0 1px 0 rgba(255,247,214,0.7)"
                : "0 1px 2px rgba(0,0,0,0.6)",
            }}
          >
            {t.label}
          </button>
        );
      })}
    </div>
  );
}

