/**
 * Deng3DText — render chat content with iMessage-style screen effects.
 *
 * Inline syntax (mirrors the way users already type "emphasis"):
 *   ***SLAM***   — heavy crash-in animation, bold
 *   **LOUD**     — pulsing scale + neon glow
 *   *gentle*     — soft breathing italic
 *   _invisible_  — invisible-ink: blurred until tapped/hovered
 *   ~~wavy~~     — every character undulates independently
 *
 * Pure-emoji messages (≤3 emojis, nothing else) render extra-large with a
 * floating 3D wobble; hovering spins them around the Y axis.
 */
import { useMemo } from "react";

interface Deng3DTextProps {
  content: string;
  isMe: boolean;
}

const EMOJI_RE =
  /^(?:\p{Extended_Pictographic}(?:\u{FE0F}|\u{200D}\p{Extended_Pictographic})*\s*){1,3}$/u;

export function Deng3DText({ content, isMe }: Deng3DTextProps) {
  const trimmed = content.trim();

  // Emoji-only messages → big floating 3D
  const isEmojiOnly = useMemo(() => {
    if (!trimmed) return false;
    try {
      return EMOJI_RE.test(trimmed);
    } catch {
      return false;
    }
  }, [trimmed]);

  if (isEmojiOnly) {
    return (
      <span className="deng3d-emoji-only" role="img" aria-label="emoji">
        {trimmed}
      </span>
    );
  }

  return (
    <p
      className={`text-sm leading-relaxed ${isMe ? "text-[#1a1003]" : "text-[#F5F0DC]"}`}
      style={{
        textShadow: isMe
          ? "0 1px 0 rgba(255,247,214,0.5), 0 -1px 0 rgba(80,60,10,0.4)"
          : "0 1px 2px rgba(0,0,0,0.6), 0 0 6px rgba(212,175,55,0.15)",
      }}
    >
      {parseEffects(content)}
    </p>
  );
}

/**
 * Tokenize the text into plain spans + effect spans. Order matters:
 * triple-asterisk before double, double before single, etc.
 */
function parseEffects(text: string): React.ReactNode[] {
  const tokens: { kind: string; value: string }[] = [];
  // Ordered patterns — longest delimiters first.
  const patterns: { kind: string; re: RegExp }[] = [
    { kind: "slam", re: /\*\*\*([^*]+)\*\*\*/g },
    { kind: "loud", re: /\*\*([^*]+)\*\*/g },
    { kind: "gentle", re: /(?<!\w)\*([^*\n]+)\*(?!\w)/g },
    { kind: "ink", re: /(?<!\w)_([^_\n]+)_(?!\w)/g },
    { kind: "wavy", re: /~~([^~]+)~~/g },
  ];

  // Brute-force replace pass — convert markup into placeholder tokens.
  let working = text;
  const slots: { kind: string; value: string }[] = [];
  patterns.forEach(({ kind, re }) => {
    working = working.replace(re, (_, body) => {
      slots.push({ kind, value: body });
      return `\u0000${slots.length - 1}\u0000`;
    });
  });

  // Now split on the placeholder markers and rebuild.
  const parts = working.split(/\u0000(\d+)\u0000/);
  parts.forEach((part, i) => {
    if (i % 2 === 0) {
      if (part) tokens.push({ kind: "plain", value: part });
    } else {
      const slot = slots[Number(part)];
      if (slot) tokens.push(slot);
    }
  });

  return tokens.map((t, idx) => {
    switch (t.kind) {
      case "slam":
        return (
          <span key={idx} className="deng3d-fx-slam">
            {t.value}
          </span>
        );
      case "loud":
        return (
          <span key={idx} className="deng3d-fx-loud" style={{ color: "#FFE9A8" }}>
            {t.value}
          </span>
        );
      case "gentle":
        return (
          <span key={idx} className="deng3d-fx-gentle">
            {t.value}
          </span>
        );
      case "ink":
        return (
          <span key={idx} className="deng3d-fx-ink" tabIndex={0}>
            {t.value}
          </span>
        );
      case "wavy":
        return (
          <span key={idx} className="deng3d-fx-wavy">
            {t.value.split("").map((ch, ci) => (
              <span key={ci} style={{ animationDelay: `${ci * 60}ms` }}>
                {ch}
              </span>
            ))}
          </span>
        );
      default:
        return <span key={idx}>{t.value}</span>;
    }
  });
}

