import { toast } from "sonner";

interface Props {
  open: boolean;
  messageId: string | null;
  initialContent: string;
  onClose: () => void;
}

export function EditMessageDialog({ open, messageId, initialContent, onClose }: Props) {
  const [text, setText] = useState(initialContent);
  const [saving, setSaving] = useState(false);

  useEffect(() => { setText(initialContent); }, [initialContent, messageId]);

  if (!open || !messageId) return null;

  const handleSave = async () => {
    if (!text.trim()) { toast.error("Mesaj boş olamaz"); return; }
    setSaving(true);
    const { data, error } = await supabase.rpc("edit_message", {
      _message_id: messageId, _new_content: text.trim(),
    });
    setSaving(false);
    if (error) { toast.error(error.message); return; }
    const res = data as { success: boolean; error?: string };
    if (!res.success) { toast.error(res.error || "Düzenlenemedi"); return; }
    toast.success("Mesaj düzenlendi");
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[70] bg-background/95 flex flex-col">
      <div className="flex items-center justify-between p-4 border-b border-border">
