import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { X, Send, Search } from "lucide-react";
import { toast } from "sonner";

interface Props {
  open: boolean;
  messageId: string | null;
  userId: string;
  onClose: () => void;
}

interface Room {
  id: string;
  name: string | null;
  type: string;
  avatar_url: string | null;
  other_name?: string;
}

export function ForwardDialog({ open, messageId, userId, onClose }: Props) {
  const [rooms, setRooms] = useState<Room[]>([]);
  const [filter, setFilter] = useState("");
  const [sending, setSending] = useState<string | null>(null);

  useEffect(() => {
    if (!open || !userId) return;
    (async () => {
      const { data: members } = await supabase.from("chat_members")
        .select("room_id").eq("user_id", userId);
      const ids = (members || []).map((m) => m.room_id);
      if (ids.length === 0) { setRooms([]); return; }
      const { data: rs } = await supabase.from("chat_rooms")
        .select("id, name, type, avatar_url").in("id", ids);
      setRooms((rs as Room[]) || []);
    })();
  }, [open, userId]);

  if (!open || !messageId) return null;

  const filtered = rooms.filter((r) =>
    !filter || (r.name || "").toLowerCase().includes(filter.toLowerCase())
  );

  const handleForward = async (roomId: string) => {
    setSending(roomId);
    const { data, error } = await supabase.rpc("forward_message", {
      _source_message_id: messageId, _target_room_id: roomId,
    });
    setSending(null);
    if (error) { toast.error(error.message); return; }
    const res = data as { success: boolean; error?: string };
    if (!res.success) { toast.error(res.error || "İletilemedi"); return; }
    toast.success("Mesaj iletildi");
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[70] bg-background/95 flex flex-col">
      <div className="flex items-center justify-between p-4 border-b border-border">
        <button onClick={onClose}><X className="h-5 w-5" /></button>
        <h2 className="text-sm font-semibold">Mesajı İlet</h2>
        <div className="w-5" />
      </div>
      <div className="p-3 border-b border-border">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <input
            value={filter} onChange={(e) => setFilter(e.target.value)}
            placeholder="Sohbet ara..."
            className="w-full h-10 pl-10 pr-3 rounded-xl bg-surface border border-border text-sm"
          />
        </div>
      </div>
      <div className="flex-1 overflow-y-auto p-3 space-y-1">
        {filtered.length === 0 ? (
          <p className="py-12 text-center text-sm text-muted-foreground">Sohbet bulunamadı</p>
        ) : (
          filtered.map((r) => (
            <button
              key={r.id}
              onClick={() => handleForward(r.id)}
              disabled={sending === r.id}
              className="flex w-full items-center gap-3 p-3 rounded-xl hover:bg-surface transition disabled:opacity-50"
            >
              <div className="h-10 w-10 rounded-full bg-primary/15 flex items-center justify-center text-base">
                {r.type === "channel" ? "📢" : r.type === "group" ? "💬" : "👤"}
              </div>
              <p className="flex-1 text-left text-sm font-medium">{r.name || "Direkt mesaj"}</p>
              <Send className="h-4 w-4 text-primary" />
            </button>
          ))
        )}
      </div>
    </div>
  );
}

