}

type SettingsTab = "members" | "moderation" | "audit" | "topics";
type RoleFilter = "all" | "admin" | "moderator" | "member";
type OnlineFilter = "all" | "online" | "offline";

interface Topic {
  id: string;
  name: string | null;
  topic_icon: string | null;
  topic_color: string | null;
  topic_order: number;
}

interface SearchHit {
  user_id: string;
  display_name: string;
  avatar_url: string | null;
  is_online?: boolean;
  is_premium?: boolean;
  kurd_id?: string | null;
  username?: string | null;
}

interface GroupSettingsProps {
  roomId: string;
  userId: string;
  isAdmin: boolean;
  onClose: () => void;
  onRoomUpdated: () => void;
  /** Called after the room is deleted or the user leaves it. */
  onRoomGone?: () => void;
}

export function GroupSettings({
  roomId,
  userId,
  isAdmin,
  onClose,
  onRoomUpdated,
  onRoomGone,
}: GroupSettingsProps) {
  const [members, setMembers] = useState<Member[]>([]);
  const [room, setRoom] = useState<{
    name: string | null;
    description: string | null;
    avatar_url: string | null;
    type: string;
    created_by: string | null;
    is_forum?: boolean;
  }>({ name: null, description: null, avatar_url: null, type: "group", created_by: null, is_forum: false });
  const [editing, setEditing] = useState(false);
  const [editName, setEditName] = useState("");
  const [editDesc, setEditDesc] = useState("");
  const [loading, setLoading] = useState(true);

  // Topics (forum mode)
  const [topics, setTopics] = useState<Topic[]>([]);
  const [forumBusy, setForumBusy] = useState(false);
  const [newTopicName, setNewTopicName] = useState("");
  const [newTopicIcon, setNewTopicIcon] = useState("💬");

  // Add-member panel
  const [showAdd, setShowAdd] = useState(false);
  const [addQuery, setAddQuery] = useState("");
  const [addResults, setAddResults] = useState<SearchHit[]>([]);
  const [addBusy, setAddBusy] = useState(false);

  // Mute toggle (own notification mute, local-only)
  const [muted, setMuted] = useState(false);

  // Tabs
  const [tab, setTab] = useState<SettingsTab>("members");

  // Member filters
  const [memberSearch, setMemberSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<RoleFilter>("all");
  const [onlineFilter, setOnlineFilter] = useState<OnlineFilter>("all");
  const [cityFilter, setCityFilter] = useState<string>("all");

  // Avatar upload
  const fileRef = useRef<HTMLInputElement | null>(null);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    fetchData();
  }, [roomId]);

  const isCreator = !!room.created_by && room.created_by === userId;
  const isChannel = room.type === "channel";
  const labelEntity = isChannel ? "Kanal" : "Grup";

  const fetchData = async () => {
    const [{ data: roomData }, { data: memberData }, { data: topicData }] = await Promise.all([
      supabase
        .from("chat_rooms")
        .select("name, description, avatar_url, type, created_by, is_forum")
        .eq("id", roomId)
        .single(),
      supabase.from("chat_members").select("id, user_id, role").eq("room_id", roomId),
      supabase
        .from("chat_rooms")
        .select("id, name, topic_icon, topic_color, topic_order")
        .eq("parent_room_id", roomId)
        .eq("is_topic", true)
        .order("topic_order", { ascending: true }),
    ]);

    if (roomData) {
      setRoom(roomData as typeof room);
      setEditName(roomData.name || "");
      setEditDesc(roomData.description || "");
    }

    if (topicData) setTopics(topicData as Topic[]);

    if (memberData) {
      const userIds = memberData.map((m) => m.user_id);
      const { data: profiles } = await supabase
        .from("profiles")
        .select("user_id, display_name, avatar_url, is_premium, username, kurd_id, city, is_online")
        .in("user_id", userIds);

      const profileMap = new Map(profiles?.map((p) => [p.user_id, p]) || []);
      setMembers(
        memberData.map((m) => {
          const p = profileMap.get(m.user_id);
          const row = m as { id: string; user_id: string; role: string; is_muted?: boolean };
          return {
            id: row.id,
            user_id: row.user_id,
            role: row.role,
            is_muted: !!row.is_muted,
            display_name: p?.display_name || "Kullanıcı",
            avatar_url: p?.avatar_url || null,
            is_premium: p?.is_premium || false,
            username: p?.username ?? null,
            kurd_id: p?.kurd_id ?? null,
            city: p?.city ?? null,
            is_online: !!p?.is_online,
          } as Member;
        })
      );
    }
    setLoading(false);
  };

  const handleToggleForum = async () => {
    setForumBusy(true);
    const enabled = !room.is_forum;
    const r = await chatAdmin.toggleForum(roomId, enabled);
    setForumBusy(false);
    if (!r.ok) {
      toast.error(r.error || "Forum modu değiştirilemedi");
      return;
    }
    toast.success(enabled ? "Forum modu açıldı" : "Forum modu kapatıldı");
    if (enabled && topics.length === 0) {
      // Seed default topics
      for (const t of DEFAULT_TOPICS) {
        await chatAdmin.createTopic(roomId, t.name, t.icon, t.color);
      }
      toast.success("Varsayılan konular eklendi");
    }
    fetchData();
    onRoomUpdated();
  };

  const handleCreateTopic = async () => {
    const name = newTopicName.trim();
    if (!name) return;
    setForumBusy(true);
    const r = await chatAdmin.createTopic(roomId, name, newTopicIcon || "💬", "gold");
    setForumBusy(false);
    if (!r.ok) {
      toast.error(r.error || "Konu oluşturulamadı");
      return;
    }
    toast.success(`#${name} konusu oluşturuldu`);
    setNewTopicName("");
    setNewTopicIcon("💬");
    fetchData();
    onRoomUpdated();
  };

  const handleSave = async () => {
    const { error } = await supabase
      .from("chat_rooms")
      .update({ name: editName.trim() || null, description: editDesc.trim() || null })
      .eq("id", roomId);
    if (error) {
      toast.error("Kaydedilemedi");
      return;
    }
    toast.success("Güncellendi");
    setEditing(false);
    onRoomUpdated();
    fetchData();
  };

  const handleRoleChange = async (targetUserId: string, newRole: string) => {
    const r = await chatAdmin.setRole(roomId, targetUserId, newRole as "member" | "moderator" | "admin");
    if (!r.ok) {
      toast.error(r.error || "Rol değiştirilemedi");
      return;
    }
    toast.success("Rol güncellendi");
    fetchData();
  };

  const handleRemoveMember = async (targetUserId: string, name: string) => {
    if (!confirm(`${name} adlı üyeyi gruptan çıkar?`)) return;
    const r = await chatAdmin.removeMember(roomId, targetUserId);
    if (!r.ok) {
      toast.error(r.error || "Üye çıkarılamadı");
      return;
    }
    toast.success(`${name} çıkarıldı`);
    fetchData();
  };

  const handleShareGroup = async () => {
    try {
      const token = await ensureGroupInviteToken(roomId);
      const url = `${window.location.origin}/chat?join=${token}`;
      const shareData = {
        title: room.name || `Sovereign ${labelEntity}`,
        text: `${room.name || `Bir ${labelEntity.toLowerCase()}a`} katıl — Jiyan Sohbet`,
        url,
      };
      if (typeof navigator !== "undefined" && navigator.share) {
        try {
          await navigator.share(shareData);
          return;
        } catch {
          // fall through to clipboard copy
        }
      }
      await navigator.clipboard.writeText(url);
      toast.success("Davet bağlantısı kopyalandı");
    } catch {
      toast.error("Davet bağlantısı oluşturulamadı");
    }
  };

  const handleCopyInvite = async () => {
    try {
      const token = await ensureGroupInviteToken(roomId);
      const url = `${window.location.origin}/chat?join=${token}`;
      await navigator.clipboard.writeText(url);
      toast.success("Bağlantı kopyalandı");
    } catch {
      toast.error("Kopyalama başarısız");
    }
  };

  const handleAvatarPick = () => fileRef.current?.click();

  const handleAvatarChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    if (!file.type.startsWith("image/")) {
      toast.error("Yalnızca görsel yüklenebilir");
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error("En fazla 5 MB");
      return;
    }
    setUploading(true);
    try {
      const ext = file.name.split(".").pop()?.toLowerCase() || "jpg";
      const path = `groups/${roomId}/${Date.now()}.${ext}`;
      const { error: upErr } = await supabase.storage
        .from("chat-media")
        .upload(path, file, { upsert: true, contentType: file.type });
      if (upErr) throw upErr;
      const { data: pub } = supabase.storage.from("chat-media").getPublicUrl(path);
      const { error: updErr } = await supabase
        .from("chat_rooms")
        .update({ avatar_url: pub.publicUrl })
        .eq("id", roomId);
      if (updErr) throw updErr;
      toast.success("Stêrka Geş güncellendi");
      onRoomUpdated();
      fetchData();
    } catch (err) {
      console.error(err);
      toast.error("Yükleme başarısız");
    } finally {
      setUploading(false);
    }
  };

  // Add-member search (debounced)
  useEffect(() => {
    if (!showAdd) return;
    if (!addQuery.trim() || addQuery.trim().length < 2) {
      setAddResults([]);
      return;
    }
    let cancelled = false;
    const t = setTimeout(async () => {
      try {
        const hits = (await searchUsers(addQuery.trim())) as SearchHit[];
        if (cancelled) return;
        const memberIds = new Set(members.map((m) => m.user_id));
        setAddResults(hits.filter((h) => !memberIds.has(h.user_id)).slice(0, 12));
      } catch {
        /* noop */
      }
    }, 220);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, [addQuery, showAdd, members]);

  const handleAddMember = async (target: SearchHit) => {
    setAddBusy(true);
    try {
      const r = await chatAdmin.addMember(roomId, target.user_id);
      if (!r.ok) {
        if (r.error?.includes("user_banned")) toast.error("Bu kullanıcı banlı");
        else toast.error(r.error || "Eklenemedi");
      } else {
        toast.success(`${target.display_name} eklendi`);
      }
      setAddQuery("");
      setAddResults([]);
      fetchData();
    } finally {
      setAddBusy(false);
    }
  };

  const handleLeave = async () => {
    if (!confirm(`${labelEntity}tan ayrıl?`)) return;
    const r = await chatAdmin.logLeave(roomId);
    if (!r.ok) {
      toast.error(r.error || "Ayrılınamadı");
      return;
    }
    toast.success("Ayrıldınız");
    onRoomGone?.();
    onClose();
  };

  const handleDeleteRoom = async () => {
    if (!confirm(`${labelEntity}u kalıcı olarak sil? Bu işlem geri alınamaz.`)) return;
    const r = await chatAdmin.deleteRoom(roomId);
    if (!r.ok) {
      toast.error(r.error || "Silinemedi");
      return;
    }
    toast.success(`${labelEntity} silindi`);
    onRoomGone?.();
    onClose();
  };

  const getRoleIcon = (role: string) => {
    if (role === "admin") return <Crown className="h-3 w-3 text-amber-300" />;
    if (role === "moderator") return <Shield className="h-3 w-3 text-emerald-400" />;
    return null;
  };

  const getRoleLabel = (role: string) => {
    if (role === "admin") return "Yönetici";
    if (role === "moderator") return "Moderatör";
    return "Üye";
  };

  return (
    <div className="flex h-full flex-col bg-background">
      {/* Glassmorphism header */}
      <div className="sticky top-0 z-10 flex items-center gap-3 border-b border-amber-400/15 bg-black/70 px-4 py-3 backdrop-blur-xl">
        <button onClick={onClose} className="text-muted-foreground hover:text-foreground">
          <X className="h-5 w-5" />
        </button>
        <h2 className="flex-1 text-sm font-semibold text-foreground">
          {labelEntity} Ayarları
        </h2>
        {isAdmin && !editing && (
          <button onClick={() => setEditing(true)} className="text-amber-300">
            <Edit2 className="h-4 w-4" />
          </button>
        )}
      </div>

      <div className="flex-1 overflow-y-auto">
        {/* Group identity */}
        <div className="border-b border-border px-4 py-5 text-center">
          <div className="relative mx-auto mb-3 h-24 w-24">
            <StarAvatar
              src={room.avatar_url}
              name={room.name || labelEntity}
              size={96}
              tone="gold"
            />
            {isAdmin && (
              <button
                onClick={handleAvatarPick}
                disabled={uploading}
                className="absolute -bottom-1 -right-1 flex h-8 w-8 items-center justify-center rounded-full border-2 border-black bg-amber-400 text-black shadow-lg transition active:scale-95 disabled:opacity-50"
                aria-label="Stêrka Geş güncelle"
                title="Grup fotoğrafını değiştir"
              >
                <Camera className="h-4 w-4" strokeWidth={2.4} />
              </button>
            )}
            <input
              ref={fileRef}
              type="file"
              accept="image/*"
              className="hidden"
              onChange={handleAvatarChange}
            />
          </div>

          {editing ? (
            <div className="mt-2 space-y-2">
              <input
                value={editName}
                onChange={(e) => setEditName(e.target.value)}
                placeholder={`${labelEntity} adı`}
                className="h-10 w-full rounded-lg border border-border bg-surface px-3 text-center text-sm text-foreground focus:border-amber-400 focus:outline-none"
              />
              <textarea
                value={editDesc}
                onChange={(e) => setEditDesc(e.target.value)}
                placeholder={`${labelEntity} açıklaması...`}
                rows={2}
                className="w-full resize-none rounded-lg border border-border bg-surface px-3 py-2 text-sm text-foreground focus:border-amber-400 focus:outline-none"
              />
              <div className="flex gap-2">
                <Button variant="outline" size="sm" className="flex-1" onClick={() => setEditing(false)}>
                  İptal
                </Button>
                <Button variant="neon" size="sm" className="flex-1" onClick={handleSave}>
                  <Check className="mr-1 h-3 w-3" /> Kaydet
                </Button>
              </div>
            </div>
          ) : (
            <>
              <h3 className="text-lg font-bold text-foreground">{room.name || labelEntity}</h3>
              {room.description && (
                <p className="mt-1 text-xs text-muted-foreground">{room.description}</p>
              )}
              <p className="mt-1 text-[10px] uppercase tracking-[0.2em] text-amber-300/60">
                {labelEntity} · {members.length} üye
              </p>
            </>
          )}
        </div>

        {/* Share */}
        <div className="grid grid-cols-2 gap-2 border-b border-border/60 px-4 py-3">
          <button
            onClick={handleShareGroup}
            className="flex items-center justify-center gap-2 rounded-xl border border-amber-400/30 bg-gradient-to-br from-amber-500/10 to-black/40 px-3 py-2.5 text-xs font-semibold text-amber-200 transition hover:border-amber-400/55"
          >
            <Share2 className="h-3.5 w-3.5" />
            {labelEntity}u Paylaş
          </button>
          <button
            onClick={handleCopyInvite}
            className="flex items-center justify-center gap-2 rounded-xl border border-border bg-surface/60 px-3 py-2.5 text-xs font-semibold text-foreground transition hover:border-amber-400/35"
          >
            <Copy className="h-3.5 w-3.5" />
            Bağlantı Kopyala
          </button>
        </div>

        {/* Quick actions */}
        <div className="flex flex-col gap-1 border-b border-border/60 px-4 py-2">
          <button
            onClick={() => setMuted((v) => !v)}
            className="flex items-center justify-between rounded-lg px-2 py-2.5 text-sm text-foreground hover:bg-muted/30"
          >
            <span className="flex items-center gap-3">
              {muted ? <BellOff className="h-4 w-4 text-muted-foreground" /> : <Bell className="h-4 w-4 text-muted-foreground" />}
              Bildirimler
            </span>
            <span className="text-[11px] text-muted-foreground">{muted ? "Sessiz" : "Açık"}</span>
          </button>

          {!isCreator && (
            <button
              onClick={handleLeave}
              className="flex items-center gap-3 rounded-lg px-2 py-2.5 text-sm text-amber-200 hover:bg-amber-400/10"
            >
              <LogOut className="h-4 w-4" />
              {labelEntity}tan Ayrıl
            </button>
          )}

          {(isCreator || isAdmin) && (
            <button
              onClick={handleDeleteRoom}
              className="flex items-center gap-3 rounded-lg px-2 py-2.5 text-sm text-red-400 hover:bg-red-500/10"
            >
              <Trash2 className="h-4 w-4" />
              {labelEntity}u Sil
            </button>
          )}
        </div>

        {/* Tabs */}
        <div className="flex items-center gap-1 border-b border-border/60 px-3 pt-2 overflow-x-auto">
          {([
            { id: "members" as const, label: "Üyeler", icon: Users },
            ...(!isChannel ? [{ id: "topics" as const, label: "Konular", icon: Hash }] : []),
            ...(isAdmin
              ? [
                  { id: "moderation" as const, label: "Moderasyon", icon: ShieldAlert },
                  { id: "audit" as const, label: "Audit", icon: ScrollText },
                ]
              : []),
          ]).map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setTab(id)}
              className={`flex items-center gap-1.5 rounded-t-lg px-3 py-1.5 text-[11px] font-semibold transition shrink-0 ${
                tab === id
                  ? "border-b-2 border-amber-400 text-amber-200"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              <Icon className="h-3 w-3" />
              {label}
            </button>
          ))}
        </div>

        {tab === "moderation" && isAdmin && (
          <ChatModerationPanel
            roomId={roomId}
            selfUserId={userId}
            members={members}
            onChanged={fetchData}
          />
        )}

        {tab === "audit" && isAdmin && <ChatAuditLogPanel roomId={roomId} />}

        {tab === "topics" && !isChannel && (
          <div className="px-4 py-3 space-y-3">
            {/* Forum mode toggle */}
            <div className="rounded-2xl border border-amber-400/25 bg-gradient-to-br from-amber-500/10 to-black/40 p-3">
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5">
                    <Hash className="h-3.5 w-3.5 text-amber-300" />
                    <h4 className="text-[13px] font-bold text-amber-200">Forum Modu</h4>
                    {room.is_forum && (
                      <span className="rounded-full bg-amber-400/20 px-1.5 py-0.5 text-[9px] font-bold text-amber-200">AKTİF</span>
                    )}
                  </div>
                  <p className="mt-1 text-[10.5px] leading-snug text-muted-foreground">
                    Büyük topluluklar için konu başlıkları (Konut, İş, Hukuk, Kültür) — her konu kendi sohbet odasına sahiptir.
                  </p>
                </div>
                {isAdmin && (
                  <button
                    onClick={handleToggleForum}
                    disabled={forumBusy}
                    className={`shrink-0 rounded-full px-3 py-1.5 text-[10px] font-bold transition ${
                      room.is_forum
                        ? "border border-red-400/40 bg-red-500/10 text-red-300 hover:bg-red-500/20"
                        : "bg-amber-400 text-black hover:bg-amber-300"
                    } disabled:opacity-50`}
                  >
                    {room.is_forum ? "Kapat" : "Aç"}
                  </button>
                )}
              </div>
            </div>

            {/* Topic list */}
            {room.is_forum ? (
              <>
                <div className="space-y-1.5">
                  {topics.length === 0 ? (
                    <p className="py-6 text-center text-[11px] text-muted-foreground">
                      Henüz konu yok. Aşağıdan ekle.
                    </p>
                  ) : (
                    topics.map((t) => (
                      <button
                        key={t.id}
                        onClick={() => {
                          // Navigate to the topic room
                          if (typeof window !== "undefined") {
                            const url = new URL(window.location.href);
                            url.searchParams.delete("join");
                            window.history.replaceState({}, "", url.toString());
                          }
                          // Trigger external navigation via onRoomUpdated then close
                          onRoomUpdated();
                          // Use a custom event so the chat page can pick the room
                          window.dispatchEvent(new CustomEvent("jiyan:open-room", { detail: { roomId: t.id } }));
                          onClose();
                        }}
                        className="flex w-full items-center gap-3 rounded-xl border border-border/40 bg-surface/40 p-2.5 text-left transition hover:border-amber-400/40 hover:bg-amber-400/5"
                      >
                        <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-amber-400/10 text-base">
                          {t.topic_icon || "💬"}
                        </span>
                        <div className="flex-1 min-w-0">
                          <p className="truncate text-[13px] font-semibold text-foreground">
                            #{t.name || "Konu"}
                          </p>
                          <p className="text-[10px] text-muted-foreground">Konu odası</p>
                        </div>
                        <MessageSquare className="h-3.5 w-3.5 text-muted-foreground" />
                      </button>
                    ))
                  )}
                </div>

                {/* Create new topic */}
                {isAdmin && (
                  <div className="rounded-xl border border-amber-400/20 bg-black/30 p-2.5">
                    <p className="mb-2 text-[10px] font-bold uppercase tracking-wide text-amber-300/80">
                      Yeni Konu
                    </p>
                    <div className="flex items-center gap-1.5">
                      <input
                        value={newTopicIcon}
                        onChange={(e) => setNewTopicIcon(e.target.value.slice(0, 2))}
                        maxLength={2}
                        placeholder="💬"
                        className="h-9 w-12 shrink-0 rounded-lg border border-border bg-surface px-2 text-center text-base focus:border-amber-400 focus:outline-none"
                      />
                      <input
                        value={newTopicName}
                        onChange={(e) => setNewTopicName(e.target.value)}
                        placeholder="Konu adı (örn. Konut, İş)"
                        className="h-9 flex-1 rounded-lg border border-border bg-surface px-3 text-xs text-foreground focus:border-amber-400 focus:outline-none"
                      />
                      <button
                        onClick={handleCreateTopic}
                        disabled={forumBusy || !newTopicName.trim()}
                        className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-amber-400 text-black transition hover:bg-amber-300 disabled:opacity-50"
                        aria-label="Konu ekle"
                      >
                        <Plus className="h-4 w-4" strokeWidth={2.6} />
                      </button>
                    </div>
                  </div>
                )}
              </>
            ) : (
              <p className="py-2 text-center text-[11px] text-muted-foreground">
                Forum modu kapalı. Açtığında varsayılan konular (Genel, Konut, İş, Hukuk, Kültür) eklenir.
              </p>
            )}
          </div>
        )}

        {tab === "members" && (
          <div className="px-4 py-3">
            <div className="mb-3 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Users className="h-4 w-4 text-muted-foreground" />
                <span className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                  Üyeler ({members.length})
                </span>
              </div>
              {isAdmin && (
                <button
                  onClick={() => setShowAdd((v) => !v)}
                  className="flex items-center gap-1.5 rounded-full border border-amber-400/40 bg-amber-400/10 px-2.5 py-1 text-[11px] font-semibold text-amber-200 transition hover:bg-amber-400/20"
                >
                  <UserPlus className="h-3 w-3" />
                  Ekle
                </button>
              )}
            </div>

            {/* Add-member search */}
            {showAdd && isAdmin && (
              <div className="mb-3 rounded-xl border border-amber-400/25 bg-black/40 p-2.5">
                <div className="flex items-center gap-2 rounded-lg border border-border bg-surface/60 px-2.5 py-1.5">
                  <Search className="h-3.5 w-3.5 text-muted-foreground" />
                  <input
                    autoFocus
                    value={addQuery}
                    onChange={(e) => setAddQuery(e.target.value)}
                    placeholder="@handle, ad veya +777..."
                    className="flex-1 bg-transparent text-xs text-foreground outline-none placeholder:text-muted-foreground/60"
                  />
                  {addQuery && (
                    <button onClick={() => setAddQuery("")} className="text-muted-foreground hover:text-foreground">
                      <X className="h-3.5 w-3.5" />
                    </button>
                  )}
                </div>
                <div className="mt-2 max-h-56 space-y-0.5 overflow-y-auto">
                  {addResults.length === 0 && addQuery.trim().length >= 2 && (
                    <p className="py-3 text-center text-[11px] text-muted-foreground">Sonuç yok</p>
                  )}
                  {addResults.map((u) => (
                    <div key={u.user_id} className="flex items-center gap-2.5 rounded-lg p-1.5 hover:bg-muted/20">
                      <StarAvatar src={u.avatar_url} name={u.display_name} size={36} premium={!!u.is_premium} online={!!u.is_online} tone="gold" />
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-xs font-semibold text-foreground">
                          {u.display_name}
                          {u.is_premium && <span className="ml-1 text-amber-300">👑</span>}
                        </p>
                        <p className="truncate text-[10px] text-muted-foreground">
                          {resolveHandle({ username: u.username, kurd_id: u.kurd_id, display_name: null })}
                        </p>
                      </div>
                      <button
                        disabled={addBusy}
                        onClick={() => handleAddMember(u)}
                        className="rounded-md border border-amber-400/40 bg-amber-400/10 px-2.5 py-1 text-[10px] font-semibold text-amber-200 hover:bg-amber-400/20 disabled:opacity-50"
                      >
                        Ekle
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Filters */}
            <div className="mb-3 space-y-2 rounded-xl border border-border/50 bg-surface/40 p-2.5">
              <div className="flex items-center gap-2 rounded-lg border border-border bg-surface/60 px-2.5 py-1.5">
                <Filter className="h-3.5 w-3.5 text-amber-300" />
                <input
                  value={memberSearch}
                  onChange={(e) => setMemberSearch(e.target.value)}
                  placeholder="Üye ara (ad, @handle, şehir)..."
                  className="flex-1 bg-transparent text-xs text-foreground outline-none placeholder:text-muted-foreground/60"
                />
              </div>
              <div className="flex flex-wrap gap-1.5">
                {(["all", "admin", "moderator", "member"] as RoleFilter[]).map((r) => (
                  <button
                    key={r}
                    onClick={() => setRoleFilter(r)}
                    className={`rounded-full border px-2.5 py-1 text-[10px] font-semibold transition ${
                      roleFilter === r
                        ? "border-amber-400/60 bg-amber-400/15 text-amber-200"
                        : "border-border bg-surface/60 text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {r === "all" ? "Tümü" : r === "admin" ? "Yönetici" : r === "moderator" ? "Moderatör" : "Üye"}
                  </button>
                ))}
                {(["all", "online", "offline"] as OnlineFilter[]).map((o) => (
                  <button
                    key={o}
                    onClick={() => setOnlineFilter(o)}
                    className={`rounded-full border px-2.5 py-1 text-[10px] font-semibold transition ${
                      onlineFilter === o
                        ? "border-emerald-400/60 bg-emerald-400/15 text-emerald-300"
                        : "border-border bg-surface/60 text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {o === "all" ? "Hepsi" : o === "online" ? "🟢 Online" : "Offline"}
                  </button>
                ))}
                {(() => {
                  const cities = Array.from(new Set(members.map((m) => m.city).filter((c): c is string => !!c))).sort();
                  if (cities.length === 0) return null;
                  return (
                    <select
                      value={cityFilter}
                      onChange={(e) => setCityFilter(e.target.value)}
                      className="rounded-full border border-border bg-surface/60 px-2.5 py-1 text-[10px] font-semibold text-foreground focus:outline-none"
                    >
                      <option value="all">📍 Tüm şehirler</option>
                      {cities.map((c) => (
                        <option key={c} value={c}>{c}</option>
                      ))}
                    </select>
                  );
                })()}
              </div>
            </div>

            <div className="space-y-1">
              {loading ? (
                <p className="py-4 text-center text-xs text-muted-foreground">Yükleniyor...</p>
              ) : (
                (() => {
                  const q = memberSearch.trim().toLowerCase();
                  const filtered = members
                    .filter((m) => roleFilter === "all" || m.role === roleFilter)
                    .filter((m) =>
                      onlineFilter === "all"
                        ? true
                        : onlineFilter === "online"
                          ? m.is_online
                          : !m.is_online
                    )
                    .filter((m) => cityFilter === "all" || m.city === cityFilter)
                    .filter((m) => {
                      if (!q) return true;
                      return (
                        m.display_name.toLowerCase().includes(q) ||
                        (m.username || "").toLowerCase().includes(q) ||
                        (m.kurd_id || "").toLowerCase().includes(q) ||
                        (m.city || "").toLowerCase().includes(q)
                      );
                    })
                    .sort((a, b) => {
                      const order = { admin: 0, moderator: 1, member: 2 };
                      return (order[a.role as keyof typeof order] ?? 2) - (order[b.role as keyof typeof order] ?? 2);
                    });

                  if (filtered.length === 0) {
                    return (
                      <p className="py-6 text-center text-[11px] text-muted-foreground">
                        Filtreyle eşleşen üye yok.
                      </p>
                    );
                  }

                  return filtered.map((member) => {
                    const handleStr = resolveHandle({ username: member.username, kurd_id: member.kurd_id, display_name: null });
                    const isSelf = member.user_id === userId;
                    return (
                      <div key={member.id} className="flex items-center gap-3 rounded-xl p-2.5 transition-colors hover:bg-accent/40">
                        <Link to="/sovereign-profile" search={{ u: member.user_id }} className="shrink-0" aria-label={`${member.display_name} profil`}>
                          <StarAvatar
                            src={member.avatar_url}
                            name={member.display_name}
                            size={42}
                            premium={member.is_premium}
                            online={member.is_online}
                            tone={member.role === "admin" ? "amber" : "gold"}
                          />
                        </Link>
                        <Link to="/sovereign-profile" search={{ u: member.user_id }} className="min-w-0 flex-1">
                          <div className="flex items-center gap-1.5">
                            <span className="truncate text-sm font-medium text-foreground">{member.display_name}</span>
                            {member.is_premium && <span className="text-xs text-amber-300">👑</span>}
                            {getRoleIcon(member.role)}
                            {member.is_muted && (
                              <MicOff className="h-3 w-3 text-orange-300" />
                            )}
                            {isSelf && (
                              <span className="rounded-full border border-amber-400/30 bg-amber-400/10 px-1.5 py-0 text-[9px] text-amber-200">Sen</span>
                            )}
                          </div>
                          <p className="text-[10px] text-muted-foreground">
                            {handleStr} · {getRoleLabel(member.role)}
                            {member.city ? ` · ${member.city}` : ""}
                          </p>
                        </Link>
                        {isAdmin && !isSelf && (
                          <div className="flex items-center gap-1">
                            <select
                              value={member.role}
                              onChange={(e) => handleRoleChange(member.user_id, e.target.value)}
                              className="appearance-none rounded-lg border border-border bg-surface px-2 py-1 text-[10px] text-foreground focus:outline-none"
                            >
                              <option value="member">Üye</option>
                              <option value="moderator">Mod</option>
                              <option value="admin">Yönetici</option>
                            </select>
                            <button
                              onClick={() => handleRemoveMember(member.user_id, member.display_name)}
                              className="flex h-7 w-7 items-center justify-center rounded-lg text-destructive hover:bg-destructive/10"
                              aria-label="Üyeyi çıkar"
                            >
                              <UserMinus className="h-3.5 w-3.5" />
                            </button>
                          </div>
                        )}
                      </div>
                    );
                  });
                })()
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { FileText, MapPin, Download } from "lucide-react";
import { VoicePlayer } from "./VoicePlayer";

interface MediaMessageBubbleProps {
  messageType: string;
  mediaUrl: string | null;
  fileName: string | null;
  fileSize: number | null;
  content: string;
  isMe: boolean;
  /** Pre-computed amplitude waveform (length VOICE_PEAK_BUCKETS) for audio messages. */
  voicePeaks?: number[] | null;
  /** Recorded duration in milliseconds (for audio messages). */
  voiceDurationMs?: number | null;
}

function formatSize(bytes: number) {
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
  return (bytes / (1024 * 1024)).toFixed(1) + " MB";
}

export function MediaMessageBubble({
  messageType,
  mediaUrl,
  fileName,
  fileSize,
  content,
  isMe,
  voicePeaks,
  voiceDurationMs,
}: MediaMessageBubbleProps) {
  if (!mediaUrl) return <p className="text-sm leading-relaxed">{content}</p>;

  switch (messageType) {
    case "image":
      return (
        <div className="space-y-1">
          <img
            src={mediaUrl}
            alt={fileName || "image"}
            className="rounded-xl max-w-full max-h-48 object-cover cursor-pointer"
            onClick={() => window.open(mediaUrl, "_blank")}
            loading="lazy"
          />
          {content && content !== fileName && <p className="text-sm leading-relaxed">{content}</p>}
        </div>
      );

    case "video":
      return (
        <div className="space-y-1">
          <video
            src={mediaUrl}
            controls
            className="rounded-xl max-w-full max-h-48"
            preload="metadata"
          />
          {content && content !== fileName && <p className="text-sm leading-relaxed">{content}</p>}
        </div>
      );

    case "audio":
      return (
        <VoicePlayer
          src={mediaUrl}
          isMe={isMe}
          peaks={voicePeaks ?? null}
          durationMs={voiceDurationMs ?? null}
        />
      );

    case "file":
      return (
        <a
          href={mediaUrl}
          target="_blank"
          rel="noopener noreferrer"
          className={`flex items-center gap-2.5 rounded-xl p-2 ${
            isMe ? "bg-white/10 hover:bg-white/15" : "bg-accent hover:bg-accent/80"
          } transition-colors`}
        >
          <div className={`flex h-10 w-10 items-center justify-center rounded-lg ${
            isMe ? "bg-white/20" : "bg-neon/10"
          }`}>
            <FileText className={`h-5 w-5 ${isMe ? "text-white" : "text-neon"}`} />
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium truncate">{fileName || "Dosya"}</p>
            {fileSize ? <p className={`text-[9px] ${isMe ? "text-white/50" : "text-muted-foreground"}`}>{formatSize(fileSize)}</p> : null}
          </div>
          <Download className={`h-4 w-4 shrink-0 ${isMe ? "text-white/60" : "text-muted-foreground"}`} />
        </a>
      );

    case "location":
      return (
        <a
          href={mediaUrl}
          target="_blank"
          rel="noopener noreferrer"
          className={`flex items-center gap-2 rounded-xl p-2 ${
            isMe ? "bg-white/10 hover:bg-white/15" : "bg-accent hover:bg-accent/80"
