import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { fireReactionBurst } from "@/components/chat/ReactionBurst";

const EMOJI_OPTIONS = ["👍", "❤️", "😂", "😮", "😢", "🔥"];

interface Reaction {
  emoji: string;
  count: number;
  hasReacted: boolean;
}

interface MessageReactionsProps {
  messageId: string;
  userId: string;
}

export function MessageReactions({ messageId, userId }: MessageReactionsProps) {
  const [reactions, setReactions] = useState<Reaction[]>([]);
  const [showPicker, setShowPicker] = useState(false);

  useEffect(() => {
    fetchReactions();
  }, [messageId]);

  const fetchReactions = async () => {
    const { data } = await supabase
      .from("channel_reactions")
      .select("emoji, user_id")
      .eq("message_id", messageId);

    if (!data) return;

    const emojiMap = new Map<string, { count: number; hasReacted: boolean }>();
    data.forEach((r) => {
      const existing = emojiMap.get(r.emoji) || { count: 0, hasReacted: false };
      existing.count++;
      if (r.user_id === userId) existing.hasReacted = true;
      emojiMap.set(r.emoji, existing);
    });

    setReactions(
      Array.from(emojiMap.entries()).map(([emoji, data]) => ({ emoji, ...data }))
    );
  };

  const toggleReaction = async (emoji: string, evt?: React.MouseEvent) => {
    const existing = reactions.find((r) => r.emoji === emoji && r.hasReacted);
    if (existing) {
      await supabase
        .from("channel_reactions")
        .delete()
        .eq("message_id", messageId)
        .eq("user_id", userId)
        .eq("emoji", emoji);
    } else {
      await supabase.from("channel_reactions").insert({
        message_id: messageId,
        user_id: userId,
        emoji,
      });
      // 3D burst at click position
      const target = evt?.currentTarget as HTMLElement | undefined;
      if (target) {
        const r = target.getBoundingClientRect();
        fireReactionBurst(r.left + r.width / 2, r.top + r.height / 2, emoji);
      }
    }
    fetchReactions();
    setShowPicker(false);
  };

  return (
    <div className="flex flex-wrap items-center gap-1 mt-1">
      {reactions.map((r) => (
        <button
          key={r.emoji}
          onClick={(e) => toggleReaction(r.emoji, e)}
          className={`deng3d-tapback ${r.hasReacted ? "ring-2 ring-amber-400/50" : ""}`}
          title={r.hasReacted ? "Tepkini kaldır" : "Tepki ver"}
        >
          <span className="deng3d-tapback-emoji">{r.emoji}</span>
          <span
            className="text-[10px] font-bold"
            style={{
              color: r.hasReacted ? "#FFE9A8" : "rgba(245,240,220,0.7)",
            }}
          >
            {r.count}
          </span>
        </button>
      ))}
      <div className="relative">
        <button
          onClick={() => setShowPicker(!showPicker)}
          className="flex h-5 w-5 items-center justify-center rounded-full text-[11px] font-bold transition-all active:scale-90"
          style={{
            background: "linear-gradient(135deg, rgba(212,175,55,0.25), rgba(8,6,2,0.6))",
            border: "1px solid rgba(212,175,55,0.4)",
            color: "#FFE9A8",
            boxShadow: "inset 0 1px 0 rgba(255,233,168,0.3), 0 1px 3px rgba(0,0,0,0.4)",
          }}
          aria-label="Tepki ekle"
        >
          +
        </button>
        {showPicker && (
          <div
            className="absolute bottom-7 left-0 z-50 flex gap-1 rounded-2xl p-2 animate-fade-in"
            style={{
              background:
                "radial-gradient(80% 100% at 50% 0%, rgba(40,28,8,0.97) 0%, rgba(8,6,2,0.97) 100%)",
              border: "1px solid rgba(212,175,55,0.4)",
              boxShadow:
                "0 8px 24px rgba(0,0,0,0.6), 0 0 18px rgba(212,175,55,0.25), inset 0 1px 0 rgba(255,233,168,0.2)",
            }}
          >
            {EMOJI_OPTIONS.map((emoji, i) => (
              <button
                key={emoji}
                onClick={(e) => toggleReaction(emoji, e)}
                className="deng3d-orb"
                style={{
                  width: 38,
                  height: 38,
                  fontSize: 20,
                  animationDelay: `${i * 40}ms`,
                }}
                aria-label={`React with ${emoji}`}
              >
                {emoji}
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

