/**
 * ReactionBurst — One-shot 3D-feel particle burst when a reaction is added.
 * Renders absolutely over the trigger; auto-removes after 900ms.
 */
import { useEffect, useState } from "react";

interface Burst {
  id: number;
  x: number;
  y: number;
  emoji: string;
}

let _seq = 0;
const listeners = new Set<(b: Burst) => void>();

export function fireReactionBurst(x: number, y: number, emoji: string) {
  const b: Burst = { id: ++_seq, x, y, emoji };
  listeners.forEach((cb) => cb(b));
}

export function ReactionBurstLayer() {
  const [bursts, setBursts] = useState<Burst[]>([]);

  useEffect(() => {
    const cb = (b: Burst) => {
      setBursts((prev) => [...prev, b]);
      setTimeout(() => setBursts((prev) => prev.filter((x) => x.id !== b.id)), 950);
    };
    listeners.add(cb);
    return () => { listeners.delete(cb); };
  }, []);

  return (
    <div className="pointer-events-none fixed inset-0 z-[60]" aria-hidden>
      {bursts.map((b) => (
        <div
          key={b.id}
          className="absolute"
          style={{ left: b.x, top: b.y, transform: "translate(-50%,-50%)" }}
        >
          <span
            className="absolute text-3xl"
            style={{
              animation: "rx-pop 700ms cubic-bezier(.2,.9,.4,1) forwards",
              filter: "drop-shadow(0 0 12px rgba(212,175,55,0.9))",
            }}
          >
            {b.emoji}
          </span>
          {Array.from({ length: 12 }).map((_, i) => {
            const a = (i / 12) * Math.PI * 2;
            const dx = Math.cos(a) * 80;
            const dy = Math.sin(a) * 80;
            return (
              <span
                key={i}
                className="absolute h-1.5 w-1.5 rounded-full"
                style={{
                  background: "radial-gradient(circle,#FFE9A8,#D4AF37)",
                  boxShadow: "0 0 8px rgba(212,175,55,0.9)",
                  ["--dx" as any]: `${dx}px`,
                  ["--dy" as any]: `${dy}px`,
                  animation: "rx-spark 850ms ease-out forwards",
                }}
              />
            );
          })}
          <span
            className="absolute h-24 w-24 -translate-x-1/2 -translate-y-1/2 rounded-full"
            style={{
              left: 0,
              top: 0,
              background:
                "radial-gradient(circle, rgba(212,175,55,0.4) 0%, transparent 70%)",
              animation: "rx-glow 700ms ease-out forwards",
            }}
          />
        </div>
      ))}
    </div>
  );
}

