/**
 * SovereignChatVoid — Three.js deep-space ambient layer behind the chat.
 *
 * Pitch black void + drifting sovereign-gold particles + subtle parallax
 * driven by scroll position. Pointer-events: none so DOM messages stay
 * interactive on top. Mounted once per chat view.
 */
import { Canvas, useFrame } from "@react-three/fiber";
import { useMemo, useRef } from "react";
import * as THREE from "three";

function GoldParticles({ scrollRef }: { scrollRef: React.MutableRefObject<number> }) {
  const ref = useRef<THREE.Points>(null);
  const COUNT = 220;

  const { positions, sizes } = useMemo(() => {
    const positions = new Float32Array(COUNT * 3);
    const sizes = new Float32Array(COUNT);
    for (let i = 0; i < COUNT; i++) {
      positions[i * 3] = (Math.random() - 0.5) * 16;
      positions[i * 3 + 1] = (Math.random() - 0.5) * 18;
      positions[i * 3 + 2] = -Math.random() * 12 - 1;
      sizes[i] = Math.random() * 0.06 + 0.02;
    }
    return { positions, sizes };
  }, []);

  useFrame((_, dt) => {
    if (!ref.current) return;
    const arr = ref.current.geometry.attributes.position.array as Float32Array;
    const scrollOffset = scrollRef.current * 0.0006;
    for (let i = 0; i < COUNT; i++) {
      arr[i * 3 + 1] += dt * 0.06 * (1 + (i % 5) * 0.04);
      if (arr[i * 3 + 1] > 9) arr[i * 3 + 1] = -9;
    }
    ref.current.geometry.attributes.position.needsUpdate = true;
    ref.current.position.y = -scrollOffset;
    ref.current.rotation.z += dt * 0.005;
  });

  return (
    <points ref={ref}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-size" args={[sizes, 1]} />
      </bufferGeometry>
      <pointsMaterial
        color={new THREE.Color("#D4AF37")}
        size={0.07}
        sizeAttenuation
        transparent
        opacity={0.85}
        depthWrite={false}
        blending={THREE.AdditiveBlending}
      />
    </points>
  );
}

function GoldFog() {
  const ref = useRef<THREE.Mesh>(null);
  useFrame((s) => {
    if (!ref.current) return;
    const t = s.clock.elapsedTime;
    ref.current.rotation.z = Math.sin(t * 0.05) * 0.1;
    (ref.current.material as THREE.MeshBasicMaterial).opacity =
      0.07 + Math.sin(t * 0.4) * 0.025;
  });
  return (
    <mesh ref={ref} position={[0, 0, -8]}>
      <planeGeometry args={[28, 22]} />
      <meshBasicMaterial
        color={new THREE.Color("#7a5a14")}
        transparent
        opacity={0.08}
        depthWrite={false}
      />
    </mesh>
  );
}

interface Props {
  scrollRef: React.MutableRefObject<number>;
}

export function SovereignChatVoid({ scrollRef }: Props) {
  return (
    <div
      className="absolute inset-0 -z-10 overflow-hidden bg-black"
      style={{ pointerEvents: "none" }}
      aria-hidden
    >
      <Canvas
        dpr={[1, 1.5]}
        gl={{ antialias: false, alpha: false, powerPreference: "low-power" }}
        camera={{ position: [0, 0, 6], fov: 60 }}
      >
        <color attach="background" args={["#000000"]} />
        <GoldFog />
        <GoldParticles scrollRef={scrollRef} />
      </Canvas>
    </div>
  );
}

