  disabled?: boolean;
}

const THRESHOLD = 64;

export function SwipeToReply({ children, isMe, onReply, disabled }: SwipeToReplyProps) {
  const [offsetX, setOffsetX] = useState(0);
  const startXRef = useRef(0);
  const startYRef = useRef(0);
  const swipingRef = useRef(false);
  const triggeredRef = useRef(false);
  const lockedRef = useRef<"horizontal" | "vertical" | null>(null);

  if (disabled) return <>{children}</>;

  const direction = isMe ? -1 : 1; // swipe left for own, right for others

  const handleTouchStart = (e: React.TouchEvent) => {
    startXRef.current = e.touches[0].clientX;
    startYRef.current = e.touches[0].clientY;
    swipingRef.current = false;
    triggeredRef.current = false;
    lockedRef.current = null;
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    const dx = e.touches[0].clientX - startXRef.current;
    const dy = e.touches[0].clientY - startYRef.current;

    // Lock direction after 8px movement
    if (!lockedRef.current && (Math.abs(dx) > 8 || Math.abs(dy) > 8)) {
      lockedRef.current = Math.abs(dx) > Math.abs(dy) ? "horizontal" : "vertical";
    }

    if (lockedRef.current === "vertical") return;

    const move = dx * direction;
    if (move <= 0) {
      setOffsetX(0);
      return;
    }

    swipingRef.current = true;
    const clamped = Math.min(move, THRESHOLD + 20);
    setOffsetX(clamped * direction);

    if (clamped >= THRESHOLD && !triggeredRef.current) {
      triggeredRef.current = true;
      // Haptic feedback
      if (navigator.vibrate) navigator.vibrate(15);
    }
  };

  const handleTouchEnd = () => {
    if (triggeredRef.current) {
      onReply();
    }
    setOffsetX(0);
    swipingRef.current = false;
    lockedRef.current = null;
  };

  const progress = Math.min(Math.abs(offsetX) / THRESHOLD, 1);

  return (
    <div className="relative overflow-visible">
      {/* Reply icon indicator */}
      <div
        className={`absolute top-1/2 -translate-y-1/2 flex items-center justify-center h-8 w-8 rounded-full transition-all duration-150 ${
          progress >= 1
            ? "bg-neon text-neon-foreground scale-110"
            : "bg-muted/60 text-muted-foreground"
        }`}
        style={{
          opacity: Math.max(progress * 1.5, 0),
          [isMe ? "right" : "left"]: -36,
          transform: `translateY(-50%) scale(${0.5 + progress * 0.5})`,
        }}
      >
        <Reply className="h-4 w-4" style={{ transform: isMe ? "scaleX(-1)" : undefined }} />
      </div>

      {/* Swipeable content */}
      <div
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        style={{
          transform: `translateX(${offsetX}px)`,
          transition: swipingRef.current ? "none" : "transform 0.25s cubic-bezier(0.2, 0, 0, 1)",
        }}
      >
        {children}
      </div>
    </div>
  );
}

