/**
 * TouchGoldLight — Soft sovereign-gold halo that follows the user's finger
 * or cursor across the chat surface. Pure DOM (radial-gradient mask) for
 * 60fps on mobile. Pointer-events disabled so it never blocks messages.
 */
import { useEffect, useRef } from "react";

export function TouchGoldLight({ targetRef }: { targetRef: React.RefObject<HTMLElement | null> }) {
  const dotRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = targetRef.current;
    const dot = dotRef.current;
    if (!el || !dot) return;

    let raf = 0;
    let tx = 0, ty = 0, x = 0, y = 0;
    let visible = false;

    const move = (cx: number, cy: number) => {
      const rect = el.getBoundingClientRect();
      tx = cx - rect.left;
      ty = cy - rect.top;
      if (!visible) {
        visible = true;
        dot.style.opacity = "0.85";
      }
      if (!raf) raf = requestAnimationFrame(tick);
    };

    const tick = () => {
      x += (tx - x) * 0.18;
      y += (ty - y) * 0.18;
      dot.style.transform = `translate3d(${x - 90}px, ${y - 90}px, 0)`;
      if (Math.abs(tx - x) > 0.3 || Math.abs(ty - y) > 0.3) {
        raf = requestAnimationFrame(tick);
      } else {
        raf = 0;
      }
    };

    const onPointer = (e: PointerEvent) => move(e.clientX, e.clientY);
    const onLeave = () => {
      visible = false;
      dot.style.opacity = "0";
    };

    el.addEventListener("pointermove", onPointer, { passive: true });
    el.addEventListener("pointerdown", onPointer, { passive: true });
    el.addEventListener("pointerleave", onLeave);
    return () => {
      el.removeEventListener("pointermove", onPointer);
      el.removeEventListener("pointerdown", onPointer);
      el.removeEventListener("pointerleave", onLeave);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [targetRef]);

  return (
    <div
      ref={dotRef}
      aria-hidden
      className="pointer-events-none absolute top-0 left-0 z-[1] mix-blend-screen transition-opacity duration-300"
      style={{
        width: 180,
        height: 180,
        opacity: 0,
        background:
          "radial-gradient(circle, rgba(212,175,55,0.55) 0%, rgba(212,175,55,0.18) 35%, transparent 70%)",
        filter: "blur(8px)",
      }}
    />
  );
}

