import { useState } from "react";
import { Languages } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

const langOptions = [
  { value: "TR", label: "Türkçe" },
  { value: "KU", label: "Kurdî" },
  { value: "AR", label: "العربية" },
  { value: "EN", label: "English" },
  { value: "DE", label: "Deutsch" },
  { value: "FR", label: "Français" },
  { value: "NL", label: "Nederlands" },
  { value: "SE", label: "Svenska" },
];

interface Props {
  text: string;
  onTranslated?: (translated: string, lang: string) => void;
}

export function TranslateButton({ text, onTranslated }: Props) {
  const [loading, setLoading] = useState(false);
  const [translated, setTranslated] = useState<string | null>(null);
  const [showPicker, setShowPicker] = useState(false);

  const translate = async (targetLang: string) => {
    setShowPicker(false);
    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke("translate-message", {
        body: { text, targetLang },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      setTranslated(data.translated);
      onTranslated?.(data.translated, targetLang);
    } catch (e: any) {
      toast.error(e?.message || "Çeviri başarısız");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="relative inline-block">
      <button
        onClick={() => {
          if (translated) {
            setTranslated(null);
          } else {
            setShowPicker(!showPicker);
          }
        }}
        disabled={loading}
        className="flex items-center gap-1 text-[10px] text-muted-foreground hover:text-neon transition-colors disabled:opacity-50"
        title={translated ? "Orijinali göster" : "Çevir"}
      >
        <Languages className="h-3 w-3" />
        {loading ? "..." : translated ? "Orijinal" : "Çevir"}
      </button>

      {showPicker && (
        <div className="absolute bottom-6 left-0 z-50 bg-background border border-border rounded-lg shadow-lg p-1 min-w-[120px]">
          {langOptions.map((l) => (
            <button
              key={l.value}
              onClick={() => translate(l.value)}
              className="block w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-accent rounded transition-colors"
            >
              {l.label}
            </button>
          ))}
        </div>
      )}

      {translated && (
        <p className="text-xs text-neon/80 mt-1 italic">{translated}</p>
      )}
    </div>
  );
}

