import { useState, useRef, useEffect, useMemo } from "react";
import { Play, Pause, Languages, FileText, Lock } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { VOICE_PEAK_BUCKETS } from "@/lib/voice-peaks";

interface VoicePlayerProps {
  src: string;
  isMe: boolean;
  /** Persisted waveform peaks (length VOICE_PEAK_BUCKETS) — used for the 3D bars. */
  peaks?: number[] | null;
  /** Recorded duration in ms — preferred over the audio element's metadata. */
  durationMs?: number | null;
}

const langOptions = [
  { value: "TR", label: "Türkçe" },
  { value: "KU", label: "Kurdî" },
  { value: "AR", label: "العربية" },
  { value: "EN", label: "English" },
  { value: "DE", label: "Deutsch" },
  { value: "FR", label: "Français" },
  { value: "NL", label: "Nederlands" },
  { value: "SE", label: "Svenska" },
];

/**
 * VoicePlayer — renders a Deng voice message with a 3D waveform bar strip.
 *
 * The bars use the persisted `peaks` array (extracted at record time), so the
 * shape never changes between renders — receivers see the exact same shape the
 * sender saw. While playing, each bar pulses with a depth-aware gradient and
 * the played portion glows in 24K gold.
 */
export function VoicePlayer({ src, isMe, peaks, durationMs }: VoicePlayerProps) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [playing, setPlaying] = useState(false);
  const [progress, setProgress] = useState(0); // 0..1
  const [audioDuration, setAudioDuration] = useState(0);
  const [speed, setSpeed] = useState(1);
  const [now, setNow] = useState(0);
  const animRef = useRef<number | null>(null);

  // Transcription state
  const [transcript, setTranscript] = useState<string | null>(null);
  const [translation, setTranslation] = useState<string | null>(null);
  const [transcribing, setTranscribing] = useState(false);
  const [showLangPicker, setShowLangPicker] = useState(false);

  // Stable bar set: prefer persisted peaks, fall back to a deterministic shape
  // derived from the URL so the same message always renders identically.
  const bars = useMemo<number[]>(() => {
    if (peaks && peaks.length > 0) return peaks;
    const seed = hashString(src);
    return Array.from({ length: VOICE_PEAK_BUCKETS }, (_, i) => {
      const t = i / VOICE_PEAK_BUCKETS;
      const wobble = Math.abs(Math.sin((seed % 100) * 0.1 + t * Math.PI * 6));
      return 0.2 + wobble * 0.7;
    });
  }, [peaks, src]);

  const totalSeconds = (durationMs ?? audioDuration * 1000) / 1000;

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    const onLoaded = () => setAudioDuration(audio.duration || 0);
    const onEnded = () => {
      setPlaying(false);
      setProgress(0);
      if (animRef.current) cancelAnimationFrame(animRef.current);
    };
    audio.addEventListener("loadedmetadata", onLoaded);
    audio.addEventListener("ended", onEnded);
    return () => {
      audio.removeEventListener("loadedmetadata", onLoaded);
      audio.removeEventListener("ended", onEnded);
    };
  }, []);

  useEffect(() => {
    if (audioRef.current) audioRef.current.playbackRate = speed;
  }, [speed]);

  useEffect(() => {
    return () => {
      if (animRef.current) cancelAnimationFrame(animRef.current);
    };
  }, []);

  const togglePlay = async () => {
    const audio = audioRef.current;
    if (!audio) return;
    if (playing) {
      audio.pause();
      setPlaying(false);
      if (animRef.current) cancelAnimationFrame(animRef.current);
      return;
    }
    try {
      await audio.play();
    } catch (err) {
      toast.error("Oynatılamadı");
      return;
    }
    setPlaying(true);
    const tick = () => {
      if (audio.duration) setProgress(audio.currentTime / audio.duration);
      setNow(performance.now());
      animRef.current = requestAnimationFrame(tick);
    };
    tick();
  };

  const handleSeek = (e: React.MouseEvent<HTMLDivElement>) => {
    const audio = audioRef.current;
    if (!audio || !audio.duration) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const pct = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    audio.currentTime = audio.duration * pct;
    setProgress(pct);
  };

  const transcribe = async (translateTo?: string) => {
    setShowLangPicker(false);
    setTranscribing(true);
    try {
      const { data, error } = await supabase.functions.invoke("transcribe-audio", {
        body: { audioUrl: src, translateTo },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      setTranscript(data.transcript);
      if (data.translation) setTranslation(data.translation);
    } catch (e) {
      const msg = e instanceof Error ? e.message : "Transkripsiyon başarısız";
      toast.error(msg);
    } finally {
      setTranscribing(false);
    }
  };

  const formatTime = (s: number) => {
    if (!s || !isFinite(s)) return "0:00";
    return `${Math.floor(s / 60)}:${Math.floor(s % 60).toString().padStart(2, "0")}`;
  };

  const displayedSeconds = playing ? (audioRef.current?.currentTime || 0) : totalSeconds;

  return (
    <div className="space-y-1">
      <div className="flex items-center gap-2 min-w-[200px]">
        <audio ref={audioRef} src={src} preload="metadata" />
        <button
          onClick={togglePlay}
          className={`relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full transition-transform active:scale-95 ${
            isMe
              ? "bg-black/20 text-[#1a1003] shadow-[0_2px_8px_rgba(140,106,27,0.4)]"
              : "bg-neon/20 text-neon shadow-[0_2px_8px_rgba(57,255,20,0.25)]"
          }`}
          aria-label={playing ? "Duraklat" : "Oynat"}
        >
          {playing ? (
            <Pause className="h-4 w-4" />
          ) : (
            <Play className="h-4 w-4 ml-0.5" />
          )}
          {playing && (
            <span
              className={`absolute inset-0 rounded-full animate-ping ${
                isMe ? "bg-[#1a1003]/20" : "bg-neon/30"
              }`}
            />
          )}
        </button>

        <div className="flex-1 flex flex-col gap-1">
          {/* 3D waveform bars — clickable to seek */}
          <div
            role="slider"
            aria-label="Sesli mesaj ilerlemesi"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(progress * 100)}
            tabIndex={0}
            onClick={handleSeek}
            className="relative flex h-7 items-center gap-[2px] cursor-pointer select-none"
          >
            {bars.map((peak, i) => {
              const barProgress = (i + 0.5) / bars.length;
              const isPlayed = barProgress <= progress;
              // Live pulse only on the currently-playing bar
              const distance = Math.abs(barProgress - progress);
              const pulse = playing && distance < 1 / bars.length
                ? 1 + Math.abs(Math.sin(now / 80)) * 0.35
                : 1;
              const baseHeight = 4 + peak * 22; // px
              const height = Math.min(28, baseHeight * pulse);
              return (
                <span
                  key={i}
                  aria-hidden
                  className="block w-[3px] rounded-full transition-[transform,box-shadow] duration-75"
                  style={{
                    height: `${height}px`,
                    background: isPlayed
                      ? "linear-gradient(180deg, #FFE9A8 0%, #D4AF37 50%, #8C6A1B 100%)"
                      : isMe
                        ? "linear-gradient(180deg, rgba(26,16,3,0.55) 0%, rgba(26,16,3,0.3) 100%)"
                        : "linear-gradient(180deg, rgba(212,175,55,0.55) 0%, rgba(140,106,27,0.25) 100%)",
                    boxShadow: isPlayed
                      ? "0 0 6px rgba(255,233,168,0.55), inset 0 1px 0 rgba(255,247,214,0.6)"
                      : "inset 0 1px 0 rgba(255,255,255,0.08)",
                    transform: `scaleY(${pulse > 1 ? pulse : 1})`,
                    transformOrigin: "center",
                  }}
                />
              );
            })}
          </div>

          <div className="flex items-center justify-between">
            <span className={`text-[10px] font-mono ${isMe ? "text-[#1a1003]/70" : "text-muted-foreground"}`}>
              {formatTime(displayedSeconds)}
            </span>
            <div className="flex items-center gap-1.5">
              {/* Mock E2EE badge */}
              <span
                className={`flex items-center gap-0.5 text-[9px] font-medium ${
                  isMe ? "text-[#1a1003]/60" : "text-muted-foreground"
                }`}
                title="Uçtan uca şifreli"
              >
                <Lock className="h-2.5 w-2.5" />
                E2EE
              </span>
              <button
                onClick={() => setSpeed(speed === 1 ? 1.5 : speed === 1.5 ? 2 : 1)}
                className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${
                  isMe ? "text-[#1a1003] bg-[#1a1003]/10" : "text-neon bg-neon/10"
                }`}
              >
                {speed}x
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Transcription controls (received messages only) */}
      {!isMe && (
        <div className="relative flex items-center gap-2">
          <button
            onClick={() => transcribe()}
            disabled={transcribing}
            className="flex items-center gap-1 text-[10px] text-muted-foreground hover:text-neon transition-colors disabled:opacity-50"
            title="Metne çevir"
          >
            <FileText className="h-3 w-3" />
            {transcribing ? "..." : transcript ? "Yenile" : "Metne çevir"}
          </button>

          <div className="relative">
            <button
              onClick={() => setShowLangPicker(!showLangPicker)}
              disabled={transcribing}
              className="flex items-center gap-1 text-[10px] text-muted-foreground hover:text-neon transition-colors disabled:opacity-50"
              title="Çevir"
            >
              <Languages className="h-3 w-3" />
              Çevir
            </button>
            {showLangPicker && (
              <div className="absolute bottom-6 left-0 z-50 bg-background border border-border rounded-lg shadow-lg p-1 min-w-[120px]">
                {langOptions.map((l) => (
                  <button
                    key={l.value}
                    onClick={() => transcribe(l.value)}
                    className="block w-full text-left px-3 py-1.5 text-xs text-foreground hover:bg-accent rounded transition-colors"
                  >
                    {l.label}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {transcript && (
        <div className={`text-xs mt-1 p-1.5 rounded-lg ${isMe ? "bg-black/10" : "bg-accent"}`}>
          <p className={isMe ? "text-[#1a1003]" : "text-foreground"}>{transcript}</p>
          {translation && (
            <p className={`mt-1 italic border-t pt-1 ${isMe ? "border-black/10 text-[#1a1003]/80" : "border-border/50 text-neon/80"}`}>
              {translation}
            </p>
          )}
        </div>
      )}
    </div>
  );
}

/** Tiny deterministic hash so the fallback shape is stable per URL. */
function hashString(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = (h * 31 + s.charCodeAt(i)) | 0;
  }
  return Math.abs(h);
}

