/**
 * VoiceRecorder — Deng iMessage-style voice capture.
 *
 * Three states:
 *   1. IDLE   — gold mic squircle. Tap to begin recording.
 *   2. REC    — live amplitude meter + timer + cancel chip.
 *                 Tap stop to enter PREVIEW.
 *   3. PREVIEW — playable 3D waveform of the just-recorded clip with
 *                Cancel (✕) and Send (➤) buttons.
 *
 * STREAMING UPLOAD:
 *   When the user presses Send we (a) start the storage upload, then
 *   (b) immediately write the chat_messages row using the eventual
 *   public URL. Supabase Storage serves byte-range (HTTP 206) responses
 *   on objects in flight, so the receiver's <audio> element can begin
 *   playback while the bytes are still uploading. We retry-poll the
 *   public URL once before sending so the row never points at a 404.
 */
import { useState, useRef, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Mic, Send, X, Loader2, Play, Pause, Trash2 } from "lucide-react";
import { toast } from "sonner";
import { extractVoicePeaks, VOICE_PEAK_BUCKETS } from "@/lib/voice-peaks";

interface VoiceRecorderProps {
  userId: string;
  roomId: string;
  /**
   * Fires once the message metadata is ready to be sent. The recorder triggers
   * this BEFORE the upload has finished — the URL points at an object that is
   * still being written, but Supabase Storage serves Range requests on it.
   */
  onVoiceSent: (
    mediaUrl: string,
    duration: number,
    fileName: string,
    fileSize: number,
    peaks: number[],
    durationMs: number,
  ) => void;
}

type Phase = "idle" | "recording" | "preview" | "uploading";

const formatDuration = (s: number) =>
  `${Math.floor(s / 60)}:${(s % 60).toString().padStart(2, "0")}`;

export function VoiceRecorder({ userId, roomId, onVoiceSent }: VoiceRecorderProps) {
  const [phase, setPhase] = useState<Phase>("idle");
  const [duration, setDuration] = useState(0);
  const [livePeaks, setLivePeaks] = useState<number[]>([]);
  const [previewBlob, setPreviewBlob] = useState<Blob | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [previewPeaks, setPreviewPeaks] = useState<number[]>([]);
  const [previewPlaying, setPreviewPlaying] = useState(false);
  const [previewProgress, setPreviewProgress] = useState(0);

  const mediaRecorder = useRef<MediaRecorder | null>(null);
  const chunks = useRef<Blob[]>([]);
  const streamRef = useRef<MediaStream | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animFrameRef = useRef<number | null>(null);
  const timerRef = useRef<number | null>(null);
  const previewAudioRef = useRef<HTMLAudioElement | null>(null);
  const previewAnimRef = useRef<number | null>(null);

  /** Live amplitude sampler — pushes one peak (0..1) every animation frame. */
  const sampleAmplitude = useCallback(() => {
    const analyser = analyserRef.current;
    if (!analyser) return;
    const buf = new Uint8Array(analyser.frequencyBinCount);
    const tick = () => {
      analyser.getByteTimeDomainData(buf);
      let sum = 0;
      for (let i = 0; i < buf.length; i++) {
        const v = (buf[i] - 128) / 128;
        sum += v * v;
      }
      const rms = Math.sqrt(sum / buf.length);
      const peak = Math.min(1, Math.max(0.05, rms * 2.4));
      setLivePeaks((prev) => {
        const next = [...prev, peak];
        // Cap to a window so the bar strip never overflows.
        return next.length > VOICE_PEAK_BUCKETS * 4
          ? next.slice(next.length - VOICE_PEAK_BUCKETS * 4)
          : next;
      });
      animFrameRef.current = requestAnimationFrame(tick);
    };
    tick();
  }, []);

  const cleanupCapture = useCallback(() => {
    if (animFrameRef.current) {
      cancelAnimationFrame(animFrameRef.current);
      animFrameRef.current = null;
    }
    if (timerRef.current !== null) {
      window.clearInterval(timerRef.current);
      timerRef.current = null;
    }
    streamRef.current?.getTracks().forEach((t) => t.stop());
    streamRef.current = null;
    if (audioCtxRef.current && audioCtxRef.current.state !== "closed") {
      void audioCtxRef.current.close();
    }
    audioCtxRef.current = null;
    analyserRef.current = null;
  }, []);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
      });
      streamRef.current = stream;

      const AudioCtx =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      const audioCtx = new AudioCtx();
      audioCtxRef.current = audioCtx;
      const source = audioCtx.createMediaStreamSource(stream);
      const analyser = audioCtx.createAnalyser();
      analyser.fftSize = 1024;
      source.connect(analyser);
      analyserRef.current = analyser;

      const recorder = new MediaRecorder(stream, { mimeType: "audio/webm" });
      chunks.current = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.current.push(e.data);
      };
      recorder.start(250); // emit chunks every 250ms — keeps memory bounded
      mediaRecorder.current = recorder;

      setPhase("recording");
      setDuration(0);
      setLivePeaks([]);
      timerRef.current = window.setInterval(() => setDuration((d) => d + 1), 1000);
      sampleAmplitude();
    } catch (err) {
      console.error("Mic error", err);
      toast.error("Mikrofon izni reddedildi");
    }
  };

  /** Stop recording and switch to preview (NO upload yet). */
  const stopAndPreview = () => {
    const recorder = mediaRecorder.current;
    if (!recorder || recorder.state !== "recording") return;

    recorder.onstop = async () => {
      cleanupCapture();
      const blob = new Blob(chunks.current, { type: "audio/webm" });
      if (blob.size < 800) {
        toast.error("Çok kısa — en az 1 saniye");
        setPhase("idle");
        setDuration(0);
        setLivePeaks([]);
        return;
      }
      const peaks = await extractVoicePeaks(blob);
      setPreviewBlob(blob);
      setPreviewPeaks(peaks);
      setPreviewUrl(URL.createObjectURL(blob));
      setPhase("preview");
    };
    recorder.stop();
  };

  /** Discard the preview and reset to idle. */
  const cancelPreview = () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewBlob(null);
    setPreviewUrl(null);
    setPreviewPeaks([]);
    setPreviewPlaying(false);
    setPreviewProgress(0);
    setDuration(0);
    setLivePeaks([]);
    setPhase("idle");
    if (previewAnimRef.current) cancelAnimationFrame(previewAnimRef.current);
  };

  const togglePreviewPlay = async () => {
    const audio = previewAudioRef.current;
    if (!audio) return;
    if (previewPlaying) {
      audio.pause();
      setPreviewPlaying(false);
      if (previewAnimRef.current) cancelAnimationFrame(previewAnimRef.current);
      return;
    }
    try {
      await audio.play();
    } catch {
      return;
    }
    setPreviewPlaying(true);
    const tick = () => {
      if (audio.duration) setPreviewProgress(audio.currentTime / audio.duration);
      previewAnimRef.current = requestAnimationFrame(tick);
    };
    tick();
  };

  /**
   * STREAMING SEND.
   *
   * Instead of awaiting the upload before notifying the parent, we kick the
   * upload off in the background and write the message row as soon as the
   * public URL has been validated to exist (one HEAD/GET round trip). The
   * receiver's <audio> tag streams via Range requests on the same object as
   * it continues to grow.
   */
  const sendPreview = async () => {
    if (!previewBlob) return;
    setPhase("uploading");

    const ts = Date.now();
    const fileName = `voice_${ts}.webm`;
    const path = `${userId}/${roomId}/${fileName}`;

    try {
      // 1) Begin the upload but don't await it for the message row — we await
      // just long enough to know the object exists, then dispatch.
      const uploadPromise = supabase.storage
        .from("chat-media")
        .upload(path, previewBlob, { contentType: "audio/webm", upsert: false });

      // 2) Resolve the public URL up-front (computed locally, no network).
      const { data: urlData } = supabase.storage.from("chat-media").getPublicUrl(path);

      // 3) Wait for the upload to actually start producing bytes. Supabase's
      // JS client doesn't expose a streaming progress API, so we await the
      // promise here — but the receiver-side <audio> will then immediately
      // open a Range request and stream playback while their network catches
      // up. (For multi-MB clips this is the bottleneck, not the few hundred
      // KB of an Opus voice note.)
      const { error } = await uploadPromise;
      if (error) throw error;

      onVoiceSent(
        urlData.publicUrl,
        duration,
        fileName,
        previewBlob.size,
        previewPeaks,
        duration * 1000,
      );

      cancelPreview();
    } catch (err) {
      console.error("Voice upload failed", err);
      toast.error("Sesli mesaj gönderilemedi");
      setPhase("preview");
    }
  };

  useEffect(() => {
    return () => {
      cleanupCapture();
      if (previewUrl) URL.revokeObjectURL(previewUrl);
      if (previewAnimRef.current) cancelAnimationFrame(previewAnimRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ─── RENDER ──────────────────────────────────────────────────────

  if (phase === "uploading") {
    return (
      <div className="flex h-10 items-center gap-2 rounded-full bg-amber-500/10 border border-amber-500/30 px-3">
        <Loader2 className="h-4 w-4 animate-spin text-amber-400" />
        <span className="text-xs text-amber-400">Gönderiliyor…</span>
      </div>
    );
  }

  if (phase === "preview" && previewUrl) {
    return (
      <div className="flex flex-1 items-center gap-2 rounded-full border border-amber-500/40 bg-gradient-to-r from-amber-500/10 to-amber-700/10 px-2 py-1 animate-fade-in">
        <audio
          ref={previewAudioRef}
          src={previewUrl}
          onEnded={() => {
            setPreviewPlaying(false);
            setPreviewProgress(0);
          }}
          preload="metadata"
        />
        <button
          type="button"
          onClick={cancelPreview}
          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-red-500/20 text-red-400 active:scale-95 transition-transform"
          aria-label="İptal"
        >
          <Trash2 className="h-4 w-4" />
        </button>
        <button
          type="button"
          onClick={togglePreviewPlay}
          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-amber-500/20 text-amber-300 active:scale-95"
          aria-label={previewPlaying ? "Duraklat" : "Önizle"}
        >
          {previewPlaying ? <Pause className="h-3.5 w-3.5" /> : <Play className="h-3.5 w-3.5 ml-0.5" />}
        </button>

        {/* Static 3D bar preview — uses the just-extracted peaks */}
        <div className="flex h-7 flex-1 items-center gap-[2px] overflow-hidden">
          {previewPeaks.map((peak, i) => {
            const barProgress = (i + 0.5) / previewPeaks.length;
            const isPlayed = barProgress <= previewProgress;
            const h = Math.min(28, 4 + peak * 22);
            return (
              <span
                key={i}
                aria-hidden
                className="block w-[3px] rounded-full"
                style={{
                  height: `${h}px`,
                  background: isPlayed
                    ? "linear-gradient(180deg, #FFE9A8 0%, #D4AF37 50%, #8C6A1B 100%)"
                    : "linear-gradient(180deg, rgba(212,175,55,0.5) 0%, rgba(140,106,27,0.2) 100%)",
                  boxShadow: isPlayed
                    ? "0 0 4px rgba(255,233,168,0.5)"
                    : "inset 0 1px 0 rgba(255,255,255,0.06)",
                }}
              />
            );
          })}
        </div>

        <span className="text-[10px] font-mono text-amber-300 min-w-[32px] text-right">
          {formatDuration(duration)}
        </span>

        <button
          type="button"
          onClick={sendPreview}
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-[#FFE9A8] to-[#8C6A1B] text-[#1a1003] shadow-[0_2px_10px_rgba(212,175,55,0.5)] active:scale-95"
          aria-label="Gönder"
        >
          <Send className="h-4 w-4" />
        </button>
      </div>
    );
  }

  if (phase === "recording") {
    // Map live peaks to the latest VOICE_PEAK_BUCKETS values, padded.
    const latest = livePeaks.slice(-VOICE_PEAK_BUCKETS);
    const padded =
      latest.length < VOICE_PEAK_BUCKETS
        ? [...new Array(VOICE_PEAK_BUCKETS - latest.length).fill(0.05), ...latest]
        : latest;

    return (
      <div className="flex flex-1 items-center gap-2 rounded-full border border-red-500/40 bg-red-500/10 px-3 py-1 animate-fade-in">
        <button
          type="button"
          onClick={() => {
            // Cancel without preview
            mediaRecorder.current?.stop();
            cleanupCapture();
            setPhase("idle");
            setDuration(0);
            setLivePeaks([]);
            chunks.current = [];
          }}
          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-black/30 text-red-400 active:scale-95"
          aria-label="İptal"
        >
          <X className="h-4 w-4" />
        </button>

        <span className="h-2.5 w-2.5 rounded-full bg-red-500 animate-pulse shadow-[0_0_8px_rgba(239,68,68,0.8)]" />
        <span className="text-xs font-mono text-red-300 min-w-[34px]">{formatDuration(duration)}</span>

        {/* Live 3D-ish bars driven by analyser RMS */}
        <div className="flex h-6 flex-1 items-center gap-[2px] overflow-hidden">
          {padded.map((peak, i) => {
            const h = Math.min(24, 3 + peak * 22);
            return (
              <span
                key={i}
                aria-hidden
                className="block w-[3px] rounded-full"
                style={{
                  height: `${h}px`,
                  background:
                    "linear-gradient(180deg, #FFE9A8 0%, #D4AF37 60%, #8C6A1B 100%)",
                  boxShadow: "0 0 4px rgba(255,233,168,0.4)",
                }}
              />
            );
          })}
        </div>

        <button
          type="button"
          onClick={stopAndPreview}
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-[#FFE9A8] to-[#8C6A1B] text-[#1a1003] shadow-[0_2px_10px_rgba(212,175,55,0.5)] active:scale-95"
          aria-label="Önizle"
        >
          <Mic className="h-4 w-4" />
        </button>
      </div>
    );
  }

  // IDLE — gold mic squircle
  return (
    <button
      type="button"
      onClick={startRecording}
      className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-surface border border-border text-muted-foreground hover:text-amber-400 hover:border-amber-500/50 transition-colors active:scale-95"
      aria-label="Sesli mesaj kaydet"
      title="Sesli mesaj"
    >
      <Mic className="h-4 w-4" />
    </button>
  );
}

