import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { AlertCircle, X } from "lucide-react";

interface Announcement {
  id: string;
  title: string;
  body: string;
  severity: string;
}

export function GlobalAnnouncementBanner() {
  const [a, setA] = useState<Announcement | null>(null);
  const [dismissed, setDismissed] = useState<string[]>(() => {
    if (typeof window === "undefined") return [];
    try {
      return JSON.parse(localStorage.getItem("dismissed_announcements") || "[]");
    } catch {
      return [];
    }
  });

  useEffect(() => {
    supabase
      .from("global_announcements")
      .select("id,title,body,severity")
      .eq("is_active", true)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle()
      .then(({ data }) => setA(data));
  }, []);

  if (!a || dismissed.includes(a.id)) return null;

  const colors = {
    info: "from-blue-500/20 to-blue-700/20 border-blue-400/40 text-blue-100",
    warning: "from-amber-500/20 to-amber-700/20 border-amber-400/40 text-amber-100",
    critical: "from-red-500/20 to-red-700/20 border-red-400/40 text-red-100",
  }[a.severity] || "from-blue-500/20 to-blue-700/20 border-blue-400/40 text-blue-100";

  return (
    <div className={`mx-4 mb-3 rounded-2xl border bg-gradient-to-r ${colors} p-3 flex items-start gap-3 backdrop-blur-sm`}>
      <AlertCircle className="w-5 h-5 mt-0.5 shrink-0" />
      <div className="flex-1 min-w-0">
        <div className="font-semibold text-sm">{a.title}</div>
        <div className="text-xs opacity-80 mt-0.5">{a.body}</div>
      </div>
      <button
        onClick={() => {
          const next = [...dismissed, a.id];
          setDismissed(next);
          localStorage.setItem("dismissed_announcements", JSON.stringify(next));
        }}
        className="opacity-60 hover:opacity-100"
      >
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

