/**
 * DengBotCard — Telegram-tarzı interaktif bot mesaj kartı.
 *
 * Deng Support'dan gelen OTP, login approval, security alert, password reset
 * gibi mesajları altın çerçeveli glass card olarak gösterir. Onay gerektiren
 * kartlarda `Onayla` / `Reddet` butonları görünür ve `decide_bot_approval`
 * RPC'sini tetikler.
 */
import { CheckCircle2, XCircle, Clock, ShieldCheck, KeyRound, Phone, Bell } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useState } from "react";
import { toast } from "sonner";
import type { DengBotMessage } from "@/hooks/useDengBot";
import { cn } from "@/lib/utils";

interface Props {
  message: DengBotMessage;
  onDecide: (approvalId: string, decision: "approved" | "rejected") => Promise<any>;
  compact?: boolean;
}

const KIND_ICON: Record<string, typeof Bell> = {
  otp: KeyRound,
  approval: ShieldCheck,
  security_alert: ShieldCheck,
  call_log: Phone,
  info: Bell,
  system: Bell,
};

const KIND_LABEL: Record<string, string> = {
  otp: "Doğrulama Kodu",
  approval: "Onay İsteği",
  security_alert: "Güvenlik Uyarısı",
  call_log: "Arama Kaydı",
  info: "Bilgilendirme",
  system: "Sistem",
};

export function DengBotCard({ message, onDecide, compact }: Props) {
  const [busy, setBusy] = useState<"approve" | "reject" | null>(null);
  const Icon = KIND_ICON[message.bot_kind] ?? Bell;
  const isPending = message.approval?.status === "pending";
  const otpCode = message.bot_kind === "otp" ? message.metadata?.code : null;

  const handle = async (decision: "approved" | "rejected") => {
    if (!message.approval) return;
    setBusy(decision === "approved" ? "approve" : "reject");
    try {
      const res = await onDecide(message.approval.id, decision);
      if (res?.success) {
        toast.success(decision === "approved" ? "Onaylandı" : "Reddedildi");
      } else {
        toast.error(res?.error ?? "İşlem başarısız");
      }
    } catch (e: any) {
      toast.error(e?.message ?? "Hata oluştu");
    } finally {
      setBusy(null);
    }
  };

  return (
    <div
      className={cn(
        "relative overflow-hidden rounded-3xl border backdrop-blur-2xl transition-all",
        compact ? "p-3" : "p-4",
      )}
      style={{
        background:
          "linear-gradient(180deg, rgba(40,28,5,0.55) 0%, rgba(8,6,2,0.85) 100%)",
        borderColor: "rgba(245,205,83,0.35)",
        boxShadow:
          "0 10px 30px -12px rgba(0,0,0,0.7), inset 0 1px 0 rgba(255,234,170,0.18)",
      }}
    >
      {/* header */}
      <div className="flex items-center gap-2 mb-2">
        <div
          className="flex h-7 w-7 items-center justify-center rounded-full"
          style={{
            background: "linear-gradient(135deg, #FFE9A8, #C99A2E)",
            color: "#1a1100",
          }}
        >
          <Icon className="h-4 w-4" strokeWidth={2.4} />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5">
            <span className="text-xs font-semibold text-[#FFE9A8]">Deng Support</span>
            <span className="text-[10px] uppercase tracking-wider text-[#FFE9A8]/60">
              · {KIND_LABEL[message.bot_kind] ?? "Bot"}
            </span>
          </div>
          <div className="text-sm font-semibold text-white truncate">
            {message.subject}
          </div>
        </div>
      </div>

      {/* body */}
      <p className={cn("text-sm text-white/85 whitespace-pre-wrap", compact && "line-clamp-3")}>
        {message.body}
      </p>

      {/* OTP highlight */}
      {otpCode && (
        <div
          className="mt-3 rounded-2xl px-4 py-3 text-center font-mono text-2xl font-bold tracking-[0.4em]"
          style={{
            background: "rgba(245,205,83,0.12)",
            border: "1px solid rgba(245,205,83,0.35)",
            color: "#FFE9A8",
          }}
        >
          {otpCode}
        </div>
      )}

      {/* approval buttons */}
      {message.approval && (
        <div className="mt-3">
          {isPending ? (
            <div className="flex gap-2">
              <Button
                size="sm"
                disabled={!!busy}
                onClick={() => handle("approved")}
                className="flex-1 bg-emerald-500/90 hover:bg-emerald-500 text-white"
              >
                <CheckCircle2 className="h-4 w-4 mr-1.5" />
                {busy === "approve" ? "..." : "Onayla"}
              </Button>
              <Button
                size="sm"
                variant="outline"
                disabled={!!busy}
                onClick={() => handle("rejected")}
                className="flex-1 border-red-500/40 text-red-300 hover:bg-red-500/10"
              >
                <XCircle className="h-4 w-4 mr-1.5" />
                {busy === "reject" ? "..." : "Reddet"}
              </Button>
            </div>
          ) : (
            <div className="flex items-center gap-1.5 text-xs text-white/60">
              {message.approval.status === "approved" && (
                <><CheckCircle2 className="h-3.5 w-3.5 text-emerald-400" /> Onaylandı</>
              )}
              {message.approval.status === "rejected" && (
                <><XCircle className="h-3.5 w-3.5 text-red-400" /> Reddedildi</>
              )}
              {message.approval.status === "expired" && (
                <><Clock className="h-3.5 w-3.5 text-white/40" /> Süresi doldu</>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

