/**
 * DengSpark3D — Global floating 3D star (Three.js).
 * - Gold body + red pulse ring (project memory: gold accents + user-requested red).
 * - Idle: smooth rotation + soft pulse.
 * - Thinking: spins faster.
 * - Speaking: heartbeat pulse.
 * - Tap → onTap, Long-press (>500ms) → onLongPress.
 * - Pure inline canvas, no DOM transforms beyond positioning.
 */
import * as React from "react";
import * as THREE from "three";

export type DengSparkState = "idle" | "thinking" | "speaking";

interface Props {
  state?: DengSparkState;
  size?: number;
  onTap?: () => void;
  onLongPress?: () => void;
  className?: string;
  ariaLabel?: string;
  /** Live amplitude getter (0..1) for music-reactive pulse. */
  getAmplitude?: () => number;
}

export function DengSpark3D({
  state = "idle",
  size = 56,
  onTap,
  onLongPress,
  className,
  ariaLabel = "Deng AI",
  getAmplitude,
}: Props) {
  const mountRef = React.useRef<HTMLDivElement>(null);
  const stateRef = React.useRef<DengSparkState>(state);
  const ampRef = React.useRef<(() => number) | undefined>(getAmplitude);
  React.useEffect(() => {
    stateRef.current = state;
  }, [state]);
  React.useEffect(() => { ampRef.current = getAmplitude; }, [getAmplitude]);

  React.useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 100);
    camera.position.set(0, 0, 3.6);

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(size, size);
    renderer.setClearColor(0x000000, 0);
    mount.appendChild(renderer.domElement);
    renderer.domElement.style.display = "block";

    // ── Star geometry: 5-point star extruded ──
    const shape = new THREE.Shape();
    const points = 5;
    const outer = 1;
    const inner = 0.42;
    for (let i = 0; i < points * 2; i++) {
      const r = i % 2 === 0 ? outer : inner;
      const a = (i / (points * 2)) * Math.PI * 2 - Math.PI / 2;
      const x = Math.cos(a) * r;
      const y = Math.sin(a) * r;
      if (i === 0) shape.moveTo(x, y);
      else shape.lineTo(x, y);
    }
    shape.closePath();

    const geom = new THREE.ExtrudeGeometry(shape, {
      depth: 0.28,
      bevelEnabled: true,
      bevelThickness: 0.08,
      bevelSize: 0.06,
      bevelSegments: 4,
      curveSegments: 12,
    });
    geom.center();

    const mat = new THREE.MeshPhysicalMaterial({
      color: 0xff1a2c,        // sovereign red — the Red Spark
      metalness: 0.85,
      roughness: 0.22,
      clearcoat: 1,
      clearcoatRoughness: 0.1,
      emissive: 0xb8121f,
      emissiveIntensity: 0.45,
    });
    const star = new THREE.Mesh(geom, mat);
    scene.add(star);

    // Gold pulse ring (torus behind star) — sovereign luxury accent
    const ringGeom = new THREE.TorusGeometry(1.25, 0.04, 12, 64);
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xffd24a,
      transparent: true,
      opacity: 0.85,
    });
    const ring = new THREE.Mesh(ringGeom, ringMat);
    ring.position.z = -0.15;
    scene.add(ring);

    // Lights
    const ambient = new THREE.AmbientLight(0xfff0c8, 0.55);
    scene.add(ambient);
    const key = new THREE.DirectionalLight(0xffffff, 1.4);
    key.position.set(2, 3, 4);
    scene.add(key);
    const rim = new THREE.PointLight(0xffc857, 1.2, 8);
    rim.position.set(-2, -1, 2);
    scene.add(rim);

    let raf = 0;
    const start = performance.now();
    const tick = () => {
      const t = (performance.now() - start) / 1000;
      const s = stateRef.current;
      const spin = s === "thinking" ? 2.4 : s === "speaking" ? 1.0 : 0.55;
      star.rotation.y = t * spin;
      star.rotation.x = Math.sin(t * 0.6) * 0.15;

      // Pulse: heartbeat for speaking, soft for idle, fast for thinking
      const freq = s === "speaking" ? 2.2 : s === "thinking" ? 3.2 : 1.1;
      const pulse = 0.5 + 0.5 * Math.sin(t * Math.PI * freq);
      // Music-reactive amplitude (0..1) — overrides idle pulse if active
      const amp = ampRef.current ? Math.max(0, Math.min(1, ampRef.current())) : 0;
      const baseScale = 1 + (s === "speaking" ? 0.18 : 0.08) * pulse;
      const scale = baseScale + amp * 0.35;
      ring.scale.setScalar(scale);
      ringMat.opacity = 0.35 + 0.55 * Math.max(pulse, amp);
      mat.emissiveIntensity = 0.25 + 0.35 * pulse + amp * 0.6;

      renderer.render(scene, camera);
      raf = requestAnimationFrame(tick);
    };
    tick();

    return () => {
      cancelAnimationFrame(raf);
      renderer.dispose();
      geom.dispose();
      mat.dispose();
      ringGeom.dispose();
      ringMat.dispose();
      if (renderer.domElement.parentNode === mount) {
        mount.removeChild(renderer.domElement);
      }
    };
  }, [size]);

  // Tap vs long-press
  const pressTimer = React.useRef<number | null>(null);
  const longFired = React.useRef(false);
  const handleDown = () => {
    longFired.current = false;
    if (onLongPress) {
      pressTimer.current = window.setTimeout(() => {
        longFired.current = true;
        onLongPress();
      }, 500);
    }
  };
  const handleUp = () => {
    if (pressTimer.current) {
      clearTimeout(pressTimer.current);
      pressTimer.current = null;
    }
    if (!longFired.current) onTap?.();
  };
  const handleCancel = () => {
    if (pressTimer.current) {
      clearTimeout(pressTimer.current);
      pressTimer.current = null;
    }
    longFired.current = false;
  };

  return (
    <button
      type="button"
      aria-label={ariaLabel}
      className={className}
      onPointerDown={handleDown}
      onPointerUp={handleUp}
      onPointerLeave={handleCancel}
      onPointerCancel={handleCancel}
      style={{
        width: size,
        height: size,
        padding: 0,
        background: "transparent",
        border: "none",
        cursor: "pointer",
        filter: "drop-shadow(0 6px 22px rgba(255,30,50,0.55)) drop-shadow(0 2px 10px rgba(255,210,80,0.4))",
        touchAction: "manipulation",
      }}
    >
      <div ref={mountRef} style={{ width: size, height: size }} />
    </button>
  );
}

