/**
 * DengSparkHost — Mounts the global Red/Gold Spark on every authed page.
 * - Smart positioning: bottom-right, lifted above bottom tab bar (96px) +
 *   safe-area inset. Hidden during full-screen calls and on the dedicated
 *   /deng route (where the dock+composer already exists).
 * - Tap → open ChatGPT-style overlay. Long-press → start voice listening.
 */
import * as React from "react";
import { useLocation } from "@tanstack/react-router";
import { DengSpark3D, type DengSparkState } from "./DengSpark3D";
import { DengSparkOverlay } from "./DengSparkOverlay";
import { useAuth } from "@/hooks/useAuth";
import { useJiyanMusic } from "@/hooks/useJiyanMusic";
import { useRitualClock } from "@/hooks/useRitualClock";

const HIDDEN_ROUTES = ["/deng", "/login", "/sso/authorize"];

export function DengSparkHost() {
  const { user } = useAuth();
  const location = useLocation();
  const [open, setOpen] = React.useState(false);
  const [voice, setVoice] = React.useState(false);
  const [state, setState] = React.useState<DengSparkState>("idle");
  const { getAmplitude, isPlaying } = useJiyanMusic();
  const { next, glow } = useRitualClock();

  // Ritual halo: gold pulse when next prayer is within 5 minutes OR when the
  // ritual clock has fired its T-0 glow flag.
  const ritualNear =
    glow || (next && next.msUntil > 0 && next.msUntil <= 5 * 60_000);

  const path = location.pathname;
  const hidden = !user || HIDDEN_ROUTES.some((p) => path === p || path.startsWith(p + "/"));

  if (hidden) return null;

  return (
    <>
      <div
        style={{
          position: "fixed",
          right: 14,
          // Lift above the 7-tab bottom bar (~72px) + safe area
          bottom: "calc(env(safe-area-inset-bottom, 0px) + 92px)",
          zIndex: 9997,
          pointerEvents: "auto",
        }}
        aria-label={ritualNear ? "Vakit yaklaştı — Ritüel Yardımcısı" : undefined}
      >
        {ritualNear && (
          <span
            aria-hidden
            style={{
              position: "absolute",
              inset: -10,
              borderRadius: "9999px",
              boxShadow:
                "0 0 0 2px rgba(255,215,90,0.55), 0 0 28px rgba(212,175,55,0.85)",
              animation: "deng-ritual-halo 2.2s ease-in-out infinite",
              pointerEvents: "none",
            }}
          />
        )}
        <DengSpark3D
          state={state}
          size={56}
          getAmplitude={isPlaying ? getAmplitude : undefined}
          onTap={() => {
            // Spec: ONE TAP = voice listening
            setVoice(true);
            setOpen(true);
          }}
          onLongPress={() => {
            // Spec: LONG PRESS = text input
            setVoice(false);
            setOpen(true);
          }}
        />
        <style>{`
          @keyframes deng-ritual-halo {
            0%,100% { opacity: 0.55; transform: scale(1); }
            50%     { opacity: 1;    transform: scale(1.08); }
          }
        `}</style>
      </div>
      <DengSparkOverlay
        open={open}
        onOpenChange={(v) => {
          setOpen(v);
          if (!v) setVoice(false);
        }}
        initialVoice={voice}
        onStateChange={setState}
      />
    </>
  );
}

