/**
 * DengSparkOverlay — Compact ChatGPT-style mini chat sheet.
 * Triggered globally by the floating DengSpark. Streams responses from
 * the deng-ai edge function (Jiyan Sovereign Intelligence brain) and
 * routes "ara/call +777 …" commands to the Sovereign Phone.
 *
 * Brand rule: never expose underlying engine names — this UI only shows
 * "Deng AI" and the golden 777 mark.
 */
import * as React from "react";
import { Send, X, ShieldCheck, Volume2, VolumeX } from "lucide-react";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { lookupByKurdId, useSovereignPhone } from "@/hooks/useSovereignPhone";
import { useJiyanMusic } from "@/hooks/useJiyanMusic";
import { parseDengCommand } from "@/lib/parseDengCommand";
import { useDengApproval } from "@/hooks/useDengApproval";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { logLocalOutgoingCall } from "@/lib/phoneRecent";
import { DengSpark3D, type DengSparkState } from "./DengSpark3D";

interface Turn {
  id: string;
  side: "user" | "deng";
  text: string;
}

const DENG_URL = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/deng-ai`;

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  initialVoice?: boolean;
  onStateChange?: (s: "idle" | "thinking" | "speaking") => void;
}

export function DengSparkOverlay({ open, onOpenChange, initialVoice, onStateChange }: Props) {
  const { placeCall } = useSovereignPhone();
  const { user } = useAuth();
  const { request: requestApproval, busy: approvalBusy, pending } = useDengApproval();
  const music = useJiyanMusic();
  const [text, setText] = React.useState("");
  const [turns, setTurns] = React.useState<Turn[]>([]);
  const [thinking, setThinking] = React.useState(false);
  const [listening, setListening] = React.useState(!!initialVoice);
  // "Listen" mode — when ON, Deng auto-speaks every reply via Web Speech TTS.
  // Default: ON per Sovereign Intelligence spec (text streaming + TTS simultaneously).
  const [autoSpeak, setAutoSpeak] = React.useState<boolean>(() => {
    try {
      const v = localStorage.getItem("deng-autospeak");
      return v == null ? true : v === "1";
    } catch { return true; }
  });
  React.useEffect(() => {
    try { localStorage.setItem("deng-autospeak", autoSpeak ? "1" : "0"); } catch {}
  }, [autoSpeak]);
  const scrollerRef = React.useRef<HTMLDivElement>(null);

  // Speak helper — uses Web Speech API (FREE, instant, on-device).
  const speak = React.useCallback((raw: string) => {
    if (!autoSpeak || !raw?.trim()) return;
    if (typeof window === "undefined" || !("speechSynthesis" in window)) return;
    try {
      window.speechSynthesis.cancel();
      // Strip markdown for cleaner speech
      const clean = raw
        .replace(/[#*_`>]/g, "")
        .replace(/!\[[^\]]*\]\([^)]+\)/g, "")
        .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
        .replace(/\s+/g, " ")
        .trim();
      const utt = new SpeechSynthesisUtterance(clean.slice(0, 800));
      utt.lang = "tr-TR";
      utt.rate = 1.0;
      utt.pitch = 1.0;
      window.speechSynthesis.speak(utt);
    } catch {}
  }, [autoSpeak]);

  React.useEffect(() => {
    onStateChange?.(thinking ? "thinking" : "idle");
  }, [thinking, onStateChange]);

  React.useEffect(() => {
    scrollerRef.current?.scrollTo({
      top: scrollerRef.current.scrollHeight,
      behavior: "smooth",
    });
  }, [turns, thinking]);

  // Close on swipe-down
  const startY = React.useRef<number | null>(null);
  const handleTouchStart = (e: React.TouchEvent) => {
    startY.current = e.touches[0].clientY;
  };
  const handleTouchEnd = (e: React.TouchEvent) => {
    if (startY.current == null) return;
    const dy = e.changedTouches[0].clientY - startY.current;
    if (dy > 80) onOpenChange(false);
    startY.current = null;
  };

  // Tiny helpers to keep the command router compact
  const pushTurns = (userText: string) => {
    const userTurn: Turn = { id: crypto.randomUUID(), side: "user", text: userText };
    const dengId = crypto.randomUUID();
    setTurns((t) => [...t, userTurn, { id: dengId, side: "deng", text: "" }]);
    return { userTurn, dengId };
  };
  const updateDeng = (dengId: string, text: string) =>
    setTurns((p) => p.map((t) => (t.id === dengId ? { ...t, text } : t)));

  const ask = React.useCallback(
    async (raw: string) => {
      const trimmed = raw.trim();
      if (!trimmed || thinking) return;

      // ─── Cross-app command router ──────────────────────────────
      const intent = parseDengCommand(trimmed);

      // 1) Phone bridge
      if (intent?.kind === "call") {
        const cmd = intent.data;
        setText("");
        const { dengId } = pushTurns(trimmed);
        updateDeng(dengId, `📞 Aranıyor: ${cmd.kurdId}…`);
        logLocalOutgoingCall(cmd.kurdId, cmd.video, "Giden Arama");
        const peer = await lookupByKurdId(cmd.kurdId);
        if (!peer?.user_id) {
          updateDeng(dengId, `📞 ${cmd.kurdId} Sovereign ağda kayıtlı değil. Sadece +777 yurttaşları aranabilir.`);
          return;
        }
        const res = await placeCall(peer.user_id, cmd.video);
        updateDeng(
          dengId,
          res.ok
            ? `📞 ${cmd.video ? "Görüntülü" : "Sesli"} arama başlatıldı: ${cmd.kurdId}`
            : `📞 Şifreli hat açılamadı: ${res.reason ?? "bilinmeyen hata"}`,
        );
        return;
      }

      // 2) DiravCash transfer — REQUIRES Deng approval (biometric/onay)
      if (intent?.kind === "transfer") {
        if (!user) {
          toast.error("Önce giriş yap");
          return;
        }
        setText("");
        const { dengId } = pushTurns(trimmed);

        // Resolve recipient
        let recipientId: string | null = null;
        let recipientLabel = "";
        if (intent.target.type === "kurdId") {
          const { data } = await supabase
            .from("profiles")
            .select("user_id, display_name")
            .eq("kurd_id", intent.target.kurdId)
            .maybeSingle();
          recipientId = data?.user_id ?? null;
          recipientLabel = data?.display_name ?? intent.target.kurdId;
        } else {
          const { data } = await supabase
            .from("profiles")
            .select("user_id, display_name, username")
            .eq("username", intent.target.handle)
            .maybeSingle();
          recipientId = data?.user_id ?? null;
          recipientLabel = data?.display_name ?? `@${intent.target.handle}`;
        }
        if (!recipientId) {
          updateDeng(dengId, `❌ Alıcı bulunamadı.`);
          toast.error("Alıcı bulunamadı");
          return;
        }
        if (recipientId === user.id) {
          updateDeng(dengId, `❌ Kendine transfer yapamazsın.`);
          return;
        }

        updateDeng(
          dengId,
          `🔐 ${intent.amount} DC → ${recipientLabel}\n\n_Deng Onay bekleniyor — Inbox'tan onaylayın…_`,
        );

        const ok = await requestApproval({
          actionType: "payment",
          subject: `${intent.amount} DC transfer onayı`,
          body: `Deng AI üzerinden başlatıldı:\n\n• Alıcı: ${recipientLabel}\n• Tutar: ${intent.amount} DC\n\nOnaylıyor musun?`,
          payload: { amount: intent.amount, recipient_id: recipientId, source: "deng_spark" },
          expiresInMinutes: 3,
        });
        if (!ok) {
          updateDeng(dengId, `🚫 Transfer iptal edildi (onay verilmedi).`);
          return;
        }

        const { data, error } = await supabase.rpc("send_tip", {
          _sender_id: user.id,
          _receiver_id: recipientId,
          _amount: intent.amount,
          _message: `Deng AI komutu`,
        });
        const result = (data ?? {}) as { success?: boolean; error?: string };
        if (error || !result.success) {
          updateDeng(dengId, `❌ Transfer başarısız: ${result.error ?? error?.message ?? "bilinmeyen hata"}`);
          toast.error("Transfer başarısız");
        } else {
          updateDeng(dengId, `✅ ${intent.amount} DC gönderildi → ${recipientLabel}`);
          toast.success(`${intent.amount} DC gönderildi`);
        }
        return;
      }

      // 3) Mail summary
      if (intent?.kind === "mail_summary") {
        if (!user) {
          toast.error("Önce giriş yap");
          return;
        }
        setText("");
        const { dengId } = pushTurns(trimmed);
        updateDeng(dengId, `📬 Inbox taranıyor…`);
        const { data: msgs } = await supabase
          .from("inbox_messages")
          .select("subject, body, is_read, created_at")
          .eq("recipient_id", user.id)
          .order("created_at", { ascending: false })
          .limit(intent.limit ?? 5);

        const list = msgs ?? [];
        if (list.length === 0) {
          updateDeng(dengId, `📭 Inbox boş.`);
          return;
        }
        const unread = list.filter((m: any) => !m.is_read).length;
        const lines = list
          .map((m: any, i: number) => {
            const tag = m.is_read ? "  " : "🔵";
            const subj = (m.subject ?? "(başlıksız)").slice(0, 60);
            const snippet = (m.body ?? "").replace(/\s+/g, " ").slice(0, 80);
            return `${tag} ${i + 1}. **${subj}** — ${snippet}${snippet.length >= 80 ? "…" : ""}`;
          })
          .join("\n");
        updateDeng(
          dengId,
          `📬 Son ${list.length} mesaj (${unread} okunmamış):\n\n${lines}`,
        );
        return;
      }

      // 4) Ritual — open /ritual hub on relevant tab
      if (intent?.kind === "ritual") {
        setText("");
        const { dengId } = pushTurns(trimmed);
        const labels: Record<string, string> = {
          times: "🕌 Namaz vakitleri açılıyor…",
          quran: "📖 Kur'an okuyucu açılıyor…",
          cevsen: "✨ Cevşen açılıyor…",
          dua: "🌙 Günün duası açılıyor…",
          qibla: "🧭 Kıble pusulası yakında — şimdilik vakitler ekranı açılıyor.",
        };
        updateDeng(dengId, labels[intent.action] ?? "🕌 Ritüel sarayı açılıyor…");
        onOpenChange(false);
        setTimeout(() => { window.location.href = "/ritual"; }, 250);
        return;
      }
      // ───────────────────────────────────────────────────────────


      setText("");
      const userTurn: Turn = { id: crypto.randomUUID(), side: "user", text: trimmed };
      const dengId = crypto.randomUUID();
      setTurns((t) => [...t, userTurn, { id: dengId, side: "deng", text: "" }]);
      setThinking(true);

      try {
        const history = [...turns, userTurn].map((t) => ({
          role: t.side === "user" ? "user" : "assistant",
          content: t.text,
        }));
        const resp = await fetch(DENG_URL, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}`,
          },
          body: JSON.stringify({ messages: history }),
        });
        if (!resp.ok || !resp.body) throw new Error(`HTTP ${resp.status}`);

        const reader = resp.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";
        let acc = "";
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });
          let idx;
          while ((idx = buffer.indexOf("\n")) !== -1) {
            let line = buffer.slice(0, idx);
            buffer = buffer.slice(idx + 1);
            if (line.endsWith("\r")) line = line.slice(0, -1);
            if (!line.startsWith("data: ")) continue;
            const json = line.slice(6).trim();
            if (json === "[DONE]") continue;
            try {
              const parsed = JSON.parse(json);
              const delta = parsed.choices?.[0]?.delta?.content;
              if (delta) {
                acc += delta;
                setTurns((prev) =>
                  prev.map((t) => (t.id === dengId ? { ...t, text: acc } : t)),
                );
              }
            } catch {
              buffer = line + "\n" + buffer;
              break;
            }
          }
        }
        // Stream finished — auto-speak the final reply if Listen mode is on.
        if (acc) speak(acc);
      } catch (e) {
        console.error(e);
        setTurns((p) =>
          p.map((t) =>
            t.id === dengId
              ? { ...t, text: "❌ Şu an Deng'e ulaşamıyorum. Birazdan tekrar dene." }
              : t,
          ),
        );
      } finally {
        setThinking(false);
      }
    },
    [thinking, turns, placeCall, user, requestApproval, speak],
  );

  // Web Speech API for voice input
  const recogRef = React.useRef<any>(null);
  const startListening = React.useCallback(() => {
    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SR) {
      toast.error("Bu cihaz sesli komutu desteklemiyor");
      return;
    }
    const r = new SR();
    r.lang = "tr-TR";
    r.continuous = false;
    r.interimResults = true;
    r.onresult = (e: any) => {
      let s = "";
      for (let i = e.resultIndex; i < e.results.length; i++) s += e.results[i][0].transcript;
      setText(s);
      if (e.results[e.results.length - 1].isFinal) {
        setListening(false);
        ask(s);
      }
    };
    r.onend = () => setListening(false);
    r.onerror = () => setListening(false);
    recogRef.current = r;
    setListening(true);
    r.start();
  }, [ask]);

  React.useEffect(() => {
    if (open && initialVoice) startListening();
    return () => {
      try {
        recogRef.current?.stop();
      } catch {}
    };
  }, [open, initialVoice, startListening]);

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-[9998] flex items-end justify-center"
      onClick={(e) => {
        if (e.target === e.currentTarget) onOpenChange(false);
      }}
      style={{ background: "rgba(0,0,0,0.55)", backdropFilter: "blur(8px)" }}
    >
      <div
        className="w-full max-w-md rounded-t-3xl border-t border-white/10 bg-background/85 shadow-2xl backdrop-blur-2xl"
        style={{ maxHeight: "80vh", display: "flex", flexDirection: "column" }}
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
      >
        {/* drag handle */}
        <div className="flex items-center justify-center pt-2 pb-1">
          <div className="h-1 w-10 rounded-full bg-white/25" />
        </div>

        <header className="flex items-center justify-between px-5 pb-3">
          <div className="flex items-center gap-3">
            <DengSpark3D state={thinking ? "thinking" : "idle"} size={36} ariaLabel="Deng" />
            <div className="text-center sm:text-left">
              <div
                className="text-base font-semibold tracking-[0.18em] text-amber-300"
                style={{ fontFamily: "'Cinzel', serif" }}
              >
                DENG AI
              </div>
              <div className="text-[9px] uppercase tracking-[0.32em] text-amber-200/60">
                Sovereign Intelligence
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {(approvalBusy || pending?.status === "pending") && (
              <span className="inline-flex items-center gap-1 rounded-full border border-amber-400/30 bg-amber-400/10 px-2 py-0.5 text-[10px] font-medium text-amber-300">
                <ShieldCheck className="h-3 w-3" />
                Deng Onay
              </span>
            )}
            <button
              type="button"
              onClick={() => {
                if (autoSpeak && typeof window !== "undefined" && "speechSynthesis" in window) {
                  window.speechSynthesis.cancel();
                }
                setAutoSpeak((v) => !v);
              }}
              className={`rounded-full p-2 transition-colors ${
                autoSpeak
                  ? "bg-amber-400/15 text-amber-300"
                  : "text-muted-foreground hover:bg-white/10"
              }`}
              aria-label={autoSpeak ? "Sessize al" : "Listen modu"}
              title={autoSpeak ? "Listen: AÇIK" : "Listen: KAPALI"}
            >
              {autoSpeak ? <Volume2 className="h-4 w-4" /> : <VolumeX className="h-4 w-4" />}
            </button>
            <button
              type="button"
              onClick={() => onOpenChange(false)}
              className="rounded-full p-2 hover:bg-white/10"
              aria-label="Kapat"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </header>

        <div
          ref={scrollerRef}
          className="flex-1 space-y-3 overflow-y-auto px-4 pb-3"
          style={{ minHeight: 160 }}
        >
          {turns.length === 0 && !thinking && (
            <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4 text-center text-xs text-muted-foreground">
              Sor, söyle veya komut ver — örn. <span className="text-foreground">"ara +777 1234 5678"</span>
            </div>
          )}
          {turns.map((t) => (
            <div
              key={t.id}
              className={`max-w-[85%] rounded-2xl px-3.5 py-2 text-sm leading-relaxed ${
                t.side === "user"
                  ? "ml-auto bg-amber-500/15 text-foreground border border-amber-400/20"
                  : "mr-auto bg-white/5 text-foreground border border-white/10"
              }`}
            >
              {t.text || (t.side === "deng" ? <span className="opacity-60">…</span> : null)}
            </div>
          ))}
          {thinking && (
            <div className="mr-auto inline-flex items-center gap-1.5 rounded-2xl bg-white/5 border border-white/10 px-3 py-2">
              <span className="h-1.5 w-1.5 rounded-full bg-amber-400 animate-pulse" />
              <span className="h-1.5 w-1.5 rounded-full bg-amber-400 animate-pulse [animation-delay:0.15s]" />
              <span className="h-1.5 w-1.5 rounded-full bg-amber-400 animate-pulse [animation-delay:0.3s]" />
            </div>
          )}
        </div>

        <footer className="border-t border-white/10 bg-background/70 p-3 pb-[max(env(safe-area-inset-bottom),12px)]">
          <div className="flex items-end gap-2">
            <Textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  ask(text);
                }
              }}
              placeholder={listening ? "Dinleniyor…" : "Deng'e sor…"}
              rows={1}
              className="min-h-[40px] max-h-32 resize-none rounded-2xl border-white/10 bg-white/5"
            />
            <div
              onClick={() => (listening ? recogRef.current?.stop() : startListening())}
              role="button"
              aria-label={listening ? "Dinlemeyi durdur" : "Sesli komut"}
              className={`shrink-0 cursor-pointer rounded-full transition ${
                listening ? "ring-2 ring-red-500/60" : ""
              }`}
            >
              <DengSpark3D
                state={listening ? "speaking" : thinking ? "thinking" : "idle"}
                size={40}
                ariaLabel="Deng yıldızı"
              />
            </div>
            <Button
              type="button"
              size="icon"
              onClick={() => ask(text)}
              disabled={!text.trim() || thinking}
              className="h-10 w-10 rounded-full bg-gradient-to-br from-amber-400 to-amber-600 text-black hover:opacity-90"
              aria-label="Gönder"
            >
              <Send className="h-4 w-4" />
            </Button>
          </div>
        </footer>
      </div>
    </div>
  );
}

