/**
 * DengVoiceMode — minimal, ChatGPT-style full-screen voice (+optional video) mode.
 *
 * Akış:
 *  1. Mikrofon izni iste — reddedilirse net uyarı + yazılı moda otomatik geçiş
 *  2. Sürekli dinleme (Web Speech API, tr-TR)
 *  3. Final transcript → deng-ai edge function streaming
 *  4. Cevap geldikçe TTS ile yüksek sesle okur (VoiceService)
 *  5. TTS bitince yeniden dinlemeye geçer
 *
 * Header'da "Yazılı" butonuyla anlık olarak yazılı moda geçilebilir.
 * Footer'da Video butonu → ön kamera self-view (görüntülü konuşma hissi).
 */
import * as React from "react";
import { X, Mic, MicOff, Video, VideoOff, MessageSquare, History } from "lucide-react";
import { VoiceService } from "@/services/voiceService";
import { useAudioAmplitude } from "@/hooks/useAudioAmplitude";
import { DengSpark3D } from "./DengSpark3D";
import { toast } from "sonner";

type VoiceState = "idle" | "listening" | "thinking" | "speaking";

const DENG_URL = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/deng-ai`;

export interface DengTranscriptTurn {
  side: "user" | "deng";
  text: string;
  source: "voice" | "text";
  ts: number;
}

interface Props {
  open: boolean;
  onClose: () => void;
  /** Mic permission reddedildiğinde / desteklenmediğinde yazılı moda düşür. */
  onFallbackToText?: (reason: string) => void;
  /** Açılışta kamera otomatik aç (görüntülü konuşma). */
  initialVideo?: boolean;
  /** Pre-acquired stream from a user gesture (keeps iOS Safari happy). */
  initialVideoStream?: MediaStream | null;
  /** Append voice turns into shared session transcript. */
  onTurn?: (turn: DengTranscriptTurn) => void;
  /** Open the unified transcript history sheet. */
  onOpenHistory?: () => void;
}

export function DengVoiceMode({ open, onClose, onFallbackToText, initialVideo = false, initialVideoStream = null, onTurn, onOpenHistory }: Props) {
  const [state, setState] = React.useState<VoiceState>("idle");
  const [partial, setPartial] = React.useState("");
  const [lastReply, setLastReply] = React.useState("");
  const [history, setHistory] = React.useState<{ role: "user" | "assistant"; content: string }[]>([]);
  const [videoOn, setVideoOn] = React.useState(false);

  const recogRef = React.useRef<any>(null);
  const audioRef = React.useRef<HTMLAudioElement | null>(null);
  const stoppingRef = React.useRef(false);
  const stateRef = React.useRef<VoiceState>("idle");
  const videoStreamRef = React.useRef<MediaStream | null>(null);
  const videoElRef = React.useRef<HTMLVideoElement | null>(null);

  React.useEffect(() => {
    stateRef.current = state;
  }, [state]);

  const stopAll = React.useCallback(() => {
    stoppingRef.current = true;
    try { recogRef.current?.stop(); } catch {}
    try { audioRef.current?.pause(); } catch {}
    try {
      if (typeof window !== "undefined" && "speechSynthesis" in window) {
        window.speechSynthesis.cancel();
      }
    } catch {}
    try {
      videoStreamRef.current?.getTracks().forEach((t) => t.stop());
      videoStreamRef.current = null;
    } catch {}
  }, []);

  const fallbackToText = React.useCallback(
    (reason: string) => {
      stopAll();
      setState("idle");
      toast.warning(reason, {
        description: "Deng yazılı moda geçiyor — klavyeden yazabilirsin.",
        duration: 5000,
      });
      if (onFallbackToText) onFallbackToText(reason);
      else onClose();
    },
    [onClose, onFallbackToText, stopAll],
  );

  const speak = React.useCallback(async (text: string) => {
    if (!text.trim()) return;
    setState("speaking");
    try {
      const r = await VoiceService.synthesize({ text, lang: "tr" });
      if (r.audioUrl) {
        const a = new Audio(r.audioUrl);
        audioRef.current = a;
        await new Promise<void>((resolve) => {
          a.onended = () => resolve();
          a.onerror = () => resolve();
          a.play().catch(() => resolve());
        });
        VoiceService.revoke(r.audioUrl);
      } else if (typeof window !== "undefined" && "speechSynthesis" in window) {
        await new Promise<void>((resolve) => {
          const utt = new SpeechSynthesisUtterance(text);
          utt.lang = "tr-TR";
          utt.rate = 1.0;
          utt.onend = () => resolve();
          utt.onerror = () => resolve();
          window.speechSynthesis.speak(utt);
        });
      }
    } catch (e) {
      console.warn("[DengVoiceMode] TTS failed", e);
    }
  }, []);

  const startListening = React.useCallback(() => {
    const SR =
      (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SR) {
      fallbackToText("Tarayıcın sesli komutu desteklemiyor");
      return;
    }
    try {
      const r = new SR();
      r.lang = "tr-TR";
      r.continuous = false;
      r.interimResults = true;
      r.onresult = (e: any) => {
        let s = "";
        for (let i = e.resultIndex; i < e.results.length; i++) {
          s += e.results[i][0].transcript;
        }
        setPartial(s);
        if (e.results[e.results.length - 1].isFinal) {
          askDeng(s);
        }
      };
      r.onend = () => {
        // Otomatik tekrar başlat (sadece listening içindeyken).
        if (!stoppingRef.current && stateRef.current === "listening") {
          try { r.start(); } catch {}
        }
      };
      r.onerror = (ev: any) => {
        if (ev?.error === "not-allowed" || ev?.error === "service-not-allowed") {
          fallbackToText("Mikrofon izni reddedildi");
        } else if (ev?.error === "no-speech") {
          // sessizlik — yok say
        } else {
          console.warn("[DengVoiceMode] recog error", ev?.error);
        }
      };
      recogRef.current = r;
      setState("listening");
      r.start();
    } catch (e) {
      console.warn("[DengVoiceMode] start failed", e);
      fallbackToText("Sesli mod başlatılamadı");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fallbackToText]);

  const askDeng = React.useCallback(async (userText: string) => {
    const trimmed = userText.trim();
    if (!trimmed) return;
    setState("thinking");
    setPartial("");

    const nextHistory = [...history, { role: "user" as const, content: trimmed }];
    setHistory(nextHistory);
    onTurn?.({ side: "user", text: trimmed, source: "voice", ts: Date.now() });

    try {
      const resp = await fetch(DENG_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}`,
        },
        body: JSON.stringify({ messages: nextHistory }),
      });
      if (!resp.ok || !resp.body) throw new Error(`HTTP ${resp.status}`);
      const reader = resp.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      let acc = "";
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        let idx;
        while ((idx = buffer.indexOf("\n")) !== -1) {
          let line = buffer.slice(0, idx);
          buffer = buffer.slice(idx + 1);
          if (line.endsWith("\r")) line = line.slice(0, -1);
          if (!line.startsWith("data: ")) continue;
          const json = line.slice(6).trim();
          if (json === "[DONE]") continue;
          try {
            const parsed = JSON.parse(json);
            const delta = parsed.choices?.[0]?.delta?.content;
            if (delta) {
              acc += delta;
              setPartial(acc);
            }
          } catch {
            buffer = line + "\n" + buffer;
            break;
          }
        }
      }

      setLastReply(acc);
      setHistory((h) => [...h, { role: "assistant", content: acc }]);
      if (acc) onTurn?.({ side: "deng", text: acc, source: "voice", ts: Date.now() });
      if (!stoppingRef.current) {
        await speak(acc);
      }
    } catch (e) {
      console.error("[DengVoiceMode] ask failed", e);
      toast.error("Deng'e ulaşamadım");
    } finally {
      if (!stoppingRef.current && open) {
        startListening();
      } else {
        setState("idle");
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [history, open, speak, startListening, onTurn]);

  // Açılışta mikrofon iste + (varsa) önceden alınmış kamera akışını bağla.
  React.useEffect(() => {
    if (open) {
      stoppingRef.current = false;
      setHistory([]);
      setPartial("");
      setLastReply("");

      // Pre-acquired video stream (gesture-preserved on iOS Safari)
      if (initialVideoStream) {
        videoStreamRef.current = initialVideoStream;
        setVideoOn(true);
        // attach in next paint
        requestAnimationFrame(() => {
          if (videoElRef.current && videoStreamRef.current) {
            videoElRef.current.srcObject = videoStreamRef.current;
            videoElRef.current.play().catch(() => {});
          }
        });
      } else {
        setVideoOn(initialVideo);
      }

      if (!navigator.mediaDevices?.getUserMedia) {
        fallbackToText("Bu cihaz mikrofonu desteklemiyor");
        return;
      }
      navigator.mediaDevices.getUserMedia({ audio: true })
        .then((s) => {
          s.getTracks().forEach((t) => t.stop());
          startListening();
        })
        .catch((err: any) => {
          const denied = err?.name === "NotAllowedError" || err?.name === "SecurityError";
          fallbackToText(denied ? "Mikrofon izni reddedildi" : "Mikrofona erişilemedi");
        });
    } else {
      stopAll();
      setState("idle");
      setVideoOn(false);
    }
    return () => stopAll();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  // Re-attach stream if videoOn flips on while we already hold a ref
  React.useEffect(() => {
    if (videoOn && videoElRef.current && videoStreamRef.current && !videoElRef.current.srcObject) {
      videoElRef.current.srcObject = videoStreamRef.current;
      videoElRef.current.play().catch(() => {});
    }
  }, [videoOn]);

  /**
   * Gesture-preserving video toggle. iOS Safari requires getUserMedia to be
   * invoked synchronously inside the click handler, otherwise the prompt is
   * silently swallowed. Camera reddedilirse → video kapanır, sesli mod
   * çalışmaya devam eder ve net bir uyarı gösterilir (yazılı moda DÜŞMEZ).
   */
  const toggleVideo = React.useCallback(async () => {
    if (videoOn) {
      try {
        videoStreamRef.current?.getTracks().forEach((t) => t.stop());
        videoStreamRef.current = null;
        if (videoElRef.current) videoElRef.current.srcObject = null;
      } catch {}
      setVideoOn(false);
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" } });
      videoStreamRef.current = stream;
      setVideoOn(true);
      requestAnimationFrame(() => {
        if (videoElRef.current) {
          videoElRef.current.srcObject = stream;
          videoElRef.current.play().catch(() => {});
        }
      });
    } catch (err: any) {
      const denied = err?.name === "NotAllowedError" || err?.name === "SecurityError";
      const notFound = err?.name === "NotFoundError";
      toast.warning(
        denied
          ? "🎥 Kamera izni reddedildi"
          : notFound
            ? "🎥 Kamera bulunamadı"
            : "🎥 Kameraya erişilemedi",
        {
          description: denied
            ? "Görüntülü konuşma kapatıldı. Tarayıcı/sistem ayarlarından kamerayı açabilirsin. Sesli sohbet devam ediyor."
            : "Görüntü başlatılamadı. Sesli sohbet devam ediyor.",
          duration: 6000,
        },
      );
      setVideoOn(false);
    }
  }, [videoOn]);

  if (!open) return null;

  const stateLabel: Record<VoiceState, string> = {
    idle: "Hazır",
    listening: "Dinliyorum",
    thinking: "Düşünüyor",
    speaking: "Konuşuyor",
  };

  return (
    <div className="fixed inset-0 z-[10000] flex flex-col bg-background text-foreground">
      {/* Header */}
      <header
        className="flex items-start justify-between px-5"
        style={{ paddingTop: "calc(env(safe-area-inset-top, 0px) + 16px)" }}
      >
        <div>
          <div
            className="text-base font-semibold tracking-[0.32em] text-amber-300"
            style={{ fontFamily: "'Cinzel', serif" }}
          >
            DENG AI
          </div>
          <div className="text-[9px] uppercase tracking-[0.42em] text-amber-200/55">
            Sovereign Intelligence
          </div>
        </div>
        <div className="flex items-center gap-2">
          {onOpenHistory && (
            <button
              type="button"
              onClick={onOpenHistory}
              aria-label="Konuşma geçmişi"
              className="h-10 w-10 rounded-full flex items-center justify-center active:scale-95 border border-border/40 bg-card/40 backdrop-blur-xl text-foreground/80 hover:text-foreground"
            >
              <History className="h-4 w-4" />
            </button>
          )}
          {/* Yazılı moda geç */}
          <button
            type="button"
            onClick={onClose}
            aria-label="Yazılı moda geç"
            className="h-10 px-3 rounded-full flex items-center gap-1.5 active:scale-95 border border-amber-300/30 bg-amber-300/10 backdrop-blur-xl text-amber-200 text-[12px] font-medium"
          >
            <MessageSquare className="h-3.5 w-3.5" />
            Yazılı
          </button>
          <button
            type="button"
            onClick={onClose}
            aria-label="Kapat"
            className="h-10 w-10 rounded-full flex items-center justify-center active:scale-95 border border-border/40 bg-card/40 backdrop-blur-xl text-foreground/80 hover:text-foreground"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      </header>

      {/* Self-view (video) — küçük yuvarlak köşede */}
      {videoOn && (
        <div
          className="absolute right-4 z-10 h-32 w-24 overflow-hidden rounded-2xl border border-amber-300/30 bg-black shadow-xl"
          style={{ top: "calc(env(safe-area-inset-top, 0px) + 80px)" }}
        >
          <video
            ref={videoElRef}
            muted
            playsInline
            className="h-full w-full object-cover"
            style={{ transform: "scaleX(-1)" }}
          />
        </div>
      )}

      {/* Live transcript */}
      <div className="px-6 pt-6 min-h-[80px]">
        {partial && state !== "speaking" && (
          <div className="mx-auto max-w-md rounded-2xl border border-border/40 bg-card/40 px-4 py-3 text-center text-sm text-foreground/80 backdrop-blur-xl">
            {partial}
          </div>
        )}
        {state === "speaking" && lastReply && (
          <div className="mx-auto max-w-md rounded-2xl border border-primary/20 bg-primary/[0.06] px-4 py-3 text-center text-sm text-foreground/90 backdrop-blur-xl">
            {lastReply}
          </div>
        )}
      </div>

      {/* Star */}
      <div className="flex-1 flex items-center justify-center">
        <DengStar state={state} audioEl={audioRef.current} />
      </div>

      {/* Footer — Video · Mic */}
      <footer
        className="flex flex-col items-center gap-4 pb-10"
        style={{ paddingBottom: "calc(env(safe-area-inset-bottom, 0px) + 32px)" }}
      >
        <div className="text-[10px] uppercase tracking-[0.32em] text-muted-foreground">
          {stateLabel[state]}
        </div>
        <div className="flex items-center gap-5">
          {/* Video toggle */}
          <button
            type="button"
            onClick={toggleVideo}
            aria-label="Video"
            className="h-12 w-12 rounded-full flex items-center justify-center active:scale-95 transition-all border border-border/50 bg-card/50 backdrop-blur-xl text-foreground hover:bg-card/70"
            style={
              videoOn
                ? {
                    borderColor: "hsl(var(--primary) / 0.5)",
                    boxShadow: "0 0 0 4px hsl(var(--primary) / 0.12)",
                  }
                : undefined
            }
          >
            {videoOn ? <Video className="h-5 w-5" /> : <VideoOff className="h-5 w-5" />}
          </button>

          {/* Mic */}
          <button
            type="button"
            onClick={() => {
              if (state === "listening") {
                try { recogRef.current?.stop(); } catch {}
                setState("idle");
              } else if (state === "idle") {
                startListening();
              }
            }}
            aria-label="Mikrofon"
            className="h-16 w-16 rounded-full flex items-center justify-center active:scale-95 transition-all border border-border/50 bg-card/50 backdrop-blur-xl text-foreground hover:bg-card/70"
            style={
              state === "listening"
                ? {
                    borderColor: "hsl(var(--primary) / 0.5)",
                    boxShadow: "0 0 0 4px hsl(var(--primary) / 0.12)",
                  }
                : undefined
            }
          >
            {state === "listening" ? <MicOff className="h-6 w-6" /> : <Mic className="h-6 w-6" />}
          </button>
        </div>
      </footer>
    </div>
  );
}

function DengStar({
  state,
  audioEl,
}: {
  state: VoiceState;
  audioEl: HTMLAudioElement | null;
}) {
  const mode: "mic" | "element" | "off" =
    state === "listening" ? "mic" : state === "speaking" ? "element" : "off";
  const { level } = useAudioAmplitude({
    mode,
    enabled: state === "listening" || state === "speaking",
    audioEl,
  });

  const reactive = state === "listening" || state === "speaking";
  const scale = reactive ? 1 + level * 0.22 : 1;
  const bright = reactive ? 1 + level * 0.4 : 1;
  const ringOpacity = 0.25 + level * 0.5;

  const baseAnim =
    state === "thinking"
      ? "deng-star-spin 4s linear infinite"
      : reactive
        ? "none"
        : "deng-star-breathe 3.6s ease-in-out infinite";

  return (
    <div className="relative h-56 w-56 flex items-center justify-center">
      <div
        aria-hidden
        className="absolute inset-0 rounded-full pointer-events-none"
        style={{
          background:
            "radial-gradient(circle, hsl(var(--primary) / 0.28) 0%, transparent 65%)",
          opacity: reactive ? ringOpacity : 0.25,
          transition: "opacity 80ms linear",
          filter: "blur(8px)",
        }}
      />
      {reactive && level > 0.05 && (
        <div
          aria-hidden
          className="absolute inset-6 rounded-full pointer-events-none"
          style={{
            boxShadow: `0 0 0 ${1 + level * 4}px hsl(var(--primary) / ${0.25 + level * 0.4})`,
            transition: "box-shadow 80ms linear",
          }}
        />
      )}
      <div
        className="relative flex items-center justify-center"
        style={{
          animation: baseAnim,
          transform: reactive ? `scale(${scale.toFixed(3)})` : undefined,
          filter: reactive
            ? `brightness(${bright.toFixed(3)}) drop-shadow(0 0 32px rgba(255,30,50,0.55))`
            : "drop-shadow(0 0 22px rgba(255,30,50,0.4))",
          transition: reactive ? "transform 60ms linear, filter 60ms linear" : undefined,
        }}
      >
        <DengSpark3D
          state={state === "thinking" ? "thinking" : state === "speaking" ? "speaking" : "idle"}
          size={160}
          ariaLabel="Deng yıldızı"
        />
      </div>

      <style>{`
        @keyframes deng-star-breathe {
          0%, 100% { transform: scale(1);    filter: drop-shadow(0 0 16px hsl(var(--primary) / 0.35)); }
          50%      { transform: scale(1.06); filter: drop-shadow(0 0 28px hsl(var(--primary) / 0.6)); }
        }
        @keyframes deng-star-spin {
          0%   { transform: rotate(0deg)   scale(1); }
          50%  { transform: rotate(180deg) scale(1.05); }
          100% { transform: rotate(360deg) scale(1); }
        }
      `}</style>
    </div>
  );
}

