/**
 * DiscoveryApp — Interactive 3D introduction to the Jiyan Sovereign Ecosystem.
 *
 * Replaces the legacy landing page on first visit. Three acts:
 *   1) IGNITE — Tap the 21-ray Stêrka Geş in a pitch-black void to "ignite the system".
 *      The star explodes into a galaxy of mini-app icons.
 *   2) TOUR — A horizontal 3D parallax swiper introduces 4 pillar features
 *      (Egemen Kimlik, Sovereign Mail, Sohbet & Sosyal, Oyun & Eğlence).
 *      Final slide is a Golden Portal CTA.
 *   3) PHYSICS PLAY — Tossable mini-app planets with simple velocity + wall bounce.
 *
 * Stack: pure CSS 3D transforms + SVG. No three.js / matter.js — mobile-first.
 * Sound: lightweight Web Audio shimmer on key interactions (gracefully muted).
 *
 * Once completed (or skipped), `sessionStorage` flag prevents replay during
 * the same session; subsequent root visits boot directly into the Hub.
 */
import { useEffect, useRef, useState, useCallback, useMemo } from "react";
import { useNavigate } from "@tanstack/react-router";
import { SovereignStar } from "@/components/keka/SovereignStar";
import { hapticTap } from "@/lib/native";
import {
  MessagesSquare,
  Mail,
  UserCircle2,
  Dices,
  Handshake,
  Crown,
  Wallet,
  Sparkles,
  ArrowRight,
  ChevronRight,
  type LucideIcon,
} from "lucide-react";

const SESSION_KEY = "jiyan_discovery_seen_v1";

interface PlanetSpec {
  id: string;
  Icon: LucideIcon;
  label: string;
}

const PLANETS: PlanetSpec[] = [
  { id: "chat", Icon: MessagesSquare, label: "Sohbet" },
  { id: "mail", Icon: Mail, label: "Mail" },
  { id: "id", Icon: UserCircle2, label: "Kimlik" },
  { id: "games", Icon: Dices, label: "Oyunlar" },
  { id: "miv", Icon: Handshake, label: "Mîvankas" },
  { id: "wallet", Icon: Wallet, label: "Cüzdan" },
  { id: "crown", Icon: Crown, label: "Egemen" },
  { id: "spark", Icon: Sparkles, label: "Keşfet" },
];

type Phase = "ignite" | "tour";

/* ─────────────────────────────  Audio  ───────────────────────────── */

let _audioCtx: AudioContext | null = null;
function getAudioCtx(): AudioContext | null {
  if (typeof window === "undefined") return null;
  try {
    if (!_audioCtx) {
      const Ctx =
        (window as unknown as { AudioContext?: typeof AudioContext }).AudioContext ||
        (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!Ctx) return null;
      _audioCtx = new Ctx();
    }
    return _audioCtx;
  } catch {
    return null;
  }
}
function shimmer(freq = 1320, dur = 0.35, gain = 0.05) {
  const ctx = getAudioCtx();
  if (!ctx) return;
  try {
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = "triangle";
    osc.frequency.setValueAtTime(freq, t);
    osc.frequency.exponentialRampToValueAtTime(freq * 1.8, t + dur);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g).connect(ctx.destination);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  } catch {
    /* ignore */
  }
}

/* ─────────────────────────────  Component  ───────────────────────────── */

export function DiscoveryApp() {
  const navigate = useNavigate();
  const [phase, setPhase] = useState<Phase>("ignite");
  const [exploded, setExploded] = useState(false);
  const [slide, setSlide] = useState(0);
  const trackRef = useRef<HTMLDivElement | null>(null);
  const dragState = useRef<{ x0: number; t0: number; startSlide: number } | null>(null);
  const [dragOffset, setDragOffset] = useState(0);
  const [exiting, setExiting] = useState(false);

  const totalSlides = 5; // 4 features + portal

  const finishDiscovery = useCallback(
    (target: string) => {
      try {
        sessionStorage.setItem(SESSION_KEY, "1");
      } catch {
        /* ignore */
      }
      hapticTap();
      shimmer(1760, 0.55, 0.07);
      setExiting(true);
      window.setTimeout(() => {
        navigate({ to: target });
      }, 520);
    },
    [navigate],
  );

  /* IGNITE → TOUR */
  const ignite = useCallback(() => {
    if (exploded) return;
    hapticTap();
    shimmer(880, 0.6, 0.08);
    setExploded(true);
    window.setTimeout(() => {
      shimmer(1320, 0.4, 0.06);
      setPhase("tour");
    }, 950);
  }, [exploded]);

  /* Swipe handlers */
  const onPointerDown = (e: React.PointerEvent) => {
    if (phase !== "tour") return;
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    dragState.current = { x0: e.clientX, t0: performance.now(), startSlide: slide };
  };
  const onPointerMove = (e: React.PointerEvent) => {
    if (!dragState.current) return;
    setDragOffset(e.clientX - dragState.current.x0);
  };
  const onPointerUp = (e: React.PointerEvent) => {
    if (!dragState.current) return;
    const dx = e.clientX - dragState.current.x0;
    const dt = performance.now() - dragState.current.t0;
    const velocity = dx / Math.max(dt, 1);
    const width = trackRef.current?.clientWidth ?? 360;
    let next = dragState.current.startSlide;
    if (Math.abs(dx) > width * 0.18 || Math.abs(velocity) > 0.5) {
      next = dx < 0 ? Math.min(totalSlides - 1, next + 1) : Math.max(0, next - 1);
    }
    if (next !== slide) {
      hapticTap();
      shimmer(1100 + next * 120, 0.18, 0.04);
    }
    dragState.current = null;
    setDragOffset(0);
    setSlide(next);
  };

  /* Skip discovery on session repeat (defensive — root also gates this) */
  useEffect(() => {
    try {
      if (sessionStorage.getItem(SESSION_KEY)) {
        navigate({ to: "/hub" });
      }
    } catch {
      /* ignore */
    }
  }, [navigate]);

  return (
    <div
      className="fixed inset-0 overflow-hidden text-white select-none"
      style={{
        background:
          "radial-gradient(140% 100% at 50% 40%, #0a0700 0%, #050300 60%, #000 100%)",
        opacity: exiting ? 0 : 1,
        transform: exiting ? "scale(1.06)" : "scale(1)",
        transition: "opacity 480ms ease, transform 480ms cubic-bezier(0.22,1,0.36,1)",
        fontFamily:
          "ui-sans-serif, system-ui, -apple-system, 'SF Pro Display', 'Inter', sans-serif",
      }}
    >
      {/* Ambient gold dust */}
      <StarField />

      {/* Skip pill */}
      {phase === "tour" && !exiting && (
        <button
          onClick={() => finishDiscovery("/hub")}
          className="absolute top-5 right-5 z-40 px-3 py-1.5 rounded-full text-[11px] uppercase tracking-[0.25em]"
          style={{
            color: "rgba(245,222,179,0.75)",
            background: "rgba(255,255,255,0.04)",
            backdropFilter: "blur(12px)",
            WebkitBackdropFilter: "blur(12px)",
            border: "1px solid rgba(212,175,55,0.25)",
          }}
        >
          Atla
        </button>
      )}

      {/* ACT 1 — Ignite */}
      {phase === "ignite" && (
        <IgniteAct exploded={exploded} onIgnite={ignite} />
      )}

      {/* ACT 2 — Tour */}
      {phase === "tour" && (
        <div
          ref={trackRef}
          className="absolute inset-0 flex items-center justify-center"
          style={{ perspective: "1400px" }}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onPointerCancel={onPointerUp}
        >
          <SwiperTrack
            slide={slide}
            dragOffset={dragOffset}
            totalSlides={totalSlides}
            onCTA={() => finishDiscovery("/hub")}
            onGuest={() => finishDiscovery("/hub")}
          />

          {/* Dots */}
          <div className="absolute bottom-6 left-0 right-0 flex justify-center gap-2 z-30">
            {Array.from({ length: totalSlides }).map((_, i) => (
              <button
                key={i}
                onClick={() => {
                  hapticTap();
                  setSlide(i);
                }}
                className="rounded-full transition-all"
                style={{
                  width: i === slide ? 22 : 6,
                  height: 6,
                  background:
                    i === slide
                      ? "linear-gradient(90deg,#FFE89A,#D4AF37)"
                      : "rgba(245,222,179,0.25)",
                  boxShadow:
                    i === slide ? "0 0 10px rgba(212,175,55,0.55)" : "none",
                }}
                aria-label={`Slide ${i + 1}`}
              />
            ))}
          </div>

          {/* Side hint chevrons (hidden on last slide) */}
          {slide < totalSlides - 1 && (
            <div
              className="absolute right-3 top-1/2 -translate-y-1/2 z-30 opacity-50 pointer-events-none animate-pulse"
              style={{ color: "#D4AF37" }}
            >
              <ChevronRight size={28} />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ─────────────────────────────  ACT 1  ───────────────────────────── */

function IgniteAct({ exploded, onIgnite }: { exploded: boolean; onIgnite: () => void }) {
  return (
    <div className="absolute inset-0 flex flex-col items-center justify-center">
      {/* Halo */}
      <div
        className="absolute"
        style={{
          width: 420,
          height: 420,
          borderRadius: "50%",
          background:
            "radial-gradient(circle, rgba(212,175,55,0.30) 0%, rgba(212,175,55,0.06) 50%, transparent 75%)",
          filter: "blur(10px)",
          animation: "discovery-halo 2.6s ease-in-out infinite",
          opacity: exploded ? 0 : 1,
          transition: "opacity 600ms ease",
        }}
      />

      {/* Tappable star */}
      <button
        onClick={onIgnite}
        aria-label="Sistemi Ateşle"
        className="relative z-10"
        style={{
          background: "transparent",
          border: 0,
          cursor: "pointer",
          transform: exploded ? "scale(2.2)" : "scale(1)",
          opacity: exploded ? 0 : 1,
          transition:
            "transform 900ms cubic-bezier(0.22,1,0.36,1), opacity 900ms ease",
          animation: exploded ? "none" : "discovery-pulse 2.4s ease-in-out infinite",
        }}
      >
        <SovereignStar size={156} glow />
      </button>

      {/* Wordmark */}
      <div
        className="mt-10 text-center"
        style={{
          opacity: exploded ? 0 : 1,
          transform: exploded ? "translateY(18px)" : "translateY(0)",
          transition: "opacity 500ms ease, transform 600ms ease",
        }}
      >
        <div
          className="text-[11px] uppercase font-semibold mb-2"
          style={{
            letterSpacing: "0.55em",
            color: "#D4AF37",
            textShadow: "0 0 14px rgba(212,175,55,0.45)",
          }}
        >
          Stêrka Geş
        </div>
        <div
          className="text-sm"
          style={{
            color: "rgba(245,222,179,0.75)",
            letterSpacing: "0.18em",
          }}
        >
          Sistemi ateşlemek için yıldıza dokun
        </div>
      </div>

      {/* Galaxy explosion of icons */}
      {exploded && <GalaxyBurst />}

      <style>{`
        @keyframes discovery-halo {
          0%,100% { opacity: 0.55; transform: scale(1); }
          50% { opacity: 0.95; transform: scale(1.1); }
        }
        @keyframes discovery-pulse {
          0%,100% { transform: scale(1); filter: drop-shadow(0 0 22px rgba(212,175,55,0.55)); }
          50% { transform: scale(1.06); filter: drop-shadow(0 0 36px rgba(255,215,90,0.85)); }
        }
        @keyframes discovery-burst {
          0% { transform: translate(0,0) scale(0.2); opacity: 0; }
          15% { opacity: 1; }
          100% { transform: translate(var(--tx), var(--ty)) scale(1); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

function GalaxyBurst() {
  // Random radial scatter of glyphs (deterministic per render)
  const seeds = useMemo(
    () =>
      PLANETS.flatMap((p, i) =>
        Array.from({ length: 4 }).map((_, j) => {
          const angle = ((i * 4 + j) / (PLANETS.length * 4)) * Math.PI * 2;
          const radius = 160 + ((i + j) % 4) * 40;
          return {
            key: `${p.id}-${j}`,
            Icon: p.Icon,
            tx: Math.cos(angle) * radius,
            ty: Math.sin(angle) * radius,
            delay: (i * 30 + j * 70) % 400,
          };
        }),
      ),
    [],
  );
  return (
    <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
      {seeds.map(({ key, Icon, tx, ty, delay }) => (
        <div
          key={key}
          className="absolute"
          style={
            {
              "--tx": `${tx}px`,
              "--ty": `${ty}px`,
              animation: `discovery-burst 900ms cubic-bezier(0.22,1,0.36,1) ${delay}ms forwards`,
              color: "#FFD24A",
              filter: "drop-shadow(0 0 8px rgba(255,210,74,0.7))",
            } as React.CSSProperties
          }
        >
          <Icon size={22} />
        </div>
      ))}
    </div>
  );
}

/* ─────────────────────────────  ACT 2 — Swiper  ───────────────────────────── */

function SwiperTrack({
  slide,
  dragOffset,
  totalSlides,
  onCTA,
  onGuest,
}: {
  slide: number;
  dragOffset: number;
  totalSlides: number;
  onCTA: () => void;
  onGuest: () => void;
}) {
  return (
    <div
      className="relative w-full h-full"
      style={{ transformStyle: "preserve-3d" }}
    >
      {Array.from({ length: totalSlides }).map((_, i) => {
        const delta = i - slide;
        const w = typeof window !== "undefined" ? window.innerWidth : 400;
        const x = delta * w + dragOffset;
        const absDelta = Math.abs(delta - dragOffset / w);
        const rotY = Math.max(-35, Math.min(35, -delta * 22 + (dragOffset / w) * 22));
        const scale = 1 - Math.min(0.18, absDelta * 0.18);
        const opacity = 1 - Math.min(0.7, absDelta * 0.7);
        return (
          <div
            key={i}
            className="absolute inset-0 flex items-center justify-center px-6"
            style={{
              transform: `translate3d(${x}px,0,0) rotateY(${rotY}deg) scale(${scale})`,
              opacity,
              transition: dragOffset === 0 ? "transform 520ms cubic-bezier(0.22,1,0.36,1), opacity 520ms ease" : "none",
              transformStyle: "preserve-3d",
              willChange: "transform, opacity",
            }}
          >
            <SlideContent index={i} onCTA={onCTA} onGuest={onGuest} />
          </div>
        );
      })}
    </div>
  );
}

function SlideContent({
  index,
  onCTA,
  onGuest,
}: {
  index: number;
  onCTA: () => void;
  onGuest: () => void;
}) {
  if (index === 0) return <SlideIdentity />;
  if (index === 1) return <SlideMail />;
  if (index === 2) return <SlideChat />;
  if (index === 3) return <SlideGames />;
  return <SlidePortal onCTA={onCTA} onGuest={onGuest} />;
}

/* ─── Glass card shell ─── */
function GlassCard({
  eyebrow,
  title,
  subtitle,
  children,
}: {
  eyebrow: string;
  title: string;
  subtitle: string;
  children: React.ReactNode;
}) {
  return (
    <div
      className="w-full max-w-[360px] flex flex-col items-center text-center"
      style={{ transformStyle: "preserve-3d" }}
    >
      <div
        className="relative w-full rounded-[28px] p-6 pt-8"
        style={{
          background:
            "linear-gradient(160deg, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.02) 60%, rgba(212,175,55,0.04) 100%)",
          border: "1px solid rgba(212,175,55,0.28)",
          boxShadow:
            "0 30px 80px -20px rgba(0,0,0,0.85), 0 0 60px -20px rgba(212,175,55,0.35), inset 0 1px 0 rgba(255,255,255,0.06)",
          backdropFilter: "blur(16px)",
          WebkitBackdropFilter: "blur(16px)",
        }}
      >
        <div className="flex justify-center mb-5" style={{ minHeight: 180 }}>
          {children}
        </div>
        <div
          className="text-[10px] uppercase font-semibold mb-2"
          style={{ letterSpacing: "0.4em", color: "#D4AF37" }}
        >
          {eyebrow}
        </div>
        <h2
          className="text-[22px] font-semibold mb-2"
          style={{
            color: "#FFF8D6",
            letterSpacing: "-0.01em",
            textShadow: "0 2px 18px rgba(212,175,55,0.25)",
          }}
        >
          {title}
        </h2>
        <p
          className="text-[13px] leading-relaxed"
          style={{ color: "rgba(245,222,179,0.65)" }}
        >
          {subtitle}
        </p>
      </div>
    </div>
  );
}

/* ─── Slide 1: Identity (rotating ID card) ─── */
function SlideIdentity() {
  return (
    <GlassCard
      eyebrow="Egemen Kimlik"
      title="+777 — Kimliğin sende"
      subtitle="Tek dokunuşla doğrulanan, devletten bağımsız Sovereign ID. Numaran, mührün, özgürlüğün."
    >
      <div
        className="relative"
        style={{
          width: 220,
          height: 140,
          transformStyle: "preserve-3d",
          animation: "id-spin 7s linear infinite",
        }}
      >
        <div
          className="absolute inset-0 rounded-2xl flex flex-col justify-between p-4"
          style={{
            background:
              "linear-gradient(135deg, #1a1206 0%, #060300 60%, #1a1206 100%)",
            border: "1.5px solid #D4AF37",
            boxShadow:
              "0 0 40px rgba(212,175,55,0.45), inset 0 1px 0 rgba(255,232,154,0.25)",
            backfaceVisibility: "hidden",
          }}
        >
          <div className="flex items-start justify-between">
            <div>
              <div
                className="text-[8px] uppercase"
                style={{ letterSpacing: "0.3em", color: "#D4AF37" }}
              >
                Sovereign ID
              </div>
              <div className="text-[16px] font-bold mt-1" style={{ color: "#FFF8D6" }}>
                +777 4218 9034
              </div>
            </div>
            <SovereignStar size={28} glow />
          </div>
          <div className="flex items-end justify-between">
            <div>
              <div className="text-[7px] uppercase" style={{ color: "rgba(245,222,179,0.5)", letterSpacing: "0.25em" }}>
                Holder
              </div>
              <div className="text-[11px] font-semibold" style={{ color: "#FFE89A" }}>
                JIYAN CITIZEN
              </div>
            </div>
            <div
              className="text-[8px] font-mono"
              style={{ color: "rgba(245,222,179,0.55)" }}
            >
              ∞ VALID
            </div>
          </div>
        </div>
      </div>
      <style>{`
        @keyframes id-spin {
          0% { transform: rotateY(0deg); }
          100% { transform: rotateY(360deg); }
        }
      `}</style>
    </GlassCard>
  );
}

/* ─── Slide 2: Mail (envelopes flying into a golden box) ─── */
function SlideMail() {
  return (
    <GlassCard
      eyebrow="Sovereign Mail"
      title="Cam zarflar, altın kasa"
      subtitle="Uçtan uca şifreli, reklamsız, sadece sana ait posta sistemi. Kasa altın, mesaj ipek."
    >
      <div className="relative" style={{ width: 220, height: 180 }}>
        {/* Golden box */}
        <div
          className="absolute left-1/2 -translate-x-1/2 bottom-0"
          style={{
            width: 110,
            height: 70,
            borderRadius: 12,
            background:
              "linear-gradient(180deg, #FFE89A 0%, #D4AF37 50%, #8C6011 100%)",
            boxShadow:
              "0 12px 40px rgba(212,175,55,0.55), inset 0 1px 0 rgba(255,255,255,0.45)",
          }}
        >
          <div
            className="absolute left-1/2 -translate-x-1/2 top-2 w-[60%] h-2 rounded-full"
            style={{ background: "rgba(0,0,0,0.35)" }}
          />
        </div>
        {/* Glass envelopes */}
        {[0, 1, 2].map((i) => (
          <div
            key={i}
            className="absolute left-1/2"
            style={{
              width: 44,
              height: 30,
              top: 0,
              marginLeft: -22 + (i - 1) * 50,
              borderRadius: 4,
              background:
                "linear-gradient(180deg, rgba(255,255,255,0.18), rgba(255,255,255,0.04))",
              border: "1px solid rgba(212,175,55,0.55)",
              boxShadow: "0 0 18px rgba(212,175,55,0.4)",
              backdropFilter: "blur(6px)",
              animation: `mail-fly 3.2s ease-in-out ${i * 0.4}s infinite`,
            }}
          >
            <div
              className="absolute inset-0"
              style={{
                background:
                  "linear-gradient(135deg, transparent 49%, rgba(212,175,55,0.55) 50%, transparent 51%)",
              }}
            />
          </div>
        ))}
      </div>
      <style>{`
        @keyframes mail-fly {
          0% { transform: translateY(0) rotate(-6deg); opacity: 0.95; }
          70% { transform: translateY(110px) rotate(2deg); opacity: 1; }
          85% { transform: translateY(118px) rotate(0deg); opacity: 0; }
          100% { transform: translateY(0) rotate(-6deg); opacity: 0; }
        }
      `}</style>
    </GlassCard>
  );
}

/* ─── Slide 3: Chat bubbles ─── */
function SlideChat() {
  return (
    <GlassCard
      eyebrow="Sohbet & Sosyal"
      title="Karanlıkta parlayan diyalog"
      subtitle="Gruplar, kanallar, sesli odalar ve etkinlikler — tek bir egemen sosyal katmanda buluşuyor."
    >
      <div className="relative w-full" style={{ height: 180 }}>
        {[
          { x: 20, y: 10, w: 140, txt: "Sılav, biraderê min" },
          { x: 70, y: 70, w: 110, txt: "Şev baş 🌙" },
          { x: 30, y: 130, w: 150, txt: "Oda 101'de görüşürüz" },
        ].map((b, i) => (
          <div
            key={i}
            className="absolute px-3 py-2 rounded-2xl text-[11px]"
            style={{
              left: b.x,
              top: b.y,
              width: b.w,
              color: "#FFF8D6",
              background:
                "linear-gradient(135deg, rgba(212,175,55,0.22), rgba(0,0,0,0.65))",
              border: "1px solid rgba(212,175,55,0.4)",
              boxShadow:
                "0 8px 24px rgba(0,0,0,0.6), 0 0 16px rgba(212,175,55,0.35)",
              backdropFilter: "blur(8px)",
              animation: `bubble-glow 2.6s ease-in-out ${i * 0.4}s infinite`,
            }}
          >
            {b.txt}
          </div>
        ))}
      </div>
      <style>{`
        @keyframes bubble-glow {
          0%,100% { box-shadow: 0 8px 24px rgba(0,0,0,0.6), 0 0 12px rgba(212,175,55,0.25); }
          50% { box-shadow: 0 8px 24px rgba(0,0,0,0.6), 0 0 28px rgba(255,210,74,0.55); }
        }
      `}</style>
    </GlassCard>
  );
}

/* ─── Slide 4: Games (gold dice) ─── */
function SlideGames() {
  return (
    <GlassCard
      eyebrow="Oyun & Eğlence"
      title="Altın kabartmalı zarlar"
