/* ─────────────────────────────  Physics  ───────────────────────────── */

interface Body {
  id: string;
  Icon: LucideIcon;
  label: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
}

function PhysicsPlayground() {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [bodies, setBodies] = useState<Body[]>([]);
  const draggingRef = useRef<{ id: string; pointerId: number; lastX: number; lastY: number; lastT: number } | null>(null);
  const rafRef = useRef<number | null>(null);

  // Initialize bodies once container is measured
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const w = el.clientWidth;
    const h = el.clientHeight;
    const r = 26;
    setBodies(
      PLANETS.slice(0, 6).map((p, i) => {
        const angle = (i / 6) * Math.PI * 2;
        const cx = w / 2 + Math.cos(angle) * (w * 0.28);
        const cy = h / 2 + Math.sin(angle) * (h * 0.32);
        return {
          id: p.id,
          Icon: p.Icon,
          label: p.label,
          x: cx,
          y: cy,
          vx: (Math.random() - 0.5) * 0.4,
          vy: (Math.random() - 0.5) * 0.4,
          r,
        };
      }),
    );
  }, []);

  // Physics tick
  useEffect(() => {
    const tick = () => {
      const el = containerRef.current;
      if (!el) {
        rafRef.current = requestAnimationFrame(tick);
        return;
      }
      const w = el.clientWidth;
      const h = el.clientHeight;
      setBodies((prev) =>
        prev.map((b) => {
          if (draggingRef.current?.id === b.id) return b;
          let { x, y, vx, vy } = b;
          x += vx;
          y += vy;
          // Wall bounce
          if (x < b.r) { x = b.r; vx = -vx * 0.7; }
          if (x > w - b.r) { x = w - b.r; vx = -vx * 0.7; }
          if (y < b.r) { y = b.r; vy = -vy * 0.7; }
          if (y > h - b.r) { y = h - b.r; vy = -vy * 0.7; }
          // Friction
          vx *= 0.985;
          vy *= 0.985;
          return { ...b, x, y, vx, vy };
        }),
      );
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const onPointerDown = (e: React.PointerEvent, id: string) => {
    e.stopPropagation();
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    draggingRef.current = {
      id,
      pointerId: e.pointerId,
      lastX: e.clientX,
      lastY: e.clientY,
      lastT: performance.now(),
    };
    hapticTap();
    shimmer(1480, 0.18, 0.04);
  };
  const onPointerMove = (e: React.PointerEvent) => {
    const d = draggingRef.current;
    if (!d || d.pointerId !== e.pointerId) return;
    e.stopPropagation();
    const dx = e.clientX - d.lastX;
    const dy = e.clientY - d.lastY;
    const now = performance.now();
    const dt = Math.max(now - d.lastT, 1);
    setBodies((prev) =>
      prev.map((b) =>
        b.id === d.id
          ? {
              ...b,
              x: b.x + dx,
              y: b.y + dy,
              vx: dx / dt * 16,
              vy: dy / dt * 16,
            }
          : b,
      ),
    );
    d.lastX = e.clientX;
    d.lastY = e.clientY;
    d.lastT = now;
  };
  const onPointerUp = (e: React.PointerEvent) => {
    if (draggingRef.current?.pointerId === e.pointerId) {
      draggingRef.current = null;
      shimmer(2100, 0.22, 0.05);
    }
  };

  return (
    <div
      ref={containerRef}
      className="relative w-full mb-6 rounded-3xl overflow-hidden"
      style={{
        height: 280,
        background:
          "radial-gradient(circle at 50% 50%, rgba(212,175,55,0.18) 0%, rgba(0,0,0,0.7) 60%, #000 100%)",
        border: "1px solid rgba(212,175,55,0.3)",
        boxShadow:
          "inset 0 0 60px rgba(212,175,55,0.2), 0 20px 60px rgba(0,0,0,0.7)",
      }}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
    >
      {/* Portal ring */}
      <div
        className="absolute left-1/2 top-1/2 rounded-full pointer-events-none"
        style={{
          width: 110,
          height: 110,
          marginLeft: -55,
          marginTop: -55,
          border: "2px solid #D4AF37",
          boxShadow:
            "0 0 60px rgba(212,175,55,0.55), inset 0 0 40px rgba(212,175,55,0.45)",
          animation: "portal-spin 8s linear infinite",
        }}
      />
      <div
        className="absolute left-1/2 top-1/2 pointer-events-none"
        style={{ marginLeft: -28, marginTop: -28 }}
      >
        <SovereignStar size={56} glow />
      </div>

      {/* Hint */}
      <div
        className="absolute top-3 left-0 right-0 text-center text-[10px] uppercase pointer-events-none"
        style={{ color: "rgba(245,222,179,0.65)", letterSpacing: "0.3em" }}
      >
        Sürükle • Fırlat
      </div>

      {/* Bodies */}
      {bodies.map((b) => (
        <button
          key={b.id}
          onPointerDown={(e) => onPointerDown(e, b.id)}
          className="absolute flex items-center justify-center rounded-full touch-none"
          style={{
            width: b.r * 2,
            height: b.r * 2,
            left: b.x - b.r,
            top: b.y - b.r,
            background:
              "radial-gradient(120% 100% at 0% 0%, rgba(212,175,55,0.32) 0%, rgba(120,90,20,0.18) 28%, rgba(8,6,2,0.96) 70%, #050300 100%)",
            border: "1px solid rgba(212,175,55,0.55)",
            boxShadow:
              "0 8px 22px rgba(0,0,0,0.7), 0 0 18px rgba(212,175,55,0.35), inset 0 1px 0 rgba(255,232,154,0.2)",
            color: "#FFE89A",
            cursor: "grab",
          }}
          aria-label={b.label}
        >
          <b.Icon size={22} />
        </button>
      ))}

      <style>{`
        @keyframes portal-spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
}

