import { useState, useRef, useEffect } from "react";
import { Play, Pause, RotateCcw, Volume2, VolumeX, Maximize2, Video } from "lucide-react";

interface VideoQuestionPlayerProps {
  videoUrl: string;
  category?: string;
  onVideoEnd?: () => void;
  autoPlay?: boolean;
}

export function VideoQuestionPlayer({ videoUrl, category, onVideoEnd, autoPlay = true }: VideoQuestionPlayerProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(true);
  const [progress, setProgress] = useState(0);
  const [showReplay, setShowReplay] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handlePlay = () => setIsPlaying(true);
    const handlePause = () => setIsPlaying(false);
    const handleEnded = () => {
      setIsPlaying(false);
      setShowReplay(true);
      onVideoEnd?.();
    };
    const handleTimeUpdate = () => {
      if (video.duration) {
        setProgress((video.currentTime / video.duration) * 100);
      }
    };
    const handleCanPlay = () => {
      setIsLoading(false);
      if (autoPlay) video.play().catch(() => {});
    };

    video.addEventListener("play", handlePlay);
    video.addEventListener("pause", handlePause);
    video.addEventListener("ended", handleEnded);
    video.addEventListener("timeupdate", handleTimeUpdate);
    video.addEventListener("canplay", handleCanPlay);

    return () => {
      video.removeEventListener("play", handlePlay);
      video.removeEventListener("pause", handlePause);
      video.removeEventListener("ended", handleEnded);
      video.removeEventListener("timeupdate", handleTimeUpdate);
      video.removeEventListener("canplay", handleCanPlay);
    };
  }, [videoUrl, autoPlay, onVideoEnd]);

  const togglePlay = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) video.play();
    else video.pause();
  };

  const replay = () => {
    const video = videoRef.current;
    if (!video) return;
    video.currentTime = 0;
    setShowReplay(false);
    video.play();
  };

  const toggleMute = () => {
    const video = videoRef.current;
    if (!video) return;
    video.muted = !video.muted;
    setIsMuted(video.muted);
  };

  const toggleFullscreen = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.requestFullscreen) video.requestFullscreen();
  };

  const categoryColors: Record<string, string> = {
    priority: "from-red-500/20 to-red-900/40",
    signs: "from-blue-500/20 to-blue-900/40",
    speed: "from-orange-500/20 to-orange-900/40",
    parking: "from-cyan-500/20 to-cyan-900/40",
    hazard: "from-yellow-500/20 to-yellow-900/40",
    rules: "from-green-500/20 to-green-900/40",
  };

  return (
    <div className="relative w-full bg-background overflow-hidden">
      {/* Video badge */}
      <div className="absolute top-2 left-2 z-20 flex items-center gap-1.5 rounded-full bg-destructive/90 px-2.5 py-1 backdrop-blur-sm">
        <Video className="h-3 w-3 text-white" />
        <span className="text-[10px] font-bold text-white uppercase tracking-wider">VİDEO SORU</span>
      </div>

      {/* Loading state */}
      {isLoading && (
        <div className="absolute inset-0 z-10 flex items-center justify-center bg-background">
          <div className="flex flex-col items-center gap-2">
            <div className="h-8 w-8 animate-spin rounded-full border-2 border-neon border-t-transparent" />
            <span className="text-xs text-muted-foreground">Video yükleniyor...</span>
          </div>
        </div>
      )}

      {/* Video element */}
      <video
        ref={videoRef}
        src={videoUrl}
        muted={isMuted}
        playsInline
        preload="auto"
        className="w-full h-56 object-cover"
        onError={(e) => { (e.target as HTMLVideoElement).style.display = "none"; }}
      />

      {/* Gradient overlay */}
      <div className={`absolute inset-0 bg-gradient-to-t ${categoryColors[category || ""] || "from-background/60 to-transparent"} pointer-events-none`} />

      {/* Replay overlay */}
      {showReplay && (
        <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/70">
          <button
            onClick={replay}
            className="flex flex-col items-center gap-2 rounded-2xl bg-neon/20 p-5 backdrop-blur-sm transition-transform active:scale-95"
          >
            <RotateCcw className="h-8 w-8 text-neon" />
            <span className="text-xs font-bold text-neon">Tekrar İzle</span>
          </button>
        </div>
      )}

      {/* Controls bar */}
      <div className="absolute bottom-0 left-0 right-0 z-20">
        {/* Progress bar */}
        <div className="h-1 w-full bg-muted/30">
          <div
            className="h-full bg-neon transition-all duration-150"
            style={{ width: `${progress}%` }}
          />
        </div>

        {/* Control buttons */}
        <div className="flex items-center justify-between px-3 py-2 bg-gradient-to-t from-background/90 to-transparent">
          <button
            onClick={togglePlay}
            className="flex h-8 w-8 items-center justify-center rounded-full bg-neon/20 text-neon transition-colors hover:bg-neon/30"
          >
            {isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4 ml-0.5" />}
          </button>

          <div className="flex items-center gap-2">
            <button
              onClick={toggleMute}
              className="flex h-7 w-7 items-center justify-center rounded-full text-muted-foreground hover:text-foreground transition-colors"
            >
              {isMuted ? <VolumeX className="h-3.5 w-3.5" /> : <Volume2 className="h-3.5 w-3.5" />}
            </button>
            <button
              onClick={toggleFullscreen}
              className="flex h-7 w-7 items-center justify-center rounded-full text-muted-foreground hover:text-foreground transition-colors"
            >
              <Maximize2 className="h-3.5 w-3.5" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

