import { useState, useMemo } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import type { Event } from "@/hooks/useEvents";

interface Props {
  events: Event[];
  onSelectDate: (date: Date) => void;
  selectedDate: Date | null;
}

export function EventCalendarView({ events, onSelectDate, selectedDate }: Props) {
  const [currentMonth, setCurrentMonth] = useState(new Date());

  const year = currentMonth.getFullYear();
  const month = currentMonth.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfWeek = new Date(year, month, 1).getDay();
  const startOffset = firstDayOfWeek === 0 ? 6 : firstDayOfWeek - 1; // Monday start

  const eventsByDay = useMemo(() => {
    const map = new Map<string, Event[]>();
    events.forEach((e) => {
      const d = new Date(e.starts_at);
      if (d.getMonth() === month && d.getFullYear() === year) {
        const key = d.getDate().toString();
        const existing = map.get(key) || [];
        existing.push(e);
        map.set(key, existing);
      }
    });
    return map;
  }, [events, month, year]);

  const today = new Date();
  const isToday = (day: number) =>
    today.getDate() === day && today.getMonth() === month && today.getFullYear() === year;

  const isSelected = (day: number) =>
    selectedDate?.getDate() === day &&
    selectedDate?.getMonth() === month &&
    selectedDate?.getFullYear() === year;

  const monthName = currentMonth.toLocaleString("tr-TR", { month: "long", year: "numeric" });
  const weekDays = ["Pzt", "Sal", "Çar", "Per", "Cum", "Cmt", "Paz"];

  const prevMonth = () => setCurrentMonth(new Date(year, month - 1, 1));
  const nextMonth = () => setCurrentMonth(new Date(year, month + 1, 1));

  const cells = [];
  for (let i = 0; i < startOffset; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  return (
    <div className="rounded-2xl border border-border bg-surface p-4">
      {/* Month navigation */}
      <div className="flex items-center justify-between mb-4">
        <button onClick={prevMonth} className="p-1.5 rounded-lg hover:bg-accent transition-colors">
          <ChevronLeft className="h-4 w-4 text-muted-foreground" />
        </button>
        <h3 className="text-sm font-semibold text-foreground capitalize">{monthName}</h3>
        <button onClick={nextMonth} className="p-1.5 rounded-lg hover:bg-accent transition-colors">
          <ChevronRight className="h-4 w-4 text-muted-foreground" />
        </button>
      </div>

      {/* Weekday headers */}
      <div className="grid grid-cols-7 gap-1 mb-2">
        {weekDays.map((d) => (
          <div key={d} className="text-center text-[10px] font-medium text-muted-foreground py-1">
            {d}
          </div>
        ))}
      </div>

      {/* Day grid */}
      <div className="grid grid-cols-7 gap-1">
        {cells.map((day, i) => {
          if (day === null) return <div key={`empty-${i}`} />;
          const dayEvents = eventsByDay.get(day.toString());
          const hasEvents = !!dayEvents && dayEvents.length > 0;

          return (
            <button
              key={day}
              onClick={() => onSelectDate(new Date(year, month, day))}
              className={`relative flex flex-col items-center justify-center rounded-lg py-2 text-xs transition-all ${
                isSelected(day)
                  ? "bg-neon text-neon-foreground font-bold"
                  : isToday(day)
                    ? "bg-neon/15 text-neon font-semibold"
                    : hasEvents
                      ? "text-foreground hover:bg-accent font-medium"
                      : "text-muted-foreground hover:bg-accent/50"
              }`}
            >
              {day}
              {hasEvents && (
                <div className="flex gap-0.5 mt-0.5">
                  {dayEvents!.slice(0, 3).map((_, idx) => (
                    <span
                      key={idx}
                      className={`h-1 w-1 rounded-full ${
                        isSelected(day) ? "bg-neon-foreground" : "bg-neon"
                      }`}
                    />
                  ))}
                </div>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}

