import { useEffect, useRef, useState } from "react";
import { Trophy, Star, Sparkles } from "lucide-react";
import { useUserXP } from "@/hooks/useGamification";
import { playChime } from "@/lib/systemSounds";

/**
 * useTweenedNumber — Smoothly animates a numeric value toward `target`
 * over `duration` ms using easeOutCubic. Returns the current display value.
 */
function useTweenedNumber(target: number, duration = 700): number {
  const [value, setValue] = useState(target);
  const fromRef = useRef(target);
  const startRef = useRef<number | null>(null);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    if (target === value) return;
    fromRef.current = value;
    startRef.current = null;
    if (rafRef.current != null) cancelAnimationFrame(rafRef.current);

    const tick = (ts: number) => {
      if (startRef.current == null) startRef.current = ts;
      const elapsed = ts - startRef.current;
      const t = Math.min(1, elapsed / duration);
      const eased = 1 - Math.pow(1 - t, 3);
      const v = fromRef.current + (target - fromRef.current) * eased;
      setValue(v);
      if (t < 1) rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => {
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, duration]);

  return value;
}

export function XPBar({ compact = false }: { compact?: boolean }) {
  const { xp, loading } = useUserXP();

  // Track level-ups: when level increases, fire a celebration burst.
  const prevLevelRef = useRef<number | null>(null);
  const [celebrate, setCelebrate] = useState(false);
  useEffect(() => {
    if (!xp) return;
    if (prevLevelRef.current != null && xp.level > prevLevelRef.current) {
      setCelebrate(true);
      try { playChime(); } catch {}
      const t = setTimeout(() => setCelebrate(false), 1600);
      prevLevelRef.current = xp.level;
      return () => clearTimeout(t);
    }
    prevLevelRef.current = xp.level;
  }, [xp]);

  // Tweened values — must be called unconditionally to keep hook order stable.
  const targetPct = xp ? Math.min(100, (xp.current_level_xp / xp.next_level_xp) * 100) : 0;
  const tweenPct = useTweenedNumber(targetPct, 800);
  const tweenTotal = useTweenedNumber(xp?.total_xp ?? 0, 600);
  const tweenCurrent = useTweenedNumber(xp?.current_level_xp ?? 0, 600);

  if (loading || !xp) return null;

  if (compact) {
    return (
      <div className="flex items-center gap-2 text-xs">
        <div
          className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-gradient-to-r from-neon/20 to-gold/20 border border-neon/30"
          style={celebrate ? { animation: "xp-level-pop 800ms ease-out" } : undefined}
        >
          <Star className="h-3 w-3 text-gold fill-gold" />
          <span className="font-bold text-foreground">Lv {xp.level}</span>
        </div>
        <div className="relative flex-1 h-1.5 rounded-full bg-muted overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-neon to-gold"
            style={{ width: `${tweenPct}%`, transition: "none" }}
          />
          {/* Shimmer sweep */}
          <div
            aria-hidden
            className="absolute inset-y-0 w-1/3 pointer-events-none"
            style={{
              background:
                "linear-gradient(90deg, transparent, rgba(255,255,255,0.55), transparent)",
              animation: "xp-shimmer 2.4s linear infinite",
              mixBlendMode: "overlay",
            }}
          />
        </div>
      </div>
    );
  }

  return (
    <div className="relative rounded-2xl border border-border bg-surface/40 p-4 backdrop-blur-sm overflow-hidden">
      {/* Level-up celebration burst */}
      {celebrate && (
        <>
          <div
            aria-hidden
            className="absolute inset-0 pointer-events-none"
            style={{
              background:
                "radial-gradient(60% 50% at 30% 50%, rgba(245,205,83,0.45), transparent 70%)",
              animation: "xp-burst 1500ms ease-out forwards",
            }}
          />
          {Array.from({ length: 8 }).map((_, i) => (
            <Sparkles
              key={i}
              aria-hidden
              className="absolute h-3 w-3 text-gold pointer-events-none"
              style={{
                left: `${15 + (i * 9) % 70}%`,
                top: `${20 + (i * 13) % 60}%`,
                animation: `xp-spark 1400ms ease-out ${i * 60}ms forwards`,
                opacity: 0,
              }}
            />
          ))}
        </>
      )}

      <div className="relative flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
          <div
            className="h-10 w-10 rounded-full bg-gradient-to-br from-neon to-gold flex items-center justify-center"
            style={celebrate ? { animation: "xp-level-pop 800ms ease-out" } : undefined}
          >
            <Trophy className="h-5 w-5 text-background" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground">Seviye</p>
            <p className="text-lg font-bold text-foreground leading-none tabular-nums">
              {xp.level}
            </p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-xs text-muted-foreground">Toplam XP</p>
          <p className="text-sm font-bold text-foreground tabular-nums">
            {Math.round(tweenTotal).toLocaleString()}
          </p>
        </div>
      </div>

      <div className="relative h-2 rounded-full bg-muted overflow-hidden">
        <div
          className="h-full bg-gradient-to-r from-neon to-gold"
          style={{
            width: `${tweenPct}%`,
            transition: "none",
            boxShadow: "0 0 12px rgba(245,205,83,0.55)",
          }}
        />
        {/* Shimmer sweep */}
        <div
          aria-hidden
          className="absolute inset-y-0 w-1/3 pointer-events-none"
          style={{
            background:
              "linear-gradient(90deg, transparent, rgba(255,255,255,0.5), transparent)",
            animation: "xp-shimmer 2.4s linear infinite",
            mixBlendMode: "overlay",
          }}
        />
      </div>

      <p className="text-[10px] text-muted-foreground mt-1 text-right tabular-nums">
        {Math.round(tweenCurrent).toLocaleString()} / {xp.next_level_xp.toLocaleString()} XP
        {" — "}sonraki seviyeye{" "}
        {Math.max(0, xp.next_level_xp - xp.current_level_xp).toLocaleString()} XP
      </p>
    </div>
  );
}

function Style() {
  return (
    <style>{`
      @keyframes xp-shimmer {
        0%   { transform: translateX(-100%); }
        100% { transform: translateX(400%); }
      }
      @keyframes xp-level-pop {
        0%   { transform: scale(1);   filter: brightness(1); }
        40%  { transform: scale(1.18); filter: brightness(1.4); }
        100% { transform: scale(1);   filter: brightness(1); }
      }
      @keyframes xp-burst {
        0%   { opacity: 0; transform: scale(0.6); }
        30%  { opacity: 1; transform: scale(1); }
        100% { opacity: 0; transform: scale(1.4); }
      }
      @keyframes xp-spark {
        0%   { opacity: 0; transform: translateY(0) scale(0.6) rotate(0deg); }
        30%  { opacity: 1; }
        100% { opacity: 0; transform: translateY(-26px) scale(1.2) rotate(160deg); }
      }
    `}</style>
  );
}

