import { useEffect, useRef, useState } from "react";
import { Link } from "@tanstack/react-router";
import { getHubIcon } from "@/lib/hubIcons";
import type { HubBanner } from "@/hooks/useHub";

interface Props {
  banners: HubBanner[];
  intervalMs?: number;
}

export function AutoBannerCarousel({ banners, intervalMs = 4500 }: Props) {
  const [index, setIndex] = useState(0);
  const scrollerRef = useRef<HTMLDivElement>(null);
  const pausedRef = useRef(false);

  // Auto-advance
  useEffect(() => {
    if (banners.length <= 1) return;
    const t = setInterval(() => {
      if (pausedRef.current) return;
      setIndex((i) => (i + 1) % banners.length);
    }, intervalMs);
    return () => clearInterval(t);
  }, [banners.length, intervalMs]);

  // Sync scroll position to active index
  useEffect(() => {
    const el = scrollerRef.current;
    if (!el) return;
    const child = el.children[index] as HTMLElement | undefined;
    if (child) {
      el.scrollTo({ left: child.offsetLeft - el.offsetLeft, behavior: "smooth" });
    }
  }, [index]);

  // Detect manual swipe → update active index
  useEffect(() => {
    const el = scrollerRef.current;
    if (!el) return;
    let raf = 0;
    const onScroll = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const center = el.scrollLeft + el.clientWidth / 2;
        let best = 0;
        let bestDist = Infinity;
        Array.from(el.children).forEach((c, i) => {
          const child = c as HTMLElement;
          const mid = child.offsetLeft + child.clientWidth / 2 - el.offsetLeft;
          const d = Math.abs(mid - center);
          if (d < bestDist) { bestDist = d; best = i; }
        });
        setIndex(best);
      });
    };
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => { el.removeEventListener("scroll", onScroll); cancelAnimationFrame(raf); };
  }, [banners.length]);

  if (banners.length === 0) return null;

  return (
    <div
      className="-mx-4"
      onMouseEnter={() => { pausedRef.current = true; }}
      onMouseLeave={() => { pausedRef.current = false; }}
      onTouchStart={() => { pausedRef.current = true; }}
      onTouchEnd={() => { setTimeout(() => { pausedRef.current = false; }, 2000); }}
    >
      <div
        ref={scrollerRef}
        className="overflow-x-auto scrollbar-hide snap-x snap-mandatory"
      >
        <div className="flex gap-3 px-4 pb-1">
          {banners.map((b) => {
            const BIcon = getHubIcon(b.icon_name);
            const isExternal = b.link_type === "external";
            const cardContent = (
              <>
                <div className="absolute -top-10 -right-10 h-40 w-40 rounded-full bg-white/15 blur-3xl" />
                <div className="absolute -bottom-12 -right-6 h-32 w-32 rounded-full bg-white/10 blur-2xl" />
                <div className="relative">
                  <h3 className="text-[22px] font-extrabold text-white leading-tight tracking-tight drop-shadow-md">
                    {b.title}
                  </h3>
                  {b.subtitle && (
                    <p className="mt-1 text-[12px] font-medium text-white/85 max-w-[80%]">
                      {b.subtitle}
                    </p>
                  )}
                  <div className="mt-5 flex items-center gap-2.5">
                    <div className={`flex h-9 w-9 items-center justify-center rounded-xl ${b.icon_gradient} ring-1 ring-white/30 shadow-[inset_0_1px_0_rgba(255,255,255,0.3)]`}>
                      <BIcon className="h-4 w-4 text-white drop-shadow" strokeWidth={2.5} />
                    </div>
                    <div className="leading-tight flex-1">
                      <p className="text-[13px] font-bold text-white">{b.app_name || b.title}</p>
                      {b.app_tag && <p className="text-[10px] text-white/75">{b.app_tag}</p>}
                    </div>
                    <span className="rounded-full bg-white/20 px-3 py-1 text-[11px] font-semibold text-white backdrop-blur">
                      {b.cta_label}
                    </span>
                  </div>
                </div>
              </>
            );

            const className = `relative flex-shrink-0 w-[88%] snap-center overflow-hidden rounded-3xl ${b.gradient} p-5 shadow-[0_8px_32px_rgba(0,0,0,0.5)] active:scale-[0.98] transition-transform`;

            return isExternal ? (
              <a key={b.id} href={b.link_url} target="_blank" rel="noopener noreferrer" className={className}>
                {cardContent}
              </a>
            ) : (
              <Link key={b.id} to={b.link_url as "/"} className={className}>
                {cardContent}
              </Link>
            );
          })}
        </div>
      </div>

      {/* Dots indicator */}
      {banners.length > 1 && (
        <div className="mt-3 flex justify-center gap-1.5">
          {banners.map((_, i) => (
            <button
              key={i}
              onClick={() => setIndex(i)}
              aria-label={`Banner ${i + 1}`}
              className={`h-1.5 rounded-full transition-all ${
                i === index ? "w-6 bg-primary" : "w-1.5 bg-white/30"
              }`}
            />
          ))}
        </div>
      )}
    </div>
  );
}

