import { useEffect } from "react";
import { createPortal } from "react-dom";
import type { HubAppDef } from "@/lib/hubApps";
import type { WidgetSize } from "@/hooks/useHubPreferences";
import { hapticTap } from "@/lib/native";
import { Square, LayoutGrid, RectangleHorizontal, X } from "lucide-react";

interface Props {
  app: HubAppDef;
  currentSize: WidgetSize;
  onSelect: (size: WidgetSize) => void;
  onHide?: () => void;
  onClose: () => void;
}

const GOLD = "#F5CD53";

export function HubAppContextMenu({ app: _app, currentSize, onSelect, onHide, onClose }: Props) {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  if (typeof document === "undefined") return null;

  const sizes: Array<{ size: WidgetSize; Icon: typeof Square; aria: string }> = [
    { size: "icon", Icon: Square, aria: "Simge boyutu (1×1)" },
    { size: "2x2", Icon: LayoutGrid, aria: "Orta widget (2×2)" },
    { size: "2x4", Icon: RectangleHorizontal, aria: "Geniş widget (2×4)" },
  ];

  return createPortal(
    <div
      role="dialog"
      aria-modal="true"
      data-no-jiggle-exit
      className="fixed inset-0 z-[1300] flex items-center justify-center"
      onClick={onClose}
      style={{ transform: "translateZ(0)" }}
    >
      {/* Backdrop — light blur, no opaque scrim. Telegram-style. */}
      <div
        aria-hidden
        className="absolute inset-0"
        style={{
          background: "rgba(0,0,0,0.35)",
          backdropFilter: "blur(10px) saturate(140%)",
          WebkitBackdropFilter: "blur(10px) saturate(140%)",
          animation: "fade-in 140ms ease-out both",
        }}
      />
      {/* Floating glass pill — icons only, no text */}
      <div
        onClick={(e) => e.stopPropagation()}
        className="relative flex items-center gap-1.5 px-2.5 py-2"
        style={{
          borderRadius: 999,
          background:
            "linear-gradient(160deg, rgba(28,28,30,0.92) 0%, rgba(8,8,10,0.96) 100%)",
          border: "0.5px solid rgba(245,205,83,0.30)",
          boxShadow:
            "0 24px 60px -12px rgba(0,0,0,0.85), inset 0 1px 0 rgba(255,255,255,0.08)",
          animation: "scale-in 200ms cubic-bezier(0.34,1.56,0.64,1) both",
          willChange: "transform, opacity",
        }}
      >
        {sizes.map(({ size, Icon, aria }) => {
          const active = currentSize === size;
          return (
            <button
              key={size}
              type="button"
              aria-label={aria}
              onClick={() => {
                hapticTap();
                onSelect(size);
                onClose();
              }}
              className="grid h-11 w-11 place-items-center rounded-full transition active:scale-90"
              style={{
                background: active ? "rgba(245,205,83,0.16)" : "rgba(255,255,255,0.04)",
                border: active
                  ? "0.5px solid rgba(245,205,83,0.55)"
                  : "0.5px solid rgba(255,255,255,0.08)",
              }}
            >
              <Icon
                className="h-[18px] w-[18px]"
                style={{ color: active ? GOLD : "rgba(255,255,255,0.85)" }}
                strokeWidth={2}
              />
            </button>
          );
        })}

        {onHide && (
          <>
            <span
              aria-hidden
              className="mx-0.5 h-7 w-px"
              style={{ background: "rgba(255,255,255,0.10)" }}
            />
            <button
              type="button"
              aria-label="Ana ekrandan kaldır"
              onClick={() => {
                hapticTap();
                onHide();
                onClose();
              }}
              className="grid h-11 w-11 place-items-center rounded-full transition active:scale-90"
              style={{
                background: "rgba(255,69,58,0.14)",
                border: "0.5px solid rgba(255,69,58,0.35)",
              }}
            >
              <X className="h-[18px] w-[18px]" style={{ color: "#FF453A" }} strokeWidth={2.4} />
            </button>
          </>
        )}
      </div>
    </div>,
    document.body,
  );
}

