/**
 * HubAppIcon — High-poly 3D Sovereign mini-app tile.
 *
 * Visual language is identical across both Hub themes:
 *   • Obsidian-Black squircle (iOS 17+ continuous corner radius approximation)
 *   • Hairline 24K gold rim
 *   • Inner gold glow (top-left highlight + bottom rim shadow)
 *   • Soft outer drop-shadow so the icon sits inside the Hub glass
 *   • Polished gold lucide stroke with luminous drop-shadow
 *
 * Modes:
 *   - normal: tap → spring zoom → navigate
 *   - editing: jiggle animation, X handle + grip indicator
 *
 * Long-press triggers `onLongPress` (used by the Hub to enter edit mode).
 * For the profile app, we render the user's `StarAvatar` (21-ray Stêrka Geş).
 */
import { Link, useNavigate } from "@tanstack/react-router";
import { useRef, useState } from "react";
import { hapticTap } from "@/lib/native";
import type { HubAppDef } from "@/lib/hubApps";
import { getKeskesorGradient } from "@/lib/hubApps";
import { StarAvatar } from "@/components/sovereign/StarAvatar";
import { useGuestGate } from "@/components/auth/GuestGateContext";
import { isGuestAllowedAppId } from "@/lib/guestMode";
import { useHubTheme } from "@/hooks/useHubTheme";
import { isFlowLocked } from "@/lib/flowLock";
import { Minus, Lock } from "lucide-react";
import { setLaunchOrigin } from "@/lib/appLaunchOrigin";

interface Props {
  app: HubAppDef;
  editing: boolean;
  onLongPress?: () => void;
  onHide?: () => void;
  /** Profile-only: render the user's avatar inside the 21-ray star. */
  profileAvatar?: { src?: string | null; name?: string | null };
  /**
   * Optional intercept — when provided AND it returns true, the default
   * navigation is skipped. Used by Hub to open the Mail half-modal sheet
   * without navigating away.
   */
  onOverrideTap?: (app: HubAppDef) => boolean;
}

/** iOS-17 squircle approximation. 22% of side length is close to Apple's curve. */
const SQUIRCLE_RADIUS = "22px";
/** 24K polished gold for icon strokes. */
const GOLD_24K = "#F5CD53";
/** Brighter highlight gold. */
const GOLD_LIGHT = "#FFE9A8";

export function HubAppIcon({ app, editing, onLongPress, onHide, profileAvatar, onOverrideTap }: Props) {
  const Icon = app.icon;
  const navigate = useNavigate();
  const { isGuest, challenge } = useGuestGate();
  const { theme, themeId } = useHubTheme();
  const isRainbow = themeId === "keskesor-os";
  // Sovereign-family themes keep the obsidian+gold tile; other themes
  // (iOS Light/Dark/Sunset/Ocean/Forest/Midnight Pro, SterkOS, Glass,
  // Stellar) use their own iconTileGradient + iconColor + iconGlow.
  const isSovereignFamily =
    themeId === "sovereign-obsidian" ||
    themeId === "royal-gold-3d" ||
    themeId === "sovereign-dark" ||
    themeId === "royal-gold";
  const useThemeTile = !isRainbow && !isSovereignFamily;
  const tileBackground = isRainbow
    ? getKeskesorGradient(app.id)
    : useThemeTile
      ? theme.iconTileGradient
      : app.vividGradient;
  const themedIconColor = useThemeTile ? theme.iconColor : isRainbow ? "#FFFFFF" : GOLD_24K;
  const themedIconGlow = useThemeTile
    ? theme.iconGlow
    : isRainbow
      ? "drop-shadow(0 1px 2px rgba(0,0,0,0.55))"
      : "drop-shadow(0 0 6px rgba(245,205,83,0.55)) drop-shadow(0 1px 1px rgba(0,0,0,0.7))";
  const themedRimColor = useThemeTile
    ? theme.accent
    : isRainbow
      ? "rgba(255,255,255,0.35)"
      : "rgba(212,175,55,0.55)";
  const locked = isGuest && !isGuestAllowedAppId(app.id);
  const pressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longFiredRef = useRef(false);
  const [zooming, setZooming] = useState(false);

  const startPress = () => {
    longFiredRef.current = false;
    pressTimer.current = setTimeout(() => {
      // Block jiggle entry while a sensitive flow (chat / booking) is active.
      if (isFlowLocked()) return;
      longFiredRef.current = true;
      hapticTap();
      onLongPress?.();
    }, 550);
  };
  const cancelPress = () => {
    if (pressTimer.current) clearTimeout(pressTimer.current);
  };

  const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    if (longFiredRef.current || editing) {
      e.preventDefault();
      return;
    }
    e.preventDefault();
    // Sovereign Wall: gate restricted apps for guests.
    if (challenge(app.id, app.label, app.to)) return;
    hapticTap();
    // Override hook (e.g. Mail half-modal sheet) — skip navigation.
    if (onOverrideTap?.(app)) return;

    // Shared element bridge: snapshot the icon's screen rect so the next
    // mini-app overlay can spring open from this exact position.
    try {
      const rect = e.currentTarget.getBoundingClientRect();
      setLaunchOrigin(app.id, rect);
    } catch {/* no-op */}

    setZooming(true);
    if (import.meta.env.DEV) {
      // eslint-disable-next-line no-console
      console.info("[HubAppIcon] navigate", { id: app.id, to: app.to, label: app.label });
    }
    // Snappy: navigate immediately — overlay handles the visual continuity.
    navigate({ to: app.to });
  };

  const tile = (
    <div
      data-testid={`hub-app-${app.id}`}
      aria-label={app.label}
      className={`relative flex flex-col items-center justify-start select-none gap-1.5 ${
        editing ? "animate-[jiggle_0.4s_ease-in-out_infinite]" : ""
      } ${zooming ? "animate-[hub-spring-launch_0.3s_cubic-bezier(0.34,1.56,0.64,1)_forwards]" : ""}`}
      style={{ touchAction: "manipulation" }}
    >
      {/* Minimalist obsidian tile — flat, hairline gold rim, subtle inner depth */}
      <div
        className="relative h-[68px] w-[68px] overflow-hidden"
        style={{
          borderRadius: SQUIRCLE_RADIUS,
          background: useThemeTile || isRainbow
            ? tileBackground
            : "linear-gradient(180deg, rgba(22,16,4,0.96) 0%, rgba(6,4,0,0.99) 100%)",
          boxShadow: [
            `0 0 0 0.5px ${themedRimColor}`,
            "inset 0 1px 0 rgba(255,236,180,0.10)",
            "0 4px 10px -4px rgba(0,0,0,0.6)",
          ].join(", "),
        }}
      >
        <div className="absolute inset-0 flex items-center justify-center">
          {profileAvatar ? (
            <StarAvatar src={profileAvatar.src} name={profileAvatar.name} size={60} tone="gold" />
          ) : (
            <Icon
              className="h-[30px] w-[30px]"
              strokeWidth={1.7}
              style={{
                color: themedIconColor,
                filter: useThemeTile
                  ? themedIconGlow
                  : "drop-shadow(0 0 3px rgba(245,205,83,0.35))",
              }}
            />
          )}
        </div>

        {/* Sovereign Wall padlock for guest-locked apps */}
        {locked && !editing && (
          <span
            aria-hidden
            className="absolute -bottom-1 -right-1 flex h-5 w-5 items-center justify-center rounded-full"
            style={{
              background: "linear-gradient(180deg,#1a1107,#000)",
              border: "1px solid rgba(212,175,55,0.6)",
              boxShadow: "0 4px 10px -2px rgba(0,0,0,0.85)",
            }}
          >
            <Lock className="h-2.5 w-2.5" style={{ color: GOLD_24K }} />
          </span>
        )}
      </div>
      {/* iOS-style minimalist red minus badge — top-left corner only */}
      {editing && onHide && (
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            hapticTap();
            onHide();
          }}
          className="absolute -top-1 -left-1 h-[22px] w-[22px] rounded-full flex items-center justify-center shadow-md z-10 active:scale-90 transition-transform"
          style={{
            background: "#FF3B30",
            border: "1.5px solid rgba(255,255,255,0.85)",
          }}
          aria-label={`${app.label} kaldır`}
        >
          <Minus className="h-3 w-3" strokeWidth={3} style={{ color: "#FFFFFF" }} />
        </button>
      )}

      {/* iOS-style label under the tile — single line, ellipsized */}
      {!editing && (
        <span
          className="block max-w-[76px] truncate text-center text-[12px] font-medium leading-tight"
          style={{
            color: theme.textPrimary ?? "rgba(255,255,255,0.92)",
            textShadow: "0 1px 2px rgba(0,0,0,0.55)",
          }}
        >
          {app.label}
        </span>
      )}
    </div>
  );

  if (editing) {
    return (
      <div
        onPointerDown={startPress}
        onPointerUp={cancelPress}
        onPointerCancel={cancelPress}
        onPointerLeave={cancelPress}
      >
        {tile}
      </div>
    );
  }

  return (
    <Link
      to={app.to}
      onClick={handleClick}
      onPointerDown={startPress}
      onPointerUp={cancelPress}
      onPointerCancel={cancelPress}
      onPointerLeave={cancelPress}
      draggable
      onDragStart={(e) => {
        // Allow Hub icons to be dragged onto the Sovereign Dynamic Dock
        // slots (works in both rest and Jiggle Mode). The Dock listens
        // for `application/x-jiyan-app-id`.
        e.dataTransfer.setData("application/x-jiyan-app-id", app.id);
        e.dataTransfer.effectAllowed = "copyMove";
      }}
      className="active:scale-95 transition-transform"
    >
      {tile}
    </Link>
  );
}

