/**
 * HubAppLibraryPage — iOS App Library clone.
 *
 *  • Search bar at the top (filters every category by label).
 *  • Categorized 2×2 mini-folder tiles (Apple's grid-of-grids):
 *      ┌─────┬─────┐
 *      │ a │ b │     ← 4 most-relevant icons per category
 *      │ c │ d │
 *      └─────┴─────┘
 *  • Tapping any of the 4 mini-icons inside a folder navigates to that app.
 *  • Tapping the surrounding folder body (background) does nothing — pure
 *    glance-and-go grid (matches Apple).
 *
 * Categories: "Öneriler", "Resmî", "Finans", "Toplum", "Oyun".
 * Apps without a `vividSection` fall into "Toplum" by convention.
 */
import { useMemo, useState } from "react";
import { Link } from "@tanstack/react-router";
import { Search, Lock, X } from "lucide-react";
import { HUB_APPS, type HubAppDef } from "@/lib/hubApps";
import { useHubTheme } from "@/hooks/useHubTheme";
import { hapticTap } from "@/lib/native";
import { useGuestGate } from "@/components/auth/GuestGateContext";
import { isGuestAllowedAppId } from "@/lib/guestMode";
import { useHubPreferences } from "@/hooks/useHubPreferences";

const SECTION_ORDER: Array<"Öneriler" | "Resmî" | "Finans" | "Toplum" | "Oyun"> = [
  "Öneriler",
  "Resmî",
  "Finans",
  "Toplum",
  "Oyun",
];

/** Build "Öneriler" — first 4 visible apps from the user's home grid. */
function buildSuggestions(visibleApps: string[]): HubAppDef[] {
  const ids = new Set(visibleApps.slice(0, 4));
  return HUB_APPS.filter((a) => ids.has(a.id)).slice(0, 4);
}

function bucketBySection(apps: HubAppDef[]): Record<string, HubAppDef[]> {
  const buckets: Record<string, HubAppDef[]> = {
    "Resmî": [],
    "Finans": [],
    "Toplum": [],
    "Oyun": [],
  };
  for (const app of apps) {
    const key = app.vividSection ?? "Toplum";
    buckets[key].push(app);
  }
  return buckets;
}

export function HubAppLibraryPage() {
  const { theme } = useHubTheme();
  const { visibleApps } = useHubPreferences();
  const [query, setQuery] = useState("");
  const [searchActive, setSearchActive] = useState(false);

  const filtered = useMemo(() => {
    const q = query.trim().toLocaleLowerCase("tr-TR");
    if (!q) return HUB_APPS;
    return HUB_APPS.filter((a) => a.label.toLocaleLowerCase("tr-TR").includes(q));
  }, [query]);

  const sections = useMemo(() => {
    const buckets = bucketBySection(filtered);
    return SECTION_ORDER.map((name) => {
      if (name === "Öneriler") {
        const suggestions = buildSuggestions(filtered.map((a) => a.id));
        return { name, apps: suggestions };
      }
      return { name, apps: buckets[name] ?? [] };
    }).filter((s) => s.apps.length > 0);
  }, [filtered, visibleApps]);

  return (
    <div
      className="relative px-4 pt-3"
      style={{
        paddingBottom: "calc(112px + env(safe-area-inset-bottom, 0px))",
      }}
      data-testid="hub-library-page"
    >
      {/* iOS search pill — neutral dark glass (gold banned per design rule) */}
      <div
        className="mx-auto mb-4 flex h-11 max-w-md items-center gap-2 rounded-full px-4"
        style={{
          background: "rgba(255,255,255,0.06)",
          border: "0.5px solid rgba(255,255,255,0.10)",
          backdropFilter: "blur(30px) saturate(160%)",
          WebkitBackdropFilter: "blur(30px) saturate(160%)",
        }}
      >
        <Search className="h-4 w-4" style={{ color: theme.textMuted }} />
        <input
          type="search"
          inputMode="search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onFocus={() => setSearchActive(true)}
          placeholder="Uygulama Arşivi"
          aria-label="Uygulama ara"
          data-testid="library-search"
          className="flex-1 bg-transparent text-[15px] outline-none placeholder:text-current"
          style={{ color: theme.textPrimary }}
          autoCorrect="off"
          autoCapitalize="none"
          spellCheck={false}
        />
        {(query || searchActive) && (
          <button
            type="button"
            onClick={() => {
              setQuery("");
              setSearchActive(false);
            }}
            aria-label="Vazgeç"
            className="grid h-5 w-5 place-items-center rounded-full bg-white/10"
          >
            <X className="h-3 w-3" style={{ color: theme.textMuted }} />
          </button>
        )}
      </div>

      {/* iOS App Library: focus or query → flat A→Z list. Otherwise → 2-column folders. */}
      {searchActive || query.trim() ? (
        <FlatAppList apps={filtered} />
      ) : (
        <div className="grid grid-cols-2 gap-4">
          {sections.map((s) => (
            <FolderTile key={s.name} title={s.name} apps={s.apps} />
          ))}
        </div>
      )}

      {filtered.length === 0 && (
        <p
          className="mt-12 text-center text-sm"
          style={{ color: theme.textMuted }}
          data-testid="library-empty"
        >
          "{query}" için sonuç yok.
        </p>
      )}
    </div>
  );
}

/** Apple-style flat alphabetical list shown while the user is searching. */
function FlatAppList({ apps }: { apps: HubAppDef[] }) {
  const { theme, themeId } = useHubTheme();
  const isSovereignFamily =
    themeId === "sovereign-obsidian" ||
    themeId === "royal-gold-3d" ||
    themeId === "sovereign-dark" ||
    themeId === "royal-gold";
  const useThemeTile = themeId !== "keskesor-os" && !isSovereignFamily;
  const { isGuest, challenge } = useGuestGate();
  const sorted = useMemo(
    () => [...apps].sort((a, b) => a.label.localeCompare(b.label, "tr-TR")),
    [apps],
  );
  return (
    <ul
      className="divide-y rounded-2xl overflow-hidden"
      style={{
        background: "rgba(255,255,255,0.04)",
        border: "0.5px solid rgba(255,255,255,0.08)",
        borderColor: "rgba(255,255,255,0.06)",
      }}
      data-testid="library-flat-list"
    >
      {sorted.map((app) => {
        const Icon = app.icon;
        const locked = isGuest && !isGuestAllowedAppId(app.id);
        return (
          <li key={app.id}>
            <Link
              to={app.to}
              onClick={(e) => {
                if (challenge(app.id, app.label, app.to)) {
                  e.preventDefault();
                  return;
                }
                hapticTap();
              }}
              className="flex items-center gap-3 px-3 py-2.5 active:bg-white/[0.06]"
              data-testid={`library-row-${app.id}`}
            >
              <span
                className="grid h-9 w-9 shrink-0 place-items-center"
                style={{
                  borderRadius: 10,
                  background: useThemeTile ? theme.iconTileGradient : app.vividGradient,
                  boxShadow:
                    "inset 0 1px 0 rgba(255,255,255,0.18), inset 0 -3px 6px rgba(0,0,0,0.5)",
                }}
              >
                <Icon
                  className="h-4 w-4"
                  strokeWidth={1.85}
                  style={{ color: theme.iconColor }}
                />
              </span>
              <span
                className="flex-1 text-[15px]"
                style={{ color: theme.textPrimary }}
              >
                {app.label}
              </span>
              {locked && <Lock className="h-3.5 w-3.5" style={{ color: theme.accent }} />}
            </Link>
          </li>
        );
      })}
    </ul>
  );
}

function FolderTile({ title, apps }: { title: string; apps: HubAppDef[] }) {
  const { theme } = useHubTheme();
  // 4 visible mini-icons; if more than 4, the 4th becomes a "stack preview".
  const top = apps.slice(0, 3);
  const overflow = apps.slice(3);

  return (
    <div
      className="flex flex-col items-center gap-2"
      data-testid={`library-folder-${title}`}
    >
      <div
        className="grid grid-cols-2 gap-2 p-3 w-full aspect-square"
        style={{
          borderRadius: 26,
          background: "rgba(255,255,255,0.05)",
          border: "0.5px solid rgba(255,255,255,0.08)",
          backdropFilter: "blur(30px) saturate(160%)",
          WebkitBackdropFilter: "blur(30px) saturate(160%)",
          boxShadow: "inset 0 1px 0 rgba(255,255,255,0.06)",
        }}
      >
        {top.map((a) => (
          <MiniIcon key={a.id} app={a} />
        ))}
        {overflow.length > 0 ? (
          <OverflowMini apps={overflow} />
        ) : (
          // pad empty slots so the 2x2 grid keeps its shape
          Array.from({ length: 3 - top.length }).map((_, i) => (
            <span key={`pad-${i}`} className="block aspect-square rounded-[14px]" />
          ))
        )}
      </div>
      <p
        className="text-[12px] font-medium tracking-tight text-center"
        style={{ color: theme.textPrimary }}
      >
        {title}
      </p>
    </div>
  );
}

function MiniIcon({ app }: { app: HubAppDef }) {
  const { theme, themeId } = useHubTheme();
  const isSovereignFamily =
    themeId === "sovereign-obsidian" ||
    themeId === "royal-gold-3d" ||
    themeId === "sovereign-dark" ||
    themeId === "royal-gold";
  const useThemeTile = themeId !== "keskesor-os" && !isSovereignFamily;
  const { isGuest, challenge } = useGuestGate();
  const locked = isGuest && !isGuestAllowedAppId(app.id);
  const Icon = app.icon;
  return (
    <Link
      to={app.to}
      onClick={(e) => {
        if (challenge(app.id, app.label, app.to)) {
          e.preventDefault();
          return;
        }
        hapticTap();
      }}
      aria-label={app.label}
      data-testid={`library-mini-${app.id}`}
      className="relative flex aspect-square items-center justify-center overflow-hidden active:scale-95 transition-transform"
      style={{
        borderRadius: 14,
        background: useThemeTile ? theme.iconTileGradient : app.vividGradient,
        boxShadow: [
          "0 0 0 0.5px rgba(255,255,255,0.10)",
          "inset 0 1px 0 rgba(255,255,255,0.20)",
          "inset 0 -4px 8px rgba(0,0,0,0.5)",
          "0 4px 10px -4px rgba(0,0,0,0.8)",
        ].join(", "),
      }}
    >
      <Icon
        className="h-5 w-5"
        strokeWidth={1.85}
        style={{ color: theme.iconColor, filter: theme.iconGlow }}
      />
      {locked && (
        <span
          aria-hidden
