/**
 * HubGoldenDustField — Interactive 3D golden dust particle field.
 *
 * Replaces the static `HubParticleField` for the Hub home screen.
 *
 * Behaviour
 *  • Canvas-based (single 60fps RAF loop, GPU-friendly)
 *  • ~80 particles in a fake-3D space (z 0..1) — far ones smaller & dimmer
 *  • Particles drift slowly upward; the cursor / touch acts as a soft gravity
 *    well that pulls nearby motes toward it (within ~180px). On pointer leave
 *    the field returns to its ambient drift.
 *  • Respects `prefers-reduced-motion` and the `lowPower` flag (skips RAF
 *    and renders nothing dynamic).
 *  • SSR-safe: only mounts on client; no hydration mismatch.
 *
 * Visual is intentionally subtle so the Hub icons stay primary.
 */
import { useEffect, useRef } from "react";

interface Props {
  enabled?: boolean;
  /** CSS color for the dust. Default = sovereign gold. */
  color?: string;
  /** Particle count (defaults scale with viewport). */
  count?: number;
}

interface Particle {
  x: number;
  y: number;
  z: number;          // depth 0 (far) .. 1 (near)
  vx: number;
  vy: number;
  size: number;
  alpha: number;
  hue: number;        // small variation around base color
}

export function HubGoldenDustField({
  enabled = true,
  color = "#F2C94C",
  count,
}: Props) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const pointerRef = useRef<{ x: number; y: number; active: boolean }>({
    x: -9999,
    y: -9999,
    active: false,
  });
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    if (!enabled) return;
    if (typeof window === "undefined") return;

    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (reduced) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    let w = window.innerWidth;
    let h = window.innerHeight;

    const resize = () => {
      w = window.innerWidth;
      h = window.innerHeight;
      canvas.width = Math.floor(w * dpr);
      canvas.height = Math.floor(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    resize();

    const N = count ?? Math.min(90, Math.max(40, Math.floor((w * h) / 16000)));
    const particles: Particle[] = Array.from({ length: N }).map(() => {
      const z = Math.random();
      return {
        x: Math.random() * w,
        y: Math.random() * h,
        z,
        vx: (Math.random() - 0.5) * 0.06 * (0.4 + z),
        vy: -0.08 - Math.random() * 0.18 * (0.4 + z),
        size: 0.6 + z * 1.8,
        alpha: 0.15 + z * 0.55,
        hue: (Math.random() - 0.5) * 14,
      };
    });

    // Parse base color → rgb so we can vary alpha cheaply.
    const baseRgb = hexToRgb(color);

    const onMove = (e: PointerEvent) => {
      pointerRef.current.x = e.clientX;
      pointerRef.current.y = e.clientY;
      pointerRef.current.active = true;
    };
    const onLeave = () => {
      pointerRef.current.active = false;
      pointerRef.current.x = -9999;
      pointerRef.current.y = -9999;
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerleave", onLeave);
    window.addEventListener("resize", resize);

    const PULL_RADIUS = 180;
    const PULL_STRENGTH = 0.18;
    const FRICTION = 0.96;
    const DRIFT_RETURN = 0.012; // tiny restoring force toward natural drift

    const tick = () => {
      ctx.clearRect(0, 0, w, h);
      const p = pointerRef.current;
      const pull = p.active;

      for (const part of particles) {
        // Pointer attraction
        if (pull) {
          const dx = p.x - part.x;
          const dy = p.y - part.y;
          const dist2 = dx * dx + dy * dy;
          if (dist2 < PULL_RADIUS * PULL_RADIUS) {
            const dist = Math.sqrt(dist2) || 1;
            const f = (1 - dist / PULL_RADIUS) * PULL_STRENGTH * (0.5 + part.z);
            part.vx += (dx / dist) * f;
            part.vy += (dy / dist) * f;
          }
        }

        // Gentle return to ambient upward drift
        const ambientVy = -0.08 - part.z * 0.18;
        part.vy += (ambientVy - part.vy) * DRIFT_RETURN;
        part.vx *= FRICTION;
        part.vy = part.vy * FRICTION + ambientVy * (1 - FRICTION);

        part.x += part.vx;
        part.y += part.vy;

        // Wrap
        if (part.y < -10) {
          part.y = h + 10;
          part.x = Math.random() * w;
        }
        if (part.x < -20) part.x = w + 20;
        else if (part.x > w + 20) part.x = -20;

        const r = part.size;
        ctx.beginPath();
        ctx.arc(part.x, part.y, r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${baseRgb.r}, ${baseRgb.g}, ${baseRgb.b}, ${part.alpha})`;
        ctx.shadowBlur = r * 4;
        ctx.shadowColor = `rgba(${baseRgb.r}, ${baseRgb.g}, ${baseRgb.b}, ${part.alpha * 0.6})`;
        ctx.fill();
      }
      ctx.shadowBlur = 0;

      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);

    return () => {
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerleave", onLeave);
      window.removeEventListener("resize", resize);
    };
  }, [enabled, color, count]);

  if (!enabled) return null;

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className="pointer-events-none fixed inset-0 z-0"
      style={{ contain: "strict" }}
    />
  );
}

function hexToRgb(hex: string): { r: number; g: number; b: number } {
  const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  if (!m) return { r: 242, g: 201, b: 76 };
  return {
    r: parseInt(m[1], 16),
    g: parseInt(m[2], 16),
    b: parseInt(m[3], 16),
  };
}

