/**
 * HubHomeGridPages — iOS SpringBoard-style horizontal pager INSIDE the
 * Hub page. Splits the user's visible apps into pages of 4 columns × 6 rows
 * (24 icons per page) with snap-scroll, page dots, and full
 * cross-page jiggle-mode drag-and-drop reordering.
 *
 * iOS parity:
 *  • Long-press an icon → enters jiggle mode.
 *  • Long-press an EMPTY slot in jiggle mode keeps you in jiggle mode and
 *    also enters it from rest (so you can re-arrange even when the grid is
 *    not full).
 *  • While jiggling, pointer-drag (touch + mouse) any icon to any slot on
 *    any page. Hovering the left/right edge of the pager auto-scrolls to
 *    the prev/next page.
 *  • All re-orders go through the parent `moveApp` callback (Supabase
 *    persistence handled there).
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { HubAppIcon } from "@/components/hub/HubAppIcon";
import { HubWidgetTile } from "@/components/hub/HubWidgetTile";
import { HubAppContextMenu } from "@/components/hub/HubAppContextMenu";
import { HUB_APPS_BY_ID, type HubAppDef } from "@/lib/hubApps";
import { useHubTheme } from "@/hooks/useHubTheme";
import { useHubPreferences, type WidgetSize } from "@/hooks/useHubPreferences";
import { hapticTap } from "@/lib/native";
import { isFlowLocked } from "@/lib/flowLock";

const COLS = 4;
const ROWS = 6;
const PAGE_SIZE = COLS * ROWS;
const EDGE_SCROLL_PX = 56;
const LONG_PRESS_MS = 480;

interface Props {
  visibleApps: string[];
  editing: boolean;
  onLongPress: () => void;
  onHide: (id: string) => void;
  /** Reorder by absolute index in the flat `visibleApps` array. */
  onReorder: (fromIdx: number, toIdx: number) => void;
  profile: { src?: string | null; name?: string | null };
  onOverrideTap?: (app: HubAppDef) => boolean;
}

interface Cell {
  /** Absolute index in `visibleApps`, or null for an empty slot. */
  idx: number | null;
  /** App id when filled. */
  id: string | null;
}

export function HubHomeGridPages({
  visibleApps,
  editing,
  onLongPress,
  onHide,
  onReorder,
  profile,
  onOverrideTap,
}: Props) {
  const { theme } = useHubTheme();
  const { widgetSizes, setWidgetSize } = useHubPreferences();
  const scrollerRef = useRef<HTMLDivElement | null>(null);
  const [activePage, setActivePage] = useState(0);
  const [draggingIdx, setDraggingIdx] = useState<number | null>(null);
  const [hoverIdx, setHoverIdx] = useState<number | null>(null);
  const [menuFor, setMenuFor] = useState<string | null>(null);

  const sizeOf = (id: string): WidgetSize => widgetSizes[id] ?? "icon";
  const footprintCols = (s: WidgetSize) => (s === "2x4" ? 4 : s === "2x2" ? 2 : 1);
  const footprintRows = (s: WidgetSize) => (s === "icon" ? 1 : 2);

  // Pack apps into pages with a simple row-fitting bin-packer. Each app
  // takes a footprint determined by its widget size; if it doesn't fit on
  // the current row we wrap, and if rows overflow we open a new page.
  type Placed = { idx: number; id: string; size: WidgetSize; col: number; row: number };
  type Page = { items: Placed[] };
  const pages = useMemo<Page[]>(() => {
    const result: Page[] = [];
    let page: Page = { items: [] };
    let row = 0;
    let col = 0;
    let rowHeight = 1;
    const flushPage = () => {
      result.push(page);
      page = { items: [] };
      row = 0;
      col = 0;
      rowHeight = 1;
    };
    for (let i = 0; i < visibleApps.length; i++) {
      const id = visibleApps[i];
      const size = sizeOf(id);
      const w = footprintCols(size);
      const h = footprintRows(size);
      if (col + w > COLS) {
        row += rowHeight;
        col = 0;
        rowHeight = 1;
      }
      if (row + h > ROWS) {
        flushPage();
      }
      page.items.push({ idx: i, id, size, col, row });
      col += w;
      rowHeight = Math.max(rowHeight, h);
    }
    if (page.items.length > 0 || result.length === 0) result.push(page);
    return result;
  }, [visibleApps, widgetSizes]);

  // ---- Page tracking + edge auto-scroll while dragging ---------------
  useEffect(() => {
    const el = scrollerRef.current;
    if (!el) return;
    let raf = 0;
    const onScroll = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const w = el.clientWidth;
        if (!w) return;
        setActivePage(Math.round(el.scrollLeft / w));
      });
    };
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      el.removeEventListener("scroll", onScroll);
      cancelAnimationFrame(raf);
    };
  }, []);

  const edgeScrollRef = useRef<{ dir: -1 | 0 | 1; raf: number }>({ dir: 0, raf: 0 });
  const stopEdgeScroll = () => {
    edgeScrollRef.current.dir = 0;
    cancelAnimationFrame(edgeScrollRef.current.raf);
  };
  const startEdgeScroll = (dir: -1 | 1) => {
    if (edgeScrollRef.current.dir === dir) return;
    stopEdgeScroll();
    edgeScrollRef.current.dir = dir;
    const tick = () => {
      const el = scrollerRef.current;
      if (!el || edgeScrollRef.current.dir === 0) return;
      const w = el.clientWidth;
      const target = Math.max(
        0,
        Math.min(
          (pages.length - 1) * w,
          el.scrollLeft + edgeScrollRef.current.dir * (w * 0.6),
        ),
      );
      el.scrollTo({ left: target, behavior: "smooth" });
      edgeScrollRef.current.dir = 0; // one snap per hover
    };
    edgeScrollRef.current.raf = requestAnimationFrame(tick);
  };

  // ---- Pointer-based drag (touch + mouse) ----------------------------
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cellRefs = useRef<Map<string, HTMLDivElement>>(new Map());
  const setCellRef = (key: string) => (el: HTMLDivElement | null) => {
    if (el) cellRefs.current.set(key, el);
    else cellRefs.current.delete(key);
  };

  const findCellAtPoint = (x: number, y: number): { absIdx: number } | null => {
    for (const [key, el] of cellRefs.current.entries()) {
      const r = el.getBoundingClientRect();
      if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) {
        const absIdx = Number(key);
        if (Number.isFinite(absIdx) && absIdx >= 0 && absIdx < visibleApps.length) {
          return { absIdx };
        }
      }
    }
    return null;
  };

  const beginPointerDrag = (absIdx: number, e: React.PointerEvent) => {
    if (!editing) return;
    if (isFlowLocked()) return;
    setDraggingIdx(absIdx);
    setHoverIdx(absIdx);
    (e.target as Element).setPointerCapture?.(e.pointerId);
  };

  const onPointerMoveGrid = (e: React.PointerEvent) => {
    if (draggingIdx == null) return;
    const scroller = scrollerRef.current;
    if (scroller) {
      const r = scroller.getBoundingClientRect();
      if (e.clientX - r.left < EDGE_SCROLL_PX) startEdgeScroll(-1);
      else if (r.right - e.clientX < EDGE_SCROLL_PX) startEdgeScroll(1);
      else stopEdgeScroll();
    }
    const hit = findCellAtPoint(e.clientX, e.clientY);
    if (hit && hit.absIdx !== hoverIdx) setHoverIdx(hit.absIdx);
  };

  const endPointerDrag = (e: React.PointerEvent) => {
    if (draggingIdx == null) return;
    stopEdgeScroll();
    const hit = findCellAtPoint(e.clientX, e.clientY);
    if (hit && hit.absIdx !== draggingIdx) {
      const target = Math.min(visibleApps.length - 1, Math.max(0, hit.absIdx));
      hapticTap();
      onReorder(draggingIdx, target);
    }
    setDraggingIdx(null);
    setHoverIdx(null);
  };

  // ---- Empty-slot long-press → enter jiggle --------------------------
  const onEmptyPointerDown = () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
    longPressTimer.current = setTimeout(() => {
      if (isFlowLocked()) return;
      hapticTap();
      onLongPress();
    }, LONG_PRESS_MS);
  };
  const cancelEmptyLongPress = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
  };

  return (
    <div className="relative w-full" data-testid="hub-home-grid-pages">
      <div
        ref={scrollerRef}
        className="flex w-full snap-x snap-mandatory overflow-x-auto overflow-y-hidden no-scrollbar"
        style={{ scrollBehavior: "smooth", touchAction: editing && draggingIdx != null ? "none" : "pan-x" }}
        onPointerMove={onPointerMoveGrid}
        onPointerUp={endPointerDrag}
        onPointerCancel={endPointerDrag}
      >
        {pages.map((page, p) => (
          <section
            key={p}
            data-testid={`hub-home-page-${p}`}
            className="snap-start shrink-0 w-full px-1"
            aria-label={`Sayfa ${p + 1}`}
          >
            <div
              className="grid gap-x-3 gap-y-4"
              style={{
                gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
                gridAutoRows: "92px",
              }}
              onPointerDown={(e) => {
                // Long-press on empty grid area → enter jiggle mode
                if (e.target === e.currentTarget) onEmptyPointerDown();
              }}
              onPointerUp={cancelEmptyLongPress}
              onPointerLeave={cancelEmptyLongPress}
              onPointerCancel={cancelEmptyLongPress}
            >
              {page.items.map(({ idx, id, size, col, row }) => {
                const app = HUB_APPS_BY_ID[id];
                if (!app) return null;
                const isHover = idx === hoverIdx && draggingIdx !== idx;
                const isDragging = idx === draggingIdx;
                const isProfile = app.id === "profile";
                const cKey = String(idx);
                const colSpan = footprintCols(size);
                const rowSpan = footprintRows(size);
                return (
                  <div
                    key={cKey}
                    ref={setCellRef(cKey)}
                    onPointerDown={(e) => {
                      if (editing) {
                        e.stopPropagation();
                        beginPointerDrag(idx, e);
                      }
                    }}
                    onClick={(e) => {
                      // In jiggle mode, tap on tile body (not the X handle)
                      // opens the iOS-style transform context menu.
                      if (!editing) return;
                      const t = e.target as HTMLElement;
                      if (t.closest('button[aria-label$="kaldır"]')) return;
                      e.preventDefault();
                      e.stopPropagation();
                      hapticTap();
                      setMenuFor(id);
                    }}
                    className={size === "icon" ? "flex justify-center items-center" : "flex items-stretch"}
                    style={{
                      gridColumn: `${col + 1} / span ${colSpan}`,
                      gridRow: `${row + 1} / span ${rowSpan}`,
                      opacity: isDragging ? 0.35 : 1,
                      transform: isHover ? "scale(0.95)" : undefined,
                      transition: "transform 120ms ease, opacity 120ms ease",
                      borderRadius: size === "icon" ? 18 : 22,
                      background: isHover ? "rgba(245,205,83,0.08)" : "transparent",
                      touchAction: editing ? "none" : "manipulation",
                    }}
                  >
                    {size === "icon" ? (
                      <HubAppIcon
                        app={app}
                        editing={editing}
                        onLongPress={onLongPress}
                        onHide={() => onHide(id)}
                        profileAvatar={isProfile ? profile : undefined}
                        onOverrideTap={onOverrideTap}
                      />
                    ) : (
                      <div className="w-full h-full">
                        <HubWidgetTile
                          app={app}
                          size={size}
                          editing={editing}
                          onLongPress={onLongPress}
                          onHide={() => onHide(id)}
                          onOverrideTap={onOverrideTap}
                        />
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </section>
        ))}
      </div>

      {menuFor && HUB_APPS_BY_ID[menuFor] && (
        <HubAppContextMenu
          app={HUB_APPS_BY_ID[menuFor]}
          currentSize={sizeOf(menuFor)}
          onSelect={(s) => setWidgetSize(menuFor, s)}
          onHide={() => onHide(menuFor)}
          onClose={() => setMenuFor(null)}
        />
      )}

      {pages.length > 1 && (
        <div
          aria-hidden
          className="mt-4 flex items-center justify-center gap-1.5"
          data-testid="hub-home-page-dots"
        >
          {pages.map((_, i) => (
            <span
              key={i}
              className="block rounded-full transition-all duration-200"
              style={{
                width: i === activePage ? 16 : 5,
                height: 5,
                background: i === activePage ? theme.accent : "rgba(255,234,170,0.32)",
                boxShadow: i === activePage ? "0 0 6px rgba(245,205,83,0.6)" : "none",
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
}

