/**
 * HubHomeIndicator — iOS-style slim horizontal bar at the very bottom.
 *
 * Visually a hairline gold line; functionally a swipe-up handle that
 * navigates back to the Hub (`/`) with a fluid spring transition.
 *
 * Hidden when already on the Hub (`/`) since it is the home itself.
 * Pointer/touch swipe-up of >40px from the bottom 28px → navigate.
 */
import { useEffect, useRef } from "react";
import { useNavigate, useLocation } from "@tanstack/react-router";
import { hapticTap } from "@/lib/native";

export function HubHomeIndicator() {
  const navigate = useNavigate();
  const location = useLocation();
  const startYRef = useRef<number | null>(null);

  // Don't show on the Hub root (we're already home).
  const onHub =
    location.pathname === "/" ||
    location.pathname === "/hub" ||
    location.pathname.startsWith("/hub/");

  useEffect(() => {
    if (onHub) return;
    const onStart = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t) return;
      const fromBottom = window.innerHeight - t.clientY;
      startYRef.current = fromBottom <= 36 ? t.clientY : null;
    };
    const onEnd = (e: TouchEvent) => {
      if (startYRef.current == null) return;
      const t = e.changedTouches[0];
      if (!t) return;
      const dy = startYRef.current - t.clientY;
      startYRef.current = null;
      if (dy > 50) {
        hapticTap();
        navigate({ to: "/" });
      }
    };
    window.addEventListener("touchstart", onStart, { passive: true });
    window.addEventListener("touchend", onEnd, { passive: true });
    return () => {
      window.removeEventListener("touchstart", onStart);
      window.removeEventListener("touchend", onEnd);
    };
  }, [navigate, onHub]);

  if (onHub) return null;

  return (
    <button
      type="button"
      onClick={() => {
        hapticTap();
        navigate({ to: "/" });
      }}
      aria-label="Hub'a dön"
      data-testid="hub-home-indicator"
      className="fixed left-1/2 z-50 h-[5px] rounded-full"
      style={{
        bottom: "calc(env(safe-area-inset-bottom, 0px) + 6px)",
        width: "134px",
        transform: "translateX(-50%)",
        background:
          "linear-gradient(90deg, rgba(212,175,55,0.55), rgba(255,236,180,0.95) 50%, rgba(212,175,55,0.55))",
        boxShadow:
          "0 0 12px rgba(212,175,55,0.55), 0 1px 0 rgba(0,0,0,0.6) inset",
        animation: "hub-home-indicator-pulse 1.6s ease-out 0.1s 1 both",
      }}
    />
  );
}

