/**
 * HubPager — iOS 18-style horizontal pager that hosts three pages:
 *
 *   ┌────────── ◀ ──────────┬──────────────┬────────── ▶ ──────────┐
 *   │   Widgets Page (left)  │    Hub      │   App Library (right)  │
 *   └────────────────────────┴──────────────┴────────────────────────┘
 *
 * Implementation:
 *  • Uses CSS scroll-snap (one snap point per page) so the gesture feels
 *    native on touch and trackpad.
 *  • A small dot indicator at the bottom shows the active page; the
 *    indicator floats just above the slim gold home-indicator bar.
 *  • Default page on mount is the Hub (centered).
 */
import { useEffect, useRef, useState } from "react";
import { useHubTheme } from "@/hooks/useHubTheme";

interface Props {
  widgetsPage: React.ReactNode;
  hubPage: React.ReactNode;
  libraryPage: React.ReactNode;
  /** Notified when the active page index changes (0=widgets, 1=hub, 2=library). */
  onPageChange?: (idx: number) => void;
}

const PAGE_COUNT = 3;
/** Center page = Hub. */
const DEFAULT_INDEX = 1;

export function HubPager({ widgetsPage, hubPage, libraryPage, onPageChange }: Props) {
  const { theme } = useHubTheme();
  const scrollerRef = useRef<HTMLDivElement | null>(null);
  const [activeIdx, setActiveIdx] = useState(DEFAULT_INDEX);

  // On mount, scroll instantly to the Hub (center page).
  useEffect(() => {
    const el = scrollerRef.current;
    if (!el) return;
    el.scrollTo({ left: el.clientWidth * DEFAULT_INDEX, behavior: "auto" });
    onPageChange?.(DEFAULT_INDEX);
  }, []);

  // Track which page is most visible.
  useEffect(() => {
    const el = scrollerRef.current;
    if (!el) return;
    let raf = 0;
    const onScroll = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const w = el.clientWidth;
        if (w === 0) return;
        const idx = Math.round(el.scrollLeft / w);
        const clamped = Math.max(0, Math.min(PAGE_COUNT - 1, idx));
        setActiveIdx(clamped);
        onPageChange?.(clamped);
      });
    };
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      el.removeEventListener("scroll", onScroll);
      cancelAnimationFrame(raf);
    };
  }, [onPageChange]);

  return (
    <div className="relative w-full" data-testid="hub-pager">
      <div
        ref={scrollerRef}
        className="hub-pager-scroller flex w-full snap-x snap-mandatory overflow-x-auto overflow-y-hidden no-scrollbar"
        style={{ scrollBehavior: "smooth", height: "100dvh" }}
      >
        <section
          className="snap-start shrink-0 w-screen max-w-full h-full overflow-y-auto overflow-x-hidden no-scrollbar"
          aria-label="Widgets"
          data-testid="hub-pager-widgets"
        >
          {widgetsPage}
        </section>
        <section
          className="snap-start shrink-0 w-screen max-w-full h-full overflow-y-auto overflow-x-hidden no-scrollbar"
          aria-label="Hub"
          data-testid="hub-pager-hub"
        >
          {hubPage}
        </section>
        <section
          className="snap-start shrink-0 w-screen max-w-full h-full overflow-y-auto overflow-x-hidden no-scrollbar"
          aria-label="App Library"
          data-testid="hub-pager-library"
        >
          {libraryPage}
        </section>
      </div>

      {/* Page-dot indicator */}
      <div
        aria-hidden
        className="pointer-events-none fixed left-1/2 z-40 flex -translate-x-1/2 items-center gap-1.5"
        style={{ bottom: "calc(env(safe-area-inset-bottom, 0px) + 94px)" }}
        data-testid="hub-pager-dots"
      >
        {Array.from({ length: PAGE_COUNT }).map((_, i) => (
          <span
            key={i}
            className="block rounded-full transition-all duration-200"
            style={{
              width: i === activeIdx ? 18 : 6,
              height: 6,
              background:
                i === activeIdx ? theme.accent : "rgba(255,234,170,0.35)",
              boxShadow:
                i === activeIdx
                  ? "0 0 8px rgba(245,205,83,0.7)"
                  : "0 0 0 rgba(0,0,0,0)",
            }}
          />
        ))}
      </div>
    </div>
  );
}

