/**
 * HubParticleField — static gold particle ambient field.
 *
 * Generates positions ONCE on mount (client-only) so:
 *  • Server-rendered HTML matches client (no hydration mismatch)
 *  • No re-renders mutate per-frame styles (lower CPU)
 *  • Animation lives in pure CSS keyframes, GPU-only.
 */
import { useEffect, useState } from "react";

interface Dot {
  size: number;
  left: number;
  top: number;
  duration: number;
  delay: number;
  opacity: number;
}

const COUNT = 10;

export function HubParticleField({ color }: { color: string }) {
  const [dots, setDots] = useState<Dot[] | null>(null);

  useEffect(() => {
    const next: Dot[] = Array.from({ length: COUNT }).map(() => ({
      size: 2 + Math.random() * 2,
      left: Math.random() * 100,
      top: Math.random() * 100,
      duration: 14 + Math.random() * 10,
      delay: -Math.random() * 12,
      opacity: 0.45 + Math.random() * 0.35,
    }));
    setDots(next);
  }, []);

  if (!dots) return null;

  return (
    <div
      aria-hidden
      className="pointer-events-none fixed inset-0 z-0 opacity-50"
      style={{ contain: "strict" }}
    >
      {dots.map((d, i) => (
        <span
          key={i}
          className="absolute rounded-full"
          style={{
            width: d.size,
            height: d.size,
            left: `${d.left}%`,
            top: `${d.top}%`,
            background: color,
            animation: `hub-float ${d.duration}s ease-in-out infinite`,
            animationDelay: `${d.delay}s`,
            opacity: d.opacity,
            willChange: "transform",
          }}
        />
      ))}
    </div>
  );
}

