/* HubScreen — Sovereign OS home (HMR refresh) */
/**
 * HubScreen — Sovereign OS home screen (shared between `/` and `/hub`).
 *
 * Behaviour:
 *  • Pitch-black canvas with two slow-drifting golden nebulas.
 *  • Frosted glass Banner + Clock/Weather + NearbyMivankas.
 *  • Customizable mini-app grid (4-col gold or iOS-Vivid sections).
 *  • Long-press any icon → Edit Mode (jiggle + remove).
 *  • Swipe-up from bottom 80px → opens the App Library drawer with bounce.
 *  • Top-right Sun/Moon toggle flips Sovereign Dark ↔ iOS Vivid.
 *  • Bottom of screen carries either:
 *       - a slim gold home-indicator only (Sovereign Dark), or
 *       - the iOS-Vivid bottom tab bar + home-indicator (Royal Gold).
 */
import { useEffect, useRef, useState } from "react";
import { useNavigate } from "@tanstack/react-router";
import { useAuth } from "@/hooks/useAuth";
import { useHubPreferences } from "@/hooks/useHubPreferences";
import { useLowPowerMode } from "@/hooks/useLowPowerMode";
import { useEdgeSwipeBack } from "@/hooks/useEdgeSwipeBack";
import { useSovereignProfile } from "@/hooks/useSovereignProfile";
import { useHubTheme } from "@/hooks/useHubTheme";
import { HUB_APPS_BY_ID } from "@/lib/hubApps";
import { GUEST_ALLOWED_APP_IDS } from "@/lib/guestMode";
import { HubAppIcon } from "@/components/hub/HubAppIcon";
import { HubThemeToggle } from "@/components/hub/HubThemeToggle";
import { GuestGateProvider } from "@/components/auth/GuestGateContext";
import { GuestSessionBadge } from "@/components/auth/GuestSessionBadge";
import { SovereignGlassLogin } from "@/components/auth/SovereignGlassLogin";

import { HubNebulaField } from "@/components/hub/HubNebulaField";
import { HubGoldenDustField } from "@/components/hub/HubGoldenDustField";
import { HubPager } from "@/components/hub/HubPager";
import { HubWidgetsPage } from "@/components/hub/HubWidgetsPage";
import { HubDiscoverPage } from "@/components/hub/HubDiscoverPage";
import { HubHomeGridPages } from "@/components/hub/HubHomeGridPages";
import { SovereignControlCenter } from "@/components/hub/SovereignControlCenter";
import { SovereignMailSheet } from "@/components/mail/SovereignMailSheet";
import { SovereignSettingsSheet } from "@/components/settings/SovereignSettingsSheet";
import { SovereignControlSheet } from "@/components/sovereign/SovereignControlSheet";
import { Check } from "lucide-react";
import { hapticTap } from "@/lib/native";

export function HubScreen() {
  return (
    <GuestGateProvider>
      <HubScreenInner />
    </GuestGateProvider>
  );
}

function HubScreenInner() {
  const { user } = useAuth();
  const isGuest = !user;
  const { data: profile } = useSovereignProfile(user?.id);
  const { visibleApps: visibleAppsAuth, moveApp, hideApp } = useHubPreferences();
  // Guest visitors see ONLY recovery-class apps. Their preferences are not
  // persisted to Supabase (they have no user), and editing is disabled.
  const visibleApps = isGuest
    ? Array.from(GUEST_ALLOWED_APP_IDS)
    : visibleAppsAuth;
  const { theme, themeId } = useHubTheme();
  const lowPower = useLowPowerMode();
  const [editing, setEditing] = useState(false);

  const [guestLoginOpen, setGuestLoginOpen] = useState(false);
  const [mailSheetOpen, setMailSheetOpen] = useState(false);
  const [settingsSheetOpen, setSettingsSheetOpen] = useState(false);
  const [controlSheetOpen, setControlSheetOpen] = useState(false);
  const [controlFocus, setControlFocus] = useState<"profile" | "security">("profile");
  const [hotSwap, setHotSwap] = useState(false);

  /**
   * Mini-app tap intercepts — open Apple-style half-modal sheets in-place
   * for the two çekirdek app'ler ki kendi route'larına gitmek yerine sheet
   * gibi açılsın:
   *  • settings → Sovereign Settings half-modal
   *  • profile  → Sovereign Control Center, Profile-first
   * Eski mail/security override'ları guvenlik+settings birleşmesi sonrası
   * artık gereksiz; deep-link'ler (/inbox, /security) hâlâ çalışıyor.
   */
  const handleAppOverride = (app: { id: string }) => {
    if (app.id === "settings") {
      setSettingsSheetOpen(true);
      return true;
    }
    if (app.id === "profile") {
      setControlFocus("profile");
      setControlSheetOpen(true);
      return true;
    }
    return false;
  };
  const wasGuestRef = useRef(isGuest);
  const navigate = useNavigate();
  useEdgeSwipeBack();

  // Swipe-up from anywhere on the Hub canvas → open the Ritual Palace.
  // Threshold: vertical drag > 90px AND |dy| > |dx|*1.6 to avoid hijacking
  // horizontal pager swipes or normal vertical scroll on small distances.
  const swipeRef = useRef<{ x: number; y: number; t: number } | null>(null);
  const handleTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
    const t = e.touches[0];
    swipeRef.current = { x: t.clientX, y: t.clientY, t: Date.now() };
  };
  const handleTouchEnd = (e: React.TouchEvent<HTMLDivElement>) => {
    const start = swipeRef.current;
    swipeRef.current = null;
    if (!start) return;
    const ch = e.changedTouches[0];
    const dx = ch.clientX - start.x;
    const dy = ch.clientY - start.y;
    const dt = Date.now() - start.t;
    if (dt > 700) return;
    if (dy < -90 && Math.abs(dy) > Math.abs(dx) * 1.6) {
      // Ignore if originating from an interactive element to keep UI sane.
      const target = e.target as HTMLElement;
      if (target.closest('button, a, [role="dialog"], input, textarea')) return;
      hapticTap();
      navigate({ to: "/ritual" });
    }
  };

  // Hot Swap — when guest transitions to authenticated without a reload,
  // play a brief golden unlock pulse over the Hub.
  useEffect(() => {
    if (wasGuestRef.current && !isGuest) {
      setHotSwap(true);
      const t = setTimeout(() => setHotSwap(false), 1100);
      wasGuestRef.current = false;
      return () => clearTimeout(t);
    }
    wasGuestRef.current = isGuest;
  }, [isGuest]);

  // ---- Pull-up swipe gesture removed (Apple-style Dynamic Dock now lives
  //      permanently at the bottom; App Library is opened via the
  //      "Tüm Uygulamalar" pill or the third Hub Pager page). --------------

  // Reorder is handled inside HubHomeGridPages via pointer events; we just
  // forward the parent's `moveApp` so Supabase persistence kicks in.
  const handleReorder = (from: number, to: number) => moveApp(from, to);

  // Dock removed — only the home indicator safe-area padding remains.
  const bottomReserve = "calc(24px + env(safe-area-inset-bottom, 0px))";

  // Tap-outside-to-exit jiggle: clicking anywhere that isn't an icon, the
  // dock, an editing handle, or an open sheet exits edit mode.
  const handleCanvasClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!editing) return;
    const t = e.target as HTMLElement;
    if (t.closest("[data-no-jiggle-exit]")) return;
    if (t.closest('[data-testid^="hub-app-"]')) return;
    if (t.closest('[role="dialog"]')) return;
    if (t.closest("button")) return;
    hapticTap();
    setEditing(false);
  };

  return (
    <div
      className="relative min-h-screen w-full overflow-x-hidden animate-hub-bounce-home"
      data-testid="hub-screen"
      data-theme={themeId}
      onClick={handleCanvasClick}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      style={{
        background: theme.pageBg,
        color: theme.textPrimary,
      }}
    >
      {/* Far-background drifting golden nebulas + interactive 3D dust */}
      <HubNebulaField enabled={!lowPower} />
      <HubGoldenDustField enabled={!lowPower} color={theme.accent ?? "#F2C94C"} />

      {/* Guest session badge — tappable upgrade pill */}
      {isGuest && <GuestSessionBadge onTap={() => setGuestLoginOpen(true)} />}
      <SovereignGlassLogin
        open={guestLoginOpen}
        onClose={() => setGuestLoginOpen(false)}
        appLabel="Tam Erişim"
        intendedPath="/"
      />

      {/* Hot Swap unlock pulse — fires when guest → authenticated. */}
      {hotSwap && (
        <div
          aria-hidden
          className="pointer-events-none fixed inset-0 z-[1200]"
          style={{
            background:
              "radial-gradient(60% 50% at 50% 50%, rgba(245,205,83,0.55) 0%, rgba(245,205,83,0.18) 35%, transparent 70%)",
            animation: "hub-hot-swap 1100ms cubic-bezier(0.22,1,0.36,1) both",
          }}
        >
          <style>{`
            @keyframes hub-hot-swap {
              0% { opacity: 0; transform: scale(0.6); }
              25% { opacity: 1; transform: scale(1); }
              100% { opacity: 0; transform: scale(1.4); }
            }
          `}</style>
        </div>
      )}

      {/* Particle field removed — no per-frame style mutation work on the
          UI thread. Nebula stays as it's a single GPU-composited layer
          gated by lowPower. */}

      {/* Sovereign Control Center (pull-down from top-right) */}
      <SovereignControlCenter />

      {/* iOS 18-style 3-page horizontal pager */}
      <div className="relative z-10">
        <HubPager
          widgetsPage={<HubWidgetsPage />}
          hubPage={
            <main
              className="mx-auto max-w-lg px-5 pt-3"
              style={{ paddingBottom: bottomReserve }}
            >
              {/* ─── Top bar (icon-only, compact). Theme toggle pinned right;
                  appears only as a tiny floating glass dot to keep the
                  iOS-parity look. ─── */}
              <header className="flex items-center justify-end mb-2 h-8">
                {editing && (
                  <button
                    type="button"
                    aria-label="Düzenlemeyi bitir"
                    onClick={() => {
                      hapticTap();
                      setEditing(false);
                    }}
                    className="grid h-8 w-8 place-items-center rounded-full border border-white/10 bg-white/5 backdrop-blur-2xl active:scale-95 transition-transform"
                  >
                    <Check className="h-4 w-4" style={{ color: theme.textPrimary }} />
                  </button>
                )}
                <HubThemeToggle />
              </header>

              {/* Page 2 = strict 4xN icon grid only. Banner + widgets moved
                  to Page 1 (Today View) for iOS-parity separation. */}

              {/* ─── SpringBoard pages — 4×6 per page, swipeable horizontally ─── */}
              <section className="mt-2" data-testid="hub-app-grid">
                <HubHomeGridPages
                  visibleApps={visibleApps}
                  editing={editing}
