    name,
    items: ids
      .map((id, idx) => ({ id, idx, app: HUB_APPS_BY_ID[id] }))
      .filter((x) => x.app && (x.app.vividSection ?? "Toplum") === name),
  })).filter((s) => s.items.length > 0);

  return (
