/**
 * HubWidgetTile — iOS-parity 2x2 / 2x4 widget rendering for any Hub app.
 *
 * Renders a glass tile with the app's gradient, icon and label. Tap navigates
 * exactly like HubAppIcon (with onOverrideTap / guest gate). In jiggle mode
 * the tile shows the same X handle and animates with the family-wide jiggle
 * keyframe so visual parity is maintained.
 *
 * Sizes:
 *   • "2x2" — square medium widget, occupies 2 grid columns × 2 grid rows.
 *   • "2x4" — wide large widget, occupies 4 grid columns × 2 grid rows.
 */
import { Link, useNavigate } from "@tanstack/react-router";
import { useState } from "react";
import { hapticTap } from "@/lib/native";
import type { HubAppDef } from "@/lib/hubApps";
import { useGuestGate } from "@/components/auth/GuestGateContext";
import { isGuestAllowedAppId } from "@/lib/guestMode";
import { isFlowLocked } from "@/lib/flowLock";
import { Minus, Lock } from "lucide-react";

const GOLD_24K = "#F5CD53";

interface Props {
  app: HubAppDef;
  size: "2x2" | "2x4";
  editing: boolean;
  onLongPress?: () => void;
  onHide?: () => void;
  onOverrideTap?: (app: HubAppDef) => boolean;
}

export function HubWidgetTile({ app, size, editing, onLongPress, onHide, onOverrideTap }: Props) {
  const Icon = app.icon;
  const navigate = useNavigate();
  const { isGuest, challenge } = useGuestGate();
  const locked = isGuest && !isGuestAllowedAppId(app.id);
  const [zooming, setZooming] = useState(false);

  // Apple corner radii: medium 22, large 28
  const radius = size === "2x4" ? 28 : 22;

  let pressTimer: ReturnType<typeof setTimeout> | null = null;
  let longFired = false;
  const startPress = () => {
    longFired = false;
    pressTimer = setTimeout(() => {
      if (isFlowLocked()) return;
      longFired = true;
      hapticTap();
      onLongPress?.();
    }, 550);
  };
  const cancelPress = () => {
    if (pressTimer) clearTimeout(pressTimer);
  };

  const handleClick = (e: React.MouseEvent) => {
    if (longFired || editing) {
      e.preventDefault();
      return;
    }
    e.preventDefault();
    if (challenge(app.id, app.label, app.to)) return;
    hapticTap();
    if (onOverrideTap?.(app)) return;
    setZooming(true);
    setTimeout(() => navigate({ to: app.to }), 240);
  };

  const tile = (
    <div
      data-testid={`hub-widget-${app.id}`}
      aria-label={app.label}
      className={`relative w-full h-full overflow-hidden p-4 flex flex-col justify-between select-none ${
        editing ? "animate-[jiggle_0.4s_ease-in-out_infinite]" : ""
      } ${zooming ? "animate-[hub-spring-launch_0.3s_cubic-bezier(0.34,1.56,0.64,1)_forwards]" : ""}`}
      style={{
        minHeight: "100%",
        borderRadius: radius,
        background:
          "linear-gradient(180deg, rgba(20,15,3,0.94) 0%, rgba(6,4,0,0.99) 100%)",
        boxShadow: [
          "0 0 0 0.5px rgba(212,175,55,0.22)",
          "inset 0 1px 0 rgba(255,236,180,0.10)",
          "0 6px 14px -6px rgba(0,0,0,0.7)",
        ].join(", "),
        touchAction: "manipulation",
      }}
    >
      {/* Header: icon */}
      <div className="relative z-10 flex items-start justify-between">
        <div
          className="grid h-10 w-10 place-items-center rounded-xl"
          style={{
            background: "rgba(0,0,0,0.35)",
            border: "0.5px solid rgba(245,205,83,0.35)",
          }}
        >
          <Icon
            className="h-5 w-5"
            strokeWidth={1.85}
            style={{
              color: GOLD_24K,
              filter: "drop-shadow(0 0 6px rgba(245,205,83,0.55))",
            }}
          />
        </div>
        {locked && !editing && (
          <span
            aria-hidden
            className="grid h-6 w-6 place-items-center rounded-full"
            style={{
              background: "rgba(0,0,0,0.5)",
              border: "0.5px solid rgba(245,205,83,0.45)",
            }}
          >
            <Lock className="h-3 w-3" style={{ color: GOLD_24K }} />
          </span>
        )}
      </div>
      {/* Footer: label only (no "Aç" subtitle) */}
      <div className="relative z-10">
        <div
          className="text-[15px] font-semibold tracking-tight text-white"
          style={{ textShadow: "0 1px 2px rgba(0,0,0,0.55)" }}
        >
          {app.label}
        </div>
      </div>

      {editing && onHide && (
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            hapticTap();
            onHide();
          }}
          className="absolute -top-1 -left-1 z-20 h-[22px] w-[22px] rounded-full flex items-center justify-center shadow-md active:scale-90 transition-transform"
          style={{ background: "#FF3B30", border: "1.5px solid rgba(255,255,255,0.85)" }}
          aria-label={`${app.label} kaldır`}
        >
          <Minus className="h-3 w-3" strokeWidth={3} style={{ color: "#FFFFFF" }} />
        </button>
      )}
    </div>
  );

  if (editing) {
    return (
      <div
        className="w-full h-full"
        onPointerDown={startPress}
        onPointerUp={cancelPress}
        onPointerCancel={cancelPress}
        onPointerLeave={cancelPress}
      >
        {tile}
      </div>
    );
  }

  return (
    <Link
      to={app.to}
      onClick={handleClick}
      onPointerDown={startPress}
      onPointerUp={cancelPress}
      onPointerCancel={cancelPress}
      onPointerLeave={cancelPress}
      className="block w-full h-full active:scale-[0.98] transition-transform"
    >
      {tile}
    </Link>
  );
}

