/**
 * SovereignBanner — Premium top banner for the Hub.
 *
 * Cycles between:
 *   1. Total DiravCash in circulation
 *   2. Latest Dîwan announcement
 *   3. Global KEKA stats
 *
 * Adapts colors to the active Sovereign OS theme.
 */
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Crown, Megaphone, TrendingUp } from "lucide-react";
import { useHubTheme } from "@/hooks/useHubTheme";

interface Slide {
  icon: typeof Crown;
  label: string;
  value: string;
  hint?: string;
}

export function SovereignBanner() {
  const { theme } = useHubTheme();
  const [slides, setSlides] = useState<Slide[]>([]);
  const [idx, setIdx] = useState(0);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const result: Slide[] = [];

      try {
        const { data } = await supabase.rpc("get_dc_total_supply" as any);
        const total = (data as number) ?? null;
        if (total != null) {
          result.push({
            icon: Crown,
            label: "Toplam DiravCash",
            value: total.toLocaleString("tr-TR") + " DC",
            hint: "tedavülde",
          });
        }
      } catch {}

      if (result.length === 0) {
        result.push({
          icon: Crown,
          label: "Sovereign Hazine",
          value: "Egemen Mali Sistem",
          hint: "WKO",
        });
      }

      try {
        const { data } = await supabase
          .from("global_announcements")
          .select("title, body")
          .eq("is_active", true)
          .order("created_at", { ascending: false })
          .limit(1)
          .maybeSingle();
        if (data) {
          result.push({
            icon: Megaphone,
            label: data.title,
            value: data.body.slice(0, 70) + (data.body.length > 70 ? "…" : ""),
            hint: "Dîwan",
          });
        }
      } catch {}

      try {
        const { data } = await supabase
          .from("keka_videos" as any)
          .select("id", { count: "exact", head: true });
        const count = (data as any)?.count ?? null;
        if (count != null) {
          result.push({
            icon: TrendingUp,
            label: "KEKA Akışı",
            value: count.toLocaleString("tr-TR") + " hikaye",
            hint: "küresel",
          });
        }
      } catch {}

      if (!cancelled) setSlides(result);
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (slides.length <= 1) return;
    const id = setInterval(() => setIdx((i) => (i + 1) % slides.length), 5000);
    return () => clearInterval(id);
  }, [slides.length]);

  const cur = slides[idx];

  return (
    <div
      className="relative rounded-[28px] p-4 overflow-hidden"
      style={{
        background: theme.surfaceBgStrong,
