/**
 * SovereignControlCenter — iOS-style pull-down panel from the top-right.
 *
 * Trigger:
 *  • Touch swipe-down from the top 28px on the right half of the screen.
 *  • Tap the small gold dot in the Hub top-right (visible during pull).
 *
 * Contents:
 *  • Three 3D gold toggles: Ses, Bildirimler, Ghost Mode
 *  • Each toggle glows when ON.
 *  • Backdrop dims the screen; tap-to-dismiss or swipe-up to close.
 *
 * Persistence: writes through `useHubPreferences` (localStorage + Supabase).
 */
import { useEffect, useState } from "react";
import { useHubTheme } from "@/hooks/useHubTheme";
import { useHubPreferences } from "@/hooks/useHubPreferences";
import { hapticTap } from "@/lib/native";
import { Volume2, VolumeX, Bell, BellOff, Ghost, X } from "lucide-react";

export function SovereignControlCenter() {
  const { theme } = useHubTheme();
  const {
    prefs,
    setSoundEnabled,
    setNotificationsEnabled,
    setGhostMode,
  } = useHubPreferences();
  const [open, setOpen] = useState(false);

  // Pull-down gesture from the top-right corner
  useEffect(() => {
    let startY: number | null = null;
    let startX: number | null = null;
    const onStart = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t) return;
      // Top 28px AND right half of the screen
      if (t.clientY > 28) return;
      if (t.clientX < window.innerWidth / 2) return;
      startY = t.clientY;
      startX = t.clientX;
    };
    const onEnd = (e: TouchEvent) => {
      if (startY == null || startX == null) return;
      const t = e.changedTouches[0];
      const dy = t.clientY - startY;
      const dx = Math.abs(t.clientX - startX);
      startY = null;
      startX = null;
      if (dy > 60 && dx < 80) {
        hapticTap();
        setOpen(true);
      }
    };
    window.addEventListener("touchstart", onStart, { passive: true });
    window.addEventListener("touchend", onEnd, { passive: true });
    return () => {
      window.removeEventListener("touchstart", onStart);
      window.removeEventListener("touchend", onEnd);
    };
  }, []);

  // Swipe-up inside the panel to close
  useEffect(() => {
    if (!open) return;
    let startY: number | null = null;
    const onStart = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t) return;
      startY = t.clientY;
    };
    const onEnd = (e: TouchEvent) => {
      if (startY == null) return;
      const t = e.changedTouches[0];
      if (startY - t.clientY > 60) setOpen(false);
      startY = null;
    };
    window.addEventListener("touchstart", onStart, { passive: true });
    window.addEventListener("touchend", onEnd, { passive: true });
    return () => {
      window.removeEventListener("touchstart", onStart);
      window.removeEventListener("touchend", onEnd);
    };
  }, [open]);

  return (
    <>
      {/* Always-visible hint dot in the top-right (under the search button) */}
      <button
        type="button"
        onClick={() => {
          hapticTap();
          setOpen(true);
        }}
        aria-label="Sovereign Control Center"
        data-testid="hub-control-center-handle"
        className="fixed right-3 z-30 h-2 w-12 rounded-full active:scale-95 transition-transform"
        style={{
          top: "calc(env(safe-area-inset-top, 0px) + 4px)",
          background:
            "linear-gradient(90deg, rgba(212,175,55,0.4), rgba(255,236,180,0.95) 50%, rgba(212,175,55,0.4))",
          boxShadow: "0 0 8px rgba(212,175,55,0.55)",
        }}
      />

      {/* Backdrop */}
      {open && (
        <div
          aria-hidden
          onClick={() => setOpen(false)}
          className="fixed inset-0 z-50 animate-fade-in"
          style={{
            background:
              "linear-gradient(180deg, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0.35) 60%, rgba(0,0,0,0.05) 100%)",
            backdropFilter: "blur(8px)",
            WebkitBackdropFilter: "blur(8px)",
          }}
        />
      )}

      {/* Panel */}
      {open && (
        <div
          role="dialog"
          aria-modal="true"
          data-testid="hub-control-center"
          className="fixed left-1/2 top-3 z-[60] w-[min(96vw,420px)] -translate-x-1/2 rounded-[28px] p-4 animate-[hub-bounce-home_0.45s_cubic-bezier(0.22,1.2,0.36,1)_both]"
          style={{
            background: theme.surfaceBgStrong,
            border: theme.borderStrong,
            backdropFilter: "blur(28px) saturate(160%)",
            WebkitBackdropFilter: "blur(28px) saturate(160%)",
            boxShadow: theme.heroShadow,
            color: theme.textPrimary,
          }}
        >
          <div className="flex items-center justify-between mb-3">
            <div
              className="text-[10px] uppercase tracking-[0.22em]"
              style={{ color: theme.textMuted }}
            >
              Sovereign Control
            </div>
            <button
              type="button"
              onClick={() => setOpen(false)}
              aria-label="Kapat"
              className="h-7 w-7 rounded-full flex items-center justify-center active:scale-95"
              style={{
                background: "rgba(0,0,0,0.45)",
                border: theme.border,
              }}
            >
              <X className="h-3.5 w-3.5" style={{ color: theme.iconColor }} />
            </button>
          </div>

          <div className="grid grid-cols-3 gap-3">
            <ControlToggle
              label="Ses"
              active={prefs.soundEnabled}
              onIcon={Volume2}
              offIcon={VolumeX}
              onToggle={() => {
                hapticTap();
                setSoundEnabled(!prefs.soundEnabled);
              }}
            />
            <ControlToggle
              label="Bildirim"
              active={prefs.notificationsEnabled}
              onIcon={Bell}
              offIcon={BellOff}
              onToggle={() => {
                hapticTap();
                setNotificationsEnabled(!prefs.notificationsEnabled);
              }}
            />
            <ControlToggle
              label="Ghost"
              active={prefs.ghostMode}
              onIcon={Ghost}
              offIcon={Ghost}
              onToggle={() => {
                hapticTap();
                setGhostMode(!prefs.ghostMode);
              }}
            />
          </div>

          <p
            className="mt-4 text-center text-[10px]"
            style={{ color: theme.textFaint }}
          >
            Yukarı kaydır · Kapat
          </p>
        </div>
      )}
    </>
  );
}

interface ToggleProps {
  label: string;
  active: boolean;
  onIcon: React.ComponentType<{ className?: string; style?: React.CSSProperties; strokeWidth?: number }>;
  offIcon: React.ComponentType<{ className?: string; style?: React.CSSProperties; strokeWidth?: number }>;
  onToggle: () => void;
}

function ControlToggle({ label, active, onIcon: OnIcon, offIcon: OffIcon, onToggle }: ToggleProps) {
  const { theme } = useHubTheme();
  const Icon = active ? OnIcon : OffIcon;
  return (
    <button
      type="button"
      onClick={onToggle}
      data-testid={`cc-toggle-${label}`}
      data-active={active}
      className="relative aspect-square rounded-[22px] flex flex-col items-center justify-center gap-1 active:scale-95 transition-transform"
      style={{
        background: active
          ? "radial-gradient(120% 100% at 30% 0%, #FFE9A8 0%, #D4AF37 50%, #6E4B0E 100%)"
          : "radial-gradient(120% 100% at 0% 0%, rgba(212,175,55,0.18) 0%, rgba(8,6,2,0.96) 70%)",
        border: active
          ? "1px solid rgba(255,236,180,0.85)"
          : theme.border,
        boxShadow: active
          ? "inset 0 1px 0 rgba(255,255,255,0.45), 0 0 18px rgba(245,205,83,0.55), 0 6px 14px -6px rgba(0,0,0,0.7)"
          : "inset 0 1px 0 rgba(255,234,170,0.18), inset 0 -6px 10px rgba(0,0,0,0.5), 0 6px 14px -6px rgba(0,0,0,0.7)",
      }}
    >
      <Icon
        className="h-6 w-6"
        strokeWidth={1.85}
        style={{
          color: active ? "#0a0500" : theme.iconColor,
          filter: active ? "drop-shadow(0 0 4px rgba(255,236,180,0.9))" : theme.iconGlow,
        }}
      />
      <span
        className="text-[10px] font-medium"
        style={{
          color: active ? "#0a0500" : theme.textPrimary,
          textShadow: active ? "none" : "0 1px 2px rgba(0,0,0,0.7)",
        }}
      >
        {label}
      </span>
    </button>
  );
}

