/**
 * SovereignDynamicDock — Apple-style 4-slot floating dock.
 *
 * Apple-parity behaviour:
 *   • 4 large rounded squircle slots inside a translucent frosted glass pill.
 *   • Tap → spring zoom + navigate (or open half-modal).
 *   • Long-press (~520ms) → enter Jiggle Mode (HEAVY haptic + audible click).
 *   • In Jiggle Mode taps are LOCKED on every slot (drag-lock); only drags
 *     and the explicit "Bitti" pill / tap-outside exit. This eliminates
 *     accidental navigation when shaking icons or initiating a drag.
 *   • Drag a Hub icon onto a slot → SUCCESS haptic + `playPop()` chime,
 *     slot glows gold, slot is replaced (or swapped if already pinned).
 *   • Exiting Jiggle Mode fires a MEDIUM haptic so the user feels the state
 *     change in both directions.
 *   • Configuration persists via `useHubPreferences().dockSlots`
 *     (localStorage + `widget_config.dockSlots` in Supabase).
 */
import { useNavigate } from "@tanstack/react-router";
import { useEffect, useRef, useState } from "react";
import { Check } from "lucide-react";
import { hapticTap, hapticMedium, hapticHeavy, hapticSuccess } from "@/lib/native";
import { playTick, playPop } from "@/lib/systemSounds";
import { useHubPreferences } from "@/hooks/useHubPreferences";
import { useHubTheme } from "@/hooks/useHubTheme";
import { HUB_APPS_BY_ID } from "@/lib/hubApps";

import { useAuth } from "@/hooks/useAuth";
import { useSovereignProfile } from "@/hooks/useSovereignProfile";
import { isFlowLocked } from "@/lib/flowLock";

const GOLD_LIGHT = "#FFE9A8";
/** iOS continuous corner radius (squircle). Uniform across all 4 slots. */
const SLOT_RADIUS = "18px";
/** Slot side length — uniform for every slot. */
const SLOT_SIZE = 60;

interface Props {
  /** Optional app-tap intercept (mail/settings/profile/security half-modals). */
  onAppTap?: (appId: string) => boolean;
}

/** First 4 default suggestions when a slot is cleared. */
const FALLBACK_SUGGESTIONS = ["deng", "akis", "pazar", "guvenlik"] as const;

export function SovereignDynamicDock({ onAppTap }: Props) {
  const navigate = useNavigate();
  const { dockSlots, setDockSlot, reorderDockSlot } = useHubPreferences();
  const { theme } = useHubTheme();
  const { user } = useAuth();
  const { data: profile } = useSovereignProfile(user?.id);

  const [editing, setEditing] = useState(false);
  const [dragOver, setDragOver] = useState<number | null>(null);
  const [pulse, setPulse] = useState<number | null>(null);
  /** Slot index whose quick-action sheet is open (long-press in jiggle mode). */
  const [actionSlot, setActionSlot] = useState<number | null>(null);
  /** Index of the dock slot currently being internally re-ordered. */
  const [internalDragIdx, setInternalDragIdx] = useState<number | null>(null);
  const [internalHoverIdx, setInternalHoverIdx] = useState<number | null>(null);
  const slotRefs = useRef<Map<number, HTMLButtonElement>>(new Map());
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longFiredRef = useRef(false);

  // Tap-outside listener: exit jiggle mode when the user taps elsewhere.
  useEffect(() => {
    if (!editing) return;
    const onDocPointerDown = (e: PointerEvent) => {
      const t = e.target as HTMLElement | null;
      if (t?.closest("[data-sovereign-dock]")) return;
      // Allow drags from Hub icons to keep editing state alive.
      if (t?.closest("[data-testid^='hub-app-']")) return;
      hapticMedium();
      setEditing(false);
    };
    document.addEventListener("pointerdown", onDocPointerDown);
    return () => document.removeEventListener("pointerdown", onDocPointerDown);
  }, [editing]);

  /**
   * Long-press behaviour:
   *  • Not editing → enter Jiggle Mode (heavy haptic + tick).
   *  • Already editing → open the slot's Quick Actions sheet.
   */
  const startLongPress = (slotIdx: number) => {
    longFiredRef.current = false;
    longPressTimer.current = setTimeout(() => {
      // Block jiggle entry while a sensitive flow is active.
      if (isFlowLocked() && !editing) return;
      longFiredRef.current = true;
      hapticHeavy();
      playTick();
      if (editing) {
        setActionSlot(slotIdx);
      } else {
        setEditing(true);
      }
    }, 520);
  };
  const cancelLongPress = () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
  };

  // ---- Intra-dock pointer reorder (jiggle mode only) -----------------
  const findSlotAtPoint = (x: number, y: number): number | null => {
    for (const [idx, el] of slotRefs.current.entries()) {
      const r = el.getBoundingClientRect();
      if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) return idx;
    }
    return null;
  };
  const onSlotPointerMove = (e: React.PointerEvent) => {
    if (internalDragIdx == null) return;
    const hit = findSlotAtPoint(e.clientX, e.clientY);
    if (hit != null && hit !== internalHoverIdx) setInternalHoverIdx(hit);
  };
  const onSlotPointerUp = (e: React.PointerEvent) => {
    if (internalDragIdx == null) return;
    const hit = findSlotAtPoint(e.clientX, e.clientY);
    if (hit != null && hit !== internalDragIdx) {
      reorderDockSlot(internalDragIdx, hit);
      hapticSuccess();
      playPop();
      setPulse(hit);
      setTimeout(() => setPulse(null), 500);
    }
    setInternalDragIdx(null);
    setInternalHoverIdx(null);
  };

  const handleSlotTap = (appId: string) => {
    // Drag-lock: when in Jiggle Mode, tapping a slot must NEVER navigate.
    if (editing || longFiredRef.current) return;
    playTick();
    hapticTap();
    if (onAppTap?.(appId)) return;
    const app = HUB_APPS_BY_ID[appId];
    if (!app) return;
    navigate({ to: app.to });
  };

  const handleDrop = (slotIdx: number, e: React.DragEvent) => {
    e.preventDefault();
    const droppedAppId = e.dataTransfer.getData("application/x-jiyan-app-id");
    if (!droppedAppId || !HUB_APPS_BY_ID[droppedAppId]) return;
    setDockSlot(slotIdx, droppedAppId);
    setDragOver(null);
    setPulse(slotIdx);
    playPop();
    hapticSuccess();
    setTimeout(() => setPulse(null), 600);
  };

  const exitEditing = () => {
    hapticMedium();
    setEditing(false);
    setActionSlot(null);
  };

  /** Replace slot with a sensible fallback so the dock never goes empty. */
  const removeSlot = (slotIdx: number) => {
    const used = new Set(dockSlots);
    const fallback =
      FALLBACK_SUGGESTIONS.find((id) => !used.has(id)) ??
      Object.keys(HUB_APPS_BY_ID).find((id) => !used.has(id)) ??
      "deng";
    setDockSlot(slotIdx, fallback);
    hapticSuccess();
    playPop();
    setActionSlot(null);
  };

  /** Swap with the slot to the left (or wrap to the end). */
  const moveSlotLeft = (slotIdx: number) => {
    const target = (slotIdx - 1 + 4) % 4;
    setDockSlot(target, dockSlots[slotIdx]);
    hapticMedium();
    playTick();
    setActionSlot(null);
  };

  /** Swap with the slot to the right (or wrap to the start). */
  const moveSlotRight = (slotIdx: number) => {
    const target = (slotIdx + 1) % 4;
    setDockSlot(target, dockSlots[slotIdx]);
    hapticMedium();
    playTick();
    setActionSlot(null);
  };


  return (
    <>
      <nav
        aria-label="Sovereign Dynamic Dock"
        data-sovereign-dock
        data-testid="sovereign-dynamic-dock"
        className="fixed left-1/2 z-40 -translate-x-1/2"
        style={{
          bottom: "calc(env(safe-area-inset-bottom, 0px) + 18px)",
        }}
      >
        {/* Outer breathing accent halo (themed) */}
        <span
          aria-hidden
          className="pointer-events-none absolute inset-0 rounded-[34px]"
          style={{
            boxShadow: editing
              ? `0 0 38px color-mix(in oklab, ${theme.accent} 75%, transparent), 0 0 80px color-mix(in oklab, ${theme.accent} 40%, transparent)`
              : `0 0 24px color-mix(in oklab, ${theme.accent} 30%, transparent), 0 0 56px color-mix(in oklab, ${theme.accent} 16%, transparent)`,
            transition: "box-shadow 300ms ease",
          }}
        />

        {/* Pill body — Apple-tier translucent frosted glass with themed hairline */}
        <div
          className="relative flex items-stretch gap-3 px-4 py-3"
          style={{
            borderRadius: "34px",
            background:
              "linear-gradient(180deg, rgba(40,32,18,0.32) 0%, rgba(8,6,2,0.55) 100%)",
            backdropFilter: "blur(60px) saturate(200%)",
            WebkitBackdropFilter: "blur(60px) saturate(200%)",
            border: `0.75px solid color-mix(in oklab, ${theme.accent} 50%, transparent)`,
            boxShadow: [
              "0 18px 44px -12px rgba(0,0,0,0.85)",
              "inset 0 1px 0 rgba(255,234,170,0.28)",
              "inset 0 -1px 0 rgba(0,0,0,0.6)",
            ].join(", "),
          }}
        >
          {dockSlots.map((appId, idx) => {
            const app = HUB_APPS_BY_ID[appId];
            if (!app) return null;
            const Icon = app.icon;
            const isProfile = app.id === "profile";
            const isOver = dragOver === idx;
            const isPulse = pulse === idx;
            const isInternalHover =
              internalDragIdx != null &&
              internalHoverIdx === idx &&
              internalDragIdx !== idx;
            const isInternalDragging = internalDragIdx === idx;

            return (
              <button
                key={`${idx}-${appId}`}
                ref={(el) => {
                  if (el) slotRefs.current.set(idx, el);
                  else slotRefs.current.delete(idx);
                }}
                type="button"
                data-testid={`dock-slot-${idx}`}
                aria-label={`${app.label} (Slot ${idx + 1})`}
                onClick={() => handleSlotTap(appId)}
                onPointerDown={(e) => {
                  startLongPress(idx);
                  // In jiggle mode, a pointer-down on a slot also begins
                  // an intra-dock reorder drag.
                  if (editing && !isFlowLocked()) {
                    setInternalDragIdx(idx);
                    setInternalHoverIdx(idx);
                    (e.currentTarget as Element).setPointerCapture?.(e.pointerId);
                  }
                }}
                onPointerMove={onSlotPointerMove}
                onPointerUp={(e) => {
                  cancelLongPress();
                  onSlotPointerUp(e);
                }}
                onPointerCancel={(e) => {
                  cancelLongPress();
                  onSlotPointerUp(e);
                }}
                onPointerLeave={cancelLongPress}
                onDragOver={(e) => {
                  e.preventDefault();
                  e.dataTransfer.dropEffect = "move";
                  setDragOver(idx);
                }}
                onDragLeave={() => setDragOver((v) => (v === idx ? null : v))}
                onDrop={(e) => handleDrop(idx, e)}
                className={`relative flex items-center justify-center overflow-hidden ${
                  editing ? "animate-[jiggle_0.4s_ease-in-out_infinite]" : ""
                }`}
                style={{
                  width: SLOT_SIZE,
                  height: SLOT_SIZE,
                  borderRadius: SLOT_RADIUS,
                  pointerEvents: "auto",
                  opacity: isInternalDragging ? 0.45 : 1,
                  transform: isInternalHover ? "scale(0.92)" : undefined,
                  // Uniform Premium Dark Glass — identical for all 4 slots.
                  background: isOver || isInternalHover
                    ? `linear-gradient(180deg, color-mix(in oklab, ${theme.accent} 35%, rgba(255,255,255,0.08)), rgba(255,255,255,0.06))`
                    : "linear-gradient(180deg, rgba(255,255,255,0.10) 0%, rgba(255,255,255,0.04) 100%)",
                  backdropFilter: "blur(24px) saturate(160%)",
                  WebkitBackdropFilter: "blur(24px) saturate(160%)",
                  boxShadow: [
                    "inset 0 0.5px 0 rgba(255,255,255,0.22)",
                    "inset 0 -0.5px 0 rgba(0,0,0,0.45)",
                    isOver || isInternalHover
                      ? `0 0 18px color-mix(in oklab, ${theme.accent} 70%, transparent)`
                      : "0 4px 12px -2px rgba(0,0,0,0.55)",
                    isPulse ? `0 0 26px ${theme.accent}` : "",
                  ]
                    .filter(Boolean)
                    .join(", "),
                  transition:
                    "transform 220ms cubic-bezier(0.34, 1.56, 0.64, 1), background 180ms, box-shadow 180ms, opacity 180ms",
                  animationDelay: `${idx * 0.04}s`,
                  touchAction: editing ? "none" : "manipulation",
                }}
              >
                {/* Top gloss — keeps the frosted-glass highlight subtle */}
                <span
                  aria-hidden
                  className="absolute inset-x-0 top-0 h-1/2 pointer-events-none"
                  style={{
                    background:
                      "linear-gradient(180deg, rgba(255,255,255,0.18) 0%, rgba(255,255,255,0.04) 60%, transparent 100%)",
                  }}
                />
                {isProfile && profile?.avatarUrl ? (
                  <img
                    src={profile.avatarUrl}
                    alt=""
                    className="relative rounded-full object-cover"
                    style={{
                      width: 30,
                      height: 30,
                      boxShadow: `0 0 0 1.5px color-mix(in oklab, ${theme.accent} 70%, transparent)`,
                    }}
                  />
                ) : (
                  <Icon
                    className="relative"
                    strokeWidth={1.9}
                    style={{
                      width: 28,
                      height: 28,
                      color: GOLD_LIGHT,
                      filter:
                        "drop-shadow(0 1px 1px rgba(0,0,0,0.85))",
                    }}
                  />
                )}
              </button>
            );
          })}
        </div>
      </nav>

      {/* "Bitti" pill — appears above the dock while in Jiggle Mode */}
      {editing && (
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            exitEditing();
          }}
          aria-label="Düzenlemeyi bitir"
          className="fixed left-1/2 z-50 -translate-x-1/2 flex items-center gap-1 rounded-full px-4 h-10 text-xs font-semibold active:scale-95 transition-transform"
          style={{
            bottom: "calc(env(safe-area-inset-bottom, 0px) + 110px)",
            background: "linear-gradient(180deg,#3a2807,#1a1003)",
            color: GOLD_LIGHT,
            border: "1px solid rgba(245,205,83,0.6)",
            boxShadow: "0 10px 26px -8px rgba(0,0,0,0.9)",
          }}
        >
          <Check className="h-3.5 w-3.5" /> Bitti
        </button>
      )}

      {/* Slot Quick Actions sheet — long-press a slot in Jiggle Mode */}
      {actionSlot !== null && (() => {
        const idx = actionSlot;
        const app = HUB_APPS_BY_ID[dockSlots[idx]];
        if (!app) return null;
        return (
          <div
            data-sovereign-dock
            className="fixed inset-0 z-[60] flex items-end justify-center"
            onClick={() => setActionSlot(null)}
          >
            <div
              aria-hidden
              className="absolute inset-0 bg-black/45 backdrop-blur-[6px]"
            />
            <div
              role="dialog"
              aria-label={`${app.label} — Hızlı eylemler`}
              data-testid="dock-quick-actions"
              onClick={(e) => e.stopPropagation()}
              className="relative w-[min(360px,90vw)] mb-[140px] rounded-3xl overflow-hidden"
              style={{
                background: "linear-gradient(180deg, rgba(40,30,10,0.92) 0%, rgba(8,6,2,0.96) 100%)",
                border: "0.75px solid rgba(245,205,83,0.45)",
                boxShadow: "0 30px 60px -10px rgba(0,0,0,0.85), inset 0 1px 0 rgba(255,234,170,0.25)",
                backdropFilter: "blur(40px) saturate(180%)",
                WebkitBackdropFilter: "blur(40px) saturate(180%)",
              }}
            >
              <div className="px-5 pt-4 pb-3 text-center">
                <p className="text-[11px] uppercase tracking-widest" style={{ color: "rgba(255,234,170,0.55)" }}>
                  Slot {idx + 1}
                </p>
                <p className="text-[15px] font-semibold mt-0.5" style={{ color: GOLD_LIGHT }}>
                  {app.label}
                </p>
              </div>

              <ActionRow
                label="Sola Taşı"
                disabled={idx === 0}
                onClick={() => moveSlotLeft(idx)}
              />
              <ActionRow
                label="Sağa Taşı"
                disabled={idx === 3}
                onClick={() => moveSlotRight(idx)}
              />
              <ActionRow
                label="Slottan Çıkar"
                destructive
                onClick={() => removeSlot(idx)}
              />
              <ActionRow
                label="Vazgeç"
                muted
                onClick={() => {
                  hapticTap();
                  setActionSlot(null);
                }}
              />
            </div>
          </div>
        );
      })()}
    </>
  );
}

function ActionRow({
  label,
  onClick,
  destructive,
  muted,
  disabled,
}: {
  label: string;
  onClick: () => void;
  destructive?: boolean;
  muted?: boolean;
  disabled?: boolean;
}) {
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      className="w-full text-center text-[15px] font-medium px-5 py-3.5 border-t transition-colors active:bg-white/5 disabled:opacity-40 disabled:active:bg-transparent"
      style={{
        borderColor: "rgba(245,205,83,0.18)",
        color: destructive ? "#FF6B6B" : muted ? "rgba(255,234,170,0.65)" : GOLD_LIGHT,
        fontWeight: muted ? 600 : 500,
      }}
    >
      {label}
    </button>
  );
}

