/**
 * ThemeBridge — Apply the active Hub theme globally.
 *
 * Reads the user's selected Görünüm theme + customisation sliders and
 * pushes them onto `:root` as CSS variables. Existing semantic tokens
 * (`--background`, `--card`, `--primary`, `--gold`, …) are remapped so
 * any screen (marketplace, orders, chat, profile, settings) instantly
 * re-skins to match the chosen Sovereign theme.
 *
 * Mounted once inside <AppShell/> so it covers every authenticated
 * route. Updates immediately on theme change because both useHubTheme
 * and useHubPreferences re-render via their event bus / state.
 */
import { useEffect } from "react";
import { useHubTheme } from "@/hooks/useHubTheme";
import { useHubPreferences } from "@/hooks/useHubPreferences";

export function ThemeBridge() {
  const { theme } = useHubTheme();
  const { prefs } = useHubPreferences();

  useEffect(() => {
    if (typeof document === "undefined") return;
    const root = document.documentElement;

    // ── Page canvas + foreground ────────────────────────────────────
    // We can't put a gradient into an oklch() var, so we expose both:
    //   --background              → flat solid for tokens needing a color
    //   --hub-page-bg             → the actual decorative gradient
    root.style.setProperty("--hub-page-bg", theme.pageBg);
    root.style.setProperty("--hub-surface-bg", theme.surfaceBg);
    root.style.setProperty("--hub-surface-bg-strong", theme.surfaceBgStrong);
    root.style.setProperty("--hub-border", theme.border);
    root.style.setProperty("--hub-border-strong", theme.borderStrong);
    root.style.setProperty("--hub-tile-shadow", theme.tileShadow);
    root.style.setProperty("--hub-hero-shadow", theme.heroShadow);
    root.style.setProperty("--hub-accent", theme.accent);
    root.style.setProperty("--hub-text-primary", theme.textPrimary);
    root.style.setProperty("--hub-text-muted", theme.textMuted);
    root.style.setProperty("--hub-text-faint", theme.textFaint);
    root.style.setProperty("--hub-icon-color", theme.iconColor);
    root.style.setProperty("--hub-icon-glow", theme.iconGlow);
    root.style.setProperty("--hub-pill-bg", theme.pillBg);

    // ── Customisation sliders → CSS multipliers ─────────────────────
    root.style.setProperty(
      "--hub-gold-intensity",
      prefs.goldIntensity.toFixed(2),
    );
    root.style.setProperty(
      "--hub-bg-depth",
      prefs.backgroundDepth.toFixed(2),
    );
    root.style.setProperty(
      "--hub-tile-alpha",
      prefs.tileTransparency.toFixed(2),
    );
    root.style.setProperty(
      "--hub-icon-scale",
      prefs.iconScale.toFixed(2),
    );

    // ── Atmosphere flag (used by global background) ─────────────────
    root.dataset.hubTheme = theme.id;
    root.dataset.hubAtmosphere = theme.atmosphere;

    // Paint the body so screens without an explicit background
    // (chat, orders, marketplace lists) inherit the theme.
    document.body.style.background = theme.pageBg;
    document.body.style.color = theme.textPrimary;
  }, [
    theme,
    prefs.goldIntensity,
    prefs.backgroundDepth,
    prefs.tileTransparency,
    prefs.iconScale,
  ]);

  return null;
}

