/**
 * UserWidgetGrid — Premium Sovereign widget panel.
 *
 * Layout:
 *   • TOP: Master AtmosphereWidget (full-width, fixed) — clock, date, weather
 *   • BELOW: Strict 2-column grid of user-selected widgets, all forced to a
 *     uniform "medium" tile so the panel never looks empty and heights stay
 *     aligned.
 *
 * Visual: ALL tiles inherit the active Görünüm theme via CSS vars
 * (`--hub-surface-bg-strong`, `--hub-border-strong`, `--hub-accent`,
 * `--hub-text-primary`, `--hub-text-muted`, `--hub-text-faint`,
 * `--hub-tile-shadow`). Yeşil tema seçildiğinde TÜM widget'lar yeşile döner.
 *
 * `app_shortcut` widget'ları HUB_APPS'tan gelen herhangi bir mini-app için
 * generic kart sunar (icon + label + blurb).
 */
import {
  useWidgetPreferences,
  type WidgetPreference,
  type WidgetSize,
} from "@/hooks/useWidgetPreferences";
import { AtmosphereWidget } from "@/components/hub/widgets/AtmosphereWidget";
import { SovereignQuoteWidget } from "@/components/hub/widgets/SovereignQuoteWidget";
