const SIZE_CLASS: Record<WidgetSize, string> = {
  small: "col-span-1 min-h-[110px]",
  medium: "col-span-1 min-h-[150px]",
  large: "col-span-2 min-h-[170px]",
};

/** Theme-aware tile material — every widget shares the SAME look so the panel
 *  feels unified, and switches color whenever the user picks a Görünüm theme. */
const cardStyle = {
  background: "var(--hub-surface-bg-strong, rgba(28,20,5,0.85))",
  border: "var(--hub-border-strong, 1px solid rgba(245,205,83,0.45))",
  backdropFilter: "blur(18px) saturate(150%)",
  WebkitBackdropFilter: "blur(18px) saturate(150%)",
  boxShadow: "var(--hub-tile-shadow, 0 12px 32px -16px rgba(0,0,0,0.6))",
  color: "var(--hub-text-primary, #FFE9A8)",
} as const;

/** Tema rengini consumer'lara ortak vermek için inline style helper'ları. */
const accentStyle = { color: "var(--hub-accent, #F2C94C)" } as const;
const mutedStyle = { color: "var(--hub-text-muted, rgba(255,233,168,0.72))" } as const;
const faintStyle = { color: "var(--hub-text-faint, rgba(255,233,168,0.5))" } as const;

export function UserWidgetGrid() {
  const { prefs, loading } = useWidgetPreferences();

  /**
   * Sadece kullanıcının "Widget Düzenle" ekranından eklediği widget'lar
   * gösterilir. Hiç widget eklenmemişse panelde sadece üstteki AtmosphereWidget
   * kalır — sabit siyah default tile'lar artık çıkmaz.
   */
  const visiblePrefs = useMemo<WidgetPreference[]>(
    () => (prefs ?? []).slice().sort((a, b) => a.position - b.position),
    [prefs],
  );

  return (
    <div className="space-y-3">
      <AtmosphereWidget />
      {/* Hourly Sovereign Quote — Deng AI greets the user with wisdom that
          changes every hour and types itself out (streaming text). */}
      <SovereignQuoteWidget />
      {!loading && visiblePrefs.length > 0 && (
        <div className="grid grid-cols-2 gap-3 auto-rows-fr">
          {visiblePrefs.map((p) => (
            <UserWidgetCell key={p.id} pref={p} />
          ))}
        </div>
      )}
    </div>
  );
}

function UserWidgetCell({ pref }: { pref: WidgetPreference }) {
  const sizeClass = SIZE_CLASS[pref.size] ?? SIZE_CLASS.medium;
  const wrapperClass = `${sizeClass} relative overflow-hidden rounded-3xl p-4 active:scale-[0.99] transition-transform`;

  switch (pref.widget_type) {
    case "deng_latest":
      return <DengThoughtCard className={wrapperClass} />;
    case "wallet_balance":
      return <HazineCard className={wrapperClass} />;
    case "phone_recent":
      return <PhoneRecentCard className={wrapperClass} />;
    case "kurd_id":
      return <KurdIdCard className={wrapperClass} />;
    case "news_top":
      return <NewsTopCard className={wrapperClass} />;
    case "weather":
      return <WeatherMiniCard className={wrapperClass} />;
    case "feed_latest":
      return <FeedLatestCard className={wrapperClass} />;
    case "mail_inbox":
      return <MailInboxCard className={wrapperClass} />;
    case "linguist_progress":
      return <LinguistProgressCard className={wrapperClass} />;
    case "driving_exam":
      return <DrivingExamCard className={wrapperClass} />;
    case "compass_clock":
      return <CompassClockTile className={wrapperClass} />;
    case "now_playing":
