    case "app_shortcut":
      return <AppShortcutCard className={wrapperClass} appId={pref.config?.app_id as string} />;
    default:
      return null;
  }
}

/* ─────────── shared header used by every tile ─────────── */
function TileHeader({ icon: Icon, label }: { icon: LucideIcon; label: string }) {
