/* ───────────────────────── HAZINE — sparkline ───────────────────────── */

function HazineCard({ className }: { className: string }) {
  const { user } = useAuth();
  const { balance, lockedBalance, transactions } = useWallet(user?.id);
  const { open } = useAppSheet();

  const points = useMemo(() => {
    const txs = (transactions ?? []).slice(0, 14).reverse();
    if (txs.length === 0) return [4, 6, 5, 8, 7, 9, 6];
    let running = 0;
    const vals = txs.map((t) => {
      running += Number(t.amount) || 0;
      return running;
    });
    const min = Math.min(...vals);
    const max = Math.max(...vals);
    const range = max - min || 1;
    return vals.slice(-7).map((v) => 1 + ((v - min) / range) * 9);
  }, [transactions]);

  const path = useMemo(() => {
    const w = 100;
    const h = 26;
    const step = w / (points.length - 1 || 1);
    return points
      .map(
        (v, i) =>
          `${i === 0 ? "M" : "L"} ${(i * step).toFixed(1)} ${(h - (v / 10) * h).toFixed(1)}`,
      )
      .join(" ");
  }, [points]);

  return (
    <button
      type="button"
      onClick={() => open("wallet")}
      className={`text-left ${className}`}
      style={cardStyle}
    >
      <TileHeader icon={Coins} label="Hazine" />
      <div className="mt-2 text-3xl font-light tabular-nums leading-none">
        {(balance ?? 0).toFixed(2)}
        <span className="text-xs ml-1" style={accentStyle}>
          DC
        </span>
      </div>
      <p className="text-[10px] mt-1" style={faintStyle}>
        Kilitli {(lockedBalance ?? 0).toFixed(2)}
      </p>
      <svg
        viewBox="0 0 100 26"
        preserveAspectRatio="none"
        className="absolute bottom-3 right-3 left-3 h-7 w-[calc(100%-24px)]"
        aria-hidden
      >
        <path
          d={`${path} L 100 26 L 0 26 Z`}
          fill="currentColor"
          style={{ color: "var(--hub-accent)", opacity: 0.18 }}
        />
        <path
          d={path}
          fill="none"
          stroke="currentColor"
          style={accentStyle}
          strokeWidth="1.4"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </button>
  );
}

/* ─────────────────── PHONE — last 3 P2P calls ─────────────────── */

function PhoneRecentCard({ className }: { className: string }) {
  const { user } = useAuth();
  const { messages } = useDengBot(user?.id);
  const navigate = useNavigate();
  const [localCalls, setLocalCalls] = useState<LocalPhoneRecent[]>(() => readLocalPhoneRecent());
  useEffect(() => {
    const refresh = () => setLocalCalls(readLocalPhoneRecent());
    window.addEventListener(PHONE_RECENT_EVENT, refresh);
    window.addEventListener("storage", refresh);
    return () => {
      window.removeEventListener(PHONE_RECENT_EVENT, refresh);
      window.removeEventListener("storage", refresh);
    };
  }, []);
  const botCalls = (messages ?? [])
    .filter((m) => m.bot_kind === "call_log")
    .map((m) => ({ id: m.id, title: m.subject, at: m.created_at }));
  const calls = [
    ...localCalls.map((c) => ({ id: c.id, title: `${c.status} · ${c.kurdId}`, at: c.createdAt })),
    ...botCalls,
  ].slice(0, 3);

  return (
    <button
      type="button"
      onClick={() => navigate({ to: "/phone" })}
      className={`text-left ${className}`}
      style={cardStyle}
    >
      <TileHeader icon={Phone} label="Son Aramalar" />
