/* ─────────────────── LINGUIST PROGRESS ─────────────────── */

function LinguistProgressCard({ className }: { className: string }) {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [streak, setStreak] = useState<number>(0);
  const [minutes, setMinutes] = useState<number>(0);

  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    (async () => {
      try {
        const today = new Date().toISOString().slice(0, 10);
        const [{ data: s }, { data: t }] = await Promise.all([
          supabase
            .from("linguist_settings")
            .select("current_streak")
            .eq("user_id", user.id)
            .maybeSingle(),
          supabase
            .from("linguist_study_sessions")
            .select("minutes_studied")
            .eq("user_id", user.id)
            .eq("session_date", today)
            .maybeSingle(),
        ]);
        if (!cancelled) {
          setStreak((s as { current_streak?: number } | null)?.current_streak ?? 0);
          setMinutes((t as { minutes_studied?: number } | null)?.minutes_studied ?? 0);
        }
      } catch {
        /* ignore */
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [user]);

  return (
    <button
      type="button"
      onClick={() => navigate({ to: "/linguist" })}
      className={`text-left ${className}`}
      style={cardStyle}
    >
      <TileHeader icon={GraduationCap} label="Linguist" />
      <p className="mt-3 text-3xl font-bold leading-none" style={accentStyle}>
        🔥 {streak}
      </p>
      <p className="mt-1 text-[11px]" style={mutedStyle}>
        {minutes} dk bugün · streak
      </p>
      <GraduationCap
        className="absolute -bottom-3 -right-3 h-16 w-16 opacity-15"
        style={accentStyle}
        strokeWidth={1}
        aria-hidden
      />
    </button>
  );
}

/* ─────────────────── DRIVING EXAM ─────────────────── */

function DrivingExamCard({ className }: { className: string }) {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [score, setScore] = useState<number | null>(null);

  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    (async () => {
      try {
        const { data } = await supabase
          .from("driving_exam_sessions")
          .select("correct_answers, total_questions")
          .eq("user_id", user.id)
          .not("finished_at", "is", null)
          .order("started_at", { ascending: false })
          .limit(1)
          .maybeSingle();
        if (!cancelled && data) {
          const row = data as { correct_answers?: number; total_questions?: number };
          const total = row.total_questions ?? 0;
          const correct = row.correct_answers ?? 0;
          setScore(total > 0 ? Math.round((correct / total) * 100) : null);
        }
      } catch {
        if (!cancelled) setScore(null);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [user]);

  return (
    <button
      type="button"
      onClick={() => navigate({ to: "/driving-exam" })}
      className={`text-left ${className}`}
      style={cardStyle}
    >
      <TileHeader icon={Car} label="Ehliyet" />
      <p className="mt-3 text-3xl font-bold leading-none" style={accentStyle}>
        {score == null ? "—" : `${score}%`}
      </p>
      <p className="mt-1 text-[11px]" style={mutedStyle}>
        son deneme · CBR
      </p>
      <Car
        className="absolute -bottom-3 -right-3 h-16 w-16 opacity-15"
        style={accentStyle}
        strokeWidth={1}
        aria-hidden
      />
    </button>
  );
}

