      .map((id) => HUB_APPS_BY_ID[id])
      .filter((app) => app && (app.vividSection ?? "Toplum") === name)
      .map((app) => app.id),
  })).filter((s) => s.items.length > 0);
}

describe("VividSectionedGrid bucketing", () => {
  it("places the 12 core apps under their declared sections", () => {
    const sections = bucket([
      "deng",
      "pazar",
