/**
 * WidgetCustomizeSheet — iOS Today View "Edit Widgets" deneyimi.
 *
 * Yenilemeler:
 *   • TÜM mini-app'ler eklenebilir (rich widget'lar + 16 mini-app shortcut'ı).
 *   • Tema-uyumlu renkler — Görünüm değiştiğinde sheet de yeşil/mavi/altın olur.
 *   • Sürükle-bırak sıralama (@dnd-kit), arka grid canlı önizleme.
 *
 * Mobile-first (430×667): bottom-sheet, max 60vh.
 */
import { X, Plus, Minus, GripVertical } from "lucide-react";
import { useMemo } from "react";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  TouchSensor,
  KeyboardSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core";
import {
  SortableContext,
  arrayMove,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import {
  ALL_WIDGETS,
  prefCatalogKey,
  useWidgetPreferences,
  type WidgetCatalogEntry,
  type WidgetPreference,
  type WidgetSize,
  type WidgetType,
} from "@/hooks/useWidgetPreferences";

interface Props {
  open: boolean;
  onClose: () => void;
}

const SIZES: WidgetSize[] = ["small", "medium", "large"];
const SIZE_LABEL: Record<WidgetSize, string> = {
  small: "S",
  medium: "M",
  large: "L",
};

/** Tema-uyumlu inline style helpers (Görünüm değiştiğinde otomatik renk). */
const accentColor = "var(--hub-accent, #F2C94C)";
const textPrimary = "var(--hub-text-primary, #FFE9A8)";
const textMuted = "var(--hub-text-muted, rgba(255,233,168,0.72))";
const textFaint = "var(--hub-text-faint, rgba(255,233,168,0.5))";
const tileBg = "var(--hub-surface-bg, rgba(20,14,4,0.72))";
const sheetBg = "var(--hub-surface-bg-strong, rgba(10,7,3,0.95))";
const borderSoft = "var(--hub-border, 1px solid rgba(212,175,55,0.32))";
const borderStrong = "var(--hub-border-strong, 1px solid rgba(245,205,83,0.55))";

export function WidgetCustomizeSheet({ open, onClose }: Props) {
  const { prefs, add, addAppShortcut, remove, reorder, setSize, clearAll } =
    useWidgetPreferences();

  const installedKeys = useMemo(
    () => new Set((prefs ?? []).map(prefCatalogKey)),
    [prefs],
  );
  const activePrefs = prefs ?? [];
  const available = ALL_WIDGETS.filter((w) => !installedKeys.has(w.key));

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(TouchSensor, { activationConstraint: { delay: 120, tolerance: 6 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );

  if (!open) return null;

  const handleDragEnd = async (e: DragEndEvent) => {
    const { active, over } = e;
    if (!over || !prefs || active.id === over.id) return;
    const oldIdx = activePrefs.findIndex((p) => p.id === active.id);
    const newIdx = activePrefs.findIndex((p) => p.id === over.id);
    if (oldIdx < 0 || newIdx < 0) return;
    const reordered = arrayMove(activePrefs, oldIdx, newIdx);
    await reorder(reordered.map((p) => p.id));
  };

  const handleAdd = async (entry: WidgetCatalogEntry) => {
    if (entry.appId) {
      await addAppShortcut(entry.appId);
    } else {
      await add(entry.type as WidgetType);
    }
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      className="fixed inset-0 z-[1100] flex items-end justify-center pointer-events-none"
    >
      <button
        type="button"
        aria-label="Kapat"
        onClick={onClose}
        className="absolute inset-0 pointer-events-auto bg-black/30 backdrop-blur-[2px] animate-fade-in"
      />
      <div
        className="relative pointer-events-auto w-full sm:max-w-md mx-auto sm:rounded-3xl rounded-t-[28px]
                   p-5 pb-7 max-h-[60vh] overflow-y-auto"
        style={{
          background: sheetBg,
          border: borderStrong,
          boxShadow: "var(--hub-hero-shadow, 0 -30px 80px -10px rgba(0,0,0,0.6))",
          color: textPrimary,
          animationName: "hub-sheet-up",
          animationDuration: "320ms",
        }}
      >
        <div
          className="flex sm:hidden justify-center mb-3 sticky top-0 -mt-5 pt-3 pb-2 -mx-5 px-5 z-10"
          style={{
            background: `linear-gradient(180deg, ${sheetBg}, transparent)`,
          }}
        >
          <span
            className="block h-1 w-10 rounded-full"
            style={{ background: accentColor, opacity: 0.45 }}
          />
        </div>
        <div className="flex items-center justify-between mb-4 gap-2">
          <div className="min-w-0">
            <h2 className="text-base font-semibold" style={{ color: textPrimary }}>
              Widget'ları Düzenle
            </h2>
            <p className="text-[11px]" style={{ color: textMuted }}>
              Sürükleyip bırak · değişiklik yukarıda canlı görünür
            </p>
          </div>
          <div className="flex items-center gap-1 flex-shrink-0">
            {activePrefs.length > 0 && (
              <button
                type="button"
                onClick={() => clearAll()}
                className="rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider hover:bg-red-500/10"
                style={{ color: "rgb(252,165,165)", border: "1px solid rgba(252,165,165,0.35)" }}
              >
                Tümünü Kaldır
              </button>
            )}
            <button
              type="button"
              onClick={onClose}
              className="rounded-full p-1.5 hover:bg-white/5"
              style={{ color: textMuted }}
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* Installed list — sortable */}
        {activePrefs.length > 0 && (
          <div className="space-y-2">
            <p
              className="text-[10px] uppercase tracking-[0.2em]"
              style={{ color: textFaint }}
            >
              Aktif · {activePrefs.length}
            </p>
            <DndContext
              sensors={sensors}
              collisionDetection={closestCenter}
              onDragEnd={handleDragEnd}
            >
              <SortableContext
                items={activePrefs.map((p) => p.id)}
                strategy={verticalListSortingStrategy}
              >
                {activePrefs.map((p) => (
                  <SortableWidgetRow
                    key={p.id}
                    pref={p}
                    onRemove={() => remove(p.id)}
                    onSize={(s) => setSize(p.id, s)}
                  />
                ))}
              </SortableContext>
            </DndContext>
          </div>
        )}

        {/* Available */}
        {available.length > 0 && (
          <div className="mt-5">
            <p
              className="text-[10px] uppercase tracking-[0.2em] mb-2"
              style={{ color: textFaint }}
            >
              Eklenebilir
            </p>
            <div className="grid grid-cols-2 gap-2">
              {available.map((w) => (
                <button
                  key={w.key}
                  type="button"
                  onClick={() => handleAdd(w)}
                  className="flex items-center gap-2 rounded-2xl p-2.5 transition-colors hover:opacity-90"
                  style={{ background: tileBg, border: borderSoft, color: textPrimary }}
                >
                  <span className="text-lg">{w.emoji}</span>
                  <span className="flex-1 text-left text-sm truncate">{w.label}</span>
                  <Plus className="h-3.5 w-3.5" style={{ color: accentColor }} />
                </button>
              ))}
            </div>
          </div>
        )}

        {available.length === 0 && (!prefs || prefs.length === 0) && (
          <p className="text-center text-xs py-6" style={{ color: textMuted }}>
            Henüz seçim yok — yukarıdaki kataloğdan widget ekle.
          </p>
        )}
      </div>
    </div>
  );
}

/* ─────────────── Sortable row ─────────────── */

function SortableWidgetRow({
  pref,
  onRemove,
  onSize,
}: {
  pref: WidgetPreference;
  onRemove: () => void;
  onSize: (s: WidgetSize) => void;
}) {
  const meta = ALL_WIDGETS.find((w) => w.key === prefCatalogKey(pref));
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: pref.id });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.6 : 1,
    zIndex: isDragging ? 50 : "auto",
    background: isDragging
      ? "color-mix(in oklab, var(--hub-accent) 15%, transparent)"
      : tileBg,
    border: isDragging ? borderStrong : borderSoft,
    color: textPrimary,
    boxShadow: isDragging ? "var(--hub-hero-shadow)" : undefined,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className="flex items-center gap-2 rounded-2xl p-2.5"
    >
      <button
        type="button"
        className="touch-none cursor-grab active:cursor-grabbing rounded-md p-1 hover:bg-white/5"
        aria-label="Sürükle"
        style={{ color: textMuted }}
        {...attributes}
        {...listeners}
      >
        <GripVertical className="h-4 w-4" />
      </button>
      <span className="text-lg">{meta?.emoji ?? "▫️"}</span>
      <span className="flex-1 text-sm truncate">{meta?.label ?? pref.widget_type}</span>
      {/* Size chips */}
      <div className="flex gap-1">
        {SIZES.map((s) => (
          <button
            key={s}
            type="button"
            onClick={() => onSize(s)}
            className="h-6 w-6 rounded-md text-[10px] font-semibold transition-colors"
            style={
              pref.size === s
                ? { background: accentColor, color: "#000" }
                : {
                    background: "color-mix(in oklab, var(--hub-accent) 12%, transparent)",
                    color: textMuted,
                  }
            }
          >
            {SIZE_LABEL[s]}
          </button>
        ))}
      </div>
      <button
        type="button"
        onClick={onRemove}
        className="rounded-full p-1 hover:bg-red-500/10"
        style={{ color: "rgb(252,165,165)" }}
        aria-label="Kaldır"
      >
        <Minus className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}

