/**
 * AtmosphereWidget — Master full-width hero widget at the top of the user
 * widget panel. Combines:
 *   • Live digital clock (HH:MM, ticks every 30s)
 *   • Sovereign-style date (Newroz year + gregorian)
 *   • Real-time weather via Open-Meteo + browser geolocation
 *
 * Visual: deep glass-black with golden accents, full-width, no row siblings.
 */
import { useEffect, useState } from "react";
import { Cloud, CloudRain, Sun, CloudSnow, MapPin, Moon } from "lucide-react";
import { useHubPreferences } from "@/hooks/useHubPreferences";
import { useStreamingText } from "@/hooks/useStreamingText";
import { useRitualClock } from "@/hooks/useRitualClock";
import { PRAYER_LABELS_TR } from "@/lib/ritualTimes";

interface Weather {
  tempC: number;
  code: number;
  city: string;
}

const ICON = (code: number) => {
  if (code === 0 || code === 1) return Sun;
  if (code >= 51 && code <= 67) return CloudRain;
  if (code >= 71 && code <= 86) return CloudSnow;
  return Cloud;
};

const CITY_PRESETS = [
  { label: "Hewlêr", lat: 36.19, lon: 44.0 },
  { label: "Amed", lat: 37.91, lon: 40.23 },
  { label: "Van", lat: 38.5, lon: 43.38 },
  { label: "Qamişlo", lat: 37.05, lon: 41.22 },
  { label: "Arnhem", lat: 51.98, lon: 5.91 },
  { label: "Berlin", lat: 52.52, lon: 13.41 },
];

const DEFAULT_CITY = CITY_PRESETS[0];

async function reverseGeocode(lat: number, lon: number) {
  try {
    const r = await fetch(
      `https://geocoding-api.open-meteo.com/v1/reverse?latitude=${lat}&longitude=${lon}&count=1&language=en`,
    );
    const j = await r.json();
    return j?.results?.[0]?.name ?? "Konum";
  } catch {
    return "Konum";
  }
}

async function fetchWeather(lat: number, lon: number) {
  const r = await fetch(
    `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,weather_code`,
  );
  const j = await r.json();
  return {
    tempC: Math.round(j.current.temperature_2m),
    code: j.current.weather_code,
  };
}

export function AtmosphereWidget() {
  const { prefs, setWeather } = useHubPreferences();
  const [now, setNow] = useState(() => new Date());
  const [wx, setWx] = useState<Weather | null>(null);

  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 30_000);
    return () => clearInterval(id);
  }, []);

  useEffect(() => {
    let cancelled = false;
    const useCoords = async (lat: number, lon: number, city: string) => {
      try {
        const w = await fetchWeather(lat, lon);
        if (!cancelled) setWx({ ...w, city });
      } catch {}
    };

    const selectedCity =
      prefs.weatherLat != null && prefs.weatherLon != null
        ? { lat: prefs.weatherLat, lon: prefs.weatherLon, label: prefs.weatherLabel ?? "Seçili şehir" }
        : DEFAULT_CITY;

    if (prefs.weatherLat != null && prefs.weatherLon != null) {
      useCoords(selectedCity.lat, selectedCity.lon, selectedCity.label);
      return () => {
        cancelled = true;
      };
    }

    if (typeof navigator !== "undefined" && navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        async (pos) => {
          const lat = pos.coords.latitude;
          const lon = pos.coords.longitude;
          const city = await reverseGeocode(lat, lon);
          if (cancelled) return;
          setWeather(lat, lon, city);
          useCoords(lat, lon, city);
        },
        () => useCoords(selectedCity.lat, selectedCity.lon, selectedCity.label),
        { timeout: 5000 },
      );
    } else {
      useCoords(selectedCity.lat, selectedCity.lon, selectedCity.label);
    }
    return () => {
      cancelled = true;
    };
  }, [prefs.weatherLat, prefs.weatherLon, prefs.weatherLabel, setWeather]);

  const hh = String(now.getHours()).padStart(2, "0");
  const mm = String(now.getMinutes()).padStart(2, "0");
  // Sovereign Calendar: Newroz year = Gregorian + 700 (cultural offset, ~2725 in 2025)
  const newrozYear = now.getFullYear() + 700;
  const dateStr = now.toLocaleDateString("tr-TR", {
    weekday: "long",
    day: "numeric",
    month: "long",
  });
  const Icon = wx ? ICON(wx.code) : Cloud;
  const selectedPresetLabel = CITY_PRESETS.some((city) => city.label === prefs.weatherLabel)
    ? prefs.weatherLabel!
    : DEFAULT_CITY.label;
  // Streaming reveal — re-streams whenever the date string changes (once per day),
  // and whenever a new city resolves. Makes the OS feel "live".
  const dateStreamed = useStreamingText(dateStr, 40);
  const cityStreamed = useStreamingText(wx?.city ?? "", 40);
  const ritual = useRitualClock();

  return (
    <div
      className="relative w-full overflow-hidden rounded-[20px] px-5 py-3.5"
      style={{
        background:
          "linear-gradient(180deg, rgba(14,10,4,0.78) 0%, rgba(8,6,2,0.86) 100%)",
        border: ritual.glow
          ? "1px solid rgba(255,215,90,0.95)"
          : "1px solid rgba(212,175,55,0.32)",
        backdropFilter: "blur(28px) saturate(180%)",
        WebkitBackdropFilter: "blur(28px) saturate(180%)",
        boxShadow: ritual.glow
          ? "0 0 0 1px rgba(255,215,90,0.5), 0 0 32px rgba(212,175,55,0.55), 0 12px 32px -18px rgba(0,0,0,0.7)"
          : "0 1px 0 rgba(255,232,160,0.06) inset, 0 12px 32px -18px rgba(0,0,0,0.7)",
        color: "#F5E6B8",
        transition: "border-color 600ms ease, box-shadow 600ms ease",
      }}
    >
      {/* hairline gold accent at top */}
      <span
        aria-hidden
        className="absolute inset-x-6 top-0 h-px"
        style={{
          background:
            "linear-gradient(90deg, transparent, rgba(212,175,55,0.65), transparent)",
        }}
      />
      <div className="flex items-center justify-between gap-3">
        {/* LEFT: time + date */}
        <div className="min-w-0">
          <div
            className="leading-none tabular-nums"
            style={{
              fontFamily:
                "'Cinzel', 'Inter', ui-sans-serif, system-ui, -apple-system",
              fontWeight: 200,
              fontSize: 36,
              letterSpacing: "0.04em",
              color: "#FFF6D9",
              textShadow: "0 0 12px rgba(212,175,55,0.18)",
            }}
          >
            {hh}
            <span className="mx-1" style={{ color: "rgba(212,175,55,0.85)" }}>
              :
            </span>
            {mm}
          </div>
          <div
            className="mt-1.5 text-[10px] capitalize truncate"
            style={{ color: "rgba(245,230,184,0.55)", letterSpacing: "0.04em" }}
          >
            {dateStreamed || "\u00A0"}
          </div>
          <div
            className="mt-0.5 text-[8.5px] uppercase truncate"
            style={{ color: "rgba(212,175,55,0.7)", letterSpacing: "0.32em" }}
          >
            Newroz · {newrozYear}
            {ritual.hijri ? ` · ${ritual.hijri}` : ""}
          </div>
        </div>

        {/* RIGHT: weather */}
        <div className="flex items-center gap-2.5 flex-shrink-0">
          <Icon
            className="h-5 w-5"
            strokeWidth={1.3}
            style={{
              color: "rgba(212,175,55,0.92)",
              filter: "drop-shadow(0 0 6px rgba(212,175,55,0.35))",
            }}
          />
          {wx && (
            <div className="flex flex-col items-end">
              <div
                className="text-xl tabular-nums leading-none"
                style={{ fontWeight: 200, color: "#FFF6D9" }}
              >
                {wx.tempC}°
              </div>
              <div
                className="mt-1 flex items-center gap-1 text-[9px]"
                style={{ color: "rgba(245,230,184,0.5)" }}
              >
                <MapPin className="h-2.5 w-2.5" />
                <span className="truncate max-w-[80px]">
                  {cityStreamed || wx.city}
                </span>
              </div>
            </div>
          )}
          <select
            value={selectedPresetLabel}
            onChange={(e) => {
              const city =
                CITY_PRESETS.find((c) => c.label === e.target.value) ??
                DEFAULT_CITY;
              setWeather(city.lat, city.lon, city.label);
            }}
            className="ml-1 rounded-full px-1.5 py-0.5 text-[9px] outline-none cursor-pointer"
            style={{
              background: "rgba(212,175,55,0.08)",
              border: "1px solid rgba(212,175,55,0.22)",
              color: "rgba(245,230,184,0.85)",
            }}
            aria-label="Şehir"
          >
            {CITY_PRESETS.map((city) => (
              <option key={city.label} value={city.label}>
                {city.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* RITUAL STRIP — next prayer + countdown, hairline gold separator */}
      {ritual.next && (
        <div
          className="mt-3 pt-2.5 flex items-center justify-between gap-2"
          style={{ borderTop: "1px solid rgba(212,175,55,0.18)" }}
        >
          <div className="flex items-center gap-2 min-w-0">
            <Moon
              className="h-3.5 w-3.5 flex-shrink-0"
              strokeWidth={1.4}
              style={{
                color: ritual.glow ? "#FFE89A" : "rgba(212,175,55,0.85)",
                filter: ritual.glow
                  ? "drop-shadow(0 0 8px rgba(255,232,154,0.9))"
                  : "drop-shadow(0 0 4px rgba(212,175,55,0.4))",
                animation: ritual.glow ? "pulse 1.2s ease-in-out infinite" : undefined,
              }}
            />
            <div className="min-w-0">
              <div
                className="text-[10px] uppercase truncate"
                style={{
                  color: "rgba(245,230,184,0.6)",
                  letterSpacing: "0.22em",
                }}
              >
                Sıradaki · {PRAYER_LABELS_TR[ritual.next.name]}
              </div>
            </div>
          </div>
          <div className="flex items-baseline gap-1.5 flex-shrink-0">
            <span
              className="tabular-nums text-[15px] leading-none"
              style={{
                fontWeight: 300,
                color: ritual.glow ? "#FFF6D9" : "#F5E6B8",
                textShadow: ritual.glow
                  ? "0 0 10px rgba(255,232,154,0.7)"
                  : undefined,
              }}
            >
              {ritual.nextAtHHMM}
            </span>
            <span
              className="tabular-nums text-[10px]"
              style={{ color: "rgba(212,175,55,0.75)" }}
            >
              · {ritual.countdown}
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

