  code: number;
  city: string;
}

const WEATHER_ICON = (code: number) => {
  if (code === 0 || code === 1) return Sun;
  if (code >= 51 && code <= 67) return CloudRain;
  if (code >= 71 && code <= 86) return CloudSnow;
  return Cloud;
};

async function reverseGeocode(lat: number, lon: number): Promise<string> {
  try {
    const r = await fetch(
      `https://geocoding-api.open-meteo.com/v1/reverse?latitude=${lat}&longitude=${lon}&count=1&language=en`,
    );
    const j = await r.json();
    return j?.results?.[0]?.name ?? "Konum";
  } catch {
    return "Konum";
  }
}

async function fetchWeather(lat: number, lon: number): Promise<Pick<Weather, "tempC" | "code">> {
  const r = await fetch(
    `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,weather_code`,
  );
  const j = await r.json();
  return { tempC: Math.round(j.current.temperature_2m), code: j.current.weather_code };
}

export function ClockWeatherWidget() {
  const { prefs, setWeather } = useHubPreferences();
  const { theme } = useHubTheme();
  const [now, setNow] = useState(() => new Date());
  const [weather, setWx] = useState<Weather | null>(null);

  // Tick every 30s
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 30_000);
    return () => clearInterval(id);
  }, []);

  // Weather init
  useEffect(() => {
    let cancelled = false;
    const useCoords = async (lat: number, lon: number, city: string) => {
      try {
        const w = await fetchWeather(lat, lon);
        if (!cancelled) setWx({ ...w, city });
      } catch {}
    };

    if (prefs.weatherLat != null && prefs.weatherLon != null) {
      useCoords(prefs.weatherLat, prefs.weatherLon, prefs.weatherLabel ?? "Konum");
      return () => {
        cancelled = true;
      };
    }

    if (typeof navigator !== "undefined" && navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        async (pos) => {
          const lat = pos.coords.latitude;
          const lon = pos.coords.longitude;
          const city = await reverseGeocode(lat, lon);
          if (cancelled) return;
          setWeather(lat, lon, city);
          useCoords(lat, lon, city);
        },
        () => {
          const lat = 36.19;
          const lon = 44.0;
          useCoords(lat, lon, "Hewlêr");
        },
        { timeout: 5000 },
      );
    } else {
      useCoords(36.19, 44.0, "Hewlêr");
    }

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const hh = String(now.getHours()).padStart(2, "0");
  const mm = String(now.getMinutes()).padStart(2, "0");
  const dateStr = now.toLocaleDateString("tr-TR", {
    weekday: "long",
    day: "numeric",
    month: "long",
  });
  const Icon = weather ? WEATHER_ICON(weather.code) : Cloud;

  return (
    <div
      className="relative col-span-3 rounded-3xl p-4 overflow-hidden"
      style={{
        background: theme.surfaceBg,
        backdropFilter: "blur(18px) saturate(160%)",
        WebkitBackdropFilter: "blur(18px) saturate(160%)",
        border: theme.border,
        boxShadow: theme.tileShadow,
      }}
    >
      <div className="flex items-start justify-between gap-3">
        <div>
          <div
            className="text-3xl font-light tracking-wider tabular-nums leading-none"
            style={{ color: theme.textPrimary }}
          >
            {hh}
            <span style={{ color: theme.accent }}>:</span>
            {mm}
          </div>
          <div
            className="mt-1.5 text-[11px] capitalize"
            style={{ color: theme.textMuted }}
          >
            {dateStr}
          </div>
        </div>
        <div className="flex flex-col items-end">
          <Icon
            className="h-7 w-7"
            strokeWidth={1.6}
            style={{ color: theme.accent, filter: theme.iconGlow }}
          />
          {weather && (
            <div
              className="mt-1 text-lg font-medium tabular-nums leading-none"
              style={{ color: theme.textPrimary }}
            >
              {weather.tempC}°
            </div>
          )}
        </div>
      </div>
      {weather && (
        <div
          className="mt-3 flex items-center gap-1 text-[10px]"
          style={{ color: theme.textFaint }}
        >
          <MapPin className="h-3 w-3" />
          <span>{weather.city}</span>
        </div>
      )}
    </div>
  );
}

