/**
 * CompassClockTile — kullanıcı tarafından eklenebilir / kaldırılabilir
 * standart boyutlu (medium / small / large) Pusula + Saat widget'ı.
 *
 * UserWidgetGrid'in cardStyle'ına uyacak şekilde tema değişkenlerini
 * (`--hub-accent`, `--hub-text-primary`, vb.) kullanır; sabit altın gradient
 * yerine grid'in geri kalanıyla aynı yüzeyi paylaşır. Tap → Pusula ↔ Saat.
 *
 * Gyro: iOS izin gerektirdiğinde mouse-parallax / küçük yön sallanmasıyla
 * fallback gösterir, yani widget hiçbir zaman ölü görünmez.
 */
import { useEffect, useRef, useState } from "react";
import { Compass } from "lucide-react";

const accentStyle = { color: "var(--hub-accent, #F2C94C)" } as const;
const mutedStyle = { color: "var(--hub-text-muted, rgba(255,233,168,0.72))" } as const;
const faintStyle = { color: "var(--hub-text-faint, rgba(255,233,168,0.5))" } as const;

interface Tilt { x: number; y: number; heading: number | null; }

export function CompassClockTile({ className }: { className: string }) {
  const [mode, setMode] = useState<"compass" | "clock">("compass");
  const [tilt, setTilt] = useState<Tilt>({ x: 0, y: 0, heading: null });
  const [now, setNow] = useState(() => new Date());
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (reduced) return;

    const handler = (e: DeviceOrientationEvent) => {
      const beta = e.beta ?? 0;
      const gamma = e.gamma ?? 0;
      const ny = Math.max(-1, Math.min(1, beta / 45));
      const nx = Math.max(-1, Math.min(1, gamma / 45));
      const heading =
        typeof (e as DeviceOrientationEvent & { webkitCompassHeading?: number })
          .webkitCompassHeading === "number"
          ? (e as DeviceOrientationEvent & { webkitCompassHeading?: number })
              .webkitCompassHeading!
          : typeof e.alpha === "number"
            ? 360 - e.alpha
            : null;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() => setTilt({ x: nx, y: ny, heading }));
    };

    type IOSReq = { requestPermission?: () => Promise<"granted" | "denied"> };
    const reqCtor = (window as unknown as { DeviceOrientationEvent?: IOSReq }).DeviceOrientationEvent;
    if (!reqCtor || typeof reqCtor.requestPermission !== "function") {
      window.addEventListener("deviceorientation", handler, true);
    }

    const onMouse = (e: MouseEvent) => {
      const nx = (e.clientX / window.innerWidth - 0.5) * 2;
      const ny = (e.clientY / window.innerHeight - 0.5) * 2;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() =>
        setTilt((p) => ({ x: nx, y: ny, heading: p.heading })),
      );
    };
    window.addEventListener("mousemove", onMouse, { passive: true });

    return () => {
      window.removeEventListener("deviceorientation", handler, true);
      window.removeEventListener("mousemove", onMouse);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const sec = now.getSeconds() + now.getMilliseconds() / 1000;
  const min = now.getMinutes() + sec / 60;
  const hr = (now.getHours() % 12) + min / 60;
  const secDeg = sec * 6;
  const minDeg = min * 6;
  const hrDeg = hr * 30;
  const needleDeg = tilt.heading != null ? -tilt.heading : tilt.x * 18;

  return (
    <button
      type="button"
      onClick={() => setMode((m) => (m === "compass" ? "clock" : "compass"))}
      className={`text-left ${className}`}
      style={{
        background: "var(--hub-surface-bg-strong, rgba(28,20,5,0.85))",
        border: "var(--hub-border-strong, 1px solid rgba(245,205,83,0.45))",
        backdropFilter: "blur(18px) saturate(150%)",
        WebkitBackdropFilter: "blur(18px) saturate(150%)",
        boxShadow: "var(--hub-tile-shadow, 0 12px 32px -16px rgba(0,0,0,0.6))",
        color: "var(--hub-text-primary, #FFE9A8)",
      }}
      aria-label="Pusula / Saat — dokun, modu değiştir"
    >
      <div className="flex items-center gap-2 text-[10px] uppercase tracking-[0.22em]" style={mutedStyle}>
        <Compass className="h-3 w-3" style={accentStyle} />
        {mode === "compass" ? "Pusula" : "Saat"}
      </div>

      {/* Compact dial — fits any tile size via aspect-square + 100% width */}
      <div className="relative mx-auto mt-2 w-full" style={{ aspectRatio: "1 / 1", maxWidth: 140 }}>
        <svg viewBox="0 0 200 200" className="absolute inset-0 h-full w-full" aria-hidden>
          {/* rim */}
          <circle cx="100" cy="100" r="92" fill="none" stroke="var(--hub-accent, #F2C94C)" strokeOpacity="0.55" strokeWidth="2" />
          <circle cx="100" cy="100" r="86" fill="rgba(0,0,0,0.35)" />

          {/* tick marks */}
          {Array.from({ length: 60 }).map((_, i) => {
            const angle = (i * 6 * Math.PI) / 180;
            const major = i % 5 === 0;
            const r1 = major ? 72 : 78;
            const r2 = 84;
            const x1 = 100 + Math.sin(angle) * r1;
            const y1 = 100 - Math.cos(angle) * r1;
            const x2 = 100 + Math.sin(angle) * r2;
            const y2 = 100 - Math.cos(angle) * r2;
            return (
              <line key={i} x1={x1} y1={y1} x2={x2} y2={y2}
                stroke="var(--hub-accent, #F2C94C)"
                strokeOpacity={major ? 0.9 : 0.4}
                strokeWidth={major ? 1.4 : 0.7}
                strokeLinecap="round" />
            );
          })}

          {mode === "compass" && (
            <g transform={`rotate(${needleDeg.toFixed(2)} 100 100)`}>
              <text x="100" y="36" textAnchor="middle" style={{ font: "600 11px ui-sans-serif", fill: "var(--hub-accent, #F2C94C)" }}>N</text>
              <text x="100" y="170" textAnchor="middle" style={{ font: "600 11px ui-sans-serif", fill: "var(--hub-accent, #F2C94C)" }}>S</text>
              <polygon points="100,44 106,100 100,108 94,100" fill="#ff5b3a" />
              <polygon points="100,156 106,100 100,92 94,100" fill="var(--hub-text-primary, #FFE9A8)" />
            </g>
          )}

          {mode === "clock" && (
            <g>
              <line x1="100" y1="100" x2="100" y2="58" stroke="var(--hub-text-primary, #FFE9A8)"
                strokeWidth="4" strokeLinecap="round" transform={`rotate(${hrDeg.toFixed(2)} 100 100)`} />
              <line x1="100" y1="100" x2="100" y2="42" stroke="var(--hub-accent, #F2C94C)"
                strokeWidth="2.6" strokeLinecap="round" transform={`rotate(${minDeg.toFixed(2)} 100 100)`} />
              <line x1="100" y1="108" x2="100" y2="32" stroke="#ff5b3a"
                strokeWidth="1.2" strokeLinecap="round" transform={`rotate(${secDeg.toFixed(2)} 100 100)`} />
            </g>
          )}

          <circle cx="100" cy="100" r="4" fill="var(--hub-text-primary, #FFE9A8)" />
          <circle cx="100" cy="100" r="1.6" fill="rgba(0,0,0,0.6)" />
        </svg>
      </div>

      <p className="mt-1 text-center text-[10px]" style={faintStyle}>
        {mode === "compass"
          ? (tilt.heading != null ? `${Math.round(tilt.heading)}°` : "tap → saat")
          : now.toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" })}
      </p>
    </button>
  );
}

