/**
 * GyroCompassWidget — Hyper-realistic 3D Golden Compass / Clock.
 *
 * A premium master tile for the Hub home that:
 *  • Renders a SVG-based golden compass + analog clock face.
 *  • Reads `DeviceOrientationEvent` (gyroscope) so the compass needle and
 *    light glints react to physical device tilt — tap once to grant iOS
 *    permission. On desktop, it falls back to mouse-parallax.
 *  • Casts a soft "shadow" beneath the rim that moves opposite to tilt,
 *    selling the 3D effect.
 *  • Updates the second/minute/hour hands in realtime.
 *  • Tap → cycles between Compass and Clock modes.
 *
 * 100 % CSS / SVG — no Three.js cost. Honours `prefers-reduced-motion`.
 */
import { useEffect, useRef, useState } from "react";
import { Compass } from "lucide-react";
import { playChime } from "@/lib/systemSounds";

interface Tilt { x: number; y: number; heading: number | null; }

export function GyroCompassWidget() {
  const [mode, setMode] = useState<"compass" | "clock">("compass");
  const [tilt, setTilt] = useState<Tilt>({ x: 0, y: 0, heading: null });
  const [now, setNow] = useState(() => new Date());
  const [needsPermission, setNeedsPermission] = useState(false);
  const rafRef = useRef<number | null>(null);

  // Live clock tick (1Hz is enough for the second hand smoothness via CSS).
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  // Gyro orientation
  useEffect(() => {
    if (typeof window === "undefined") return;
    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (reduced) return;

    const handler = (e: DeviceOrientationEvent) => {
      // beta = front-back (-180..180), gamma = left-right (-90..90)
      const beta = (e.beta ?? 0);
      const gamma = (e.gamma ?? 0);
      // Clamp to a comfortable range and normalize -1..1
      const ny = Math.max(-1, Math.min(1, beta / 45));
      const nx = Math.max(-1, Math.min(1, gamma / 45));
      const heading =
        typeof (e as DeviceOrientationEvent & { webkitCompassHeading?: number })
          .webkitCompassHeading === "number"
          ? (e as DeviceOrientationEvent & { webkitCompassHeading?: number })
              .webkitCompassHeading!
          : typeof e.alpha === "number"
            ? 360 - e.alpha
            : null;
      // Throttle via RAF
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() => {
        setTilt({ x: nx, y: ny, heading });
      });
    };

    type IOSReq = { requestPermission?: () => Promise<"granted" | "denied"> };
    const reqCtor = (window as unknown as { DeviceOrientationEvent?: IOSReq })
      .DeviceOrientationEvent;
    if (reqCtor && typeof reqCtor.requestPermission === "function") {
      // iOS — needs explicit user gesture
      setNeedsPermission(true);
    } else {
      window.addEventListener("deviceorientation", handler, true);
    }

    // Mouse parallax fallback for desktop
    const onMouse = (e: MouseEvent) => {
      const nx = (e.clientX / window.innerWidth - 0.5) * 2;
      const ny = (e.clientY / window.innerHeight - 0.5) * 2;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() => {
        setTilt((prev) => ({ x: nx, y: ny, heading: prev.heading }));
      });
    };
    window.addEventListener("mousemove", onMouse, { passive: true });

    return () => {
      window.removeEventListener("deviceorientation", handler, true);
      window.removeEventListener("mousemove", onMouse);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const requestGyro = async () => {
    type IOSReq = { requestPermission?: () => Promise<"granted" | "denied"> };
    const reqCtor = (window as unknown as { DeviceOrientationEvent?: IOSReq })
      .DeviceOrientationEvent;
    try {
      const res = await reqCtor?.requestPermission?.();
      if (res === "granted") {
        setNeedsPermission(false);
        window.addEventListener(
          "deviceorientation",
          ((e: DeviceOrientationEvent) => {
            const beta = e.beta ?? 0;
            const gamma = e.gamma ?? 0;
            setTilt({
              x: Math.max(-1, Math.min(1, gamma / 45)),
              y: Math.max(-1, Math.min(1, beta / 45)),
              heading: typeof e.alpha === "number" ? 360 - e.alpha : null,
            });
          }) as EventListener,
          true,
        );
      }
    } catch { /* ignore */ }
  };

  const cycleMode = () => {
    setMode((m) => (m === "compass" ? "clock" : "compass"));
    playChime();
  };

  // Derived 3D transforms
  const tiltDeg = `rotateX(${(-tilt.y * 14).toFixed(2)}deg) rotateY(${(tilt.x * 14).toFixed(2)}deg)`;
  const glintX = 50 + tilt.x * 22;
