      }}
      aria-label="Egemen Pusula — dokun, modu değiştir"
    >
      {/* Header */}
      <div className="relative z-10 flex items-center gap-2 mb-3">
        <Compass className="h-3.5 w-3.5" style={{ color: "#F2C94C" }} />
        <span className="text-[10px] uppercase tracking-[0.26em]" style={{ color: "#F2C94C" }}>
          Egemen {mode === "compass" ? "Pusula" : "Saat"}
        </span>
        <span className="ml-auto text-[10px]" style={{ color: "rgba(245,205,83,0.55)" }}>
          {tilt.heading != null ? `${Math.round(tilt.heading)}°` : "tap → mod"}
        </span>
      </div>

      {/* Stage */}
      <div
        className="relative mx-auto"
        style={{
          width: 200,
          height: 200,
          transformStyle: "preserve-3d",
          transform: tiltDeg,
          transition: "transform 80ms linear",
        }}
      >
        {/* Floor shadow */}
        <div
          aria-hidden
          className="absolute rounded-full"
          style={{
            left: "50%",
