/**
 * MiniWidget — Tek tip minimalist widget tile.
 *
 *  • 2x2 kare (aspect-square), iOS Today View ölçüsü.
 *  • Tap → useAppSheet().open(appId): Telegram tarzı sheet açılır.
 *  • Üst sol: ikon + küçük etiket. Alt: tek satır canlı veri (children).
 *  • Aksan altın bir noktaya indirgenmiştir; ana yüzey obsidiyen cam.
 */
import { ReactNode } from "react";
import { LucideIcon } from "lucide-react";
import { hapticTap } from "@/lib/native";
import { useAppSheet, AppSheetId } from "@/components/sovereign/AppSheetHost";

interface Props {
  appId: AppSheetId;
  label: string;
  icon: LucideIcon;
  /** Canlı/öne çıkan değer (örn: "12 ilan", "+777 0123 4567"). */
  value?: ReactNode;
  /** İkincil satır (örn: kaynak, tarih, durum). */
  hint?: ReactNode;
  /** Sağ üst sayaç rozeti. */
  badge?: number;
  /** Wide (2x4) yapmak için. Default: square. */
  wide?: boolean;
  testId?: string;
}

export function MiniWidget({
  appId,
  label,
  icon: Icon,
  value,
  hint,
  badge,
  wide,
  testId,
}: Props) {
  const { open } = useAppSheet();
  return (
    <button
      type="button"
      onClick={() => {
        hapticTap();
        open(appId);
      }}
      data-testid={testId ?? `mini-widget-${appId}`}
      className={[
        "relative w-full overflow-hidden p-4 flex flex-col text-left",
        "active:scale-[0.97] transition-transform",
        wide ? "" : "aspect-square",
      ].join(" ")}
      style={{
        borderRadius: 22,
        background:
          "linear-gradient(160deg, rgba(28,28,30,0.92) 0%, rgba(8,8,10,0.96) 100%)",
        backdropFilter: "blur(22px) saturate(160%)",
        WebkitBackdropFilter: "blur(22px) saturate(160%)",
        border: "0.5px solid rgba(255,255,255,0.10)",
        boxShadow:
          "0 12px 28px -10px rgba(0,0,0,0.7), inset 0 1px 0 rgba(255,255,255,0.08)",
      }}
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5">
          <Icon className="h-3.5 w-3.5 text-white/70" strokeWidth={1.7} />
          <span className="text-[10px] uppercase tracking-[0.2em] text-white/55">
            {label}
          </span>
        </div>
        {badge != null && badge > 0 && (
          <span
            className="text-[10px] font-semibold px-1.5 py-0.5 rounded-full"
            style={{
              background: "rgba(245,205,83,0.18)",
              color: "#FDE68A",
              border: "1px solid rgba(245,205,83,0.35)",
            }}
          >
            {badge > 99 ? "99+" : badge}
          </span>
        )}
      </div>

      <div className="mt-auto">
        {value != null && (
          <div className="text-[18px] font-light text-white tabular-nums leading-tight line-clamp-2">
            {value}
          </div>
        )}
        {hint != null && (
          <div className="mt-1 text-[10px] text-white/50 line-clamp-1">{hint}</div>
        )}
      </div>

      {/* Aksan: üst hairline gold */}
      <span
        aria-hidden
        className="absolute inset-x-0 top-0 h-px"
        style={{
          background:
            "linear-gradient(90deg, transparent, rgba(245,205,83,0.30), transparent)",
        }}
      />
    </button>
  );
}

