/**
 * MockBatteryWidget — iOS-parity small widget showing device battery.
 * Uses navigator.getBattery() if available; otherwise renders a neutral
 * placeholder so the grid stays balanced. No persistent label.
 */
import { useEffect, useState } from "react";
import { BatteryFull, BatteryMedium, BatteryLow, Battery } from "lucide-react";

interface BatteryManagerLike {
  level: number;
  charging: boolean;
  addEventListener?: (type: string, fn: () => void) => void;
  removeEventListener?: (type: string, fn: () => void) => void;
}

export function MockBatteryWidget() {
  const [pct, setPct] = useState<number | null>(null);
  const [charging, setCharging] = useState(false);

  useEffect(() => {
    let bm: BatteryManagerLike | null = null;
    let cancelled = false;
    const handler = () => {
      if (!bm || cancelled) return;
      setPct(Math.round(bm.level * 100));
      setCharging(bm.charging);
    };
    const nav = navigator as unknown as { getBattery?: () => Promise<BatteryManagerLike> };
    if (typeof nav.getBattery === "function") {
      nav.getBattery().then((b) => {
        if (cancelled) return;
        bm = b;
        handler();
        b.addEventListener?.("levelchange", handler);
        b.addEventListener?.("chargingchange", handler);
      }).catch(() => setPct(82));
    } else {
      setPct(82);
    }
    return () => {
      cancelled = true;
      bm?.removeEventListener?.("levelchange", handler);
      bm?.removeEventListener?.("chargingchange", handler);
    };
  }, []);

  const Icon = pct == null ? Battery : pct > 66 ? BatteryFull : pct > 33 ? BatteryMedium : BatteryLow;
  const ringColor = pct == null ? "#6B7280" : pct > 20 ? "#34C759" : "#FF453A";

  return (
    <div
      className="relative aspect-square w-full overflow-hidden p-3 flex flex-col justify-between"
      style={{
        borderRadius: 18,
        background:
          "linear-gradient(160deg, rgba(28,28,30,0.85) 0%, rgba(8,8,10,0.95) 100%)",
        backdropFilter: "blur(22px) saturate(160%)",
        WebkitBackdropFilter: "blur(22px) saturate(160%)",
        border: "0.5px solid rgba(255,255,255,0.08)",
        boxShadow: "0 10px 24px -10px rgba(0,0,0,0.7), inset 0 1px 0 rgba(255,255,255,0.06)",
      }}
    >
      <Icon className="h-5 w-5" style={{ color: ringColor }} strokeWidth={1.6} />
      <div>
        <div className="text-[22px] font-light text-white tabular-nums leading-none">
          {pct ?? "—"}%
        </div>
        <div className="mt-1 text-[10px] text-white/55">
          {charging ? "Şarjda" : "Pil"}
        </div>
      </div>
    </div>
  );
}

