/**
 * MockWeatherWidget — iOS-parity 2x2 medium widget.
 * Shows current temp, condition icon, hi/lo, location. No persistent label.
 * Pure presentational — uses ClockWeatherWidget's data fetch pattern but
 * isolated so the layout stays Apple-strict (corner radius 22px).
 */
import { useEffect, useState } from "react";
import { Cloud, CloudRain, Sun, CloudSnow } from "lucide-react";

const ICON = (c: number) => {
  if (c <= 1) return Sun;
  if (c >= 51 && c <= 67) return CloudRain;
  if (c >= 71 && c <= 86) return CloudSnow;
  return Cloud;
};

interface Wx { tempC: number; code: number; hi: number; lo: number; city: string }

export function MockWeatherWidget() {
  const [wx, setWx] = useState<Wx | null>(null);

  useEffect(() => {
    let off = false;
    const load = async (lat: number, lon: number, city: string) => {
      try {
        const r = await fetch(
          `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,weather_code&daily=temperature_2m_max,temperature_2m_min&timezone=auto`,
        );
        const j = await r.json();
        if (off) return;
        setWx({
          tempC: Math.round(j.current.temperature_2m),
          code: j.current.weather_code,
          hi: Math.round(j.daily?.temperature_2m_max?.[0] ?? 0),
          lo: Math.round(j.daily?.temperature_2m_min?.[0] ?? 0),
          city,
        });
      } catch {}
    };
    if (typeof navigator !== "undefined" && navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (p) => load(p.coords.latitude, p.coords.longitude, "Konum"),
        () => load(36.19, 44.0, "Hewlêr"),
        { timeout: 4000 },
      );
    } else load(36.19, 44.0, "Hewlêr");
    return () => { off = true; };
  }, []);

  const Icon = wx ? ICON(wx.code) : Cloud;

  return (
    <div
      className="relative aspect-square w-full overflow-hidden p-4 flex flex-col justify-between"
      style={{
        borderRadius: 22,
        background:
          "linear-gradient(160deg, rgba(40,72,120,0.55) 0%, rgba(8,18,38,0.92) 100%)",
        backdropFilter: "blur(22px) saturate(160%)",
        WebkitBackdropFilter: "blur(22px) saturate(160%)",
        border: "0.5px solid rgba(255,255,255,0.10)",
        boxShadow: "0 12px 28px -10px rgba(0,0,0,0.7), inset 0 1px 0 rgba(255,255,255,0.08)",
      }}
    >
      <div className="flex items-start justify-between">
        <div className="text-[12px] font-medium text-white/85 truncate">{wx?.city ?? "—"}</div>
        <Icon className="h-5 w-5 text-white/95" strokeWidth={1.6} />
      </div>
      <div>
        <div className="text-4xl font-light text-white tabular-nums leading-none">
          {wx ? wx.tempC : "—"}°
        </div>
        <div className="mt-1 text-[11px] text-white/65 tabular-nums">
          {wx ? `Y:${wx.hi}°  D:${wx.lo}°` : ""}
        </div>
      </div>
    </div>
  );
}

