/**
 * SovereignQuoteWidget — Hourly-rotating wisdom card for the Hub home.
 *
 * Picks a quote deterministically from `SOVEREIGN_QUOTES` based on the
 * current hour of year, so every visitor on the same hour sees the same
 * line. Re-rolls every 60 minutes via a re-render trigger.
 *
 * Streaming-text reveal makes the OS feel "live" — the quote types itself
 * out the first time it appears in any given hour (the index becomes the key
 * for the streaming hook so each new hour re-streams).
 *
 * Tap to copy / re-stream manually.
 */
import { useEffect, useMemo, useState } from "react";
import { useStreamingText } from "@/hooks/useStreamingText";
import { playChime } from "@/lib/systemSounds";
import { Sparkles, Quote } from "lucide-react";

const SOVEREIGN_QUOTES: { text: string; author: string }[] = [
  { text: "Egemenlik ödünç alınmaz, mühürlenir.", author: "Deng AI" },
  { text: "Bir milletin sesi, en sessiz olduğu yerde duyulur.", author: "Cegerxwîn" },
  { text: "Toprak hatırlar, taş konuşur, dengbêj söyler.", author: "Halk" },
  { text: "Kimliğin bir numara değil, bir mühürdür.", author: "Jiyan Anayasası" },
  { text: "Özgürlük bir başkasının izniyle gelmez.", author: "Apê Musa" },
  { text: "Sözün senin, mührün senin, kararın senin.", author: "Sovereign Code" },
  { text: "Dağ konuşmaz, ama her şeyi bilir.", author: "Atasözü" },
  { text: "Newroz, kül değil — kıvılcımdır.", author: "Halk" },
  { text: "Bir dilin yaşaması, bir halkın nefes almasıdır.", author: "Mehmed Uzun" },
  { text: "Asıl zenginlik, paylaşılan ekmektir.", author: "Atasözü" },
  { text: "Korkak, kendi gölgesinden bile özür diler.", author: "Ehmedê Xanî" },
  { text: "Adalet geç gelir ama eli boş dönmez.", author: "Halk" },
  { text: "Bir kalem, bin kılıçtan keskindir.", author: "Cizîrî" },
  { text: "Sürgün, kalbin geri dönüş yolculuğudur.", author: "Şivan Perwer" },
  { text: "Zaman, sabırlının yanındadır.", author: "Atasözü" },
  { text: "Bilmediğin yol, en uzun yoldur.", author: "Halk" },
  { text: "Mühür altın değil, sözdendir.", author: "Sovereign Code" },
  { text: "Bir çocuğun gülüşü, en saf devrimdir.", author: "Halk" },
  { text: "Kardeşlik, kanı değil, niyeti bağlar.", author: "Atasözü" },
  { text: "Konuşmadan önce dinle, dinlemeden önce sus.", author: "Dengbêj" },
  { text: "Kürtçe bir hâl, bir his, bir mühürdür.", author: "Mehmed Uzun" },
