  { text: "Vatan, ayağının değdiği değil — kalbinin durduğu yerdir.", author: "Halk" },
];

function pickIndex(): number {
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const diffMs = now.getTime() - start.getTime();
  const hourOfYear = Math.floor(diffMs / (1000 * 60 * 60));
  return hourOfYear % SOVEREIGN_QUOTES.length;
}

export function SovereignQuoteWidget() {
  const [idx, setIdx] = useState<number>(() => pickIndex());

  // Re-pick every minute (cheap) and update only if the hour changed.
  useEffect(() => {
    const id = setInterval(() => {
      const next = pickIndex();
      setIdx((cur) => (cur === next ? cur : next));
    }, 60_000);
    return () => clearInterval(id);
  }, []);

  const quote = SOVEREIGN_QUOTES[idx];
  const fullLine = useMemo(() => `"${quote.text}"`, [quote.text]);
  const streamed = useStreamingText(fullLine, 48);

  return (
    <button
      type="button"
      onClick={() => {
        setIdx((i) => (i + 1) % SOVEREIGN_QUOTES.length);
        playChime();
