        }}
      />
      {/* Soft golden glow that pulses to feel "alive" */}
      <span
        aria-hidden
        className="absolute -top-10 -right-10 h-32 w-32 rounded-full"
        style={{
          background:
            "radial-gradient(circle, rgba(245,205,83,0.25), transparent 70%)",
