import { useState } from "react";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Shield, Loader2, Scroll, CheckCircle2 } from "lucide-react";
import { toast } from "sonner";
import { useConstitution } from "@/hooks/useConstitution";

const CHARTER_TEXT = `
WORLD KURDISM ORGANIZATION (WKO) — GLOBAL CHARTER
Reference: WKO International Governance Standards

Article 1 — Universal Sovereign Identity
Every individual, without distinction of age, gender, ethnicity, or belief, has the
right to obtain a Sovereign KurdID under the World Kurdism Organization (WKO).

Article 2 — Democratic Participation (WKO Congress)
Every citizen who has signed this Charter has the right to vote in WKO Congress
referendums on matters affecting them. Every vote is encrypted and verifiable.

Article 3 — DiravCash Property Rights
Citizens' DiravCash balances are private property. The World Kurdism Organization
shall not interfere with these balances without the user's explicit consent.

Article 4 — WKO Academy & Knowledge Rights
Every citizen has the right to access the WKO Academy — global education in
language, technology and leadership — and to earn WKO-certified diplomas.

Article 5 — Privacy (Global WKO Privacy Protocols)
All personal data is governed by Global WKO Privacy Protocols and GDPR-level
international standards. The right to erasure is permanent and irrevocable.

WKO Citizen Oath:
By signing this Charter, I commit to upholding the founding values of the
World Kurdism Organization — sovereignty, solidarity, equality, and mutual respect.
`;

interface Props {
  open: boolean;
  onClose: () => void;
}

export function ConstitutionOnboarding({ open, onClose }: Props) {
  const { sign } = useConstitution();
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1);
  const [agreed, setAgreed] = useState(false);
  const [signing, setSigning] = useState(false);
  const [hash, setHash] = useState<string | null>(null);

  const handleSign = async () => {
    if (!agreed) return;
    setSigning(true);
    try {
      const res = await sign();
      if (res.success) {
        setHash(res.signature_hash ?? null);
        setStep(4);
        toast.success("WKO Global Charter signed! 🎉");
      } else {
        toast.error(res.error || "Signature failed");
      }
    } catch (e: any) {
      toast.error(e.message);
    } finally {
      setSigning(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-md p-0 bg-gradient-to-br from-slate-950 via-amber-950/30 to-black border-amber-500/30">
        {/* Step 1: Cinematic intro */}
        {step === 1 && (
          <div className="p-8 text-center animate-fade-in">
            <div className="w-20 h-20 mx-auto rounded-full bg-amber-500/20 border border-amber-400/40 flex items-center justify-center mb-6 animate-pulse">
              <Shield className="w-10 h-10 text-amber-300" />
            </div>
            <p className="text-[10px] font-bold tracking-[0.3em] text-amber-300/80 uppercase mb-2">
              World Kurdism Organization
            </p>
            <h2 className="text-2xl font-bold mb-2">Activate KurdID Sovereign</h2>
            <p className="text-sm text-muted-foreground mb-6">
              Welcome to the WKO digital citizenship. Sign the WKO Global Charter
              to activate your Sovereign status.
            </p>
            <Button onClick={() => setStep(2)} className="w-full bg-amber-600 hover:bg-amber-700 text-amber-50">
              Continue
            </Button>
          </div>
        )}

        {/* Step 2: Auto-scroll legal text */}
        {step === 2 && (
          <div className="p-6 animate-fade-in">
            <div className="flex items-center gap-2 mb-3">
              <Scroll className="w-5 h-5 text-amber-400" />
              <h3 className="font-bold">WKO Global Charter</h3>
            </div>
            <div className="h-64 overflow-y-auto rounded-lg bg-black/40 border border-white/10 p-4 text-xs leading-relaxed whitespace-pre-line text-muted-foreground">
              {CHARTER_TEXT}
            </div>
            <Button onClick={() => setStep(3)} className="w-full mt-4 bg-amber-600 hover:bg-amber-700 text-amber-50">
              I have read it — Continue
            </Button>
          </div>
        )}

        {/* Step 3: Oath checkbox + sign */}
        {step === 3 && (
          <div className="p-6 animate-fade-in">
            <h3 className="font-bold mb-4 text-center">WKO Citizen Oath & Digital Signature</h3>
            <label className="flex items-start gap-3 p-4 rounded-xl bg-amber-500/5 border border-amber-400/20 cursor-pointer mb-4">
              <Checkbox checked={agreed} onCheckedChange={(v) => setAgreed(!!v)} className="mt-0.5" />
              <span className="text-sm leading-snug">
                <strong>I swear</strong> to uphold the founding values of the World Kurdism
                Organization — sovereignty, solidarity, equality and mutual respect.
              </span>
            </label>

            <button
              onClick={handleSign}
              disabled={!agreed || signing}
              className={`w-full relative aspect-[3/1] rounded-2xl flex items-center justify-center font-bold text-sm transition-all ${
                agreed
                  ? "bg-gradient-to-br from-amber-500 via-yellow-400 to-amber-600 text-amber-950 shadow-[0_0_40px_-5px_rgba(251,191,36,0.6)] hover:scale-[1.02] active:scale-95 cursor-pointer"
                  : "bg-white/5 text-muted-foreground cursor-not-allowed border border-white/10"
              }`}
            >
              {signing ? (
                <Loader2 className="w-6 h-6 animate-spin" />
              ) : agreed ? (
                <span className="flex flex-col items-center gap-1">
                  <Shield className="w-6 h-6" />
                  Activate WKO Seal — Sign +777 Sovereign ID
                </span>
              ) : (
                "Confirm the oath first"
              )}
            </button>
          </div>
        )}

        {/* Step 4: Success */}
        {step === 4 && (
          <div className="p-8 text-center animate-scale-in">
            <div className="w-20 h-20 mx-auto rounded-full bg-green-500/20 border border-green-400/40 flex items-center justify-center mb-6">
              <CheckCircle2 className="w-10 h-10 text-green-300" />
            </div>
            <h2 className="text-2xl font-bold mb-2">Welcome, WKO Citizen!</h2>
            <p className="text-sm text-muted-foreground mb-3">
              You have officially signed the WKO Global Charter. Your KurdID Sovereign
              status is now active.
            </p>
            {hash && (
              <div className="text-[10px] font-mono opacity-60 mb-6 break-all px-4">
                Hash: {hash}
              </div>
            )}
            <Button onClick={onClose} className="w-full bg-green-600 hover:bg-green-700">
              Go to Dashboard
            </Button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

