import { QRCodeSVG } from "qrcode.react";
import { Crown, Shield, Sparkles, Globe2, BadgeCheck, Download, Wallet, Share2, Image as ImageIcon, Loader2 } from "lucide-react";
import { useRef, useState } from "react";
import { toast } from "sonner";
import { toPng, toJpeg } from "html-to-image";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";

interface KurdIdCardProps {
  displayName: string;
  kurdId: string | null;
  tier?: string;
  isPremium?: boolean;
  isVerified?: boolean;
  avatarUrl?: string | null;
  citizenSince?: string;
  badges?: Array<{ badge_name: string; badge_icon: string }>;
  shareUrl?: string;
}

export function KurdIdCard({
  displayName,
  kurdId,
  tier = "normal",
  isPremium = false,
  isVerified = false,
  avatarUrl,
  citizenSince,
  badges = [],
  shareUrl,
}: KurdIdCardProps) {
  const [flipped, setFlipped] = useState(false);
  const [shareOpen, setShareOpen] = useState(false);
  const [walletLoading, setWalletLoading] = useState(false);
  const [savingImage, setSavingImage] = useState(false);
  const cardWrapperRef = useRef<HTMLDivElement>(null);
  const qrRef = useRef<HTMLDivElement>(null);

  const isGold = isPremium || tier === "ultra_premium";
  const sinceYear = citizenSince ? new Date(citizenSince).getFullYear() : new Date().getFullYear();
  const qrValue = shareUrl || `https://jiyan.world/verify/${kurdId?.replace(/\s/g, "") || "unknown"}`;
  const safeFileName = `wko-sovereign-${(kurdId || "id").replace(/[^\d]/g, "")}`;

  // ============ APPLE WALLET ============
  const handleAppleWallet = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setWalletLoading(true);
    try {
      // TODO: Backend endpoint for .pkpass when WKO Pass Type ID is approved
      // const res = await fetch("/api/wallet/apple-pass", { ... });
      // const blob = await res.blob();
      // downloadBlob(blob, `${safeFileName}.pkpass`);
      await new Promise((r) => setTimeout(r, 1200));
      toast.info("Cüzdan dosyası hazırlanıyor...", {
        description: "WKO Pass Type ID sertifikası onay bekliyor. Hazır olduğunda otomatik indirilecek.",
      });
    } catch {
      toast.error("Apple Wallet hatası");
    } finally {
      setWalletLoading(false);
    }
  };

  // ============ GOOGLE WALLET ============
  const handleGoogleWallet = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setWalletLoading(true);
    try {
      // TODO: Backend signs JWT with Google Wallet issuer service account
      // const { saveUrl } = await fetch("/api/wallet/google-pass").then(r => r.json());
      // window.open(saveUrl, "_blank");
      await new Promise((r) => setTimeout(r, 800));
      toast.info("Google Wallet entegrasyonu hazırlanıyor", {
        description: "Sovereign Identity için JWT imzalama servisi yakında aktif.",
      });
    } catch {
      toast.error("Google Wallet hatası");
    } finally {
      setWalletLoading(false);
    }
  };

  // ============ SAVE AS IMAGE ============
  const captureCard = async (format: "png" | "jpg" = "png"): Promise<Blob | null> => {
    if (!cardWrapperRef.current) return null;
    const node = cardWrapperRef.current;
    const dataUrl = format === "jpg"
      ? await toJpeg(node, { quality: 0.95, pixelRatio: 3, backgroundColor: "#000000", cacheBust: true })
      : await toPng(node, { pixelRatio: 3, cacheBust: true });
    const res = await fetch(dataUrl);
    return await res.blob();
  };

  const downloadBlob = (blob: Blob, filename: string) => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  const handleSaveAsImage = async (format: "png" | "jpg") => {
    setSavingImage(true);
    try {
      const blob = await captureCard(format);
      if (!blob) throw new Error("capture failed");
      const filename = `${safeFileName}.${format}`;
      const file = new File([blob], filename, { type: blob.type });

      // Try native share with file (best for mobile → save to gallery)
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        try {
          await navigator.share({
            files: [file],
            title: "WKO Sovereign Identity",
            text: `${displayName} — ${kurdId}`,
          });
          setShareOpen(false);
          return;
        } catch (err: any) {
          if (err?.name === "AbortError") return;
        }
      }
      // Fallback: direct download
      downloadBlob(blob, filename);
      toast.success("Kart fotoğraf olarak kaydedildi");
      setShareOpen(false);
    } catch (err) {
      console.error(err);
      toast.error("Görsel oluşturulamadı");
    } finally {
      setSavingImage(false);
    }
  };

  // ============ SHARE LINK ============
  const handleShareLink = async () => {
    try {
      if (navigator.share) {
        await navigator.share({
          title: "WKO Global Passport",
          text: `${displayName} — ${kurdId}`,
          url: qrValue,
        });
      } else {
        await navigator.clipboard.writeText(qrValue);
        toast.success("Doğrulama linki kopyalandı");
      }
      setShareOpen(false);
    } catch {}
  };

  // ============ QR SAVE/SHARE ============
  const captureQr = async (): Promise<Blob | null> => {
    if (!qrRef.current) return null;
    const dataUrl = await toPng(qrRef.current, { pixelRatio: 4, backgroundColor: "#ffffff", cacheBust: true });
    const res = await fetch(dataUrl);
    return await res.blob();
  };

  const handleQrSave = async () => {
    try {
      const blob = await captureQr();
      if (!blob) return;
      const filename = `${safeFileName}-qr.png`;
      const file = new File([blob], filename, { type: "image/png" });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        try {
          await navigator.share({ files: [file], title: "Verification QR" });
          return;
        } catch (err: any) {
          if (err?.name === "AbortError") return;
        }
      }
      downloadBlob(blob, filename);
      toast.success("QR kod kaydedildi");
    } catch {
      toast.error("QR kaydedilemedi");
    }
  };

  return (
    <div className="w-full max-w-sm mx-auto select-none [perspective:1200px]">
      <div ref={cardWrapperRef} className="bg-black rounded-3xl">
        <div
          onClick={() => setFlipped(!flipped)}
          className={`relative w-full aspect-[1.586/1] cursor-pointer transition-transform duration-700 [transform-style:preserve-3d] ${
            flipped ? "[transform:rotateY(180deg)]" : ""
          }`}
        >
          {/* FRONT — WKO Sovereign Identity (GOLD) */}
          <div
            className="absolute inset-0 [backface-visibility:hidden] rounded-3xl p-5 overflow-hidden border border-amber-300/60 bg-gradient-to-br from-amber-900/50 via-yellow-700/30 to-amber-950/70 shadow-[0_0_40px_-5px_rgba(251,191,36,0.45)]"
          >
            <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/10 to-transparent opacity-50 pointer-events-none" />
            <div className="absolute -top-20 -right-20 w-48 h-48 rounded-full blur-3xl bg-amber-400/30" />

            <div className="relative h-full flex flex-col justify-between">
              <div className="flex items-start justify-between">
                <div>
                  <div className="flex items-center gap-1.5 text-[10px] font-bold tracking-[0.2em] text-amber-100/90">
                    <Shield className="w-3 h-3" />
                    WKO · SOVEREIGN IDENTITY
                  </div>
                  <div className="text-[9px] mt-0.5 text-amber-200/60 tracking-wider">WORLD KURDISM ORGANIZATION</div>
                </div>
                <div className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-400/25 border border-amber-300/50">
                  <Crown className="w-3 h-3 text-amber-200" />
                  <span className="text-[9px] font-bold text-amber-100">{isGold ? "GOLD" : "CITIZEN"}</span>
                </div>
              </div>

              <div className="flex items-center gap-3">
                <div className="w-14 h-14 rounded-2xl overflow-hidden border-2 border-amber-300/60 bg-black/30 flex items-center justify-center text-xl font-bold">
                  {avatarUrl ? (
                    <img src={avatarUrl} alt={displayName} className="w-full h-full object-cover" crossOrigin="anonymous" />
                  ) : (
                    displayName.slice(0, 1).toUpperCase()
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-base font-bold truncate flex items-center gap-1 text-amber-50">
                    {displayName}
                    {isVerified && (
                      <span title="WKO Verified" className="inline-flex items-center">
                        <BadgeCheck className="w-3.5 h-3.5 text-amber-200" />
                      </span>
                    )}
                  </div>
                  <div className="text-[10px] text-amber-200/70">CITIZEN SINCE {sinceYear}</div>
                </div>
              </div>

              <div>
                <div className="text-[9px] text-amber-200/60 tracking-widest mb-0.5">SOVEREIGN NUMBER</div>
                <div className="font-mono text-lg font-bold tracking-wider text-amber-50">{kurdId || "+777 ---- ----"}</div>
                {badges.length > 0 && (
                  <div className="flex gap-1 mt-1.5">
                    {badges.slice(0, 5).map((b, i) => (
                      <span key={i} className="text-base" title={b.badge_name}>{b.badge_icon}</span>
                    ))}
                    {badges.length > 5 && <span className="text-[10px] text-amber-200/60 self-center">+{badges.length - 5}</span>}
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* BACK — WKO Global Passport (PURPLE) */}
          <div className="absolute inset-0 [backface-visibility:hidden] [transform:rotateY(180deg)] rounded-3xl p-5 overflow-hidden border border-purple-400/40 bg-gradient-to-br from-purple-950 via-indigo-950 to-black shadow-[0_0_40px_-10px_rgba(168,85,247,0.5)]">
            <div className="absolute -top-16 -right-16 w-44 h-44 rounded-full blur-3xl bg-purple-500/25" />
            <div className="absolute -bottom-16 -left-16 w-44 h-44 rounded-full blur-3xl bg-fuchsia-500/15" />

            <div className="relative h-full flex items-center gap-4">
              <div
                ref={qrRef}
                className="flex flex-col items-center gap-1"
                onContextMenu={(e) => {
                  // long-press / right-click → save QR
                  e.preventDefault();
                  e.stopPropagation();
                  handleQrSave();
                }}
              >
                <div className="bg-white p-2 rounded-xl">
                  <QRCodeSVG value={qrValue} size={92} level="H" />
                </div>
                <div className="text-[8px] tracking-widest text-purple-200/70">SCAN · LONG-PRESS TO SAVE</div>
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5 text-[10px] font-bold tracking-[0.18em] text-purple-100">
                  <Globe2 className="w-3 h-3" />
                  WKO · GLOBAL PASSPORT
                </div>
                <div className="text-[9px] mt-0.5 text-purple-300/70 tracking-wider">UNIVERSAL · SHAREABLE</div>
                <div className="mt-3 text-sm font-bold truncate text-white flex items-center gap-1">
                  {displayName}
                  {isVerified && <BadgeCheck className="w-3.5 h-3.5 text-purple-200" />}
                </div>
                <div className="font-mono text-xs text-purple-100 mt-1 truncate">{kurdId}</div>
                <div className="mt-2 inline-flex items-center gap-1 rounded-full border border-purple-400/30 bg-purple-500/10 px-2 py-0.5">
                  <Sparkles className="w-2.5 h-2.5 text-purple-200" />
                  <span className="text-[9px] font-semibold text-purple-100">jiyan.world</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Action buttons */}
      <div className="flex gap-2 mt-3">
        <button
          onClick={handleAppleWallet}
          disabled={walletLoading}
          className="flex-1 min-h-[44px] bg-black border border-white/20 text-white text-xs font-semibold py-2.5 px-2 rounded-xl hover:bg-white/5 active:scale-[0.98] transition disabled:opacity-60 inline-flex items-center justify-center gap-1.5"
        >
