          {walletLoading ? "Hazırlanıyor..." : "Add to Wallet"}
        </button>

        <Dialog open={shareOpen} onOpenChange={setShareOpen}>
          <DialogTrigger asChild>
            <button
              className="flex-1 min-h-[44px] bg-white/10 border border-white/20 text-white text-xs font-semibold py-2.5 px-2 rounded-xl hover:bg-white/15 active:scale-[0.98] transition inline-flex items-center justify-center gap-1.5"
            >
              <Share2 className="w-3.5 h-3.5" />
              Share / Save
            </button>
          </DialogTrigger>
          <DialogContent className="max-w-xs">
            <DialogHeader>
