                disabled={savingImage}
                className="w-full min-h-[44px] flex items-center gap-3 px-4 py-3 rounded-xl bg-white/5 border border-white/10 hover:bg-white/10 transition text-left disabled:opacity-60"
              >
                <Download className="w-4 h-4" />
                <div>
                  <div className="text-sm font-semibold">JPG olarak indir</div>
                  <div className="text-[11px] opacity-60">Daha küçük dosya boyutu</div>
