import { Zap } from "lucide-react";
import { ENERGY_MAX, formatRefillIn } from "@/hooks/useKekaEnergy";

interface EnergyBarProps {
  energy: number;
  msUntilRefill: number;
  /** Compact variant for tight overlays */
  compact?: boolean;
}

/**
 * Sovereign Energy bar — KEKA addiction loop indicator.
 * Refills automatically every 24h (handled by useKekaEnergy).
 */
export function EnergyBar({ energy, msUntilRefill, compact = false }: EnergyBarProps) {
  const pct = Math.max(0, Math.min(100, (energy / ENERGY_MAX) * 100));
  const low = energy <= 10;
  const mid = energy <= 40;

  const barColor = low
    ? "from-red-400 via-red-500 to-red-600"
    : mid
      ? "from-amber-300 via-amber-400 to-orange-500"
      : "from-amber-200 via-amber-400 to-amber-600";

  return (
    <div
      className={`flex items-center gap-2 rounded-full bg-black/55 backdrop-blur border border-amber-400/30 ${
        compact ? "px-2 py-0.5" : "px-2.5 py-1"
      }`}
    >
      <Zap
        className={`${compact ? "h-3 w-3" : "h-3.5 w-3.5"} ${
          low ? "text-red-300" : "text-amber-300"
        } drop-shadow-[0_0_4px_rgba(255,200,80,0.7)]`}
        strokeWidth={2.6}
      />
      <div
        className={`relative ${compact ? "h-1.5 w-16" : "h-2 w-24"} rounded-full bg-white/10 overflow-hidden`}
      >
        <div
          className={`h-full bg-gradient-to-r ${barColor} transition-all duration-500 ${
            low ? "animate-pulse" : ""
          }`}
          style={{ width: `${pct}%` }}
        />
      </div>
      <span
        className={`${compact ? "text-[9px]" : "text-[10px]"} font-bold tabular-nums ${
          low ? "text-red-200" : "text-amber-200"
        }`}
        title={energy < ENERGY_MAX ? `Yenilenme: ${formatRefillIn(msUntilRefill)}` : "Tam dolu"}
      >
        {energy}
        <span className="opacity-50">/{ENERGY_MAX}</span>
      </span>
    </div>
  );
}

