import { useEffect, useState } from "react";

interface Coin {
  id: number;
  left: number;
  delay: number;
  duration: number;
  size: number;
  rotate: number;
}

interface Props {
  amount: 1 | 5 | 10;
  onDone: () => void;
}

/**
 * Full-screen overlay: a shower of golden coins falling from the top, scaling
 * with the tip amount. Auto-dismisses ~2.6 s after mount.
 */
export function GoldRain({ amount, onDone }: Props) {
  const [coins] = useState<Coin[]>(() => {
    const count = amount === 1 ? 18 : amount === 5 ? 36 : 60;
    return Array.from({ length: count }, (_, i) => ({
      id: i,
      left: Math.random() * 100,
      delay: Math.random() * 0.4,
      duration: 1.6 + Math.random() * 0.9,
      size: 22 + Math.random() * 18,
      rotate: Math.random() * 720 - 360,
    }));
  });

  useEffect(() => {
    const t = setTimeout(onDone, 2600);
    return () => clearTimeout(t);
  }, [onDone]);

  return (
    <div className="pointer-events-none fixed inset-0 z-[200] overflow-hidden">
      {/* Soft golden flash */}
      <div className="absolute inset-0 bg-gradient-to-b from-amber-300/15 via-transparent to-transparent animate-[fadeInOut_1.2s_ease-out]" />

      {coins.map((c) => (
        <span
          key={c.id}
          className="absolute -top-12 select-none drop-shadow-[0_0_8px_rgba(255,200,60,0.7)]"
          style={{
            left: `${c.left}%`,
            fontSize: c.size,
            animation: `coinFall ${c.duration}s cubic-bezier(0.4, 0.6, 0.6, 1) ${c.delay}s forwards`,
            transform: `rotate(${c.rotate}deg)`,
          }}
        >
          🪙
        </span>
      ))}

      {/* Center burst */}
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="text-center animate-[burst_1.4s_ease-out]">
          <div className="text-6xl mb-1">💛</div>
          <div className="text-3xl font-extrabold bg-gradient-to-r from-amber-300 to-yellow-500 bg-clip-text text-transparent">
            +{amount} DC
          </div>
        </div>
      </div>

      <style>{`
        @keyframes coinFall {
          0%   { transform: translateY(-10vh) rotate(0deg); opacity: 0; }
          10%  { opacity: 1; }
          100% { transform: translateY(110vh) rotate(720deg); opacity: 0.9; }
        }
        @keyframes burst {
          0%   { transform: scale(0.4); opacity: 0; }
          25%  { transform: scale(1.2); opacity: 1; }
          75%  { transform: scale(1); opacity: 1; }
          100% { transform: scale(0.9); opacity: 0; }
        }
        @keyframes fadeInOut {
          0%   { opacity: 0; }
          25%  { opacity: 1; }
          100% { opacity: 0; }
        }
      `}</style>
    </div>
  );
}

