import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Loader2, Send, Trash2 } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";
import {
  deleteKekaComment,
  fetchKekaComments,
  postKekaComment,
  type KekaComment,
} from "@/hooks/useKeka";
import { useAuth } from "@/hooks/useAuth";
import { formatDistanceToNow } from "date-fns";
import { tr } from "date-fns/locale";

interface Props {
  open: boolean;
  videoId: string | null;
  onOpenChange: (open: boolean) => void;
  onCountChange?: (videoId: string, delta: number) => void;
}

export function KekaCommentsSheet({ open, videoId, onOpenChange, onCountChange }: Props) {
  const { user } = useAuth();
  const [comments, setComments] = useState<KekaComment[]>([]);
  const [loading, setLoading] = useState(false);
  const [text, setText] = useState("");
  const [posting, setPosting] = useState(false);

  useEffect(() => {
    if (!open || !videoId) return;
    setLoading(true);
    fetchKekaComments(videoId)
      .then(setComments)
      .catch(() => toast.error("Yorumlar yüklenemedi"))
      .finally(() => setLoading(false));
  }, [open, videoId]);

  const handlePost = async () => {
    if (!videoId || !text.trim() || posting) return;
    if (!user) {
      toast.error("Yorum için giriş yap");
      return;
    }
    setPosting(true);
    try {
      const c = await postKekaComment(videoId, text);
      // enrich with current profile (best-effort)
      const enriched: KekaComment = {
        ...c,
        profile: {
          display_name: user.user_metadata?.display_name ?? user.email ?? "Sen",
          avatar_url: user.user_metadata?.avatar_url ?? null,
          kurd_id: null,
        },
      };
      setComments((prev) => [enriched, ...prev]);
      setText("");
      onCountChange?.(videoId, 1);
    } catch (e: any) {
      toast.error(e?.message ?? "Yorum gönderilemedi");
    } finally {
      setPosting(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!videoId) return;
    try {
      await deleteKekaComment(id);
      setComments((prev) => prev.filter((c) => c.id !== id));
      onCountChange?.(videoId, -1);
    } catch {
      toast.error("Silinemedi");
    }
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="bg-zinc-950 border-amber-400/20 text-white h-[80dvh] p-0 rounded-t-3xl flex flex-col"
      >
        <SheetHeader className="px-4 pt-4 pb-2 border-b border-white/10">
          <SheetTitle className="text-white text-base">
            Yorumlar {comments.length > 0 && <span className="text-amber-300">({comments.length})</span>}
          </SheetTitle>
        </SheetHeader>

        {/* List */}
        <div className="flex-1 overflow-y-auto px-4 py-3 space-y-4">
          {loading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="h-5 w-5 animate-spin text-amber-300" />
            </div>
          ) : comments.length === 0 ? (
            <p className="text-center text-white/50 text-sm py-8">
              İlk yorumu sen yaz 💬
            </p>
          ) : (
            comments.map((c) => {
              const name = c.profile?.display_name ?? "Anonim";
              const initial = name[0]?.toUpperCase() ?? "?";
              const isMine = user?.id === c.user_id;
              return (
                <div key={c.id} className="flex gap-3">
                  <Avatar className="h-8 w-8 shrink-0">
                    <AvatarImage src={c.profile?.avatar_url ?? undefined} />
                    <AvatarFallback className="bg-amber-500/30 text-amber-100 text-xs">
                      {initial}
                    </AvatarFallback>
                  </Avatar>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-baseline gap-2">
                      <p className="text-xs font-bold text-white truncate">{name}</p>
                      <span className="text-[10px] text-white/40">
                        {formatDistanceToNow(new Date(c.created_at), { addSuffix: true, locale: tr })}
                      </span>
                    </div>
                    <p className="text-sm text-white/90 leading-snug break-words">{c.content}</p>
                  </div>
                  {isMine && (
                    <button
                      onClick={() => handleDelete(c.id)}
                      className="text-white/40 hover:text-red-400 active:scale-90 transition shrink-0"
                      aria-label="Sil"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  )}
                </div>
              );
            })
          )}
        </div>

        {/* Composer */}
        <div className="border-t border-white/10 p-3 pb-[max(env(safe-area-inset-bottom),12px)] bg-zinc-950">
          <div className="flex items-center gap-2 bg-white/5 border border-white/10 rounded-full pl-4 pr-1 py-1">
            <input
              type="text"
              value={text}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  handlePost();
                }
              }}
              maxLength={500}
              placeholder={user ? "Yorum yaz…" : "Yorum için giriş yap"}
              disabled={!user || posting}
              className="flex-1 bg-transparent outline-none text-sm text-white placeholder:text-white/35"
            />
            <button
              onClick={handlePost}
              disabled={!user || !text.trim() || posting}
              className="h-9 w-9 rounded-full bg-amber-400 text-black flex items-center justify-center disabled:opacity-40 active:scale-90 transition"
              aria-label="Gönder"
            >
              {posting ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Send className="h-4 w-4" />
              )}
            </button>
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

