export function KekaPointsCard({ userId, compact = false }: Props) {
  const { points, dcEquivalent, canRedeem, redeeming, redeem } = useKekaPoints(userId);
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);

  const handleRedeem = async (amount: number) => {
    setPendingAmount(amount);
    const res = await redeem(amount);
    setPendingAmount(null);
    if (res.success) {
      toast.success(`+${res.dc_credited} DC cüzdana eklendi 💛`, {
        description: `Yeni bakiye: ${res.new_balance} DC`,
      });
    } else {
      const map: Record<string, string> = {
        not_authenticated: "Giriş yapmalısın",
        min_100_points: "En az 100 puan gerekiyor",
        must_be_multiple_of_100: "Tutar 100'ün katı olmalı",
        insufficient_points: "Yeterli puanın yok",
      };
      toast.error(map[res.error] ?? res.error);
    }
  };

  if (!userId) return null;

  if (compact) {
    return (
      <div className="flex items-center gap-2 px-3 py-2 rounded-xl bg-gradient-to-r from-amber-500/10 to-amber-700/5 border border-amber-400/30">
