        {canRedeem && (
          <button
            onClick={() => handleRedeem(Math.floor(points / POINTS_PER_DC) * POINTS_PER_DC)}
            disabled={redeeming}
            className="text-[10px] font-bold px-2.5 py-1 rounded-full bg-amber-400 text-black active:scale-95 disabled:opacity-50"
          >
            {redeeming ? <Loader2 className="h-3 w-3 animate-spin" /> : "Çevir"}
          </button>
        )}
      </div>
    );
  }

  const presets = [100, 500, 1000].filter((p) => p <= points);

  return (
    <div className="rounded-2xl bg-gradient-to-br from-amber-500/15 via-amber-600/10 to-amber-900/20 border border-amber-400/40 p-4 space-y-3">
      <div className="flex items-center gap-2">
        <SovereignStar size={28} glow />
        <div className="flex-1">
          <h3 className="text-sm font-bold text-amber-100 tracking-wide">KEKA Puanın</h3>
          <p className="text-[10px] text-amber-300/70 uppercase tracking-widest">
            Sovereign Reward
