        <span className="text-xs text-amber-300/70">puan</span>
        <span className="text-xs text-white/40 ml-auto">
          ≈ <strong className="text-amber-200">{dcEquivalent}</strong> DC
        </span>
      </div>

      <div className="text-[10px] text-white/55 leading-relaxed">
        Her <strong>100 KEKA Puanı</strong> = <strong className="text-amber-200">1 DiravCash</strong>.
        Doğrudan cüzdanına aktarılır.
      </div>

      {canRedeem ? (
        <div className="grid grid-cols-3 gap-2">
          {presets.length === 0 && (
            <button
              onClick={() => handleRedeem(POINTS_PER_DC)}
              disabled={redeeming}
              className="col-span-3 h-10 rounded-xl bg-gradient-to-r from-amber-400 to-amber-600 text-black text-xs font-bold flex items-center justify-center gap-2 active:scale-95 disabled:opacity-50"
            >
              {redeeming ? <Loader2 className="h-4 w-4 animate-spin" /> : <Coins className="h-4 w-4" />}
              100 puan → 1 DC
            </button>
          )}
          {presets.map((amt) => (
            <button
              key={amt}
              onClick={() => handleRedeem(amt)}
              disabled={redeeming}
              className="h-11 rounded-xl bg-amber-400/20 border border-amber-400/50 text-amber-100 text-xs font-bold flex flex-col items-center justify-center active:scale-95 disabled:opacity-50"
            >
              {redeeming && pendingAmount === amt ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <>
                  <span>{amt}p</span>
                  <span className="text-[9px] text-amber-300/80">{amt / POINTS_PER_DC} DC</span>
                </>
              )}
            </button>
          ))}
