type FilterId = "none" | "warm" | "cool" | "vivid" | "noir" | "gold" | "vhs" | "dream" | "dengbej";
interface FilterDef { id: FilterId; label: string; css: string; premium: boolean; }
const FILTERS: FilterDef[] = [
  { id: "none",    label: "Orijinal",  css: "none", premium: false },
  { id: "dengbej", label: "Dengbêj",   css: "saturate(1.15) sepia(0.55) hue-rotate(-18deg) contrast(1.18) brightness(1.05)", premium: false },
  { id: "warm",    label: "Sıcak",     css: "saturate(1.2) sepia(0.15) hue-rotate(-8deg)", premium: false },
  { id: "cool",    label: "Soğuk",     css: "saturate(1.1) hue-rotate(15deg) brightness(1.05)", premium: false },
  { id: "vivid",   label: "Canlı",     css: "saturate(1.6) contrast(1.15)", premium: true },
  { id: "noir",    label: "Noir",      css: "grayscale(1) contrast(1.3) brightness(0.95)", premium: true },
  { id: "gold",    label: "Altın",     css: "saturate(1.3) sepia(0.4) hue-rotate(-15deg) brightness(1.1)", premium: true },
  { id: "vhs",     label: "VHS",       css: "contrast(1.2) saturate(0.85) hue-rotate(-5deg) blur(0.3px)", premium: true },
  { id: "dream",   label: "Rüya",      css: "saturate(1.2) blur(0.6px) brightness(1.1) contrast(0.95)", premium: true },
];

const MAX_SECONDS = 15;
const COUNTDOWN_SECONDS = 3;
const DENGBEJ_MOTTO = "Dengê te, azadiya te ye";

export function KekaRecorder({ open, userId, onClose, onUploaded }: Props) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const recorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const countdownTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [recording, setRecording] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [previewBlob, setPreviewBlob] = useState<Blob | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [caption, setCaption] = useState("");
  const [isAdult, setIsAdult] = useState(false);
  const [isDengbej, setIsDengbej] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [cameraReady, setCameraReady] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [filter, setFilter] = useState<FilterId>("none");
  const [countdown, setCountdown] = useState<number | null>(null);
  const { isPremium } = usePremium(userId);
  const activeFilter = FILTERS.find((f) => f.id === filter) ?? FILTERS[0];

  // When Dengbêj mode is on, force the cinematic golden-sepia filter
  useEffect(() => {
    if (isDengbej) setFilter("dengbej");
  }, [isDengbej]);

  const handleFilePick = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith("video/")) {
      toast.error("Lütfen bir video dosyası seç");
      return;
    }
    if (file.size > 60 * 1024 * 1024) {
      toast.error("Video çok büyük (maks 60 MB)");
      return;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
    setPreviewBlob(file);
    setPreviewUrl(URL.createObjectURL(file));
  };

  const cleanup = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    if (countdownTimerRef.current) {
      clearInterval(countdownTimerRef.current);
      countdownTimerRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
    if (recorderRef.current && recorderRef.current.state !== "inactive") {
      try { recorderRef.current.stop(); } catch {}
    }
    recorderRef.current = null;
    chunksRef.current = [];
  };

  useEffect(() => {
    if (!open) {
      cleanup();
      if (previewUrl) URL.revokeObjectURL(previewUrl);
      setPreviewBlob(null);
      setPreviewUrl(null);
      setCaption("");
      setIsAdult(false);
      setIsDengbej(false);
      setElapsed(0);
      setRecording(false);
      setCountdown(null);
      setFilter("none");
      return;
    }
    (async () => {
      setCameraReady(false);
      setCameraError(null);
      if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
        setCameraError("Bu cihazda kamera erişimi yok. Galeriden video yükleyebilirsin.");
        return;
      }
      try {
        // Vocal Booster: AGC + noise suppression + echo cancel for clearer voice
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: { ideal: 720 }, height: { ideal: 1280 } },
          audio: {
            autoGainControl: true,
            echoCancellation: true,
            noiseSuppression: true,
            sampleRate: 48000,
          } as MediaTrackConstraints,
        });
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play().catch(() => {});
        }
        setCameraReady(true);
      } catch (e: any) {
        const msg = e?.name === "NotAllowedError"
          ? "Kamera izni reddedildi. Galeriden video yükleyebilirsin."
          : "Kameraya erişilemedi. Galeriden video yükleyebilirsin.";
        setCameraError(msg);
      }
    })();
    return () => cleanup();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const beginRecordingNow = () => {
    if (!streamRef.current) return;
    try {
      const mime = MediaRecorder.isTypeSupported("video/mp4")
        ? "video/mp4"
        : MediaRecorder.isTypeSupported("video/webm;codecs=vp9,opus")
          ? "video/webm;codecs=vp9,opus"
          : "video/webm";
      const rec = new MediaRecorder(streamRef.current, { mimeType: mime });
      chunksRef.current = [];
      rec.ondataavailable = (e) => {
        if (e.data && e.data.size > 0) chunksRef.current.push(e.data);
      };
      rec.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: mime });
        setPreviewBlob(blob);
        setPreviewUrl(URL.createObjectURL(blob));
        if (streamRef.current) {
          streamRef.current.getTracks().forEach((t) => t.stop());
          streamRef.current = null;
        }
      };
      rec.start();
      recorderRef.current = rec;
      setRecording(true);
      setElapsed(0);
      timerRef.current = setInterval(() => {
        setElapsed((e) => {
          if (e + 0.1 >= MAX_SECONDS) {
            stopRecording();
            return MAX_SECONDS;
          }
          return e + 0.1;
        });
      }, 100);
    } catch (e: any) {
      toast.error("Kayıt başlatılamadı: " + (e?.message ?? ""));
    }
  };

  const startRecording = () => {
    if (!streamRef.current) return;
    // Dengbêj Mode → 3-second countdown with motto first
    if (isDengbej) {
      setCountdown(COUNTDOWN_SECONDS);
      countdownTimerRef.current = setInterval(() => {
        setCountdown((c) => {
          if (c === null) return null;
          if (c <= 1) {
            if (countdownTimerRef.current) {
              clearInterval(countdownTimerRef.current);
              countdownTimerRef.current = null;
            }
            // Begin actual recording on next tick so countdown UI clears
            setTimeout(() => beginRecordingNow(), 0);
            return null;
          }
          return c - 1;
        });
      }, 1000);
      return;
    }
    beginRecordingNow();
  };

  const stopRecording = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    if (recorderRef.current && recorderRef.current.state !== "inactive") {
      try { recorderRef.current.stop(); } catch {}
    }
    setRecording(false);
  };

  const handleUpload = async () => {
    if (!previewBlob) return;
    setUploading(true);
    try {
      // Auto-prepend hashtag for Dengbêj clips so they surface in the archive feed
      const finalCaption = isDengbej && !/#dengbej/i.test(caption)
        ? `${caption.trim()} #dengbej #voicesofjiyan`.trim()
        : caption.trim();
      await uploadKekaVideo(userId, previewBlob, finalCaption, isAdult, { isDengbej });
      toast.success(isDengbej ? "Dengê te arşive eklendi 🌟" : "KEKA'na yüklendi 🎬");
      onUploaded();
      onClose();
    } catch (e: any) {
      toast.error("Yükleme başarısız: " + (e?.message ?? ""));
    } finally {
      setUploading(false);
    }
  };

  const handleRetake = () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewBlob(null);
    setPreviewUrl(null);
    setElapsed(0);
    setCaption("");
    (async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user" },
          audio: {
            autoGainControl: true,
            echoCancellation: true,
            noiseSuppression: true,
          } as MediaTrackConstraints,
        });
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play().catch(() => {});
        }
      } catch {}
    })();
  };

  if (!open) return null;

  const progressPct = (elapsed / MAX_SECONDS) * 100;

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col">
      {/* Top bar */}
      <div className="absolute top-0 inset-x-0 z-20 flex items-center justify-between px-3 pt-3">
        <button
          onClick={onClose}
          className="h-10 w-10 rounded-full bg-black/60 backdrop-blur border border-white/15 flex items-center justify-center text-white"
          aria-label="Kapat"
        >
          <X className="h-5 w-5" />
        </button>
        <span className={`text-[10px] font-bold tracking-widest px-2 py-1 rounded-md border ${
          isDengbej
            ? "text-amber-200 bg-amber-950/70 border-amber-400/60"
            : "text-amber-300 bg-black/50 border-amber-400/30"
        }`}>
          {isDengbej ? "DENGBÊJ" : "KEKA"} · {Math.max(0, MAX_SECONDS - elapsed).toFixed(1)}s
        </span>
        <div className="w-10" />
      </div>

      {/* Progress bar */}
      <div className="absolute top-14 inset-x-3 z-20 h-1 rounded-full bg-white/10 overflow-hidden">
        <div
          className="h-full bg-gradient-to-r from-amber-300 to-amber-500 transition-[width] duration-100"
          style={{ width: `${progressPct}%` }}
        />
      </div>

      {/* Camera / preview */}
      <div className="flex-1 relative bg-black overflow-hidden">
        {previewUrl ? (
          <video
            src={previewUrl}
            playsInline
            autoPlay
            loop
            muted
            style={{ filter: activeFilter.css }}
            className="absolute inset-0 h-full w-full object-cover"
          />
        ) : (
          <video
            ref={videoRef}
            playsInline
            muted
            style={{ filter: activeFilter.css }}
            className="absolute inset-0 h-full w-full object-cover scale-x-[-1]"
          />
        )}

        {/* Dengbêj overlay marker on preview */}
        {previewBlob && isDengbej && (
          <div className="pointer-events-none absolute top-3 left-1/2 -translate-x-1/2 z-10 flex items-center gap-1.5 px-3 py-1 rounded-full bg-amber-950/80 backdrop-blur border border-amber-400/60">
            <Mic className="h-3 w-3 text-amber-200" />
            <Star className="h-3 w-3 text-amber-200 fill-amber-300" />
            <span className="text-[10px] font-bold tracking-widest text-amber-100">
              VOICES OF JIYAN
            </span>
          </div>
        )}

        {/* 3-second Dengbêj countdown overlay */}
        {countdown !== null && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black/65 backdrop-blur-sm px-6 text-center">
            <p className="text-amber-200 text-xs tracking-[0.3em] mb-3 font-semibold">
              DENGBÊJ MODE
            </p>
            <p className="text-amber-100 text-xl font-bold mb-6 italic max-w-xs leading-snug">
              "{DENGBEJ_MOTTO}"
            </p>
            <p className="text-amber-300/80 text-[11px] mb-2">Sesin, özgürlüğündür</p>
            <div className="relative">
              <div className="h-32 w-32 rounded-full border-4 border-amber-400/40 flex items-center justify-center">
                <span className="text-7xl font-black text-amber-300 drop-shadow-[0_0_20px_rgba(255,200,80,0.7)] animate-pulse">
                  {countdown}
                </span>
              </div>
            </div>
          </div>
        )}

        {/* Filter strip + Dengbêj toggle — only when not previewing/recording */}
        {!previewBlob && !recording && cameraReady && countdown === null && (
          <div className="absolute bottom-3 inset-x-0 z-10 px-3 space-y-2">
            {/* Dengbêj Mode toggle — prominent above filter strip */}
            <button
              onClick={() => setIsDengbej((v) => !v)}
              className={`w-full flex items-center justify-center gap-2 rounded-2xl py-2.5 text-xs font-bold transition border-2 ${
                isDengbej
                  ? "bg-gradient-to-r from-amber-600/40 via-amber-500/40 to-amber-600/40 border-amber-300 text-amber-100 shadow-[0_0_18px_rgba(255,200,80,0.45)]"
                  : "bg-black/60 border-amber-400/30 text-amber-200/85"
              }`}
            >
              <Mic className="h-4 w-4" />
              <span className="tracking-wider">DENGBÊJ MODE</span>
              <Star className={`h-4 w-4 ${isDengbej ? "fill-amber-300 text-amber-300" : "text-amber-300/70"}`} />
              <span className="text-[9px] opacity-80 ml-1">{isDengbej ? "AÇIK" : "Hikâyeni anlat"}</span>
            </button>

            <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-none" style={{ scrollbarWidth: "none" }}>
              {FILTERS.map((f) => {
                // Sovereign filters: unlocked by KYC + +777 Seal — no payment.
                const locked = f.premium && !isPremium;
                const selected = filter === f.id;
                const isDengbejFilter = f.id === "dengbej";
                return (
                  <button
                    key={f.id}
                    onClick={() => {
                      if (locked) {
                        toast.error("Egemen filtreler — Mührünü tamamla", {
                          description: "KYC doğrulaması ve +777 ID ile kilidini aç.",
                          action: { label: "Egemenliğini Tamamla", onClick: () => (window.location.href = "/kyc") },
                        });
                        return;
                      }
                      setFilter(f.id);
                      // selecting non-dengbej filter while in dengbej mode disables it
                      if (!isDengbejFilter && isDengbej) setIsDengbej(false);
                    }}
                    className={`shrink-0 relative flex flex-col items-center justify-center min-w-[58px] h-14 rounded-xl border text-[10px] font-bold transition active:scale-95 ${
                      selected
                        ? "bg-amber-500/30 border-amber-400 text-amber-100"
                        : locked
                          ? "bg-black/50 border-amber-400/30 text-amber-300/70"
                          : isDengbejFilter
                            ? "bg-amber-900/40 border-amber-500/50 text-amber-200"
                            : "bg-black/55 border-white/15 text-white/85"
                    }`}
                  >
                    {f.premium && (
                      <Crown className={`absolute -top-1 -right-1 h-3 w-3 ${locked ? "text-amber-400" : "text-amber-300"}`} />
                    )}
                    {locked && <Lock className="h-3 w-3 mb-0.5" />}
                    {!locked && f.id === "none" && <Sparkles className="h-3 w-3 mb-0.5" />}
                    {!locked && isDengbejFilter && <Mic className="h-3 w-3 mb-0.5" />}
                    <span>{f.label}</span>
                  </button>
                );
              })}
            </div>
            {!isPremium && (
              <Link
                to="/kyc"
                className="block text-center text-[10px] text-amber-300/80 underline"
              >
                ⚖ Egemenliğini Tamamla — Mühür ile filtreleri aç
              </Link>
            )}
          </div>
        )}

        {/* Camera error overlay */}
        {!previewUrl && cameraError && (
          <div className="absolute inset-0 z-10 flex flex-col items-center justify-center px-8 text-center bg-black/70">
            <Camera className="h-10 w-10 text-amber-300/70 mb-3" />
            <p className="text-sm text-white/80 mb-4">{cameraError}</p>
            <button
              onClick={() => fileInputRef.current?.click()}
              className="h-11 px-5 rounded-full bg-gradient-to-r from-amber-400 to-amber-600 text-black text-sm font-bold flex items-center gap-2 active:scale-95 transition"
            >
              <Upload className="h-4 w-4" />
              Galeriden seç
            </button>
          </div>
        )}

        {/* Caption box + toggles (after preview) */}
        {previewBlob && (
          <div className="absolute bottom-28 inset-x-3 z-10 space-y-2">
            <input
              value={caption}
              onChange={(e) => setCaption(e.target.value)}
              placeholder={isDengbej ? "Hikâyeni birkaç kelimeyle anlat… (#dengbej otomatik)" : "Açıklama ekle (#hashtag destekli)…"}
              maxLength={140}
              className="w-full bg-black/60 backdrop-blur border border-white/15 rounded-2xl px-4 py-3 text-sm text-white placeholder:text-white/40 outline-none focus:border-amber-400/60"
            />
            <button
              type="button"
              onClick={() => setIsAdult((v) => !v)}
              className={`w-full flex items-center gap-2 rounded-2xl px-4 py-2.5 text-xs font-semibold transition border ${
                isAdult
                  ? "bg-red-500/20 border-red-400/60 text-red-100"
                  : "bg-black/60 border-white/15 text-white/80"
              }`}
            >
              <span
                className={`h-5 w-9 rounded-full relative transition ${
                  isAdult ? "bg-red-500" : "bg-white/15"
                }`}
              >
                <span
                  className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-all ${
                    isAdult ? "left-[18px]" : "left-0.5"
                  }`}
                />
              </span>
              <span className="flex-1 text-left">
                18+ içerik olarak işaretle
              </span>
              {isAdult && <span className="text-[10px] opacity-80">Yetişkinlere özel</span>}
            </button>
          </div>
        )}
      </div>

      {/* Hidden file input for gallery upload */}
      <input
        ref={fileInputRef}
        type="file"
        accept="video/*,video/mp4,video/quicktime,video/webm"
        className="hidden"
        onChange={handleFilePick}
      />

      {/* Bottom controls */}
      <div className="relative z-10 px-4 py-5 bg-black flex items-center justify-center gap-4">
        {previewBlob ? (
          <>
            <button
              onClick={handleRetake}
              disabled={uploading}
              className="h-12 px-5 rounded-full bg-white/10 border border-white/20 text-white text-sm font-semibold active:scale-95 transition disabled:opacity-50"
            >
              Tekrar çek
            </button>
            <button
              onClick={handleUpload}
              disabled={uploading}
              className={`h-12 px-6 rounded-full text-black text-sm font-bold flex items-center gap-2 active:scale-95 transition disabled:opacity-50 ${
                isDengbej
                  ? "bg-gradient-to-r from-amber-300 via-amber-500 to-amber-700 shadow-[0_0_28px_rgba(255,200,80,0.65)]"
                  : "bg-gradient-to-r from-amber-400 to-amber-600 shadow-lg shadow-amber-500/40"
              }`}
            >
              {uploading ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : isDengbej ? (
                <Mic className="h-4 w-4" />
              ) : (
                <Send className="h-4 w-4" />
              )}
              {isDengbej ? "Dengê Xwe Bişîne" : "Yayınla"}
            </button>
          </>
        ) : recording ? (
          <button
            onClick={stopRecording}
            className="h-16 w-16 rounded-full bg-red-600 border-4 border-white/80 flex items-center justify-center active:scale-95 transition"
            aria-label="Kaydı durdur"
          >
            <Square className="h-6 w-6 text-white fill-white" />
          </button>
        ) : countdown !== null ? (
          <div className="h-16 w-16" />
        ) : (
          <>
            <button
              onClick={() => fileInputRef.current?.click()}
              className="h-12 w-12 rounded-full bg-white/10 border border-white/20 flex items-center justify-center text-white active:scale-95 transition"
              aria-label="Galeriden seç"
              title="Galeriden seç"
            >
              <Upload className="h-5 w-5" />
            </button>
            <button
              onClick={startRecording}
              disabled={!cameraReady}
              className={`h-16 w-16 rounded-full border-4 border-white/80 flex items-center justify-center active:scale-95 transition disabled:opacity-40 ${
                isDengbej
                  ? "bg-gradient-to-br from-amber-300 via-amber-500 to-amber-700 shadow-[0_0_24px_rgba(255,200,80,0.7)]"
                  : "bg-amber-400 shadow-lg shadow-amber-500/50"
              }`}
              aria-label="Kayda başla"
            >
              {isDengbej ? <Mic className="h-6 w-6 text-black" /> : <Camera className="h-6 w-6 text-black" />}
            </button>
            <div className="w-12" />
          </>
        )}
      </div>
    </div>
  );
}

