import { useState } from "react";
import { Flag, UserX, AlertTriangle, Loader2 } from "lucide-react";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { reportKekaVideo, blockUser } from "@/hooks/useKeka";

interface Props {
  open: boolean;
  videoId: string | null;
  videoOwnerId: string | null;
  videoOwnerName?: string | null;
  onOpenChange: (open: boolean) => void;
  onActionComplete?: () => void;
}

const REASONS = [
  { id: "spam", label: "Spam veya yanıltıcı" },
  { id: "harassment", label: "Taciz / nefret söylemi" },
  { id: "violence", label: "Şiddet / tehlikeli içerik" },
  { id: "sexual", label: "Cinsel içerik / uygunsuz" },
  { id: "minor_safety", label: "Çocuk güvenliği" },
  { id: "copyright", label: "Telif ihlali" },
  { id: "other", label: "Diğer" },
];

export function KekaReportSheet({
  open,
  videoId,
  videoOwnerId,
  videoOwnerName,
  onOpenChange,
  onActionComplete,
}: Props) {
  const [mode, setMode] = useState<"menu" | "report" | "block">("menu");
  const [reason, setReason] = useState<string>("");
  const [details, setDetails] = useState("");
  const [busy, setBusy] = useState(false);

  const reset = () => {
    setMode("menu");
    setReason("");
    setDetails("");
    setBusy(false);
  };

  const close = () => {
    reset();
    onOpenChange(false);
  };

  const submitReport = async () => {
    if (!videoId || !reason) return;
    setBusy(true);
    try {
      const res = await reportKekaVideo(videoId, reason, details.trim() || undefined);
      if (res.success) {
        toast.success(
          res.auto_hidden
            ? "Şikayet alındı. Video çoklu rapor nedeniyle gizlendi."
            : "Şikayetin alındı. Moderatörler inceleyecek.",
        );
        onActionComplete?.();
        close();
      } else {
        toast.error(res.error ?? "Şikayet gönderilemedi");
      }
    } catch (e: any) {
      toast.error(e?.message ?? "Şikayet gönderilemedi");
    } finally {
      setBusy(false);
    }
  };

  const submitBlock = async () => {
    if (!videoOwnerId) return;
    setBusy(true);
    try {
      const res = await blockUser(videoOwnerId);
      if (res.success) {
        toast.success(`${videoOwnerName ?? "Kullanıcı"} engellendi. Tekrar görmeyeceksin.`);
        onActionComplete?.();
        close();
      } else {
        toast.error(res.error ?? "Engelleme başarısız");
      }
    } catch (e: any) {
      toast.error(e?.message ?? "Engelleme başarısız");
    } finally {
      setBusy(false);
    }
  };

  return (
    <Sheet
      open={open}
      onOpenChange={(o) => {
        if (!o) reset();
        onOpenChange(o);
      }}
    >
      <SheetContent
        side="bottom"
        className="bg-zinc-950 border-t border-amber-500/20 text-white rounded-t-3xl pb-8 max-h-[80vh]"
      >
        <SheetHeader>
          <SheetTitle className="text-white text-base">
            {mode === "menu" && "Bu içeriği bildir"}
            {mode === "report" && "Şikayet sebebi"}
            {mode === "block" && "Kullanıcıyı engelle"}
          </SheetTitle>
        </SheetHeader>

        {mode === "menu" && (
          <div className="space-y-2 mt-4">
            <button
              onClick={() => setMode("report")}
              className="w-full flex items-center gap-3 p-4 rounded-2xl bg-zinc-900/80 border border-white/10 active:scale-[0.98] transition"
            >
              <Flag className="h-5 w-5 text-amber-400" />
              <div className="text-left flex-1">
                <p className="text-sm font-semibold">Videoyu şikayet et</p>
                <p className="text-xs text-white/55">Topluluk kurallarını ihlal ediyor</p>
              </div>
            </button>
            <button
              onClick={() => setMode("block")}
              disabled={!videoOwnerId}
              className="w-full flex items-center gap-3 p-4 rounded-2xl bg-zinc-900/80 border border-white/10 active:scale-[0.98] transition disabled:opacity-50"
            >
              <UserX className="h-5 w-5 text-red-400" />
              <div className="text-left flex-1">
                <p className="text-sm font-semibold">{videoOwnerName ?? "Kullanıcıyı"} engelle</p>
                <p className="text-xs text-white/55">İçeriklerini ve mesajlarını gizle</p>
              </div>
            </button>
          </div>
        )}

        {mode === "report" && (
          <div className="mt-4 space-y-3">
            <div className="grid gap-2">
              {REASONS.map((r) => (
                <button
                  key={r.id}
                  onClick={() => setReason(r.id)}
                  className={`text-left px-4 py-3 rounded-xl border text-sm transition ${
                    reason === r.id
                      ? "bg-amber-500/15 border-amber-400/60 text-amber-100"
                      : "bg-zinc-900/60 border-white/10 text-white/85"
                  }`}
                >
                  {r.label}
                </button>
              ))}
            </div>
            <Textarea
              value={details}
              onChange={(e) => setDetails(e.target.value)}
              placeholder="Detay (opsiyonel, maks 300 karakter)"
              maxLength={300}
              className="bg-zinc-900/60 border-white/10 text-white text-sm"
              rows={3}
            />
            <div className="flex gap-2 pt-1">
              <Button
                variant="ghost"
                onClick={() => setMode("menu")}
                disabled={busy}
                className="flex-1 text-white/70"
              >
                Geri
              </Button>
              <Button
                onClick={submitReport}
                disabled={!reason || busy}
