            </div>
            <div className="flex gap-2">
              <Button
                variant="ghost"
                onClick={() => setMode("menu")}
                disabled={busy}
                className="flex-1 text-white/70"
              >
                Vazgeç
              </Button>
              <Button
                onClick={submitBlock}
                disabled={busy}
                className="flex-1 bg-red-600 hover:bg-red-700 text-white font-bold"
              >
                {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : "Engelle"}
              </Button>
            </div>
          </div>
        )}
      </SheetContent>
    </Sheet>
  );
}

