import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { toast } from "sonner";
import { Copy, MessageCircle, Send } from "lucide-react";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  videoId: string;
  caption?: string;
  authorName?: string;
}

/**
 * Share KEKA video to WhatsApp / X / Telegram or copy link.
 * Link format: <origin>/keka?v=<videoId>
 */
export function KekaShareSheet({ open, onOpenChange, videoId, caption, authorName }: Props) {
  const url =
    typeof window !== "undefined"
      ? `${window.location.origin}/keka?v=${videoId}`
      : `https://jiyan.world/keka?v=${videoId}`;
  const text = caption?.trim()
    ? `${caption}\n— ${authorName ?? "KEKA"} · Jiyan KEKA`
    : `KEKA'da bu videoyu izle · ${authorName ?? "Jiyan"}`;

  const shareTo = (target: "whatsapp" | "x" | "telegram") => {
    const enc = encodeURIComponent;
    let href = "";
    if (target === "whatsapp") href = `https://wa.me/?text=${enc(text + "\n" + url)}`;
    else if (target === "x")
      href = `https://twitter.com/intent/tweet?text=${enc(text)}&url=${enc(url)}`;
    else if (target === "telegram")
      href = `https://t.me/share/url?url=${enc(url)}&text=${enc(text)}`;
    window.open(href, "_blank", "noopener,noreferrer");
    onOpenChange(false);
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(url);
      toast.success("Bağlantı kopyalandı");
      onOpenChange(false);
    } catch {
      toast.error("Kopyalanamadı");
    }
  };

  const handleNative = async () => {
    try {
      if (navigator.share) {
        await navigator.share({ title: `KEKA · ${authorName ?? ""}`, text, url });
        onOpenChange(false);
      } else {
        handleCopy();
      }
    } catch {
      // user cancelled
    }
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="bottom" className="bg-zinc-950 border-t border-amber-500/20 p-0 rounded-t-3xl">
        <SheetHeader className="px-5 pt-5 pb-2">
          <SheetTitle className="text-white text-base">Paylaş</SheetTitle>
        </SheetHeader>
        <div className="px-5 pb-2 grid grid-cols-4 gap-3">
          <ShareTile
            label="WhatsApp"
            color="bg-emerald-500"
            icon={<MessageCircle className="h-6 w-6 text-white" />}
            onClick={() => shareTo("whatsapp")}
          />
          <ShareTile
            label="X"
            color="bg-black border border-white/20"
            icon={<XIcon />}
            onClick={() => shareTo("x")}
          />
          <ShareTile
            label="Telegram"
            color="bg-sky-500"
            icon={<Send className="h-6 w-6 text-white" />}
            onClick={() => shareTo("telegram")}
          />
          <ShareTile
            label="Kopyala"
            color="bg-amber-500"
            icon={<Copy className="h-6 w-6 text-black" />}
            onClick={handleCopy}
          />
        </div>
        <div className="px-5 pb-5 pt-3">
          <div className="flex items-center gap-2 rounded-xl bg-zinc-900 border border-white/10 px-3 py-2.5">
            <span className="text-[11px] text-white/55 font-mono truncate flex-1">{url}</span>
            <button
              onClick={handleCopy}
              className="text-[11px] text-amber-300 font-bold px-2 py-1 rounded-md bg-amber-500/15 active:scale-95"
            >
              Kopyala
            </button>
          </div>
          {typeof navigator !== "undefined" && "share" in navigator && (
            <button
              onClick={handleNative}
              className="mt-3 w-full h-11 rounded-full bg-white/10 border border-white/15 text-white text-sm font-semibold active:scale-95"
            >
              Daha fazla seçenek…
            </button>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

function ShareTile({
  label,
  color,
  icon,
  onClick,
}: {
  label: string;
  color: string;
  icon: React.ReactNode;
  onClick: () => void;
}) {
  return (
    <button onClick={onClick} className="flex flex-col items-center gap-1.5 active:scale-90 transition">
      <span className={`h-14 w-14 rounded-full flex items-center justify-center ${color}`}>{icon}</span>
      <span className="text-[11px] text-white/85 font-medium">{label}</span>
    </button>
  );
}

function XIcon() {
  return (
    <svg viewBox="0 0 24 24" className="h-5 w-5 text-white" fill="currentColor" aria-hidden>
      <path d="M18.244 2H21.5l-7.5 8.57L23 22h-6.844l-5.36-6.99L4.6 22H1.34l8.04-9.18L1 2h7.02l4.84 6.4L18.244 2Zm-1.2 18h1.84L7.04 4H5.1l11.944 16Z" />
    </svg>
  );
}

