import { useEffect, useRef, useState } from "react";
import { Link } from "@tanstack/react-router";
import { Heart, Share2, Coins, Bookmark, MessageCircle, MoreVertical, EyeOff, Radio, BadgeCheck, Crown, UserPlus, Check, Mic, Star } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import type { KekaVideo } from "@/hooks/useKeka";
import { useFollow } from "@/hooks/useFollow";
import { useAuth } from "@/hooks/useAuth";
import { SovereignStar } from "@/components/keka/SovereignStar";

interface Props {
  video: KekaVideo;
  active: boolean;
  muted: boolean;
  liked: boolean;
  bookmarked: boolean;
  onToggleMute: () => void;
  onLike: () => void;
  onTip: () => void;
  onShare: () => void;
  onBookmark: () => void;
  onComment: () => void;
  onReport: () => void;
  onViewed: (videoId: string) => void;
  onVisible?: () => void;
}

/**
 * Single KEKA video slide. Autoplays when active, pauses otherwise.
 * Records a view (for KEKA-points logic) once the video has played ≥ 80% of its duration.
 */
export function KekaSlide({
  video,
  active,
  muted,
  liked,
  bookmarked,
  onToggleMute,
  onLike,
  onTip,
  onShare,
  onBookmark,
  onComment,
  onReport,
  onViewed,
}: Props) {
  const [revealed, setRevealed] = useState(false);
  const isAdult = !!video.is_adult;
  const ref = useRef<HTMLVideoElement>(null);
  const viewedRef = useRef(false);
  const [progress, setProgress] = useState(0);
  const lastTapRef = useRef(0);
  const [heartBurst, setHeartBurst] = useState<{ x: number; y: number; key: number } | null>(null);

  useEffect(() => {
    const v = ref.current;
    if (!v) return;
    if (active) {
      v.currentTime = 0;
      viewedRef.current = false;
      setProgress(0);
      v.play().catch(() => {});
    } else {
      v.pause();
    }
  }, [active]);

  useEffect(() => {
    const v = ref.current;
    if (!v) return;
    v.muted = muted;
  }, [muted]);

  const handleTimeUpdate = () => {
    const v = ref.current;
    if (!v || !active) return;
    const pct = v.duration ? (v.currentTime / v.duration) * 100 : 0;
    setProgress(pct);
    if (!viewedRef.current && pct >= 80) {
      viewedRef.current = true;
      onViewed(video.id);
    }
  };

  const handleTapZone = (e: React.MouseEvent<HTMLButtonElement>) => {
    const now = Date.now();
    const delta = now - lastTapRef.current;
    if (delta < 280 && delta > 0) {
      // Double tap → like + heart burst
      const rect = e.currentTarget.getBoundingClientRect();
      setHeartBurst({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
        key: now,
      });
      if (!liked) onLike();
      lastTapRef.current = 0;
      window.setTimeout(() => setHeartBurst(null), 700);
    } else {
      lastTapRef.current = now;
      window.setTimeout(() => {
        if (lastTapRef.current === now) onToggleMute();
      }, 280);
    }
  };

  const displayName = video.profile?.display_name || "Anonim";
  const initial = displayName[0]?.toUpperCase() || "?";

  return (
    <section
      data-keka-slide
      className="relative h-[100dvh] w-full snap-start snap-always bg-black"
    >
      {/* Video */}
      <video
        ref={ref}
        poster={video.thumbnail_url ?? undefined}
        playsInline
        loop
        autoPlay
        muted={muted}
        preload={active ? "auto" : "metadata"}
        className="absolute inset-0 h-full w-full object-cover bg-black"
        onTimeUpdate={handleTimeUpdate}
        onError={(e) => {
          const el = e.currentTarget;
          console.error("[KEKA] video error", {
            id: video.id,
            url: video.video_url,
            code: el.error?.code,
            message: el.error?.message,
          });
        }}
        onLoadedData={() => {
          if (active) ref.current?.play().catch(() => {});
        }}
      >
        <source src={video.video_url} type="video/mp4" />
        <source src={video.video_url} type="video/quicktime" />
        <source src={video.video_url} type="video/webm" />
      </video>

      {/* Tap zone — tek dokun: ses, çift dokun: beğen */}
      {active && (
        <button
          aria-label="Sesi aç/kapat veya çift dokunarak beğen"
          onClick={handleTapZone}
          className="absolute inset-y-0 left-0 right-20 z-10 cursor-pointer focus:outline-none"
          style={{ background: "transparent" }}
        />
      )}

      {/* Double-tap heart burst */}
      {heartBurst && (
        <div
          aria-hidden
          className="pointer-events-none absolute z-20"
          style={{ left: heartBurst.x - 40, top: heartBurst.y - 40 }}
        >
          <Heart className="h-20 w-20 fill-red-500 text-red-500 drop-shadow-[0_0_18px_rgba(239,68,68,0.8)] animate-[ping_0.7s_ease-out]" />
        </div>
      )}

      {/* Top progress + brand */}
      <div className="pointer-events-none absolute inset-x-0 top-0 h-32 bg-gradient-to-b from-black/80 via-black/30 to-transparent z-10" />
      <div className="absolute top-3 inset-x-3 z-20 flex items-center justify-center gap-2">
        <div className="flex items-center gap-1 px-2.5 py-1 rounded-full bg-black/55 backdrop-blur border border-amber-400/30">
          <span className="h-1.5 w-1.5 rounded-full bg-amber-400 animate-pulse" />
          <span className="text-[10px] font-bold tracking-widest text-amber-300">KEKA FLOW</span>
        </div>
        {video.is_dengbej && (
          <div className="flex items-center gap-1 px-2.5 py-1 rounded-full bg-amber-950/80 backdrop-blur border border-amber-300/60 shadow-[0_0_12px_rgba(255,200,80,0.45)]">
            <Mic className="h-3 w-3 text-amber-200" />
            <Star className="h-3 w-3 text-amber-200 fill-amber-300" />
            <span className="text-[10px] font-bold tracking-widest text-amber-100">DENGBÊJ</span>
          </div>
        )}
        {(video as KekaVideo & { is_live?: boolean }).is_live && (
          <div className="flex items-center gap-1 px-2.5 py-1 rounded-full bg-red-600/80 backdrop-blur border border-red-300/40">
            <Radio className="h-3 w-3 text-white animate-pulse" />
            <span className="text-[10px] font-bold tracking-widest text-white">CANLI</span>
          </div>
        )}
      </div>

      {/* Bottom gradient + caption */}
      <div className="pointer-events-none absolute inset-x-0 bottom-0 h-72 bg-gradient-to-t from-black/95 via-black/40 to-transparent z-10" />
      <div className="absolute bottom-0 left-0 right-20 z-20 px-4 pb-6">
        <div className="flex items-center gap-2 mb-2">
          <div className="relative">
            <Avatar className="h-9 w-9 ring-2 ring-amber-400/60">
              <AvatarImage src={video.profile?.avatar_url ?? undefined} />
              <AvatarFallback className="bg-amber-500/30 text-amber-100 text-xs">{initial}</AvatarFallback>
            </Avatar>
            <KekaInlineFollow targetUserId={video.user_id} />
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-1">
              <p className="text-sm font-bold text-white truncate drop-shadow">{displayName}</p>
              {video.profile?.is_verified_creator && (
                <BadgeCheck className="h-4 w-4 text-amber-300 fill-amber-400/30 drop-shadow" aria-label="Doğrulanmış Yaratıcı" />
              )}
              {video.profile?.is_premium && !video.profile?.is_verified_creator && (
                <Crown className="h-3.5 w-3.5 text-amber-300 fill-amber-400/40" aria-label="Egemen — Sovereign" />
              )}
            </div>
            {video.profile?.kurd_id && (
              <p className="text-[10px] font-mono text-amber-300/85">{video.profile.kurd_id}</p>
            )}
          </div>
        </div>
        {video.caption && (
          <CaptionWithTags caption={video.caption} />
        )}
      </div>

      {/* Right action rail — TikTok style */}
      <div className="absolute bottom-28 right-2 z-20 flex flex-col items-center gap-5">
        <ActionButton
          icon={<Heart className={`h-7 w-7 ${liked ? "fill-red-500 text-red-500" : "text-white"}`} />}
          label={video.like_count.toLocaleString()}
          onClick={onLike}
        />
        <ActionButton
          icon={<MessageCircle className="h-7 w-7 text-white" />}
          label={video.comment_count.toLocaleString()}
          onClick={onComment}
        />
        <ActionButton
          icon={<Bookmark className={`h-7 w-7 ${bookmarked ? "fill-amber-300 text-amber-300" : "text-white"}`} />}
          label="Kaydet"
          onClick={onBookmark}
        />
        <ActionButton
          icon={<Coins className={`h-7 w-7 ${video.is_dengbej ? "text-amber-200 drop-shadow-[0_0_8px_rgba(255,200,80,0.85)]" : "text-amber-300"}`} />}
          label={video.tip_count.toLocaleString()}
          onClick={onTip}
          glow
          honor={video.is_dengbej}
        />
        <ActionButton
          icon={<Share2 className="h-7 w-7 text-white" />}
          label="Paylaş"
          onClick={onShare}
        />
        <ActionButton
          icon={<MoreVertical className="h-6 w-6 text-white" />}
          label=""
          onClick={onReport}
        />
      </div>

      {/* 18+ overlay until user reveals */}
      {isAdult && !revealed && (
        <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black/85 backdrop-blur-sm px-8 text-center">
          <EyeOff className="h-12 w-12 text-amber-300 mb-3" />
          <p className="text-white font-bold text-lg">18+ İçerik</p>
          <p className="text-white/65 text-sm mt-1 max-w-xs">
            Bu video yetişkin içerik olarak işaretlendi. Devam etmek için yaşının uygun olduğunu onaylıyorsun.
          </p>
          <button
            onClick={() => setRevealed(true)}
            className="mt-5 h-11 px-6 rounded-full bg-amber-500 text-black text-sm font-bold active:scale-95"
          >
            18 yaşımdan büyüğüm, göster
          </button>
        </div>
      )}

      {/* Sovereign Star watermark — bottom-right (above bottom progress, below action rail) */}
      <div
        aria-hidden
        className="pointer-events-none absolute bottom-3 right-2 z-10 opacity-80 mix-blend-screen"
        style={{ filter: "drop-shadow(0 0 6px rgba(255,200,80,0.45))" }}
      >
        <SovereignStar size={28} />
      </div>

      {/* Dengbêj corner mark — Mic + Star, distinguishes cultural clips */}
      {video.is_dengbej && (
        <div
          aria-hidden
          className="pointer-events-none absolute top-16 right-3 z-10 flex items-center gap-1 px-2 py-1 rounded-full bg-black/55 backdrop-blur border border-amber-300/50"
          style={{ filter: "drop-shadow(0 0 6px rgba(255,200,80,0.4))" }}
        >
          <Mic className="h-3 w-3 text-amber-200" />
          <Star className="h-3 w-3 text-amber-200 fill-amber-300" />
        </div>
      )}

      {/* Bottom progress bar */}
      {active && (
        <div className="absolute bottom-0 inset-x-0 z-20 h-0.5 bg-white/10">
          <div
            className="h-full bg-amber-400 transition-[width] duration-200"
            style={{ width: `${progress}%` }}
          />
        </div>
      )}
    </section>
  );
}

function ActionButton({
  icon,
  label,
  onClick,
  glow,
  honor,
}: {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  glow?: boolean;
  honor?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      className="flex flex-col items-center gap-0.5 active:scale-90 transition"
    >
      <span
        className={`h-11 w-11 rounded-full flex items-center justify-center backdrop-blur border ${
          honor
            ? "bg-amber-500/30 border-amber-300/80 shadow-[0_0_24px_rgba(255,200,80,0.7)] animate-pulse"
            : glow
              ? "bg-amber-500/15 border-amber-400/50 shadow-[0_0_18px_rgba(255,215,0,0.35)]"
              : "bg-black/45 border-white/15"
        }`}
      >
        {icon}
      </span>
      {label && <span className={`text-[10px] font-semibold drop-shadow ${honor ? "text-amber-200" : "text-white/85"}`}>{label}</span>}
    </button>
  );
}

/**
 * Renders caption text with #hashtags as clickable links to /keka/tag/$tag.
 */
function CaptionWithTags({ caption }: { caption: string }) {
  const parts = caption.split(/(#[A-Za-z0-9_]{1,40})/g);
  return (
    <p className="text-[13px] text-white/95 leading-snug drop-shadow line-clamp-3">
      {parts.map((p, i) => {
        if (p.startsWith("#")) {
          const tag = p.slice(1).toLowerCase();
          return (
            <Link
              key={i}
              to="/keka/tag/$tag"
              params={{ tag }}
              onClick={(e) => e.stopPropagation()}
              className="text-amber-300 font-semibold hover:underline"
            >
              {p}
            </Link>
          );
        }
        return <span key={i}>{p}</span>;
      })}
    </p>
  );
}

/**
 * Small "+" follow chip overlapping the avatar (TikTok style).
 * Hides if you are the owner. Renders a check after follow.
 */
function KekaInlineFollow({ targetUserId }: { targetUserId: string }) {
  const { user } = useAuth();
  const { isFollowing, loading, toggle } = useFollow(targetUserId);
  if (!user || user.id === targetUserId) return null;
  if (isFollowing) {
    return (
      <span
        aria-label="Takip ediliyor"
        className="absolute -bottom-1.5 left-1/2 -translate-x-1/2 h-5 w-5 rounded-full bg-emerald-500 flex items-center justify-center ring-2 ring-black"
      >
        <Check className="h-3 w-3 text-white" strokeWidth={3} />
      </span>
    );
  }
  return (
    <button
      onClick={(e) => {
        e.stopPropagation();
        toggle();
      }}
      disabled={loading}
      aria-label="Takip et"
      className="absolute -bottom-1.5 left-1/2 -translate-x-1/2 h-5 w-5 rounded-full bg-red-500 flex items-center justify-center ring-2 ring-black active:scale-90 transition disabled:opacity-50"
    >
      <UserPlus className="h-3 w-3 text-white" strokeWidth={3} />
    </button>
  );
}

