import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Coins, Loader2 } from "lucide-react";
import { useState } from "react";

const AMOUNTS: Array<1 | 5 | 10> = [1, 5, 10];

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSend: (amount: 1 | 5 | 10) => Promise<void>;
  creatorName: string;
}

export function KekaTipDialog({ open, onOpenChange, onSend, creatorName }: Props) {
  const [busy, setBusy] = useState<1 | 5 | 10 | null>(null);

  const handleClick = async (amount: 1 | 5 | 10) => {
    setBusy(amount);
    try {
      await onSend(amount);
    } finally {
      setBusy(null);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-black border-amber-400/30 max-w-xs">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-amber-300">
            <Coins className="h-5 w-5" />
            Tip gönder
          </DialogTitle>
        </DialogHeader>
        <p className="text-xs text-white/60 -mt-2">
          <span className="text-amber-300 font-semibold">{creatorName}</span> içeriğini destekle.
        </p>
        <div className="grid grid-cols-3 gap-2 mt-1">
          {AMOUNTS.map((amt) => (
            <button
              key={amt}
              onClick={() => handleClick(amt)}
              disabled={busy !== null}
              className="relative flex flex-col items-center justify-center py-4 rounded-2xl bg-gradient-to-br from-amber-400/20 to-amber-600/10 border border-amber-400/40 active:scale-95 transition-all disabled:opacity-50"
            >
              {busy === amt ? (
                <Loader2 className="h-5 w-5 animate-spin text-amber-300" />
              ) : (
                <>
                  <Coins className="h-5 w-5 text-amber-300 mb-1" />
                  <span className="text-lg font-bold text-amber-200">{amt}</span>
                  <span className="text-[9px] text-amber-300/70 uppercase tracking-wider">DC</span>
                </>
              )}
            </button>
          ))}
        </div>
        <p className="text-[10px] text-white/40 text-center mt-2">
          %5 platform komisyonu uygulanır.
        </p>
      </DialogContent>
    </Dialog>
