import { Link } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { Eye, Loader2, Sparkles } from "lucide-react";
import { fetchUserKekaVideos, type KekaVideo } from "@/hooks/useKeka";

interface Props {
  userId: string;
}

/**
 * Instagram-style 3-column KEKA grid for profile pages.
 */
export function ProfileKekaGrid({ userId }: Props) {
  const [videos, setVideos] = useState<KekaVideo[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    fetchUserKekaVideos(userId)
      .then(setVideos)
      .finally(() => setLoading(false));
  }, [userId]);

  if (loading) {
    return (
      <div className="flex justify-center py-10">
        <Loader2 className="h-5 w-5 animate-spin text-amber-300" />
      </div>
    );
  }

  if (videos.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
        <Sparkles className="h-10 w-10 text-amber-300/50 mb-2" />
        <p className="text-sm font-semibold text-foreground">Henüz KEKA yok</p>
        <p className="text-xs text-muted-foreground mt-1 max-w-xs">
          15 saniyelik dikey video çek, KEKA puanı ve DC kazan.
        </p>
        <Link
          to="/keka"
          className="mt-4 h-10 px-4 rounded-full bg-gradient-to-r from-amber-400 to-amber-600 text-black text-xs font-bold inline-flex items-center"
        >
          KEKA Flow'u aç
        </Link>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-3 gap-0.5">
      {videos.map((v) => (
        <Link
          key={v.id}
          to="/keka"
          search={{ v: v.id } as never}
          className="relative aspect-[9/14] bg-zinc-900 overflow-hidden active:opacity-70"
        >
          {v.thumbnail_url ? (
            <img
              src={v.thumbnail_url}
              alt={v.caption || "KEKA"}
              loading="lazy"
              className="absolute inset-0 h-full w-full object-cover"
            />
          ) : (
            <video
              src={v.video_url}
              preload="metadata"
              muted
              playsInline
              className="absolute inset-0 h-full w-full object-cover"
            />
          )}
          <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 to-transparent px-1.5 py-1 flex items-center gap-1">
            <Eye className="h-3 w-3 text-white" />
            <span className="text-[10px] font-bold text-white">
              {v.view_count >= 1000
                ? `${(v.view_count / 1000).toFixed(1)}K`
                : v.view_count}
            </span>
          </div>
        </Link>
      ))}
    </div>
  );
}

