import { useEffect, useState } from "react";
import { Activity } from "lucide-react";

/**
 * Live Global Pulse — "Anlık Egemen Sayısı"
 * Shows a smoothly-incrementing live counter of sovereign citizens online.
 * Pure visual effect — no real backend hit (kept lightweight for landing).
 */
export function GlobalPulseCounter() {
  const [count, setCount] = useState(52_847);

  useEffect(() => {
    const id = setInterval(() => {
      setCount((c) => c + Math.floor(Math.random() * 3) + 1);
    }, 1800);
    return () => clearInterval(id);
  }, []);

  return (
    <div className="relative z-20 inline-flex items-center gap-3 rounded-full border border-gold/30 bg-background/60 px-4 py-2 backdrop-blur-xl shadow-[0_0_30px_-5px_oklch(0.82_0.16_85/0.35)]">
      {/* Animated pulse dot */}
      <span className="relative flex h-2.5 w-2.5">
        <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-gold opacity-70" />
        <span className="relative inline-flex h-2.5 w-2.5 rounded-full bg-gold" />
      </span>

      <Activity className="h-3.5 w-3.5 text-gold" />

      <div className="flex items-baseline gap-1.5">
        <span className="text-[10px] font-bold uppercase tracking-[0.25em] text-muted-foreground">
          Anlık Egemen
        </span>
        <span className="text-sm font-black tabular-nums text-gold text-glow-gold">
          {count.toLocaleString("tr-TR")}
        </span>
      </div>
    </div>
  );
}

