import { useSwipeDownBack } from "@/hooks/useSwipeDownBack";
import { HubHomeIndicator } from "@/components/hub/HubHomeIndicator";
import { ThemeBridge } from "@/components/hub/ThemeBridge";
import { SovereignShieldIndicator } from "@/components/auth/SovereignShieldIndicator";
import { SovereignDynamicDock } from "@/components/hub/SovereignDynamicDock";
import { SheetShell } from "@/components/layout/SheetShell";
import { FloatingBackButton } from "@/components/layout/FloatingBackButton";
import { MiniAppOverlay } from "@/components/layout/MiniAppOverlay";
import { IncomingCallIsland } from "@/components/phone/IncomingCallIsland";
import { SovereignCallScreen } from "@/components/phone/SovereignCallScreen";
import { SovereignIncomingScreen } from "@/components/phone/SovereignIncomingScreen";
import { HapticGlowPulse } from "@/components/phone/HapticGlowPulse";
import { FloatingActiveCallPill } from "@/components/phone/FloatingActiveCallPill";
// SovereignPhoneProvider is mounted once at the route root (__root.tsx) so the
// phone hook works for any page, including those that call it above AppShell.
// SovereignAssistant + DengOrb floating buttons removed — Deng AI is now a fixed top tab in /chat.

/**
 * AppShell — Sovereign OS chrome.
 *
 * NO tab bars, NO drawers. The only persistent navigation surface is the
 * Apple-style Sovereign Dynamic Dock (4 pinned slots, long-press → jiggle,
 * drag-to-swap), which floats at the bottom on every authenticated route.
 *
 * The dock is hidden on:
 *   • The Hub itself (it mounts its own copy already)
 *   • KEKA full-screen flow (immersive)
 *   • The unauthenticated landing / login flow
 */
export function AppShell({ children }: { children: React.ReactNode }) {
  const { open, setOpen } = useGlobalSearch();
  // tourOpen removed with WelcomeTour.
  const location = useLocation();
  const { user } = useAuth();
  const isImmersiveRoute = location.pathname.startsWith("/games");

  // Hide chrome on the Hub itself + KEKA full-screen flow + landing for guests.
  const isHubRoot = location.pathname === "/" && !!user;
  const isHubRoute = location.pathname === "/hub" || location.pathname.startsWith("/hub/");
  const onKeka = location.pathname.startsWith("/keka");
  const onLogin =
    location.pathname.startsWith("/login") ||
    location.pathname.startsWith("/reset-password");
  const hideChrome = isHubRoot || isHubRoute || onKeka || !user;

  // Global Floating Dock removed from all mini-apps per product decision.
  // The Hub root mounts its own dock; mini-apps are dock-free for an
  // immersive single-task feel (swipe-down / back-pill to return to Hub).
  const showGlobalDock = false;

  // Telegram-style global gestures — swipe from left edge OR pull down from
  // the top header strip to close the current screen (history.back()).
  useEdgeSwipeBack();
  useSwipeDownBack();

  // Legacy global hook kept as a no-op so settings.tsx "Tekrar başlat" doesn't crash.
  if (typeof window !== "undefined") {
    (window as any).__openJiyanTour = () => { /* tour disabled */ };
  }

  return (
    <div
      className="min-h-screen overflow-x-hidden w-full"
      style={{
        background: "var(--hub-page-bg, var(--background))",
        color: "var(--hub-text-primary, var(--foreground))",
      }}
    >
      {/* Push active Görünüm theme tokens onto :root for every screen. */}
      <ThemeBridge />

      {/* Floating Search button removed — clashed with the luxury OS chrome.
          Cmd/Ctrl+K still opens GlobalSearch on desktop; mobile uses Joogle
          omnibox + dock gestures. */}

      {/* Mini-app overlay sistemi (Faz 2): authed kullanıcı bir mini-app
          route'undaysa içerik TGSheet ile öne kaydırılır, Hub arka planda
          kalır. /, /hub, /keka, /games ve login akışları HARİÇ.

          Telefon (`/phone`) WhatsApp/iPhone tarzı tam-ekran sahip — kendi
          safe-area'sını + alt dock'unu yönetir, AppShell padding'i 0 olur. */}
      {(() => {
        const isPhone = location.pathname.startsWith("/phone");
        const padTop = isPhone ? "0px" : "calc(env(safe-area-inset-top, 0px) + 70px)";
        const padBottom = isPhone
          ? "0px"
          : "calc(80px + env(safe-area-inset-bottom, 0px))";
        const padBottomFlat = isPhone
          ? "0px"
          : hideChrome
            ? undefined
            : "64px";
        return !hideChrome && !isImmersiveRoute ? (
          <MiniAppOverlay>
            <main
              key={location.pathname}
              className="mx-auto max-w-lg overflow-x-hidden w-full"
              style={{
                paddingTop: padTop,
                paddingBottom: padBottom,
                transform: "translateZ(0)",
                willChange: "transform, opacity",
              }}
            >
              {children}
            </main>
          </MiniAppOverlay>
        ) : (
          <main
            key={location.pathname}
            className={`mx-auto max-w-lg overflow-x-hidden w-full animate-mini-app-in`}
            style={{
              paddingTop: padTop,
              paddingBottom: padBottomFlat,
              transform: "translateZ(0)",
              willChange: "transform, opacity",
            }}
          >
            <SheetShell disabled={hideChrome}>{children}</SheetShell>
          </main>
        );
      })()}

      {/* iOS-style slim gold home-indicator (replaces the legacy Hub pill). */}
      {!hideChrome && <HubHomeIndicator />}

      {/* Cross-app sovereign sync indicator — only renders when relevant. */}
      {user && <SovereignShieldIndicator />}

      {/* Apple-style Sovereign Dynamic Dock — globally mounted on every
          authenticated, non-immersive, non-Hub route. The Hub mounts its own
          copy with `onAppTap` overrides for half-modal sheets. */}
      {showGlobalDock && <SovereignDynamicDock />}

      {/* Floating glass back-pill — visible on every authed mini-app route
          (hidden on Hub root via the component's own check). Provides a
          reliable "return to Springboard" affordance alongside the
          Telegram-style swipe gestures. */}
      {!hideChrome && <FloatingBackButton />}

      <NotificationListener />

      {/* Sovereign Phone — global Dynamic Island for incoming calls and the
          full-screen in-call overlay. Both render conditionally based on the
          shared phone hook so any route can dial / receive. */}
      {!!user && <IncomingCallIsland />}
      {!!user && <SovereignIncomingScreen />}
      {!!user && <SovereignCallScreen />}
      {!!user && <HapticGlowPulse />}
      {!!user && <FloatingActiveCallPill />}
      {/* Floating Deng AI / Sovereign Assistant orbs removed — Deng AI now lives
          as a fixed top tab inside /chat (no more overlapping floating buttons). */}
      <GlobalSearch open={open} onOpenChange={setOpen} />
      {/* WelcomeTour disabled globally — onboarding now lives inline in /sovereign-space.
          Kept import-free so the modal never blocks any route (e.g. /linguist). */}
      <InstallPrompt />
      <Toaster position="top-center" richColors />
    </div>
  );
}

