/**
 * FloatingBackButton — Apple-style glass pill back button.
 *
 * Mounted globally by AppShell on every authenticated route EXCEPT the Hub
 * root. Uses TanStack Router history; if there is no in-app history (deep
 * link / fresh tab) it falls back to "/" so users never get trapped.
 *
 * Visual: 44×44 squircle, dark frosted glass, gold hairline, top-left,
 * safe-area aware. Matches the Sovereign Dynamic Dock material.
 */
import { useNavigate, useLocation } from "@tanstack/react-router";
import { ChevronLeft } from "lucide-react";
import { hapticTap } from "@/lib/native";

const GOLD_LIGHT = "#FFE9A8";

export function FloatingBackButton() {
  const navigate = useNavigate();
  const location = useLocation();

  // Don't render on the Hub root — there's nowhere to go back to.
  if (location.pathname === "/" || location.pathname === "/hub") return null;

  const handleBack = () => {
    hapticTap();
    // Hub-centric model: every mini-app back button returns to the Hub
    // root so users never get stranded inside redirect chains
    // (e.g. /phone → /chat) or deep nested sub-routes.
    navigate({ to: "/" });
  };

  return (
    <button
      type="button"
      onClick={handleBack}
      aria-label="Geri"
      data-testid="floating-back-button"
      className="fixed left-3 z-[1100] flex items-center justify-center active:scale-95 transition-transform"
      style={{
        top: "calc(env(safe-area-inset-top, 0px) + 10px)",
        width: 44,
        height: 44,
        borderRadius: 16,
        background:
          "linear-gradient(180deg, rgba(40,28,5,0.65) 0%, rgba(8,6,2,0.85) 100%)",
        backdropFilter: "blur(28px) saturate(180%)",
        WebkitBackdropFilter: "blur(28px) saturate(180%)",
        border: "0.75px solid rgba(245,205,83,0.45)",
        boxShadow: [
          "0 6px 18px -4px rgba(0,0,0,0.7)",
          "inset 0 1px 0 rgba(255,234,170,0.22)",
          "inset 0 -1px 0 rgba(0,0,0,0.5)",
        ].join(", "),
        color: GOLD_LIGHT,
      }}
    >
      <ChevronLeft className="h-5 w-5" strokeWidth={2.4} />
    </button>
  );
}

