/**
 * MiniAppHeader — Telegram-style transparent blurred header for mini-apps.
 *
 * Replaces traditional in-page top bars and back buttons. Shows ONLY the
 * app name centred over a frosted glass strip. The header itself is the
 * drag handle for the global "swipe-down-to-close" gesture (handled by
 * `useSwipeDownBack` mounted in AppShell), so no explicit chrome is needed.
 *
 * Use at the very top of any mini-app / settings / profile screen instead
 * of a custom header + back button.
 */
import type { ReactNode } from "react";

interface Props {
  title: string;
  /** Optional trailing slot (e.g. an action icon). Keep to a single icon. */
  trailing?: ReactNode;
}

export function MiniAppHeader({ title, trailing }: Props) {
  return (
    <header
      className="sticky top-0 z-30 w-full"
      style={{
        // Hardware-accelerated layer — keeps blur off the main paint path.
        transform: "translateZ(0)",
        willChange: "transform",
        paddingTop: "env(safe-area-inset-top, 0px)",
        background:
          "linear-gradient(180deg, rgba(10,10,12,0.55) 0%, rgba(10,10,12,0.30) 70%, rgba(10,10,12,0) 100%)",
        backdropFilter: "blur(24px) saturate(160%)",
        WebkitBackdropFilter: "blur(24px) saturate(160%)",
      }}
    >
      {/* iOS-style top "grabber" hint — visual cue that this surface can be
          swiped away. */}
      <div
        aria-hidden
        className="mx-auto mt-1.5 h-[5px] w-9 rounded-full"
        style={{ background: "rgba(255,255,255,0.22)" }}
      />
      <div className="relative flex items-center justify-center px-4 py-2.5">
        <h1
          className="text-[15px] font-semibold tracking-tight text-white/95 truncate max-w-[70%]"
          style={{ textShadow: "0 1px 2px rgba(0,0,0,0.5)" }}
        >
          {title}
        </h1>
        {trailing && (
          <div className="absolute right-3 top-1/2 -translate-y-1/2">
            {trailing}
          </div>
        )}
      </div>
    </header>
  );
}

