/**
 * MiniAppOverlay — jsdom E2E for scroll + swipe-down close.
 *
 * Verifies the two behaviors users complained about across every mini-app:
 *
 *   1. The overlay container scrolls vertically (overflow-y: auto), so tall
 *      children are reachable. The freezing bug came from overflow-hidden;
 *      this test locks the fix.
 *   2. The uniform top-right ✕ button + top grab handle exist on every
 *      mini-app and trigger a navigate("/") through the swipe-close path.
 *   3. Escape key closes (keyboard a11y parity with swipe).
 *   4. The pure swipe-dismiss predicate honours the new sensitivity contract
 *      (110 px / 700 px·s⁻¹) — locks the Telegram-grade UX promise.
 *
 * We mock @tanstack/react-router so the overlay renders without a real
 * router tree and we can spy on navigate().
 */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, fireEvent } from "@testing-library/react";

const navigateSpy = vi.fn();

vi.mock("@tanstack/react-router", () => ({
  useNavigate: () => navigateSpy,
  useLocation: () => ({ pathname: "/pazar" }),
}));

// Hub icon rect lookup is irrelevant in jsdom — return null so the overlay
// uses its fade-out exit path. (Module-level mock keeps it simple.)
vi.mock("@/lib/appLaunchOrigin", () => ({
  consumeLaunchOrigin: () => null,
  getIconRect: () => null,
}));

vi.mock("@/components/hub/HubNebulaField", () => ({
  HubNebulaField: () => null,
}));

import { MiniAppOverlay, shouldDismiss } from "@/components/layout/MiniAppOverlay";

beforeEach(() => {
  navigateSpy.mockClear();
});

describe("MiniAppOverlay — scroll + swipe-close E2E", () => {
  it("renders a vertically scrollable container so tall children scroll", () => {
    const { getByTestId } = render(
      <MiniAppOverlay>
        <div data-testid="tall" style={{ height: 4000 }}>
          long content
        </div>
      </MiniAppOverlay>,
    );
    const overlay = document.querySelector("[data-mini-app-overlay]") as HTMLElement;
    expect(overlay).toBeTruthy();
    expect(overlay.className).toMatch(/overflow-y-auto/);
    expect(overlay.className).not.toMatch(/(^|\s)overflow-hidden(\s|$)/);
    expect(getByTestId("tall")).toBeTruthy();
  });

  it("exposes the uniform top-right ✕ button on every mini-app", () => {
    const { getByTestId } = render(
      <MiniAppOverlay>
        <div>app body</div>
      </MiniAppOverlay>,
    );
    const closeBtn = getByTestId("mini-app-close");
    expect(closeBtn.getAttribute("aria-label")).toBe("Kapat");
  });

  it("clicking ✕ triggers navigate('/') after the shrink animation", async () => {
    const { getByTestId } = render(
      <MiniAppOverlay>
        <div>app body</div>
      </MiniAppOverlay>,
    );
    fireEvent.click(getByTestId("mini-app-close"));
    await new Promise((r) => setTimeout(r, 260));
    expect(navigateSpy).toHaveBeenCalledWith({ to: "/" });
  });

  it("Escape key closes the overlay (keyboard a11y parity with swipe)", async () => {
    render(
      <MiniAppOverlay>
        <div>app body</div>
      </MiniAppOverlay>,
    );
    fireEvent.keyDown(window, { key: "Escape" });
    await new Promise((r) => setTimeout(r, 260));
    expect(navigateSpy).toHaveBeenCalledWith({ to: "/" });
  });

  it("exposes the top grab handle with proper screen-reader label", () => {
    const { getByTestId } = render(
      <MiniAppOverlay>
        <div>app body</div>
      </MiniAppOverlay>,
    );
    const handle = getByTestId("mini-app-handle");
    expect(handle.getAttribute("aria-label")).toBe("Mini uygulamayı kapat");
  });

  it("swipe predicate commits at the new Telegram-grade sensitivity", () => {
    // 120 px deliberate pull → dismiss; 90 px wobble → stay.
    expect(shouldDismiss(120, 0)).toBe(true);
    expect(shouldDismiss(90, 0)).toBe(false);
    // 750 px/s flick from a tiny offset → dismiss.
    expect(shouldDismiss(20, 750)).toBe(true);
    // Upward (page-scroll) gestures never dismiss.
    expect(shouldDismiss(-300, -1500)).toBe(false);
  });
});

