/**
 * MiniAppOverlay swipe-dismiss tests.
 *
 * The overlay collapses back into its launching Hub icon when the user swipes
 * down past either threshold:
 *   • offset    > 110px          (deliberate pull, easier than 140 — Telegram-grade)
 *   • velocity  > 700 px/s       (fast flick from a small offset)
 *
 * These thresholds are the public contract used by motion handlers and any
 * future gesture providers. We test the pure predicate to lock the contract
 * without spinning up framer-motion / DOM gestures.
 */
import { describe, it, expect } from "vitest";
import {
  shouldDismiss,
  SWIPE_DISMISS_OFFSET_PX,
  SWIPE_DISMISS_VELOCITY,
} from "@/components/layout/MiniAppOverlay";

describe("MiniAppOverlay shouldDismiss", () => {
  it("exports the documented thresholds", () => {
    expect(SWIPE_DISMISS_OFFSET_PX).toBe(110);
    expect(SWIPE_DISMISS_VELOCITY).toBe(700);
  });

  it("does NOT dismiss for tiny pulls under both thresholds", () => {
    expect(shouldDismiss(0, 0)).toBe(false);
    expect(shouldDismiss(50, 100)).toBe(false);
    expect(shouldDismiss(SWIPE_DISMISS_OFFSET_PX, SWIPE_DISMISS_VELOCITY)).toBe(false); // strictly greater
  });

  it("dismisses when offset exceeds threshold even at zero velocity", () => {
    expect(shouldDismiss(SWIPE_DISMISS_OFFSET_PX + 1, 0)).toBe(true);
    expect(shouldDismiss(300, 0)).toBe(true);
  });

  it("dismisses on fast flick when velocity exceeds threshold, even at small offset", () => {
    expect(shouldDismiss(20, SWIPE_DISMISS_VELOCITY + 1)).toBe(true);
    expect(shouldDismiss(0, 1500)).toBe(true);
  });

  it("ignores upward gestures (negative offset / velocity)", () => {
    expect(shouldDismiss(-200, -1000)).toBe(false);
    expect(shouldDismiss(-50, 0)).toBe(false);
  });

  it("either threshold alone is enough — they are OR'd, not AND'd", () => {
    expect(shouldDismiss(200, 0)).toBe(true);
    expect(shouldDismiss(0, 1000)).toBe(true);
  });

  it("is more permissive than the previous 140/800 contract", () => {
    // Confirms the sensitivity tweak: a 120px pull or 750 px/s flick now
    // dismisses where it previously wouldn't have. Locks the UX promise.
    expect(shouldDismiss(120, 0)).toBe(true);
    expect(shouldDismiss(0, 750)).toBe(true);
  });
});

