/**
 * MiniAppOverlay — Global Wrapper for Apple-grade mini-app transitions.
 *
 * Açılış: Hub'da tıklanan ikonun ekran rect'i `appLaunchOrigin` üzerinden
 *   yakalanır → overlay o rect'ten tam ekrana snappy spring ile açılır
 *   (shared element illusion, layoutId yerine cross-tree rect bridge).
 *
 * Kapanış: Üstten aşağıya swipe → eşik aşılırsa overlay küçülerek aynı
 *   ikona geri uçar → /'a navige eder. Deep-link'le açıldıysa (origin yok)
 *   ekrana doğru fade+scale-out yapar.
 *
 * Hız: framer-motion `spring` — stiffness 480, damping 38 → ~150ms snappy
 *   "Apple App Library" hissi. Mass minimal, restDelta sıkı.
 *
 * Tüm mini-app'ler için tek standart wrapper — istisnasız.
 */
import { ReactNode, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate, useLocation } from "@tanstack/react-router";
import { motion, AnimatePresence, useDragControls, useMotionValue, useTransform, type Transition } from "framer-motion";
import { X } from "lucide-react";
import { HubNebulaField } from "@/components/hub/HubNebulaField";
import { consumeLaunchOrigin, getIconRect, type LaunchOrigin } from "@/lib/appLaunchOrigin";
import { appIdFromPath } from "@/lib/hubApps";

interface Props {
  children: ReactNode;
}

/** Apple-grade snappy spring (~120-180ms perceived). */
const SPRING: Transition = {
  type: "spring",
  stiffness: 480,
  damping: 38,
  mass: 0.55,
  restDelta: 0.5,
};

/** Convert an icon rect (top-left x/y/w/h) into transform values that map a
 *  fullscreen layer back onto the icon. We use scale + translate of the
 *  layer's center against the viewport center. */
function rectToCollapsedTransform(rect: LaunchOrigin["rect"]) {
  if (typeof window === "undefined") {
    return { scale: 0.18, x: 0, y: 0, opacity: 0 };
  }
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const iconCenterX = rect.x + rect.width / 2;
  const iconCenterY = rect.y + rect.height / 2;
  const screenCenterX = vw / 2;
  const screenCenterY = vh / 2;
  // Target: the fullscreen layer (vw×vh) becomes the icon (rect.w×rect.h)
  // sitting at the icon's center.
  const scale = Math.max(rect.width / vw, rect.height / vh);
  return {
    scale,
    x: iconCenterX - screenCenterX,
    y: iconCenterY - screenCenterY,
    opacity: 0.4,
    borderRadius: 22,
  };
}

const FULLSCREEN = { scale: 1, x: 0, y: 0, opacity: 1, borderRadius: 0 };

export function MiniAppOverlay({ children }: Props) {
  const navigate = useNavigate();
  const location = useLocation();

  /** Origin captured at icon-tap time (or null for deep-links). Read
   *  synchronously on first render so framer-motion's `initial` matches the
   *  icon rect on the very first frame (no fallback flash). */
  const [origin, setOrigin] = useState<LaunchOrigin | null>(() =>
    typeof window === "undefined" ? null : consumeLaunchOrigin(),
  );
  /** Drag progress 0..1 used by the Springboard backdrop. */
  const dragY = useMotionValue(0);
  const dragControls = useDragControls();
  const [closing, setClosing] = useState(false);
  const closingTargetRef = useRef<LaunchOrigin["rect"] | null>(null);

  // On every route change INTO a different mini-app, consume a fresh origin.
  const lastPathRef = useRef(location.pathname);
  useEffect(() => {
    if (lastPathRef.current !== location.pathname) {
      lastPathRef.current = location.pathname;
      setOrigin(consumeLaunchOrigin());
      setClosing(false);
      dragY.set(0);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.pathname]);

  /** Springboard backdrop: scales 0.92→1 as user drags overlay down. Range
   *  matches the dismiss threshold (110px) so the parallax peaks exactly when
   *  the gesture commits — Telegram-style "rubber band ready to snap". */
  const backdropScale = useTransform(dragY, [0, 220], [0.92, 1]);
  const backdropBlur = useTransform(dragY, [0, 220], [6, 0]);
  const backdropFilter = useTransform(backdropBlur, (b) => `blur(${b}px) brightness(${0.7 + (6 - b) * 0.05})`);
  /** Live overlay opacity reacts to drag — gives the user immediate visual
   *  confirmation that swipe-down will close. Bottoms out at 0.55 so content
   *  stays legible if the user releases below threshold. */
  const overlayOpacity = useTransform(dragY, [0, 220], [1, 0.55]);
  const overlayScale = useTransform(dragY, [0, 220], [1, 0.94]);

  /** Compute the close-target rect: prefer remembered icon rect for the
   *  current route's appId, else the original launch origin. */
  const closeTargetRect = useMemo(() => {
    const appId = appIdFromPath(location.pathname);
    return getIconRect(appId) ?? origin?.rect ?? null;
  }, [location.pathname, origin]);

  const handleClose = () => {
    if (closing) return;
    closingTargetRef.current = closeTargetRect;
    setClosing(true);
    // Wait for shrink-to-icon animation, then navigate Home.
    window.setTimeout(() => {
      navigate({ to: "/" });
    }, 220);
  };

  // Keyboard a11y: Escape closes the overlay, mirroring the swipe-down
  // gesture so keyboard / screen-reader users have the same exit affordance.
  useEffect(() => {
    if (closing) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        handleClose();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [closing, closeTargetRect]);

  const initialTransform = origin
    ? rectToCollapsedTransform(origin.rect)
    : { scale: 0.96, x: 0, y: 0, opacity: 0, borderRadius: 24 };

  const exitTransform = closingTargetRef.current
    ? rectToCollapsedTransform(closingTargetRef.current)
    : { scale: 0.94, x: 0, y: 24, opacity: 0, borderRadius: 24 };

  return (
    <>
      {/* Springboard illusion behind the overlay */}
      <motion.div
        className="fixed inset-0 z-0 pointer-events-none will-change-transform"
        style={{
          background:
            "radial-gradient(140% 100% at 50% 0%, rgba(40,28,5,0.6) 0%, #050300 60%)",
          scale: backdropScale,
          filter: backdropFilter,
          transformOrigin: "center center",
        }}
      >
        <HubNebulaField enabled />
      </motion.div>

      <AnimatePresence mode="wait">
        {!closing && (
          <motion.div
            key={location.pathname}
            role="dialog"
            aria-modal="true"
            aria-label="Mini uygulama"
            className="fixed inset-0 z-40 overflow-x-hidden overflow-y-auto overscroll-contain bg-background outline-none"
            data-mini-app-overlay
            style={{
              transformOrigin: "center center",
              willChange: "transform, opacity",
              opacity: overlayOpacity,
              scale: overlayScale,
            }}
            initial={initialTransform}
            animate={FULLSCREEN}
            exit={exitTransform}
            transition={SPRING}
            // Vertical drag-to-dismiss is handle-only so page content can scroll normally.
            drag="y"
            dragControls={dragControls}
            dragListener={false}
            dragConstraints={{ top: 0, bottom: 0 }}
            // Higher elastic + no momentum = silky, low-friction Telegram pull.
            dragElastic={{ top: 0, bottom: 0.85 }}
            dragMomentum={false}
            onDrag={(_, info) => {
              dragY.set(Math.max(0, info.offset.y));
            }}
            onDragEnd={(_, info) => {
              if (shouldDismiss(info.offset.y, info.velocity.y)) {
                handleClose();
              } else {
                dragY.set(0);
              }
            }}
          >
            {/* Top grab-handle — keyboard focusable so screen-reader / keyboard
                users have an explicit "close mini app" affordance equivalent
                to the swipe-down gesture. */}
            <button
              type="button"
              data-testid="mini-app-handle"
              onClick={handleClose}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " " || e.key === "Escape") {
                  e.preventDefault();
                  handleClose();
                }
              }}
              aria-label="Mini uygulamayı kapat"
              title="Kapat"
              onPointerDown={(e) => dragControls.start(e)}
              className="absolute top-0 left-1/2 -translate-x-1/2 z-50 mt-1.5 flex h-7 w-20 items-start justify-center pt-0 rounded-full bg-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-300/70"
            >
              <span
                aria-hidden
                className="h-1 w-10 rounded-full"
                style={{ background: "rgba(255,233,168,0.35)" }}
              />
            </button>

            {/* Uniform top-right close (X) — every mini-app gets the same
                affordance, just like Telegram's "✕". Independent of the
                swipe handle so users always have a tap target. */}
            <button
              type="button"
              data-testid="mini-app-close"
              onClick={handleClose}
              aria-label="Kapat"
              title="Kapat"
              className="absolute top-2 right-3 z-50 flex h-9 w-9 items-center justify-center rounded-full bg-black/35 text-white/90 backdrop-blur-md ring-1 ring-white/15 transition hover:bg-black/55 active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-300/70"
              style={{ marginTop: "max(env(safe-area-inset-top), 0px)" }}
            >
              <X className="h-4 w-4" />
            </button>
            {children}
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

/**
 * Pure swipe-dismiss threshold predicate — exported for unit tests so the
 * 110px / 700 velocity contract is locked. Lowered from 140/800 to feel
 * closer to Telegram's responsive sheet — easier to dismiss without being
 * accidental (still requires deliberate downward intent).
 */
export const SWIPE_DISMISS_OFFSET_PX = 110;
export const SWIPE_DISMISS_VELOCITY = 700;
export function shouldDismiss(offsetY: number, velocityY: number): boolean {
  return offsetY > SWIPE_DISMISS_OFFSET_PX || velocityY > SWIPE_DISMISS_VELOCITY;
}

