/**
 * SheetShell — iOS 18 bottom-sheet wrapper for every mini-app / sub-page.
 *
 * Wraps `<main>` content in AppShell so every non-Hub authenticated route
 * presents like the screenshot the user shared (Egemen Kontrol style):
 *   • slides up from the bottom on enter (spring)
 *   • rounded top corners + faint border + grabber pill
 *   • pull-down-from-anywhere-on-sheet to dismiss (history.back)
 *
 * The Hub root (/) and unauthenticated landing remain full-bleed.
 *
 * Pages can opt-out of the dismiss gesture on a specific element by adding
 * `data-no-swipe-back` (e.g. on a horizontally-scrolling carousel or chat
 * input). The opt-out is honoured by `useSheetDismiss` below.
 */
import { useEffect, useRef, type ReactNode } from "react";
import { isFlowLocked } from "@/lib/flowLock";

interface Props {
  children: ReactNode;
  /** When true, render content full-bleed (no sheet chrome). */
  disabled?: boolean;
}

export function SheetShell({ children, disabled }: Props) {
  const ref = useRef<HTMLDivElement | null>(null);
  useSheetDismiss(ref, !disabled);

  if (disabled) {
    return <>{children}</>;
  }

  return (
    <div
      ref={ref}
      className="sovereign-sheet"
      style={{
        // Hardware-accelerated layer — spring animation + drag stay 60fps.
        transform: "translateZ(0)",
        willChange: "transform, opacity",
      }}
    >
      {/* iOS-style grabber — visual cue that the sheet can be pulled down. */}
      <div className="sovereign-sheet__grabber" aria-hidden />
      <div className="sovereign-sheet__content">{children}</div>
    </div>
  );
}

/**
 * Pull-down-anywhere-on-sheet gesture. Mirrors `useSwipeDownBack` but is
 * scoped to the sheet element and only triggers when the user is at scrollTop
 * (so vertical scrolling inside the sheet still works normally).
 */
function useSheetDismiss(ref: React.RefObject<HTMLDivElement | null>, enabled: boolean) {
  useEffect(() => {
    if (!enabled) return;
    if (typeof window === "undefined") return;
    if (window.matchMedia?.("(hover: hover)").matches) return; // desktop — skip

    const el = ref.current;
    if (!el) return;

    let startX = 0;
    let startY = 0;
    let dy = 0;
    let tracking = false;
    let dragging = false;

    const onStart = (e: TouchEvent) => {
      if (isFlowLocked()) return;
      const t = e.touches[0];
      if (!t) return;

      const target = e.target as HTMLElement | null;
      if (target?.closest?.("[data-no-swipe-back]")) return;
      const tag = target?.tagName?.toLowerCase();
      if (tag === "input" || tag === "textarea" || tag === "select") return;

      // Only allow dismiss when the page itself is scrolled to top — otherwise
      // the user is scrolling content, not dismissing.
      if (window.scrollY > 4) return;

      startX = t.clientX;
      startY = t.clientY;
      dy = 0;
      tracking = true;
      dragging = false;
    };

    const onMove = (e: TouchEvent) => {
      if (!tracking) return;
      const t = e.touches[0];
      if (!t) return;
      const delta = t.clientY - startY;
      const absX = Math.abs(t.clientX - startX);

      // Once we know it's a vertical pull-down, mark as dragging.
      if (!dragging) {
        if (delta > 8 && delta > absX) {
          dragging = true;
        } else if (Math.abs(delta) > 8 || absX > 8) {
          // Horizontal or upward — abort.
          tracking = false;
          return;
        }
      }

      if (dragging && delta > 0) {
        dy = delta;
        // Live drag — translate the sheet with rubber-banding past 240px.
        const eased = delta < 240 ? delta : 240 + (delta - 240) * 0.4;
        el.style.transform = `translate3d(0, ${eased}px, 0)`;
        el.style.opacity = String(Math.max(0.55, 1 - eased / 700));
      }
    };

    const reset = () => {
      el.style.transition = "transform 220ms cubic-bezier(0.32,0.72,0,1), opacity 220ms";
      el.style.transform = "translate3d(0,0,0)";
      el.style.opacity = "1";
      window.setTimeout(() => {
        el.style.transition = "";
      }, 240);
    };

    const onEnd = () => {
      if (!tracking) return;
      const shouldClose = dragging && dy > 110;
      tracking = false;
      dragging = false;
      if (!shouldClose) {
        if (dy > 0) reset();
        return;
      }
      el.style.transition = "transform 220ms cubic-bezier(0.32,0.72,0,1), opacity 220ms";
      el.style.transform = "translate3d(0, 100%, 0)";
      el.style.opacity = "0";
      window.setTimeout(() => {
        try {
          window.history.back();
        } catch {
          /* noop */
        }
      }, 200);
    };

    el.addEventListener("touchstart", onStart, { passive: true });
    el.addEventListener("touchmove", onMove, { passive: true });
    el.addEventListener("touchend", onEnd, { passive: true });
    el.addEventListener("touchcancel", onEnd, { passive: true });
    return () => {
      el.removeEventListener("touchstart", onStart);
      el.removeEventListener("touchmove", onMove);
      el.removeEventListener("touchend", onEnd);
      el.removeEventListener("touchcancel", onEnd);
    };
  }, [ref, enabled]);
}

