import { useEffect, useRef, useState } from "react";

export type TopTabValue = "following" | "foryou" | "explore";

interface Tab {
  value: TopTabValue;
  label: string;
}

interface Props {
  tabs: Tab[];
  value: TopTabValue;
  onChange: (v: TopTabValue) => void;
  /** Render on dark immersive background (e.g. KEKA) */
  variant?: "dark" | "light";
}

/**
 * TikTok-style centered top tab bar with animated underline.
 * Tap = switch instantly. Active tab is bold + underlined.
 */
export function TopTabs({ tabs, value, onChange, variant = "dark" }: Props) {
  const refs = useRef<Map<TopTabValue, HTMLButtonElement | null>>(new Map());
  const [indicator, setIndicator] = useState({ left: 0, width: 0 });

  useEffect(() => {
    const el = refs.current.get(value);
    if (!el) return;
    setIndicator({ left: el.offsetLeft, width: el.offsetWidth });
  }, [value, tabs]);

  const isDark = variant === "dark";

  return (
    <div className="relative w-full flex items-center justify-center">
      <div className="relative flex items-center gap-5">
        {tabs.map((t) => {
          const active = t.value === value;
          return (
            <button
              key={t.value}
              ref={(el) => {
                refs.current.set(t.value, el);
              }}
              onClick={() => onChange(t.value)}
              className={`relative px-1 py-1.5 text-[14px] font-semibold transition-all duration-200 ${
                active
                  ? isDark
                    ? "text-white"
                    : "text-foreground"
                  : isDark
                    ? "text-white/55 hover:text-white/80"
                    : "text-muted-foreground hover:text-foreground"
              }`}
              style={{
                textShadow: isDark && active ? "0 1px 4px rgba(0,0,0,0.6)" : undefined,
              }}
            >
              {t.label}
            </button>
          );
        })}
        {/* Animated underline */}
        <span
          aria-hidden
          className={`absolute -bottom-0.5 h-[3px] rounded-full transition-all duration-300 ease-out ${
            isDark ? "bg-white" : "bg-foreground"
          }`}
          style={{
            left: indicator.left,
            width: indicator.width,
          }}
        />
      </div>
    </div>
  );
}

