                  <div className="font-bold text-white text-sm">
                    {opt.minutes} dk — <span className="text-[#9B59B6]">{opt.label}</span>
                  </div>
                  <div className="text-[10px] text-zinc-500 mt-0.5">{opt.description}</div>
                </button>
              ))}
