            <div className="flex gap-2">
              <Button
                variant="outline"
                onClick={() => setStep(1)}
                disabled={saving}
                className="flex-1 border-zinc-700 text-zinc-300"
              >
                Geri
              </Button>
              <Button
                onClick={() => onComplete({ source_language: source, target_language: target, daily_goal_minutes: goal })}
                disabled={saving}
                className="flex-1 bg-[#FFD700] text-black hover:bg-[#FFD700]/90 font-semibold"
              >
                {saving ? "Kaydediliyor..." : "Başla"}
              </Button>
            </div>
          </>
        )}
      </Card>
    </div>
  );
}

