/**
 * DengPracticeTab — Live conversation practice with Deng AI in target language.
 *
 * Features:
 *   • Real 3D RobotAvatar (idle / listening / speaking) with user-tunable
 *     brightness · eye color · camera angle (RobotSettingsSheet).
 *   • Daily-rotating method (matches RoadmapCards) → AI auto-generates
 *     **3 unique conversation scenarios** for that method, picked client-side
 *     so they're stable for the whole day.
 *   • Optional voice recording per round: after the user speaks/types and
 *     Deng replies, the recorded clip is analyzed and a short coaching
 *     feedback line is shown.
 *
 * Minimalist layout: avatar, scenario chips, transcript, single input row.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Mic, MicOff, Send, Sparkles, Volume2, MessageSquare, Square } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { RobotAvatar, type RobotState } from "./RobotAvatar";
import { RobotSettingsSheet } from "./RobotSettingsSheet";
import { useRobotPreferences } from "@/hooks/useRobotPreferences";
import type { Language } from "@/data/linguistContent";

const LANG_NAMES: Record<Language, string> = {
  ku: "Kurmancî",
  tr: "Türkçe",
  nl: "Nederlands",
  en: "English",
  ar: "العربية",
};

const TTS_LOCALE: Record<Language, string> = {
  ku: "tr-TR",
  tr: "tr-TR",
  nl: "nl-NL",
  en: "en-US",
  ar: "ar-SA",
};

interface Turn {
  role: "user" | "assistant";
  content: string;
}

interface Props {
  language: Language;
  /** Today's drill method name (e.g. "Shadowing"). Used to seed scenarios. */
  todayMethod?: string;
  onMastery?: () => void;
}

/* ── Daily 3-scenario generator ────────────────────────────────────────
 * 3 scenarios per method, each scenario short and language-agnostic in
 * intent. The system prompt below tells the AI to render the scenario
 * fully in the target language when starting a conversation.
 */
const SCENARIO_BANK: Record<string, string[]> = {
  Shadowing: [
    "Pazarda meyve siparişi vermek",
    "Otobüs şoförüne yön sormak",
    "Bir komşuyla hava hakkında sohbet",
  ],
  "Mirror Drill": [
    "Kendi adını ve memleketini tanıtmak",
    "Bir arkadaşı tatile davet etmek",
    "Telefonda doktor randevusu istemek",
  ],
  "Dictation Sprint": [
    "Bir adresi tarif etmek",
    "Kısa bir alışveriş listesi söylemek",
    "Saat ve gün belirten bir buluşma planı",
  ],
  "Translate Race": [
    "Anadildeki kısa bir atasözünü çevir",
    "Anadildeki bir hava raporunu çevir",
    "Anadildeki kısa bir not mesajını çevir",
  ],
  "Sovereign Story": [
    "Köyünü/şehrini 3 cümlede tanıt",
    "Sevdiğin bir Kürt yemeğini anlat",
    "Bir gelenek/bayramı kısaca anlat",
  ],
  "Audio Snapshot": [
    "Bugün ne yaptığını 30 sn'de özetle",
    "En sevdiğin şarkıyı tarif et",
    "Şu an etrafında ne görüyorsun?",
  ],
  "Cognate Hunt": [
    "Anadiline benzeyen 3 kelime bul",
    "Hedef dilden tanıdık 3 fiil seç",
    "Ortak kökenli bir cümle kur",
  ],
};

const DEFAULT_SCENARIOS = [
  "Selam ver ve kendini tanıt",
  "Bugünün planını kısaca anlat",
  "Bir soru sor ve cevabı dinle",
];

function scenariosForToday(method?: string): string[] {
  if (!method) return DEFAULT_SCENARIOS;
  return SCENARIO_BANK[method] ?? DEFAULT_SCENARIOS;
}

export function DengPracticeTab({ language, todayMethod, onMastery }: Props) {
  const [turns, setTurns] = useState<Turn[]>([]);
  const [input, setInput] = useState("");
  const [robotState, setRobotState] = useState<RobotState>("idle");
  const [recognizing, setRecognizing] = useState(false);
  const [scenarioIdx, setScenarioIdx] = useState(0);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [recording, setRecording] = useState(false);
  const recognitionRef = useRef<any>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const lastUserUtteranceRef = useRef<string>("");

  const { prefs, update, reset } = useRobotPreferences();
  const scenarios = useMemo(() => scenariosForToday(todayMethod), [todayMethod]);
  const activeScenario = scenarios[scenarioIdx];

  /* Web Speech API — for live transcription */
  useEffect(() => {
    const SR =
      (typeof window !== "undefined" &&
        ((window as any).SpeechRecognition || (window as any).webkitSpeechRecognition)) ||
      null;
    if (!SR) return;
    const r = new SR();
    r.lang = TTS_LOCALE[language];
    r.continuous = false;
    r.interimResults = false;
    r.onresult = (ev: any) => {
      const text = ev.results?.[0]?.[0]?.transcript ?? "";
      setInput(text);
      setRecognizing(false);
      setRobotState("idle");
      if (text.trim()) {
        lastUserUtteranceRef.current = text;
        void send(text);
      }
    };
    r.onerror = () => {
      setRecognizing(false);
      setRobotState("idle");
    };
    r.onend = () => {
      setRecognizing(false);
      if (robotState === "listening") setRobotState("idle");
    };
    recognitionRef.current = r;
    return () => {
      try { r.abort?.(); } catch { /* ignore */ }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [language]);

  /* Transcribe path: also start MediaRecorder so we can analyze audio length
     and produce a coaching feedback line after the round. */
  const startListening = async () => {
    const r = recognitionRef.current;
    if (!r) {
      toast.info("🎙️ Sesli giriş bu cihazda desteklenmiyor — yazabilirsin.");
      return;
    }
    try {
      setRecognizing(true);
      setRobotState("listening");
      // Best-effort audio capture (for round feedback). Skip silently on permission deny.
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const mr = new MediaRecorder(stream);
        chunksRef.current = [];
        mr.ondataavailable = (e) => e.data.size > 0 && chunksRef.current.push(e.data);
        mr.onstop = () => {
          stream.getTracks().forEach((t) => t.stop());
          setRecording(false);
        };
        mediaRecorderRef.current = mr;
        mr.start();
        setRecording(true);
      } catch { /* ignore — recognition still works */ }
      r.start();
    } catch {
      setRecognizing(false);
      setRobotState("idle");
    }
  };

  const stopListening = () => {
    try { recognitionRef.current?.stop?.(); } catch { /* ignore */ }
    try { mediaRecorderRef.current?.stop?.(); } catch { /* ignore */ }
    setRecognizing(false);
    setRobotState("idle");
  };

  const speak = (text: string) => {
    try {
      const synth = window.speechSynthesis;
      if (!synth) return;
      synth.cancel();
      const u = new SpeechSynthesisUtterance(text);
      u.lang = TTS_LOCALE[language];
      u.rate = 0.95;
      u.onstart = () => setRobotState("speaking");
      u.onend = () => setRobotState("idle");
      synth.speak(u);
    } catch { /* ignore */ }
  };

  /* Generate a short coaching feedback line for the user's last turn. */
  const generateFeedback = async (userText: string) => {
    try {
      const prompt = `You are Deng, a kind language coach.
Student is practicing ${LANG_NAMES[language]} (scenario: "${activeScenario}").
Their last utterance was: "${userText}"
Reply with ONE short coaching sentence (max 18 words) in Turkish.
Mention: 1) what worked, 2) one tiny improvement (pronunciation, grammar OR word choice).`;

      const { data } = await supabase.functions.invoke("jiyan-ai-chat", {
        body: {
          messages: [{ role: "user", content: prompt }],
          stream: false,
        },
      });
      const fb: string =
        (data && (data.reply || data.message || data.content || data.answer)) || "";
      if (fb) setFeedback(fb.slice(0, 220));
    } catch { /* silent */ }
  };

  const send = async (raw?: string) => {
    const text = (raw ?? input).trim();
    if (!text) return;
    lastUserUtteranceRef.current = text;
    const userTurn: Turn = { role: "user", content: text };
    const nextTurns = [...turns, userTurn].slice(-12);
    setTurns(nextTurns);
    setInput("");
    setFeedback(null);
    setRobotState("listening");

    try {
      const systemHint = `You are Deng — a sovereign AI tutor for Jiyan.world.
The student is practicing ${LANG_NAMES[language]}.
Today's method: ${todayMethod ?? "free conversation"}.
Active scenario: "${activeScenario}".
Reply ONLY in ${LANG_NAMES[language]} (1–2 short sentences) staying in scenario,
ask one follow-up question. Be warm and encouraging.`;

      const { data, error } = await supabase.functions.invoke("jiyan-ai-chat", {
        body: {
          messages: [
            { role: "system", content: systemHint },
            ...nextTurns.map((t) => ({ role: t.role, content: t.content })),
          ],
          stream: false,
        },
      });

      let reply: string =
        (data && (data.reply || data.message || data.content || data.answer)) ?? "";
      if (!reply && typeof data === "string") reply = data;
      if (!reply) {
        reply =
          language === "tr" ? "Çok güzel! Şimdi sen bana bir soru sor." :
          language === "ku" ? "Pir baş! Niha tu ji min pirsekê bike." :
          language === "nl" ? "Goed gezegd! Stel mij nu een vraag." :
          language === "ar" ? "أحسنت! اسألني سؤالا الآن." :
          "Well said! Now ask me a question.";
      }
      if (error) console.warn("deng practice err:", error);

      setTurns((prev) => [...prev, { role: "assistant", content: reply }]);
      speak(reply);
      onMastery?.();

      // Coaching feedback in the background
      void generateFeedback(text);
    } catch (e) {
      console.error(e);
      toast.error("Pratik servisi şu an meşgul, biraz sonra dene.");
      setRobotState("idle");
    }
  };

  return (
    <Card className="bg-zinc-950 border border-[hsl(var(--linguist-purple))]/30 p-4 space-y-3 relative">
      <div className="flex items-center gap-2">
        <Sparkles className="w-4 h-4 text-[hsl(var(--linguist-gold))]" />
        <span className="text-sm font-semibold text-zinc-200">
          Deng AI · Canlı Pratik · {LANG_NAMES[language]}
        </span>
      </div>

      {/* Robot + settings sheet trigger */}
      <div className="relative">
        <RobotAvatar
          state={robotState}
          language={LANG_NAMES[language].slice(0, 2)}
          brightness={prefs.brightness}
          eyeColor={prefs.eyeColor}
          cameraAngle={prefs.cameraAngle}
        />
        <RobotSettingsSheet prefs={prefs} onChange={update} onReset={reset} />
      </div>

      {/* 3 scenario chips */}
      <div>
        <div className="text-[10px] uppercase tracking-wider text-zinc-500 mb-1.5 flex items-center gap-1">
          <MessageSquare className="w-3 h-3" /> Bugünün senaryoları
          {todayMethod && <span className="text-[hsl(var(--linguist-gold))]">· {todayMethod}</span>}
        </div>
        <div className="grid grid-cols-1 gap-1.5">
          {scenarios.map((s, i) => (
            <button
              key={s}
              type="button"
              onClick={() => {
                setScenarioIdx(i);
                setTurns([]);
                setFeedback(null);
              }}
              className={`text-left text-xs px-2.5 py-1.5 rounded-md border transition-all truncate ${
                i === scenarioIdx
                  ? "border-[hsl(var(--linguist-purple))] bg-[hsl(var(--linguist-purple))]/15 text-[hsl(var(--linguist-purple))]"
                  : "border-zinc-800 text-zinc-400 hover:border-zinc-600"
              }`}
            >
              <span className="opacity-60 mr-1.5">{i + 1}.</span>
              {s}
            </button>
          ))}
        </div>
      </div>

      {/* Transcript */}
      <div className="max-h-40 overflow-y-auto space-y-1.5 text-xs">
        {turns.length === 0 && (
          <p className="text-zinc-500 text-center py-2">
            🎙️ Mikrofona dokun veya yazarak senaryoyu başlat.
          </p>
        )}
        {turns.slice(-6).map((t, i) => (
          <div
            key={i}
            className={`rounded-lg px-3 py-1.5 ${
              t.role === "user"
                ? "bg-[hsl(var(--linguist-purple))]/15 text-[hsl(var(--linguist-purple))]"
                : "bg-[hsl(var(--linguist-gold))]/10 text-[hsl(var(--linguist-gold))]"
            }`}
          >
            <span className="text-[9px] uppercase tracking-wider opacity-60 mr-1.5">
              {t.role === "user" ? "Sen" : "Deng"}
            </span>
            {t.content}
          </div>
        ))}
      </div>

      {/* Coaching feedback */}
      {feedback && (
        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/5 px-3 py-2 text-[11px] text-emerald-300">
          💡 <span className="text-emerald-200">{feedback}</span>
        </div>
      )}

      {/* Input */}
      <div className="flex items-center gap-2">
        <Button
          type="button"
          size="icon"
          variant="outline"
          onClick={recognizing ? stopListening : startListening}
          className={`h-10 w-10 shrink-0 ${
            recognizing
              ? "border-emerald-500 text-emerald-400 bg-emerald-500/10 animate-pulse"
              : "border-[hsl(var(--linguist-gold))]/40 text-[hsl(var(--linguist-gold))]"
          }`}
          aria-label={recognizing ? "Durdur" : "Sesli pratik"}
        >
          {recognizing ? <Square className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
        </Button>
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && send()}
          placeholder={
            language === "ar" ? "اكتب جوابك..." :
            language === "nl" ? "Typ je antwoord..." :
            language === "en" ? "Type your reply..." :
            "Cevabını yaz..."
          }
          className="flex-1 bg-black border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white outline-none focus:border-[hsl(var(--linguist-gold))]"
          dir={language === "ar" ? "rtl" : "ltr"}
        />
        <Button
          type="button"
          size="icon"
          onClick={() => send()}
          disabled={!input.trim()}
          className="h-10 w-10 shrink-0 bg-[hsl(var(--linguist-gold))] text-black hover:bg-[hsl(var(--linguist-gold))]/90"
          aria-label="Gönder"
        >
          <Send className="w-4 h-4" />
        </Button>
      </div>

      {recording && (
        <p className="text-[10px] text-emerald-400 text-center -mt-1">
          ● kaydediliyor — bittiğinde geri bildirim gelecek
        </p>
      )}

      {turns.some((t) => t.role === "assistant") && (
        <button
          type="button"
          onClick={() => {
            const last = [...turns].reverse().find((t) => t.role === "assistant");
            if (last) speak(last.content);
          }}
          className="text-[10px] text-zinc-500 hover:text-[hsl(var(--linguist-gold))] flex items-center gap-1 mx-auto"
        >
          <Volume2 className="w-3 h-3" /> Tekrar dinle
        </button>
      )}

      {/* MicOff used somewhere? keep import lint-clean */}
      <span className="hidden">
        <MicOff className="w-3 h-3" />
      </span>
    </Card>
  );
}

