import { useEffect, useRef, useState } from "react";
import { Volume2, RotateCw } from "lucide-react";
import type { Flashcard as FlashcardType } from "@/data/linguistFlashcards";
import { linguistSounds } from "@/lib/linguistAudio";

interface Props {
  card: FlashcardType;
  onSwipe: (direction: "left" | "right") => void;
  active: boolean;
}

export function Flashcard({ card, onSwipe, active }: Props) {
  const [flipped, setFlipped] = useState(false);
  const [drag, setDrag] = useState({ x: 0, dragging: false });
  const startX = useRef(0);

  // Reset on new card
  useEffect(() => {
    setFlipped(false);
    setDrag({ x: 0, dragging: false });
  }, [card.id]);

  const onPointerDown = (e: React.PointerEvent) => {
    if (!active) return;
    startX.current = e.clientX;
    setDrag({ x: 0, dragging: true });
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
  };
  const onPointerMove = (e: React.PointerEvent) => {
    if (!drag.dragging) return;
    setDrag({ x: e.clientX - startX.current, dragging: true });
  };
  const onPointerUp = () => {
    if (!drag.dragging) return;
    const threshold = 100;
    if (drag.x > threshold) {
      setDrag({ x: 600, dragging: false });
      setTimeout(() => onSwipe("right"), 180);
    } else if (drag.x < -threshold) {
      setDrag({ x: -600, dragging: false });
      setTimeout(() => onSwipe("left"), 180);
    } else {
      setDrag({ x: 0, dragging: false });
    }
  };

  const rotate = drag.x / 20;
  const opacity = 1 - Math.min(0.5, Math.abs(drag.x) / 400);

  return (
    <div className="relative w-full" style={{ perspective: "1200px" }}>
      {/* Swipe action labels */}
      {drag.dragging && drag.x > 30 && (
        <div className="absolute top-4 right-4 z-20 px-3 py-1.5 rounded-lg bg-[#FFD700] text-black font-bold text-sm rotate-12 pointer-events-none">
          MASTERED ✓
        </div>
      )}
      {drag.dragging && drag.x < -30 && (
        <div className="absolute top-4 left-4 z-20 px-3 py-1.5 rounded-lg bg-[#9B59B6] text-white font-bold text-sm -rotate-12 pointer-events-none">
          REVIEW ↻
        </div>
      )}

      <div
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        className="touch-none select-none cursor-grab active:cursor-grabbing"
        style={{
          transform: `translateX(${drag.x}px) rotate(${rotate}deg)`,
          opacity,
          transition: drag.dragging ? "none" : "transform 200ms ease-out, opacity 200ms",
        }}
      >
        <div
          className="relative w-full aspect-[3/4] rounded-3xl"
          style={{
            transformStyle: "preserve-3d",
            transform: flipped ? "rotateY(180deg)" : "rotateY(0deg)",
            transition: "transform 600ms cubic-bezier(0.4, 0.0, 0.2, 1)",
          }}
        >
          {/* FRONT — Dutch */}
          <div
            className="absolute inset-0 rounded-3xl bg-black border-2 border-[#FFD700] p-6 flex flex-col items-center justify-between overflow-hidden"
