interface Props {
  value: number; // current minutes
  goal: number; // target minutes
  size?: number;
  label?: string;
}

export function GoalRing({ value, goal, size = 180, label }: Props) {
  const stroke = 12;
  const radius = (size - stroke) / 2;
  const circ = 2 * Math.PI * radius;
  const pct = Math.min(1, goal > 0 ? value / goal : 0);
  const dash = circ * pct;

  return (
    <div className="relative inline-flex items-center justify-center">
      <svg width={size} height={size} className="-rotate-90">
        <defs>
          <linearGradient id="goal-grad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#FFD700" />
            <stop offset="100%" stopColor="#9B59B6" />
          </linearGradient>
        </defs>
        <circle cx={size / 2} cy={size / 2} r={radius} stroke="rgba(255,255,255,0.08)" strokeWidth={stroke} fill="none" />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="url(#goal-grad)"
          strokeWidth={stroke}
          strokeLinecap="round"
          fill="none"
          strokeDasharray={`${dash} ${circ}`}
          style={{ transition: "stroke-dasharray 600ms ease-out" }}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
        <div className="text-4xl font-bold text-white tabular-nums">{value}</div>
        <div className="text-xs text-zinc-400 uppercase tracking-wider">/ {goal} min</div>
        {label && <div className="text-[10px] text-[#FFD700] mt-1 font-semibold">{label}</div>}
      </div>
    </div>
  );
}

