import { useState } from "react";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { ArrowDown, Check } from "lucide-react";
import type { Language } from "@/data/linguistContent";

const LANGS: { code: Language; flag: string; label: string }[] = [
  { code: "tr", flag: "🇹🇷", label: "Türkçe" },
  { code: "ku", flag: "☀️", label: "Kurmancî" },
  { code: "en", flag: "🇬🇧", label: "English" },
  { code: "nl", flag: "🇳🇱", label: "Nederlands" },
  { code: "ar", flag: "🇮🇶", label: "العربية" },
];

interface Props {
  open: boolean;
  initialNative?: Language;
  initialTarget?: Language;
  onConfirm: (p: { native: Language; target: Language }) => void;
}

export function LanguagePickerSheet({ open, initialNative = "tr", initialTarget = "ku", onConfirm }: Props) {
  const [native, setNative] = useState<Language>(initialNative);
  const [target, setTarget] = useState<Language>(initialTarget);
