              <ArrowDown className="w-4 h-4 text-[hsl(var(--linguist-gold))]" />
            </div>
          </div>

          {/* Target row */}
          <div>
            <div className="text-[10px] uppercase tracking-[0.2em] text-[hsl(var(--linguist-purple))] mb-2">
