            </div>
            <div className="grid grid-cols-5 gap-1.5">
              {LANGS.map((l) => {
                const disabled = l.code === native;
                const active = l.code === target;
                return (
                  <button
                    key={`t-${l.code}`}
                    type="button"
                    disabled={disabled}
                    onClick={() => setTarget(l.code)}
                    className={`aspect-square rounded-xl border-2 flex flex-col items-center justify-center gap-0.5 transition-all ${
                      active
                        ? "border-[hsl(var(--linguist-purple))] bg-[hsl(var(--linguist-purple))]/15 scale-105"
                        : disabled
                        ? "border-zinc-900 bg-zinc-950 opacity-30"
                        : "border-zinc-800 hover:border-zinc-600"
                    }`}
                  >
                    <div className="text-2xl leading-none">{l.flag}</div>
                    <div className="text-[9px] text-zinc-400 truncate w-full text-center">
                      {l.label.split(" ")[0]}
                    </div>
