/**
 * LevelBadges — Visible XP → Level + Badges panel for Linguist.
 *
 * Levels:  Level = 1 + floor(totalXp / 100). Each level needs +100 XP.
 * Badges (unlocked when condition met):
 *   • 🔥 Streak Spark — 1 day streak
 *   • 💎 Constant      — 7 day streak
 *   • 🏔️  Mountain      — 30 day streak
 *   • 📚 Word Hunter   — 25 mastered cards
 *   • 🧠 Polyglot      — practiced 3+ different languages (passed in via languagesUsed)
 *   • 🏆 Cert Holder   — at least 1 certificate
 *
 * Pure presentation — receives all numbers as props.
 */
import { Card } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Trophy, Star } from "lucide-react";

interface Badge {
  emoji: string;
  label: string;
  unlocked: boolean;
}

interface Props {
  totalXp: number;
  streak: number;
  mastered: number;
  certificates: number;
  languagesUsed: number;
}

export function LevelBadges({ totalXp, streak, mastered, certificates, languagesUsed }: Props) {
  const level = 1 + Math.floor(totalXp / 100);
  const intoLevel = totalXp % 100;
  const toNext = 100 - intoLevel;

  const badges: Badge[] = [
    { emoji: "🔥", label: "Spark", unlocked: streak >= 1 },
    { emoji: "💎", label: "Sabit · 7g", unlocked: streak >= 7 },
    { emoji: "🏔️", label: "Dağ · 30g", unlocked: streak >= 30 },
    { emoji: "📚", label: "Kelime Avcısı", unlocked: mastered >= 25 },
    { emoji: "🧠", label: "Polyglot", unlocked: languagesUsed >= 3 },
    { emoji: "🏆", label: "Sertifikalı", unlocked: certificates >= 1 },
  ];

  const earned = badges.filter((b) => b.unlocked).length;

  return (
    <Card className="bg-zinc-950 border border-[hsl(var(--linguist-gold))]/30 p-4 space-y-3">
      <div className="flex items-center gap-3">
        <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-[hsl(var(--linguist-gold))] to-[hsl(var(--linguist-purple))] flex items-center justify-center shadow-lg">
          <Star className="w-6 h-6 text-black" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-baseline gap-2">
            <span className="text-2xl font-bold text-[hsl(var(--linguist-gold))]">Lv {level}</span>
            <span className="text-[10px] uppercase tracking-wider text-zinc-500">
              {totalXp} XP toplam · {toNext} XP sonraki
            </span>
          </div>
          <Progress
            value={intoLevel}
            className="h-1.5 mt-1 bg-zinc-900 [&>div]:bg-gradient-to-r [&>div]:from-[hsl(var(--linguist-gold))] [&>div]:to-[hsl(var(--linguist-purple))]"
          />
        </div>
        <div className="text-right shrink-0">
          <Trophy className="w-4 h-4 text-[hsl(var(--linguist-gold))] ml-auto" />
          <div className="text-xs font-semibold text-zinc-300 mt-0.5">
            {earned}/{badges.length}
          </div>
          <div className="text-[9px] uppercase text-zinc-500">rozet</div>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-2">
        {badges.map((b) => (
          <div
            key={b.label}
            className={`rounded-lg p-2 text-center border transition-all ${
              b.unlocked
                ? "border-[hsl(var(--linguist-gold))]/50 bg-[hsl(var(--linguist-gold))]/10"
                : "border-zinc-800 bg-zinc-900/50 opacity-50"
            }`}
            title={b.label}
          >
            <div className="text-lg leading-none">{b.unlocked ? b.emoji : "🔒"}</div>
            <div className="text-[9px] mt-0.5 text-zinc-400">{b.label}</div>
          </div>
        ))}
      </div>
    </Card>
  );
}

