import { useState, useMemo, useEffect } from "react";
import { Lesson, Exercise, LanguageCourse } from "@/data/linguistContent";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { CheckCircle2, XCircle, Volume2, ArrowRight, Trophy, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";

interface Props {
  lesson: Lesson;
  course: LanguageCourse;
  onComplete: (score: number) => Promise<void> | void;
  onExit: () => void;
}

export function LinguistLessonPlayer({ lesson, course, onComplete, onExit }: Props) {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [selected, setSelected] = useState<string>("");
  const [textInput, setTextInput] = useState("");
  const [feedback, setFeedback] = useState<"correct" | "wrong" | null>(null);
  const [correctCount, setCorrectCount] = useState(0);
  const [finished, setFinished] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const exercise: Exercise | undefined = lesson.exercises[currentIdx];
  const progress = useMemo(
    () => ((currentIdx + (feedback ? 1 : 0)) / lesson.exercises.length) * 100,
    [currentIdx, feedback, lesson.exercises.length]
  );

  // Reset transient state when exercise changes
  useEffect(() => {
    setSelected("");
    setTextInput("");
    setFeedback(null);
  }, [currentIdx]);

  const speak = (text: string) => {
    if (typeof window === "undefined" || !("speechSynthesis" in window)) return;
    const u = new SpeechSynthesisUtterance(text);
    u.lang = course.ttsLocale;
    u.rate = 0.9;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(u);
  };

  const checkAnswer = () => {
    if (!exercise || feedback) return;
    const userAnswer = exercise.type === "listen" ? textInput.trim() : selected;
    if (!userAnswer) return;
    const ok = userAnswer.toLowerCase() === exercise.correctAnswer.toLowerCase();
    setFeedback(ok ? "correct" : "wrong");
    if (ok) setCorrectCount((c) => c + 1);
  };

  const next = async () => {
    if (currentIdx + 1 < lesson.exercises.length) {
      setCurrentIdx((i) => i + 1);
    } else {
      setFinished(true);
      setSubmitting(true);
      const finalScore = Math.round(((correctCount + (feedback === "correct" ? 0 : 0)) / lesson.exercises.length) * 100);
      try {
        await onComplete(finalScore);
      } finally {
        setSubmitting(false);
      }
    }
  };

  if (finished) {
    const finalScore = Math.round((correctCount / lesson.exercises.length) * 100);
    return (
      <Card className="bg-black border-2 border-[hsl(var(--linguist-gold))] p-8 text-center">
        <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-gradient-to-br from-[hsl(var(--linguist-gold))] to-[hsl(var(--linguist-purple))] flex items-center justify-center">
          <Trophy className="w-10 h-10 text-black" />
        </div>
        <h2 className="text-2xl font-bold text-[hsl(var(--linguist-gold))] mb-2">Lesson Complete!</h2>
        <p className="text-zinc-400 mb-1">{lesson.title}</p>
        <div className="my-6">
          <div className="text-5xl font-bold text-white">{finalScore}%</div>
          <div className="text-sm text-zinc-500 mt-1">
            {correctCount} / {lesson.exercises.length} correct
          </div>
        </div>
        <div className="flex items-center justify-center gap-2 text-[hsl(var(--linguist-purple))] mb-6">
          <Sparkles className="w-4 h-4" />
          <span className="font-semibold">+{lesson.xp} Academy XP</span>
        </div>
        <Button
          onClick={onExit}
          disabled={submitting}
          className="w-full bg-[hsl(var(--linguist-gold))] text-black hover:bg-[hsl(var(--linguist-gold))]/90 font-semibold"
        >
          {submitting ? "Saving..." : "Continue"}
        </Button>
      </Card>
    );
  }

  if (!exercise) return null;

  return (
    <div className="space-y-4">
      {/* Top bar */}
      <div className="flex items-center gap-3">
        <Button size="sm" variant="ghost" onClick={onExit} className="text-zinc-500 hover:text-white">
          ✕
        </Button>
        <Progress value={progress} className="flex-1 h-2 bg-zinc-900 [&>div]:bg-gradient-to-r [&>div]:from-[hsl(var(--linguist-gold))] [&>div]:to-[hsl(var(--linguist-purple))]" />
        <Badge variant="outline" className="border-[hsl(var(--linguist-purple))] text-[hsl(var(--linguist-purple))]">
          {currentIdx + 1}/{lesson.exercises.length}
        </Badge>
      </div>

      <Card className="bg-zinc-950 border-zinc-800 p-6 min-h-[400px]">
        <Badge className="mb-4 bg-[hsl(var(--linguist-purple))]/20 text-[hsl(var(--linguist-purple))] border-[hsl(var(--linguist-purple))]/40">
          {exercise.type === "mcq" && "Multiple Choice"}
          {exercise.type === "match" && "Match"}
          {exercise.type === "listen" && "Listening"}
          {exercise.type === "read" && "Reading"}
        </Badge>

        {/* Reading passage */}
        {exercise.type === "read" && exercise.passage && (
          <div className="mb-5 p-4 rounded-lg border border-[hsl(var(--linguist-gold))]/30 bg-black">
            <p className="text-sm leading-relaxed text-zinc-200 italic">{exercise.passage}</p>
          </div>
        )}

        {/* Listen player */}
        {exercise.type === "listen" && exercise.ttsText && (
          <div className="mb-5 flex justify-center">
            <Button
              type="button"
              onClick={() => speak(exercise.ttsText!)}
              className="w-24 h-24 rounded-full bg-gradient-to-br from-[hsl(var(--linguist-gold))] to-[hsl(var(--linguist-purple))] hover:opacity-90"
            >
              <Volume2 className="w-10 h-10 text-black" />
            </Button>
          </div>
        )}

        <h3 className="text-xl font-semibold text-white mb-1">{exercise.prompt}</h3>
        {exercise.promptHint && <p className="text-sm text-zinc-500 mb-4">{exercise.promptHint}</p>}

        {/* MCQ / Match / Read options */}
        {exercise.options && (
          <div className="grid grid-cols-1 gap-2 mt-4">
            {exercise.options.map((opt) => {
              const isSelected = selected === opt;
              const isCorrect = feedback && opt.toLowerCase() === exercise.correctAnswer.toLowerCase();
              const isWrongPick = feedback === "wrong" && isSelected;
              return (
                <button
                  key={opt}
                  onClick={() => !feedback && setSelected(opt)}
                  disabled={!!feedback}
                  className={cn(
                    "w-full text-left px-4 py-3 rounded-lg border-2 transition-all font-medium",
                    "bg-black text-white border-zinc-800 hover:border-[hsl(var(--linguist-gold))]",
                    isSelected && !feedback && "border-[hsl(var(--linguist-purple))] bg-[hsl(var(--linguist-purple))]/10",
                    isCorrect && "border-green-500 bg-green-500/10 text-green-400",
                    isWrongPick && "border-red-500 bg-red-500/10 text-red-400"
                  )}
                >
                  {opt}
                </button>
              );
            })}
          </div>
        )}

        {/* Read-only "continue" prompt for read passages without options */}
        {exercise.type === "read" && !exercise.options && (
          <div className="mt-4">
            <Input
              value={textInput}
              onChange={(e) => setTextInput(e.target.value)}
              placeholder="Type a key word from the article..."
              disabled={!!feedback}
              className="bg-black border-zinc-700 text-white"
            />
          </div>
        )}

        {/* Listen input */}
        {exercise.type === "listen" && (
          <Input
            value={textInput}
            onChange={(e) => setTextInput(e.target.value)}
            placeholder="Type what you hear..."
            disabled={!!feedback}
            className="mt-4 bg-black border-zinc-700 text-white"
          />
        )}

        {/* Feedback */}
        {feedback && (
          <div
            className={cn(
              "mt-4 p-3 rounded-lg flex items-center gap-2 font-semibold",
              feedback === "correct" ? "bg-green-500/10 text-green-400" : "bg-red-500/10 text-red-400"
            )}
          >
            {feedback === "correct" ? (
              <>
                <CheckCircle2 className="w-5 h-5" /> Correct! +5 XP
              </>
            ) : (
              <>
                <XCircle className="w-5 h-5" /> Answer: {exercise.correctAnswer}
              </>
            )}
          </div>
        )}
      </Card>

      <Button
        onClick={feedback ? next : checkAnswer}
        disabled={!feedback && !selected && !textInput.trim()}
        className="w-full h-12 bg-[hsl(var(--linguist-gold))] text-black hover:bg-[hsl(var(--linguist-gold))]/90 font-bold disabled:opacity-40"
      >
        {feedback ? (
          <>
            {currentIdx + 1 === lesson.exercises.length ? "Finish" : "Next"}
            <ArrowRight className="w-4 h-4 ml-2" />
          </>
        ) : (
          "Check"
        )}
      </Button>
    </div>
  );
}

/**
 * MirrorModeCard — Deng says a target-language phrase, the user repeats it,
 * and we score the prosody match using Web Audio RMS profiles.
 *
 * 100 % client side: no backend, no transcription. The score reflects how
 * closely the user's amplitude envelope tracks Deng's TTS envelope.
 */
import { useRef, useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Mic, Square, Volume2, RefreshCcw, Activity } from "lucide-react";
import type { Language } from "@/data/linguistContent";
import { todayBridge } from "@/data/linguistBridge";

const TTS: Record<Language, string> = {
  tr: "tr-TR", ku: "tr-TR", en: "en-US", nl: "nl-NL", ar: "ar-SA",
};

interface Props {
  target: Language;
}

/** RMS envelope (0..1) from raw PCM samples, downsampled to N points. */
function envelope(pcm: Float32Array, points = 32): number[] {
  if (pcm.length === 0) return new Array(points).fill(0);
  const bucket = Math.max(1, Math.floor(pcm.length / points));
  const out: number[] = [];
  for (let i = 0; i < points; i++) {
    const start = i * bucket;
    const end = Math.min(pcm.length, start + bucket);
    let sum = 0;
    for (let j = start; j < end; j++) sum += pcm[j] * pcm[j];
    out.push(Math.sqrt(sum / Math.max(1, end - start)));
  }
  // Normalize 0..1
  const max = Math.max(...out, 1e-6);
  return out.map((v) => v / max);
}

/** Cosine similarity in [0..1] */
function cosine(a: number[], b: number[]): number {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  if (na === 0 || nb === 0) return 0;
  return Math.max(0, Math.min(1, dot / Math.sqrt(na * nb)));
}

/** Estimate Deng's envelope from TTS duration (no real PCM access in browser). */
function syntheticEnvelope(text: string, points = 32): number[] {
  // Build a soft envelope shaped like spoken phrase rhythm based on word lengths.
  const words = text.split(/\s+/).filter(Boolean);
  const arr: number[] = [];
  const perWord = Math.max(1, Math.floor(points / Math.max(1, words.length)));
  words.forEach((w, i) => {
    const peak = Math.min(1, 0.4 + w.length * 0.06);
    for (let j = 0; j < perWord; j++) {
      const phase = j / perWord;
      arr.push(peak * Math.sin(Math.PI * phase) + 0.05);
    }
    if (i < words.length - 1) arr.push(0.05); // gap
  });
  while (arr.length < points) arr.push(0.05);
  return arr.slice(0, points);
}

export function MirrorModeCard({ target }: Props) {
  const [phrase, setPhrase] = useState(() => {
    const w = todayBridge()[0];
    return w.text[target];
  });
  const [recording, setRecording] = useState(false);
  const [score, setScore] = useState<number | null>(null);
  const [busy, setBusy] = useState(false);
  const mrRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const streamRef = useRef<MediaStream | null>(null);

  const speak = () => {
    try {
      const synth = window.speechSynthesis;
      if (!synth) return;
      synth.cancel();
      const u = new SpeechSynthesisUtterance(phrase);
      u.lang = TTS[target];
      u.rate = 0.9;
      synth.speak(u);
    } catch { /* ignore */ }
  };

  const startRecord = async () => {
    setScore(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const mr = new MediaRecorder(stream);
      chunksRef.current = [];
      mr.ondataavailable = (e) => e.data.size > 0 && chunksRef.current.push(e.data);
      mr.onstop = async () => {
        setBusy(true);
        try {
          const blob = new Blob(chunksRef.current, { type: "audio/webm" });
          const arrayBuf = await blob.arrayBuffer();
          const ctx = new AudioContext();
          const audioBuf = await ctx.decodeAudioData(arrayBuf.slice(0));
          const userEnv = envelope(audioBuf.getChannelData(0), 32);
          const dengEnv = syntheticEnvelope(phrase, 32);
          const sim = cosine(userEnv, dengEnv);
          // Boost a bit so >0.5 feels like decent mirror
          const pct = Math.round(Math.min(100, sim * 110));
          setScore(pct);
          await ctx.close();
        } catch (e) {
          console.warn("mirror analyze err", e);
          setScore(0);
        } finally {
          setBusy(false);
          streamRef.current?.getTracks().forEach((t) => t.stop());
          streamRef.current = null;
        }
      };
      mrRef.current = mr;
      mr.start();
      setRecording(true);
      // Auto-stop after 4s safety
      setTimeout(() => {
        if (mrRef.current?.state === "recording") {
          mrRef.current.stop();
          setRecording(false);
        }
      }, 4500);
    } catch {
      setRecording(false);
    }
  };

  const stopRecord = () => {
    try { mrRef.current?.stop(); } catch { /* ignore */ }
    setRecording(false);
  };

  const reroll = () => {
    const list = todayBridge();
    const next = list[Math.floor(Math.random() * list.length)];
    setPhrase(next.text[target]);
    setScore(null);
  };

  const tone =
    score === null ? "text-zinc-500"
      : score >= 75 ? "text-emerald-400"
      : score >= 50 ? "text-[hsl(var(--linguist-gold))]"
      : "text-rose-400";

  return (
    <Card className="bg-zinc-950 border border-emerald-500/30 p-4 space-y-3">
      <div className="flex items-center gap-2">
        <Activity className="w-4 h-4 text-emerald-400" />
        <span className="text-sm font-semibold text-zinc-200">Mirror Mode</span>
        <button
          type="button"
          onClick={reroll}
          className="ml-auto text-[10px] text-zinc-500 hover:text-emerald-400 flex items-center gap-1"
        >
          <RefreshCcw className="w-3 h-3" /> yenile
        </button>
      </div>

      <div className="rounded-xl border border-zinc-800 bg-black p-4 text-center">
        <div className="text-[10px] uppercase tracking-wider text-zinc-500 mb-1">
          {target.toUpperCase()} · tekrar et
        </div>
        <div
          className="text-2xl font-bold text-emerald-300 break-words"
          dir={target === "ar" ? "rtl" : "ltr"}
        >
          {phrase}
        </div>
        <button
          type="button"
          onClick={speak}
          className="mt-2 inline-flex items-center gap-1 text-[10px] text-zinc-400 hover:text-emerald-400"
        >
          <Volume2 className="w-3 h-3" /> Deng'i dinle
        </button>
      </div>

      <div className="flex items-center gap-2">
        <Button
          type="button"
          onClick={recording ? stopRecord : startRecord}
          disabled={busy}
          className={`flex-1 h-11 ${
            recording
              ? "bg-rose-500 text-white hover:bg-rose-500/90 animate-pulse"
              : "bg-emerald-500 text-black hover:bg-emerald-500/90"
          }`}
        >
          {recording ? (
            <><Square className="w-4 h-4 mr-1.5" /> Durdur</>
          ) : (
            <><Mic className="w-4 h-4 mr-1.5" /> {busy ? "Hesaplıyor..." : "Tekrar et"}</>
          )}
        </Button>
      </div>

      {score !== null && (
        <div className="rounded-lg border border-zinc-800 bg-zinc-900/50 p-3 text-center">
          <div className="text-[10px] uppercase tracking-wider text-zinc-500">Eşleşme</div>
          <div className={`text-3xl font-bold tabular-nums ${tone}`}>%{score}</div>
          <div className="mt-2 h-1.5 rounded-full bg-zinc-800 overflow-hidden">
            <div
              className={`h-full transition-all duration-500 ${
                score >= 75 ? "bg-emerald-500"
                  : score >= 50 ? "bg-[hsl(var(--linguist-gold))]"
                  : "bg-rose-500"
              }`}
              style={{ width: `${score}%` }}
            />
          </div>
          <p className="text-[10px] text-zinc-500 mt-2">
            {score >= 75 ? "Mükemmel ritim — Deng senle gurur duyuyor."
              : score >= 50 ? "İyi gidiyorsun, vurguyu biraz daha taklit et."
              : "Önce dinle, sonra aynı hızda tekrar et."}
          </p>
        </div>
      )}
    </Card>
  );
}

