/**
 * QuickQuizCard — minimalist 4-question rapid quiz, separate from lessons.
 * Pulls 4 random MCQ-style exercises from the active language course and
 * awards mastery callbacks per correct answer. Designed to fit the
 * "5-minute roadmap" warm-up step.
 */
import { useEffect, useMemo, useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { CheckCircle2, XCircle, Zap, RefreshCw } from "lucide-react";
import { getCourse, type Language, type Exercise } from "@/data/linguistContent";

interface Props {
  language: Language;
  onCorrect?: () => void;
  onComplete?: (score: number) => void;
}

function shuffle<T>(arr: T[], seed: number): T[] {
  const a = [...arr];
  let s = seed || 1;
  for (let i = a.length - 1; i > 0; i--) {
    s = (s * 9301 + 49297) % 233280;
    const j = Math.floor((s / 233280) * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export function QuickQuizCard({ language, onCorrect, onComplete }: Props) {
  const [seed, setSeed] = useState(() => Date.now());
  const [step, setStep] = useState(0);
  const [score, setScore] = useState(0);
  const [picked, setPicked] = useState<string | null>(null);
  const [done, setDone] = useState(false);

  const questions: Exercise[] = useMemo(() => {
    const course = getCourse(language);
    const allMcq: Exercise[] = course.lessons
      .flatMap((l) => l.exercises)
      .filter((e) => (e.type === "mcq" || e.type === "match") && (e.options?.length ?? 0) >= 2);
    return shuffle(allMcq, seed).slice(0, 4);
  }, [language, seed]);

  // Reset when language or seed changes
  useEffect(() => {
    setStep(0);
    setScore(0);
    setPicked(null);
    setDone(false);
  }, [language, seed]);

  if (questions.length === 0) {
    return null;
  }

  const q = questions[step];
  const correct = picked && picked.trim().toLowerCase() === q.correctAnswer.trim().toLowerCase();

  const choose = (opt: string) => {
    if (picked) return;
    setPicked(opt);
    const isRight = opt.trim().toLowerCase() === q.correctAnswer.trim().toLowerCase();
    if (isRight) {
      setScore((s) => s + 1);
      onCorrect?.();
    }
    setTimeout(() => {
      if (step + 1 >= questions.length) {
        setDone(true);
        onComplete?.(score + (isRight ? 1 : 0));
      } else {
        setStep((s) => s + 1);
        setPicked(null);
      }
    }, 700);
  };

  const restart = () => setSeed(Date.now());

  return (
    <Card className="bg-zinc-950 border border-[hsl(var(--linguist-gold))]/30 p-4 space-y-3">
      <div className="flex items-center gap-2">
        <Zap className="w-4 h-4 text-[hsl(var(--linguist-gold))]" />
        <span className="text-sm font-semibold text-zinc-200">4 Soruluk Hızlı Kart</span>
        <Badge className="ml-auto bg-[hsl(var(--linguist-gold))]/15 text-[hsl(var(--linguist-gold))] border-0 text-[10px]">
          {done ? `${score}/${questions.length}` : `${step + 1}/${questions.length}`}
        </Badge>
      </div>

      {!done ? (
        <>
          <div className="text-[10px] uppercase tracking-wider text-zinc-500">Soru {step + 1}</div>
          <p className="text-base font-semibold text-white leading-snug">{q.prompt}</p>

          <div className="grid grid-cols-2 gap-2 pt-1">
            {q.options?.map((opt) => {
              const state =
                picked === null
                  ? "idle"
                  : opt === q.correctAnswer
                  ? "right"
                  : opt === picked
                  ? "wrong"
                  : "muted";
              return (
                <button
                  key={opt}
                  type="button"
                  disabled={!!picked}
                  onClick={() => choose(opt)}
                  className={`text-left px-3 py-2.5 rounded-lg border text-sm font-medium transition-all ${
                    state === "right"
                      ? "border-emerald-500 bg-emerald-500/15 text-emerald-300"
                      : state === "wrong"
                      ? "border-rose-500 bg-rose-500/15 text-rose-300"
                      : state === "muted"
                      ? "border-zinc-800 text-zinc-500 opacity-60"
                      : "border-zinc-800 text-zinc-200 hover:border-[hsl(var(--linguist-gold))]/60 hover:bg-[hsl(var(--linguist-gold))]/5"
                  }`}
                >
                  <span className="flex items-center gap-1.5">
                    {state === "right" && <CheckCircle2 className="w-3.5 h-3.5" />}
                    {state === "wrong" && <XCircle className="w-3.5 h-3.5" />}
                    <span className="truncate">{opt}</span>
                  </span>
                </button>
              );
            })}
          </div>
        </>
      ) : (
        <div className="text-center py-3 space-y-2">
          <div className="text-3xl">{score === questions.length ? "🏆" : score >= 2 ? "✨" : "💪"}</div>
          <div className="text-lg font-bold text-white">
            {score} / {questions.length} doğru
          </div>
          <p className="text-xs text-zinc-400">
            {score === questions.length
              ? "Mükemmel! Bütün kartlar tamam."
              : score >= 2
              ? "Güzel ilerleme — bir tur daha at."
              : "Tekrar dene, kas hafızası gelecek."}
          </p>
          <Button
            onClick={restart}
            size="sm"
            className="bg-[hsl(var(--linguist-gold))] text-black hover:bg-[hsl(var(--linguist-gold))]/90"
          >
            <RefreshCw className="w-3 h-3 mr-1.5" /> Yeni 4 Soru
          </Button>
        </div>
      )}
    </Card>
  );
}

