import { useEffect, useMemo, useState } from "react";
import { Volume2, Check, X } from "lucide-react";
import type { Flashcard } from "@/data/linguistFlashcards";
import { linguistSounds } from "@/lib/linguistAudio";
import { Button } from "@/components/ui/button";

interface Props {
  card: Flashcard;
  pool: Flashcard[];
  onAnswer: (correct: boolean) => void;
  /** "nl-to-tr" shows Dutch word, asks for Turkish meaning. "tr-to-nl" the reverse. */
  direction?: "nl-to-tr" | "tr-to-nl";
}

function shuffle<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export function QuizCard({ card, pool, onAnswer, direction = "nl-to-tr" }: Props) {
  const [selected, setSelected] = useState<string | null>(null);
  const [revealed, setRevealed] = useState(false);

  const isNlToTr = direction === "nl-to-tr";
  const prompt = isNlToTr ? card.dutch : card.turkish;
  const correct = isNlToTr ? card.turkish : card.dutch;

  // Build 4 options: correct + 3 distractors from same category if possible
  const options = useMemo(() => {
    const sameCat = pool.filter((c) => c.id !== card.id && c.category === card.category);
    const others = pool.filter((c) => c.id !== card.id && c.category !== card.category);
    const distractors = shuffle([...sameCat, ...others]).slice(0, 3);
    const all = shuffle([card, ...distractors]);
    return all.map((c) => (isNlToTr ? c.turkish : c.dutch));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [card.id]);

  // Reset on new card
  useEffect(() => {
    setSelected(null);
    setRevealed(false);
  }, [card.id]);

  const handleSelect = (opt: string) => {
    if (revealed) return;
    setSelected(opt);
    setRevealed(true);
    const isCorrect = opt === correct;
    if (isCorrect) linguistSounds.mastered();
    else linguistSounds.review();
    setTimeout(() => onAnswer(isCorrect), 850);
  };

  return (
    <div className="w-full space-y-4">
      {/* Prompt card */}
      <div className="relative rounded-3xl bg-black border-2 border-[#FFD700] p-6 overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-br from-[#FFD700]/5 via-transparent to-[#9B59B6]/10 pointer-events-none" />
        <div className="absolute top-3 left-3 w-6 h-6 border-t-2 border-l-2 border-[#9B59B6]" />
        <div className="absolute top-3 right-3 w-6 h-6 border-t-2 border-r-2 border-[#9B59B6]" />
        <div className="absolute bottom-3 left-3 w-6 h-6 border-b-2 border-l-2 border-[#9B59B6]" />
        <div className="absolute bottom-3 right-3 w-6 h-6 border-b-2 border-r-2 border-[#9B59B6]" />

        <div className="relative flex items-center justify-between mb-4">
          <span className="text-[10px] uppercase tracking-[0.2em] text-[#9B59B6] font-bold">
            {isNlToTr ? "🇳🇱 Çevir → 🇹🇷" : "🇹🇷 Çevir → 🇳🇱"}
          </span>
          <span className="text-[10px] uppercase tracking-[0.2em] text-zinc-600 font-bold">
            {card.category}
          </span>
        </div>

        <div className="relative flex flex-col items-center gap-3 py-4">
          <div className="text-3xl md:text-4xl font-bold text-white text-center leading-tight">
            {prompt}
          </div>
          {isNlToTr && (
            <button
              type="button"
              onClick={() => linguistSounds.speak(card.dutch, "nl-NL")}
              className="w-11 h-11 rounded-full bg-gradient-to-br from-[#FFD700] to-[#9B59B6] flex items-center justify-center shadow-[0_0_24px_rgba(255,215,0,0.3)] hover:scale-105 transition-transform"
              aria-label="Sesli oku"
            >
              <Volume2 className="w-5 h-5 text-black" />
            </button>
          )}
        </div>
      </div>

      {/* 4 options */}
      <div className="grid grid-cols-1 gap-2.5">
        {options.map((opt, idx) => {
          const isCorrectOpt = opt === correct;
          const isPicked = selected === opt;
          let cls =
            "border-zinc-800 bg-zinc-950 text-white hover:border-[#9B59B6]/60 hover:bg-zinc-900";
          if (revealed) {
            if (isCorrectOpt) cls = "border-[#FFD700] bg-[#FFD700]/15 text-[#FFD700]";
            else if (isPicked) cls = "border-red-500 bg-red-500/10 text-red-400";
            else cls = "border-zinc-900 bg-zinc-950 text-zinc-600";
          }
          return (
            <button
              key={`${card.id}-${idx}`}
              type="button"
              disabled={revealed}
              onClick={() => handleSelect(opt)}
              className={`flex items-center justify-between gap-3 px-4 py-3.5 rounded-xl border-2 text-left font-semibold transition-all disabled:cursor-default ${cls}`}
            >
              <span className="flex items-center gap-3">
                <span className="w-6 h-6 rounded-md border border-current/30 flex items-center justify-center text-[11px] font-bold tabular-nums">
                  {idx + 1}
                </span>
                <span className="text-sm md:text-base">{opt}</span>
              </span>
              {revealed && isCorrectOpt && <Check className="w-5 h-5" />}
              {revealed && isPicked && !isCorrectOpt && <X className="w-5 h-5" />}
            </button>
          );
        })}
      </div>

      {/* Explanation reveal */}
      {revealed && (
        <div className="rounded-xl border border-[#9B59B6]/40 bg-[#9B59B6]/5 p-3 text-xs text-zinc-300 leading-relaxed">
          <span className="text-[#FFD700] font-bold">Örnek:</span> "{card.exampleNl}"
          <div className="text-zinc-500 mt-1">{card.exampleTr}</div>
        </div>
      )}

      {!revealed && (
        <Button
          variant="ghost"
          size="sm"
          onClick={() => handleSelect("__skip__")}
          className="w-full text-zinc-500 hover:text-zinc-300"
        >
          Bilmiyorum, atla
        </Button>
      )}
    </div>
  );
}

