/**
 * RoadmapCards — The classic 4-card "5-minute roadmap" panel.
 *
 * Renders 4 professional cards (Warm-up · Drill · Live Practice · Reflect)
 * with:
 *   • Step numbers + estimated minutes (sums to ~5 min)
 *   • Per-step progress bar
 *   • Active step ring (theme gold)
 *   • A unique daily "method" picked from a rotating pool — so users never see
 *     the same drill two days in a row (Shadowing → Mirror → Dictation Sprint →
 *     Translate Race → Sovereign Story → Audio Snapshot → Cognate Hunt).
 */
import { useEffect, useMemo } from "react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Sparkles, Target, Mic, BookOpen, Lightbulb } from "lucide-react";

export type RoadmapStepKey = "warmup" | "drill" | "practice" | "reflect";

interface Props {
  /** 0-100 percent for each of the 4 steps */
  progress: Record<RoadmapStepKey, number>;
  /** which step is "now" — defaults to first incomplete */
  activeKey?: RoadmapStepKey;
  onStepClick?: (key: RoadmapStepKey) => void;
  /** Expose today's drill method to the parent (for Deng scenarios) */
  onMethodResolved?: (method: string) => void;
}

/** Per-step measurement rules surfaced in the UI so progress is transparent. */
const RULES: Record<RoadmapStepKey, string> = {
  warmup: "1 dk uygulamada kal · veya 4 hızlı soruyu çöz",
  drill: "4 kart öğrenildi (her kart %25)",
  practice: "Deng AI ile 1 turu tamamla",
  reflect: "Yansımayı manuel mühürle",
};

/** Daily-rotating unique method names (shows next to "Drill" card) */
const DRILL_METHODS = [
  { name: "Shadowing", hint: "Robotu duy → 1 saniye sonra aynısını söyle." },
  { name: "Mirror Drill", hint: "Aynaya bakarak ağız hareketini taklit et." },
  { name: "Dictation Sprint", hint: "Duyduğunu 30 sn'de yaz — hız > mükemmellik." },
  { name: "Translate Race", hint: "Anadilden hedef dile en hızlı çeviri." },
  { name: "Sovereign Story", hint: "3 cümlede kendi anayasal kimliğini anlat." },
  { name: "Audio Snapshot", hint: "10 sn'lik ses notu kaydet, kendini dinle." },
  { name: "Cognate Hunt", hint: "Anadiline benzeyen 3 kelime keşfet." },
];

const REFLECT_PROMPTS = [
  "Bugün öğrendiğin 1 kelimeyi gerçek bir cümlede kullan.",
  "Yeni öğrendiğin yapıyı bir hatıra ile eşleştir.",
  "Bir Kürt köyünün ismini hedef dilde tarif et.",
  "Anadilinde olmayan bir nüansı not et.",
  "Bugünün kelimesini Deng'e öğret.",
  "Öğrendiğini yarın birine anlatacağını hayal et.",
  "Hedef dilde 'özgürlük' nasıl yazılır? Sesli söyle.",
];

export function RoadmapCards({ progress, activeKey, onStepClick, onMethodResolved }: Props) {
  /** Stable daily index → users see the same method all day, then it rotates */
  const dayIndex = useMemo(() => {
    const d = new Date();
    return Math.floor(
      Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) / 86_400_000,
    );
  }, []);
  const drill = DRILL_METHODS[dayIndex % DRILL_METHODS.length];
  const reflectPrompt = REFLECT_PROMPTS[dayIndex % REFLECT_PROMPTS.length];

  // Notify parent so DengPracticeTab can sync scenarios with the daily method.
  useEffect(() => {
    onMethodResolved?.(drill.name);
  }, [drill.name, onMethodResolved]);

  /** Auto-detect active step if not passed */
  const computedActive: RoadmapStepKey = useMemo(() => {
    if (activeKey) return activeKey;
    const order: RoadmapStepKey[] = ["warmup", "drill", "practice", "reflect"];
    return order.find((k) => (progress[k] ?? 0) < 100) ?? "reflect";
  }, [activeKey, progress]);

  const STEPS: {
    key: RoadmapStepKey;
    n: number;
    minutes: number;
    title: string;
    body: string;
    Icon: typeof Sparkles;
    hue: "gold" | "purple" | "emerald" | "blue";
  }[] = [
    {
      key: "warmup",
      n: 1,
      minutes: 1,
      title: "Isınma",
      body: "Dünkü 5 kelimeyi 60 sn'de gözden geçir.",
      Icon: Sparkles,
      hue: "gold",
    },
    {
      key: "drill",
      n: 2,
      minutes: 2,
      title: `${drill.name}`,
      body: drill.hint,
      Icon: Target,
      hue: "purple",
    },
    {
      key: "practice",
      n: 3,
      minutes: 1,
      title: "Canlı Pratik",
      body: "Deng AI ile 1 dk sesli mini-diyalog.",
      Icon: Mic,
      hue: "emerald",
    },
    {
      key: "reflect",
      n: 4,
      minutes: 1,
      title: "Yansıt & Mühürle",
      body: reflectPrompt,
      Icon: Lightbulb,
      hue: "blue",
    },
  ];

  const totalDone = STEPS.reduce((s, x) => s + (progress[x.key] ?? 0), 0) / STEPS.length;

  return (
    <Card className="bg-zinc-950 border border-[hsl(var(--linguist-gold))]/30 p-4 space-y-4">
      <div className="flex items-center gap-2">
        <BookOpen className="w-4 h-4 text-[hsl(var(--linguist-gold))]" />
        <span className="text-sm font-semibold text-zinc-200">5 Dakikalık Yol Haritası</span>
        <Badge className="ml-auto bg-[hsl(var(--linguist-gold))]/15 text-[hsl(var(--linguist-gold))] border-0 text-[10px]">
          Bugünkü metot · {drill.name}
        </Badge>
      </div>

      {/* overall ribbon */}
      <Progress
        value={totalDone}
        className="h-1.5 bg-zinc-900 [&>div]:bg-gradient-to-r [&>div]:from-[hsl(var(--linguist-gold))] [&>div]:to-[hsl(var(--linguist-purple))]"
      />

      <div className="grid grid-cols-2 gap-3">
        {STEPS.map(({ key, n, minutes, title, body, Icon, hue }) => {
          const value = progress[key] ?? 0;
          const isActive = key === computedActive;
          const done = value >= 100;
          const ring =
            hue === "gold"
              ? "from-[hsl(var(--linguist-gold))]/40 to-amber-500/10"
              : hue === "purple"
              ? "from-[hsl(var(--linguist-purple))]/40 to-violet-500/10"
              : hue === "emerald"
              ? "from-emerald-500/40 to-emerald-700/10"
              : "from-sky-500/40 to-sky-700/10";
          const text =
            hue === "gold"
              ? "text-[hsl(var(--linguist-gold))]"
              : hue === "purple"
              ? "text-[hsl(var(--linguist-purple))]"
              : hue === "emerald"
              ? "text-emerald-400"
              : "text-sky-400";
          return (
            <button
              key={key}
              type="button"
              onClick={() => onStepClick?.(key)}
              className={`text-left group relative overflow-hidden rounded-xl p-3 border transition-all ${
                isActive
                  ? "border-[hsl(var(--linguist-gold))]/70 bg-gradient-to-br from-zinc-900 to-black shadow-[0_0_24px_-6px_hsl(var(--linguist-gold)/0.4)]"
                  : "border-zinc-800 bg-zinc-950 hover:border-zinc-700"
              }`}
            >
              <div
                className={`absolute -top-10 -right-10 w-24 h-24 rounded-full bg-gradient-to-br ${ring} blur-2xl opacity-70 pointer-events-none`}
              />
              <div className="flex items-start gap-2 relative">
                <div
                  className={`w-7 h-7 rounded-md grid place-items-center bg-black/60 border ${
                    done ? "border-emerald-500/60" : "border-zinc-700"
                  }`}
                >
                  <Icon className={`w-3.5 h-3.5 ${text}`} />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between gap-1">
                    <div className="text-[10px] uppercase tracking-wider text-zinc-500">
                      Adım {n} · {minutes} dk
                    </div>
                    {done && (
                      <span className="text-[9px] font-semibold text-emerald-400 uppercase">
                        ✓ tamam
                      </span>
                    )}
                  </div>
                  <h3 className={`text-sm font-bold mt-0.5 ${text} truncate`}>{title}</h3>
                  <p className="text-[11px] text-zinc-400 leading-snug mt-1 line-clamp-2">
                    {body}
                  </p>
                  <p className="text-[9px] text-zinc-600 mt-1 italic line-clamp-1">
                    Ölçüm: {RULES[key]}
                  </p>
                </div>
              </div>
              <div className="mt-2 flex items-center justify-between text-[9px] text-zinc-500">
                <span>%{Math.round(value)}</span>
                <span>{done ? "tamam" : "devam"}</span>
              </div>
              <div className="mt-2.5">
                <div className="h-1 rounded-full bg-zinc-900 overflow-hidden">
                  <div
                    className={`h-full transition-all duration-500 ${
                      done
                        ? "bg-emerald-500"
                        : "bg-gradient-to-r from-[hsl(var(--linguist-gold))] to-[hsl(var(--linguist-purple))]"
                    }`}
                    style={{ width: `${Math.min(100, value)}%` }}
                  />
                </div>
              </div>
            </button>
          );
        })}
      </div>

      <p className="text-[10px] text-zinc-500 text-center">
        💡 Yöntem her gün otomatik değişir — hiçbir gün aynı egzersizi tekrarlamazsın.
      </p>
    </Card>
  );
}

