/**
 * RobotAvatar — Real 3D robot built with @react-three/fiber.
 * Theme-aware (gold + purple) with user-tunable brightness, eye color and
 * camera angle (see useRobotPreferences).
 *
 * States:
 *   • "idle"      — gentle breathing + slow rotation
 *   • "listening" — emerald eye pulse + faster bob, antenna blinks
 *   • "speaking"  — gold halo, mouth bars animate, head nods
 */
import { Suspense, useMemo, useRef, useState, useEffect, Component, type ReactNode } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { Float, ContactShadows, RoundedBox, Text } from "@react-three/drei";
import * as THREE from "three";
import {
  EYE_COLORS,
  CAMERA_ANGLES,
  type EyeColorKey,
  type CameraAngleKey,
} from "@/hooks/useRobotPreferences";

export type RobotState = "idle" | "listening" | "speaking";

interface Props {
  state?: RobotState;
  size?: number;
  language?: string;
  brightness?: number;            // 0.4..1.8, default 1
  eyeColor?: EyeColorKey;         // default "purple"
  cameraAngle?: CameraAngleKey;   // default "front"
}

/* ─── Inner 3D scene (must live inside <Canvas>) ─── */
function RobotMesh({
  state,
  language,
  baseEye,
}: {
  state: RobotState;
  language?: string;
  baseEye: string;
}) {
  const head = useRef<THREE.Group>(null);
  const antenna = useRef<THREE.Mesh>(null);
  const leftEye = useRef<THREE.Mesh>(null);
  const rightEye = useRef<THREE.Mesh>(null);
  const halo = useRef<THREE.Mesh>(null);
  const mouthBars = useRef<THREE.Group>(null);

  const eyeColor = useMemo(() => {
    if (state === "listening") return new THREE.Color("#34d399");
    if (state === "speaking") return new THREE.Color("#F2C94C");
    return new THREE.Color(baseEye);
  }, [state, baseEye]);

  const haloColor = useMemo(() => {
    if (state === "speaking") return new THREE.Color("#F2C94C");
    if (state === "listening") return new THREE.Color("#34d399");
    return new THREE.Color(baseEye);
  }, [state, baseEye]);

  useFrame(({ clock }) => {
    const t = clock.getElapsedTime();
    if (head.current) {
      const speed = state === "idle" ? 1 : 2.4;
      head.current.position.y = Math.sin(t * speed) * 0.06 + 0.05;
      head.current.rotation.y =
        state === "speaking" ? Math.sin(t * 4) * 0.08 : Math.sin(t * 0.6) * 0.18;
      head.current.rotation.x = state === "speaking" ? Math.sin(t * 3) * 0.05 : 0;
    }
    if (antenna.current) {
      const s = 1 + (Math.sin(t * (state === "listening" ? 7 : 2)) + 1) * 0.25;
      antenna.current.scale.set(s, s, s);
    }
    if (leftEye.current && rightEye.current) {
      const pulse = state === "listening" ? 1 + Math.abs(Math.sin(t * 6)) * 0.35 : 1;
      leftEye.current.scale.set(pulse, pulse, pulse);
      rightEye.current.scale.set(pulse, pulse, pulse);
      (leftEye.current.material as THREE.MeshStandardMaterial).emissiveIntensity =
        state === "idle" ? 0.6 : 1.4;
      (rightEye.current.material as THREE.MeshStandardMaterial).emissiveIntensity =
        state === "idle" ? 0.6 : 1.4;
    }
    if (halo.current) {
      halo.current.rotation.z = t * 0.4;
      const breathe = 1 + Math.sin(t * (state === "idle" ? 1.2 : 3.4)) * 0.06;
      halo.current.scale.set(breathe, breathe, breathe);
      (halo.current.material as THREE.MeshBasicMaterial).opacity = state === "idle" ? 0.2 : 0.45;
    }
    if (mouthBars.current && state === "speaking") {
      mouthBars.current.children.forEach((bar, i) => {
        const m = bar as THREE.Mesh;
        const h = 0.05 + Math.abs(Math.sin(t * 8 + i * 0.7)) * 0.18;
        m.scale.y = h * 10;
      });
    } else if (mouthBars.current) {
      mouthBars.current.children.forEach((bar) => {
        (bar as THREE.Mesh).scale.y = 0.4;
      });
    }
  });

  return (
    <Float speed={1.2} rotationIntensity={state === "idle" ? 0.25 : 0.05} floatIntensity={0.3}>
      <mesh ref={halo} position={[0, 0.4, -0.4]} rotation={[Math.PI / 2, 0, 0]}>
        <ringGeometry args={[0.95, 1.1, 64]} />
        <meshBasicMaterial color={haloColor} transparent opacity={0.3} side={THREE.DoubleSide} />
      </mesh>

      <RoundedBox args={[1.1, 0.7, 0.55]} radius={0.12} smoothness={4} position={[0, -0.55, 0]}>
        <meshStandardMaterial color="#141414" metalness={0.65} roughness={0.32} />
      </RoundedBox>

      <mesh position={[0, -0.55, 0.28]}>
        <cylinderGeometry args={[0.13, 0.13, 0.05, 32]} />
        <meshStandardMaterial
          color="#0a0a0a"
          emissive={haloColor}
          emissiveIntensity={state === "speaking" ? 1.2 : 0.5}
          metalness={0.8}
          roughness={0.2}
        />
      </mesh>

      <mesh position={[0, -0.15, 0]}>
        <cylinderGeometry args={[0.13, 0.16, 0.18, 16]} />
        <meshStandardMaterial color="#1a1a1a" metalness={0.7} roughness={0.4} />
      </mesh>

      <group ref={head} position={[0, 0.4, 0]}>
        <RoundedBox args={[1.15, 1.0, 0.95]} radius={0.18} smoothness={5}>
          <meshStandardMaterial color="#1c1c1c" metalness={0.7} roughness={0.28} />
        </RoundedBox>

        <RoundedBox args={[0.9, 0.42, 0.04]} radius={0.1} smoothness={4} position={[0, 0.08, 0.49]}>
          <meshStandardMaterial
            color="#0a0a0a"
            metalness={0.95}
            roughness={0.05}
            emissive="#F2C94C"
            emissiveIntensity={0.08}
          />
        </RoundedBox>

        <mesh ref={leftEye} position={[-0.2, 0.08, 0.52]}>
          <sphereGeometry args={[0.07, 24, 24]} />
          <meshStandardMaterial
            color={eyeColor}
            emissive={eyeColor}
            emissiveIntensity={1}
            metalness={0.2}
            roughness={0.2}
          />
        </mesh>
        <mesh ref={rightEye} position={[0.2, 0.08, 0.52]}>
          <sphereGeometry args={[0.07, 24, 24]} />
          <meshStandardMaterial
            color={eyeColor}
            emissive={eyeColor}
            emissiveIntensity={1}
            metalness={0.2}
            roughness={0.2}
          />
        </mesh>

        <group ref={mouthBars} position={[0, -0.22, 0.5]}>
          {[-0.16, -0.08, 0, 0.08, 0.16].map((x) => (
            <mesh key={x} position={[x, 0, 0]}>
              <boxGeometry args={[0.04, 0.04, 0.02]} />
              <meshStandardMaterial color="#F2C94C" emissive="#F2C94C" emissiveIntensity={0.8} />
            </mesh>
          ))}
        </group>

        <mesh position={[-0.6, 0, 0]}>
          <cylinderGeometry args={[0.08, 0.08, 0.18, 16]} />
          <meshStandardMaterial color="#2a2a2a" metalness={0.7} roughness={0.4} />
        </mesh>
        <mesh position={[0.6, 0, 0]}>
          <cylinderGeometry args={[0.08, 0.08, 0.18, 16]} />
          <meshStandardMaterial color="#2a2a2a" metalness={0.7} roughness={0.4} />
        </mesh>

        <mesh position={[0, 0.6, 0]}>
          <cylinderGeometry args={[0.012, 0.012, 0.28, 8]} />
          <meshStandardMaterial color="#F2C94C" metalness={0.9} roughness={0.2} />
        </mesh>
        <mesh ref={antenna} position={[0, 0.78, 0]}>
          <sphereGeometry args={[0.06, 16, 16]} />
          <meshStandardMaterial
            color="#F2C94C"
            emissive="#F2C94C"
            emissiveIntensity={state === "listening" ? 1.6 : 0.8}
          />
        </mesh>

        {language && (
          <Text
            position={[0, -0.45, 0.5]}
            fontSize={0.09}
            color="#F2C94C"
            anchorX="center"
            anchorY="middle"
            letterSpacing={0.08}
          >
            {language.toUpperCase()}
          </Text>
        )}
      </group>
    </Float>
  );
}

/* SSR-safe error boundary so a R3F crash never breaks the page. */
class CanvasBoundary extends Component<{ children: ReactNode; fallback: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidCatch(err: unknown) { console.warn("[RobotAvatar] 3D canvas failed, using fallback", err); }
  render() { return this.state.failed ? this.props.fallback : this.props.children; }
}

export function RobotAvatar({
  state = "idle",
  size = 220,
  language,
  brightness = 1,
  eyeColor = "purple",
  cameraAngle = "front",
}: Props) {
  const baseEye = EYE_COLORS[eyeColor].hex;
  const cam = CAMERA_ANGLES[cameraAngle].pos;
  const b = Math.max(0.2, brightness);

  // Mount the Canvas only after the component has hydrated on the client —
  // R3F's `Canvas.connect` reads `parent.addEventListener` and crashes when
  // it runs against an SSR/null host element.
  const [mounted, setMounted] = useState(false);
  useEffect(() => { setMounted(true); }, []);

  const fallback2D = (
    <div
      className="w-full h-full flex items-center justify-center"
      style={{
        background: `radial-gradient(circle at 50% 50%, ${baseEye}33 0%, transparent 70%)`,
      }}
      aria-hidden
    >
      <div
        className="rounded-full"
        style={{
          width: size * 0.55,
          height: size * 0.55,
          background: `radial-gradient(circle at 35% 30%, ${baseEye} 0%, #1a1a1a 70%)`,
          boxShadow: `0 0 40px ${baseEye}66`,
        }}
      />
    </div>
  );

  return (
    <div
      className="relative mx-auto select-none"
      style={{ width: size, height: size }}
      aria-label={`Deng AI ${state}`}
    >
      {mounted ? (
        <CanvasBoundary fallback={fallback2D}>
          <Canvas
            dpr={[1, 2]}
            camera={{ position: cam, fov: 38 }}
            gl={{ antialias: true, alpha: true, powerPreference: "high-performance" }}
            style={{ background: "transparent" }}
          >
            <Suspense fallback={null}>
              <ambientLight intensity={0.55 * b} />
              <directionalLight position={[3, 4, 4]} intensity={1.1 * b} color="#F2C94C" />
              <directionalLight position={[-3, 2, 2]} intensity={0.6 * b} color="#8b5cf6" />
              <pointLight position={[0, -2, 2]} intensity={0.4 * b} color="#34d399" />
              <RobotMesh state={state} language={language} baseEye={baseEye} />
              <ContactShadows
                position={[0, -1.15, 0]}
                opacity={0.45}
                scale={4}
                blur={2.2}
                far={2}
                color="#000000"
              />
            </Suspense>
          </Canvas>
        </CanvasBoundary>
      ) : (
        fallback2D
      )}

      <div
        className="absolute inset-0 -z-10 pointer-events-none rounded-full"
        style={{
          background:
            state === "speaking"
              ? "radial-gradient(circle at 50% 55%, rgba(242,201,76,0.35) 0%, transparent 65%)"
              : state === "listening"
              ? "radial-gradient(circle at 50% 55%, rgba(52,211,153,0.32) 0%, transparent 65%)"
              : `radial-gradient(circle at 50% 55%, ${baseEye}55 0%, transparent 70%)`,
          filter: "blur(8px)",
          opacity: 0.65 * b,
        }}
      />
    </div>
  );
}

