/**
 * RobotSettingsSheet — minimalist control panel for the 3D Deng robot.
 * Lets the user adjust brightness, eye color and camera angle.
 */
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { Slider } from "@/components/ui/slider";
import { Settings2, RotateCcw } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  EYE_COLORS,
  CAMERA_ANGLES,
  type RobotPreferences,
  type EyeColorKey,
  type CameraAngleKey,
} from "@/hooks/useRobotPreferences";

interface Props {
  prefs: RobotPreferences;
  onChange: (patch: Partial<RobotPreferences>) => void;
  onReset: () => void;
}

export function RobotSettingsSheet({ prefs, onChange, onReset }: Props) {
  return (
    <Sheet>
      <SheetTrigger asChild>
        <button
          type="button"
          aria-label="Robot ayarları"
          className="absolute top-2 right-2 z-10 w-8 h-8 rounded-full bg-black/60 backdrop-blur border border-zinc-700 grid place-items-center text-zinc-300 hover:text-[hsl(var(--linguist-gold))] hover:border-[hsl(var(--linguist-gold))]/60 transition"
        >
          <Settings2 className="w-3.5 h-3.5" />
        </button>
      </SheetTrigger>
      <SheetContent side="bottom" className="bg-zinc-950 border-t border-[hsl(var(--linguist-gold))]/30 text-white">
        <SheetHeader>
          <SheetTitle className="text-[hsl(var(--linguist-gold))]">Robot Ayarları</SheetTitle>
        </SheetHeader>

        <div className="space-y-5 py-4 max-w-md mx-auto">
          {/* Brightness */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs uppercase tracking-wider text-zinc-400">Parlaklık</label>
              <span className="text-xs text-[hsl(var(--linguist-gold))] font-mono">
                {prefs.brightness.toFixed(2)}×
              </span>
            </div>
            <Slider
              min={0.4}
              max={1.8}
              step={0.05}
              value={[prefs.brightness]}
              onValueChange={([v]) => onChange({ brightness: v })}
            />
          </div>

          {/* Eye color */}
          <div>
            <label className="text-xs uppercase tracking-wider text-zinc-400 mb-2 block">Göz Rengi</label>
            <div className="grid grid-cols-5 gap-2">
              {(Object.keys(EYE_COLORS) as EyeColorKey[]).map((k) => (
                <button
                  key={k}
                  type="button"
                  onClick={() => onChange({ eyeColor: k })}
                  className={`aspect-square rounded-full border-2 transition-transform ${
                    prefs.eyeColor === k
                      ? "border-[hsl(var(--linguist-gold))] scale-110"
                      : "border-zinc-700 hover:border-zinc-500"
                  }`}
                  style={{
                    background: `radial-gradient(circle at 35% 30%, ${EYE_COLORS[k].hex}, #0a0a0a 80%)`,
                    boxShadow: prefs.eyeColor === k ? `0 0 18px ${EYE_COLORS[k].hex}99` : "none",
                  }}
                  aria-label={EYE_COLORS[k].label}
                  title={EYE_COLORS[k].label}
                />
              ))}
            </div>
          </div>

          {/* Camera angle */}
          <div>
            <label className="text-xs uppercase tracking-wider text-zinc-400 mb-2 block">Kamera Açısı</label>
            <div className="grid grid-cols-4 gap-2">
              {(Object.keys(CAMERA_ANGLES) as CameraAngleKey[]).map((k) => (
                <button
                  key={k}
                  type="button"
                  onClick={() => onChange({ cameraAngle: k })}
                  className={`py-2 rounded-md border text-[11px] font-semibold transition-all ${
                    prefs.cameraAngle === k
                      ? "border-[hsl(var(--linguist-gold))] bg-[hsl(var(--linguist-gold))]/10 text-[hsl(var(--linguist-gold))]"
                      : "border-zinc-800 text-zinc-400 hover:border-zinc-600"
                  }`}
                >
                  {CAMERA_ANGLES[k].label}
                </button>
              ))}
            </div>
          </div>

          <Button
            variant="outline"
            size="sm"
            onClick={onReset}
            className="w-full border-zinc-700 text-zinc-300"
          >
            <RotateCcw className="w-3 h-3 mr-1.5" /> Varsayılana dön
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  );
}

