/**
 * SovereignBridgeCard — 5 "köprü kelime" of the day.
 * One swipeable card that flips between native and target language with a tap.
 * Pure client logic — zero API calls.
 */
import { useMemo, useState } from "react";
import { Card } from "@/components/ui/card";
import { Volume2, ChevronRight, ChevronLeft, Sparkles } from "lucide-react";
import { todayBridge } from "@/data/linguistBridge";
import type { Language } from "@/data/linguistContent";

const TTS: Record<Language, string> = {
  tr: "tr-TR", ku: "tr-TR", en: "en-US", nl: "nl-NL", ar: "ar-SA",
};

interface Props {
  native: Language;
  target: Language;
}

export function SovereignBridgeCard({ native, target }: Props) {
  const words = useMemo(() => todayBridge(), []);
  const [idx, setIdx] = useState(0);
  const [showTarget, setShowTarget] = useState(true);
  const w = words[idx];

  const speak = (text: string, lang: Language) => {
    try {
      const synth = window.speechSynthesis;
      if (!synth) return;
      synth.cancel();
      const u = new SpeechSynthesisUtterance(text);
      u.lang = TTS[lang];
      u.rate = 0.9;
      synth.speak(u);
    } catch { /* ignore */ }
  };

  const front = showTarget ? w.text[target] : w.text[native];
  const back = showTarget ? w.text[native] : w.text[target];
  const frontLang: Language = showTarget ? target : native;
  const backLang: Language = showTarget ? native : target;

  return (
    <Card className="bg-zinc-950 border border-[hsl(var(--linguist-gold))]/30 p-4 space-y-3">
      <div className="flex items-center gap-2">
        <Sparkles className="w-4 h-4 text-[hsl(var(--linguist-gold))]" />
        <span className="text-sm font-semibold text-zinc-200">Sovereign Bridge</span>
        <span className="ml-auto text-[10px] text-zinc-500">
          {idx + 1} / {words.length} · bugün
        </span>
      </div>

      <button
        type="button"
        onClick={() => setShowTarget((v) => !v)}
        className="relative w-full rounded-2xl border-2 border-[hsl(var(--linguist-gold))]/30 bg-gradient-to-br from-zinc-900 via-black to-zinc-900 p-6 text-center min-h-[140px] active:scale-[0.99] transition-transform"
        aria-label="Çevir"
      >
        <div className="text-[10px] uppercase tracking-[0.25em] text-zinc-500 mb-1">
          {frontLang.toUpperCase()}
        </div>
        <div
          className="text-3xl font-bold text-[hsl(var(--linguist-gold))] break-words"
          dir={frontLang === "ar" ? "rtl" : "ltr"}
        >
          {front}
        </div>
        <div className="mt-3 pt-3 border-t border-zinc-800 text-[11px] text-zinc-500">
          <span className="opacity-60 mr-1">{backLang.toUpperCase()}:</span>
          <span dir={backLang === "ar" ? "rtl" : "ltr"}>{back}</span>
        </div>
        {w.hint && (
          <div className="mt-2 text-[10px] text-[hsl(var(--linguist-purple))] italic">
            {w.hint}
          </div>
        )}
        <div className="absolute bottom-2 right-2 flex gap-1">
          <span
            role="button"
            onClick={(e) => { e.stopPropagation(); speak(front, frontLang); }}
            className="w-7 h-7 grid place-items-center rounded-full bg-black/60 border border-zinc-700 text-zinc-400 hover:text-[hsl(var(--linguist-gold))]"
          >
            <Volume2 className="w-3 h-3" />
          </span>
        </div>
      </button>

      <div className="flex items-center justify-between">
        <button
          type="button"
          onClick={() => setIdx((i) => (i - 1 + words.length) % words.length)}
          className="h-9 px-3 rounded-lg border border-zinc-800 text-zinc-400 hover:border-zinc-600 flex items-center gap-1 text-xs"
        >
          <ChevronLeft className="w-3.5 h-3.5" /> Önceki
        </button>
        <div className="flex gap-1">
          {words.map((_, i) => (
            <span
              key={i}
              className={`w-1.5 h-1.5 rounded-full transition-all ${
                i === idx ? "bg-[hsl(var(--linguist-gold))] w-4" : "bg-zinc-700"
              }`}
            />
          ))}
        </div>
        <button
          type="button"
          onClick={() => setIdx((i) => (i + 1) % words.length)}
          className="h-9 px-3 rounded-lg border border-[hsl(var(--linguist-gold))]/40 text-[hsl(var(--linguist-gold))] hover:bg-[hsl(var(--linguist-gold))]/10 flex items-center gap-1 text-xs font-semibold"
        >
          Sonraki <ChevronRight className="w-3.5 h-3.5" />
        </button>
      </div>

      <p className="text-[10px] text-zinc-600 text-center">
        💡 Karta dokunarak {native.toUpperCase()} ↔ {target.toUpperCase()} arası çevir.
      </p>
    </Card>
  );
}

