/**
 * StorySeedCard — Pick 1 word, Deng AI generates a 3-sentence micro-story
 * in the target language. Local archive in localStorage.
 */
import { useEffect, useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Sprout, Volume2, BookmarkPlus, Loader2 } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import type { Language } from "@/data/linguistContent";
import { todayBridge } from "@/data/linguistBridge";

const TTS: Record<Language, string> = {
  tr: "tr-TR", ku: "tr-TR", en: "en-US", nl: "nl-NL", ar: "ar-SA",
};

const LANG_NAMES: Record<Language, string> = {
  tr: "Turkish", ku: "Kurmanji", nl: "Dutch", en: "English", ar: "Arabic",
};

interface SeedEntry {
  word: string;
  story: string;
  date: string;
  lang: Language;
}

const ARCHIVE_KEY = "linguist:storyseed:v1";

interface Props {
  target: Language;
}

export function StorySeedCard({ target }: Props) {
  const [seed, setSeed] = useState<string>("");
  const [story, setStory] = useState<string>("");
  const [busy, setBusy] = useState(false);
  const [archive, setArchive] = useState<SeedEntry[]>([]);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(ARCHIVE_KEY);
      if (raw) setArchive(JSON.parse(raw));
    } catch { /* ignore */ }
    // Suggest today's first bridge word in target language
    const w = todayBridge()[0];
    setSeed(w.text[target]);
  }, [target]);

  const speak = (text: string) => {
    try {
      const synth = window.speechSynthesis;
      if (!synth) return;
      synth.cancel();
      const u = new SpeechSynthesisUtterance(text);
      u.lang = TTS[target];
      u.rate = 0.9;
      synth.speak(u);
    } catch { /* ignore */ }
  };

  const generate = async () => {
    if (!seed.trim()) return;
    setBusy(true);
    setStory("");
    try {
      const prompt = `You are Deng, a sovereign Kurdish AI storyteller.
Write EXACTLY 3 short sentences in ${LANG_NAMES[target]} using the seed word "${seed}".
Tone: warm, simple, A1-A2 level. No preamble. Plain text only.`;
      const { data } = await supabase.functions.invoke("jiyan-ai-chat", {
        body: { messages: [{ role: "user", content: prompt }], stream: false },
      });
      const reply: string =
        (data && (data.reply || data.message || data.content || data.answer)) || "";
      const clean = (reply || "").trim().slice(0, 600);
      if (!clean) {
        toast.error("Hikâye üretilemedi, tekrar dene.");
      } else {
        setStory(clean);
      }
    } catch (e) {
      console.error(e);
      toast.error("Servis meşgul.");
    } finally {
      setBusy(false);
    }
  };

  const save = () => {
    if (!story.trim()) return;
    const entry: SeedEntry = {
      word: seed,
      story,
      date: new Date().toISOString().slice(0, 10),
      lang: target,
    };
    const next = [entry, ...archive].slice(0, 30);
    setArchive(next);
    try { localStorage.setItem(ARCHIVE_KEY, JSON.stringify(next)); } catch { /* ignore */ }
    toast.success("📖 Hikâye arşivine eklendi");
  };

  return (
    <Card className="bg-zinc-950 border border-[hsl(var(--linguist-purple))]/30 p-4 space-y-3">
      <div className="flex items-center gap-2">
        <Sprout className="w-4 h-4 text-[hsl(var(--linguist-purple))]" />
        <span className="text-sm font-semibold text-zinc-200">Story Seed</span>
        <span className="ml-auto text-[10px] text-zinc-500">
          {archive.length} hikâye arşivde
        </span>
      </div>

      <div className="flex gap-2">
        <input
          value={seed}
          onChange={(e) => setSeed(e.target.value)}
          placeholder={`${target.toUpperCase()} kelime...`}
          className="flex-1 bg-black border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white outline-none focus:border-[hsl(var(--linguist-purple))]"
          dir={target === "ar" ? "rtl" : "ltr"}
        />
        <Button
          type="button"
          onClick={generate}
          disabled={busy || !seed.trim()}
          className="bg-[hsl(var(--linguist-purple))] text-white hover:bg-[hsl(var(--linguist-purple))]/90"
        >
          {busy ? <Loader2 className="w-4 h-4 animate-spin" /> : "Filizlen"}
        </Button>
      </div>

      {story && (
        <div className="rounded-xl border border-[hsl(var(--linguist-purple))]/30 bg-black p-4 space-y-2">
          <p
            className="text-sm leading-relaxed text-zinc-200 whitespace-pre-wrap"
            dir={target === "ar" ? "rtl" : "ltr"}
          >
            {story}
          </p>
          <div className="flex items-center gap-2 pt-1 border-t border-zinc-800">
            <button
              type="button"
              onClick={() => speak(story)}
              className="text-[11px] text-zinc-400 hover:text-[hsl(var(--linguist-gold))] flex items-center gap-1"
            >
              <Volume2 className="w-3 h-3" /> Dinle
            </button>
            <button
              type="button"
              onClick={save}
              className="ml-auto text-[11px] text-[hsl(var(--linguist-purple))] hover:text-[hsl(var(--linguist-gold))] flex items-center gap-1"
            >
              <BookmarkPlus className="w-3 h-3" /> Arşivle
            </button>
          </div>
        </div>
      )}

      {archive.length > 0 && (
        <details className="rounded-lg border border-zinc-800 bg-zinc-950">
          <summary className="cursor-pointer px-3 py-2 text-[11px] text-zinc-400 select-none">
            📚 Arşiv ({archive.length})
          </summary>
          <div className="px-3 pb-3 space-y-1.5 max-h-48 overflow-y-auto">
            {archive.map((e, i) => (
              <div key={i} className="text-[11px] text-zinc-400 border-b border-zinc-900 pb-1.5">
                <div className="text-[hsl(var(--linguist-gold))] font-semibold">
                  {e.word} <span className="text-zinc-600 text-[9px]">· {e.date} · {e.lang}</span>
                </div>
                <div dir={e.lang === "ar" ? "rtl" : "ltr"}>{e.story}</div>
              </div>
            ))}
          </div>
        </details>
      )}
    </Card>
  );
}

