import type { StudySession } from "@/hooks/useLinguistAcademy";

interface Props {
  sessions: StudySession[];
  goal: number;
}

const DAY_LABELS = ["Pzt", "Sal", "Çar", "Per", "Cum", "Cmt", "Paz"];

export function WeeklyChart({ sessions, goal }: Props) {
  // Build last-7-days array (oldest → newest)
  const today = new Date();
  const days: { date: string; minutes: number; goalReached: boolean; label: string; isToday: boolean }[] = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    const iso = d.toISOString().slice(0, 10);
    const session = sessions.find((s) => s.session_date === iso);
    // JS getDay: 0=Sun..6=Sat → map to Mon-first
    const jsDay = d.getDay();
    const idx = jsDay === 0 ? 6 : jsDay - 1;
    days.push({
      date: iso,
      minutes: session?.minutes_studied ?? 0,
      goalReached: session?.goal_reached ?? false,
      label: DAY_LABELS[idx],
      isToday: i === 0,
    });
  }

  const max = Math.max(goal, ...days.map((d) => d.minutes), 10);

  return (
    <div className="w-full">
      <div className="flex items-end justify-between gap-2 h-40 px-1">
        {days.map((d) => {
          const heightPct = (d.minutes / max) * 100;
          const goalLineY = (goal / max) * 100;
          return (
            <div key={d.date} className="flex-1 flex flex-col items-center gap-1.5 h-full justify-end relative">
              {/* Goal line indicator (rendered behind bars) */}
              <div
                className="absolute left-0 right-0 border-t border-dashed border-[#FFD700]/30"
                style={{ bottom: `${goalLineY + 24}%` }}
                aria-hidden
              />
              <div className="text-[9px] text-zinc-500 tabular-nums h-3">
                {d.minutes > 0 ? d.minutes : ""}
              </div>
              <div
                className={`w-full rounded-t-md transition-all duration-500 ${
                  d.goalReached
                    ? "bg-gradient-to-t from-[#FFD700] to-[#9B59B6] shadow-[0_0_12px_rgba(255,215,0,0.4)]"
                    : d.minutes > 0
                    ? "bg-gradient-to-t from-zinc-700 to-zinc-500"
                    : "bg-zinc-900"
                }`}
                style={{ height: `${Math.max(2, heightPct)}%` }}
              />
              <div className={`text-[10px] font-semibold ${d.isToday ? "text-[#FFD700]" : "text-zinc-500"}`}>
                {d.label}
              </div>
            </div>
          );
        })}
      </div>
      <div className="flex items-center justify-between mt-3 text-[10px] text-zinc-500">
        <span className="flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-sm bg-gradient-to-br from-[#FFD700] to-[#9B59B6]" /> Hedef tamamlandı
        </span>
        <span className="text-[#FFD700]/70">- - - {goal} dk hedef</span>
      </div>
    </div>
  );
}

