/**
 * WhisperStreakCard — silent / on-the-go practice mode.
 * Shows ONE word at a time on a black canvas, whispered via TTS at low volume.
 * Auto-advances every 6s; user can pause/resume. Vibrates briefly between words
 * (when supported) so it works as a discreet commute companion.
 */
import { useEffect, useRef, useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { EarOff, Play, Pause, X } from "lucide-react";
import { todayBridge, BRIDGE_BANK } from "@/data/linguistBridge";
import type { Language } from "@/data/linguistContent";

const TTS: Record<Language, string> = {
  tr: "tr-TR", ku: "tr-TR", en: "en-US", nl: "nl-NL", ar: "ar-SA",
};

interface Props {
  native: Language;
  target: Language;
}

export function WhisperStreakCard({ native, target }: Props) {
  const [active, setActive] = useState(false);
  const [paused, setPaused] = useState(false);
  const [idx, setIdx] = useState(0);
  // 5 today + 5 random extras → 10-card whisper loop
  const wordsRef = useRef(
    [...todayBridge(0, 5), ...todayBridge(7, 5)].slice(0, 10),
  );
  const tickRef = useRef<number | null>(null);

  const w = wordsRef.current[idx % wordsRef.current.length];

  useEffect(() => {
    if (!active || paused) {
      if (tickRef.current) window.clearInterval(tickRef.current);
      tickRef.current = null;
      return;
    }
    // Speak now, then advance every 6s
    const speak = () => {
      try {
        const synth = window.speechSynthesis;
        if (!synth) return;
        synth.cancel();
        const u = new SpeechSynthesisUtterance(w.text[target]);
        u.lang = TTS[target];
        u.volume = 0.45; // whisper
        u.rate = 0.85;
        synth.speak(u);
      } catch { /* ignore */ }
      try { (navigator as any).vibrate?.(30); } catch { /* ignore */ }
    };
    speak();
    tickRef.current = window.setInterval(() => {
      setIdx((i) => i + 1);
    }, 6000);
    return () => {
      if (tickRef.current) window.clearInterval(tickRef.current);
    };
  }, [active, paused, idx, target, w]);

  // Stop TTS when leaving the mode
  useEffect(() => {
    if (!active) {
      try { window.speechSynthesis?.cancel(); } catch { /* ignore */ }
    }
    return () => {
      try { window.speechSynthesis?.cancel(); } catch { /* ignore */ }
    };
  }, [active]);

  if (!active) {
    return (
      <Card className="bg-zinc-950 border border-zinc-800 p-4 space-y-2">
        <div className="flex items-center gap-2">
          <EarOff className="w-4 h-4 text-zinc-400" />
          <span className="text-sm font-semibold text-zinc-200">Whisper Streak</span>
        </div>
        <p className="text-[11px] text-zinc-500 leading-relaxed">
          Sessiz mod — kulaklığını tak, ekran tek kelime gösterir, Deng fısıldar.
          Toplu taşıma, yürüyüş ya da iş arası için.
        </p>
        <Button
          type="button"
          onClick={() => { setActive(true); setIdx(0); setPaused(false); }}
          className="w-full bg-zinc-800 text-white hover:bg-zinc-700"
        >
          <Play className="w-4 h-4 mr-1.5" /> Başlat ({wordsRef.current.length} kelime)
        </Button>
      </Card>
    );
  }

  // Active full-card minimalist view
  return (
    <Card className="bg-black border border-[hsl(var(--linguist-gold))]/20 p-0 overflow-hidden">
      <div className="relative min-h-[220px] flex flex-col items-center justify-center px-6 py-10">
        <button
          type="button"
          onClick={() => setActive(false)}
          aria-label="Çık"
          className="absolute top-2 right-2 w-8 h-8 grid place-items-center rounded-full bg-zinc-900/80 border border-zinc-800 text-zinc-400 hover:text-white"
        >
          <X className="w-3.5 h-3.5" />
        </button>

        <div className="text-[10px] uppercase tracking-[0.3em] text-zinc-600 mb-3">
          {target.toUpperCase()}
        </div>
        <div
          className="text-4xl font-bold text-[hsl(var(--linguist-gold))] text-center break-words"
          dir={target === "ar" ? "rtl" : "ltr"}
        >
          {w.text[target]}
        </div>
        <div
          className="mt-3 text-xs text-zinc-500 text-center"
          dir={native === "ar" ? "rtl" : "ltr"}
        >
          {w.text[native]}
        </div>

        <div className="mt-6 flex items-center gap-3">
          <button
            type="button"
            onClick={() => setPaused((p) => !p)}
            className="w-10 h-10 grid place-items-center rounded-full bg-zinc-900 border border-zinc-700 text-zinc-200"
            aria-label={paused ? "Devam" : "Duraklat"}
          >
            {paused ? <Play className="w-4 h-4" /> : <Pause className="w-4 h-4" />}
          </button>
          <div className="text-[10px] text-zinc-600 tabular-nums">
            {(idx % wordsRef.current.length) + 1} / {wordsRef.current.length}
          </div>
        </div>

        <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-zinc-900">
          <div
            key={idx}
            className="h-full bg-[hsl(var(--linguist-gold))]"
            style={{
              animation: paused ? "none" : "whisper-bar 6s linear forwards",
              width: paused ? "0%" : "100%",
            }}
          />
        </div>
      </div>

      <style>{`@keyframes whisper-bar { from { width: 0% } to { width: 100% } }`}</style>
    </Card>
  );
}

// Re-export for tree-shake friendliness in case BRIDGE_BANK is unused above
export const __WHISPER_BANK_LEN = BRIDGE_BANK.length;

