/**
 * ComposeSheet — Apple-style premium compose bottom sheet.
 *
 * Auto-saves a draft every 2 s of inactivity (only after the user has typed
 * at least one of: recipient / subject / body). The draft id is reused on
 * subsequent saves so we never spam the table.
 */
import { useEffect, useRef, useState } from "react";
import { ArrowLeft, Send, Trash2, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

interface Props {
  initial?: { id?: string; recipient?: string; subject?: string; body?: string };
  onClose: () => void;
  onSend: (recipient: string, subject: string, body: string) => Promise<void>;
  onSaveDraft: (draft: {
    id?: string;
    recipient?: string;
    subject: string;
    body: string;
  }) => Promise<string>;
  onDiscardDraft?: (id: string) => Promise<void>;
}

export function ComposeSheet({
  initial,
  onClose,
  onSend,
  onSaveDraft,
  onDiscardDraft,
}: Props) {
  const [recipient, setRecipient] = useState(initial?.recipient ?? "");
  const [subject, setSubject] = useState(initial?.subject ?? "");
  const [body, setBody] = useState(initial?.body ?? "");
  const [sending, setSending] = useState(false);
  const draftIdRef = useRef<string | undefined>(initial?.id);
  const dirtyRef = useRef(false);

  // Debounced auto-save — fires only when there's something worth saving.
  useEffect(() => {
    if (!dirtyRef.current) {
      dirtyRef.current = !!(recipient || subject || body);
      if (!dirtyRef.current) return;
    }
    if (!recipient && !subject && !body) return;
    const t = setTimeout(async () => {
      try {
        const id = await onSaveDraft({
          id: draftIdRef.current,
          recipient,
          subject,
          body,
        });
        draftIdRef.current = id;
      } catch {
        /* silent — surfaced on send */
      }
    }, 2000);
    return () => clearTimeout(t);
  }, [recipient, subject, body, onSaveDraft]);

  const handleSend = async () => {
    if (!recipient.trim() || !body.trim()) {
      toast.error("Alıcı ve mesaj zorunlu");
      return;
    }
    setSending(true);
    try {
      await onSend(recipient.trim(), subject.trim() || "(Konusuz)", body.trim());
      // If the draft was saved, remove it now that it's actually sent.
      if (draftIdRef.current && onDiscardDraft) {
        try {
          await onDiscardDraft(draftIdRef.current);
        } catch {
          /* ignore */
        }
      }
      toast.success("Mesaj gönderildi");
      onClose();
    } catch (e: any) {
      toast.error(e?.message ?? "Gönderilemedi");
    } finally {
      setSending(false);
    }
  };

  const handleDiscard = async () => {
    if (draftIdRef.current && onDiscardDraft) {
      try {
        await onDiscardDraft(draftIdRef.current);
        toast.success("Taslak silindi");
      } catch {
        /* ignore */
      }
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-background/95 backdrop-blur-xl">
      {/* Top bar */}
      <div className="flex items-center justify-between border-b border-amber-400/10 px-4 py-3">
        <button
          onClick={onClose}
          className="flex items-center gap-2 text-muted-foreground"
          aria-label="Geri"
        >
          <ArrowLeft className="h-5 w-5" />
        </button>
        <h2 className="text-sm font-semibold tracking-wide text-foreground">
          Yeni Mesaj
        </h2>
        <Button
          size="sm"
          onClick={handleSend}
          disabled={sending || !recipient.trim() || !body.trim()}
          className="bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-500 font-semibold text-black shadow-[0_2px_14px_rgba(245,200,80,0.35)]"
        >
          <Send className="mr-1 h-3.5 w-3.5" />
          {sending ? "..." : "Gönder"}
        </Button>
      </div>

      {/* Body */}
      <div className="flex-1 space-y-4 overflow-y-auto p-4">
        <Field label="Alıcı">
          <input
            value={recipient}
            onChange={(e) => setRecipient(e.target.value)}
            placeholder="@kullaniciadi  •  +777 1234 5678"
            inputMode="email"
            className="h-11 w-full rounded-xl border border-border bg-surface px-4 text-sm text-foreground placeholder:text-muted-foreground focus:border-amber-400/60 focus:outline-none"
          />
        </Field>
        <Field label="Konu">
          <input
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            placeholder="İsteğe bağlı"
            className="h-11 w-full rounded-xl border border-border bg-surface px-4 text-sm text-foreground placeholder:text-muted-foreground focus:border-amber-400/60 focus:outline-none"
          />
        </Field>
        <Field label="Mesaj">
          <textarea
            value={body}
            onChange={(e) => setBody(e.target.value)}
            placeholder="Mesajınızı yazın..."
            rows={10}
            className="w-full resize-none rounded-xl border border-border bg-surface px-4 py-3 text-sm leading-relaxed text-foreground placeholder:text-muted-foreground focus:border-amber-400/60 focus:outline-none"
          />
        </Field>

        <div className="flex items-center justify-between pt-2">
          <p className="flex items-center gap-1.5 text-[11px] text-amber-200/60">
            <Sparkles className="h-3 w-3" />
            Otomatik taslak — yazıldıkça kaydediliyor
          </p>
          <button
            onClick={handleDiscard}
            className="inline-flex items-center gap-1 text-[12px] text-muted-foreground hover:text-destructive"
          >
            <Trash2 className="h-3.5 w-3.5" /> Taslağı sil
          </button>
        </div>
      </div>
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <label className="mb-1 block text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
        {label}
      </label>
      {children}
    </div>
  );
}

