/**
 * MailSidebar — Apple-style folder rail.
 *
 * Horizontal pill scroller on mobile (≤ md) so it works on the 430px
 * viewport without stealing screen real-estate, vertical list on tablet+.
 */
import {
  Inbox,
  Star,
  Send,
  FileEdit,
  ShieldCheck,
  Archive,
  Trash2,
} from "lucide-react";
import type { MailFolder } from "@/hooks/useMail";

interface FolderDef {
  key: MailFolder;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
}

const FOLDERS: FolderDef[] = [
  { key: "inbox", label: "Gelen", icon: Inbox },
  { key: "starred", label: "Yıldızlı", icon: Star },
  { key: "sent", label: "Gönderilen", icon: Send },
  { key: "drafts", label: "Taslaklar", icon: FileEdit },
  { key: "system", label: "Sistem", icon: ShieldCheck },
  { key: "archived", label: "Arşiv", icon: Archive },
  { key: "trash", label: "Çöp", icon: Trash2 },
];

interface Props {
  active: MailFolder;
  onChange: (f: MailFolder) => void;
  badges: Partial<Record<MailFolder, number>>;
}

export function MailSidebar({ active, onChange, badges }: Props) {
  return (
    <nav
      className="-mx-4 flex gap-2 overflow-x-auto px-4 pb-2 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      aria-label="Mail klasörleri"
    >
      {FOLDERS.map(({ key, label, icon: Icon }) => {
        const isActive = active === key;
        const badge = badges[key] ?? 0;
        const isSystem = key === "system";
        return (
          <button
            key={key}
            onClick={() => onChange(key)}
            className={[
              "group relative flex shrink-0 items-center gap-1.5 rounded-full px-3.5 py-1.5 text-xs font-medium transition-all",
              isActive
                ? isSystem
                  ? "bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-500 text-black shadow-[0_2px_14px_rgba(245,200,80,0.45)]"
                  : "bg-foreground text-background shadow-[0_2px_10px_rgba(0,0,0,0.3)]"
                : "bg-surface text-muted-foreground hover:text-foreground",
            ].join(" ")}
            aria-pressed={isActive}
          >
            <Icon className="h-3.5 w-3.5" />
            <span>{label}</span>
            {badge > 0 && (
              <span
                className={[
                  "ml-0.5 inline-flex h-4 min-w-4 items-center justify-center rounded-full px-1 text-[10px] font-bold",
                  isActive
                    ? "bg-background/20 text-current"
                    : isSystem
                    ? "bg-amber-400 text-black"
                    : "bg-neon text-neon-foreground",
                ].join(" ")}
              >
                {badge > 99 ? "99+" : badge}
              </span>
            )}
          </button>
        );
      })}
    </nav>
  );
}

/**
 * SovereignMailSheet — Gmail-style Mail Mini-App as a half-modal sheet.
 *
 * Lives INSIDE the Hub (no navigation). Spring physics on open/close,
 * swipe-down to dismiss, frosted black-gold glassmorphism background.
 *
 * Three internal modes:
 *   • "auth"     — guest/logged-out: Oturum Aç + Hesap Oluştur tabs +
 *                  "Şifremi Unuttum" → Yaşam Anahtarı (24-word) recovery.
 *   • "inbox"    — Gmail-style minimalist list with sender avatars,
 *                  unread bold + neon dot, pull-to-compose FAB.
 *   • "compose"  — slide-up Compose pane on top of the inbox.
 *
 * Persistence: once authenticated, the sheet stays "warm" — closing it just
 * hides the surface. The realtime mail subscription (useMail) keeps the
 * inbox up to date in the background of the Hub.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useMail, type MailMessage } from "@/hooks/useMail";
import { useSovereignProfile } from "@/hooks/useSovereignProfile";
import { SovereignRecoveryFlow } from "@/components/settings/SovereignRecoveryFlow";
import { ComposeSheet } from "@/components/mail/ComposeSheet";
import { TGSheet } from "@/components/sovereign/TGSheet";
import { hapticTap } from "@/lib/native";
import { toast } from "sonner";
import {
  ArrowLeft,
  CheckCheck,
  Inbox as InboxIcon,
  Loader2,
  Mail,
  Pencil,
  Search,
  Shield,
  ShieldCheck,
  Star,
  StarOff,
  Trash2,
  X,
} from "lucide-react";

interface Props {
  open: boolean;
  onClose: () => void;
}

type AuthTab = "signin" | "signup" | "recover";

export function SovereignMailSheet({ open, onClose }: Props) {
  const { user, signIn, signUp } = useAuth();
  const { data: profile } = useSovereignProfile(user?.id);
  const mail = useMail(user?.id);

  // ─── swipe-down to dismiss ─────────────────────────────────────
  const sheetRef = useRef<HTMLDivElement | null>(null);
  const dragStartY = useRef<number | null>(null);
  const [dragY, setDragY] = useState(0);

  const onTouchStart = (e: React.TouchEvent) => {
    if (!sheetRef.current) return;
    // Only initiate drag from the grabber zone (top 60px).
    const rect = sheetRef.current.getBoundingClientRect();
    if (e.touches[0].clientY - rect.top > 60) return;
    dragStartY.current = e.touches[0].clientY;
  };
  const onTouchMove = (e: React.TouchEvent) => {
    if (dragStartY.current == null) return;
    const dy = e.touches[0].clientY - dragStartY.current;
    if (dy > 0) setDragY(dy);
  };
  const onTouchEnd = () => {
    if (dragStartY.current == null) return;
    if (dragY > 110) {
      hapticTap();
      onClose();
    }
    dragStartY.current = null;
    setDragY(0);
  };

  // ESC closes
  useEffect(() => {
    if (!open) return;
    const onEsc = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    document.addEventListener("keydown", onEsc);
    return () => document.removeEventListener("keydown", onEsc);
  }, [open, onClose]);

  // Internal view (only relevant when authenticated)
  const [openId, setOpenId] = useState<string | null>(null);
  const [composeOpen, setComposeOpen] = useState(false);
  const [query, setQuery] = useState("");

  const inboxList = useMemo(() => {
    if (!user) return [] as MailMessage[];
    const base = mail.filterFolder("inbox");
    if (!query.trim()) return base;
    const q = query.toLowerCase();
    return base.filter(
      (m) => m.subject.toLowerCase().includes(q) || m.body.toLowerCase().includes(q),
    );
  }, [mail, user, query]);

  const openMsg = openId ? mail.messages.find((m) => m.id === openId) ?? null : null;

  if (!open) return null;

  return (
    <>
      <TGSheet open={open} onClose={onClose} title="Mail" height={1}>
        <div ref={sheetRef} className="relative flex flex-col h-full">
          {!user ? (
            <MailAuthPanel onSignIn={signIn} onSignUp={signUp} />
          ) : openMsg ? (
            <MessageDetail
              m={openMsg}
              ownerId={user.id}
              onBack={() => setOpenId(null)}
              onStar={() => mail.toggleStar(openMsg)}
              onArchive={() => {
                mail.archive(openMsg.id);
                setOpenId(null);
              }}
              onTrash={() => {
                mail.trash(openMsg.id);
                setOpenId(null);
              }}
            />
          ) : (
            <InboxView
              query={query}
              onQuery={setQuery}
              loading={mail.loading}
              messages={inboxList}
              ownerId={user.id}
              ownerAvatar={profile?.avatarUrl ?? null}
              ownerName={profile?.displayName ?? user.email ?? null}
              unreadCount={mail.counts.inboxUnread}
              onOpen={(m) => {
                setOpenId(m.id);
                if (!m.is_read) mail.markAsRead(m.id);
              }}
              onStar={(m) => mail.toggleStar(m)}
              onTrash={(m) => mail.trash(m.id)}
              onMarkAllRead={mail.markAllInboxRead}
            />
          )}

          {/* Compose FAB — only when authenticated and not viewing a message */}
          {user && !openMsg && (
            <button
              type="button"
              onClick={() => {
                hapticTap();
                setComposeOpen(true);
              }}
              aria-label="Yeni mesaj"
              className="fixed bottom-8 right-5 z-[1100] flex h-14 w-14 items-center justify-center rounded-full active:scale-95 transition-transform"
              style={{
                background: "linear-gradient(180deg, #F5CD53 0%, #C99A2A 100%)",
                boxShadow:
                  "0 12px 28px -6px rgba(245,205,83,0.55), inset 0 1px 0 rgba(255,236,180,0.65), inset 0 -2px 0 rgba(120,80,10,0.5)",
                color: "#0A0700",
              }}
            >
              <Pencil className="h-5 w-5" strokeWidth={2.4} />
            </button>
          )}
        </div>
      </TGSheet>

      {/* Compose layered above the sheet */}
      {user && composeOpen && (
        <ComposeSheet
          initial={{}}
          onClose={() => setComposeOpen(false)}
          onSend={async (r, s, b) => {
            await mail.send(r, s, b);
            hapticTap();
            toast.success("Gönderildi");
          }}
          onSaveDraft={(d) => mail.saveDraft(d)}
          onDiscardDraft={(id) => mail.deletePermanent(id)}
        />
      )}
    </>
  );
}

// ────────────────────────────────────────────────────────── Auth Panel

function MailAuthPanel({
  onSignIn,
  onSignUp,
}: {
  onSignIn: (email: string, password: string) => Promise<unknown>;
  onSignUp: (email: string, password: string, displayName: string) => Promise<unknown>;
}) {
  const [tab, setTab] = useState<AuthTab>("signin");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [busy, setBusy] = useState(false);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    try {
      if (tab === "signin") {
        await onSignIn(email, password);
        hapticTap();
        toast.success("Hoş geldin");
      } else if (tab === "signup") {
        await onSignUp(email, password, displayName || email.split("@")[0]);
        hapticTap();
        toast.success("Hesap oluşturuldu", {
          description: "Doğrulama bağlantısı için e-postanı kontrol et.",
        });
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "İşlem başarısız";
      toast.error(msg);
    } finally {
      setBusy(false);
    }
  };

  if (tab === "recover") {
    return (
      <div className="px-5 pb-10 pt-2">
        <button
          type="button"
          onClick={() => setTab("signin")}
          className="mb-3 inline-flex items-center gap-1.5 text-[12px] text-amber-200/75"
        >
          <ArrowLeft className="h-3.5 w-3.5" /> Girişe Dön
        </button>
        <h3 className="text-[16px] font-semibold text-amber-100">
          Şifremi Unuttum
        </h3>
        <p className="mt-1 mb-4 text-[12px] text-amber-200/65 max-w-sm">
          Yaşam Anahtarı'nı (24 kelime) gir veya yedek e-posta üzerinden
          kurtarma bağlantısı al.
        </p>
        <SovereignRecoveryFlow />
      </div>
    );
  }

  return (
    <div className="px-5 pb-10 pt-1">
      {/* Tab switch */}
      <div
        className="mb-5 flex p-1 rounded-2xl"
        style={{
          background: "rgba(0,0,0,0.55)",
          border: "1px solid rgba(212,175,55,0.25)",
        }}
      >
        {(["signin", "signup"] as const).map((k) => (
          <button
            key={k}
            type="button"
            onClick={() => setTab(k)}
            className="flex-1 rounded-xl py-2 text-[12.5px] font-semibold transition-all"
            style={
              tab === k
                ? {
                    background:
                      "linear-gradient(180deg, #F5CD53 0%, #C99A2A 100%)",
                    color: "#0A0700",
                    boxShadow:
                      "inset 0 1px 0 rgba(255,236,180,0.6), 0 4px 12px -4px rgba(245,205,83,0.4)",
                  }
                : { color: "rgba(253,230,138,0.7)" }
            }
          >
            {k === "signin" ? "Oturum Aç" : "Hesap Oluştur"}
          </button>
        ))}
      </div>

      <form onSubmit={submit} className="space-y-3">
        {tab === "signup" && (
          <Field
            label="Görünen ad"
            value={displayName}
            onChange={setDisplayName}
            placeholder="Welat"
          />
        )}
        <Field
          label="E-posta"
          type="email"
          value={email}
          onChange={setEmail}
          placeholder="welat@jiyan.world"
          required
        />
        <Field
          label="Şifre"
          type="password"
          value={password}
          onChange={setPassword}
          placeholder="••••••••"
          required
          minLength={8}
        />

        <button
          type="submit"
          disabled={busy}
          className="mt-2 flex w-full items-center justify-center gap-2 rounded-2xl py-3 text-[13px] font-semibold active:scale-[0.99] transition-transform"
          style={{
            background:
              "linear-gradient(180deg, #F5CD53 0%, #C99A2A 100%)",
            color: "#0A0700",
            boxShadow:
              "inset 0 1px 0 rgba(255,236,180,0.65), inset 0 -2px 0 rgba(120,80,10,0.5), 0 10px 24px -8px rgba(245,205,83,0.45)",
            opacity: busy ? 0.7 : 1,
          }}
        >
          {busy ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : tab === "signin" ? (
            "Oturum Aç"
          ) : (
            "Hesap Oluştur · +777"
          )}
        </button>

        {tab === "signin" && (
          <button
            type="button"
            onClick={() => setTab("recover")}
            className="mt-1 block w-full text-center text-[12px] text-amber-200/75 underline-offset-4 hover:underline"
          >
            Şifremi Unuttum · Yaşam Anahtarı ile Aç
          </button>
        )}

        <p className="mt-3 text-center text-[10.5px] text-amber-200/50">
          +777 Sovereign Identity · Google · Apple · E-posta hepsi tek kimliğe
          bağlanır.
        </p>
      </form>
    </div>
  );
}

function Field({
  label,
  value,
  onChange,
  type = "text",
  placeholder,
  required,
  minLength,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: string;
  placeholder?: string;
  required?: boolean;
  minLength?: number;
}) {
  return (
    <label className="block">
      <span className="mb-1 block text-[10px] uppercase tracking-[0.22em] text-amber-200/55">
        {label}
      </span>
      <input
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        required={required}
        minLength={minLength}
        className="w-full rounded-xl px-3.5 py-2.5 text-[13.5px] text-amber-50 placeholder:text-amber-200/30 focus:outline-none"
        style={{
          background: "rgba(0,0,0,0.55)",
          border: "1px solid rgba(212,175,55,0.3)",
        }}
      />
    </label>
  );
}

// ──────────────────────────────────────────────────────── Inbox View

function InboxView({
  query,
  onQuery,
  loading,
  messages,
  ownerId,
  ownerAvatar,
  ownerName,
  unreadCount,
  onOpen,
  onStar,
  onTrash,
  onMarkAllRead,
}: {
  query: string;
  onQuery: (v: string) => void;
  loading: boolean;
  messages: MailMessage[];
  ownerId: string;
  ownerAvatar: string | null;
  ownerName: string | null;
  unreadCount: number;
  onOpen: (m: MailMessage) => void;
  onStar: (m: MailMessage) => void;
  onTrash: (m: MailMessage) => void;
  onMarkAllRead: () => void;
}) {
  return (
    <div className="px-5 pt-1 pb-24">
      {/* Owner row */}
      <div
        className="mb-4 flex items-center gap-3 rounded-2xl p-3"
        style={{
          background: "rgba(245,205,83,0.06)",
          border: "1px solid rgba(212,175,55,0.2)",
        }}
      >
        <Avatar src={ownerAvatar} name={ownerName ?? ""} size={40} />
        <div className="min-w-0 flex-1">
          <p className="truncate text-[13.5px] font-semibold text-amber-50">
            {ownerName ?? "Egemen"}
          </p>
          <p className="truncate text-[10.5px] uppercase tracking-[0.22em] text-amber-200/55">
            +777 · Persistent Session
          </p>
        </div>
        {unreadCount > 0 && (
          <button
            type="button"
            onClick={onMarkAllRead}
            className="flex items-center gap-1 text-[11px] text-amber-200/85"
          >
            <CheckCheck className="h-3.5 w-3.5" /> Hepsi
          </button>
        )}
      </div>

      {/* Search */}
      <div className="relative mb-3">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-amber-200/45" />
        <input
          value={query}
          onChange={(e) => onQuery(e.target.value)}
          placeholder="Mesajlarda ara…"
          className="h-10 w-full rounded-full pl-10 pr-3 text-[13px] text-amber-50 placeholder:text-amber-200/40 focus:outline-none"
          style={{
            background: "rgba(0,0,0,0.55)",
            border: "1px solid rgba(212,175,55,0.22)",
          }}
        />
      </div>

      {/* List */}
      {loading ? (
        <div className="py-14 text-center text-[12px] text-amber-200/55">
          <Loader2 className="mx-auto mb-2 h-5 w-5 animate-spin" />
          Yükleniyor…
        </div>
      ) : messages.length === 0 ? (
        <div className="py-14 text-center">
          <InboxIcon className="mx-auto mb-3 h-10 w-10 text-amber-200/25" />
          <p className="text-[13px] font-medium text-amber-100">
            Gelen kutusu temiz
          </p>
          <p className="text-[11.5px] text-amber-200/55">
            Yeni mesaj geldiğinde burada görünecek.
          </p>
        </div>
      ) : (
        <ul className="space-y-1">
          {messages.map((m) => (
            <MailRow
              key={m.id}
              m={m}
              ownerId={ownerId}
              onOpen={() => onOpen(m)}
              onStar={() => onStar(m)}
              onTrash={() => onTrash(m)}
            />
          ))}
        </ul>
      )}
    </div>
  );
}

function MailRow({
  m,
  ownerId,
  onOpen,
  onStar,
  onTrash,
}: {
  m: MailMessage;
  ownerId: string;
  onOpen: () => void;
  onStar: () => void;
  onTrash: () => void;
}) {
  const isSystem = m.message_type === "system" || m.message_type === "verification";
  const isOutgoing = m.sender_id === ownerId;
  const senderLabel = isSystem ? "Jiyan System" : isOutgoing ? "Sen" : "Kullanıcı";

  return (
    <li>
      <button
        type="button"
        onClick={onOpen}
        className="flex w-full items-start gap-3 rounded-2xl p-3 text-left transition-all active:scale-[0.99]"
        style={{
          background: m.is_read
            ? "rgba(0,0,0,0.35)"
            : "linear-gradient(180deg, rgba(245,205,83,0.08), rgba(0,0,0,0.4))",
          border: m.is_read
            ? "1px solid rgba(212,175,55,0.1)"
            : "1px solid rgba(212,175,55,0.32)",
        }}
      >
        {isSystem ? (
          <div
            className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-full"
            style={{
              background:
                "radial-gradient(120% 100% at 30% 30%, rgba(245,205,83,0.5), rgba(8,6,2,0.95) 70%)",
              border: "1px solid rgba(212,175,55,0.55)",
            }}
          >
            {m.message_type === "verification" ? (
              <Shield className="h-4 w-4 text-amber-100" />
            ) : (
              <ShieldCheck className="h-4 w-4 text-amber-100" />
            )}
          </div>
        ) : (
          <Avatar name={senderLabel} size={36} />
        )}

        <div className="min-w-0 flex-1">
          <div className="flex items-baseline gap-2">
            <p
              className={`truncate text-[13px] ${
                m.is_read ? "text-amber-100/85" : "font-semibold text-amber-50"
