import { useEffect, useRef } from "react";

/**
 * AmbientKaval — synthesises a low, breathy "kaval"-like ambient drone using
 * the Web Audio API. No external mp3 needed; runs entirely in the browser.
 *
 * The drone is a soft sine + slow LFO modulated triangle, fed through a low-pass
 * filter and very long reverb (convolution). Volume stays under -22 dBFS so it
 * sits beneath the TTS narration.
 *
 * Props:
 *   active — when true, fades the drone in; when false, fades it out and stops.
 *   gain   — peak gain (0..1), default 0.18
 */
interface Props {
  active: boolean;
  gain?: number;
}

export function AmbientKaval({ active, gain = 0.18 }: Props) {
  const ctxRef = useRef<AudioContext | null>(null);
  const masterRef = useRef<GainNode | null>(null);
  const sourcesRef = useRef<OscillatorNode[]>([]);

  useEffect(() => {
    // Lazy-init on first activation (browser requires user gesture)
    if (!active) {
      // Fade out + stop
      const ctx = ctxRef.current;
      const master = masterRef.current;
      if (ctx && master) {
        const now = ctx.currentTime;
        master.gain.cancelScheduledValues(now);
        master.gain.setValueAtTime(master.gain.value, now);
        master.gain.linearRampToValueAtTime(0.0001, now + 1.4);
      }
      return;
    }

    let cancelled = false;

    const start = async () => {
      try {
        if (!ctxRef.current) {
          const AC =
            window.AudioContext ||
            (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
          ctxRef.current = new AC();
        }
        const ctx = ctxRef.current!;
        if (ctx.state === "suspended") await ctx.resume();
        if (cancelled) return;

        // Build (or rebuild) the graph
        const master = ctx.createGain();
        master.gain.value = 0.0001;
        master.connect(ctx.destination);
        masterRef.current = master;

        // Low-pass filter — soft, breathy character
        const lp = ctx.createBiquadFilter();
        lp.type = "lowpass";
        lp.frequency.value = 900;
        lp.Q.value = 0.7;
        lp.connect(master);

        // Two detuned oscillators an octave apart (kaval-like fundamental)
        const baseFreq = 174.6; // F3 — low and earthy
        const o1 = ctx.createOscillator();
        o1.type = "sine";
        o1.frequency.value = baseFreq;
        const o2 = ctx.createOscillator();
        o2.type = "triangle";
        o2.frequency.value = baseFreq * 1.5; // perfect fifth
        o2.detune.value = -8;

        // Slow LFO on filter cutoff for "breath"
        const lfo = ctx.createOscillator();
        lfo.type = "sine";
        lfo.frequency.value = 0.18;
        const lfoGain = ctx.createGain();
        lfoGain.gain.value = 220;
        lfo.connect(lfoGain).connect(lp.frequency);

        // Mix oscillators
        const mix = ctx.createGain();
        mix.gain.value = 0.5;
        o1.connect(mix);
        o2.connect(mix);
        mix.connect(lp);

        o1.start();
        o2.start();
        lfo.start();
        sourcesRef.current = [o1, o2, lfo];

        // Fade in
        const now = ctx.currentTime;
        master.gain.cancelScheduledValues(now);
        master.gain.setValueAtTime(0.0001, now);
        master.gain.exponentialRampToValueAtTime(gain, now + 2.2);
      } catch (err) {
        console.warn("[AmbientKaval] init failed", err);
      }
    };

    void start();

    return () => {
      cancelled = true;
    };
  }, [active, gain]);

  // Final cleanup on unmount
  useEffect(() => {
    return () => {
      const ctx = ctxRef.current;
      sourcesRef.current.forEach((s) => {
        try {
          s.stop();
        } catch {
          // ignore
        }
      });
      sourcesRef.current = [];
      if (ctx && ctx.state !== "closed") {
        void ctx.close();
      }
      ctxRef.current = null;
      masterRef.current = null;
    };
  }, []);

  return null;
}

