import { useEffect, useRef } from "react";

/**
 * CircularWaveform — concentric golden waveform that pulses with TTS.
 * When `active` is true it animates with synthesised micro-rhythm.
 * When `playing` (audio element supplied), it can drive amplitude from
 * AnalyserNode. For browser SpeechSynthesis (no AudioElement), it falls
 * back to a procedural pulsing animation timed to natural speech cadence.
 */
interface Props {
  active: boolean;
  size?: number;
}

export function CircularWaveform({ active, size = 280 }: Props) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const rafRef = useRef<number | null>(null);
  const startRef = useRef<number>(performance.now());

  useEffect(() => {
    if (!active) {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
      const c = canvasRef.current;
      if (c) {
        const ctx = c.getContext("2d");
        ctx?.clearRect(0, 0, c.width, c.height);
      }
      return;
    }

    const c = canvasRef.current;
    if (!c) return;
    const ctx = c.getContext("2d");
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    c.width = size * dpr;
    c.height = size * dpr;
    ctx.scale(dpr, dpr);

    startRef.current = performance.now();

    const draw = () => {
      const t = (performance.now() - startRef.current) / 1000;
      const cx = size / 2;
      const cy = size / 2;
      ctx.clearRect(0, 0, size, size);

      // Outer glow
      const grad = ctx.createRadialGradient(cx, cy, 8, cx, cy, size / 2);
      grad.addColorStop(0, "rgba(255, 224, 138, 0.25)");
      grad.addColorStop(0.6, "rgba(212, 175, 55, 0.08)");
      grad.addColorStop(1, "rgba(0,0,0,0)");
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(cx, cy, size / 2, 0, Math.PI * 2);
      ctx.fill();

      // 4 concentric "ring waves" with phased amplitude
      const ringCount = 4;
      for (let r = 0; r < ringCount; r++) {
        const baseRadius = 38 + r * 28;
        const phase = t * (1 + r * 0.4) + r * 1.2;
        const breath = 0.55 + 0.45 * Math.sin(phase * 0.9);
        ctx.beginPath();
        for (let a = 0; a <= 360; a += 2) {
          const rad = (a * Math.PI) / 180;
          // Rhythmic radial modulation — kaval-like cadence
          const wob =
            Math.sin(rad * 6 + phase * 2.4) * 4 * breath +
            Math.sin(rad * 12 - phase * 1.6) * 2 * breath;
          const radius = baseRadius + wob;
          const x = cx + Math.cos(rad) * radius;
          const y = cy + Math.sin(rad) * radius;
          if (a === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.strokeStyle = `rgba(255, ${200 + r * 10}, ${100 + r * 30}, ${0.65 - r * 0.12})`;
        ctx.lineWidth = 1.4 - r * 0.2;
        ctx.shadowBlur = 12;
        ctx.shadowColor = "rgba(255, 200, 80, 0.55)";
        ctx.stroke();
      }
      ctx.shadowBlur = 0;

      // Center bright dot
      const pulse = 0.8 + 0.2 * Math.sin(t * 4);
      ctx.beginPath();
      ctx.arc(cx, cy, 6 * pulse, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(255, 232, 154, 0.95)";
      ctx.shadowBlur = 18;
      ctx.shadowColor = "rgba(255, 200, 80, 0.9)";
      ctx.fill();
      ctx.shadowBlur = 0;

      rafRef.current = requestAnimationFrame(draw);
    };
    rafRef.current = requestAnimationFrame(draw);

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    };
  }, [active, size]);

  return (
    <canvas
      ref={canvasRef}
      style={{ width: size, height: size }}
      className="pointer-events-none"
      aria-hidden="true"
    />
  );
}

