import { useEffect, useState } from "react";
import { Settings2, X, Vibrate, Waves } from "lucide-react";
import { useTranslation } from "react-i18next";

const STORAGE_KEY = "manifesto.soundscape.v1";

export interface SoundscapePrefs {
  intensity: number; // 0..1
  hapticEnabled: boolean;
}

const DEFAULTS: SoundscapePrefs = { intensity: 0.6, hapticEnabled: true };

export function loadSoundscapePrefs(): SoundscapePrefs {
  if (typeof window === "undefined") return DEFAULTS;
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return DEFAULTS;
    const parsed = JSON.parse(raw);
    return {
      intensity:
        typeof parsed.intensity === "number"
          ? Math.max(0, Math.min(1, parsed.intensity))
          : DEFAULTS.intensity,
      hapticEnabled:
        typeof parsed.hapticEnabled === "boolean"
          ? parsed.hapticEnabled
          : DEFAULTS.hapticEnabled,
    };
  } catch {
    return DEFAULTS;
  }
}

function persist(prefs: SoundscapePrefs) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
  } catch {
    /* ignore quota errors */
  }
}

interface Props {
  prefs: SoundscapePrefs;
  onChange: (next: SoundscapePrefs) => void;
}

/**
 * Floating settings dial for the manifesto soundscape — controls the reverb
 * + tembûr ambience intensity and the haptic feedback toggle. Persists to
 * localStorage.
 */
export function SoundscapeSettings({ prefs, onChange }: Props) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);

  const update = (next: SoundscapePrefs) => {
    persist(next);
    onChange(next);
  };

  // Close on Escape for keyboard users
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open]);

  return (
    <>
      <button
        onClick={() => setOpen((v) => !v)}
        aria-label={t("manifesto.soundscape.title", "Soundscape")}
        className={`fixed left-3 top-1/2 -translate-y-1/2 z-40 flex h-10 w-10 items-center justify-center rounded-full border transition-all ${
          open
            ? "border-amber-200 bg-amber-300/30 text-amber-50"
            : "border-amber-300/40 bg-black/55 text-amber-200 hover:bg-amber-300/15"
        }`}
      >
        <Settings2 className="h-4 w-4" />
      </button>

      {open && (
        <div
          role="dialog"
          aria-label={t("manifesto.soundscape.title", "Soundscape")}
          className="fixed left-3 top-1/2 -translate-y-1/2 z-40 w-[280px] max-w-[calc(100vw-24px)] translate-x-12 rounded-2xl border border-amber-300/30 bg-black/85 backdrop-blur-xl p-4 shadow-[0_20px_60px_-20px_rgba(212,175,55,0.5)]"
        >
          <div className="mb-3 flex items-center justify-between">
            <p className="text-[10px] font-black uppercase tracking-[0.3em] text-amber-300">
              {t("manifesto.soundscape.title", "Ses Atmosferi")}
            </p>
            <button
              onClick={() => setOpen(false)}
              aria-label="Close"
              className="text-amber-200/60 hover:text-amber-100"
            >
              <X className="h-4 w-4" />
            </button>
          </div>

          {/* Intensity */}
          <div className="mb-4">
            <label className="mb-2 flex items-center justify-between gap-2 text-[11px] font-bold uppercase tracking-widest text-amber-100">
