import { useEffect, useState } from "react";

interface Props {
  text: string;
  progress: number; // 0..1
  currentTime: number; // seconds
  duration: number; // seconds
  visible: boolean;
}

function fmt(sec: number): string {
  if (!Number.isFinite(sec) || sec < 0) sec = 0;
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${String(m).padStart(1, "0")}:${String(s).padStart(2, "0")}`;
}

/**
 * SubtitleStrip — fixed bottom caption + thin progress bar with elapsed and
 * remaining time. Renders nothing when invisible so it does not steal taps.
 */
export function SubtitleStrip({ text, progress, currentTime, duration, visible }: Props) {
  // Smoothly fade subtitle text when it changes — small CSS-only crossfade.
  const [shown, setShown] = useState(text);
  const [phase, setPhase] = useState<"in" | "out">("in");
  useEffect(() => {
    if (text === shown) return;
    setPhase("out");
    const id = window.setTimeout(() => {
      setShown(text);
      setPhase("in");
    }, 140);
    return () => window.clearTimeout(id);
  }, [text, shown]);

  if (!visible) return null;

  const remaining = Math.max(0, duration - currentTime);
  const pct = Math.max(0, Math.min(1, progress));

  return (
    <div
      aria-live="polite"
      className="pointer-events-none fixed inset-x-0 bottom-20 z-40 flex flex-col items-center px-4"
    >
      {/* Caption card */}
      <div className="w-full max-w-md rounded-2xl border border-amber-300/25 bg-black/75 backdrop-blur-xl px-4 py-3 shadow-[0_10px_30px_-10px_rgba(0,0,0,0.8)]">
        <p
          className={`text-center text-[14px] sm:text-[15px] leading-snug font-medium text-amber-50 transition-opacity duration-150 ${
            phase === "in" ? "opacity-100" : "opacity-0"
          }`}
          style={{ minHeight: "1.6em" }}
        >
          {shown || "…"}
        </p>

        {/* Progress bar + times */}
        <div className="mt-2.5 flex items-center gap-2">
          <span className="tabular-nums text-[10px] font-bold text-amber-200/70 w-9 text-right">
            {fmt(currentTime)}
          </span>
          <div className="relative h-1 flex-1 overflow-hidden rounded-full bg-amber-200/15">
            <div
              className="absolute left-0 top-0 h-full rounded-full bg-gradient-to-r from-amber-200 via-amber-300 to-amber-500 shadow-[0_0_8px_rgba(255,200,80,0.6)] transition-[width] duration-150 ease-linear"
              style={{ width: `${pct * 100}%` }}
            />
          </div>
          <span className="tabular-nums text-[10px] font-bold text-amber-200/70 w-10">
            -{fmt(remaining)}
          </span>
        </div>
      </div>
    </div>
  );
}

