import { useEffect, useRef } from "react";

/**
 * TemburAtmosphere — synthesises a soft tembûr (Kurdish long-necked lute) drone
 * and a faint, distant wind, then sums them into a hall reverb. Used UNDER
 * the dengbêj narration to evoke a vast cyber-temple.
 *
 * Pure Web Audio — no external assets. Auto fades in/out with `active`.
 */
interface Props {
  active: boolean;
  /** Peak gain (0..1). Default 0.22 — kept low so it sits beneath the voice. */
  gain?: number;
}

const TEMBUR_NOTES_HZ = [146.83, 220.0, 293.66]; // D3, A3, D4 — open tembûr-like drone
const PLUCK_INTERVAL_MS = 4200;

export function TemburAtmosphere({ active, gain = 0.22 }: Props) {
  const ctxRef = useRef<AudioContext | null>(null);
  const masterRef = useRef<GainNode | null>(null);
  const cleanupRef = useRef<(() => void) | null>(null);
  const pluckTimerRef = useRef<number | null>(null);

  useEffect(() => {
    if (!active) {
      const master = masterRef.current;
      const ctx = ctxRef.current;
      if (master && ctx) {
        const now = ctx.currentTime;
        master.gain.cancelScheduledValues(now);
        master.gain.setValueAtTime(master.gain.value, now);
        master.gain.linearRampToValueAtTime(0.0001, now + 1.2);
      }
      if (pluckTimerRef.current) {
        window.clearInterval(pluckTimerRef.current);
        pluckTimerRef.current = null;
      }
      return;
    }

    let cancelled = false;
    const start = async () => {
      try {
        if (!ctxRef.current) {
          const AC =
            window.AudioContext ||
            (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
          ctxRef.current = new AC();
        }
        const ctx = ctxRef.current!;
        if (ctx.state === "suspended") await ctx.resume();
        if (cancelled) return;

        // ── Master ────────────────────────────────────────────────
        const master = ctx.createGain();
        master.gain.value = 0.0001;
        master.connect(ctx.destination);
        masterRef.current = master;

        // ── Hall reverb (sacred cyber-temple) ─────────────────────
        const reverb = ctx.createConvolver();
        reverb.buffer = makeImpulse(ctx, 4.5, 3.2);
        const wet = ctx.createGain();
        wet.gain.value = 0.55;
        reverb.connect(wet).connect(master);
        const dry = ctx.createGain();
        dry.gain.value = 0.45;
        dry.connect(master);

        // Shared bus that splits to dry + reverb
        const bus = ctx.createGain();
        bus.gain.value = 0.9;
        bus.connect(dry);
        bus.connect(reverb);

        // ── Distant wind layer (filtered noise) ───────────────────
        const noiseBuf = ctx.createBuffer(1, ctx.sampleRate * 4, ctx.sampleRate);
        const noiseData = noiseBuf.getChannelData(0);
        for (let i = 0; i < noiseData.length; i++) noiseData[i] = Math.random() * 2 - 1;
        const noise = ctx.createBufferSource();
        noise.buffer = noiseBuf;
        noise.loop = true;

        const windHpf = ctx.createBiquadFilter();
        windHpf.type = "highpass";
        windHpf.frequency.value = 300;
        const windLpf = ctx.createBiquadFilter();
        windLpf.type = "lowpass";
        windLpf.frequency.value = 850;
        const windGain = ctx.createGain();
        windGain.gain.value = 0.07;

        // Slow LFO breathing on wind cutoff
        const windLfo = ctx.createOscillator();
        windLfo.frequency.value = 0.09;
        const windLfoAmp = ctx.createGain();
        windLfoAmp.gain.value = 200;
        windLfo.connect(windLfoAmp).connect(windLpf.frequency);

        noise.connect(windHpf).connect(windLpf).connect(windGain).connect(bus);
        noise.start();
        windLfo.start();

        // ── Pluck a tembûr-like note periodically ────────────────
        let pluckIndex = 0;
        const pluck = () => {
          const c = ctxRef.current;
          if (!c || c.state === "closed") return;
          const freq = TEMBUR_NOTES_HZ[pluckIndex % TEMBUR_NOTES_HZ.length];
          pluckIndex++;
          spawnTemburPluck(c, bus, freq);
        };
        pluck();
        pluckTimerRef.current = window.setInterval(pluck, PLUCK_INTERVAL_MS);

        // Fade in
        const now = ctx.currentTime;
        master.gain.cancelScheduledValues(now);
        master.gain.setValueAtTime(0.0001, now);
        master.gain.exponentialRampToValueAtTime(gain, now + 1.8);

        cleanupRef.current = () => {
          try { noise.stop(); } catch { /* ignore */ }
          try { windLfo.stop(); } catch { /* ignore */ }
        };
      } catch (err) {
        console.warn("[TemburAtmosphere] init failed", err);
      }
    };

    void start();
    return () => {
      cancelled = true;
    };
  }, [active, gain]);

  // Final cleanup
  useEffect(() => {
    return () => {
      if (pluckTimerRef.current) {
        window.clearInterval(pluckTimerRef.current);
        pluckTimerRef.current = null;
      }
      cleanupRef.current?.();
      cleanupRef.current = null;
      const ctx = ctxRef.current;
      if (ctx && ctx.state !== "closed") void ctx.close();
      ctxRef.current = null;
      masterRef.current = null;
    };
  }, []);

  return null;
}

// ── Helpers ──────────────────────────────────────────────────────────

function makeImpulse(ctx: AudioContext, durationSec: number, decay: number) {
  const rate = ctx.sampleRate;
  const length = Math.floor(rate * durationSec);
  const impulse = ctx.createBuffer(2, length, rate);
  for (let ch = 0; ch < 2; ch++) {
    const data = impulse.getChannelData(ch);
    for (let i = 0; i < length; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay);
    }
  }
  return impulse;
}

/**
 * Spawn one plucked tembûr-like note. We use a short noise burst (the pluck)
 * shaped by a band-pass filter at the fundamental, plus a triangle wave at
 * the same fundamental with slow-decaying envelope (the sustain), and a
 * detuned triangle a fifth above for shimmer.
 */
function spawnTemburPluck(ctx: AudioContext, dest: AudioNode, freq: number) {
  const now = ctx.currentTime;
  const totalDur = 3.2;

  // Pluck transient (filtered noise burst, very short)
  const noiseBuf = ctx.createBuffer(1, ctx.sampleRate * 0.25, ctx.sampleRate);
  const nd = noiseBuf.getChannelData(0);
  for (let i = 0; i < nd.length; i++) nd[i] = Math.random() * 2 - 1;
  const burst = ctx.createBufferSource();
  burst.buffer = noiseBuf;
  const bp = ctx.createBiquadFilter();
  bp.type = "bandpass";
  bp.frequency.value = freq * 2;
  bp.Q.value = 6;
  const burstEnv = ctx.createGain();
  burstEnv.gain.setValueAtTime(0.0001, now);
  burstEnv.gain.exponentialRampToValueAtTime(0.35, now + 0.005);
  burstEnv.gain.exponentialRampToValueAtTime(0.0001, now + 0.18);
  burst.connect(bp).connect(burstEnv).connect(dest);
  burst.start(now);
  burst.stop(now + 0.25);

  // Sustain — triangle fundamental + detuned fifth
  const o1 = ctx.createOscillator();
  o1.type = "triangle";
  o1.frequency.value = freq;
  const o2 = ctx.createOscillator();
  o2.type = "triangle";
  o2.frequency.value = freq * 1.5;
  o2.detune.value = -7;

  const sustainEnv = ctx.createGain();
  sustainEnv.gain.setValueAtTime(0.0001, now);
  sustainEnv.gain.exponentialRampToValueAtTime(0.18, now + 0.04);
  sustainEnv.gain.exponentialRampToValueAtTime(0.0001, now + totalDur);

  // Soft low-pass to keep it warm
  const tone = ctx.createBiquadFilter();
  tone.type = "lowpass";
  tone.frequency.value = 1600;

  o1.connect(sustainEnv);
  o2.connect(sustainEnv);
  sustainEnv.connect(tone).connect(dest);
  o1.start(now);
  o2.start(now);
  o1.stop(now + totalDur + 0.1);
  o2.stop(now + totalDur + 0.1);
}

