import type { VisualEffect } from "@/data/manifesto";

interface Props {
  effect: VisualEffect;
  className?: string;
}

/**
 * Sinematic, gold-themed SVG/Canvas backdrops for each manifesto step.
 * All use pure SVG with CSS keyframe animations (defined in styles.css).
 * Pointer-events disabled — purely decorative.
 */
export function ManifestoVisualEffect({ effect, className = "" }: Props) {
  return (
    <div className={`pointer-events-none absolute inset-0 overflow-hidden ${className}`}>
      {effect === "global_network_glow" && <GlobalNetwork />}
      {effect === "id_pulse_radiant" && <IdPulse />}
      {effect === "golden_currency_flow" && <CurrencyFlow />}
      {effect === "council_rings_connection" && <CouncilRings />}
      {effect === "cultural_pattern_morph" && <CulturalPattern />}
      {effect === "neural_network_nodes" && <NeuralNodes />}
      {effect === "audio_waveform_gold" && <AudioWaveform />}
      {effect === "solidarity_shield_glow" && <SolidarityShield />}
      {effect === "card_3d_render" && <Card3D />}
      {effect === "vault_opening_light" && <VaultOpening />}
    </div>
  );
}

const GOLD = "#D4AF37";
const GOLD_BRIGHT = "#FFE89A";

function GlobalNetwork() {
  // Concentric pulsing rings + roaming orbiting dots = "global network"
  const dots = Array.from({ length: 14 });
  return (
    <svg viewBox="0 0 400 400" className="h-full w-full">
      <defs>
        <radialGradient id="gn-glow" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor={GOLD} stopOpacity="0.45" />
          <stop offset="100%" stopColor="transparent" />
        </radialGradient>
      </defs>
      <circle cx="200" cy="200" r="180" fill="url(#gn-glow)" />
      {[60, 100, 140, 180].map((r, i) => (
        <circle
          key={r}
          cx="200"
          cy="200"
          r={r}
          fill="none"
          stroke={GOLD}
          strokeOpacity={0.25 + i * 0.1}
          strokeWidth="0.6"
          className="animate-mf-pulse"
          style={{ animationDelay: `${i * 0.4}s` }}
        />
      ))}
      <g className="origin-center animate-mf-spin-slow">
        {dots.map((_, i) => {
          const angle = (i / dots.length) * Math.PI * 2;
          const x = 200 + Math.cos(angle) * 150;
          const y = 200 + Math.sin(angle) * 150;
          return <circle key={i} cx={x} cy={y} r="2.4" fill={GOLD_BRIGHT} />;
        })}
      </g>
    </svg>
  );
}

function IdPulse() {
