          <stop offset="60%" stopColor={GOLD} stopOpacity="0.2" />
          <stop offset="100%" stopColor="transparent" />
        </radialGradient>
      </defs>
      <circle
        cx="200"
        cy="200"
        r="120"
        fill="url(#va-light)"
        className="animate-mf-pulse"
