          const angle = (i / 8) * Math.PI * 2;
          const x1 = 200 + Math.cos(angle) * 80;
          const y1 = 200 + Math.sin(angle) * 80;
          const x2 = 200 + Math.cos(angle) * 110;
          const y2 = 200 + Math.sin(angle) * 110;
          return (
            <line
              key={i}
              x1={x1}
              y1={y1}
              x2={x2}
              y2={y2}
              stroke={GOLD_BRIGHT}
              strokeWidth="3"
              strokeLinecap="round"
            />
          );
        })}
      </g>
      <text
        x="200"
        y="208"
        textAnchor="middle"
        fontSize="28"
        fontWeight="900"
        fill="#1a1208"
        fontFamily="ui-monospace, monospace"
      >
        50/40/10
      </text>
    </svg>
  );
}

