import { useState } from "react";
import { useEscrow } from "@/hooks/useMarketplace2";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Lock, CheckCircle2, RotateCcw, AlertTriangle } from "lucide-react";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Textarea } from "@/components/ui/textarea";

interface Props {
  bookingId: string;
  bookingAmount: number;
  customerId: string;
  providerId: string;
  bookingStatus: string;
}

export function EscrowPanel({ bookingId, bookingAmount, customerId, providerId, bookingStatus }: Props) {
  const { user } = useAuth();
  const { escrow, loading, createForBooking, release, refund, dispute } = useEscrow(bookingId);
  const [disputeReason, setDisputeReason] = useState("");

  if (!user) return null;
  const isBuyer = user.id === customerId;
  const isSeller = user.id === providerId;
  if (!isBuyer && !isSeller) return null;

  // No escrow yet → buyer can create
  if (!escrow) {
    if (!isBuyer || bookingStatus !== "pending") return null;
    return (
      <div className="rounded-2xl border border-border/30 bg-surface/40 p-4 backdrop-blur-md">
        <div className="flex items-center gap-2 mb-2">
          <Lock className="h-4 w-4 text-neon" />
          <h3 className="text-sm font-semibold text-foreground">Güvenli Ödeme (Escrow)</h3>
        </div>
        <p className="text-xs text-muted-foreground mb-3">
          {bookingAmount} DC kilitli olarak escrow'a alınır. İş tamamlandığında satıcıya serbest bırakırsınız.
        </p>
        <Button variant="neon" size="sm" disabled={loading} onClick={createForBooking} className="w-full">
          🔒 {bookingAmount} DC'yi Escrow'a Yatır
        </Button>
      </div>
    );
  }

  return (
    <div className="rounded-2xl border border-border/30 bg-surface/40 p-4 backdrop-blur-md space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Lock className="h-4 w-4 text-neon" />
          <h3 className="text-sm font-semibold text-foreground">Escrow</h3>
        </div>
        <StatusBadge status={escrow.status} />
      </div>

      <div className="grid grid-cols-3 gap-2 text-center text-xs">
        <Stat label="Tutar" value={`${escrow.amount} DC`} />
        <Stat label="Komisyon" value={`${escrow.commission} DC`} tone="muted" />
        <Stat label="Net" value={`${escrow.net_to_seller} DC`} tone="neon" />
      </div>

      {escrow.status === "held" && isBuyer && (
        <div className="flex gap-2">
          <Button variant="neon" size="sm" disabled={loading} onClick={() => release(escrow.id)} className="flex-1">
            <CheckCircle2 className="h-3.5 w-3.5" /> Onayla & Serbest Bırak
          </Button>
          <AlertDialog>
            <AlertDialogTrigger asChild>
              <Button variant="glass" size="sm"><AlertTriangle className="h-3.5 w-3.5" /></Button>
            </AlertDialogTrigger>
            <AlertDialogContent>
              <AlertDialogHeader>
                <AlertDialogTitle>İtiraz Aç</AlertDialogTitle>
                <AlertDialogDescription>Yöneticiler durumu inceleyecek.</AlertDialogDescription>
              </AlertDialogHeader>
              <Textarea value={disputeReason} onChange={(e) => setDisputeReason(e.target.value)} placeholder="Sorun nedir?" />
              <AlertDialogFooter>
                <AlertDialogCancel>Vazgeç</AlertDialogCancel>
                <AlertDialogAction onClick={() => disputeReason && dispute(escrow.id, disputeReason)}>İtiraz Et</AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        </div>
      )}

      {escrow.status === "held" && isSeller && (
        <p className="text-xs text-muted-foreground">İşi tamamlayın — müşteri onaylayınca {escrow.net_to_seller} DC kullanılabilir bakiyenize geçer.</p>
      )}

      {escrow.status === "disputed" && (
        <div className="rounded-lg bg-destructive/10 border border-destructive/30 p-2 text-xs text-destructive">
          ⚖️ İtirazlı: {escrow.dispute_reason || "—"}
        </div>
      )}

      {escrow.status === "released" && (
        <p className="text-xs text-neon">✅ Tamamlandı — {new Date(escrow.released_at!).toLocaleString("tr-TR")}</p>
      )}

      {escrow.status === "refunded" && (
        <p className="text-xs text-muted-foreground">💸 İade edildi — {new Date(escrow.refunded_at!).toLocaleString("tr-TR")}</p>
      )}
    </div>
  );
}

function Stat({ label, value, tone }: { label: string; value: string; tone?: "neon" | "muted" }) {
  return (
    <div className="rounded-lg bg-background/40 p-2">
      <div className={`text-sm font-bold ${tone === "neon" ? "text-neon" : tone === "muted" ? "text-muted-foreground" : "text-foreground"}`}>{value}</div>
      <div className="text-[10px] text-muted-foreground mt-0.5">{label}</div>
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, { label: string; cls: string }> = {
    held: { label: "Kilitli", cls: "bg-amber-500/20 text-amber-400 border-amber-500/30" },
    released: { label: "Serbest", cls: "bg-neon/20 text-neon border-neon/30" },
    refunded: { label: "İade", cls: "bg-muted/40 text-muted-foreground border-border/30" },
    disputed: { label: "İtirazlı", cls: "bg-destructive/20 text-destructive border-destructive/30" },
  };
  const m = map[status] ?? map.held;
  return <span className={`text-[10px] px-2 py-0.5 rounded-full border ${m.cls}`}>{m.label}</span>;
}

