import { useState } from "react";
import { useJobBids } from "@/hooks/useMarketplace2";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Hammer, Clock, Check } from "lucide-react";

interface Props { jobId: string; jobOwnerId: string; jobStatus: string; }

export function JobBidList({ jobId, jobOwnerId, jobStatus }: Props) {
  const { user } = useAuth();
  const { bids, loading, placeBid, acceptBid } = useJobBids(jobId);
  const [price, setPrice] = useState("");
  const [hours, setHours] = useState("");
  const [message, setMessage] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const isOwner = user?.id === jobOwnerId;
  const canBid = !!user && !isOwner && jobStatus === "open";

  const submit = async () => {
    const p = Number(price);
    if (!p || p <= 0) return;
    setSubmitting(true);
    const ok = await placeBid(p, hours ? Number(hours) : undefined, message || undefined);
    setSubmitting(false);
    if (ok) { setPrice(""); setHours(""); setMessage(""); }
  };

  return (
    <div className="space-y-4">
      {canBid && (
        <div className="rounded-2xl border border-border/30 bg-surface/40 p-4 backdrop-blur-md space-y-2">
          <div className="flex items-center gap-2 mb-1">
            <Hammer className="h-4 w-4 text-neon" />
            <h3 className="text-sm font-semibold text-foreground">Teklif Ver</h3>
          </div>
          <div className="flex gap-2">
            <Input type="number" placeholder="Fiyat (DC)" value={price} onChange={(e) => setPrice(e.target.value)} />
            <Input type="number" placeholder="Saat" value={hours} onChange={(e) => setHours(e.target.value)} className="w-24" />
          </div>
          <Textarea placeholder="Kısa mesaj (opsiyonel)" value={message} onChange={(e) => setMessage(e.target.value)} rows={2} />
          <Button variant="neon" size="sm" disabled={submitting || !price} onClick={submit} className="w-full">
            Teklifi Gönder
          </Button>
        </div>
      )}

      <div className="space-y-2">
        <h3 className="text-xs font-bold uppercase tracking-widest text-muted-foreground px-1">
          Teklifler ({bids.length})
        </h3>
        {loading && <p className="text-xs text-muted-foreground">Yükleniyor…</p>}
        {!loading && bids.length === 0 && (
          <p className="text-xs text-muted-foreground text-center py-6">Henüz teklif yok.</p>
        )}
        {bids.map((b) => (
          <div key={b.id} className="flex items-center gap-3 rounded-xl border border-border/20 bg-surface/30 p-3">
            <Avatar className="h-9 w-9">
              <AvatarImage src={b.provider?.avatar_url ?? undefined} />
              <AvatarFallback>{b.provider?.display_name?.[0] ?? "?"}</AvatarFallback>
            </Avatar>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <p className="text-sm font-medium text-foreground truncate">{b.provider?.display_name ?? "—"}</p>
                {b.status === "accepted" && <span className="text-[10px] text-neon">✓ Kazandı</span>}
                {b.status === "rejected" && <span className="text-[10px] text-muted-foreground">Reddedildi</span>}
              </div>
              <div className="flex items-center gap-3 text-[11px] text-muted-foreground mt-0.5">
                <span className="font-bold text-neon">{b.price} DC</span>
                {b.estimated_hours && <span className="flex items-center gap-1"><Clock className="h-3 w-3" />{b.estimated_hours}h</span>}
              </div>
              {b.message && <p className="text-[11px] text-muted-foreground mt-1 line-clamp-2">{b.message}</p>}
            </div>
            {isOwner && jobStatus === "open" && b.status === "pending" && (
              <Button variant="neon" size="sm" onClick={() => acceptBid(b.id)}>
                <Check className="h-3.5 w-3.5" /> Kabul
              </Button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

