import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Diamond, Sparkles, Star, ShoppingCart, Tag, Loader2, AlertTriangle } from "lucide-react";
import { toast } from "sonner";
import { SovereignActionGate } from "@/components/sovereign/SovereignActionGate";

interface Listing {
  id: string;
  seller_id: string;
  kurd_id: string;
  kurd_id_tier: string;
  price: number;
  status: string;
  created_at: string;
  seller_name?: string;
}

const TIER_ICONS: Record<string, typeof Diamond> = {
  ultra_premium: Diamond,
  premium: Sparkles,
  normal: Star,
};

const TIER_LABELS: Record<string, string> = {
  ultra_premium: "Ultra Premium",
  premium: "Premium",
  normal: "Standart",
};

const TIER_COLORS: Record<string, string> = {
  ultra_premium: "text-purple-400",
  premium: "text-blue-400",
  normal: "text-neon",
};

const TIER_BG: Record<string, string> = {
  ultra_premium: "bg-purple-500/10 border-purple-500/30",
  premium: "bg-blue-500/10 border-blue-500/30",
  normal: "bg-neon/10 border-neon/30",
};

export function NumberMarketplace({ userId, userKurdId, userTier, onPurchase }: {
  userId: string | undefined;
  userKurdId: string | null;
  userTier: string;
  onPurchase: () => void;
}) {
  const [listings, setListings] = useState<Listing[]>([]);
  const [myListings, setMyListings] = useState<Listing[]>([]);
  const [loading, setLoading] = useState(true);
  const [sellOpen, setSellOpen] = useState(false);
  const [buyListing, setBuyListing] = useState<Listing | null>(null);
  const [price, setPrice] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [filterTier, setFilterTier] = useState<string | null>(null);
  const [gateListing, setGateListing] = useState<Listing | null>(null);

  const fetchListings = useCallback(async () => {
    setLoading(true);
    const { data } = await supabase
      .from("number_listings")
      .select("*")
      .eq("status", "active")
      .order("created_at", { ascending: false });

    if (data) {
      // Fetch seller names
      const sellerIds = [...new Set(data.map(l => l.seller_id))];
      const { data: profiles } = await supabase
        .from("profiles")
        .select("user_id, display_name")
        .in("user_id", sellerIds);

      const nameMap = new Map(profiles?.map(p => [p.user_id, p.display_name]) || []);
      setListings(data.map(l => ({ ...l, seller_name: nameMap.get(l.seller_id) || "Anonim" })));
    }

    if (userId) {
      const { data: my } = await supabase
        .from("number_listings")
        .select("*")
        .eq("seller_id", userId)
        .in("status", ["active"]);
      setMyListings(my || []);
    }

    setLoading(false);
  }, [userId]);

  useEffect(() => { fetchListings(); }, [fetchListings]);

  const handleSell = async () => {
    if (!userId || !userKurdId) return;
    const p = parseFloat(price);
    if (isNaN(p) || p < 1) {
      toast.error("Geçerli bir fiyat girin (min 1 DC)");
      return;
    }

    if (myListings.length > 0) {
      toast.error("Zaten aktif bir ilanınız var");
      return;
    }

    setSubmitting(true);
    const { error } = await supabase.from("number_listings").insert({
      seller_id: userId,
      kurd_id: userKurdId,
      kurd_id_tier: userTier,
      price: p,
    });

    if (error) {
      toast.error("İlan oluşturulamadı");
    } else {
      toast.success("Numaran satışa çıkarıldı!");
      setSellOpen(false);
      setPrice("");
      fetchListings();
    }
    setSubmitting(false);
  };

  const handleBuy = async (listing: Listing) => {
    if (!userId) return;
    setSubmitting(true);

    const { data, error } = await supabase.rpc("purchase_number", {
      _buyer_id: userId,
      _listing_id: listing.id,
    });

    if (error) {
      toast.error(error.message || "Satın alma başarısız");
    } else if (data && typeof data === "object") {
      const result = data as Record<string, unknown>;
      if (result.success) {
        toast.success(`🎉 Yeni numaran: ${result.new_number}`);
        onPurchase();
        fetchListings();
      } else {
        toast.error((result.error as string) || "Satın alma başarısız");
      }
    }

    setBuyListing(null);
    setSubmitting(false);
  };

  const handleCancel = async (listingId: string) => {
    const { error } = await supabase
      .from("number_listings")
      .update({ status: "cancelled" })
      .eq("id", listingId);

    if (error) {
      toast.error("İlan iptal edilemedi");
    } else {
      toast.success("İlan iptal edildi");
      fetchListings();
    }
  };

  const filtered = filterTier ? listings.filter(l => l.kurd_id_tier === filterTier) : listings;

  return (
    <div className="space-y-4">
      {/* My Active Listing */}
      {myListings.length > 0 && (
        <div className="rounded-xl border border-gold/30 bg-gold/5 p-3">
          <p className="text-xs font-semibold text-gold mb-2">📢 Aktif İlanın</p>
          {myListings.map(l => (
            <div key={l.id} className="flex items-center justify-between">
              <div>
                <p className="text-sm font-mono font-bold text-foreground">{l.kurd_id}</p>
                <p className="text-xs text-muted-foreground">{l.price} DC</p>
              </div>
              <Button size="sm" variant="outline" onClick={() => handleCancel(l.id)}>
                İptal Et
              </Button>
            </div>
          ))}
        </div>
      )}

      {/* Sell Button */}
      {userId && myListings.length === 0 && (
        <Button variant="neon" className="w-full" onClick={() => setSellOpen(true)}>
          <Tag className="h-4 w-4 mr-2" /> Numaramı Satışa Koy
        </Button>
      )}

      {/* Filter */}
      <div className="flex gap-2">
        <button
          onClick={() => setFilterTier(null)}
          className={`text-xs px-3 py-1.5 rounded-full border transition-colors ${!filterTier ? "bg-neon/15 border-neon/40 text-neon" : "border-border text-muted-foreground"}`}
        >
          Tümü
        </button>
        {(["ultra_premium", "premium", "normal"] as const).map(t => {
          const Icon = TIER_ICONS[t];
          return (
            <button
              key={t}
              onClick={() => setFilterTier(filterTier === t ? null : t)}
              className={`flex items-center gap-1 text-xs px-3 py-1.5 rounded-full border transition-colors ${filterTier === t ? `${TIER_BG[t]} ${TIER_COLORS[t]}` : "border-border text-muted-foreground"}`}
            >
              <Icon className="h-3 w-3" />
              {TIER_LABELS[t]}
            </button>
          );
        })}
      </div>

      {/* Listings */}
      {loading ? (
        <div className="flex justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-8 text-sm text-muted-foreground">
          Henüz satışta numara yok
        </div>
      ) : (
        <div className="space-y-2">
          {filtered.map(listing => {
            const Icon = TIER_ICONS[listing.kurd_id_tier] || Star;
            const isMine = listing.seller_id === userId;
            return (
              <div key={listing.id} className={`rounded-xl border p-3 ${TIER_BG[listing.kurd_id_tier] || "border-border bg-surface"}`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className={`flex h-10 w-10 items-center justify-center rounded-lg bg-background/50 ${TIER_COLORS[listing.kurd_id_tier]}`}>
                      <Icon className="h-5 w-5" />
                    </div>
                    <div>
                      <p className={`text-sm font-mono font-bold ${TIER_COLORS[listing.kurd_id_tier]}`}>
                        {listing.kurd_id}
                      </p>
                      <p className="text-[10px] text-muted-foreground">
                        {TIER_LABELS[listing.kurd_id_tier]} · {listing.seller_name}
                      </p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-bold text-gold">{listing.price} DC</p>
                    {!isMine && userId && (
                      <Button size="sm" variant="neon" className="mt-1 h-7 text-xs" onClick={() => setBuyListing(listing)}>
                        <ShoppingCart className="h-3 w-3 mr-1" /> Satın Al
                      </Button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Sell Dialog */}
      <Dialog open={sellOpen} onOpenChange={setSellOpen}>
        <DialogContent className="bg-surface border-border">
          <DialogHeader>
            <DialogTitle>Numaranı Satışa Koy</DialogTitle>
            <DialogDescription>
              Numaran satıldığında sana yeni bir rastgele numara atanacak.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className={`rounded-xl border p-3 ${TIER_BG[userTier]}`}>
              <p className="text-xs text-muted-foreground mb-1">Satışa çıkarılacak numara:</p>
              <p className={`text-lg font-mono font-bold ${TIER_COLORS[userTier]}`}>{userKurdId}</p>
              <p className="text-[10px] text-muted-foreground">{TIER_LABELS[userTier]}</p>
            </div>

            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Fiyat (DC)</label>
              <Input
                type="number"
                placeholder="Fiyat belirle..."
                value={price}
                onChange={e => setPrice(e.target.value)}
                min={1}
                className="bg-background"
              />
            </div>

            <div className="flex items-start gap-2 rounded-lg bg-yellow-500/5 border border-yellow-500/20 p-2.5">
              <AlertTriangle className="h-4 w-4 text-yellow-400 shrink-0 mt-0.5" />
              <div className="text-[11px] text-muted-foreground">
                <p>Satış gerçekleştiğinde %5 platform komisyonu kesilir.</p>
                <p className="mt-1">Numaranız satıldığında size yeni bir rastgele numara atanır.</p>
              </div>
            </div>

            <Button variant="neon" className="w-full" onClick={handleSell} disabled={submitting}>
              {submitting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <Tag className="h-4 w-4 mr-2" />}
              Satışa Koy
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Buy Confirmation Dialog */}
      <Dialog open={!!buyListing} onOpenChange={() => setBuyListing(null)}>
        <DialogContent className="bg-surface border-border">
          <DialogHeader>
            <DialogTitle>Numara Satın Al</DialogTitle>
            <DialogDescription>
              Bu numarayı satın almak istediğinden emin misin?
            </DialogDescription>
          </DialogHeader>
          {buyListing && (
            <div className="space-y-4">
              <div className={`rounded-xl border p-4 text-center ${TIER_BG[buyListing.kurd_id_tier]}`}>
                <p className={`text-2xl font-mono font-bold ${TIER_COLORS[buyListing.kurd_id_tier]}`}>
                  {buyListing.kurd_id}
                </p>
                <p className="text-xs text-muted-foreground mt-1">{TIER_LABELS[buyListing.kurd_id_tier]}</p>
              </div>

              <div className="rounded-lg bg-background/50 p-3 space-y-1.5">
                <div className="flex justify-between text-xs">
                  <span className="text-muted-foreground">Fiyat</span>
                  <span className="font-semibold text-gold">{buyListing.price} DC</span>
                </div>
                <div className="flex justify-between text-xs">
                  <span className="text-muted-foreground">Mevcut numaran</span>
                  <span className="font-mono text-muted-foreground">{userKurdId}</span>
                </div>
              </div>

              <p className="text-[11px] text-muted-foreground text-center">
                Satın aldığında mevcut numaran değişecek ve yeni numara sana atanacak.
              </p>

              <Button
                variant="neon"
                className="w-full"
                onClick={() => {
                  setGateListing(buyListing);
                  setBuyListing(null);
                }}
                disabled={submitting}
              >
                {submitting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <ShoppingCart className="h-4 w-4 mr-2" />}
                {buyListing.price} DC ile Satın Al
              </Button>
            </div>
          )}
        </DialogContent>
      </Dialog>

      <SovereignActionGate
        open={!!gateListing}
        actionLabel={
          gateListing ? `Kurd-ID Borsa · ${gateListing.price} DC` : ""
        }
        actionDetail={gateListing ? gateListing.kurd_id : undefined}
        onConfirm={async () => {
          if (gateListing) await handleBuy(gateListing);
        }}
        onClose={() => setGateListing(null)}
      />
    </div>
  );
}

