/**
 * BookingDetailsDrawer — tap-to-expand details panel for a single Mivankas
 * booking. Surfaces all the secondary information that we keep out of the
 * compact row to preserve the Uber-minimal feel:
 *
 *   • Listing title, cover, category, host name
 *   • Live ETA (if Ride) and final price in DC
 *   • Payment-lock state derived from booking status:
 *       pending  → "Stripe Authorisation Pending"
 *       accepted → "Funds Locked in Escrow"     (🔒)
 *       active   → "Funds Locked in Escrow"     (🔒)
 *       completed→ "Funds Released to Host"     (✓)
 *       declined / cancelled → "Authorisation Voided"
 *   • One-tap "Open chat" button that opens (or creates) the 1-to-1 DM
 *     between guest and host.
 *   • Cancel flow with a structured reason picker — writes the reason into
 *     `mivankas_bookings.host_response` (no schema change required) and flips
 *     the status to `cancelled` (guest) or `declined` (host).
 *
 * The drawer is purely presentational; all mutations are delegated through
 * props so the parent route owns optimistic refresh + realtime updates.
 */
import { useEffect, useMemo, useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  Lock,
  LockOpen,
  CheckCircle2,
  Clock,
  MessageCircle,
  XCircle,
  ChevronRight,
  MapPin,
  Coins,
  Sparkles,
  Loader2,
  ShieldAlert,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { SterkFace } from "@/components/sovereign/SterkFace";
import type { MivankasBooking } from "@/hooks/useMivankas";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  booking: MivankasBooking | null;
  /** Current user id — used to pick which side ("guest" / "host") we're on. */
  currentUserId: string;
  /** Live distance estimate (km) between current user and listing, if known. */
  distanceKm: number | null;
  /** Final price in DC locked into Stripe escrow for this booking. */
  priceDc: number;
  /** Open or create the 1-to-1 chat for this booking, then navigate. */
  onOpenChat: (booking: MivankasBooking) => Promise<void> | void;
  /** Cancel the booking with the chosen reason. The parent persists it to
   *  `mivankas_bookings.host_response` (prefixed `[CANCEL_REASON]`). */
  onCancel: (booking: MivankasBooking, reason: string) => Promise<boolean>;
}

const CANCEL_REASONS = [
  { id: "wait", label: "Çok uzun süre bekledim" },
  { id: "plans", label: "Planlarım değişti" },
  { id: "wrong", label: "Yanlışlıkla rezervasyon yaptım" },
  { id: "host_unreachable", label: "Host'a ulaşılamıyor" },
  { id: "found_alternative", label: "Başka bir alternatif buldum" },
  { id: "other", label: "Diğer" },
] as const;

type LockState = "pending" | "locked" | "released" | "voided";

function deriveLockState(status: MivankasBooking["status"]): LockState {
  if (status === "pending") return "pending";
  if (status === "accepted" || status === "active") return "locked";
  if (status === "completed") return "released";
  return "voided"; // declined | cancelled
}

const LOCK_META: Record<
  LockState,
  { label: string; sub: string; tone: string; Icon: typeof Lock }
> = {
  pending: {
    label: "Stripe Onayı Bekleniyor",
    sub: "Kart yetkilendirmesi alınıyor",
    tone: "text-amber-200 bg-amber-400/10 border-amber-400/30",
    Icon: Clock,
  },
  locked: {
    label: "Fonlar Stripe Escrow'da Kilitli",
    sub: "Tamamlanınca host'a aktarılacak",
    tone: "text-cyan-100 bg-cyan-400/10 border-cyan-400/30",
    Icon: Lock,
  },
  released: {
    label: "Ödeme Host'a Aktarıldı",
    sub: "Stripe transferi tamamlandı",
    tone: "text-emerald-100 bg-emerald-400/10 border-emerald-400/30",
    Icon: CheckCircle2,
  },
  voided: {
    label: "Yetkilendirme İptal Edildi",
    sub: "Karttan tahsilat yapılmadı",
    tone: "text-rose-100 bg-rose-400/10 border-rose-400/30",
    Icon: LockOpen,
  },
};

export function BookingDetailsDrawer({
  open,
  onOpenChange,
  booking,
  currentUserId,
  distanceKm,
  priceDc,
  onOpenChat,
  onCancel,
}: Props) {
  const [view, setView] = useState<"details" | "cancel">("details");
  const [reasonId, setReasonId] = useState<string | null>(null);
  const [extra, setExtra] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [openingChat, setOpeningChat] = useState(false);

  // Reset internal view whenever the drawer closes.
  useEffect(() => {
    if (!open) {
      setView("details");
      setReasonId(null);
      setExtra("");
      setSubmitting(false);
      setOpeningChat(false);
    }
  }, [open]);

  const lockState = useMemo<LockState>(
    () => (booking ? deriveLockState(booking.status) : "pending"),
    [booking],
  );

  if (!booking) return null;
  const isHost = booking.host_id === currentUserId;
  const otherName = isHost
    ? "Misafir"
    : booking.listing?.host_id
      ? "Host"
      : "Egemen";
  const lock = LOCK_META[lockState];
  const Ico = lock.Icon;
  const canCancel =
    booking.status === "pending" ||
    booking.status === "accepted" ||
    booking.status === "active";
  const score = 0; // host score not joined on bookings; SterkFace tolerates 0
  const distLabel =
    distanceKm != null
      ? distanceKm < 1
        ? `${Math.round(distanceKm * 1000)} m`
        : `${distanceKm.toFixed(1)} km`
      : booking.listing?.city || "—";

  const handleConfirmCancel = async () => {
    if (!reasonId || submitting) return;
    const reasonLabel = CANCEL_REASONS.find((r) => r.id === reasonId)?.label ?? reasonId;
    const detail = extra.trim();
    const reasonText = detail ? `${reasonLabel} — ${detail}` : reasonLabel;
    setSubmitting(true);
    const ok = await onCancel(booking, reasonText);
    setSubmitting(false);
    if (ok) onOpenChange(false);
  };

  const handleOpenChat = async () => {
    if (openingChat) return;
    setOpeningChat(true);
    try {
      await onOpenChat(booking);
    } finally {
      setOpeningChat(false);
    }
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="bg-[#0A0A0C] border-t border-amber-400/25 p-0 max-h-[88vh] overflow-hidden flex flex-col"
      >
        <SheetHeader className="px-5 pt-3 pb-2 text-left">
          <div className="flex justify-center pb-1">
            <span className="block h-1 w-10 rounded-full bg-white/15" />
          </div>
          <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-amber-300/70">
            {view === "cancel" ? "İptal Sebebi" : "Sipariş Detayı"}
          </div>
          <SheetTitle className="text-white text-[18px] font-semibold">
            {view === "cancel" ? "Neden iptal ediyorsun?" : booking.listing?.title ?? "—"}
          </SheetTitle>
        </SheetHeader>

        {view === "details" && (
          <div className="flex-1 overflow-y-auto px-5 pb-2 space-y-4">
            {/* === Host / guest summary === */}
            <div className="flex items-center gap-3">
              <SterkFace
                avatarUrl={booking.listing?.cover_url ?? undefined}
                displayName={otherName}
                kekaScore={score}
                size={56}
                showAura={false}
              />
              <div className="flex-1 min-w-0">
                <div className="text-[15px] font-semibold text-white truncate">
                  {otherName}
                </div>
                <div className="flex items-center gap-1.5 text-[12px] text-white/55 mt-0.5">
                  <MapPin className="h-3 w-3" />
                  <span>{distLabel}</span>
                  <span className="text-white/20">·</span>
                  <span className="capitalize">{booking.listing?.category ?? "—"}</span>
                </div>
              </div>
            </div>

            {/* === Price + ETA tile === */}
            <div className="rounded-2xl bg-white/[0.04] border border-white/[0.08] p-4 flex items-center gap-3">
              <div className="flex-1">
                <div className="text-[10px] font-mono uppercase tracking-widest text-white/45">
                  Tahmini varış
                </div>
                <div className="text-[18px] font-semibold text-white tabular-nums leading-tight mt-0.5">
                  {distanceKm != null ? `${Math.max(2, Math.round(3 + distanceKm * 1.6))} dk` : "—"}
                </div>
              </div>
              <span className="h-10 w-px bg-white/10" />
              <div className="flex-1 text-right">
                <div className="text-[10px] font-mono uppercase tracking-widest text-white/45">
                  Mühür ücreti
                </div>
                <div className="text-[18px] font-semibold text-amber-100 tabular-nums leading-tight mt-0.5">
                  {priceDc} <span className="text-[12px] font-normal text-amber-200/70">DC</span>
                </div>
              </div>
            </div>

            {/* === Payment lock state pill === */}
            <div
              className={cn(
                "rounded-2xl border px-4 py-3 flex items-center gap-3",
                lock.tone,
              )}
            >
              <Ico className="h-5 w-5 shrink-0" />
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold leading-tight">
                  {lock.label}
                </div>
                <div className="text-[11px] opacity-70 mt-0.5">{lock.sub}</div>
              </div>
            </div>

            {/* === Listing description === */}
            {booking.listing?.description && (
              <div className="rounded-xl bg-white/[0.02] border border-white/[0.06] p-3">
                <div className="text-[10px] font-mono uppercase tracking-widest text-white/45 mb-1">
                  İlan Notu
                </div>
                <div className="text-[12px] text-white/75 leading-relaxed line-clamp-4">
                  {booking.listing.description}
                </div>
              </div>
            )}

            {booking.guest_message && (
              <div className="rounded-xl bg-white/[0.02] border border-white/[0.06] p-3">
                <div className="text-[10px] font-mono uppercase tracking-widest text-white/45 mb-1">
                  Misafir Mesajı
                </div>
                <div className="text-[12px] text-white/85 italic">
                  "{booking.guest_message}"
                </div>
              </div>
            )}
          </div>
        )}

        {view === "cancel" && (
          <div className="flex-1 overflow-y-auto px-5 pb-2 space-y-2">
            <div className="rounded-2xl bg-rose-400/10 border border-rose-400/30 p-3 flex items-start gap-2.5">
              <ShieldAlert className="h-4 w-4 text-rose-200 shrink-0 mt-0.5" />
              <div className="text-[11px] text-rose-100 leading-relaxed">
                İptal sebebin host'a iletilir ve siparişe kalıcı olarak işlenir.
                {lockState === "locked" && " Stripe escrow yetkilendirmesi geri çekilir."}
              </div>
            </div>
            <div className="space-y-1.5 pt-1">
              {CANCEL_REASONS.map((r) => {
                const active = reasonId === r.id;
                return (
                  <button
                    key={r.id}
                    onClick={() => setReasonId(r.id)}
                    className={cn(
                      "w-full flex items-center justify-between gap-3 px-4 h-12 rounded-xl border text-left text-[13px] transition active:scale-[0.99]",
                      active
                        ? "bg-amber-400/15 border-amber-300/60 text-amber-100"
                        : "bg-white/[0.03] border-white/10 text-white/80",
                    )}
                  >
                    <span>{r.label}</span>
                    {active && <CheckCircle2 className="h-4 w-4 text-amber-300" />}
                  </button>
                );
              })}
            </div>
            {reasonId === "other" && (
              <textarea
                value={extra}
                onChange={(e) => setExtra(e.target.value.slice(0, 200))}
                placeholder="Daha fazla detay ver…"
                rows={3}
                className="w-full rounded-xl bg-white/[0.04] border border-white/10 px-3 py-2 text-[12px] text-white placeholder:text-white/30 focus:outline-none focus:border-amber-300/50 mt-1"
              />
            )}
          </div>
        )}

        {/* === Footer actions === */}
        <div
          className="border-t border-white/[0.06] px-4 pt-3 mt-3 bg-[#0A0A0C] space-y-2"
          style={{ paddingBottom: "max(env(safe-area-inset-bottom), 12px)" }}
        >
          {view === "details" ? (
            <>
              <button
                onClick={handleOpenChat}
                disabled={openingChat}
                className="w-full h-12 rounded-2xl flex items-center justify-center gap-2 bg-gradient-to-r from-amber-400 to-yellow-300 text-black font-bold text-[14px] active:scale-[0.98] shadow-[0_8px_24px_-8px_rgba(245,158,11,0.6)] disabled:opacity-70"
              >
                {openingChat ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <MessageCircle className="h-4 w-4" />
                )}
                Sohbet aç
                <ChevronRight className="h-4 w-4" />
              </button>
              {canCancel && (
                <button
                  onClick={() => setView("cancel")}
                  className="w-full h-11 rounded-2xl flex items-center justify-center gap-2 bg-white/[0.04] border border-rose-400/30 text-rose-200 font-semibold text-[12px] active:scale-[0.98]"
                >
                  <XCircle className="h-4 w-4" />
                  {isHost ? "Reddet / İptal" : "Siparişi iptal et"}
                </button>
              )}
            </>
          ) : (
            <>
              <button
                onClick={handleConfirmCancel}
                disabled={!reasonId || submitting}
                className="w-full h-12 rounded-2xl flex items-center justify-center gap-2 bg-rose-500 text-white font-bold text-[14px] active:scale-[0.98] disabled:opacity-50 disabled:active:scale-100"
              >
                {submitting ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <XCircle className="h-4 w-4" />
                )}
                İptali Onayla
              </button>
              <button
                onClick={() => setView("details")}
                disabled={submitting}
                className="w-full h-10 rounded-2xl flex items-center justify-center gap-2 bg-transparent text-white/55 text-[12px] active:scale-[0.98]"
              >
                Vazgeç, geri dön
              </button>
            </>
          )}
          <div className="text-center text-[10px] text-white/35 pt-1 flex items-center justify-center gap-1">
            <Coins className="h-3 w-3" />
            {priceDc} DC
            <span className="text-white/20">·</span>
            <Sparkles className="h-3 w-3" />
            {lock.label}
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

