/**
 * BookingStatusTracker — compact 4-step horizontal tracker for a Mivankas
 * booking lifecycle. Shows: Talep → Kabul → Yolda → Tamamlandı.
 *
 * Map to mivankas_bookings.status:
 *   pending  -> step 0  (Talep gönderildi)
 *   accepted -> step 1  (Host kabul etti)
 *   active   -> step 2  (Yolda / In progress)
 *   completed -> step 3 (Tamamlandı)
 *   declined / cancelled -> rendered separately (terminal red state)
 *
 * Pure presentational; the parent supplies `status` and the tracker animates
 * via CSS transitions when it changes (works seamlessly with the realtime
 * subscription that already drives the bookings list).
 */
import { Check, Clock, Sparkles, Truck, Lock, LockOpen, CheckCircle2 } from "lucide-react";
import { cn } from "@/lib/utils";

export type BookingStatus =
  | "pending"
  | "accepted"
  | "active"
  | "completed"
  | "declined"
  | "cancelled";

const STEPS = [
  { key: "pending", label: "Talep", Icon: Clock },
  { key: "accepted", label: "Kabul", Icon: Sparkles },
  { key: "active", label: "Yolda", Icon: Truck },
  { key: "completed", label: "Tamam", Icon: Check },
] as const;

const STATUS_INDEX: Record<BookingStatus, number> = {
  pending: 0,
  accepted: 1,
  active: 2,
  completed: 3,
  declined: -1,
  cancelled: -1,
};

/** Maps booking status → Stripe payment-lock label so the user always knows
 *  whether their card has been charged, the funds are escrowed, or already
 *  released to the host. Hidden in compact mode to keep rows tight. */
const PAYMENT_LOCK: Record<
  BookingStatus,
  { label: string; tone: string; Icon: typeof Lock } | null
> = {
  pending: {
    label: "Stripe yetkilendirme bekleniyor",
    tone: "text-amber-200 bg-amber-400/10 border-amber-400/25",
    Icon: Clock,
  },
  accepted: {
    label: "Fonlar Stripe escrow'da kilitli",
    tone: "text-cyan-100 bg-cyan-400/10 border-cyan-400/30",
    Icon: Lock,
  },
  active: {
    label: "Fonlar Stripe escrow'da kilitli",
    tone: "text-cyan-100 bg-cyan-400/10 border-cyan-400/30",
    Icon: Lock,
  },
  completed: {
    label: "Ödeme host'a aktarıldı",
    tone: "text-emerald-100 bg-emerald-400/10 border-emerald-400/30",
    Icon: CheckCircle2,
  },
  declined: {
    label: "Yetkilendirme iptal edildi",
    tone: "text-rose-100 bg-rose-400/10 border-rose-400/30",
    Icon: LockOpen,
  },
  cancelled: {
    label: "Yetkilendirme iptal edildi",
    tone: "text-rose-100 bg-rose-400/10 border-rose-400/30",
    Icon: LockOpen,
  },
};

interface Props {
  status: BookingStatus;
  /** When true, render in a tighter inline form (no labels). */
  compact?: boolean;
  /** Show the Stripe payment-lock label below the stepper. Default: true. */
  showPaymentLock?: boolean;
}

export function BookingStatusTracker({
  status,
  compact = false,
  showPaymentLock = true,
}: Props) {
  const lock = PAYMENT_LOCK[status];

  // Terminal cancelled states get their own minimal pill + the voided lock label.
  if (status === "declined" || status === "cancelled") {
    return (
      <div className="space-y-2">
        <div className="inline-flex items-center gap-1.5 px-2 py-1 rounded-full bg-rose-500/10 border border-rose-400/30 text-[10px] font-bold text-rose-200">
          <span className="h-1.5 w-1.5 rounded-full bg-rose-400" />
          {status === "declined" ? "Reddedildi" : "İptal"}
        </div>
        {showPaymentLock && lock && !compact && (
          <PaymentLockPill lock={lock} />
        )}
      </div>
    );
  }

  const activeIdx = STATUS_INDEX[status];

  return (
    <div className="w-full space-y-2">
      <div className="flex items-center">
        {STEPS.map((step, i) => {
          const Done = i < activeIdx;
          const Active = i === activeIdx;
          const Future = i > activeIdx;
          const Ico = step.Icon;
          return (
            <div key={step.key} className="flex items-center flex-1 last:flex-initial">
              <div className="relative flex flex-col items-center">
                <span
                  className={cn(
                    "relative flex items-center justify-center rounded-full transition-all duration-300",
                    compact ? "h-5 w-5" : "h-6 w-6",
                    Done && "bg-amber-400 text-black",
                    Active &&
                      "bg-amber-400 text-black ring-2 ring-amber-300/70 ring-offset-2 ring-offset-[#0A0A0C]",
                    Future && "bg-white/5 text-white/30 border border-white/10",
                  )}
                >
                  <Ico
                    className={cn(compact ? "h-2.5 w-2.5" : "h-3 w-3")}
                    strokeWidth={2.6}
                  />
                  {Active && (
                    <span
                      aria-hidden
                      className="absolute inset-0 rounded-full border border-amber-300/60 animate-ping"
                    />
                  )}
                </span>
                {!compact && (
                  <span
                    className={cn(
                      "mt-1 text-[9px] font-medium uppercase tracking-wider whitespace-nowrap transition-colors",
                      Done || Active ? "text-amber-100" : "text-white/35",
                    )}
                  >
                    {step.label}
                  </span>
                )}
              </div>
              {/* Connector line — except after last step */}
              {i < STEPS.length - 1 && (
                <span
                  className={cn(
                    "flex-1 h-px mx-1 transition-colors duration-300",
                    i < activeIdx ? "bg-amber-300/70" : "bg-white/10",
                  )}
                />
              )}
            </div>
          );
        })}
      </div>
      {showPaymentLock && lock && !compact && <PaymentLockPill lock={lock} />}
    </div>
  );
}

function PaymentLockPill({
  lock,
}: {
  lock: NonNullable<(typeof PAYMENT_LOCK)[BookingStatus]>;
}) {
  const Ico = lock.Icon;
  return (
    <div
      className={cn(
        "inline-flex items-center gap-1.5 px-2 py-1 rounded-full border text-[10px] font-medium",
        lock.tone,
      )}
    >
      <Ico className="h-3 w-3" strokeWidth={2.4} />
      <span className="truncate">{lock.label}</span>
    </div>
  );
}

