            disabled={busy}
            className="w-full px-4 py-3 rounded-xl bg-gradient-to-r from-amber-500 to-amber-300 text-black font-bold tracking-wider uppercase text-[12px] disabled:opacity-50 active:scale-[0.98]"
          >
            {busy ? "Yayınlanıyor…" : "İlanı Mühürle"}
          </button>
        </div>
      </SheetContent>
    </Sheet>
  );
}

