/**
 * DestinationSearchSheet — Uber-style "Where to?" experience for Mivankas.
 *
 * Filters the live `ride` (Sürmek) listings by:
 *   • free-text destination / city query
 *   • availability window (now / today / tomorrow / any)
 *   • minimum capacity (passenger seats)
 *   • Sovereign tier tab (All / Sovereign-X / Dîwan-Premium / Sovereign-Group)
 *
 * Results are ranked by KEKA tier (Dîwan ≥ 4000 → Civat ≥ 1500 → Egemen ≥ 500),
 * then by distance from the rider's live GPS position when available.
 *
 * Each driver row uses the 21-ray Stêrka Geş emblem so the rider sees a real
 * Sovereign face — not a generic icon.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Input } from "@/components/ui/input";
import {
  Search,
  Car,
  MapPin,
  Sparkles,
  Clock,
  Users,
  Navigation,
  ShieldCheck,
  History,
  X,
  Crown,
  Bus,
  Globe2,
  Loader2,
} from "lucide-react";
import type { MivankasListing } from "@/hooks/useMivankas";
import { cn } from "@/lib/utils";
import { SterkFace } from "@/components/sovereign/SterkFace";
import { useRecentDestinations } from "@/hooks/useRecentDestinations";
import {
  fetchEuropeAddressSuggestions,
  type PhotonSuggestion,
} from "@/lib/photonAutocomplete";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  listings: MivankasListing[];
  selfLocation: { lat: number; lng: number } | null;
  onSelectDriver: (listing: MivankasListing) => void;
}

type WhenFilter = "any" | "now" | "today" | "tomorrow";
type SeatsFilter = 1 | 2 | 4;
type TierTab = "all" | "sovereign-x" | "premium-diwan" | "sovereign-group";

type DriverTier = "diwan" | "civat" | "egemen" | "default";

function tierFromKeka(score: number): DriverTier {
  if (score >= 4000) return "diwan";
  if (score >= 1500) return "civat";
  if (score >= 500) return "egemen";
  return "default";
}

const TIER_RANK: Record<DriverTier, number> = {
  diwan: 3,
  civat: 2,
  egemen: 1,
  default: 0,
};

const TIER_META: Record<
  DriverTier,
  { label: string; color: string }
> = {
  diwan: { label: "Dîwan", color: "text-amber-100" },
  civat: { label: "Civat", color: "text-amber-200" },
  egemen: { label: "Egemen", color: "text-amber-300" },
  default: { label: "Sürmek", color: "text-amber-300/80" },
};

const TIER_TABS: {
  key: TierTab;
  label: string;
  Icon: typeof Car;
  hint: string;
}[] = [
  { key: "all", label: "Tümü", Icon: Sparkles, hint: "Tüm Sürmek" },
  { key: "sovereign-x", label: "Sovereign-X", Icon: Car, hint: "Ekonomik" },
  { key: "premium-diwan", label: "Dîwan", Icon: Crown, hint: "Premium · KEKA ≥ 1500" },
  { key: "sovereign-group", label: "Group", Icon: Bus, hint: "4+ koltuk" },
];

/** Map a driver to one (or many) of the marketing tier tabs. */
function matchesTab(tab: TierTab, driverTier: DriverTier, capacity: number): boolean {
  if (tab === "all") return true;
  if (tab === "sovereign-x") return driverTier === "default" || driverTier === "egemen";
  if (tab === "premium-diwan") return driverTier === "civat" || driverTier === "diwan";
  if (tab === "sovereign-group") return capacity >= 4;
  return true;
}

/** Haversine distance in km between two lat/lng pairs. */
function distanceKm(a: { lat: number; lng: number }, b: { lat: number; lng: number }) {
  const R = 6371;
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
  const lat1 = (a.lat * Math.PI) / 180;
  const lat2 = (b.lat * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.sin(dLng / 2) ** 2 * Math.cos(lat1) * Math.cos(lat2);
  return 2 * R * Math.asin(Math.sqrt(h));
}

function withinWindow(listing: MivankasListing, when: WhenFilter): boolean {
  if (when === "any") return true;
  const now = new Date();
  const from = listing.available_from ? new Date(listing.available_from) : null;
  const until = listing.available_until ? new Date(listing.available_until) : null;
  if (!from && !until) return true;
  if (when === "now") {
    if (from && from > now) return false;
    if (until && until < now) return false;
    return true;
  }
  const dayStart = new Date(now);
  dayStart.setHours(0, 0, 0, 0);
  const dayEnd = new Date(dayStart);
  dayEnd.setDate(dayEnd.getDate() + (when === "today" ? 1 : 2));
  const target = when === "today" ? dayStart : new Date(dayStart.getTime() + 86400000);
  const targetEnd = when === "today" ? dayEnd : new Date(dayEnd.getTime());
  if (until && until < target) return false;
  if (from && from > targetEnd) return false;
  return true;
}

export function DestinationSearchSheet({
  open,
  onOpenChange,
  listings,
  selfLocation,
  onSelectDriver,
}: Props) {
  const [destination, setDestination] = useState("");
  const [when, setWhen] = useState<WhenFilter>("any");
  const [seats, setSeats] = useState<SeatsFilter>(1);
  const [tab, setTab] = useState<TierTab>("all");
  const { recents, push: pushRecent, remove: removeRecent, clear: clearRecents } =
    useRecentDestinations();

  // ── Europe-wide address autocomplete (Photon / OpenStreetMap) ────────────
  // Free, no API key, covers every street in Europe. We debounce to 250ms so
  // we don't hammer the API on every keystroke.
  const [photonResults, setPhotonResults] = useState<PhotonSuggestion[]>([]);
  const [photonLoading, setPhotonLoading] = useState(false);
  const photonAbortRef = useRef<AbortController | null>(null);
  useEffect(() => {
    const q = destination.trim();
    if (q.length < 2) {
      setPhotonResults([]);
      setPhotonLoading(false);
      return;
    }
    const t = setTimeout(async () => {
      photonAbortRef.current?.abort();
      const ctrl = new AbortController();
      photonAbortRef.current = ctrl;
      setPhotonLoading(true);
      const results = await fetchEuropeAddressSuggestions(q, ctrl.signal, 6);
      if (!ctrl.signal.aborted) {
        setPhotonResults(results);
        setPhotonLoading(false);
      }
    }, 250);
    return () => clearTimeout(t);
  }, [destination]);

  // Reset query when sheet closes so the next open is fresh.
  useEffect(() => {
    if (!open) {
      setDestination("");
      setTab("all");
      setPhotonResults([]);
      photonAbortRef.current?.abort();
    }
  }, [open]);

  const matchingDrivers = useMemo(() => {
    const q = destination.trim().toLowerCase();
    const onlyRides = listings.filter((l) => l.category === "ride" && l.is_active);

    const filtered = onlyRides.filter((l) => {
      if (l.capacity < seats) return false;
      if (!withinWindow(l, when)) return false;
      const driverTier = tierFromKeka(l.host?.keka_points ?? 0);
      if (!matchesTab(tab, driverTier, l.capacity)) return false;
      if (q) {
        const hay = `${l.city} ${l.title} ${l.description}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });

    const enriched = filtered.map((l) => {
      const score = l.host?.keka_points ?? 0;
      const tierKey = tierFromKeka(score);
      const dist =
        selfLocation && l.latitude != null && l.longitude != null
          ? distanceKm(selfLocation, { lat: l.latitude, lng: l.longitude })
          : null;
      return { listing: l, tier: tierKey, score, distanceKm: dist };
    });

    enriched.sort((a, b) => {
      const t = TIER_RANK[b.tier] - TIER_RANK[a.tier];
      if (t !== 0) return t;
      if (a.distanceKm != null && b.distanceKm != null) {
        return a.distanceKm - b.distanceKm;
      }
      if (a.distanceKm == null && b.distanceKm != null) return 1;
      if (a.distanceKm != null && b.distanceKm == null) return -1;
      return b.score - a.score;
    });

    return enriched.slice(0, 30);
  }, [destination, when, seats, tab, listings, selfLocation]);

  // Per-tab counts for badge bubbles
  const tabCounts = useMemo(() => {
    const counts: Record<TierTab, number> = {
      all: 0,
      "sovereign-x": 0,
      "premium-diwan": 0,
      "sovereign-group": 0,
    };
    listings
      .filter((l) => l.category === "ride" && l.is_active)
      .forEach((l) => {
        const driverTier = tierFromKeka(l.host?.keka_points ?? 0);
        TIER_TABS.forEach(({ key }) => {
          if (matchesTab(key, driverTier, l.capacity)) counts[key]++;
        });
      });
    return counts;
  }, [listings]);

  const handleSelect = (listing: MivankasListing) => {
    pushRecent(listing.city || listing.title);
    onSelectDriver(listing);
    onOpenChange(false);
  };

  // Live autocomplete suggestions — distinct city/title strings drawn from
  // the listings, ranked by frequency, capped at 8.
  const autocomplete = useMemo(() => {
    const q = destination.trim().toLowerCase();
    if (q.length < 1) return [] as string[];
    const counts = new Map<string, number>();
    listings.forEach((l) => {
      [l.city, l.title].forEach((raw) => {
        if (!raw) return;
        const v = raw.trim();
        if (!v) return;
        if (!v.toLowerCase().includes(q)) return;
        counts.set(v, (counts.get(v) ?? 0) + 1);
      });
    });
    return Array.from(counts.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8)
      .map(([v]) => v);
  }, [destination, listings]);

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        // Full-screen Uber-style overlay — no rounded top, no drag handle,
        // so it reads as a dedicated search PAGE rather than a peeking sheet.
        className="bg-[#0A0A0C] border-0 p-0 h-[100dvh] max-h-[100dvh] overflow-hidden flex flex-col rounded-none"
      >
        {/* === Uber-minimal header: back arrow + "Nereye?" pill === */}
        <div
          className="px-4 pt-2 pb-3 flex items-center gap-2 border-b border-white/[0.06]"
          style={{ paddingTop: "max(env(safe-area-inset-top), 0.5rem)" }}
        >
          <button
            onClick={() => onOpenChange(false)}
            aria-label="Haritaya dön"
            className="h-11 w-11 rounded-full bg-white/[0.06] flex items-center justify-center active:scale-95 transition shrink-0"
          >
            <X className="h-4 w-4 text-white" />
          </button>
          <div className="flex-1 flex items-center gap-2.5 h-11 rounded-full bg-white/[0.08] px-4">
            <Search className="h-4 w-4 text-white/60 shrink-0" />
            <Input
              autoFocus
              value={destination}
              onChange={(e) => setDestination(e.target.value)}
              placeholder="Nereye?"
              className="flex-1 h-9 bg-transparent border-0 text-[14px] text-white placeholder:text-white/40 focus-visible:ring-0 px-0"
            />
            {destination && (
              <button
                type="button"
                onClick={() => setDestination("")}
                aria-label="Temizle"
                className="h-6 w-6 rounded-full bg-white/10 flex items-center justify-center text-white/70 active:scale-95"
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>
        </div>

        <SheetHeader className="sr-only">
          <SheetTitle>Nereye gidiyorsun?</SheetTitle>
        </SheetHeader>

        {/* === Autocomplete suggestions ===
            Two layers, ordered by specificity:
              1) Photon (Europe-wide street-level addresses)
              2) Local listing matches (city + title) — the original engine */}
        {(photonResults.length > 0 || autocomplete.length > 0 || photonLoading) && (
          <div className="border-b border-white/[0.04]">
            {photonLoading && photonResults.length === 0 && (
              <div className="flex items-center gap-3 px-5 h-11 text-[12px] text-white/45">
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                Avrupa adresleri aranıyor…
              </div>
            )}
            {photonResults.map((s) => (
              <button
                key={s.key}
                onClick={() => setDestination(s.label)}
                className="w-full flex items-center gap-3 px-5 h-14 text-left active:bg-white/[0.04] transition"
              >
                <div className="h-8 w-8 rounded-full bg-amber-400/10 border border-amber-300/30 flex items-center justify-center shrink-0">
                  <Globe2 className="h-3.5 w-3.5 text-amber-300" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-[14px] font-medium text-white truncate">
                    {s.label}
                  </div>
                  {s.countryCode && (
                    <div className="text-[10px] text-white/40 mt-0.5 uppercase tracking-wider font-mono">
                      {s.countryCode}
                      {s.city ? ` · ${s.city}` : ""}
                    </div>
                  )}
                </div>
                <Search className="h-3.5 w-3.5 text-white/30 shrink-0" />
              </button>
            ))}
            {autocomplete.map((s) => (
              <button
                key={s}
                onClick={() => setDestination(s)}
                className="w-full flex items-center gap-3 px-5 h-12 text-left active:bg-white/[0.04] transition"
              >
                <div className="h-8 w-8 rounded-full bg-white/[0.06] flex items-center justify-center shrink-0">
                  <MapPin className="h-3.5 w-3.5 text-white/55" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-[14px] font-medium text-white truncate">{s}</div>
                  <div className="text-[10px] text-white/40 mt-0.5">Sahada eşleşme</div>
                </div>
                <Search className="h-3.5 w-3.5 text-white/30 shrink-0" />
              </button>
            ))}
          </div>
        )}

        {/* Recent destinations — shows when query is empty */}
        {destination.trim().length === 0 && recents.length > 0 && (
