import { useMemo, useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Textarea } from "@/components/ui/textarea";
import {
  Car,
  Home,
  UtensilsCrossed,
  Hammer,
  Sparkles,
  ShieldCheck,
  Users,
  MapPin,
  ChevronLeft,
  ChevronRight,
} from "lucide-react";
import type { MivankasListing, MivankasCategory } from "@/hooks/useMivankas";
import type { MivankasMeta } from "@/lib/mivankasMeta";
import { SterkFace } from "@/components/sovereign/SterkFace";
import { cn } from "@/lib/utils";

const ICON: Record<MivankasCategory, typeof Car> = {
  ride: Car,
  home: Home,
  sofra: UtensilsCrossed,
  xezine: Hammer,
};

const CATEGORY_LABEL: Record<MivankasCategory, string> = {
  ride: "Ride · Yolculuk",
  home: "Home · Sığınak",
  sofra: "Sofra · Yemek",
  xezine: "Xezîne · Eşya",
};

interface Props {
  listing: MivankasListing | null;
  open: boolean;
  onOpenChange: (v: boolean) => void;
  isOwn: boolean;
  onRequest: (listing: MivankasListing, message: string) => Promise<string | null>;
}

/** Pull the right gallery from category-specific meta with sane fallbacks. */
function galleryFor(listing: MivankasListing): string[] {
  const meta = (listing.metadata ?? {}) as MivankasMeta;
  let urls: string[] = [];
  if (listing.category === "home") urls = meta.home?.gallery_urls ?? [];
  else if (listing.category === "sofra") urls = meta.sofra?.menu_urls ?? [];
  else urls = meta.gallery_urls ?? [];
  // Ensure cover is first if present and not already in the gallery
  if (listing.cover_url && !urls.includes(listing.cover_url)) {
    urls = [listing.cover_url, ...urls];
  }
  return urls.filter((u) => typeof u === "string" && u.length > 0);
}

export function ListingDetailSheet({
  listing,
  open,
  onOpenChange,
  isOwn,
  onRequest,
}: Props) {
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);

  // Hooks before any early return — order must be stable across renders.
  const gallery = useMemo(() => (listing ? galleryFor(listing) : []), [listing]);

  if (!listing) return null;
  const Icon = ICON[listing.category];
  const reputation = listing.host?.keka_points ?? 0;

  const submit = async () => {
    setBusy(true);
    const id = await onRequest(listing, message);
    setBusy(false);
    if (id) {
      setMessage("");
      onOpenChange(false);
    }
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="bg-[#0A0A0A] border-amber-400/20 text-foreground max-h-[88vh] overflow-y-auto"
      >
        <SheetHeader className="text-left">
          <div className="flex items-center gap-2">
            <div className="w-9 h-9 rounded-lg bg-amber-400/15 border border-amber-400/30 flex items-center justify-center">
              <Icon className="w-4 h-4 text-amber-300" />
            </div>
            <div>
              <div className="text-[9px] font-mono uppercase tracking-[0.25em] text-amber-300/70">
                {CATEGORY_LABEL[listing.category]}
              </div>
              <SheetTitle className="text-amber-100 text-base">{listing.title}</SheetTitle>
            </div>
          </div>
        </SheetHeader>

        <div className="mt-4 space-y-4">
          {/* Swipeable gallery (Ev / Sofra / Xezîne — Ride uses Sterk-face only) */}
          {gallery.length > 0 && listing.category !== "ride" && (
            <SwipeableGallery urls={gallery} title={listing.title} />
          )}

          {/* Host card */}
          <div className="rounded-xl border border-amber-400/20 bg-white/[0.03] p-3">
            <div className="flex items-center gap-3">
              <SterkFace
                avatarUrl={listing.host?.avatar_url}
                displayName={listing.host?.display_name}
                kekaScore={reputation}
                kurdId={listing.host?.kurd_id}
                size={64}
                showAura={false}
              />
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5">
                  <div className="text-[12px] font-bold text-amber-100 truncate">
                    {listing.host?.display_name ?? "Egemen"}
                  </div>
                  {listing.host?.is_verified && (
                    <ShieldCheck className="w-3 h-3 text-cyan-300" />
                  )}
                </div>
                <div className="text-[10px] font-mono opacity-60 truncate">
                  {listing.host?.kurd_id ?? "+777 — — — —"}
                </div>
              </div>
              <div className="flex items-center gap-1 px-2 py-1 rounded-full bg-amber-400/15 border border-amber-400/30">
                <Sparkles className="w-3 h-3 text-amber-300" />
                <span className="text-[11px] font-bold text-amber-200 tabular-nums">
                  {reputation}
                </span>
              </div>
            </div>
          </div>

          {/* Meta */}
          <div className="grid grid-cols-2 gap-2">
            <Meta icon={<MapPin className="w-3 h-3" />} label="Şehir" value={listing.city || "—"} />
            <Meta
              icon={<Users className="w-3 h-3" />}
              label="Kapasite"
              value={`${listing.capacity}`}
            />
          </div>

          {listing.description && (
            <div className="rounded-xl border border-white/10 bg-white/[0.02] p-3">
              <div className="text-[9px] font-mono uppercase tracking-widest opacity-50 mb-1.5">
                Açıklama
              </div>
              <div className="text-[12px] leading-relaxed whitespace-pre-wrap">
                {listing.description}
              </div>
            </div>
          )}

          {/* Reputation note */}
          <div className="rounded-xl border border-cyan-400/20 bg-cyan-400/5 p-3">
            <div className="text-[10px] font-mono uppercase tracking-widest text-cyan-300/80 mb-1">
              Eşleşme: İtibar Tabanlı
            </div>
            <div className="text-[11px] opacity-70 leading-relaxed">
              Bu modülde fiyat yoktur. Talebin host'un KEKA itibarına ve sözüne bakar. Tamamlanan
              karşılaşmalardan sonra "Seal the Deal" ekranında onur puanı verirsin.
            </div>
          </div>

          {/* Action */}
          {isOwn ? (
            <div className="text-[11px] text-amber-300/70 font-mono text-center py-2">
              Bu sizin ilanınız.
            </div>
          ) : (
            <>
              <Textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Selam — kendini kısaca tanıt, ne zaman ihtiyacın olduğunu söyle…"
                maxLength={400}
                className="bg-white/5 border-amber-400/20 min-h-[80px]"
              />
              <button
                onClick={submit}
                disabled={busy || !message.trim()}
                className="w-full px-4 py-3 rounded-xl bg-gradient-to-r from-amber-500 to-amber-300 text-black font-bold tracking-wider uppercase text-[12px] disabled:opacity-40 active:scale-[0.98]"
              >
                {busy ? "Gönderiliyor…" : "Eşleşme Talebi Gönder"}
              </button>
            </>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

/* -------------------------------------------------------------------------- */
/* Swipeable gallery — horizontal snap with dots + tap arrows                  */
/* -------------------------------------------------------------------------- */
function SwipeableGallery({ urls, title }: { urls: string[]; title: string }) {
  const [index, setIndex] = useState(0);
  const trackRef = (el: HTMLDivElement | null) => {
    // no-op — kept for symmetry; we drive the scroll via state below.
    if (!el) return;
  };

  const go = (i: number) => {
    const next = Math.max(0, Math.min(urls.length - 1, i));
    setIndex(next);
  };

  return (
    <div className="relative rounded-2xl overflow-hidden border border-amber-400/25 bg-black/40 shadow-[0_4px_20px_rgba(0,0,0,0.45)]">
      <div
        ref={trackRef}
        className="flex overflow-x-auto snap-x snap-mandatory no-scrollbar"
        onScroll={(e) => {
          const w = e.currentTarget.clientWidth;
          if (!w) return;
          const i = Math.round(e.currentTarget.scrollLeft / w);
          if (i !== index) setIndex(i);
        }}
        style={{ aspectRatio: "16 / 10", touchAction: "pan-x pan-y" }}
      >
        {urls.map((u, i) => (
          <div
            key={u + i}
            className="snap-start shrink-0 w-full h-full relative"
          >
            <img
              src={u}
              alt={`${title} — ${i + 1}/${urls.length}`}
              className="absolute inset-0 w-full h-full object-cover"
              loading={i === 0 ? "eager" : "lazy"}
            />
          </div>
        ))}
      </div>

      {/* Counter pill */}
      <div className="absolute top-2 right-2 px-2 py-0.5 rounded-full bg-black/70 border border-amber-300/30 text-[10px] font-mono font-bold text-amber-100">
        {index + 1} / {urls.length}
      </div>

      {/* Arrows (visible on >1 photo) */}
      {urls.length > 1 && (
        <>
          <button
            type="button"
            onClick={() => {
              const next = index - 1;
              if (next < 0) return;
              const track = (document.activeElement as HTMLElement)?.closest(".relative")?.querySelector(".snap-x") as HTMLElement | null;
              if (track) track.scrollTo({ left: next * track.clientWidth, behavior: "smooth" });
              go(next);
            }}
            className={cn(
              "absolute left-2 top-1/2 -translate-y-1/2 h-8 w-8 rounded-full bg-black/70 border border-amber-300/40 flex items-center justify-center text-amber-200 active:scale-90 transition",
              index === 0 && "opacity-30",
            )}
            aria-label="Önceki"
            disabled={index === 0}
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
          <button
            type="button"
            onClick={() => {
              const next = index + 1;
              if (next >= urls.length) return;
              const track = (document.activeElement as HTMLElement)?.closest(".relative")?.querySelector(".snap-x") as HTMLElement | null;
              if (track) track.scrollTo({ left: next * track.clientWidth, behavior: "smooth" });
              go(next);
            }}
            className={cn(
              "absolute right-2 top-1/2 -translate-y-1/2 h-8 w-8 rounded-full bg-black/70 border border-amber-300/40 flex items-center justify-center text-amber-200 active:scale-90 transition",
              index === urls.length - 1 && "opacity-30",
            )}
            aria-label="Sonraki"
            disabled={index === urls.length - 1}
          >
            <ChevronRight className="h-4 w-4" />
          </button>

          {/* Dots */}
          <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex items-center gap-1">
            {urls.map((_, i) => (
              <span
                key={i}
                className={cn(
                  "h-1.5 rounded-full transition-all",
                  i === index ? "w-4 bg-amber-300" : "w-1.5 bg-white/40",
                )}
              />
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function Meta({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
}) {
  return (
    <div className="rounded-lg border border-white/10 bg-white/[0.02] px-3 py-2">
      <div className="flex items-center gap-1 text-[9px] font-mono uppercase tracking-widest opacity-50">
        {icon}
        {label}
      </div>
      <div className="text-[12px] font-bold text-amber-100 mt-0.5 truncate">{value}</div>
    </div>
  );
}

