/**
 * ListingFormSheet — rich create/edit form for the Mivankas provider panel.
 *
 * Supports all four categories with category-specific metadata fields and
 * the shared MivankasMediaUploader for galleries. Replaces the legacy
 * CreateListingSheet which only captured base fields.
 *
 * Modes:
 *   • create: insert a new listing
 *   • edit:   patch an existing listing (fields pre-filled from `initial`)
 */
import { useEffect, useMemo, useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Car,
  Home,
  UtensilsCrossed,
  Hammer,
  Loader2,
  MapPin,
  Crown,
  Bus,
  ShieldCheck,
  Plus,
  Trash2,
} from "lucide-react";
import type {
  CreateListingInput,
  MivankasCategory,
  MivankasListing,
  UpdateListingInput,
} from "@/hooks/useMivankas";
import type {
  HomeMeta,
  MealSlot,
  MivankasMeta,
  RideMeta,
  RideTier,
  SofraMeta,
  XezineMeta,
  XezineProduct,
  ItemCondition,
} from "@/lib/mivankasMeta";
import { TIER_LABEL } from "@/lib/mivankasMeta";
import { MivankasMediaUploader } from "./MivankasMediaUploader";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  userId: string;
  /** When set we run in EDIT mode; otherwise CREATE. */
  initial?: MivankasListing | null;
  onCreate: (input: CreateListingInput) => Promise<string | null>;
  onUpdate: (id: string, patch: UpdateListingInput) => Promise<boolean>;
  /** Called after a successful save so the parent can refresh lists. */
  onSaved?: () => void;
}

const CATEGORIES: {
  key: MivankasCategory;
  label: string;
  desc: string;
  Icon: typeof Car;
}[] = [
  { key: "ride", label: "Sürmek", desc: "Yolculuk", Icon: Car },
  { key: "home", label: "Ev", desc: "Ev / oda", Icon: Home },
  { key: "sofra", label: "Sofra", desc: "Yemek", Icon: UtensilsCrossed },
  { key: "xezine", label: "Xezîne", desc: "Eşya / katalog", Icon: Hammer },
];

const RIDE_TIERS: { key: RideTier; Icon: typeof Car }[] = [
  { key: "sovereign-x", Icon: Car },
  { key: "premium-diwan", Icon: Crown },
  { key: "van", Icon: Bus },
];

const HOME_AMENITIES = ["wifi", "heating", "kitchen", "parking", "tv", "washer"];
const SOFRA_DIETARY = ["halal", "vegan", "vegetarian", "gluten-free", "kosher"];
const SOFRA_SLOTS: MealSlot[] = ["breakfast", "lunch", "dinner"];
const ITEM_CONDITIONS: ItemCondition[] = ["new", "like-new", "good", "used"];

export function ListingFormSheet({
  open,
  onOpenChange,
  userId,
  initial,
  onCreate,
  onUpdate,
  onSaved,
}: Props) {
  const isEdit = !!initial;
  const [category, setCategory] = useState<MivankasCategory>("ride");
  const [title, setTitle] = useState("");
  const [city, setCity] = useState("");
  const [description, setDescription] = useState("");
  const [capacity, setCapacity] = useState(1);
  const [coords, setCoords] = useState<{ lat: number; lng: number } | null>(null);
  const [coverUrl, setCoverUrl] = useState<string | null>(null);
  const [gallery, setGallery] = useState<string[]>([]);
  const [meta, setMeta] = useState<MivankasMeta>({});
  const [busy, setBusy] = useState(false);
  const [locating, setLocating] = useState(false);

  // Hydrate when opened (or when `initial` switches between drafts).
  useEffect(() => {
    if (!open) return;
    if (initial) {
      setCategory(initial.category);
      setTitle(initial.title);
      setCity(initial.city);
      setDescription(initial.description);
      setCapacity(initial.capacity);
      setCoords(
        initial.latitude != null && initial.longitude != null
          ? { lat: initial.latitude, lng: initial.longitude }
          : null,
      );
      setCoverUrl(initial.cover_url ?? null);
      const m = (initial.metadata ?? {}) as MivankasMeta;
      setMeta(m);
      setGallery(
        m.home?.gallery_urls ?? m.sofra?.menu_urls ?? m.gallery_urls ?? [],
      );
    } else {
      setCategory("ride");
      setTitle("");
      setCity("");
      setDescription("");
      setCapacity(1);
      setCoords(null);
      setCoverUrl(null);
      setGallery([]);
      setMeta({});
    }
  }, [open, initial]);

  const useMyLocation = () => {
    if (!navigator.geolocation) {
      toast.error("Konum desteklenmiyor");
      return;
    }
    setLocating(true);
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        setLocating(false);
        toast.success("Konum eklendi");
      },
      () => {
        setLocating(false);
        toast.error("Konum alınamadı");
      },
      { enableHighAccuracy: true, timeout: 8000 },
    );
  };

  const finalMeta = useMemo<MivankasMeta>(() => {
    const out: MivankasMeta = { ...meta };
    if (category === "home") {
      out.home = { ...(out.home ?? {}), gallery_urls: gallery };
    } else if (category === "sofra") {
      out.sofra = { ...(out.sofra ?? {}), menu_urls: gallery };
    } else if (category === "xezine") {
      out.gallery_urls = gallery;
    } else {
      out.gallery_urls = gallery;
    }
    return out;
  }, [meta, gallery, category]);

  const submit = async () => {
    if (!title.trim() || !city.trim()) {
      toast.error("Başlık ve şehir zorunludur");
      return;
    }
    setBusy(true);
    try {
      if (isEdit && initial) {
        const ok = await onUpdate(initial.id, {
          title,
          description,
          city,
          capacity,
          cover_url: coverUrl,
          metadata: finalMeta,
        });
        if (ok) {
          toast.success("İlan güncellendi");
          onSaved?.();
          onOpenChange(false);
        }
      } else {
        const id = await onCreate({
          category,
          title,
          description,
          city,
          capacity,
          latitude: coords?.lat ?? null,
          longitude: coords?.lng ?? null,
          cover_url: coverUrl ?? gallery[0] ?? null,
          metadata: finalMeta,
        });
        if (id) {
          onSaved?.();
          onOpenChange(false);
        }
      }
    } finally {
      setBusy(false);
    }
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="bg-[#0A0A0C] border-amber-400/20 text-foreground max-h-[94vh] overflow-y-auto"
      >
        <SheetHeader className="text-left">
          <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-amber-300/70">
            Mivankas · {isEdit ? "Düzenle" : "Yeni İlan"}
          </div>
          <SheetTitle className="text-amber-100 flex items-center gap-2">
            <ShieldCheck className="h-4 w-4 text-amber-300" />
            {isEdit ? initial?.title : "Onur Ekonomisine Katıl"}
          </SheetTitle>
          <p className="text-[11px] opacity-70">
            Profesyonel detaylar — daha iyi eşleşmeler.
          </p>
        </SheetHeader>

        <div className="mt-4 space-y-5">
          {/* Category picker (locked in edit mode) */}
          <div>
            <Label>Kategori</Label>
            <div className="grid grid-cols-4 gap-2 mt-1.5">
              {CATEGORIES.map(({ key, label, desc, Icon }) => {
                const active = category === key;
                return (
                  <button
                    key={key}
                    type="button"
                    disabled={isEdit}
                    onClick={() => setCategory(key)}
                    className={cn(
                      "flex flex-col items-center gap-1 rounded-xl p-2 border transition active:scale-95",
                      active
                        ? "bg-amber-400/15 border-amber-300/60 shadow-[0_0_18px_rgba(212,175,55,0.25)]"
                        : "bg-white/[0.03] border-white/10",
                      isEdit && !active && "opacity-40",
                    )}
                  >
                    <Icon className={cn("w-4 h-4", active ? "text-amber-200" : "text-amber-300/70")} />
                    <div className={cn("text-[10px] font-bold", active ? "text-amber-100" : "text-white/70")}>
                      {label}
                    </div>
                    <div className="text-[8px] opacity-50 leading-tight text-center">{desc}</div>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Common fields */}
          <Field label="Başlık">
            <Input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={titlePlaceholder(category)}
              className="bg-white/5 border-amber-400/20"
              maxLength={80}
            />
          </Field>

          <div className="grid grid-cols-3 gap-2">
            <div className="col-span-2">
              <Field label="Şehir">
                <Input
                  value={city}
                  onChange={(e) => setCity(e.target.value)}
                  placeholder="Köln"
                  className="bg-white/5 border-amber-400/20"
                  maxLength={60}
                />
              </Field>
            </div>
            <div>
              <Field label="Kapasite">
                <Input
                  type="number"
                  min={1}
                  max={20}
                  value={capacity}
                  onChange={(e) => setCapacity(Math.max(1, Number(e.target.value) || 1))}
                  className="bg-white/5 border-amber-400/20"
                />
              </Field>
            </div>
          </div>

          <Field label="Açıklama">
            <Textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Detaylar, koşullar, müsaitlik…"
              className="bg-white/5 border-amber-400/20 min-h-[80px]"
              maxLength={500}
            />
          </Field>

          {/* Category-specific blocks */}
          {category === "ride" && (
            <RideFields
              meta={meta.ride ?? {}}
              onChange={(ride) => setMeta((m) => ({ ...m, ride }))}
            />
          )}
          {category === "home" && (
            <HomeFields
              meta={meta.home ?? {}}
              onChange={(home) => setMeta((m) => ({ ...m, home }))}
            />
          )}
          {category === "sofra" && (
            <SofraFields
              meta={meta.sofra ?? {}}
              onChange={(sofra) => setMeta((m) => ({ ...m, sofra }))}
            />
          )}
          {category === "xezine" && (
            <XezineFields
              meta={meta.xezine ?? {}}
              onChange={(xezine) => setMeta((m) => ({ ...m, xezine }))}
            />
          )}

          {/* Media gallery (all categories) */}
          <MivankasMediaUploader
            userId={userId}
            value={gallery}
            onChange={(urls) => {
              setGallery(urls);
              if (!coverUrl && urls[0]) setCoverUrl(urls[0]);
            }}
            folder={initial?.id ?? "drafts"}
            label={category === "sofra" ? "Menü fotoğrafları" : "Galeri"}
          />

          {/* Geo (only meaningful in create mode for now) */}
          {!isEdit && (
            <button
              type="button"
              onClick={useMyLocation}
              disabled={locating}
              className="flex items-center gap-2 w-full px-3 py-2.5 rounded-xl bg-cyan-400/10 border border-cyan-400/30 text-cyan-100 text-[12px] font-bold hover:bg-cyan-400/15 disabled:opacity-50"
            >
              {locating ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <MapPin className="w-3.5 h-3.5" />
              )}
              {coords
                ? `Konum eklendi (${coords.lat.toFixed(3)}, ${coords.lng.toFixed(3)})`
                : "Mevcut konumumu kullan"}
            </button>
          )}

          <button
            onClick={submit}
            disabled={busy}
            className="w-full px-4 py-3 rounded-xl bg-gradient-to-r from-amber-500 to-amber-300 text-black font-bold tracking-wider uppercase text-[12px] disabled:opacity-50 active:scale-[0.98] flex items-center justify-center gap-2"
          >
            {busy && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
            {isEdit ? "Mührü Güncelle" : "İlanı Mühürle"}
          </button>
        </div>
      </SheetContent>
    </Sheet>
  );
}

