function XezineFields({
  meta,
  onChange,
}: {
  meta: XezineMeta;
  onChange: (m: XezineMeta) => void;
}) {
  const products = meta.products ?? [];
  const updateProduct = (idx: number, patch: Partial<XezineProduct>) => {
    const next = products.map((p, i) => (i === idx ? { ...p, ...patch } : p));
    onChange({ ...meta, products: next });
  };
  const addProduct = () => {
    onChange({
      ...meta,
      products: [...products, { name: "", condition: "good" }],
    });
  };
  const removeProduct = (idx: number) => {
    onChange({ ...meta, products: products.filter((_, i) => i !== idx) });
  };
  return (
    <Section title="Xezîne · Katalog">
      <Field label="Pickup adresi">
        <Input
          value={meta.pickup_address ?? ""}
          onChange={(e) => onChange({ ...meta, pickup_address: e.target.value })}
          placeholder="Mahalle / sokak"
          className="bg-white/5 border-amber-400/20"
        />
      </Field>
      <Field label="Teslim saatleri">
        <Input
          value={meta.pickup_hours ?? ""}
          onChange={(e) => onChange({ ...meta, pickup_hours: e.target.value })}
          placeholder="10:00–20:00"
          className="bg-white/5 border-amber-400/20"
        />
      </Field>
      <ToggleRow
        active={!!meta.shipping_available}
        onChange={(v) => onChange({ ...meta, shipping_available: v })}
        label="Kargo gönderebilirim"
      />

      <div>
        <div className="flex items-center justify-between mb-1.5">
          <Label>Ürünler · {products.length}</Label>
          <button
            type="button"
            onClick={addProduct}
            className="h-7 px-2.5 rounded-full bg-amber-400/15 border border-amber-300/40 text-amber-100 text-[10px] font-bold uppercase tracking-wider active:scale-95 inline-flex items-center gap-1"
          >
            <Plus className="h-3 w-3" />
            Ürün
          </button>
        </div>
        <div className="space-y-2">
          {products.map((p, idx) => (
            <div
              key={idx}
              className="rounded-xl border border-amber-400/20 bg-white/[0.03] p-2 space-y-1.5"
            >
              <div className="flex gap-1.5">
                <Input
                  value={p.name}
                  onChange={(e) => updateProduct(idx, { name: e.target.value })}
                  placeholder="Ürün adı"
                  className="bg-white/5 border-amber-400/20 h-9"
                />
                <button
                  type="button"
                  onClick={() => removeProduct(idx)}
                  className="h-9 w-9 rounded-lg bg-red-500/10 border border-red-400/30 text-red-300 active:scale-95 flex items-center justify-center shrink-0"
                  aria-label="Sil"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
              <div className="flex gap-1.5">
                <select
                  value={p.condition}
                  onChange={(e) =>
                    updateProduct(idx, { condition: e.target.value as ItemCondition })
                  }
                  className="flex-1 h-9 rounded-lg bg-white/5 border border-amber-400/20 text-[12px] text-amber-100 px-2"
                >
                  {ITEM_CONDITIONS.map((c) => (
                    <option key={c} value={c} className="bg-[#0A0A0C]">
                      {c}
                    </option>
                  ))}
                </select>
                <Input
                  type="number"
                  min={0}
                  value={p.price_dc ?? ""}
                  onChange={(e) =>
                    updateProduct(idx, {
                      price_dc: e.target.value ? Number(e.target.value) : undefined,
                    })
                  }
                  placeholder="DC"
                  className="bg-white/5 border-amber-400/20 h-9 w-20"
                />
              </div>
            </div>
          ))}
          {products.length === 0 && (
            <div className="rounded-xl border border-dashed border-amber-400/20 bg-white/[0.02] py-4 text-center text-[11px] opacity-60">
              Henüz ürün yok — “Ürün” ile ekle.
            </div>
          )}
        </div>
      </div>
    </Section>
  );
}

