function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="rounded-2xl border border-amber-400/15 bg-amber-400/[0.02] p-3 space-y-3">
      <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-amber-300/70">
        {title}
      </div>
      {children}
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <Label>{label}</Label>
      <div className="mt-1">{children}</div>
    </div>
  );
}

function Label({ children }: { children: React.ReactNode }) {
  return (
    <label className="text-[9px] font-mono uppercase tracking-widest text-amber-300/70">
      {children}
    </label>
  );
}

function ToggleRow({
  active,
  onChange,
  label,
  hint,
}: {
  active: boolean;
  onChange: (v: boolean) => void;
  label: string;
  hint?: string;
}) {
  return (
    <button
      type="button"
      onClick={() => onChange(!active)}
      className={cn(
        "w-full flex items-center gap-3 px-3 py-2.5 rounded-xl border text-left active:scale-[0.99]",
        active
          ? "bg-emerald-400/10 border-emerald-300/40"
          : "bg-white/[0.03] border-white/10",
      )}
    >
      <span
        className={cn(
          "h-5 w-9 rounded-full p-0.5 transition flex",
          active ? "bg-emerald-400/70" : "bg-white/15",
        )}
      >
        <span
          className={cn(
            "h-4 w-4 rounded-full bg-white shadow transition",
            active ? "translate-x-4" : "translate-x-0",
          )}
        />
      </span>
      <span className="flex-1">
        <span
          className={cn(
            "block text-[12px] font-bold",
            active ? "text-emerald-100" : "text-amber-100/85",
          )}
        >
          {label}
        </span>
        {hint && <span className="block text-[10px] opacity-60">{hint}</span>}
      </span>
    </button>
  );
}

function titlePlaceholder(c: MivankasCategory): string {
  switch (c) {
