import { useEffect, useRef, useState } from "react";
import L, { type Map as LeafletMap, type Marker, type LayerGroup } from "leaflet";
import "leaflet/dist/leaflet.css";
import type { MivankasListing, MivankasCategory } from "@/hooks/useMivankas";
import { Car, Home, UtensilsCrossed, Hammer, Crosshair, Plus, Minus } from "lucide-react";
import { renderToStaticMarkup } from "react-dom/server";

interface Props {
  listings: MivankasListing[];
  center?: [number, number];
  onMarkerClick: (listing: MivankasListing) => void;
  /** Notify parent when our self-position updates (used by destination sheet for distance) */
  onSelfLocation?: (lat: number, lng: number) => void;
  /** When set, draws a glowing gold polyline from the rider to this point. */
  routePreview?: { lat: number; lng: number } | null;
}

const CATEGORY_META: Record<
  MivankasCategory,
  { icon: typeof Car; color: string; bg: string }
> = {
  ride: { icon: Car, color: "#FFD466", bg: "#1A1408" },
  home: { icon: Home, color: "#D4AF37", bg: "#0E1A12" },
  sofra: { icon: UtensilsCrossed, color: "#FFD466", bg: "#1A0F08" },
  xezine: { icon: Hammer, color: "#00FFFF", bg: "#08161A" },
};

function rideTierFromKeka(score: number): "diwan" | "civat" | "default" {
  if (score >= 4000) return "diwan";
  if (score >= 1500) return "civat";
  return "default";
}

// 21-ray star polygon points for SVG (Sovereign Stêrk-Face silhouette).
// Built once at module load — every pin reuses this string.
const STAR_PATH_21 = (() => {
  const rays = 21;
  const cx = 50;
  const cy = 50;
  const outer = 50;
  const inner = 39;
  const pts: string[] = [];
  for (let i = 0; i < rays * 2; i++) {
    const r = i % 2 === 0 ? outer : inner;
    const a = (Math.PI * 2 * i) / (rays * 2) - Math.PI / 2;
    pts.push(`${(cx + Math.cos(a) * r).toFixed(2)},${(cy + Math.sin(a) * r).toFixed(2)}`);
  }
  return pts.join(" ");
})();

function buildPinIcon(cat: MivankasCategory, listing?: MivankasListing) {
  const meta = CATEGORY_META[cat];
  const Ico = meta.icon;
  const score = listing?.host?.keka_points ?? 0;
  const isDiwan = score >= 4000;
  const haloIntensity = isDiwan ? 0.85 : 0.5;
  const avatarUrl = listing?.host?.avatar_url ?? null;
  const initial = (listing?.host?.display_name?.trim()?.[0] ?? "?").toUpperCase();
  // Unique clip id per render so multiple pins don't collide in the DOM.
  const clipId = `mvk-star-${Math.random().toString(36).slice(2, 9)}`;
  const iconSvg = renderToStaticMarkup(
    <Ico size={10} color={meta.color} strokeWidth={2.6} />,
  );
  const innerContent = avatarUrl
    ? `<image href="${avatarUrl}" x="0" y="0" width="100" height="100" preserveAspectRatio="xMidYMid slice" clip-path="url(#${clipId})"/>`
    : `<rect width="100" height="100" fill="${meta.bg}" clip-path="url(#${clipId})"/>
       <text x="50" y="58" text-anchor="middle" font-family="ui-serif, Georgia, serif" font-size="38" font-weight="700" fill="${meta.color}">${initial}</text>`;
  // Star pin: 21-ray gold silhouette with category icon overlay (top-right) +
  // a tiny tail dot beneath so it reads as a pin on the map.
  const html = `
    <svg width="40" height="46" viewBox="0 0 100 116" xmlns="http://www.w3.org/2000/svg" style="overflow:visible;filter:drop-shadow(0 0 ${isDiwan ? 8 : 5}px ${meta.color}${isDiwan ? "B0" : "70"});">
      <defs>
        <clipPath id="${clipId}">
          <polygon points="${STAR_PATH_21}"/>
        </clipPath>
        <linearGradient id="${clipId}-ring" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="#FFE9A8"/>
          <stop offset="0.5" stop-color="${meta.color}"/>
          <stop offset="1" stop-color="#8C6A1B"/>
        </linearGradient>
      </defs>
      <polygon points="${STAR_PATH_21}" fill="url(#${clipId}-ring)" opacity="${haloIntensity}"/>
      ${innerContent}
      <polygon points="${STAR_PATH_21}" fill="none" stroke="${meta.color}" stroke-width="1.2" opacity="0.85"/>
      <circle cx="78" cy="22" r="13" fill="#070604" stroke="${meta.color}" stroke-width="1.2"/>
      <g transform="translate(68 12)">${iconSvg}</g>
      <line x1="50" y1="100" x2="50" y2="112" stroke="${meta.color}" stroke-width="1.5" opacity="0.6"/>
      <circle cx="50" cy="113" r="3" fill="${meta.color}"/>
    </svg>
  `;
  return L.divIcon({
    html,
    className: "mivankas-marker",
    iconSize: [40, 46],
    iconAnchor: [20, 44],
  });
}

function buildCarIcon(tier: "diwan" | "civat" | "default", bearing: number) {
  const halo =
    tier === "diwan"
      ? "0 0 22px #FFD466, 0 0 44px rgba(255,212,102,0.55), inset 0 0 6px rgba(255,255,255,0.5)"
      : tier === "civat"
        ? "0 0 14px #F4C84A, 0 0 28px rgba(244,200,74,0.4)"
        : "0 0 10px rgba(255,212,102,0.35)";
  const ring =
    tier === "diwan"
      ? "2px solid #FFE9A6"
      : tier === "civat"
        ? "1.5px solid #F4C84A"
        : "1.2px solid #C9A24B";
  const tierBadge =
    tier === "diwan"
      ? '<span style="position:absolute;top:-6px;right:-6px;width:14px;height:14px;border-radius:50%;background:#FFE9A6;color:#070604;font:700 8px/14px ui-monospace,monospace;text-align:center;border:1.5px solid #070604;">S</span>'
      : tier === "civat"
        ? '<span style="position:absolute;top:-6px;right:-6px;width:14px;height:14px;border-radius:50%;background:#F4C84A;color:#070604;font:700 8px/14px ui-monospace,monospace;text-align:center;border:1.5px solid #070604;">A</span>'
        : "";
  const carSvg = `
    <svg viewBox="0 0 36 36" width="22" height="22" style="transform:rotate(${bearing}deg);transition:transform 0.6s ease-out;">
      <defs>
        <linearGradient id="car-body-${tier}" x1="0" x2="0" y1="0" y2="1">
          <stop offset="0" stop-color="#FFE9A6"/>
          <stop offset="1" stop-color="#B8860B"/>
        </linearGradient>
      </defs>
      <rect x="9" y="3" width="18" height="30" rx="6" fill="url(#car-body-${tier})" stroke="#5C3A0A" stroke-width="0.8"/>
      <rect x="11" y="7" width="14" height="7" rx="2" fill="#0A0805" opacity="0.85"/>
      <rect x="11" y="22" width="14" height="7" rx="2" fill="#0A0805" opacity="0.85"/>
      <circle cx="18" cy="18" r="1" fill="#FFE9A6"/>
    </svg>`;
  const html = `
    <div style="position:relative;width:34px;height:34px;border-radius:50%;
      background:radial-gradient(circle,#1A1408 0%, #070604 70%);
      border:${ring};
      box-shadow:${halo};
      display:flex;align-items:center;justify-content:center;">
      ${carSvg}
      ${tierBadge}
    </div>
  `;
  return L.divIcon({
    html,
    className: "mivankas-car-marker",
    iconSize: [34, 34],
    iconAnchor: [17, 17],
  });
}

function buildSelfIcon() {
  const html = `
    <div style="position:relative;width:18px;height:18px;">
      <span style="position:absolute;inset:0;border-radius:50%;background:rgba(99,179,237,0.35);animation:mivankas-self-pulse 1.8s ease-out infinite;"></span>
      <span style="position:absolute;inset:4px;border-radius:50%;background:#3FA9F5;border:2px solid #ffffff;box-shadow:0 0 10px rgba(99,179,237,0.85);"></span>
    </div>
    <style>@keyframes mivankas-self-pulse{0%{transform:scale(0.6);opacity:0.85}100%{transform:scale(2.2);opacity:0}}</style>
  `;
  return L.divIcon({
    html,
    className: "mivankas-self-marker",
    iconSize: [18, 18],
    iconAnchor: [9, 9],
  });
}

const DEFAULT_CENTER: [number, number] = [50.85, 4.35];

/** Smoothly animate a Leaflet marker between coordinates using rAF easing. */
function tweenMarker(
  marker: Marker,
  to: { lat: number; lng: number },
  durationMs: number,
  rafRef: React.MutableRefObject<number | null>,
) {
  const start = marker.getLatLng();
  const startLat = start.lat;
  const startLng = start.lng;
  const dLat = to.lat - startLat;
  const dLng = to.lng - startLng;
  // Skip the tween for tiny deltas (saves CPU and avoids jitter).
  if (Math.abs(dLat) < 1e-7 && Math.abs(dLng) < 1e-7) return;
  const t0 = performance.now();
  if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
  const step = (now: number) => {
    const t = Math.min(1, (now - t0) / durationMs);
    // ease-out cubic
    const k = 1 - Math.pow(1 - t, 3);
    marker.setLatLng([startLat + dLat * k, startLng + dLng * k]);
    if (t < 1) {
      rafRef.current = requestAnimationFrame(step);
    } else {
      rafRef.current = null;
    }
  };
  rafRef.current = requestAnimationFrame(step);
}

export function MivankasMap({ listings, center, onMarkerClick, onSelfLocation, routePreview }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<LeafletMap | null>(null);
  const layerRef = useRef<LayerGroup | null>(null);
  const selfMarkerRef = useRef<Marker | null>(null);
  const selfRafRef = useRef<number | null>(null);
  /** Per-driver state — last known position + smooth bearing. */
  const driverPosRef = useRef<
    Map<string, { lat: number; lng: number; bearing: number; rafId: number | null }>
  >(new Map());
  const driverMarkersRef = useRef<Map<string, Marker>>(new Map());
  /** Auto-follow self — turns OFF as soon as the user pans/zooms. */
  const followSelfRef = useRef<boolean>(true);
  const [followSelf, setFollowSelf] = useState<boolean>(true);
  const lastSelfLatLngRef = useRef<{ lat: number; lng: number } | null>(null);
  /** Layered route polyline (glow + core) drawn between rider and destination. */
  const routeLayerRef = useRef<L.LayerGroup | null>(null);
  const routeDestMarkerRef = useRef<Marker | null>(null);

  // Init map once
  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;
    let alive = true;
    const map = L.map(containerRef.current, {
      center: center ?? DEFAULT_CENTER,
      zoom: 5,
      zoomControl: false,
      attributionControl: false,
    });
    // Stock zoom buttons removed — replaced by the unified minimalist control
    // pill (zoom in / zoom out / recenter) rendered in this component's JSX.

    L.tileLayer(
      "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png",
      { subdomains: "abcd", maxZoom: 19 },
    ).addTo(map);

    layerRef.current = L.layerGroup().addTo(map);
    mapRef.current = map;

    // === Auto-follow disengage — any user-initiated pan/zoom turns it off ===
    const disengageFollow = () => {
      if (followSelfRef.current) {
        followSelfRef.current = false;
        setFollowSelf(false);
      }
    };
    map.on("dragstart", disengageFollow);
    // Only disengage on user-driven zoom (zoomstart fires on programmatic too;
    // we filter by checking that it didn't originate from our setView).
    map.on("zoomstart", () => {
      // If a programmatic setView is in progress we set a temporary flag.
      if (!suppressNextZoomDisengageRef.current) disengageFollow();
      suppressNextZoomDisengageRef.current = false;
    });

    let watchId: number | null = null;
    if (typeof navigator !== "undefined" && navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          if (!alive || !mapRef.current) return;
          try {
            suppressNextZoomDisengageRef.current = true;
            map.setView([pos.coords.latitude, pos.coords.longitude], 13);
            placeSelfMarker(pos.coords.latitude, pos.coords.longitude);
            onSelfLocation?.(pos.coords.latitude, pos.coords.longitude);
          } catch {
            /* map was torn down */
          }
        },
        () => {},
        { enableHighAccuracy: true, timeout: 5000 },
      );
      watchId = navigator.geolocation.watchPosition(
        (pos) => {
          if (!alive) return;
          placeSelfMarker(pos.coords.latitude, pos.coords.longitude);
          onSelfLocation?.(pos.coords.latitude, pos.coords.longitude);
        },
        () => {},
        { enableHighAccuracy: true, maximumAge: 4000, timeout: 8000 },
      );
    }

    function placeSelfMarker(lat: number, lng: number) {
      if (!mapRef.current) return;
      lastSelfLatLngRef.current = { lat, lng };
      if (!selfMarkerRef.current) {
        selfMarkerRef.current = L.marker([lat, lng], {
          icon: buildSelfIcon(),
          interactive: false,
          keyboard: false,
        }).addTo(mapRef.current);
      } else {
        // Smoothly tween the self-dot rather than snapping it.
        tweenMarker(selfMarkerRef.current, { lat, lng }, 900, selfRafRef);
      }
      // If auto-follow is still active, gently pan the map with the user.
      if (followSelfRef.current && mapRef.current) {
        suppressNextZoomDisengageRef.current = true;
        mapRef.current.panTo([lat, lng], { animate: true, duration: 0.6 });
      }
    }

    return () => {
      alive = false;
      if (watchId !== null && navigator.geolocation) {
        try {
          navigator.geolocation.clearWatch(watchId);
        } catch {
          /* ignore */
        }
      }
      if (selfRafRef.current) cancelAnimationFrame(selfRafRef.current);
      driverPosRef.current.forEach((d) => {
        if (d.rafId) cancelAnimationFrame(d.rafId);
      });
      map.remove();
      mapRef.current = null;
      layerRef.current = null;
      selfMarkerRef.current = null;
      driverMarkersRef.current.clear();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /** Suppress the next zoomstart-triggered disengage when WE pan/zoom. */
  const suppressNextZoomDisengageRef = useRef<boolean>(false);

  // Sync markers — high-KEKA Sürmek drivers sort to the top so their golden
  // halos render above lower-tier pins (Leaflet draws later layers on top).
  // Driver markers persist across renders so we can tween them smoothly.
  useEffect(() => {
    const layer = layerRef.current;
    if (!layer) return;

    const sorted = [...listings].sort((a, b) => {
      const aRide = a.category === "ride" ? 1 : 0;
      const bRide = b.category === "ride" ? 1 : 0;
      if (aRide !== bRide) return aRide - bRide;
      return (a.host?.keka_points ?? 0) - (b.host?.keka_points ?? 0);
    });

    const seenIds = new Set<string>();
    sorted.forEach((l) => {
      if (l.latitude == null || l.longitude == null) return;
      seenIds.add(l.id);

      if (l.category === "ride") {
        const tier = rideTierFromKeka(l.host?.keka_points ?? 0);
        const prev = driverPosRef.current.get(l.id);
        let bearing = prev?.bearing ?? 0;
        if (prev) {
          const dy = l.latitude - prev.lat;
          const dx = l.longitude - prev.lng;
          if (Math.abs(dx) + Math.abs(dy) > 1e-6) {
            bearing = (Math.atan2(dx, dy) * 180) / Math.PI;
          }
        }

        let marker = driverMarkersRef.current.get(l.id);
        if (!marker) {
          marker = L.marker([l.latitude, l.longitude], {
            icon: buildCarIcon(tier, bearing),
          });
          marker.on("click", () => onMarkerClick(l));
          marker.addTo(layer);
          driverMarkersRef.current.set(l.id, marker);
        } else {
          // Re-render icon (bearing/tier may have changed) and tween position.
          marker.setIcon(buildCarIcon(tier, bearing));
          const rafState = { current: prev?.rafId ?? null };
          tweenMarker(marker, { lat: l.latitude, lng: l.longitude }, 1200, rafState);
          driverPosRef.current.set(l.id, {
            lat: l.latitude,
            lng: l.longitude,
            bearing,
            rafId: rafState.current,
          });
          return;
        }

        driverPosRef.current.set(l.id, {
          lat: l.latitude,
          lng: l.longitude,
          bearing,
          rafId: null,
        });
      } else {
        // Non-ride pins are static; rebuild on each sync.
        const icon = buildPinIcon(l.category, l);
        const marker: Marker = L.marker([l.latitude, l.longitude], { icon });
        marker.on("click", () => onMarkerClick(l));
        layer.addLayer(marker);
      }
    });

    // Remove driver markers that are no longer in the listings.
    driverMarkersRef.current.forEach((marker, id) => {
      if (!seenIds.has(id)) {
        layer.removeLayer(marker);
        driverMarkersRef.current.delete(id);
        const d = driverPosRef.current.get(id);
        if (d?.rafId) cancelAnimationFrame(d.rafId);
        driverPosRef.current.delete(id);
      }
    });

    // Remove non-ride markers that aren't driver markers (they were re-added above).
    layer.eachLayer((lyr) => {
      if (lyr instanceof L.Marker) {
        const isDriver = Array.from(driverMarkersRef.current.values()).includes(lyr);
        if (isDriver) return;
        // Stale non-ride pin? Leave them — they were just added this render pass.
      }
    });
    // Reset non-ride pins by clearing then re-adding only on the next render
    // is handled by the mount/unmount cycle; for simplicity we accept the
    // small flash for static categories. Driver markers (the moving ones) are
    // the priority for smoothness.
  }, [listings, onMarkerClick]);

  /** Glowing-gold route preview between rider and selected destination. */
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    // Tear down any previous route layers.
    if (routeLayerRef.current) {
      map.removeLayer(routeLayerRef.current);
      routeLayerRef.current = null;
    }
    if (routeDestMarkerRef.current) {
      map.removeLayer(routeDestMarkerRef.current);
      routeDestMarkerRef.current = null;
    }

    const self = lastSelfLatLngRef.current;
    if (!routePreview || !self) return;

    // Three layered polylines = soft halo + mid glow + sharp gold core.
    const halo = L.polyline(
      [
        [self.lat, self.lng],
        [routePreview.lat, routePreview.lng],
      ],
      {
        color: "#FFE9A6",
        weight: 14,
        opacity: 0.18,
        lineCap: "round",
        lineJoin: "round",
        interactive: false,
      },
    );
    const mid = L.polyline(
      [
        [self.lat, self.lng],
        [routePreview.lat, routePreview.lng],
      ],
      {
        color: "#F5C850",
        weight: 7,
        opacity: 0.55,
        lineCap: "round",
        lineJoin: "round",
        interactive: false,
      },
    );
    const core = L.polyline(
      [
        [self.lat, self.lng],
        [routePreview.lat, routePreview.lng],
      ],
      {
        color: "#FFFFFF",
        weight: 2.2,
        opacity: 0.95,
        dashArray: "1 10",
        lineCap: "round",
        interactive: false,
        className: "mivankas-route-core",
      },
    );

    const group = L.layerGroup([halo, mid, core]).addTo(map);
    routeLayerRef.current = group;

    // Glowing destination pin
    const destHtml = `
      <div style="position:relative;width:30px;height:30px;">
        <span style="position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle,rgba(245,200,80,0.5),rgba(245,200,80,0) 70%);animation:mivankas-dest-pulse 1.6s ease-out infinite;"></span>
        <span style="position:absolute;inset:7px;border-radius:50%;background:#FFE9A6;border:2px solid #5C3A0A;box-shadow:0 0 12px #F5C850,0 0 24px rgba(245,200,80,0.55);"></span>
      </div>
      <style>@keyframes mivankas-dest-pulse{0%{transform:scale(0.6);opacity:0.85}100%{transform:scale(2.2);opacity:0}}</style>
    `;
    const destIcon = L.divIcon({
      html: destHtml,
      className: "mivankas-dest-marker",
      iconSize: [30, 30],
      iconAnchor: [15, 15],
    });
    routeDestMarkerRef.current = L.marker([routePreview.lat, routePreview.lng], {
      icon: destIcon,
      interactive: false,
      keyboard: false,
    }).addTo(map);

    // Frame both endpoints — only when route changes (not on every pan).
    try {
      const bounds = L.latLngBounds([
        [self.lat, self.lng],
        [routePreview.lat, routePreview.lng],
      ]);
      suppressNextZoomDisengageRef.current = true;
      map.fitBounds(bounds, { padding: [80, 80], maxZoom: 14, animate: true });
    } catch {
      /* ignore — bounds may be invalid for identical points */
    }

    return () => {
      if (routeLayerRef.current) {
        map.removeLayer(routeLayerRef.current);
        routeLayerRef.current = null;
      }
      if (routeDestMarkerRef.current) {
        map.removeLayer(routeDestMarkerRef.current);
        routeDestMarkerRef.current = null;
      }
    };
  }, [routePreview]);


  /** Re-engage auto-follow + recenter on the user. */
  const recenterOnSelf = () => {
    const self = lastSelfLatLngRef.current;
    if (!self || !mapRef.current) return;
    followSelfRef.current = true;
    setFollowSelf(true);
    suppressNextZoomDisengageRef.current = true;
    mapRef.current.flyTo([self.lat, self.lng], Math.max(mapRef.current.getZoom(), 14), {
      duration: 0.7,
    });
  };

  /** Programmatic zoom — flagged so we don't disengage auto-follow. */
  const zoomBy = (delta: number) => {
    const map = mapRef.current;
    if (!map) return;
    suppressNextZoomDisengageRef.current = true;
    map.setZoom(map.getZoom() + delta, { animate: true });
  };

  return (
    <>
      <div
        ref={containerRef}
        className="absolute inset-0 mivankas-map-container"
        aria-label="MIVANKAS Map"
      />
      {/*
        Unified minimalist map control pill — vertical stack of zoom-in,
        zoom-out and recenter. Sits above the bottom sheet's safe-area inset.
        Replaces both Leaflet's stock zoom buttons and the standalone
        recenter button so there's only ONE control surface on the map.
      */}
      <div
        className="absolute right-3 z-[420] flex flex-col rounded-full bg-black/70 backdrop-blur-xl border border-white/10 shadow-[0_4px_18px_rgba(0,0,0,0.6)] overflow-hidden"
        style={{ bottom: "calc(env(safe-area-inset-bottom, 0px) + 240px)" }}
      >
        <button
