  routePreview?: { lat: number; lng: number } | null;
}

// Lazy import keeps `leaflet` (which references `window` at module top) out of
// the SSR bundle. The component is only loaded in the browser.
const MivankasMap = lazy(() =>
  import("./MivankasMap").then((m) => ({ default: m.MivankasMap })),
);

export function MivankasMapClient(props: Props) {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

