/**
 * MivankasMediaUploader — drag-free, mobile-first multi-image uploader for
 * the provider panel. Files are pushed to the public `mivankas-media` bucket
 * under `<userId>/<listingDraftId>/...` so the storage RLS policy
 * (folder-must-equal-uid) is satisfied.
 *
 * Returns the list of public URLs to the parent. The first URL is treated as
 * the cover photo. Users can:
 *   • Reorder photos via ◀ / ▶ buttons (mobile-friendly, no drag library).
 *   • Promote any photo to the cover via the ★ button (moves it to index 0).
 *   • Remove individual photos.
 */
import { useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Camera, ChevronLeft, ChevronRight, Loader2, Plus, Star, Trash2 } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface Props {
  userId: string;
  /** Current list of public URLs (controlled). First entry = cover. */
  value: string[];
  onChange: (urls: string[]) => void;
  /** Folder under `<uid>/` — usually a draft id or the listing id. */
  folder?: string;
  max?: number;
  label?: string;
}

export function MivankasMediaUploader({
  userId,
  value,
  onChange,
  folder = "drafts",
  max = 8,
  label = "Galeri",
}: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);

  const pick = () => inputRef.current?.click();

  const handleFiles = async (files: FileList | null) => {
    if (!files || files.length === 0) return;
    if (value.length + files.length > max) {
      toast.error(`En fazla ${max} fotoğraf yükleyebilirsin`);
      return;
    }
    setBusy(true);
    try {
      const next: string[] = [];
      for (const file of Array.from(files)) {
        if (!file.type.startsWith("image/")) {
          toast.error("Sadece görsel dosya yükleyebilirsin");
          continue;
        }
        if (file.size > 6 * 1024 * 1024) {
          toast.error(`${file.name} 6 MB'den büyük`);
          continue;
        }
        const ext = file.name.split(".").pop() ?? "jpg";
        const path = `${userId}/${folder}/${crypto.randomUUID()}.${ext}`;
        const { error } = await supabase.storage
          .from("mivankas-media")
          .upload(path, file, { upsert: false, contentType: file.type });
        if (error) {
          toast.error("Yüklenemedi: " + error.message);
          continue;
        }
        const { data } = supabase.storage.from("mivankas-media").getPublicUrl(path);
        next.push(data.publicUrl);
      }
      if (next.length) onChange([...value, ...next]);
    } finally {
      setBusy(false);
      if (inputRef.current) inputRef.current.value = "";
    }
  };

  const removeAt = (i: number) => onChange(value.filter((_, idx) => idx !== i));

  const move = (from: number, to: number) => {
    if (to < 0 || to >= value.length) return;
    const next = [...value];
    const [item] = next.splice(from, 1);
    next.splice(to, 0, item);
    onChange(next);
  };

  const makeCover = (i: number) => {
    if (i === 0) return;
    const next = [...value];
    const [item] = next.splice(i, 1);
    next.unshift(item);
    onChange(next);
    toast.success("Kapak fotoğrafı güncellendi");
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-1.5">
        <label className="text-[9px] font-mono uppercase tracking-widest text-amber-300/70">
          {label} · {value.length}/{max}
        </label>
        <div className="flex items-center gap-2">
          {value.length > 1 && (
            <span className="text-[8px] font-mono text-amber-300/60 uppercase tracking-wider">
              ★ kapak · ◀▶ sırala
            </span>
          )}
          {busy && <Loader2 className="h-3 w-3 text-amber-300 animate-spin" />}
        </div>
      </div>
      <div className="grid grid-cols-3 gap-2">
        {value.map((url, i) => {
          const isCover = i === 0;
          return (
            <div
              key={url + i}
              className={cn(
                "relative aspect-square rounded-lg overflow-hidden border bg-black/40 group",
                isCover
                  ? "border-amber-300/70 shadow-[0_0_14px_rgba(212,175,55,0.35)]"
                  : "border-amber-400/20",
              )}
            >
              <img
                src={url}
                alt={isCover ? "Kapak fotoğrafı" : `Galeri fotoğrafı ${i + 1}`}
                className="absolute inset-0 w-full h-full object-cover"
              />
              {isCover && (
                <div className="absolute top-1 left-1 inline-flex items-center gap-0.5 rounded-full bg-amber-300/95 text-black px-1.5 py-0.5 text-[8px] font-black tracking-wider">
                  <Star className="h-2 w-2 fill-black" />
                  KAPAK
                </div>
              )}
              <button
                type="button"
                onClick={() => removeAt(i)}
                className="absolute top-1 right-1 h-5 w-5 rounded-full bg-black/80 border border-white/10 flex items-center justify-center text-red-300 active:scale-90"
                aria-label="Sil"
              >
                <Trash2 className="h-2.5 w-2.5" />
              </button>

              {/* Bottom action row */}
              <div className="absolute inset-x-0 bottom-0 flex items-center justify-between gap-1 px-1 pb-1 pt-3 bg-gradient-to-t from-black/90 via-black/50 to-transparent">
                <button
                  type="button"
                  onClick={() => move(i, i - 1)}
                  disabled={i === 0}
                  className="h-5 w-5 rounded-md bg-black/70 border border-white/15 flex items-center justify-center text-amber-200 active:scale-90 disabled:opacity-30"
                  aria-label="Sola taşı"
                >
                  <ChevronLeft className="h-3 w-3" />
                </button>
                {!isCover && (
                  <button
                    type="button"
                    onClick={() => makeCover(i)}
                    className="h-5 px-1.5 rounded-md bg-amber-400/20 border border-amber-300/50 flex items-center gap-0.5 text-amber-100 text-[8px] font-black active:scale-90"
                    aria-label="Kapak yap"
                  >
                    <Star className="h-2.5 w-2.5" />
                  </button>
                )}
                <button
                  type="button"
                  onClick={() => move(i, i + 1)}
                  disabled={i === value.length - 1}
                  className="h-5 w-5 rounded-md bg-black/70 border border-white/15 flex items-center justify-center text-amber-200 active:scale-90 disabled:opacity-30"
                  aria-label="Sağa taşı"
                >
                  <ChevronRight className="h-3 w-3" />
                </button>
              </div>
            </div>
          );
        })}
        {value.length < max && (
          <button
            type="button"
            onClick={pick}
            disabled={busy}
            className="aspect-square rounded-lg border border-dashed border-amber-400/30 bg-amber-400/5 flex flex-col items-center justify-center gap-0.5 text-amber-200/80 active:scale-95 disabled:opacity-50"
          >
            {busy ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : value.length === 0 ? (
              <Camera className="h-4 w-4" />
            ) : (
              <Plus className="h-4 w-4" />
            )}
            <span className="text-[8px] font-bold tracking-wider">EKLE</span>
          </button>
        )}
      </div>
      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        multiple
        capture="environment"
        className="hidden"
        onChange={(e) => handleFiles(e.target.files)}
      />
    </div>
  );
}

