/**
 * NearbyDriversSheet — Uber-style draggable bottom sheet that lives on
 * /mivankas. Snaps at three heights (peek / mid / full) and surfaces the
 * nearby Sovereign drivers with **live** ETA and DC price estimates that
 * recompute on every selfLocation/listing update.
 *
 * Draggable via touch + mouse (pointer events). The handle area is the
 * primary drag affordance, but the whole header is also draggable. The
 * inner list scrolls only when the sheet is at full height.
 */
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react";
import {
  Car,
  Crown,
  Bus,
  Home,
  Package,
  ShieldCheck,
  UtensilsCrossed,
} from "lucide-react";
import { cn } from "@/lib/utils";
import type { MivankasCategory, MivankasListing } from "@/hooks/useMivankas";
import { SterkFace } from "@/components/sovereign/SterkFace";
import {
  TIER_BASE_DC,
  TIER_ETA_MIN,
  type RideTier,
} from "@/lib/mivankasMeta";

interface Props {
  listings: MivankasListing[];
  selfLocation: { lat: number; lng: number } | null;
  onSelectDriver: (listing: MivankasListing) => void;
  /** Bottom offset (px) so the sheet sits above the persistent Sovereign Dock.
   *  Default = 108 (84px dock + 18px halo + 6px breathing). */
  bottomOffset?: number;
  /** Current discovery radius in km (5–10). */
  radiusKm: number;
  /** Notify parent when the rider drags the radius slider. */
  onRadiusChange: (km: number) => void;
}

type CategoryTab = MivankasCategory;
type DriverTier = "diwan" | "civat" | "egemen" | "default";

const CATEGORY_TABS: {
  key: CategoryTab;
  label: string;
  Icon: typeof Car;
}[] = [
  { key: "ride", label: "Sürmek", Icon: Car },
  { key: "home", label: "Ev", Icon: Home },
  { key: "sofra", label: "Sofra", Icon: UtensilsCrossed },
  { key: "xezine", label: "Xezîne", Icon: Package },
];

const TIER_META: Record<DriverTier, { label: string; color: string }> = {
  diwan: { label: "Dîwan", color: "text-amber-100" },
  civat: { label: "Civat", color: "text-amber-200" },
  egemen: { label: "Egemen", color: "text-amber-300" },
  default: { label: "Sovereign", color: "text-amber-300/80" },
};

function tierFromKeka(score: number): DriverTier {
  if (score >= 4000) return "diwan";
  if (score >= 1500) return "civat";
  if (score >= 500) return "egemen";
  return "default";
}

const TIER_RANK: Record<DriverTier, number> = {
  diwan: 3,
  civat: 2,
  egemen: 1,
  default: 0,
};

function distanceKm(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
) {
  const R = 6371;
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
  const lat1 = (a.lat * Math.PI) / 180;
  const lat2 = (b.lat * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.sin(dLng / 2) ** 2 * Math.cos(lat1) * Math.cos(lat2);
  return 2 * R * Math.asin(Math.sqrt(h));
}

/** Pick the most expressive RideTier from a driver's KEKA + listing. */
function rideTierFor(driver: DriverTier, capacity: number): RideTier {
  if (capacity >= 4) return "van";
  if (driver === "diwan" || driver === "civat") return "premium-diwan";
  return "sovereign-x";
}

/**
 * Live ETA + price model — pure UI estimate so it changes as drivers move.
 *  • Base ETA range from tier (minutes)
 *  • Add ~2 min per km between rider and driver
 *  • DC price = tier base * (0.9 + 0.42 * km), min 5 DC
 */
function estimate(distance: number | null, tier: RideTier) {
  const dist = distance ?? 4;
  const [lo, hi] = TIER_ETA_MIN[tier];
  const etaLo = Math.max(1, Math.round(lo + dist * 1.4));
  const etaHi = Math.max(etaLo + 2, Math.round(hi + dist * 2.2));
  const dc = Math.max(5, Math.round(TIER_BASE_DC[tier] * (0.9 + dist * 0.42)));
  return { etaLo, etaHi, dc };
}

export function NearbyDriversSheet({
  listings,
  selfLocation,
  onSelectDriver,
  bottomOffset = 108,
  radiusKm,
  onRadiusChange,
}: Props) {
  const [tab, setTab] = useState<CategoryTab>("ride");
  const wrapRef = useRef<HTMLDivElement | null>(null);

  /** Snap heights as % of viewport — peek shows just header + 1 row.
   *  Resolved at runtime so the sheet works on every device size, and we
   *  subtract iOS/Android safe-area insets + the persistent BottomNav offset
   *  so the "full" snap never crashes into the notch on iPhone or under the
   *  Android system gesture bar. */
  const [vh, setVh] = useState<number>(() =>
    typeof window !== "undefined" ? window.innerHeight : 800,
  );
  /** Read the actual safe-area-inset values from CSS env so the math matches
   *  what Safari/Chrome on the device will paint. We refresh on resize and
   *  visualViewport changes so the sheet adapts when the keyboard opens. */
  const [insets, setInsets] = useState<{ top: number; bottom: number }>({ top: 0, bottom: 0 });
  useEffect(() => {
    const readInsets = () => {
      if (typeof window === "undefined") return;
      const probe = document.createElement("div");
      probe.style.cssText =
        "position:fixed;top:0;left:0;width:0;height:0;padding-top:env(safe-area-inset-top);padding-bottom:env(safe-area-inset-bottom);visibility:hidden;pointer-events:none;";
      document.body.appendChild(probe);
      const cs = getComputedStyle(probe);
      const top = parseFloat(cs.paddingTop) || 0;
      const bottom = parseFloat(cs.paddingBottom) || 0;
      document.body.removeChild(probe);
      setInsets({ top, bottom });
    };
    const onResize = () => {
      setVh(
        window.visualViewport?.height ?? window.innerHeight,
      );
      readInsets();
    };
    readInsets();
    window.addEventListener("resize", onResize);
    window.visualViewport?.addEventListener("resize", onResize);
    return () => {
      window.removeEventListener("resize", onResize);
      window.visualViewport?.removeEventListener("resize", onResize);
    };
  }, []);

  // Snap points expressed as the sheet's *height* in px. We subtract the
  // top inset + a 12px breathing buffer so "full" stops just below the notch.
  const SNAPS = useMemo(() => {
    const usable = Math.max(360, vh - insets.top - 12);
    const peek = Math.round(usable * 0.22);
    const mid = Math.round(usable * 0.5);
    const full = Math.round(usable * 0.85);
    return { peek, mid, full };
  }, [vh, insets.top]);

  const [snap, setSnap] = useState<"peek" | "mid" | "full">("peek");
  const targetHeight = SNAPS[snap];

  /** Tap-outside collapse — if the user taps the map / dock area while the
   *  sheet is expanded, snap back to peek so the underlying surface (and
   *  especially the Sovereign Dock) never gets blocked by an open sheet. */
  useEffect(() => {
    if (snap === "peek") return;
    const onDocPointerDown = (e: PointerEvent) => {
      const t = e.target as HTMLElement | null;
      if (!t) return;
      // Ignore taps inside the sheet itself or on the dock.
      if (wrapRef.current?.contains(t)) return;
      if (t.closest("[data-sovereign-dock]")) return;
      setSnap("peek");
    };
    // Use capture so we collapse before the dock handler runs but never
    // swallow the dock tap (we don't preventDefault).
    document.addEventListener("pointerdown", onDocPointerDown, true);
    return () => document.removeEventListener("pointerdown", onDocPointerDown, true);
  }, [snap]);

  /** Live drag state — current sheet height while the user pulls. */
  const [dragHeight, setDragHeight] = useState<number | null>(null);
  const dragStartRef = useRef<{
    y: number;
    height: number;
    pointerId: number;
  } | null>(null);

  const onPointerDown = useCallback(
    (e: ReactPointerEvent) => {
      // Don't hijack touches on the inner scroll list
      if ((e.target as HTMLElement).closest("[data-no-drag]")) return;
      const start = wrapRef.current?.getBoundingClientRect();
      if (!start) return;
      dragStartRef.current = {
        y: e.clientY,
        height: start.height,
        pointerId: e.pointerId,
      };
      try {
        (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
      } catch {
        /* iOS sometimes refuses capture on synthetic events — ignore */
      }
      setDragHeight(start.height);
    },
    [],
  );

  const onPointerMove = useCallback(
    (e: ReactPointerEvent) => {
      const s = dragStartRef.current;
      if (!s || s.pointerId !== e.pointerId) return;
      const dy = e.clientY - s.y;
      const next = Math.max(SNAPS.peek - 40, Math.min(SNAPS.full + 40, s.height - dy));
      setDragHeight(next);
    },
    [SNAPS],
  );

  const onPointerUp = useCallback(
    (e: ReactPointerEvent) => {
      const s = dragStartRef.current;
      if (!s || s.pointerId !== e.pointerId) return;
      dragStartRef.current = null;
      const finalHeight = dragHeight ?? targetHeight;
      // Snap to nearest of peek/mid/full
      const candidates: Array<["peek" | "mid" | "full", number]> = [
        ["peek", SNAPS.peek],
        ["mid", SNAPS.mid],
        ["full", SNAPS.full],
      ];
      let best: "peek" | "mid" | "full" = "peek";
      let bestDist = Infinity;
      for (const [k, v] of candidates) {
        const d = Math.abs(finalHeight - v);
        if (d < bestDist) {
          bestDist = d;
          best = k;
        }
      }
      setSnap(best);
      setDragHeight(null);
    },
    [SNAPS, dragHeight, targetHeight],
  );

  // Computed rows — recomputes when listings or selfLocation change so ETA/price
  // tick down naturally as drivers move closer. Also drops listings outside the
  // active radius (only when we know where the rider is). Filtered to the
  // active category tab.
  const rows = useMemo(() => {
    const inCategory = listings.filter(
      (l) => l.category === tab && l.is_active,
    );

    const enriched = inCategory
      .map((l) => {
        const score = l.host?.keka_points ?? 0;
        const tierKey = tierFromKeka(score);
        const dist =
          selfLocation && l.latitude != null && l.longitude != null
            ? distanceKm(selfLocation, { lat: l.latitude, lng: l.longitude })
            : null;
        const rideTier = rideTierFor(tierKey, l.capacity);
        const est = estimate(dist, rideTier);
        return { listing: l, tier: tierKey, score, distanceKm: dist, est, rideTier };
      })
      // Hard radius gate — but only when we actually have a rider position.
      // Listings without coordinates always pass (we can't measure them).
      // Rides stay visible globally to mimic Uber's "drivers en route" UX.
      .filter(
        (r) =>
          tab === "ride" || r.distanceKm == null || r.distanceKm <= radiusKm,
      );

    // Meritocracy first (Dîwan ahead of Civat ahead of Egemen), then distance.
    enriched.sort((a, b) => {
      const t = TIER_RANK[b.tier] - TIER_RANK[a.tier];
      if (t !== 0) return t;
      if (a.distanceKm != null && b.distanceKm != null) {
        return a.distanceKm - b.distanceKm;
      }
      if (a.distanceKm == null && b.distanceKm != null) return 1;
      if (a.distanceKm != null && b.distanceKm == null) return -1;
      return b.score - a.score;
    });

    return enriched;
  }, [listings, selfLocation, tab, radiusKm]);

  // How many active listings each category has — drives the count badges.
  const tabCounts = useMemo(() => {
    const counts: Record<CategoryTab, number> = {
      ride: 0,
      home: 0,
      sofra: 0,
      xezine: 0,
    };
    listings.forEach((l) => {
      if (!l.is_active) return;
      if (l.category in counts) counts[l.category as CategoryTab]++;
    });
    return counts;
  }, [listings]);

  const fastestEta = rows[0]?.est.etaLo ?? null;
  // Category-aware copy so the same sheet feels native to each service.
  const tabMeta = CATEGORY_TABS.find((t) => t.key === tab) ?? CATEGORY_TABS[0];
  const unitWord =
    tab === "ride"
      ? "sürücü"
      : tab === "home"
        ? "ev"
        : tab === "sofra"
          ? "sofra"
          : "ilan";
  const emptyCopy =
    tab === "ride"
      ? "Bu yarıçapta henüz Sürmek yok"
      : tab === "home"
        ? "Bu yarıçapta açık Ev yok"
        : tab === "sofra"
          ? "Bu yarıçapta açık Sofra yok"
          : "Bu yarıçapta Xezîne ilanı yok";

  const heightPx = dragHeight ?? targetHeight;

  return (
    <div
      ref={wrapRef}
      className="absolute left-0 right-0 z-[470] touch-none"
      style={{
        bottom: `calc(env(safe-area-inset-bottom, 0px) + ${bottomOffset}px)`,
        height: `${heightPx}px`,
        transition: dragHeight == null ? "height 280ms cubic-bezier(0.22,1,0.36,1)" : "none",
      }}
    >
      <div
        className="relative h-full rounded-t-3xl bg-[#0A0A0C] border-t border-white/[0.06] shadow-[0_-12px_40px_rgba(0,0,0,0.7)] overflow-hidden flex flex-col"
      >
        {/* Drag area — handle + header */}
        <div
          className="cursor-grab active:cursor-grabbing select-none touch-none"
