/**
 * ProviderDashboardSheet — full-screen bottom sheet where hosts/drivers
 * manage their own listings with rich category-specific details and toggle
 * Online/Offline visibility. Replaces the legacy "create only" CTA.
 */
import { useEffect, useMemo, useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  Car,
  Home,
  UtensilsCrossed,
  Hammer,
  Plus,
  Power,
  Pencil,
  ChevronRight,
  ShieldCheck,
  Sparkles,
  Wifi,
  WifiOff,
} from "lucide-react";
import {
  type MivankasListing,
  type MivankasCategory,
  type UpdateListingInput,
} from "@/hooks/useMivankas";
import type { RideMeta } from "@/lib/mivankasMeta";
import { TIER_LABEL } from "@/lib/mivankasMeta";
import { cn } from "@/lib/utils";

const ICON: Record<MivankasCategory, typeof Car> = {
  ride: Car,
  home: Home,
  sofra: UtensilsCrossed,
  xezine: Hammer,
};

const CATEGORY_LABEL: Record<MivankasCategory, string> = {
  ride: "Sürmek",
  home: "Ev",
  sofra: "Sofra",
  xezine: "Xezîne",
};

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  listings: MivankasListing[];
  loading: boolean;
  onCreate: () => void;
  onEdit: (listing: MivankasListing) => void;
  onUpdate: (id: string, patch: UpdateListingInput) => Promise<boolean>;
  refresh: () => void;
  /** Pre-select a category tab when the sheet opens. */
  initialFilter?: MivankasCategory | "all";
}

type FilterKey = MivankasCategory | "all";

export function ProviderDashboardSheet({
  open,
  onOpenChange,
  listings,
  loading,
  onCreate,
  onEdit,
  onUpdate,
  refresh,
  initialFilter = "all",
}: Props) {
  const [filter, setFilter] = useState<FilterKey>(initialFilter);

  // Sync external filter changes (e.g. when a different tile in
  // ProviderCenterCard is tapped) into local state.
  useEffect(() => {
    if (open) setFilter(initialFilter);
  }, [open, initialFilter]);

  const filtered = useMemo(
    () => (filter === "all" ? listings : listings.filter((l) => l.category === filter)),
    [filter, listings],
  );

  const counts = useMemo(() => {
    const out: Record<FilterKey, number> = {
      all: listings.length,
      ride: 0,
      home: 0,
      sofra: 0,
      xezine: 0,
    };
    listings.forEach((l) => (out[l.category] = (out[l.category] ?? 0) + 1));
    return out;
  }, [listings]);

  const toggleActive = async (l: MivankasListing) => {
    const ok = await onUpdate(l.id, { is_active: !l.is_active });
    if (ok) refresh();
  };

  const toggleOnline = async (l: MivankasListing) => {
    if (l.category !== "ride") return;
    const meta = (l.metadata ?? {}) as { ride?: RideMeta };
    const next = { ...meta, ride: { ...(meta.ride ?? {}), online: !meta.ride?.online } };
    const ok = await onUpdate(l.id, { metadata: next });
    if (ok) refresh();
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="bg-[#0A0A0C] border-t border-amber-400/25 p-0 max-h-[92vh] overflow-hidden flex flex-col"
      >
        <SheetHeader className="px-4 pt-3 pb-2 text-left">
          <div className="flex justify-center pb-1">
            <span className="block h-1 w-10 rounded-full bg-white/15" />
          </div>
          <div className="flex items-center justify-between gap-2">
            <div>
              <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-amber-300/70">
                Mivankas · Provider
              </div>
              <SheetTitle className="text-amber-100 text-base font-bold flex items-center gap-2">
                <ShieldCheck className="h-4 w-4 text-amber-300" />
                Sürücü & Host Paneli
              </SheetTitle>
            </div>
            <button
              type="button"
              onClick={onCreate}
              className="h-9 px-3 rounded-full bg-gradient-to-r from-amber-400 to-yellow-300 text-black text-[11px] font-bold uppercase tracking-wider flex items-center gap-1.5 active:scale-95 shadow-[0_4px_14px_-4px_rgba(245,158,11,0.6)]"
            >
              <Plus className="h-3.5 w-3.5" strokeWidth={3} />
              İlan
            </button>
          </div>
          <p className="text-[11px] text-amber-200/60 -mt-0.5">
            Her ilan zengin medya ve gerçek zamanlı durum desteğiyle.
          </p>
        </SheetHeader>

        {/* Category filter */}
        <div className="px-3 pt-1 pb-2 flex gap-1.5 overflow-x-auto no-scrollbar">
          {(["all", "ride", "home", "sofra", "xezine"] as FilterKey[]).map((k) => {
            const active = filter === k;
            const Ico = k === "all" ? Sparkles : ICON[k];
            const label = k === "all" ? "Tümü" : CATEGORY_LABEL[k];
            return (
              <button
                key={k}
                onClick={() => setFilter(k)}
                className={cn(
                  "flex items-center gap-1.5 px-3 h-8 rounded-full border text-[11px] font-bold whitespace-nowrap transition active:scale-95",
                  active
                    ? "bg-amber-400/25 border-amber-300/70 text-amber-100 shadow-[0_0_10px_rgba(212,175,55,0.35)]"
                    : "bg-white/[0.04] border-white/10 text-white/65",
                )}
              >
                <Ico className="h-3 w-3" />
                {label}
                <span className="ml-0.5 text-[9px] opacity-70">{counts[k]}</span>
              </button>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto px-3 pb-6 space-y-2">
          {loading && filtered.length === 0 && (
            <div className="text-center py-12">
              <div className="inline-block h-5 w-5 rounded-full border-2 border-amber-400/30 border-t-amber-300 animate-spin" />
            </div>
          )}
          {!loading && filtered.length === 0 && (
            <button
              onClick={onCreate}
              className="w-full rounded-2xl border border-dashed border-amber-400/30 bg-amber-400/5 py-10 text-center active:scale-[0.99] transition"
            >
              <div className="mx-auto w-10 h-10 rounded-full bg-amber-400/15 border border-amber-300/40 flex items-center justify-center mb-2">
                <Plus className="h-4 w-4 text-amber-200" strokeWidth={3} />
              </div>
              <div className="text-[12px] font-bold text-amber-100">
                İlk ilanını mühürle
              </div>
              <div className="text-[10px] opacity-60 mt-0.5 px-6">
                Ride, Home, Sofra veya Xezîne — paylaş ve egemen ol.
              </div>
            </button>
          )}

          {filtered.map((l) => (
            <ProviderListingCard
              key={l.id}
              listing={l}
              onEdit={() => onEdit(l)}
              onToggleActive={() => toggleActive(l)}
              onToggleOnline={() => toggleOnline(l)}
            />
          ))}
        </div>
      </SheetContent>
    </Sheet>
  );
}

function ProviderListingCard({
  listing,
  onEdit,
  onToggleActive,
  onToggleOnline,
}: {
  listing: MivankasListing;
  onEdit: () => void;
  onToggleActive: () => void;
  onToggleOnline: () => void;
}) {
  const Icon = ICON[listing.category];
  const meta = (listing.metadata ?? {}) as Record<string, unknown> & {
    ride?: RideMeta;
    home?: { gallery_urls?: string[] };
    sofra?: { menu_urls?: string[]; slots?: string[] };
    xezine?: { products?: { name: string; image_url?: string }[] };
    gallery_urls?: string[];
  };
  const online = listing.category === "ride" ? !!meta.ride?.online : null;

  // Build a unified gallery (cover first, then category-specific media, dedup, max 4)
  const gallery: string[] = (() => {
    const out: string[] = [];
    const push = (u?: string | null) => {
      if (u && !out.includes(u)) out.push(u);
    };
    push(listing.cover_url);
    meta.home?.gallery_urls?.forEach(push);
    meta.sofra?.menu_urls?.forEach(push);
    meta.gallery_urls?.forEach(push);
    meta.xezine?.products?.forEach((p) => push(p.image_url));
    return out.slice(0, 4);
  })();
  const cover = gallery[0] ?? null;
  const extras = gallery.slice(1);

  return (
    <div
      className={cn(
        "rounded-2xl border bg-black/60 overflow-hidden transition",
        listing.is_active ? "border-amber-400/25" : "border-white/10 opacity-70",
      )}
    >
      <div className="flex">
        {/* Cover thumbnail */}
        <div className="relative h-20 w-20 shrink-0 bg-gradient-to-br from-amber-900/30 to-black/60 border-r border-amber-400/10">
          {cover ? (
            <img src={cover} alt="" className="absolute inset-0 w-full h-full object-cover" />
          ) : (
            <div className="absolute inset-0 flex items-center justify-center">
              <Icon className="h-6 w-6 text-amber-300/40" />
            </div>
          )}
          <span
            className={cn(
              "absolute top-1 left-1 h-4 px-1 rounded-full text-[8px] font-black uppercase tracking-wider flex items-center gap-0.5",
              listing.is_active
                ? "bg-emerald-400/90 text-black"
                : "bg-white/15 text-white/70",
            )}
          >
            {listing.is_active ? "AÇIK" : "PASİF"}
          </span>
        </div>

        <div className="flex-1 min-w-0 p-2.5">
          <div className="flex items-center gap-1.5 text-[9px] font-mono uppercase tracking-widest text-amber-300/70">
            <Icon className="h-2.5 w-2.5" />
            {CATEGORY_LABEL[listing.category]}
            {listing.category === "ride" && meta.ride?.tier && (
              <span className="ml-1 px-1 rounded-sm bg-amber-400/15 text-amber-200">
                {TIER_LABEL[meta.ride.tier]}
              </span>
            )}
          </div>
          <div className="text-[12px] font-bold text-amber-50 truncate mt-0.5">
            {listing.title}
          </div>
          <div className="text-[10px] opacity-60 truncate">
            {listing.city || "—"}
            {listing.category === "ride" && meta.ride?.license_plate && (
              <span className="ml-2 font-mono text-amber-200/80">
                {meta.ride.license_plate}
              </span>
            )}
            {listing.category === "sofra" && meta.sofra?.slots?.length && (
              <span className="ml-2 text-amber-200/80">{meta.sofra.slots.join(" · ")}</span>
            )}
            {listing.category === "xezine" && meta.xezine?.products?.length && (
              <span className="ml-2 text-amber-200/80">
                {meta.xezine.products.length} ürün
              </span>
            )}
          </div>
        </div>
      </div>

      {/* Airbnb-style gallery strip — shows when listing has multiple photos */}
      {extras.length > 0 && (
        <div className="flex gap-1 px-2 pb-2 pt-0.5">
          {extras.map((u, i) => (
            <div
              key={i}
              className="relative h-12 flex-1 rounded-md overflow-hidden border border-white/5 bg-black/40"
            >
              <img src={u} alt="" className="absolute inset-0 w-full h-full object-cover" />
            </div>
          ))}
          {/* Pad with subtle placeholders so the row doesn't jump */}
          {Array.from({ length: Math.max(0, 3 - extras.length) }).map((_, i) => (
            <div
              key={`p-${i}`}
              aria-hidden
              className="h-12 flex-1 rounded-md border border-dashed border-amber-400/10 bg-black/30"
            />
          ))}
        </div>
      )}

      {/* Actions row */}
      <div className="flex items-center gap-1 px-2 pb-2 pt-1 border-t border-white/5">
        {listing.category === "ride" && (
          <button
            onClick={onToggleOnline}
            className={cn(
              "flex items-center gap-1 px-2 h-7 rounded-md text-[10px] font-bold border active:scale-95",
              online
                ? "bg-emerald-400/15 border-emerald-300/40 text-emerald-100"
                : "bg-white/5 border-white/10 text-white/65",
            )}
          >
            {online ? <Wifi className="h-3 w-3" /> : <WifiOff className="h-3 w-3" />}
            {online ? "Online" : "Offline"}
          </button>
        )}
        <button
          onClick={onToggleActive}
          className="flex items-center gap-1 px-2 h-7 rounded-md text-[10px] font-bold bg-white/5 border border-white/10 text-white/70 active:scale-95"
        >
          <Power className="h-3 w-3" />
          {listing.is_active ? "Yayından kaldır" : "Yayınla"}
        </button>
        <button
          onClick={onEdit}
          className="ml-auto flex items-center gap-1 px-2.5 h-7 rounded-md text-[10px] font-bold bg-amber-400/20 border border-amber-300/50 text-amber-100 active:scale-95"
        >
          <Pencil className="h-3 w-3" />
          Düzenle
          <ChevronRight className="h-3 w-3 -mr-0.5" />
        </button>
      </div>
    </div>
  );
}

