/**
 * QuickBookingSheet — Uber-style one-tap booking confirmation.
 *
 * Replaces the older 2-step ServiceCategorySheet → ListingDetailSheet flow
 * for the most common scenario: rider taps a driver/host in the nearby list
 * and immediately sees price, ETA, and a single Confirm button. No tier
 * picker, no second sheet — just price, ETA, "Mührüyle Onayla".
 *
 * For the four Mivankas categories the wording adapts:
 *   ride   -> ETA + DC ride price
 *   home   -> Capacity + 1 night DC estimate
 *   sofra  -> Open hours + per-seat DC estimate
 *   xezine -> Item status + listing DC value
 *
 * The Confirm button is KYC-gated for ride bookings (legal/insurance), and
 * always-on for the other categories so first-time Sovereigns can still
 * book a meal or borrow a tool.
 */
import { useEffect, useMemo, useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  Car,
  Crown,
  Home,
  UtensilsCrossed,
  Package,
  Coins,
  Banknote,
  ShieldCheck,
  Lock,
  ChevronRight,
  MapPin,
  Sparkles,
  Loader2,
  MessageCircle,
  Users,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { SterkFace } from "@/components/sovereign/SterkFace";
import type { MivankasCategory, MivankasListing } from "@/hooks/useMivankas";
import { TIER_BASE_DC, TIER_ETA_MIN, type MivankasMeta } from "@/lib/mivankasMeta";
import { useDcRate } from "@/hooks/useDcRate";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  listing: MivankasListing | null;
  /** Approximate distance (km) between rider and listing for ETA/price. */
  distanceKm: number | null;
  /** Whether the rider's Sovereign ID is verified — required for rides. */
  kycVerified: boolean;
  /** Confirm — fires the actual mivankas_bookings INSERT in the parent.
   *  Receives the chosen payment method so the parent can persist it. */
  onConfirm: (
    listing: MivankasListing,
    payment: "cash" | "dc",
  ) => Promise<string | null>;
  /** Open a 1-to-1 chat with the host BEFORE booking. */
  onMessage?: (listing: MivankasListing) => void | Promise<void>;
  /** Open the KYC route — used when the rider isn't verified. */
  onOpenKyc: () => void;
}

const CATEGORY_META: Record<
  MivankasCategory,
  { Icon: typeof Car; label: string; color: string; cta: string }
> = {
  ride: { Icon: Car, label: "Sürmek", color: "text-amber-100", cta: "Mührüyle Eşleş" },
  home: { Icon: Home, label: "Ev", color: "text-amber-100", cta: "Konaklamayı Mühürle" },
  sofra: { Icon: UtensilsCrossed, label: "Sofra", color: "text-amber-100", cta: "Sofraya Otur" },
  xezine: { Icon: Package, label: "Xezîne", color: "text-amber-100", cta: "Talep Gönder" },
};

function tierFromKeka(score: number): "diwan" | "civat" | "egemen" | "default" {
  if (score >= 4000) return "diwan";
  if (score >= 1500) return "civat";
  if (score >= 500) return "egemen";
  return "default";
}

function rideTierFor(score: number, capacity: number) {
  if (capacity >= 4) return "van" as const;
  const t = tierFromKeka(score);
  if (t === "diwan" || t === "civat") return "premium-diwan" as const;
  return "sovereign-x" as const;
}

export function QuickBookingSheet({
  open,
  onOpenChange,
  listing,
  distanceKm,
  kycVerified,
  onConfirm,
  onMessage,
  onOpenKyc,
}: Props) {
  const [submitting, setSubmitting] = useState(false);
  const [payment, setPayment] = useState<"cash" | "dc">("dc");
  const { rate: dcRate } = useDcRate();

  // Reset transient UI state whenever the sheet closes.
  useEffect(() => {
    if (!open) {
      setSubmitting(false);
      setPayment("dc");
    }
  }, [open]);

  const meta = listing ? CATEGORY_META[listing.category] : null;

  // Live estimate matches NearbyDriversSheet so the rider sees identical
  // numbers between the list row and the confirm step.
  const estimate = useMemo(() => {
    if (!listing) return { etaLo: 0, etaHi: 0, dc: 0 };
    const dist = distanceKm ?? 4;
    const score = listing.host?.keka_points ?? 0;
    if (listing.category === "ride") {
      const tier = rideTierFor(score, listing.capacity);
      const [lo, hi] = TIER_ETA_MIN[tier];
      const etaLo = Math.max(1, Math.round(lo + dist * 1.4));
      const etaHi = Math.max(etaLo + 2, Math.round(hi + dist * 2.2));
      const dc = Math.max(5, Math.round(TIER_BASE_DC[tier] * (0.9 + dist * 0.42)));
      return { etaLo, etaHi, dc };
    }
    if (listing.category === "home") {
      // Estimate: tier-base * capacity for one night
      const dc = Math.max(20, Math.round((score >= 1500 ? 35 : 22) * listing.capacity));
      return { etaLo: 0, etaHi: 0, dc };
    }
    if (listing.category === "sofra") {
      // Estimate: per-seat dining value
      const dc = Math.max(10, Math.round((score >= 1500 ? 18 : 12) * listing.capacity));
      return { etaLo: 0, etaHi: 0, dc };
    }
    // xezine — flat tool/item value
    const dc = Math.max(5, Math.round(score >= 1500 ? 25 : 15));
    return { etaLo: 0, etaHi: 0, dc };
  }, [listing, distanceKm]);

  if (!listing || !meta) return null;
  const Ico = meta.Icon;
  const score = listing.host?.keka_points ?? 0;
  const isRide = listing.category === "ride";
  const canConfirm = !isRide || kycVerified;

  const distLabel =
    distanceKm != null
      ? distanceKm < 1
        ? `${Math.round(distanceKm * 1000)} m`
        : `${distanceKm.toFixed(1)} km`
      : listing.city || "—";

  const handleConfirm = async () => {
    if (submitting) return;
    setSubmitting(true);
    const id = await onConfirm(listing, payment);
    if (id) {
      onOpenChange(false);
    } else {
      setSubmitting(false);
    }
  };

  const handleMessage = async () => {
    if (!onMessage) return;
    await onMessage(listing);
    onOpenChange(false);
  };

  // Compact, minimalist detail line: vehicle make/model for ride, capacity
  // for home/sofra, item condition for xezîne. One line, no clutter.
  const detailLine = ((): string | null => {
    const m = (listing.metadata ?? {}) as MivankasMeta;
    if (listing.category === "ride") {
      const r = m.ride ?? {};
      const parts = [r.vehicle_make, r.vehicle_model].filter(Boolean).join(" ");
      const seats = r.seats ?? listing.capacity;
      if (parts) return `${parts}${seats ? ` · ${seats} koltuk` : ""}`;
      return seats ? `${seats} koltuk` : null;
    }
    if (listing.category === "home") {
      const h = m.home ?? {};
      const bits: string[] = [];
      if (h.bedrooms) bits.push(`${h.bedrooms} oda`);
      bits.push(`${listing.capacity} kişi`);
      return bits.join(" · ");
    }
    if (listing.category === "sofra") {
      const s = m.sofra ?? {};
      const bits: string[] = [];
      if (s.cuisine) bits.push(s.cuisine);
      bits.push(`${s.serves ?? listing.capacity} kişilik sofra`);
      return bits.join(" · ");
    }
    const x = m.xezine ?? {};
    const first = x.products?.[0];
    if (first) return `${first.name} · ${first.condition}`;
    return null;
  })();

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="bg-[#0A0A0C] border-t border-amber-400/25 p-0 max-h-[85vh] overflow-hidden flex flex-col"
      >
        <SheetHeader className="px-5 pt-3 pb-2 text-left">
          <div className="flex justify-center pb-1">
            <span className="block h-1 w-10 rounded-full bg-white/15" />
          </div>
          <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-amber-300/70">
            Hızlı Onay
          </div>
          <SheetTitle className="text-white text-[18px] font-semibold flex items-center gap-2">
            <Ico className="h-4 w-4 text-amber-300" />
            {meta.label} · onayla ve mühürle
          </SheetTitle>
        </SheetHeader>

        {/* Profile + headline */}
        <div className="px-5 pt-2 pb-4 flex items-center gap-3">
          <SterkFace
            avatarUrl={listing.host?.avatar_url}
            displayName={listing.host?.display_name}
            kekaScore={score}
            size={56}
            showAura={false}
          />
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5">
              <span className="text-[15px] font-semibold text-white truncate">
                {listing.host?.display_name ?? listing.title}
              </span>
              {listing.host?.is_verified && (
                <ShieldCheck className="h-3.5 w-3.5 text-cyan-300 shrink-0" />
              )}
              {tierFromKeka(score) === "diwan" && (
                <Crown className="h-3.5 w-3.5 text-amber-300 shrink-0" />
              )}
            </div>
            <div className="flex items-center gap-1.5 text-[12px] text-white/55 mt-0.5">
              <MapPin className="h-3 w-3" />
              <span>{distLabel}</span>
              <span className="text-white/20">·</span>
              <span className="inline-flex items-center gap-0.5">
                <Sparkles className="h-3 w-3" />
                {score.toLocaleString("en-US")} KEKA
              </span>
            </div>
          </div>
        </div>

        {/* === Price + ETA tile === */}
        <div className="px-5">
          <div className="rounded-2xl bg-white/[0.04] border border-white/[0.08] p-4 flex items-center gap-3">
            {isRide ? (
              <>
                <div className="flex-1">
                  <div className="text-[10px] font-mono uppercase tracking-widest text-white/45">
                    Tahmini varış
                  </div>
                  <div className="text-[22px] font-semibold text-white tabular-nums leading-tight mt-0.5">
                    {estimate.etaLo}{" "}
                    <span className="text-[12px] font-normal text-white/55">dk</span>
                  </div>
                  <div className="text-[10px] text-white/40 mt-0.5">
                    {estimate.etaLo}–{estimate.etaHi} dk arası
                  </div>
                </div>
                <span className="h-10 w-px bg-white/10" />
                <div className="flex-1 text-right">
                  <div className="text-[10px] font-mono uppercase tracking-widest text-white/45">
                    Mühür ücreti
                  </div>
                  <div className="text-[22px] font-semibold text-amber-100 tabular-nums leading-tight mt-0.5">
                    {estimate.dc}{" "}
                    <span className="text-[12px] font-normal text-amber-200/70">DC</span>
                  </div>
                  <div className="text-[10px] text-white/40 mt-0.5 tabular-nums">
                    ≈ €{(estimate.dc * dcRate).toFixed(2)} · şoförle son anlaşma
                  </div>
                </div>
              </>
            ) : (
              <>
                <div className="flex-1">
                  <div className="text-[10px] font-mono uppercase tracking-widest text-white/45">
                    {listing.category === "home"
                      ? "Kapasite"
                      : listing.category === "sofra"
                        ? "Sofra Açık"
                        : "Durum"}
                  </div>
                  <div className="text-[18px] font-semibold text-white leading-tight mt-0.5">
                    {listing.category === "home"
                      ? `${listing.capacity} kişi`
                      : listing.category === "sofra"
                        ? "Bugün"
                        : "Stokta"}
                  </div>
                </div>
                <span className="h-10 w-px bg-white/10" />
                <div className="flex-1 text-right">
                  <div className="text-[10px] font-mono uppercase tracking-widest text-white/45">
                    Tahmini bedel
                  </div>
                  <div className="text-[22px] font-semibold text-amber-100 tabular-nums leading-tight mt-0.5">
                    {estimate.dc}{" "}
                    <span className="text-[12px] font-normal text-amber-200/70">DC</span>
                  </div>
                  <div className="text-[10px] text-white/40 mt-0.5 tabular-nums">
                    ≈ €{(estimate.dc * dcRate).toFixed(2)}
                  </div>
                </div>
              </>
            )}
          </div>

          {/* Listing summary — title + minimalist detail line */}
          <div className="mt-3">
            <div className="text-[13px] font-medium text-white truncate">
              {listing.title}
            </div>
            {detailLine && (
              <div className="flex items-center gap-1.5 mt-1 text-[11px] text-white/60">
                {isRide ? (
                  <Car className="h-3 w-3 text-amber-300/80" />
                ) : (
                  <Users className="h-3 w-3 text-amber-300/80" />
                )}
                <span className="truncate">{detailLine}</span>
              </div>
            )}
            {listing.description && (
              <div className="text-[12px] text-white/45 mt-1 line-clamp-2">
                {listing.description}
              </div>
            )}
          </div>

          {/* === Payment toggle — Nakit ↔ DiravCash === */}
          <div className="mt-4">
            <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-white/40 mb-1.5">
              Ödeme yöntemi
            </div>
            <div
              role="tablist"
              aria-label="Ödeme yöntemi"
              className="grid grid-cols-2 gap-1 p-1 rounded-2xl bg-white/[0.04] border border-white/[0.08]"
            >
              {(
                [
                  { id: "cash" as const, label: "Nakit", Icon: Banknote },
                  { id: "dc" as const, label: "DiravCash", Icon: Coins },
                ] as const
              ).map(({ id, label, Icon }) => {
                const active = payment === id;
                return (
                  <button
                    key={id}
                    role="tab"
                    aria-selected={active}
                    type="button"
                    onClick={() => setPayment(id)}
                    className={cn(
                      "h-10 rounded-xl flex items-center justify-center gap-1.5 text-[12px] font-semibold transition active:scale-[0.98]",
                      active
                        ? "bg-gradient-to-r from-amber-400 to-yellow-300 text-black shadow-[0_4px_14px_-6px_rgba(245,158,11,0.7)]"
                        : "text-white/65 hover:text-white",
                    )}
                  >
                    <Icon className="h-3.5 w-3.5" />
                    {label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* === Footer — dual CTA: Direkt Mesaj + Mühürle === */}
        <div
          className="border-t border-white/[0.06] px-4 pt-3 mt-4 bg-[#0A0A0C]"
          style={{ paddingBottom: "max(env(safe-area-inset-bottom), 12px)" }}
        >
          {canConfirm ? (
            <div className="flex items-stretch gap-2">
              <button
                type="button"
                onClick={handleMessage}
                disabled={!onMessage || submitting}
                className="h-12 px-4 rounded-2xl flex items-center justify-center gap-1.5 bg-white/[0.06] border border-white/15 text-white/85 font-semibold text-[12px] active:scale-[0.98] disabled:opacity-40"
                aria-label="Direkt mesaj yaz"
              >
                <MessageCircle className="h-4 w-4" />
                Mesaj
              </button>
              <button
                onClick={handleConfirm}
                disabled={submitting}
                className={cn(
                  "flex-1 h-12 rounded-2xl flex items-center justify-center gap-2 bg-gradient-to-r from-amber-400 to-yellow-300 text-black font-bold tracking-wide text-[14px] active:scale-[0.98] shadow-[0_8px_24px_-8px_rgba(245,158,11,0.6)] disabled:opacity-70",
                )}
              >
                {submitting ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Mühürleniyor…
                  </>
                ) : (
                  <>
                    {payment === "dc" ? (
                      <Coins className="h-4 w-4" />
                    ) : (
                      <Banknote className="h-4 w-4" />
                    )}
                    Mühürle
                    <ChevronRight className="h-4 w-4" />
                  </>
                )}
              </button>
            </div>
          ) : (
            <button
              onClick={onOpenKyc}
              className="w-full h-12 rounded-2xl flex items-center justify-center gap-2 bg-white/5 border border-amber-400/30 text-amber-100 font-semibold text-[12px] active:scale-[0.98]"
            >
              <Lock className="h-4 w-4 text-amber-300" />
              Sürmek için Sovereign ID gerekli
              <ChevronRight className="h-4 w-4" />
            </button>
          )}
          <div className="text-center text-[10px] text-white/35 mt-2">
            {payment === "dc"
              ? "DC bakiyenden çekilir · iptal ederse iade edilir"
              : "Nakit ödeme · sürücü/host ile yüz yüze"}
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

