import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Sparkles, Coins } from "lucide-react";
import type { MivankasBooking } from "@/hooks/useMivankas";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  booking: MivankasBooking | null;
  /** Current user is host or guest? Determines who the "receiver" of the seal is. */
  receiverId: string;
  receiverName: string;
  walletBalance: number;
  onSeal: (input: {
    bookingId: string;
    receiverId: string;
    kekaPoints: number;
    honorTipDc: number;
    comment: string;
  }) => Promise<boolean>;
}

const TIP_OPTIONS = [0, 5, 10, 25];
const STARS = [1, 2, 3, 4, 5];

export function SealTheDealDialog({
  open,
  onOpenChange,
  booking,
  receiverId,
  receiverName,
  walletBalance,
  onSeal,
}: Props) {
  const [stars, setStars] = useState(5);
  const [tip, setTip] = useState(0);
  const [comment, setComment] = useState("");
  const [busy, setBusy] = useState(false);

  if (!booking) return null;

  const kekaPoints = stars * 20; // 1★ = 20pt, 5★ = 100pt
  const insufficientFunds = tip > walletBalance;

  const submit = async () => {
    setBusy(true);
    const ok = await onSeal({
      bookingId: booking.id,
      receiverId,
      kekaPoints,
      honorTipDc: tip,
      comment,
    });
    setBusy(false);
    if (ok) {
      onOpenChange(false);
      setStars(5);
      setTip(0);
      setComment("");
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-[#0A0A0A] border-amber-400/30 text-foreground max-w-md">
        <DialogHeader>
          <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-amber-300/70 text-center">
            Seal the Deal
          </div>
          <DialogTitle className="text-amber-100 text-center text-lg">
            Onur Mührünü Yerleştir
          </DialogTitle>
          <p className="text-[11px] opacity-70 text-center">
            <span className="font-bold text-amber-200">{receiverName}</span> ile karşılaşman nasıldı?
          </p>
        </DialogHeader>

        <div className="space-y-5 mt-2">
          {/* Stars */}
          <div className="flex items-center justify-center gap-2">
            {STARS.map((n) => (
              <button
                key={n}
                onClick={() => setStars(n)}
                className={`w-10 h-10 rounded-full flex items-center justify-center transition active:scale-90 ${
                  n <= stars
                    ? "bg-amber-400/25 border border-amber-300/70 shadow-[0_0_12px_rgba(212,175,55,0.4)]"
                    : "bg-white/5 border border-white/10"
                }`}
                aria-label={`${n} stars`}
              >
                <Sparkles
                  className={`w-4 h-4 ${n <= stars ? "text-amber-200" : "text-white/30"}`}
                />
              </button>
            ))}
          </div>
          <div className="text-center text-[11px] font-mono">
            <span className="text-amber-300 font-bold">+{kekaPoints} KEKA</span>{" "}
            <span className="opacity-50">→ {receiverName.split(" ")[0]}</span>
          </div>

          {/* Honor tip */}
          <div>
            <div className="text-[9px] font-mono uppercase tracking-widest text-amber-300/70 mb-2 flex items-center gap-1">
              <Coins className="w-3 h-3" />
              Honor Tip (opsiyonel · DiravCash)
            </div>
            <div className="grid grid-cols-4 gap-2">
              {TIP_OPTIONS.map((dc) => {
                const active = tip === dc;
                const disabled = dc > walletBalance;
                return (
                  <button
                    key={dc}
                    onClick={() => setTip(dc)}
                    disabled={disabled}
                    className={`py-2 rounded-lg text-[11px] font-bold border transition active:scale-95 ${
                      active
                        ? "bg-amber-400/20 border-amber-300/70 text-amber-100"
                        : "bg-white/5 border-white/10 text-white/70"
                    } ${disabled ? "opacity-30 cursor-not-allowed" : ""}`}
                  >
                    {dc === 0 ? "—" : `${dc} DC`}
                  </button>
                );
              })}
            </div>
            <div className="text-[9px] font-mono opacity-50 mt-1.5 text-right">
              Bakiye: {walletBalance} DC
            </div>
            {insufficientFunds && (
              <div className="text-[10px] text-red-400 mt-1">Yetersiz bakiye</div>
            )}
          </div>

          {/* Comment */}
          <div>
            <div className="text-[9px] font-mono uppercase tracking-widest text-amber-300/70 mb-1">
              Yorum (opsiyonel)
            </div>
            <Textarea
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder="Topluluk için bir kelime…"
              maxLength={280}
              className="bg-white/5 border-amber-400/20 min-h-[60px]"
            />
          </div>

          <button
            onClick={submit}
            disabled={busy || insufficientFunds}
            className="w-full px-4 py-3 rounded-xl bg-gradient-to-r from-amber-500 to-amber-300 text-black font-bold tracking-wider uppercase text-[12px] disabled:opacity-40 active:scale-[0.98]"
          >
            {busy ? "Mühürleniyor…" : "Mührü Bas"}
          </button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

