/**
 * ServiceCategorySheet — Uber-style "what kind of ride do you want?" panel
 * shown right after the rider sets a destination. Lists the three Sovereign
 * tiers with estimated DC price (mock — pure UI) and ETA, then routes the
 * user to a final Mühür confirm step.
 */
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  Car,
  Crown,
  Bus,
  Sparkles,
  Clock,
  Coins,
  ShieldCheck,
  ChevronRight,
  Lock,
} from "lucide-react";
import {
  TIER_BASE_DC,
  TIER_ETA_MIN,
  TIER_LABEL,
  type RideTier,
} from "@/lib/mivankasMeta";
import { cn } from "@/lib/utils";
import { useMemo, useState } from "react";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  destination: string;
  /** Rider's distance to the closest available driver (km), if known. */
  approxDistanceKm: number | null;
  /** Whether the rider's Sovereign ID is verified — gates the booking action. */
  kycVerified: boolean;
  /** When the rider taps confirm, parent opens the seal/booking flow. */
  onConfirm: (tier: RideTier) => void;
  /** Open the KYC route — used when the user isn't verified. */
  onOpenKyc: () => void;
}

const TIER_META: Record<
  RideTier,
  { Icon: typeof Car; tagline: string; perk: string }
> = {
  "sovereign-x": {
    Icon: Car,
    tagline: "Hızlı · Egemen şoförler",
    perk: "Standart Sovereign rota",
  },
  "premium-diwan": {
    Icon: Crown,
    tagline: "Lüks · Sadece Dîwan rütbesi",
    perk: "Sessiz, premium araç + altın halkalı şoför",
  },
  van: {
    Icon: Bus,
    tagline: "Geniş · 6+ koltuk",
    perk: "Aile ve eşya için ferah araç",
  },
};

export function ServiceCategorySheet({
  open,
  onOpenChange,
  destination,
  approxDistanceKm,
  kycVerified,
  onConfirm,
  onOpenKyc,
}: Props) {
  const [tier, setTier] = useState<RideTier>("sovereign-x");

  const tiers: RideTier[] = ["sovereign-x", "premium-diwan", "van"];

  const estimate = useMemo(() => {
    const dist = approxDistanceKm ?? 5; // assume ~5km if rider has no GPS
    const factor = 0.9 + dist * 0.42;
    return tiers.map((t) => ({
      tier: t,
      dc: Math.max(5, Math.round(TIER_BASE_DC[t] * factor)),
      eta: TIER_ETA_MIN[t],
    }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [approxDistanceKm]);

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="bg-[#0A0A0C] border-t border-amber-400/25 p-0 max-h-[88vh] overflow-hidden flex flex-col"
      >
        <SheetHeader className="px-4 pt-3 pb-2 text-left">
          <div className="flex justify-center pb-1">
            <span className="block h-1 w-10 rounded-full bg-white/15" />
          </div>
          <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-amber-300/70">
            Mivankas · Service
          </div>
          <SheetTitle className="text-amber-100 text-base font-bold flex items-center gap-2">
            <Sparkles className="h-4 w-4 text-amber-300" />
            Hangi hizmet?
          </SheetTitle>
          <p className="text-[11px] text-amber-200/70 -mt-0.5 truncate">
            <span className="opacity-60">Hedef:</span> {destination || "—"}
            {approxDistanceKm != null && (
              <span className="ml-2 opacity-60">
                · {approxDistanceKm < 1
                  ? `${Math.round(approxDistanceKm * 1000)} m`
                  : `${approxDistanceKm.toFixed(1)} km`}
              </span>
            )}
          </p>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto px-3 pb-3 space-y-2">
          {estimate.map(({ tier: t, dc, eta }) => {
            const meta = TIER_META[t];
            const Ico = meta.Icon;
            const active = tier === t;
            return (
              <button
                key={t}
                onClick={() => setTier(t)}
                className={cn(
                  "w-full text-left rounded-2xl border bg-black/60 px-3 py-3 active:scale-[0.99] transition flex items-center gap-3",
                  active
