/**
 * MusicAdminUpload — Admin-only track upload panel.
 *
 * RLS already gates `music_tracks` INSERT to admins; this component is also
 * defensively hidden via `useSovereignAdmin`. Audio + cover yüklenirken
 * `music` storage bucket'ına atılır, public URL `audio_url`/`cover_url`'a
 * kaydedilir. CID alanı manuel IPFS girişi içindir (Lighthouse'tan kopyalanan).
 */
import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useStaffAccess } from "@/hooks/useStaffAccess";
import { toast } from "sonner";
import { Loader2, Upload } from "lucide-react";
import type { MusicCategory } from "@/hooks/useJiyanMusic";

interface Props {
  onUploaded?: () => void;
}

export function MusicAdminUpload({ onUploaded }: Props) {
  const { user } = useAuth();
  const { isAdmin } = useStaffAccess();
  const [busy, setBusy] = useState(false);
  const [title, setTitle] = useState("");
  const [artist, setArtist] = useState("");
  const [category, setCategory] = useState<MusicCategory>("general");
  const [is8d, setIs8d] = useState(false);
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [coverFile, setCoverFile] = useState<File | null>(null);
  const [externalAudioUrl, setExternalAudioUrl] = useState("");
  const [audioCid, setAudioCid] = useState("");

  if (!isAdmin) return null;

  const upload = async (file: File, prefix: string) => {
    const ext = file.name.split(".").pop() || "bin";
    const path = `${prefix}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
    const { error } = await supabase.storage.from("music").upload(path, file, {
      cacheControl: "3600",
      upsert: false,
      contentType: file.type,
    });
    if (error) throw error;
    return supabase.storage.from("music").getPublicUrl(path).data.publicUrl;
  };

  const submit = async () => {
    if (!user) return;
    if (!title.trim() || !artist.trim()) {
      toast.error("Başlık ve sanatçı zorunlu");
      return;
    }
    if (!audioFile && !externalAudioUrl.trim()) {
      toast.error("Ses dosyası yükleyin veya URL girin");
      return;
    }
    setBusy(true);
    try {
      const audio_url = audioFile
        ? await upload(audioFile, "audio")
        : externalAudioUrl.trim();
      const cover_url = coverFile ? await upload(coverFile, "cover") : null;

      const { error } = await supabase.from("music_tracks").insert({
        title: title.trim(),
        artist: artist.trim(),
        category,
        is_8d: is8d,
        audio_url,
        audio_cid: audioCid.trim() || null,
        cover_url,
        uploaded_by: user.id,
      });
      if (error) throw error;
      toast.success("🎵 Şarkı yüklendi");
      setTitle("");
      setArtist("");
      setAudioFile(null);
      setCoverFile(null);
      setExternalAudioUrl("");
      setAudioCid("");
      setIs8d(false);
      onUploaded?.();
    } catch (e: any) {
      console.error(e);
      toast.error("Yükleme başarısız", { description: e?.message });
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      className="rounded-2xl p-4 space-y-3"
      style={{
        background: "rgba(20,14,4,0.85)",
        border: "0.75px solid rgba(212,175,55,0.45)",
      }}
    >
      <div className="flex items-center gap-2 text-[11px] uppercase tracking-[0.22em] text-amber-300/80">
        <Upload className="h-3 w-3" /> Yönetici · Şarkı Yükle
      </div>

      <input
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        placeholder="Başlık"
        className="w-full bg-black/40 border border-amber-700/40 rounded-lg px-3 py-2 text-sm text-amber-100 placeholder:text-amber-100/40"
      />
      <input
        value={artist}
        onChange={(e) => setArtist(e.target.value)}
        placeholder="Sanatçı"
        className="w-full bg-black/40 border border-amber-700/40 rounded-lg px-3 py-2 text-sm text-amber-100 placeholder:text-amber-100/40"
      />

      <div className="flex gap-2">
        <select
          value={category}
          onChange={(e) => setCategory(e.target.value as MusicCategory)}
          className="flex-1 bg-black/40 border border-amber-700/40 rounded-lg px-3 py-2 text-sm text-amber-100"
        >
          <option value="general">Genel</option>
          <option value="manifesto">Manifesto Audio</option>
          <option value="meditation">Sovereign Meditation</option>
        </select>
        <label className="flex items-center gap-2 px-3 text-xs text-amber-200/80 select-none">
          <input
            type="checkbox"
            checked={is8d}
            onChange={(e) => setIs8d(e.target.checked)}
          />
          8D
        </label>
      </div>

      <div className="space-y-1">
        <label className="text-[10px] uppercase tracking-widest text-amber-300/60">
          Ses dosyası (mp3 / m4a / wav)
        </label>
        <input
          type="file"
          accept="audio/*"
          onChange={(e) => setAudioFile(e.target.files?.[0] ?? null)}
          className="block text-xs text-amber-100/80"
        />
        <input
          value={externalAudioUrl}
          onChange={(e) => setExternalAudioUrl(e.target.value)}
          placeholder="Veya HTTPS / IPFS gateway URL"
          className="w-full bg-black/40 border border-amber-700/40 rounded-lg px-3 py-2 text-xs text-amber-100 placeholder:text-amber-100/40 mt-1"
        />
        <input
          value={audioCid}
          onChange={(e) => setAudioCid(e.target.value)}
          placeholder="(opsiyonel) IPFS CID"
          className="w-full bg-black/40 border border-amber-700/40 rounded-lg px-3 py-2 text-xs text-amber-100 placeholder:text-amber-100/40"
        />
      </div>

      <div className="space-y-1">
        <label className="text-[10px] uppercase tracking-widest text-amber-300/60">
          Kapak görseli
        </label>
        <input
          type="file"
          accept="image/*"
          onChange={(e) => setCoverFile(e.target.files?.[0] ?? null)}
          className="block text-xs text-amber-100/80"
        />
      </div>

      <button
        onClick={() => void submit()}
        disabled={busy}
        className="w-full py-2.5 rounded-xl text-sm font-medium flex items-center justify-center gap-2 disabled:opacity-50"
        style={{
          background: "linear-gradient(135deg,#d4af37,#a07820)",
          color: "#0a0700",
        }}
      >
        {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}
        {busy ? "Yükleniyor…" : "Yükle"}
      </button>
    </div>
  );
}

