/**
 * MusicMiniPlayer — Global floating mini-player.
 *
 * Apple-grade UX:
 *   - Üstte görünür "tutamaç" (handle) çizgisi + ChevronDown ipucu
 *   - Yukarı/aşağı drag ile pürüzsüz morph (FLIP-style transform during drag)
 *   - 8px eşik geçince hapticTap, kapanırken hapticMedium
 *   - Tap → /music tam ekran
 */
import { useNavigate, useLocation } from "@tanstack/react-router";
import { useEffect, useRef, useState } from "react";
import { useJiyanMusic } from "@/hooks/useJiyanMusic";
import { useMusicFavorites } from "@/hooks/useMusicFavorites";
import { hapticTap, hapticMedium } from "@/lib/native";
import { Pause, Play, Music2, X, Heart, ChevronUp, ChevronDown } from "lucide-react";

export function MusicMiniPlayer() {
  const { track, isPlaying, toggle, position, duration, stop } = useJiyanMusic();
  const { isFavorite, toggle: toggleFav } = useMusicFavorites();
  const navigate = useNavigate();
  const location = useLocation();
  const [collapsed, setCollapsed] = useState(false);
  const startY = useRef<number | null>(null);
  const dragRef = useRef<HTMLDivElement | null>(null);
  const hapticFiredRef = useRef(false);

  // Reset collapsed state when track changes
  useEffect(() => { setCollapsed(false); }, [track?.id]);

  if (!track) return null;
  if (location.pathname.startsWith("/music")) return null;
  if (location.pathname.startsWith("/phone")) return null;

  const pct = duration > 0 ? Math.min(100, (position / duration) * 100) : 0;
  const fav = isFavorite(track.id);

  const onTouchStart = (e: React.TouchEvent) => {
    startY.current = e.touches[0].clientY;
    hapticFiredRef.current = false;
    if (dragRef.current) dragRef.current.style.transition = "none";
  };
  const onTouchMove = (e: React.TouchEvent) => {
    if (startY.current == null || !dragRef.current) return;
    const dy = e.touches[0].clientY - startY.current;
    // Allow visual lag while dragging (clamped, with rubber-band)
    const clamped = collapsed
      ? Math.min(0, Math.max(-80, dy)) // collapsed: only allow upward drag (negative)
      : Math.max(-30, Math.min(120, dy)); // expanded: mostly downward
    dragRef.current.style.transform = `translate3d(-50%, ${clamped}px, 0)`;
    if (!hapticFiredRef.current && Math.abs(dy) > 8) {
      hapticFiredRef.current = true;
      void hapticTap();
    }
  };
  const onTouchEnd = (e: React.TouchEvent) => {
    if (startY.current == null || !dragRef.current) return;
    const dy = e.changedTouches[0].clientY - startY.current;
    startY.current = null;
    dragRef.current.style.transition = "transform 260ms cubic-bezier(0.32,0.72,0,1)";
    dragRef.current.style.transform = "translate3d(-50%, 0, 0)";
    if (dy < -28 && !collapsed) { void hapticMedium(); setCollapsed(true); }
    else if (dy > 28 && collapsed) { void hapticMedium(); setCollapsed(false); }
  };

  // ── Collapsed pill ──
  if (collapsed) {
    return (
      <button
        ref={dragRef as any}
        onClick={() => { void hapticTap(); setCollapsed(false); }}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
        className="fixed left-1/2 z-[80] flex items-center gap-2 px-3 py-1.5 rounded-full will-change-transform"
        style={{
          bottom: "calc(76px + env(safe-area-inset-bottom, 0px))",
          transform: "translate3d(-50%, 0, 0)",
          background: "linear-gradient(135deg,#120c02 0%,#1f1606 100%)",
          border: "0.75px solid rgba(212,175,55,0.55)",
          boxShadow: "0 6px 20px -8px rgba(0,0,0,0.7)",
          color: "#FFE9A8",
        }}
        aria-label="Mini-player aç"
      >
        {isPlaying ? (
          <span className="flex items-end gap-0.5 h-3">
            <span className="w-0.5 bg-amber-300 animate-pulse" style={{ height: "100%" }} />
            <span className="w-0.5 bg-amber-300 animate-pulse" style={{ height: "60%", animationDelay: "0.15s" }} />
            <span className="w-0.5 bg-amber-300 animate-pulse" style={{ height: "80%", animationDelay: "0.3s" }} />
          </span>
        ) : (
          <Music2 className="h-3 w-3" />
        )}
        <span className="text-[11px] font-medium truncate max-w-[140px]">{track.title}</span>
        <ChevronUp className="h-3 w-3 opacity-70" />
      </button>
    );
  }

  return (
    <div
      ref={dragRef}
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
      className="fixed left-1/2 z-[80] pointer-events-auto will-change-transform"
      style={{
        bottom: "calc(76px + env(safe-area-inset-bottom, 0px))",
        transform: "translate3d(-50%, 0, 0)",
        width: "min(92vw, 460px)",
      }}
    >
      <div
        className="relative rounded-2xl overflow-hidden flex items-stretch gap-1 pl-2 pr-1 pt-3 pb-2"
        style={{
          background: "linear-gradient(135deg,#120c02 0%,#1f1606 100%)",
          border: "0.75px solid rgba(212,175,55,0.55)",
          boxShadow: "0 10px 30px -12px rgba(0,0,0,0.7), 0 0 24px -8px rgba(212,175,55,0.35)",
        }}
      >
        {/* Drag handle (visible) */}
        <div
          aria-hidden
          className="absolute left-1/2 -translate-x-1/2 top-1 h-1 w-10 rounded-full"
          style={{ background: "rgba(212,175,55,0.55)" }}
        />
        <ChevronDown
          aria-hidden
          className="absolute right-2 top-0.5 h-3 w-3 opacity-50"
          style={{ color: "#FFE9A8" }}
        />
        <button
          onClick={() => navigate({ to: "/music" })}
          className="flex items-center gap-2 flex-1 min-w-0 text-left"
          aria-label="Müzik çalarını aç"
        >
          <div className="relative h-10 w-10 rounded-lg overflow-hidden flex-shrink-0 bg-amber-950/50 grid place-items-center">
            {track.cover_url ? (
              <img
                src={track.cover_url}
                alt=""
                className={`h-full w-full object-cover ${isPlaying ? "animate-spin-slow" : ""}`}
                style={{ animationDuration: "8s" }}
              />
            ) : (
              <Music2 className="h-5 w-5 text-amber-400" />
            )}
          </div>
          <div className="min-w-0 flex-1">
            <div className="truncate text-sm font-medium" style={{ color: "#FFE9A8" }}>
              {track.title}
            </div>
            <div className="truncate text-[11px]" style={{ color: "rgba(255,233,168,0.6)" }}>
              {track.artist}
            </div>
            <div className="mt-1 h-0.5 w-full rounded-full overflow-hidden bg-amber-950/60">
              <div
                className="h-full"
                style={{ width: `${pct}%`, background: "linear-gradient(90deg,#d4af37,#ffd56b)" }}
              />
            </div>
          </div>
        </button>
        <button
          onClick={() => { void hapticTap(); void toggleFav(track); }}
          className="h-10 w-9 grid place-items-center rounded-full"
          style={{ color: fav ? "#ff5c7a" : "#FFE9A8" }}
          aria-label={fav ? "Favorilerden çıkar" : "Favorilere ekle"}
        >
          <Heart className={`h-4 w-4 ${fav ? "fill-current" : ""}`} />
        </button>
        <button
          onClick={() => { void hapticTap(); void toggle(); }}
          className="h-10 w-10 grid place-items-center rounded-full"
          style={{ background: "rgba(212,175,55,0.18)", color: "#FFE9A8" }}
          aria-label={isPlaying ? "Duraklat" : "Çal"}
        >
          {isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
        </button>
        <button
          onClick={() => { void hapticMedium(); void stop(); }}
          className="h-10 w-7 grid place-items-center rounded-full opacity-70 hover:opacity-100"
          style={{ color: "#FFE9A8" }}
          aria-label="Kapat"
        >
          <X className="h-3.5 w-3.5" />
        </button>
      </div>
    </div>
  );
}

