/**
 * NowPlayingCard — Hub widget showing the user's currently playing track.
 *
 * Realtime'a abone (`music_now_playing`). Şarkı yoksa CTA: "Müziği Başlat".
 * Spinning vinyl-tarzı cover + altın "LIVE" rozet (çalıyorsa).
 */
import { useNavigate } from "@tanstack/react-router";
import { useAuth } from "@/hooks/useAuth";
import { useNowPlayingFor, useJiyanMusic } from "@/hooks/useJiyanMusic";
import { Music2, Pause, Play } from "lucide-react";

export function NowPlayingCard({ className }: { className: string }) {
  const { user } = useAuth();
  const { track, row } = useNowPlayingFor(user?.id);
  const { toggle, track: liveTrack, isPlaying: liveIsPlaying } = useJiyanMusic();
  const navigate = useNavigate();

  // Prefer the live (in-memory) state if it matches — keeps UI snappy when
  // user controls the player from this same tab.
  const isSameTrack = liveTrack && row?.track_id === liveTrack.id;
  const isPlaying = isSameTrack ? liveIsPlaying : !!row?.is_playing;
  const display = isSameTrack ? liveTrack : track;

  return (
    <button
      onClick={() => navigate({ to: "/music" })}
      className={`${className} text-left flex flex-col gap-2`}
      style={{
        background: "var(--hub-surface-bg-strong, rgba(28,20,5,0.85))",
        border: "var(--hub-border-strong, 1px solid rgba(245,205,83,0.45))",
        backdropFilter: "blur(18px) saturate(150%)",
        boxShadow: "var(--hub-tile-shadow, 0 12px 32px -16px rgba(0,0,0,0.6))",
      }}
    >
      <div
        className="flex items-center gap-2 text-[10px] uppercase tracking-[0.22em]"
        style={{ color: "var(--hub-text-muted, rgba(255,233,168,0.72))" }}
      >
        <Music2 className="h-3 w-3" style={{ color: "var(--hub-accent, #F2C94C)" }} />
        Now Playing
        {isPlaying && (
          <span
            className="ml-auto px-1.5 py-px rounded text-[8px] tracking-widest"
            style={{
              background: "rgba(212,175,55,0.25)",
              color: "#FFD56B",
              border: "0.5px solid rgba(212,175,55,0.5)",
            }}
          >
            LIVE
          </span>
        )}
      </div>

      {display ? (
        <div className="flex items-center gap-3 mt-auto">
          <div className="relative h-12 w-12 rounded-full overflow-hidden flex-shrink-0 bg-amber-950/40 grid place-items-center">
            {display.cover_url ? (
              <img
                src={display.cover_url}
                alt=""
                className={`h-full w-full object-cover ${isPlaying ? "animate-spin-slow" : ""}`}
                style={{ animationDuration: "8s" }}
              />
            ) : (
              <Music2 className="h-5 w-5 text-amber-400" />
            )}
            {/* vinyl center hole */}
            <div className="absolute inset-1/2 -translate-x-1/2 -translate-y-1/2 h-1.5 w-1.5 rounded-full bg-black" />
          </div>
          <div className="min-w-0 flex-1">
            <div
              className="truncate text-sm font-medium"
              style={{ color: "var(--hub-text-primary, #FFE9A8)" }}
            >
              {display.title}
            </div>
            <div
              className="truncate text-[11px]"
              style={{ color: "var(--hub-text-muted, rgba(255,233,168,0.72))" }}
            >
              {display.artist}
            </div>
          </div>
          {isSameTrack && (
            <span
              role="button"
              onClick={(e) => {
                e.stopPropagation();
                void toggle();
              }}
              className="h-8 w-8 grid place-items-center rounded-full"
              style={{ background: "rgba(212,175,55,0.18)", color: "#FFE9A8" }}
            >
              {isPlaying ? <Pause className="h-3.5 w-3.5" /> : <Play className="h-3.5 w-3.5" />}
            </span>
          )}
        </div>
      ) : (
        <div className="flex flex-col items-start gap-1 mt-auto">
          <span
            className="text-sm font-medium"
            style={{ color: "var(--hub-text-primary, #FFE9A8)" }}
          >
            Sessizlik.
          </span>
          <span
            className="text-[11px]"
            style={{ color: "var(--hub-text-muted, rgba(255,233,168,0.72))" }}
          >
            Jiyan Music'i aç →
          </span>
        </div>
      )}
    </button>
  );
}

/**
 * SovereignComposer — Open-source AI music studio panel inside /music.
 *
 * Three engines, all open weights, all routed through Replicate:
 *   • Stable Audio 2.5 (ambient/electronic, Stability AI)
 *   • ACE-Step         (vocal songs, fast)
 *   • Meta MusicGen    (melody-conditioned)
 *
 * Ghost Architecture: every generation request is shrouded in Phantom Armor
 * decoy traffic so DPI cannot trivially fingerprint AI calls. Audio output
 * stays inside the app sandbox (HTMLAudioElement, no external player).
 */
import { useRef, useState } from "react";
import { useServerFn } from "@tanstack/react-start";
import { generateMusic } from "@/lib/musicGen.functions";
import { startPhantomArmor, stopPhantomArmor } from "@/lib/phantomArmor";
import { Loader2, Music4, Mic2, Wand2, Play, Pause, Shield, Download, Share2, Link2 } from "lucide-react";
import { toast } from "sonner";

type Engine = "stable-audio" | "ace-step" | "musicgen";

const ENGINES: Array<{
  id: Engine;
  label: string;
  blurb: string;
  icon: typeof Music4;
}> = [
  { id: "stable-audio", label: "Stable Audio 2.5", blurb: "Ambient · Electronic", icon: Wand2 },
  { id: "ace-step", label: "ACE-Step", blurb: "Vokal · Hızlı", icon: Mic2 },
  { id: "musicgen", label: "Meta MusicGen", blurb: "Melodi referansı", icon: Music4 },
];

export function SovereignComposer() {
  const gen = useServerFn(generateMusic);
  const [engine, setEngine] = useState<Engine>("stable-audio");
  const [prompt, setPrompt] = useState("");
  const [lyrics, setLyrics] = useState("");
  const [duration, setDuration] = useState(12);
  const [busy, setBusy] = useState(false);
  const [url, setUrl] = useState<string | null>(null);
  const [playing, setPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const handleGenerate = async () => {
    if (!prompt.trim() || busy) return;
    setBusy(true);
    setUrl(null);
    startPhantomArmor(); // mask AI traffic
    try {
      const res = await gen({
        data: {
          engine,
          prompt: prompt.trim(),
          durationSec: duration,
          lyrics: engine === "ace-step" ? lyrics : undefined,
        },
      });
      setUrl(res.url);
      toast.success("Beste hazır", { description: ENGINES.find((e) => e.id === engine)?.label });
    } catch (e) {
      toast.error("Üretim başarısız", {
        description: e instanceof Error ? e.message : "Bilinmeyen hata",
      });
    } finally {
      stopPhantomArmor();
      setBusy(false);
    }
  };

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (playing) {
      audioRef.current.pause();
      setPlaying(false);
    } else {
      void audioRef.current.play();
      setPlaying(true);
    }
  };

  const filename = () => {
    const slug = (prompt || "beste")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 40) || "beste";
    return `jiyan-${engine}-${slug}.mp3`;
  };

  const downloadMp3 = async () => {
    if (!url) return;
    try {
      const res = await fetch(url);
      const blob = await res.blob();
      const objUrl = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = objUrl;
      a.download = filename();
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(objUrl), 2000);
      toast.success("İndirildi", { description: filename() });
    } catch (e) {
      // Fallback: open in new tab
      window.open(url, "_blank", "noopener");
      toast.message("Yeni sekmede açıldı", { description: "Tarayıcı üzerinden kaydet" });
    }
  };

  const copyLink = async () => {
    if (!url) return;
    try {
      await navigator.clipboard.writeText(url);
      toast.success("Link kopyalandı");
    } catch {
      toast.error("Kopyalanamadı");
    }
  };

  const shareTrack = async () => {
    if (!url) return;
    const title = "Jiyan · Sovereign Beste";
    const text = `${ENGINES.find((e) => e.id === engine)?.label} ile ürettim: "${prompt}"`;
    // Try native file share first (best on iOS/Android)
    try {
      const res = await fetch(url);
      const blob = await res.blob();
      const file = new File([blob], filename(), { type: blob.type || "audio/mpeg" });
      const navAny = navigator as any;
      if (navAny.canShare?.({ files: [file] })) {
        await navAny.share({ files: [file], title, text });
        return;
      }
      if (navigator.share) {
        await navigator.share({ title, text, url });
        return;
      }
    } catch {/* fall through to copy */}
    await copyLink();
  };

  return (
    <section
      className="rounded-3xl p-4 space-y-3"
      style={{
        background: "linear-gradient(160deg, rgba(40,28,8,0.85), rgba(15,10,2,0.92))",
        border: "0.75px solid rgba(212,175,55,0.45)",
        backdropFilter: "blur(18px) saturate(150%)",
        boxShadow: "0 24px 64px -28px rgba(0,0,0,0.7)",
      }}
    >
      <div className="flex items-center gap-2">
        <Wand2 className="h-4 w-4" style={{ color: "#d4af37" }} />
        <div className="text-[11px] uppercase tracking-[0.22em]" style={{ color: "#FFE9A8" }}>
          Sovereign Beste · Open-Source
        </div>
        <span
          className="ml-auto inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px]"
          style={{
            background: "rgba(46, 213, 115, 0.12)",
            color: "#7FE5A1",
            border: "0.5px solid rgba(46,213,115,0.4)",
          }}
          title="Phantom Armor: AI istekleri decoy trafikle maskelenir"
        >
          <Shield className="h-2.5 w-2.5" /> Ghost
        </span>
      </div>

      {/* engine cards */}
      <div className="grid grid-cols-3 gap-2">
        {ENGINES.map((e) => {
          const Icon = e.icon;
          const active = engine === e.id;
          return (
            <button
              key={e.id}
              type="button"
              onClick={() => setEngine(e.id)}
              className="rounded-2xl p-2.5 text-left transition"
              style={{
                background: active
                  ? "linear-gradient(135deg, rgba(212,175,55,0.28), rgba(60,40,8,0.6))"
                  : "rgba(10,7,1,0.55)",
                border: active
                  ? "1px solid #d4af37"
                  : "0.75px solid rgba(212,175,55,0.2)",
              }}
            >
              <Icon className="h-4 w-4 mb-1" style={{ color: active ? "#FFE9A8" : "#d4af37" }} />
              <div className="text-[11px] font-medium" style={{ color: "#FFE9A8" }}>
                {e.label}
              </div>
              <div className="text-[9px]" style={{ color: "rgba(255,233,168,0.55)" }}>
                {e.blurb}
              </div>
            </button>
          );
        })}
      </div>

      {/* prompt */}
      <textarea
        value={prompt}
        onChange={(e) => setPrompt(e.target.value)}
        rows={2}
        placeholder={
          engine === "musicgen"
            ? "ör. dengbêj melody, slow tempo, kemençe lead"
            : engine === "ace-step"
              ? "tarz etiketleri: kurdish folk, female vocal, 90 bpm"
              : "ör. sovereign electronic, gold drone, sunrise pad"
        }
        className="w-full rounded-2xl px-3 py-2 text-sm bg-black/40 outline-none resize-none"
        style={{
          color: "#FFE9A8",
          border: "0.75px solid rgba(212,175,55,0.25)",
        }}
      />

      {engine === "ace-step" && (
        <textarea
          value={lyrics}
          onChange={(e) => setLyrics(e.target.value)}
          rows={2}
          placeholder="Sözler (opsiyonel) — boşsa enstrümantal"
          className="w-full rounded-2xl px-3 py-2 text-xs bg-black/40 outline-none resize-none"
          style={{
            color: "#FFE9A8",
            border: "0.75px solid rgba(212,175,55,0.2)",
          }}
        />
      )}

      <div className="flex items-center gap-3">
        <label className="text-[10px]" style={{ color: "rgba(255,233,168,0.7)" }}>
          Süre: <span style={{ color: "#FFE9A8" }}>{duration}s</span>
        </label>
        <input
          type="range"
          min={4}
          max={30}
          value={duration}
          onChange={(e) => setDuration(Number(e.target.value))}
          className="flex-1 accent-amber-400"
        />
      </div>

      <button
        type="button"
        onClick={handleGenerate}
        disabled={busy || !prompt.trim()}
        className="w-full h-11 rounded-2xl text-sm font-semibold flex items-center justify-center gap-2 disabled:opacity-50"
        style={{
          background: "linear-gradient(135deg,#d4af37,#a07820)",
          color: "#0a0700",
          boxShadow: "0 0 24px -6px rgba(212,175,55,0.6)",
        }}
      >
        {busy ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" /> Üretiliyor… (Phantom aktif)
          </>
        ) : (
          <>
            <Wand2 className="h-4 w-4" /> Beste
          </>
        )}
      </button>

      {url && (
        <div
          className="rounded-2xl p-3 space-y-2"
          style={{
            background: "rgba(10,7,1,0.6)",
            border: "0.75px solid rgba(212,175,55,0.3)",
          }}
        >
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={togglePlay}
              className="h-10 w-10 grid place-items-center rounded-full shrink-0"
              style={{
                background: "linear-gradient(135deg,#d4af37,#a07820)",
                color: "#0a0700",
              }}
              aria-label={playing ? "Duraklat" : "Çal"}
            >
              {playing ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
            </button>
            <div className="flex-1 min-w-0">
              <div className="text-xs truncate" style={{ color: "#FFE9A8" }}>
                Yeni beste · {ENGINES.find((e) => e.id === engine)?.label}
              </div>
              <audio
                ref={audioRef}
                src={url}
                onEnded={() => setPlaying(false)}
                onPause={() => setPlaying(false)}
                onPlay={() => setPlaying(true)}
                controls
                className="w-full mt-1"
                style={{ height: 28 }}
              />
            </div>
          </div>

          {/* Download / Share / Copy link */}
          <div className="grid grid-cols-3 gap-2 pt-1">
            <button
              type="button"
              onClick={downloadMp3}
              className="h-9 rounded-xl text-[11px] font-semibold flex items-center justify-center gap-1.5"
              style={{
                background: "linear-gradient(135deg,#d4af37,#a07820)",
                color: "#0a0700",
              }}
            >
              <Download className="h-3.5 w-3.5" /> MP3 indir
            </button>
            <button
              type="button"
              onClick={shareTrack}
              className="h-9 rounded-xl text-[11px] font-semibold flex items-center justify-center gap-1.5"
              style={{
                background: "rgba(212,175,55,0.14)",
                color: "#FFE9A8",
                border: "0.75px solid rgba(212,175,55,0.45)",
              }}
            >
              <Share2 className="h-3.5 w-3.5" /> Paylaş
            </button>
            <button
              type="button"
              onClick={copyLink}
              className="h-9 rounded-xl text-[11px] font-semibold flex items-center justify-center gap-1.5"
              style={{
                background: "rgba(10,7,1,0.7)",
                color: "#FFE9A8",
                border: "0.75px solid rgba(212,175,55,0.3)",
              }}
            >
              <Link2 className="h-3.5 w-3.5" /> Link kopyala
            </button>
          </div>
        </div>
      )}
    </section>
  );
}

