import { useEffect, useState } from "react";
import { useNavigate } from "@tanstack/react-router";
import { Shield, Wallet, MessageCircle, LayoutGrid, Crown, ChevronRight, X } from "lucide-react";
import { Button } from "@/components/ui/button";

const TOUR_KEY = "jiyan_tour_completed_v1";

const SLIDES = [
  {
    icon: Shield,
    title: "Kurd-ID — Egemen Kimliğin",
    desc: "Her vatandaşa benzersiz +777 XXXX XXXX kimlik. QR kodla anında doğrulan, ID Borsa'da DC karşılığı sat.",
    color: "from-blue-500/30 to-indigo-600/20",
    iconColor: "text-blue-300",
  },
  {
    icon: Wallet,
    title: "DiravCash — İç Ekonomi",
    desc: "DC ile hizmet al, bahşiş gönder, mystery box aç. Stripe ile güvenli yükleme, anlık transfer.",
    color: "from-emerald-500/30 to-teal-600/20",
    iconColor: "text-emerald-300",
  },
  {
    icon: MessageCircle,
    title: "Sohbet — Şifreli & Çevirili",
    desc: "DM, Grup, Kanal. AI çeviri, sesli mesaj, ghost mod, kendini imha eden mesajlar. Telegram seviyesi.",
    color: "from-purple-500/30 to-fuchsia-600/20",
    iconColor: "text-purple-300",
  },
  {
    icon: LayoutGrid,
    title: "Apps Hub — 30+ Modül",
    desc: "JiyanPedia, Avukatlar, Etkinlikler, Ehliyet sınavı, Sesli odalar... Hepsi tek dokunuşla.",
    color: "from-amber-500/30 to-orange-600/20",
    iconColor: "text-amber-300",
  },
  {
    icon: Crown,
    title: "Egemenlik — Mührünü Tamamla",
    desc: "KYC doğrulaması ve +777 Sovereign ID ile tüm yetkiler açılır. Para değil — şeref ile kazanılan otorite.",
    color: "from-yellow-500/40 to-amber-600/30",
    iconColor: "text-yellow-300",
  },
];

export function WelcomeTour({
  forceOpen,
  suppressAutoOpen,
  onClose,
}: {
  forceOpen?: boolean;
  suppressAutoOpen?: boolean;
  onClose?: () => void;
}) {
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const navigate = useNavigate();

  useEffect(() => {
    if (forceOpen) { setOpen(true); setStep(0); return; }
    if (suppressAutoOpen) return;
    try {
      const done = localStorage.getItem(TOUR_KEY);
      if (!done) {
        const t = setTimeout(() => setOpen(true), 800);
        return () => clearTimeout(t);
      }
    } catch {}
  }, [forceOpen, suppressAutoOpen]);

  const finish = (goSovereignty = false) => {
    try { localStorage.setItem(TOUR_KEY, "1"); } catch {}
    setOpen(false);
    onClose?.();
    // Route deprecated paywall flow to KYC sovereignty completion instead.
    if (goSovereignty) navigate({ to: "/kyc" });
  };

  if (!open) return null;
  const slide = SLIDES[step];
  const Icon = slide.icon;
  const isLast = step === SLIDES.length - 1;

  return (
    <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center bg-black/80 backdrop-blur-sm animate-fade-in">
      <div className="relative w-full max-w-md mx-auto sm:m-4 rounded-t-3xl sm:rounded-3xl bg-gradient-to-b from-background to-surface border border-border/40 shadow-2xl overflow-hidden">
        {/* Close */}
        <button
          onClick={() => finish(false)}
          className="absolute top-3 right-3 z-10 h-8 w-8 rounded-full bg-black/40 flex items-center justify-center text-foreground/70 hover:text-foreground hover:bg-black/60 transition"
          aria-label="Turu kapat"
        >
          <X className="h-4 w-4" />
        </button>

        {/* Visual */}
        <div className={`relative h-44 bg-gradient-to-br ${slide.color} flex items-center justify-center overflow-hidden`}>
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,rgba(255,255,255,0.08),transparent_70%)]" />
          <Icon className={`h-20 w-20 ${slide.iconColor} drop-shadow-[0_0_24px_currentColor] animate-scale-in`} strokeWidth={1.5} />
        </div>

        {/* Content */}
        <div className="px-6 pt-6 pb-5 text-center">
          <h2 className="text-xl font-bold text-foreground mb-2">{slide.title}</h2>
          <p className="text-sm text-muted-foreground leading-relaxed">{slide.desc}</p>
        </div>

        {/* Dots */}
        <div className="flex justify-center gap-1.5 pb-4">
          {SLIDES.map((_, i) => (
            <button
              key={i}
              onClick={() => setStep(i)}
              className={`h-1.5 rounded-full transition-all ${i === step ? "w-6 bg-primary" : "w-1.5 bg-muted"}`}
              aria-label={`Adım ${i + 1}`}
            />
          ))}
        </div>

        {/* Actions */}
        <div className="px-6 pb-6 flex gap-2">
          {!isLast ? (
            <>
              <Button variant="ghost" className="flex-1" onClick={() => finish(false)}>
                Atla
              </Button>
              <Button variant="neon" className="flex-1" onClick={() => setStep((s) => s + 1)}>
                İleri <ChevronRight className="h-4 w-4" />
              </Button>
            </>
          ) : (
            <>
              <Button variant="ghost" className="flex-1" onClick={() => finish(false)}>
                Keşfet
              </Button>
              <Button variant="gold" className="flex-1" onClick={() => finish(true)}>
                <Crown className="h-4 w-4" /> Egemenliğini Tamamla
              </Button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

export function resetTour() {
  try { localStorage.removeItem(TOUR_KEY); } catch {}
}

