/**
 * FloatingActiveCallPill — Sovereign gold pill rendered globally whenever
 * an active call exists AND the user has navigated AWAY from the dedicated
 * full-screen call surfaces (`/phone` or the SovereignCallScreen overlay).
 *
 * • Tap pill body  → navigate to `/phone` (returns to the call UI)
 * • Tap red X      → instantly hang up the active call
 * • Live timer + breathing emerald dot
 *
 * Mounted once at the AppShell root so it floats over every page.
 */
import { useEffect, useState } from "react";
import { useLocation, useNavigate } from "@tanstack/react-router";
import { PhoneOff, Phone } from "lucide-react";
import { useSovereignPhone } from "@/hooks/useSovereignPhone";
import { useHangupConfirm } from "@/hooks/useHangupConfirm";
import { expandCall, useCallMinimized } from "@/lib/callMinimize";

function fmt(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000));
  const m = Math.floor(s / 60);
  return `${m}:${(s % 60).toString().padStart(2, "0")}`;
}

export function FloatingActiveCallPill() {
  const { active, remoteStream } = useSovereignPhone();
  const { armOrConfirm, armed, pending } = useHangupConfirm();
  const navigate = useNavigate();
  const location = useLocation();
  const minimized = useCallMinimized();
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    if (!active) return;
    const id = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(id);
  }, [active]);

  if (!active) return null;
  // Hide on the dedicated /phone surface UNLESS the call is minimized.
  if (location.pathname.startsWith("/phone") && !minimized) return null;

  const elapsed = remoteStream ? now - active.startedAt : 0;
  const label = remoteStream
    ? fmt(elapsed)
    : active.outbound
      ? "Aranıyor…"
      : "Bağlanıyor…";
  const peer = active.peerKurdId ?? active.peerName ?? "Sovereign";

  const handleTap = () => {
    if (minimized) {
      expandCall();
    } else {
      navigate({ to: "/phone" });
    }
  };

  return (
    <div
      className="fixed left-1/2 z-[9998] -translate-x-1/2 pointer-events-none"
      style={{
        top: "calc(env(safe-area-inset-top, 0px) + 8px)",
      }}
      role="status"
      aria-live="polite"
    >
      <div
        className="pointer-events-auto flex items-center gap-2 rounded-full pr-1 pl-3 py-1"
        style={{
          background: "linear-gradient(135deg,#1a1208 0%,#2a1a08 100%)",
          border: "0.75px solid rgba(212,175,55,0.55)",
          boxShadow:
            "0 8px 24px rgba(0,0,0,0.55), 0 0 0 1px rgba(253,230,138,0.08) inset, 0 0 22px rgba(212,175,55,0.25)",
          backdropFilter: "blur(20px) saturate(180%)",
          WebkitBackdropFilter: "blur(20px) saturate(180%)",
          maxWidth: "min(92vw, 380px)",
        }}
      >
        <button
          type="button"
          onClick={handleTap}
          className="flex items-center gap-2 min-w-0 active:scale-[0.98] transition-transform"
          aria-label={minimized ? "Aktif çağrıyı büyüt" : "Aktif çağrıya dön"}
        >
          <span
            className="inline-flex h-6 w-6 items-center justify-center rounded-full shrink-0"
            style={{
              background:
                "radial-gradient(circle at 30% 28%, #54e07a 0%, #1FBF55 60%, #0e8a3a 100%)",
              boxShadow: "0 0 10px rgba(31,191,85,0.55)",
              animation: "fcp-breathe 1.6s ease-in-out infinite",
            }}
          >
            <Phone className="h-3 w-3 text-white" fill="currentColor" />
          </span>
          <span className="flex flex-col leading-tight min-w-0 text-left">
            <span
              className="text-[11px] font-semibold tabular-nums truncate"
              style={{ color: "#FDE68A", maxWidth: 180 }}
            >
              {peer}
            </span>
            <span className="text-[10px] text-amber-200/70 tabular-nums">{label}</span>
          </span>
        </button>

        <button
          type="button"
          onClick={armOrConfirm}
          disabled={pending}
          aria-label={armed ? "Onayla: aramayı sonlandır" : "Aramayı sonlandır"}
          className="ml-1 flex h-8 items-center justify-center rounded-full active:scale-90 transition-all shrink-0 disabled:opacity-60"
          style={{
            width: armed ? 90 : 32,
            paddingLeft: armed ? 10 : 0,
            paddingRight: armed ? 10 : 0,
            background: armed
              ? "linear-gradient(135deg, #ff4d4d 0%, #b00020 100%)"
              : "radial-gradient(circle at 30% 28%, #ff8a8a 0%, #e3322f 45%, #8a0d0d 100%)",
            boxShadow: armed
              ? "0 0 0 2px rgba(255,90,90,0.45), 0 6px 18px rgba(227,50,47,0.7)"
              : "0 4px 14px rgba(227,50,47,0.55), inset 0 -3px 6px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,200,200,0.4)",
          }}
        >
          <PhoneOff className="h-4 w-4 text-white shrink-0" strokeWidth={2.6} />
          {armed && (
            <span className="ml-1 text-[10px] font-bold text-white uppercase tracking-wider">
              Onayla
            </span>
          )}
        </button>
      </div>

      <style>{`
        @keyframes fcp-breathe {
          0%, 100% { transform: scale(1); box-shadow: 0 0 8px rgba(31,191,85,0.45); }
          50%      { transform: scale(1.08); box-shadow: 0 0 16px rgba(31,191,85,0.75); }
        }
      `}</style>
    </div>
  );
}

