/**
 * HapticGlowPulse — Global edge-of-screen golden flash that pulses when a
 * Sovereign Phone call rings in (and a softer red flash when one is rejected
 * or hung up). Pure CSS / portal-free overlay; pointer-events: none so it
 * never intercepts taps.
 *
 * The visual "haptic" complements the device-level vibration triggered by
 * useSovereignPhone (hapticHeavy on inbound ring).
 */
import { useEffect, useRef, useState } from "react";
import { useSovereignPhone } from "@/hooks/useSovereignPhone";

type Pulse = "none" | "gold" | "red";

export function HapticGlowPulse() {
  const { incoming, active } = useSovereignPhone();
  const [pulse, setPulse] = useState<Pulse>("none");
  const lastIncomingId = useRef<string | null>(null);
  const lastActiveId = useRef<string | null>(null);

  // Inbound ring → gold edge flash
  useEffect(() => {
    if (incoming && incoming.callId !== lastIncomingId.current) {
      lastIncomingId.current = incoming.callId;
      setPulse("gold");
      const t = setTimeout(() => setPulse("none"), 1100);
      return () => clearTimeout(t);
    }
    if (!incoming) lastIncomingId.current = null;
  }, [incoming]);

  // Call ended (active just dropped) → red soft flash
  useEffect(() => {
    if (active) {
      lastActiveId.current = active.callId;
    } else if (lastActiveId.current) {
      lastActiveId.current = null;
      setPulse("red");
      const t = setTimeout(() => setPulse("none"), 800);
      return () => clearTimeout(t);
    }
  }, [active]);

  if (pulse === "none") return null;

  const color =
    pulse === "gold"
      ? "rgba(245,205,83,0.55)"
      : "rgba(227,50,47,0.45)";

  return (
    <div
      aria-hidden
      className="pointer-events-none fixed inset-0 z-[9998]"
      style={{
        boxShadow: `inset 0 0 120px 30px ${color}`,
        animation: "haptic-glow-pulse 900ms ease-out forwards",
      }}
    >
      <style>{`
        @keyframes haptic-glow-pulse {
          0%   { opacity: 0; }
          25%  { opacity: 1; }
          100% { opacity: 0; }
        }
      `}</style>
    </div>
  );
}

