/**
 * SovereignCallScreen — In-call full-screen overlay.
 *
 * Apple-tier visuals:
 *   • Pitch-black canvas with a blurred 3D avatar that slowly Ken Burns-zooms.
 *   • Big +777 ID + name at the top, with live call timer.
 *   • Three 24K gold control orbs: Mute · Speaker · Video.
 *   • A vibrant red 3D Hangup button (matches the green 3D Call button).
 *   • For video calls: remote stream fills the screen, local stream is a
 *     draggable PiP in the bottom-right (free positioning later).
 *   • **Audio-reactive 3D rotating Red Star** in the center — once remote
 *     audio arrives, an AnalyserNode samples its amplitude and drives the
 *     star's scale + glow at 60FPS, giving the call a living, sovereign feel.
 *   • **"Searching for Sovereign Signal…"** state for outbound calls before
 *     the peer answers; auto-times-out after 25s to "Citizen is Offline" and
 *     hangs up cleanly.
 */
import { useEffect, useRef, useState } from "react";
import { Mic, MicOff, Volume2, Video, VideoOff, PhoneOff, Grid3x3, X, Minus, Sparkles, PictureInPicture2 } from "lucide-react";
import { useSovereignPhone } from "@/hooks/useSovereignPhone";
import { useHangupConfirm } from "@/hooks/useHangupConfirm";
import { useMediaSheetSwipeDown } from "@/hooks/useMediaSheetSwipeDown";
import { hapticTap } from "@/lib/native";
import { minimizeCall, useCallMinimized, resetCallMinimize } from "@/lib/callMinimize";
import { useCallBgPrefs, setCallBgEnabled, setCallBgLowData, buildPollinationsBg } from "@/lib/callBackground";

function formatDuration(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${s.toString().padStart(2, "0")}`;
}

const RING_TIMEOUT_MS = 25_000;

export function SovereignCallScreen() {
  const phone = useSovereignPhone();
  const { active, muted, speaker, videoOn, localStream, remoteStream, sendDtmf } = phone;
  // UI guard: confirm + double-tap debounce for the End-Call button.
  const { armOrConfirm: confirmHangup, armed: hangupArmed, pending: hangupPending } = useHangupConfirm();
  const [keypadOpen, setKeypadOpen] = useState(false);
  const [dtmfBuffer, setDtmfBuffer] = useState("");

  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    if (!active) return;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [active]);

  // Haptic-style "connected" green flash when remote stream first arrives.
  const [connectedFlash, setConnectedFlash] = useState(false);
  const seenRemote = useRef(false);
  useEffect(() => {
    if (remoteStream && !seenRemote.current) {
      seenRemote.current = true;
      setConnectedFlash(true);
      const t = setTimeout(() => setConnectedFlash(false), 900);
      return () => clearTimeout(t);
    }
    if (!remoteStream) seenRemote.current = false;
  }, [remoteStream]);

  // ───────── Outbound "Searching for Sovereign Signal…" timeout ─────────
  // Outbound call without remoteStream after RING_TIMEOUT_MS → assume the
  // citizen is offline, hang up gracefully.
  const [timedOut, setTimedOut] = useState(false);
  useEffect(() => {
    setTimedOut(false);
    if (!active || !active.outbound || remoteStream) return;
    const id = window.setTimeout(() => setTimedOut(true), RING_TIMEOUT_MS);
    return () => window.clearTimeout(id);
  }, [active, remoteStream]);
  useEffect(() => {
    if (!timedOut) return;
    // Hang up shortly after surfacing the message so the user sees it.
    const id = window.setTimeout(() => { void phone.hangup(); }, 2200);
    return () => window.clearTimeout(id);
  }, [timedOut, phone]);

  // ───────── Audio-reactive 3D Red Star ─────────
  const [pulse, setPulse] = useState(0); // 0..1 amplitude
  useEffect(() => {
    if (!remoteStream) {
      setPulse(0);
      return;
    }
    let raf = 0;
    let ctx: AudioContext | null = null;
    let analyser: AnalyserNode | null = null;
    let src: MediaStreamAudioSourceNode | null = null;
    let mounted = true;
    try {
      const Ctor = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!Ctor) return;
      ctx = new Ctor();
      src = ctx.createMediaStreamSource(remoteStream);
      analyser = ctx.createAnalyser();
      analyser.fftSize = 256;
      analyser.smoothingTimeConstant = 0.78;
      src.connect(analyser);
      const data = new Uint8Array(analyser.frequencyBinCount);
      const tick = () => {
        if (!mounted || !analyser) return;
        analyser.getByteFrequencyData(data);
        let sum = 0;
        for (let i = 0; i < data.length; i++) sum += data[i];
        const avg = sum / data.length / 255;
        setPulse(avg);
        raf = requestAnimationFrame(tick);
      };
      tick();
    } catch {/* analyser not available — leave pulse at 0 */}
    return () => {
      mounted = false;
      if (raf) cancelAnimationFrame(raf);
      try { src?.disconnect(); } catch {/* noop */}
      try { analyser?.disconnect(); } catch {/* noop */}
      try { void ctx?.close(); } catch {/* noop */}
    };
  }, [remoteStream]);

  const localVideoRef = useRef<HTMLVideoElement | null>(null);
  const remoteVideoRef = useRef<HTMLVideoElement | null>(null);
  const remoteAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    if (localVideoRef.current && localStream) {
      localVideoRef.current.srcObject = localStream;
    }
  }, [localStream]);

  useEffect(() => {
    if (remoteVideoRef.current && remoteStream) {
      remoteVideoRef.current.srcObject = remoteStream;
    }
    if (remoteAudioRef.current && remoteStream) {
      remoteAudioRef.current.srcObject = remoteStream;
    }
  }, [remoteStream]);

  // Swipe-down → Telegram-style MINIMIZE (call keeps running, FloatingActiveCallPill takes over).
  const { ref: swipeRef } = useMediaSheetSwipeDown(() => {
    void hapticTap();
    minimizeCall();
  });

  const minimized = useCallMinimized();

  // Reset minimize state when the active call disappears (hangup, reject, etc).
  useEffect(() => {
    if (!active) resetCallMinimize();
  }, [active]);

  if (!active) return null;
  if (minimized) return null;

  const isVideo = active.video && videoOn;
  const elapsed = now - active.startedAt;
  const peerName = active.peerName ?? active.peerKurdId ?? "Sovereign";
  const searching = active.outbound && !remoteStream && !timedOut;
  // Living scale: base 1, +up to 0.18 from amplitude, +small breathing when searching.
  const starScale = 1 + pulse * 0.18 + (searching ? 0.04 * Math.sin(now / 250) : 0);
  const starGlow = 30 + pulse * 70;

  // Pollinations.ai dynamic background (audio-only). Disabled in low-data mode? still loads but small.
  const bgPrefs = useCallBgPrefs();
  const pollinationsBg = !isVideo && bgPrefs.enabled
    ? buildPollinationsBg({ seed: peerName + (active.peerKurdId ?? ""), lowData: bgPrefs.lowDataMode })
    : null;

  // Picture-in-Picture for video calls.
  const requestPiP = async () => {
    try {
      const v = remoteVideoRef.current;
      if (!v) return;
      const doc = document as Document & {
        pictureInPictureElement?: Element | null;
        exitPictureInPicture?: () => Promise<void>;
      };
      if (doc.pictureInPictureElement) await doc.exitPictureInPicture?.();
      else await (v as HTMLVideoElement & { requestPictureInPicture?: () => Promise<PictureInPictureWindow> }).requestPictureInPicture?.();
      void hapticTap();
    } catch {/* noop */}
  };

  return (
    <div
      ref={swipeRef}
      className="fixed inset-0 z-[10000] flex flex-col"
      style={{ background: "#000", touchAction: "none" }}
      role="dialog"
      aria-label="Aktif çağrı — aşağı kaydırarak küçült"
    >
      {/* Minimize chevron (Telegram-style) */}
      <button
        type="button"
        onClick={() => { void hapticTap(); minimizeCall(); }}
        aria-label="Çağrıyı küçült"
        className="absolute z-20 left-4 flex h-9 w-9 items-center justify-center rounded-full active:scale-90 transition-transform"
        style={{
          top: "calc(env(safe-area-inset-top, 0px) + 12px)",
          background: "rgba(20,16,8,0.55)",
          border: "0.75px solid rgba(245,205,83,0.45)",
          backdropFilter: "blur(20px) saturate(180%)",
        }}
      >
        <Minus className="h-4 w-4 text-amber-200" strokeWidth={2.4} />
      </button>

      {/* Top-right cluster: BG toggle, low-data toggle, PiP (video only) */}
      <div
        className="absolute z-20 right-4 flex items-center gap-2"
        style={{ top: "calc(env(safe-area-inset-top, 0px) + 12px)" }}
      >
        {!isVideo && (
          <>
            <button
              type="button"
              onClick={() => { void hapticTap(); setCallBgEnabled(!bgPrefs.enabled); }}
              aria-label={bgPrefs.enabled ? "Dinamik arka planı kapat" : "Dinamik arka planı aç"}
              aria-pressed={bgPrefs.enabled}
              className="flex h-9 px-3 items-center gap-1.5 rounded-full active:scale-90 transition-transform text-[11px] font-semibold"
              style={{
                background: bgPrefs.enabled ? "rgba(245,205,83,0.18)" : "rgba(20,16,8,0.55)",
                border: "0.75px solid rgba(245,205,83,0.45)",
                backdropFilter: "blur(20px) saturate(180%)",
                color: "#FFE9A8",
              }}
            >
              <Sparkles className="h-3.5 w-3.5" strokeWidth={2.4} />
              BG
            </button>
            {bgPrefs.enabled && (
              <button
                type="button"
                onClick={() => { void hapticTap(); setCallBgLowData(!bgPrefs.lowDataMode); }}
                aria-label={bgPrefs.lowDataMode ? "Düşük veri modu aktif" : "Düşük veri modunu aç"}
                aria-pressed={bgPrefs.lowDataMode}
                className="flex h-9 px-3 items-center rounded-full active:scale-90 transition-transform text-[11px] font-semibold"
                style={{
                  background: bgPrefs.lowDataMode ? "rgba(34,197,94,0.22)" : "rgba(20,16,8,0.55)",
                  border: "0.75px solid rgba(245,205,83,0.45)",
                  backdropFilter: "blur(20px) saturate(180%)",
                  color: "#FFE9A8",
                }}
              >
                {bgPrefs.lowDataMode ? "Lite" : "HD"}
              </button>
            )}
          </>
        )}
        {isVideo && (
          <button
            type="button"
            onClick={requestPiP}
            aria-label="Resim içinde resim"
            className="flex h-9 w-9 items-center justify-center rounded-full active:scale-90 transition-transform"
            style={{
              background: "rgba(20,16,8,0.55)",
              border: "0.75px solid rgba(245,205,83,0.45)",
              backdropFilter: "blur(20px) saturate(180%)",
            }}
          >
            <PictureInPicture2 className="h-4 w-4 text-amber-200" strokeWidth={2.4} />
          </button>
        )}
      </div>

      {/* Background — Pollinations.ai dynamic backdrop OR blurred avatar with Ken Burns */}
      {!isVideo && (
        <div
          aria-hidden
          className="absolute inset-0 overflow-hidden"
          style={{
            background: pollinationsBg
              ? `url(${pollinationsBg}) center/cover no-repeat`
              : active.peerAvatar
                ? `url(${active.peerAvatar}) center/cover no-repeat`
                : "linear-gradient(180deg,#1a1003 0%, #000 100%)",
            filter: pollinationsBg
              ? "blur(28px) saturate(160%) brightness(0.55)"
