      {/* Audio sink (always present so call audio plays even on audio-only) */}
      <audio ref={remoteAudioRef} autoPlay playsInline className="hidden" />

      {/* Header — caller name + timer */}
      <div
        className="relative z-10 px-6 pt-12 pb-4 text-center"
