          "0 -8px 14px rgba(0,0,0,0.5) inset",
          "0 1px 0 rgba(255,234,170,0.35) inset",
          active ? "0 8px 26px rgba(245,205,83,0.45)" : "0 8px 18px rgba(0,0,0,0.55)",
        ].join(", "),
      }}
    >
      <Icon
        className="h-6 w-6"
        strokeWidth={2.2}
        style={{
          color: active ? "#1a1003" : "#FFE9A8",
          filter: active ? "none" : "drop-shadow(0 0 6px rgba(245,205,83,0.55))",
        }}
      />
    </button>
  );
}

