/**
 * SovereignIncomingScreen — WhatsApp-grade full-screen ringing overlay.
 *
 * Triggered by `useSovereignPhone().incoming`. Replaces the small Dynamic
 * Island pill with an immersive screen:
 *   • Pitch-black canvas with caller avatar blurred + Ken Burns'd as BG.
 *   • Drifting golden particle field overlay.
 *   • Pulsing 3D Red Star at the center as the "ringing heart".
 *   • Big +777 ID + display name above.
 *   • Two minimalist orbs at the bottom: green Accept / red Decline,
 *     each with breathing glow + haptic tap on press.
 *
 * Mounted globally (AppShell). Ignores route — surfaces over Hazine, Mail,
 * Hub, anything. The smaller IncomingCallIsland is hidden while this is up
 * (this component owns the inbound-ringing UX from now on).
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { Phone, PhoneOff, ChevronDown } from "lucide-react";
import { useSovereignPhone } from "@/hooks/useSovereignPhone";
import { hapticHeavy, hapticTap } from "@/lib/native";

interface Particle {
  x: number;
  y: number;
  r: number;
  vx: number;
  vy: number;
  alpha: number;
}

export function SovereignIncomingScreen() {
  const phone = useSovereignPhone();
  const { incoming } = phone;
  const [tick, setTick] = useState(0);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const rafRef = useRef<number | null>(null);

  // Vibrate periodically while ringing (mobile only — desktop ignores).
  useEffect(() => {
    if (!incoming) return;
    void hapticHeavy();
    const id = window.setInterval(() => {
      void hapticHeavy();
      setTick((t) => t + 1);
    }, 1700);
    return () => window.clearInterval(id);
  }, [incoming]);

  // Golden particle field — drifting upward, soft re-spawn.
  useEffect(() => {
    if (!incoming) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const resize = () => {
      canvas.width = window.innerWidth * dpr;
      canvas.height = window.innerHeight * dpr;
      canvas.style.width = `${window.innerWidth}px`;
      canvas.style.height = `${window.innerHeight}px`;
    };
    resize();
    window.addEventListener("resize", resize);

    const COUNT = 64;
    const particles: Particle[] = Array.from({ length: COUNT }).map(() => ({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      r: (Math.random() * 1.6 + 0.5) * dpr,
      vx: (Math.random() - 0.5) * 0.18 * dpr,
      vy: -(Math.random() * 0.45 + 0.12) * dpr,
      alpha: Math.random() * 0.6 + 0.25,
    }));

    const loop = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      for (const p of particles) {
        p.x += p.vx;
        p.y += p.vy;
        if (p.y < -8) {
          p.y = canvas.height + 8;
          p.x = Math.random() * canvas.width;
        }
        ctx.beginPath();
        const grad = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r * 6);
        grad.addColorStop(0, `rgba(255,224,140,${p.alpha})`);
        grad.addColorStop(1, "rgba(255,224,140,0)");
        ctx.fillStyle = grad;
        ctx.arc(p.x, p.y, p.r * 6, 0, Math.PI * 2);
        ctx.fill();
      }
      rafRef.current = requestAnimationFrame(loop);
    };
    loop();

    return () => {
      window.removeEventListener("resize", resize);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [incoming]);

  const accept = async () => {
    void hapticTap();
    await phone.accept();
  };
  const decline = async () => {
    void hapticTap();
    await phone.reject();
  };

  const ringtoneFallbackVisible = useMemo(() => {
    if (typeof document === "undefined") return false;
    return !document.hasFocus();
  }, []);

  if (!incoming) return null;

  const name = incoming.fromName ?? incoming.fromKurdId ?? "Sovereign";
  const sub = incoming.fromKurdId ?? "+777 — Sovereign Phone";
  const isVideo = incoming.video;

  return (
    <div
      className="fixed inset-0 z-[10001] flex flex-col"
      style={{ background: "#000", touchAction: "none" }}
      role="dialog"
      aria-label={`Gelen çağrı — ${name}`}
    >
      {/* Blurred avatar background — Ken Burns drift */}
      <div
        aria-hidden
        className="absolute inset-0 overflow-hidden"
        style={{
          background: incoming.fromAvatar
            ? `url(${incoming.fromAvatar}) center/cover no-repeat`
            : "radial-gradient(circle at 50% 35%, #2a1c06 0%, #0a0703 60%, #000 100%)",
          filter: "blur(60px) saturate(150%) brightness(0.55)",
          transform: "scale(1.5)",
          animation: "ring-kenburns 14s ease-in-out infinite alternate",
        }}
      />

      {/* Golden particles */}
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 pointer-events-none"
      />

      {/* Header — caller info */}
      <div
        className="relative z-10 px-6 text-center"
        style={{ paddingTop: "calc(env(safe-area-inset-top, 0px) + 56px)" }}
      >
        <div className="text-[12px] uppercase tracking-[0.22em] text-amber-200/80 font-semibold">
          {isVideo ? "Sovereign Görüntülü Çağrı" : "Sovereign Phone · gelen çağrı"}
        </div>
        <div className="mt-3 text-[34px] font-semibold text-white tracking-tight leading-tight">
          {name}
        </div>
        <div className="mt-1 text-[15px] text-amber-200/85 font-mono tabular-nums">
          {sub}
        </div>
        {ringtoneFallbackVisible && (
          <div className="mt-3 text-[11px] text-amber-200/55">
            Ekrana dokun → ses açılır
          </div>
        )}
      </div>

      {/* Pulsing 3D Red Star — the "ringing heart" */}
      <div className="relative z-10 flex flex-1 items-center justify-center">
        <div
          aria-hidden
          className="relative"
          style={{
            width: 220,
            height: 220,
          }}
        >
          {/* Outer breathing halo */}
          <span
            className="absolute inset-0 rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(245,205,83,0.22) 0%, transparent 65%)",
              animation: "ring-halo-breathe 1.7s ease-in-out infinite",
            }}
          />
          {/* Mid pulse ring */}
          <span
            className="absolute inset-6 rounded-full"
            style={{
              border: "1px solid rgba(245,205,83,0.45)",
              animation: "ring-pulse-ring 1.7s ease-out infinite",
            }}
          />
          {/* 3D Red Star core */}
          <div
            className="absolute inset-12 rounded-full flex items-center justify-center"
            style={{
              background:
                "radial-gradient(circle at 32% 28%, #ffb3a8 0%, #e3322f 38%, #6a0a0a 100%)",
              boxShadow: [
                "0 0 0 1px rgba(255,180,170,0.55) inset",
                "0 -16px 30px rgba(0,0,0,0.55) inset",
                "0 18px 50px rgba(227,50,47,0.55)",
                `0 0 ${40 + (tick % 2) * 25}px rgba(227,50,47,${0.55 + (tick % 2) * 0.15})`,
              ].join(", "),
              transition: "box-shadow 700ms ease",
            }}
          >
            <svg viewBox="0 0 64 64" width={64} height={64} aria-hidden>
              <defs>
                <radialGradient id="star-gold" cx="35%" cy="30%">
                  <stop offset="0%" stopColor="#FFE9A8" />
                  <stop offset="55%" stopColor="#D4AF37" />
                  <stop offset="100%" stopColor="#6E5113" />
                </radialGradient>
              </defs>
              <polygon
                points="32,4 39,24 60,24 43,37 49,58 32,46 15,58 21,37 4,24 25,24"
                fill="url(#star-gold)"
                stroke="rgba(0,0,0,0.35)"
                strokeWidth={0.8}
                style={{
                  filter: "drop-shadow(0 4px 8px rgba(0,0,0,0.5))",
                }}
              />
            </svg>
          </div>
        </div>
      </div>

      {/* Hint to swipe down */}
      <div className="relative z-10 flex justify-center pb-2">
        <div className="flex items-center gap-1 text-[11px] text-white/45">
          <ChevronDown className="h-3 w-3" />
          aşağı kaydır → küçült
        </div>
      </div>

      {/* Action orbs */}
      <div
        className="relative z-10 px-10 pb-12 flex items-center justify-between"
        style={{ paddingBottom: "calc(env(safe-area-inset-bottom, 0px) + 48px)" }}
      >
        {/* Decline */}
        <button
          onClick={decline}
          aria-label="Reddet"
          className="flex flex-col items-center gap-2 active:scale-95 transition-transform"
        >
          <span
            className="flex h-[78px] w-[78px] items-center justify-center rounded-full"
            style={{
              background:
                "radial-gradient(circle at 30% 28%, #ff8a8a 0%, #e3322f 38%, #8a0d0d 100%)",
              boxShadow: [
                "0 0 0 1px rgba(255,160,160,0.5) inset",
                "0 -10px 18px rgba(0,0,0,0.45) inset",
                "0 14px 36px rgba(227,50,47,0.55)",
                "0 4px 0 rgba(0,0,0,0.3)",
              ].join(", "),
            }}
          >
            <PhoneOff className="h-8 w-8 text-white" strokeWidth={2.4} />
          </span>
          <span className="text-[12px] text-rose-200/80 font-medium">Reddet</span>
        </button>

        {/* Accept */}
        <button
          onClick={accept}
          aria-label="Cevapla"
          className="flex flex-col items-center gap-2 active:scale-95 transition-transform"
        >
          <span
            className="flex h-[78px] w-[78px] items-center justify-center rounded-full"
            style={{
              background:
                "radial-gradient(circle at 30% 28%, #b8ff9a 0%, #2bb44e 38%, #0a5a1c 100%)",
              boxShadow: [
                "0 0 0 1px rgba(180,255,160,0.5) inset",
                "0 -10px 18px rgba(0,0,0,0.45) inset",
                "0 14px 36px rgba(43,180,78,0.55)",
                `0 0 ${30 + (tick % 2) * 18}px rgba(43,180,78,${0.55 + (tick % 2) * 0.18})`,
                "0 4px 0 rgba(0,0,0,0.3)",
              ].join(", "),
              transition: "box-shadow 700ms ease",
            }}
          >
            <Phone className="h-8 w-8 text-white" strokeWidth={2.4} />
          </span>
          <span className="text-[12px] text-emerald-200/85 font-medium">Cevapla</span>
        </button>
      </div>

      <style>{`
        @keyframes ring-kenburns {
          0%   { transform: scale(1.5) translate(0, 0); }
          100% { transform: scale(1.62) translate(-3%, -2%); }
        }
        @keyframes ring-halo-breathe {
          0%, 100% { transform: scale(1); opacity: 0.7; }
          50%      { transform: scale(1.18); opacity: 1; }
        }
        @keyframes ring-pulse-ring {
          0%   { transform: scale(1); opacity: 0.85; }
          100% { transform: scale(1.55); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

