/**
 * Module-resolution guard for the Sovereign Phone hook.
 *
 * This test exists solely to lock in the import path used by the phone
 * components (`@/hooks/useSovereignPhone`). If the underlying file is ever
 * renamed (e.g. .ts ↔ .tsx) or moved, the import below fails to resolve and
 * Vitest surfaces the error before it reaches the dev server / production
 * build — preventing regressions like the "Failed to load url" Vite error
 * from recurring.
 *
 * It also asserts that the public surface used by IncomingCallIsland and
 * SovereignCallScreen (the provider + the hook) is exported.
 */
import { describe, it, expect } from "vitest";
import * as PhoneModule from "@/hooks/useSovereignPhone";

describe("useSovereignPhone module resolution", () => {
  it("resolves from the canonical alias path", () => {
    expect(PhoneModule).toBeTruthy();
  });

  it("exports the hook consumed by phone components", () => {
    expect(typeof PhoneModule.useSovereignPhone).toBe("function");
  });

  it("exports the provider mounted in AppShell", () => {
    expect(typeof PhoneModule.SovereignPhoneProvider).toBe("function");
  });
});

