/**
 * ProfileSovereignStar — Minimalist 3D profile hero.
 *
 * Uses the SAME Stêrka Geş visual language as the boot splash
 * (`SovereignStar`), but as a true 3D, tilt-on-touch identity emblem
 * with the user's avatar locked in the central core.
 *
 * Design pillars:
 *   • Pitch black backdrop · 24K Sovereign Gold blades
 *   • Ultra-minimalist: no labels, no gradients fighting the avatar
 *   • Pure CSS 3D transforms — no canvas, no WebGL. Mobile-fast.
 *   • Subtle parallax on pointer / device tilt (under 60fps budget)
 *   • Soft golden halo + slow rotation to feel alive at rest
 */
import { useEffect, useRef, useState } from "react";
import { SovereignStar } from "@/components/keka/SovereignStar";

export interface ProfileSovereignStarProps {
  avatarUrl?: string | null;
  displayName?: string | null;
  /** Diameter in px. Default 280. */
  size?: number;
  /** Show pulsing halo behind the star. Default true. */
  glow?: boolean;
  /** Tap handler — used for "download Stêrk-Face" or share */
  onClick?: () => void;
  /** Two-letter fallback when no avatar */
  initials?: string;
}

function getInitials(name?: string | null): string {
  if (!name) return "JW";
  const parts = name.trim().split(/\s+/).slice(0, 2);
  return parts.map((p) => p.charAt(0).toUpperCase()).join("") || "JW";
}

export function ProfileSovereignStar({
  avatarUrl,
  displayName,
  size = 280,
  glow = true,
  onClick,
  initials,
}: ProfileSovereignStarProps) {
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const [tilt, setTilt] = useState({ rx: 0, ry: 0 });
  const reduceMotion = useRef(false);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reduceMotion.current = mq.matches;
    const handler = (e: MediaQueryListEvent) => {
      reduceMotion.current = e.matches;
      if (e.matches) setTilt({ rx: 0, ry: 0 });
    };
    mq.addEventListener?.("change", handler);
    return () => mq.removeEventListener?.("change", handler);
  }, []);

  const handlePointerMove = (e: React.PointerEvent<HTMLElement>) => {
    if (reduceMotion.current) return;
    const el = wrapRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const dx = (e.clientX - cx) / rect.width;
    const dy = (e.clientY - cy) / rect.height;
    // max 14° tilt for a subtle 3D feel
    setTilt({ rx: -dy * 14, ry: dx * 14 });
  };

  const handlePointerLeave = () => setTilt({ rx: 0, ry: 0 });

  const Tag = onClick ? "button" : "div";
  const photoR = size * 0.21; // 21% of diameter — minimal, leaves rays prominent
  const fallback = initials ?? getInitials(displayName);

  return (
    <Tag
      type={onClick ? "button" : undefined}
      onClick={onClick}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      aria-label={
        onClick ? `${displayName ?? "Egemen"} — Stêrk-Face` : "Stêrka Geş"
      }
      className="relative inline-flex items-center justify-center select-none"
      style={{
        width: size,
        height: size,
        perspective: 1200,
        background: "transparent",
        border: "none",
        padding: 0,
        cursor: onClick ? "pointer" : "default",
      }}
    >
      {/* Outer pulsing halo */}
      {glow && (
        <div
          aria-hidden
          className="absolute inset-0 pointer-events-none"
          style={{
            borderRadius: "50%",
            background:
              "radial-gradient(circle at 50% 50%, rgba(255,210,90,0.28) 0%, rgba(212,175,55,0.10) 42%, rgba(0,0,0,0) 70%)",
            filter: "blur(6px)",
            animation: "psov-halo 3.4s ease-in-out infinite",
          }}
        />
      )}

      {/* The 3D scene */}
      <div
        ref={wrapRef}
        className="relative"
        style={{
          width: size,
          height: size,
          transformStyle: "preserve-3d",
          transform: `rotateX(${tilt.rx}deg) rotateY(${tilt.ry}deg)`,
          transition: "transform 380ms cubic-bezier(0.22, 1, 0.36, 1)",
        }}
      >
        {/* Slow back-rotation layer for the star itself */}
        <div
          className="absolute inset-0 flex items-center justify-center"
          style={{
            transform: "translateZ(0px)",
            animation: reduceMotion.current
              ? undefined
              : "psov-spin 38s linear infinite",
          }}
        >
          <SovereignStar size={size} glow />
        </div>

        {/* Soft inner gold rim disc (depth) */}
        <div
          aria-hidden
          className="absolute"
          style={{
            top: "50%",
            left: "50%",
            width: photoR * 2 + 22,
            height: photoR * 2 + 22,
            marginTop: -(photoR + 11),
            marginLeft: -(photoR + 11),
            borderRadius: "50%",
            background:
              "radial-gradient(circle, rgba(0,0,0,0.85) 55%, rgba(255,210,90,0.28) 100%)",
            boxShadow:
              "inset 0 0 0 1.5px rgba(255,220,120,0.85), 0 6px 18px rgba(0,0,0,0.6)",
            transform: "translateZ(28px)",
          }}
        />

        {/* Avatar core — sits forward in 3D space */}
        <div
          className="absolute overflow-hidden"
          style={{
            top: "50%",
            left: "50%",
            width: photoR * 2,
            height: photoR * 2,
            marginTop: -photoR,
            marginLeft: -photoR,
            borderRadius: "50%",
            transform: "translateZ(36px)",
            background:
              "radial-gradient(circle at 30% 25%, #2a1a05 0%, #0a0500 75%)",
            boxShadow:
              "inset 0 1px 0 rgba(255,235,150,0.4), inset 0 -8px 16px rgba(0,0,0,0.6), 0 8px 22px rgba(0,0,0,0.55)",
          }}
        >
          {avatarUrl ? (
            <img
              src={avatarUrl}
              alt={displayName ?? "Avatar"}
              draggable={false}
              className="w-full h-full object-cover"
              style={{ display: "block" }}
            />
          ) : (
            <div
              className="w-full h-full flex items-center justify-center font-bold"
              style={{
                color: "#FFE89A",
                fontSize: photoR * 0.7,
                letterSpacing: "0.04em",
                textShadow: "0 0 12px rgba(255,200,80,0.55)",
              }}
            >
              {fallback}
            </div>
          )}

          {/* Glassy specular highlight */}
          <div
            aria-hidden
            className="absolute inset-0 pointer-events-none"
            style={{
              background:
                "linear-gradient(160deg, rgba(255,255,255,0.18) 0%, rgba(255,255,255,0) 38%, rgba(0,0,0,0.25) 100%)",
            }}
          />
        </div>
      </div>

      <style>{`
        @keyframes psov-spin {
          from { transform: rotate(0deg); }
          to   { transform: rotate(360deg); }
        }
        @keyframes psov-halo {
          0%, 100% { opacity: 0.55; transform: scale(1); }
          50%      { opacity: 0.95; transform: scale(1.06); }
        }
      `}</style>
    </Tag>
  );
}

