import { useEffect, useState } from "react";
import { Download, X, Share, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";

const DISMISS_KEY = "jiyan_pwa_dismissed_at";
const COOLDOWN_DAYS = 7;
const SHOW_AFTER_MS = 30_000;

interface BIPEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: "accepted" | "dismissed" }>;
}

export function InstallPrompt() {
  const [evt, setEvt] = useState<BIPEvent | null>(null);
  const [show, setShow] = useState(false);
  const [isIOS, setIsIOS] = useState(false);

  useEffect(() => {
    // skip in iframe / preview
    try {
      if (window.self !== window.top) return;
    } catch { return; }

    // already installed
    if (window.matchMedia("(display-mode: standalone)").matches) return;

    // cooldown
    try {
      const last = Number(localStorage.getItem(DISMISS_KEY) || 0);
      if (last && Date.now() - last < COOLDOWN_DAYS * 86400_000) return;
    } catch {}

    const ua = navigator.userAgent;
    const iOS = /iPad|iPhone|iPod/.test(ua) && !(window as any).MSStream;
    setIsIOS(iOS);

    const onBIP = (e: Event) => {
      e.preventDefault();
      setEvt(e as BIPEvent);
    };
    window.addEventListener("beforeinstallprompt", onBIP);

    const t = setTimeout(() => {
      // show on iOS without BIP, or when BIP captured
      setShow(true);
    }, SHOW_AFTER_MS);

    return () => {
      window.removeEventListener("beforeinstallprompt", onBIP);
      clearTimeout(t);
    };
  }, []);

  const dismiss = () => {
    try { localStorage.setItem(DISMISS_KEY, String(Date.now())); } catch {}
    setShow(false);
  };

  const install = async () => {
    if (!evt) return;
    await evt.prompt();
    const { outcome } = await evt.userChoice;
    if (outcome === "accepted") setShow(false);
    dismiss();
  };

  if (!show || (!evt && !isIOS)) return null;

  return (
    <div className="fixed inset-x-0 bottom-20 z-50 px-4 pointer-events-none">
      <div className="mx-auto max-w-md rounded-2xl border border-border/40 bg-surface/95 backdrop-blur-xl shadow-2xl p-4 pointer-events-auto animate-fade-in">
        <div className="flex items-start gap-3">
          <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-primary to-neon flex items-center justify-center shrink-0">
            <Download className="h-5 w-5 text-primary-foreground" />
          </div>
          <div className="flex-1 min-w-0">
            <h3 className="text-sm font-semibold text-foreground">Jiyan'ı Ana Ekrana Ekle</h3>
            {isIOS && !evt ? (
              <p className="text-xs text-muted-foreground mt-1 leading-relaxed">
                Safari'de <Share className="inline h-3 w-3 mx-0.5" /> Paylaş → <Plus className="inline h-3 w-3 mx-0.5" /> "Ana Ekrana Ekle"
              </p>
            ) : (
              <p className="text-xs text-muted-foreground mt-1">
                Tek dokunuşla aç, daha hızlı kullan.
              </p>
            )}
          </div>
          <button onClick={dismiss} className="h-7 w-7 rounded-full hover:bg-muted/50 flex items-center justify-center" aria-label="Kapat">
            <X className="h-4 w-4 text-muted-foreground" />
          </button>
        </div>
        {!isIOS && evt && (
          <div className="flex gap-2 mt-3">
            <Button variant="ghost" size="sm" className="flex-1" onClick={dismiss}>Sonra</Button>
            <Button variant="neon" size="sm" className="flex-1" onClick={install}>
              <Download className="h-3.5 w-3.5" /> Ekle
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

