 * RitualDayStrip.test — UI guard: highlights next prayer, dims past, returns
 * null when schedule unavailable, shows "complete" badge after Isha.
 */
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { render, screen, cleanup } from "@testing-library/react";
import "@/i18n";

vi.mock("@/hooks/useRitualClock", () => ({
  useRitualClock: vi.fn(),
}));

import { useRitualClock } from "@/hooks/useRitualClock";
import { RitualDayStrip } from "@/components/ritual/RitualDayStrip";

function mkSchedule(hours: Record<string, number>) {
  const mk = (h: number) => {
    const d = new Date();
    d.setHours(h, 0, 0, 0);
    return d;
  };
  return {
    fajr: mk(hours.fajr ?? 5),
    sunrise: mk(hours.sunrise ?? 6),
    dhuhr: mk(hours.dhuhr ?? 13),
    asr: mk(hours.asr ?? 16),
    maghrib: mk(hours.maghrib ?? 19),
    isha: mk(hours.isha ?? 20),
  };
}

afterEach(() => cleanup());

describe("RitualDayStrip", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date(new Date().setHours(10, 0, 0, 0)));
  });
  afterEach(() => vi.useRealTimers());

  it("returns nothing when schedule is unavailable", () => {
    (useRitualClock as any).mockReturnValue({ schedule: null, next: null });
    const { container } = render(<RitualDayStrip />);
    expect(container.firstChild).toBeNull();
  });

  it("renders 5 prayer chips and highlights the next one", () => {
    const sch = mkSchedule({});
    (useRitualClock as any).mockReturnValue({
      schedule: sch,
      next: { name: "dhuhr", at: sch.dhuhr, msUntil: sch.dhuhr.getTime() - Date.now() },
    });
    render(<RitualDayStrip />);
    const chips = screen.getAllByRole("listitem");
    expect(chips).toHaveLength(5);
    const current = chips.find((c) => c.getAttribute("aria-current") === "time");
    expect(current).toBeTruthy();
  });

  it("shows complete state after isha", () => {
    vi.setSystemTime(new Date(new Date().setHours(23, 0, 0, 0)));
    const sch = mkSchedule({});
    (useRitualClock as any).mockReturnValue({
      schedule: sch,
      next: { name: "fajr", at: sch.fajr, msUntil: 0 },
    });
    render(<RitualDayStrip />);
    expect(screen.getByText(/✓/)).toBeInTheDocument();
  });
});

