/**
 * RitualDayStrip — Faz 5 polish: Ajanda integration.
 *
 * Drops today's 5 prayer times into any daily-planning UI. Highlights the
 * upcoming prayer in Jiyan Gold, fades past prayers, shows a graceful
 * "all complete" state after Isha, and skips render entirely if the schedule
 * cannot be computed (extreme latitude / API down — fallback already handled
 * inside useRitualClock).
 *
 * a11y: semantic <ol>, aria-current on the next prayer, role="status" wrapper
 * so screen readers can announce schedule changes; respects reduced-motion.
 * i18n: prayer labels and header read from the `ritual` namespace.
 */
import { useRitualClock } from "@/hooks/useRitualClock";
import { formatHHMM, type PrayerName } from "@/lib/ritualTimes";
import { Moon } from "lucide-react";
import { useTranslation } from "react-i18next";

const ORDER: PrayerName[] = ["fajr", "dhuhr", "asr", "maghrib", "isha"];

export function RitualDayStrip() {
  const { schedule, next } = useRitualClock();
  const { t } = useTranslation();

  if (!schedule) return null;

  const now = new Date();
  // After Isha, `next` rolls to tomorrow's fajr — surface that as a calm
  // "all complete" state instead of leaving every chip dimmed.
  const allComplete = !next || next.name === "fajr" && schedule.isha.getTime() < now.getTime();

  return (
    <section
      aria-label={t("ritual.bugununVakitleri", "Bugünün Vakitleri") as string}
      role="status"
      className="relative overflow-hidden rounded-2xl px-3 py-2.5"
      style={{
        background: "linear-gradient(180deg, rgba(14,10,4,0.7), rgba(8,6,2,0.78))",
        border: "1px solid rgba(212,175,55,0.32)",
        backdropFilter: "blur(20px) saturate(160%)",
        WebkitBackdropFilter: "blur(20px) saturate(160%)",
      }}
    >
      <div
        className="flex items-center justify-between gap-2 mb-2"
        style={{ color: "rgba(212,175,55,0.85)" }}
      >
        <div
          className="flex items-center gap-1.5 text-[9.5px] uppercase"
          style={{ letterSpacing: "0.28em" }}
        >
          <Moon className="h-3 w-3" aria-hidden /> {t("ritual.bugununVakitleri")}
        </div>
        {allComplete && (
          <span
            className="text-[9px] uppercase"
            style={{ letterSpacing: "0.18em", color: "rgba(245,230,184,0.7)" }}
          >
            ✓ {t("ritual.butunVakitlerGecti")}
          </span>
        )}
      </div>
      <ol className="flex justify-between gap-1 list-none m-0 p-0">
        {ORDER.map((name) => {
          const at = schedule[name];
          const past = at.getTime() < now.getTime();
          const isNext = !allComplete && next?.name === name;
          return (
            <li
              key={name}
              aria-current={isNext ? "time" : undefined}
              className="flex flex-col items-center flex-1 rounded-xl py-1.5 min-w-0"
              style={{
                background: isNext ? "rgba(212,175,55,0.14)" : "transparent",
                border: isNext ? "1px solid rgba(212,175,55,0.6)" : "1px solid transparent",
                opacity: past && !isNext ? 0.45 : 1,
                transition: "background 240ms ease, border-color 240ms ease, opacity 240ms ease",
              }}
            >
              <span
                className="text-[9px] uppercase truncate max-w-full"
                style={{
                  color: isNext ? "#FFE89A" : "rgba(245,230,184,0.7)",
                  letterSpacing: "0.18em",
                  fontFamily: "'Inter', system-ui",
                }}
              >
                {t(`ritual.${name}`)}
              </span>
              <span
                className="text-[12px] tabular-nums mt-0.5"
                style={{
                  color: isNext ? "#FFF6D9" : "#F5E6B8",
                  fontWeight: 300,
                }}
              >
                {formatHHMM(at)}
              </span>
            </li>
          );
        })}
      </ol>
    </section>
  );
}

