/**
 * RitualModulePanels — fully functional implementations for the
 * 14 secondary modules surfaced from the RitualMenuGrid.
 *
 * Each panel is self-contained, uses the gold/bordo Jiyan palette and
 * gracefully degrades if the user is signed out or the network is offline.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import {
  ChevronRight, Loader2, Sparkles, Calculator, CalendarClock, Radio,
  MapPin, PlayCircle, Mail, Quote, MessageSquareQuote, NotebookPen,
  Headphones, Building2, CalendarDays, Star, Pause, Play, RefreshCw, Send,
  SkipForward, Heart,
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useDengbejTTS } from "@/hooks/useDengbejTTS";
import { useEsmaProgress } from "@/hooks/useEsmaProgress";
import { useHutbeArchive } from "@/hooks/useHutbeArchive";

import {
  ESMA_UL_HUSNA, DINI_GUNLER, HIKMETLER, HADISLER,
  KURAN_RADYOLAR, MEDIA_LISTESI,
} from "@/lib/ritualDatasets";
import {
  gregorianToHijri, hijriToGregorian, calculateZekat,
} from "@/lib/hicriCalendar";

const GOLD = "#D4AF37";
const BORDO = "#8B1E2F";

function Header({ title, onBack, icon: Icon }: { title: string; onBack: () => void; icon: typeof Sparkles }) {
  return (
    <div className="space-y-2 mb-3">
      <button
        onClick={onBack}
        className="flex items-center gap-1 text-[12px]"
        style={{ color: "rgba(212,175,55,0.85)" }}
      >
        <ChevronRight className="h-3.5 w-3.5 rotate-180" /> Menü
      </button>
      <div className="flex items-center gap-2">
        <Icon className="h-5 w-5" style={{ color: GOLD }} strokeWidth={1.5} />
        <h2
          className="text-xl"
          style={{ fontFamily: "'Cinzel', Inter", fontWeight: 200, color: "#FFF6D9" }}
        >
          {title}
        </h2>
      </div>
    </div>
  );
}

const card =
  "rounded-2xl px-4 py-3 border";
const cardStyle = {
  background: "rgba(10,7,2,0.65)",
  borderColor: "rgba(212,175,55,0.18)",
  color: "#F5E6B8",
};

/* ─── 1. Esmaül Hüsna ─── */
export function EsmaPanel({ onBack }: { onBack: () => void }) {
  const { speak, stop, status, activeKey, progress: ttsProgress } = useDengbejTTS();
  const { favorites, progress, toggleFavorite, recordPlay } = useEsmaProgress();
  const [filter, setFilter] = useState<"all" | "fav" | "recent">("all");
  const [autoNext, setAutoNext] = useState(false);

  // Auto-advance: when current finishes (progress reaches 1) jump to next
  const lastFiredRef = useRef<string | null>(null);
  useEffect(() => {
    if (!autoNext || status !== "idle") return;
    const last = lastFiredRef.current;
    if (!last) return;
    lastFiredRef.current = null;
    const m = /^esma-(\d+)$/.exec(last);
    if (!m) return;
    const next = (parseInt(m[1], 10) % 99) + 1;
    const e = ESMA_UL_HUSNA.find((x) => x.no === next);
    if (e) {
      const k = `esma-${e.no}`;
      lastFiredRef.current = k;
      void recordPlay(e.no);
      void speak(`${e.tr}. ${e.meaning}.`, k, "tr", e.ar);
    }
  }, [status, autoNext, speak, recordPlay]);

  const list = useMemo(() => {
    if (filter === "fav") return ESMA_UL_HUSNA.filter((e) => favorites.has(e.no));
    if (filter === "recent") {
      return [...ESMA_UL_HUSNA].sort((a, b) => {
        const ta = progress.get(a.no)?.last_played_at ?? "";
        const tb = progress.get(b.no)?.last_played_at ?? "";
        return tb.localeCompare(ta);
      }).slice(0, 20);
    }
    return ESMA_UL_HUSNA;
  }, [filter, favorites, progress]);

  return (
    <div>
      <Header title="Esmaül Hüsna" onBack={onBack} icon={Star} />
      <div className="flex items-center justify-between gap-2 mb-3">
        <div className="flex gap-1">
          {(["all","fav","recent"] as const).map((f) => (
            <button key={f} onClick={() => setFilter(f)}
              className="px-2.5 py-1 rounded-full text-[10px] uppercase tracking-[0.18em]"
              style={{
                background: filter === f ? "rgba(212,175,55,0.22)" : "transparent",
                border: `1px solid ${filter === f ? GOLD : "rgba(212,175,55,0.25)"}`,
                color: filter === f ? "#FFF6D9" : "rgba(245,230,184,0.7)",
              }}>
              {f === "all" ? "Tümü" : f === "fav" ? `★ ${favorites.size}` : "Son"}
            </button>
          ))}
        </div>
        <button onClick={() => setAutoNext((v) => !v)}
          className="flex items-center gap-1 text-[10px] uppercase tracking-[0.18em] px-2 py-1 rounded-full"
          style={{
            background: autoNext ? "rgba(212,175,55,0.18)" : "transparent",
            border: `1px solid ${autoNext ? GOLD : "rgba(212,175,55,0.25)"}`,
            color: autoNext ? "#FFE89A" : "rgba(245,230,184,0.7)",
          }}>
          <SkipForward className="h-3 w-3" /> Auto
        </button>
      </div>

      {filter === "fav" && list.length === 0 && (
        <p className="text-[12px] text-center py-6" style={{ color: "rgba(245,230,184,0.55)" }}>
          Henüz favori eklemedin — kalp ikonuna dokun.
        </p>
      )}

      <div className="grid grid-cols-1 gap-2">
        {list.map((e) => {
          const key = `esma-${e.no}`;
          const active = activeKey === key && (status === "playing" || status === "loading");
          const fav = favorites.has(e.no);
          const plays = progress.get(e.no)?.play_count ?? 0;
          return (
            <div key={e.no}
              className={card}
              style={{
                ...(cardStyle as any),
                borderColor: active ? GOLD : (cardStyle as any).borderColor,
                boxShadow: active ? `0 0 18px ${GOLD}55` : "none",
              }}>
              <div className="flex items-baseline justify-between gap-3">
                <button
                  className="flex items-baseline gap-2 min-w-0 text-left flex-1"
                  onClick={() => {
                    if (active) { stop(); lastFiredRef.current = null; return; }
                    lastFiredRef.current = key;
                    void recordPlay(e.no);
                    void speak(`${e.tr}. ${e.meaning}.`, key, "tr", e.ar);
                  }}>
                  <span className="text-[10px] tabular-nums" style={{ color: "rgba(212,175,55,0.6)" }}>
                    {String(e.no).padStart(2, "0")}
                  </span>
                  <span className="text-[14px]" style={{ color: "#FFF6D9", fontWeight: 500 }}>
                    {e.tr}
                  </span>
                  {active && status === "loading" && <Loader2 className="h-3 w-3 animate-spin" style={{ color: GOLD }} />}
                  {active && status === "playing" && <Pause className="h-3 w-3" style={{ color: GOLD }} />}
                  {plays > 0 && (
                    <span className="text-[9px] tabular-nums px-1.5 py-0.5 rounded-full"
                      style={{ background: "rgba(212,175,55,0.12)", color: GOLD }}>
                      ×{plays}
                    </span>
                  )}
                </button>
                <button
                  onClick={() => toggleFavorite(e.no)}
                  className="flex-shrink-0 h-7 w-7 rounded-full flex items-center justify-center"
                  aria-label={fav ? "Favoriden çıkar" : "Favorilere ekle"}
                  style={{ background: fav ? "rgba(255,215,90,0.14)" : "transparent" }}>
                  <Heart className="h-3.5 w-3.5"
                    fill={fav ? "#FFE89A" : "transparent"}
                    style={{ color: fav ? "#FFE89A" : "rgba(212,175,55,0.5)" }} />
                </button>
                <span className="text-lg flex-shrink-0" dir="rtl"
                  style={{ fontFamily: "'Amiri', serif", color: "#FFE89A" }}>
                  {e.ar}
                </span>
              </div>
              <div className="mt-1 text-[11px]" style={{ color: "rgba(245,230,184,0.65)" }}>
                {e.meaning}
              </div>
              {active && (
                <div className="mt-2 h-0.5 rounded-full overflow-hidden" style={{ background: "rgba(212,175,55,0.15)" }}>
                  <div className="h-full" style={{ width: `${ttsProgress * 100}%`, background: GOLD, transition: "width 200ms linear" }} />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ─── 2. Hatim Takibi ─── */
export function HatimPanel({ onBack }: { onBack: () => void }) {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [progress, setProgress] = useState<{ surah_no: number; ayah_no: number; started_at: string } | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!user) { setLoading(false); return; }
    supabase.from("hatim_progress").select("surah_no, ayah_no, started_at")
      .eq("user_id", user.id).maybeSingle().then(({ data }) => {
        setProgress(data ?? null);
        setLoading(false);
      });
  }, [user]);

  const start = async () => {
    if (!user) return;
    setSaving(true);
    const { data } = await supabase.from("hatim_progress")
      .upsert({ user_id: user.id, surah_no: 1, ayah_no: 1, started_at: new Date().toISOString(), last_read_at: new Date().toISOString() }, { onConflict: "user_id" })
      .select().single();
    if (data) setProgress(data as any);
    setSaving(false);
  };

  const advance = async (deltaAyat: number) => {
    if (!user || !progress) return;
    setSaving(true);
    const newAyah = progress.ayah_no + deltaAyat;
    await supabase.from("hatim_progress")
      .update({ ayah_no: newAyah, last_read_at: new Date().toISOString() })
      .eq("user_id", user.id);
    setProgress({ ...progress, ayah_no: newAyah });
    setSaving(false);
  };

  return (
    <div>
      <Header title="Hatim Takibi" onBack={onBack} icon={NotebookPen} />
      {!user ? (
        <p className="text-sm" style={{ color: "rgba(245,230,184,0.7)" }}>
          Hatim takibinizi senkronlamak için giriş yapın.
        </p>
      ) : loading ? (
        <div className="flex justify-center py-8"><Loader2 className="h-5 w-5 animate-spin opacity-60" /></div>
      ) : !progress ? (
        <div className={card + " text-center py-8"} style={cardStyle as any}>
          <p className="text-sm mb-4">Yeni hatim başlat ve Sovereign Quran'ı 30 günde tamamla.</p>
          <button
            onClick={start} disabled={saving}
            className="px-5 py-2 rounded-full text-[12px]"
            style={{ background: GOLD, color: "#0A0700", fontWeight: 600 }}
          >
            Hatime Başla
          </button>
        </div>
      ) : (
        <div className="space-y-3">
          <div className={card} style={cardStyle as any}>
            <div className="text-[10px] uppercase tracking-[0.22em]" style={{ color: "rgba(212,175,55,0.7)" }}>
              Mevcut konum
            </div>
            <div className="mt-1 text-2xl tabular-nums" style={{ color: "#FFF6D9", fontWeight: 200 }}>
              Sûre {progress.surah_no} · Âyet {progress.ayah_no}
            </div>
            <div className="text-[10px] mt-1" style={{ color: "rgba(245,230,184,0.55)" }}>
              Başlangıç: {new Date(progress.started_at).toLocaleDateString()}
            </div>
          </div>
          <div className="grid grid-cols-3 gap-2">
            {[1, 5, 10].map((n) => (
              <button
                key={n}
                onClick={() => advance(n)} disabled={saving}
                className="rounded-xl py-3 text-[12px]"
                style={{ background: "rgba(212,175,55,0.12)", border: `1px solid ${GOLD}55`, color: "#FFF6D9" }}
              >
                +{n} âyet
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ─── 3. Kazalar ─── */
const PRAYERS = ["fajr","dhuhr","asr","maghrib","isha","vitr"] as const;
const PRAYER_TR: Record<string, string> = { fajr:"Sabah", dhuhr:"Öğle", asr:"İkindi", maghrib:"Akşam", isha:"Yatsı", vitr:"Vitr" };

export function KazaPanel({ onBack }: { onBack: () => void }) {
  const { user } = useAuth();
  const [rows, setRows] = useState<Record<string, number>>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) { setLoading(false); return; }
    supabase.from("kaza_log").select("prayer, remaining").eq("user_id", user.id)
      .then(({ data }) => {
        const r: Record<string, number> = {};
        (data ?? []).forEach((d: any) => { r[d.prayer] = d.remaining; });
        setRows(r);
        setLoading(false);
      });
  }, [user]);

  const update = async (prayer: string, delta: number) => {
    if (!user) return;
    const next = Math.max(0, (rows[prayer] ?? 0) + delta);
    setRows({ ...rows, [prayer]: next });
    await supabase.from("kaza_log").upsert({
      user_id: user.id, prayer, remaining: next,
    }, { onConflict: "user_id,prayer" });
  };

  return (
    <div>
      <Header title="Kaza Namaz Takibi" onBack={onBack} icon={Calculator} />
      {!user ? (
        <p className="text-sm" style={{ color: "rgba(245,230,184,0.7)" }}>Giriş yapın.</p>
      ) : loading ? (
        <Loader2 className="h-5 w-5 animate-spin opacity-60 mx-auto my-8" />
      ) : (
        <div className="space-y-2">
          {PRAYERS.map((p) => (
            <div key={p} className={card + " flex items-center justify-between"} style={cardStyle as any}>
              <div>
                <div style={{ color: "#FFF6D9" }}>{PRAYER_TR[p]}</div>
                <div className="text-[11px]" style={{ color: "rgba(245,230,184,0.55)" }}>
                  Kalan: <span className="tabular-nums" style={{ color: GOLD }}>{rows[p] ?? 0}</span>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={() => update(p, -1)} className="h-8 w-8 rounded-full" style={{ background: BORDO, color: "#FFF6D9" }}>−</button>
                <button onClick={() => update(p, 1)} className="h-8 w-8 rounded-full" style={{ background: GOLD, color: "#0A0700", fontWeight: 700 }}>+</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ─── 4. Zekat Hesaplayıcı ─── */
export function ZekatPanel({ onBack }: { onBack: () => void }) {
  const [cash, setCash] = useState(0);
  const [gold, setGold] = useState(0);
  const [silver, setSilver] = useState(0);
  const [recv, setRecv] = useState(0);
  const [debts, setDebts] = useState(0);
  const [goldPrice, setGoldPrice] = useState(75); // EUR/g default
  const result = calculateZekat({
    cashEUR: cash, goldGrams: gold, silverGrams: silver,
    receivables: recv, debts, goldPriceEURPerGram: goldPrice,
  });

  const Field = ({ label, value, set }: { label: string; value: number; set: (n: number) => void }) => (
    <label className={card + " block"} style={cardStyle as any}>
      <div className="text-[10px] uppercase tracking-[0.2em]" style={{ color: "rgba(212,175,55,0.7)" }}>{label}</div>
      <input
        type="number" value={value} onChange={(e) => set(Number(e.target.value) || 0)}
        className="w-full bg-transparent outline-none text-lg tabular-nums" style={{ color: "#FFF6D9" }}
      />
    </label>
  );

  return (
    <div>
      <Header title="Zekat Hesaplayıcı" onBack={onBack} icon={Calculator} />
      <div className="space-y-2">
        <Field label="Nakit (€)" value={cash} set={setCash} />
        <Field label="Altın (gram)" value={gold} set={setGold} />
        <Field label="Gümüş (gram)" value={silver} set={setSilver} />
        <Field label="Alacaklar (€)" value={recv} set={setRecv} />
        <Field label="Borçlar (€)" value={debts} set={setDebts} />
        <Field label="Altın fiyatı €/g" value={goldPrice} set={setGoldPrice} />
        <div className={card + " mt-4"} style={{ ...cardStyle, borderColor: GOLD } as any}>
          <div className="text-[10px] uppercase tracking-[0.2em]" style={{ color: "rgba(212,175,55,0.7)" }}>Sonuç</div>
          <div className="mt-2 grid grid-cols-2 gap-2 text-sm">
            <div>Toplam servet</div><div className="text-right tabular-nums">€{result.wealth.toFixed(2)}</div>
            <div>Nisab eşiği</div><div className="text-right tabular-nums">€{result.nisab.toFixed(2)}</div>
            <div className="col-span-2 mt-2 pt-2 border-t" style={{ borderColor: "rgba(212,175,55,0.2)" }}>
              {result.obligated ? (
                <div style={{ color: GOLD, fontWeight: 600 }}>
                  Zekat: <span className="tabular-nums">€{result.zekat.toFixed(2)}</span>
                </div>
              ) : (
                <div style={{ color: "rgba(245,230,184,0.7)" }}>Servet nisabın altında — zekat yükümlülüğü yok.</div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ─── 5. Hicri ↔ Miladi Çevirici ─── */
export function HicriPanel({ onBack }: { onBack: () => void }) {
  const today = new Date();
  const [date, setDate] = useState<string>(today.toISOString().slice(0, 10));
  const hijri = gregorianToHijri(new Date(date));
  const [hY, setHY] = useState(hijri.year);
  const [hM, setHM] = useState(hijri.month);
  const [hD, setHD] = useState(hijri.day);
  const reverse = hijriToGregorian(hY, hM, hD);

  return (
    <div>
      <Header title="Miladi ↔ Hicri" onBack={onBack} icon={CalendarClock} />
      <div className="space-y-3">
        <div className={card} style={cardStyle as any}>
          <div className="text-[10px] uppercase tracking-[0.2em]" style={{ color: "rgba(212,175,55,0.7)" }}>Miladi → Hicri</div>
          <input type="date" value={date} onChange={(e) => setDate(e.target.value)}
            className="w-full bg-transparent text-lg outline-none mt-1" style={{ color: "#FFF6D9" }} />
          <div className="mt-2 text-base" style={{ color: GOLD }}>{hijri.label}</div>
        </div>
        <div className={card} style={cardStyle as any}>
