/* ─── 10. Haftanın Hutbesi (Dengbêj Podcast) ─── */
export function HutbePanel({ onBack }: { onBack: () => void }) {
  const { list, loading, progress: progressMap, markPosition } = useHutbeArchive();
  const { speak, stop, status, activeKey, subtitle, progress, currentTime, duration } = useDengbejTTS();
  const [activeId, setActiveId] = useState<string | null>(null);
  const [autoNext, setAutoNext] = useState(true);

  // Auto-select latest if nothing chosen
  useEffect(() => {
    if (!activeId && list.length) setActiveId(list[0].id);
  }, [list, activeId]);

  const active = list.find((h) => h.id === activeId) ?? null;
  const key = active ? `hutbe-${active.id}` : "";
  const playing = activeKey === key && (status === "playing" || status === "loading");

  // Persist position every ~2s
  useEffect(() => {
    if (!active || !playing || !duration) return;
    const completed = progress > 0.97;
    void markPosition(active.id, currentTime, completed);
  }, [active, playing, currentTime, duration, progress, markPosition]);

  // Auto-next when one finishes
  const finishedRef = useRef<string | null>(null);
  useEffect(() => {
    if (status === "playing" && active) finishedRef.current = active.id;
    if (status === "idle" && finishedRef.current && autoNext) {
      const finishedId = finishedRef.current;
      finishedRef.current = null;
      const idx = list.findIndex((h) => h.id === finishedId);
      const nxt = idx >= 0 ? list[idx + 1] : null;
      if (nxt) {
        setActiveId(nxt.id);
        setTimeout(() => {
          void speak(nxt.content, `hutbe-${nxt.id}`, "tr", nxt.title);
        }, 600);
      }
    }
  }, [status, active, list, autoNext, speak]);

  const playActive = () => {
    if (!active) return;
    if (playing) { stop(); return; }
    void speak(active.content, key, "tr", active.title);
  };

  return (
    <div>
      <Header title="Hutbe Podcast" onBack={onBack} icon={Building2} />
      {loading ? <Loader2 className="h-5 w-5 animate-spin opacity-60 mx-auto my-8" /> :
       list.length === 0 ? (
        <p className={card + " text-center text-sm"} style={cardStyle as any}>
          Henüz hutbe yayınlanmadı.
        </p>
       ) : (
        <div className="space-y-3">
          {/* Now playing card */}
          {active && (
            <div className={card} style={cardStyle as any}>
              <div className="flex items-center justify-between gap-3">
                <div className="text-[10px] uppercase tracking-[0.22em]" style={{ color: GOLD }}>
                  {new Date(active.week_of).toLocaleDateString("tr-TR")}
                </div>
                <div className="flex items-center gap-1.5">
                  <button onClick={() => setAutoNext((v) => !v)}
                    className="text-[9px] uppercase tracking-[0.18em] px-2 py-1 rounded-full"
                    style={{
                      background: autoNext ? "rgba(212,175,55,0.18)" : "transparent",
                      border: `1px solid ${autoNext ? GOLD : "rgba(212,175,55,0.3)"}`,
                      color: autoNext ? "#FFE89A" : "rgba(245,230,184,0.7)",
                    }}>
                    Auto-Next
                  </button>
                  <button onClick={playActive}
                    className="h-9 px-3 rounded-full flex items-center gap-1.5 text-[11px]"
                    style={{ background: playing ? GOLD : "rgba(212,175,55,0.18)", color: playing ? "#0A0700" : GOLD, fontWeight: 600 }}>
                    {status === "loading" && playing ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> :
                     playing ? <Pause className="h-3.5 w-3.5" /> : <Play className="h-3.5 w-3.5" />}
                    {playing ? "Durdur" : (progressMap.get(active.id)?.position_sec ?? 0) > 5 ? "Devam Et" : "Dinle"}
                  </button>
                </div>
              </div>
              <h3 className="mt-2 text-lg" style={{ fontFamily: "'Cinzel'", color: "#FFF6D9" }}>{active.title}</h3>
              {playing && (
                <div className="mt-3 space-y-2">
                  <div className="h-1 rounded-full overflow-hidden" style={{ background: "rgba(212,175,55,0.15)" }}>
                    <div className="h-full" style={{ width: `${progress * 100}%`, background: GOLD, transition: "width 200ms linear" }} />
                  </div>
                  {subtitle && <div className="text-[12px] italic" style={{ color: "#FFE89A" }}>{subtitle}</div>}
                </div>
              )}
              <p className="mt-3 text-sm leading-relaxed whitespace-pre-wrap" style={{ color: "#F5E6B8" }}>{active.content}</p>
              {active.author && <div className="mt-4 text-[11px]" style={{ color: "rgba(245,230,184,0.6)" }}>— {active.author}</div>}
            </div>
          )}

          {/* Episode list */}
          <div>
            <div className="text-[10px] uppercase tracking-[0.22em] mb-2 px-1" style={{ color: "rgba(212,175,55,0.7)" }}>
              Bölümler · {list.length}
            </div>
            <div className="space-y-1.5">
              {list.map((h) => {
                const p = progressMap.get(h.id);
                const isActive = h.id === activeId;
                return (
                  <button key={h.id} onClick={() => setActiveId(h.id)}
                    className={card + " w-full text-left flex items-center justify-between gap-2"}
                    style={{
                      ...(cardStyle as any),
                      borderColor: isActive ? GOLD : (cardStyle as any).borderColor,
                      background: isActive ? "rgba(212,175,55,0.08)" : (cardStyle as any).background,
                    }}>
                    <div className="min-w-0">
                      <div className="text-[13px] truncate" style={{ color: "#FFF6D9" }}>{h.title}</div>
                      <div className="text-[10px] mt-0.5" style={{ color: "rgba(245,230,184,0.6)" }}>
                        {new Date(h.week_of).toLocaleDateString("tr-TR")}
                        {p?.completed && " · ✓ Tamamlandı"}
                        {p && !p.completed && p.position_sec > 5 && ` · ${Math.round(p.position_sec)}sn'de kaldı`}
                      </div>
                    </div>
                    <ChevronRight className="h-4 w-4 flex-shrink-0" style={{ color: GOLD }} />
                  </button>
                );
              })}
            </div>
          </div>
        </div>
       )}
    </div>
  );
}

