/* ─── 12. Yakın Camiler ─── */
export function CamilerPanel({ onBack }: { onBack: () => void }) {
  const [coords, setCoords] = useState<{ lat: number; lon: number } | null>(null);
  const [mosques, setMosques] = useState<Array<{ id: number; name: string; lat: number; lon: number; dist: number }>>([]);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const find = () => {
    if (!navigator.geolocation) { setErr("Konum desteklenmiyor"); return; }
    setLoading(true); setErr(null);
    navigator.geolocation.getCurrentPosition(async (pos) => {
      const { latitude: lat, longitude: lon } = pos.coords;
      setCoords({ lat, lon });
      const mirrors = [
        "https://overpass-api.de/api/interpreter",
        "https://overpass.kumi.systems/api/interpreter",
        "https://overpass.openstreetmap.ru/api/interpreter",
      ];
      const q = `[out:json][timeout:25];(node["amenity"="place_of_worship"]["religion"="muslim"](around:8000,${lat},${lon});way["amenity"="place_of_worship"]["religion"="muslim"](around:8000,${lat},${lon}););out center 50;`;
      let data: any = null;
      for (const m of mirrors) {
        try {
          const res = await fetch(m, { method: "POST", body: "data=" + encodeURIComponent(q), headers: { "Content-Type": "application/x-www-form-urlencoded" } });
          if (!res.ok) continue;
          data = await res.json();
          if (data?.elements?.length >= 0) break;
        } catch { /* try next */ }
      }
      if (!data) { setErr("Veri alınamadı (Overpass erişilemiyor)"); setLoading(false); return; }
      const list = (data.elements as any[]).map((e) => {
        const elat = e.lat ?? e.center?.lat;
        const elon = e.lon ?? e.center?.lon;
        if (elat == null || elon == null) return null;
        return { id: e.id, name: e.tags?.name || e.tags?.["name:tr"] || "Cami", lat: elat, lon: elon, dist: distKm(lat, lon, elat, elon) };
      }).filter(Boolean).sort((a: any, b: any) => a.dist - b.dist) as any[];
      setMosques(list);
      if (!list.length) setErr("8 km içinde cami bulunamadı");
      setLoading(false);
    }, () => { setErr("Konum reddedildi"); setLoading(false); });
  };

  return (
    <div>
      <Header title="Yakın Camiler" onBack={onBack} icon={MapPin} />
      {!coords && (
        <button onClick={find} disabled={loading}
          className="w-full py-3 rounded-full text-[13px]"
          style={{ background: GOLD, color: "#0A0700", fontWeight: 600 }}>
          {loading ? "Aranıyor…" : "Yakındaki Camileri Bul"}
        </button>
      )}
      {err && <p className="mt-3 text-sm" style={{ color: BORDO }}>{err}</p>}
      {mosques.length > 0 && (
        <div className="mt-4 space-y-2">
          {mosques.map((m) => (
            <a key={m.id} target="_blank" rel="noreferrer"
              href={`https://www.openstreetmap.org/?mlat=${m.lat}&mlon=${m.lon}#map=18/${m.lat}/${m.lon}`}
              className={card + " flex items-center justify-between"} style={cardStyle as any}>
              <span style={{ color: "#FFF6D9" }}>{m.name}</span>
              <span className="text-[11px] tabular-nums" style={{ color: GOLD }}>{m.dist.toFixed(2)} km</span>
            </a>
          ))}
        </div>
      )}
    </div>
  );
}
function distKm(a1: number, a2: number, b1: number, b2: number) {
  const r = 6371; const t = (x: number) => x * Math.PI / 180;
  const dlat = t(b1 - a1), dlon = t(b2 - a2);
  const h = Math.sin(dlat/2)**2 + Math.cos(t(a1)) * Math.cos(t(b1)) * Math.sin(dlon/2)**2;
  return 2 * r * Math.asin(Math.sqrt(h));
}

