export function OnlineZikirPanel({ onBack }: { onBack: () => void }) {
  const [rows, setRows] = useState<Array<{ zikir: string; total: number }>>([]);
  const [loading, setLoading] = useState(true);

  const refresh = () => {
    supabase.from("global_tesbih").select("zikir, total").order("total", { ascending: false })
