/**
 * RitualProCountdown — "Vaktin Çıkmasına" hero countdown.
 *
 * Big high-end white digits over deep glassmorphism. Live-ticking seconds,
 * a horizontal timeline of all 6 prayers (current = Jiyan Gold + glowing
 * pulse), city + Hijri footer, and a small "Kerahate kalan" indicator in
 * an elegant serif when the active prayer window is closing.
 *
 * Designed to work in two modes:
 *   variant="hero"    — full-bleed Ritual page top.
 *   variant="widget"  — compact home-grid tile (col-span-4 friendly).
 *
 * Tappable: navigates to /ritual on click in widget mode.
 */
import { useEffect, useMemo, useState } from "react";
import { Link } from "@tanstack/react-router";
import { useRitualClock } from "@/hooks/useRitualClock";
import {
  PRAYER_LABELS_TR,
  formatHHMM,
  type PrayerName,
} from "@/lib/ritualTimes";

const ORDER: PrayerName[] = ["fajr", "sunrise", "dhuhr", "asr", "maghrib", "isha"];
const SHORT_TR: Record<PrayerName, string> = {
  fajr: "İmsak",
  sunrise: "Güneş",
  dhuhr: "Öğle",
  asr: "İkindi",
  maghrib: "Akşam",
  isha: "Yatsı",
};

function pad(n: number) {
  return String(n).padStart(2, "0");
}
function liveCountdown(target: Date, now: Date) {
  let ms = target.getTime() - now.getTime();
  if (ms < 0) ms = 0;
  const total = Math.floor(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return { h, m, s, ms };
}

export interface RitualProCountdownProps {
  variant?: "hero" | "widget";
  className?: string;
}

export function RitualProCountdown({ variant = "hero", className = "" }: RitualProCountdownProps) {
  const { schedule, next, city, hijri } = useRitualClock();
  const [now, setNow] = useState(() => new Date());

  // 1-second ticker (only this component pays for it).
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  const cd = useMemo(
    () => (next ? liveCountdown(next.at, now) : null),
    [next, now],
  );

  // Active prayer = the most-recently-started one (used for timeline glow).
  const activeName: PrayerName | null = useMemo(() => {
    if (!schedule) return null;
    let active: PrayerName | null = null;
    for (const n of ORDER) {
      if (schedule[n].getTime() <= now.getTime()) active = n;
    }
    return active;
  }, [schedule, now]);

  // Kerahat = last 30 min before next prayer is the closing window of the
  // active one. Surface as elegant secondary line when within that window.
  const kerahatLeftMin = cd && cd.ms < 30 * 60_000 ? Math.ceil(cd.ms / 60_000) : null;

  const isHero = variant === "hero";

  const Body = (
    <div
      className={`relative overflow-hidden ${
        isHero ? "rounded-[28px] px-6 py-7" : "rounded-2xl px-4 py-4"
      } ${className}`}
      style={{
        background:
          "linear-gradient(155deg, rgba(18,12,4,0.92) 0%, rgba(8,6,2,0.96) 60%, rgba(14,10,4,0.92) 100%)",
        border: "1px solid rgba(212,175,55,0.32)",
        backdropFilter: "blur(60px) saturate(180%)",
        WebkitBackdropFilter: "blur(60px) saturate(180%)",
        boxShadow:
          "0 30px 80px -40px rgba(0,0,0,0.85), 0 0 0 1px rgba(212,175,55,0.06) inset, 0 1px 0 rgba(255,230,160,0.05) inset",
      }}
    >
      {/* Soft gold aura behind the digits */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-x-8 -top-10 h-32 blur-3xl opacity-60"
        style={{
          background:
            "radial-gradient(closest-side, rgba(212,175,55,0.35), transparent 70%)",
        }}
      />

      {/* Header line */}
      <div className="relative flex items-center justify-between">
        <span
          className="text-[10px] uppercase"
          style={{ color: "rgba(212,175,55,0.85)", letterSpacing: "0.34em" }}
        >
          Vaktin Çıkmasına
        </span>
        {next && (
          <span
            className="text-[10px] uppercase tabular-nums"
            style={{ color: "rgba(245,230,184,0.7)", letterSpacing: "0.22em" }}
          >
            {PRAYER_LABELS_TR[next.name]} · {formatHHMM(next.at)}
          </span>
        )}
      </div>

      {/* Massive digits */}
      <div className="relative mt-3 flex items-end justify-center gap-2">
        {cd ? (
          <>
            <DigitGroup value={pad(cd.h)} hero={isHero} />
            <Sep hero={isHero} />
            <DigitGroup value={pad(cd.m)} hero={isHero} />
            <Sep hero={isHero} />
            <DigitGroup value={pad(cd.s)} hero={isHero} ticking />
          </>
        ) : (
          <span
            className="text-base"
            style={{ color: "rgba(245,230,184,0.7)" }}
          >
            Vakit hesaplanıyor…
          </span>
        )}
      </div>

      {/* Hour / Min / Sec captions */}
      {cd && (
        <div className="relative mt-1 flex items-start justify-center gap-2">
          {["SAAT", "DAKİKA", "SANİYE"].map((c) => (
            <span
              key={c}
              className={`text-center ${isHero ? "w-[72px]" : "w-[52px]"} text-[9px] uppercase`}
              style={{
                color: "rgba(245,230,184,0.45)",
                letterSpacing: "0.32em",
              }}
            >
              {c}
            </span>
          ))}
        </div>
      )}

      {/* Kerahat indicator */}
      {kerahatLeftMin != null && (
        <p
          className="relative mt-3 text-center"
          style={{
            fontFamily: "'Cinzel', 'Times New Roman', serif",
            fontStyle: "italic",
            fontWeight: 300,
            fontSize: isHero ? 13 : 11,
            color: "rgba(255,220,140,0.85)",
            letterSpacing: "0.04em",
          }}
        >
          Kerahate kalan süre · {kerahatLeftMin} dakika
        </p>
      )}

      {/* Prayer timeline */}
      {schedule && (
        <ol
          className={`relative mt-${isHero ? "5" : "4"} grid list-none p-0 m-0`}
          style={{ gridTemplateColumns: "repeat(6, minmax(0, 1fr))", gap: 4 }}
        >
          {ORDER.map((name) => {
            const at = schedule[name];
            const isActive = activeName === name;
            const isNext = next?.name === name;
            return (
              <li
                key={name}
                aria-current={isActive ? "time" : undefined}
                className="relative flex flex-col items-center justify-center rounded-xl py-2"
                style={{
                  background: isActive
                    ? "linear-gradient(180deg, rgba(212,175,55,0.32), rgba(212,175,55,0.08))"
                    : isNext
                      ? "rgba(212,175,55,0.06)"
                      : "transparent",
                  border: isActive
                    ? "1px solid rgba(255,215,90,0.85)"
                    : "1px solid rgba(212,175,55,0.12)",
                  boxShadow: isActive
                    ? "0 0 22px rgba(212,175,55,0.55), 0 0 0 1px rgba(255,230,160,0.25) inset"
                    : "none",
                  animation: isActive ? "ritual-pulse 2.4s ease-in-out infinite" : undefined,
                }}
              >
                <span
                  className="text-[8.5px] uppercase truncate max-w-full"
                  style={{
                    color: isActive ? "#FFF6D9" : "rgba(245,230,184,0.62)",
                    letterSpacing: "0.18em",
                  }}
                >
                  {SHORT_TR[name]}
                </span>
                <span
                  className="mt-0.5 text-[11px] tabular-nums"
                  style={{
                    color: isActive ? "#FFE89A" : "rgba(245,230,184,0.85)",
                    fontWeight: 300,
                  }}
                >
                  {formatHHMM(at)}
                </span>
              </li>
            );
          })}
        </ol>
      )}

      {/* Footer: city + Hijri */}
      <div className="relative mt-3 flex items-center justify-between">
        <span
          className="text-[10px] uppercase"
          style={{ color: "rgba(245,230,184,0.55)", letterSpacing: "0.24em" }}
        >
          {city}
        </span>
        {hijri && (
          <span
            className="text-[10px]"
            style={{
              color: "rgba(245,230,184,0.55)",
              fontFamily: "'Cinzel', serif",
              letterSpacing: "0.08em",
            }}
          >
            {hijri}
          </span>
        )}
      </div>

      <style>{`
        @keyframes ritual-pulse {
          0%, 100% { box-shadow: 0 0 18px rgba(212,175,55,0.45), 0 0 0 1px rgba(255,230,160,0.25) inset; }
          50%      { box-shadow: 0 0 32px rgba(255,215,90,0.85), 0 0 0 1px rgba(255,230,160,0.45) inset; }
        }
        @keyframes ritual-tick {
          0%   { transform: translateY(-2px); opacity: 0; }
          40%  { transform: translateY(0); opacity: 1; }
          100% { transform: translateY(0); opacity: 1; }
        }
      `}</style>
    </div>
  );

  if (variant === "widget") {
    return (
      <Link
        to="/ritual"
        aria-label="Ritüel Sarayı"
        className="block focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[rgba(212,175,55,0.6)] rounded-2xl"
      >
        {Body}
      </Link>
    );
  }
  return Body;
}

/* ─────────── building blocks ─────────── */

function DigitGroup({ value, hero, ticking }: { value: string; hero: boolean; ticking?: boolean }) {
  return (
    <span
      className="inline-flex items-baseline tabular-nums"
      style={{
        color: "#FFFFFF",
        fontFamily: "'SF Pro Display', 'Inter', system-ui",
        fontWeight: 200,
        fontSize: hero ? 64 : 38,
        lineHeight: 1,
