      {value}
    </span>
  );
}

function Sep({ hero }: { hero: boolean }) {
  return (
    <span
      aria-hidden
      style={{
        color: "rgba(212,175,55,0.7)",
        fontWeight: 200,
        fontSize: hero ? 56 : 32,
        lineHeight: 1,
        transform: "translateY(-4px)",
      }}
    >
      :
    </span>
  );
}

