function dailyIndex(modulo: number) {
  const d = new Date();
  const day = Math.floor(d.getTime() / 86_400_000);
  return ((day % modulo) + modulo) % modulo;
}

type SlotId = "ayet" | "hadis" | "dua";

const SLOT_META: Record<SlotId, { label: string; glyph: string; sub: string }> = {
  ayet: { label: "Ayet", glyph: "آ", sub: "Günün Ayeti" },
  hadis: { label: "Hadis", glyph: "ح", sub: "Günün Hadisi" },
  dua: { label: "Dua", glyph: "د", sub: "Günün Duası" },
};

export function RitualTrinity() {
  const [open, setOpen] = useState<SlotId | null>(null);

