  const hadis = useMemo(() => HADIS_POOL[dailyIndex(HADIS_POOL.length)], []);
  const dua = useMemo(() => DAILY_DUAS[dailyIndex(DAILY_DUAS.length)], []);

  const slots: SlotId[] = ["ayet", "hadis", "dua"];

  return (
    <div className="px-5">
