                    : "0 12px 32px -16px rgba(0,0,0,0.7), 0 0 0 1px rgba(255,230,160,0.08) inset",
                }}
              >
                <span
                  className="text-3xl"
                  style={{
                    fontFamily: "'Amiri', 'Scheherazade New', 'Cinzel', serif",
                    color: "#FFE89A",
                    fontWeight: 300,
                    textShadow: "0 0 12px rgba(212,175,55,0.45)",
                  }}
                >
                  {meta.glyph}
                </span>
              </span>
              <span
                className="text-[10px] uppercase"
                style={{
                  letterSpacing: "0.28em",
                  color: active ? "#FFF6D9" : "rgba(245,230,184,0.7)",
                }}
              >
                {meta.label}
              </span>
            </button>
          );
        })}
      </div>

      {/* 3D Flip card */}
      <div
        className="mt-4"
