import { useEffect, useState, useCallback } from "react";
import { useNavigate } from "@tanstack/react-router";
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command";
import { supabase } from "@/integrations/supabase/client";
import {
  Home, MessageCircle, ShoppingBag, Calendar, Newspaper, BookOpen,
  Users, Wallet, Crown, Shield, Search as SearchIcon, Briefcase,
  Car, HelpCircle, Mic, Vote, Gamepad2, Inbox, Bell, User, Clock,
} from "lucide-react";

interface SearchResult {
  id: string;
  type: "user" | "service" | "article" | "event" | "news";
  title: string;
  subtitle?: string;
  href: string;
}

const PAGES = [
  { label: "Ana Sayfa", href: "/", icon: Home, kw: "home" },
  { label: "Sohbet", href: "/chat", icon: MessageCircle, kw: "dm chat" },
  { label: "Pazar Yeri", href: "/marketplace", icon: ShoppingBag, kw: "market" },
  { label: "Etkinlikler", href: "/events", icon: Calendar, kw: "event" },
  { label: "Haberler", href: "/feed", icon: Newspaper, kw: "news feed" },
  { label: "JiyanPedia", href: "/kurdpedia", icon: BookOpen, kw: "wiki" },
  { label: "Arkadaşlar", href: "/friends", icon: Users, kw: "kişi" },
  { label: "Cüzdan", href: "/wallet", icon: Wallet, kw: "dc money" },
  { label: "Egemenlik (KYC)", href: "/kyc", icon: Crown, kw: "sovereign egemen mühür" },
  { label: "Kurd-ID", href: "/kurd-id", icon: Shield, kw: "id borsa" },

  { label: "Ehliyet Sınavı", href: "/driving-exam", icon: Car, kw: "drive" },
  { label: "Yardım", href: "/help", icon: HelpCircle, kw: "asylum iltica" },
  { label: "Sesli Odalar", href: "/audio-rooms", icon: Mic, kw: "podcast" },
  { label: "E-Devlet", href: "/e-devlet", icon: Vote, kw: "kongre anayasa manifesto whitepaper devlet sovereign" },
  { label: "Oyunlar", href: "/games", icon: Gamepad2, kw: "duello" },
  { label: "Gelen Kutusu", href: "/inbox", icon: Inbox, kw: "mail" },
  { label: "Bildirimler", href: "/notifications", icon: Bell, kw: "" },
  { label: "Profil", href: "/profile", icon: User, kw: "" },
] as const;

const RECENT_KEY = "jiyan_recent_searches";

export function GlobalSearch({ open, onOpenChange }: { open: boolean; onOpenChange: (v: boolean) => void }) {
  const navigate = useNavigate();
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [recent, setRecent] = useState<SearchResult[]>([]);

  useEffect(() => {
    if (open) {
      try {
        const saved = JSON.parse(localStorage.getItem(RECENT_KEY) || "[]");
        setRecent(Array.isArray(saved) ? saved.slice(0, 5) : []);
      } catch { setRecent([]); }
    } else {
      setQuery("");
      setResults([]);
    }
  }, [open]);

  const search = useCallback(async (q: string) => {
    if (q.length < 2) { setResults([]); return; }
    setLoading(true);
    try {
      const [users, services, articles, events, news] = await Promise.all([
        supabase.from("profiles").select("user_id, display_name, username, kurd_id, avatar_url").or(`display_name.ilike.%${q}%,username.ilike.%${q}%,kurd_id.ilike.%${q}%`).limit(5),
        supabase.from("services").select("id, title, category, city").ilike("title", `%${q}%`).eq("is_active", true).limit(5),
        supabase.from("kurdpedia_articles").select("id, title, category").ilike("title", `%${q}%`).eq("is_published", true).limit(5),
        supabase.from("events").select("id, title, city").ilike("title", `%${q}%`).eq("is_published", true).limit(5),
        supabase.from("news_articles").select("id, title, source").ilike("title", `%${q}%`).limit(5),
      ]);

      const out: SearchResult[] = [];
      (users.data || []).forEach((u: any) => out.push({
        id: u.user_id, type: "user",
        title: u.display_name || "Kullanıcı",
        subtitle: u.username ? `@${u.username}` : u.kurd_id || "",
        href: `/profile`,
      }));
      (services.data || []).forEach((s: any) => out.push({
        id: s.id, type: "service", title: s.title,
        subtitle: `${s.category} • ${s.city}`,
        href: `/services/${s.id}`,
      }));
      (articles.data || []).forEach((a: any) => out.push({
        id: a.id, type: "article", title: a.title,
        subtitle: a.category, href: `/kurdpedia/${a.id}`,
      }));
      (events.data || []).forEach((e: any) => out.push({
        id: e.id, type: "event", title: e.title,
        subtitle: e.city, href: `/events/${e.id}`,
      }));
      (news.data || []).forEach((n: any) => out.push({
        id: n.id, type: "news", title: n.title,
        subtitle: n.source, href: `/news/${n.id}`,
      }));

      setResults(out);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const t = setTimeout(() => search(query), 250);
    return () => clearTimeout(t);
  }, [query, search]);

  const go = (item: { href: string; title: string; type?: string; id?: string; subtitle?: string }) => {
    if (item.type && item.id) {
      const next = [{ id: item.id, type: item.type as any, title: item.title, subtitle: item.subtitle, href: item.href }, ...recent.filter(r => r.id !== item.id)].slice(0, 5);
      try { localStorage.setItem(RECENT_KEY, JSON.stringify(next)); } catch {}
    }
    onOpenChange(false);
    navigate({ to: item.href });
  };

  const filteredPages = query
    ? PAGES.filter(p => p.label.toLowerCase().includes(query.toLowerCase()) || p.kw.includes(query.toLowerCase()))
    : PAGES.slice(0, 8);

  const iconFor = (type: string) => {
    switch (type) {
      case "user": return User;
      case "service": return ShoppingBag;
      case "article": return BookOpen;
      case "event": return Calendar;
      case "news": return Newspaper;
      default: return SearchIcon;
    }
  };

  return (
    <CommandDialog open={open} onOpenChange={onOpenChange}>
      <CommandInput
        placeholder="Kullanıcı, hizmet, makale, sayfa ara..."
        value={query}
        onValueChange={setQuery}
      />
      <CommandList>
        <CommandEmpty>{loading ? "Aranıyor..." : "Sonuç bulunamadı."}</CommandEmpty>

        {!query && recent.length > 0 && (
          <>
            <CommandGroup heading="Son Aramalar">
              {recent.map((r) => {
                const Icon = iconFor(r.type);
                return (
                  <CommandItem key={`r-${r.id}`} onSelect={() => go(r)}>
                    <Clock className="mr-2 h-4 w-4 opacity-60" />
                    <Icon className="mr-2 h-4 w-4" />
                    <div className="flex flex-col">
                      <span>{r.title}</span>
                      {r.subtitle && <span className="text-xs text-muted-foreground">{r.subtitle}</span>}
                    </div>
                  </CommandItem>
                );
              })}
            </CommandGroup>
            <CommandSeparator />
          </>
        )}

        {results.length > 0 && (
          <>
            <CommandGroup heading="Sonuçlar">
              {results.map((r) => {
                const Icon = iconFor(r.type);
                return (
                  <CommandItem key={`${r.type}-${r.id}`} onSelect={() => go(r)}>
                    <Icon className="mr-2 h-4 w-4" />
                    <div className="flex flex-col">
                      <span>{r.title}</span>
                      {r.subtitle && <span className="text-xs text-muted-foreground">{r.subtitle}</span>}
                    </div>
                  </CommandItem>
                );
              })}
            </CommandGroup>
            <CommandSeparator />
          </>
        )}

        <CommandGroup heading="Sayfalar">
          {filteredPages.map((p) => (
            <CommandItem key={p.href} onSelect={() => go({ href: p.href, title: p.label })}>
              <p.icon className="mr-2 h-4 w-4" />
              {p.label}
            </CommandItem>
          ))}
        </CommandGroup>
      </CommandList>
    </CommandDialog>
  );
}

export function useGlobalSearch() {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        setOpen((v) => !v);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
  return { open, setOpen };
}

