import { useEffect, useState } from "react";
import { ScanFace } from "lucide-react";
import { useBiometric } from "@/hooks/useBiometric";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";
import { Switch } from "@/components/ui/switch";
import { cn } from "@/lib/utils";

export function BiometricToggle() {
  const { user } = useAuth();
  const { enabled, supported, secureContext, checking, enable, disable } = useBiometric();
  const [isEnabled, setIsEnabled] = useState(enabled);

  const isUnsupported = !supported || !secureContext;
  const isDisabled = checking || !user || isUnsupported;

  useEffect(() => {
    setIsEnabled(enabled);
  }, [enabled]);

  const handleCheckedChange = async (nextValue: boolean) => {
    if (!user) {
      toast.error("Önce giriş yapın");
      return;
    }

    if (isUnsupported) return;

    setIsEnabled(nextValue);

    if (!nextValue) {
      disable();
      return;
    }

    const success = await enable();
    if (!success) setIsEnabled(false);
  };

  return (
    <div
      className={cn(
        "flex items-center gap-3 rounded-2xl border px-3 py-3 transition-all duration-200 ease-in-out",
        isUnsupported
          ? "border-border bg-muted/30 opacity-60"
          : "border-gold/20 bg-gradient-to-r from-gold/10 via-surface to-transparent",
      )}
    >
      <ScanFace className={cn("h-4 w-4 transition-colors duration-200 ease-in-out", isEnabled ? "text-gold" : "text-foreground")} />
      <div className="flex-1">
        <span className="text-sm text-foreground">FaceID / Parmak İzi ile Giriş</span>
        <p className="text-[10px] text-muted-foreground">
          {!user
            ? "Önce giriş yapın"
            : checking
              ? "Cihaz kontrol ediliyor..."
              : isUnsupported
                ? "Cihazınız desteklenmiyor."
                : "Cihaz biyometriği · Veriler cihazda kalır"}
        </p>
      </div>

      <Switch
        checked={isEnabled}
        disabled={isDisabled}
        onCheckedChange={handleCheckedChange}
        aria-label="FaceID / Parmak İzi ile Giriş"
        className="data-[state=checked]:bg-gold data-[state=unchecked]:bg-muted transition-all duration-200 ease-in-out"
      />
    </div>
  );
}

