/**
 * GuestRecoveryCard — Inside /security (Güvenlik Merkezi). When a guest
 * lands here they need to recover their password without logging in. This
 * card runs `supabase.auth.resetPasswordForEmail` and tells them to check
 * their inbox. The link redirects back to /reset-password where they can
 * set a new password.
 */
import { useState } from "react";
import { Mail, Loader2, ShieldCheck, KeyRound } from "lucide-react";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

export function GuestRecoveryCard() {
  const [email, setEmail] = useState("");
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState(false);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;
    setBusy(true);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo:
          typeof window !== "undefined"
            ? `${window.location.origin}/reset-password`
            : undefined,
      });
      if (error) throw error;
      setSent(true);
      toast.success("Kurtarma bağlantısı gönderildi", {
        description: "Posta kutunu kontrol et.",
      });
    } catch (err: any) {
      toast.error(err?.message ?? "Gönderilemedi");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="rounded-3xl border border-amber-400/30 bg-gradient-to-br from-amber-500/10 via-black/50 to-amber-600/5 p-5 space-y-4">
      <div className="flex items-center gap-2">
        <KeyRound className="h-5 w-5 text-amber-300" />
        <h2 className="text-sm font-bold text-amber-100 tracking-wide uppercase">
          Şifremi Unuttum
        </h2>
      </div>
      <p className="text-[11.5px] leading-relaxed text-amber-200/70">
        E-posta adresini gir, sana güvenli bir kurtarma bağlantısı gönderelim.
        Bağlantı 60 dakika geçerlidir ve sadece tek kullanımlıktır.
      </p>

      {sent ? (
        <div className="flex items-center gap-3 rounded-2xl border border-emerald-400/30 bg-emerald-500/10 p-3 text-[12px] text-emerald-200">
          <ShieldCheck className="h-4 w-4 shrink-0" />
          Bağlantı <span className="font-semibold">{email}</span> adresine gönderildi.
        </div>
      ) : (
        <form onSubmit={submit} className="space-y-3">
          <div className="relative">
            <Mail className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-amber-200/60" />
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="ornek@jiyan.world"
              required
              className="h-11 w-full rounded-xl border border-amber-400/30 bg-black/50 pl-10 pr-3 text-sm text-amber-100 placeholder:text-amber-200/30 focus:border-amber-400/70 focus:outline-none"
            />
          </div>
          <Button
            type="submit"
            disabled={busy}
            className="w-full h-11 bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-500 text-black font-semibold shadow-[0_4px_20px_rgba(245,205,83,0.4)]"
          >
            {busy ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" /> Gönderiliyor…
              </>
            ) : (
              "Kurtarma Bağlantısı Gönder"
            )}
          </Button>
        </form>
      )}
    </div>
  );
}

