import { useTrustedDevices } from "@/hooks/useTrustedDevices";
import { Button } from "@/components/ui/button";
import { Smartphone, ShieldOff, Check, Clock } from "lucide-react";

function formatRelative(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60_000);
  if (mins < 1) return "az önce";
  if (mins < 60) return `${mins}d önce`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}sa önce`;
  const days = Math.floor(hrs / 24);
  return `${days}g önce`;
}

export function TrustedDevicesList() {
  const { devices, loading, currentFp, revoke } = useTrustedDevices();

  if (loading) {
    return <div className="text-xs text-muted-foreground py-4">Yükleniyor...</div>;
  }

  if (devices.length === 0) {
    return <div className="text-xs text-muted-foreground py-4">Henüz kayıtlı cihaz yok.</div>;
  }

  return (
    <div className="space-y-2">
      {devices.map((d) => {
        const isCurrent = d.device_fingerprint === currentFp;
        return (
          <div
            key={d.id}
            className={`flex items-center gap-3 rounded-xl border px-3 py-2.5 ${
              d.is_revoked
                ? "border-rose-500/30 bg-rose-500/5 opacity-70"
                : isCurrent
                  ? "border-amber-400/40 bg-amber-400/5"
                  : "border-border bg-surface"
            }`}
          >
            <Smartphone className={`h-4 w-4 ${isCurrent ? "text-amber-300" : "text-muted-foreground"}`} />
            <div className="flex-1 min-w-0">
              <div className="text-sm font-medium text-foreground flex items-center gap-2">
                <span className="truncate">{d.device_label}</span>
                {isCurrent && (
                  <span className="text-[9px] uppercase tracking-wider text-amber-300 bg-amber-400/10 border border-amber-400/30 rounded px-1.5 py-0.5 font-mono">
                    Bu Cihaz
                  </span>
                )}
                {d.is_revoked && (
                  <span className="text-[9px] uppercase tracking-wider text-rose-300 bg-rose-500/10 border border-rose-500/30 rounded px-1.5 py-0.5 font-mono">
                    İptal
                  </span>
                )}
              </div>
              <div className="text-[10px] text-muted-foreground flex items-center gap-1 mt-0.5">
                <Clock className="w-3 h-3" />{formatRelative(d.last_seen_at)}
                {d.approved_at && <><Check className="w-3 h-3 ml-2 text-emerald-400" />onaylı</>}
              </div>
            </div>
            {!isCurrent && !d.is_revoked && (
              <Button
                variant="ghost"
                size="sm"
                className="text-rose-300 hover:text-rose-200 hover:bg-rose-500/10"
                onClick={() => revoke(d.id)}
              >
                <ShieldOff className="w-4 h-4" />
              </Button>
            )}
          </div>
        );
      })}
    </div>
  );
}

