import { useEffect, useMemo, useState } from "react";
import { ShieldCheck } from "lucide-react";
import { useTwoFactor } from "@/hooks/useTwoFactor";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";
import { Switch } from "@/components/ui/switch";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export function TwoFactorToggle() {
  const { user } = useAuth();
  const { enabled, loading, setTwoFactorEnabled } = useTwoFactor();
  const [isEnabled, setIsEnabled] = useState(enabled);
  const [showValidation, setShowValidation] = useState(false);

  const deliveryEmail = useMemo(() => user?.email || "hesabınıza bağlı e-posta", [user?.email]);

  useEffect(() => {
    setIsEnabled(enabled);
    if (enabled) setShowValidation(false);
  }, [enabled]);

  const handleCheckedChange = async (nextValue: boolean) => {
    if (!user) {
      toast.error("Önce giriş yapın");
      return;
    }

    if (nextValue) {
      setIsEnabled(true);
      setShowValidation(true);
      return;
    }

    setShowValidation(false);
    setIsEnabled(false);
    const success = await setTwoFactorEnabled(false);
    if (!success) setIsEnabled(true);
  };

  const handleConfirm = async () => {
    const success = await setTwoFactorEnabled(true);
    if (!success) {
      setIsEnabled(false);
      return;
    }

    setShowValidation(false);
  };

  const handleCancel = () => {
    setShowValidation(false);
    setIsEnabled(false);
