/**
 * SovereignRecoveryFlow — multi-layer "Şifremi Unuttum" inside Settings.
 *
 * Two layers, both available to logged-in users (so they can rehearse
 * recovery) and guests:
 *   1) "Yaşam Anahtarı ile Giriş" — verify the 24-word phrase. If valid,
 *       a magic link is dispatched to the registered backup email so the
 *       user lands back in a fully authenticated session.
 *   2) "Yedek Kanal" — send a Magic Link / password reset to a backup
 *       email or phone number.
 * Success is celebrated with a 3D pulsing Sovereign Star.
 */
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { supabase } from "@/integrations/supabase/client";
import { useSovereignRecovery } from "@/hooks/useSovereignRecovery";
import { Mail, KeyRound, Loader2, ShieldCheck, Sparkles } from "lucide-react";
import { toast } from "sonner";

type Mode = "menu" | "phrase" | "channel" | "success";

export function SovereignRecoveryFlow() {
  const { verifyPhrase } = useSovereignRecovery();
  const [mode, setMode] = useState<Mode>("menu");
  const [busy, setBusy] = useState(false);
  const [email, setEmail] = useState("");
  const [phrase, setPhrase] = useState("");

  const sendMagicLink = async (target: string) => {
    setBusy(true);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(target, {
        redirectTo:
          typeof window !== "undefined"
            ? `${window.location.origin}/reset-password`
            : undefined,
      });
      if (error) throw error;
      setMode("success");
      toast.success("Kurtarma bağlantısı gönderildi");
    } catch (e: any) {
      toast.error(e?.message ?? "Gönderilemedi");
    } finally {
      setBusy(false);
    }
  };

  const submitPhrase = async (e: React.FormEvent) => {
    e.preventDefault();
    const words = phrase
      .trim()
      .split(/\s+/)
      .filter(Boolean);
    if (words.length !== 24) {
      toast.error("24 kelimelik anahtar gerekli");
      return;
    }
    setBusy(true);
    try {
      const ok = await verifyPhrase(words);
      if (!ok) {
        toast.error("Anahtar doğrulanamadı");
        return;
      }
      // Phrase valid — kick a magic link to the backup channel
      if (email) {
        await sendMagicLink(email);
      } else {
        setMode("success");
        toast.success("Yaşam Anahtarı doğrulandı", {
          description: "Yedek e-postanı eklersen tek dokunuşla giriş yapabilirsin.",
        });
      }
    } finally {
      setBusy(false);
    }
  };

  if (mode === "success") {
    return (
      <div className="rounded-3xl border border-amber-400/40 bg-gradient-to-br from-amber-500/15 via-black/60 to-amber-600/5 p-6 text-center">
        <div className="relative mx-auto mb-4 h-20 w-20">
          <div
            className="absolute inset-0 animate-ping rounded-full bg-amber-300/40"
            aria-hidden
          />
          <div className="absolute inset-2 rounded-full bg-gradient-to-br from-amber-300 to-amber-600 shadow-[0_0_40px_rgba(245,200,80,0.7)] flex items-center justify-center">
            <Sparkles className="h-8 w-8 text-black" />
          </div>
        </div>
        <h3 className="text-base font-bold text-amber-100">Egemenlik Geri Kazanıldı</h3>
        <p className="mt-1 text-[12px] text-amber-200/70 max-w-xs mx-auto">
          Posta kutunu kontrol et — kurtarma bağlantısı 60 dk geçerlidir.
        </p>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => {
            setMode("menu");
            setPhrase("");
          }}
          className="mt-4 text-amber-200/70"
        >
          Geri Dön
        </Button>
      </div>
    );
  }

  if (mode === "menu") {
    return (
      <div className="space-y-2">
        <RecoveryRow
          icon={<KeyRound className="h-4 w-4" />}
          title="Yaşam Anahtarı ile Giriş"
          sub="24 kelimelik kurtarma anahtarın"
          onClick={() => setMode("phrase")}
        />
        <RecoveryRow
          icon={<Mail className="h-4 w-4" />}
          title="Yedek Kanal · Magic Link"
          sub="Kayıtlı e-postana kurtarma bağlantısı"
          onClick={() => setMode("channel")}
        />
      </div>
    );
  }

  if (mode === "channel") {
    return (
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (email) sendMagicLink(email);
        }}
        className="rounded-3xl border border-amber-400/25 bg-black/40 p-4 space-y-3"
      >
        <div className="flex items-center gap-2">
          <Mail className="h-4 w-4 text-amber-300" />
          <h4 className="text-sm font-semibold text-amber-100">Yedek E-posta</h4>
        </div>
        <Input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="onda@ornek.com"
          required
          className="bg-black/50 border-amber-400/30 text-amber-100 placeholder:text-amber-200/30"
        />
        <div className="flex gap-2">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => setMode("menu")}
            className="flex-1"
          >
            İptal
          </Button>
          <Button
            type="submit"
            disabled={busy || !email}
            size="sm"
            className="flex-1 bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold"
          >
            {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : "Magic Link Gönder"}
          </Button>
        </div>
      </form>
    );
  }

  // mode === "phrase"
  return (
    <form
      onSubmit={submitPhrase}
      className="rounded-3xl border border-amber-400/25 bg-black/40 p-4 space-y-3"
    >
      <div className="flex items-center gap-2">
        <KeyRound className="h-4 w-4 text-amber-300" />
        <h4 className="text-sm font-semibold text-amber-100">Yaşam Anahtarı</h4>
      </div>
      <textarea
        value={phrase}
        onChange={(e) => setPhrase(e.target.value)}
        rows={4}
        placeholder="24 kelimelik kurtarma anahtarını boşlukla ayırarak yapıştır"
        className="w-full rounded-xl border border-amber-400/30 bg-black/50 px-3 py-2 text-sm text-amber-100 placeholder:text-amber-200/30 focus:border-amber-400/70 focus:outline-none resize-none font-mono"
      />
      <Input
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="Yedek e-posta (opsiyonel)"
        className="bg-black/50 border-amber-400/30 text-amber-100 placeholder:text-amber-200/30"
      />
      <div className="flex gap-2">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={() => setMode("menu")}
          className="flex-1"
        >
          İptal
        </Button>
        <Button
          type="submit"
          disabled={busy}
          size="sm"
          className="flex-1 bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold"
        >
          {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : "Doğrula & Giriş"}
        </Button>
      </div>
    </form>
  );
}

function RecoveryRow({
  icon,
  title,
  sub,
  onClick,
}: {
  icon: React.ReactNode;
  title: string;
  sub: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="group flex w-full items-center gap-3 rounded-2xl border border-amber-400/15 bg-black/30 px-3 py-3 text-left transition-all hover:border-amber-400/45 hover:bg-amber-400/5"
    >
      <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-amber-400/15 text-amber-300 border border-amber-400/30">
        {icon}
      </span>
      <div className="min-w-0 flex-1">
        <p className="text-sm font-semibold text-amber-100">{title}</p>
        <p className="text-[10.5px] text-amber-200/55">{sub}</p>
      </div>
      <ShieldCheck className="h-3.5 w-3.5 text-amber-300/40 group-hover:text-amber-300 transition" />
    </button>
  );
}

