  onClose: () => void;
}

export function SovereignSettingsSheet({ open, onClose }: Props) {
  const navigate = useNavigate();
  const { user, signOut } = useAuth();
  const { data: profile } = useSovereignProfile(user?.id);
  const {
    prefs,
    setSoundEnabled,
    setNotificationsEnabled,
    setGhostMode,
    setHapticIntensity,
  } = useHubPreferences();

  const isGuest = !user;

  const go = (path: string) => {
    hapticTap();
    // Navigate first so the next route mounts immediately, then close the
    // sheet on the next tick. Closing first + setTimeout(220) was racing
    // with the body.overflow cleanup and sometimes left the page locked.
    navigate({ to: path as any });
    requestAnimationFrame(() => onClose());
  };

  const handleSignOut = async () => {
    hapticTap();
    try {
      await signOut();
      toast.success("Oturum kapatıldı");
