        className="w-full mt-1 mb-4 rounded-2xl p-4 flex items-center gap-3 active:scale-[0.99] transition-transform text-left"
        style={{
          background:
            "linear-gradient(140deg, rgba(40,28,5,0.85), rgba(8,5,0,0.96))",
          border: "1px solid rgba(212,175,55,0.35)",
          boxShadow:
            "inset 0 1px 0 rgba(253,230,138,0.18), 0 8px 24px -10px rgba(0,0,0,0.7)",
        }}
      >
        <div
          className="h-12 w-12 rounded-2xl flex items-center justify-center text-lg font-semibold"
          style={{
            background:
              "radial-gradient(120% 100% at 30% 0%, #FFE9A8 0%, #D4AF37 50%, #6E4B0E 100%)",
            color: "#1a0e00",
            boxShadow:
              "inset 0 1px 0 rgba(255,255,255,0.5), 0 4px 12px rgba(0,0,0,0.5)",
          }}
        >
          {profile?.avatarUrl ? (
