          ) : (
            (profile?.displayName?.[0] ?? user?.email?.[0] ?? "S").toUpperCase()
          )}
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-[15px] font-semibold text-amber-50 truncate">
            {isGuest ? "Misafir Ziyaretçi" : profile?.displayName ?? "Sovereign"}
          </p>
          <p className="text-[11px] text-amber-200/60 truncate">
            {isGuest
              ? "Egemen Kimliğinizle giriş yapın"
              : profile?.kurdId
                ? `+777 ${profile.kurdId}`
                : "Jiyan ID, hesap ve gizlilik"}
          </p>
        </div>
        <ChevronRight className="h-4 w-4 text-amber-200/50" />
      </button>

      {/* Quick toggles — inline, no navigation */}
      <SovereignSettingsGroup title="Hızlı Kontrol">
        <ToggleRow
          icon={prefs.soundEnabled ? Volume2 : VolumeX}
          label="Ses"
          sub="Sistem efektleri ve haptik"
          active={prefs.soundEnabled}
          onToggle={() => {
            hapticTap();
            setSoundEnabled(!prefs.soundEnabled);
          }}
        />
        <ToggleRow
          icon={prefs.notificationsEnabled ? Bell : BellOff}
          label="Bildirim"
          sub="Anlık posta + sistem uyarıları"
          active={prefs.notificationsEnabled}
          onToggle={() => {
            hapticTap();
            setNotificationsEnabled(!prefs.notificationsEnabled);
          }}
        />
        <ToggleRow
