            // Defer to the next tick so localStorage is updated before
            // native.ts reads the new intensity.
            setTimeout(() => {
              if (v === "off") return;
              if (v === "low") hapticTap();
              else if (v === "medium") hapticMedium();
              else hapticHeavy();
