import { useEffect, useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { Gift, Copy, Share2, Users } from "lucide-react";
import { toast } from "sonner";

export function ReferralCard() {
  const { user } = useAuth();
  const [code, setCode] = useState<string>("");
  const [stats, setStats] = useState({ uses: 0, earned: 0 });

  useEffect(() => {
    if (!user) return;
    (async () => {
      const { data } = await supabase.rpc("get_or_create_referral_code", { _user_id: user.id });
      if (data) {
        setCode(data as string);
        const { data: row } = await supabase
          .from("referral_codes")
          .select("uses_count, total_earned")
          .eq("user_id", user.id)
          .maybeSingle();
        if (row) setStats({ uses: row.uses_count || 0, earned: Number(row.total_earned) || 0 });
      }
    })();
  }, [user]);

  const link = typeof window !== "undefined" ? `${window.location.origin}/?ref=${code}` : "";

  const copy = async () => {
    await navigator.clipboard.writeText(link);
    toast.success("Link kopyalandı");
  };

  const share = async () => {
    if (navigator.share) {
      try { await navigator.share({ title: "Jiyan'a katıl", text: "Beraber 5 DC kazanalım!", url: link }); } catch {}
    } else copy();
  };

  if (!user) return null;

  return (
    <Card className="p-4 bg-gradient-to-br from-primary/10 via-surface to-neon/5 border-primary/20">
      <div className="flex items-center gap-2 mb-3">
        <div className="h-9 w-9 rounded-xl bg-primary/20 flex items-center justify-center">
          <Gift className="h-4 w-4 text-primary" />
        </div>
        <div>
          <h3 className="text-sm font-semibold">Arkadaşını Davet Et</h3>
          <p className="text-xs text-muted-foreground">Sen 5 DC, o 5 DC kazanır</p>
        </div>
      </div>

      <div className="flex gap-2 mb-3">
        <Input value={code} readOnly className="font-mono text-center font-bold tracking-widest" />
        <Button size="icon" variant="outline" onClick={copy}><Copy className="h-4 w-4" /></Button>
        <Button size="icon" variant="neon" onClick={share}><Share2 className="h-4 w-4" /></Button>
      </div>

      <div className="grid grid-cols-2 gap-2 text-center">
        <div className="rounded-lg bg-surface/60 p-2">
          <div className="flex items-center justify-center gap-1 text-xs text-muted-foreground"><Users className="h-3 w-3" /> Davet</div>
          <div className="text-lg font-bold">{stats.uses}</div>
        </div>
        <div className="rounded-lg bg-surface/60 p-2">
          <div className="text-xs text-muted-foreground">Kazanç</div>
          <div className="text-lg font-bold text-gold">{stats.earned} DC</div>
        </div>
      </div>
    </Card>
  );
}

