import { useEffect, useRef, useState } from "react";
import { Camera, X, AlertTriangle } from "lucide-react";
import type { PresencePoint } from "@/hooks/useSovereignSpace";
import { haversineMeters } from "@/hooks/useSovereignSpace";

interface Props {
  open: boolean;
  onClose: () => void;
  coords: { lat: number; lng: number } | null;
  presences: PresencePoint[];
  simulated: boolean;
}

/**
 * AR-style overlay: tries to open the device camera and projects
 * golden "Sovereign Pillars" + connecting lines on top.
 * Pure CSS — no WebXR / Three.js. Falls back to dark cyber sky if camera denied.
 */
export function ARPillarsView({ open, onClose, coords, presences, simulated }: Props) {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [camErr, setCamErr] = useState<string | null>(null);
  const [streaming, setStreaming] = useState(false);

  useEffect(() => {
    if (!open) return;
    let stream: MediaStream | null = null;
    (async () => {
      try {
        if (!navigator.mediaDevices?.getUserMedia) {
          throw new Error("Kamera desteklenmiyor");
        }
        stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "environment" },
          audio: false,
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play();
          setStreaming(true);
        }
      } catch (e: any) {
        setCamErr(e?.message || "Kamera açılamadı");
      }
    })();
    return () => {
      stream?.getTracks().forEach((t) => t.stop());
      setStreaming(false);
      setCamErr(null);
    };
  }, [open]);

  if (!open) return null;

  // Determine pillar positions for nearby sovereigns + simulated extras
  const realDots = coords
    ? presences
        .map((p) => ({
          id: p.user_id,
          d: haversineMeters(coords.lat, coords.lng, p.latitude, p.longitude),
        }))
        .filter((p) => p.d < 300)
        .slice(0, 8)
    : [];
  const simExtras =
    simulated && realDots.length < 7
      ? Array.from({ length: 7 - realDots.length }).map((_, i) => ({
          id: `s-${i}`,
          d: 80 + i * 25,
        }))
      : [];
  const all = [...realDots, ...simExtras];

  return (
    <div className="fixed inset-0 z-[9998] bg-black overflow-hidden">
      {/* Camera feed */}
      {streaming ? (
        <video
          ref={videoRef}
          playsInline
          muted
          className="absolute inset-0 w-full h-full object-cover"
        />
      ) : (
        <video ref={videoRef} playsInline muted className="hidden" />
      )}
      {!streaming && (
        <div
          aria-hidden
          className="absolute inset-0"
          style={{
            background:
              "radial-gradient(ellipse at top, #1A1A1A 0%, #0A0A0A 70%)",
          }}
        />
      )}

      {/* Dark vignette + grain */}
      <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/70 pointer-events-none" />
      <div className="absolute inset-0 sovereign-grain pointer-events-none" />

      {/* Pillars layer */}
      <div className="absolute inset-0 flex items-end justify-around px-6 pb-32 pointer-events-none">
        {all.map((p, i) => {
          const height = Math.max(30, 80 - (p.d / 300) * 50); // % vh
          const left = (i / Math.max(1, all.length - 1)) * 100;
          return (
            <div
              key={p.id}
              className="absolute bottom-24"
              style={{
                left: `${left}%`,
                transform: "translateX(-50%)",
                height: `${height}vh`,
              }}
            >
              <div
                className="w-3 h-full rounded-t-full"
                style={{
                  background:
                    "linear-gradient(to top, rgba(212,175,55,0.95), rgba(212,175,55,0.6) 50%, rgba(212,175,55,0) 100%)",
                  boxShadow:
                    "0 0 30px rgba(212,175,55,0.85), 0 0 80px rgba(212,175,55,0.45)",
                }}
              />
              <div
                className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-10 h-10 rounded-full"
                style={{
                  background:
                    "radial-gradient(circle, rgba(212,175,55,0.6), transparent 70%)",
                }}
              />
            </div>
          );
        })}
      </div>

      {/* Connecting lines (between pillar bases) */}
      <svg
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        className="absolute inset-0 w-full h-full pointer-events-none"
      >
        {all.map((_, i) => {
          if (i === all.length - 1) return null;
          const x1 = (i / Math.max(1, all.length - 1)) * 100;
          const x2 = ((i + 1) / Math.max(1, all.length - 1)) * 100;
          return (
            <line
              key={i}
              x1={x1}
              y1={75}
              x2={x2}
              y2={75}
              stroke="rgba(212,175,55,0.55)"
              strokeWidth="0.2"
              strokeDasharray="0.8 0.6"
            />
          );
        })}
      </svg>

      {/* HUD */}
      <div className="absolute top-0 left-0 right-0 px-4 pt-safe pt-6 flex items-start justify-between">
        <div className="rounded-xl bg-black/60 border border-amber-400/30 backdrop-blur px-3 py-2">
          <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-amber-300/80">
            AR Sovereign View
          </div>
          <div className="text-sm font-bold text-amber-100 flex items-center gap-1.5">
            <Camera className="w-3.5 h-3.5" />
            {all.length} sütun · {coords ? "GPS aktif" : "GPS yok"}
          </div>
        </div>
        <button
          onClick={onClose}
          className="w-10 h-10 rounded-full bg-black/60 border border-white/20 backdrop-blur flex items-center justify-center text-white/85"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {camErr && (
        <div className="absolute bottom-28 left-4 right-4 rounded-xl bg-amber-400/10 border border-amber-400/30 px-3 py-2 text-[11px] text-amber-200 flex items-center gap-2 backdrop-blur">
          <AlertTriangle className="w-3.5 h-3.5" />
          {camErr} — sembolik gökyüzü modu kullanılıyor
        </div>
      )}

      {/* Bottom motto */}
      <div className="absolute bottom-8 left-0 right-0 text-center">
        <div className="text-[10px] font-mono uppercase tracking-[0.4em] text-amber-300/80">
          Em Sînor in
        </div>
        <div className="text-base font-bold text-amber-100">Em Welat in</div>
      </div>
    </div>
  );
}

