/**
 * AppSheetHost — Mini-app launcher (Aşama 1: 12 çekirdek app).
 *
 * Eski 33-app routing katmanı yerine, artık 12 birleşik mini-app'e
 * navige ediyoruz. Eski ID'ler `resolveAppId` ile yeniye çevrilir
 * (chat→deng, mivankas→pazar, news→akis, …) — kayıtlı widget/dock
 * shortcut'lar otomatik çalışır.
 *
 * Telegram-style swipe-down davranışı route seviyesindeki
 * `useSwipeDownBack` hook'u tarafından sağlanır.
 */
import { createContext, ReactNode, useCallback, useContext, useMemo } from "react";
import { useNavigate } from "@tanstack/react-router";
import { hapticTap } from "@/lib/native";
import { HUB_APPS_BY_ID, resolveAppId } from "@/lib/hubApps";

/**
 * 12 çekirdek mini-app + widget'ların kullandığı bazı eski alias'lar
 * (`mivankas`, `news`, `tv`, `phone`, `edevlet`) — `resolveAppId` zaten
 * remap eder, ama yine de tip güvenli kalsın diye union'da listeliyoruz.
 */
export type AppSheetId =
  | "deng"
  | "dengai"
  | "pazar"
  | "edevlet"
  | "profile"
  | "wallet"
  | "akis"
  | "academy"
  | "keka"
  | "jiyantv"
  | "games"
  | "joogle"
  | "guvenlik"
  | "settings"
  // Legacy aliases — still accepted for backward compat with existing widgets
  | "mivankas"
  | "news"
  | "tv"
  | "phone";

interface AppSheetCtx {
  open: (id: AppSheetId | string) => void;
  close: () => void;
  current: AppSheetId | null;
}

const Ctx = createContext<AppSheetCtx | null>(null);

export function useAppSheet(): AppSheetCtx {
  const c = useContext(Ctx);
  if (!c) return { open: () => {}, close: () => {}, current: null };
  return c;
}

export function AppSheetProvider({ children }: { children: ReactNode }) {
  const navigate = useNavigate();

  const open = useCallback(
    (id: AppSheetId | string) => {
      hapticTap();
      const resolved = resolveAppId(String(id));
      const app = HUB_APPS_BY_ID[resolved];
      if (app?.to) navigate({ to: app.to } as never);
    },
    [navigate],
  );
  const close = useCallback(() => {
    /* no-op — route-level swipe-down handles closing. */
  }, []);

  const value = useMemo<AppSheetCtx>(
    () => ({ open, close, current: null }),
    [open, close],
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

