/**
 * AppTabsBar — Phase 2 minimalist üst sekme şeridi.
 *
 * Aktif route'a göre core app'in alt sekmelerini gösterir. Mevcut sayfa
 * layout'una dokunmaz; sticky olarak ekranın en üstüne yapışır. Hub,
 * auth, sheet host gibi yerlerde gizlidir.
 */
import { Link, useLocation } from "@tanstack/react-router";
import { findAppTabsForPath, isTabActive } from "@/lib/appTabs";

const HIDDEN_PREFIXES = [
  "/hub",
  "/auth",
  "/login",
  "/signup",
  "/onboarding",
  "/boot",
  "/sso",
  "/api",
  "/_dev",
  // Immersive / full-screen experiences — own their internal nav
  "/keka",
  "/jiyan-tv",
  "/games",
  "/leaderboard",
  // Phone is iPhone-style, owns its own bottom dock — no top tabs.
  "/phone",
];

export function AppTabsBar() {
  const { pathname } = useLocation();

  if (pathname === "/" || HIDDEN_PREFIXES.some((p) => pathname.startsWith(p))) {
    return null;
  }

  const group = findAppTabsForPath(pathname);
  if (!group || group.tabs.length < 2) return null;

  return (
    <div
      className="fixed top-0 left-0 right-0 z-[80] w-full pointer-events-none"
      style={{
        paddingTop: "calc(env(safe-area-inset-top) + 14px)",
        // Sayfa içeriğinin altında kalmasın diye global CSS değişkeni;
        // MiniAppOverlay ve diğer wrapper'lar bunu padding-top olarak okur.
        ["--app-tabs-h" as any]: "64px",
      }}
    >
      {/* Okunabilirlik için yumuşak üst gradyan — video/içerik üstünde overlay */}
      <div
        aria-hidden
        className="absolute inset-x-0 top-0 h-32 -z-10"
        style={{
          background:
            "linear-gradient(to bottom, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0.25) 60%, rgba(0,0,0,0) 100%)",
        }}
      />
      <div className="pointer-events-auto mx-auto flex w-fit max-w-[92vw] items-center gap-1 overflow-x-auto rounded-full border border-white/10 bg-white/8 px-1.5 py-1 shadow-[0_8px_32px_rgba(0,0,0,0.45)] backdrop-blur-2xl no-scrollbar mt-2">
        {group.tabs.map((tab) => {
          const active = isTabActive(tab, pathname);
          return (
            <Link
              key={tab.to}
              to={tab.to}
              className={[
                "shrink-0 rounded-full px-4 py-1.5 text-xs font-semibold tracking-wide transition-all",
                active
                  ? "bg-amber-400/95 text-black shadow-[0_0_14px_rgba(212,175,55,0.45)]"
                  : "text-white/85 hover:text-white hover:bg-white/10",
              ].join(" ")}
            >
              {tab.label}
            </Link>
          );
        })}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { ScanFace, ShieldCheck } from "lucide-react";

interface Props {
  displayName: string;
  onComplete: () => void;
}

type Phase = "scanning" | "verifying" | "complete";

/**
 * Centered +777 golden seal animation + simulated FaceID scan.
 * Calls onComplete after the verified phase finishes.
 */
export function BiometricSeal({ displayName, onComplete }: Props) {
  const [phase, setPhase] = useState<Phase>("scanning");
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const t1 = setInterval(() => {
      setProgress((p) => {
        if (p >= 100) {
          clearInterval(t1);
          return 100;
        }
        return p + 2;
      });
    }, 30);
    return () => clearInterval(t1);
  }, []);

  useEffect(() => {
    if (progress >= 100 && phase === "scanning") {
      setPhase("verifying");
      const t = setTimeout(() => setPhase("complete"), 900);
      return () => clearTimeout(t);
    }
    if (phase === "complete") {
      const t = setTimeout(onComplete, 1300);
      return () => clearTimeout(t);
    }
  }, [progress, phase, onComplete]);

  return (
    <div className="fixed inset-0 z-[9999] bg-[#0A0A0A] flex flex-col items-center justify-center px-6 sovereign-grain">
      {/* Outer glow rings */}
      <div className="relative w-64 h-64 flex items-center justify-center">
        <div className="absolute inset-0 rounded-full border border-amber-400/20 animate-[seal-ring_3s_linear_infinite]" />
        <div className="absolute inset-4 rounded-full border border-amber-400/30 animate-[seal-ring_4s_linear_infinite_reverse]" />
        <div className="absolute inset-8 rounded-full border border-cyan-400/20 animate-[seal-ring_5s_linear_infinite]" />

        {/* Scanning beam */}
        {phase === "scanning" && (
          <div className="absolute inset-12 overflow-hidden rounded-full">
            <div className="sovereign-scan-beam" />
          </div>
        )}

        {/* Center medallion */}
        <div className="relative w-44 h-44 rounded-full sovereign-medallion flex flex-col items-center justify-center">
          {phase === "complete" ? (
            <>
              <ShieldCheck className="w-12 h-12 text-amber-300 mb-1 animate-[seal-pop_0.6s_ease-out]" />
              <div className="font-mono text-xl font-bold text-amber-200 tracking-widest">
                +777
              </div>
            </>
          ) : (
            <>
              <ScanFace className="w-12 h-12 text-amber-300/80 mb-1" />
              <div className="font-mono text-xl font-bold text-amber-200/80 tracking-widest">
                +777
              </div>
            </>
          )}
        </div>
      </div>

      {/* Status text */}
      <div className="mt-10 text-center max-w-sm">
        {phase === "scanning" && (
          <>
            <div className="text-[10px] font-mono uppercase tracking-[0.3em] text-amber-300/70 mb-2">
              Biometrik Tarama
            </div>
            <div className="text-base font-semibold text-white/90">
              Egemenliğiniz doğrulanıyor...
            </div>
            <div className="mt-4 h-0.5 w-48 mx-auto bg-white/10 rounded-full overflow-hidden">
              <div
                className="h-full bg-gradient-to-r from-amber-400 via-amber-300 to-cyan-400 transition-[width] duration-100"
                style={{ width: `${progress}%` }}
              />
            </div>
            <div className="mt-2 text-[10px] font-mono opacity-50 tabular-nums">
              {progress}% — sovereign signature analyzed
            </div>
          </>
        )}
        {phase === "verifying" && (
          <>
            <div className="text-[10px] font-mono uppercase tracking-[0.3em] text-cyan-300/70 mb-2">
              Doğrulama
            </div>
            <div className="text-base font-semibold text-white/90">
              Anayasa mührü kontrol ediliyor...
            </div>
          </>
        )}
        {phase === "complete" && (
          <>
            <div className="text-[10px] font-mono uppercase tracking-[0.3em] text-amber-300 mb-2">
              ✓ Egemenlik Doğrulandı
            </div>
            <div className="text-lg font-bold text-amber-100">
              Hoş geldiniz, {displayName}
            </div>
            <div className="text-xs opacity-60 mt-1">
              Sovereign Gateway erişimi açılıyor
            </div>
          </>
        )}
      </div>
    </div>
  );
}

