import { useState } from "react";
import { Link } from "@tanstack/react-router";
import { ShieldAlert, Check, X, MinusCircle, Vote, Clock } from "lucide-react";
import { useCivat, type VoteChoice, type CivatProposal } from "@/hooks/useCivat";
import { toast } from "sonner";

const CATEGORY_LABEL: Record<CivatProposal["category"], string> = {
  governance: "Yönetim",
  finance: "Finans",
  culture: "Kültür",
  technology: "Teknoloji",
  social: "Sosyal",
};

const CATEGORY_COLOR: Record<CivatProposal["category"], string> = {
  governance: "text-cyan-300 bg-cyan-400/10 border-cyan-400/30",
  finance: "text-amber-300 bg-amber-400/10 border-amber-400/30",
  culture: "text-rose-300 bg-rose-400/10 border-rose-400/30",
  technology: "text-violet-300 bg-violet-400/10 border-violet-400/30",
  social: "text-emerald-300 bg-emerald-400/10 border-emerald-400/30",
};

function timeRemaining(endsAt: string) {
  const ms = new Date(endsAt).getTime() - Date.now();
  if (ms <= 0) return "Süre doldu";
  const days = Math.floor(ms / 86_400_000);
  const hrs = Math.floor((ms % 86_400_000) / 3_600_000);
  if (days > 0) return `${days}g ${hrs}s kaldı`;
  return `${hrs} saat kaldı`;
}

export function CivatVotingPanel() {
  const { proposals, myVotes, loading, eligible, castVote } = useCivat();
  const active = proposals.filter((p) => p.status === "active");

  if (loading) {
    return (
      <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-6 text-center text-xs opacity-60">
        Civat oturumu yükleniyor...
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {!eligible && (
        <div className="rounded-2xl border border-amber-400/30 bg-amber-500/5 p-3 flex items-start gap-3">
          <ShieldAlert className="w-4 h-4 text-amber-300 shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <div className="text-xs font-bold text-amber-100">Oy hakkı kilitli</div>
            <div className="text-[11px] opacity-70 mt-0.5">
              Civat'ta oy kullanmak için KYC + Anayasa mührü gerekir.
            </div>
            <div className="flex gap-2 mt-2">
              <Link
                to="/kyc"
                className="text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded bg-amber-400/20 border border-amber-400/40 text-amber-100"
              >
                KYC Tamamla
              </Link>
              <Link
                to="/manifesto"
                className="text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded bg-cyan-400/15 border border-cyan-400/30 text-cyan-100"
              >
                Anayasayı Mühürle
              </Link>
            </div>
          </div>
        </div>
      )}

      {active.length === 0 ? (
        <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-6 text-center">
          <Vote className="w-6 h-6 mx-auto opacity-40 mb-2" />
          <div className="text-xs opacity-60">
            Şu anda onayınızı bekleyen aktif karar bulunmuyor.
          </div>
        </div>
      ) : (
        active.map((p) => (
          <ProposalCard
            key={p.id}
            proposal={p}
            myVote={myVotes[p.id]}
            eligible={eligible}
            onVote={castVote}
          />
        ))
      )}
    </div>
  );
}

function ProposalCard({
  proposal,
  myVote,
  eligible,
  onVote,
}: {
  proposal: CivatProposal;
  myVote?: VoteChoice;
  eligible: boolean;
  onVote: (id: string, v: VoteChoice) => Promise<{ ok: boolean; error?: string }>;
}) {
  const [busy, setBusy] = useState<VoteChoice | null>(null);
  const total = proposal.yes_count + proposal.no_count + proposal.abstain_count;
  const pct = (n: number) => (total === 0 ? 0 : Math.round((n / total) * 100));

  const handle = async (v: VoteChoice) => {
    if (!eligible) {
      toast.error("Oy kullanmak için KYC + Anayasa mührü gerekir");
      return;
    }
    setBusy(v);
    const r = await onVote(proposal.id, v);
    setBusy(null);
    if (r.ok) toast.success("Oyunuz kaydedildi");
    else toast.error(r.error || "Oy kaydedilemedi");
  };

  return (
    <div className="rounded-2xl border border-white/10 bg-gradient-to-br from-white/[0.04] to-white/[0.01] p-4 backdrop-blur-xl">
      <div className="flex items-start justify-between gap-2 mb-2">
        <span
          className={`text-[9px] font-bold uppercase tracking-widest px-2 py-0.5 rounded-full border ${CATEGORY_COLOR[proposal.category]}`}
        >
          {CATEGORY_LABEL[proposal.category]}
        </span>
        <span className="text-[10px] font-mono opacity-60 flex items-center gap-1">
          <Clock className="w-3 h-3" />
          {timeRemaining(proposal.ends_at)}
        </span>
      </div>

      <h3 className="font-bold text-sm text-amber-100 leading-snug mb-1">
        {proposal.title}
      </h3>
      <p className="text-[11px] opacity-75 leading-relaxed mb-3">
        {proposal.summary}
      </p>

      {/* Tally bar */}
      <div className="flex h-1.5 rounded-full overflow-hidden bg-white/5 mb-2">
        <div
          className="bg-emerald-400/80 transition-[width]"
          style={{ width: `${pct(proposal.yes_count)}%` }}
        />
        <div
          className="bg-rose-400/80 transition-[width]"
          style={{ width: `${pct(proposal.no_count)}%` }}
        />
        <div
          className="bg-white/30 transition-[width]"
          style={{ width: `${pct(proposal.abstain_count)}%` }}
        />
      </div>
      <div className="flex justify-between text-[10px] font-mono opacity-70 mb-3">
        <span className="text-emerald-300">Lê {proposal.yes_count} ({pct(proposal.yes_count)}%)</span>
        <span className="text-rose-300">Na {proposal.no_count} ({pct(proposal.no_count)}%)</span>
        <span>Çekimser {proposal.abstain_count}</span>
      </div>

      <div className="grid grid-cols-3 gap-2">
        <VoteButton
          label="Lê (Onay)"
          icon={<Check className="w-3.5 h-3.5" />}
          active={myVote === "yes"}
          tone="emerald"
          disabled={!eligible || busy !== null}
          loading={busy === "yes"}
          onClick={() => handle("yes")}
        />
        <VoteButton
          label="Na (Ret)"
          icon={<X className="w-3.5 h-3.5" />}
          active={myVote === "no"}
          tone="rose"
          disabled={!eligible || busy !== null}
          loading={busy === "no"}
          onClick={() => handle("no")}
        />
        <VoteButton
          label="Çekimser"
          icon={<MinusCircle className="w-3.5 h-3.5" />}
          active={myVote === "abstain"}
          tone="neutral"
          disabled={!eligible || busy !== null}
          loading={busy === "abstain"}
          onClick={() => handle("abstain")}
        />
      </div>
    </div>
  );
}

function VoteButton({
  label,
  icon,
  active,
  tone,
  disabled,
  loading,
  onClick,
}: {
  label: string;
  icon: React.ReactNode;
  active: boolean;
  tone: "emerald" | "rose" | "neutral";
  disabled: boolean;
  loading: boolean;
  onClick: () => void;
}) {
  const tones = {
    emerald: active
      ? "bg-emerald-400/25 border-emerald-300/60 text-emerald-100"
      : "border-white/10 hover:border-emerald-400/40 hover:bg-emerald-400/5",
    rose: active
      ? "bg-rose-400/25 border-rose-300/60 text-rose-100"
      : "border-white/10 hover:border-rose-400/40 hover:bg-rose-400/5",
    neutral: active
      ? "bg-white/15 border-white/40 text-white"
      : "border-white/10 hover:border-white/30 hover:bg-white/5",
  };
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={`flex items-center justify-center gap-1 py-2 rounded-xl border text-[11px] font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed ${tones[tone]}`}
    >
      {loading ? (
        <span className="w-3.5 h-3.5 border-2 border-current border-t-transparent rounded-full animate-spin" />
      ) : (
        icon
      )}
      {label}
    </button>
  );
}

