import { useState } from "react";
import { MapPin, Plus, Sparkles, Lock, Unlock, ScrollText, Music } from "lucide-react";
import type { Totem } from "@/hooks/useSovereignSpace";
import { haversineMeters } from "@/hooks/useSovereignSpace";

interface Props {
  coords: { lat: number; lng: number } | null;
  totems: Totem[];
  unlockedIds: Set<string>;
  nearbyTotems: { t: Totem; d: number }[];
  onDrop: (input: {
    title: string;
    content: string;
    content_type: Totem["content_type"];
  }) => Promise<Totem>;
}

const TYPE_META = {
  message: { icon: Sparkles, label: "Mesaj", color: "text-amber-200" },
  dengbej: { icon: Music, label: "Dengbêj", color: "text-cyan-300" },
  doctrine: { icon: ScrollText, label: "Doktrin", color: "text-amber-300" },
} as const;

export function DigitalTotem({
  coords,
  totems,
  unlockedIds,
  nearbyTotems,
  onDrop,
}: Props) {
  const [showForm, setShowForm] = useState(false);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [type, setType] = useState<Totem["content_type"]>("message");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const submit = async () => {
    if (!title.trim() || !coords) return;
    setBusy(true);
    setErr(null);
    try {
      await onDrop({ title: title.trim(), content: content.trim(), content_type: type });
      setTitle("");
      setContent("");
      setShowForm(false);
    } catch (e: any) {
      setErr(e.message || "Mühür bırakılamadı");
    } finally {
      setBusy(false);
    }
  };

  const nearbyIds = new Set(nearbyTotems.map((n) => n.t.id));
  const sorted = coords
    ? [...totems].sort(
        (a, b) =>
          haversineMeters(coords.lat, coords.lng, a.latitude, a.longitude) -
          haversineMeters(coords.lat, coords.lng, b.latitude, b.longitude),
      )
    : totems;

  return (
    <div className="relative rounded-3xl overflow-hidden border border-amber-400/15 bg-gradient-to-b from-[#13100A] to-[#0A0A0A] p-5 sovereign-grain">
      <div className="relative z-10 flex items-start justify-between mb-3">
        <div>
          <div className="text-[10px] font-mono tracking-[0.3em] text-amber-300/80 uppercase">
            Digital Totem
          </div>
          <div className="text-base font-semibold text-amber-100 mt-0.5">
            Hafıza Çivisi
          </div>
        </div>
        <button
          onClick={() => setShowForm((s) => !s)}
          disabled={!coords}
          className="px-3 h-9 rounded-full bg-amber-400/15 border border-amber-400/40 text-amber-200 text-xs font-medium uppercase tracking-widest flex items-center gap-1.5 disabled:opacity-40"
        >
          <Plus className="w-3.5 h-3.5" />
          Mühür
        </button>
      </div>

      {/* Form */}
      {showForm && (
        <div className="relative z-10 mb-4 rounded-2xl bg-black/40 border border-amber-400/20 p-3 space-y-2 animate-[fade-in_0.2s_ease-out]">
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            maxLength={80}
            placeholder="Mührün adı (örn: 'Bu meydanda durdum')"
            className="w-full bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-sm text-amber-100 placeholder:text-white/30 focus:outline-none focus:border-amber-400/50"
          />
          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            maxLength={500}
            rows={2}
            placeholder="Mesaj, dize, doktrin parçası…"
            className="w-full bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-sm text-amber-100 placeholder:text-white/30 focus:outline-none focus:border-amber-400/50 resize-none"
          />
          <div className="flex gap-1.5">
            {(Object.keys(TYPE_META) as Array<keyof typeof TYPE_META>).map((k) => {
              const M = TYPE_META[k];
              const Icon = M.icon;
              const sel = type === k;
              return (
                <button
                  key={k}
                  onClick={() => setType(k)}
                  className={`flex-1 flex items-center justify-center gap-1.5 px-2 py-1.5 rounded-lg border text-[11px] font-medium ${
                    sel
                      ? "bg-amber-400/15 border-amber-400/50 text-amber-200"
                      : "bg-white/5 border-white/10 text-white/60"
                  }`}
                >
                  <Icon className="w-3 h-3" />
                  {M.label}
                </button>
              );
            })}
          </div>
          {err && <div className="text-[11px] text-red-300">{err}</div>}
          <div className="flex gap-2">
            <button
              onClick={() => setShowForm(false)}
              className="flex-1 h-9 rounded-lg bg-white/5 border border-white/10 text-white/70 text-xs font-medium"
            >
              İptal
            </button>
            <button
              onClick={submit}
              disabled={!title.trim() || busy}
              className="flex-1 h-9 rounded-lg bg-gradient-to-r from-amber-500 to-amber-400 text-[#0A0A0A] text-xs font-bold uppercase tracking-widest disabled:opacity-50"
            >
              {busy ? "…" : "Mührü Bırak"}
            </button>
          </div>
        </div>
      )}

      {/* List */}
      <div className="relative z-10 space-y-2 max-h-[280px] overflow-y-auto pr-1 -mr-1">
        {sorted.length === 0 && (
          <div className="text-center py-6 text-white/40 text-xs">
            Bu bölgede henüz mühür yok. İlk çiviyi sen çak.
          </div>
        )}
        {sorted.map((t) => {
          const Icon = TYPE_META[t.content_type].icon;
          const dist = coords
            ? haversineMeters(coords.lat, coords.lng, t.latitude, t.longitude)
            : null;
          const isNearby = nearbyIds.has(t.id);
          const isUnlocked = unlockedIds.has(t.id);
          const visible = isUnlocked || isNearby;
          return (
            <div
              key={t.id}
              className={`rounded-xl border p-3 transition-all ${
                visible
                  ? "bg-amber-400/5 border-amber-400/30"
                  : "bg-white/5 border-white/10"
              }`}
            >
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-2 min-w-0">
                  <div
                    className={`w-7 h-7 rounded-full flex items-center justify-center ${
                      visible ? "bg-amber-400/20" : "bg-white/5"
                    }`}
                  >
