import { useMemo } from "react";
import { ShieldCheck, Radar, AlertTriangle } from "lucide-react";
import type { PresencePoint } from "@/hooks/useSovereignSpace";
import { haversineMeters } from "@/hooks/useSovereignSpace";

interface Props {
  coords: { lat: number; lng: number } | null;
  presences: PresencePoint[];
  nearbyCount: number;
  borderActive: boolean;
  permission: "prompt" | "granted" | "denied" | "unsupported";
  simulated: boolean;
  onToggleSim: (v: boolean) => void;
}

const RADAR_RADIUS_M = 200;

export function EtherBorderRadar({
  coords,
  presences,
  nearbyCount,
  borderActive,
  permission,
  simulated,
  onToggleSim,
}: Props) {
  const dots = useMemo(() => {
    if (!coords) return [];
    return presences
      .map((p) => {
        const dist = haversineMeters(
          coords.lat,
          coords.lng,
          p.latitude,
          p.longitude,
        );
        if (dist > RADAR_RADIUS_M) return null;
        // bearing
        const dLng = ((p.longitude - coords.lng) * Math.PI) / 180;
        const lat1 = (coords.lat * Math.PI) / 180;
        const lat2 = (p.latitude * Math.PI) / 180;
        const y = Math.sin(dLng) * Math.cos(lat2);
        const x =
          Math.cos(lat1) * Math.sin(lat2) -
          Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLng);
        const bearing = Math.atan2(y, x);
        const r = (dist / RADAR_RADIUS_M) * 47; // % of half-radar
        const cx = 50 + r * Math.sin(bearing);
        const cy = 50 - r * Math.cos(bearing);
        return { id: p.user_id, cx, cy, dist };
      })
      .filter(Boolean) as { id: string; cx: number; cy: number; dist: number }[];
  }, [coords, presences]);

  // Add simulated phantom dots when toggle is on and we have less than 7 real
  const simDots = useMemo(() => {
    if (!simulated) return [];
    const need = Math.max(0, 7 - dots.length);
    const arr: { id: string; cx: number; cy: number }[] = [];
    for (let i = 0; i < need; i++) {
      const angle = (i / 7) * Math.PI * 2 + 0.4;
      const r = 18 + (i % 3) * 10;
      arr.push({
        id: `sim-${i}`,
        cx: 50 + r * Math.cos(angle),
        cy: 50 + r * Math.sin(angle),
      });
    }
    return arr;
  }, [simulated, dots.length]);

  return (
    <div
      className={`relative rounded-3xl overflow-hidden border ${
        borderActive
          ? "border-amber-400/70 shadow-[0_0_60px_rgba(212,175,55,0.45)]"
          : "border-amber-400/15"
      } bg-gradient-to-b from-[#15110A] to-[#0A0A0A] p-5 sovereign-grain transition-all duration-700`}
    >
      {/* Header */}
      <div className="relative z-10 flex items-start justify-between mb-3">
        <div>
          <div className="text-[10px] font-mono tracking-[0.3em] text-amber-300/80 uppercase">
            Ether-Border
          </div>
          <div className="text-base font-semibold text-amber-100 mt-0.5">
            Egemenlik Alanı
          </div>
        </div>
        <div
          className={`px-2.5 py-1 rounded-full text-[10px] font-mono uppercase tracking-widest ${
            borderActive
              ? "bg-amber-400/20 text-amber-200 border border-amber-400/40"
              : "bg-white/5 text-white/50 border border-white/10"
          }`}
        >
          {borderActive ? "● AKTİF" : "○ Beklemede"}
        </div>
      </div>

      {/* Radar */}
      <div className="relative z-10 mx-auto aspect-square max-w-[280px]">
        <svg viewBox="0 0 100 100" className="w-full h-full">
          {/* concentric rings */}
          {[15, 30, 45].map((r) => (
            <circle
              key={r}
              cx="50"
              cy="50"
              r={r}
              fill="none"
              stroke={borderActive ? "rgba(212,175,55,0.35)" : "rgba(212,175,55,0.15)"}
              strokeWidth="0.4"
            />
          ))}
          {/* crosshair */}
          <line x1="50" y1="3" x2="50" y2="97" stroke="rgba(0,255,255,0.12)" strokeWidth="0.3" />
          <line x1="3" y1="50" x2="97" y2="50" stroke="rgba(0,255,255,0.12)" strokeWidth="0.3" />

          {/* sweep beam */}
          <defs>
            <linearGradient id="sweep" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="rgba(212,175,55,0)" />
              <stop offset="100%" stopColor="rgba(212,175,55,0.6)" />
            </linearGradient>
          </defs>
          <g className="origin-center" style={{ transformOrigin: "50px 50px" }}>
            <g className="animate-[radar-spin_4s_linear_infinite]" style={{ transformOrigin: "50px 50px" }}>
              <path
                d="M 50 50 L 50 5 A 45 45 0 0 1 95 50 Z"
                fill="url(#sweep)"
                opacity="0.55"
              />
            </g>
          </g>

          {/* center node */}
          <circle cx="50" cy="50" r="2.4" fill="#D4AF37" />
          <circle
            cx="50"
            cy="50"
            r="4"
            fill="none"
            stroke="rgba(212,175,55,0.6)"
            strokeWidth="0.4"
            className="animate-ping"
          />

          {/* real presences */}
          {dots.map((d) => (
            <g key={d.id}>
              <circle cx={d.cx} cy={d.cy} r="1.8" fill="#00FFFF" opacity="0.95" />
              <circle
                cx={d.cx}
                cy={d.cy}
                r="3"
                fill="none"
                stroke="rgba(0,255,255,0.5)"
                strokeWidth="0.3"
              />
            </g>
          ))}
          {/* simulated dots */}
          {simDots.map((d) => (
            <circle
              key={d.id}
              cx={d.cx}
              cy={d.cy}
              r="1.5"
              fill="#D4AF37"
              opacity="0.7"
            />
          ))}
        </svg>

        {/* Border shield glow overlay */}
        {borderActive && (
          <div className="pointer-events-none absolute inset-0 rounded-full">
            <div className="absolute inset-0 rounded-full border-2 border-amber-400/60 animate-pulse" />
            <div className="absolute -inset-2 rounded-full border border-amber-400/30" />
          </div>
        )}
      </div>

      {/* Stats */}
      <div className="relative z-10 mt-4 grid grid-cols-3 gap-2 text-center">
        <div className="rounded-xl bg-white/5 border border-white/10 px-2 py-2">
          <div className="text-[9px] font-mono uppercase tracking-widest text-white/50">
            Yakındaki
          </div>
          <div className="text-lg font-bold text-amber-200 tabular-nums">{nearbyCount}</div>
        </div>
        <div className="rounded-xl bg-white/5 border border-white/10 px-2 py-2">
          <div className="text-[9px] font-mono uppercase tracking-widest text-white/50">
            Eşik
          </div>
          <div className="text-lg font-bold text-cyan-300 tabular-nums">7</div>
        </div>
        <div className="rounded-xl bg-white/5 border border-white/10 px-2 py-2">
          <div className="text-[9px] font-mono uppercase tracking-widest text-white/50">
            Yarıçap
          </div>
          <div className="text-lg font-bold text-white/85 tabular-nums">200m</div>
        </div>
      </div>

      {/* Permission/help line */}
      <div className="relative z-10 mt-3 flex items-center justify-between gap-2 text-[11px]">
        <div className="flex items-center gap-1.5 text-white/55">
          {permission === "denied" ? (
            <>
              <AlertTriangle className="w-3 h-3 text-amber-400" />
              <span>Konum reddedildi — radar kapalı</span>
            </>
          ) : permission === "unsupported" ? (
            <>
              <AlertTriangle className="w-3 h-3 text-amber-400" />
              <span>Tarayıcı konumu desteklemiyor</span>
            </>
          ) : !coords ? (
            <>
              <Radar className="w-3 h-3 animate-pulse" />
              <span>Konum alınıyor…</span>
            </>
          ) : borderActive ? (
            <>
              <ShieldCheck className="w-3 h-3 text-amber-300" />
              <span className="text-amber-200">Egemenlik kalkanı yükseldi</span>
            </>
          ) : (
            <span>{`${nearbyCount}/7 sovereign — eşik için ${Math.max(0, 7 - nearbyCount)} kişi daha`}</span>
          )}
        </div>
        <button
          onClick={() => onToggleSim(!simulated)}
          className={`px-2 py-1 rounded-md font-mono text-[10px] uppercase tracking-widest border ${
            simulated
              ? "bg-amber-400/15 border-amber-400/40 text-amber-200"
              : "bg-white/5 border-white/10 text-white/60"
          }`}
        >
          {simulated ? "Sim ON" : "Sim OFF"}
        </button>
      </div>
    </div>
  );
}

