/**
 * IpfsVerifiedBadge — small fixed corner pill that shows the last sealed
 * Mainnet CID and "Verified by IPFS" status on every authenticated screen.
 * Re-verifies on mount; auto-hides if no seal exists yet.
 */
import { useEffect, useState } from "react";
import { ShieldCheck, Loader2 } from "lucide-react";
import { getLastSeal, verifySeal, type SealMeta } from "@/services/lighthouse";
import { useAuth } from "@/hooks/useAuth";

export function IpfsVerifiedBadge() {
  const { user } = useAuth();
  const [meta, setMeta] = useState<SealMeta | null>(null);
  const [verifying, setVerifying] = useState(false);
  const [verified, setVerified] = useState<boolean | null>(null);

  useEffect(() => {
    if (!user) return;
    const m = getLastSeal();
    if (!m?.cid) return;
    setMeta(m);
    setVerifying(true);
    verifySeal(m.cid)
      .then((r) => setVerified(r.ok))
      .catch(() => setVerified(false))
      .finally(() => setVerifying(false));
  }, [user]);

  if (!user || !meta?.cid) return null;
  const short = `${meta.cid.slice(0, 6)}…${meta.cid.slice(-4)}`;
  const ok = verified === true;

  return (
    <a
      href={meta.url}
      target="_blank"
      rel="noopener noreferrer"
      title={`Last seal: ${meta.cid}`}
      className="fixed bottom-3 left-3 z-30 flex items-center gap-1.5 rounded-full border border-amber-300/30 bg-black/55 px-2.5 py-1 text-[10px] font-semibold text-amber-200 backdrop-blur-md hover:border-amber-300/60"
      style={{ marginBottom: "calc(env(safe-area-inset-bottom, 0px) + 56px)" }}
    >
      {verifying ? (
        <Loader2 className="h-3 w-3 animate-spin" />
      ) : (
        <ShieldCheck className={`h-3 w-3 ${ok ? "text-emerald-300" : "text-amber-300/60"}`} />
      )}
      <span>{ok ? "Verified by IPFS" : "Mühür"}</span>
      <span className="opacity-60">· {short}</span>
    </a>
  );
}

