import { useTotp } from "@/hooks/useTotp";
import { useSovereignAuth } from "@/hooks/useSovereignAuth";
import { Button } from "@/components/ui/button";
import { Shield, Copy, Power, ShieldCheck } from "lucide-react";
import { toast } from "sonner";
import { StarRingProgress } from "@/components/auth/StarRingProgress";

/**
 * Jiyan Authenticator — Egemen Kod (Sovereign Code) screen.
 *
 * Renders the live RFC 6238 TOTP code inside the 21-ray Stêrka Geş
 * progress ring. Tapping "Onayla & Senkronize Et" verifies the current
 * window and bumps `sovereign_auth_state` so every mini-app (Mail,
 * Wallet, ID Borsa) sees the user as Sovereign-Verified for the next
 * 15 minutes — no secondary prompts needed.
 */
export function JiyanAuthenticator() {
  const { row, loading, code, remaining, enable, disable, validate } = useTotp();
  const { bump, isSovereignVerified, remainingSeconds } = useSovereignAuth();

  if (loading) {
    return <div className="text-center py-10 text-amber-200/60 text-sm">Yükleniyor...</div>;
  }

  // ---------- Not yet enabled -------------------------------------------
  if (!row || !row.is_active) {
    return (
      <div className="text-center space-y-5 py-4">
        <div className="mx-auto w-20 h-20 rounded-full bg-gradient-to-br from-amber-400/20 to-amber-600/20 border border-amber-400/40 flex items-center justify-center">
          <Shield className="w-10 h-10 text-amber-300" />
        </div>
        <div>
          <h2 className="text-xl font-bold text-amber-100">Jiyan Authenticator</h2>
          <p className="text-xs text-amber-200/60 mt-2 max-w-xs mx-auto leading-relaxed">
            Yüksek güvenlikli işlemler için (DiravCash transferleri, hesap değişiklikleri)
            30 saniyede bir değişen 6 haneli <strong className="text-amber-200">Egemen Kod</strong>.
          </p>
        </div>
        <Button
          onClick={enable}
          className="bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold hover:opacity-90"
        >
          Aktifleştir
        </Button>
      </div>
    );
  }

  // ---------- Active — show live 21-ray Sovereign code ------------------
  const progress = remaining / 30;

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      toast.success("Egemen Kod kopyalandı");
    } catch {
      toast.error("Kopyalanamadı");
    }
  };

  const confirmAndSync = async () => {
    if (code.includes("-")) return;
    const ok = await validate(code);
    if (!ok) {
      toast.error("Kod doğrulanamadı, lütfen tekrar dene");
      return;
    }
    await bump("totp", 15, "Jiyan Authenticator");
    toast.success("Egemen Güvenlik aktif — 15 dk", {
      description: "Mail, Cüzdan ve ID Borsa artık ek doğrulama istemeyecek.",
    });
  };

  return (
    <div className="text-center space-y-5 py-2">
      {/* 21-ray Stêrka Geş ring with the live code in the centre */}
      <div className="flex justify-center">
        <button
          type="button"
          onClick={copy}
          aria-label="Egemen Kod'u kopyala"
          className="rounded-full transition-transform active:scale-[0.97] focus:outline-none focus-visible:ring-2 focus-visible:ring-amber-400/50"
        >
          <StarRingProgress
            progress={progress}
            code={code}
            seconds={remaining}
            size={236}
          />
        </button>
      </div>
      <p className="text-[10px] text-amber-200/50">Koda dokunarak kopyala</p>

      {/* Sovereign Window status */}
      <div
        className={`mx-auto inline-flex items-center gap-2 rounded-full px-3 py-1.5 text-[11px] font-semibold tracking-wide transition-colors ${
          isSovereignVerified
            ? "bg-emerald-400/10 text-emerald-200 border border-emerald-400/30"
            : "bg-amber-400/5 text-amber-200/70 border border-amber-400/20"
        }`}
      >
        <ShieldCheck className="h-3.5 w-3.5" />
        {isSovereignVerified
          ? `Egemen Pencere açık · ${Math.floor(remainingSeconds / 60)}:${String(remainingSeconds % 60).padStart(2, "0")}`
          : "Egemen Pencere kapalı"}
      </div>

      {/* Primary CTA — confirm + cross-app sync */}
      <Button
        onClick={confirmAndSync}
        className="w-full max-w-xs mx-auto bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-400 text-black font-semibold shadow-[0_4px_24px_rgba(255,200,60,0.35)] hover:shadow-[0_4px_32px_rgba(255,200,60,0.5)]"
      >
        <ShieldCheck className="w-4 h-4 mr-2" />
        Onayla & Tüm Uygulamalara Senkronize Et
      </Button>

      <div className="flex gap-2 justify-center">
        <Button variant="outline" size="sm" className="border-amber-400/30 text-amber-100" onClick={copy}>
          <Copy className="w-3.5 h-3.5 mr-1.5" />Kopyala
        </Button>
        <Button variant="outline" size="sm" className="border-rose-500/40 text-rose-300 hover:text-rose-200" onClick={disable}>
          <Power className="w-3.5 h-3.5 mr-1.5" />Devre Dışı
        </Button>
      </div>

      <p className="text-[10px] text-amber-200/50 max-w-xs mx-auto leading-relaxed">
        Kod 30 saniyede bir yenilenir. Onayladığında 15 dakika boyunca tüm Jiyan
        mini uygulamaları (Mail, Cüzdan, ID Borsa) seni doğrulanmış kabul eder.
      </p>
    </div>
  );
}

