/**
 * KycProgressWidget — visual KYC progress for the Sovereign Identity Required gate.
 *
 * Steps:
 *   1. Hesap Oluştur     (account exists)
 *   2. Belge Yükle       (KYC submitted: pending|approved|rejected)
 *   3. İnceleme           (status === 'pending')
 *   4. Mühür Onaylandı   (is_verified = true)
 *
 * Includes a Refresh / Retry button that re-fetches the latest KYC state.
 */
import { CheckCircle2, Circle, Loader2, RefreshCw, ShieldAlert, Timer } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";

export type KycStage = "no_account" | "no_submission" | "pending" | "rejected" | "verified";

interface Props {
  stage: KycStage;
  rejectionReason?: string | null;
  submittedAt?: string | null;
  refreshing: boolean;
  onRefresh: () => void;
}

const STEPS: { key: KycStage[]; title: string; subtitle: string }[] = [
  { key: ["no_account"], title: "Hesap Oluştur", subtitle: "Sovereign hesabı açıldı" },
  {
    key: ["no_submission", "pending", "rejected", "verified"],
    title: "Belge Yükle",
    subtitle: "Kimlik belgesi + selfie",
  },
  { key: ["pending", "verified"], title: "İnceleme", subtitle: "~24 saat içinde" },
  { key: ["verified"], title: "Mühür Onaylandı", subtitle: "E-Devlet açık" },
];

function isStepDone(stepIndex: number, stage: KycStage): boolean {
  if (stage === "verified") return true;
  if (stage === "no_account") return stepIndex < 0;
  if (stage === "no_submission") return stepIndex < 1;
  if (stage === "rejected") return stepIndex < 2; // step 2 (Belge) done, step 3 (İnceleme) failed
  if (stage === "pending") return stepIndex < 2; // step 2 done, step 3 active
  return false;
}

function isStepActive(stepIndex: number, stage: KycStage): boolean {
  if (stage === "no_account") return stepIndex === 0;
  if (stage === "no_submission") return stepIndex === 1;
  if (stage === "pending") return stepIndex === 2;
  if (stage === "rejected") return stepIndex === 2;
  return false;
}

export function KycProgressWidget({ stage, rejectionReason, submittedAt, refreshing, onRefresh }: Props) {
  const eta = stage === "pending" ? estimateEta(submittedAt) : null;

  return (
    <div className="rounded-2xl border border-amber-400/20 bg-[linear-gradient(180deg,rgba(245,158,11,0.05),rgba(0,0,0,0.45))] p-4">
      <div className="flex items-center justify-between mb-4">
        <div>
          <p className="text-[10px] uppercase tracking-widest text-amber-200/60">İlerleme</p>
          <p className="text-sm font-bold text-amber-100">Mühür Süreci</p>
        </div>
        <button
          onClick={onRefresh}
          disabled={refreshing}
          aria-label="Doğrulama durumunu yenile"
          className="h-8 w-8 rounded-full border border-amber-400/25 bg-black/40 flex items-center justify-center text-amber-200/80 active:scale-95 transition disabled:opacity-50"
        >
          <RefreshCw className={cn("h-3.5 w-3.5", refreshing && "animate-spin")} />
        </button>
      </div>

      <ol className="space-y-3">
        {STEPS.map((s, i) => {
          const done = isStepDone(i, stage);
          const active = isStepActive(i, stage);
          const failed = stage === "rejected" && i === 2;
          return (
            <li key={i} className="flex items-start gap-3">
              <div
                className={cn(
                  "mt-0.5 h-7 w-7 rounded-full flex items-center justify-center border flex-shrink-0",
                  done && "bg-amber-500/20 border-amber-400/60 text-amber-200",
                  active && !failed && "bg-amber-500/10 border-amber-400/40 text-amber-300 animate-pulse",
                  failed && "bg-red-500/15 border-red-400/40 text-red-300",
                  !done && !active && !failed && "border-white/10 text-white/30",
                )}
              >
                {done ? (
                  <CheckCircle2 className="h-4 w-4" strokeWidth={2.5} />
                ) : active && !failed ? (
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                ) : failed ? (
                  <ShieldAlert className="h-3.5 w-3.5" />
                ) : (
                  <Circle className="h-3.5 w-3.5" />
                )}
              </div>
              <div className="flex-1 min-w-0 pt-0.5">
                <p
                  className={cn(
                    "text-sm font-semibold leading-tight",
                    done ? "text-amber-100" : active ? "text-amber-200" : failed ? "text-red-200" : "text-white/40",
                  )}
                >
                  {s.title}
                </p>
                <p className="text-[11px] text-amber-100/50 leading-snug">{s.subtitle}</p>
                {active && !failed && i === 2 && eta && (
                  <p className="mt-1 inline-flex items-center gap-1 text-[10px] text-amber-300/80 font-mono">
                    <Timer className="h-3 w-3" /> Tahmini: {eta}
                  </p>
                )}
                {failed && rejectionReason && (
                  <p className="mt-1 text-[10px] text-red-300/80 leading-snug">
                    Reddedilme: {rejectionReason}
                  </p>
                )}
              </div>
            </li>
          );
        })}
      </ol>

      {stage === "pending" && (
        <Button
          onClick={onRefresh}
          disabled={refreshing}
          variant="outline"
          className="mt-4 w-full h-9 text-xs border-amber-400/30 bg-amber-500/5 text-amber-200 hover:bg-amber-500/10"
        >
          {refreshing ? (
            <>
              <Loader2 className="h-3.5 w-3.5 mr-2 animate-spin" />
              Kontrol ediliyor…
            </>
          ) : (
            <>
              <RefreshCw className="h-3.5 w-3.5 mr-2" />
              Doğrulamayı Yenile
            </>
          )}
        </Button>
      )}
    </div>
  );
}

function estimateEta(submittedAt: string | null | undefined): string | null {
  if (!submittedAt) return "~24 saat";
  const submitted = new Date(submittedAt).getTime();
  const target = submitted + 24 * 60 * 60 * 1000;
  const diff = target - Date.now();
  if (diff <= 0) return "çok yakında";
  const hours = Math.floor(diff / (60 * 60 * 1000));
  const mins = Math.floor((diff % (60 * 60 * 1000)) / (60 * 1000));
  if (hours > 0) return `${hours} sa ${mins} dk`;
  return `${mins} dk`;
}

