/**
 * MuhrSeal — golden State Seal animation primitives for E-Devlet.
 *
 * Exports:
 *   • <MuhrButton/>     — gold button that plays an "imprint" stamp animation on press
 *   • <MuhrTransition/> — full-screen golden seal stamp overlay (used when entering documents)
 *   • <MuhrScroll/>     — animated scroll open/close container for document panels
 */
import { useEffect, useState, type ButtonHTMLAttributes, type ReactNode } from "react";
import { Landmark, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

// ───────────────────────────────────────────────────────────────────────────────
// MuhrButton — gold seal button with stamp ripple
// ───────────────────────────────────────────────────────────────────────────────
interface MuhrButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  loading?: boolean;
  variant?: "primary" | "ghost";
  icon?: ReactNode;
}

export function MuhrButton({
  children,
  loading,
  variant = "primary",
  icon,
  className,
  onClick,
  disabled,
  ...rest
}: MuhrButtonProps) {
  const [stamping, setStamping] = useState(false);

  const handleClick: React.MouseEventHandler<HTMLButtonElement> = (e) => {
    if (disabled || loading) return;
    setStamping(true);
    window.setTimeout(() => setStamping(false), 600);
    onClick?.(e);
  };

  return (
    <button
      onClick={handleClick}
      disabled={disabled || loading}
      className={cn(
        "relative overflow-hidden rounded-xl h-12 px-5 font-bold text-sm",
        "transition-all active:scale-[0.97] disabled:opacity-50 disabled:cursor-not-allowed",
        variant === "primary"
          ? "bg-gradient-to-r from-amber-500 to-yellow-300 text-black shadow-[0_8px_24px_-8px_rgba(245,158,11,0.55)] hover:from-amber-400 hover:to-yellow-200"
          : "border border-amber-400/30 bg-amber-500/5 text-amber-100 hover:bg-amber-500/10",
        className,
      )}
      {...rest}
    >
      {/* Ripple/stamp ring */}
      {stamping && (
        <span
          aria-hidden
          className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 h-2 w-2 rounded-full bg-white/70 animate-muhr-stamp"
        />
      )}
      {/* Inner sheen */}
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"
      />
      <span className="relative flex items-center justify-center gap-2">
        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : icon}
        {children}
      </span>
    </button>
  );
}

// ───────────────────────────────────────────────────────────────────────────────
// MuhrTransition — full-screen golden seal stamp before navigation
// ───────────────────────────────────────────────────────────────────────────────
export function MuhrTransition({
  active,
  label = "Mühür uygulanıyor",
  onComplete,
  duration = 900,
}: {
  active: boolean;
  label?: string;
  onComplete?: () => void;
  duration?: number;
}) {
  useEffect(() => {
    if (!active) return;
    const t = window.setTimeout(() => onComplete?.(), duration);
    return () => window.clearTimeout(t);
  }, [active, duration, onComplete]);

  if (!active) return null;
  return (
    <div
      role="status"
      aria-live="polite"
      className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-[#070604]/95 backdrop-blur-sm animate-fade-in"
    >
      <div className="relative h-32 w-32 mb-5">
        <div className="absolute inset-0 rounded-full bg-amber-400/30 blur-2xl animate-pulse" />
        <div
          className="relative h-full w-full rounded-full border-2 border-amber-300/60 bg-gradient-to-br from-amber-500/40 to-yellow-300/10 flex items-center justify-center animate-muhr-impact"
        >
          <Landmark className="h-12 w-12 text-amber-100" strokeWidth={1.5} />
        </div>
        <div
          aria-hidden
          className="absolute inset-0 rounded-full border-2 border-amber-300/70 animate-muhr-ring"
        />
      </div>
      <p className="text-[10px] uppercase tracking-[0.4em] text-amber-300/80 font-semibold">
        {label}
      </p>
    </div>
  );
}

// ───────────────────────────────────────────────────────────────────────────────
// MuhrScroll — animated scroll open/close panel
// ───────────────────────────────────────────────────────────────────────────────
export function MuhrScroll({
  open,
  children,
  className,
}: {
  open: boolean;
  children: ReactNode;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "overflow-hidden transition-all duration-500 ease-out",
        open ? "max-h-[2000px] opacity-100" : "max-h-0 opacity-0",
        className,
      )}
    >
      <div className={cn("transform-gpu transition-transform duration-500", open ? "scale-y-100" : "scale-y-95")}>
        {children}
      </div>
    </div>
  );
}

