          "relative mt-4 flex items-center justify-center gap-2 h-11 rounded-xl font-bold text-[12px] uppercase tracking-wider active:scale-[0.98] transition shadow-[0_6px_18px_-6px_rgba(245,158,11,0.55)]",
          access.stage === "rejected"
