import { useEffect, useRef, useState } from "react";
import { Dialog, DialogContent } from "@/components/ui/dialog";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  /** Called once the celebration is complete and the +777 card has glowed */
  onComplete?: () => void;
  /** How long the celebration plays before auto-closing (ms) */
  duration?: number;
}

function vibrate(p: number | number[]) {
  if (typeof navigator !== "undefined" && "vibrate" in navigator) {
    try {
      (navigator as Navigator & { vibrate?: (p: number | number[]) => boolean }).vibrate?.(p);
    } catch {
      /* ignore */
    }
  }
}

/**
 * Plays a brief celebratory "desert party" cue using the WebAudio API
 * (no asset files required). Falls back silently if AudioContext is unavailable.
 */
function playDarbukaRiff() {
  if (typeof window === "undefined") return;
  try {
    const Ctx =
      (window as unknown as { AudioContext?: typeof AudioContext }).AudioContext ??
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    const now = ctx.currentTime;

    // Camel bell — bright sine ping
    const bell = ctx.createOscillator();
    const bellGain = ctx.createGain();
    bell.type = "sine";
    bell.frequency.setValueAtTime(1320, now);
    bell.frequency.exponentialRampToValueAtTime(880, now + 0.35);
    bellGain.gain.setValueAtTime(0.0001, now);
    bellGain.gain.exponentialRampToValueAtTime(0.18, now + 0.02);
    bellGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.5);
    bell.connect(bellGain).connect(ctx.destination);
    bell.start(now);
    bell.stop(now + 0.55);

    // Darbuka-style low beats (4 thumps)
    const beats = [0.05, 0.22, 0.42, 0.65];
    beats.forEach((t, i) => {
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.type = "triangle";
      osc.frequency.setValueAtTime(i % 2 === 0 ? 110 : 75, now + t);
      osc.frequency.exponentialRampToValueAtTime(50, now + t + 0.18);
      g.gain.setValueAtTime(0.0001, now + t);
      g.gain.exponentialRampToValueAtTime(0.32, now + t + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, now + t + 0.22);
      osc.connect(g).connect(ctx.destination);
      osc.start(now + t);
      osc.stop(now + t + 0.25);
    });

    setTimeout(() => ctx.close().catch(() => undefined), 1500);
  } catch {
    /* ignore — silent if WebAudio is blocked */
  }
}

interface Coin {
  id: number;
  delay: number;
  x: number;
  rotate: number;
}

export function ReCaravanCelebration({
  open,
  onOpenChange,
  onComplete,
  duration = 3400,
}: Props) {
  const [phase, setPhase] = useState<"intro" | "wink" | "coins" | "outro">("intro");
  const [coins] = useState<Coin[]>(() =>
    Array.from({ length: 8 }, (_, i) => ({
      id: i,
      delay: 200 + i * 120,
      x: -120 + Math.random() * 40,
      rotate: -25 + Math.random() * 50,
    })),
  );
  const completedRef = useRef(false);

  useEffect(() => {
    if (!open) {
      setPhase("intro");
      completedRef.current = false;
      return;
    }

    completedRef.current = false;
    playDarbukaRiff();
    vibrate([15, 40, 25, 60]);

    const t1 = setTimeout(() => {
      setPhase("wink");
      vibrate([30, 30, 30]); // bounce on wink
    }, 350);
    const t2 = setTimeout(() => setPhase("coins"), 700);
    const t3 = setTimeout(() => setPhase("outro"), duration - 800);
    const t4 = setTimeout(() => {
      if (!completedRef.current) {
        completedRef.current = true;
        onComplete?.();
        onOpenChange(false);
      }
    }, duration);

    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
      clearTimeout(t3);
      clearTimeout(t4);
    };
  }, [open, duration, onComplete, onOpenChange]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="re-celebration-dialog max-w-sm bg-gradient-to-b from-[#1A0F08] via-[#08070A] to-black border-amber-400/40 overflow-hidden p-0"
      >
        {/* Soft desert glow */}
        <div className="re-celebration-bg" aria-hidden />

        <div className="relative px-6 pt-7 pb-6 flex flex-col items-center text-center">
          {/* "Rê" logo */}
          <div className="re-logo mb-3" aria-hidden>
            <svg viewBox="0 0 64 64" className="w-12 h-12">
              <defs>
                <linearGradient id="re-grad" x1="0" y1="0" x2="1" y2="1">
                  <stop offset="0%" stopColor="#F7DA86" />
                  <stop offset="100%" stopColor="#B8860B" />
                </linearGradient>
              </defs>
              {/* Protective arc */}
              <path
                d="M8 38 Q32 6 56 38"
                fill="none"
                stroke="url(#re-grad)"
                strokeWidth="2.4"
                strokeLinecap="round"
                opacity="0.85"
              />
              {/* Winding road */}
              <path
                d="M14 54 Q24 44 32 50 T 50 44"
                fill="none"
                stroke="url(#re-grad)"
                strokeWidth="3"
                strokeLinecap="round"
                strokeDasharray="0 0"
              />
              {/* Star spark */}
              <circle cx="32" cy="14" r="1.6" fill="#FFE9A6" />
            </svg>
          </div>

          <div className="text-[9px] font-mono uppercase tracking-[0.35em] text-amber-300/70">
            Rê · Pathfinder
          </div>

          {/* Camel scene */}
          <div className="relative mt-4 h-32 w-full flex items-end justify-center">
            {/* Coin trail */}
