/**
 * SealToMainnet — Admin "Mühürle" CTA + boot-time verification + history.
 */
import { useEffect, useMemo, useState } from "react";
import { ShieldCheck, Loader2, Copy, ExternalLink, History, CheckCircle2, AlertCircle, X, Scroll } from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import {
  getLastSeal,
  getSealHistory,
  sealToMainnet,
  sealFullArchive,
  verifySeal,
  type SealMeta,
  type SealVerification,
} from "@/services/lighthouse";
import { Brain } from "lucide-react";

interface AuditRow {
  id: string;
  admin_id: string;
  cid: string;
  gateway_url: string | null;
  version: string | null;
  origin: string | null;
  created_at: string;
}

export function SealToMainnet() {
  const { user } = useAuth();
  const [busy, setBusy] = useState(false);
  const [archiveBusy, setArchiveBusy] = useState(false);
  const [archiveProgress, setArchiveProgress] = useState<{ loaded: number; total: number } | null>(null);
  const [last, setLast] = useState<SealMeta | null>(null);
  const [history, setHistory] = useState<SealMeta[]>([]);
  const [verifying, setVerifying] = useState(false);
  const [verification, setVerification] = useState<SealVerification | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [showAudit, setShowAudit] = useState(false);
  const [audit, setAudit] = useState<AuditRow[]>([]);
  const [detail, setDetail] = useState<SealMeta | null>(null);

  const refresh = () => {
    setLast(getLastSeal());
    setHistory(getSealHistory());
  };

  const loadAudit = async () => {
    const { data, error } = await supabase
      .from("mainnet_seal_audit")
      .select("id, admin_id, cid, gateway_url, version, origin, created_at")
      .order("created_at", { ascending: false })
      .limit(100);
    if (!error && data) setAudit(data as AuditRow[]);
  };

  // On mount: verify last seal + load audit
  useEffect(() => {
    refresh();
    void loadAudit();
    const seal = getLastSeal();
    if (!seal?.cid) return;
    setVerifying(true);
    verifySeal(seal.cid)
      .then((v) => setVerification(v))
      .finally(() => setVerifying(false));
  }, []);

  const handleSeal = async () => {
    setBusy(true);
    try {
      const res = await sealToMainnet();
      refresh();
      setVerification({ cid: res.cid, ok: true, gateway: res.url });
      // Audit log (best-effort — never blocks toast)
      if (user) {
        const { error: auditErr } = await supabase.from("mainnet_seal_audit").insert({
          admin_id: user.id,
          cid: res.cid,
          gateway_url: res.url,
          version: (typeof window !== "undefined" && (window as any).__JIYAN_VERSION__) || "1.0.0",
          origin: typeof window !== "undefined" ? window.location.origin : null,
          user_agent: typeof navigator !== "undefined" ? navigator.userAgent : null,
        });
        if (auditErr) console.warn("[seal] audit insert failed", auditErr);
        else void loadAudit();
      }
      toast.success(`Mühürlendi: ${res.cid.slice(0, 12)}…`);
    } catch (e: any) {
      console.error("[seal] failed", e);
      toast.error(e?.message || "Mühürleme başarısız");
    } finally {
      setBusy(false);
    }
  };


  const handleArchive = async () => {
    setArchiveBusy(true);
    setArchiveProgress({ loaded: 0, total: 0 });
    try {
      const res = await sealFullArchive((loaded, total) =>
        setArchiveProgress({ loaded, total }),
      );
      refresh();
      setVerification({ cid: res.cid, ok: true, gateway: res.url });
      if (user) {
        const { error: auditErr } = await supabase.from("mainnet_seal_audit").insert({
          admin_id: user.id,
          cid: res.cid,
          gateway_url: res.url,
          version: `archive-${res.fileCount}f-${(res.bytes / 1024 / 1024).toFixed(2)}MB`,
          origin: typeof window !== "undefined" ? window.location.origin : null,
          user_agent: typeof navigator !== "undefined" ? navigator.userAgent : null,
        });
        if (auditErr) console.warn("[archive] audit insert failed", auditErr);
        else void loadAudit();
      }
      toast.success(`Sovereign Archive mühürlendi: ${res.fileCount} dosya · ${res.cid.slice(0, 12)}…`);
    } catch (e: any) {
      console.error("[archive] failed", e);
      toast.error(e?.message || "Arşivleme başarısız");
    } finally {
      setArchiveBusy(false);
      setArchiveProgress(null);
    }
  };

  const copy = async (txt: string) => {
    try {
      await navigator.clipboard.writeText(txt);
      toast.success("CID kopyalandı");
    } catch {
      toast.error("Kopyalanamadı");
    }
  };

  const verifyBadge = useMemo(() => {
    if (verifying) return { icon: Loader2, label: "Doğrulanıyor…", cls: "text-amber-300", spin: true };
    if (!last) return null;
    if (verification?.ok) return { icon: CheckCircle2, label: "Doğrulandı (IPFS)", cls: "text-emerald-400", spin: false };
    if (verification && !verification.ok) return { icon: AlertCircle, label: "Doğrulanamadı", cls: "text-rose-400", spin: false };
    return null;
  }, [verifying, verification, last]);

  return (
    <div className="rounded-2xl border border-amber-400/30 bg-black/40 p-4 backdrop-blur-sm">
      <div className="flex items-center justify-between gap-2 mb-3">
        <div className="flex items-center gap-2">
          <ShieldCheck className="h-5 w-5 text-amber-400" />
          <h3 className="text-sm font-bold uppercase tracking-wider">Mainnet Mühürü (IPFS / Filecoin)</h3>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setShowAudit(true)}
            className="flex items-center gap-1 text-[10px] uppercase tracking-widest text-muted-foreground hover:text-foreground"
          >
            <Scroll className="h-3.5 w-3.5" /> Audit ({audit.length})
          </button>
          <button
            onClick={() => setShowHistory(true)}
            className="flex items-center gap-1 text-[10px] uppercase tracking-widest text-muted-foreground hover:text-foreground"
          >
            <History className="h-3.5 w-3.5" /> Geçmiş ({history.length})
          </button>
        </div>
      </div>

      <p className="text-xs text-muted-foreground mb-3">
        Mevcut sürümü Lighthouse üzerinden merkeziyetsiz ağa mühürle.
        Geri alınamaz, değiştirilemez bir CID üretilir.
      </p>

      <button
        onClick={handleSeal}
        disabled={busy}
        className="w-full h-12 flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-400 text-black font-black uppercase tracking-[0.15em] text-xs disabled:opacity-60 active:scale-[0.98] transition"
      >
        {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <ShieldCheck className="h-4 w-4" />}
        {busy ? "Mühürleniyor…" : "Seal to Mainnet"}
      </button>

      <button
        onClick={handleArchive}
        disabled={archiveBusy || busy}
        className="mt-2 w-full h-12 flex items-center justify-center gap-2 rounded-xl border border-amber-400/40 bg-black/60 text-amber-200 font-black uppercase tracking-[0.15em] text-xs disabled:opacity-60 active:scale-[0.98] transition"
      >
        {archiveBusy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Brain className="h-4 w-4" />}
        {archiveBusy
          ? archiveProgress
            ? `Arşivleniyor ${archiveProgress.loaded}/${archiveProgress.total}…`
            : "Hazırlanıyor…"
          : "Sovereign Archive (Tüm Beyni Mühürle)"}
      </button>
      <p className="text-[10px] text-muted-foreground mt-2 leading-relaxed">
        Tüm Jiyan OS kaynak kodu (Deng AI · Jiyan TV · Hazine · AppShell · edge functions) tek bir
        manifest JSON olarak IPFS/Filecoin'e kazınır.
      </p>

      {last && (
        <div className="mt-4 rounded-xl border border-white/10 bg-white/[0.02] p-3 space-y-2">
          <div className="flex items-center justify-between">
            <div className="text-[10px] uppercase tracking-widest text-muted-foreground">Son Mühür CID</div>
            {verifyBadge && (
              <div className={`flex items-center gap-1 text-[10px] ${verifyBadge.cls}`}>
                <verifyBadge.icon className={`h-3 w-3 ${verifyBadge.spin ? "animate-spin" : ""}`} />
                {verifyBadge.label}
              </div>
            )}
          </div>
          <div className="flex items-center gap-2">
            <code className="flex-1 text-[11px] font-mono text-amber-300 break-all">{last.cid}</code>
            <button onClick={() => copy(last.cid)} className="h-7 w-7 grid place-items-center rounded-md hover:bg-white/10" aria-label="Copy CID">
              <Copy className="h-3.5 w-3.5" />
            </button>
            <a href={last.url} target="_blank" rel="noreferrer" className="h-7 w-7 grid place-items-center rounded-md hover:bg-white/10" aria-label="Open gateway">
              <ExternalLink className="h-3.5 w-3.5" />
            </a>
          </div>
          {last.sealedAt && (
            <div className="text-[10px] text-muted-foreground">
              {new Date(last.sealedAt).toLocaleString()} · v{last.version || "?"}
            </div>
          )}
        </div>
      )}

      {/* HISTORY MODAL */}
      {showHistory && (
        <div className="fixed inset-0 z-[120] bg-black/80 backdrop-blur-sm grid place-items-center p-4" onClick={() => setShowHistory(false)}>
          <div className="w-full max-w-md max-h-[80vh] overflow-y-auto rounded-2xl border border-amber-400/30 bg-black p-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-3">
              <h4 className="text-sm font-bold uppercase tracking-wider">Mühür Geçmişi</h4>
              <button onClick={() => setShowHistory(false)} className="h-8 w-8 grid place-items-center rounded-md hover:bg-white/10"><X className="h-4 w-4" /></button>
            </div>
            {history.length === 0 ? (
              <p className="text-xs text-muted-foreground py-6 text-center">Henüz mühür yok.</p>
            ) : (
              <ul className="space-y-2">
                {history.map((h) => (
                  <li key={h.cid}>
                    <button
                      onClick={() => setDetail(h)}
                      className="w-full text-left rounded-lg border border-white/10 bg-white/[0.03] p-3 hover:bg-white/[0.06]"
                    >
                      <div className="text-[11px] font-mono text-amber-300 truncate">{h.cid}</div>
                      <div className="text-[10px] text-muted-foreground mt-0.5">
                        {h.sealedAt ? new Date(h.sealedAt).toLocaleString() : "?"} · v{h.version || "?"}
                      </div>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}

      {/* DETAIL MODAL */}
      {detail && (
        <div className="fixed inset-0 z-[130] bg-black/85 backdrop-blur-sm grid place-items-center p-4" onClick={() => setDetail(null)}>
          <div className="w-full max-w-md rounded-2xl border border-amber-400/40 bg-black p-4 space-y-3" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between">
              <h4 className="text-sm font-bold uppercase tracking-wider">Mühür Detayı</h4>
              <button onClick={() => setDetail(null)} className="h-8 w-8 grid place-items-center rounded-md hover:bg-white/10"><X className="h-4 w-4" /></button>
            </div>
            <Field label="CID" value={detail.cid} mono onCopy={() => copy(detail.cid)} />
            <Field label="Sealed At" value={detail.sealedAt ? new Date(detail.sealedAt).toLocaleString() : "?"} />
            <Field label="Version" value={detail.version || "?"} />
            {detail.origin && <Field label="Origin" value={detail.origin} />}
            <a
              href={detail.url}
              target="_blank"
              rel="noreferrer"
              className="flex items-center justify-center gap-2 w-full h-10 rounded-xl bg-amber-400 text-black text-xs font-bold uppercase tracking-widest"
            >
              <ExternalLink className="h-3.5 w-3.5" /> Gateway'de Aç
            </a>
          </div>
        </div>
      )}

      {/* AUDIT MODAL — server-side log of admin seals */}
      {showAudit && (
        <div className="fixed inset-0 z-[125] bg-black/80 backdrop-blur-sm grid place-items-center p-4" onClick={() => setShowAudit(false)}>
          <div className="w-full max-w-md max-h-[80vh] overflow-y-auto rounded-2xl border border-amber-400/30 bg-black p-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-3">
              <h4 className="text-sm font-bold uppercase tracking-wider">Admin Audit Log</h4>
              <button onClick={() => setShowAudit(false)} className="h-8 w-8 grid place-items-center rounded-md hover:bg-white/10"><X className="h-4 w-4" /></button>
            </div>
            <p className="text-[10px] text-muted-foreground mb-3">
              Sunucu tarafında kayıtlı tüm "Seal to Mainnet" işlemleri (admin · zaman · CID).
            </p>
            {audit.length === 0 ? (
              <p className="text-xs text-muted-foreground py-6 text-center">Henüz kayıt yok.</p>
            ) : (
              <ul className="space-y-2">
                {audit.map((a) => (
                  <li key={a.id} className="rounded-lg border border-white/10 bg-white/[0.03] p-3">
                    <div className="flex items-center justify-between gap-2">
                      <code className="text-[10px] font-mono text-amber-300 truncate flex-1">{a.cid}</code>
                      <button onClick={() => copy(a.cid)} className="h-6 w-6 grid place-items-center rounded hover:bg-white/10" aria-label="Copy">
                        <Copy className="h-3 w-3" />
                      </button>
                      {a.gateway_url && (
                        <a href={a.gateway_url} target="_blank" rel="noreferrer" className="h-6 w-6 grid place-items-center rounded hover:bg-white/10">
                          <ExternalLink className="h-3 w-3" />
                        </a>
                      )}
                    </div>
                    <div className="text-[10px] text-muted-foreground mt-1 flex items-center justify-between">
                      <span>{new Date(a.created_at).toLocaleString()}</span>
                      <span>v{a.version || "?"}</span>
                    </div>
                    <div className="text-[9px] text-muted-foreground/70 mt-0.5 font-mono truncate">
                      admin: {a.admin_id.slice(0, 8)}…
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

function Field({ label, value, mono, onCopy }: { label: string; value: string; mono?: boolean; onCopy?: () => void }) {
  return (
    <div className="rounded-lg border border-white/10 bg-white/[0.03] p-2">
      <div className="flex items-center justify-between">
        <div className="text-[9px] uppercase tracking-widest text-muted-foreground">{label}</div>
        {onCopy && (
          <button onClick={onCopy} className="h-6 w-6 grid place-items-center rounded hover:bg-white/10" aria-label="Copy">
            <Copy className="h-3 w-3" />
          </button>
        )}
      </div>
      <div className={`text-[11px] mt-1 break-all ${mono ? "font-mono text-amber-300" : "text-foreground"}`}>{value}</div>
    </div>
  );
}

