import { useEffect, useRef, useState } from "react";
import { useNavigate } from "@tanstack/react-router";
import { KeyRound, Lock, Unlock } from "lucide-react";
import { toast } from "sonner";

const HOLD_MS = 900;
const UNLOCK_WINDOW_MS = 30_000;

function vibrate(pattern: number | number[]) {
  if (typeof navigator !== "undefined" && "vibrate" in navigator) {
    try {
      (navigator as Navigator & { vibrate?: (p: number | number[]) => boolean }).vibrate?.(
        pattern,
      );
    } catch {
      /* ignore */
    }
  }
}

/**
 * Sealed Edit — long-press the seal (≥0.9s) to unlock the edit window for 30s.
 * On unlock, navigates to /profile/edit. While locked, single tap shows a hint.
 */
export function SealedEditButton({ to = "/profile/edit" as const }: { to?: "/profile/edit" }) {
  const navigate = useNavigate();
  const [progress, setProgress] = useState(0); // 0..1 hold progress
  const [unlockedUntil, setUnlockedUntil] = useState<number | null>(null);
  const [now, setNow] = useState(Date.now());
  const holdRef = useRef<number | null>(null);
  const startRef = useRef<number>(0);

  // Tick when unlocked to show countdown
  useEffect(() => {
    if (!unlockedUntil) return;
    const id = window.setInterval(() => setNow(Date.now()), 250);
    return () => window.clearInterval(id);
  }, [unlockedUntil]);

  const remaining = unlockedUntil ? Math.max(0, unlockedUntil - now) : 0;
  const isUnlocked = remaining > 0;

  useEffect(() => {
    if (unlockedUntil && remaining === 0) {
      setUnlockedUntil(null);
      toast("🔒 Mühür yeniden kapandı", { duration: 1800 });
    }
  }, [remaining, unlockedUntil]);

  const cancelHold = () => {
    if (holdRef.current !== null) {
      window.cancelAnimationFrame(holdRef.current);
      holdRef.current = null;
    }
    setProgress(0);
  };

  const startHold = () => {
    if (isUnlocked) {
      // Already unlocked: tap = go straight in
      navigate({ to });
      return;
    }
    startRef.current = performance.now();
    vibrate(8);
    const tick = () => {
      const elapsed = performance.now() - startRef.current;
      const p = Math.min(1, elapsed / HOLD_MS);
      setProgress(p);
      if (p >= 1) {
        // Sealed unlocked
        const until = Date.now() + UNLOCK_WINDOW_MS;
        setUnlockedUntil(until);
        setProgress(0);
        holdRef.current = null;
        vibrate([20, 40, 80]);
        toast.success("🔓 Mühür açıldı · 30s düzenleme penceresi", { duration: 2400 });
        // small delay so the user sees the unlock state
        window.setTimeout(() => navigate({ to }), 320);
        return;
      }
      holdRef.current = window.requestAnimationFrame(tick);
    };
    holdRef.current = window.requestAnimationFrame(tick);
  };

  const onTap = () => {
    if (!isUnlocked && progress === 0) {
      toast("Düzenlemek için mührü 1sn basılı tut", {
        icon: "🔏",
        duration: 1600,
      });
    }
  };

  return (
    <button
      type="button"
      aria-label={isUnlocked ? "Open profile editor" : "Long-press to unseal editing"}
      onPointerDown={(e) => {
        e.preventDefault();
        startHold();
      }}
      onPointerUp={() => {
        if (progress > 0 && progress < 1) {
          cancelHold();
          onTap();
        }
      }}
      onPointerLeave={cancelHold}
      onPointerCancel={cancelHold}
      className="relative h-10 w-10 rounded-full border border-amber-400/30 bg-black/40 backdrop-blur-md flex items-center justify-center hover:border-amber-400/60 transition active:scale-95"
    >
      {/* Progress ring */}
      <svg
        className="absolute inset-0 -rotate-90 pointer-events-none"
        viewBox="0 0 40 40"
        aria-hidden
      >
        <circle
          cx="20"
          cy="20"
          r="18"
          fill="none"
          stroke="currentColor"
          className={isUnlocked ? "text-amber-300/70" : "text-amber-400/60"}
          strokeWidth="2"
          strokeDasharray={`${(isUnlocked ? remaining / UNLOCK_WINDOW_MS : progress) * 113.1} 113.1`}
          strokeLinecap="round"
        />
      </svg>
      {isUnlocked ? (
        <Unlock className="h-4 w-4 text-amber-200" />
      ) : progress > 0 ? (
        <Lock className="h-4 w-4 text-amber-300 animate-pulse" />
      ) : (
        <KeyRound className="h-4 w-4 text-amber-300/85" />
      )}
    </button>
  );
}

