import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { hashSeedPhrase } from "@/lib/sovereignCrypto";
import { Key, AlertTriangle, Check, Lock, Eye, EyeOff, Mail } from "lucide-react";
import { toast } from "sonner";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
}

type Step = "intro" | "input" | "newPassword" | "done" | "emailSent";

/**
 * SeedRecoveryDialog — "Yaşam Anahtarı ile Giriş Yap".
 *
 * Flow:
 *   1. intro       — explainer.
 *   2. input       — Kurd-ID + 24 words. Hashed client-side; plaintext never leaves.
 *   3. newPassword — direct in-dialog password reset (no email round-trip).
 *   4. done        — success, user can sign in immediately.
 *
 * Fallback: if the in-dialog reset fails (e.g. user prefers email), they can
 * trigger the legacy "send reset link" path which lands on `emailSent`.
 */
export function SeedRecoveryDialog({ open, onOpenChange }: Props) {
  const [step, setStep] = useState<Step>("intro");
  const [kurdId, setKurdId] = useState("");
  const [phrase, setPhrase] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Verified context carried into the password step
  const [verifiedKurdId, setVerifiedKurdId] = useState<string | null>(null);
  const [verifiedSeedHash, setVerifiedSeedHash] = useState<string | null>(null);
  const [verifiedEmail, setVerifiedEmail] = useState<string | null>(null);

  // New password fields
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPwd, setShowPwd] = useState(false);
  const [matchedEmail, setMatchedEmail] = useState<string | null>(null);

  const reset = () => {
    setStep("intro");
    setKurdId("");
    setPhrase("");
    setError(null);
    setVerifiedKurdId(null);
    setVerifiedSeedHash(null);
    setVerifiedEmail(null);
    setNewPassword("");
    setConfirmPassword("");
    setShowPwd(false);
    setMatchedEmail(null);
  };

  const close = () => {
    onOpenChange(false);
    setTimeout(reset, 250);
  };

  const formatKurdId = (raw: string) => {
    const digits = raw.replace(/\D/g, "").slice(0, 8);
    return digits.length > 4 ? `${digits.slice(0, 4)} ${digits.slice(4)}` : digits;
  };

  const verify = async () => {
    setError(null);
    const digits = kurdId.replace(/\s/g, "");
    if (digits.length !== 8) {
      setError("Kurd-ID 8 haneli olmalı (+777 XXXX XXXX).");
      return;
    }
    const words = phrase.trim().toLowerCase().split(/\s+/);
    if (words.length !== 24) {
      setError(`24 kelime gerekli — şu an ${words.length} kelime girdin.`);
      return;
    }

    setLoading(true);
    try {
      const formatted = `+777 ${digits.slice(0, 4)} ${digits.slice(4)}`;
      const { data: lookupData, error: lookupErr } = await supabase.rpc(
        "kurdid_public_lookup",
        { _kurd_id: formatted },
      );
      if (lookupErr) throw lookupErr;
      const row = Array.isArray(lookupData) && lookupData.length > 0 ? lookupData[0] : null;
      if (!row || !row.username) {
        setError("Bu Kurd-ID'ye bağlı bir hesap bulunamadı.");
        return;
      }

      const seedHash = await hashSeedPhrase(words);
      const { data: ok, error: verifyErr } = await supabase.rpc(
        "verify_recovery_phrase_for_kurd_id" as never,
        { _kurd_id: formatted, _seed_hash: seedHash } as never,
      );
      let verified = !!ok;
      if (verifyErr) {
        const legacy = await supabase.rpc("verify_recovery_phrase", { _seed_hash: seedHash });
        verified = !!legacy.data;
      }
      if (!verified) {
        setError("Yaşam Anahtarı eşleşmedi. Kelimeleri ve sıralamayı kontrol et.");
        return;
      }

      // Verified — carry context into the in-dialog password reset step
      setVerifiedKurdId(formatted);
      setVerifiedSeedHash(seedHash);
      setVerifiedEmail(`${row.username}@jiyan.world`);
      setStep("newPassword");
      toast.success("Yaşam Anahtarı doğrulandı");
    } catch (e: any) {
      setError(e.message || "Doğrulama başarısız oldu, lütfen tekrar dene.");
    } finally {
      setLoading(false);
    }
  };

  const submitNewPassword = async () => {
    setError(null);
    if (!verifiedKurdId || !verifiedSeedHash) {
      setError("Doğrulama bilgisi kayboldu, lütfen tekrar başla.");
      return;
    }
    if (newPassword.length < 8) {
      setError("Şifre en az 8 karakter olmalı.");
      return;
    }
    if (newPassword !== confirmPassword) {
      setError("Şifreler eşleşmiyor.");
      return;
    }

    setLoading(true);
    try {
      const { data, error: rpcErr } = await supabase.rpc(
        "reset_password_via_seed" as never,
        {
          _kurd_id: verifiedKurdId,
          _seed_hash: verifiedSeedHash,
          _new_password: newPassword,
        } as never,
      );
      if (rpcErr) throw rpcErr;
      if (!data) {
        setError("Şifre güncellenemedi. Yaşam Anahtarı doğrulamasını tekrar yapmayı dene.");
        return;
      }
      setStep("done");
      toast.success("Şifren güncellendi — şimdi giriş yapabilirsin");
    } catch (e: any) {
      setError(e.message || "Şifre güncellenemedi.");
    } finally {
      setLoading(false);
    }
  };

  const sendResetEmailFallback = async () => {
    if (!verifiedEmail) return;
    setLoading(true);
    try {
      const { error: resetErr } = await supabase.auth.resetPasswordForEmail(verifiedEmail, {
        redirectTo: `${window.location.origin}/reset-password`,
      });
      if (resetErr) throw resetErr;
      setMatchedEmail(verifiedEmail);
      setStep("emailSent");
      toast.success("Kurtarma bağlantısı gönderildi");
    } catch (e: any) {
      setError(e.message || "E-posta gönderilemedi.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => (v ? onOpenChange(true) : close())}>
      <DialogContent className="bg-[#0A0A0A] border-amber-400/30 text-amber-100 max-w-md">
        <DialogHeader>
          <DialogTitle className="sr-only">Yaşam Anahtarı ile Giriş</DialogTitle>
        </DialogHeader>

        {step === "intro" && (
          <div className="space-y-4 text-center">
            <div className="mx-auto w-16 h-16 rounded-full bg-gradient-to-br from-amber-400/20 to-amber-600/20 border border-amber-400/40 flex items-center justify-center">
              <Key className="w-8 h-8 text-amber-300" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-amber-100">Yaşam Anahtarı ile Kurtar</h2>
              <p className="text-xs text-amber-200/60 mt-2 leading-relaxed max-w-xs mx-auto">
                24 kelimelik egemen kurtarma anahtarınla doğrula, ardından
                <b className="text-amber-100"> aynı ekranda yeni şifreni</b> belirle. Kelimeler
                tarayıcından çıkmaz; sadece SHA-256 özet gönderilir.
              </p>
            </div>
            <Button
              onClick={() => setStep("input")}
              className="w-full bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold hover:opacity-90"
            >
              Devam Et
            </Button>
          </div>
        )}

        {step === "input" && (
          <div className="space-y-4">
            <div>
              <label className="text-[10px] uppercase tracking-wider text-amber-300/70 font-mono">Kurd-ID</label>
              <div className="relative mt-1">
                <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-xs font-bold text-amber-300">
                  +777
                </span>
                <input
                  type="text"
                  inputMode="numeric"
                  value={kurdId}
                  onChange={(e) => setKurdId(formatKurdId(e.target.value))}
                  placeholder="0000 0000"
                  className="w-full bg-black/40 border border-amber-400/30 rounded-lg pl-14 pr-3 py-2 font-mono text-sm tracking-[0.15em] text-amber-100 focus:outline-none focus:border-amber-300"
                />
              </div>
            </div>

            <div>
              <label className="text-[10px] uppercase tracking-wider text-amber-300/70 font-mono">
                Yaşam Anahtarı (24 kelime)
              </label>
              <textarea
                value={phrase}
                onChange={(e) => {
                  setPhrase(e.target.value);
                  if (error) setError(null);
                }}
                rows={4}
                spellCheck={false}
                autoCapitalize="none"
                placeholder="kelime1 kelime2 kelime3 ... kelime24"
                className="w-full mt-1 bg-black/40 border border-amber-400/30 rounded-lg px-3 py-2 text-amber-100 text-sm font-mono focus:outline-none focus:border-amber-300 resize-none"
              />
              <p className="mt-1 text-[10px] text-amber-200/50">
                Kelime sayısı: {phrase.trim() ? phrase.trim().split(/\s+/).length : 0} / 24
              </p>
            </div>

            {error && (
              <div className="flex items-start gap-2 rounded-lg border border-rose-500/40 bg-rose-500/10 p-2.5 text-[11px] text-rose-200">
                <AlertTriangle className="w-4 h-4 text-rose-300 shrink-0 mt-0.5" />
                <span>{error}</span>
              </div>
            )}

            <div className="flex gap-2">
              <Button variant="outline" className="flex-1 border-amber-400/30" onClick={close}>
                İptal
              </Button>
              <Button
                onClick={verify}
                disabled={loading}
                className="flex-1 bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold hover:opacity-90"
              >
                {loading ? "Doğrulanıyor..." : "Doğrula"}
              </Button>
            </div>
          </div>
        )}

        {step === "newPassword" && (
          <div className="space-y-4">
            <div className="text-center">
              <div className="mx-auto w-14 h-14 rounded-full bg-gradient-to-br from-emerald-400/20 to-emerald-600/20 border border-emerald-400/40 flex items-center justify-center">
                <Check className="w-7 h-7 text-emerald-300" />
              </div>
              <h2 className="mt-3 text-lg font-bold text-amber-100">Yeni Şifreni Belirle</h2>
              <p className="text-[11px] text-amber-200/60 mt-1">
                Yaşam Anahtarın doğrulandı. Hesabın için yeni bir şifre oluştur.
              </p>
            </div>

            <div>
              <label className="text-[10px] uppercase tracking-wider text-amber-300/70 font-mono">Yeni Şifre</label>
              <div className="relative mt-1">
                <Lock className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-amber-400/60" />
                <input
                  type={showPwd ? "text" : "password"}
                  value={newPassword}
                  onChange={(e) => {
                    setNewPassword(e.target.value);
                    if (error) setError(null);
                  }}
                  placeholder="En az 8 karakter"
                  className="w-full bg-black/40 border border-amber-400/30 rounded-lg pl-10 pr-10 py-2 text-amber-100 text-sm focus:outline-none focus:border-amber-300"
                />
                <button
                  type="button"
                  onClick={() => setShowPwd((v) => !v)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-amber-400/70 hover:text-amber-300"
                  aria-label={showPwd ? "Şifreyi gizle" : "Şifreyi göster"}
                >
                  {showPwd ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>

            <div>
              <label className="text-[10px] uppercase tracking-wider text-amber-300/70 font-mono">Şifre (Tekrar)</label>
              <div className="relative mt-1">
                <Lock className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-amber-400/60" />
                <input
                  type={showPwd ? "text" : "password"}
                  value={confirmPassword}
                  onChange={(e) => {
                    setConfirmPassword(e.target.value);
                    if (error) setError(null);
                  }}
                  placeholder="Şifreyi tekrar gir"
                  className="w-full bg-black/40 border border-amber-400/30 rounded-lg pl-10 pr-3 py-2 text-amber-100 text-sm focus:outline-none focus:border-amber-300"
                />
              </div>
            </div>

            {error && (
              <div className="flex items-start gap-2 rounded-lg border border-rose-500/40 bg-rose-500/10 p-2.5 text-[11px] text-rose-200">
                <AlertTriangle className="w-4 h-4 text-rose-300 shrink-0 mt-0.5" />
                <span>{error}</span>
              </div>
            )}

            <div className="flex gap-2">
              <Button variant="outline" className="flex-1 border-amber-400/30" onClick={close}>
                İptal
              </Button>
              <Button
                onClick={submitNewPassword}
                disabled={loading || newPassword.length < 8 || newPassword !== confirmPassword}
                className="flex-1 bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold hover:opacity-90"
              >
                {loading ? "Güncelleniyor..." : "Şifreyi Güncelle"}
              </Button>
            </div>

            <button
              type="button"
              onClick={sendResetEmailFallback}
              disabled={loading}
              className="w-full text-center text-[11px] text-amber-300/70 hover:text-amber-200 underline underline-offset-2"
            >
              Bunun yerine kurtarma e-postası gönder
            </button>
          </div>
        )}

        {step === "done" && (
          <div className="space-y-4 text-center py-2">
            <div className="mx-auto w-16 h-16 rounded-full bg-gradient-to-br from-emerald-400 to-emerald-600 flex items-center justify-center">
              <Check className="w-8 h-8 text-black" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-amber-100">Şifre Güncellendi</h2>
              <p className="text-xs text-amber-200/70 mt-2 leading-relaxed">
                Hesabına yeni şifrenle hemen giriş yapabilirsin.
              </p>
            </div>
            <Button
              onClick={close}
              className="w-full bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold"
            >
              Giriş Ekranına Dön
            </Button>
          </div>
        )}

        {step === "emailSent" && (
          <div className="space-y-4 text-center py-2">
            <div className="mx-auto w-16 h-16 rounded-full bg-gradient-to-br from-amber-400 to-amber-600 flex items-center justify-center">
              <Mail className="w-8 h-8 text-black" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-amber-100">Kurtarma E-postası Gönderildi</h2>
              <p className="text-xs text-amber-200/70 mt-2 leading-relaxed">
                <span className="font-mono">{matchedEmail}</span>
                <br />
                adresine şifre sıfırlama bağlantısı gönderildi.
              </p>
            </div>
            <Button onClick={close} className="w-full bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold">
