import { useMemo, useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { QRCodeSVG } from "qrcode.react";
import { Copy, Check, Share2, ScanLine, Sparkles, ShieldCheck } from "lucide-react";
import { toast } from "sonner";
import { buildEgemenShareUrl } from "@/lib/egemenToken";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  /** Public profile slug — username preferred, falls back to user id */
  handle: string;
  displayName: string;
  kurdId: string | null;
  kekaScore: number;
}

export function ShareEgemenDialog({
  open,
  onOpenChange,
  handle,
  displayName,
  kurdId,
  kekaScore,
}: Props) {
  const [copied, setCopied] = useState(false);

  const url = useMemo(() => {
    if (typeof window === "undefined") return "";
    return buildEgemenShareUrl(window.location.origin, {
      u: handle,
      n: displayName,
      k: kurdId,
      s: kekaScore,
    });
  }, [handle, displayName, kurdId, kekaScore]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(url);
      setCopied(true);
      toast.success("Link kopyalandı");
      setTimeout(() => setCopied(false), 1800);
    } catch {
      toast.error("Kopyalanamadı");
    }
  };

  const share = async () => {
    if (typeof navigator !== "undefined" && "share" in navigator) {
      try {
        await (
          navigator as Navigator & { share: (data: ShareData) => Promise<void> }
        ).share({
          title: `${displayName} · Egemen`,
          text: "Egemen kartımı tara — Sovereign Profile",
          url,
        });
      } catch {
        /* user cancelled */
      }
    } else {
      copy();
    }
  };

  // Short visual fingerprint of the signed token
  const fingerprint = useMemo(() => {
    const sig = url.split(".").pop() ?? "";
    return sig.slice(0, 7).toUpperCase();
  }, [url]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-[#08070A] border-amber-400/30 text-foreground max-w-sm">
        <DialogHeader>
          <div className="text-[9px] font-mono uppercase tracking-[0.3em] text-amber-300/70 text-center">
            Share Egemen Card
          </div>
          <DialogTitle className="text-amber-100 text-center text-base">
            Egemen Kartımı Paylaş
          </DialogTitle>
        </DialogHeader>

        {/* QR */}
        <div className="mt-2 flex justify-center">
          <div className="relative p-4 rounded-2xl bg-gradient-to-br from-amber-400/15 via-amber-500/5 to-black border border-amber-400/40 shadow-[0_0_40px_-10px_rgba(212,175,55,0.6)]">
            <div className="absolute inset-0 rounded-2xl pointer-events-none ring-1 ring-inset ring-amber-300/20" />
            <div className="bg-black p-3 rounded-xl">
              <QRCodeSVG
                value={url || "https://jiyan.world"}
                size={184}
                bgColor="#000000"
                fgColor="#D4AF37"
                level="M"
                marginSize={0}
              />
            </div>
            <div className="absolute -top-2 left-1/2 -translate-x-1/2 px-2 py-0.5 rounded-full bg-amber-400 text-[8px] font-black uppercase tracking-widest text-black flex items-center gap-1">
              <Sparkles className="h-2.5 w-2.5" /> +777
            </div>
          </div>
        </div>

        {/* Signed token strip */}
        <div className="mt-3 flex items-center justify-center gap-1.5 text-[9px] font-mono uppercase tracking-[0.25em] text-amber-300/60">
          <ShieldCheck className="h-3 w-3 text-amber-400/80" />
          Signed · <span className="text-amber-200/85">{fingerprint}</span>
        </div>

        {/* Identity strip */}
        <div className="mt-3 flex items-center justify-between rounded-xl border border-amber-400/20 bg-black/40 px-3 py-2.5">
          <div className="min-w-0">
            <div className="text-sm font-bold text-amber-100 truncate">{displayName}</div>
            {kurdId && (
              <div className="text-[10px] font-mono text-amber-300/70 truncate">
                {kurdId}
              </div>
            )}
          </div>
          <div className="text-right shrink-0 ml-3">
            <div className="text-[8px] font-mono uppercase tracking-widest text-amber-300/60">
              KEKA
            </div>
            <div className="text-base font-black text-amber-200 tabular-nums leading-none">
              {kekaScore.toLocaleString("en-US")}
            </div>
          </div>
        </div>

        {/* URL row */}
        <button
          onClick={copy}
          className="mt-3 w-full flex items-center justify-between gap-2 rounded-xl border border-amber-400/15 bg-black/40 px-3 py-2.5 text-left hover:border-amber-400/35 transition"
        >
          <span className="text-[11px] font-mono text-amber-200/85 truncate">{url}</span>
          {copied ? (
            <Check className="h-4 w-4 text-amber-300 shrink-0" />
          ) : (
            <Copy className="h-4 w-4 text-amber-300/70 shrink-0" />
          )}
        </button>

        {/* Actions */}
        <div className="mt-3 grid grid-cols-2 gap-2">
          <button
            onClick={share}
            className="flex items-center justify-center gap-1.5 py-3 rounded-xl bg-gradient-to-r from-amber-500 to-amber-300 text-black font-bold tracking-wider uppercase text-[11px] active:scale-[0.98]"
          >
            <Share2 className="h-3.5 w-3.5" />
            Paylaş
          </button>
          <button
            onClick={() => onOpenChange(false)}
            className="flex items-center justify-center gap-1.5 py-3 rounded-xl border border-amber-400/30 text-amber-200 text-[11px] font-bold uppercase tracking-wider hover:bg-amber-400/10 transition"
          >
            <ScanLine className="h-3.5 w-3.5" />
            Tarat
          </button>
        </div>

        <p className="mt-3 text-center text-[10px] font-mono italic text-amber-200/50">
          “Honor is the only currency that never devalues.”
        </p>
      </DialogContent>
    </Dialog>
  );
}

