import { useEffect, useRef, useState } from "react";
import { Music, Crown, Square, Plus, Minus, Users, Zap, LogOut } from "lucide-react";
import type { GovendSession } from "@/hooks/useSovereignSpace";

interface Props {
  userId: string | null;
  active: GovendSession | null;
  list: GovendSession[];
  onStart: (bpm: number) => Promise<void> | void;
  onJoin: (id: string) => Promise<void> | void;
  onLeave: () => Promise<void> | void;
  onStop: () => Promise<void> | void;
  onBpmChange: (bpm: number) => void;
  hapticEnabled: boolean;
}

export function SmartGovend({
  userId,
  active,
  list,
  onStart,
  onJoin,
  onLeave,
  onStop,
  onBpmChange,
  hapticEnabled,
}: Props) {
  const [pulse, setPulse] = useState(0);
  const [energy, setEnergy] = useState(0);
  const tickRef = useRef<number | null>(null);

  const isLeader = !!active && active.leader_id === userId;
  const bpm = active?.bpm ?? 100;
  const intervalMs = 60000 / bpm;

  // Beat loop
  useEffect(() => {
    if (!active) {
      setPulse(0);
      return;
    }
    const tick = () => {
      setPulse((p) => p + 1);
      setEnergy((e) => Math.min(100, e + 1.2));
      if (hapticEnabled && typeof navigator !== "undefined" && navigator.vibrate) {
        try {
          navigator.vibrate(35);
        } catch {
          /* noop */
        }
      }
    };
    tick();
    tickRef.current = window.setInterval(tick, intervalMs);
    return () => {
      if (tickRef.current) clearInterval(tickRef.current);
    };
  }, [active, intervalMs, hapticEnabled]);

  // Energy decay
  useEffect(() => {
