/**
 * SovereignActionGate — Wraps any high-value action (DiravCash transfer,
 * Kurd-ID Borsa purchase, future Mail-signed message) in a single check:
 *
 *   • Egemen Pencere (Sovereign Window) aktifse → kullanıcıya hiçbir şey
 *     sormadan altın bir "Senkronize" rozeti gösterip aksiyonu otomatik
 *     onaylar (~600ms cinematic delay).
 *   • Aktif değilse → minimal bir altın bottom-sheet açar:
 *       1. Yaşam Anahtarı (FaceID/TouchID) — tek dokunuşla
 *       2. Egemen Kod (Authenticator TOTP) — 6 hane
 *     Başarılı doğrulamadan sonra `bump_sovereign_auth` çağrılır,
 *     `onConfirm()` tetiklenir ve sonraki 15 dk her aksiyon sessizce geçer.
 *
 * Not: Mevcut `SovereignGate` (E-Devlet KYC kapısı) ile karıştırılmamalı —
 * bu daha hafif, *adım-yükseltici* (step-up) bir kapıdır.
 */
import { useState, useEffect, useCallback } from "react";
import { ShieldCheck, KeyRound, Fingerprint, Loader2, X, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useSovereignAuth } from "@/hooks/useSovereignAuth";
import { usePasskeys } from "@/hooks/usePasskeys";
import { useTotp } from "@/hooks/useTotp";
import { useDengApproval } from "@/hooks/useDengApproval";
import { toast } from "sonner";

interface SovereignActionGateProps {
  open: boolean;
  /** Short label of the action being authorised, e.g. "12 DC Transferi". */
  actionLabel: string;
  /** Optional secondary line, e.g. recipient name. */
  actionDetail?: string;
  /** Called once the user is verified (silently or via a method). */
  onConfirm: () => void | Promise<void>;
  onClose: () => void;
}

export function SovereignActionGate({
  open,
  actionLabel,
  actionDetail,
  onConfirm,
  onClose,
}: SovereignActionGateProps) {
  const { isSovereignVerified, remainingSeconds, bump } = useSovereignAuth();
  const { authenticate, hasPasskeys, isSupported } = usePasskeys();
  const { row: totpRow, validate } = useTotp();
  const { request: requestDeng } = useDengApproval();

  const [code, setCode] = useState("");
  const [busy, setBusy] = useState(false);
  const [silentTried, setSilentTried] = useState(false);
  const [dengWaiting, setDengWaiting] = useState(false);

  const runConfirm = useCallback(async () => {
    setBusy(true);
    try {
      await onConfirm();
    } finally {
      setBusy(false);
      onClose();
    }
  }, [onConfirm, onClose]);

  // Silent path — Sovereign Window aktifse cinematic 600ms ardından geç.
  useEffect(() => {
    if (!open || silentTried) return;
    if (isSovereignVerified) {
      setSilentTried(true);
      const t = setTimeout(() => {
        runConfirm();
      }, 600);
      return () => clearTimeout(t);
    }
  }, [open, silentTried, isSovereignVerified, runConfirm]);

  // Sheet kapandığında state sıfırla
  useEffect(() => {
    if (!open) {
      setCode("");
      setBusy(false);
      setSilentTried(false);
      setDengWaiting(false);
    }
  }, [open]);

  if (!open) return null;

  const handleDeng = async () => {
    setBusy(true);
    setDengWaiting(true);
    try {
      const ok = await requestDeng({
        actionType: "sensitive_action",
        subject: "Egemen Onay İsteği",
        body: `${actionLabel}${actionDetail ? `\n${actionDetail}` : ""}\n\nDeng üzerinden onay vermek için "Onayla"ya bas.`,
        expiresInMinutes: 3,
      });
      if (ok) {
        await bump("password" as any, 15, "Deng Onayı");
        toast.success("Deng onayı alındı — egemen pencere açıldı");
        await onConfirm();
        onClose();
      } else {
        toast.error("Deng onayı verilmedi");
      }
    } catch (e: any) {
      toast.error(e?.message ?? "Deng onayı başarısız");
    } finally {
      setBusy(false);
      setDengWaiting(false);
    }
  };

  const handlePasskey = async () => {
    if (!isSupported || !hasPasskeys) {
      toast.error("Yaşam Anahtarı bu cihazda kayıtlı değil");
      return;
    }
    setBusy(true);
    try {
      const ok = await authenticate();
      if (ok) {
        await bump("passkey", 15, "Yaşam Anahtarı");
        toast.success("Egemen pencere açıldı — 15 dk");
        await onConfirm();
        onClose();
      } else {
        toast.error("Doğrulama iptal edildi");
      }
    } finally {
      setBusy(false);
    }
  };

  const handleTotp = async () => {
    if (code.length !== 6) return;
    setBusy(true);
    try {
      const ok = await validate(code);
      if (!ok) {
        toast.error("Egemen Kod hatalı");
        return;
      }
      await bump("totp", 15, "Jiyan Authenticator");
      toast.success("Egemen pencere açıldı — 15 dk");
      await onConfirm();
      onClose();
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      className="fixed inset-0 z-[1100] flex items-end sm:items-center justify-center"
    >
      <button
        type="button"
        aria-label="Kapat"
        onClick={busy ? undefined : onClose}
        className="absolute inset-0 bg-black/70 backdrop-blur-2xl animate-fade-in"
      />

      <div
        className="relative w-full max-w-md mx-auto sm:rounded-3xl rounded-t-[28px]
                   border border-amber-400/30
                   bg-gradient-to-b from-[#1a1107]/95 via-[#0a0703]/98 to-black/100
                   shadow-[0_-30px_80px_-10px_rgba(245,200,80,0.30)] p-5 pb-7"
        style={{ animationName: "hub-sheet-up", animationDuration: "320ms" }}
      >
        <div className="flex sm:hidden justify-center mb-3">
          <span className="block h-1 w-10 rounded-full bg-amber-300/40" />
        </div>

        <div className="flex items-start justify-between mb-3">
          <div className="flex items-center gap-2">
            <span className="relative flex h-9 w-9 items-center justify-center rounded-full bg-amber-400/15 border border-amber-400/30">
              <ShieldCheck className="h-4 w-4 text-amber-300" />
              {isSovereignVerified && (
                <span className="absolute inset-0 rounded-full bg-amber-400/30 animate-ping" />
              )}
            </span>
            <div>
              <h2 className="text-sm font-semibold text-amber-100 tracking-tight">
                Egemen Onay
              </h2>
              <p className="text-[10px] uppercase tracking-[0.2em] text-amber-200/60">
                Sovereign Security
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={busy ? undefined : onClose}
            className="rounded-full p-1.5 text-amber-200/60 hover:text-amber-100 hover:bg-amber-400/10 disabled:opacity-40"
            disabled={busy}
            aria-label="Kapat"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Action summary */}
        <div className="rounded-2xl border border-amber-400/20 bg-black/40 p-3 mb-4">
          <p className="text-[10px] uppercase tracking-[0.2em] text-amber-200/55">
            Onaylanacak işlem
          </p>
          <p className="text-base font-semibold text-amber-100 mt-0.5">
            {actionLabel}
          </p>
          {actionDetail && (
            <p className="text-xs text-amber-200/65 mt-0.5">{actionDetail}</p>
          )}
        </div>

        {isSovereignVerified ? (
          <div className="flex flex-col items-center justify-center py-6 gap-2">
            {busy ? (
              <Loader2 className="h-7 w-7 text-amber-300 animate-spin" />
            ) : (
              <ShieldCheck className="h-9 w-9 text-amber-300" />
            )}
            <p className="text-sm text-amber-100">
              Egemen pencere aktif · {Math.ceil(remainingSeconds / 60)} dk
            </p>
            <p className="text-[11px] text-amber-200/60">
              Doğrulamadan otomatik onaylanıyor…
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {isSupported && hasPasskeys && (
              <button
                type="button"
                onClick={handlePasskey}
                disabled={busy}
                className="w-full flex items-center gap-3 rounded-2xl border border-amber-400/30
                           bg-gradient-to-r from-amber-500/10 to-amber-600/5 px-4 py-3
                           hover:from-amber-500/20 hover:to-amber-600/10 transition-all disabled:opacity-50"
              >
                <span className="flex h-9 w-9 items-center justify-center rounded-full bg-amber-400/15 border border-amber-400/30">
                  <Fingerprint className="h-4 w-4 text-amber-200" />
                </span>
                <div className="flex-1 text-left">
                  <p className="text-sm font-semibold text-amber-100">Yaşam Anahtarı</p>
                  <p className="text-[11px] text-amber-200/60">
                    FaceID / TouchID ile tek dokunuş
                  </p>
                </div>
              </button>
            )}

            {/* Deng Onayı — universal fallback / primary */}
            <button
              type="button"
              onClick={handleDeng}
              disabled={busy}
              className="w-full flex items-center gap-3 rounded-2xl border border-amber-400/30
                         bg-gradient-to-r from-amber-500/15 to-amber-600/5 px-4 py-3
                         hover:from-amber-500/25 hover:to-amber-600/10 transition-all disabled:opacity-50"
            >
              <span className="flex h-9 w-9 items-center justify-center rounded-full bg-amber-400/15 border border-amber-400/30">
                {dengWaiting ? (
                  <Loader2 className="h-4 w-4 text-amber-200 animate-spin" />
                ) : (
                  <Sparkles className="h-4 w-4 text-amber-200" />
                )}
              </span>
              <div className="flex-1 text-left">
                <p className="text-sm font-semibold text-amber-100">
                  {dengWaiting ? "Deng'de bekleniyor…" : "Deng ile Onayla"}
                </p>
                <p className="text-[11px] text-amber-200/60">
                  {dengWaiting
                    ? "Telefonundan Deng inbox'ında onayla"
                    : "Onay isteği Deng Support'tan gelir · 3 dk"}
                </p>
              </div>
            </button>

            {totpRow?.is_active ? (
              <div className="rounded-2xl border border-amber-400/25 bg-black/50 px-4 py-3">
                <div className="flex items-center gap-2 mb-2">
                  <KeyRound className="h-4 w-4 text-amber-300" />
                  <p className="text-sm font-semibold text-amber-100">Egemen Kod</p>
                </div>
                <input
                  type="text"
                  inputMode="numeric"
                  pattern="\d*"
                  maxLength={6}
                  placeholder="6 hane"
                  value={code}
                  onChange={(e) =>
                    setCode(e.target.value.replace(/\D/g, "").slice(0, 6))
                  }
                  className="w-full bg-black/60 border border-amber-400/25 rounded-xl
                             px-3 py-2 text-amber-100 text-center font-mono text-xl
                             tracking-[0.4em] placeholder:text-amber-200/30
                             focus:outline-none focus:border-amber-400/60"
                />
                <Button
                  onClick={handleTotp}
                  disabled={code.length !== 6 || busy}
                  className="w-full mt-2 bg-gradient-to-r from-amber-500 to-amber-600
                             hover:from-amber-400 hover:to-amber-500 text-black font-semibold"
                >
                  {busy ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    "Onayla & Senkronize Et"
                  )}
                </Button>
              </div>
            ) : (
              !hasPasskeys && (
                <p className="text-xs text-amber-200/60 text-center py-2">
                  Önce{" "}
                  <a href="/authenticator" className="text-amber-300 underline">
                    Egemen Kod
                  </a>{" "}
                  veya{" "}
                  <a href="/security" className="text-amber-300 underline">
                    Yaşam Anahtarı
                  </a>{" "}
                  kur.
                </p>
              )
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * SovereignActionSheet — Telegram-tarzı sheet için ince sarmalayıcı.
 *
 * Geriye dönük uyumluluk: aynı props (open/onClose/title/subtitle/height/children).
 * Subtitle artık küçük altın etiket olarak korunur; geri kalan tüm davranış
 * yeni TGSheet primitive'ine devredilir.
 */
import { ReactNode } from "react";
import { TGSheet } from "@/components/sovereign/TGSheet";

interface Props {
  open: boolean;
  onClose: () => void;
  title?: string;
  subtitle?: string;
  /** 0–1 viewport oranı. Default 0.86 (yarım sheet). 1 = tam ekran. */
  height?: number;
  children: ReactNode;
}

export function SovereignActionSheet({
  open,
  onClose,
  title,
  subtitle,
  height = 0.86,
  children,
}: Props) {
  return (
    <TGSheet open={open} onClose={onClose} title={title} height={height}>
      {subtitle && (
        <div
          className="px-5 pt-1 pb-3 text-[10px] uppercase tracking-[0.32em]"
          style={{ color: "#D4AF37" }}
        >
          {subtitle}
        </div>
      )}
      <div className="px-4 pb-6">{children}</div>
    </TGSheet>
  );
}

