/**
 * SovereignControlSheet — Apple-style unified Profile + Security panel.
 *
 * Module 4 of the Sovereign OS suite. Surfaces in a half-modal bottom sheet
 * when the user taps the "Profil" or "Güvenlik" mini-app from the Hub. Brings
 * Profile, Security verification window, TOTP Authenticator, 2FA, Yaşam
 * Anahtarı (passkey), and active sessions into one premium surface.
 *
 * Built on SovereignActionSheet (swipe-down to dismiss, frosted glass).
 * Heavy operations (TOTP enable, passkey register) reuse the existing hooks
 * and write through Lovable Cloud — no duplicated business logic.
 */
import { useNavigate } from "@tanstack/react-router";
import { useAuth } from "@/hooks/useAuth";
import { useSovereignProfile } from "@/hooks/useSovereignProfile";
import { useSovereignAuth } from "@/hooks/useSovereignAuth";
import { useTotp } from "@/hooks/useTotp";
import { useTwoFactor } from "@/hooks/useTwoFactor";
import { usePasskeys } from "@/hooks/usePasskeys";
import { SovereignActionSheet } from "@/components/sovereign/SovereignActionSheet";
import { SovereignSettingsGroup } from "@/components/settings/SovereignSettingsGroup";
import { SovereignSettingRow } from "@/components/settings/SovereignSettingRow";
import { hapticTap } from "@/lib/native";
import { toast } from "sonner";
import {
  ShieldCheck,
  Fingerprint,
  KeyRound,
  Smartphone,
  Crown,
  IdCard,
  UserCircle2,
  Sparkles,
  Pencil,
  ChevronRight,
  Clock,
  Plus,
} from "lucide-react";

interface Props {
  open: boolean;
  onClose: () => void;
  /** Which intent surfaced the sheet — selects the highlighted section. */
  focus?: "profile" | "security";
}

export function SovereignControlSheet({ open, onClose, focus = "profile" }: Props) {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { data: profile } = useSovereignProfile(user?.id);
  const { isSovereignVerified, remainingSeconds, state } = useSovereignAuth();
  const { row: totpRow, code, remaining, enable: enableTotp, disable: disableTotp } = useTotp();
  const { enabled: tfaEnabled, setTwoFactorEnabled, loading: tfaLoading } = useTwoFactor();
  const { passkeys, hasPasskeys, isSupported: passkeySupported, register: registerPasskey, busy: passkeyBusy } = usePasskeys();

  const isGuest = !user;
  const minutes = Math.ceil(remainingSeconds / 60);

  const go = (path: string) => {
    hapticTap();
    onClose();
    setTimeout(() => navigate({ to: path }), 220);
  };

  const handleTotp = async () => {
    hapticTap();
    if (totpRow?.is_active) {
      await disableTotp();
    } else {
      await enableTotp();
    }
  };

  const handle2FA = async () => {
    hapticTap();
    const ok = await setTwoFactorEnabled(!tfaEnabled);
    if (ok) toast.success(!tfaEnabled ? "2FA açıldı" : "2FA kapatıldı");
  };

  const handlePasskey = async () => {
    hapticTap();
    await registerPasskey();
  };

  if (isGuest) {
    return (
      <SovereignActionSheet
        open={open}
        onClose={onClose}
        title="Egemen Kimlik"
        subtitle="Sovereign Control"
        height={0.55}
      >
        <div className="mt-2 rounded-2xl p-5 text-center"
          style={{
            background: "linear-gradient(140deg, rgba(40,28,5,0.85), rgba(8,5,0,0.96))",
            border: "1px solid rgba(212,175,55,0.35)",
          }}
        >
          <Crown className="mx-auto h-10 w-10 mb-3" style={{ color: "#F5CD53" }} />
          <h3 className="text-base font-semibold text-amber-100">
            Profil + Güvenlik kilitli
          </h3>
          <p className="mt-2 text-[12px] text-amber-200/65 leading-relaxed">
            Egemen Kontrol Merkezini kullanmak için Jiyan ID ile giriş yapın.
          </p>
          <button
