/**
 * SovereignGate — server-trusted KYC gate used by /e-devlet and every E-Devlet
 * sub-route (/e-devlet/congress, /e-devlet/whitepaper, /e-devlet/manifesto).
 *
 * Renders one of three states:
 *   1. Loading — Mühür kontrol ediliyor…
 *   2. Identity Required — full gate with KycProgressWidget + retry button
 *   3. Verified — renders children
 *
 * Verification flag comes from the SECURITY DEFINER RPC `get_my_kyc_status`
 * (see useEDevletAccess), so client UI cannot bypass the check.
 */
import { type ReactNode } from "react";
import { Link, useNavigate } from "@tanstack/react-router";
import {
  Loader2,
  Lock,
  ShieldAlert,
  ShieldCheck,
  ArrowRight,
  Fingerprint,
  ChevronLeft,
  Landmark,
} from "lucide-react";
import { AppShell } from "@/components/layout/AppShell";
import { Button } from "@/components/ui/button";
import { useEDevletAccess } from "@/hooks/useEDevletAccess";
import { KycProgressWidget } from "./KycProgressWidget";

interface Props {
  /** Path shown in the back button — defaults to /e-devlet */
  backTo?: string;
  /** Doc title shown in the gate (e.g. "Kongre", "Manifesto") */
  documentLabel?: string;
  children: ReactNode;
}

export function SovereignGate({ backTo = "/e-devlet", documentLabel, children }: Props) {
  const access = useEDevletAccess();
  const navigate = useNavigate();

  if (access.loading) {
    return (
      <AppShell>
        <GateShell>
          <div className="flex flex-col items-center justify-center py-32 gap-3">
            <Loader2 className="h-6 w-6 animate-spin text-amber-300" />
            <p className="text-xs text-amber-200/60 tracking-widest uppercase">Mühür kontrol ediliyor…</p>
          </div>
        </GateShell>
      </AppShell>
    );
  }

  if (!access.isVerified) {
    return (
      <AppShell>
        <GateShell backTo={backTo}>
          <section className="relative px-5 pt-4 pb-12">
            <div className="mx-auto max-w-md">
              {/* Crest */}
              <div className="flex flex-col items-center text-center">
                <div className="relative h-28 w-28 mb-5">
                  <div className="absolute inset-0 rounded-full bg-gradient-to-br from-amber-400/25 to-yellow-300/10 blur-xl" />
                  <div className="relative h-full w-full rounded-full border-2 border-amber-400/40 bg-black/60 flex items-center justify-center">
                    <Lock className="h-10 w-10 text-amber-300" strokeWidth={1.5} />
                    <ShieldAlert className="absolute -bottom-1 -right-1 h-7 w-7 text-amber-300 bg-[#070604] rounded-full p-1 border border-amber-400/40" />
                  </div>
                </div>

                <p className="text-[10px] uppercase tracking-[0.35em] text-amber-300/80 mb-2">
                  Sovereign Identity Required
                </p>
                <h1 className="text-2xl font-bold text-amber-100 leading-tight">
                  {documentLabel ? `${documentLabel} mühürlüdür` : "E-Devlet kapısı mühürlüdür"}
                </h1>
                <p className="mt-3 text-sm text-amber-100/60 leading-relaxed max-w-sm">
                  {documentLabel
                    ? `${documentLabel} belgesine yalnızca KYC doğrulanmış egemenler erişebilir.`
                    : "Kongre, Anayasa ve Manifesto'ya yalnızca KYC doğrulanmış egemenler erişebilir."}{" "}
                  Devlet kapısından geçmek için kimliğinizi mühürleyin.
                </p>
              </div>

              {/* Identity status row */}
              <div className="mt-7 rounded-2xl border border-amber-400/20 bg-[linear-gradient(180deg,rgba(245,158,11,0.05),rgba(0,0,0,0.4))] p-4">
                <div className="flex items-center gap-3">
                  <Fingerprint className="h-5 w-5 text-amber-300/80" />
                  <div className="flex-1 min-w-0">
                    <p className="text-[10px] uppercase tracking-widest text-amber-200/50">Kimlik Durumu</p>
                    <p className="text-sm font-semibold text-amber-100">{stageLabel(access.stage)}</p>
                  </div>
                  <span className="text-[10px] px-2 py-1 rounded-full bg-red-500/15 text-red-300 border border-red-400/30 font-semibold">
                    KAPALI
                  </span>
                </div>
                {access.kurdId && (
                  <div className="mt-3 pt-3 border-t border-amber-400/10 text-[11px] text-amber-200/50 font-mono">
                    {access.kurdId}
                  </div>
                )}
              </div>

              {/* Progress widget */}
              <div className="mt-4">
                <KycProgressWidget
                  stage={access.stage}
                  rejectionReason={access.rejectionReason}
                  submittedAt={access.submittedAt}
                  refreshing={access.refreshing}
                  onRefresh={access.refresh}
                />
              </div>

              {access.error && (
                <div className="mt-4 rounded-xl border border-red-400/20 bg-red-500/10 p-3 text-[11px] leading-relaxed text-red-200/85">
                  Kimlik durumu alınırken geçici bir sorun oluştu. Lütfen yenile butonuna basın.
                </div>
              )}

              {/* CTA */}
              <div className="mt-6 space-y-2.5">
                <Button
                  onClick={() =>
                    navigate({ to: access.stage === "no_account" ? "/login" : "/kyc" })
                  }
                  className="w-full h-12 bg-gradient-to-r from-amber-500 to-yellow-300 text-black font-bold hover:from-amber-400 hover:to-yellow-200 shadow-[0_8px_24px_-8px_rgba(245,158,11,0.5)]"
                >
                  <ShieldCheck className="h-4 w-4 mr-2" />
                  {ctaLabel(access.stage)}
                  <ArrowRight className="h-4 w-4 ml-2" />
                </Button>
                <Button
                  variant="ghost"
                  onClick={() => navigate({ to: "/dashboard" })}
                  className="w-full h-10 text-amber-200/60 hover:text-amber-100 hover:bg-amber-500/5"
                >
                  Ana Ekrana Dön
                </Button>
              </div>

              <div className="mt-7 rounded-xl border border-white/5 bg-white/[0.02] p-4 text-[11px] leading-relaxed text-amber-100/50">
                <p className="text-amber-200/80 font-semibold mb-1.5 text-xs">Neden mühürlü?</p>
                E-Devlet; halk oylamaları, anayasal imzalar ve resmi belgeler içerir. Mühürlü kimlik
                tek-kişi-tek-oy ilkesini ve sahte temsilciliklere karşı korumayı garanti eder.
              </div>
            </div>
          </section>
        </GateShell>
      </AppShell>
    );
  }

  return <>{children}</>;
}

function GateShell({ backTo, children }: { backTo?: string; children: ReactNode }) {
  return (
    <div className="min-h-[100dvh] bg-[#070604] text-amber-50 relative overflow-hidden">
      <div
        aria-hidden
        className="pointer-events-none absolute -top-32 left-1/2 -translate-x-1/2 h-[420px] w-[420px] rounded-full bg-amber-500/15 blur-3xl"
      />
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_50%_-10%,rgba(245,158,11,0.08),transparent_60%)]"
      />
      <header className="relative px-4 pt-5 pb-3 flex items-center justify-between">
        {backTo ? (
          <Link
            to={backTo}
            className="h-9 w-9 rounded-full border border-amber-400/20 bg-black/40 flex items-center justify-center text-amber-200/80 active:scale-95 transition"
            aria-label="Geri"
          >
            <ChevronLeft className="h-4 w-4" />
          </Link>
        ) : (
          <div className="w-9" />
        )}
        <div className="flex items-center gap-1.5 text-[10px] uppercase tracking-[0.25em] text-amber-200/70">
          <Landmark className="h-3 w-3" />
          WKO Sovereign State
        </div>
        <div className="w-9" />
      </header>
      {children}
    </div>
  );
}

function stageLabel(stage: ReturnType<typeof useEDevletAccess>["stage"]): string {
  switch (stage) {
    case "no_account":
      return "Hesap bulunamadı";
    case "no_submission":
      return "KYC başlatılmadı";
    case "pending":
      return "KYC İncelemede";
    case "rejected":
      return "KYC Reddedildi";
    case "verified":
      return "Mühürlü";
  }
}

function ctaLabel(stage: ReturnType<typeof useEDevletAccess>["stage"]): string {
  switch (stage) {
    case "no_account":
      return "Giriş Yap & Mühürle";
    case "rejected":
      return "Yeniden Gönder";
    case "pending":
      return "Doğrulama Devam Ediyor";
    default:
      return "Kimliğimi Mühürle (KYC)";
  }
}

