import { useEffect, useRef, useState } from "react";
import { ShieldCheck, ScrollText, Fingerprint, Sparkles, QrCode, Wallet as WalletIcon, Share2, RotateCw } from "lucide-react";
import { QRCodeSVG } from "qrcode.react";
import { useUserPublicRoles } from "@/hooks/useSovereignAdmin";
import { ROLE_META } from "@/lib/roleMeta";
import { SterkFace } from "./SterkFace";

interface Props {
  displayName: string;
  kurdId: string | null;
  isKycVerified: boolean;
  isConstitutionalSignatory: boolean;
  citizenSince?: string | null;
  /** KEKA reputation score (0–999+) */
  kekaScore?: number;
  /** Tier letter, optional, e.g. "S" / "A" / "B" */
  kekaTier?: string;
  /** Owner's user_id — used to fetch public roles for badges */
  userId?: string | null;
  /** Avatar image URL — placed inside the Stêrk-Face star */
  avatarUrl?: string | null;
}

interface DeviceOrientationEventStatic extends EventTarget {
  requestPermission?: () => Promise<"granted" | "denied">;
}

/**
 * Sovereign 3D ID Card — pure CSS 3D transform with gyroscope + mouse tilt.
 * Cyber-Ancient: Pitch black + Sovereign Gold (#D4AF37) + Cyber Cyan accents.
 */
export function SovereignIdCard({
  displayName,
  kurdId,
  isKycVerified,
  isConstitutionalSignatory,
  citizenSince,
  kekaScore = 0,
  kekaTier,
  userId,
  avatarUrl,
}: Props) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const [tilt, setTilt] = useState({ x: 0, y: 0 });
  const { roles: publicRoles } = useUserPublicRoles(userId ?? null);
  const [needsGyroPermission, setNeedsGyroPermission] = useState(false);
  const [gyroActive, setGyroActive] = useState(false);

  // Detect iOS 13+ DeviceOrientation permission requirement
  useEffect(() => {
    if (typeof window === "undefined") return;
    const Ctor = (window as unknown as { DeviceOrientationEvent?: DeviceOrientationEventStatic })
      .DeviceOrientationEvent;
    if (Ctor && typeof Ctor.requestPermission === "function") {
      setNeedsGyroPermission(true);
    } else if (typeof window !== "undefined" && "DeviceOrientationEvent" in window) {
      attachGyroListener();
      setGyroActive(true);
    }
    return () => {
      window.removeEventListener("deviceorientation", onOrient as EventListener);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onOrient = (e: DeviceOrientationEvent) => {
    const beta = Math.max(-30, Math.min(30, e.beta ?? 0));
    const gamma = Math.max(-30, Math.min(30, e.gamma ?? 0));
    setTilt({ x: -beta * 0.4, y: gamma * 0.7 });
  };

  function attachGyroListener() {
    window.addEventListener("deviceorientation", onOrient as EventListener);
  }

  const requestGyro = async () => {
    const Ctor = (window as unknown as { DeviceOrientationEvent?: DeviceOrientationEventStatic })
      .DeviceOrientationEvent;
    if (!Ctor?.requestPermission) return;
    try {
      const result = await Ctor.requestPermission();
      if (result === "granted") {
        attachGyroListener();
        setGyroActive(true);
        setNeedsGyroPermission(false);
      }
    } catch {
      /* user denied */
    }
  };

  const handleMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (gyroActive) return; // gyroscope wins
    const el = wrapRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const px = (e.clientX - rect.left) / rect.width - 0.5;
    const py = (e.clientY - rect.top) / rect.height - 0.5;
    setTilt({ x: -py * 18, y: px * 22 });
  };
  const handleLeave = () => {
    if (!gyroActive) setTilt({ x: 0, y: 0 });
  };

  const formattedId = kurdId || "PENDING";
  const issued = citizenSince
    ? new Date(citizenSince).toLocaleDateString("en-GB", { month: "short", year: "numeric" })
    : "—";

  // Derive tier from score if not provided
  const computedTier =
    kekaTier ??
    (kekaScore >= 750 ? "S" : kekaScore >= 500 ? "A" : kekaScore >= 250 ? "B" : "C");

  const scoreColor =
    computedTier === "S"
      ? "text-amber-200"
      : computedTier === "A"
        ? "text-amber-300"
        : computedTier === "B"
