/**
 * SovereignSeal — golden +777 stamp animation overlaid on the user's portrait.
 * Plays after every successful login. Pure CSS, no Three.js required.
 */
export function SovereignSeal({ avatarUrl, displayName, onComplete }: Props) {
  const [stamped, setStamped] = useState(false);

  useEffect(() => {
    const t1 = setTimeout(() => setStamped(true), 600);
