/**
 * StarAvatar — Lightweight Stêrk-Face wrapper for high-density UIs.
 *
 * Designed for chat lists, message headers, map pins, provider cards — places
 * where the full SterkFace SVG (with embers, shimmer, name-plate, dual blade
 * rings) would render dozens of times and tank scroll performance.
 *
 * Pure CSS gold star using `clip-path: polygon(...)` for the 21-ray Kurdish
 * star silhouette. Renders in <1ms per instance.
 *
 * Sovereign Gold (#D4AF37) on Pitch Black (#000).
 */
import { memo } from "react";

interface StarAvatarProps {
  src?: string | null;
  name?: string | null;
  /** Outer star size in px. Avatar core auto-scales. Default 52. */
  size?: number;
  /** Online dot in bottom-right. */
  online?: boolean;
  /** Verified seal badge in top-right. */
  sealed?: boolean;
  /** Premium crown indicator. */
  premium?: boolean;
  /** KEKA tier color override: 'gold' | 'cyan' | 'purple' (ghost) | 'amber'. */
  tone?: "gold" | "cyan" | "purple" | "amber";
  className?: string;
  onClick?: () => void;
}

// 21-ray star polygon (clip-path) — alternating outer + inner points
const STAR_POINTS = (() => {
  const rays = 21;
  const cx = 50;
  const cy = 50;
  const outer = 50;
  const inner = 39;
  const pts: string[] = [];
  for (let i = 0; i < rays * 2; i++) {
    const r = i % 2 === 0 ? outer : inner;
    const a = (Math.PI * 2 * i) / (rays * 2) - Math.PI / 2;
    pts.push(`${(cx + Math.cos(a) * r).toFixed(2)}% ${(cy + Math.sin(a) * r).toFixed(2)}%`);
  }
  return pts.join(", ");
})();

const TONE_RING: Record<NonNullable<StarAvatarProps["tone"]>, string> = {
  gold: "linear-gradient(135deg, #FFE9A8 0%, #D4AF37 45%, #8C6A1B 100%)",
  amber: "linear-gradient(135deg, #FFD27A 0%, #D4AF37 50%, #6E4B0E 100%)",
  cyan: "linear-gradient(135deg, #B6FFFF 0%, #00FFFF 45%, #0A6E78 100%)",
  purple: "linear-gradient(135deg, #E2B6FF 0%, #A855F7 45%, #4A2070 100%)",
};

export const StarAvatar = memo(function StarAvatar({
  src,
  name,
  size = 52,
  online,
  sealed,
  premium,
  tone = "gold",
  className = "",
  onClick,
}: StarAvatarProps) {
  // Avatar core ~74% of star outer diameter so the face sits inside the rays
  const coreSize = Math.round(size * 0.74);
  const ringBackground = TONE_RING[tone];
  const initial = (name?.trim()?.[0] ?? "?").toUpperCase();

  return (
    <div
      className={`relative inline-block shrink-0 ${className}`}
      style={{ width: size, height: size }}
      onClick={onClick}
      role={onClick ? "button" : undefined}
    >
      {/* Star silhouette (gold gradient) */}
      <div
        aria-hidden
        className="absolute inset-0"
        style={{
          background: ringBackground,
          clipPath: `polygon(${STAR_POINTS})`,
          WebkitClipPath: `polygon(${STAR_POINTS})`,
          filter: "drop-shadow(0 0 6px rgba(212, 175, 55, 0.45))",
        }}
      />
      {/* Inner core: round avatar locked into the star centre */}
      <div
        className="absolute rounded-full overflow-hidden bg-black border border-amber-200/30"
        style={{
          width: coreSize,
          height: coreSize,
          left: (size - coreSize) / 2,
          top: (size - coreSize) / 2,
          boxShadow: "inset 0 0 0 1px rgba(0,0,0,0.7), 0 1px 4px rgba(0,0,0,0.6)",
        }}
      >
        {src ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={src}
            alt={name ?? ""}
            className="h-full w-full object-cover"
            loading="lazy"
            draggable={false}
          />
        ) : (
          <div
            className="h-full w-full flex items-center justify-center text-amber-200 font-bold"
            style={{ fontSize: coreSize * 0.42, fontFamily: "ui-serif, Georgia, serif" }}
          >
            {initial}
          </div>
        )}
      </div>

      {/* Online dot */}
      {online && (
        <span
          aria-hidden
          className="absolute rounded-full bg-emerald-400 border-2 border-black"
          style={{
            width: size * 0.22,
            height: size * 0.22,
            right: size * 0.04,
            bottom: size * 0.04,
            boxShadow: "0 0 6px rgba(16, 185, 129, 0.7)",
          }}
        />
      )}

      {/* Seal badge */}
      {sealed && (
        <span
          aria-hidden
          className="absolute rounded-full bg-amber-400 border-2 border-black flex items-center justify-center"
          style={{
            width: size * 0.3,
            height: size * 0.3,
            right: -size * 0.04,
            top: -size * 0.04,
            color: "#000",
            fontSize: size * 0.18,
            fontWeight: 900,
            boxShadow: "0 0 8px rgba(212, 175, 55, 0.7)",
          }}
          title="Mühürlü"
        >
          ✦
        </span>
      )}

      {/* Premium crown */}
      {premium && !sealed && (
        <span
          aria-hidden
          className="absolute"
          style={{
            right: -size * 0.04,
            top: -size * 0.06,
            fontSize: size * 0.28,
            filter: "drop-shadow(0 1px 2px rgba(0,0,0,0.7))",
          }}
        >
          👑
        </span>
      )}
    </div>
  );
});

