/**
 * StêrkFace — Sovereign Star-Face identity emblem.
 *
 * 4K, layered Kurdish "Stêrka Geş" (Glowing Star):
 *   • Twin sunburst stars — outer hollow contour ring + inner solid blade ring
 *   • Each blade is a sharp diamond facet with double highlight & shadow edge
 *   • Round avatar locked into the central core, gold rope ring around it
 *   • Warm amber halo + scattered ember sparks drifting in the background
 *   • Floating name plate at the bottom (e.g. "MİKAİL")
 *   • Subtle shimmer animation across the gold blades when KEKA ≥ 4000 (Dîwan)
 *
 * Pure SVG. No external assets. Scales crisply at any size — true 4K vector.
 */
import { useMemo } from "react";

export type SterkRank = "diwan" | "civat" | "egemen" | "restricted";

export interface SterkFaceProps {
  avatarUrl?: string | null;
  displayName?: string | null;
  kekaScore: number;
  /** Optional — when set, takes precedence over `displayName` for the bottom name plate.
   *  Pass the exact text you want shown (e.g. "MİKAİL ŞAHIN"). Up to 18 chars. */
  nameOverride?: string | null;
  kurdId?: string | null;
  size?: number;
  /** Show the floating ID + score aura ring (kept for back-compat; visual is always rich) */
  showAura?: boolean;
  /** Show the bottom "MİKAİL"-style name plate (default true) */
  showNamePlate?: boolean;
  /** Show the embers / spark particles around the star (default true) */
  showEmbers?: boolean;
  /** Halo brightness, 0–1.5. Default 1. Higher = brighter glow on dark backgrounds. */
  haloIntensity?: number;
  /** Ember density, 0–2. Default 1. 0 = none, 2 = ~32 embers. */
  emberDensity?: number;
  /** Avatar core radius in SVG units (out of 100). Default 26. Tweak to fit the face perfectly. */
  coreSize?: number;
  /** Gold rope ring thickness in SVG units. Default 1.6. */
  ringThickness?: number;
  /** Force the shimmer animation regardless of KEKA score. */
  shimmer?: boolean;
  onClick?: () => void;
}

export function rankFromKeka(score: number): SterkRank {
  if (score >= 4000) return "diwan";
  if (score >= 1500) return "civat";
  if (score >= 500) return "egemen";
  return "restricted";
}

interface RankStyle {
  label: string;
  bladeHi: string;
  bladeMid: string;
  bladeLo: string;
  contour: string;
  halo: string;
  ring: string;
  tier: string;
}

const RANK_STYLE: Record<SterkRank, RankStyle> = {
  diwan: {
    label: "Dîwan",
    bladeHi: "#FFF1B5",
    bladeMid: "#E9B949",
    bladeLo: "#7A4A0B",
    contour: "#FFD86A",
    halo: "rgba(255, 184, 64, 0.55)",
    ring: "#1A0E04",
    tier: "S",
  },
  civat: {
    label: "Civat",
    bladeHi: "#FFE69A",
    bladeMid: "#D9A53D",
    bladeLo: "#5E380A",
    contour: "#F0C758",
    halo: "rgba(230, 160, 50, 0.45)",
    ring: "#150A02",
    tier: "A",
  },
  egemen: {
    label: "Egemen",
    bladeHi: "#F4D78A",
    bladeMid: "#B8862E",
    bladeLo: "#3F2606",
    contour: "#C99A36",
    halo: "rgba(180, 120, 40, 0.32)",
    ring: "#100802",
    tier: "B",
  },
  restricted: {
    label: "Sınırlı",
    bladeHi: "#777",
    bladeMid: "#444",
    bladeLo: "#1a1a1a",
    contour: "#3F3F3F",
    halo: "rgba(0,0,0,0)",
    ring: "#0a0a0a",
    tier: "C",
  },
};

interface Blade {
  hi: string;
  lo: string;
  outline: string;
}

/**
 * Build a sunburst of N pointed blades (diamonds). Each blade is split
 * into two triangles — a HI (highlight) face and a LO (shadow) face.
 */
function buildBlades(count: number, innerR: number, outerR: number): Blade[] {
  const cx = 100;
  const cy = 100;
  const half = Math.PI / count;
  return Array.from({ length: count }, (_, i) => {
    const angle = (i / count) * Math.PI * 2 - Math.PI / 2;
    const tipX = cx + Math.cos(angle) * outerR;
    const tipY = cy + Math.sin(angle) * outerR;
    const leftX = cx + Math.cos(angle - half) * innerR;
    const leftY = cy + Math.sin(angle - half) * innerR;
    const rightX = cx + Math.cos(angle + half) * innerR;
    const rightY = cy + Math.sin(angle + half) * innerR;
    const baseX = cx + Math.cos(angle) * innerR * 0.55;
    const baseY = cy + Math.sin(angle) * innerR * 0.55;
    return {
      hi: `M ${baseX.toFixed(2)} ${baseY.toFixed(2)} L ${tipX.toFixed(2)} ${tipY.toFixed(2)} L ${leftX.toFixed(2)} ${leftY.toFixed(2)} Z`,
      lo: `M ${baseX.toFixed(2)} ${baseY.toFixed(2)} L ${tipX.toFixed(2)} ${tipY.toFixed(2)} L ${rightX.toFixed(2)} ${rightY.toFixed(2)} Z`,
      outline: `M ${leftX.toFixed(2)} ${leftY.toFixed(2)} L ${tipX.toFixed(2)} ${tipY.toFixed(2)} L ${rightX.toFixed(2)} ${rightY.toFixed(2)}`,
    };
  });
}

function useBlades(count: number, innerR: number, outerR: number): Blade[] {
  return useMemo(() => buildBlades(count, innerR, outerR), [count, innerR, outerR]);
}

/** Pre-computed ember positions (deterministic — looks scattered, no SSR mismatch). */
const EMBERS_BASE: { x: number; y: number; r: number; o: number }[] = [
  { x: 18, y: 22, r: 1.2, o: 0.9 },
  { x: 32, y: 12, r: 0.8, o: 0.7 },
  { x: 60, y: 8, r: 1.0, o: 0.85 },
  { x: 86, y: 18, r: 1.6, o: 0.95 },
  { x: 168, y: 26, r: 1.1, o: 0.8 },
  { x: 184, y: 64, r: 0.9, o: 0.75 },
  { x: 178, y: 132, r: 1.3, o: 0.88 },
  { x: 162, y: 178, r: 0.9, o: 0.7 },
  { x: 120, y: 188, r: 1.0, o: 0.8 },
  { x: 70, y: 184, r: 0.7, o: 0.65 },
  { x: 28, y: 168, r: 1.2, o: 0.85 },
  { x: 12, y: 116, r: 0.9, o: 0.7 },
  { x: 8, y: 76, r: 1.0, o: 0.75 },
  { x: 50, y: 36, r: 0.5, o: 0.55 },
  { x: 150, y: 44, r: 0.6, o: 0.6 },
  { x: 188, y: 96, r: 0.5, o: 0.55 },
];

/** Extra embers added when density > 1, doubling up the spark count. */
const EMBERS_EXTRA: { x: number; y: number; r: number; o: number }[] = [
  { x: 24, y: 50, r: 0.6, o: 0.6 },
  { x: 44, y: 22, r: 0.7, o: 0.7 },
  { x: 76, y: 24, r: 0.5, o: 0.55 },
  { x: 110, y: 14, r: 0.9, o: 0.75 },
  { x: 140, y: 22, r: 0.6, o: 0.6 },
  { x: 176, y: 50, r: 0.7, o: 0.7 },
  { x: 192, y: 88, r: 0.4, o: 0.5 },
  { x: 188, y: 116, r: 0.7, o: 0.65 },
  { x: 172, y: 152, r: 0.5, o: 0.55 },
  { x: 144, y: 180, r: 0.6, o: 0.65 },
  { x: 96, y: 192, r: 0.5, o: 0.55 },
  { x: 56, y: 176, r: 0.7, o: 0.7 },
  { x: 24, y: 144, r: 0.6, o: 0.6 },
  { x: 14, y: 92, r: 0.7, o: 0.65 },
  { x: 38, y: 60, r: 0.5, o: 0.55 },
  { x: 162, y: 80, r: 0.5, o: 0.55 },
];

function getInitials(name?: string | null): string {
  if (!name) return "·";
  const parts = name.trim().split(/\s+/).slice(0, 2);
  return parts.map((p) => p[0] ?? "").join("").toUpperCase() || "·";
}

function firstName(name?: string | null): string {
  if (!name) return "";
  return name.trim().split(/\s+/)[0]?.toUpperCase() ?? "";
}

/** Trigger a download of a standalone .svg file of the current Stêrk-Face. */
export function downloadSterkFaceSVG(
  props: SterkFaceProps & { fileName?: string },
): void {
  if (typeof document === "undefined") return;
  const svg = renderSterkFaceSVGString(props);
  const blob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = props.fileName ?? `sterk-face-${Date.now()}.svg`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * Render the Stêrk-Face as a self-contained SVG string suitable for
 * downloading or sharing (4K-crisp at any rendered size).
 */
export function renderSterkFaceSVGString(props: SterkFaceProps): string {
  const {
    avatarUrl,
    displayName,
    kekaScore,
    nameOverride,
    showNamePlate = true,
    showEmbers = true,
    haloIntensity = 1,
    emberDensity = 1,
    coreSize = 26,
    ringThickness = 1.6,
    shimmer,
  } = props;
  const rank = rankFromKeka(kekaScore);
  const style = RANK_STYLE[rank];
  const outer = buildBlades(16, 50, 95);
  const inner = buildBlades(16, 38, 74);
  const PHOTO_R = Math.min(40, Math.max(14, coreSize));
  const initials = getInitials(displayName);
  const plateName = (nameOverride ?? firstName(displayName)).slice(0, 18);
  const shimmerOn = shimmer ?? rank === "diwan";
  const embers = [
    ...EMBERS_BASE,
    ...(emberDensity > 1 ? EMBERS_EXTRA : []),
  ].slice(0, Math.round(EMBERS_BASE.length * Math.max(0, Math.min(2, emberDensity))));

  const uid = `sf`;
  const haloOpacityHigh = (0.85 * haloIntensity).toFixed(2);
  const haloOpacityMid = (0.25 * haloIntensity).toFixed(2);

  const bladePaths = (b: Blade, sw: string) =>
    `<path d="${b.hi}" fill="url(#${uid}-hi)"/><path d="${b.lo}" fill="url(#${uid}-lo)"/><path d="${b.outline}" fill="none" stroke="${style.contour}" stroke-width="${sw}" stroke-linejoin="round" stroke-linecap="round" opacity="0.9"/>`;

  const shimmerDef = shimmerOn
    ? `<linearGradient id="${uid}-shimmer" x1="0%" y1="0%" x2="100%" y2="0%">
         <stop offset="0%" stop-color="#FFFFFF" stop-opacity="0"/>
         <stop offset="50%" stop-color="#FFFFFF" stop-opacity="0.55"/>
         <stop offset="100%" stop-color="#FFFFFF" stop-opacity="0"/>
         <animate attributeName="x1" values="-100%;100%" dur="3.6s" repeatCount="indefinite"/>
         <animate attributeName="x2" values="0%;200%" dur="3.6s" repeatCount="indefinite"/>
       </linearGradient>`
    : "";

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" width="1024" height="1024" shape-rendering="geometricPrecision">
  <defs>
    <radialGradient id="${uid}-halo" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="${style.halo}" stop-opacity="${haloOpacityHigh}"/>
      <stop offset="55%" stop-color="${style.halo}" stop-opacity="${haloOpacityMid}"/>
      <stop offset="100%" stop-color="#000" stop-opacity="0"/>
    </radialGradient>
    <linearGradient id="${uid}-hi" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#FFFBE3"/>
      <stop offset="55%" stop-color="${style.bladeHi}"/>
      <stop offset="100%" stop-color="${style.bladeMid}"/>
    </linearGradient>
    <linearGradient id="${uid}-lo" x1="100%" y1="0%" x2="0%" y2="100%">
      <stop offset="0%" stop-color="${style.bladeMid}"/>
      <stop offset="60%" stop-color="${style.bladeLo}"/>
      <stop offset="100%" stop-color="#1a0c02"/>
    </linearGradient>
    <radialGradient id="${uid}-core" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#FFF7C8"/>
      <stop offset="60%" stop-color="${style.bladeMid}" stop-opacity="0.95"/>
      <stop offset="100%" stop-color="${style.bladeLo}" stop-opacity="0.85"/>
    </radialGradient>
    <clipPath id="${uid}-clip"><circle cx="100" cy="100" r="${PHOTO_R}"/></clipPath>
    <linearGradient id="${uid}-plate" x1="0%" y1="0%" x2="0%" y2="100%">
      <stop offset="0%" stop-color="#1a1206"/>
      <stop offset="100%" stop-color="#000"/>
    </linearGradient>
    ${shimmerDef}
  </defs>
  <circle cx="100" cy="100" r="98" fill="url(#${uid}-halo)"/>
  ${
    showEmbers && rank !== "restricted"
      ? `<g>${embers
          .map(
            (e) =>
              `<circle cx="${e.x}" cy="${e.y}" r="${e.r}" fill="#FFB347" opacity="${e.o}"/>`,
          )
          .join("")}</g>`
      : ""
  }
  <g transform="rotate(11.25 100 100)">${outer.map((b) => bladePaths(b, "0.9")).join("")}</g>
  <g>${inner.map((b) => bladePaths(b, "0.55")).join("")}</g>
  ${
    shimmerOn
      ? `<g transform="rotate(11.25 100 100)" opacity="0.85"><circle cx="100" cy="100" r="95" fill="url(#${uid}-shimmer)" style="mix-blend-mode:screen"/></g>`
      : ""
  }
  <circle cx="100" cy="100" r="${PHOTO_R + 6}" fill="url(#${uid}-core)"/>
  <circle cx="100" cy="100" r="${PHOTO_R + 3}" fill="none" stroke="${style.contour}" stroke-width="${ringThickness}"/>
  <circle cx="100" cy="100" r="${PHOTO_R + 1.4}" fill="none" stroke="${style.bladeLo}" stroke-width="${(ringThickness * 0.4).toFixed(2)}" opacity="0.7"/>
  <circle cx="100" cy="100" r="${PHOTO_R}" fill="${style.ring}"/>
  ${
    avatarUrl
      ? `<image href="${avatarUrl}" x="${100 - PHOTO_R}" y="${100 - PHOTO_R}" width="${PHOTO_R * 2}" height="${PHOTO_R * 2}" preserveAspectRatio="xMidYMid slice" clip-path="url(#${uid}-clip)"/>`
      : `<text x="100" y="100" text-anchor="middle" dominant-baseline="central" font-family="ui-sans-serif, system-ui" font-weight="700" font-size="18" fill="${style.contour}">${initials}</text>`
  }
  ${
    showNamePlate && plateName
      ? `<g><rect x="${100 - Math.max(18, plateName.length * 3.6)}" y="132" rx="6" ry="6" width="${Math.max(36, plateName.length * 7.2)}" height="14" fill="url(#${uid}-plate)" stroke="${style.contour}" stroke-width="0.9"/><text x="100" y="139.5" text-anchor="middle" dominant-baseline="central" font-family="ui-sans-serif, system-ui" font-weight="700" font-size="7" letter-spacing="1.2" fill="${style.bladeHi}">${plateName}</text></g>`
      : ""
  }
</svg>`;
}

export function SterkFace({
  avatarUrl,
  displayName,
  kekaScore,
  nameOverride,
  kurdId: _kurdId,
  size = 168,
  showAura: _showAura = true,
  showNamePlate = true,
  showEmbers = true,
  haloIntensity = 1,
  emberDensity = 1,
  coreSize = 26,
  ringThickness = 1.6,
  shimmer,
  onClick,
}: SterkFaceProps) {
  const rank = rankFromKeka(kekaScore);
  const style = RANK_STYLE[rank];

  // Outer (hollow) star — 16 long blades reaching the rim
  const outerBlades = useBlades(16, 50, 95);
  // Inner (solid) star — 16 shorter blades, layered on top
  const innerBlades = useBlades(16, 38, 74);

  const initials = getInitials(displayName);
  const plateName = (nameOverride ?? firstName(displayName)).slice(0, 18);

  const PHOTO_R = Math.min(40, Math.max(14, coreSize));
  const Wrapper = onClick ? "button" : "div";
  const uid = `sf-${rank}`;
  const shimmerOn = (shimmer ?? rank === "diwan") && rank !== "restricted";

  // Embers: density 0..2 → ~0..32 sparks
  const embers = useMemo(() => {
    const d = Math.max(0, Math.min(2, emberDensity));
    const all = [...EMBERS_BASE, ...EMBERS_EXTRA];
    const count = Math.round(EMBERS_BASE.length * d);
    return all.slice(0, count);
  }, [emberDensity]);

  // Halo intensity 0..1.5 — modulates stops + drop-shadow blur
  const halo = Math.max(0, Math.min(1.5, haloIntensity));
  const dropShadow =
    rank === "restricted"
      ? "saturate(0.35) brightness(0.75)"
      : `drop-shadow(0 0 ${(18 * halo).toFixed(0)}px ${style.halo})`;

  return (
    <Wrapper
      onClick={onClick}
      aria-label={
        onClick ? `Sovereign Star-Face — ${style.label} · KEKA ${kekaScore}` : undefined
      }
      className={
        "relative inline-flex items-center justify-center select-none " +
        (onClick ? "active:scale-95 transition-transform" : "")
      }
      style={{ width: size, height: size }}
    >
      <svg
        viewBox="0 0 200 200"
        width={size}
        height={size}
        xmlns="http://www.w3.org/2000/svg"
        shapeRendering="geometricPrecision"
        style={{ filter: dropShadow }}
      >
        <defs>
          <radialGradient id={`${uid}-halo`} cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor={style.halo} stopOpacity={(0.85 * halo).toFixed(2)} />
            <stop offset="55%" stopColor={style.halo} stopOpacity={(0.25 * halo).toFixed(2)} />
            <stop offset="100%" stopColor="#000" stopOpacity="0" />
          </radialGradient>

          <linearGradient id={`${uid}-hi`} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#FFFBE3" />
            <stop offset="55%" stopColor={style.bladeHi} />
            <stop offset="100%" stopColor={style.bladeMid} />
          </linearGradient>

          <linearGradient id={`${uid}-lo`} x1="100%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor={style.bladeMid} />
            <stop offset="60%" stopColor={style.bladeLo} />
            <stop offset="100%" stopColor="#1a0c02" />
          </linearGradient>

          <radialGradient id={`${uid}-core`} cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#FFF7C8" stopOpacity="1" />
            <stop offset="60%" stopColor={style.bladeMid} stopOpacity="0.95" />
            <stop offset="100%" stopColor={style.bladeLo} stopOpacity="0.85" />
          </radialGradient>

          <clipPath id={`${uid}-clip`}>
            <circle cx="100" cy="100" r={PHOTO_R} />
          </clipPath>

          <linearGradient id={`${uid}-plate`} x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#1a1206" />
            <stop offset="100%" stopColor="#000" />
          </linearGradient>

          {/* Animated shimmer band — only mounted when active to keep DOM lean */}
          {shimmerOn && (
            <linearGradient id={`${uid}-shimmer`} x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0" />
              <stop offset="50%" stopColor="#FFFFFF" stopOpacity="0.55" />
              <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0" />
              <animate attributeName="x1" values="-100%;100%" dur="3.6s" repeatCount="indefinite" />
              <animate attributeName="x2" values="0%;200%" dur="3.6s" repeatCount="indefinite" />
            </linearGradient>
          )}
        </defs>

        {/* Soft amber halo behind everything */}
        {rank !== "restricted" && (
          <circle cx="100" cy="100" r="98" fill={`url(#${uid}-halo)`} />
        )}

        {/* Embers / sparks */}
        {showEmbers && rank !== "restricted" && embers.length > 0 && (
          <g>
            {embers.map((e, i) => (
              <circle
                key={i}
                cx={e.x}
                cy={e.y}
                r={e.r}
                fill="#FFB347"
                opacity={e.o}
                style={{ filter: "drop-shadow(0 0 3px rgba(255, 160, 60, 0.95))" }}
              />
            ))}
          </g>
        )}

        {/* OUTER STAR */}
        <g transform="rotate(11.25 100 100)">
          {outerBlades.map((b, i) => (
            <g key={`o-${i}`}>
              <path d={b.hi} fill={`url(#${uid}-hi)`} opacity="0.95" />
              <path d={b.lo} fill={`url(#${uid}-lo)`} opacity="0.95" />
            </g>
          ))}
          {outerBlades.map((b, i) => (
            <path
              key={`oo-${i}`}
              d={b.outline}
              fill="none"
              stroke={style.contour}
              strokeWidth="0.9"
              strokeLinejoin="round"
              strokeLinecap="round"
              opacity="0.95"
            />
          ))}
        </g>

        {/* INNER STAR */}
        <g>
          {innerBlades.map((b, i) => (
            <g key={`i-${i}`}>
              <path d={b.hi} fill={`url(#${uid}-hi)`} />
              <path d={b.lo} fill={`url(#${uid}-lo)`} />
              <path
                d={b.outline}
                fill="none"
                stroke={style.contour}
                strokeWidth="0.55"
                strokeLinejoin="round"
                strokeLinecap="round"
                opacity="0.9"
              />
            </g>
          ))}
        </g>

        {/* Shimmer pass — sweeps a bright band across the gold blades */}
        {shimmerOn && (
          <g transform="rotate(11.25 100 100)" style={{ mixBlendMode: "screen" }} opacity="0.85">
            <circle cx="100" cy="100" r="95" fill={`url(#${uid}-shimmer)`} />
          </g>
        )}

        {/* Bright core disk behind the photo */}
        <circle cx="100" cy="100" r={PHOTO_R + 6} fill={`url(#${uid}-core)`} />

        {/* Gold rope ring around the photo */}
        <circle
          cx="100"
          cy="100"
          r={PHOTO_R + 3}
          fill="none"
          stroke={style.contour}
          strokeWidth={ringThickness}
          opacity="0.95"
        />
        <circle
          cx="100"
          cy="100"
          r={PHOTO_R + 1.4}
          fill="none"
          stroke={style.bladeLo}
          strokeWidth={ringThickness * 0.4}
          opacity="0.7"
        />

        {/* Photo background */}
        <circle cx="100" cy="100" r={PHOTO_R} fill={style.ring} />

        {/* Avatar */}
        {avatarUrl ? (
          <image
            href={avatarUrl}
            x={100 - PHOTO_R}
            y={100 - PHOTO_R}
            width={PHOTO_R * 2}
            height={PHOTO_R * 2}
            preserveAspectRatio="xMidYMid slice"
            clipPath={`url(#${uid}-clip)`}
          />
        ) : (
          <text
            x="100"
            y="100"
            textAnchor="middle"
            dominantBaseline="central"
            fontFamily="ui-sans-serif, system-ui"
            fontWeight="700"
            fontSize="18"
            fill={style.contour}
          >
            {initials}
          </text>
        )}

        {/* Restricted: fracture line */}
        {rank === "restricted" && (
          <line
            x1="74"
            y1="86"
            x2="126"
            y2="114"
            stroke="#0A0805"
            strokeWidth="2"
            strokeDasharray="3 3"
            opacity="0.85"
          />
        )}

        {/* Bottom name plate */}
        {showNamePlate && plateName && (
          <g>
            <rect
              x={100 - Math.max(18, plateName.length * 3.6)}
              y={132}
              rx={6}
              ry={6}
              width={Math.max(36, plateName.length * 7.2)}
              height={14}
              fill={`url(#${uid}-plate)`}
              stroke={style.contour}
              strokeWidth="0.9"
            />
            <text
              x="100"
              y="139.5"
              textAnchor="middle"
              dominantBaseline="central"
              fontFamily="ui-sans-serif, system-ui"
              fontWeight="700"
              fontSize="7"
              letterSpacing="1.2"
              fill={style.bladeHi}
            >
              {plateName}
            </text>
          </g>
        )}
      </svg>
    </Wrapper>
  );
}

