/**
 * TGSheet — Telegram-style mini-app sheet primitive.
 *
 * Davranış:
 *  • Alttan tam ekran (default 100vh) açılır, spring rise.
 *  • Üstten swipe-down ile kapanır (her yerden başlatılabilir; içerik scroll
 *    pozisyonu 0 ise drag, değilse normal scroll).
 *  • 60FPS — translate3d + will-change.
 *  • Heavy frosted backdrop arkayı karartır.
 *  • Header tek satır: drag handle + title + X butonu.
 *  • Altın aksanlar minimum: hairline rim + thin handle.
 *
 * Tüm modal/sheet'ler bu primitive'i kullanmalı.
 */
import { ReactNode, useEffect, useRef, useState } from "react";
import { X } from "lucide-react";
import { hapticTap } from "@/lib/native";

interface Props {
  open: boolean;
  onClose: () => void;
  title?: string;
  /** Sağ üst köşeye ekstra aksiyon (örn. "Kaydet"). */
  headerAction?: ReactNode;
  /** Yarım sheet için 0.6–0.95 arası viewport oranı. Default: 1 (tam ekran). */
  height?: number;
  /** false → header gizlenir (özel çağrı/medya overlay'leri için). */
  showHeader?: boolean;
  /**
   * Drag ilerlemesi (0 = sheet üstte, 1 = tamamen kapanıyor). Parent'ın
   * "shrink back to icon" gibi eşzamanlı animasyonlar yapmasına izin verir
   * (iOS Springboard tarzı geri-zoom efekti).
   */
  onDragProgress?: (p: number) => void;
  children: ReactNode;
}

const SPRING = "transform 360ms cubic-bezier(0.22, 1.2, 0.36, 1)";

export function TGSheet({
  open,
  onClose,
  title,
  headerAction,
  height = 1,
  showHeader = true,
  onDragProgress,
  children,
}: Props) {
  const sheetRef = useRef<HTMLDivElement | null>(null);
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const [drag, setDrag] = useState(0);
  const [closing, setClosing] = useState(false);
  const startY = useRef<number | null>(null);
  const lastY = useRef(0);
  const lastT = useRef(0);
  const draggingRef = useRef(false);
  /** Drag yalnızca scroll = 0 iken başlar, böylece içerik kaydırması bozulmaz. */
  const allowDragRef = useRef(true);

  useEffect(() => {
    if (!open) return;
    setDrag(0);
    setClosing(false);
    const onEsc = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    document.addEventListener("keydown", onEsc);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onEsc);
      document.body.style.overflow = prev;
    };
  }, [open, onClose]);

  if (!open && !closing) return null;

  const close = () => {
    if (closing) return;
    setClosing(true);
    hapticTap();
    const el = sheetRef.current;
    if (el) {
      el.style.transition = "transform 240ms cubic-bezier(0.32,0.72,0,1), opacity 240ms";
      el.style.transform = "translate3d(0, 100%, 0)";
      el.style.opacity = "0.7";
    }
    window.setTimeout(() => {
      setClosing(false);
      setDrag(0);
      onClose();
    }, 250);
  };

  const onTouchStart = (e: React.TouchEvent) => {
    const sc = scrollRef.current;
    allowDragRef.current = !sc || sc.scrollTop <= 0;
    if (!allowDragRef.current) return;
    startY.current = e.touches[0].clientY;
    lastY.current = startY.current;
    lastT.current = performance.now();
    draggingRef.current = true;
  };
  const onTouchMove = (e: React.TouchEvent) => {
    if (!draggingRef.current || startY.current == null) return;
    const y = e.touches[0].clientY;
    const dy = Math.max(0, y - startY.current);
    setDrag(dy);
    lastY.current = y;
    lastT.current = performance.now();
    if (onDragProgress) {
      const p = Math.min(1, dy / (typeof window !== "undefined" ? window.innerHeight : 800));
      onDragProgress(p);
    }
  };
  const onTouchEnd = () => {
    if (!draggingRef.current) return;
    draggingRef.current = false;
    startY.current = null;
    const elapsed = performance.now() - lastT.current;
    const velocity = elapsed > 0 ? drag / Math.max(elapsed, 1) : 0;
    if (drag > 130 || velocity > 0.55) {
      close();
    } else {
      setDrag(0);
      onDragProgress?.(0);
    }
  };

  const sheetVH = Math.round(height * 100);
  const isFull = height >= 0.99;

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={title}
      className="fixed inset-0 z-[1000] flex items-end justify-center"
    >
      {/* Backdrop — opacity follows drag for parallax feel */}
      <button
        type="button"
        aria-label="Kapat"
        onClick={close}
        className="absolute inset-0"
        style={{
          background: "rgba(0,0,0,0.62)",
          backdropFilter: "blur(18px) saturate(140%)",
          WebkitBackdropFilter: "blur(18px) saturate(140%)",
          opacity: Math.max(0.35, 1 - drag / 600),
          animation: "fade-in 200ms ease-out both",
        }}
      />

      {/* Sheet */}
      <div
        ref={sheetRef}
        className="relative w-full max-w-[520px] flex flex-col will-change-transform"
        style={{
          height: `${sheetVH}vh`,
          borderTopLeftRadius: isFull ? 16 : 28,
          borderTopRightRadius: isFull ? 16 : 28,
          background:
            "linear-gradient(180deg, rgba(18,14,4,0.985) 0%, rgba(4,3,0,0.99) 100%)",
          border: "1px solid rgba(212,175,55,0.22)",
          borderBottom: "none",
          boxShadow:
            "0 -24px 60px -8px rgba(0,0,0,0.92), inset 0 1px 0 rgba(253,230,138,0.15)",
          transform: `translate3d(0, ${drag}px, 0)`,
          transition: draggingRef.current ? "none" : SPRING,
          animation:
            drag === 0 && !draggingRef.current && !closing
              ? "tgsheet-rise 380ms cubic-bezier(0.22,1.2,0.36,1) both"
              : undefined,
          paddingBottom: "env(safe-area-inset-bottom, 0px)",
        }}
      >
        <style>{`
          @keyframes tgsheet-rise {
            from { transform: translate3d(0, 100%, 0); }
            to   { transform: translate3d(0, 0, 0); }
          }
        `}</style>

        {/* Drag-grip strip — touch listeners cover the WHOLE header area too */}
        <div
          onTouchStart={onTouchStart}
          onTouchMove={onTouchMove}
          onTouchEnd={onTouchEnd}
          onTouchCancel={onTouchEnd}
          className="shrink-0"
        >
          <div className="pt-2.5 pb-1.5 flex items-center justify-center">
            <div
              className="h-[5px] w-10 rounded-full"
              style={{ background: "rgba(255,236,180,0.45)" }}
            />
          </div>

          {showHeader && (title || headerAction) && (
            <div className="px-4 pb-3 flex items-center justify-between gap-3">
              <div className="min-w-0 flex-1">
                {title && (
                  <h2
                    className="text-[17px] font-semibold tracking-tight truncate"
                    style={{ color: "#FFE9A8" }}
                  >
                    {title}
                  </h2>
                )}
              </div>
              <div className="flex items-center gap-2 shrink-0">
                {headerAction}
                <button
                  type="button"
                  onClick={close}
                  aria-label="Kapat"
                  className="h-8 w-8 rounded-full flex items-center justify-center active:scale-95"
                  style={{
                    background: "rgba(255,255,255,0.06)",
                    border: "1px solid rgba(212,175,55,0.22)",
                  }}
                >
                  <X className="h-4 w-4" style={{ color: "#FDE68A" }} />
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Scrollable body. Native scroll always works here — drag-to-close
            is only available from the top grip strip above. This guarantees
            long pages (Linguist, settings, etc.) never get stuck. */}
        <div
          ref={scrollRef}
          className="flex-1 overflow-y-auto overscroll-contain"
          style={{ WebkitOverflowScrolling: "touch", touchAction: "pan-y" }}
        >
          {children}
        </div>
      </div>
    </div>
  );
}

import { useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { Copy, Eye, EyeOff, ShieldCheck, AlertTriangle, Check } from "lucide-react";
import { generateSeedPhrase } from "@/lib/sovereignCrypto";
import { useSovereignRecovery } from "@/hooks/useSovereignRecovery";
import { toast } from "sonner";

type Step = "intro" | "reveal" | "verify" | "done";

interface Props {
  onComplete?: () => void;
  onCancel?: () => void;
}

/**
 * Yaşam Anahtarı (24-word recovery phrase) onboarding flow.
 * Apple-style minimalist gold-on-black.
 */
export function YasamAnahtari({ onComplete, onCancel }: Props) {
  const { savePhrase } = useSovereignRecovery();
  const [step, setStep] = useState<Step>("intro");
  const [words, setWords] = useState<string[]>([]);
  const [hidden, setHidden] = useState(true);
  const [saving, setSaving] = useState(false);

  // Pick 3 random word positions to verify
  const verifyIndexes = useMemo(() => {
    if (words.length === 0) return [];
    const all = [...Array(24).keys()];
    const out: number[] = [];
    for (let i = 0; i < 3; i++) {
      const k = Math.floor(Math.random() * all.length);
      out.push(all.splice(k, 1)[0]);
    }
    return out.sort((a, b) => a - b);
  }, [words]);

  const [answers, setAnswers] = useState<Record<number, string>>({});
  const [attempts, setAttempts] = useState(0);
  const [verifyError, setVerifyError] = useState<string | null>(null);

  const start = () => {
    setWords(generateSeedPhrase());
    setStep("reveal");
    setAttempts(0);
    setAnswers({});
    setVerifyError(null);
  };

  // Per-word live status: matched / wrong / empty
  const wordStatus = (idx: number): "match" | "wrong" | "empty" => {
    const v = (answers[idx] ?? "").trim().toLowerCase();
    if (!v) return "empty";
    return v === words[idx] ? "match" : "wrong";
  };
  const allMatched = verifyIndexes.length > 0 && verifyIndexes.every((i) => wordStatus(i) === "match");

  const copyAll = async () => {
    try {
      await navigator.clipboard.writeText(words.join(" "));
      toast.success("Panoya kopyalandı");
    } catch {
      toast.error("Kopyalanamadı");
    }
  };

  const submitVerification = async () => {
    setVerifyError(null);
    const wrong = verifyIndexes.filter((idx) => wordStatus(idx) !== "match");
    if (wrong.length > 0) {
      const next = attempts + 1;
      setAttempts(next);
      const positions = wrong.map((i) => `#${(i + 1).toString().padStart(2, "0")}`).join(", ");
      setVerifyError(
        `${wrong.length} kelime eşleşmedi (${positions}). Büyük/küçük harf ve yazım hatalarını kontrol et.`,
      );
      toast.error("Kelimeler eşleşmedi");
      return;
    }
    setSaving(true);
    const ok = await savePhrase(words);
    setSaving(false);
    if (ok) {
      setStep("done");
      setTimeout(() => onComplete?.(), 1500);
    }
  };

  // ---------- INTRO -------------------------------------------------------
  if (step === "intro") {
    return (
      <div className="space-y-6 text-center">
        <div className="mx-auto w-20 h-20 rounded-full bg-gradient-to-br from-amber-400/20 to-amber-600/20 border border-amber-400/40 flex items-center justify-center">
          <ShieldCheck className="w-10 h-10 text-amber-300" />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-amber-100">Yaşam Anahtarı</h2>
          <p className="text-sm text-amber-200/60 mt-2 max-w-sm mx-auto leading-relaxed">
            24 kelimelik egemen kurtarma anahtarın. Telefonunu kaybedersen +777 kimliğini sadece
            bu kelimelerle geri kazanabilirsin.
          </p>
        </div>
        <div className="bg-amber-500/5 border border-amber-400/20 rounded-2xl p-4 text-left text-xs text-amber-200/70 space-y-2">
          <div className="flex gap-2"><AlertTriangle className="w-4 h-4 text-amber-300 shrink-0" /><span>Kelimeler <b className="text-amber-100">asla</b> sunucuya gönderilmez. Yalnızca SHA-256 özet (hash) saklanır.</span></div>
          <div className="flex gap-2"><AlertTriangle className="w-4 h-4 text-amber-300 shrink-0" /><span>Kelimeleri <b className="text-amber-100">kaybedersen kurtarma yoktur</b>. Güvenli bir yere yaz.</span></div>
        </div>
        <div className="flex gap-3">
          {onCancel && (
            <Button variant="outline" className="flex-1 border-amber-400/30" onClick={onCancel}>
              Sonra
            </Button>
          )}
          <Button onClick={start} className="flex-1 bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold hover:opacity-90">
            Anahtarı Üret
          </Button>
        </div>
      </div>
    );
  }

  // ---------- REVEAL -------------------------------------------------------
  if (step === "reveal") {
    return (
      <div className="space-y-5">
        <div className="text-center">
          <h2 className="text-xl font-bold text-amber-100">Yaşam Anahtarın</h2>
          <p className="text-xs text-amber-200/60 mt-1">Bu 24 kelimeyi sırasıyla yaz, kimseyle paylaşma.</p>
        </div>

        <div className="grid grid-cols-3 gap-2 bg-black/40 border border-amber-400/20 rounded-2xl p-3">
          {words.map((w, i) => (
            <div key={i} className="bg-gradient-to-br from-amber-500/10 to-amber-600/5 border border-amber-400/20 rounded-lg px-2 py-2 text-center">
              <div className="text-[9px] text-amber-300/60 font-mono">{(i + 1).toString().padStart(2, "0")}</div>
              <div className="text-xs font-semibold text-amber-100 font-mono tabular-nums">
                {hidden ? "•••••" : w}
              </div>
            </div>
          ))}
        </div>

        <div className="flex gap-2">
          <Button variant="outline" size="sm" className="flex-1 border-amber-400/30" onClick={() => setHidden((v) => !v)}>
            {hidden ? <><Eye className="w-4 h-4 mr-1.5" />Göster</> : <><EyeOff className="w-4 h-4 mr-1.5" />Gizle</>}
          </Button>
          <Button variant="outline" size="sm" className="flex-1 border-amber-400/30" onClick={copyAll} disabled={hidden}>
            <Copy className="w-4 h-4 mr-1.5" />Kopyala
          </Button>
        </div>

        <Button
          onClick={() => setStep("verify")}
          disabled={hidden}
          className="w-full bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold hover:opacity-90"
        >
          Kelimeleri Yazdım, Devam Et
        </Button>
      </div>
    );
  }

  // ---------- VERIFY -------------------------------------------------------
  if (step === "verify") {
    return (
      <div className="space-y-5">
        <div className="text-center">
          <h2 className="text-xl font-bold text-amber-100">Doğrulama</h2>
          <p className="text-xs text-amber-200/60 mt-1">
            Kaydettiğinden emin olmak için aşağıdaki 3 kelimeyi sırasıyla gir.
          </p>
          {attempts > 0 && (
            <p className="mt-1 text-[10px] text-amber-300/70 font-mono">
              Deneme: {attempts}
            </p>
          )}
        </div>

        <div className="space-y-3">
          {verifyIndexes.map((idx) => {
            const status = wordStatus(idx);
            const borderClass =
              status === "match"
                ? "border-emerald-400/60 focus:border-emerald-300"
                : status === "wrong"
                  ? "border-rose-500/60 focus:border-rose-400"
                  : "border-amber-400/30 focus:border-amber-300";
            return (
              <div key={idx}>
                <label className="text-[10px] uppercase tracking-wider text-amber-300/70 font-mono flex items-center justify-between">
                  <span>{(idx + 1).toString().padStart(2, "0")}. kelime</span>
                  {status === "match" && (
                    <span className="flex items-center gap-1 text-emerald-300 normal-case tracking-normal">
                      <Check className="w-3 h-3" /> doğru
                    </span>
                  )}
                  {status === "wrong" && (
                    <span className="text-rose-300 normal-case tracking-normal">eşleşmiyor</span>
                  )}
                </label>
                <div className="relative">
                  <input
                    type="text"
                    value={answers[idx] ?? ""}
                    onChange={(e) => {
                      setAnswers((s) => ({ ...s, [idx]: e.target.value }));
                      if (verifyError) setVerifyError(null);
                    }}
                    className={`w-full mt-1 bg-black/40 border rounded-lg px-3 py-2 pr-9 text-amber-100 text-sm focus:outline-none transition-colors ${borderClass}`}
                    autoComplete="off"
                    spellCheck={false}
                    autoCapitalize="none"
                  />
                  {status === "match" && (
                    <Check className="absolute right-2.5 top-1/2 mt-[2px] -translate-y-1/2 w-4 h-4 text-emerald-300" />
                  )}
                  {status === "wrong" && (
                    <AlertTriangle className="absolute right-2.5 top-1/2 mt-[2px] -translate-y-1/2 w-4 h-4 text-rose-400" />
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {verifyError && (
          <div className="flex items-start gap-2 rounded-xl border border-rose-500/40 bg-rose-500/10 p-3 text-[11px] text-rose-200">
            <AlertTriangle className="w-4 h-4 text-rose-300 shrink-0 mt-0.5" />
            <div className="space-y-1">
              <div className="font-semibold">{verifyError}</div>
              {attempts >= 2 && (
                <button
                  onClick={() => setStep("reveal")}
                  className="underline text-rose-100 hover:text-white"
                >
                  Kelimeleri tekrar göster
                </button>
              )}
            </div>
          </div>
        )}

        {allMatched && !verifyError && (
          <div className="flex items-center gap-2 rounded-xl border border-emerald-400/40 bg-emerald-500/10 p-2.5 text-[11px] text-emerald-200">
            <Check className="w-4 h-4 text-emerald-300" />
            <span>Tüm kelimeler doğru — anahtarı mühürlemeye hazırsın.</span>
          </div>
        )}

        <div className="flex gap-2">
          <Button variant="outline" className="flex-1 border-amber-400/30" onClick={() => setStep("reveal")}>
            Geri
          </Button>
          <Button
            onClick={submitVerification}
            disabled={saving || verifyIndexes.some((i) => !(answers[i] ?? "").trim())}
            className="flex-1 bg-gradient-to-r from-amber-400 to-amber-600 text-black font-semibold hover:opacity-90"
          >
            {saving ? "Mühürleniyor..." : "Doğrula & Kaydet"}
          </Button>
        </div>
      </div>
    );
  }

  // ---------- DONE ---------------------------------------------------------
  return (
    <div className="text-center space-y-4 py-6">
      <div className="mx-auto w-20 h-20 rounded-full bg-gradient-to-br from-amber-400 to-amber-600 flex items-center justify-center animate-[seal-pop_0.6s_ease-out]">
        <Check className="w-10 h-10 text-black" />
      </div>
      <div>
        <h2 className="text-xl font-bold text-amber-100">Mühürlendi</h2>
        <p className="text-xs text-amber-200/60 mt-1">Yaşam Anahtarın güvenli — sadece sen biliyorsun.</p>
      </div>
    </div>
  );
}

