import * as React from "react";
import { cn } from "@/lib/utils";

interface SterkAppIcon {
  id: string;
  label: string;
  emoji: string;
  onOpen: () => void;
  /** Optional gradient classes for the icon tile. */
  gradient?: string;
}

interface FloatingPillDockProps {
  apps: SterkAppIcon[];
  /** Allowed pool to swap from when in jiggle mode. */
  pool?: SterkAppIcon[];
  storageKey?: string;
}

/**
 * iOS 18 Floating Glass Dock — fully detached from bottom & sides,
 * intense backdrop blur, soft top sheen, soft bottom shadow.
 *
 *  - Long-press (550ms) any icon → enters Jiggle Mode.
 *  - In Jiggle Mode, tapping an icon cycles it through the available pool.
 *  - Tap outside or press Done to leave.
 *  - Selection persisted in localStorage under `storageKey`.
 */
export function FloatingPillDock({
  apps,
  pool = [],
  storageKey = "sterk:dock",
}: FloatingPillDockProps) {
  const [jiggle, setJiggle] = React.useState(false);
  const [order, setOrder] = React.useState<string[]>(() => {
    try {
      const raw = localStorage.getItem(storageKey);
      if (raw) return JSON.parse(raw);
    } catch {}
    return apps.map((a) => a.id);
  });

  const all = React.useMemo(() => {
    const map = new Map<string, SterkAppIcon>();
    [...apps, ...pool].forEach((a) => map.set(a.id, a));
    return map;
  }, [apps, pool]);

  const visible = order.map((id) => all.get(id)).filter(Boolean) as SterkAppIcon[];

  React.useEffect(() => {
    try {
      localStorage.setItem(storageKey, JSON.stringify(order));
    } catch {}
  }, [order, storageKey]);

  const pressTimer = React.useRef<number | null>(null);
  const startPress = () => {
    pressTimer.current = window.setTimeout(() => setJiggle(true), 550);
  };
  const cancelPress = () => {
    if (pressTimer.current) {
      window.clearTimeout(pressTimer.current);
      pressTimer.current = null;
    }
  };

  const cycleSlot = (slotIndex: number) => {
    if (!jiggle) return;
    const currentId = order[slotIndex];
    const candidates = [...apps, ...pool]
      .map((a) => a.id)
      .filter((id) => id === currentId || !order.includes(id));
    const idx = candidates.indexOf(currentId);
    const next = candidates[(idx + 1) % candidates.length];
    if (next && next !== currentId) {
      const newOrder = [...order];
      newOrder[slotIndex] = next;
      setOrder(newOrder);
    }
  };

  return (
    <>
      {jiggle && (
        <button
          aria-label="Done customizing"
          onClick={() => setJiggle(false)}
          className="fixed inset-0 z-40 bg-black/40 backdrop-blur-[2px]"
        />
      )}
      <div
        className={cn(
          "fixed left-1/2 z-50 -translate-x-1/2",
          // Detached from bottom (true iOS 18 floating dock)
          "bottom-[calc(env(safe-area-inset-bottom,0px)+22px)]",
          "flex items-center gap-2 rounded-[32px] px-3 py-2.5",
          // Heavy translucent glass
          "border border-white/15",
          "bg-white/10 dark:bg-white/[0.07]",
          "backdrop-blur-[40px] backdrop-saturate-150",
          "shadow-[0_24px_60px_-20px_rgba(0,0,0,0.75),inset_0_1px_0_rgba(255,255,255,0.22),inset_0_-1px_0_rgba(0,0,0,0.35)]",
        )}
      >
        {visible.map((app, i) => (
          <button
            key={app.id + i}
            onMouseDown={startPress}
            onMouseUp={cancelPress}
            onMouseLeave={cancelPress}
            onTouchStart={startPress}
            onTouchEnd={cancelPress}
            onClick={(e) => {
              e.stopPropagation();
              if (jiggle) cycleSlot(i);
              else app.onOpen();
            }}
            className={cn(
              "relative grid h-14 w-14 place-items-center rounded-[18px] text-[28px] leading-none",
              "bg-gradient-to-b from-white/15 to-white/[0.04]",
              "border border-white/10",
              "shadow-[0_10px_18px_-10px_rgba(0,0,0,0.85),inset_0_1px_0_rgba(255,255,255,0.3)]",
              "transition-transform active:scale-95",
              app.gradient,
              jiggle && "animate-[jiggle_0.35s_ease-in-out_infinite]",
            )}
            style={{
              animationDelay: jiggle ? `${(i % 2) * -0.12}s` : undefined,
            }}
            aria-label={app.label}
          >
            <span className="drop-shadow-[0_2px_4px_rgba(0,0,0,0.6)]">{app.emoji}</span>
            {jiggle && (
              <span className="absolute -right-1 -top-1 grid h-5 w-5 place-items-center rounded-full bg-white text-[11px] font-bold text-black shadow">
                ↻
              </span>
            )}
          </button>
        ))}
      </div>
      <style>{`
        @keyframes jiggle {
          0%   { transform: rotate(-2deg) translateY(0); }
          50%  { transform: rotate(2deg) translateY(-1px); }
          100% { transform: rotate(-2deg) translateY(0); }
        }
      `}</style>
    </>
  );
}

