import * as React from "react";
import { cn } from "@/lib/utils";

interface GlassBubbleProps {
  side: "user" | "deng";
  children: React.ReactNode;
  className?: string;
}

/**
 * 3D theme-aware glass bubble.
 * Both sides use neutral white-glass tints so the bubble adapts to whatever
 * theme the page is currently using (no hardcoded amber/yellow).
 */
export function GlassBubble({ side, children, className }: GlassBubbleProps) {
  const ref = React.useRef<HTMLDivElement>(null);

  const onMove = (e: React.MouseEvent) => {
    const el = ref.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width - 0.5;
    const y = (e.clientY - r.top) / r.height - 0.5;
    el.style.setProperty("--rx", `${(-y * 6).toFixed(2)}deg`);
    el.style.setProperty("--ry", `${(x * 8).toFixed(2)}deg`);
    el.style.setProperty("--mx", `${((x + 0.5) * 100).toFixed(1)}%`);
    el.style.setProperty("--my", `${((y + 0.5) * 100).toFixed(1)}%`);
  };
  const onLeave = () => {
    const el = ref.current;
    if (!el) return;
    el.style.setProperty("--rx", "0deg");
    el.style.setProperty("--ry", "0deg");
  };

  const isUser = side === "user";
  return (
    <div
      className={cn("flex w-full", isUser ? "justify-end" : "justify-start")}
      style={{ perspective: "800px" }}
    >
      <div
        ref={ref}
        onMouseMove={onMove}
        onMouseLeave={onLeave}
        className={cn(
          "relative max-w-[82%] rounded-3xl px-4 py-3 text-sm leading-relaxed",
          "border border-white/15 backdrop-blur-2xl",
          "transition-transform duration-200 will-change-transform",
          isUser
            ? // User bubble — uses primary tint
              "bg-primary/15 text-foreground"
            : // Deng bubble — neutral glass, theme-agnostic
              "bg-white/[0.06] text-foreground",
          "shadow-[0_15px_30px_-15px_rgba(0,0,0,0.6),inset_0_1px_0_rgba(255,255,255,0.22)]",
          className,
        )}
        style={{
          transform: "rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg))",
        }}
      >
        <span
          className="pointer-events-none absolute inset-0 rounded-3xl opacity-60"
          style={{
            background:
              "radial-gradient(circle at var(--mx,30%) var(--my,20%), rgba(255,255,255,0.30), transparent 45%)",
          }}
        />
        <span className="relative z-[1] whitespace-pre-wrap">{children}</span>
      </div>
    </div>
  );
}

