interface GoldenWaveProps {
  /** Whether audio is currently playing — drives animation. */
  active: boolean;
  className?: string;
  bars?: number;
}

/**
 * 3D golden sound waves. Pure CSS bars with staggered animation, layered
 * with two soft golden glows to fake depth. Pulses only when `active`.
 */
export function GoldenWave({ active, className, bars = 28 }: GoldenWaveProps) {
  return (
    <div
      className={cn(
        "relative mx-auto flex h-32 w-full max-w-md items-center justify-center gap-[3px]",
        className,
      )}
      aria-hidden
    >
      {/* Back glow */}
      <div
        className={cn(
          "pointer-events-none absolute inset-0 rounded-full blur-3xl transition-opacity duration-500",
          active ? "opacity-80" : "opacity-25",
        )}
        style={{
          background:
            "radial-gradient(ellipse at center, rgba(255,200,80,0.55), transparent 60%)",
        }}
      />
      {/* Mirror floor reflection */}
      <div
        className="pointer-events-none absolute inset-x-0 bottom-0 h-1/2 opacity-30"
        style={{
          background:
            "linear-gradient(to top, rgba(255,180,60,0.25), transparent)",
          maskImage: "linear-gradient(to top, black, transparent)",
        }}
      />
      {Array.from({ length: bars }).map((_, i) => {
        const center = bars / 2;
        const dist = Math.abs(i - center) / center; // 0 → 1
        const baseHeight = 18 + (1 - dist) * 60;
        return (
          <span
            key={i}
            className={cn(
              "block w-[4px] rounded-full",
              "bg-gradient-to-t from-[#7a4a00] via-[#f5c560] to-[#fff3c0]",
              "shadow-[0_0_8px_rgba(255,200,80,0.7),inset_0_0_2px_rgba(255,255,255,0.6)]",
              active && "animate-[wave_1.1s_ease-in-out_infinite]",
            )}
            style={{
              height: `${baseHeight}%`,
              animationDelay: `${i * 60}ms`,
              transformOrigin: "center",
            }}
          />
        );
      })}
      <style>{`
        @keyframes wave {
          0%, 100% { transform: scaleY(0.4); }
          50%      { transform: scaleY(1.0); }
        }
      `}</style>
    </div>
  );
}

