import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { toast } from "sonner";
import { Check } from "lucide-react";

interface Story {
  id: string;
  media_url: string;
  media_type: string;
}

export function AddToHighlightDialog({ userId, onClose }: { userId: string; onClose: () => void }) {
  const [stories, setStories] = useState<Story[]>([]);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [title, setTitle] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    // Get all of user's stories (including expired ones for highlighting)
    supabase
      .from("stories")
      .select("id, media_url, media_type")
      .eq("user_id", userId)
      .order("created_at", { ascending: false })
      .limit(50)
      .then(({ data }) => setStories((data as Story[]) || []));
  }, [userId]);

  const toggle = (id: string) => {
    const next = new Set(selected);
    next.has(id) ? next.delete(id) : next.add(id);
    setSelected(next);
  };

  const save = async () => {
    if (!title.trim()) { toast.error("Bir başlık ver"); return; }
    if (selected.size === 0) { toast.error("En az bir story seç"); return; }
    setSaving(true);
    const ids = Array.from(selected);
    const cover = stories.find((s) => s.id === ids[0])?.media_url || null;
    const { error } = await supabase.from("story_highlights").insert({
      user_id: userId,
      title: title.trim(),
      cover_url: cover,
      story_ids: ids,
    });
    setSaving(false);
    if (error) { toast.error("Kaydedilemedi"); return; }
    toast.success("Highlight oluşturuldu");
    onClose();
  };

  return (
    <Dialog open onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Yeni Highlight</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <Input
            placeholder="Başlık (örn: Seyahat, Aile)"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            maxLength={20}
          />
          {stories.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-8">
              Henüz hikayen yok. Önce bir hikaye paylaş.
            </p>
          ) : (
            <div className="grid grid-cols-3 gap-2 max-h-[300px] overflow-y-auto">
              {stories.map((s) => {
                const sel = selected.has(s.id);
                return (
                  <button
                    key={s.id}
                    onClick={() => toggle(s.id)}
                    className={`relative aspect-[3/4] rounded-lg overflow-hidden border-2 transition ${sel ? "border-primary" : "border-transparent"}`}
                  >
                    {s.media_type === "video" ? (
                      <video src={s.media_url} className="h-full w-full object-cover" />
                    ) : (
                      <img src={s.media_url} alt="" className="h-full w-full object-cover" />
                    )}
                    {sel && (
                      <div className="absolute inset-0 bg-primary/40 flex items-center justify-center">
                        <div className="h-7 w-7 rounded-full bg-primary flex items-center justify-center">
                          <Check className="h-4 w-4 text-primary-foreground" />
                        </div>
                      </div>
                    )}
                  </button>
                );
              })}
            </div>
          )}
          <div className="flex gap-2">
            <Button variant="ghost" className="flex-1" onClick={onClose}>İptal</Button>
            <Button variant="neon" className="flex-1" onClick={save} disabled={saving}>
              {saving ? "Kaydediliyor..." : `Kaydet (${selected.size})`}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

