import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { X, Trash2, ChevronLeft, ChevronRight } from "lucide-react";
import { toast } from "sonner";

interface Highlight {
  id: string;
  title: string;
  story_ids: string[];
}
interface Story {
  id: string;
  media_url: string;
  media_type: string;
  caption: string | null;
}

export function HighlightViewer({ highlight, isOwner, onClose }: { highlight: Highlight; isOwner: boolean; onClose: () => void }) {
  const [stories, setStories] = useState<Story[]>([]);
  const [idx, setIdx] = useState(0);

  useEffect(() => {
    if (highlight.story_ids.length === 0) return;
    supabase
      .from("stories")
      .select("id, media_url, media_type, caption")
      .in("id", highlight.story_ids)
      .then(({ data }) => {
        const ordered = highlight.story_ids
          .map((id) => (data as Story[] | null)?.find((s) => s.id === id))
          .filter(Boolean) as Story[];
        setStories(ordered);
      });
  }, [highlight]);

  const remove = async () => {
    if (!confirm(`"${highlight.title}" silinsin mi?`)) return;
    const { error } = await supabase.from("story_highlights").delete().eq("id", highlight.id);
    if (error) { toast.error("Silinemedi"); return; }
    toast.success("Silindi");
    onClose();
  };

  const current = stories[idx];

  return (
    <div className="fixed inset-0 z-[100] bg-black flex items-center justify-center">
      <button onClick={onClose} className="absolute top-4 right-4 z-10 h-9 w-9 rounded-full bg-black/50 flex items-center justify-center text-white">
        <X className="h-5 w-5" />
      </button>
      {isOwner && (
        <button onClick={remove} className="absolute top-4 left-4 z-10 h-9 w-9 rounded-full bg-black/50 flex items-center justify-center text-red-400">
          <Trash2 className="h-4 w-4" />
        </button>
      )}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 z-10 text-white text-sm font-medium">
        {highlight.title} • {idx + 1}/{stories.length}
      </div>

      {stories.length > 0 && current && (
        <div className="relative w-full h-full flex items-center justify-center">
          {current.media_type === "video" ? (
            <video src={current.media_url} controls autoPlay className="max-h-full max-w-full" />
          ) : (
            <img src={current.media_url} alt="" className="max-h-full max-w-full object-contain" />
          )}
          {current.caption && (
            <div className="absolute bottom-20 left-0 right-0 text-center text-white text-sm px-6 bg-gradient-to-t from-black/80 to-transparent py-4">
              {current.caption}
            </div>
          )}
          {idx > 0 && (
            <button onClick={() => setIdx(i => i - 1)} className="absolute left-4 top-1/2 -translate-y-1/2 h-10 w-10 rounded-full bg-black/40 flex items-center justify-center text-white">
              <ChevronLeft className="h-5 w-5" />
            </button>
          )}
          {idx < stories.length - 1 && (
            <button onClick={() => setIdx(i => i + 1)} className="absolute right-4 top-1/2 -translate-y-1/2 h-10 w-10 rounded-full bg-black/40 flex items-center justify-center text-white">
              <ChevronRight className="h-5 w-5" />
            </button>
          )}
        </div>
      )}

      {stories.length === 0 && (
        <p className="text-white/70">Yükleniyor...</p>
      )}
    </div>
  );
}

