import { useState, useRef } from "react";
import { X, Send, ImagePlus, Film, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";

interface StoryCreatorProps {
  onSubmit: (file: File, caption?: string) => Promise<void>;
  onClose: () => void;
}

export function StoryCreator({ onSubmit, onClose }: StoryCreatorProps) {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [caption, setCaption] = useState("");
  const [uploading, setUploading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (!f) return;

    // 20MB limit
    if (f.size > 20 * 1024 * 1024) {
      toast.error("Dosya boyutu 20MB'den küçük olmalı");
      return;
    }

    setFile(f);
    setPreview(URL.createObjectURL(f));
  };

  const handleSubmit = async () => {
    if (!file) return;
    setUploading(true);
    try {
      await onSubmit(file, caption || undefined);
      toast.success("Hikaye paylaşıldı!");
      onClose();
    } catch {
      toast.error("Hikaye paylaşılamadı");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-background flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <button onClick={onClose} aria-label="Kapat">
          <X className="h-6 w-6 text-foreground" />
        </button>
        <h2 className="text-sm font-semibold text-foreground">Hikaye Oluştur</h2>
        <Button
          size="sm"
          disabled={!file || uploading}
          onClick={handleSubmit}
          className="gradient-neon text-neon-foreground"
        >
          {uploading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
        </Button>
      </div>

      {/* Content */}
      <div className="flex-1 flex flex-col items-center justify-center p-4">
        {preview ? (
          <div className="relative w-full max-w-sm aspect-[9/16] rounded-2xl overflow-hidden bg-black">
            {file?.type.startsWith("video") ? (
              <video
                src={preview}
                className="w-full h-full object-contain"
                autoPlay
                loop
                muted
                playsInline
              />
            ) : (
              <img
                src={preview}
                className="w-full h-full object-contain"
                alt="Hikaye önizleme"
              />
            )}
            <button
              onClick={() => { setFile(null); setPreview(null); }}
              className="absolute top-3 right-3 bg-black/50 rounded-full p-1.5"
              aria-label="Medyayı kaldır"
            >
              <X className="h-4 w-4 text-white" />
            </button>
          </div>
        ) : (
          <button
            onClick={() => inputRef.current?.click()}
            className="flex flex-col items-center gap-4 p-12 border-2 border-dashed border-muted-foreground/30 rounded-2xl hover:border-neon/50 transition-colors"
          >
            <div className="flex gap-3">
              <ImagePlus className="h-10 w-10 text-muted-foreground" />
              <Film className="h-10 w-10 text-muted-foreground" />
            </div>
            <p className="text-sm text-muted-foreground">Fotoğraf veya video seç</p>
          </button>
        )}

        <input
          ref={inputRef}
          type="file"
          accept="image/*,video/*"
          className="hidden"
          onChange={handleFile}
        />

        {file && (
          <Input
            value={caption}
            onChange={(e) => setCaption(e.target.value)}
            placeholder="Açıklama ekle..."
            className="mt-4 max-w-sm bg-secondary border-border"
            maxLength={200}
          />
        )}
      </div>
    </div>
  );
}

