import { useState, useEffect, useCallback, useRef } from "react";
import { X, ChevronLeft, ChevronRight, Eye } from "lucide-react";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import type { StoryGroup } from "@/hooks/useStories";

interface StoryViewerProps {
  groups: StoryGroup[];
  initialGroupIndex: number;
  currentUserId: string | undefined;
  onMarkViewed: (storyId: string) => Promise<void>;
  onClose: () => void;
}

const STORY_DURATION = 5000;

export function StoryViewer({ groups, initialGroupIndex, currentUserId, onMarkViewed, onClose }: StoryViewerProps) {
  const [groupIdx, setGroupIdx] = useState(initialGroupIndex);
  const [storyIdx, setStoryIdx] = useState(0);
  const [progress, setProgress] = useState(0);
  const timerRef = useRef<ReturnType<typeof setInterval> | undefined>(undefined);
  const startTimeRef = useRef(Date.now());

  const group = groups[groupIdx];
  const story = group?.stories[storyIdx];
  const storyId = story?.id;
  const storyUserId = story?.user_id;
  const mediaType = story?.media_type;

  // Mark viewed
  useEffect(() => {
    if (storyId && currentUserId && storyUserId !== currentUserId) {
      onMarkViewed(storyId);
    }
  }, [storyId, storyUserId, currentUserId, onMarkViewed]);

  const goNext = useCallback(() => {
    if (!group) return;
    if (storyIdx < group.stories.length - 1) {
      setStoryIdx((i) => i + 1);
    } else if (groupIdx < groups.length - 1) {
      setGroupIdx((i) => i + 1);
      setStoryIdx(0);
    } else {
      onClose();
    }
  }, [group, storyIdx, groupIdx, groups.length, onClose]);

  // Progress timer
  useEffect(() => {
    setProgress(0);
    startTimeRef.current = Date.now();

    const duration = mediaType === "video" ? 15000 : STORY_DURATION;

    timerRef.current = setInterval(() => {
      const elapsed = Date.now() - startTimeRef.current;
      const pct = Math.min(elapsed / duration, 1);
      setProgress(pct);
      if (pct >= 1) {
        goNext();
      }
    }, 50);

    return () => clearInterval(timerRef.current);
  }, [groupIdx, storyIdx, mediaType, goNext]);


  const goPrev = useCallback(() => {
    if (storyIdx > 0) {
      setStoryIdx((i) => i - 1);
    } else if (groupIdx > 0) {
      setGroupIdx((i) => i - 1);
      setStoryIdx(groups[groupIdx - 1].stories.length - 1);
    }
  }, [storyIdx, groupIdx, groups]);

  // Touch / click areas
  const handleTap = (e: React.MouseEvent | React.TouchEvent) => {
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const clientX = "touches" in e ? e.changedTouches[0].clientX : e.clientX;
    if (clientX < rect.left + rect.width / 3) {
      goPrev();
    } else {
      goNext();
    }
  };

  if (!group || !story) return null;

  const timeAgo = getTimeAgo(story.created_at);

  return (
    <div className="fixed inset-0 z-[100] bg-black flex items-center justify-center">
      {/* Progress bars */}
      <div className="absolute top-0 left-0 right-0 z-10 flex gap-1 p-2 pt-[env(safe-area-inset-top,8px)]">
        {group.stories.map((_, i) => (
          <div key={i} className="flex-1 h-[3px] rounded-full bg-white/20 overflow-hidden">
            <div
              className="h-full bg-white rounded-full transition-none"
              style={{
                width: `${i < storyIdx ? 100 : i === storyIdx ? progress * 100 : 0}%`,
              }}
            />
          </div>
        ))}
      </div>

      {/* Header */}
      <div className="absolute top-8 left-0 right-0 z-10 flex items-center justify-between px-4">
        <div className="flex items-center gap-2">
          <Avatar className="h-8 w-8 border border-white/30">
            <AvatarImage src={group.avatar_url ?? undefined} />
            <AvatarFallback className="text-xs bg-secondary">
              {group.display_name.slice(0, 2).toUpperCase()}
            </AvatarFallback>
          </Avatar>
          <div>
            <p className="text-white text-sm font-medium">{group.display_name}</p>
            <p className="text-white/60 text-[10px]">{timeAgo}</p>
          </div>
        </div>
        <button onClick={onClose} className="text-white p-2" aria-label="Kapat">
          <X className="h-6 w-6" />
        </button>
      </div>

      {/* Media */}
      <div className="w-full h-full" onClick={handleTap}>
        {story.media_type === "video" ? (
          <video
            key={story.id}
            src={story.media_url}
            className="w-full h-full object-contain"
            autoPlay
            playsInline
            muted={false}
          />
        ) : (
          <img
            key={story.id}
            src={story.media_url}
            className="w-full h-full object-contain"
            alt={story.caption ?? "Hikaye"}
          />
        )}
      </div>

      {/* Caption */}
      {story.caption && (
        <div className="absolute bottom-8 left-0 right-0 z-10 px-6 text-center">
          <p className="text-white text-sm bg-black/40 rounded-xl px-4 py-2 backdrop-blur-sm inline-block">
            {story.caption}
          </p>
        </div>
      )}

      {/* Navigation arrows (desktop) */}
      {groupIdx > 0 && (
        <button
          onClick={(e) => { e.stopPropagation(); goPrev(); }}
          className="absolute left-2 top-1/2 -translate-y-1/2 z-10 text-white/60 hover:text-white hidden sm:block"
          aria-label="Önceki"
        >
          <ChevronLeft className="h-8 w-8" />
        </button>
      )}
      {(storyIdx < group.stories.length - 1 || groupIdx < groups.length - 1) && (
        <button
          onClick={(e) => { e.stopPropagation(); goNext(); }}
          className="absolute right-2 top-1/2 -translate-y-1/2 z-10 text-white/60 hover:text-white hidden sm:block"
          aria-label="Sonraki"
        >
          <ChevronRight className="h-8 w-8" />
        </button>
      )}
    </div>
  );
}

function getTimeAgo(date: string): string {
  const diff = Date.now() - new Date(date).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "şimdi";
  if (mins < 60) return `${mins}dk`;
  const hours = Math.floor(mins / 60);
  return `${hours}sa`;
}

