import { useEffect, useState } from "react";

interface Burst {
  id: number;
  emoji: string;
  left: number;
  drift: number;
  duration: number;
}

export function FloatingReactions({ triggers }: { triggers: { id: number; emoji: string }[] }) {
  const [bursts, setBursts] = useState<Burst[]>([]);

  useEffect(() => {
    if (triggers.length === 0) return;
    const last = triggers[triggers.length - 1];
    const newBurst: Burst = {
      id: last.id,
      emoji: last.emoji,
      left: 30 + Math.random() * 50,
      drift: (Math.random() - 0.5) * 80,
      duration: 2200 + Math.random() * 600,
    };
    setBursts((prev) => [...prev, newBurst]);
    const t = setTimeout(() => {
      setBursts((prev) => prev.filter((b) => b.id !== newBurst.id));
    }, newBurst.duration);
    return () => clearTimeout(t);
  }, [triggers]);

  return (
    <div className="pointer-events-none absolute inset-0 overflow-hidden">
      {bursts.map((b) => (
        <span
          key={b.id}
          className="absolute bottom-4 text-3xl"
          style={{
            left: `${b.left}%`,
            animation: `tvFloat ${b.duration}ms ease-out forwards`,
            ["--drift" as any]: `${b.drift}px`,
          }}
        >
          {b.emoji}
        </span>
      ))}
      <style>{`
        @keyframes tvFloat {
          0% { transform: translate(0, 0) scale(0.6); opacity: 0; }
          15% { opacity: 1; transform: translate(0, -10px) scale(1.1); }
          100% { transform: translate(var(--drift), -340px) scale(1.4); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

