import { useEffect, useRef, useImperativeHandle, forwardRef } from "react";
import Hls from "hls.js";

export interface HlsPlayerHandle {
  play: () => Promise<void>;
  pause: () => void;
  unmute: () => void;
  mute: () => void;
  enterPiP: () => Promise<void>;
  getVideo: () => HTMLVideoElement | null;
}

interface Props {
  src: string;
  active: boolean;
  muted: boolean;
  poster?: string | null;
  className?: string;
  onError?: (msg: string) => void;
}

/**
 * Adaptive HLS player with HLS.js (Netflix-style ABR).
 * Falls back to native playback for Safari (`canPlayType("application/vnd.apple.mpegurl")`).
 */
export const HlsPlayer = forwardRef<HlsPlayerHandle, Props>(function HlsPlayer(
  { src, active, muted, poster, className, onError },
  ref,
) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const hlsRef = useRef<Hls | null>(null);

  useImperativeHandle(ref, () => ({
    play: async () => {
      const v = videoRef.current;
      if (!v) return;
      try {
        await v.play();
      } catch {
        /* autoplay-policy will block until user gesture */
      }
    },
    pause: () => videoRef.current?.pause(),
    unmute: () => {
      if (videoRef.current) videoRef.current.muted = false;
    },
    mute: () => {
      if (videoRef.current) videoRef.current.muted = true;
    },
    enterPiP: async () => {
      const v = videoRef.current as any;
      if (!v) return;
      try {
        if (document.pictureInPictureElement) {
          await (document as any).exitPictureInPicture();
        } else if (v.requestPictureInPicture) {
          await v.requestPictureInPicture();
        }
      } catch (e) {
        console.warn("PiP failed", e);
      }
    },
    getVideo: () => videoRef.current,
  }));

  // Setup / teardown HLS instance
  useEffect(() => {
    const video = videoRef.current;
    if (!video || !src) return;

    let cancelled = false;

    if (Hls.isSupported()) {
      const hls = new Hls({
        // ABR / low-latency tuning
        enableWorker: true,
        lowLatencyMode: true,
        backBufferLength: 30,
        maxBufferLength: 30,
        maxMaxBufferLength: 60,
        capLevelToPlayerSize: true, // cap quality to player size for bandwidth efficiency
      });
      hlsRef.current = hls;
      hls.loadSource(src);
      hls.attachMedia(video);
      hls.on(Hls.Events.ERROR, (_e, data) => {
        if (cancelled) return;
        if (data.fatal) {
          switch (data.type) {
            case Hls.ErrorTypes.NETWORK_ERROR:
              hls.startLoad();
              break;
            case Hls.ErrorTypes.MEDIA_ERROR:
              hls.recoverMediaError();
              break;
            default:
              onError?.(data.details || "Stream error");
              hls.destroy();
          }
        }
      });
    } else if (video.canPlayType("application/vnd.apple.mpegurl")) {
      // Native HLS (Safari / iOS)
      video.src = src;
    } else {
      onError?.("Bu cihaz HLS desteklemiyor");
    }

    return () => {
      cancelled = true;
      if (hlsRef.current) {
        try {
          hlsRef.current.destroy();
        } catch {}
        hlsRef.current = null;
      }
      try {
        video.removeAttribute("src");
        video.load();
      } catch {}
    };
  }, [src, onError]);

  // Play/pause based on active flag
  useEffect(() => {
    const v = videoRef.current;
    if (!v) return;
    if (active) {
      v.muted = muted;
      v.play().catch(() => {});
    } else {
      v.pause();
      try {
        v.currentTime = Math.max(0, v.currentTime - 0.01);
      } catch {}
    }
  }, [active, muted]);

  return (
    <video
      ref={videoRef}
      className={className}
      poster={poster || undefined}
      playsInline
      muted={muted}
      autoPlay={active}
      controls={false}
      preload="metadata"
    />
  );
});

