export function JiyanTVTab() {
  const { user } = useAuth();
  const { broadcast, channels, loading } = useJiyanTV();
  const [selectedYoutubeId, setSelectedYoutubeId] = useState<string | null>(null);
  const [showChat, setShowChat] = useState(false);
  const [liveKekas, setLiveKekas] = useState<KekaVideo[]>([]);

  useEffect(() => {
    fetchLiveKekaVideos(8).then(setLiveKekas).catch(() => {});
    const i = setInterval(() => {
      fetchLiveKekaVideos(8).then(setLiveKekas).catch(() => {});
    }, 30000);
    return () => clearInterval(i);
  }, []);

  const activeId = selectedYoutubeId || broadcast?.youtube_id || null;
  const isOfficial = !selectedYoutubeId && !!broadcast;
  const activeChannel = channels.find((c) => c.youtube_id === activeId);

  const { messages, send } = useTVChat(broadcast?.id ?? null);
