            <div className="flex gap-2 overflow-x-auto -mx-1 px-1 scrollbar-none">
              {liveKekas.map((v) => (
                <Link
                  key={v.id}
                  to="/keka"
                  search={{ v: v.id }}
                  className="relative shrink-0 w-24 aspect-[9/14] rounded-xl overflow-hidden bg-zinc-900 border border-amber-400/30 active:scale-95 transition"
                >
                  {v.thumbnail_url ? (
                    <img
