                  <div className="absolute inset-x-0 top-0 p-1.5">
                    <span className="text-[8px] font-bold px-1 py-0.5 rounded bg-red-600 text-white tracking-wider">
                      LIVE
                    </span>
                  </div>
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/90 to-transparent p-1.5">
                    <p className="text-[10px] font-semibold text-white truncate">
                      {v.profile?.display_name || "Anonim"}
                    </p>
                  </div>
                </Link>
              ))}
            </div>
          </div>
        )}

        {/* Resmi yayın kartı */}
        {broadcast && (
          <button
            onClick={() => setSelectedYoutubeId(null)}
            className={`w-full text-left rounded-2xl overflow-hidden border transition ${
              isOfficial
                ? "border-amber-400/60 bg-gradient-to-br from-amber-500/15 to-orange-500/5"
                : "border-amber-500/20 bg-amber-500/[0.04] hover:bg-amber-500/10"
            }`}
          >
            <div className="flex gap-3 p-3 items-center">
              <div className="h-14 w-14 rounded-xl bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center shadow-lg shadow-amber-500/30 shrink-0">
                <Radio className="h-6 w-6 text-black" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5 mb-0.5">
                  <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-red-600 text-white tracking-wider">
                    WKO LIVE
                  </span>
                  {isOfficial && (
                    <span className="text-[9px] font-bold text-amber-400">▶ İZLENİYOR</span>
                  )}
                </div>
                <p className="text-sm font-semibold truncate">{broadcast.title}</p>
                <p className="text-[10px] text-white/50">Resmi WKO yayını · global</p>
              </div>
            </div>
          </button>
        )}

        {channels.length === 0 && !broadcast ? (
          <div className="rounded-2xl border border-white/5 bg-white/[0.02] p-6 text-center">
            <Tv className="h-8 w-8 text-white/20 mx-auto mb-2" />
            <p className="text-sm text-white/60">Henüz kanal eklenmedi</p>
            <p className="text-[11px] text-white/30 mt-1">Yakında daha fazla yayın</p>
          </div>
        ) : (
          channels.map((c) => {
            const isActive = c.youtube_id === activeId && !isOfficial;
            return (
              <button
                key={c.id}
                onClick={() => setSelectedYoutubeId(c.youtube_id)}
                className={`w-full text-left rounded-2xl overflow-hidden border transition ${
                  isActive
                    ? "border-amber-400/60 bg-amber-500/10"
                    : "border-white/10 bg-white/[0.03] hover:bg-white/[0.07]"
                }`}
              >
                <div className="flex gap-3 p-3 items-center">
                  <div className="relative h-14 w-14 rounded-xl overflow-hidden shrink-0 bg-white/5">
                    {c.avatar_url ? (
                      <img src={c.avatar_url} alt={c.name} loading="lazy" className="h-full w-full object-cover" />
                    ) : (
                      <div className="h-full w-full bg-gradient-to-br from-amber-500/30 to-orange-600/20 flex items-center justify-center text-base font-bold text-amber-300">
                        {c.name[0]}
                      </div>
                    )}
                    <span className="absolute bottom-1 right-1 h-2 w-2 rounded-full bg-red-500 ring-2 ring-black animate-pulse" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-1.5 mb-0.5">
                      <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-red-500/20 text-red-300 tracking-wider">
                        LIVE
                      </span>
                      <span className="text-[9px] uppercase tracking-wider text-white/40">{c.category}</span>
                    </div>
                    <p className="text-sm font-semibold truncate">{c.name}</p>
                    <p className="text-[10px] text-white/40">YouTube · canlı yayın</p>
                  </div>
                  {isActive && (
                    <span className="text-[9px] font-bold text-amber-400 shrink-0">▶</span>
                  )}
                </div>
              </button>
            );
          })
        )}
      </div>
    </div>
  );
}

