import { useState, useRef, useEffect } from "react";
import { Send, X } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import type { TVChatMessage } from "@/hooks/useJiyanTV";

interface Props {
  messages: TVChatMessage[];
  onSend: (content: string) => void;
  onClose: () => void;
  canSend: boolean;
}

export function TVChatOverlay({ messages, onSend, onClose, canSend }: Props) {
  const [text, setText] = useState("");
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
  }, [messages]);

  const handleSend = () => {
    if (!text.trim()) return;
    onSend(text);
    setText("");
  };

  return (
    <div className="absolute right-0 top-0 bottom-0 z-30 w-72 max-w-[80vw] bg-black/85 backdrop-blur-xl border-l border-amber-500/20 flex flex-col">
      <div className="flex items-center justify-between px-3 py-2 border-b border-white/10">
        <span className="text-xs font-bold uppercase tracking-wider text-amber-400">Live Chat</span>
        <button onClick={onClose} className="p-1 rounded hover:bg-white/10 text-white/70" aria-label="Close chat">
          <X className="h-4 w-4" />
        </button>
      </div>
      <div ref={scrollRef} className="flex-1 overflow-y-auto px-3 py-2 space-y-2 text-xs">
        {messages.length === 0 ? (
          <p className="text-white/40 text-center py-6">Sohbet sessiz... ilk mesajı sen at.</p>
        ) : (
          messages.map((m) => (
            <div key={m.id} className="flex gap-2">
              <Avatar className="h-6 w-6 shrink-0">
                <AvatarImage src={m.profile?.avatar_url || undefined} />
                <AvatarFallback className="text-[9px] bg-amber-500/20 text-amber-300">
                  {(m.profile?.display_name || "?")[0]}
                </AvatarFallback>
              </Avatar>
              <div className="min-w-0 flex-1">
                <p className="text-amber-300 font-semibold text-[10px] truncate">
                  {m.profile?.display_name || "Anon"}
                </p>
                <p className="text-white/85 break-words">{m.content}</p>
              </div>
            </div>
          ))
        )}
      </div>
      <div className="p-2 border-t border-white/10">
        {canSend ? (
          <div className="flex gap-1">
            <input
              type="text"
              value={text}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSend()}
              placeholder="Mesaj yaz..."
              maxLength={200}
              className="flex-1 bg-white/5 border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white placeholder:text-white/30 outline-none focus:border-amber-400/50"
            />
            <button
              onClick={handleSend}
              className="p-2 rounded-lg bg-amber-500/90 hover:bg-amber-500 text-black"
              aria-label="Send"
            >
              <Send className="h-3.5 w-3.5" />
            </button>
          </div>
        ) : (
          <p className="text-[10px] text-white/40 text-center">Sohbet için giriş yap</p>
        )}
      </div>
    </div>
  );
}

