import { useEffect, useRef, useState, useMemo } from "react";
import { Volume2, VolumeX, Maximize, PictureInPicture2, MessageCircle, Heart, Sparkles, Sun, Hand, Send, X, Radio, Eye } from "lucide-react";
import { HlsPlayer, type HlsPlayerHandle } from "./HlsPlayer";
import { FloatingReactions } from "./FloatingReactions";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { useTVChat, useTVReactions, type TVBroadcast, type TVChannel } from "@/hooks/useJiyanTV";
import { useTVPresence } from "@/hooks/useTVPresence";
import { toast } from "sonner";

export interface FeedSlide {
  /** Unique key (broadcast id or channel id) */
  id: string;
  title: string;
  subtitle?: string;
  avatar_url?: string | null;
  stream_type: "youtube" | "hls";
  /** youtube video id OR full hls url */
  src: string;
  is_official?: boolean;
  /** broadcast id used for chat/reactions/presence — only for slides backed by tv_broadcasts */
  broadcast_id?: string | null;
}

interface Props {
  broadcast: TVBroadcast | null;
  channels: TVChannel[];
  user: { id: string } | null;
  userProfile?: {
    display_name?: string | null;
    avatar_url?: string | null;
    kurd_id?: string | null;
  } | null;
}

/**
 * Build the slide list — official broadcast first (if any), then pinned channels, then the rest.
 */
function buildSlides(broadcast: TVBroadcast | null, channels: TVChannel[]): FeedSlide[] {
  const slides: FeedSlide[] = [];
  if (broadcast?.is_active) {
    const isHls = broadcast.stream_type === "hls" && !!broadcast.stream_url;
    slides.push({
      id: `b-${broadcast.id}`,
      title: broadcast.title,
      subtitle: "WKO Resmi Yayını",
      stream_type: isHls ? "hls" : "youtube",
      src: isHls ? (broadcast.stream_url as string) : broadcast.youtube_id,
      is_official: true,
      broadcast_id: broadcast.id,
    });
  }
  for (const c of channels) {
    const isHls = c.stream_type === "hls" && !!c.stream_url;
    slides.push({
      id: `c-${c.id}`,
      title: c.name,
      subtitle: c.category?.toUpperCase() || "LIVE",
      avatar_url: c.avatar_url,
      stream_type: isHls ? "hls" : "youtube",
      src: isHls ? (c.stream_url as string) : c.youtube_id,
    });
  }
  return slides;
}

export function VerticalTVFeed({ broadcast, channels, user, userProfile }: Props) {
  const slides = useMemo(() => buildSlides(broadcast, channels), [broadcast, channels]);
  const [activeIndex, setActiveIndex] = useState(0);
  const [muted, setMuted] = useState(true);
  const [showChat, setShowChat] = useState(false);
  const [chatText, setChatText] = useState("");
  // Lazy loading — yalnızca görünür ve aktif çevresindeki slide'lar yüklenir.
  // Bant genişliği ve mobil pil tasarrufu için kritik.
  const [visibleIndices, setVisibleIndices] = useState<Set<number>>(() => new Set([0]));

  const containerRef = useRef<HTMLDivElement>(null);
  const slideRefs = useRef<Array<HTMLElement | null>>([]);
  const playerRefs = useRef<Array<HlsPlayerHandle | null>>([]);

  const activeSlide = slides[activeIndex];
  const broadcastId = activeSlide?.broadcast_id ?? null;
  const presenceTarget = activeSlide?.id ?? null;

  const { messages, send } = useTVChat(broadcastId);
  const { bursts, react } = useTVReactions(broadcastId);
  const liveViewers = useTVPresence(presenceTarget, user?.id ?? null);

  // Snap-scroll observer to detect which slide is in view
  useEffect(() => {
    const root = containerRef.current;
    if (!root) return;
    const observer = new IntersectionObserver(
      (entries) => {
        // Pick entry with the largest intersection ratio above threshold
        let best: IntersectionObserverEntry | null = null;
        for (const e of entries) {
          if (e.isIntersecting && (!best || e.intersectionRatio > best.intersectionRatio)) {
            best = e;
          }
        }
        if (best) {
          const idx = Number((best.target as HTMLElement).dataset.idx);
          if (!Number.isNaN(idx)) setActiveIndex(idx);
        }
      },
      { root, threshold: [0.6] },
    );
    slideRefs.current.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [slides.length]);

  // Lazy preload — aktif slide ± 1 (önceki/sonraki) yüklenir, gerisi placeholder.
  useEffect(() => {
    setVisibleIndices((prev) => {
      const next = new Set(prev);
      [activeIndex - 1, activeIndex, activeIndex + 1].forEach((i) => {
        if (i >= 0 && i < slides.length) next.add(i);
      });
      return next;
    });
  }, [activeIndex, slides.length]);

  const handleReact = async (emoji: string) => {
    if (!user) {
      toast.error("Giriş yap → reaksiyon gönder");
      return;
    }
    if (!broadcastId) {
      toast.info("Reaksiyon yalnızca resmi yayında aktif");
      return;
    }
    await react(user.id, emoji);
  };

  const handleSend = () => {
    const t = chatText.trim();
    if (!t) return;
    if (!user) {
      toast.error("Giriş yap → mesaj gönder");
      return;
    }
    if (!broadcastId) {
      toast.info("Sohbet yalnızca resmi yayında aktif");
      return;
    }
    send(user.id, t);
    setChatText("");
  };

  const enterFullscreen = async () => {
    try {
      const el = containerRef.current;
      if (!el) return;
      if (document.fullscreenElement) {
        await document.exitFullscreen();
      } else {
        await el.requestFullscreen();
        try {
          const o = (screen as any).orientation;
          if (o?.lock) await o.lock("landscape");
        } catch {}
      }
    } catch (e) {
      console.warn("Fullscreen failed", e);
    }
  };

  const enterPiP = async () => {
    const p = playerRefs.current[activeIndex];
    if (!p) {
      toast.info("PiP yalnızca HLS yayınlarda destekleniyor");
      return;
    }
    await p.enterPiP();
  };

  if (slides.length === 0) {
    return (
      <div className="h-[100dvh] bg-black flex flex-col items-center justify-center text-white/60 px-6 text-center">
        <Radio className="h-10 w-10 text-amber-400/50 mb-3" />
        <p className="text-sm font-semibold">Şu an aktif yayın yok</p>
        <p className="text-[11px] text-white/30 mt-1">Admin panelinden bir kanal veya yayın eklediğinde burada görünecek</p>
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      className="h-[100dvh] w-full bg-black overflow-y-auto snap-y snap-mandatory overscroll-contain scrollbar-none"
      style={{ scrollbarWidth: "none" }}
    >
      {slides.map((slide, idx) => {
        const isActive = idx === activeIndex;
        const shouldRender = visibleIndices.has(idx);
        return (
          <section
            key={slide.id}
            data-idx={idx}
            ref={(el) => {
              slideRefs.current[idx] = el;
            }}
            className="relative h-[100dvh] w-full snap-start snap-always bg-black"
          >
            {/* Player layer — lazy: sadece görünür / komşu slide'lar yüklenir */}
            <div className="absolute inset-0">
              {!shouldRender ? (
                /* Placeholder thumbnail — bant tasarrufu */
                <div className="absolute inset-0 flex items-center justify-center bg-gradient-to-br from-black via-zinc-950 to-black">
                  {slide.avatar_url ? (
                    <img
                      src={slide.avatar_url}
                      alt={slide.title}
                      loading="lazy"
                      decoding="async"
                      className="h-32 w-32 rounded-2xl object-cover opacity-30 blur-sm"
                    />
                  ) : (
                    <Radio className="h-12 w-12 text-amber-400/30" />
                  )}
                </div>
              ) : slide.stream_type === "hls" ? (
                <HlsPlayer
                  ref={(h) => {
                    playerRefs.current[idx] = h;
                  }}
                  src={slide.src}
                  active={isActive}
                  muted={muted}
                  className="h-full w-full object-cover"
                  onError={(m) => isActive && toast.error(`Yayın hatası: ${m}`)}
                />
              ) : (
                isActive && (
                  <iframe
                    key={slide.src}
                    src={`https://www.youtube.com/embed/${slide.src}?autoplay=1&mute=${muted ? 1 : 0}&rel=0&modestbranding=1&playsinline=1&controls=0`}
                    title={slide.title}
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                    allowFullScreen
                    className="h-full w-full border-0"
                    loading="lazy"
                  />
                )
              )}
            </div>

            {/* Tap overlay → toggle mute on the active slide */}
            {isActive && (
              <button
                aria-label="Toggle sound"
                onClick={() => setMuted((m) => !m)}
                className="absolute inset-0 z-10 cursor-pointer focus:outline-none"
                style={{ background: "transparent" }}
              />
            )}

            {/* Top gradient */}
            <div className="pointer-events-none absolute inset-x-0 top-0 h-32 bg-gradient-to-b from-black/80 via-black/30 to-transparent z-10" />
            {/* Bottom gradient */}
            <div className="pointer-events-none absolute inset-x-0 bottom-0 h-72 bg-gradient-to-t from-black/90 via-black/40 to-transparent z-10" />

            {/* TOP: brand + viewers + KurdID avatar */}
            <div className="absolute top-0 left-0 right-0 z-20 flex items-start justify-between px-3 pt-3">
              <div className="flex items-center gap-2">
                {slide.is_official && (
                  <span className="flex items-center gap-1 px-2 py-0.5 rounded-md bg-red-600/95 shadow text-[10px] font-bold tracking-wider text-white">
                    <span className="h-1.5 w-1.5 rounded-full bg-white animate-pulse" />
                    WKO LIVE
                  </span>
                )}
                <span className="flex items-center gap-1 px-2 py-0.5 rounded-md bg-black/60 backdrop-blur border border-white/10 text-[10px] font-semibold text-white/85">
                  <Eye className="h-3 w-3 text-amber-300" />
                  {liveViewers.toLocaleString()}
                </span>
              </div>
              {userProfile && (
                <div className="flex items-center gap-1.5 px-1.5 py-1 rounded-full bg-black/55 backdrop-blur border border-amber-400/30">
                  <Avatar className="h-6 w-6 ring-1 ring-amber-400/60">
                    <AvatarImage src={userProfile.avatar_url || undefined} />
                    <AvatarFallback className="text-[9px] bg-amber-500/30 text-amber-100">
                      {(userProfile.display_name || "?")[0]}
                    </AvatarFallback>
                  </Avatar>
                  {userProfile.kurd_id && (
                    <span className="text-[9px] font-mono text-amber-300/90 pr-1">{userProfile.kurd_id}</span>
                  )}
                </div>
              )}
            </div>

            {/* BOTTOM-LEFT: title + chat */}
            <div className="absolute bottom-0 left-0 right-20 z-20 px-3 pb-5">
              <div className="flex items-center gap-2 mb-1.5">
                <div className="h-9 w-9 rounded-full overflow-hidden bg-amber-500/20 border border-amber-400/40 shrink-0">
                  {slide.avatar_url ? (
                    <img src={slide.avatar_url} alt="" className="h-full w-full object-cover" />
                  ) : (
                    <div className="h-full w-full flex items-center justify-center text-amber-300 font-bold text-sm">
                      {slide.title[0]}
                    </div>
                  )}
                </div>
                <div className="min-w-0">
                  <p className="text-sm font-bold text-white truncate drop-shadow">{slide.title}</p>
                  <p className="text-[10px] uppercase tracking-wider text-amber-300/85">{slide.subtitle}</p>
                </div>
              </div>

              {/* Auto-scrolling chat box */}
              {isActive && broadcastId && showChat && (
                <ChatStream messages={messages} />
              )}
              {isActive && broadcastId && (
                <div className="mt-2 flex gap-1.5">
                  <input
                    value={chatText}
                    onChange={(e) => setChatText(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && handleSend()}
                    placeholder={user ? "Mesaj yaz…" : "Sohbet için giriş yap"}
                    disabled={!user}
                    maxLength={200}
                    className="flex-1 bg-black/55 backdrop-blur border border-white/15 rounded-full px-3 py-1.5 text-xs text-white placeholder:text-white/45 outline-none focus:border-amber-400/60 disabled:opacity-50"
                  />
                  <button
                    onClick={handleSend}
                    disabled={!user || !chatText.trim()}
                    aria-label="Send message"
                    className="h-8 w-8 rounded-full bg-amber-500 text-black flex items-center justify-center disabled:opacity-40"
                  >
                    <Send className="h-3.5 w-3.5" />
                  </button>
                </div>
              )}
              {isActive && !broadcastId && (
                <p className="text-[10px] text-white/40 mt-1">Sohbet & reaksiyonlar yalnızca WKO resmi yayınında</p>
              )}
            </div>

            {/* RIGHT vertical action bar */}
            <div className="absolute bottom-24 right-2 z-20 flex flex-col items-center gap-3">
              <ActionButton
                icon={muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}
                label={muted ? "Sessiz" : "Sesli"}
                onClick={() => setMuted((m) => !m)}
              />
              <ActionButton
                icon={<MessageCircle className="h-5 w-5" />}
                label="Chat"
                active={showChat}
                onClick={() => setShowChat((s) => !s)}
              />
              <ActionButton
                icon={<Heart className="h-5 w-5" />}
                label="❤️"
                onClick={() => handleReact("❤️")}
              />
              <ActionButton
                icon={<Sparkles className="h-5 w-5" />}
                label="🔥"
                onClick={() => handleReact("🔥")}
              />
              <ActionButton
                icon={<Hand className="h-5 w-5" />}
                label="👏"
                onClick={() => handleReact("👏")}
              />
              <ActionButton
                icon={<Sun className="h-5 w-5" />}
                label="☀️"
                onClick={() => handleReact("☀️")}
              />
              <ActionButton
                icon={<PictureInPicture2 className="h-5 w-5" />}
                label="PiP"
                onClick={enterPiP}
              />
              <ActionButton
                icon={<Maximize className="h-5 w-5" />}
                label="Tam"
                onClick={enterFullscreen}
              />
            </div>

            {/* Floating reactions over the active slide only */}
            {isActive && <FloatingReactions triggers={bursts} />}

            {/* Slide index pill */}
            <div className="absolute top-1/2 right-1 -translate-y-1/2 z-20 flex flex-col gap-1">
              {slides.map((_, i) => (
                <span
                  key={i}
                  className={`h-4 w-0.5 rounded-full transition-all ${
                    i === activeIndex ? "bg-amber-400 h-6" : "bg-white/25"
                  }`}
                />
              ))}
            </div>
          </section>
        );
      })}
    </div>
  );
}

function ActionButton({
  icon,
  label,
  onClick,
  active,
}: {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  active?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      className="flex flex-col items-center gap-0.5 group active:scale-90 transition"
    >
      <span
        className={`h-10 w-10 rounded-full flex items-center justify-center backdrop-blur border ${
          active
            ? "bg-amber-500 border-amber-300 text-black shadow-lg shadow-amber-500/40"
            : "bg-black/45 border-white/15 text-white"
        }`}
      >
        {icon}
      </span>
      <span className="text-[9px] text-white/80 font-medium drop-shadow">{label}</span>
    </button>
  );
}

function ChatStream({ messages }: { messages: { id: string; content: string; profile?: { display_name: string; avatar_url: string | null } }[] }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    ref.current?.scrollTo({ top: ref.current.scrollHeight, behavior: "smooth" });
  }, [messages]);
  return (
    <div
      ref={ref}
      className="max-h-40 overflow-y-auto rounded-xl bg-black/45 backdrop-blur border border-white/10 px-2 py-1.5 space-y-1 text-[11px] scrollbar-none"
      style={{ scrollbarWidth: "none" }}
    >
      {messages.length === 0 ? (
        <p className="text-white/40 text-center py-2">Sohbet sessiz…</p>
      ) : (
        messages.slice(-12).map((m) => (
          <p key={m.id} className="text-white/90 leading-snug">
            <span className="text-amber-300 font-semibold mr-1">
              {m.profile?.display_name || "Anon"}:
            </span>
            {m.content}
          </p>
        ))
      )}
    </div>
  );
}

