import { useState, useEffect } from "react";
import { QrCode, X, Loader2, ScanLine } from "lucide-react";

interface QrScanToPayProps {
  onClose: () => void;
  onScanned: (kurdId: string) => void;
}

/**
 * Visual QR scan simulation. Uses an animated scan line
 * over a fake camera viewport. After 2.5s, returns a mock +777 ID.
 */
export function QrScanToPay({ onClose, onScanned }: QrScanToPayProps) {
  const [scanning, setScanning] = useState(true);

  useEffect(() => {
    const t = setTimeout(() => {
      setScanning(false);
      // Mock detected ID
      const mockId = `+777 ${Math.floor(1000 + Math.random() * 9000)} ${Math.floor(1000 + Math.random() * 9000)}`;
      setTimeout(() => onScanned(mockId), 600);
    }, 2500);
    return () => clearTimeout(t);
  }, [onScanned]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/85 backdrop-blur-sm animate-fade-in p-4">
      <div className="relative w-full max-w-sm">
        <button
          onClick={onClose}
          className="absolute -top-12 right-0 flex h-9 w-9 items-center justify-center rounded-full bg-secondary text-foreground"
        >
          <X className="h-4 w-4" />
        </button>

        <div className="mb-5 text-center">
          <div className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/15 mb-2">
            <QrCode className="h-6 w-6 text-primary" />
          </div>
          <h2 className="text-lg font-bold text-foreground">QR Scan to Pay</h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Karşı tarafın Kurd-ID QR'ını çerçeveye al
          </p>
        </div>

        {/* Camera viewport */}
        <div className="relative aspect-square w-full overflow-hidden rounded-3xl border-2 border-primary/40 bg-gradient-to-br from-secondary via-card to-secondary shadow-[0_0_60px_rgba(59,130,246,0.35)]">
          {/* Corner brackets */}
          <div className="absolute top-4 left-4 h-8 w-8 border-t-2 border-l-2 border-primary rounded-tl-lg" />
          <div className="absolute top-4 right-4 h-8 w-8 border-t-2 border-r-2 border-primary rounded-tr-lg" />
          <div className="absolute bottom-4 left-4 h-8 w-8 border-b-2 border-l-2 border-primary rounded-bl-lg" />
          <div className="absolute bottom-4 right-4 h-8 w-8 border-b-2 border-r-2 border-primary rounded-br-lg" />

          {/* Animated scan line */}
          {scanning && (
            <div
              className="absolute left-0 right-0 h-1 bg-gradient-to-r from-transparent via-primary to-transparent shadow-[0_0_20px_rgba(59,130,246,0.9)]"
              style={{
                animation: "scanLine 2.5s linear",
              }}
            />
          )}

          {/* Center icon */}
          <div className="absolute inset-0 flex items-center justify-center">
            {scanning ? (
              <div className="flex flex-col items-center gap-3">
                <ScanLine className="h-12 w-12 text-primary animate-pulse" />
                <p className="text-xs font-mono text-primary">SCANNING...</p>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-3 animate-scale-in">
                <Loader2 className="h-10 w-10 text-green-400 animate-spin" />
                <p className="text-xs font-mono text-green-400">QR DETECTED ✓</p>
              </div>
            )}
          </div>
        </div>

        <p className="mt-4 text-center text-[11px] text-muted-foreground">
          🔐 Bu bir görsel demo — gerçek kamera erişimi production'da aktifleşir
        </p>
      </div>

      <style>{`
        @keyframes scanLine {
          0% { top: 16px; }
          50% { top: calc(100% - 20px); }
          100% { top: 16px; }
        }
      `}</style>
    </div>
  );
}

