import { useState, useEffect } from "react";
import { Send, Loader2, X, CheckCircle2, AlertCircle, User } from "lucide-react";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { SovereignActionGate } from "@/components/sovereign/SovereignActionGate";

interface SendByKurdIdProps {
  senderId: string;
  onSuccess: (amount: number, recipient: string) => void;
  onClose: () => void;
}

interface RecipientPreview {
  user_id: string;
  display_name: string;
  avatar_url: string | null;
  kurd_id_tier: string;
  is_premium: boolean;
}

type LookupState =
  | { status: "idle" }
  | { status: "searching" }
  | { status: "found"; recipient: RecipientPreview }
  | { status: "not_found" }
  | { status: "self" }
  | { status: "invalid" };

const KURD_ID_REGEX = /^\+777\s?\d{4}\s?\d{4}$/;

export function SendByKurdId({ senderId, onSuccess, onClose }: SendByKurdIdProps) {
  const [kurdId, setKurdId] = useState("+777 ");
  const [amount, setAmount] = useState<number>(5);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const [lookup, setLookup] = useState<LookupState>({ status: "idle" });
  const [gateOpen, setGateOpen] = useState(false);

  // Debounced recipient lookup
  useEffect(() => {
    const trimmed = kurdId.trim();

    // Empty or just prefix → idle
    if (!trimmed || trimmed === "+777" || trimmed === "+777 ") {
      setLookup({ status: "idle" });
      return;
    }

    // Format check
    if (!KURD_ID_REGEX.test(trimmed)) {
      setLookup({ status: "invalid" });
      return;
    }

    setLookup({ status: "searching" });
    const handle = setTimeout(async () => {
      const { data } = await supabase
        .from("profiles")
        .select("user_id, display_name, avatar_url, kurd_id_tier, is_premium")
        .eq("kurd_id", trimmed)
        .maybeSingle();

      if (!data) {
        setLookup({ status: "not_found" });
      } else if (data.user_id === senderId) {
        setLookup({ status: "self" });
      } else {
        setLookup({ status: "found", recipient: data as RecipientPreview });
      }
    }, 350);

    return () => clearTimeout(handle);
  }, [kurdId, senderId]);

  const canSend = lookup.status === "found" && amount >= 1 && !loading;

  // Sovereign gate first; the actual transfer runs only after Egemen Onay.
  const handleSend = () => {
    if (lookup.status !== "found") return;
    setGateOpen(true);
  };

  const executeTransfer = async () => {
    if (lookup.status !== "found") return;
    setLoading(true);
    try {
      const { data, error } = await supabase.rpc("send_tip", {
        _sender_id: senderId,
        _receiver_id: lookup.recipient.user_id,
        _amount: amount,
        _message: message || undefined,
      });

      if (error) {
        toast.error("Transfer başarısız");
      } else {
        const result = data as unknown as { success: boolean; error?: string; received?: number };
        if (!result.success) {
          toast.error(result.error || "Hata");
        } else {
          onSuccess(amount, lookup.recipient.display_name);
        }
      }
    } catch {
      toast.error("Transfer sırasında bir hata oluştu");
    } finally {
      setLoading(false);
    }
  };

  const inputBorderClass =
    lookup.status === "found"
      ? "border-emerald-500/60 focus:border-emerald-500 focus:ring-emerald-500/30"
      : lookup.status === "not_found" || lookup.status === "invalid" || lookup.status === "self"
        ? "border-destructive/60 focus:border-destructive focus:ring-destructive/30"
        : "border-border focus:border-primary focus:ring-primary/30";

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/70 backdrop-blur-sm animate-fade-in p-4">
      <div className="relative w-full max-w-md rounded-3xl border border-primary/30 bg-card p-5 shadow-[0_20px_60px_rgba(59,130,246,0.25)] animate-scale-in">
        <button
          onClick={onClose}
          className="absolute right-4 top-4 flex h-8 w-8 items-center justify-center rounded-full bg-secondary text-muted-foreground hover:text-foreground transition-colors"
        >
          <X className="h-4 w-4" />
