import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Heart } from "lucide-react";

const tipAmounts = [1, 5, 10, 25, 50];

interface TipDialogProps {
  senderId: string;
  receiverId: string;
  receiverName: string;
  trigger?: React.ReactNode;
}

export function TipDialog({ senderId, receiverId, receiverName, trigger }: TipDialogProps) {
  const [open, setOpen] = useState(false);
  const [amount, setAmount] = useState<number | null>(null);
  const [customAmount, setCustomAmount] = useState("");
  const [message, setMessage] = useState("");
  const [sending, setSending] = useState(false);

  const finalAmount = amount ?? (customAmount ? Number(customAmount) : 0);

  const handleSend = async () => {
    if (!finalAmount || finalAmount < 1 || sending) return;
    setSending(true);

    const { data, error } = await supabase.rpc("send_tip", {
      _sender_id: senderId,
      _receiver_id: receiverId,
      _amount: finalAmount,
      _message: message || undefined,
    });

    if (error) {
      toast.error("Tip gönderilemedi");
    } else {
      const result = data as unknown as { success: boolean; error?: string; sent: number; commission: number; received: number };
      if (!result.success) {
        toast.error(result.error || "Hata oluştu");
      } else {
        toast.success(`💰 ${result.received} DC gönderildi! (${result.commission} DC komisyon)`);
        setOpen(false);
        setAmount(null);
        setCustomAmount("");
        setMessage("");
      }
    }
    setSending(false);
  };

  if (senderId === receiverId) return null;

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {trigger || (
          <Button variant="outline" size="sm" className="gap-1.5 border-gold/30 text-gold hover:bg-gold/10">
            <Heart className="h-3.5 w-3.5" />
            Tip
          </Button>
        )}
      </DialogTrigger>
      <DialogContent className="max-w-sm bg-background border-border">
        <DialogHeader>
          <DialogTitle className="text-foreground">💰 {receiverName}'e Tip Gönder</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Quick amounts */}
          <div className="grid grid-cols-5 gap-2">
            {tipAmounts.map((a) => (
              <button
                key={a}
                onClick={() => { setAmount(a); setCustomAmount(""); }}
                className={`rounded-xl border py-2.5 text-center text-sm font-semibold transition-all active:scale-95 ${
                  amount === a
                    ? "border-gold bg-gold/10 text-gold"
                    : "border-border bg-surface text-foreground hover:border-gold/30"
                }`}
              >
                {a}
              </button>
            ))}
          </div>

          {/* Custom amount */}
          <Input
            type="number"
            placeholder="Özel miktar (1-100 DC)"
            value={customAmount}
            onChange={(e) => { setCustomAmount(e.target.value); setAmount(null); }}
            min={1}
            max={100}
            className="bg-surface border-border"
          />

          {/* Message */}
          <Input
            placeholder="Mesaj (opsiyonel)"
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            maxLength={100}
            className="bg-surface border-border"
          />

          {/* Commission info */}
          {finalAmount > 0 && (
            <div className="rounded-lg bg-surface border border-border p-2.5 text-[11px] text-muted-foreground">
              <div className="flex justify-between"><span>Gönderilecek</span><span className="text-foreground font-medium">{finalAmount} DC</span></div>
              <div className="flex justify-between"><span>Platform komisyonu (%5)</span><span>{(finalAmount * 0.05).toFixed(2)} DC</span></div>
              <div className="flex justify-between mt-1 pt-1 border-t border-border"><span>Alıcı alacak</span><span className="text-gold font-semibold">{(finalAmount * 0.95).toFixed(2)} DC</span></div>
            </div>
          )}

          <Button
            variant="neon"
            className="w-full"
            disabled={!finalAmount || finalAmount < 1 || finalAmount > 100 || sending}
            onClick={handleSend}
          >
            {sending ? "Gönderiliyor..." : `💰 ${finalAmount || 0} DC Gönder`}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

