            {recipient} adresine gönderildi
          </p>
          <p className="mt-3 text-[10px] font-mono text-muted-foreground/70">
            🔐 Encrypted via Kurd-ID · {new Date().toLocaleTimeString()}
          </p>
        </div>
      </div>
    </div>
  );
}

