/**
 * Sovereign Bridge — daily 5 "köprü kelime" pairs.
 * One small phrase rendered in all 5 languages so any (native → target)
 * combination resolves instantly without an API call.
 */
import type { Language } from "./linguistContent";

export interface BridgeWord {
  id: string;
  /** Phrase in every supported language */
  text: Record<Language, string>;
  /** Tiny memorable hint (Turkish) */
  hint?: string;
}

export const BRIDGE_BANK: BridgeWord[] = [
  { id: "hello",   text: { tr: "Merhaba",   ku: "Silav",         en: "Hello",       nl: "Hallo",      ar: "مرحبا" }, hint: "Selamlama — günün anahtarı" },
