  { id: "no",      text: { tr: "Hayır",     ku: "Na",            en: "No",          nl: "Nee",        ar: "لا"    } },
  { id: "water",   text: { tr: "Su",        ku: "Av",            en: "Water",       nl: "Water",      ar: "ماء"   }, hint: "Hayat" },
  { id: "bread",   text: { tr: "Ekmek",     ku: "Nan",           en: "Bread",       nl: "Brood",      ar: "خبز"   } },
  { id: "friend",  text: { tr: "Arkadaş",   ku: "Heval",         en: "Friend",      nl: "Vriend",     ar: "صديق"  }, hint: "Yoldaş" },
  { id: "freedom", text: { tr: "Özgürlük",  ku: "Azadî",         en: "Freedom",     nl: "Vrijheid",   ar: "حرية"  }, hint: "Egemenlik kelimesi" },
  { id: "home",    text: { tr: "Ev",        ku: "Mal",           en: "Home",        nl: "Thuis",      ar: "بيت"   } },
  { id: "today",   text: { tr: "Bugün",     ku: "Îro",           en: "Today",       nl: "Vandaag",    ar: "اليوم" } },
  { id: "love",    text: { tr: "Sevgi",     ku: "Hez",           en: "Love",        nl: "Liefde",     ar: "حب"    } },
  { id: "moon",    text: { tr: "Ay",        ku: "Heyv",          en: "Moon",        nl: "Maan",       ar: "قمر"   } },
  { id: "sun",     text: { tr: "Güneş",     ku: "Roj",           en: "Sun",         nl: "Zon",        ar: "شمس"   }, hint: "☀️ Bayrakta da var" },
  { id: "morning", text: { tr: "Sabah",     ku: "Sibe",          en: "Morning",     nl: "Ochtend",    ar: "صباح"  } },
  { id: "mountain",text: { tr: "Dağ",       ku: "Çiya",          en: "Mountain",    nl: "Berg",       ar: "جبل"   }, hint: "Güç" },
  { id: "river",   text: { tr: "Nehir",     ku: "Çem",           en: "River",       nl: "Rivier",     ar: "نهر"   } },
  { id: "song",    text: { tr: "Şarkı",     ku: "Stran",         en: "Song",        nl: "Lied",       ar: "أغنية" } },
  { id: "voice",   text: { tr: "Ses",      ku: "Deng",          en: "Voice",       nl: "Stem",       ar: "صوت"   }, hint: "Bizim yapay zekanın adı" },
  { id: "peace",   text: { tr: "Barış",    ku: "Aştî",          en: "Peace",       nl: "Vrede",      ar: "سلام"  } },
  { id: "people",  text: { tr: "Halk",     ku: "Gel",           en: "People",      nl: "Volk",       ar: "شعب"   } },
  { id: "land",    text: { tr: "Toprak",   ku: "Ax",            en: "Land",        nl: "Land",       ar: "أرض"   } },
];

/** Pick 5 deterministic words for today (and language pair) */
export function todayBridge(seed = 0, count = 5): BridgeWord[] {
  const day = Math.floor(Date.UTC(
    new Date().getUTCFullYear(),
    new Date().getUTCMonth(),
    new Date().getUTCDate(),
  ) / 86_400_000);
  const start = (day + seed) % BRIDGE_BANK.length;
  const out: BridgeWord[] = [];
  for (let i = 0; i < count; i++) {
    out.push(BRIDGE_BANK[(start + i) % BRIDGE_BANK.length]);
  }
  return out;
}

