    ttsLocale: "ku",
    lessons: [...kurdishLessons, ...sovereignLessons, ...constitutionLessons],
  },
  {
    language: "tr",
    nativeName: "Türkçe",
    englishName: "Turkish",
    flag: "🇹🇷",
    ttsLocale: "tr-TR",
    lessons: [...turkishLessons, ...sovereignLessons, ...constitutionLessons],
  },
  {
    language: "nl",
    nativeName: "Nederlands",
    englishName: "Dutch",
    flag: "🇳🇱",
    ttsLocale: "nl-NL",
    lessons: [...dutchLessons, ...sovereignLessons, ...constitutionLessons],
  },
  {
