    nativeName: "English",
    englishName: "English",
    flag: "🇬🇧",
    ttsLocale: "en-US",
    lessons: [...englishLessons, ...sovereignLessons, ...constitutionLessons],
  },
  {
    language: "ar",
    nativeName: "العربية",
    englishName: "Arabic",
    flag: "🇸🇦",
    ttsLocale: "ar-SA",
    lessons: [...arabicLessons, ...sovereignLessons, ...constitutionLessons],
  },
];

export function getCourse(lang: Language): LanguageCourse {
  return LINGUIST_COURSES.find((c) => c.language === lang) ?? LINGUIST_COURSES[0];
}

export function getLesson(lang: Language, lessonId: string): Lesson | undefined {
  return getCourse(lang).lessons.find((l) => l.id === lessonId);
}

// Determine if lesson completes a level milestone
export function isLevelMilestone(course: LanguageCourse, lesson: Lesson, completedLessonIds: Set<string>): boolean {
  const sameLevelLessons = course.lessons.filter((l) => l.level === lesson.level && l.category === lesson.category);
  const completedInLevel = sameLevelLessons.filter((l) => completedLessonIds.has(l.id) || l.id === lesson.id);
  return completedInLevel.length === sameLevelLessons.length;
}

