import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

type Session = {
  id: string;
  device_name: string;
  device_type: string;
  user_agent: string | null;
  last_active_at: string;
  created_at: string;
  is_current: boolean;
};

const SESSION_KEY = "jiyan_session_id";

function getDeviceName() {
  if (typeof navigator === "undefined") return "Unknown";
  const ua = navigator.userAgent;
  if (/iPhone/.test(ua)) return "iPhone";
  if (/iPad/.test(ua)) return "iPad";
  if (/Android/.test(ua)) return "Android";
  if (/Mac/.test(ua)) return "Mac";
  if (/Windows/.test(ua)) return "Windows";
  if (/Linux/.test(ua)) return "Linux";
  return "Web";
}

export function useActiveSessions() {
  const { user } = useAuth();
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    if (!user) { setSessions([]); setLoading(false); return; }
    const { data } = await supabase
      .from("active_sessions")
      .select("*")
      .eq("user_id", user.id)
      .order("last_active_at", { ascending: false });
    setSessions((data ?? []) as Session[]);
    setLoading(false);
  }, [user]);

  // Register current session once
  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    (async () => {
      const existingId = typeof window !== "undefined" ? localStorage.getItem(SESSION_KEY) : null;
      if (existingId) {
        // Update last_active
        await supabase
          .from("active_sessions")
          .update({ last_active_at: new Date().toISOString() })
          .eq("id", existingId)
          .eq("user_id", user.id);
      } else {
        const { data } = await supabase
          .from("active_sessions")
          .insert({
            user_id: user.id,
            device_name: getDeviceName(),
            device_type: "web",
            user_agent: typeof navigator !== "undefined" ? navigator.userAgent.slice(0, 255) : null,
            is_current: true,
          })
          .select("id")
          .single();
        if (data && typeof window !== "undefined") localStorage.setItem(SESSION_KEY, data.id);
      }
      if (!cancelled) load();
    })();
    return () => { cancelled = true; };
  }, [user, load]);

  const revoke = async (id: string) => {
    const currentId = typeof window !== "undefined" ? localStorage.getItem(SESSION_KEY) : null;
    if (id === currentId) { toast.error("Mevcut oturumu kapatamazsınız (önce çıkış yapın)"); return; }
    const { error } = await supabase.from("active_sessions").delete().eq("id", id);
    if (error) { toast.error(error.message); return; }
    toast.success("Cihaz oturumu kapatıldı");
    load();
  };

  return { sessions, loading, revoke, refresh: load, currentSessionId: typeof window !== "undefined" ? localStorage.getItem(SESSION_KEY) : null };
}

