/**
 * useAmelLog — Amel Defteri (ritual activity log) hook.
 *
 * Logs and aggregates user spiritual actions (tesbih, namaz, kuran, dua, oruç).
 * All writes RLS-scoped to auth.uid(). Optimistic local count for the
 * "today" totals so the Tasbih and dashboard widgets feel instant.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export type AmelKind = "tesbih" | "namaz" | "kuran" | "dua" | "oruc";

export interface AmelTotals {
  tesbih: number;
  namaz: number;
  kuran: number;
  dua: number;
  oruc: number;
}

const EMPTY: AmelTotals = { tesbih: 0, namaz: 0, kuran: 0, dua: 0, oruc: 0 };

function startOfDayIso(): string {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d.toISOString();
}

export function useAmelLog() {
  const [today, setToday] = useState<AmelTotals>(EMPTY);
  const [userId, setUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async (uid: string) => {
    const { data, error } = await supabase
      .from("amel_logs")
      .select("kind,count")
      .eq("user_id", uid)
      .gte("logged_at", startOfDayIso());
    if (error || !data) {
      setToday(EMPTY);
      return;
    }
    const totals: AmelTotals = { ...EMPTY };
    for (const row of data) {
      const k = row.kind as AmelKind;
      if (k in totals) totals[k] += row.count ?? 1;
    }
    setToday(totals);
  }, []);

  useEffect(() => {
    let mounted = true;
    supabase.auth.getUser().then(({ data }) => {
      if (!mounted) return;
      const uid = data.user?.id ?? null;
      setUserId(uid);
      if (uid) refresh(uid).finally(() => setLoading(false));
      else setLoading(false);
    });
    return () => {
      mounted = false;
    };
  }, [refresh]);

  const log = useCallback(
    async (kind: AmelKind, count = 1, note?: string) => {
      // Optimistic local update
      setToday((t) => ({ ...t, [kind]: t[kind] + count }));
      if (!userId) return;
      await supabase.from("amel_logs").insert({
        user_id: userId,
        kind,
        count,
        note: note ?? null,
      });
    },
    [userId],
  );

  return { today, loading, log, signedIn: !!userId };
}

