import { useEffect } from "react";
import { useRouter } from "@tanstack/react-router";
import { isNative } from "@/lib/native";

/**
 * Android donanım "Geri" tuşunu router history'ye bağlar.
 * - Modal/dialog açıkken: ESC eventi tetikler (Radix ESC ile kapanır)
 * - Geçmişte sayfa varsa: bir önceki sayfaya döner
 * - Ana sayfadaysa: uygulama minimize olur (App.minimizeApp), KAPANMAZ
 *
 * Lovable preview'da no-op. Sadece Android APK içinde aktif.
 */
export function useAndroidBackButton() {
  const router = useRouter();

  useEffect(() => {
    if (!isNative()) return;

    let cleanup: (() => void) | null = null;

    (async () => {
      try {
        const { App } = await import("@capacitor/app");
        const handle = await App.addListener("backButton", async () => {
          // 1) Açık modal var mı? (Radix data-state="open")
          const openModal = document.querySelector(
            '[role="dialog"][data-state="open"], [data-state="open"][role="alertdialog"]',
          );
          if (openModal) {
            document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape" }));
            return;
          }

          // 2) Router history'de geri gidilebilir sayfa var mı?
          const canGoBack = window.history.length > 1 && router.state.location.pathname !== "/";
          if (canGoBack) {
            router.history.back();
            return;
          }

          // 3) Ana sayfadaysa uygulamayı KAPATMA, minimize et
          try {
            await App.minimizeApp();
          } catch {
            // minimizeApp her zaman desteklenmeyebilir; bu durumda sessizce geç
          }
        });

        cleanup = () => handle.remove();
      } catch (e) {
        console.warn("Android back button listener failed", e);
      }
    })();

    return () => {
      cleanup?.();
    };
  }, [router]);
}

