/**
 * useAudioAmplitude — Live RMS amplitude (0..1) from either:
 *   • the user's microphone (when `mode === "mic"`), or
 *   • a given <audio> element (when `mode === "element"` + `audioEl` provided).
 *
 * Returns a ref whose `.current` is updated every animation frame, plus a
 * `level` state that is throttled to ~30Hz for cheap React renders.
 *
 * Lazily allocates a single shared AudioContext. Cleans up source/analyser
 * on unmount or `enabled=false`.
 */
import { useEffect, useRef, useState } from "react";

type Mode = "mic" | "element" | "off";

interface Opts {
  mode: Mode;
  enabled: boolean;
  audioEl?: HTMLAudioElement | null;
}

let _sharedCtx: AudioContext | null = null;
function getCtx(): AudioContext | null {
  if (typeof window === "undefined") return null;
  const Ctor =
    (window as any).AudioContext || (window as any).webkitAudioContext;
  if (!Ctor) return null;
  if (!_sharedCtx) _sharedCtx = new Ctor();
  return _sharedCtx;
}

const elementSourceCache = new WeakMap<HTMLAudioElement, MediaElementAudioSourceNode>();

export function useAudioAmplitude({ mode, enabled, audioEl }: Opts) {
  const levelRef = useRef(0);
  const [level, setLevel] = useState(0);

  useEffect(() => {
    if (!enabled || mode === "off") {
      levelRef.current = 0;
      setLevel(0);
      return;
    }
    const ctx = getCtx();
    if (!ctx) return;

    let cancelled = false;
    let raf: number | null = null;
    let analyser: AnalyserNode | null = null;
    let micStream: MediaStream | null = null;
    let micSource: MediaStreamAudioSourceNode | null = null;

    const setup = async () => {
      try {
        if (ctx.state === "suspended") await ctx.resume();
        analyser = ctx.createAnalyser();
        analyser.fftSize = 512;
        analyser.smoothingTimeConstant = 0.75;

        if (mode === "mic") {
          micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
          if (cancelled) return;
          micSource = ctx.createMediaStreamSource(micStream);
          micSource.connect(analyser);
        } else if (mode === "element" && audioEl) {
          let src = elementSourceCache.get(audioEl);
          if (!src) {
            src = ctx.createMediaElementSource(audioEl);
            elementSourceCache.set(audioEl, src);
          }
          src.connect(analyser);
          src.connect(ctx.destination);
        } else {
          return;
        }

        const data = new Uint8Array(analyser.frequencyBinCount);
        let lastSet = 0;
        const tick = () => {
          if (!analyser || cancelled) return;
          analyser.getByteFrequencyData(data);
          // RMS over low-mid bins (voice range)
          let sum = 0;
          const n = Math.min(64, data.length);
          for (let i = 0; i < n; i++) {
            const v = data[i] / 255;
            sum += v * v;
          }
          const rms = Math.sqrt(sum / n);
          // Boost so soft speech reads visibly
          const boosted = Math.min(1, rms * 2.4);
          levelRef.current = boosted;
          const now = performance.now();
          if (now - lastSet > 33) {
            lastSet = now;
            setLevel(boosted);
          }
          raf = requestAnimationFrame(tick);
        };
        raf = requestAnimationFrame(tick);
      } catch (e) {
        console.warn("[useAudioAmplitude] setup failed", e);
      }
    };
    setup();

    return () => {
      cancelled = true;
      if (raf != null) cancelAnimationFrame(raf);
      try { micSource?.disconnect(); } catch {}
      try { analyser?.disconnect(); } catch {}
      try { micStream?.getTracks().forEach((t) => t.stop()); } catch {}
      levelRef.current = 0;
      setLevel(0);
    };
  }, [mode, enabled, audioEl]);

  return { level, levelRef };
}

