  listener_count: number;
  created_at: string;
}

export interface AudioParticipant {
  id: string;
  room_id: string;
  user_id: string;
  role: string;
  joined_at: string;
}

export const AUDIO_CATEGORIES = [
  { value: "general", label: "Genel" },
  { value: "music", label: "Müzik" },
  { value: "culture", label: "Kültür" },
  { value: "politics", label: "Siyaset" },
  { value: "education", label: "Eğitim" },
  { value: "tech", label: "Teknoloji" },
  { value: "entertainment", label: "Eğlence" },
  { value: "sports", label: "Spor" },
];

export function useAudioRooms(userId?: string) {
  const [rooms, setRooms] = useState<AudioRoom[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchRooms = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from("audio_rooms")
      .select("*")
      .eq("is_active", true)
      .order("created_at", { ascending: false });

    if (!error && data) setRooms(data);
    setLoading(false);
  }, []);

  useEffect(() => {
    fetchRooms();

    const channel = supabase
      .channel("audio-rooms-realtime")
      .on("postgres_changes", { event: "*", schema: "public", table: "audio_rooms" }, () => fetchRooms())
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [fetchRooms]);

  const createRoom = async (room: {
    title: string;
    description?: string;
    category: string;
    room_type: string;
    city: string;
    audio_url?: string;
    cover_url?: string;
    duration?: number;
  }) => {
    if (!userId) return;
    const { error } = await supabase.from("audio_rooms").insert({
      ...room,
      creator_id: userId,
      is_live: room.room_type === "live",
    });
    if (error) {
      toast.error("Oda oluşturulamadı");
      console.error(error);
    } else {
      toast.success("Sesli oda oluşturuldu!");
      fetchRooms();
    }
  };

  const joinRoom = async (roomId: string) => {
    if (!userId) return;
    const { error } = await supabase.from("audio_room_participants").upsert({
      room_id: roomId,
      user_id: userId,
      role: "listener",
    }, { onConflict: "room_id,user_id" });
    if (error) console.error(error);
  };

  const leaveRoom = async (roomId: string) => {
    if (!userId) return;
    await supabase.from("audio_room_participants")
      .delete()
      .eq("room_id", roomId)
      .eq("user_id", userId);
  };

  const getParticipants = async (roomId: string): Promise<AudioParticipant[]> => {
    const { data } = await supabase
      .from("audio_room_participants")
      .select("*")
      .eq("room_id", roomId);
    return data || [];
  };

  const deleteRoom = async (roomId: string) => {
    if (!userId) return;
    const { error } = await supabase.from("audio_rooms").delete().eq("id", roomId).eq("creator_id", userId);
    if (error) toast.error("Silinemedi");
    else { toast.success("Oda silindi"); fetchRooms(); }
  };

  return { rooms, loading, createRoom, joinRoom, leaveRoom, getParticipants, deleteRoom, refetch: fetchRooms };
}

