import { useCallback, useEffect, useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";
import { isNative } from "@/lib/native";

const STORAGE_KEY = "jiyan_biometric_enabled";
const USER_KEY = "jiyan_biometric_user";

/**
 * Privacy-First Biometric hook.
 * - Stores ONLY a boolean flag + user id locally (no biometric data ever leaves device).
 * - Web: WebAuthn platform authenticator (Face ID / Touch ID / Windows Hello).
 * - Android APK (Capacitor): @aparajita/capacitor-biometric-auth (Fingerprint / Face Unlock).
 */
export function useBiometric() {
  const { user } = useAuth();
  const [enabled, setEnabled] = useState(false);
  const [supported, setSupported] = useState(false);
  const [secureContext, setSecureContext] = useState(false);
  const [checking, setChecking] = useState(true);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      if (typeof window === "undefined") return;

      // --- Native (Android APK) yolu ---
      if (isNative()) {
        if (!cancelled) setSecureContext(true);
        try {
          const { BiometricAuth } = await import("@aparajita/capacitor-biometric-auth");
          const info = await BiometricAuth.checkBiometry();
          if (!cancelled) {
            setSupported(!!info.isAvailable);
            setChecking(false);
          }
        } catch {
          if (!cancelled) {
            setSupported(false);
            setChecking(false);
          }
        }
        return;
      }

      // --- Web (PWA) yolu — WebAuthn ---
      const isSecure = window.isSecureContext && window.location.protocol === "https:";
      if (!cancelled) setSecureContext(isSecure);

      if (!isSecure || !window.PublicKeyCredential) {
        if (!cancelled) {
          setSupported(false);
          setChecking(false);
        }
        return;
      }

      try {
        const ok = await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable?.();
        if (!cancelled) {
          setSupported(!!ok);
          setChecking(false);
        }
      } catch {
        if (!cancelled) {
          setSupported(false);
          setChecking(false);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const flag = localStorage.getItem(STORAGE_KEY) === "1";
    const storedUser = localStorage.getItem(USER_KEY);
    setEnabled(flag && (!user || storedUser === user.id));
  }, [user]);

  const enable = useCallback(async () => {
    if (!user) {
      toast.error("Önce giriş yapın");
      return false;
    }

    if (!supported || !secureContext) {
      toast.error("Biyometrik doğrulama başarısız.");
      return false;
    }

    // Native (Android APK)
    if (isNative()) {
      try {
        const { BiometricAuth } = await import("@aparajita/capacitor-biometric-auth");
        await BiometricAuth.authenticate({
          reason: "Jiyan ID kimlik doğrulama",
          androidTitle: "Jiyan",
          androidSubtitle: "Biyometrik giriş etkinleştir",
          androidConfirmationRequired: false,
          allowDeviceCredential: true,
        });
        localStorage.setItem(STORAGE_KEY, "1");
        localStorage.setItem(USER_KEY, user.id);
        setEnabled(true);
        toast.success("Biyometrik giriş aktif");
        return true;
      } catch {
        setEnabled(false);
        toast.error("Biyometrik doğrulama başarısız.");
        return false;
      }
    }

    try {
      const challenge = new Uint8Array(32);
      crypto.getRandomValues(challenge);
      const userId = new TextEncoder().encode(user.id).slice(0, 64);

      const credential = await navigator.credentials.create({
        publicKey: {
          challenge,
          rp: { name: "Jiyan ID" },
          user: {
            id: userId,
            name: user.email || "jiyan-user",
            displayName: (user.user_metadata?.display_name as string) || "Jiyan Citizen",
          },
          pubKeyCredParams: [
            { type: "public-key", alg: -7 },
            { type: "public-key", alg: -257 },
          ],
          authenticatorSelection: {
            authenticatorAttachment: "platform",
            userVerification: "required",
            residentKey: "discouraged",
          },
          timeout: 30000,
          attestation: "none",
        },
      });

      if (!credential) throw new Error("cancelled");

      localStorage.setItem(STORAGE_KEY, "1");
      localStorage.setItem(USER_KEY, user.id);
      setEnabled(true);
      toast.success("Biyometrik giriş aktif");
      return true;
    } catch {
      setEnabled(false);
      toast.error("Biyometrik doğrulama başarısız.");
      return false;
    }
  }, [secureContext, supported, user]);

  const disable = useCallback(() => {
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(USER_KEY);
    setEnabled(false);
    toast.success("Biyometrik giriş kapatıldı");
  }, []);

  const verify = useCallback(async (): Promise<boolean> => {
    if (!supported || !secureContext) return false;

    // Native (Android APK)
    if (isNative()) {
      try {
        const { BiometricAuth } = await import("@aparajita/capacitor-biometric-auth");
        await BiometricAuth.authenticate({
          reason: "Jiyan ID giriş",
          androidTitle: "Jiyan",
          androidSubtitle: "Devam etmek için doğrulayın",
          allowDeviceCredential: true,
        });
        return true;
      } catch {
        return false;
      }
    }

    try {
      const challenge = new Uint8Array(32);
      crypto.getRandomValues(challenge);
      const result = await navigator.credentials
        .get({
          publicKey: {
            challenge,
            timeout: 30000,
            userVerification: "required",
          },
        } as CredentialRequestOptions)
        .catch(() => null);

      return !!result;
    } catch {
      return false;
    }
  }, [secureContext, supported]);

  return { enabled, supported, secureContext, checking, enable, disable, verify };
}

/** Read the biometric flag without auth context (for login page). */
export function readBiometricFlag(): { enabled: boolean; userId: string | null } {
  if (typeof window === "undefined") return { enabled: false, userId: null };
  return {
    enabled: localStorage.getItem(STORAGE_KEY) === "1",
    userId: localStorage.getItem(USER_KEY),
  };
}

