import { supabase } from "@/integrations/supabase/client";

interface Booking {
  id: string;
  service_id: string;
  customer_id: string;
  provider_id: string;
  status: string;
  amount: number;
  notes: string | null;
  created_at: string;
  updated_at: string;
}

export function useBookings(userId: string | undefined) {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchBookings = useCallback(async () => {
    if (!userId) { setLoading(false); return; }
    const { data } = await supabase
      .from("bookings")
      .select("*, services(title)")
      .or(`customer_id.eq.${userId},provider_id.eq.${userId}`)
      .order("created_at", { ascending: false });
    if (data) setBookings(data.map((b: any) => ({ ...b, service_title: b.services?.title })) as any[]);

    setLoading(false);
  }, [userId]);

  useEffect(() => { fetchBookings(); }, [fetchBookings]);

  const createBooking = async (serviceId: string, providerId: string, amount: number, notes?: string) => {
    if (!userId) return null;
    const { data, error } = await supabase
      .from("bookings")
      .insert({ service_id: serviceId, customer_id: userId, provider_id: providerId, amount, notes: notes || null })
      .select()
      .single();
    if (error) return null;
    await fetchBookings();
    return data;
  };

  const updateStatus = async (bookingId: string, status: string) => {
    const { error } = await supabase
      .from("bookings")
      .update({ status })
      .eq("id", bookingId);
    if (!error) await fetchBookings();
    return !error;
  };

  return { bookings, loading, createBooking, updateStatus, refetch: fetchBookings };
}

