/**
 * useCemaatPulseNotifier — Sovereign-unique notification.
 *
 * Subscribes globally to `global_tesbih` realtime updates. Every time the
 * cemaat's TOTAL crosses a milestone (1k, 5k, 10k, 50k, 100k, 500k, 1M…),
 * fires a gold toast + haptic burst + ritual chime so every user feels the
 * collective heartbeat regardless of which page they're on.
 *
 * Mounted once globally in __root.
 */
import { useEffect, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

const MILESTONES = [
  100, 500, 1000, 5000, 10_000, 50_000, 100_000, 500_000,
  1_000_000, 5_000_000, 10_000_000,
];
const STORAGE_KEY = "jiyan.cemaat.lastMilestone";

function nextMilestone(total: number): number | null {
  for (const m of MILESTONES) if (total < m) return m;
  return null;
}

function chime() {
  try {
    const AC = (window.AudioContext || (window as any).webkitAudioContext) as typeof AudioContext;
    const ctx = new AC();
    const now = ctx.currentTime;
    [880, 1320, 1760].forEach((f, i) => {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = "sine";
      o.frequency.value = f;
      g.gain.setValueAtTime(0, now + i * 0.12);
      g.gain.linearRampToValueAtTime(0.18, now + i * 0.12 + 0.04);
      g.gain.exponentialRampToValueAtTime(0.001, now + i * 0.12 + 0.9);
      o.connect(g).connect(ctx.destination);
      o.start(now + i * 0.12);
      o.stop(now + i * 0.12 + 1);
    });
    setTimeout(() => void ctx.close(), 1500);
  } catch {
    /* ignore */
  }
}

export function useCemaatPulseNotifier() {
  const totalRef = useRef<number>(0);
  const lastFiredRef = useRef<number>(
    typeof localStorage !== "undefined" ? Number(localStorage.getItem(STORAGE_KEY) ?? 0) : 0,
  );

  useEffect(() => {
    let mounted = true;
    let ch: ReturnType<typeof supabase.channel> | null = null;
    let retry: number | null = null;
    let attempts = 0;

    const refreshTotal = async () => {
      const { data } = await supabase.from("global_tesbih").select("total");
      if (!mounted) return;
      totalRef.current = ((data ?? []) as Array<{ total: number }>)
        .reduce((a, x) => a + Number(x.total ?? 0), 0);
    };

    const fireIfMilestone = (newTotal: number) => {
      const target = nextMilestone(lastFiredRef.current);
      if (target == null) return;
      if (newTotal < target) return;
      lastFiredRef.current = target;
      try { localStorage.setItem(STORAGE_KEY, String(target)); } catch { /* ignore */ }

      try { navigator.vibrate?.([20, 60, 20, 60, 30]); } catch { /* ignore */ }
      chime();
      toast(`✦ Cemaat ${target.toLocaleString()} zikre ulaştı`, {
        description: "Sovereign topluluk birlikte bir kalp atışı bıraktı.",
        duration: 6000,
        style: {
          background: "linear-gradient(180deg, rgba(20,14,4,0.96), rgba(8,6,2,0.96))",
          border: "1px solid rgba(255,215,90,0.6)",
          color: "#FFF6D9",
          boxShadow: "0 0 32px rgba(212,175,55,0.4)",
        },
      });
    };

    const connect = () => {
      ch = supabase
        .channel(`cemaat-pulse-${Date.now()}`)
        .on(
          "postgres_changes",
          { event: "UPDATE", schema: "public", table: "global_tesbih" },
          (p) => {
            const old = (p.old as { total?: number } | null)?.total ?? 0;
            const next = (p.new as { total?: number } | null)?.total ?? 0;
            const delta = Math.max(0, next - old);
            if (delta <= 0) return;
            totalRef.current += delta;
            fireIfMilestone(totalRef.current);
          },
        )
        .subscribe((s) => {
          // Only retry on hard errors. "CLOSED" fires when WE remove the
          // channel, so reacting to it here would cause infinite recursion
          // (removeChannel → onClose → CLOSED → removeChannel → ...).
          if (s === "CHANNEL_ERROR" || s === "TIMED_OUT") {
            const delay = Math.min(20_000, 1500 * 2 ** attempts);
            attempts += 1;
            const dead = ch;
            ch = null;
            if (dead) void supabase.removeChannel(dead);
            retry = window.setTimeout(() => mounted && connect(), delay);
          } else if (s === "SUBSCRIBED") {
            attempts = 0;
            void refreshTotal();
          }
        });
    };

    void refreshTotal().then(() => {
      // If the stored milestone is way behind reality, snap forward silently.
      if (lastFiredRef.current === 0 && totalRef.current > 0) {
        const last = [...MILESTONES].reverse().find((m) => totalRef.current >= m) ?? 0;
        lastFiredRef.current = last;
        try { localStorage.setItem(STORAGE_KEY, String(last)); } catch { /* ignore */ }
      }
    });
    connect();

    return () => {
      mounted = false;
      if (retry) clearTimeout(retry);
      if (ch) void supabase.removeChannel(ch);
    };
  }, []);
}

