import { useState, useEffect, useCallback, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import type { RealtimeChannel } from "@supabase/supabase-js";

interface ChatMessage {
  id: string;
  room_id: string;
  sender_id: string;
  content: string;
  created_at: string;
  self_destruct_at: string | null;
  is_ghost: boolean;
  message_type: string;
  media_url: string | null;
  file_name: string | null;
  file_size: number | null;
  is_sealed?: boolean;
  sealed_at?: string | null;
  sealed_by?: string | null;
  sender?: { display_name: string; avatar_url: string | null };
}

/**
 * Mühürle (Seal) — pin + verify a message and write a permanent honor_ledger
 * entry. Wraps the `seal_chat_message` Postgres RPC. Toggles: calling on an
 * already-sealed message unseals it (sealer or admin only).
 */
export async function sealChatMessage(messageId: string) {
  const { data, error } = await supabase.rpc("seal_chat_message" as never, {
    _message_id: messageId,
  } as never);
  if (error) throw error;
  return data as { sealed: boolean; message_id: string; sealed_at?: string; sealed_by?: string };
}

interface ChatRoom {
  id: string;
  name: string | null;
  type: string;
  city: string | null;
  is_ghost_mode: boolean;
  created_at: string;
  is_forum?: boolean;
  is_topic?: boolean;
  parent_room_id?: string | null;
  topic_icon?: string | null;
  topic_color?: string | null;
  topic_order?: number;
  last_message?: string;
  last_message_time?: string;
  unread_count?: number;
  is_member?: boolean;
  members?: { user_id: string; display_name: string; is_online: boolean }[];
}

export function useChat(userId: string | undefined) {
  const [rooms, setRooms] = useState<ChatRoom[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchRooms = useCallback(async () => {
    if (!userId) return;
    const { data } = await supabase
      .from("chat_rooms")
      .select("*")
      .order("created_at", { ascending: false });

    if (!data) { setLoading(false); return; }

    // Enrich rooms with last message, unread count, and member info
    const enriched = await Promise.all(
      data.map(async (room) => {
        // Check membership
        const { data: membership } = await supabase
          .from("chat_members")
          .select("user_id")
          .eq("room_id", room.id)
          .eq("user_id", userId)
          .maybeSingle();
        const isMember = !!membership;

        // Skip enrichment for non-member rooms
        if (!isMember) {
          return {
            ...room,
            last_message: "",
            last_message_time: room.created_at,
            unread_count: 0,
            is_member: false,
            members: [],
          } as ChatRoom;
        }

        // Last message
        const { data: lastMsgs } = await supabase
          .from("chat_messages")
          .select("content, created_at, message_type")
          .eq("room_id", room.id)
          .order("created_at", { ascending: false })
          .limit(1);

        const lastMsg = lastMsgs?.[0];
        let lastMessageText = lastMsg?.content || "";
        if (lastMsg?.message_type === "audio") lastMessageText = "🎤 Sesli mesaj";
        else if (lastMsg?.message_type === "image") lastMessageText = "📷 Fotoğraf";
        else if (lastMsg?.message_type === "video") lastMessageText = "🎬 Video";
        else if (lastMsg?.message_type === "file") lastMessageText = "📎 Dosya";
        else if (lastMsg?.message_type === "location") lastMessageText = "📍 Konum";

        // Unread count
        const { data: readMsgs } = await supabase
          .from("message_reads")
          .select("message_id")
          .eq("user_id", userId);
        const readIds = (readMsgs || []).map((r) => r.message_id);

        let unreadQuery = supabase
          .from("chat_messages")
          .select("id", { count: "exact", head: true })
          .eq("room_id", room.id)
          .neq("sender_id", userId);

        if (readIds.length > 0) {
          unreadQuery = unreadQuery.not("id", "in", `(${readIds.join(",")})`);
        }

        const { count } = await unreadQuery;

        // Members with online status (for DMs)
        let members: ChatRoom["members"] = [];
        if (room.type === "direct") {
          const { data: memberData } = await supabase
            .from("chat_members")
            .select("user_id")
            .eq("room_id", room.id)
            .neq("user_id", userId);

          if (memberData && memberData.length > 0) {
            const otherUserId = memberData[0].user_id;
            const { data: profile } = await supabase
              .from("profiles")
              .select("user_id, display_name, is_online, avatar_url")
              .eq("user_id", otherUserId)
              .single();
            if (profile) {
              members = [{ user_id: profile.user_id, display_name: profile.display_name, is_online: profile.is_online }];
            }
          }
        }

        return {
          ...room,
          last_message: lastMessageText,
          last_message_time: lastMsg?.created_at || room.created_at,
          unread_count: count || 0,
          is_member: true,
          members,
        } as ChatRoom;
      })
    );

    // Sort by last message time
    enriched.sort((a, b) => new Date(b.last_message_time!).getTime() - new Date(a.last_message_time!).getTime());
    setRooms(enriched);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    fetchRooms();
  }, [fetchRooms]);

  return { rooms, loading, refetch: fetchRooms };
}

export function useChatMessages(roomId: string | null, userId: string | undefined) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [loading, setLoading] = useState(true);
  const [readStatus, setReadStatus] = useState<Record<string, string[]>>({}); // msgId -> userIds who read

  useEffect(() => {
    if (!roomId || !userId) return;

    const fetchMessages = async () => {
      const { data } = await supabase
        .from("chat_messages")
        .select("*")
        .eq("room_id", roomId)
        .order("created_at", { ascending: true })
        .limit(100);

      if (data) setMessages(data as ChatMessage[]);
      setLoading(false);

      // Mark all messages as read
      if (data && data.length > 0) {
        const myUnread = data.filter((m) => m.sender_id !== userId);
        if (myUnread.length > 0) {
          const inserts = myUnread.map((m) => ({ message_id: m.id, user_id: userId }));
          await supabase.from("message_reads").upsert(inserts, { onConflict: "message_id,user_id" });
        }
      }

      // Fetch read receipts for my messages
      if (data) {
        const myMsgIds = data.filter((m) => m.sender_id === userId).map((m) => m.id);
        if (myMsgIds.length > 0) {
          const { data: reads } = await supabase
            .from("message_reads")
            .select("message_id, user_id")
            .in("message_id", myMsgIds);
          if (reads) {
            const map: Record<string, string[]> = {};
            reads.forEach((r) => {
              if (!map[r.message_id]) map[r.message_id] = [];
              map[r.message_id].push(r.user_id);
            });
            setReadStatus(map);
          }
        }
      }
    };

    fetchMessages();

    const channel: RealtimeChannel = supabase
      .channel(`room:${roomId}`)
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "chat_messages", filter: `room_id=eq.${roomId}` },
        (payload) => {
          const newMsg = payload.new as ChatMessage;
          setMessages((prev) => [...prev, newMsg]);
          // Auto-mark as read if not mine
          if (newMsg.sender_id !== userId) {
            supabase.from("message_reads").upsert(
              [{ message_id: newMsg.id, user_id: userId }],
              { onConflict: "message_id,user_id" }
            );
          }
        }
      )
      .on(
        "postgres_changes",
        { event: "DELETE", schema: "public", table: "chat_messages", filter: `room_id=eq.${roomId}` },
        (payload) => {
          const deletedId = (payload.old as { id: string }).id;
          setMessages((prev) => prev.filter((m) => m.id !== deletedId));
        }
      )
      .on(
        "postgres_changes",
        { event: "UPDATE", schema: "public", table: "chat_messages", filter: `room_id=eq.${roomId}` },
        (payload) => {
          const updated = payload.new as ChatMessage;
          setMessages((prev) => prev.map((m) => (m.id === updated.id ? { ...m, ...updated } : m)));
        }
      )
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "message_reads" },
        (payload) => {
          const read = payload.new as { message_id: string; user_id: string };
          setReadStatus((prev) => {
            const existing = prev[read.message_id] || [];
            if (existing.includes(read.user_id)) return prev;
            return { ...prev, [read.message_id]: [...existing, read.user_id] };
          });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [roomId, userId]);

  const sendMessage = async (
    content: string,
    options?: {
      selfDestructSeconds?: number | null;
      isGhost?: boolean;
      messageType?: string;
      mediaUrl?: string | null;
      fileName?: string | null;
      fileSize?: number | null;
      voicePeaks?: number[] | null;
      voiceDurationMs?: number | null;
    }
  ) => {
    if (!roomId || !userId) return;
    if (!content.trim() && !options?.mediaUrl) return;

    const selfDestructAt = options?.selfDestructSeconds
      ? new Date(Date.now() + options.selfDestructSeconds * 1000).toISOString()
      : null;

    await supabase.from("chat_messages").insert({
      room_id: roomId,
      sender_id: userId,
      content: content.trim() || options?.fileName || "",
      self_destruct_at: selfDestructAt,
      is_ghost: options?.isGhost ?? false,
      message_type: options?.messageType ?? "text",
      media_url: options?.mediaUrl ?? null,
      file_name: options?.fileName ?? null,
      file_size: options?.fileSize ?? null,
      // Voice-specific metadata (null for non-audio messages)
      voice_peaks: options?.voicePeaks ?? null,
      voice_duration_ms: options?.voiceDurationMs ?? null,
    });
  };

  return { messages, loading, sendMessage, readStatus };
}

/* ─── Typing Indicator ─── */

export function useTypingIndicator(roomId: string | null, userId: string | undefined) {
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const typingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!roomId || !userId) return;

    // Listen for typing changes
    const channel = supabase
      .channel(`typing:${roomId}`)
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "typing_status", filter: `room_id=eq.${roomId}` },
        (payload) => {
          if (payload.eventType === "DELETE") return;
          const row = payload.new as { user_id: string; is_typing: boolean };
          if (row.user_id === userId) return;
          setTypingUsers((prev) => {
            if (row.is_typing) {
              return prev.includes(row.user_id) ? prev : [...prev, row.user_id];
            }
            return prev.filter((id) => id !== row.user_id);
          });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [roomId, userId]);

  const setTyping = useCallback(
    async (isTyping: boolean) => {
      if (!roomId || !userId) return;
      await supabase.from("typing_status").upsert(
        { room_id: roomId, user_id: userId, is_typing: isTyping, updated_at: new Date().toISOString() },
        { onConflict: "room_id,user_id" }
      );
    },
    [roomId, userId]
  );

  const handleTypingInput = useCallback(() => {
    setTyping(true);
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => setTyping(false), 3000);
  }, [setTyping]);

  const stopTyping = useCallback(() => {
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    setTyping(false);
  }, [setTyping]);

  return { typingUsers, handleTypingInput, stopTyping };
}

