export async function createDirectChat(userId: string, otherUserId: string) {
  const { data, error } = await supabase.rpc("create_direct_chat", {
    _user_id: userId,
    _other_user_id: otherUserId,
  });
  if (error || !data) throw new Error("Failed to create room");
  return { id: data as string };
}

export async function createGroupChat(userId: string, name: string, city: string) {
  const { data, error } = await supabase.rpc("create_group_chat", {
    _user_id: userId,
    _name: name,
    _city: city,
  });
  if (error || !data) throw new Error("Failed to create room");
  return { id: data as string };
}

export async function createGhostChat(userId: string, otherUserId: string) {
  const { data, error } = await supabase.rpc("create_ghost_chat", {
    _user_id: userId,
    _other_user_id: otherUserId,
  });
  if (error || !data) throw new Error("Failed to create ghost room");
  return { id: data as string };
}

/**
 * "Sil (benden)" — hide a single message only for the current viewer.
 * Other participants still see it. Wraps the `hide_message_for_me` RPC.
 */
export async function hideMessageForMe(messageId: string) {
  const { error } = await supabase.rpc("hide_message_for_me" as never, {
    _message_id: messageId,
  } as never);
  if (error) throw error;
}

/**
 * Fetch the message ids the current user has personally hidden, so the chat
 * view can filter them client-side.
 */
export async function fetchHiddenMessageIds(userId: string): Promise<Set<string>> {
  const { data, error } = await supabase
    .from("message_hidden_for" as never)
    .select("message_id")
    .eq("user_id" as never, userId as never);
  if (error || !data) return new Set();
  return new Set((data as unknown as { message_id: string }[]).map((r) => r.message_id));
}

/**
 * "Grubu Paylaş" — get (or auto-create) a permanent invite token for a
 * group/channel. Returns a shareable URL fragment.
 */
export async function ensureGroupInviteToken(roomId: string): Promise<string> {
  const { data, error } = await supabase.rpc("ensure_group_invite_token" as never, {
    _room_id: roomId,
  } as never);
  if (error) throw error;
  return data as unknown as string;
}

/** Join a group/channel via an invite token. */
export async function joinChatViaToken(token: string) {
  const { data, error } = await supabase.rpc("join_chat_via_token" as never, {
    _token: token,
  } as never);
  if (error) throw error;
  return data as { success: boolean; room_id?: string; error?: string };
}

export async function searchUsers(query: string) {
  if (!query.trim()) return [];

  const isKurdId = query.startsWith("+KRD");

  if (isKurdId) {
    const { data } = await supabase
      .from("profiles")
      .select("user_id, display_name, avatar_url, kurd_id, is_online, is_premium")
      .ilike("kurd_id", `%${query}%`)
      .limit(10);
    return data || [];
  }

  const { data } = await supabase
    .from("profiles")
    .select("user_id, display_name, avatar_url, kurd_id, is_online, is_premium")
    .ilike("display_name", `%${query}%`)
    .limit(10);
  return data || [];
}

