/**
 * Sohbet (group/channel) moderation hooks & RPCs.
 *
 * All admin actions are wrapped SECURITY DEFINER RPCs that auto-write to
 * `chat_audit_log`. Every action returns `{ ok, error? }` so callers can
 * surface a clean toast.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

/* ─── Types ─── */

export type ChatAuditAction =
  | "role_change"
  | "member_added"
  | "member_removed"
  | "member_left"
  | "member_muted"
  | "member_unmuted"
  | "user_banned"
  | "user_unbanned";

export interface ChatAuditEntry {
  id: string;
  room_id: string;
  actor_id: string | null;
  target_user_id: string | null;
  action: ChatAuditAction | string;
  payload: Record<string, unknown>;
  created_at: string;
  actor_name?: string | null;
  target_name?: string | null;
}

export interface BannedUser {
  id: string;
  user_id: string;
  reason: string | null;
  created_at: string;
  display_name: string | null;
  avatar_url: string | null;
  username: string | null;
  kurd_id: string | null;
}

/* ─── Action wrappers ─── */

async function rpc<T>(name: string, args: Record<string, unknown>): Promise<{ ok: true; data: T } | { ok: false; error: string }> {
  // Bypass strict RPC typing — these RPCs are added in this migration.
  const { data, error } = await supabase.rpc(name as never, args as never);
  if (error) return { ok: false, error: error.message };
  return { ok: true, data: data as T };
}

export const chatAdmin = {
  setRole: (roomId: string, target: string, role: "member" | "moderator" | "admin") =>
