/* ─── Audit log feed (room admins only) ─── */

export function useChatAuditLog(roomId: string | null, opts?: { limit?: number }) {
  const [entries, setEntries] = useState<ChatAuditEntry[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!roomId) {
      setEntries([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    const { data, error } = await supabase
      .from("chat_audit_log" as never)
      .select("id, room_id, actor_id, target_user_id, action, payload, created_at")
      .eq("room_id" as never, roomId as never)
      .order("created_at" as never, { ascending: false } as never)
      .limit(opts?.limit ?? 200);

    if (error || !data) {
      setEntries([]);
      setLoading(false);
      return;
    }

    const rows = data as unknown as ChatAuditEntry[];
    const userIds = Array.from(
      new Set(
        rows
          .flatMap((r) => [r.actor_id, r.target_user_id])
          .filter((x): x is string => !!x)
      )
    );

    const nameMap = new Map<string, string>();
    if (userIds.length > 0) {
      const { data: profs } = await supabase
        .from("profiles")
        .select("user_id, display_name")
        .in("user_id", userIds);
      (profs || []).forEach((p) => nameMap.set(p.user_id, p.display_name || "Sovereign"));
    }

    setEntries(
      rows.map((r) => ({
        ...r,
        actor_name: r.actor_id ? nameMap.get(r.actor_id) ?? null : null,
        target_name: r.target_user_id ? nameMap.get(r.target_user_id) ?? null : null,
      }))
    );
    setLoading(false);
  }, [roomId, opts?.limit]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // realtime: refresh on new audit row for this room
  useEffect(() => {
    if (!roomId) return;
    const channel = supabase
      .channel(`chat-audit-${roomId}`)
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "chat_audit_log", filter: `room_id=eq.${roomId}` },
        () => refresh()
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [roomId, refresh]);

  return { entries, loading, refresh };
}

/* ─── Banned users feed ─── */

export function useChatBans(roomId: string | null) {
  const [bans, setBans] = useState<BannedUser[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!roomId) {
      setBans([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    const { data } = await supabase
      .from("chat_member_bans" as never)
      .select("id, user_id, reason, created_at")
      .eq("room_id" as never, roomId as never)
      .order("created_at" as never, { ascending: false } as never);

    const rows = (data as unknown as { id: string; user_id: string; reason: string | null; created_at: string }[]) || [];
    if (rows.length === 0) {
      setBans([]);
      setLoading(false);
      return;
    }
    const { data: profs } = await supabase
      .from("profiles")
      .select("user_id, display_name, avatar_url, username, kurd_id")
      .in("user_id", rows.map((r) => r.user_id));
    const map = new Map((profs || []).map((p) => [p.user_id, p]));
    setBans(
      rows.map((r) => {
        const p = map.get(r.user_id);
        return {
          id: r.id,
          user_id: r.user_id,
          reason: r.reason,
          created_at: r.created_at,
          display_name: p?.display_name ?? null,
          avatar_url: p?.avatar_url ?? null,
          username: p?.username ?? null,
          kurd_id: p?.kurd_id ?? null,
        };
      })
    );
    setLoading(false);
  }, [roomId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  useEffect(() => {
    if (!roomId) return;
    const channel = supabase
      .channel(`chat-bans-${roomId}`)
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "chat_member_bans", filter: `room_id=eq.${roomId}` },
        () => refresh()
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [roomId, refresh]);

  return { bans, loading, refresh };
}

/* ─── Audit action labels (TR) ─── */

export function describeAuditAction(action: string, payload: Record<string, unknown> = {}): string {
  switch (action) {
    case "role_change": {
      const from = (payload.from as string) || "üye";
      const to = (payload.to as string) || "üye";
      return `Rol değişti: ${from} → ${to}`;
    }
    case "member_added":
      return "Üye eklendi";
    case "member_removed":
      return payload.reason ? `Üye çıkarıldı (${payload.reason})` : "Üye çıkarıldı";
    case "member_left":
      return "Üye ayrıldı";
    case "member_muted":
      return "Üye susturuldu";
    case "member_unmuted":
      return "Susturma kaldırıldı";
    case "user_banned":
      return payload.reason ? `Banlandı (${payload.reason})` : "Banlandı";
    case "user_unbanned":
      return "Ban kaldırıldı";
    default:
      return action;
  }
}

