import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";

export interface CivatProposal {
  id: string;
  title: string;
  summary: string;
  description: string;
  category: "governance" | "finance" | "culture" | "technology" | "social";
  status: "active" | "passed" | "rejected" | "expired" | "draft";
  yes_count: number;
  no_count: number;
  abstain_count: number;
  ends_at: string;
  starts_at: string;
}

export type VoteChoice = "yes" | "no" | "abstain";

export function useCivat() {
  const { user } = useAuth();
  const [proposals, setProposals] = useState<CivatProposal[]>([]);
  const [myVotes, setMyVotes] = useState<Record<string, VoteChoice>>({});
  const [loading, setLoading] = useState(true);
  const [eligible, setEligible] = useState(false);

  const fetchAll = useCallback(async () => {
    setLoading(true);
    const { data: props } = await supabase
      .from("civat_proposals")
      .select("*")
      .in("status", ["active", "passed", "rejected"])
      .order("ends_at", { ascending: true })
      .limit(50);
    setProposals((props ?? []) as CivatProposal[]);

    if (user) {
      const [{ data: votes }, { data: kyc }, { data: sig }] = await Promise.all([
        supabase
          .from("civat_votes")
          .select("proposal_id, vote")
          .eq("user_id", user.id),
        supabase
          .from("kyc_requests")
          .select("id")
          .eq("user_id", user.id)
          .eq("status", "approved")
          .limit(1)
          .maybeSingle(),
        supabase
          .from("constitution_signatures")
          .select("id")
          .eq("user_id", user.id)
          .limit(1)
          .maybeSingle(),
      ]);
      const m: Record<string, VoteChoice> = {};
      (votes ?? []).forEach((v: any) => {
        m[v.proposal_id] = v.vote as VoteChoice;
      });
      setMyVotes(m);
      setEligible(!!kyc && !!sig);
    } else {
      setMyVotes({});
      setEligible(false);
    }
    setLoading(false);
  }, [user]);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  const castVote = useCallback(
    async (proposalId: string, vote: VoteChoice) => {
      if (!user) return { ok: false, error: "login_required" };
      const existing = myVotes[proposalId];
      if (existing === vote) return { ok: true };

      const { error } = await supabase
        .from("civat_votes")
        .upsert(
          { proposal_id: proposalId, user_id: user.id, vote },
          { onConflict: "proposal_id,user_id" },
        );
      if (error) return { ok: false, error: error.message };
      setMyVotes((m) => ({ ...m, [proposalId]: vote }));
      // Optimistic count refresh
      setProposals((prev) =>
        prev.map((p) => {
          if (p.id !== proposalId) return p;
          const next = { ...p };
          if (existing) {
            (next as any)[`${existing}_count`] = Math.max(0, (next as any)[`${existing}_count`] - 1);
          }
          (next as any)[`${vote}_count`] = (next as any)[`${vote}_count`] + 1;
          return next;
        }),
      );
      return { ok: true };
    },
    [user, myVotes],
  );

  return { proposals, myVotes, loading, eligible, castVote, refresh: fetchAll };
}

