import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";

export function useConstitution() {
  const { user } = useAuth();
  const [signed, setSigned] = useState<boolean | null>(null);
  const [signatureCount, setSignatureCount] = useState(0);
  const [signatureHash, setSignatureHash] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    setLoading(true);
    const { data: countData } = await supabase.rpc("get_constitution_signature_count");
    setSignatureCount(Number(countData ?? 0));

    if (user?.id) {
      const { data } = await supabase
        .from("constitution_signatures")
        .select("signature_hash")
        .eq("user_id", user.id)
        .maybeSingle();
      setSigned(!!data);
      setSignatureHash(data?.signature_hash ?? null);
    } else {
      setSigned(false);
    }
    setLoading(false);
  }, [user?.id]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const sign = useCallback(async () => {
    if (!user?.id) throw new Error("Giriş yapmalısın");
    const { data, error } = await supabase.rpc("sign_constitution", {
      _user_id: user.id,
    });
    if (error) throw error;
    await refresh();
    return data as { success: boolean; signature_hash?: string; error?: string };
  }, [user?.id, refresh]);

  return { signed, signatureCount, signatureHash, loading, sign, refresh };
}

