import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

// ─── Yaratıcı Fonu ─────────────────────────────────────────────────────────
export interface CreatorFundPayout {
  id: string;
  user_id: string;
  period_month: string;
  total_views: number;
  total_followers: number;
  share_pct: number;
  amount_dc: number;
  paid_at: string;
}

export interface CreatorFundPool {
  id: string;
  period_month: string;
  total_dc: number;
  is_distributed: boolean;
  distributed_at: string | null;
}

export function useCreatorEligibility(userId: string | null | undefined) {
  const [eligible, setEligible] = useState(false);
  const [followers, setFollowers] = useState(0);
  const [views30d, setViews30d] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!userId) { setLoading(false); return; }
    let cancelled = false;
    (async () => {
      setLoading(true);
      const since = new Date(Date.now() - 30 * 86400000).toISOString();
      const [followsRes, viewsRes] = await Promise.all([
        supabase.from("follows").select("id", { count: "exact", head: true }).eq("following_id", userId),
        supabase.from("keka_videos").select("view_count").eq("user_id", userId).gte("created_at", since),
      ]);
      if (cancelled) return;
      const f = followsRes.count || 0;
      const v = (viewsRes.data || []).reduce((s, r: any) => s + (r.view_count || 0), 0);
      setFollowers(f);
      setViews30d(v);
      setEligible(f >= 10000 && v >= 100000);
      setLoading(false);
    })();
    return () => { cancelled = true; };
  }, [userId]);

  return { eligible, followers, views30d, loading };
}

export function useMyCreatorFundPayouts(userId: string | null | undefined) {
  const [payouts, setPayouts] = useState<CreatorFundPayout[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!userId) { setLoading(false); return; }
    (async () => {
      const { data } = await supabase
        .from("creator_fund_payouts")
        .select("*")
        .eq("user_id", userId)
        .order("period_month", { ascending: false })
        .limit(12);
      setPayouts((data || []) as any);
      setLoading(false);
    })();
  }, [userId]);

  return { payouts, loading };
}

export function useCurrentFundPool() {
  const [pool, setPool] = useState<CreatorFundPool | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    const start = new Date();
    start.setDate(1);
    const monthStr = start.toISOString().slice(0, 10);
    const { data } = await supabase
      .from("creator_fund_pool")
      .select("*")
      .eq("period_month", monthStr)
      .maybeSingle();
    setPool((data || null) as any);
    setLoading(false);
  }, []);

  useEffect(() => { refresh(); }, [refresh]);
  return { pool, loading, refresh };
}

