export function useBrandDeals(filter: "open" | "all" = "open") {
  const [deals, setDeals] = useState<BrandDeal[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    setLoading(true);
    let q = supabase.from("brand_deals").select("*").order("created_at", { ascending: false }).limit(60);
    if (filter === "open") q = q.eq("status", "open");
    const { data } = await q;
    if (!data || data.length === 0) {
      setDeals([]);
      setLoading(false);
      return;
    }
    const ids = Array.from(new Set(data.map((d: any) => d.brand_id)));
    const { data: brands } = await supabase
      .from("profiles")
      .select("user_id, display_name, avatar_url")
      .in("user_id", ids);
    const map = new Map((brands || []).map((b) => [b.user_id, b]));
    setDeals(
      data.map((d: any) => ({ ...d, brand: map.get(d.brand_id) ?? null })) as BrandDeal[],
    );
    setLoading(false);
  }, [filter]);

  useEffect(() => { refresh(); }, [refresh]);
  return { deals, loading, refresh };
}

