    if (!dealId) return;
    setLoading(true);
    const { data } = await supabase.from("brand_deal_applications")
      .select("*").eq("deal_id", dealId).order("created_at", { ascending: false });
    if (!data || data.length === 0) { setApps([]); setLoading(false); return; }
    const ids = Array.from(new Set(data.map((a: any) => a.creator_id)));
    const { data: profiles } = await supabase
      .from("profiles").select("user_id, display_name, avatar_url, kurd_id").in("user_id", ids);
    const map = new Map((profiles || []).map((p) => [p.user_id, p]));
    setApps(data.map((a: any) => ({ ...a, creator: map.get(a.creator_id) ?? null })) as any);
    setLoading(false);
  }, [dealId]);

  useEffect(() => { refresh(); }, [refresh]);
  return { apps, loading, refresh };
