import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

export type Campaign = {
  id: string;
  creator_id: string;
  title: string;
  description: string;
  category: string;
  cover_url: string | null;
  goal_amount: number;
  raised_amount: number;
  contributor_count: number;
  status: string;
  ends_at: string;
  created_at: string;
};

export function useCampaigns() {
  const [campaigns, setCampaigns] = useState<Campaign[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    const { data } = await supabase
      .from("crowdfund_campaigns")
      .select("*")
      .eq("status", "active")
      .order("created_at", { ascending: false });
    setCampaigns((data ?? []) as Campaign[]);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  return { campaigns, loading, refresh: load };
}

export function useCreateCampaign() {
  const { user } = useAuth();
  const [creating, setCreating] = useState(false);

  const create = async (input: { title: string; description: string; goal_amount: number; category?: string; cover_url?: string }) => {
    if (!user) { toast.error("Önce giriş yapın"); return null; }
    if (!input.title.trim() || input.goal_amount <= 0) { toast.error("Geçersiz veri"); return null; }
    setCreating(true);
    const { data, error } = await supabase
      .from("crowdfund_campaigns")
      .insert({
        creator_id: user.id,
        title: input.title.trim(),
        description: input.description.trim(),
        goal_amount: input.goal_amount,
        category: input.category ?? "community",
        cover_url: input.cover_url ?? null,
      })
      .select()
      .single();
    setCreating(false);
    if (error) { toast.error(error.message); return null; }
    toast.success("Kampanya oluşturuldu!");
    return data as Campaign;
  };

  return { create, creating };
}

export function useContribute() {
  const { user } = useAuth();
  const [contributing, setContributing] = useState(false);

  const contribute = async (campaignId: string, amount: number, message?: string, isAnonymous = false) => {
    if (!user) { toast.error("Önce giriş yapın"); return false; }
    if (amount <= 0) { toast.error("Geçersiz miktar"); return false; }
    setContributing(true);
    const { data, error } = await supabase.rpc("contribute_to_campaign", {
      _campaign_id: campaignId,
      _contributor_id: user.id,
      _amount: amount,
      _message: message ?? undefined,
      _is_anonymous: isAnonymous,
    });
    setContributing(false);
    if (error) { toast.error(error.message); return false; }
    const result = data as { success: boolean; error?: string };
    if (!result.success) { toast.error(result.error || "Hata"); return false; }
    toast.success(`${amount} DC gönderildi! 🙏`);
    return true;
  };

  return { contribute, contributing };
}

