import { useEffect, useState } from "react";

/**
 * Simulated DC → EUR rate.
 * Slowly fluctuates around 1.00 EUR per DC with small ticks.
 */
export function useDcRate() {
  const [rate, setRate] = useState(1.0);
  const [trend, setTrend] = useState<"up" | "down" | "flat">("flat");

  useEffect(() => {
    let mounted = true;
    const tick = () => {
      if (!mounted) return;
      setRate((prev) => {
        const delta = (Math.random() - 0.5) * 0.012; // ±0.6%
        const next = Math.max(0.92, Math.min(1.08, prev + delta));
        if (next > prev + 0.0005) setTrend("up");
        else if (next < prev - 0.0005) setTrend("down");
        else setTrend("flat");
        return parseFloat(next.toFixed(4));
      });
    };
    const interval = setInterval(tick, 4000);
    return () => {
      mounted = false;
      clearInterval(interval);
    };
  }, []);

  return { rate, trend };
}

