/**
 * useDengApproval — Faz B: Hassas eylem öncesi kullanıcının kendi Deng
 * Inbox'ına bir onay kartı düşür, kullanıcı "Onayla" / "Reddet" deyince
 * bekleyen Promise'i çöz. SMS/Email yerine Deng tek kanal.
 *
 * Akış:
 *   1) `request({ actionType, subject, body, payload, expiresInMinutes })`
 *   2) Postgres RPC `request_deng_approval` bot_approvals satırı yaratır.
 *   3) Realtime + 2sn polling ile status takip edilir.
 *   4) approved → resolve(true), rejected/expired → resolve(false).
 *
 * Hiçbir parola/2FA detayı bu hook'tan geçmez — sadece "kullanıcı bu
 * eylemi başlattı mı?" sorusuna cevap verir.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export type DengApprovalAction =
  | "login_approval"
  | "password_reset"
  | "otp_verify"
  | "payment"
  | "kyc"
  | "sso_consent"
  | "sensitive_action";

export interface RequestDengApprovalArgs {
  actionType: DengApprovalAction;
  subject: string;
  body: string;
  payload?: Record<string, any>;
  expiresInMinutes?: number;
}

export interface PendingDengApproval {
  approvalId: string;
  status: "pending" | "approved" | "rejected" | "expired";
  expiresAt: string;
}

export function useDengApproval() {
  const [pending, setPending] = useState<PendingDengApproval | null>(null);
  const [busy, setBusy] = useState(false);
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const resolveRef = useRef<((ok: boolean) => void) | null>(null);

  const cleanup = useCallback(() => {
    if (channelRef.current) {
      supabase.removeChannel(channelRef.current);
      channelRef.current = null;
    }
    if (pollRef.current) {
      clearInterval(pollRef.current);
      pollRef.current = null;
    }
  }, []);

  useEffect(() => () => cleanup(), [cleanup]);

  const settle = useCallback(
    (ok: boolean) => {
      cleanup();
      const r = resolveRef.current;
      resolveRef.current = null;
      setPending(null);
      r?.(ok);
    },
    [cleanup],
  );

  /** Yeni bir Deng onay kartı oluştur ve kullanıcının kararını bekle. */
  const request = useCallback(
    async (args: RequestDengApprovalArgs): Promise<boolean> => {
      setBusy(true);
      try {
        const { data, error } = await supabase.rpc("request_deng_approval", {
          _action_type: args.actionType,
          _subject: args.subject,
          _body: args.body,
          _payload: (args.payload ?? {}) as any,
          _expires_in_minutes: args.expiresInMinutes ?? 5,
        });
        if (error) throw error;
        const result = (data ?? {}) as {
          success?: boolean;
          approval_id?: string;
          error?: string;
        };
        if (!result.success || !result.approval_id) {
          throw new Error(result.error ?? "Deng onay oluşturulamadı");
        }

        const approvalId = result.approval_id;
        setPending({
          approvalId,
          status: "pending",
          expiresAt: new Date(
            Date.now() + (args.expiresInMinutes ?? 5) * 60_000,
          ).toISOString(),
        });

        return await new Promise<boolean>((resolve) => {
          resolveRef.current = resolve;

          // Realtime status updates
          const ch = supabase
            .channel(`deng-approval-${approvalId}`)
            .on(
              "postgres_changes",
              {
                event: "UPDATE",
                schema: "public",
                table: "bot_approvals",
                filter: `id=eq.${approvalId}`,
              },
              (payload) => {
                const newStatus = (payload.new as any)?.status;
                if (newStatus === "approved") settle(true);
                else if (newStatus === "rejected" || newStatus === "expired")
                  settle(false);
              },
            )
            .subscribe();
          channelRef.current = ch;

          // Polling fallback (2sn) — realtime gecikmesine karşı + expire kontrol
          pollRef.current = setInterval(async () => {
            const { data: poll } = await supabase.rpc(
              "get_bot_approval_status",
              { _approval_id: approvalId },
            );
            const s = (poll as any)?.status;
            if (s === "approved") settle(true);
            else if (s === "rejected" || s === "expired") settle(false);
          }, 2000);
        });
      } finally {
        setBusy(false);
      }
    },
    [settle],
  );

  /** Bekleyen onay varsa kullanıcı manuel iptal edebilir. */
  const cancel = useCallback(() => {
    settle(false);
  }, [settle]);

  return { request, cancel, pending, busy };
}

