/**
 * useDengBot — Faz A: Deng Support bot mesajları + onay (approval) akışı.
 *
 * `inbox_messages.bot_kind` doldurulmuş kayıtları "Deng Bot" olarak okur,
 * onaya bağlı ise `bot_approvals` durumunu birlikte getirir. Realtime ile
 * yeni bot mesajlarını anında yakalar (OTP, login approval, security alert).
 *
 * Onayla/Reddet butonları `decide_bot_approval` RPC'sini çağırır — bu RPC
 * SECURITY DEFINER'dır ve sadece kayıt sahibi karar verebilir.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export type DengBotKind =
  | "otp"
  | "approval"
  | "info"
  | "call_log"
  | "security_alert"
  | "system";

export interface DengBotMessage {
  id: string;
  recipient_id: string;
  subject: string;
  body: string;
  bot_kind: DengBotKind;
  metadata: Record<string, any>;
  is_read: boolean;
  created_at: string;
  approval?: {
    id: string;
    action_type: string;
    status: "pending" | "approved" | "rejected" | "expired";
    expires_at: string;
    payload: Record<string, any>;
  } | null;
}

export function useDengBot(userId: string | undefined) {
  const [messages, setMessages] = useState<DengBotMessage[]>([]);
  const [loading, setLoading] = useState(true);
  const [latest, setLatest] = useState<DengBotMessage | null>(null);

  const fetch = useCallback(async () => {
    if (!userId) {
      setLoading(false);
      return;
    }
    const { data: msgs } = await supabase
      .from("inbox_messages")
      .select("id, recipient_id, subject, body, bot_kind, metadata, is_read, created_at")
      .eq("recipient_id", userId)
      .not("bot_kind", "is", null)
      .order("created_at", { ascending: false })
      .limit(50);

    const list = (msgs ?? []) as any[];
    if (list.length === 0) {
      setMessages([]);
      setLatest(null);
      setLoading(false);
      return;
    }

    const ids = list.map((m) => m.id);
    const { data: approvals } = await supabase
      .from("bot_approvals")
      .select("id, inbox_message_id, action_type, status, expires_at, payload")
      .in("inbox_message_id", ids);

    const apMap = new Map<string, any>();
    (approvals ?? []).forEach((a: any) => apMap.set(a.inbox_message_id, a));

    const merged: DengBotMessage[] = list.map((m) => ({
      ...m,
      bot_kind: m.bot_kind as DengBotKind,
      metadata: m.metadata ?? {},
      approval: apMap.get(m.id)
        ? {
            id: apMap.get(m.id).id,
            action_type: apMap.get(m.id).action_type,
            status: apMap.get(m.id).status,
            expires_at: apMap.get(m.id).expires_at,
            payload: apMap.get(m.id).payload ?? {},
          }
        : null,
    }));
    setMessages(merged);
    setLatest(merged[0] ?? null);
    setLoading(false);
  }, [userId]);

  const fetchRef = useRef(fetch);
  useEffect(() => {
    fetchRef.current = fetch;
  }, [fetch]);

  useEffect(() => {
    fetch();
  }, [fetch]);

  // Realtime — new bot messages + approval status changes
  useEffect(() => {
    if (!userId) return;
    const channelName = `deng-bot-${userId}-${Math.random().toString(36).slice(2, 8)}`;
    const ch = supabase.channel(channelName);
    ch.on(
      "postgres_changes" as any,
      {
        event: "INSERT",
        schema: "public",
        table: "inbox_messages",
        filter: `recipient_id=eq.${userId}`,
      },
      () => fetchRef.current(),
    )
      .on(
        "postgres_changes" as any,
        {
          event: "UPDATE",
          schema: "public",
          table: "bot_approvals",
          filter: `user_id=eq.${userId}`,
        },
        () => fetchRef.current(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(ch);
    };
  }, [userId]);

  const decide = useCallback(
    async (approvalId: string, decision: "approved" | "rejected") => {
      const { data, error } = await supabase.rpc("decide_bot_approval", {
        _approval_id: approvalId,
        _decision: decision,
      });
      if (error) throw error;
      await fetch();
      return data as { success: boolean; status?: string; error?: string };
    },
    [fetch],
  );

  const markRead = useCallback(async (id: string) => {
    await supabase.from("inbox_messages").update({ is_read: true }).eq("id", id);
    setMessages((prev) =>
      prev.map((m) => (m.id === id ? { ...m, is_read: true } : m)),
    );
  }, []);

  const pendingApprovals = messages.filter(
    (m) => m.approval && m.approval.status === "pending",
  );

  return {
    messages,
    latest,
    pendingApprovals,
    loading,
    decide,
    markRead,
    refetch: fetch,
  };
}

