import { useCallback, useEffect, useRef, useState } from "react";

/**
 * Dengbêj TTS — narrates manifesto step text in the voice of a legendary
 * dengbêj (Şivan Perver-like), routed through a cinematic vocal chain:
 *
 *   source → low-shelf (chest warmth)
 *          → presence peak (clarity 2.8 kHz)
 *          → tanh saturation (epic character)
 *          → BIG hall reverb (sacred cyber-temple, 4.5s tail)
 *          → bass analyser → Vibration API (haptic sync)
 *          → destination
 *
 * Strategy:
 *   1. Try edge function `dengbej-tts` (Lovable AI Gateway → OpenAI mp3).
 *   2. Pipe the audio through the chain above.
 *   3. If the function returns `{ fallback: true }` or fails, fall back to
 *      the browser's built-in SpeechSynthesis API with deep pitch.
 *
 * Per-step audio buffers are cached as blob URLs for the session.
 *
 * --- Subtitle / progress sync ---
 * For real audio playback we use `audio.currentTime` / `audio.duration` and
 * pre-segment the spoken script into sentence-level cues with start/end times
 * proportional to character count (good enough for a karaoke-style highlight).
 *
 * For the SpeechSynthesis fallback we use the `boundary` event to advance
 * cues per sentence in real time, plus an estimated total duration based on
 * average words-per-minute so we can still surface a progress bar.
 */

const TTS_URL = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/dengbej-tts`;
const PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string;

type Status = "idle" | "loading" | "playing" | "paused" | "error";

export interface SubtitleCue {
  text: string;
  start: number; // seconds, relative to playback start
  end: number;
}

export interface SoundscapeSettings {
  /** 0..1 — scales reverb wet level + saturation drive on the vocal chain. */
  intensity: number;
  /** When false, no Vibration API calls are made. */
  hapticEnabled: boolean;
}

const DEFAULT_SETTINGS: SoundscapeSettings = { intensity: 0.6, hapticEnabled: true };

// Build a stereo impulse response for big convolution reverb (sacred hall).
function makeImpulseResponse(ctx: AudioContext, durationSec = 4.5, decay = 3.2) {
  const rate = ctx.sampleRate;
  const length = Math.floor(rate * durationSec);
  const impulse = ctx.createBuffer(2, length, rate);
  for (let ch = 0; ch < 2; ch++) {
    const data = impulse.getChannelData(ch);
    for (let i = 0; i < length; i++) {
      // Slight pre-delay shape: first 30ms is silent for clarity
      const preDelaySamples = Math.floor(rate * 0.03);
      const t = i < preDelaySamples ? 0 : (i - preDelaySamples) / (length - preDelaySamples);
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, decay);
    }
  }
  return impulse;
}

interface VocalChain {
  context: AudioContext;
  analyser: AnalyserNode; // bass envelope source for haptics
}

function buildVocalBoosterChain(audio: HTMLAudioElement, intensity: number): VocalChain {
  const AC =
    window.AudioContext ||
    (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
  const ctx = new AC();
  const source = ctx.createMediaElementSource(audio);

  // Low shelf — chest warmth
  const lowShelf = ctx.createBiquadFilter();
  lowShelf.type = "lowshelf";
  lowShelf.frequency.value = 240;
  lowShelf.gain.value = 6.0;

  // High-pass to remove sub-rumble below 70Hz
  const hp = ctx.createBiquadFilter();
  hp.type = "highpass";
  hp.frequency.value = 70;

  // Presence peak — clarity around 2.8 kHz
  const presence = ctx.createBiquadFilter();
  presence.type = "peaking";
  presence.frequency.value = 2800;
  presence.Q.value = 1.0;
  presence.gain.value = 3.5;

  // Soft saturation via WaveShaper for "epic" character — drive scales with intensity
  const shaper = ctx.createWaveShaper();
  const drive = 1.2 + intensity * 0.9; // 1.2..2.1
  const curve = new Float32Array(1024);
  for (let i = 0; i < curve.length; i++) {
    const x = (i * 2) / curve.length - 1;
    curve[i] = Math.tanh(x * drive);
  }
  shaper.curve = curve;
  shaper.oversample = "2x";

  // Big hall reverb send — wet level scales with intensity (0.15 .. 0.85)
  const dryGain = ctx.createGain();
  dryGain.gain.value = 0.62;
  const wetGain = ctx.createGain();
  wetGain.gain.value = 0.15 + intensity * 0.7;
  const convolver = ctx.createConvolver();
  convolver.buffer = makeImpulseResponse(ctx, 4.5, 3.2);

  // Output makeup
  const makeup = ctx.createGain();
  makeup.gain.value = 1.05;

  // Analyser tap (post-saturation, pre-reverb) — drives haptic vibration
  const analyser = ctx.createAnalyser();
  analyser.fftSize = 256;
  analyser.smoothingTimeConstant = 0.7;

  // Wire up
  source.connect(hp);
  hp.connect(lowShelf);
  lowShelf.connect(presence);
  presence.connect(shaper);
  shaper.connect(analyser);
  shaper.connect(dryGain).connect(makeup);
  shaper.connect(convolver).connect(wetGain).connect(makeup);
  makeup.connect(ctx.destination);

  return { context: ctx, analyser };
}

/**
 * Split a full script into sentence-level cues. We keep the gold-box `quote`
 * as its own opening cue (with a small ceremonial pause baked in), then split
 * the body on sentence punctuation.
 */
function buildCues(text: string, quote?: string): { segments: string[]; weights: number[] } {
  const segments: string[] = [];
  const weights: number[] = [];

  if (quote && quote.trim().length > 0) {
    const q = quote.trim();
    segments.push(q);
    // Quote is recited with deliberate pacing → +30% weight, plus a short pause.
    weights.push(q.length * 1.3 + 40);
  }

  // Split on sentence-ending punctuation but keep the punctuation glued.
  const parts = text
    .replace(/\s+/g, " ")
    .trim()
    .split(/(?<=[.!?…])\s+(?=[A-ZÇĞİÖŞÜA-Za-zÂÎÊÛ])/u);
  for (const p of parts) {
    const trimmed = p.trim();
    if (!trimmed) continue;
    segments.push(trimmed);
    weights.push(Math.max(20, trimmed.length));
  }

  return { segments, weights };
}

function cuesFromDuration(
  segments: string[],
  weights: number[],
  totalSec: number,
): SubtitleCue[] {
  const total = weights.reduce((a, b) => a + b, 0) || 1;
  let acc = 0;
  return segments.map((seg, i) => {
    const start = (acc / total) * totalSec;
    acc += weights[i];
    const end = (acc / total) * totalSec;
    return { text: seg, start, end };
  });
}

export function useDengbejTTS() {
  const [status, setStatus] = useState<Status>("idle");
  const [activeKey, setActiveKey] = useState<string | null>(null);

  // Subtitle / progress state — surfaced to UI for the captions strip + bar
  const [subtitle, setSubtitle] = useState<string>("");
  const [progress, setProgress] = useState<number>(0); // 0..1
  const [currentTime, setCurrentTime] = useState<number>(0); // seconds
  const [duration, setDuration] = useState<number>(0); // seconds (estimated for browser TTS)

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const cacheRef = useRef<Map<string, string>>(new Map()); // key -> blob URL
  const utterRef = useRef<SpeechSynthesisUtterance | null>(null);
  const chainCtxRef = useRef<AudioContext | null>(null);
  const hapticRafRef = useRef<number | null>(null);
  const hapticLastTsRef = useRef<number>(0);
  const cuesRef = useRef<SubtitleCue[]>([]);
  const tickRafRef = useRef<number | null>(null);
  const browserStartRef = useRef<number>(0);
  const settingsRef = useRef<SoundscapeSettings>(DEFAULT_SETTINGS);

  const setSettings = useCallback((s: SoundscapeSettings) => {
    settingsRef.current = s;
  }, []);

  const stopHaptics = useCallback(() => {
    if (hapticRafRef.current !== null) {
      cancelAnimationFrame(hapticRafRef.current);
      hapticRafRef.current = null;
    }
  }, []);

  const stopTick = useCallback(() => {
    if (tickRafRef.current !== null) {
      cancelAnimationFrame(tickRafRef.current);
      tickRafRef.current = null;
    }
  }, []);

  const stop = useCallback(() => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
    if (typeof window !== "undefined" && window.speechSynthesis) {
      window.speechSynthesis.cancel();
    }
    stopHaptics();
    stopTick();
    setStatus("idle");
    setActiveKey(null);
    setSubtitle("");
    setProgress(0);
    setCurrentTime(0);
    setDuration(0);
  }, [stopHaptics, stopTick]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stop();
      cacheRef.current.forEach((url) => URL.revokeObjectURL(url));
      cacheRef.current.clear();
      if (chainCtxRef.current && chainCtxRef.current.state !== "closed") {
        void chainCtxRef.current.close();
      }
      chainCtxRef.current = null;
    };
  }, [stop]);

  /**
   * Drive the Vibration API from the bass envelope of the analyser. We sample
   * low frequency bins (~50–250 Hz) and trigger short vibration pulses when
   * the bass energy exceeds an adaptive threshold.
   */
  const startHapticSync = useCallback((analyser: AnalyserNode) => {
    if (typeof window === "undefined" || !("vibrate" in navigator)) return;

    const bins = new Uint8Array(analyser.frequencyBinCount);
    // For fftSize=256 at 48kHz, each bin ≈ 187.5Hz. Take first 4 bins (≈ 0–750Hz)
    // and weight the lowest bins highest.
    const weights = [0, 1.0, 0.8, 0.5];

    const tick = (ts: number) => {
      hapticRafRef.current = requestAnimationFrame(tick);
      if (!settingsRef.current.hapticEnabled) return;
      analyser.getByteFrequencyData(bins);
      let energy = 0;
      let totalW = 0;
      for (let i = 0; i < weights.length; i++) {
        energy += bins[i] * weights[i];
        totalW += weights[i];
      }
      energy = energy / (totalW * 255); // normalise 0..1

      // Trigger short pulse on bass peaks, throttled to ~1 every 220ms
      if (energy > 0.55 && ts - hapticLastTsRef.current > 220) {
        try {
          // Pulse duration scales with energy: 12ms (soft) → 45ms (deep baseline)
          const dur = Math.round(12 + energy * 33);
          navigator.vibrate(dur);
          hapticLastTsRef.current = ts;
        } catch {
          // Vibration might be blocked by user-gesture policy — ignore.
        }
      }
    };
    hapticRafRef.current = requestAnimationFrame(tick);
  }, []);

  /**
   * Drive subtitle + progress state from audio.currentTime. Recomputes cue
   * timings on first metadata tick so the rough character-weight estimate is
   * stretched onto the real measured audio length.
   */
  const startCueTick = useCallback(
    (audio: HTMLAudioElement, segments: string[], weights: number[]) => {
      let resolved = false;
      const tick = () => {
        tickRafRef.current = requestAnimationFrame(tick);
        const t = audio.currentTime;
        const d = Number.isFinite(audio.duration) && audio.duration > 0 ? audio.duration : 0;
        if (!resolved && d > 0) {
          cuesRef.current = cuesFromDuration(segments, weights, d);
          setDuration(d);
          resolved = true;
        }
        setCurrentTime(t);
        if (d > 0) setProgress(Math.min(1, t / d));
        const cues = cuesRef.current;
        if (cues.length) {
          // Find the cue whose [start,end) contains t — fall back to the last
          // one once we run past the final cue's end.
          let active = cues[0];
          for (let i = 0; i < cues.length; i++) {
            if (t >= cues[i].start && t < cues[i].end) {
              active = cues[i];
              break;
            }
            if (t >= cues[i].end) active = cues[i];
          }
          setSubtitle(active.text);
        }
      };
      tickRafRef.current = requestAnimationFrame(tick);
    },
    [],
  );

  const playBrowserTTS = useCallback(
    (text: string, lang: string, key: string, segments: string[], weights: number[]) => {
      if (typeof window === "undefined" || !window.speechSynthesis) {
        setStatus("error");
        return;
      }
      window.speechSynthesis.cancel();
      const utter = new SpeechSynthesisUtterance(text);
      utter.lang = lang === "ku" ? "tr-TR" : lang === "tr" ? "tr-TR" : "en-US";
      utter.rate = 0.82;
      utter.pitch = 0.7; // very deep / dengbêj-like
      utter.volume = 1.0;

      // Estimate duration: ~2.6 chars/sec at this rate → use char total / 2.6.
      const totalChars = text.length || 1;
      const estDuration = Math.max(6, totalChars / 2.6);
      cuesRef.current = cuesFromDuration(segments, weights, estDuration);
      setDuration(estDuration);

      const startTickLoop = () => {
        const tick = () => {
          tickRafRef.current = requestAnimationFrame(tick);
          const t = (performance.now() - browserStartRef.current) / 1000;
          setCurrentTime(t);
          setProgress(Math.min(1, t / estDuration));
        };
        tickRafRef.current = requestAnimationFrame(tick);
      };

      utter.onstart = () => {
        browserStartRef.current = performance.now();
        setStatus("playing");
        setActiveKey(key);
        if (segments.length) setSubtitle(segments[0]);
        startTickLoop();
      };
      utter.onboundary = (ev) => {
        // Advance the active cue when SpeechSynthesis crosses a sentence break.
        if (ev.name && ev.name !== "sentence" && ev.name !== "word") return;
        const charIndex = ev.charIndex ?? 0;
        // Map charIndex back to a segment index using cumulative segment lengths
        // built from `text` (which is what the synthesizer is reading).
        let acc = 0;
        for (let i = 0; i < segments.length; i++) {
          acc += segments[i].length + 1; // +1 for the space we inserted between
          if (charIndex < acc) {
            setSubtitle(segments[i]);
            return;
          }
        }
        if (segments.length) setSubtitle(segments[segments.length - 1]);
      };
      utter.onend = () => {
        stopTick();
        setStatus("idle");
        setActiveKey(null);
        setSubtitle("");
        setProgress(0);
        setCurrentTime(0);
        setDuration(0);
      };
      utter.onerror = () => {
        stopTick();
        setStatus("error");
        setActiveKey(null);
        setSubtitle("");
      };
      utterRef.current = utter;
      window.speechSynthesis.speak(utter);
    },
    [stopTick],
  );

  const playWithBooster = useCallback(
    async (
      audio: HTMLAudioElement,
      key: string,
      text: string,
      lang: string,
      segments: string[],
      weights: number[],
    ) => {
      audioRef.current = audio;
      audio.crossOrigin = "anonymous";

      // Pre-seed cues with a rough estimate; replaced once metadata loads.
      const preEst = Math.max(6, text.length / 2.6);
      cuesRef.current = cuesFromDuration(segments, weights, preEst);
      setDuration(preEst);
      if (segments.length) setSubtitle(segments[0]);

      audio.onplay = () => {
        setStatus("playing");
        startCueTick(audio, segments, weights);
      };
      audio.onloadedmetadata = () => {
        if (Number.isFinite(audio.duration) && audio.duration > 0) {
          cuesRef.current = cuesFromDuration(segments, weights, audio.duration);
          setDuration(audio.duration);
        }
      };
      audio.onended = () => {
        stopHaptics();
        stopTick();
        setStatus("idle");
        setActiveKey(null);
        setSubtitle("");
        setProgress(0);
        setCurrentTime(0);
        setDuration(0);
      };
      audio.onerror = () => {
        stopHaptics();
        stopTick();
        playBrowserTTS(text, lang, key, segments, weights);
      };

      // Build vocal booster chain — fresh context per playback (MediaElement
      // can only be wired once per AudioContext).
      try {
        if (chainCtxRef.current && chainCtxRef.current.state !== "closed") {
          await chainCtxRef.current.close();
        }
        const chain = buildVocalBoosterChain(audio, settingsRef.current.intensity);
        chainCtxRef.current = chain.context;
        if (chain.context.state === "suspended") {
          await chain.context.resume();
        }
        // Start haptic sync on the bass analyser
        startHapticSync(chain.analyser);
      } catch (err) {
        console.warn("[dengbej-tts] vocal booster chain failed, playing dry", err);
      }

      try {
        await audio.play();
      } catch {
        stopHaptics();
        stopTick();
        playBrowserTTS(text, lang, key, segments, weights);
      }
    },
    [playBrowserTTS, startHapticSync, startCueTick, stopHaptics, stopTick],
  );

  /**
   * speak — narrate `text` with optional sacred `quote` recited first.
   *
   * The quote (e.g. the gold-box quotation on each manifesto article) is sent
   * to the edge function as `quote` and the dengbêj recites it BEFORE the
   * main body, with a long ceremonial pause in between.
   */
  const speak = useCallback(
    async (text: string, key: string, lang: string = "tr", quote?: string) => {
      // Toggle off if same key is currently playing
      if (activeKey === key && (status === "playing" || status === "loading")) {
        stop();
        return;
      }

      stop();
      setStatus("loading");
      setActiveKey(key);

      const { segments, weights } = buildCues(text, quote);

      // 1. Try cached blob URL (cache key includes quote presence)
      const cacheKey = quote ? `${key}::q` : key;
      const cached = cacheRef.current.get(cacheKey);
      if (cached) {
        const audio = new Audio(cached);
        await playWithBooster(audio, key, text, lang, segments, weights);
        return;
      }

      // 2. Fetch from edge function
      try {
        const res = await fetch(TTS_URL, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${PUBLISHABLE_KEY}`,
          },
          body: JSON.stringify({ text, lang, voice: "onyx", quote }),
        });

        const contentType = res.headers.get("content-type") || "";
        if (contentType.includes("audio/")) {
          const buf = await res.arrayBuffer();
          const blob = new Blob([buf], { type: "audio/mpeg" });
          const url = URL.createObjectURL(blob);
          cacheRef.current.set(cacheKey, url);
          const audio = new Audio(url);
          await playWithBooster(audio, key, text, lang, segments, weights);
          return;
        }

        // JSON fallback marker — recite quote + body via SpeechSynthesis
        const fallbackText = quote ? `${quote}. ... ${text}` : text;
        playBrowserTTS(fallbackText, lang, key, segments, weights);
      } catch (err) {
        console.warn("[dengbej-tts] falling back to browser TTS", err);
        const fallbackText = quote ? `${quote}. ... ${text}` : text;
        playBrowserTTS(fallbackText, lang, key, segments, weights);
      }
    },
    [activeKey, status, stop, playBrowserTTS, playWithBooster],
  );

  return {
    speak,
    stop,
    status,
    activeKey,
    subtitle,
    progress,
    currentTime,
    duration,
    setSettings,
  };
}

