import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export interface DrivingQuestion {
  id: string;
  country: string;
  question_text: string;
  image_url: string | null;
  video_url: string | null;
  question_type: string;
  options: string[];
  correct_answer: string;
  explanation: string | null;
  difficulty: string;
  category: string;
  language: string;
}

export interface ExamSession {
  id: string;
  total_questions: number;
  correct_answers: number;
  is_passed: boolean | null;
  started_at: string;
  finished_at: string | null;
}

export interface UserStats {
  totalAnswered: number;
  correctAnswers: number;
  successRate: number;
  weakCategories: string[];
  readinessScore: number;
}

export function useDrivingExam() {
  const { user } = useAuth();
  const [questions, setQuestions] = useState<DrivingQuestion[]>([]);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState<UserStats>({
    totalAnswered: 0,
    correctAnswers: 0,
    successRate: 0,
    weakCategories: [],
    readinessScore: 0,
  });

  const fetchQuestions = useCallback(
    async (filters: { country?: string; category?: string; difficulty?: string; limit?: number }) => {
      setLoading(true);
      let query = supabase
        .from("driving_questions")
        .select("*");

      if (filters.country) query = query.eq("country", filters.country);
      if (filters.category) query = query.eq("category", filters.category);
      if (filters.difficulty) query = query.eq("difficulty", filters.difficulty);

      const { data, error } = await query.limit(filters.limit || 50);
      setLoading(false);

      if (error) {
        console.error("Error fetching questions:", error);
        return [];
      }

      const mapped = (data || []).map((q: any) => ({
        ...q,
        options: Array.isArray(q.options) ? q.options : JSON.parse(q.options || "[]"),
      }));

      // Shuffle
      const shuffled = mapped.sort(() => Math.random() - 0.5);
      setQuestions(shuffled);
      return shuffled;
    },
    []
  );

  const recordAnswer = useCallback(
    async (questionId: string, isCorrect: boolean) => {
      if (!user) return;
      await supabase.from("driving_progress").insert({
        user_id: user.id,
        question_id: questionId,
        is_correct: isCorrect,
      });
    },
    [user]
  );

  const createExamSession = useCallback(
    async (country: string, totalQuestions: number) => {
      if (!user) return null;
      const { data, error } = await supabase
        .from("driving_exam_sessions")
        .insert({
          user_id: user.id,
          country,
          total_questions: totalQuestions,
        })
        .select()
        .single();

      if (error) {
        console.error("Error creating session:", error);
        return null;
      }
      return data as ExamSession;
    },
    [user]
  );

  const finishExamSession = useCallback(
    async (sessionId: string, correctAnswers: number, totalQuestions: number) => {
      if (!user) return;
      const passed = correctAnswers / totalQuestions >= 0.7;
      await supabase
        .from("driving_exam_sessions")
        .update({
          correct_answers: correctAnswers,
          is_passed: passed,
          finished_at: new Date().toISOString(),
        })
        .eq("id", sessionId);
    },
    [user]
  );

  const fetchStats = useCallback(async () => {
    if (!user) return;

    const { data: progress } = await supabase
      .from("driving_progress")
      .select("is_correct, driving_questions(category)")
      .eq("user_id", user.id);

    if (!progress || progress.length === 0) return;

    const total = progress.length;
    const correct = progress.filter((p: any) => p.is_correct).length;
    const rate = Math.round((correct / total) * 100);

    // Find weak categories
    const categoryStats: Record<string, { total: number; correct: number }> = {};
    progress.forEach((p: any) => {
      const cat = (p.driving_questions as any)?.category || "general";
      if (!categoryStats[cat]) categoryStats[cat] = { total: 0, correct: 0 };
      categoryStats[cat].total++;
      if (p.is_correct) categoryStats[cat].correct++;
    });

    const weak = Object.entries(categoryStats)
      .filter(([, s]) => s.total >= 3 && s.correct / s.total < 0.6)
      .map(([cat]) => cat);

    const readiness = Math.min(100, Math.round(
      (rate * 0.6) + (Math.min(total, 200) / 200 * 40)
    ));

    setStats({ totalAnswered: total, correctAnswers: correct, successRate: rate, weakCategories: weak, readinessScore: readiness });
  }, [user]);

  const generateAIQuestions = useCallback(
    async (country: string, count: number = 5) => {
      const { data, error } = await supabase.functions.invoke("driving-exam-ai", {
        body: { country, count },
      });
      if (error) {
        console.error("AI generation error:", error);
        return [];
      }
      return data?.questions || [];
    },
    []
  );

  useEffect(() => {
    if (user) fetchStats();
  }, [user, fetchStats]);

  return {
    questions,
    loading,
    stats,
    fetchQuestions,
    recordAnswer,
    createExamSession,
    finishExamSession,
    fetchStats,
    generateAIQuestions,
  };
}

