/**
 * useDuaBoard — Anonymous Dua Kardeşliği prayer board.
 *
 * Loads currently-active duas (24h TTL), subscribes to realtime inserts so
 * the wall updates live, and exposes `post()` + `amen()` actions backed by
 * the `say_amen` RPC for atomic counter updates.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export interface DuaRequest {
  id: string;
  author_id: string;
  body: string;
  lang: string;
  amen_count: number;
  created_at: string;
  expires_at: string;
}

export function useDuaBoard() {
  const { user } = useAuth();
  const [duas, setDuas] = useState<DuaRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [posting, setPosting] = useState(false);
  const [amened, setAmened] = useState<Set<string>>(new Set());

  const refresh = useCallback(async () => {
    const { data } = await supabase
      .from("dua_requests")
      .select("*")
      .gt("expires_at", new Date().toISOString())
      .order("created_at", { ascending: false })
      .limit(80);
    setDuas((data as DuaRequest[]) ?? []);
    setLoading(false);

    if (user) {
      const { data: a } = await supabase
        .from("dua_amens")
        .select("dua_id")
        .eq("user_id", user.id);
      setAmened(new Set(((a as { dua_id: string }[]) ?? []).map((x) => x.dua_id)));
    }
  }, [user]);

  useEffect(() => {
    refresh();
    const ch = supabase
      .channel("dua_board")
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "dua_requests" },
        (payload) => {
          setDuas((prev) => [payload.new as DuaRequest, ...prev].slice(0, 80));
        },
      )
      .on(
        "postgres_changes",
        { event: "UPDATE", schema: "public", table: "dua_requests" },
        (payload) => {
          const next = payload.new as DuaRequest;
          setDuas((prev) => prev.map((d) => (d.id === next.id ? next : d)));
        },
      )
      .subscribe();
    return () => {
      supabase.removeChannel(ch);
    };
  }, [refresh]);

  const post = useCallback(
    async (body: string, lang = "tr") => {
      if (!user) throw new Error("Giriş yap");
      const trimmed = body.trim();
      if (trimmed.length < 4) throw new Error("Çok kısa");
      setPosting(true);
      try {
        const { error } = await supabase
          .from("dua_requests")
          .insert({ author_id: user.id, body: trimmed, lang });
        if (error) throw error;
      } finally {
        setPosting(false);
      }
    },
    [user],
  );

  const amen = useCallback(
    async (duaId: string) => {
      if (!user || amened.has(duaId)) return;
      setAmened((prev) => new Set(prev).add(duaId));
      setDuas((prev) =>
        prev.map((d) =>
          d.id === duaId ? { ...d, amen_count: d.amen_count + 1 } : d,
        ),
      );
      const { error } = await supabase.rpc("say_amen" as never, {
        _dua_id: duaId,
      } as never);
      if (error) {
        // rollback
        setAmened((prev) => {
          const next = new Set(prev);
          next.delete(duaId);
          return next;
        });
        await refresh();
      }
    },
    [user, amened, refresh],
  );

  return { duas, loading, posting, amened, post, amen, refresh };
}

