/**
 * useEDevletAccess — server-trusted KYC gate hook for /e-devlet/*.
 *
 * Calls the SECURITY DEFINER RPC `get_my_kyc_status` so the verification
 * decision cannot be spoofed by tampering with client state.  The RPC only
 * returns the caller's own profile (auth.uid() guard).
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export type KycStage = "no_account" | "no_submission" | "pending" | "rejected" | "verified";

export interface EDevletAccess {
  loading: boolean;
  refreshing: boolean;
  error: string | null;
  isVerified: boolean;
  stage: KycStage;
  kurdId: string | null;
  displayName: string | null;
  rejectionReason: string | null;
  submittedAt: string | null;
  refresh: () => Promise<void>;
}

export function useEDevletAccess(): EDevletAccess {
  const { user, loading: authLoading } = useAuth();
  const [state, setState] = useState<Omit<EDevletAccess, "refresh" | "refreshing">>({
    loading: true,
    error: null,
    isVerified: false,
    stage: "no_account",
    kurdId: null,
    displayName: null,
    rejectionReason: null,
    submittedAt: null,
  });
  const [refreshing, setRefreshing] = useState(false);

  const fetchStatus = useCallback(
    async (markRefreshing = false) => {
      if (markRefreshing) setRefreshing(true);
      if (!user) {
        setState({
          loading: false,
          error: null,
          isVerified: false,
          stage: "no_account",
          kurdId: null,
          displayName: null,
          rejectionReason: null,
          submittedAt: null,
        });
        if (markRefreshing) setRefreshing(false);
        return;
      }
      const { data, error } = await supabase.rpc("get_my_kyc_status");
      if (error) {
        setState({
          loading: false,
          error: error.message,
          isVerified: false,
          stage: "no_submission",
          kurdId: null,
          displayName: null,
          rejectionReason: null,
          submittedAt: null,
        });
        if (markRefreshing) setRefreshing(false);
        return;
      }
      const row = (data as Array<{
        is_verified: boolean;
        kurd_id: string | null;
        display_name: string | null;
        kyc_status: string;
        rejection_reason: string | null;
        submitted_at: string | null;
      }> | null)?.[0];

      const verified = !!row?.is_verified;
      const kycStatus = row?.kyc_status ?? "none";
      let stage: KycStage = "no_submission";
      if (verified) stage = "verified";
      else if (kycStatus === "pending") stage = "pending";
      else if (kycStatus === "rejected") stage = "rejected";
      else if (kycStatus === "approved") stage = "verified";

      setState({
        loading: false,
        error: null,
        isVerified: verified,
        stage,
        kurdId: row?.kurd_id ?? null,
        displayName: row?.display_name ?? null,
        rejectionReason: row?.rejection_reason ?? null,
        submittedAt: row?.submitted_at ?? null,
      });
      if (markRefreshing) setRefreshing(false);
    },
    [user],
  );

  useEffect(() => {
    if (authLoading) return;
    void fetchStatus();
  }, [authLoading, fetchStatus]);

  return {
    ...state,
    loading: authLoading || state.loading,
    refreshing,
    refresh: () => fetchStatus(true),
  };
}

