/**
 * useEdgeSwipeBack — Detect a swipe-from-left-edge gesture and call
 * `window.history.back()`. Mobile only (matchMedia hover:none).
 *
 * Skips when the active element is an input/textarea or when the user is
 * scrolling a horizontal carousel.
 */
import { useEffect } from "react";

export function useEdgeSwipeBack() {
  useEffect(() => {
    if (typeof window === "undefined") return;
    if (window.matchMedia?.("(hover: hover)").matches) return; // desktop only — skip

    let startX = 0;
    let startY = 0;
    let tracking = false;

    const onStart = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t) return;
      // Only trigger from the very-left edge (≤16px)
      if (t.clientX > 16) return;
      const tag = (e.target as HTMLElement | null)?.tagName?.toLowerCase();
      if (tag === "input" || tag === "textarea" || tag === "select") return;
      startX = t.clientX;
      startY = t.clientY;
      tracking = true;
    };

    const onEnd = (e: TouchEvent) => {
      if (!tracking) return;
      tracking = false;
      const t = e.changedTouches[0];
      if (!t) return;
      const dx = t.clientX - startX;
      const dy = Math.abs(t.clientY - startY);
      // Must be mostly horizontal, ≥80px right
      if (dx >= 80 && dy < 60) {
        try {
          window.history.back();
        } catch {}
      }
    };

    window.addEventListener("touchstart", onStart, { passive: true });
    window.addEventListener("touchend", onEnd, { passive: true });
    return () => {
      window.removeEventListener("touchstart", onStart);
      window.removeEventListener("touchend", onEnd);
    };
  }, []);
}

