/**
 * useEsmaProgress — favorites + recitation history for the 99 Names.
 *
 * Backed by `esma_favorites` (starred) and `esma_progress` (play_count +
 * last_played_at). Falls back to local in-memory state when signed out so
 * the UI still feels responsive.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export interface EsmaProgressRow {
  esma_no: number;
  play_count: number;
  last_played_at: string;
}

export function useEsmaProgress() {
  const { user } = useAuth();
  const [favorites, setFavorites] = useState<Set<number>>(new Set());
  const [progress, setProgress] = useState<Map<number, EsmaProgressRow>>(new Map());
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    if (!user) {
      setFavorites(new Set());
      setProgress(new Map());
      setLoaded(true);
      return;
    }
    let mounted = true;
    void Promise.all([
      supabase.from("esma_favorites").select("esma_no").eq("user_id", user.id),
      supabase.from("esma_progress").select("esma_no, play_count, last_played_at").eq("user_id", user.id),
    ]).then(([f, p]) => {
      if (!mounted) return;
      const favSet = new Set<number>((f.data ?? []).map((r: any) => r.esma_no));
      const map = new Map<number, EsmaProgressRow>();
      (p.data ?? []).forEach((r: any) => map.set(r.esma_no, r));
      setFavorites(favSet);
      setProgress(map);
      setLoaded(true);
    });
    return () => { mounted = false; };
  }, [user]);

  const toggleFavorite = useCallback(async (no: number) => {
    setFavorites((prev) => {
      const next = new Set(prev);
      next.has(no) ? next.delete(no) : next.add(no);
      return next;
    });
    if (!user) return;
    const isFav = favorites.has(no);
    if (isFav) {
      await supabase.from("esma_favorites").delete().eq("user_id", user.id).eq("esma_no", no);
    } else {
      await supabase.from("esma_favorites").insert({ user_id: user.id, esma_no: no });
    }
  }, [user, favorites]);

  const recordPlay = useCallback(async (no: number) => {
    setProgress((prev) => {
      const next = new Map(prev);
      const cur = next.get(no);
      next.set(no, {
        esma_no: no,
        play_count: (cur?.play_count ?? 0) + 1,
        last_played_at: new Date().toISOString(),
      });
      return next;
    });
    if (!user) return;
    const cur = progress.get(no);
    await supabase.from("esma_progress").upsert({
      user_id: user.id,
      esma_no: no,
      play_count: (cur?.play_count ?? 0) + 1,
      last_played_at: new Date().toISOString(),
    }, { onConflict: "user_id,esma_no" });
  }, [user, progress]);

  return { favorites, progress, loaded, toggleFavorite, recordPlay };
}

