  { value: "meetup", label: "Buluşma" },
  { value: "education", label: "Eğitim & Seminer" },
  { value: "charity", label: "Yardım & Dayanışma" },
] as const;

export function useEvents(userId: string | undefined) {
  const [events, setEvents] = useState<Event[]>([]);
  const [rsvps, setRsvps] = useState<EventRsvp[]>([]);
  const [rsvpCounts, setRsvpCounts] = useState<Record<string, { going: number; interested: number }>>({});
  const [loading, setLoading] = useState(true);

  const fetchEvents = useCallback(async () => {
    const { data } = await supabase
      .from("events")
      .select("*")
      .gte("starts_at", new Date().toISOString())
      .order("starts_at", { ascending: true });

    const list = (data as Event[]) ?? [];
    setEvents(list);

    // Aggregate RSVP counts in a single query
    if (list.length > 0) {
      const ids = list.map((e) => e.id);
      const { data: allRsvps } = await supabase
        .from("event_rsvps")
        .select("event_id, status")
        .in("event_id", ids);
      const counts: Record<string, { going: number; interested: number }> = {};
      (allRsvps ?? []).forEach((r: { event_id: string; status: string }) => {
        if (!counts[r.event_id]) counts[r.event_id] = { going: 0, interested: 0 };
        if (r.status === "going") counts[r.event_id].going += 1;
        else if (r.status === "interested") counts[r.event_id].interested += 1;
      });
      setRsvpCounts(counts);
    } else {
      setRsvpCounts({});
    }

    if (userId) {
      const { data: rsvpData } = await supabase
        .from("event_rsvps")
        .select("*")
        .eq("user_id", userId);
      setRsvps((rsvpData as EventRsvp[]) ?? []);
    }

    setLoading(false);
  }, [userId]);

  useEffect(() => {
    fetchEvents();

    const channel = supabase
      .channel("event-rsvps-rt")
      .on("postgres_changes", { event: "*", schema: "public", table: "event_rsvps" }, () => {
        fetchEvents();
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [fetchEvents]);

  const createEvent = useCallback(
    async (event: {
      title: string;
      description?: string;
      location?: string;
      city: string;
      category: string;
      starts_at: string;
      ends_at?: string;
      max_attendees?: number;
      image_url?: string;
    }) => {
      if (!userId) throw new Error("Not authenticated");
      const { error } = await supabase.from("events").insert({
        ...event,
        creator_id: userId,
      } as any);
      if (error) throw error;
      await fetchEvents();
    },
    [userId, fetchEvents]
  );

  const rsvpEvent = useCallback(
    async (eventId: string, status: "going" | "interested" | "not_going", remindBefore = false) => {
      if (!userId) throw new Error("Not authenticated");
      const { error } = await supabase.from("event_rsvps").upsert(
        {
          event_id: eventId,
          user_id: userId,
          status,
          remind_before: remindBefore,
        } as any,
        { onConflict: "event_id,user_id" }
      );
      if (error) throw error;
      await fetchEvents();
    },
    [userId, fetchEvents]
  );

  const removeRsvp = useCallback(
    async (eventId: string) => {
      if (!userId) return;
      await supabase
        .from("event_rsvps")
        .delete()
        .eq("event_id", eventId)
        .eq("user_id", userId);
      await fetchEvents();
    },
    [userId, fetchEvents]
  );

  const getRsvpCounts = useCallback(
    (eventId: string) => rsvpCounts[eventId] ?? { going: 0, interested: 0 },
    [rsvpCounts]
  );

  const getUserRsvp = useCallback(
    (eventId: string) => rsvps.find((r) => r.event_id === eventId),
    [rsvps]
  );

  return { events, loading, createEvent, rsvpEvent, removeRsvp, getUserRsvp, getRsvpCounts, refresh: fetchEvents };
}

