import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { toast } from "sonner";

export function useFollow(targetUserId?: string) {
  const { user } = useAuth();
  const [isFollowing, setIsFollowing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [counts, setCounts] = useState({ followers: 0, following: 0 });

  const refresh = useCallback(async () => {
    if (!targetUserId) return;
    const [{ data: rel }, { data: prof }] = await Promise.all([
      user
        ? supabase.from("follows").select("id").eq("follower_id", user.id).eq("following_id", targetUserId).maybeSingle()
        : Promise.resolve({ data: null }),
      supabase.from("profiles").select("follower_count, following_count").eq("user_id", targetUserId).maybeSingle(),
    ]);
    setIsFollowing(!!rel);
    if (prof) setCounts({ followers: prof.follower_count || 0, following: prof.following_count || 0 });
  }, [targetUserId, user]);

  useEffect(() => { refresh(); }, [refresh]);

  const toggle = async () => {
    if (!user || !targetUserId) {
      toast.error("Önce giriş yap");
      return;
    }
    if (user.id === targetUserId) return;
    setLoading(true);
    try {
      if (isFollowing) {
        await supabase.from("follows").delete().eq("follower_id", user.id).eq("following_id", targetUserId);
      } else {
        await supabase.from("follows").insert({ follower_id: user.id, following_id: targetUserId });
      }
      await refresh();
    } catch (e: any) {
      toast.error(e.message || "Hata");
    } finally {
      setLoading(false);
    }
  };

  return { isFollowing, loading, counts, toggle, refresh };
}

