import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

interface FriendProfile {
  user_id: string;
  display_name: string;
  kurd_id: string | null;
  avatar_url: string | null;
  city: string;
  is_online: boolean;
  phone_number: string | null;
  last_seen: string | null;
}

interface FriendRow {
  id: string;
  user_id: string;
  friend_id: string;
  created_at: string;
}

export function useFriends(userId: string | undefined) {
  const [friends, setFriends] = useState<FriendProfile[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchFriends = useCallback(async () => {
    if (!userId) {
      setLoading(false);
      return;
    }

    const { data: friendRows } = await supabase
      .from("friends")
      .select("friend_id")
      .eq("user_id", userId) as { data: { friend_id: string }[] | null };

    if (!friendRows || friendRows.length === 0) {
      setFriends([]);
      setLoading(false);
      return;
    }

    const friendIds = friendRows.map((f) => f.friend_id);
    const { data: profiles } = await supabase
      .from("profiles")
      .select("user_id, display_name, kurd_id, avatar_url, city, is_online, phone_number, last_seen")
      .in("user_id", friendIds);

    if (profiles) setFriends(profiles as FriendProfile[]);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    fetchFriends();
  }, [fetchFriends]);

  const addFriend = async (friendUserId: string, optimisticProfile?: FriendProfile) => {
    if (!userId) return false;
    // Optimistic update: show friend immediately
    if (optimisticProfile) {
      setFriends((prev) => [...prev, optimisticProfile]);
    }
    const { error } = await supabase
      .from("friends")
      .insert({ user_id: userId, friend_id: friendUserId });
    if (error) {
      // Rollback on error
      if (optimisticProfile) {
        setFriends((prev) => prev.filter((f) => f.user_id !== friendUserId));
      }
      return false;
    }
    // Refresh to get accurate data
    fetchFriends();
    return true;
  };

  const removeFriend = async (friendUserId: string) => {
    if (!userId) return false;
    const { error } = await supabase
      .from("friends")
      .delete()
      .eq("user_id", userId)
      .eq("friend_id", friendUserId);
    if (error) return false;
    await fetchFriends();
    return true;
  };

  const searchByKurdId = async (kurdId: string) => {
    const { data } = await supabase
      .from("profiles")
      .select("user_id, display_name, kurd_id, avatar_url, city, is_online, phone_number")
      .ilike("kurd_id", `%${kurdId}%`)
      .limit(10);
    return (data || []) as FriendProfile[];
  };

  const searchByPhone = async (phone: string) => {
    const { data } = await supabase
      .from("profiles")
      .select("user_id, display_name, kurd_id, avatar_url, city, is_online, phone_number")
      .ilike("phone_number", `%${phone}%`)
      .limit(10);
    return (data || []) as FriendProfile[];
  };

  return { friends, loading, addFriend, removeFriend, searchByKurdId, searchByPhone, refetch: fetchFriends };
}

