export function useDailyQuests() {
  const { user } = useAuth();
  const [quests, setQuests] = useState<QuestWithProgress[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!user) { setLoading(false); return; }
    const today = new Date().toISOString().slice(0, 10);
    const [questsRes, progRes] = await Promise.all([
      supabase.from("daily_quests").select("*").eq("is_active", true),
      supabase.from("user_quest_progress").select("*").eq("user_id", user.id).eq("quest_date", today),
    ]);
    if (questsRes.data) {
      const progMap = new Map((progRes.data || []).map((p) => [p.quest_id, p]));
      const merged: QuestWithProgress[] = questsRes.data.map((q) => {
        const p = progMap.get(q.id);
        return {
          id: q.id, code: q.code, title: q.title, description: q.description,
          icon: q.icon || "🎯", target_count: q.target_count,
          xp_reward: q.xp_reward, dc_reward: Number(q.dc_reward),
          current_count: p?.current_count || 0, is_completed: p?.is_completed || false,
        };
      });
      // sort: active incomplete first, then completed
      merged.sort((a, b) => Number(a.is_completed) - Number(b.is_completed));
      setQuests(merged);
    }
    setLoading(false);
  }, [user]);

  useEffect(() => { refresh(); }, [refresh]);

  // claim daily login on mount
  useEffect(() => {
    if (!user) return;
    supabase.rpc("increment_quest_progress" as never, { _user_id: user.id, _quest_code: "daily_login", _amount: 1 } as never)
      .then(() => refresh());
  }, [user, refresh]);

  return { quests, loading, refresh };
}

