    const { data } = await supabase.rpc("get_weekly_leaderboard" as never, { _limit: 50 } as never);
    if (data) setEntries(data as LeaderboardEntry[]);
    setLoading(false);
  }, []);

  useEffect(() => { refresh(); }, [refresh]);

  return { entries, loading, refresh };
}

