/**
 * useHangupConfirm — UI guard for the "End Call" buttons.
 *
 * Two safety layers:
 *  1) **Confirm window**: first tap opens a 2-second amber toast that asks
 *     "Tekrar dokun: aramayı sonlandır". Only a second tap inside that
 *     window actually fires `hangup()`.
 *  2) **Double-tap / half-close debounce**: while a hangup is in flight
 *     (`pending`), every additional tap is silently swallowed so the call
 *     can never be torn down twice in parallel — which previously caused
 *     the "yarım kapanma" bug where the local PC closed but the remote
 *     never received the signal.
 *
 * The hook returns a single `armOrConfirm` handler that callers wire to
 * their red button. UI components can also read `armed` / `pending` to
 * style the button (e.g. switch label to "Onayla").
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { useSovereignPhone } from "@/hooks/useSovereignPhone";
import { hapticHeavy, hapticTap } from "@/lib/native";

const CONFIRM_WINDOW_MS = 2000;
const DOUBLE_TAP_DEBOUNCE_MS = 250;
const HANGUP_TOAST_ID = "phone-hangup-confirm";

interface HangupConfirmApi {
  /** Tap handler — first tap arms, second tap (within 2s) confirms. */
  armOrConfirm: () => void;
  /** True while waiting for the second confirmation tap. */
  armed: boolean;
  /** True while the hangup signal is in flight. */
  pending: boolean;
}

export function useHangupConfirm(): HangupConfirmApi {
  const { hangup, active } = useSovereignPhone();
  const [armed, setArmed] = useState(false);
  const [pending, setPending] = useState(false);
  const lastTapRef = useRef<number>(0);
  const armTimerRef = useRef<number | null>(null);

  const clearArmTimer = useCallback(() => {
    if (armTimerRef.current !== null) {
      window.clearTimeout(armTimerRef.current);
      armTimerRef.current = null;
    }
  }, []);

  // If the call ends for any reason, clear our local state.
  useEffect(() => {
    if (!active) {
      clearArmTimer();
      setArmed(false);
      setPending(false);
      toast.dismiss(HANGUP_TOAST_ID);
    }
  }, [active, clearArmTimer]);

  useEffect(() => () => clearArmTimer(), [clearArmTimer]);

  const armOrConfirm = useCallback(() => {
    // (1) Hard debounce — block accidental double-taps while a hangup
    //     RPC is mid-flight or two taps land within 250 ms of each other.
    const now = Date.now();
    if (pending) return;
    if (now - lastTapRef.current < DOUBLE_TAP_DEBOUNCE_MS) return;
    lastTapRef.current = now;

    // (2) Second tap within the confirm window → execute hangup.
    if (armed) {
      clearArmTimer();
      setArmed(false);
      setPending(true);
      void hapticHeavy();
      toast.dismiss(HANGUP_TOAST_ID);
      toast.loading("📴 Sovereign hat kapatılıyor…", {
        id: HANGUP_TOAST_ID,
        style: {
          background: "linear-gradient(135deg,#1a1208,#2a1a08)",
          border: "1px solid #d4af37",
          color: "#f5d57a",
        },
      });
      void (async () => {
        try {
          await hangup();
          toast.success("Arama sonlandırıldı", {
            id: HANGUP_TOAST_ID,
            duration: 2200,
            style: {
              background: "linear-gradient(135deg,#1a1208,#2a1a08)",
              border: "1px solid #d4af37",
              color: "#f5d57a",
            },
          });
        } catch (err) {
          toast.error("Hat kapatılamadı: " + (err instanceof Error ? err.message : "bilinmeyen"), {
            id: HANGUP_TOAST_ID,
          });
        } finally {
          setPending(false);
        }
      })();
      return;
    }

    // (3) First tap → arm + show 2 s confirm toast.
    void hapticTap();
    setArmed(true);
    toast.warning("📞 Tekrar dokun · aramayı sonlandır", {
      id: HANGUP_TOAST_ID,
      description: "Yanlışlıkla kapatmayı önlemek için onay gerekiyor.",
      duration: CONFIRM_WINDOW_MS,
      style: {
        background: "linear-gradient(135deg,#1a1208,#2a1a08)",
        border: "1px solid #d4af37",
        color: "#f5d57a",
      },
    });
    clearArmTimer();
    armTimerRef.current = window.setTimeout(() => {
      setArmed(false);
      armTimerRef.current = null;
    }, CONFIRM_WINDOW_MS);
  }, [armed, pending, hangup, clearArmTimer]);

  return { armOrConfirm, armed, pending };
}

