/**
 * Honor Ledger hooks — append-only audit log for community honor events.
 *
 * RLS rule:
 *  - Citizens can only SELECT their own rows (own +777 history).
 *  - Admins can SELECT all rows AND call admin_* RPCs.
 *  - All INSERT / UPDATE / DELETE are blocked client-side; writes happen
 *    only via the SECURITY DEFINER RPC `record_re_contribution`.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface HonorEntry {
  id: string;
  action: string;
  honor_delta: number;
  description: string | null;
  metadata: Record<string, unknown>;
  created_at: string;
}

export interface AdminHonorEntry extends HonorEntry {
  user_id: string;
  display_name: string | null;
  kurd_id: string | null;
}

/**
 * Calls `record_re_contribution` with a hard 8-second timeout.
 * Returns a discriminated result so callers can decide whether to
 * launch the celebration or surface a retry CTA — never both.
 */
export type ReResult =
  | { ok: true; ledgerId: string; newKeka: number }
  | { ok: false; kind: "rate_limited" | "timeout" | "auth" | "network" | "unknown"; message: string };

export async function recordReContribution(note?: string): Promise<ReResult> {
  try {
    // supabase-js v2 doesn't accept AbortSignal on rpc — emulate timeout via Promise.race
    const rpc = supabase.rpc("record_re_contribution", { _note: note ?? undefined });
    const timeout = new Promise<{ data: null; error: { message: string; code?: string } }>(
      (resolve) =>
        setTimeout(
          () =>
            resolve({
              data: null,
              error: { message: "timeout: caravan did not respond in time", code: "ETIMEOUT" },
            }),
          8000,
        ),
    );

    const result = (await Promise.race([rpc, timeout])) as {
      data: Array<{ new_keka: number; ledger_id: string }> | null;
      error: { message: string; code?: string } | null;
    };

    if (result.error) {
      const msg = result.error.message ?? "";
      if (msg.includes("rate_limited")) {
        return { ok: false, kind: "rate_limited", message: "Kervan henüz yolda — biraz bekle." };
      }
      if (msg.toLowerCase().includes("authentication")) {
        return { ok: false, kind: "auth", message: "Önce oturum aç." };
      }
      if (result.error.code === "ETIMEOUT" || msg.toLowerCase().includes("timeout")) {
        return { ok: false, kind: "timeout", message: "Sunucu yanıt vermedi. Tekrar dene." };
      }
      return { ok: false, kind: "unknown", message: msg || "Bilinmeyen hata" };
    }

    const row = result.data?.[0];
    if (!row) {
      return { ok: false, kind: "unknown", message: "Ledger satırı dönmedi." };
    }
    return { ok: true, ledgerId: row.ledger_id, newKeka: row.new_keka };
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    return { ok: false, kind: "network", message: msg };
  }
}

/** Latest +777 Rê event for the profile widget */
export function useLatestReEvent(userId: string | undefined) {
  const [entry, setEntry] = useState<HonorEntry | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!userId) {
      setEntry(null);
      setLoading(false);
      return;
    }
    const { data } = await supabase.rpc("get_latest_re_event");
    const row = (data as HonorEntry[] | null)?.[0] ?? null;
    setEntry(row);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  return { entry, loading, refresh };
}

/** Personal honor history (paged) */
export function useMyHonorHistory(userId: string | undefined, pageSize = 50) {
  const [entries, setEntries] = useState<HonorEntry[]>([]);
  const [offset, setOffset] = useState(0);
  const [loading, setLoading] = useState(true);
  const [hasMore, setHasMore] = useState(true);

  const load = useCallback(
    async (nextOffset: number, append: boolean) => {
      if (!userId) {
        setEntries([]);
        setLoading(false);
        return;
      }
      setLoading(true);
      const { data, error } = await supabase.rpc("get_my_honor_history", {
        _limit: pageSize,
        _offset: nextOffset,
      });
      if (error) {
        setLoading(false);
        return;
      }
      const rows = (data as HonorEntry[] | null) ?? [];
      setEntries((prev) => (append ? [...prev, ...rows] : rows));
      setHasMore(rows.length === pageSize);
      setOffset(nextOffset + rows.length);
      setLoading(false);
    },
    [userId, pageSize],
  );

  useEffect(() => {
    load(0, false);
  }, [load]);

  const loadMore = useCallback(() => load(offset, true), [load, offset]);
  const refresh = useCallback(() => load(0, false), [load]);

  return { entries, loading, hasMore, loadMore, refresh };
}

export interface AdminSearchParams {
  userId?: string;
  action?: string;
  from?: string; // ISO
  to?: string; // ISO
  limit?: number;
  offset?: number;
}

/** Admin-only ledger search */
export async function adminSearchHonorLedger(
  params: AdminSearchParams,
): Promise<{ rows: AdminHonorEntry[]; error: string | null }> {
  const { data, error } = await supabase.rpc("admin_search_honor_ledger", {
    _user_id: params.userId ?? undefined,
    _action: params.action ?? undefined,
    _from: params.from ?? undefined,
    _to: params.to ?? undefined,
    _limit: params.limit ?? 50,
    _offset: params.offset ?? 0,
  });
  if (error) return { rows: [], error: error.message };
  return { rows: (data as AdminHonorEntry[] | null) ?? [], error: null };
}

