import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import type { Database } from "@/integrations/supabase/types";

export type HubBanner = Database["public"]["Tables"]["hub_banners"]["Row"];
export type HubApp = Database["public"]["Tables"]["hub_apps"]["Row"];
export type HubAppCategory = "official" | "finance" | "community" | "global";

export function useHubBanners(includeInactive = false) {
  const [data, setData] = useState<HubBanner[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const refetch = useCallback(async () => {
    setIsLoading(true);
    let q = supabase.from("hub_banners").select("*").order("sort_order", { ascending: true });
    if (!includeInactive) q = q.eq("is_active", true);
    const { data: rows, error: err } = await q;
    if (err) setError(err as any);
    else setData((rows ?? []) as HubBanner[]);
    setIsLoading(false);
  }, [includeInactive]);

  useEffect(() => { refetch(); }, [refetch]);

  return { data, isLoading, error, refetch };
}

export function useHubApps(includeInactive = false) {
  const [data, setData] = useState<HubApp[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const refetch = useCallback(async () => {
    setIsLoading(true);
    let q = supabase.from("hub_apps").select("*").order("category").order("sort_order", { ascending: true });
    if (!includeInactive) q = q.eq("is_active", true);
    const { data: rows, error: err } = await q;
    if (err) setError(err as any);
    else setData((rows ?? []) as HubApp[]);
    setIsLoading(false);
  }, [includeInactive]);

  useEffect(() => { refetch(); }, [refetch]);

  return { data, isLoading, error, refetch };
}

export function useHubMutations(onChange?: () => void) {
  const upsertBanner = async (banner: Partial<HubBanner> & { title: string; link_url: string }) => {
    const { data, error } = banner.id
      ? await supabase.from("hub_banners").update(banner).eq("id", banner.id).select().maybeSingle()
      : await supabase.from("hub_banners").insert(banner as any).select().maybeSingle();
    if (error) throw error;
    onChange?.();
    return data;
  };

  const deleteBanner = async (id: string) => {
    const { error } = await supabase.from("hub_banners").delete().eq("id", id);
    if (error) throw error;
    onChange?.();
  };

  const toggleBanner = async ({ id, is_active }: { id: string; is_active: boolean }) => {
    const { error } = await supabase.from("hub_banners").update({ is_active }).eq("id", id);
    if (error) throw error;
    onChange?.();
  };

  const upsertApp = async (app: Partial<HubApp> & { label: string; link_url: string }) => {
    const { data, error } = app.id
      ? await supabase.from("hub_apps").update(app).eq("id", app.id).select().maybeSingle()
      : await supabase.from("hub_apps").insert(app as any).select().maybeSingle();
    if (error) throw error;
    onChange?.();
    return data;
  };

  const deleteApp = async (id: string) => {
    const { error } = await supabase.from("hub_apps").delete().eq("id", id);
    if (error) throw error;
    onChange?.();
  };

  const toggleApp = async ({ id, is_active }: { id: string; is_active: boolean }) => {
    const { error } = await supabase.from("hub_apps").update({ is_active }).eq("id", id);
    if (error) throw error;
    onChange?.();
  };

  return { upsertBanner, deleteBanner, toggleBanner, upsertApp, deleteApp, toggleApp };
}

