/**
 * useHubPreferences — Sovereign OS Hub layout state.
 *
 * Persists the user's icon ordering and hidden-apps list in BOTH:
 *   1. localStorage (instant, offline, anonymous-safe)
 *   2. `hub_user_preferences` table (synced across devices when logged in)
 *
 * On mount: read localStorage immediately, then hydrate from Supabase if
 * authenticated. On any change: write localStorage + debounce-write Supabase.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { DEFAULT_VISIBLE_IDS, HUB_APPS, resolveAppId } from "@/lib/hubApps";

const LS_KEY = "jiyan_hub_prefs_v1";
const ALL_IDS = HUB_APPS.map((a) => a.id);
const VALID_IDS = new Set(ALL_IDS);

/**
 * Aşama 1 birleşmesi sonrası kayıtlı listelerde eski ID'ler olabilir
 * (chat, mivankas, jobs, …). Hepsini yeni 12 çekirdek ID'ye remap eder,
 * geçersizleri at, yinelemeleri tek bırak.
 */
function migrateIds(ids: unknown): string[] {
  if (!Array.isArray(ids)) return [];
  const seen = new Set<string>();
  const out: string[] = [];
  for (const raw of ids) {
    if (typeof raw !== "string") continue;
    const mapped = resolveAppId(raw);
    if (!VALID_IDS.has(mapped) || seen.has(mapped)) continue;
    seen.add(mapped);
    out.push(mapped);
  }
  return out;
}

/**
 * Aşama 1 birleşmesinden sonra eski 33 ID'nin %90'ı yeni 12 çekirdek app'e
 * remap olduğu için kullanıcının `hiddenApps` listesi yanlışlıkla çekirdek
 * app'leri gizliyor (ör. eski "chat" gizliydi → yeni "deng" de gizli sayılıyor).
 * Bu fonksiyon çekirdek (default visible) app'leri hidden listesinden temizler.
 */
function sanitizeHidden(hidden: string[]): string[] {
  const coreSet = new Set(DEFAULT_VISIBLE_IDS);
  return hidden.filter((id) => !coreSet.has(id));
}

interface HubPrefs {
  appOrder: string[];
  hiddenApps: string[];
  weatherLat: number | null;
  weatherLon: number | null;
  weatherLabel: string | null;
  /** 0.85 → 1.25 — multiplies the 64px squircle. */
  iconScale: number;
  /** 0.4 → 1.0 — surface alpha for widgets. */
  tileTransparency: number;
  /** 0.4 → 1.4 — multiplier for gold accent intensity (glow / particles). */
  goldIntensity: number;
  /** 0 → 1 — depth of the background nebula / atmosphere layer. */
  backgroundDepth: number;
  /** Sovereign Control Center toggles. */
  soundEnabled: boolean;
  notificationsEnabled: boolean;
  ghostMode: boolean;
  /**
   * Dynamic Dock — exactly 4 app IDs pinned to the bottom floating dock.
   * Apple-style: long-press → jiggle → drag any Hub app onto a slot to swap.
   * Persisted to BOTH localStorage AND `widget_config.dockSlots` so the
   * configuration follows the user across devices.
   */
  dockSlots: [string, string, string, string];
  /**
   * Haptic intensity — controls strength of every native vibration / haptic
   * impulse across the OS (jiggle, swap, taps, success). Mirrored to
   * localStorage under `jiyan_haptic_intensity_v1` so `src/lib/native.ts`
   * can read it without React context.
   */
  hapticIntensity: HapticIntensity;
  /**
   * Per-app widget size on the SpringBoard grid.
   *  • "icon" (default): standard 1x1 squircle.
   *  • "2x2": medium widget (2 columns × 2 rows).
   *  • "2x4": large/wide widget (4 columns × 2 rows).
   * Long-press an icon in jiggle mode → context menu → choose a size.
   */
  widgetSizes: Record<string, "icon" | "2x2" | "2x4">;
}

export type WidgetSize = "icon" | "2x2" | "2x4";

export type HapticIntensity = "off" | "low" | "medium" | "high";
export const HAPTIC_LS_KEY = "jiyan_haptic_intensity_v1";

const DEFAULT_DOCK_SLOTS: [string, string, string, string] = [
  "deng",
  "akis",
  "pazar",
  "guvenlik",
];

const DEFAULT_PREFS: HubPrefs = {
  appOrder: DEFAULT_VISIBLE_IDS.slice(),
  hiddenApps: ALL_IDS.filter((id) => !DEFAULT_VISIBLE_IDS.includes(id)),
  weatherLat: null,
  weatherLon: null,
  weatherLabel: null,
  iconScale: 1,
  tileTransparency: 0.78,
  goldIntensity: 1,
  backgroundDepth: 0.7,
  soundEnabled: true,
  notificationsEnabled: true,
  ghostMode: false,
  dockSlots: DEFAULT_DOCK_SLOTS,
  hapticIntensity: "medium",
  widgetSizes: {},
};

function isWidgetSize(v: unknown): v is WidgetSize {
  return v === "icon" || v === "2x2" || v === "2x4";
}

function sanitizeWidgetSizes(v: unknown): Record<string, WidgetSize> {
  if (!v || typeof v !== "object") return {};
  const out: Record<string, WidgetSize> = {};
  for (const [k, val] of Object.entries(v as Record<string, unknown>)) {
    if (isWidgetSize(val) && val !== "icon") out[k] = val;
  }
  return out;
}

function isHapticIntensity(v: unknown): v is HapticIntensity {
  return v === "off" || v === "low" || v === "medium" || v === "high";
}

function writeHapticLS(v: HapticIntensity) {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(HAPTIC_LS_KEY, v);
  } catch {}
}

function isValidDockSlots(v: unknown): v is [string, string, string, string] {
  return (
    Array.isArray(v) &&
    v.length === 4 &&
    v.every((s) => typeof s === "string" && VALID_IDS.has(resolveAppId(s)))
  );
}

function migrateDockSlots(v: unknown): [string, string, string, string] {
  if (!isValidDockSlots(v)) return DEFAULT_DOCK_SLOTS;
  return v.map((s) => resolveAppId(s)) as [string, string, string, string];
}

function readLocal(): HubPrefs {
  if (typeof window === "undefined") return DEFAULT_PREFS;
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (!raw) return DEFAULT_PREFS;
    const parsed = JSON.parse(raw);
    const merged = { ...DEFAULT_PREFS, ...parsed } as HubPrefs;
    // Aşama 1 migration: eski 33 ID'yi yeni 12'ye remap, geçersizleri at,
    // hiddenApps'i kalan tüm app'lerle sınırla.
    const order = migrateIds(merged.appOrder);
    const hidden = sanitizeHidden(migrateIds(merged.hiddenApps).filter((id) => !order.includes(id)));
    // appOrder'da olmayan çekirdek app'leri sona ekle (yeni release = yeni icon)
    const orderAll = [...order, ...ALL_IDS.filter((id) => !order.includes(id) && !hidden.includes(id))];
    merged.appOrder = orderAll;
    merged.hiddenApps = hidden;
    merged.dockSlots = migrateDockSlots(merged.dockSlots);
    return merged;
  } catch {
    return DEFAULT_PREFS;
  }
}

function writeLocal(prefs: HubPrefs) {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(LS_KEY, JSON.stringify(prefs));
  } catch {}
}

export function useHubPreferences() {
  const { user } = useAuth();
  const [prefs, setPrefs] = useState<HubPrefs>(() => readLocal());
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hydratedRef = useRef(false);

  // Hydrate from Supabase on login
  useEffect(() => {
    if (!user?.id || hydratedRef.current) return;
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from("hub_user_preferences")
        .select("app_order, hidden_apps, weather_lat, weather_lon, weather_label, widget_config")
        .eq("user_id", user.id)
        .maybeSingle();
      if (cancelled) return;
      if (data) {
        const cfg = (data.widget_config as Record<string, unknown> | null) ?? {};
        const orderMig = migrateIds(data.app_order);
        const hiddenMig = sanitizeHidden(migrateIds(data.hidden_apps).filter((id) => !orderMig.includes(id)));
        const orderAll = [...orderMig, ...ALL_IDS.filter((id) => !orderMig.includes(id) && !hiddenMig.includes(id))];
        const remote: HubPrefs = {
          appOrder: orderAll.length > 0 ? orderAll : DEFAULT_PREFS.appOrder,
          hiddenApps: hiddenMig,
          weatherLat: data.weather_lat as number | null,
          weatherLon: data.weather_lon as number | null,
          weatherLabel: data.weather_label as string | null,
          iconScale: typeof cfg.iconScale === "number" ? cfg.iconScale : DEFAULT_PREFS.iconScale,
          tileTransparency:
            typeof cfg.tileTransparency === "number" ? cfg.tileTransparency : DEFAULT_PREFS.tileTransparency,
          goldIntensity:
            typeof cfg.goldIntensity === "number" ? cfg.goldIntensity : DEFAULT_PREFS.goldIntensity,
          backgroundDepth:
            typeof cfg.backgroundDepth === "number" ? cfg.backgroundDepth : DEFAULT_PREFS.backgroundDepth,
          soundEnabled: typeof cfg.soundEnabled === "boolean" ? cfg.soundEnabled : DEFAULT_PREFS.soundEnabled,
          notificationsEnabled:
            typeof cfg.notificationsEnabled === "boolean"
              ? cfg.notificationsEnabled
              : DEFAULT_PREFS.notificationsEnabled,
          ghostMode: typeof cfg.ghostMode === "boolean" ? cfg.ghostMode : DEFAULT_PREFS.ghostMode,
          dockSlots: migrateDockSlots(cfg.dockSlots),
          hapticIntensity: isHapticIntensity(cfg.hapticIntensity) ? cfg.hapticIntensity : DEFAULT_PREFS.hapticIntensity,
          widgetSizes: sanitizeWidgetSizes(cfg.widgetSizes),
        };
        setPrefs(remote);
        writeLocal(remote);
      }
      hydratedRef.current = true;
    })();
    return () => {
      cancelled = true;
    };
  }, [user?.id]);

  // Debounced Supabase upsert (preserves theme stored under widget_config.theme)
  const persist = useCallback(
    (next: HubPrefs) => {
      writeLocal(next);
      // Mirror haptic intensity to its dedicated key so non-React modules
      // (src/lib/native.ts) can read it synchronously.
      writeHapticLS(next.hapticIntensity);
      if (!user?.id) return;
      if (debounceRef.current) clearTimeout(debounceRef.current);
      debounceRef.current = setTimeout(async () => {
        // Read existing widget_config so we don't clobber `theme`
        const { data } = await supabase
          .from("hub_user_preferences")
          .select("widget_config")
          .eq("user_id", user.id)
          .maybeSingle();
        const existing = (data?.widget_config as Record<string, unknown> | null) ?? {};
        await supabase
          .from("hub_user_preferences")
          .upsert(
            {
              user_id: user.id,
              app_order: next.appOrder,
              hidden_apps: next.hiddenApps,
              weather_lat: next.weatherLat,
              weather_lon: next.weatherLon,
              weather_label: next.weatherLabel,
              widget_config: {
                ...existing,
                iconScale: next.iconScale,
                tileTransparency: next.tileTransparency,
                goldIntensity: next.goldIntensity,
                backgroundDepth: next.backgroundDepth,
                soundEnabled: next.soundEnabled,
                notificationsEnabled: next.notificationsEnabled,
                ghostMode: next.ghostMode,
                dockSlots: next.dockSlots,
                hapticIntensity: next.hapticIntensity,
                widgetSizes: next.widgetSizes,
              },
            },
            { onConflict: "user_id" },
          );
      }, 600);
    },
    [user?.id],
  );

  const update = useCallback(
    (patch: Partial<HubPrefs> | ((p: HubPrefs) => Partial<HubPrefs>)) => {
      setPrefs((p) => {
        const delta = typeof patch === "function" ? patch(p) : patch;
        const next = { ...p, ...delta };
        persist(next);
        return next;
      });
    },
    [persist],
  );

  // ---- Convenience operations ---------------------------------------
  const visibleApps = prefs.appOrder.filter((id) => !prefs.hiddenApps.includes(id) && HUB_APPS.some((a) => a.id === id));
  const libraryApps = ALL_IDS.filter((id) => !visibleApps.includes(id));

  const moveApp = useCallback(
    (fromIdx: number, toIdx: number) => {
      update((p) => {
        const visible = p.appOrder.filter((id) => !p.hiddenApps.includes(id));
        if (fromIdx < 0 || toIdx < 0 || fromIdx >= visible.length || toIdx >= visible.length) return {};
        const next = visible.slice();
        const [m] = next.splice(fromIdx, 1);
        next.splice(toIdx, 0, m);
        const hidden = p.appOrder.filter((id) => p.hiddenApps.includes(id));
        return { appOrder: [...next, ...hidden] };
      });
    },
    [update],
  );

  const hideApp = useCallback(
    (id: string) => {
      update((p) => ({ hiddenApps: [...new Set([...p.hiddenApps, id])] }));
    },
    [update],
  );

  const showApp = useCallback(
    (id: string) => {
      update((p) => ({
        hiddenApps: p.hiddenApps.filter((h) => h !== id),
        appOrder: p.appOrder.includes(id) ? p.appOrder : [...p.appOrder, id],
      }));
    },
    [update],
  );

  const setWeather = useCallback(
    (lat: number, lon: number, label: string) => {
      update({ weatherLat: lat, weatherLon: lon, weatherLabel: label });
    },
    [update],
  );

  const setIconScale = useCallback((v: number) => update({ iconScale: v }), [update]);
  const setTileTransparency = useCallback((v: number) => update({ tileTransparency: v }), [update]);
  const setGoldIntensity = useCallback((v: number) => update({ goldIntensity: v }), [update]);
  const setBackgroundDepth = useCallback((v: number) => update({ backgroundDepth: v }), [update]);
  const setSoundEnabled = useCallback((v: boolean) => update({ soundEnabled: v }), [update]);
  const setNotificationsEnabled = useCallback(
    (v: boolean) => update({ notificationsEnabled: v }),
    [update],
  );
  const setGhostMode = useCallback((v: boolean) => update({ ghostMode: v }), [update]);
  const setHapticIntensity = useCallback(
    (v: HapticIntensity) => update({ hapticIntensity: v }),
    [update],
  );

  /**
   * setDockSlot — replace a single dock slot with a new app id.
   * No-ops if the same app is already in another slot (we swap instead).
   */
  const setDockSlot = useCallback(
    (slotIndex: number, appId: string) => {
      if (slotIndex < 0 || slotIndex > 3) return;
      if (!HUB_APPS.some((a) => a.id === appId)) return;
      update((p) => {
        const next = [...p.dockSlots] as [string, string, string, string];
        const existingIdx = next.indexOf(appId);
        if (existingIdx === slotIndex) return {};
        if (existingIdx >= 0) {
          // Swap the two slots so we never lose an icon
          [next[slotIndex], next[existingIdx]] = [next[existingIdx], next[slotIndex]];
        } else {
          next[slotIndex] = appId;
        }
        return { dockSlots: next };
      });
    },
    [update],
  );

  /**
   * reorderDockSlot — move dock slot at `from` to position `to` (insertion
   * style, like iOS dock drag). Persists to Supabase via `update`.
   */
  const reorderDockSlot = useCallback(
    (from: number, to: number) => {
      if (from === to) return;
      if (from < 0 || from > 3 || to < 0 || to > 3) return;
      update((p) => {
        const next = [...p.dockSlots] as [string, string, string, string];
        const [m] = next.splice(from, 1);
        next.splice(to, 0, m);
        return { dockSlots: next };
      });
    },
    [update],
  );

  /**
   * setWidgetSize — change an app's tile footprint on the SpringBoard grid.
   * Pass "icon" to revert (entry is dropped from the persisted map).
   */
  const setWidgetSize = useCallback(
    (appId: string, size: WidgetSize) => {
      if (!HUB_APPS.some((a) => a.id === appId)) return;
      update((p) => {
        const next = { ...p.widgetSizes };
        if (size === "icon") delete next[appId];
        else next[appId] = size;
        return { widgetSizes: next };
      });
    },
    [update],
  );

  const reset = useCallback(() => {
    update(DEFAULT_PREFS);
  }, [update]);

  return {
    prefs,
    visibleApps,
    libraryApps,
    moveApp,
    hideApp,
    showApp,
    setWeather,
    setIconScale,
    setTileTransparency,
    setGoldIntensity,
    setBackgroundDepth,
    setSoundEnabled,
    setNotificationsEnabled,
    setGhostMode,
    setHapticIntensity,
    setDockSlot,
    reorderDockSlot,
    dockSlots: prefs.dockSlots,
    setWidgetSize,
    widgetSizes: prefs.widgetSizes,
    reset,
  };
}

