/**
 * useHubTheme — Active Sovereign OS Hub theme + persistence.
 *
 * Persists in localStorage immediately and (when authenticated) syncs to
 * `hub_user_preferences.widget_config.theme`. Uses a tiny event bus so every
 * subscriber updates instantly when the user toggles from anywhere.
 *
 * Now supports 4 themes: sovereign-obsidian, royal-gold-3d,
 * sovereign-glass, stellar-symbol. Legacy ids ("sovereign-dark",
 * "royal-gold") are migrated transparently via `normalizeThemeId`.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import {
  DEFAULT_HUB_THEME,
  HUB_THEMES,
  HUB_THEME_ORDER,
  normalizeThemeId,
  type HubThemeId,
  type HubThemeTokens,
} from "@/lib/hubTheme";

const LS_KEY = "jiyan_hub_theme_v1";
const EVENT = "jiyan:hub-theme-change";

function readLocal(): HubThemeId {
  if (typeof window === "undefined") return DEFAULT_HUB_THEME;
  try {
    const v = localStorage.getItem(LS_KEY);
    return normalizeThemeId(v);
  } catch {
    return DEFAULT_HUB_THEME;
  }
}

export function useHubTheme(): {
  theme: HubThemeTokens;
  themeId: HubThemeId;
  setThemeId: (id: HubThemeId) => void;
  toggle: () => void;
} {
  const { user } = useAuth();
  const [themeId, setLocalId] = useState<HubThemeId>(() => readLocal());

  // Hydrate from Supabase once when logged-in
  useEffect(() => {
    if (!user?.id) return;
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from("hub_user_preferences")
        .select("widget_config")
        .eq("user_id", user.id)
        .maybeSingle();
      if (cancelled) return;
      const remoteRaw = (data?.widget_config as { theme?: string } | null)
        ?.theme;
      const remote = normalizeThemeId(remoteRaw);
      if (remote !== themeId) {
        setLocalId(remote);
        try {
          localStorage.setItem(LS_KEY, remote);
        } catch {}
      }
    })();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  // Cross-instance sync via custom event
  useEffect(() => {
    const onChange = (e: Event) => {
      const next = (e as CustomEvent<HubThemeId>).detail;
      if (next && next !== themeId) setLocalId(normalizeThemeId(next));
    };
    window.addEventListener(EVENT, onChange as EventListener);
    return () => window.removeEventListener(EVENT, onChange as EventListener);
  }, [themeId]);

  const setThemeId = useCallback(
    (id: HubThemeId) => {
      const normalized = normalizeThemeId(id);
      setLocalId(normalized);
      try {
        localStorage.setItem(LS_KEY, normalized);
      } catch {}
      try {
        window.dispatchEvent(
          new CustomEvent(EVENT, { detail: normalized }),
        );
      } catch {}
      // Persist remotely (best-effort, fire-and-forget)
      if (user?.id) {
        (async () => {
          const { data } = await supabase
            .from("hub_user_preferences")
            .select("widget_config")
            .eq("user_id", user.id)
            .maybeSingle();
          const cfg =
            (data?.widget_config as Record<string, unknown> | null) ?? {};
          await supabase
            .from("hub_user_preferences")
            .upsert(
              {
                user_id: user.id,
                widget_config: { ...cfg, theme: normalized },
              },
              { onConflict: "user_id" },
            );
        })();
      }
    },
    [user?.id],
  );

  const toggle = useCallback(() => {
    const order = HUB_THEME_ORDER;
    const idx = order.indexOf(normalizeThemeId(themeId));
    const next = order[(idx + 1) % order.length];
    setThemeId(next);
  }, [themeId, setThemeId]);

  const normalized = normalizeThemeId(themeId);
  return {
    theme: HUB_THEMES[normalized as keyof typeof HUB_THEMES],
    themeId: normalized,
    setThemeId,
    toggle,
  };
}

