/**
 * useHutbeArchive — list every published hutbe (newest first), surface
 * per-user resume position, and expose `markPosition` / `markComplete`.
 *
 * Hutbeler are read by everyone; per-user progress lives in `hutbe_progress`.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export interface HutbeRow {
  id: string;
  title: string;
  content: string;
  week_of: string;
  author: string | null;
}

export interface HutbeProgress {
  hutbe_id: string;
  position_sec: number;
  completed: boolean;
}

export function useHutbeArchive() {
  const { user } = useAuth();
  const [list, setList] = useState<HutbeRow[]>([]);
  const [progress, setProgress] = useState<Map<string, HutbeProgress>>(new Map());
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;
    void supabase
      .from("hutbeler")
      .select("id,title,content,week_of,author")
      .order("week_of", { ascending: false })
      .limit(40)
      .then(({ data }) => {
        if (mounted) {
          setList((data as any) ?? []);
          setLoading(false);
        }
      });
    return () => { mounted = false; };
  }, []);

  useEffect(() => {
    if (!user) { setProgress(new Map()); return; }
    let mounted = true;
    void supabase
      .from("hutbe_progress")
      .select("hutbe_id, position_sec, completed")
      .eq("user_id", user.id)
      .then(({ data }) => {
        if (!mounted) return;
        const m = new Map<string, HutbeProgress>();
        (data ?? []).forEach((r: any) => m.set(r.hutbe_id, r));
        setProgress(m);
      });
    return () => { mounted = false; };
  }, [user]);

  const markPosition = useCallback(async (hutbeId: string, positionSec: number, completed: boolean) => {
    setProgress((prev) => {
      const n = new Map(prev);
      n.set(hutbeId, { hutbe_id: hutbeId, position_sec: positionSec, completed });
      return n;
    });
    if (!user) return;
    await supabase.from("hutbe_progress").upsert({
      user_id: user.id,
      hutbe_id: hutbeId,
      position_sec: positionSec,
      completed,
      updated_at: new Date().toISOString(),
    }, { onConflict: "user_id,hutbe_id" });
  }, [user]);

  return { list, loading, progress, markPosition };
}

