import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface InboxMessage {
  id: string;
  sender_id: string | null;
  recipient_id: string;
  subject: string;
  body: string;
  message_type: string;
  is_read: boolean;
  reference_code: string | null;
  created_at: string;
  sender_profile?: { display_name: string; username: string | null; kurd_id: string | null } | null;
}

export function useInbox(userId: string | undefined) {
  const [messages, setMessages] = useState<InboxMessage[]>([]);
  const [loading, setLoading] = useState(true);
  const [unreadCount, setUnreadCount] = useState(0);

  const fetchMessages = useCallback(async () => {
    if (!userId) return;
    const { data } = await supabase
      .from("inbox_messages")
      .select("*")
      .eq("recipient_id", userId)
      .order("created_at", { ascending: false })
      .limit(100);

    if (data) {
      setMessages(data as InboxMessage[]);
      setUnreadCount(data.filter((m: any) => !m.is_read).length);
    }
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    fetchMessages();
  }, [fetchMessages]);

  // Realtime subscription
  useEffect(() => {
    if (!userId) return;
    const channelName = `inbox-rt-${userId}-${Date.now()}`;
    const channel = supabase
      .channel(channelName)
      .on("postgres_changes", {
        event: "INSERT",
        schema: "public",
        table: "inbox_messages",
        filter: `recipient_id=eq.${userId}`,
      }, (payload) => {
        const newMsg = payload.new as InboxMessage;
        setMessages((prev) => [newMsg, ...prev]);
        setUnreadCount((c) => c + 1);
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [userId]);

  const markAsRead = useCallback(async (id: string) => {
    await supabase.from("inbox_messages").update({ is_read: true }).eq("id", id);
    setMessages((prev) => prev.map((m) => m.id === id ? { ...m, is_read: true } : m));
    setUnreadCount((c) => Math.max(0, c - 1));
  }, []);

  const markAllRead = useCallback(async () => {
    if (!userId) return;
    await supabase.from("inbox_messages").update({ is_read: true }).eq("recipient_id", userId).eq("is_read", false);
    setMessages((prev) => prev.map((m) => ({ ...m, is_read: true })));
    setUnreadCount(0);
  }, [userId]);

  const sendMessage = useCallback(async (recipient: string, subject: string, body: string) => {
    if (!userId) throw new Error("Not authenticated");
    const { data, error } = await supabase.rpc("send_inbox_message", {
      _sender_id: userId,
      _recipient_identifier: recipient,
      _subject: subject,
      _body: body,
    });
    if (error) throw error;
    const result = data as any;
    if (!result.success) throw new Error(result.error);
    return result;
  }, [userId]);

  return { messages, loading, unreadCount, markAsRead, markAllRead, sendMessage, refetch: fetchMessages };
}

