import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { toast } from "sonner";

// --- Local cache for AI responses (cost saver) ---
const AI_CACHE_KEY = "jiyan-ai-cache-v1";
const AI_CACHE_MAX = 100;
const AI_CACHE_TTL_MS = 1000 * 60 * 60 * 24 * 7; // 7 days

type CacheEntry = { a: string; t: number };

function readCache(): Record<string, CacheEntry> {
  try { return JSON.parse(localStorage.getItem(AI_CACHE_KEY) || "{}"); } catch { return {}; }
}
function writeCache(c: Record<string, CacheEntry>) {
  try { localStorage.setItem(AI_CACHE_KEY, JSON.stringify(c)); } catch {}
}
function cacheGet(key: string): string | null {
  const c = readCache();
  const hit = c[key];
  if (!hit) return null;
  if (Date.now() - hit.t > AI_CACHE_TTL_MS) { delete c[key]; writeCache(c); return null; }
  return hit.a;
}
function cacheSet(key: string, answer: string) {
  const c = readCache();
  c[key] = { a: answer, t: Date.now() };
  const keys = Object.keys(c);
  if (keys.length > AI_CACHE_MAX) {
    keys.sort((a, b) => c[a].t - c[b].t).slice(0, keys.length - AI_CACHE_MAX).forEach(k => delete c[k]);
  }
  writeCache(c);
}

export interface AIMessage {
  id?: string;
  role: "user" | "assistant" | "system";
  content: string;
  created_at?: string;
}

export interface AIConversation {
  id: string;
  title: string;
  updated_at: string;
}

export function useAIConversations() {
  const { user } = useAuth();
  const [conversations, setConversations] = useState<AIConversation[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!user) { setLoading(false); return; }
    const { data } = await supabase
      .from("ai_conversations")
      .select("id, title, updated_at")
      .eq("user_id", user.id)
      .order("updated_at", { ascending: false })
      .limit(20);
    if (data) setConversations(data);
    setLoading(false);
  }, [user]);

  useEffect(() => { refresh(); }, [refresh]);

  return { conversations, loading, refresh };
}

export function useAIChat(conversationId: string | null) {
  const { user } = useAuth();
  const [messages, setMessages] = useState<AIMessage[]>([]);
  const [streaming, setStreaming] = useState(false);
  const [activeId, setActiveId] = useState<string | null>(conversationId);

  useEffect(() => { setActiveId(conversationId); }, [conversationId]);

  useEffect(() => {
    if (!activeId) { setMessages([]); return; }
    supabase
      .from("ai_messages")
      .select("*")
      .eq("conversation_id", activeId)
      .order("created_at")
      .then(({ data }) => {
        if (data) setMessages(data as AIMessage[]);
      });
  }, [activeId]);

  const send = useCallback(async (content: string): Promise<void> => {
    if (!user || !content.trim() || streaming) return;
    setStreaming(true);

    let convId = activeId;
    if (!convId) {
      const { data: conv } = await supabase
        .from("ai_conversations")
        .insert({ user_id: user.id, title: content.slice(0, 50) })
        .select("id")
        .single();
      if (!conv) { setStreaming(false); return; }
      convId = conv.id;
      setActiveId(convId);
    }

    const userMsg: AIMessage = { role: "user", content, conversation_id: convId } as AIMessage & { conversation_id: string };
    setMessages((prev) => [...prev, userMsg, { role: "assistant", content: "" }]);

    await supabase.from("ai_messages").insert({ conversation_id: convId, role: "user", content });

    // Cost-saver: exact-match cache for single-shot questions (only when no prior context)
    const cacheKey = messages.length === 0 ? content.trim() : null;
    if (cacheKey) {
      const cached = cacheGet(cacheKey);
      if (cached) {
        setMessages((prev) => {
          const next = [...prev];
          next[next.length - 1] = { role: "assistant", content: cached };
          return next;
        });
        await supabase.from("ai_messages").insert({ conversation_id: convId, role: "assistant", content: cached });
        setStreaming(false);
        return;
      }
    }

    const history = messages.concat(userMsg).map(({ role, content }) => ({ role, content }));

    try {
      // Primary brain: Jiyan Sovereign Intelligence (sovereign edge function).
      const url = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/replicate-deepseek`;
      const resp = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}`,
        },
        body: JSON.stringify({ messages: history }),
      });

      if (resp.status === 429) {
        setMessages((prev) => prev.slice(0, -1).concat({ role: "assistant", content: "⏳ Çok fazla istek geldi. Lütfen 30 saniye bekleyip tekrar dene." }));
        setStreaming(false); return;
      }
      if (resp.status === 402) {
        toast.warning("💎 AI kredisi düşük", {
          description: "Workspace AI bakiyesine kredi ekleyin.",
          duration: 6000,
        });
        setMessages((prev) => prev.slice(0, -1).concat({
          role: "assistant",
          content: "💎 **AI kredisi tükendi**\n\nJiyan AI'yı kullanmak için workspace AI bakiyesine kredi eklenmeli.\n\n**Yönetici için:** Lovable → Settings → Workspace → Usage → AI balance'a top-up yap.\n\nBu arada platformun diğer özelliklerini kullanmaya devam edebilirsin: 💬 Sohbet, 🛒 Marketplace, 📚 JiyanPedia, 🚗 Ehliyet sınavı.",
        }));
        setStreaming(false); return;
      }
      if (!resp.ok || !resp.body) throw new Error("Stream başlatılamadı");

      const reader = resp.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      let assistantContent = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        let idx;
        while ((idx = buffer.indexOf("\n")) !== -1) {
          let line = buffer.slice(0, idx);
          buffer = buffer.slice(idx + 1);
          if (line.endsWith("\r")) line = line.slice(0, -1);
          if (line.startsWith(":") || !line.startsWith("data: ")) continue;
          const json = line.slice(6).trim();
          if (json === "[DONE]") continue;
          try {
            const parsed = JSON.parse(json);
            const delta = parsed.choices?.[0]?.delta?.content;
            if (delta) {
              assistantContent += delta;
              setMessages((prev) => {
                const next = [...prev];
                next[next.length - 1] = { role: "assistant", content: assistantContent };
                return next;
              });
            }
          } catch { buffer = line + "\n" + buffer; break; }
        }
      }

      if (assistantContent && convId) {
        await supabase.from("ai_messages").insert({ conversation_id: convId, role: "assistant", content: assistantContent });
        await supabase.from("ai_conversations").update({ updated_at: new Date().toISOString() }).eq("id", convId);
        if (cacheKey) cacheSet(cacheKey, assistantContent);
        // quest progress
        await supabase.rpc("increment_quest_progress" as never, { _user_id: user.id, _quest_code: "chat_with_ai", _amount: 1 } as never);
      }
    } catch (e) {
      console.error(e);
      setMessages((prev) => prev.slice(0, -1).concat({ role: "assistant", content: "❌ Bir hata oluştu. Tekrar dener misin?" }));
    } finally {
      setStreaming(false);
    }
  }, [user, activeId, messages, streaming]);

  return { messages, send, streaming, activeId };
}

