/**
 * useJiyanMusic — Jiyan Music Faz 1 global player.
 *
 * Tek bir <audio> elementi tüm uygulama hayatı boyunca var olur. Şarkı,
 * çalma durumu, pozisyon ve katalog state'i Context üzerinden paylaşılır.
 * Now Playing tablosu (`music_now_playing`) realtime senkronize edilir, böylece
 * Hub widget'ı ve mini-player anında güncellenir.
 *
 * Faz 1 kapsamı:
 *   - Library (`music_tracks`) çekme + kategori filtre
 *   - Play / pause / next / prev / seek + queue
 *   - 8D ses sahte-stereo PannerNode (manifesto/meditasyon)
 *   - Now Playing senkronizasyonu (Postgres + Realtime)
 */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { resolvePipedAudio } from "@/lib/musicSources";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const isVirtualId = (id: string) => !UUID_RE.test(id);

export type MusicCategory = "general" | "manifesto" | "meditation";

export interface MusicTrack {
  id: string;
  title: string;
  artist: string;
  album: string | null;
  category: MusicCategory;
  duration_seconds: number | null;
  audio_url: string;
  audio_cid: string | null;
  cover_url: string | null;
  is_8d: boolean;
  language: string | null;
  tags: string[] | null;
  is_published: boolean;
  play_count: number;
  created_at: string;
}

export interface NowPlayingState {
  track: MusicTrack | null;
  isPlaying: boolean;
  position: number;
  duration: number;
}

interface MusicContextValue extends NowPlayingState {
  tracks: MusicTrack[];
  loading: boolean;
  queue: MusicTrack[];
  refetch: () => Promise<void>;
  play: (track: MusicTrack, queue?: MusicTrack[]) => Promise<void>;
  toggle: () => Promise<void>;
  pause: () => void;
  resume: () => Promise<void>;
  next: () => Promise<void>;
  prev: () => Promise<void>;
  seek: (sec: number) => void;
  stop: () => Promise<void>;
  /** Live amplitude getter (0..1). Call from a RAF for visualizers. */
  getAmplitude: () => number;
  /** Smoothly fade volume to target (0..1) over `ms`. Returns when done. */
  fadeVolume: (target: number, ms?: number) => Promise<void>;
  /** Lock stereo pan to a specific value (-1 left .. 1 right). Suspends 8D rotation. */
  setManualPan: (pan: number | null) => void;
}

const Ctx = createContext<MusicContextValue | null>(null);

export function MusicProvider({ children }: { children: React.ReactNode }) {
  const { user } = useAuth();
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Web Audio nodes (lazy) for 8D rotation + amplitude visualisation
  const ctxRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);
  const pannerRef = useRef<StereoPannerNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const analyserBufRef = useRef<Uint8Array | null>(null);
  const panRafRef = useRef<number | null>(null);

  const [tracks, setTracks] = useState<MusicTrack[]>([]);
  const [loading, setLoading] = useState(true);
  const [queue, setQueue] = useState<MusicTrack[]>([]);
  const [track, setTrack] = useState<MusicTrack | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [position, setPosition] = useState(0);
  const [duration, setDuration] = useState(0);

  /* ──────────────── audio element bootstrap (browser only) ──────────────── */
  useEffect(() => {
    if (typeof window === "undefined") return;
    const a = new Audio();
    a.preload = "metadata";
    a.crossOrigin = "anonymous";
    audioRef.current = a;

    const onTime = () => setPosition(a.currentTime || 0);
    const onLoaded = () => setDuration(a.duration || 0);
    const onPlay = () => setIsPlaying(true);
    const onPause = () => setIsPlaying(false);
    const onEnded = () => {
      setIsPlaying(false);
      // auto-advance to next track in queue
      void nextRef.current?.();
    };
    a.addEventListener("timeupdate", onTime);
    a.addEventListener("loadedmetadata", onLoaded);
    a.addEventListener("play", onPlay);
    a.addEventListener("pause", onPause);
    a.addEventListener("ended", onEnded);

    return () => {
      a.pause();
      a.removeEventListener("timeupdate", onTime);
      a.removeEventListener("loadedmetadata", onLoaded);
      a.removeEventListener("play", onPlay);
      a.removeEventListener("pause", onPause);
      a.removeEventListener("ended", onEnded);
      if (panRafRef.current) cancelAnimationFrame(panRafRef.current);
      try {
        sourceRef.current?.disconnect();
        pannerRef.current?.disconnect();
        void ctxRef.current?.close();
      } catch {}
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ──────────────── catalog fetch + realtime ──────────────── */
  const refetch = useCallback(async () => {
    setLoading(true);
    const { data } = await supabase
      .from("music_tracks")
      .select(
        "id,title,artist,album,category,duration_seconds,audio_url,audio_cid,cover_url,is_8d,language,tags,is_published,play_count,created_at",
      )
      .eq("is_published", true)
      .order("created_at", { ascending: false })
      .limit(200);
    setTracks((data ?? []) as MusicTrack[]);
    setLoading(false);
  }, []);

  useEffect(() => {
    void refetch();
  }, [refetch]);

  /* ──────────────── 8D rotation effect ──────────────── */
  const ensureAudioGraph = useCallback(() => {
    const a = audioRef.current;
    if (!a || ctxRef.current) return;
    try {
      const AC =
        (window as any).AudioContext ||
        (window as any).webkitAudioContext;
      if (!AC) return;
      const ctx: AudioContext = new AC();
      const src = ctx.createMediaElementSource(a);
      const panner = ctx.createStereoPanner();
      const analyser = ctx.createAnalyser();
      analyser.fftSize = 256;
      // src → panner → analyser → destination
      src.connect(panner);
      panner.connect(analyser);
      analyser.connect(ctx.destination);
      ctxRef.current = ctx;
      sourceRef.current = src;
      pannerRef.current = panner;
      analyserRef.current = analyser;
      analyserBufRef.current = new Uint8Array(analyser.frequencyBinCount);
    } catch (e) {
      console.warn("Music: AudioContext init failed", e);
    }
  }, []);

  const manualPanRef = useRef<number | null>(null);

  const startPanRotation = useCallback(() => {
    if (panRafRef.current) cancelAnimationFrame(panRafRef.current);
    const start = performance.now();
    const tick = (now: number) => {
      const t = (now - start) / 1000;
      const v = Math.sin((t / 8) * Math.PI * 2);
      // Manual pan (qibla) overrides 8D rotation while active
      if (pannerRef.current && manualPanRef.current == null)
        pannerRef.current.pan.value = v;
      panRafRef.current = requestAnimationFrame(tick);
    };
    panRafRef.current = requestAnimationFrame(tick);
  }, []);

  const stopPanRotation = useCallback(() => {
    if (panRafRef.current) cancelAnimationFrame(panRafRef.current);
    panRafRef.current = null;
    if (pannerRef.current && manualPanRef.current == null)
      pannerRef.current.pan.value = 0;
  }, []);

  const setManualPan = useCallback((pan: number | null) => {
    manualPanRef.current = pan;
    ensureAudioGraph();
    if (pannerRef.current) {
      pannerRef.current.pan.value = pan == null ? 0 : Math.max(-1, Math.min(1, pan));
    }
  }, [ensureAudioGraph]);

  const fadeVolume = useCallback(async (target: number, ms = 1500) => {
    const a = audioRef.current;
    if (!a) return;
    const start = a.volume;
    const t0 = performance.now();
    return new Promise<void>((resolve) => {
      const step = (now: number) => {
        const k = Math.min(1, (now - t0) / ms);
        a.volume = start + (target - start) * k;
        if (k < 1) requestAnimationFrame(step);
        else resolve();
      };
      requestAnimationFrame(step);
    });
  }, []);

  /* ──────────────── now playing sync ──────────────── */
  const syncNowPlaying = useCallback(
    async (t: MusicTrack | null, playing: boolean, pos: number) => {
      if (!user) return;
      try {
        await supabase.from("music_now_playing").upsert(
          {
            user_id: user.id,
            track_id: t?.id ?? null,
            is_playing: playing,
            position_seconds: Math.floor(pos),
            updated_at: new Date().toISOString(),
          },
          { onConflict: "user_id" },
        );
      } catch {
        /* best-effort */
      }
    },
    [user],
  );

  // Throttled position sync (every ~5s while playing)
  useEffect(() => {
    if (!isPlaying || !track) return;
    const id = setInterval(() => void syncNowPlaying(track, true, position), 5000);
    return () => clearInterval(id);
  }, [isPlaying, track, position, syncNowPlaying]);

  /* ──────────────── MediaSession (OS Control Center / lock screen) ──────────────── */
  useEffect(() => {
    if (typeof navigator === "undefined" || !("mediaSession" in navigator)) return;
    const ms = (navigator as any).mediaSession;
    if (!track) {
      try { ms.metadata = null; ms.playbackState = "none"; } catch {}
      return;
    }
    try {
      const MM: any = (window as any).MediaMetadata;
      if (MM) {
        ms.metadata = new MM({
          title: track.title,
          artist: track.artist,
          album: track.album ?? "Jiyan Music",
          artwork: track.cover_url
            ? [
                { src: track.cover_url, sizes: "256x256", type: "image/png" },
                { src: track.cover_url, sizes: "512x512", type: "image/png" },
              ]
            : [],
        });
      }
      ms.playbackState = isPlaying ? "playing" : "paused";
    } catch {}
  }, [track, isPlaying]);

  useEffect(() => {
    if (typeof navigator === "undefined" || !("mediaSession" in navigator)) return;
    const ms = (navigator as any).mediaSession;
    const set = (action: string, fn: ((d?: any) => void) | null) => {
      try { ms.setActionHandler(action, fn as any); } catch {}
    };
    set("play", () => { void resumeRef.current?.(); });
    set("pause", () => pauseRef.current?.());
    set("previoustrack", () => { void prevRef.current?.(); });
    set("nexttrack", () => { void nextRef.current?.(); });
    set("seekto", (details: any) => {
      if (typeof details?.seekTime === "number") seekRef.current?.(details.seekTime);
    });
    return () => {
      ["play","pause","previoustrack","nexttrack","seekto"].forEach((a) => set(a, null));
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // MediaSession position state (for OS scrubber)
  useEffect(() => {
    if (typeof navigator === "undefined" || !("mediaSession" in navigator)) return;
    const ms = (navigator as any).mediaSession;
    if (!ms.setPositionState || !duration) return;
    try {
      ms.setPositionState({
        duration,
        position: Math.min(position, duration),
        playbackRate: 1,
      });
    } catch {}
  }, [position, duration]);

  /* ──────────────── controls ──────────────── */
  const play = useCallback(
    async (t: MusicTrack, q?: MusicTrack[]) => {
      const a = audioRef.current;
      if (!a) return;
      ensureAudioGraph();
      // Resume AudioContext (autoplay policy)
      try { if (ctxRef.current?.state === "suspended") await ctxRef.current.resume(); } catch {}

      if (q?.length) setQueue(q);
      setTrack(t);

      // Resolve dynamic sources (Piped) lazily — avoids upfront API calls
      let src = t.audio_url;
      if (!src && t.id.startsWith("piped:")) {
        const resolved = await resolvePipedAudio(t.id);
        if (resolved) src = resolved;
      } else if (t.id.startsWith("piped:") && !src) {
        const resolved = await resolvePipedAudio(t.id);
        if (resolved) src = resolved;
      }
      if (!src) {
        console.warn("Music: no playable URL for", t.id);
        return;
      }
      a.src = src;
      try {
        await a.play();
        if (t.is_8d) startPanRotation();
        else stopPanRotation();
      } catch (e) {
        console.warn("Music: play failed", e);
      }
      void syncNowPlaying(t, true, 0);
      // Persisted tracks only — virtual ids (audius:/piped:) skip DB write
      if (!isVirtualId(t.id)) {
        void supabase
          .from("music_tracks")
          .update({ play_count: (t.play_count ?? 0) + 1 })
          .eq("id", t.id);
      }
    },
    [ensureAudioGraph, startPanRotation, stopPanRotation, syncNowPlaying],
  );

  const getAmplitude = useCallback(() => {
    const an = analyserRef.current;
    const buf = analyserBufRef.current;
    if (!an || !buf) return 0;
    an.getByteFrequencyData(buf as unknown as Uint8Array<ArrayBuffer>);
    let sum = 0;
    for (let i = 0; i < buf.length; i++) sum += buf[i];
    return Math.min(1, sum / (buf.length * 255));
  }, []);

  const pause = useCallback(() => {
    audioRef.current?.pause();
    stopPanRotation();
    if (track) void syncNowPlaying(track, false, position);
  }, [track, position, syncNowPlaying, stopPanRotation]);

  const resume = useCallback(async () => {
    const a = audioRef.current;
    if (!a) return;
    try {
      await a.play();
      if (track?.is_8d) startPanRotation();
      if (track) void syncNowPlaying(track, true, a.currentTime);
    } catch {}
  }, [track, syncNowPlaying, startPanRotation]);

  const toggle = useCallback(async () => {
    if (isPlaying) pause();
    else await resume();
  }, [isPlaying, pause, resume]);

  const next = useCallback(async () => {
    if (!track || queue.length === 0) return;
    const idx = queue.findIndex((q) => q.id === track.id);
    const nxt = queue[idx + 1];
    if (nxt) await play(nxt, queue);
  }, [track, queue, play]);

  const prev = useCallback(async () => {
    if (!track || queue.length === 0) return;
    const idx = queue.findIndex((q) => q.id === track.id);
    const prv = queue[idx - 1];
    if (prv) await play(prv, queue);
    else audioRef.current && (audioRef.current.currentTime = 0);
  }, [track, queue, play]);

  const seek = useCallback((sec: number) => {
    const a = audioRef.current;
    if (!a) return;
    a.currentTime = Math.max(0, Math.min(sec, a.duration || sec));
    setPosition(a.currentTime);
  }, []);

  const stop = useCallback(async () => {
    const a = audioRef.current;
    if (!a) return;
    a.pause();
    a.currentTime = 0;
    setTrack(null);
    setIsPlaying(false);
    setPosition(0);
    stopPanRotation();
    await syncNowPlaying(null, false, 0);
  }, [syncNowPlaying, stopPanRotation]);

  const nextRef = useRef(next);
  const prevRef = useRef(prev);
  const pauseRef = useRef(pause);
  const resumeRef = useRef(resume);
  const seekRef = useRef(seek);
  useEffect(() => {
    nextRef.current = next;
    prevRef.current = prev;
    pauseRef.current = pause;
    resumeRef.current = resume;
    seekRef.current = seek;
  }, [next, prev, pause, resume, seek]);

  const value = useMemo<MusicContextValue>(
    () => ({
      tracks, loading, queue, track, isPlaying, position, duration,
      refetch, play, toggle, pause, resume, next, prev, seek, stop, getAmplitude,
      fadeVolume, setManualPan,
    }),
    [tracks, loading, queue, track, isPlaying, position, duration,
      refetch, play, toggle, pause, resume, next, prev, seek, stop, getAmplitude,
      fadeVolume, setManualPan],
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useJiyanMusic(): MusicContextValue {
  const v = useContext(Ctx);
  if (!v) {
    // Safe noop fallback so widgets in unmounted contexts (SSR, tests) don't crash.
    return {
      tracks: [],
      loading: false,
      queue: [],
      track: null,
      isPlaying: false,
      position: 0,
      duration: 0,
      refetch: async () => {},
      play: async () => {},
      toggle: async () => {},
      pause: () => {},
      resume: async () => {},
      next: async () => {},
      prev: async () => {},
      seek: () => {},
      stop: async () => {},
      getAmplitude: () => 0,
      fadeVolume: async () => {},
      setManualPan: () => {},
    };
  }
  return v;
}

/**
 * useNowPlayingFor — a Hub widget can call this for ANY user (e.g. self).
 * Reads `music_now_playing` directly so the widget reflects the truth even
 * if the global player isn't mounted on the current screen.
 */
export function useNowPlayingFor(userId: string | undefined) {
  const [row, setRow] = useState<{
    track_id: string | null;
    is_playing: boolean;
    position_seconds: number;
  } | null>(null);
  const [trackInfo, setTrackInfo] = useState<MusicTrack | null>(null);

  const fetchRow = useCallback(async () => {
    if (!userId) return;
    const { data } = await supabase
      .from("music_now_playing")
      .select("track_id,is_playing,position_seconds")
      .eq("user_id", userId)
      .maybeSingle();
    setRow(data ?? null);
    if (data?.track_id) {
      const { data: t } = await supabase
        .from("music_tracks")
        .select(
          "id,title,artist,album,category,duration_seconds,audio_url,audio_cid,cover_url,is_8d,language,tags,is_published,play_count,created_at",
        )
        .eq("id", data.track_id)
        .maybeSingle();
      setTrackInfo((t as MusicTrack) ?? null);
    } else {
      setTrackInfo(null);
    }
  }, [userId]);

  useEffect(() => {
    void fetchRow();
  }, [fetchRow]);

  useEffect(() => {
    if (!userId) return;
    const ch = supabase
      .channel(`now-playing-${userId}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "music_now_playing",
          filter: `user_id=eq.${userId}`,
        },
        () => void fetchRow(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(ch);
    };
  }, [userId, fetchRow]);

  return { row, track: trackInfo, refetch: fetchRow };
}

