import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface TVBroadcast {
  id: string;
  youtube_id: string;
  title: string;
  description: string | null;
  is_live: boolean;
  is_active: boolean;
  created_at: string;
  stream_url?: string | null;
  stream_type?: "youtube" | "hls";
}

export interface TVChannel {
  id: string;
  name: string;
  youtube_id: string;
  avatar_url: string | null;
  category: string;
  sort_order: number;
  stream_url?: string | null;
  stream_type?: "youtube" | "hls";
  is_pinned?: boolean;
}

export interface TVChatMessage {
  id: string;
  broadcast_id: string | null;
  user_id: string;
  content: string;
  created_at: string;
  profile?: { display_name: string; avatar_url: string | null };
}

export function useJiyanTV() {
  const [broadcast, setBroadcast] = useState<TVBroadcast | null>(null);
  const [channels, setChannels] = useState<TVChannel[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchData = useCallback(async () => {
    const [bRes, cRes] = await Promise.all([
      supabase
        .from("tv_broadcasts")
        .select("*")
        .eq("is_active", true)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle(),
      supabase
        .from("tv_channels")
        .select("*")
        .eq("is_active", true)
        .order("is_pinned", { ascending: false })
        .order("sort_order"),
    ]);
    if (bRes.data) setBroadcast(bRes.data as TVBroadcast);
    if (cRes.data) setChannels(cRes.data as TVChannel[]);
    setLoading(false);
  }, []);

  useEffect(() => {
    fetchData();
    const channel = supabase
      .channel("tv-broadcasts")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "tv_broadcasts" },
        () => fetchData()
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [fetchData]);

  return { broadcast, channels, loading, refetch: fetchData };
}

export function useTVChat(broadcastId: string | null) {
  const [messages, setMessages] = useState<TVChatMessage[]>([]);

  useEffect(() => {
    if (!broadcastId) return;
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from("tv_chat_messages")
        .select("*, profile:profiles!tv_chat_messages_user_id_fkey(display_name, avatar_url)")
        .eq("broadcast_id", broadcastId)
        .order("created_at", { ascending: false })
        .limit(50);
      if (!cancelled && data) setMessages((data as any[]).reverse() as TVChatMessage[]);
    })();

    const channel = supabase
      .channel(`tv-chat-${broadcastId}`)
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "tv_chat_messages", filter: `broadcast_id=eq.${broadcastId}` },
        async (payload) => {
          const m = payload.new as TVChatMessage;
          const { data: prof } = await supabase
            .from("profiles")
            .select("display_name, avatar_url")
            .eq("user_id", m.user_id)
            .maybeSingle();
          setMessages((prev) => [...prev.slice(-49), { ...m, profile: prof || undefined }]);
        }
      )
      .subscribe();
    return () => {
      cancelled = true;
      supabase.removeChannel(channel);
    };
  }, [broadcastId]);

  const send = useCallback(async (userId: string, content: string) => {
    if (!broadcastId || !content.trim()) return;
    await supabase.from("tv_chat_messages").insert({
      broadcast_id: broadcastId,
      user_id: userId,
      content: content.trim().slice(0, 200),
    });
  }, [broadcastId]);

  return { messages, send };
}

export function useTVReactions(broadcastId: string | null) {
  const [bursts, setBursts] = useState<{ id: number; emoji: string }[]>([]);

  useEffect(() => {
    if (!broadcastId) return;
    const channel = supabase
      .channel(`tv-reactions-${broadcastId}`)
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "tv_reactions", filter: `broadcast_id=eq.${broadcastId}` },
        (payload) => {
          const r = payload.new as { emoji: string };
          setBursts((prev) => [...prev, { id: Date.now() + Math.random(), emoji: r.emoji }]);
          setTimeout(() => {
            setBursts((prev) => prev.slice(1));
          }, 3000);
        }
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [broadcastId]);

  const react = useCallback(async (userId: string, emoji: string = "🔥") => {
    if (!broadcastId) return;
    await supabase.from("tv_reactions").insert({
      broadcast_id: broadcastId,
      user_id: userId,
      emoji,
    });
  }, [broadcastId]);

  return { bursts, react };
}

