/**
 * useJoogleSearch — streams sovereign search results from /functions/v1/joogle-search.
 *
 * Output frames:
 *   { type: "sources", sources: SourceCard[] }
 *   { type: "delta", text: string }
 *   { type: "done" }
 */
import { useCallback, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface JoogleSource {
  title: string;
  url: string;
  snippet: string;
  domain: string;
  kurdish: boolean;
}

export interface JoogleResult {
  query: string;
  answer: string;
  sources: JoogleSource[];
}

const ENDPOINT = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/joogle-search`;

export function useJoogleSearch() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<JoogleResult | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const search = useCallback(async (query: string) => {
    const q = query.trim();
    if (q.length < 2) return;

    abortRef.current?.abort();
    const ctrl = new AbortController();
    abortRef.current = ctrl;

    setError(null);
    setLoading(true);
    setResult({ query: q, answer: "", sources: [] });

    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData.session?.access_token ?? import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

      const resp = await fetch(ENDPOINT, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ query: q }),
        signal: ctrl.signal,
      });

      if (!resp.ok || !resp.body) {
        const txt = await resp.text().catch(() => "");
        throw new Error(`Joogle: ${resp.status} ${txt.slice(0, 120)}`);
      }

      const reader = resp.body.getReader();
      const decoder = new TextDecoder();
      let buf = "";
      let done = false;

      while (!done) {
        const { done: d, value } = await reader.read();
        if (d) break;
        buf += decoder.decode(value, { stream: true });
        let nl: number;
        while ((nl = buf.indexOf("\n")) !== -1) {
          let line = buf.slice(0, nl);
          buf = buf.slice(nl + 1);
          if (line.endsWith("\r")) line = line.slice(0, -1);
          if (!line.startsWith("data: ")) continue;
          const json = line.slice(6).trim();
          if (!json) continue;
          try {
            const evt = JSON.parse(json);
            if (evt.type === "sources") {
              setResult((r) => r ? { ...r, sources: evt.sources } : r);
            } else if (evt.type === "delta") {
              setResult((r) => r ? { ...r, answer: r.answer + evt.text } : r);
            } else if (evt.type === "done") {
              done = true;
            }
          } catch {
            // partial — re-buffer
            buf = line + "\n" + buf;
            break;
          }
        }
      }
    } catch (e) {
      if ((e as Error).name === "AbortError") return;
      setError((e as Error).message || "Lêgerîn neserkeftî bû");
    } finally {
      setLoading(false);
    }
  }, []);

  const reset = useCallback(() => {
    abortRef.current?.abort();
    setResult(null);
    setError(null);
    setLoading(false);
  }, []);

  return { loading, error, result, search, reset };
}

