import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface KekaVideo {
  id: string;
  user_id: string;
  video_url: string;
  thumbnail_url: string | null;
  caption: string;
  duration_seconds: number;
  view_count: number;
  like_count: number;
  comment_count: number;
  tip_count: number;
  tip_total: number;
  is_published: boolean;
  is_adult?: boolean;
  is_dengbej?: boolean;
  is_live?: boolean;
  live_started_at?: string | null;
  moderation_status?: string;
  created_at: string;
  profile?: {
    display_name: string | null;
    avatar_url: string | null;
    kurd_id: string | null;
    is_verified_creator?: boolean | null;
    is_premium?: boolean | null;
  } | null;
}

export type KekaFeedMode = "foryou" | "following";

export function useKekaFeed(limit = 30, mode: KekaFeedMode = "foryou") {
  const [videos, setVideos] = useState<KekaVideo[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchFeed = useCallback(async () => {
    setLoading(true);
    // 1. Determine current user + adult preference + blocked ids
    const { data: u } = await supabase.auth.getUser();
    const me = u.user?.id ?? null;

    let showAdult = false;
    const blockedIds = new Set<string>();
    let followingIds: string[] = [];

    if (me) {
      const { data: profile } = await supabase
        .from("profiles")
        .select("show_adult_content")
        .eq("user_id", me)
        .maybeSingle();
      showAdult = !!profile?.show_adult_content;

      // Two-way block: hide videos from anyone in either direction
      const { data: blocks } = await supabase
        .from("user_blocks")
        .select("blocker_id, blocked_id")
        .or(`blocker_id.eq.${me},blocked_id.eq.${me}`);
      (blocks || []).forEach((b: any) => {
        blockedIds.add(b.blocker_id === me ? b.blocked_id : b.blocker_id);
      });

      if (mode === "following") {
        const { data: rels } = await supabase
          .from("follows")
          .select("following_id")
          .eq("follower_id", me);
        followingIds = (rels || []).map((r: any) => r.following_id);
      }
    }

    // Following mode but user not logged in or follows nobody → empty result
    if (mode === "following" && (!me || followingIds.length === 0)) {
      setVideos([]);
      setLoading(false);
      return;
    }

    let query = supabase
      .from("keka_videos")
      .select("*")
      .eq("is_published", true)
      .order("created_at", { ascending: false })
      .limit(limit);

    if (!showAdult) query = query.eq("is_adult", false);
    if (mode === "following") query = query.in("user_id", followingIds);

    const { data: rows } = await query;

    const filtered = (rows || []).filter((v: any) => !blockedIds.has(v.user_id));

    if (filtered.length === 0) {
      setVideos([]);
      setLoading(false);
      return;
    }

    const userIds = Array.from(new Set(filtered.map((v: any) => v.user_id)));
    const { data: profiles } = await supabase
      .from("profiles")
      .select("user_id, display_name, avatar_url, kurd_id, is_verified_creator, is_premium")
      .in("user_id", userIds);

    const map = new Map((profiles || []).map((p) => [p.user_id, p]));
    setVideos(
      filtered.map((v: any) => ({
        ...v,
        profile: map.get(v.user_id) ?? null,
      })) as KekaVideo[],
    );
    setLoading(false);
  }, [limit, mode]);

  useEffect(() => {
    fetchFeed();
  }, [fetchFeed]);

  return { videos, loading, refetch: fetchFeed };
}

export async function kekaToggleLike(videoId: string) {
