export async function uploadKekaVideo(
  userId: string,
  blob: Blob,
  caption: string,
  isAdult = false,
  opts: { isDengbej?: boolean } = {},
): Promise<KekaVideo> {
  // Pick correct extension from MIME type so the public URL ends with the
  // right suffix (some browsers refuse to play when extension lies about MIME).
  const type = blob.type || "video/mp4";
  const ext = type.includes("quicktime")
    ? "mov"
    : type.includes("mp4")
      ? "mp4"
      : type.includes("webm")
        ? "webm"
        : type.includes("ogg")
          ? "ogg"
          : "mp4";
  const filename = `${userId}/${Date.now()}.${ext}`;
  const { error: upErr } = await supabase.storage
    .from("keka-videos")
    .upload(filename, blob, { contentType: type, upsert: false });
  if (upErr) throw upErr;
  const { data: pub } = supabase.storage.from("keka-videos").getPublicUrl(filename);
  const { data: row, error: insErr } = await supabase
    .from("keka_videos")
    .insert({
      user_id: userId,
      video_url: pub.publicUrl,
      caption,
      duration_seconds: 15,
      is_adult: isAdult,
      is_dengbej: !!opts.isDengbej,
    })
    .select()
    .single();
  if (insErr) throw insErr;

  // Extract & attach hashtags from caption (best-effort, non-blocking)
  if (caption && caption.includes("#")) {
    supabase
      .rpc("keka_attach_hashtags", { _video_id: row.id, _caption: caption })
      .then(() => {});
  }

  // Trigger AI moderation in background (non-blocking)
  if (caption && caption.trim()) {
    supabase.functions
      .invoke("moderate-keka-content", {
        body: { video_id: row.id, caption },
      })
      .catch((e) => console.warn("[KEKA] moderation failed", e));
  }

  return row as KekaVideo;
}

// ─── Moderation & Safety ──────────────────────────────────────────────────
export async function reportKekaVideo(
  videoId: string,
  reason: string,
  details?: string,
) {
  const { data, error } = await supabase.rpc("keka_report_video", {
    _video_id: videoId,
    _reason: reason,
    ...(details ? { _details: details } : {}),
  } as any);
  if (error) throw error;
  return data as {
    success: boolean;
