import { useCallback, useEffect, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

/**
 * Sovereign Energy — hybrid (localStorage cache + Supabase persistence).
 *
 * Rules:
 *   • Max 100, refill to 100 when >= 24h since last_refill_at
 *   • Watching a KEKA video: 2 units
 *   • Recording a KEKA video: 10 units
 *   • Anonymous users: localStorage only
 *   • Authenticated: write-through to public.user_keka_energy via RPC
 */
export const ENERGY_MAX = 100;
export const ENERGY_COST = {
  WATCH: 2,
  RECORD: 10,
} as const;
export type EnergyAction = keyof typeof ENERGY_COST;

const LS_KEY = "jiyan_keka_energy";
const REFILL_MS = 24 * 60 * 60 * 1000;

type EnergyState = { energy: number; last_refill_at: string };

function readLocal(): EnergyState {
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (!raw) return { energy: ENERGY_MAX, last_refill_at: new Date().toISOString() };
    const parsed = JSON.parse(raw) as EnergyState;
    return applyRefill(parsed);
  } catch {
    return { energy: ENERGY_MAX, last_refill_at: new Date().toISOString() };
  }
}

function writeLocal(state: EnergyState) {
  try {
    localStorage.setItem(LS_KEY, JSON.stringify(state));
  } catch {
    // Silently fail if storage is blocked
  }
}

function applyRefill(s: EnergyState): EnergyState {
  const last = new Date(s.last_refill_at).getTime();
  if (Date.now() - last >= REFILL_MS) {
    return { energy: ENERGY_MAX, last_refill_at: new Date().toISOString() };
  }
  return s;
}

export function useKekaEnergy(userId: string | undefined) {
  // SSR-safe: always start with the same default on server + first client render,
  // then hydrate from localStorage in an effect to avoid hydration mismatch.
  const [state, setState] = useState<EnergyState>(() => ({
    energy: ENERGY_MAX,
    last_refill_at: new Date(0).toISOString(),
  }));
  const syncedRef = useRef(false);

  // Hydrate from localStorage after mount (client-only)
  useEffect(() => {
    const local = readLocal();
    setState(local);
    writeLocal(local);
  }, []);

  // Sync from Supabase on mount when user is logged in
  useEffect(() => {
    if (!userId || syncedRef.current) return;
    syncedRef.current = true;
    (async () => {
      const { data } = await supabase
        .from("user_keka_energy")
        .select("energy, last_refill_at")
        .eq("user_id", userId)
        .maybeSingle();
      if (data) {
        const refilled = applyRefill({
          energy: data.energy,
          last_refill_at: data.last_refill_at,
        });
        setState(refilled);
        writeLocal(refilled);
      }
    })();
  }, [userId]);

  // Tick: re-evaluate refill every minute (cheap)
  useEffect(() => {
    const id = setInterval(() => {
      setState((prev) => {
        const next = applyRefill(prev);
        if (next.energy !== prev.energy) writeLocal(next);
        return next;
      });
    }, 60_000);
    return () => clearInterval(id);
  }, []);

  /** Try to spend `cost` energy. Returns true if successful. */
  const consume = useCallback(
    async (action: EnergyAction): Promise<{ ok: boolean; energy: number; reason?: string }> => {
      const cost = ENERGY_COST[action];

      // Local guard first (instant UX)
      const current = applyRefill(state);
      if (current.energy < cost) {
        if (current.energy !== state.energy) {
          setState(current);
          writeLocal(current);
        }
        return { ok: false, energy: current.energy, reason: "not_enough_energy" };
      }

      // Optimistic local deduction
      const optimistic: EnergyState = {
        energy: current.energy - cost,
        last_refill_at: current.last_refill_at,
      };
      setState(optimistic);
      writeLocal(optimistic);

      // Server sync (only when authenticated)
      if (userId) {
        try {
          const { data, error } = await supabase.rpc("keka_consume_energy", { _cost: cost });
          if (error || !data) return { ok: true, energy: optimistic.energy };
          const payload = data as { success: boolean; energy?: number; last_refill_at?: string; error?: string };
          if (payload.success && typeof payload.energy === "number" && payload.last_refill_at) {
            const synced: EnergyState = {
              energy: payload.energy,
              last_refill_at: payload.last_refill_at,
            };
            setState(synced);
            writeLocal(synced);
            return { ok: true, energy: payload.energy };
          }
          if (!payload.success) {
            // Server says no — revert optimistic
            const reverted: EnergyState = {
              energy: payload.energy ?? current.energy,
              last_refill_at: payload.last_refill_at ?? current.last_refill_at,
            };
            setState(reverted);
            writeLocal(reverted);
            return { ok: false, energy: reverted.energy, reason: payload.error };
          }
        } catch {
          // network failure → keep optimistic local state
        }
      }

      return { ok: true, energy: optimistic.energy };
    },
    [state, userId],
  );

  const msUntilRefill = Math.max(
    0,
    new Date(state.last_refill_at).getTime() + REFILL_MS - Date.now(),
  );

  return {
    energy: state.energy,
    max: ENERGY_MAX,
    msUntilRefill,
    consume,
  };
}

/** Format ms to "Xs / Xm / Xh" */
export function formatRefillIn(ms: number): string {
  if (ms <= 0) return "şimdi";
  const h = Math.floor(ms / 3_600_000);
  const m = Math.floor((ms % 3_600_000) / 60_000);
  if (h > 0) return `${h}sa ${m}dk`;
  if (m > 0) return `${m}dk`;
  return `${Math.ceil(ms / 1000)}sn`;
}

