import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

/**
 * KEKA Points → DiravCash bridge.
 * 100 puan = 1 DC (defined server-side in keka_redeem_points RPC).
 */
export const POINTS_PER_DC = 100;

export function useKekaPoints(userId: string | undefined) {
  const [points, setPoints] = useState<number>(0);
  const [loading, setLoading] = useState(false);
  const [redeeming, setRedeeming] = useState(false);

  const refresh = useCallback(async () => {
    if (!userId) return;
    setLoading(true);
    const { data } = await supabase
      .from("profiles")
      .select("keka_points")
      .eq("user_id", userId)
      .maybeSingle();
    setPoints(data?.keka_points ?? 0);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    if (!userId) {
      setPoints(0);
      return;
    }
    refresh();
  }, [userId, refresh]);

  /** Redeem `_points` (must be ≥100, multiple of 100). */
  const redeem = useCallback(
    async (
      _points: number,
    ): Promise<
      | { success: true; dc_credited: number; new_balance: number; remaining_points: number }
      | { success: false; error: string }
    > => {
      setRedeeming(true);
      try {
        const { data, error } = await supabase.rpc("keka_redeem_points", { _points });
        if (error) return { success: false, error: error.message };
        const payload = data as {
          success: boolean;
          dc_credited?: number;
          new_balance?: number;
          remaining_points?: number;
          error?: string;
        };
        if (!payload?.success) {
          return { success: false, error: payload?.error ?? "redeem_failed" };
        }
        setPoints(payload.remaining_points ?? 0);
        return {
          success: true,
          dc_credited: payload.dc_credited!,
          new_balance: payload.new_balance!,
          remaining_points: payload.remaining_points!,
        };
      } finally {
        setRedeeming(false);
      }
    },
    [],
  );

  const dcEquivalent = Math.floor(points / POINTS_PER_DC);
  const canRedeem = points >= POINTS_PER_DC;

  return { points, dcEquivalent, canRedeem, loading, redeeming, refresh, redeem };
}

