/**
 * useLanguagePair — first-run onboarding state for Linguist.
 * Persists "native" (known) + "target" (learning) language in localStorage.
 */
import { useCallback, useEffect, useState } from "react";
import type { Language } from "@/data/linguistContent";

export interface LangPair {
  native: Language;
  target: Language;
}

const KEY = "linguist:langs:v1";
const DEFAULT: LangPair = { native: "tr", target: "ku" };

export function useLanguagePair() {
  const [pair, setPair] = useState<LangPair | null>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) {
        const p = JSON.parse(raw) as Partial<LangPair>;
        if (p.native && p.target && p.native !== p.target) {
          setPair({ native: p.native as Language, target: p.target as Language });
        }
      }
    } catch { /* ignore */ }
    setReady(true);
  }, []);

  const save = useCallback((p: LangPair) => {
    if (p.native === p.target) return;
    setPair(p);
    try { localStorage.setItem(KEY, JSON.stringify(p)); } catch { /* ignore */ }
  }, []);

  const reset = useCallback(() => {
    setPair(null);
    try { localStorage.removeItem(KEY); } catch { /* ignore */ }
  }, []);

  return { pair, ready, save, reset, isFirstRun: ready && !pair, DEFAULT };
}

