import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export interface ProgressRow {
  id: string;
  language: string;
  level: string;
  lesson_id: string;
  score: number;
  xp_earned: number;
  dc_earned: number;
  completed_at: string;
}

export interface CertificateRow {
  id: string;
  language: string;
  level: string;
  certificate_no: string;
  issued_at: string;
}

export function useLinguist() {
  const { user } = useAuth();
  const [progress, setProgress] = useState<ProgressRow[]>([]);
  const [certificates, setCertificates] = useState<CertificateRow[]>([]);
  const [hasConsent, setHasConsent] = useState<boolean | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchAll = useCallback(async () => {
    if (!user) {
      setProgress([]);
      setCertificates([]);
      setHasConsent(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    const [{ data: prog }, { data: certs }, { data: consent }] = await Promise.all([
      supabase.from("linguist_progress").select("*").eq("user_id", user.id).order("completed_at", { ascending: false }),
      supabase.from("linguist_certificates").select("*").eq("user_id", user.id).order("issued_at", { ascending: false }),
      supabase.from("linguist_consents").select("id").eq("user_id", user.id).maybeSingle(),
    ]);
    setProgress((prog ?? []) as ProgressRow[]);
    setCertificates((certs ?? []) as CertificateRow[]);
    setHasConsent(!!consent);
    setLoading(false);
  }, [user]);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  const grantConsent = useCallback(async () => {
    if (!user) return { success: false, error: "Auth required" };
    const { error } = await supabase
      .from("linguist_consents")
      .insert({ user_id: user.id, version: "1.0" });
    if (error && !error.message.includes("duplicate")) return { success: false, error: error.message };
    setHasConsent(true);
    return { success: true };
  }, [user]);

  const completeLesson = useCallback(
    async (language: string, level: string, lessonId: string, score: number, xp: number, isMilestone: boolean) => {
      if (!user) return { success: false, error: "Auth required" };
      const { data, error } = await supabase.rpc("complete_linguist_lesson", {
        _language: language,
        _level: level,
        _lesson_id: lessonId,
        _score: score,
        _xp: xp,
        _is_milestone: isMilestone,
      });
      if (error) return { success: false, error: error.message };
      await fetchAll();
      return data as { success: boolean; xp: number; dc: number; already_completed?: boolean; milestone?: boolean };
    },
    [user, fetchAll]
  );

  const issueCertificate = useCallback(
    async (language: string, level: string) => {
      if (!user) return { success: false, error: "Auth required" };
      const { data, error } = await supabase.rpc("issue_linguist_certificate", {
        _language: language,
        _level: level,
      });
      if (error) return { success: false, error: error.message };
      await fetchAll();
      return data as { success: boolean; certificate_no: string; already_issued?: boolean };
    },
    [user, fetchAll]
  );

  return {
    progress,
    certificates,
    hasConsent,
    loading,
    grantConsent,
    completeLesson,
    issueCertificate,
    refetch: fetchAll,
  };
}

