import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export interface LinguistSettings {
  user_id: string;
  daily_goal_minutes: number;
  source_language: string;
  target_language: string;
  current_streak: number;
  longest_streak: number;
  last_study_date: string | null;
}

export interface StudySession {
  session_date: string;
  minutes_studied: number;
  cards_mastered: number;
  goal_reached: boolean;
}

export interface FlashcardState {
  card_id: string;
  status: "new" | "learning" | "review" | "mastered";
  repetitions: number;
}

export function useLinguistAcademy() {
  const { user } = useAuth();
  const [settings, setSettings] = useState<LinguistSettings | null>(null);
  const [sessions, setSessions] = useState<StudySession[]>([]);
  const [cardStates, setCardStates] = useState<Record<string, FlashcardState>>({});
  const [loading, setLoading] = useState(true);

  const fetchAll = useCallback(async () => {
    if (!user) {
      setSettings(null);
      setSessions([]);
      setCardStates({});
      setLoading(false);
      return;
    }
    setLoading(true);
    const since = new Date();
    since.setDate(since.getDate() - 6);
    const sinceStr = since.toISOString().slice(0, 10);

    const [{ data: s }, { data: ss }, { data: cs }] = await Promise.all([
      supabase.from("linguist_settings").select("*").eq("user_id", user.id).maybeSingle(),
      supabase
        .from("linguist_study_sessions")
        .select("session_date, minutes_studied, cards_mastered, goal_reached")
        .eq("user_id", user.id)
        .gte("session_date", sinceStr)
        .order("session_date", { ascending: true }),
      supabase
        .from("linguist_flashcard_state")
        .select("card_id, status, repetitions")
        .eq("user_id", user.id),
    ]);

    setSettings((s as LinguistSettings | null) ?? null);
    setSessions((ss ?? []) as StudySession[]);
    const map: Record<string, FlashcardState> = {};
    (cs ?? []).forEach((c) => {
      map[c.card_id] = c as FlashcardState;
    });
    setCardStates(map);
    setLoading(false);
  }, [user]);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  const saveSettings = useCallback(
    async (patch: Partial<Omit<LinguistSettings, "user_id">>) => {
      if (!user) return { success: false, error: "auth required" };
      const { error } = await supabase
        .from("linguist_settings")
        .upsert({ user_id: user.id, ...patch }, { onConflict: "user_id" });
      if (error) return { success: false, error: error.message };
      await fetchAll();
      return { success: true };
    },
    [user, fetchAll]
  );

  const setCardStatus = useCallback(
    async (cardId: string, language: string, mastered: boolean) => {
      if (!user) return;
      const status = mastered ? "mastered" : "review";
      const prev = cardStates[cardId];
      const reps = (prev?.repetitions ?? 0) + 1;
      // optimistic update
      setCardStates((cur) => ({ ...cur, [cardId]: { card_id: cardId, status, repetitions: reps } }));
      await supabase.from("linguist_flashcard_state").upsert(
        {
          user_id: user.id,
          card_id: cardId,
          language,
          status,
          repetitions: reps,
          last_seen_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
        { onConflict: "user_id,card_id,language" }
      );
    },
    [user, cardStates]
  );

  const recordSession = useCallback(
    async (minutes: number, cardsMastered: number) => {
      if (!user) return { success: false };
      const { data, error } = await supabase.rpc("record_linguist_session", {
        _minutes: minutes,
        _cards_mastered: cardsMastered,
      });
      if (error) return { success: false, error: error.message };
      await fetchAll();
      return data as {
        success: boolean;
        minutes_today: number;
        goal_reached: boolean;
        streak: number;
        badge_awarded: boolean;
        milestone_dc: number;
      };
    },
    [user, fetchAll]
  );

  return {
    settings,
    sessions,
    cardStates,
    loading,
    saveSettings,
    setCardStatus,
    recordSession,
    refetch: fetchAll,
  };
}

