/**
 * useLowPowerMode — Returns true when the user's OS reports
 * `prefers-reduced-motion: reduce`.
 *
 * Components can use this to skip particle systems, heavy blurs, and
 * continuous animations.
 */
import { useEffect, useState } from "react";

export function useLowPowerMode(): boolean {
  const [low, setLow] = useState<boolean>(() => {
    if (typeof window === "undefined" || !window.matchMedia) return false;
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  });

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = (e: MediaQueryListEvent) => setLow(e.matches);
    mq.addEventListener?.("change", onChange);
    return () => mq.removeEventListener?.("change", onChange);
  }, []);

  return low;
}

