/**
 * useMail — Gmail-style mailbox built on top of `inbox_messages`.
 *
 * Folders: inbox | starred | sent | drafts | system | archived | trash
 * Actions: star, archive, trash, restore, deletePermanent, markRead,
 *          saveDraft, sendDraft, send (one-shot)
 *
 * The hook subscribes to realtime INSERT/UPDATE/DELETE on inbox_messages
 * for the current user (as recipient OR sender) so every folder stays in
 * sync across tabs without manual refetch.
 */
import { useCallback, useEffect, useMemo, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export type MailFolder =
  | "inbox"
  | "starred"
  | "sent"
  | "drafts"
  | "system"
  | "archived"
  | "trash";

export interface MailMessage {
  id: string;
  sender_id: string | null;
  recipient_id: string | null;
  subject: string;
  body: string;
  message_type: string;
  is_read: boolean;
  is_starred: boolean;
  is_archived: boolean;
  is_trashed: boolean;
  is_draft: boolean;
  reference_code: string | null;
  trashed_at: string | null;
  created_at: string;
  updated_at: string;
}

const PAGE_SIZE = 200;

export function useMail(userId: string | undefined) {
  const [messages, setMessages] = useState<MailMessage[]>([]);
  const [loading, setLoading] = useState(true);

  /** Pull both inbox (recipient) AND outgoing (sender) so every folder is filterable client-side. */
  const refresh = useCallback(async () => {
    if (!userId) {
      setMessages([]);
      setLoading(false);
      return;
    }
    const { data } = await supabase
      .from("inbox_messages")
      .select(
        "id,sender_id,recipient_id,subject,body,message_type,is_read,is_starred,is_archived,is_trashed,is_draft,reference_code,trashed_at,created_at,updated_at",
      )
      .or(`recipient_id.eq.${userId},sender_id.eq.${userId}`)
      .order("created_at", { ascending: false })
      .limit(PAGE_SIZE);
    setMessages((data ?? []) as MailMessage[]);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Realtime — keep the cache fresh on every change touching this user.
  useEffect(() => {
    if (!userId) return;
    const ch = supabase
      .channel(`mail-${userId}`)
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "inbox_messages", filter: `recipient_id=eq.${userId}` },
        () => refresh(),
      )
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "inbox_messages", filter: `sender_id=eq.${userId}` },
        () => refresh(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(ch);
    };
  }, [userId, refresh]);

  /** Folder counts (unread inbox / drafts / starred). */
  const counts = useMemo(() => {
    let inboxUnread = 0;
    let drafts = 0;
    let starred = 0;
    for (const m of messages) {
      if (
        m.recipient_id === userId &&
        !m.is_trashed &&
        !m.is_archived &&
        !m.is_read &&
        !m.is_draft
      ) {
        inboxUnread++;
      }
      if (m.is_draft && m.sender_id === userId) drafts++;
      if (
        m.is_starred &&
        !m.is_trashed &&
        (m.recipient_id === userId || m.sender_id === userId)
      ) {
        starred++;
      }
    }
    return { inboxUnread, drafts, starred };
  }, [messages, userId]);

  /** Filter the cached set by folder. */
  const filterFolder = useCallback(
    (folder: MailFolder): MailMessage[] => {
      if (!userId) return [];
      return messages.filter((m) => {
        if (m.is_trashed && folder !== "trash") return false;
        switch (folder) {
          case "inbox":
            return (
              m.recipient_id === userId &&
              !m.is_archived &&
              !m.is_draft &&
              m.message_type !== "system" &&
              m.message_type !== "verification"
            );
          case "system":
            return (
              m.recipient_id === userId &&
              !m.is_archived &&
              (m.message_type === "system" || m.message_type === "verification")
            );
          case "starred":
            return m.is_starred && (m.recipient_id === userId || m.sender_id === userId);
          case "sent":
            return m.sender_id === userId && !m.is_draft;
          case "drafts":
            return m.is_draft && m.sender_id === userId;
          case "archived":
            return m.recipient_id === userId && m.is_archived;
          case "trash":
            return m.is_trashed && (m.recipient_id === userId || m.sender_id === userId);
          default:
            return false;
        }
      });
    },
    [messages, userId],
  );

  // ---- mutations ----------------------------------------------------------

  const patch = useCallback(async (id: string, patch: Partial<MailMessage>) => {
    setMessages((prev) => prev.map((m) => (m.id === id ? { ...m, ...patch } : m)));
    await supabase.from("inbox_messages").update(patch).eq("id", id);
  }, []);

  const markAsRead = useCallback((id: string) => patch(id, { is_read: true }), [patch]);
  const toggleStar = useCallback(
    (m: MailMessage) => patch(m.id, { is_starred: !m.is_starred }),
    [patch],
  );
  const archive = useCallback(
    (id: string) => patch(id, { is_archived: true, is_read: true }),
    [patch],
  );
  const unarchive = useCallback(
    (id: string) => patch(id, { is_archived: false }),
    [patch],
  );
  const trash = useCallback(
    (id: string) =>
      patch(id, { is_trashed: true, trashed_at: new Date().toISOString(), is_read: true }),
    [patch],
  );
  const restoreFromTrash = useCallback(
    (id: string) => patch(id, { is_trashed: false, trashed_at: null }),
    [patch],
  );

  const deletePermanent = useCallback(async (id: string) => {
    setMessages((prev) => prev.filter((m) => m.id !== id));
    await supabase.from("inbox_messages").delete().eq("id", id);
  }, []);

  const markAllInboxRead = useCallback(async () => {
    if (!userId) return;
    setMessages((prev) =>
      prev.map((m) => (m.recipient_id === userId && !m.is_trashed ? { ...m, is_read: true } : m)),
    );
    await supabase
      .from("inbox_messages")
      .update({ is_read: true })
      .eq("recipient_id", userId)
      .eq("is_read", false);
  }, [userId]);

  /** Send via the existing RPC (resolves @username / +777 ID, validates limits). */
  const send = useCallback(
    async (recipient: string, subject: string, body: string) => {
      if (!userId) throw new Error("Önce giriş yapın");
      const { data, error } = await supabase.rpc("send_inbox_message", {
        _sender_id: userId,
        _recipient_identifier: recipient,
        _subject: subject || "(Konusuz)",
        _body: body,
      });
      if (error) throw error;
      const r = data as { success?: boolean; error?: string };
      if (!r?.success) throw new Error(r?.error ?? "Gönderilemedi");
      await refresh();
      return r;
    },
    [userId, refresh],
  );

  /** Save / update a draft (sender only, recipient optional). */
  const saveDraft = useCallback(
    async (draft: { id?: string; recipient?: string; subject: string; body: string }) => {
      if (!userId) throw new Error("Önce giriş yapın");
      const payload = {
        sender_id: userId,
        recipient_id: null,
        subject: draft.subject || "(Taslak)",
        body: draft.body,
        message_type: "user",
        is_draft: true,
        is_read: true,
      };
      if (draft.id) {
        await supabase
          .from("inbox_messages")
          .update({ subject: payload.subject, body: payload.body })
          .eq("id", draft.id);
        return draft.id;
      }
      const { data, error } = await supabase
        .from("inbox_messages")
        .insert(payload)
        .select("id")
        .single();
      if (error) throw error;
      await refresh();
      return data.id as string;
    },
    [userId, refresh],
  );

  /** Send a saved draft: resend through RPC and remove the draft row. */
  const sendDraft = useCallback(
    async (draftId: string, recipient: string, subject: string, body: string) => {
      const result = await send(recipient, subject, body);
      await supabase.from("inbox_messages").delete().eq("id", draftId);
      await refresh();
      return result;
    },
    [send, refresh],
  );

  return {
    messages,
    loading,
    counts,
    filterFolder,
    refresh,
    markAsRead,
    markAllInboxRead,
    toggleStar,
    archive,
    unarchive,
    trash,
    restoreFromTrash,
    deletePermanent,
    send,
    saveDraft,
    sendDraft,
  };
}

