import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { MANIFESTO_VERSION } from "@/data/manifesto";

/**
 * useManifestoSeal — checks if the current user has sealed the WKO Doctrine,
 * and exposes a `seal()` action to grant the "Dengbêjê Manifestoyê" title.
 */
export function useManifestoSeal() {
  const { user } = useAuth();
  const [isSealed, setIsSealed] = useState(false);
  const [sealedAt, setSealedAt] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  // Load existing seal
  useEffect(() => {
    if (!user) {
      setIsSealed(false);
      setSealedAt(null);
      return;
    }
    let cancelled = false;
    (async () => {
      const { data, error } = await supabase
        .from("manifesto_seals")
        .select("sealed_at")
        .eq("user_id", user.id)
        .maybeSingle();
      if (cancelled) return;
      if (!error && data) {
        setIsSealed(true);
        setSealedAt(data.sealed_at);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [user]);

  const seal = useCallback(async (): Promise<{ ok: boolean; error?: string }> => {
    if (!user) return { ok: false, error: "login_required" };
    if (isSealed) return { ok: false, error: "already_sealed" };
    setLoading(true);
    const { data, error } = await supabase
      .from("manifesto_seals")
      .insert({
        user_id: user.id,
        manifesto_version: MANIFESTO_VERSION,
        title: "Dengbêjê Manifestoyê",
      })
      .select("sealed_at")
      .single();
    setLoading(false);
    if (error) {
      // Unique violation = already sealed (race condition / refresh)
      if (error.code === "23505") {
        setIsSealed(true);
        return { ok: false, error: "already_sealed" };
      }
      return { ok: false, error: error.message };
    }
    setIsSealed(true);
    setSealedAt(data.sealed_at);
    return { ok: true };
  }, [user, isSealed]);

  return { isSealed, sealedAt, seal, loading };
}

