import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

interface MarketplaceService {
  id: string;
  provider_id: string;
  title: string;
  description: string | null;
  category: string;
  price: number;
  price_type: string;
  city: string;
  rating: number | null;
  review_count: number | null;
  is_active: boolean;
  is_available: boolean;
  response_time_minutes: number;
  completed_jobs: number;
  created_at: string;
  provider?: {
    display_name: string;
    avatar_url: string | null;
    is_verified: boolean;
    is_premium: boolean;
    is_available: boolean;
  };
}

interface JobRequest {
  id: string;
  user_id: string;
  title: string;
  description: string;
  category: string;
  budget: number | null;
  urgency: string;
  city: string;
  status: string;
  created_at: string;
  bid_count?: number;
  user?: { display_name: string; avatar_url: string | null };
}

interface JobBid {
  id: string;
  job_id: string;
  provider_id: string;
  price: number;
  message: string;
  estimated_hours: number | null;
  status: string;
  created_at: string;
  provider?: { display_name: string; avatar_url: string | null; is_verified: boolean };
}

interface SmartSuggestion {
  icon: string;
  text: string;
  type: string;
  category?: string;
}

export function useMarketplace(filters?: { category?: string; city?: string; search?: string; availableOnly?: boolean }) {
  const [services, setServices] = useState<MarketplaceService[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetch = async () => {
      let query = supabase
        .from("services")
        .select("*")
        .eq("is_active", true)
        .order("is_available", { ascending: false })
        .order("rating", { ascending: false })
        .limit(50);

      if (filters?.category && filters.category !== "all") {
        query = query.eq("category", filters.category);
      }
      if (filters?.city) query = query.eq("city", filters.city);
      if (filters?.availableOnly) query = query.eq("is_available", true);
      if (filters?.search) {
        query = query.or(`title.ilike.%${filters.search}%,description.ilike.%${filters.search}%`);
      }

      const { data } = await query;
      if (!data) { setServices([]); setLoading(false); return; }

      // Enrich with provider info
      const providerIds = [...new Set(data.map(s => s.provider_id))];
      const { data: profiles } = await supabase
        .from("profiles")
        .select("user_id, display_name, avatar_url, is_verified, is_premium, is_available")
        .in("user_id", providerIds);

      const profileMap = new Map((profiles || []).map(p => [p.user_id, p]));
      const enriched = data.map(s => ({
        ...s,
        provider: profileMap.get(s.provider_id) || undefined,
      })) as MarketplaceService[];

      setServices(enriched);
      setLoading(false);
    };
    fetch();
  }, [filters?.category, filters?.city, filters?.search, filters?.availableOnly]);

  return { services, loading };
}

export function useAvailableProviders(city?: string) {
  const [providers, setProviders] = useState<MarketplaceService[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetch = async () => {
      let query = supabase
        .from("services")
        .select("*")
        .eq("is_active", true)
        .eq("is_available", true)
        .order("rating", { ascending: false })
        .limit(20);

      if (city) query = query.eq("city", city);
      const { data } = await query;
      if (!data) { setProviders([]); setLoading(false); return; }

      const providerIds = [...new Set(data.map(s => s.provider_id))];
      const { data: profiles } = await supabase
        .from("profiles")
        .select("user_id, display_name, avatar_url, is_verified, is_premium, is_available")
        .in("user_id", providerIds);

      const profileMap = new Map((profiles || []).map(p => [p.user_id, p]));
      setProviders(data.map(s => ({ ...s, provider: profileMap.get(s.provider_id) || undefined })) as MarketplaceService[]);
      setLoading(false);
    };
    fetch();
  }, [city]);

  return { providers, loading };
}

export function useJobRequests(userId?: string) {
  const [jobs, setJobs] = useState<JobRequest[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchJobs = useCallback(async () => {
    const { data } = await supabase
      .from("job_requests")
      .select("*")
      .eq("status", "open")
      .order("created_at", { ascending: false })
      .limit(50);

    if (!data) { setJobs([]); setLoading(false); return; }

    // Get user info and bid counts
    const userIds = [...new Set(data.map(j => j.user_id))];
    const jobIds = data.map(j => j.id);

    const [{ data: profiles }, { data: bids }] = await Promise.all([
      supabase.from("profiles").select("user_id, display_name, avatar_url").in("user_id", userIds),
      supabase.from("job_bids").select("job_id").in("job_id", jobIds),
    ]);

    const profileMap = new Map((profiles || []).map(p => [p.user_id, p]));
    const bidCounts: Record<string, number> = {};
    (bids || []).forEach(b => { bidCounts[b.job_id] = (bidCounts[b.job_id] || 0) + 1; });

    setJobs(data.map(j => ({
      ...j,
      user: profileMap.get(j.user_id) || undefined,
      bid_count: bidCounts[j.id] || 0,
    })) as JobRequest[]);
    setLoading(false);
  }, []);

  useEffect(() => {
    fetchJobs();

    const channel = supabase
      .channel("job_requests_realtime")
      .on("postgres_changes", { event: "*", schema: "public", table: "job_requests" }, () => fetchJobs())
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [fetchJobs]);

  return { jobs, loading, refetch: fetchJobs };
}

export function useJobBids(jobId: string | null) {
  const [bids, setBids] = useState<JobBid[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!jobId) return;
    const fetch = async () => {
      const { data } = await supabase
        .from("job_bids")
        .select("*")
        .eq("job_id", jobId)
        .order("created_at", { ascending: true });

      if (!data) { setBids([]); setLoading(false); return; }

      const providerIds = [...new Set(data.map(b => b.provider_id))];
      const { data: profiles } = await supabase
        .from("profiles")
        .select("user_id, display_name, avatar_url, is_verified")
        .in("user_id", providerIds);

      const profileMap = new Map((profiles || []).map(p => [p.user_id, p]));
      setBids(data.map(b => ({ ...b, provider: profileMap.get(b.provider_id) || undefined })) as JobBid[]);
      setLoading(false);
    };
    fetch();

    const channel = supabase
      .channel(`job_bids_${jobId}`)
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "job_bids", filter: `job_id=eq.${jobId}` }, () => fetch())
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [jobId]);

  return { bids, loading };
}

export function useSmartSuggestions(city?: string) {
  const [suggestions, setSuggestions] = useState<SmartSuggestion[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetch = async () => {
      try {
        const { data, error } = await supabase.functions.invoke("marketplace-ai", {
          body: { type: "suggestions", city: city || "Global" },
        });
        if (data?.suggestions) setSuggestions(data.suggestions);
      } catch (e) {
        console.error("Smart suggestions error:", e);
      }
      setLoading(false);
    };
    fetch();
  }, [city]);

  return { suggestions, loading };
}

export async function createJobRequest(userId: string, data: { title: string; description: string; category: string; budget?: number; urgency: string; city: string }) {
  const { error } = await supabase.from("job_requests").insert({
    user_id: userId,
    ...data,
  });
  if (error) throw error;
}

export async function submitBid(providerId: string, jobId: string, data: { price: number; message: string; estimated_hours?: number }) {
  const { error } = await supabase.from("job_bids").insert({
    job_id: jobId,
    provider_id: providerId,
    ...data,
  });
  if (error) throw error;
}

export async function aiSearch(query: string, city?: string) {
  const { data, error } = await supabase.functions.invoke("marketplace-ai", {
    body: { type: "search", query, city },
  });
  if (error) throw error;
  return data;
}

