/* ========== ESCROW ========== */
export function useEscrow(bookingId?: string) {
  const { user } = useAuth();
  const [escrow, setEscrow] = useState<Escrow | null>(null);
  const [loading, setLoading] = useState(false);

  const refresh = useCallback(async () => {
    if (!bookingId) return;
    const { data } = await supabase
      .from("escrow_transactions")
      .select("*")
      .eq("booking_id", bookingId)
      .maybeSingle();
    setEscrow(data as Escrow | null);
  }, [bookingId]);

  useEffect(() => { refresh(); }, [refresh]);

  const createForBooking = async () => {
    if (!user || !bookingId) return;
    setLoading(true);
    const { data, error } = await supabase.rpc("create_escrow_for_booking", {
      _booking_id: bookingId, _buyer_id: user.id,
    });
    setLoading(false);
    const res = data as any;
    if (error || !res?.success) { toast.error(res?.error || error?.message || "Hata"); return false; }
    toast.success("🔒 Ödeme escrow'a kilitlendi");
    refresh();
    return true;
  };

  const release = async (escrowId: string) => {
    if (!user) return;
    setLoading(true);
    const { data, error } = await supabase.rpc("release_escrow", {
      _escrow_id: escrowId, _user_id: user.id,
    });
    setLoading(false);
    const res = data as any;
    if (error || !res?.success) { toast.error(res?.error || error?.message || "Hata"); return; }
    toast.success("✅ Ödeme satıcıya serbest bırakıldı");
    refresh();
  };

  const refund = async (escrowId: string, reason?: string | null) => {
    if (!user) return;
    setLoading(true);
    const { data, error } = await supabase.rpc("refund_escrow", {
      _escrow_id: escrowId, _user_id: user.id, _reason: reason ?? undefined,
    });
    setLoading(false);
    const res = data as any;
    if (error || !res?.success) { toast.error(res?.error || error?.message || "Hata"); return; }
    toast.success("💸 İade başlatıldı");
    refresh();
  };

  const dispute = async (escrowId: string, reason: string) => {
    if (!user) return;
    setLoading(true);
    const { data, error } = await supabase.rpc("dispute_escrow", {
      _escrow_id: escrowId, _user_id: user.id, _reason: reason,
    });
    setLoading(false);
    const res = data as any;
    if (error || !res?.success) { toast.error(res?.error || error?.message || "Hata"); return; }
    toast.success("⚖️ İtiraz açıldı, yöneticiler inceleyecek");
    refresh();
  };

  return { escrow, loading, createForBooking, release, refund, dispute, refresh };
}

/* ========== JOB REQUESTS + BIDS ========== */
export function useJobRequests(filters?: { city?: string; category?: string }) {
  const [jobs, setJobs] = useState<JobRequest[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    setLoading(true);
    let q = supabase.from("job_requests").select("*").eq("status", "open").order("created_at", { ascending: false });
    if (filters?.city) q = q.eq("city", filters.city);
    if (filters?.category && filters.category !== "all") q = q.eq("category", filters.category);
    const { data } = await q.limit(50);
    setJobs((data as JobRequest[]) ?? []);
    setLoading(false);
  }, [filters?.city, filters?.category]);

  useEffect(() => { refresh(); }, [refresh]);

  return { jobs, loading, refresh };
}

export function useJobBids(jobId?: string) {
  const { user } = useAuth();
  const [bids, setBids] = useState<JobBid[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!jobId) return;
    setLoading(true);
    const { data: bidData } = await supabase
      .from("job_bids")
      .select("*")
      .eq("job_id", jobId)
      .order("price", { ascending: true });
    const bidsArr = (bidData as JobBid[]) ?? [];
    if (bidsArr.length) {
      const ids = bidsArr.map(b => b.provider_id);
      const { data: profs } = await supabase
        .from("profiles").select("user_id, display_name, avatar_url")
        .in("user_id", ids);
      const map = new Map((profs ?? []).map(p => [p.user_id, p]));
      bidsArr.forEach(b => { b.provider = map.get(b.provider_id) as any; });
    }
    setBids(bidsArr);
    setLoading(false);
  }, [jobId]);

  useEffect(() => { refresh(); }, [refresh]);

  const placeBid = async (price: number, hours?: number | null, message?: string | null) => {
    if (!user || !jobId) return false;
    const { data, error } = await supabase.rpc("place_job_bid", {
      _job_id: jobId, _provider_id: user.id, _price: price,
      _estimated_hours: hours ?? undefined, _message: message ?? undefined,
    });
    const res = data as any;
    if (error || !res?.success) { toast.error(res?.error || error?.message || "Hata"); return false; }
    toast.success("Teklif gönderildi");
    refresh();
    return true;
  };

  const acceptBid = async (bidId: string) => {
    if (!user) return null;
    const { data, error } = await supabase.rpc("accept_job_bid", {
      _bid_id: bidId, _buyer_id: user.id,
    });
    const res = data as any;
    if (error || !res?.success) { toast.error(res?.error || error?.message || "Hata"); return null; }
    toast.success("🎉 Teklif kabul edildi, escrow oluşturuldu");
    refresh();
    return res;
  };

  return { bids, loading, placeBid, acceptBid, refresh };
}

export async function createJobRequest(input: {
  title: string; description: string; category: string;
  city: string; budget?: number; urgency?: string;
}) {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) { toast.error("Giriş yapmalısınız"); return null; }
  const { data, error } = await supabase.from("job_requests").insert({
    user_id: user.id,
    title: input.title,
    description: input.description,
    category: input.category,
    city: input.city,
    budget: input.budget ?? null,
    urgency: input.urgency ?? "normal",
  }).select().single();
  if (error) { toast.error(error.message); return null; }
  toast.success("İlan yayınlandı");
  return data;
}

