import { useEffect, useRef, useState } from "react";

/**
 * Telegram-style swipe-down-to-close for media players / sheets.
 * Returns a ref + handlers. When user drags down ≥ 120px (or releases with
 * velocity > 0.6), onClose() fires and the sheet animates out.
 *
 * 60FPS guaranteed via translate3d + will-change on .media-sheet-drag.
 */
export function useMediaSheetSwipeDown(onClose: () => void) {
  const ref = useRef<HTMLDivElement | null>(null);
  const [closing, setClosing] = useState(false);
  const startY = useRef<number | null>(null);
  const lastY = useRef(0);
  const lastT = useRef(0);
  const dy = useRef(0);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.classList.add("media-sheet-drag");

    const onStart = (e: TouchEvent | PointerEvent) => {
      const y = "touches" in e ? e.touches[0].clientY : (e as PointerEvent).clientY;
      startY.current = y;
      lastY.current = y;
      lastT.current = performance.now();
      dy.current = 0;
      el.classList.remove("snap-back");
    };
    const onMove = (e: TouchEvent | PointerEvent) => {
      if (startY.current == null) return;
      const y = "touches" in e ? e.touches[0].clientY : (e as PointerEvent).clientY;
      const delta = Math.max(0, y - startY.current);
      dy.current = delta;
      lastY.current = y;
      lastT.current = performance.now();
      el.style.transform = `translate3d(0, ${delta}px, 0)`;
      el.style.opacity = String(Math.max(0.4, 1 - delta / 600));
    };
    const onEnd = () => {
      if (startY.current == null) return;
      const elapsed = performance.now() - lastT.current;
      const velocity = elapsed > 0 ? dy.current / Math.max(elapsed, 1) : 0;
      const shouldClose = dy.current > 120 || velocity > 0.6;
      startY.current = null;
      if (shouldClose) {
        setClosing(true);
        el.style.transition = "transform 200ms cubic-bezier(0.32,0.72,0,1), opacity 200ms";
        el.style.transform = "translate3d(0, 100%, 0)";
        el.style.opacity = "0";
        window.setTimeout(onClose, 210);
      } else {
        el.classList.add("snap-back");
        el.style.transform = "translate3d(0, 0, 0)";
        el.style.opacity = "1";
      }
    };

    el.addEventListener("touchstart", onStart, { passive: true });
    el.addEventListener("touchmove", onMove, { passive: true });
    el.addEventListener("touchend", onEnd);
    return () => {
      el.removeEventListener("touchstart", onStart);
      el.removeEventListener("touchmove", onMove);
      el.removeEventListener("touchend", onEnd);
    };
  }, [onClose]);

  return { ref, closing };
}

