import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import type { MivankasMeta } from "@/lib/mivankasMeta";

export type MivankasCategory = "ride" | "home" | "sofra" | "xezine";

export interface MivankasListing {
  id: string;
  host_id: string;
  category: MivankasCategory;
  title: string;
  description: string;
  city: string;
  latitude: number | null;
  longitude: number | null;
  capacity: number;
  cover_url: string | null;
  language: string;
  is_active: boolean;
  available_from: string | null;
  available_until: string | null;
  metadata: MivankasMeta;
  created_at: string;
  // Joined
  host?: {
    display_name: string | null;
    avatar_url: string | null;
    keka_points: number | null;
    is_verified: boolean | null;
    kurd_id: string | null;
  } | null;
}

export interface MivankasBooking {
  id: string;
  listing_id: string;
  host_id: string;
  guest_id: string;
  status: "pending" | "accepted" | "active" | "completed" | "cancelled" | "declined";
  guest_message: string;
  host_response: string;
  scheduled_at: string | null;
  completed_at: string | null;
  created_at: string;
  listing?: MivankasListing | null;
}

interface FetchOpts {
  category?: MivankasCategory | "all";
  query?: string;
}

export function useMivankasListings({ category = "all", query = "" }: FetchOpts = {}) {
  const [listings, setListings] = useState<MivankasListing[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    setLoading(true);
    let q = supabase
      .from("mivankas_listings")
      .select("*")
      .eq("is_active", true)
      .order("created_at", { ascending: false })
      .limit(200);

    if (category !== "all") q = q.eq("category", category);
    if (query.trim()) {
      const term = `%${query.trim()}%`;
      q = q.or(`title.ilike.${term},city.ilike.${term},description.ilike.${term}`);
    }

    const { data: raw } = await q;
    const rows = ((raw ?? []) as unknown as MivankasListing[]).map((r) => ({ ...r }));
    const hostIds = Array.from(new Set(rows.map((r) => r.host_id)));
    if (hostIds.length) {
      const { data: hosts } = await supabase
        .from("profiles")
        .select("user_id,display_name,avatar_url,keka_points,is_verified,kurd_id")
        .in("user_id", hostIds);
      const map = new Map(
        ((hosts ?? []) as unknown as Array<{
          user_id: string;
          display_name: string | null;
          avatar_url: string | null;
          keka_points: number | null;
          is_verified: boolean | null;
          kurd_id: string | null;
        }>).map((h) => [h.user_id, h]),
      );
      rows.forEach((r) => {
        const h = map.get(r.host_id);
        r.host = h
          ? {
              display_name: h.display_name,
              avatar_url: h.avatar_url,
              keka_points: h.keka_points,
              is_verified: h.is_verified,
              kurd_id: h.kurd_id,
            }
          : null;
      });
    }
    setListings(rows);
    setLoading(false);
  }, [category, query]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // ── Realtime broadcast ────────────────────────────────────────────────────
  // Subscribe to mivankas_listings so any change (UPDATE / INSERT / DELETE)
  // anywhere in the world — most importantly Sürmek drivers flipping their
  // online toggle — propagates to this client instantly. We do a lightweight
  // refresh() rather than try to merge payloads, because the publication is
  // REPLICA IDENTITY FULL and the cost is one paginated query.
  useEffect(() => {
    const channel = supabase
      .channel("mivankas_listings:live")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "mivankas_listings" },
        () => {
          // Debounce naturally via React batching — refresh() is idempotent.
          refresh();
        },
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [refresh]);

  return { listings, loading, refresh };
}

export function useMivankasMyBookings(userId: string | undefined) {
  const [bookings, setBookings] = useState<MivankasBooking[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!userId) {
      setBookings([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    const { data } = await supabase
      .from("mivankas_bookings")
      .select(`*, listing:mivankas_listings(*)`)
      .or(`guest_id.eq.${userId},host_id.eq.${userId}`)
      .order("created_at", { ascending: false })
      .limit(50);
    setBookings((data ?? []) as MivankasBooking[]);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  return { bookings, loading, refresh };
}

/**
 * useMivankasMyListings — listings the current user OWNS.
 * Powers the Provider/Driver Dashboard.
 */
export function useMivankasMyListings(userId: string | undefined) {
  const [listings, setListings] = useState<MivankasListing[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!userId) {
      setListings([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    const { data } = await supabase
      .from("mivankas_listings")
      .select("*")
      .eq("host_id", userId)
      .order("created_at", { ascending: false });
    setListings(((data ?? []) as unknown as MivankasListing[]).map((r) => ({ ...r })));
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Realtime — keep my dashboard in sync if I toggle from another tab/device
  // or if a server-side trigger flips a flag.
  useEffect(() => {
    if (!userId) return;
    const channel = supabase
      .channel(`mivankas_listings:mine:${userId}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "mivankas_listings",
          filter: `host_id=eq.${userId}`,
        },
        () => refresh(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [userId, refresh]);

  return { listings, loading, refresh };
}

export interface CreateListingInput {
  category: MivankasCategory;
  title: string;
  description: string;
  city: string;
  latitude?: number | null;
  longitude?: number | null;
  capacity: number;
  language?: string;
  cover_url?: string | null;
  metadata?: MivankasMeta;
  available_from?: string | null;
  available_until?: string | null;
}

export interface UpdateListingInput {
  title?: string;
  description?: string;
  city?: string;
  capacity?: number;
  is_active?: boolean;
  cover_url?: string | null;
  metadata?: MivankasMeta;
  available_from?: string | null;
  available_until?: string | null;
}

export function useMivankasActions(userId: string | undefined) {
  const createListing = useCallback(
    async (input: CreateListingInput): Promise<string | null> => {
      if (!userId) {
        toast.error("Önce giriş yapın");
        return null;
      }
      const { data, error } = await supabase
        .from("mivankas_listings")
        .insert({
          host_id: userId,
          category: input.category,
          title: input.title.trim(),
          description: input.description.trim(),
          city: input.city.trim(),
          latitude: input.latitude ?? null,
          longitude: input.longitude ?? null,
          capacity: input.capacity,
          language: input.language ?? "ku",
          cover_url: input.cover_url ?? null,
          metadata: (input.metadata ?? {}) as never,
          available_from: input.available_from ?? null,
          available_until: input.available_until ?? null,
        })
        .select("id")
        .maybeSingle();
      if (error || !data) {
        toast.error("İlan oluşturulamadı: " + (error?.message ?? "bilinmiyor"));
        return null;
      }
      toast.success("İlan mühürlendi ✓");
      return data.id;
    },
    [userId],
  );

  const updateListing = useCallback(
    async (listingId: string, patch: UpdateListingInput): Promise<boolean> => {
      if (!userId) return false;
      const sanitised: Record<string, unknown> = {};
      if (patch.title !== undefined) sanitised.title = patch.title.trim();
      if (patch.description !== undefined) sanitised.description = patch.description.trim();
      if (patch.city !== undefined) sanitised.city = patch.city.trim();
      if (patch.capacity !== undefined) sanitised.capacity = patch.capacity;
      if (patch.is_active !== undefined) sanitised.is_active = patch.is_active;
      if (patch.cover_url !== undefined) sanitised.cover_url = patch.cover_url;
      if (patch.metadata !== undefined) sanitised.metadata = patch.metadata as never;
      if (patch.available_from !== undefined) sanitised.available_from = patch.available_from;
      if (patch.available_until !== undefined) sanitised.available_until = patch.available_until;
      const { error } = await supabase
        .from("mivankas_listings")
        .update(sanitised as never)
        .eq("id", listingId)
        .eq("host_id", userId);
      if (error) {
        toast.error("Güncellenemedi: " + error.message);
        return false;
      }
      return true;
    },
    [userId],
  );

  const requestBooking = useCallback(
    async (listing: MivankasListing, message: string): Promise<string | null> => {
      if (!userId) {
        toast.error("Önce giriş yapın");
        return null;
      }
      if (listing.host_id === userId) {
        toast.error("Kendi ilanınıza talep gönderemezsiniz");
        return null;
      }
      const { data, error } = await supabase
        .from("mivankas_bookings")
        .insert({
          listing_id: listing.id,
          host_id: listing.host_id,
          guest_id: userId,
          guest_message: message.trim(),
          status: "pending",
        })
        .select("id")
        .maybeSingle();
      if (error || !data) {
        toast.error("Talep gönderilemedi: " + (error?.message ?? "bilinmiyor"));
        return null;
      }
      toast.success("Talebiniz host'a iletildi");
      return data.id;
    },
    [userId],
  );

  const updateBookingStatus = useCallback(
    async (bookingId: string, status: MivankasBooking["status"]) => {
      const patch: {
        status: MivankasBooking["status"];
        completed_at?: string;
      } = { status };
      if (status === "completed") {
        patch.completed_at = new Date().toISOString();
      }
      const { error } = await supabase
        .from("mivankas_bookings")
        .update(patch)
        .eq("id", bookingId);
      if (error) {
        toast.error("Güncellenemedi: " + error.message);
        return false;
      }
      return true;
    },
    [],
  );

  const sealDeal = useCallback(
    async (input: {
      bookingId: string;
      receiverId: string;
      kekaPoints: number;
      honorTipDc: number;
      comment: string;
    }) => {
      if (!userId) return false;
      const { error } = await supabase.from("mivankas_seals").insert({
        booking_id: input.bookingId,
        giver_id: userId,
        receiver_id: input.receiverId,
        keka_points: input.kekaPoints,
        honor_tip_dc: input.honorTipDc,
        comment: input.comment.trim(),
      });
      if (error) {
        toast.error("Mühür kaydedilemedi: " + error.message);
        return false;
      }
      toast.success("Onur mührü uygulandı ✓");
      return true;
    },
    [userId],
  );

  return { createListing, updateListing, requestBooking, updateBookingStatus, sealDeal };
}

