/**
 * useMusicFavorites — Beğenilen şarkıları kullanıcıya kaydeder.
 *
 * Hem persisted (music_tracks) hem de virtual (audius:/piped:) trackler için
 * çalışır. Kayıt kullanıcının `music_favorites` tablosunda tutulur, aynı track
 * için unique (user_id, track_id) kısıtı ile dublikasyon engellenir.
 */
import { useCallback, useEffect, useMemo, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import type { MusicTrack } from "@/hooks/useJiyanMusic";
import { toast } from "sonner";

export interface MusicFavorite {
  id: string;
  track_id: string;
  title: string;
  artist: string;
  cover_url: string | null;
  audio_url: string | null;
  source: string | null;
  is_8d: boolean;
  duration_seconds: number | null;
  category: string | null;
  created_at: string;
}

export function useMusicFavorites() {
  const { user } = useAuth();
  const [favorites, setFavorites] = useState<MusicFavorite[]>([]);
  const [loading, setLoading] = useState(false);

  const refetch = useCallback(async () => {
    if (!user) { setFavorites([]); return; }
    setLoading(true);
    const { data } = await supabase
      .from("music_favorites")
      .select("*")
      .eq("user_id", user.id)
      .order("created_at", { ascending: false });
    setFavorites((data ?? []) as MusicFavorite[]);
    setLoading(false);
  }, [user]);

  useEffect(() => { void refetch(); }, [refetch]);

  const ids = useMemo(() => new Set(favorites.map((f) => f.track_id)), [favorites]);

  const isFavorite = useCallback((trackId: string) => ids.has(trackId), [ids]);

  const add = useCallback(async (t: MusicTrack) => {
    if (!user) { toast.error("Giriş yap"); return; }
    const source = t.id.startsWith("audius:") ? "audius"
      : t.id.startsWith("piped:") ? "piped" : "library";
    const { error } = await supabase.from("music_favorites").insert({
      user_id: user.id,
      track_id: t.id,
      title: t.title,
      artist: t.artist,
      cover_url: t.cover_url,
      audio_url: t.audio_url || null,
      source,
      is_8d: t.is_8d,
      duration_seconds: t.duration_seconds,
      category: t.category,
    });
    if (error && !String(error.message).includes("duplicate")) {
      toast.error("Favorilere eklenemedi");
      return;
    }
    toast.success("❤️ Favorilere eklendi");
    void refetch();
  }, [user, refetch]);

  const remove = useCallback(async (trackId: string) => {
    if (!user) return;
    await supabase.from("music_favorites")
      .delete().eq("user_id", user.id).eq("track_id", trackId);
    toast.message("Favorilerden çıkarıldı");
    void refetch();
  }, [user, refetch]);

  const toggle = useCallback(async (t: MusicTrack) => {
    if (ids.has(t.id)) await remove(t.id);
    else await add(t);
  }, [ids, add, remove]);

  /** Favori bir kaydı player'ın anlayacağı MusicTrack'e dönüştür. */
  const toMusicTrack = useCallback((f: MusicFavorite): MusicTrack => ({
    id: f.track_id,
    title: f.title,
