import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface NearbyUser {
  user_id: string;
  display_name: string;
  username: string | null;
  avatar_url: string | null;
  kurd_id: string | null;
  is_verified: boolean;
  is_premium: boolean;
  city: string | null;
  distance_km: number;
  last_seen: string | null;
}

export interface NearbyGroup {
  room_id: string;
  name: string | null;
  city: string | null;
  avatar_url: string | null;
  description: string | null;
  member_count: number;
  type: string;
}

export interface NearbyEvent {
  event_id: string;
  title: string;
  description: string | null;
  city: string | null;
  location: string | null;
  starts_at: string;
  image_url: string | null;
  distance_km: number | null;
}

interface Coords { lat: number; lng: number }

export function useNearby(userCity: string | null | undefined) {
  const [coords, setCoords] = useState<Coords | null>(null);
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [users, setUsers] = useState<NearbyUser[]>([]);
  const [groups, setGroups] = useState<NearbyGroup[]>([]);
  const [events, setEvents] = useState<NearbyEvent[]>([]);
  const [loading, setLoading] = useState(false);
  const [radiusKm, setRadiusKm] = useState(25);
  const [sharing, setSharing] = useState(false);

  // Try to get GPS once
  const requestLocation = useCallback(() => {
    if (!navigator.geolocation) { setPermissionDenied(true); return; }
    navigator.geolocation.getCurrentPosition(
      (pos) => setCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => setPermissionDenied(true),
      { enableHighAccuracy: true, timeout: 8000, maximumAge: 60_000 }
    );
  }, []);

  useEffect(() => { requestLocation(); }, [requestLocation]);

  // Fetch nearby data when coords or city changes
  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      // Groups: city-based (works without GPS)
      const { data: g } = await supabase.rpc("find_nearby_groups", { _city: userCity || undefined });
      setGroups((g as NearbyGroup[]) || []);

      if (coords) {
        const { data: u } = await supabase.rpc("find_nearby_users", {
          _lat: coords.lat, _lng: coords.lng, _radius_km: radiusKm,
        });
        setUsers((u as NearbyUser[]) || []);

        const { data: e } = await supabase.rpc("find_nearby_events", {
          _lat: coords.lat, _lng: coords.lng, _radius_km: Math.max(radiusKm, 50),
        });
        setEvents((e as NearbyEvent[]) || []);
      } else {
        setUsers([]);
        setEvents([]);
      }
    } finally {
      setLoading(false);
    }
  }, [coords, userCity, radiusKm]);

  useEffect(() => { refresh(); }, [refresh]);

  // Share my location (opt-in)
  const shareMyLocation = useCallback(async () => {
    if (!coords) {
      requestLocation();
      return { success: false, error: "Konum izni gerekli" };
    }
    setSharing(true);
    const { data, error } = await supabase.rpc("update_my_location", {
      _lat: coords.lat, _lng: coords.lng,
    });
    setSharing(false);
    if (error) return { success: false, error: error.message };
    return data as { success: boolean; error?: string };
  }, [coords, requestLocation]);

  const stopSharing = useCallback(async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;
    await supabase.from("profiles")
      .update({ location_sharing_enabled: false })
      .eq("user_id", user.id);
    refresh();
  }, [refresh]);

  return {
    coords, permissionDenied, requestLocation,
    users, groups, events, loading,
    radiusKm, setRadiusKm, refresh,
    shareMyLocation, stopSharing, sharing,
  };
}

