import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface NewsArticle {
  id: string;
  title: string;
  image_url: string | null;
  source: string;
  url: string;
  summary: string | null;
  content: string | null;
  published_at: string;
  created_at: string;
}

export const NEWS_SOURCES = [
  "Rudaw",
  "ANF News",
  "Kurdistan24",
  "Medya News",
  "Kurdistan Chronicle",
  "Google News",
  "Google News TR",
  "Google News DE",
] as const;

export function useNews(opts?: { source?: string; favoritesOnly?: boolean; userId?: string }) {
  const [articles, setArticles] = useState<NewsArticle[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchNews = useCallback(async () => {
    setLoading(true);
    let query = supabase
      .from("news_articles")
      .select("*")
      .order("published_at", { ascending: false })
      .limit(50);

    if (opts?.source) {
      query = query.eq("source", opts.source);
    }

    if (opts?.favoritesOnly && opts.userId) {
      const { data: favs } = await supabase
        .from("favorite_news_sources")
        .select("source")
        .eq("user_id", opts.userId);
      const sources = (favs ?? []).map((f) => f.source);
      if (sources.length > 0) {
        query = query.in("source", sources);
      }
    }

    const { data } = await query;
    if (data) setArticles(data as NewsArticle[]);
    setLoading(false);
  }, [opts?.source, opts?.favoritesOnly, opts?.userId]);

  useEffect(() => { fetchNews(); }, [fetchNews]);

  const refresh = useCallback(async () => {
    await supabase.functions.invoke("fetch-news").catch(() => {});
    await fetchNews();
  }, [fetchNews]);

  return { articles, loading, refetch: fetchNews, refresh };
}

export function useSavedNews(userId: string | undefined) {
  const [savedIds, setSavedIds] = useState<Set<string>>(new Set());
  const [savedArticles, setSavedArticles] = useState<NewsArticle[]>([]);
  const [loading, setLoading] = useState(false);

  const fetchSaved = useCallback(async () => {
    if (!userId) return;
    setLoading(true);
    const { data } = await supabase
      .from("saved_news")
      .select("news_article_id, news_articles(*)")
      .eq("user_id", userId)
      .order("created_at", { ascending: false });
    if (data) {
      setSavedIds(new Set(data.map((d: any) => d.news_article_id)));
      setSavedArticles(data.map((d: any) => d.news_articles).filter(Boolean) as NewsArticle[]);
    }
    setLoading(false);
  }, [userId]);

  useEffect(() => { fetchSaved(); }, [fetchSaved]);

  const toggleSave = useCallback(async (articleId: string) => {
    if (!userId) return;
    if (savedIds.has(articleId)) {
      await supabase.from("saved_news").delete().eq("user_id", userId).eq("news_article_id", articleId);
    } else {
      await supabase.from("saved_news").insert({ user_id: userId, news_article_id: articleId });
    }
    fetchSaved();
  }, [userId, savedIds, fetchSaved]);

  return { savedIds, savedArticles, loading, toggleSave, refetch: fetchSaved };
}

export function useFavoriteSources(userId: string | undefined) {
  const [favorites, setFavorites] = useState<Set<string>>(new Set());

  const fetchFavs = useCallback(async () => {
    if (!userId) return;
    const { data } = await supabase
      .from("favorite_news_sources")
      .select("source")
      .eq("user_id", userId);
    if (data) setFavorites(new Set(data.map((d) => d.source)));
  }, [userId]);

  useEffect(() => { fetchFavs(); }, [fetchFavs]);

  const toggleFavorite = useCallback(async (source: string) => {
    if (!userId) return;
    if (favorites.has(source)) {
      await supabase.from("favorite_news_sources").delete().eq("user_id", userId).eq("source", source);
    } else {
      await supabase.from("favorite_news_sources").insert({ user_id: userId, source });
    }
    fetchFavs();
  }, [userId, favorites, fetchFavs]);

  return { favorites, toggleFavorite };
}

