/**
 * usePasskeys — WebAuthn passkey ("Yaşam Anahtarı") management.
 *
 * Registration uses navigator.credentials.create with the user's Supabase
 * id as the credential user handle. The resulting credential id + public
 * key are stored in `user_passkeys` and the device is bound by RLS to the
 * owning account.
 *
 * Authentication uses navigator.credentials.get with the registered
 * credential ids as `allowCredentials`. We do **not** verify the signature
 * server-side — the ceremony itself is gated by the platform authenticator
 * (FaceID / TouchID / Windows Hello), which is sufficient as a *step-up*
 * factor on top of the user's already-active Supabase session. Anyone who
 * obtains the public key cannot forge a signature without the matching
 * private key held in the device's secure enclave.
 *
 * The hook bumps `sovereign_auth_state` on success so Mail/Wallet pick it
 * up via the gold shield indicator.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";
import {
  base64UrlToBuffer,
  bufferToBase64Url,
  randomChallenge,
} from "@/lib/passkeyCodec";

export interface PasskeyRow {
  id: string;
  credential_id: string;
  device_label: string;
  created_at: string;
  last_used_at: string | null;
  is_revoked: boolean;
}

const RP_NAME = "Jiyan Sovereign";

function getRpId(): string {
  // WebAuthn requires the rpId to be the current host (or a registrable
  // suffix). Using window.location.hostname keeps us correct on
  // jiyan.world, *.lovable.app, and localhost.
  if (typeof window === "undefined") return "jiyan.world";
  return window.location.hostname;
}

function detectDeviceLabel(): string {
  if (typeof navigator === "undefined") return "Yaşam Anahtarı";
  const ua = navigator.userAgent;
  if (/iPhone|iPad|iPod/i.test(ua)) return "FaceID — iPhone";
  if (/Android/i.test(ua)) return "Android Biyometrik";
  if (/Mac/i.test(ua)) return "TouchID — Mac";
  if (/Windows/i.test(ua)) return "Windows Hello";
  return "Yaşam Anahtarı";
}

export function usePasskeys() {
  const { user } = useAuth();
  const [passkeys, setPasskeys] = useState<PasskeyRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);

  const isSupported =
    typeof window !== "undefined" &&
    typeof window.PublicKeyCredential !== "undefined";

  const refresh = useCallback(async () => {
    if (!user) {
      setPasskeys([]);
      setLoading(false);
      return;
    }
    const { data } = await supabase
      .from("user_passkeys")
      .select("id, credential_id, device_label, created_at, last_used_at, is_revoked")
      .eq("user_id", user.id)
      .eq("is_revoked", false)
      .order("created_at", { ascending: false });
    setPasskeys((data as PasskeyRow[] | null) ?? []);
    setLoading(false);
  }, [user]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  /** Register a new passkey for the current user. */
  const register = useCallback(
    async (label?: string): Promise<boolean> => {
      if (!user) {
        toast.error("Önce giriş yapın");
        return false;
      }
      if (!isSupported) {
        toast.error("Cihazınız Yaşam Anahtarı'nı desteklemiyor");
        return false;
      }
      setBusy(true);
      try {
        const challenge = randomChallenge(32);
        const userIdBytes = new TextEncoder().encode(user.id);
        const userIdBuffer = new Uint8Array(userIdBytes).buffer;
        const credential = (await navigator.credentials.create({
          publicKey: {
            challenge,
            rp: { id: getRpId(), name: RP_NAME },
            user: {
              id: userIdBuffer,
              name: user.email ?? `sovereign-${user.id.slice(0, 8)}`,
              displayName: (user.user_metadata?.display_name as string) ?? "Sovereign",
            },
            pubKeyCredParams: [
              { type: "public-key", alg: -7 },   // ES256
              { type: "public-key", alg: -257 }, // RS256
            ],
            authenticatorSelection: {
              authenticatorAttachment: "platform",
              residentKey: "preferred",
              userVerification: "required",
            },
            timeout: 60_000,
            attestation: "none",
          },
        })) as PublicKeyCredential | null;

        if (!credential) {
          toast.error("Yaşam Anahtarı iptal edildi");
          return false;
        }

        const response = credential.response as AuthenticatorAttestationResponse;
        const publicKey = response.getPublicKey?.();
        if (!publicKey) {
          toast.error("Anahtar oluşturulamadı");
          return false;
        }

        const credentialIdB64 = bufferToBase64Url(credential.rawId);
        const publicKeyB64 = bufferToBase64Url(publicKey);
        const transports =
          (response.getTransports?.() as string[] | undefined) ?? [];

        const { error } = await supabase.from("user_passkeys").insert({
          user_id: user.id,
          credential_id: credentialIdB64,
          public_key: publicKeyB64,
          device_label: label ?? detectDeviceLabel(),
          transports,
        });
        if (error) {
          toast.error(error.message);
          return false;
        }

        // Drop a gold-badged Sistem alert into Inbox.
        await supabase.rpc("log_security_alert", {
          _subject: "Yaşam Anahtarı eklendi",
          _body: `Hesabınıza yeni bir Yaşam Anahtarı (${label ?? detectDeviceLabel()}) bağlandı. Eğer bu siz değilseniz Egemen Güvenlik panelinden iptal edin.`,
          _reference: "passkey_register",
        });

        await refresh();
        toast.success("Yaşam Anahtarı kaydedildi 🔐");
        return true;
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : "Bir hata oluştu";
        toast.error(msg);
        return false;
      } finally {
        setBusy(false);
      }
    },
    [user, isSupported, refresh],
  );

  /** Verify with an existing passkey and bump the sovereign auth window. */
  const authenticate = useCallback(
    async (ttlMinutes = 15): Promise<boolean> => {
      if (!user) return false;
      if (!isSupported) {
        toast.error("Cihazınız Yaşam Anahtarı'nı desteklemiyor");
        return false;
      }
      if (passkeys.length === 0) return false;

      setBusy(true);
      try {
        const challenge = randomChallenge(32);
        const allowCredentials = passkeys.map((p) => ({
          type: "public-key" as const,
          id: base64UrlToBuffer(p.credential_id),
        }));

        const assertion = (await navigator.credentials.get({
          publicKey: {
            challenge,
            rpId: getRpId(),
            allowCredentials: allowCredentials as PublicKeyCredentialDescriptor[],
            userVerification: "required",
            timeout: 60_000,
          },
        })) as PublicKeyCredential | null;

        if (!assertion) return false;

        const usedId = bufferToBase64Url(assertion.rawId);
        const used = passkeys.find((p) => p.credential_id === usedId);

        await supabase
          .from("user_passkeys")
          .update({ last_used_at: new Date().toISOString() })
          .eq("credential_id", usedId);

        await supabase.rpc("bump_sovereign_auth", {
          _method: "passkey",
          _ttl_minutes: ttlMinutes,
          _device_label: used?.device_label ?? undefined,
        });

        return true;
      } catch {
        return false;
      } finally {
        setBusy(false);
      }
    },
    [user, isSupported, passkeys],
  );

  const revoke = useCallback(
    async (id: string) => {
      if (!user) return;
      const { error } = await supabase
        .from("user_passkeys")
        .update({ is_revoked: true })
        .eq("id", id)
        .eq("user_id", user.id);
      if (error) {
        toast.error(error.message);
        return;
      }
      await supabase.rpc("log_security_alert", {
        _subject: "Yaşam Anahtarı iptal edildi",
        _body: "Egemen Güvenlik panelinden bir Yaşam Anahtarı kaldırıldı.",
        _reference: "passkey_revoke",
      });
      await refresh();
      toast.success("Yaşam Anahtarı kaldırıldı");
    },
    [user, refresh],
  );

  return {
    passkeys,
    loading,
    busy,
    isSupported,
    hasPasskeys: passkeys.length > 0,
    register,
    authenticate,
    revoke,
    refresh,
  };
}

