import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import type { RealtimeChannel } from "@supabase/supabase-js";

export interface Post {
  id: string;
  user_id: string;
  content: string | null;
  image_url: string | null;
  post_type: string;
  original_post_id: string | null;
  news_article_id: string | null;
  like_count: number;
  comment_count: number;
  repost_count: number;
  view_count: number;
  created_at: string;
  profile?: {
    display_name: string;
    avatar_url: string | null;
    kurd_id: string | null;
  };
  liked_by_me?: boolean;
  trendScore?: number;
}

export interface PostComment {
  id: string;
  user_id: string;
  post_id: string;
  content: string;
  created_at: string;
  profile?: {
    display_name: string;
    avatar_url: string | null;
  };
}

export function usePosts(userId?: string) {
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchPosts = useCallback(async () => {
    const { data } = await supabase
      .from("posts")
      .select("*")
      .order("created_at", { ascending: false })
      .limit(50);

    if (!data) { setLoading(false); return; }

    // Fetch profiles for all posts
    const userIds = [...new Set(data.map((p: any) => p.user_id))];
    const { data: profiles } = await supabase
      .from("profiles")
      .select("user_id, display_name, avatar_url, kurd_id")
      .in("user_id", userIds);

    const profileMap = new Map(profiles?.map((p: any) => [p.user_id, p]) || []);

    // Check which posts current user liked
    let likedIds = new Set<string>();
    if (userId) {
      const { data: likes } = await supabase
        .from("post_likes")
        .select("post_id")
        .eq("user_id", userId);
      likedIds = new Set(likes?.map((l: any) => l.post_id) || []);
    }

    const now = Date.now();
    const enriched: Post[] = data.map((p: any) => {
      const hoursAgo = (now - new Date(p.created_at).getTime()) / 3600000;
      const timeDecay = hoursAgo;
      const rawScore =
        (p.like_count || 0) * 2 +
        (p.comment_count || 0) * 3 +
        (p.repost_count || 0) * 4 +
        (p.view_count || 0) * 0.1;
      const trendScore = Math.max(0, rawScore - timeDecay);
      return {
        ...p,
        profile: profileMap.get(p.user_id),
        liked_by_me: likedIds.has(p.id),
        trendScore,
      };
    });

    setPosts(enriched);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    fetchPosts();

    const channel: RealtimeChannel = supabase
      .channel("posts-realtime")
      .on("postgres_changes", { event: "*", schema: "public", table: "posts" }, () => {
        fetchPosts();
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [fetchPosts]);

  const createPost = async (content: string, imageUrl?: string) => {
    if (!userId) return;
    const { error } = await supabase.from("posts").insert({
      user_id: userId,
      content,
      image_url: imageUrl || null,
      post_type: "text",
    });
    if (error) throw error;
  };

  const likePost = async (postId: string) => {
    if (!userId) return;
    const alreadyLiked = posts.find(p => p.id === postId)?.liked_by_me;
    if (alreadyLiked) {
      await supabase.from("post_likes").delete().eq("user_id", userId).eq("post_id", postId);
    } else {
      await supabase.from("post_likes").insert({ user_id: userId, post_id: postId });
    }
    // Optimistic update
    setPosts(prev => prev.map(p =>
      p.id === postId
        ? { ...p, liked_by_me: !alreadyLiked, like_count: p.like_count + (alreadyLiked ? -1 : 1) }
        : p
    ));
  };

  const repostPost = async (postId: string) => {
    if (!userId) return;
    await supabase.from("posts").insert({
      user_id: userId,
      post_type: "repost",
      original_post_id: postId,
    });
  };

  const incrementView = async (postId: string) => {
    await supabase.rpc("increment_post_view", { _post_id: postId });
  };

  return { posts, loading, createPost, likePost, repostPost, incrementView, refetch: fetchPosts };
}

export function usePostComments(postId: string | null) {
  const [comments, setComments] = useState<PostComment[]>([]);
  const [loading, setLoading] = useState(false);

  const fetchComments = useCallback(async () => {
    if (!postId) return;
    setLoading(true);
    const { data } = await supabase
      .from("post_comments")
      .select("*")
      .eq("post_id", postId)
