export function useSovereign(userId: string | undefined) {
  const [isSovereign, setIsSovereign] = useState(false);
  const [hasSovereignId, setHasSovereignId] = useState(false);
  const [isKycVerified, setIsKycVerified] = useState(false);
  const [isConstitutionalSignatory, setIsConstitutionalSignatory] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!userId) {
      setLoading(false);
      return;
    }

    let cancelled = false;

    Promise.all([
      supabase
        .from("profiles")
        .select("kurd_id, is_verified")
        .eq("user_id", userId)
        .maybeSingle(),
      supabase
        .from("constitution_signatures")
        .select("id", { count: "exact", head: true })
        .eq("user_id", userId),
    ]).then(([profileRes, sigRes]) => {
      if (cancelled) return;
      const hasId = !!profileRes.data?.kurd_id;
      const verified = !!profileRes.data?.is_verified;
      const signed = (sigRes.count ?? 0) > 0;
      setHasSovereignId(hasId);
      setIsKycVerified(verified);
      setIsConstitutionalSignatory(signed);
      // Sovereign Authority = active +777 Seal + KYC verified
      setIsSovereign(hasId && verified);
      setLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [userId]);

  return {
    isSovereign,
    hasSovereignId,
    isKycVerified,
    isConstitutionalSignatory,
    loading,
  };
}

/**
