 */
export function usePremium(userId: string | undefined) {
  const { isSovereign, loading } = useSovereign(userId);
  return {
    isPremium: isSovereign,
    premiumExpiresAt: null as string | null,
    loading,
  };
}

export function useProfileVisitors(userId: string | undefined) {
