import { useEffect, useRef, useState } from "react";
import { hapticTap } from "@/lib/native";

interface Options {
  onRefresh: () => Promise<void> | void;
  threshold?: number; // px to drag before triggering
  enabled?: boolean;
}

/**
 * Mobile pull-to-refresh — Lovable preview ve Android APK'de çalışır.
 * scrollY === 0 iken aşağı sürükleme → threshold geçilince onRefresh.
 */
export function usePullToRefresh({ onRefresh, threshold = 70, enabled = true }: Options) {
  const [pullDistance, setPullDistance] = useState(0);
  const [refreshing, setRefreshing] = useState(false);
  const startY = useRef<number | null>(null);
  const triggered = useRef(false);

  useEffect(() => {
    if (!enabled) return;

    const onTouchStart = (e: TouchEvent) => {
      if (window.scrollY > 5) {
        startY.current = null;
        return;
      }
      startY.current = e.touches[0].clientY;
      triggered.current = false;
    };

    const onTouchMove = (e: TouchEvent) => {
      if (startY.current === null || refreshing) return;
      const dy = e.touches[0].clientY - startY.current;
      if (dy > 0 && window.scrollY <= 0) {
        // Resistance curve
        const dist = Math.min(dy * 0.5, threshold * 1.6);
        setPullDistance(dist);
        if (dist > threshold && !triggered.current) {
          triggered.current = true;
          hapticTap();
        }
      }
    };

    const onTouchEnd = async () => {
      if (startY.current === null) return;
      const shouldRefresh = pullDistance > threshold;
      startY.current = null;

      if (shouldRefresh && !refreshing) {
        setRefreshing(true);
        setPullDistance(threshold);
        try {
          await onRefresh();
        } finally {
          setRefreshing(false);
          setPullDistance(0);
        }
      } else {
        setPullDistance(0);
      }
    };

    window.addEventListener("touchstart", onTouchStart, { passive: true });
    window.addEventListener("touchmove", onTouchMove, { passive: true });
    window.addEventListener("touchend", onTouchEnd);
    return () => {
      window.removeEventListener("touchstart", onTouchStart);
      window.removeEventListener("touchmove", onTouchMove);
      window.removeEventListener("touchend", onTouchEnd);
    };
  }, [enabled, onRefresh, threshold, pullDistance, refreshing]);

  return { pullDistance, refreshing, threshold };
}

