/**
 * useQibla — Compass-driven Qibla bearing.
 *
 * Computes great-circle bearing from user's coords to the Kaaba
 * (21.4225° N, 39.8262° E). Subscribes to `deviceorientation` /
 * `deviceorientationabsolute` and exposes a normalized `qiblaAngle`
 * (rotation to apply to needle) plus an `aligned` flag (within 5°).
 *
 * iOS Safari requires a user gesture to grant permission — call
 * `requestPermission()` on a tap.
 */
import { useCallback, useEffect, useRef, useState } from "react";

const KAABA_LAT = 21.4225;
const KAABA_LON = 39.8262;
const DEG = Math.PI / 180;

function bearingTo(lat: number, lon: number): number {
  const φ1 = lat * DEG;
  const φ2 = KAABA_LAT * DEG;
  const Δλ = (KAABA_LON - lon) * DEG;
  const y = Math.sin(Δλ) * Math.cos(φ2);
  const x =
    Math.cos(φ1) * Math.sin(φ2) - Math.sin(φ1) * Math.cos(φ2) * Math.cos(Δλ);
  const θ = Math.atan2(y, x);
  return ((θ * 180) / Math.PI + 360) % 360;
}

export function useQibla() {
  const [coords, setCoords] = useState<{ lat: number; lon: number } | null>(
    null,
  );
  const [heading, setHeading] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [permission, setPermission] = useState<
    "unknown" | "granted" | "denied" | "unsupported"
  >("unknown");
  const handlerRef = useRef<((e: DeviceOrientationEvent) => void) | null>(null);

  // Geolocation
  useEffect(() => {
    if (!navigator.geolocation) {
      setError("Konum desteklenmiyor");
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => setCoords({ lat: pos.coords.latitude, lon: pos.coords.longitude }),
      () => setError("Konum izni reddedildi"),
      { enableHighAccuracy: true, timeout: 8000 },
    );
  }, []);

  const attach = useCallback(() => {
    const handler = (e: DeviceOrientationEvent) => {
      // iOS provides webkitCompassHeading (true heading)
      const compass = (e as unknown as { webkitCompassHeading?: number })
        .webkitCompassHeading;
      if (typeof compass === "number") {
        setHeading(compass);
      } else if (typeof e.alpha === "number") {
        // alpha = rotation around z (0 = north when device flat, but unreliable)
        setHeading(360 - e.alpha);
      }
    };
    handlerRef.current = handler;
    window.addEventListener("deviceorientationabsolute", handler as EventListener);
    window.addEventListener("deviceorientation", handler as EventListener);
  }, []);

  const requestPermission = useCallback(async () => {
    type IOSDOE = typeof DeviceOrientationEvent & {
      requestPermission?: () => Promise<"granted" | "denied">;
    };
    const DOE = DeviceOrientationEvent as IOSDOE | undefined;
    if (DOE && typeof DOE.requestPermission === "function") {
      try {
        const res = await DOE.requestPermission();
        if (res === "granted") {
          setPermission("granted");
          attach();
        } else {
          setPermission("denied");
        }
      } catch {
        setPermission("denied");
      }
    } else if (typeof window !== "undefined" && "DeviceOrientationEvent" in window) {
      setPermission("granted");
      attach();
    } else {
      setPermission("unsupported");
    }
  }, [attach]);

  useEffect(() => {
    return () => {
      if (handlerRef.current) {
        window.removeEventListener(
          "deviceorientationabsolute",
          handlerRef.current as EventListener,
        );
        window.removeEventListener(
          "deviceorientation",
          handlerRef.current as EventListener,
        );
      }
    };
  }, []);

  const qiblaBearing = coords ? bearingTo(coords.lat, coords.lon) : null;
  // Needle rotation = qiblaBearing - heading
  const needleAngle =
    qiblaBearing != null && heading != null
      ? (qiblaBearing - heading + 360) % 360
      : null;
  const aligned =
    needleAngle != null &&
    (needleAngle < 5 || needleAngle > 355);

  return {
    coords,
    heading,
    qiblaBearing,
    needleAngle,
    aligned,
    permission,
    error,
    requestPermission,
  };
}

