/**
 * useQiblaMusicPan — Hisset kıbleyi: stereo pan = sin(needleAngle).
 *
 * QiblaPanel'e `enabled` true geçildiğinde, müzik çalarken kıble yönüne
 * dönüş ses panoraması üzerinden hissedilir. Tam yönde (needleAngle≈0):
 * her iki kulakta eşit (pan=0). Sağa döndükçe ses sola, sola döndükçe ses
 * sağa kayar — kıble yönünü ses ile bul.
 *
 * Cleanup: enabled=false → manuel pan kilidini bırakır, 8D rotasyonu
 * (varsa) kaldığı yerden devam eder.
 */
import { useEffect } from "react";
import { useJiyanMusic } from "@/hooks/useJiyanMusic";

export function useQiblaMusicPan(needleAngle: number | null, enabled: boolean) {
  const { setManualPan, isPlaying } = useJiyanMusic();

  useEffect(() => {
    if (!enabled || !isPlaying || needleAngle == null) {
      setManualPan(null);
      return;
    }
    // needleAngle = derece kıbleye kalan dönüş (0 = hizalı)
    // sin ile -1..1 yumuşak dönüşüm; sapmayı ters yönde pan ederek "ses kıbleden geliyor" hissi
    const rad = (needleAngle * Math.PI) / 180;
    const pan = -Math.sin(rad); // sağa döndün → ses sola → kıbleye dön ipucu
    setManualPan(Math.max(-1, Math.min(1, pan)));
  }, [needleAngle, enabled, isPlaying, setManualPan]);

  useEffect(() => {
    return () => setManualPan(null);
  }, [setManualPan]);
}

