import { useCallback, useEffect, useState } from "react";

/**
 * useRecentDestinations — tiny localStorage-backed list of the last places the
 * rider searched for in Mivankas. Powers the "Son Gidilenler" quick chips and
 * the recent list inside the destination sheet.
 *
 * Stores a flat list of trimmed query strings (max 8), most recent first.
 */
const STORAGE_KEY = "saha:recent-destinations:v1";
const MAX_ITEMS = 8;

function read(): string[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((s): s is string => typeof s === "string").slice(0, MAX_ITEMS);
  } catch {
    return [];
  }
}

function write(list: string[]) {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(list.slice(0, MAX_ITEMS)));
  } catch {
    /* quota / private mode — ignore */
  }
}

export function useRecentDestinations() {
  const [recents, setRecents] = useState<string[]>([]);

  useEffect(() => {
    setRecents(read());
  }, []);

  const push = useCallback((value: string) => {
    const trimmed = value.trim();
    if (!trimmed) return;
    setRecents((prev) => {
      const next = [trimmed, ...prev.filter((p) => p.toLowerCase() !== trimmed.toLowerCase())].slice(
        0,
        MAX_ITEMS,
      );
      write(next);
      return next;
    });
  }, []);

  const remove = useCallback((value: string) => {
    setRecents((prev) => {
      const next = prev.filter((p) => p !== value);
      write(next);
      return next;
    });
  }, []);

  const clear = useCallback(() => {
    setRecents([]);
    write([]);
  }, []);

  return { recents, push, remove, clear };
}

