import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

interface Review {
  id: string;
  service_id: string;
  reviewer_id: string;
  rating: number;
  comment: string | null;
  created_at: string;
  reviewer_name?: string;
}

export function useReviews(serviceId: string | undefined) {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchReviews = useCallback(async () => {
    if (!serviceId) { setLoading(false); return; }
    const { data } = await supabase
      .from("reviews")
      .select("*")
      .eq("service_id", serviceId)
      .order("created_at", { ascending: false });

    if (data && data.length > 0) {
      const reviewerIds = [...new Set(data.map((r) => r.reviewer_id))];
      const { data: profiles } = await supabase
        .from("profiles")
        .select("user_id, display_name")
        .in("user_id", reviewerIds);

      const nameMap: Record<string, string> = {};
      profiles?.forEach((p) => { nameMap[p.user_id] = p.display_name; });

      setReviews(data.map((r) => ({ ...r, reviewer_name: nameMap[r.reviewer_id] || "User" })) as Review[]);
    } else {
      setReviews([]);
    }
    setLoading(false);
  }, [serviceId]);

  useEffect(() => { fetchReviews(); }, [fetchReviews]);

  const addReview = async (reviewerId: string, rating: number, comment?: string) => {
    if (!serviceId) return false;
    const { error } = await supabase
      .from("reviews")
      .insert({ service_id: serviceId, reviewer_id: reviewerId, rating, comment: comment || null });
    if (error) return false;
    await fetchReviews();
    return true;
  };

  return { reviews, loading, addReview, refetch: fetchReviews };
}

