/**
 * useRitualClock — Sovereign Ritual hook.
 *
 * Loads the user's ritual_settings (or sensible defaults), computes today's
 * prayer schedule via Adhan.js (Aladhan fallback), tracks the next prayer
 * with live countdown, and fires:
 *   • playRitualWarning() at T-(pre_alert_minutes) of every prayer
 *   • playAdhanChime()    at T-0 of every prayer
 *   • a 12s `glow` pulse flag the widget reads to flash gold.
 *
 * Returns everything the AtmosphereWidget needs in a single render-cheap
 * object. SSR-safe: no work on the server.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useHubPreferences } from "@/hooks/useHubPreferences";
import {
  computeRitualTimes,
  fetchRitualTimesAladhan,
  findNextPrayer,
  formatCountdown,
  formatHHMM,
  formatHijri,
  type CalcMethodId,
  type NextPrayer,
  type RitualSchedule,
} from "@/lib/ritualTimes";
import { playAdhanChime, playRitualWarning } from "@/lib/ritualSounds";

interface RitualSettingsRow {
  user_id: string;
  calc_method: string;
  madhab: string;
  latitude: number | null;
  longitude: number | null;
  city_label: string | null;
  adhan_sound: boolean;
  pre_alert_minutes: number;
}

const DEFAULT_LAT = 36.19; // Hewlêr
const DEFAULT_LON = 44.0;

export function useRitualClock() {
  const { user } = useAuth();
  const { prefs } = useHubPreferences();
  const [settings, setSettings] = useState<RitualSettingsRow | null>(null);
  const [schedule, setSchedule] = useState<RitualSchedule | null>(null);
  const [now, setNow] = useState(() => new Date());
  const [glow, setGlow] = useState(false);
  const firedWarnRef = useRef<Set<string>>(new Set());
  const firedChimeRef = useRef<Set<string>>(new Set());

  // Load user settings (best-effort)
  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from("ritual_settings")
        .select("*")
        .eq("user_id", user.id)
        .maybeSingle();
      if (cancelled) return;
      setSettings((data as unknown as RitualSettingsRow) ?? null);
    })();
    return () => {
      cancelled = true;
    };
  }, [user]);

  // Resolve lat/lon: settings → hub weather prefs → default Hewlêr
  const lat =
    settings?.latitude ??
    prefs.weatherLat ??
    DEFAULT_LAT;
  const lon =
    settings?.longitude ??
    prefs.weatherLon ??
    DEFAULT_LON;
  const city = settings?.city_label ?? prefs.weatherLabel ?? "Hewlêr";
  const method = (settings?.calc_method as CalcMethodId) ?? "MWL";
  const madhab = (settings?.madhab as "shafi" | "hanafi") ?? "shafi";
  const preAlert = settings?.pre_alert_minutes ?? 5;
  const adhanOn = settings?.adhan_sound ?? true;

  // Compute schedule for today
  useEffect(() => {
    let cancelled = false;
    try {
      const sch = computeRitualTimes({ latitude: lat, longitude: lon, method, madhab });
      if (!cancelled) setSchedule(sch);
    } catch {
      fetchRitualTimesAladhan(lat, lon).then((sch) => {
        if (!cancelled && sch) setSchedule(sch);
      });
    }
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lat, lon, method, madhab, new Date().toDateString()]);

  // Tick the clock every 15s for accurate countdown / triggers
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 15_000);
    return () => clearInterval(id);
  }, []);

  // Fire warnings / chimes at the right moment
  useEffect(() => {
    if (!schedule) return;
    const today = now.toDateString();
    (Object.keys(schedule) as Array<keyof RitualSchedule>).forEach((name) => {
      if (name === "sunrise") return; // No alert for sunrise
      const at = schedule[name];
      const diffMs = at.getTime() - now.getTime();
      const warnKey = `${today}|${name}|warn`;
      const chimeKey = `${today}|${name}|chime`;

      // Warning window: T-preAlert..T-preAlert+30s
      const warnFrom = preAlert * 60_000;
      if (diffMs <= warnFrom && diffMs > warnFrom - 30_000 && !firedWarnRef.current.has(warnKey)) {
        firedWarnRef.current.add(warnKey);
        if (adhanOn) playRitualWarning();
      }

      // Chime window: T-0..T+30s
      if (diffMs <= 0 && diffMs > -30_000 && !firedChimeRef.current.has(chimeKey)) {
        firedChimeRef.current.add(chimeKey);
        if (adhanOn) playAdhanChime();
        setGlow(true);
        setTimeout(() => setGlow(false), 12_000);
      }
    });
  }, [now, schedule, preAlert, adhanOn]);

  const next: NextPrayer | null = useMemo(
    () => (schedule ? findNextPrayer(schedule, now) : null),
    [schedule, now],
  );

  const updateSettings = useCallback(
    async (patch: Partial<Omit<RitualSettingsRow, "user_id">>) => {
      if (!user) return;
      const merged = {
        user_id: user.id,
        calc_method: settings?.calc_method ?? "MWL",
        madhab: settings?.madhab ?? "shafi",
        latitude: settings?.latitude ?? null,
        longitude: settings?.longitude ?? null,
        city_label: settings?.city_label ?? null,
        adhan_sound: settings?.adhan_sound ?? true,
        pre_alert_minutes: settings?.pre_alert_minutes ?? 5,
        ...patch,
      };
      const { data } = await supabase
        .from("ritual_settings")
        .upsert(merged, { onConflict: "user_id" })
        .select()
        .single();
      if (data) setSettings(data as unknown as RitualSettingsRow);
    },
    [user, settings],
  );

  return {
    schedule,
    next,
    glow,
    city,
    hijri: formatHijri(now),
    countdown: next ? formatCountdown(next.msUntil) : "",
    nextAtHHMM: next ? formatHHMM(next.at) : "",
    settings,
    updateSettings,
    formatHHMM,
  };
}

