/**
 * useRitualMusicBridge — Ritual × Jiyan Music sound bridge.
 *
 * Mounted globally in __root. Watches the user's prayer schedule and:
 *
 *   1. **Sound Bridge (#1)**: At T-(preAlert) of every prayer, gently fades
 *      music volume from 1 → 0.15 over ~6s so the warning chime is audible
 *      without harsh interruption.
 *   2. **Smart Silence (#10)**: At T-0 (vakit girdi) it pauses music and
 *      schedules an automatic resume after `RESUME_AFTER_MS` so the user can
 *      pray, then continues exactly where it left off — volume restored.
 *
 * All effects are no-ops when nothing is playing or when the user disabled
 * the adhan sound (settings.adhan_sound = false).
 */
import { useEffect, useRef } from "react";
import { useJiyanMusic } from "@/hooks/useJiyanMusic";
import { useRitualClock } from "@/hooks/useRitualClock";
import { toast } from "sonner";

const RESUME_AFTER_MS = 5 * 60_000; // 5 dk
const FADE_OUT_MS = 6_000;
const FADE_IN_MS = 2_500;

export function useRitualMusicBridge() {
  const { schedule, settings } = useRitualClock();
  const { isPlaying, pause, resume, fadeVolume, track } = useJiyanMusic();
  const firedFadeRef = useRef<Set<string>>(new Set());
  const firedPauseRef = useRef<Set<string>>(new Set());
  const resumeTimerRef = useRef<number | null>(null);
  const wasPlayingRef = useRef(false);

  const adhanOn = settings?.adhan_sound ?? true;
  const preAlert = settings?.pre_alert_minutes ?? 5;

  useEffect(() => {
    if (!schedule || !adhanOn) return;
    const id = window.setInterval(() => {
      const now = Date.now();
      const today = new Date(now).toDateString();
      (Object.keys(schedule) as Array<keyof typeof schedule>).forEach((name) => {
        if (name === "sunrise") return;
        const at = schedule[name].getTime();
        const diff = at - now;
        const fadeKey = `${today}|${name}|fade`;
        const pauseKey = `${today}|${name}|pause`;

        // T-preAlert window → fade down
        const fadeFrom = preAlert * 60_000;
        if (
          diff <= fadeFrom &&
          diff > fadeFrom - 30_000 &&
          !firedFadeRef.current.has(fadeKey) &&
          isPlaying
        ) {
          firedFadeRef.current.add(fadeKey);
          void fadeVolume(0.15, FADE_OUT_MS);
          toast.info(`${formatName(String(name))} yaklaşıyor`, {
            description: "Müzik kısıldı — vakit girdiğinde duraklayacak",
          });
        }

        // T-0 window → pause + schedule resume
        if (
          diff <= 0 &&
          diff > -30_000 &&
          !firedPauseRef.current.has(pauseKey) &&
          (isPlaying || wasPlayingRef.current)
        ) {
          firedPauseRef.current.add(pauseKey);
          wasPlayingRef.current = isPlaying;
          if (isPlaying) pause();
          if (resumeTimerRef.current) clearTimeout(resumeTimerRef.current);
          resumeTimerRef.current = window.setTimeout(async () => {
            await fadeVolume(1, FADE_IN_MS).catch(() => {});
            // Restore volume even if user already resumed manually
            if (wasPlayingRef.current && track) {
              await resume();
              toast("Müzik geri yüklendi", { description: "Vakit tamamlandı" });
            }
          }, RESUME_AFTER_MS);
        }
      });
    }, 10_000);
    return () => clearInterval(id);
  }, [schedule, adhanOn, preAlert, isPlaying, pause, resume, fadeVolume, track]);

  // Cleanup resume timer on unmount
  useEffect(() => {
    return () => {
      if (resumeTimerRef.current) clearTimeout(resumeTimerRef.current);
    };
  }, []);
}

function formatName(n: string): string {
  const m: Record<string, string> = {
    fajr: "Fajr",
    dhuhr: "Dhuhr",
    asr: "Asr",
    maghrib: "Maghrib",
    isha: "Isha",
  };
  return m[n] ?? n;
}

