/**
 * useRobotPreferences — local-storage preferences for the 3D Deng AI robot.
 * Theme-aware: presets follow the Linguist's gold/purple palette but the user
 * can override brightness, eye color, and camera angle.
 */
import { useEffect, useState, useCallback } from "react";

export type EyeColorKey = "purple" | "gold" | "emerald" | "azure" | "rose";
export type CameraAngleKey = "front" | "low" | "high" | "tilt";

export interface RobotPreferences {
  brightness: number;       // 0.4 .. 1.8
  eyeColor: EyeColorKey;
  cameraAngle: CameraAngleKey;
}

export const EYE_COLORS: Record<EyeColorKey, { hex: string; label: string }> = {
  purple:  { hex: "#a78bfa", label: "Mor" },
  gold:    { hex: "#F2C94C", label: "Altın" },
  emerald: { hex: "#34d399", label: "Zümrüt" },
  azure:   { hex: "#60a5fa", label: "Gök" },
  rose:    { hex: "#fb7185", label: "Gül" },
};

export const CAMERA_ANGLES: Record<CameraAngleKey, { pos: [number, number, number]; label: string }> = {
  front: { pos: [0, 0.2, 3.2],  label: "Önden" },
  low:   { pos: [0, -0.6, 3.2], label: "Alttan" },
  high:  { pos: [0, 1.0, 3.0],  label: "Üstten" },
  tilt:  { pos: [1.6, 0.4, 2.8], label: "Yandan" },
};

const DEFAULTS: RobotPreferences = {
  brightness: 1,
  eyeColor: "purple",
  cameraAngle: "front",
};

const KEY = "linguist:robotPrefs:v1";

export function useRobotPreferences() {
  const [prefs, setPrefs] = useState<RobotPreferences>(DEFAULTS);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) setPrefs({ ...DEFAULTS, ...JSON.parse(raw) });
    } catch { /* ignore */ }
  }, []);

  const update = useCallback((patch: Partial<RobotPreferences>) => {
    setPrefs((p) => {
      const next = { ...p, ...patch };
      try { localStorage.setItem(KEY, JSON.stringify(next)); } catch { /* ignore */ }
      return next;
    });
  }, []);

  const reset = useCallback(() => {
    setPrefs(DEFAULTS);
    try { localStorage.removeItem(KEY); } catch { /* ignore */ }
  }, []);

  return { prefs, update, reset };
}

