import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import JSZip from "jszip";

export interface SosEvidenceFile {
  id: string;
  user_id: string;
  storage_path: string;
  file_name: string;
  content_type: string;
  size_bytes: number;
  captured_at: string;
  latitude: number | null;
  longitude: number | null;
  notes: string;
  created_at: string;
}

export function useSosEvidence(userId: string | undefined) {
  const [files, setFiles] = useState<SosEvidenceFile[]>([]);
  const [loading, setLoading] = useState(true);
  const [exporting, setExporting] = useState(false);
  const [uploading, setUploading] = useState(false);

  const refresh = useCallback(async () => {
    if (!userId) {
      setFiles([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    const { data } = await supabase
      .from("sos_evidence_files")
      .select("*")
      .eq("user_id", userId)
      .order("captured_at", { ascending: false })
      .limit(200);
    setFiles((data ?? []) as SosEvidenceFile[]);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  /** Upload an evidence file (image/video/audio) to the private bucket. */
  const uploadEvidence = useCallback(
    async (
      file: File,
      meta?: { latitude?: number | null; longitude?: number | null; notes?: string },
    ): Promise<boolean> => {
      if (!userId) {
        toast.error("Önce giriş yapın");
        return false;
      }
      setUploading(true);
      try {
        const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, "_");
        const path = `${userId}/${Date.now()}_${safeName}`;
        const { error: upErr } = await supabase.storage
          .from("sos-evidence")
          .upload(path, file, { contentType: file.type, upsert: false });
        if (upErr) {
          toast.error("Yükleme hatası: " + upErr.message);
          return false;
        }
        const { error: dbErr } = await supabase.from("sos_evidence_files").insert({
          user_id: userId,
          storage_path: path,
          file_name: file.name,
          content_type: file.type || "application/octet-stream",
          size_bytes: file.size,
          latitude: meta?.latitude ?? null,
          longitude: meta?.longitude ?? null,
          notes: meta?.notes ?? "",
        });
        if (dbErr) {
          toast.error("Kayıt başarısız: " + dbErr.message);
          return false;
        }
        toast.success("Kanıt kasaya eklendi");
        await refresh();
        return true;
      } finally {
        setUploading(false);
      }
    },
    [userId, refresh],
  );

  /** Build a ZIP bundle with all evidence + a JSON manifest and trigger browser download. */
  const exportBundle = useCallback(async (): Promise<boolean> => {
    if (!userId) return false;
    if (files.length === 0) {
      toast.error("Kasa boş");
      return false;
    }
    setExporting(true);
    try {
      const zip = new JSZip();
      const folder = zip.folder("evidence");
      const manifest = {
        generated_at: new Date().toISOString(),
        owner_user_id: userId,
        total_files: files.length,
        bucket: "sos-evidence",
        files: [] as Array<{
          id: string;
          file_name: string;
          archive_path: string;
          captured_at: string;
          content_type: string;
          size_bytes: number;
          latitude: number | null;
          longitude: number | null;
          notes: string;
        }>,
      };

      for (const f of files) {
        const { data: blob, error } = await supabase.storage
          .from("sos-evidence")
          .download(f.storage_path);
        if (error || !blob) {
          // Skip missing/forbidden files but still record in manifest
          manifest.files.push({
            id: f.id,
            file_name: f.file_name,
            archive_path: `evidence/MISSING_${f.file_name}`,
            captured_at: f.captured_at,
            content_type: f.content_type,
            size_bytes: f.size_bytes,
            latitude: f.latitude,
            longitude: f.longitude,
            notes: f.notes,
          });
          continue;
        }
        const ts = f.captured_at.replace(/[:.]/g, "-");
        const archivePath = `${ts}__${f.file_name}`;
        folder?.file(archivePath, blob);
        manifest.files.push({
          id: f.id,
          file_name: f.file_name,
          archive_path: `evidence/${archivePath}`,
          captured_at: f.captured_at,
          content_type: f.content_type,
          size_bytes: f.size_bytes,
          latitude: f.latitude,
          longitude: f.longitude,
          notes: f.notes,
        });
      }

      zip.file("manifest.json", JSON.stringify(manifest, null, 2));
      zip.file(
        "README.txt",
        [
          "WKO Sovereign — SOS Evidence Vault Export",
          `Generated: ${manifest.generated_at}`,
          `Owner: ${userId}`,
          `Files: ${manifest.total_files}`,
          "",
          "All evidence is stored in the encrypted /evidence folder.",
          "manifest.json contains timestamps, content types, sizes and GPS metadata.",
        ].join("\n"),
      );

      const blob = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `sos-evidence-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-")}.zip`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);

      toast.success("Kanıt paketi indiriliyor");
      return true;
    } catch (e) {
      toast.error("Export hatası: " + (e instanceof Error ? e.message : "bilinmiyor"));
      return false;
    } finally {
      setExporting(false);
    }
  }, [userId, files]);

  const totalBytes = files.reduce((s, f) => s + (f.size_bytes ?? 0), 0);

  return {
    files,
    loading,
    exporting,
    uploading,
    totalBytes,
    refresh,
    uploadEvidence,
    exportBundle,
  };
}

