/**
 * Admin RPCs for the Executive Command Center.
 * All RPCs are SECURITY DEFINER and check has_role(auth.uid(), 'admin').
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export type AppRole =
  | "admin"
  | "moderator"
  | "field_representative"
  | "district_guardian"
  | "creator"
  | "user";

export interface CitizenRow {
  user_id: string;
  display_name: string | null;
  username: string | null;
  kurd_id: string | null;
  is_verified: boolean;
  keka_points: number;
  city: string | null;
  avatar_url: string | null;
  created_at: string;
  role_count: number;
}

export interface UserRoleRow {
  id: string;
  role: AppRole;
  district: string | null;
  notes: string | null;
  assigned_at: string;
  assigned_by: string | null;
  assigned_by_name: string | null;
}

export interface TreasuryStats {
  total_treasury_dc: number;
  locked_dc: number;
  circulating_dc: number;
  total_citizens: number;
  verified_citizens: number;
  avg_keka: number;
  active_roles: number;
}

export function useCitizenSearch(initialQuery = "") {
  const [query, setQuery] = useState(initialQuery);
  const [rows, setRows] = useState<CitizenRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchRows = useCallback(async (q: string) => {
    setLoading(true);
    setError(null);
    const { data, error } = await supabase.rpc("admin_search_citizens", {
      _query: q || undefined,
      _limit: 100,
      _offset: 0,
    });
    if (error) setError(error.message);
    else setRows((data as CitizenRow[]) ?? []);
    setLoading(false);
  }, []);

  useEffect(() => {
    const t = setTimeout(() => fetchRows(query), 250);
    return () => clearTimeout(t);
  }, [query, fetchRows]);

  // Realtime: refresh when profiles or user_roles change
  useEffect(() => {
    const channel = supabase
      .channel("admin-citizens-live")
      .on("postgres_changes", { event: "*", schema: "public", table: "profiles" }, () => {
        fetchRows(query);
      })
      .on("postgres_changes", { event: "*", schema: "public", table: "user_roles" }, () => {
        fetchRows(query);
      })
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [query, fetchRows]);

  return { query, setQuery, rows, loading, error, refresh: () => fetchRows(query) };
}

export function useUserRoles(userId: string | null) {
  const [roles, setRoles] = useState<UserRoleRow[]>([]);
  const [loading, setLoading] = useState(false);

  const refresh = useCallback(async () => {
    if (!userId) {
      setRoles([]);
      return;
    }
    setLoading(true);
    const { data } = await supabase.rpc("admin_get_user_roles", { _target_user: userId });
    setRoles((data as UserRoleRow[]) ?? []);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Realtime: live role changes for this user
  useEffect(() => {
    if (!userId) return;
    const channel = supabase
      .channel(`admin-user-roles-${userId}`)
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "user_roles", filter: `user_id=eq.${userId}` },
        () => refresh()
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [userId, refresh]);

  return { roles, loading, refresh };
}

export function useTreasuryStats() {
  const [stats, setStats] = useState<TreasuryStats | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    setLoading(true);
    const { data } = await supabase.rpc("admin_get_treasury_stats");
    const row = (data as TreasuryStats[] | null)?.[0] ?? null;
    setStats(row);
    setLoading(false);
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  return { stats, loading, refresh };
}

export async function adminAssignRole(params: {
  targetUser: string;
  role: AppRole;
  district?: string;
  notes?: string;
}): Promise<{ ok: boolean; error?: string }> {
  const { error } = await supabase.rpc("admin_assign_role", {
    _target_user: params.targetUser,
    _role: params.role,
    _district: params.district ?? undefined,
    _notes: params.notes ?? undefined,
  });
  if (error) return { ok: false, error: error.message };
  return { ok: true };
}

export async function adminRevokeRole(roleId: string, reason?: string) {
  const { error } = await supabase.rpc("admin_revoke_role", {
    _role_id: roleId,
    _reason: reason ?? undefined,
  });
  if (error) return { ok: false, error: error.message };
  return { ok: true };
}

export async function adminOverrideKyc(targetUser: string, verified: boolean, reason?: string) {
  const { error } = await supabase.rpc("admin_override_kyc", {
    _target_user: targetUser,
    _verified: verified,
    _reason: reason ?? undefined,
  });
  if (error) return { ok: false, error: error.message };
  return { ok: true };
}

/** Public — returns visible roles for any user, used by Sovereign ID badge. */
export interface PublicRole {
  role: AppRole;
  district: string | null;
  assigned_at: string;
}

export function useUserPublicRoles(userId: string | null | undefined) {
  const [roles, setRoles] = useState<PublicRole[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!userId) {
      setRoles([]);
      setLoading(false);
      return;
    }
    let alive = true;
    setLoading(true);
    supabase
      .rpc("get_user_public_roles", { _target_user: userId })
      .then(({ data }) => {
        if (!alive) return;
        setRoles((data as PublicRole[]) ?? []);
        setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [userId]);

  return { roles, loading };
}

