/**
 * useSovereignAuth — Global cross-app authentication state.
 *
 * Reads `sovereign_auth_state` for the current user. When a user verifies
 * with the Authenticator (TOTP), passkey, or biometric the row's
 * `verified_until` is bumped via `bump_sovereign_auth`. Mini-apps (Mail,
 * Wallet, ID Borsa) read `isSovereignVerified` to skip secondary prompts.
 *
 * The hook subscribes to realtime changes so the gold shield in the status
 * bar pulses across every open tab the moment verification happens.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export type SovereignAuthMethod = "totp" | "passkey" | "biometric" | "password";

export interface SovereignAuthState {
  verifiedAt: string | null;
  verifiedUntil: string | null;
  lastMethod: SovereignAuthMethod | null;
  lastDeviceLabel: string | null;
}

const EMPTY: SovereignAuthState = {
  verifiedAt: null,
  verifiedUntil: null,
  lastMethod: null,
  lastDeviceLabel: null,
};

export function useSovereignAuth() {
  const { user } = useAuth();
  const [state, setState] = useState<SovereignAuthState>(EMPTY);
  const [loading, setLoading] = useState(true);
  const [now, setNow] = useState(() => Date.now());

  // 5-second tick so isSovereignVerified flips to false the moment the
  // verification window expires, without waiting for a DB poll.
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 5_000);
    return () => clearInterval(t);
  }, []);

  const refresh = useCallback(async () => {
    if (!user) {
      setState(EMPTY);
      setLoading(false);
      return;
    }
    const { data } = await supabase
      .from("sovereign_auth_state")
      .select("verified_at, verified_until, last_method, last_device_label")
      .eq("user_id", user.id)
      .maybeSingle();
    setState({
      verifiedAt: data?.verified_at ?? null,
      verifiedUntil: data?.verified_until ?? null,
      lastMethod: (data?.last_method as SovereignAuthMethod | null) ?? null,
      lastDeviceLabel: data?.last_device_label ?? null,
    });
    setLoading(false);
  }, [user]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Realtime — pulse the gold shield across tabs.
  // NOTE: nonce ensures every hook instance gets its own channel — Supabase
  // Realtime forbids adding postgres_changes callbacks to a channel name that
  // already has an active subscription from another component on the page.
  useEffect(() => {
    if (!user) return;
    const nonce = Math.random().toString(36).slice(2, 10);
    const channel = supabase
      .channel(`sovereign-auth-${user.id}-${nonce}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "sovereign_auth_state",
          filter: `user_id=eq.${user.id}`,
        },
        () => refresh(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, refresh]);

  /** Push the verified window forward (used by Authenticator + passkey verify). */
  const bump = useCallback(
    async (
      method: SovereignAuthMethod,
      ttlMinutes = 15,
      deviceLabel?: string,
    ): Promise<string | null> => {
      if (!user) return null;
      const { data, error } = await supabase.rpc("bump_sovereign_auth", {
        _method: method,
        _ttl_minutes: ttlMinutes,
        _device_label: deviceLabel,
      });
      if (error) return null;
      await refresh();
      return (data as string | null) ?? null;
    },
    [user, refresh],
  );

  const verifiedUntilMs = state.verifiedUntil
    ? new Date(state.verifiedUntil).getTime()
    : 0;
  const isSovereignVerified = verifiedUntilMs > now;
  const remainingSeconds = isSovereignVerified
    ? Math.max(0, Math.floor((verifiedUntilMs - now) / 1000))
    : 0;

  return {
    state,
    loading,
    isSovereignVerified,
    remainingSeconds,
    bump,
    refresh,
  };
}

