/**
 * useSovereignIdentity — the +777 Identity Bridge.
 *
 * Maps every authentication method (Google, Apple, Email/Şifre, Kurd-ID
 * passkey, biometric) to ONE Sovereign Identity. Whichever method the
 * citizen used to log in, the result resolves to the same +777 ID and
 * the same profile row.
 *
 * Sovereign Identity unifies:
 *   • Linked auth providers (Supabase reports them in `user.identities`)
 *   • Whether the citizen owns a Kurd-ID (+777 XXXX XXXX)
 *   • Trusted device / passkey signals
 *
 * This hook is purely client-side: it reads what Supabase already knows
 * about the user's session (no extra round-trips on every render). The
 * shape returned is intentionally cheap to use anywhere — Hub badges,
 * settings rows, login screen subtitle, profile chips.
 */
import { useEffect, useMemo, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export type IdentityProvider = "google" | "apple" | "email" | "phone" | "kurd-id";

export interface SovereignIdentity {
  /** True once the bridge has loaded the profile row */
  ready: boolean;
  /** Authenticated user id (Supabase) — null when guest */
  userId: string | null;
  /** Display name from profile */
  displayName: string | null;
  /** Avatar URL from profile */
  avatarUrl: string | null;
  /** Citizen's +777 ID, e.g. "+777 4242 0001". null when none yet */
  kurdId: string | null;
  /** All linked auth providers (deduplicated) */
  providers: IdentityProvider[];
  /** Convenience checks */
  hasGoogle: boolean;
  hasApple: boolean;
  hasEmail: boolean;
  hasKurdId: boolean;
  /** Email of the +777 mailbox (e.g. "<username>@jiyan.world") */
  jiyanEmail: string | null;
  /** True when the citizen is fully sealed (has a Kurd-ID + ≥1 OAuth) */
  isSealed: boolean;
}

const EMPTY: SovereignIdentity = {
  ready: false,
  userId: null,
  displayName: null,
  avatarUrl: null,
  kurdId: null,
  providers: [],
  hasGoogle: false,
  hasApple: false,
  hasEmail: false,
  hasKurdId: false,
  jiyanEmail: null,
  isSealed: false,
};

interface ProfileRow {
  display_name: string | null;
  avatar_url: string | null;
  kurd_id: string | null;
  username: string | null;
}

export function useSovereignIdentity(): SovereignIdentity {
  const { user, loading } = useAuth();
  const [profile, setProfile] = useState<ProfileRow | null>(null);
  const [profileLoaded, setProfileLoaded] = useState(false);

  useEffect(() => {
    let cancelled = false;
    if (!user) {
      setProfile(null);
      setProfileLoaded(false);
      return;
    }
    setProfileLoaded(false);
    supabase
      .from("profiles")
      .select("display_name, avatar_url, kurd_id, username")
      .eq("user_id", user.id)
      .maybeSingle()
      .then(({ data }) => {
        if (cancelled) return;
        setProfile((data as ProfileRow) ?? null);
        setProfileLoaded(true);
      });
    return () => {
      cancelled = true;
    };
  }, [user]);

  return useMemo<SovereignIdentity>(() => {
    if (loading) return EMPTY;
    if (!user) return { ...EMPTY, ready: true };

    // Supabase exposes linked identities on `user.identities`. Fall back
    // to `app_metadata.providers` (older sessions) and finally to the
    // single `app_metadata.provider`.
    const set = new Set<IdentityProvider>();
    const ids = (user as unknown as { identities?: Array<{ provider: string }> }).identities ?? [];
    ids.forEach((i) => mapProvider(i.provider).forEach((p) => set.add(p)));
    const meta = (user.app_metadata ?? {}) as { providers?: string[]; provider?: string };
    (meta.providers ?? []).forEach((p) => mapProvider(p).forEach((x) => set.add(x)));
    if (meta.provider) mapProvider(meta.provider).forEach((p) => set.add(p));
    if (profile?.kurd_id) set.add("kurd-id");

    const providers = Array.from(set);
    const hasGoogle = set.has("google");
    const hasApple = set.has("apple");
    const hasEmail = set.has("email");
    const hasKurdId = !!profile?.kurd_id;
    const jiyanEmail = profile?.username ? `${profile.username}@jiyan.world` : null;

    return {
      ready: profileLoaded,
      userId: user.id,
      displayName: profile?.display_name ?? null,
      avatarUrl: profile?.avatar_url ?? null,
      kurdId: profile?.kurd_id ?? null,
      providers,
      hasGoogle,
      hasApple,
      hasEmail,
      hasKurdId,
      jiyanEmail,
      isSealed: hasKurdId && (hasGoogle || hasApple || hasEmail),
    };
  }, [user, loading, profile, profileLoaded]);
}

function mapProvider(p: string): IdentityProvider[] {
  const k = p.toLowerCase();
  if (k === "google") return ["google"];
  if (k === "apple") return ["apple"];
  if (k === "email" || k === "password") return ["email"];
  if (k === "phone") return ["phone"];
  return [];
}

