/**
 * useSovereignPhone — Sovereign Phone (+777 VoIP) WebRTC engine.
 *
 * IMPORTANT — Singleton via Context:
 *   The hook MUST share a single state across IncomingCallIsland,
 *   SovereignCallScreen and the /phone route. Otherwise each consumer creates
 *   its own RTCPeerConnection and Realtime subscription, the inbound `offer`
 *   never finds the PC built by `accept()`, and the call screen never opens.
 *
 *   We mount <SovereignPhoneProvider> exactly once at the AppShell level.
 *
 * Architecture:
 *   • Peer-to-peer WebRTC for ultra-low latency audio/video.
 *   • Signaling relayed through `phone_call_signals` (Supabase Realtime),
 *     keyed on a per-call UUID + the recipient's `auth.users.id`.
 *   • Public Google STUN servers (no TURN — works on most networks; if a
 *     symmetric NAT blocks it the call fails fast).
 *   • E2E media via DTLS-SRTP (built into WebRTC) — payloads never touch
 *     our DB; only the SDP offer/answer + ICE candidates do.
 */
import {
  createContext,
  ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { hapticHeavy, hapticSuccess, hapticTap } from "@/lib/native";
import { publishIntentToLighthouse } from "@/lib/lighthouseStorage";
import { startSovereignRingtone, stopSovereignRingtone } from "@/lib/sovereignRingtone";
import { acquireWakeLock, releaseWakeLock } from "@/lib/wakeLock";
import { logLocalOutgoingCall } from "@/lib/phoneRecent";
import { startCallKeepAlive, stopCallKeepAlive } from "@/lib/keepCallAlive";
import { startPhantomArmor, stopPhantomArmor } from "@/lib/phantomArmor";

type SignalKind = "ring" | "offer" | "answer" | "ice" | "hangup" | "reject" | "accept";

interface SignalRow {
  id: string;
  call_id: string;
  from_user: string;
  to_user: string;
  kind: SignalKind;
  payload: Record<string, unknown>;
  created_at: string;
}

export interface IncomingCall {
  callId: string;
  fromUserId: string;
  fromKurdId: string | null;
  fromName: string | null;
  fromAvatar: string | null;
  video: boolean;
  ringingSince: number;
}

export interface ActiveCall {
  callId: string;
  peerUserId: string;
  peerKurdId: string | null;
  peerName: string | null;
  peerAvatar: string | null;
  video: boolean;
  outbound: boolean;
  startedAt: number;
}

const ICE_SERVERS: RTCIceServer[] = [
  { urls: "stun:stun.l.google.com:19302" },
  { urls: "stun:stun1.l.google.com:19302" },
];

interface PeerProfile {
  user_id: string;
  display_name: string | null;
  kurd_id: string | null;
  avatar_url: string | null;
}

async function fetchProfile(userId: string): Promise<PeerProfile | null> {
  const { data } = await supabase
    .from("profiles")
    .select("user_id, display_name, kurd_id, avatar_url")
    .eq("user_id", userId)
    .maybeSingle();
  return (data as PeerProfile | null) ?? null;
}

/** Resolve a Kurd-ID like "+777 1234 5678" → user_id. */
export async function lookupByKurdId(kurdId: string): Promise<PeerProfile | null> {
  const cleaned = kurdId.replace(/\s+/g, "");
  const variants = [kurdId, cleaned, cleaned.startsWith("+") ? cleaned : `+${cleaned}`];
  for (const v of variants) {
    const { data } = await supabase
      .from("profiles")
      .select("user_id, display_name, kurd_id, avatar_url")
      .eq("kurd_id", v)
      .maybeSingle();
    if (data) return data as PeerProfile;
  }
  return null;
}

interface PhoneApi {
  incoming: IncomingCall | null;
  active: ActiveCall | null;
  muted: boolean;
  speaker: boolean;
  videoOn: boolean;
  localStream: MediaStream | null;
  remoteStream: MediaStream | null;
  requestAudioAccess: (video?: boolean) => Promise<{ ok: boolean; reason?: string }>;
  placeCall: (toUserId: string, video?: boolean) => Promise<{ ok: boolean; reason?: string }>;
  accept: () => Promise<{ ok: boolean; reason?: string }>;
  reject: () => Promise<void>;
  hangup: () => Promise<void>;
  toggleMute: () => void;
  toggleSpeaker: () => void;
  toggleVideo: () => Promise<void>;
  sendDtmf: (tones: string) => void;
}

const PhoneContext = createContext<PhoneApi | null>(null);

function useSovereignPhoneEngine(): PhoneApi {
  const { user } = useAuth();
  const userId = user?.id;

  const [incoming, setIncoming] = useState<IncomingCall | null>(null);
  const [active, setActive] = useState<ActiveCall | null>(null);
  const [muted, setMuted] = useState(false);
  const [speaker, setSpeaker] = useState(true);
  const [videoOn, setVideoOn] = useState(false);
  const [localStream, setLocalStream] = useState<MediaStream | null>(null);
  const [remoteStream, setRemoteStream] = useState<MediaStream | null>(null);

  const pcRef = useRef<RTCPeerConnection | null>(null);
  const localStreamRef = useRef<MediaStream | null>(null);
  /** Buffer ICE candidates received before the remote description is set. */
  const pendingIceRef = useRef<RTCIceCandidateInit[]>([]);
  /** Buffer the remote offer SDP if it arrives before we have built our PC (callee race). */
  const pendingOfferRef = useRef<{ sdp: string; type: RTCSdpType; from: string; callId: string } | null>(null);
  /** The single in-flight call ID we're tracking. */
  const callIdRef = useRef<string | null>(null);
  const peerIdRef = useRef<string | null>(null);

  /** Send a signal to the peer. */
  const sendSignal = useCallback(
    async (kind: SignalKind, toUser: string, callId: string, payload: Record<string, unknown> = {}) => {
      if (!userId) return;
      await supabase.from("phone_call_signals").insert([
        {
          call_id: callId,
          from_user: userId,
          to_user: toUser,
          kind,
          payload: payload as never,
        },
      ]);
    },
    [userId],
  );

  /** Tear down the peer connection + local media. */
  const teardown = useCallback(async () => {
    // Phase 1 — kill the network: WebRTC senders + decoy Phantom Armor.
    stopPhantomArmor();
    stopCallKeepAlive();
    try {
      pcRef.current?.getSenders().forEach((s) => s.track?.stop());
      pcRef.current?.getReceivers().forEach((r) => r.track?.stop());
      pcRef.current?.close();
    } catch {/* noop */}
    pcRef.current = null;

    // Phase 2 — wipe in-RAM media streams (mic/cam) so no track keeps the
    // hardware indicator on after hangup.
    localStreamRef.current?.getTracks().forEach((t) => t.stop());
    localStreamRef.current = null;
    setLocalStream(null);
    setRemoteStream(null);

    // Phase 3 — wipe pending signaling buffers so a stale ICE/offer cannot
    // resurrect the call after teardown completes.
    pendingIceRef.current = [];
    pendingOfferRef.current = null;

    const cid = callIdRef.current;
    if (cid) {
      // Phase 4 — purge call signals + finalize the sovereign ledger.
      try {
        await supabase.from("phone_call_signals").delete().eq("call_id", cid);
      } catch {/* noop */}
      try {
        await supabase
          .from("call_intents")
          .update({ status: "ended", ended_at: new Date().toISOString() })
          .eq("call_id", cid)
          .in("status", ["ringing", "accepted"]);
      } catch {/* noop */}
    }
    callIdRef.current = null;
    peerIdRef.current = null;
    setActive(null);
    setMuted(false);
    setVideoOn(false);

    // Dev-only RAM wipe verification — surfaces leaks immediately.
    if (import.meta.env.DEV) {
      const leak =
        pcRef.current ||
        localStreamRef.current ||
        callIdRef.current ||
        peerIdRef.current ||
        pendingIceRef.current.length > 0 ||
        pendingOfferRef.current;
      if (leak) {
        // eslint-disable-next-line no-console
        console.warn("[SovereignPhone] teardown LEAK detected", { leak });
      } else {
        // eslint-disable-next-line no-console
        console.info("[SovereignPhone] teardown clean — RAM wiped");
      }
    }
  }, []);

  /** Prefer modern HD video codecs (VP9 → H.265/HEVC → H.264 → VP8). */
  const applyPreferredVideoCodecs = useCallback((pc: RTCPeerConnection) => {
    try {
      const caps = (RTCRtpReceiver as unknown as { getCapabilities?: (k: string) => RTCRtpCapabilities | null })
        .getCapabilities?.("video");
      const codecs = caps?.codecs ?? [];
      if (!codecs.length) return;
      const order = ["video/VP9", "video/H265", "video/H264", "video/VP8"];
      const sorted = [...codecs].sort(
        (a, b) => order.findIndex((m) => m.toLowerCase() === a.mimeType.toLowerCase())
                - order.findIndex((m) => m.toLowerCase() === b.mimeType.toLowerCase())
      );
      pc.getTransceivers().forEach((t) => {
        if (t.sender?.track?.kind === "video" || t.receiver?.track?.kind === "video") {
          try { t.setCodecPreferences?.(sorted); } catch {/* unsupported */}
        }
      });
    } catch {/* unsupported */}
  }, []);

  /** Build a fresh RTCPeerConnection with our standard handlers. */
  const buildPC = useCallback(
    (peerId: string, callId: string): RTCPeerConnection => {
      const pc = new RTCPeerConnection({ iceServers: ICE_SERVERS });

      pc.onicecandidate = (e) => {
        if (e.candidate) {
          void sendSignal("ice", peerId, callId, { candidate: e.candidate.toJSON() });
        }
      };

      pc.ontrack = (e) => {
        const stream = e.streams[0] ?? new MediaStream([e.track]);
        setRemoteStream(stream);
      };

      pc.onconnectionstatechange = () => {
        const s = pc.connectionState;
        if (s === "failed" || s === "disconnected" || s === "closed") {
          if (callIdRef.current === callId) void teardown();
        }
      };

      pcRef.current = pc;
      return pc;
    },
    [sendSignal, teardown],
  );

  /** Acquire mic (+ camera if video). */
  const getLocalMedia = useCallback(async (video: boolean): Promise<MediaStream> => {
    if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
      throw new Error("Bu cihaz güvenli mikrofon erişimini desteklemiyor");
    }
    const stream = await navigator.mediaDevices.getUserMedia({
      audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
      // HD video: 1280x720 @ 30fps preferred, falls back gracefully if unsupported.
      video: video
        ? {
            width: { ideal: 1280, max: 1920 },
            height: { ideal: 720, max: 1080 },
            frameRate: { ideal: 30, max: 60 },
            facingMode: "user",
          }
        : false,
    });
    localStreamRef.current = stream;
    setLocalStream(stream);
    setVideoOn(video);
    return stream;
  }, []);

  const requestAudioAccess = useCallback(
    async (video = false): Promise<{ ok: boolean; reason?: string }> => {
      try {
        const stream = await getLocalMedia(video);
        stream.getTracks().forEach((t) => t.stop());
        localStreamRef.current = null;
        setLocalStream(null);
        setVideoOn(false);
        return { ok: true };
      } catch (err) {
        const reason = err instanceof Error ? err.message : "Mikrofon erişimi reddedildi";
        return { ok: false, reason };
      }
    },
    [getLocalMedia],
  );

  /** ─── Outbound: place a call ───────────────────────────────────── */
  const placeCall = useCallback(
    async (toUserId: string, video = false): Promise<{ ok: boolean; reason?: string }> => {
      if (!userId) return { ok: false, reason: "Oturum yok" };
      if (active || incoming) return { ok: false, reason: "Zaten bir çağrı var" };

      // Sovereign-only: WebRTC zorunlu. Yerel GSM dialer'a fallback YOK —
      // her arama jiyan.world şifreli veri akışı üzerinden gider.
      if (typeof window !== "undefined" && typeof RTCPeerConnection === "undefined") {
        return { ok: false, reason: "Bu cihaz WebRTC desteklemiyor (Sovereign hat açılamadı)" };
      }

      const callId = (typeof crypto !== "undefined" && "randomUUID" in crypto
        ? crypto.randomUUID()
        : `call-${Date.now()}-${Math.random().toString(36).slice(2)}`);

      callIdRef.current = callId;
      peerIdRef.current = toUserId;

      const peerProfile = await fetchProfile(toUserId);

      try {
        const stream = await getLocalMedia(video);
        const pc = buildPC(toUserId, callId);
        stream.getTracks().forEach((t) => pc.addTrack(t, stream));
        if (video) applyPreferredVideoCodecs(pc);

        const intentInsert = await supabase.from("call_intents").insert({
          caller_id: userId,
          callee_id: toUserId,
          call_id: callId,
          video,
          intent_cid: null,
          status: "ringing",
        });
        if (intentInsert.error) throw intentInsert.error;

        const offer = await pc.createOffer({ offerToReceiveAudio: true, offerToReceiveVideo: video });
        await pc.setLocalDescription(offer);

        await sendSignal("ring", toUserId, callId, { video });
        await sendSignal("offer", toUserId, callId, { sdp: offer.sdp, type: offer.type, video });

        setActive({
          callId,
          peerUserId: toUserId,
          peerKurdId: peerProfile?.kurd_id ?? null,
          peerName: peerProfile?.display_name ?? null,
          peerAvatar: peerProfile?.avatar_url ?? null,
          video,
          outbound: true,
          startedAt: Date.now(),
        });
        startPhantomArmor();

        // ── Sovereign anchoring (best-effort, non-blocking) ──
        // Publish an encrypted Call Intent CID on Filecoin/IPFS via Lighthouse,
        // and write a public `call_intents` row so the call exists outside any
        // single backend. Real-time signaling still rides Realtime above.
        void (async () => {
          try {
            const intentPayload = {
              v: 1,
              callId,
              from: userId,
              to: toUserId,
              video,
              ts: Date.now(),
            };
            const lh = await publishIntentToLighthouse(intentPayload, `call-${callId}.json`);
            if (lh?.cid) {
              await supabase.from("call_intents").update({ intent_cid: lh.cid }).eq("call_id", callId);
            }
            if (lh?.cid) {
              await sendSignal("ring", toUserId, callId, { video, cid: lh.cid });
            }
          } catch (e) {
            console.warn("[phone] intent anchor failed", e);
          }
        })();

        void hapticTap();
        return { ok: true };
      } catch (err) {
        await teardown();
        return { ok: false, reason: err instanceof Error ? err.message : "Mikrofon erişimi reddedildi" };
      }
    },
    [userId, active, incoming, getLocalMedia, buildPC, sendSignal, teardown],
  );

  /** ─── Inbound: accept the ringing call ─────────────────────────── */
  const accept = useCallback(async (): Promise<{ ok: boolean; reason?: string }> => {
    if (!incoming || !userId) return { ok: false, reason: "Çağrı yok" };
    const call = incoming;
    setIncoming(null);

    callIdRef.current = call.callId;
    peerIdRef.current = call.fromUserId;

    try {
      const stream = await getLocalMedia(call.video);
      const pc = buildPC(call.fromUserId, call.callId);
      stream.getTracks().forEach((t) => pc.addTrack(t, stream));
      if (call.video) applyPreferredVideoCodecs(pc);

      // If the offer SDP already arrived (it almost always does — `ring` and
      // `offer` are inserted back-to-back by the caller), consume it now.
      const buffered = pendingOfferRef.current;
      if (buffered && buffered.callId === call.callId) {
        await pc.setRemoteDescription({ type: buffered.type, sdp: buffered.sdp });
        const answer = await pc.createAnswer();
        await pc.setLocalDescription(answer);
        await sendSignal("answer", buffered.from, buffered.callId, {
          sdp: answer.sdp,
          type: answer.type,
        });
        for (const c of pendingIceRef.current) {
          try { await pc.addIceCandidate(c); } catch {/* noop */}
        }
        pendingIceRef.current = [];
        pendingOfferRef.current = null;
      }

      await sendSignal("accept", call.fromUserId, call.callId, {});
      void supabase
        .from("call_intents")
        .update({ status: "accepted" })
        .eq("call_id", call.callId);

      setActive({
        callId: call.callId,
        peerUserId: call.fromUserId,
        peerKurdId: call.fromKurdId,
        peerName: call.fromName,
        peerAvatar: call.fromAvatar,
        video: call.video,
        outbound: false,
        startedAt: Date.now(),
      });
      startPhantomArmor();
      void hapticSuccess();
      return { ok: true };
    } catch (err) {
      await sendSignal("reject", call.fromUserId, call.callId, {
        reason: err instanceof Error ? err.message : "denied",
      });
      await teardown();
      return { ok: false, reason: err instanceof Error ? err.message : "Mikrofon erişimi reddedildi" };
    }
  }, [incoming, userId, getLocalMedia, buildPC, sendSignal, teardown]);

  const reject = useCallback(async () => {
    if (!incoming) return;
    await sendSignal("reject", incoming.fromUserId, incoming.callId, {});
    void supabase
      .from("call_intents")
      .update({ status: "rejected", ended_at: new Date().toISOString() })
      .eq("call_id", incoming.callId);
    setIncoming(null);
    void hapticTap();
  }, [incoming, sendSignal]);

  const hangup = useCallback(async () => {
    const peer = peerIdRef.current;
    const cid = callIdRef.current;
    if (peer && cid) {
      await sendSignal("hangup", peer, cid, {});
    }
    await teardown();
    void hapticTap();
  }, [sendSignal, teardown]);

  const toggleMute = useCallback(() => {
    const stream = localStreamRef.current;
    if (!stream) return;
    const next = !muted;
    stream.getAudioTracks().forEach((t) => (t.enabled = !next));
    setMuted(next);
    void hapticTap();
  }, [muted]);

  const toggleSpeaker = useCallback(() => {
    setSpeaker((v) => {
      const next = !v;
      // Best-effort real speaker switch: route call audio between
      // earpiece (false) and speakerphone (true) where supported.
      try {
        const audios = document.querySelectorAll<HTMLAudioElement>("audio");
        audios.forEach((el) => {
          const anyEl = el as HTMLAudioElement & { setSinkId?: (id: string) => Promise<void> };
          if (typeof anyEl.setSinkId === "function") {
            // "" = system default (earpiece on iOS), "default" = speaker
            anyEl.setSinkId(next ? "default" : "").catch(() => {/* noop */});
          }
          // Volume nudge so the change is perceptible even when sinkId is unsupported
          el.volume = next ? 1 : 0.85;
        });
      } catch {/* noop */}
      return next;
    });
    void hapticTap();
  }, []);

  const toggleVideo = useCallback(async () => {
    const stream = localStreamRef.current;
    if (!stream) return;
    const has = stream.getVideoTracks().length > 0;
    if (has) {
      stream.getVideoTracks().forEach((t) => {
        t.enabled = !t.enabled;
      });
      setVideoOn(stream.getVideoTracks()[0]?.enabled ?? false);
    } else {
      try {
        const v = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" } });
        v.getVideoTracks().forEach((t) => {
          stream.addTrack(t);
          pcRef.current?.addTrack(t, stream);
        });
        setVideoOn(true);
      } catch {/* noop */}
    }
    void hapticTap();
  }, []);

  /** Latest state mirrors so the realtime callback never closes over stale values. */
  const incomingRef = useRef<IncomingCall | null>(null);
  const activeRef = useRef<ActiveCall | null>(null);
  useEffect(() => { incomingRef.current = incoming; }, [incoming]);
  useEffect(() => { activeRef.current = active; }, [active]);

  /** Ringtone — start/stop with the inbound ringing state. */
  useEffect(() => {
    if (incoming) {
      startSovereignRingtone();
      return () => stopSovereignRingtone();
    }
    stopSovereignRingtone();
    return undefined;
  }, [incoming]);

  /** Wake Lock + silent AudioContext — keep the call alive while screen is
   *  off or the tab is backgrounded (Telegram-style). */
  useEffect(() => {
    if (active) {
      void acquireWakeLock();
      startCallKeepAlive();
      return () => {
        void releaseWakeLock();
        stopCallKeepAlive();
      };
    }
    return undefined;
  }, [active]);

  /** DTMF — send keypad tones over the active audio sender. */
  const sendDtmf = useCallback((tones: string) => {
    const pc = pcRef.current;
    if (!pc) return;
    const sender = pc.getSenders().find((s) => s.track?.kind === "audio");
    const dtmf = sender?.dtmf;
    if (dtmf) {
      try { dtmf.insertDTMF(tones, 160, 60); } catch {/* noop */}
    }
    void hapticTap();
  }, []);

  /** Mirror inbound calls (accepted, missed, rejected) into the local
   *  "Son Aramalar" widget feed so the widget updates in real-time. */
  const prevIncomingRef = useRef<IncomingCall | null>(null);
  useEffect(() => {
    const prev = prevIncomingRef.current;
    // An inbound call just disappeared — figure out why.
    if (prev && !incoming) {
      // Accepted → an active call now exists for the same callId.
      const nowActive = activeRef.current;
      if (nowActive && nowActive.callId === prev.callId && !nowActive.outbound) {
        if (prev.fromKurdId) {
          logLocalOutgoingCall(prev.fromKurdId, prev.video, "Gelen Arama");
        }
      } else {
        // Not picked up — log as missed.
        if (prev.fromKurdId) {
          logLocalOutgoingCall(prev.fromKurdId, prev.video, "Cevapsız Arama");
        }
      }
    }
    prevIncomingRef.current = incoming;
  }, [incoming]);

  /** ─── Realtime subscription: react to inbound signals ──────────── */
  useEffect(() => {
    if (!userId) return;

    const handleSignal = async (row: SignalRow) => {
      if (row.to_user !== userId) return;

      switch (row.kind) {
        case "ring": {
          if (incomingRef.current || activeRef.current) {
            await sendSignal("reject", row.from_user, row.call_id, { reason: "busy" });
            return;
          }
          const profile = await fetchProfile(row.from_user);
          setIncoming({
            callId: row.call_id,
            fromUserId: row.from_user,
            fromKurdId: profile?.kurd_id ?? null,
            fromName: profile?.display_name ?? null,
            fromAvatar: profile?.avatar_url ?? null,
            video: !!(row.payload as { video?: boolean }).video,
            ringingSince: Date.now(),
          });
          void hapticHeavy();
          break;
        }

        case "offer": {
          const sdp = (row.payload as { sdp?: string; type?: RTCSdpType }).sdp;
          const type = (row.payload as { sdp?: string; type?: RTCSdpType }).type;
          if (!sdp || !type) return;

          const pc = pcRef.current;
          // Callee path: PC may not exist yet (user hasn't tapped Accept).
          // Buffer the offer and let `accept()` consume it.
          if (!pc || callIdRef.current !== row.call_id) {
            pendingOfferRef.current = { sdp, type, from: row.from_user, callId: row.call_id };
            // Race: `offer` arrived before `ring` (rare). Synthesize an
            // incoming entry so the IncomingCallIsland still appears.
            if (!incomingRef.current && !activeRef.current) {
              const profile = await fetchProfile(row.from_user);
              setIncoming({
                callId: row.call_id,
                fromUserId: row.from_user,
                fromKurdId: profile?.kurd_id ?? null,
                fromName: profile?.display_name ?? null,
                fromAvatar: profile?.avatar_url ?? null,
                video: !!(row.payload as { video?: boolean }).video,
                ringingSince: Date.now(),
              });
              void hapticHeavy();
            }
            return;
          }
          await pc.setRemoteDescription({ type, sdp });
          const answer = await pc.createAnswer();
          await pc.setLocalDescription(answer);
          await sendSignal("answer", row.from_user, row.call_id, {
            sdp: answer.sdp,
            type: answer.type,
          });
          for (const c of pendingIceRef.current) {
            try { await pc.addIceCandidate(c); } catch {/* noop */}
          }
          pendingIceRef.current = [];
          break;
        }

        case "answer": {
          const pc = pcRef.current;
          if (!pc || callIdRef.current !== row.call_id) return;
          const sdp = (row.payload as { sdp?: string; type?: RTCSdpType }).sdp;
          const type = (row.payload as { sdp?: string; type?: RTCSdpType }).type;
          if (!sdp || !type) return;
          await pc.setRemoteDescription({ type, sdp });
          for (const c of pendingIceRef.current) {
            try { await pc.addIceCandidate(c); } catch {/* noop */}
          }
          pendingIceRef.current = [];
          void hapticSuccess();
          break;
        }

        case "ice": {
          const pc = pcRef.current;
          const cand = (row.payload as { candidate?: RTCIceCandidateInit }).candidate;
          if (!cand) return;
          if (pc?.remoteDescription) {
            try { await pc.addIceCandidate(cand); } catch {/* noop */}
          } else {
            pendingIceRef.current.push(cand);
          }
          break;
        }

        case "reject":
        case "hangup": {
          // Deng AI courtesy: if our outbound call was rejected because the
          // peer was busy, speak a sovereign voicemail-style line via the
          // browser's TTS so the caller knows immediately.
          if (
            row.kind === "reject" &&
            (row.payload as { reason?: string }).reason === "busy" &&
            activeRef.current?.callId === row.call_id &&
            activeRef.current?.outbound
          ) {
            try {
              const synth = window.speechSynthesis;
              if (synth) {
                const u = new SpeechSynthesisUtterance(
                  "Master is currently sovereign. Please leave a message.",
                );
                u.rate = 0.95;
                u.pitch = 0.95;
                u.volume = 1;
                synth.cancel();
                synth.speak(u);
              }
            } catch {/* noop */}
          }
          if (callIdRef.current === row.call_id) {
            await teardown();
          }
          if (incomingRef.current?.callId === row.call_id) {
            setIncoming(null);
          }
          break;
        }

        case "accept": {
          break;
        }
      }
    };

    const channelName = `phone-signals-${userId}-${Math.random().toString(36).slice(2, 8)}`;
    const channel = supabase
      .channel(channelName)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "phone_call_signals",
          filter: `to_user=eq.${userId}`,
        },
        (payload) => {
          void handleSignal(payload.new as SignalRow);
        },
      )
      .subscribe();

    return () => {
      void supabase.removeChannel(channel);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [userId]);

  /** Cleanup on unmount. */
  useEffect(() => {
    return () => {
      void teardown();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return useMemo(
    () => ({
      incoming,
      active,
      muted,
      speaker,
      videoOn,
      localStream,
      remoteStream,
      requestAudioAccess,
      placeCall,
      accept,
      reject,
      hangup,
      toggleMute,
      toggleSpeaker,
      toggleVideo,
      sendDtmf,
    }),
    [
      incoming, active, muted, speaker, videoOn, localStream, remoteStream,
      requestAudioAccess, placeCall, accept, reject, hangup, toggleMute, toggleSpeaker, toggleVideo, sendDtmf,
    ],
  );
}

export function SovereignPhoneProvider({ children }: { children: ReactNode }) {
  const api = useSovereignPhoneEngine();
  return <PhoneContext.Provider value={api}>{children}</PhoneContext.Provider>;
}

/**
 * Read the shared phone engine. Falls back to a no-op stub if used outside
 * the provider so that pages render gracefully (e.g. during Storybook /
 * isolated tests). In production the provider wraps the entire AppShell.
 */
export function useSovereignPhone(): PhoneApi {
  const ctx = useContext(PhoneContext);
  if (ctx) return ctx;
  return STUB_API;
}

const STUB_API: PhoneApi = {
  incoming: null,
  active: null,
  muted: false,
  speaker: true,
  videoOn: false,
  localStream: null,
  remoteStream: null,
  requestAudioAccess: async () => ({ ok: false, reason: "Telefon servisi başlatılmadı" }),
  placeCall: async () => ({ ok: false, reason: "Telefon servisi başlatılmadı" }),
  accept: async () => ({ ok: false, reason: "Telefon servisi başlatılmadı" }),
  reject: async () => {},
  hangup: async () => {},
  toggleMute: () => {},
  toggleSpeaker: () => {},
  toggleVideo: async () => {},
  sendDtmf: () => {},
};

