import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import type { MivankasCategory, MivankasListing } from "./useMivankas";

export interface SovereignProfileData {
  // Identity
  displayName: string;
  kurdId: string | null;
  isKycVerified: boolean;
  isConstitutionalSignatory: boolean;
  citizenSince: string | null;
  avatarUrl: string | null;
  username: string | null;
  city: string | null;
  bio: string | null;
  isOnline: boolean;

  // Sovereign Merit (replaces "Premium")
  isSovereignMerit: boolean;
  meritExpiresAt: string | null;

  // Reputation
  kekaScore: number;

  // Vault
  diravBalance: number;

  // Honor metrics
  livesTouched: number;
  honorSeals: number;
  guardianActs: number;

  // Operational
  serviceCount: number;
  unreadInbox: number;
  unreadNotifications: number;
  isAdmin: boolean;
}

export function useSovereignProfile(userId: string | undefined) {
  const [data, setData] = useState<SovereignProfileData | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!userId) {
      setData(null);
      setLoading(false);
      return;
    }
    setLoading(true);

    const [
      profileRes,
      balanceRes,
      sealsRes,
      guardianRes,
      livesRes,
      signRes,
      serviceRes,
      inboxRes,
      notifRes,
    ] = await Promise.all([
      supabase
        .from("profiles")
        .select(
          "display_name, kurd_id, is_verified, avatar_url, keka_points, created_at, username, city, bio, is_online, is_premium, premium_expires_at, role",
        )
        .eq("user_id", userId)
        .maybeSingle(),
      supabase.rpc("get_wallet_balance", { _user_id: userId }),
      supabase
        .from("mivankas_seals")
        .select("id, keka_points", { count: "exact" })
        .eq("receiver_id", userId)
        .gte("keka_points", 4),
      supabase
        .from("sos_evidence_files")
        .select("id", { count: "exact", head: true })
        .eq("user_id", userId),
      supabase
        .from("mivankas_bookings")
        .select("guest_id, host_id")
        .or(`host_id.eq.${userId},guest_id.eq.${userId}`)
        .in("status", ["completed", "active"]),
      supabase
        .from("constitution_signatures")
        .select("id", { count: "exact", head: true })
        .eq("user_id", userId),
      supabase
        .from("services")
        .select("id", { count: "exact", head: true })
        .eq("provider_id", userId),
      supabase
        .from("inbox_messages")
        .select("id", { count: "exact", head: true })
        .eq("recipient_id", userId)
        .eq("is_read", false),
      supabase
        .from("notifications")
        .select("id", { count: "exact", head: true })
        .eq("user_id", userId)
        .eq("is_read", false),
    ]);

    const profile = profileRes.data as
      | {
          display_name: string | null;
          kurd_id: string | null;
          is_verified: boolean | null;
          avatar_url: string | null;
          keka_points: number | null;
          created_at: string | null;
          username: string | null;
          city: string | null;
          bio: string | null;
          is_online: boolean | null;
          is_premium: boolean | null;
          premium_expires_at: string | null;
          role: string | null;
        }
      | null;

    const distinct = new Set<string>();
    (livesRes.data ?? []).forEach((b: { guest_id: string; host_id: string }) => {
      const other = b.guest_id === userId ? b.host_id : b.guest_id;
      if (other) distinct.add(other);
    });

    setData({
      displayName: profile?.display_name ?? "Egemen",
      kurdId: profile?.kurd_id ?? null,
      isKycVerified: !!profile?.is_verified,
      isConstitutionalSignatory: (signRes.count ?? 0) > 0,
      citizenSince: profile?.created_at ?? null,
      avatarUrl: profile?.avatar_url ?? null,
      username: profile?.username ?? null,
      city: profile?.city ?? null,
      bio: profile?.bio ?? null,
      isOnline: !!profile?.is_online,
      isSovereignMerit: !!profile?.is_premium,
      meritExpiresAt: profile?.premium_expires_at ?? null,
      kekaScore: profile?.keka_points ?? 0,
      diravBalance: Number(balanceRes.data ?? 0),
      livesTouched: distinct.size,
      honorSeals: sealsRes.count ?? 0,
      guardianActs: guardianRes.count ?? 0,
      serviceCount: serviceRes.count ?? 0,
      unreadInbox: inboxRes.count ?? 0,
      unreadNotifications: notifRes.count ?? 0,
      isAdmin: profile?.role === "admin",
    });
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Realtime — keka_points changes from sealing.
  // Per-instance nonce so multiple components calling this hook on the same
  // page (e.g. HubScreen + Settings) don't collide on the same channel name.
  useEffect(() => {
    if (!userId) return;
    const nonce = Math.random().toString(36).slice(2, 10);
    const ch = supabase
      .channel(`sovereign-profile-${userId}-${nonce}`)
      .on(
        "postgres_changes",
        { event: "UPDATE", schema: "public", table: "profiles", filter: `user_id=eq.${userId}` },
        () => refresh(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(ch);
    };
  }, [userId, refresh]);

  return { data, loading, refresh };
}

/**
 * "My Open Doors" — categorical listings I host.
 * Returns the latest listing per category so we can flip its is_active toggle.
 */
export function useMyOpenDoors(userId: string | undefined) {
  const [byCategory, setByCategory] = useState<Record<MivankasCategory, MivankasListing | null>>({
    ride: null,
    home: null,
    sofra: null,
    xezine: null,
  });
  const [xezineList, setXezineList] = useState<MivankasListing[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!userId) {
      setLoading(false);
      return;
    }
    setLoading(true);
    const { data } = await supabase
      .from("mivankas_listings")
      .select("*")
      .eq("host_id", userId)
      .order("created_at", { ascending: false });
    const rows = (data ?? []) as unknown as MivankasListing[];

    const byCat: Record<MivankasCategory, MivankasListing | null> = {
      ride: null,
      home: null,
      sofra: null,
      xezine: null,
    };
    rows.forEach((r) => {
      if (!byCat[r.category]) byCat[r.category] = r;
    });
    setByCategory(byCat);
    setXezineList(rows.filter((r) => r.category === "xezine"));
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const toggleActive = useCallback(
    async (listingId: string, next: boolean) => {
      const { error } = await supabase
        .from("mivankas_listings")
        .update({ is_active: next })
        .eq("id", listingId);
      if (error) {
        toast.error("Güncellenemedi: " + error.message);
        return false;
      }
      // Haptic
      if (typeof navigator !== "undefined" && "vibrate" in navigator) {
        try {
          (navigator as Navigator & { vibrate?: (n: number) => boolean }).vibrate?.(15);
        } catch {
          /* ignore */
        }
      }
      toast.success(next ? "Kapı açıldı" : "Kapı kapandı");
      await refresh();
      return true;
    },
    [refresh],
  );

  return { byCategory, xezineList, loading, refresh, toggleActive };
}

