import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { hashSeedPhrase } from "@/lib/sovereignCrypto";
import { toast } from "sonner";

export interface RecoveryRow {
  id: string;
  seed_hash: string;
  backup_email: string | null;
  backup_phone: string | null;
  is_verified: boolean;
  verified_at: string | null;
  created_at: string;
}

/** Manage the user's "Yaşam Anahtarı" (24-word seed) backup record. */
export function useSovereignRecovery() {
  const { user } = useAuth();
  const [row, setRow] = useState<RecoveryRow | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!user) {
      setRow(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    const { data } = await supabase
      .from("sovereign_recovery")
      .select("id, seed_hash, backup_email, backup_phone, is_verified, verified_at, created_at")
      .eq("user_id", user.id)
      .maybeSingle();
    setRow(data ?? null);
    setLoading(false);
  }, [user]);

  useEffect(() => { refresh(); }, [refresh]);

  /** Save a freshly generated phrase (only the hash is stored). */
  const savePhrase = useCallback(async (words: string[]): Promise<boolean> => {
    if (!user) {
      toast.error("Önce giriş yapın");
      return false;
    }
    const seed_hash = await hashSeedPhrase(words);
    const { error } = await supabase
      .from("sovereign_recovery")
      .upsert(
        { user_id: user.id, seed_hash, is_verified: true, verified_at: new Date().toISOString() },
        { onConflict: "user_id" },
      );
    if (error) {
      toast.error(error.message);
      return false;
    }
    toast.success("Yaşam Anahtarı güvenle kaydedildi");
    await refresh();
    return true;
  }, [user, refresh]);

  /** Update optional backup channels. */
  const updateBackup = useCallback(async (patch: { backup_email?: string | null; backup_phone?: string | null }) => {
    if (!user) return false;
    const { error } = await supabase
      .from("sovereign_recovery")
      .update(patch)
      .eq("user_id", user.id);
    if (error) {
      toast.error(error.message);
      return false;
    }
    toast.success("Yedek kanal güncellendi");
    await refresh();
    return true;
  }, [user, refresh]);

  /** Verify a phrase entered on a NEW device (used for revocation). */
  const verifyPhrase = useCallback(async (words: string[]): Promise<boolean> => {
    const seed_hash = await hashSeedPhrase(words);
    const { data, error } = await supabase.rpc("verify_recovery_phrase", { _seed_hash: seed_hash });
    if (error) {
      toast.error(error.message);
      return false;
    }
    return !!data;
  }, []);

  return { row, loading, refresh, savePhrase, updateBackup, verifyPhrase };
}

