import { useCallback, useEffect, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";

// ----- types
export interface PresencePoint {
  user_id: string;
  latitude: number;
  longitude: number;
  last_seen_at: string;
}

export interface Totem {
  id: string;
  creator_id: string;
  title: string;
  content: string;
  content_type: "message" | "dengbej" | "doctrine";
  media_url: string | null;
  latitude: number;
  longitude: number;
  unlock_radius_m: number;
  unlock_count: number;
  created_at: string;
}

export interface GovendSession {
  id: string;
  leader_id: string;
  title: string;
  bpm: number;
  is_active: boolean;
  participant_count: number;
  energy_level: number;
  started_at: string;
}

// ----- utils
function haversineMeters(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number,
): number {
  const R = 6371000;
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

// ----- core hook
export function useSovereignSpace() {
  const { user } = useAuth();
  const [coords, setCoords] = useState<{ lat: number; lng: number } | null>(
    null,
  );
  const [accuracy, setAccuracy] = useState<number | null>(null);
  const [presences, setPresences] = useState<PresencePoint[]>([]);
  const [totems, setTotems] = useState<Totem[]>([]);
  const [unlockedTotemIds, setUnlockedTotemIds] = useState<Set<string>>(
    new Set(),
  );
  const [activeGovend, setActiveGovend] = useState<GovendSession | null>(null);
  const [govendList, setGovendList] = useState<GovendSession[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [permission, setPermission] = useState<
    "prompt" | "granted" | "denied" | "unsupported"
  >("prompt");
  const [simulated, setSimulated] = useState(false);
  const watchIdRef = useRef<number | null>(null);

  // ------- geo watch
  useEffect(() => {
    if (typeof navigator === "undefined" || !navigator.geolocation) {
      setPermission("unsupported");
      return;
    }
    const id = navigator.geolocation.watchPosition(
      (pos) => {
        setPermission("granted");
        setCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        setAccuracy(pos.coords.accuracy);
      },
      (err) => {
        setError(err.message);
        if (err.code === err.PERMISSION_DENIED) setPermission("denied");
      },
      { enableHighAccuracy: true, maximumAge: 5000, timeout: 15000 },
    );
    watchIdRef.current = id;
    return () => {
      if (watchIdRef.current !== null)
        navigator.geolocation.clearWatch(watchIdRef.current);
    };
  }, []);

  // ------- push my presence every 20s while user + coords ready
  useEffect(() => {
    if (!user || !coords) return;
    let cancelled = false;
    const push = async () => {
      if (cancelled) return;
      await supabase.from("sovereign_presence").upsert(
        {
          user_id: user.id,
          latitude: coords.lat,
          longitude: coords.lng,
          accuracy: accuracy ?? undefined,
          is_active: true,
          last_seen_at: new Date().toISOString(),
        },
        { onConflict: "user_id" },
      );
    };
    push();
    const t = setInterval(push, 20000);
    return () => {
      cancelled = true;
      clearInterval(t);
      // Mark inactive on unmount
      supabase
        .from("sovereign_presence")
        .update({ is_active: false })
        .eq("user_id", user.id);
    };
  }, [user, coords, accuracy]);

  // ------- load nearby presences (poll + realtime)
  const fetchPresences = useCallback(async () => {
    const { data } = await supabase
      .from("sovereign_presence")
      .select("user_id, latitude, longitude, last_seen_at")
      .eq("is_active", true)
      .gte(
        "last_seen_at",
        new Date(Date.now() - 5 * 60 * 1000).toISOString(),
      );
    if (data) setPresences(data as PresencePoint[]);
  }, []);

  useEffect(() => {
    fetchPresences();
    const t = setInterval(fetchPresences, 15000);
    const ch = supabase
      .channel("sovereign_presence_rt")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "sovereign_presence" },
        fetchPresences,
      )
      .subscribe();
    return () => {
      clearInterval(t);
      supabase.removeChannel(ch);
    };
  }, [fetchPresences]);

  // ------- totems near coords
  const fetchTotems = useCallback(async () => {
    if (!coords) return;
    // simple bounding box ~ 5km
    const dLat = 0.045;
    const dLng = 0.045;
    const { data } = await supabase
      .from("sovereign_totems")
      .select("*")
      .gte("latitude", coords.lat - dLat)
      .lte("latitude", coords.lat + dLat)
      .gte("longitude", coords.lng - dLng)
      .lte("longitude", coords.lng + dLng)
      .eq("is_public", true)
      .order("created_at", { ascending: false })
      .limit(50);
    if (data) setTotems(data as Totem[]);
  }, [coords]);

  useEffect(() => {
    fetchTotems();
  }, [fetchTotems]);

  // ------- previous unlocks
  useEffect(() => {
    if (!user) return;
    supabase
      .from("sovereign_totem_unlocks")
      .select("totem_id")
      .eq("user_id", user.id)
      .then(({ data }) => {
        if (data)
          setUnlockedTotemIds(new Set(data.map((d: any) => d.totem_id)));
      });
  }, [user]);

  // ------- nearby (within 50m) — auto unlock
  const nearbyTotems = (
    coords
      ? totems
          .map((t) => ({
            t,
            d: haversineMeters(coords.lat, coords.lng, t.latitude, t.longitude),
          }))
          .filter(({ t, d }) => d <= t.unlock_radius_m)
      : []
  ) as { t: Totem; d: number }[];

  useEffect(() => {
    if (!user) return;
    nearbyTotems.forEach(({ t }) => {
      if (unlockedTotemIds.has(t.id) || t.creator_id === user.id) return;
      supabase
        .from("sovereign_totem_unlocks")
        .insert({ totem_id: t.id, user_id: user.id })
        .then(({ error }) => {
          if (!error) {
            setUnlockedTotemIds((s) => new Set(s).add(t.id));
          }
        });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nearbyTotems.length, user]);

  // ------- govend sessions
  const fetchGovend = useCallback(async () => {
    const { data } = await supabase
      .from("govend_sessions")
      .select("*")
      .eq("is_active", true)
      .order("started_at", { ascending: false })
      .limit(20);
    if (data) setGovendList(data as GovendSession[]);
  }, []);

  useEffect(() => {
    fetchGovend();
    const ch = supabase
      .channel("govend_rt")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "govend_sessions" },
        fetchGovend,
      )
      .subscribe();
    const t = setInterval(fetchGovend, 15000);
    return () => {
      clearInterval(t);
      supabase.removeChannel(ch);
    };
  }, [fetchGovend]);

  // ------- compose results
  const otherPresences = user
    ? presences.filter((p) => p.user_id !== user.id)
    : presences;

  const nearbyCount = coords
    ? otherPresences.filter(
        (p) =>
          haversineMeters(coords.lat, coords.lng, p.latitude, p.longitude) <
          200,
      ).length
    : 0;

  const baseCount = nearbyCount;
  const effectiveCount = simulated ? Math.max(baseCount, 7) : baseCount;
  const borderActive = effectiveCount >= 7;

  // ----- actions
  const dropTotem = useCallback(
    async (input: {
      title: string;
      content: string;
      content_type: Totem["content_type"];
    }) => {
      if (!user || !coords) throw new Error("no_location");
      const { data, error } = await supabase
        .from("sovereign_totems")
        .insert({
          creator_id: user.id,
          title: input.title,
          content: input.content,
          content_type: input.content_type,
          latitude: coords.lat,
          longitude: coords.lng,
          unlock_radius_m: 50,
          is_public: true,
        })
        .select("*")
        .maybeSingle();
      if (error) throw error;
      await fetchTotems();
      return data as Totem;
    },
    [user, coords, fetchTotems],
  );

  const startGovend = useCallback(
    async (bpm = 100, title = "Govend") => {
      if (!user) throw new Error("auth_required");
      const { data, error } = await supabase
        .from("govend_sessions")
        .insert({
          leader_id: user.id,
          title,
          bpm,
          is_active: true,
          participant_count: 1,
          latitude: coords?.lat,
          longitude: coords?.lng,
        })
        .select("*")
        .maybeSingle();
      if (error) throw error;
      await supabase
        .from("govend_participants")
        .insert({ session_id: (data as GovendSession).id, user_id: user.id });
      setActiveGovend(data as GovendSession);
      await fetchGovend();
      return data as GovendSession;
    },
    [user, coords, fetchGovend],
  );

  const joinGovend = useCallback(
    async (sessionId: string) => {
      if (!user) throw new Error("auth_required");
      await supabase
        .from("govend_participants")
        .upsert(
          { session_id: sessionId, user_id: user.id, left_at: null },
          { onConflict: "session_id,user_id" },
        );
      const found = govendList.find((g) => g.id === sessionId);
      if (found) setActiveGovend(found);
    },
    [user, govendList],
  );

  const leaveGovend = useCallback(async () => {
    if (!user || !activeGovend) return;
    await supabase
      .from("govend_participants")
      .update({ left_at: new Date().toISOString() })
      .eq("session_id", activeGovend.id)
      .eq("user_id", user.id);
    setActiveGovend(null);
  }, [user, activeGovend]);

  const stopGovend = useCallback(async () => {
    if (!user || !activeGovend || activeGovend.leader_id !== user.id) return;
    await supabase
      .from("govend_sessions")
      .update({ is_active: false, ended_at: new Date().toISOString() })
      .eq("id", activeGovend.id);
    setActiveGovend(null);
  }, [user, activeGovend]);

  const updateBpm = useCallback(
    async (bpm: number) => {
      if (!user || !activeGovend || activeGovend.leader_id !== user.id) return;
      const clamped = Math.max(40, Math.min(220, Math.round(bpm)));
      setActiveGovend({ ...activeGovend, bpm: clamped });
      await supabase
        .from("govend_sessions")
        .update({ bpm: clamped })
        .eq("id", activeGovend.id);
    },
    [user, activeGovend],
  );

  return {
    // state
    user,
    coords,
    accuracy,
    permission,
    error,
    presences: otherPresences,
    nearbyCount: effectiveCount,
    realNearbyCount: baseCount,
    borderActive,
    simulated,
    setSimulated,
    totems,
    unlockedTotemIds,
    nearbyTotems,
    govendList,
    activeGovend,
    // actions
    dropTotem,
    startGovend,
    joinGovend,
    leaveGovend,
    stopGovend,
    updateBpm,
  };
}

