/**
 * useStaffAccess — server-trusted check for whether the current user holds
 * any "staff" role that grants entry to the Executive Command Center
 * (Yürütme Komuta Merkezi).
 *
 * Roles considered staff:
 *   • admin               — full executive
 *   • moderator           — mod / hakem
 *   • field_representative — Nûner (district representative)
 *   • district_guardian   — Bekçi (guardian)
 *
 * Uses the SECURITY DEFINER `has_role` RPC so the decision cannot be
 * spoofed from the client. Falls back to a legacy profiles.role === 'admin'
 * check so existing admin accounts that pre-date the user_roles table
 * still get access.
 */
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export type StaffRole =
  | "admin"
  | "moderator"
  | "field_representative"
  | "district_guardian";

const STAFF_ROLES: StaffRole[] = [
  "admin",
  "moderator",
  "field_representative",
  "district_guardian",
];

export interface StaffAccess {
  loading: boolean;
  isStaff: boolean;
  isAdmin: boolean;
  /** All staff roles this user holds (subset of STAFF_ROLES). */
  roles: StaffRole[];
}

export function useStaffAccess(): StaffAccess {
  const { user, loading: authLoading } = useAuth();
  const [state, setState] = useState<StaffAccess>({
    loading: true,
    isStaff: false,
    isAdmin: false,
    roles: [],
  });

  useEffect(() => {
    if (authLoading) return;
    if (!user) {
      setState({ loading: false, isStaff: false, isAdmin: false, roles: [] });
      return;
    }

    let cancelled = false;
    (async () => {
      // Run all role checks in parallel via the SECURITY DEFINER RPC.
      const checks = await Promise.all(
        STAFF_ROLES.map(async (role) => {
          const { data, error } = await supabase.rpc("has_role", {
            _user_id: user.id,
            _role: role as never,
          });
          if (error) return { role, has: false };
          return { role, has: !!data };
        }),
      );

      const held = checks.filter((c) => c.has).map((c) => c.role);

      // Legacy fallback: profiles.role === 'admin'
      let legacyAdmin = false;
      if (held.length === 0) {
        const { data } = await supabase
          .from("profiles")
          .select("role")
          .eq("user_id", user.id)
          .maybeSingle();
        legacyAdmin = data?.role === "admin";
        if (legacyAdmin) held.push("admin");
      }

      if (cancelled) return;
      setState({
        loading: false,
        isStaff: held.length > 0,
        isAdmin: held.includes("admin"),
        roles: held,
      });
    })();

    return () => {
      cancelled = true;
    };
  }, [user, authLoading]);

  return state;
}

