import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface Story {
  id: string;
  user_id: string;
  media_url: string;
  media_type: string;
  caption: string | null;
  created_at: string;
  expires_at: string;
}

export interface StoryGroup {
  user_id: string;
  display_name: string;
  avatar_url: string | null;
  stories: Story[];
  hasUnviewed: boolean;
}

export function useStories(currentUserId: string | undefined) {
  const [storyGroups, setStoryGroups] = useState<StoryGroup[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchStories = useCallback(async () => {
    const { data: stories } = await supabase
      .from("stories")
      .select("*")
      .order("created_at", { ascending: true });

    if (!stories || stories.length === 0) {
      setStoryGroups([]);
      setLoading(false);
      return;
    }

    // Get unique user IDs
    const userIds = [...new Set(stories.map((s) => s.user_id))];
    const { data: profiles } = await supabase
      .from("profiles")
      .select("user_id, display_name, avatar_url")
      .in("user_id", userIds);

    // Get viewed story IDs for current user
    let viewedIds = new Set<string>();
    if (currentUserId) {
      const { data: views } = await supabase
        .from("story_views")
        .select("story_id")
        .eq("viewer_id", currentUserId);
      viewedIds = new Set((views ?? []).map((v) => v.story_id));
    }

    const profileMap = new Map(
      (profiles ?? []).map((p) => [p.user_id, p])
    );

    // Group by user
    const groupMap = new Map<string, StoryGroup>();
    for (const story of stories) {
      const profile = profileMap.get(story.user_id);
      if (!groupMap.has(story.user_id)) {
        groupMap.set(story.user_id, {
          user_id: story.user_id,
          display_name: profile?.display_name ?? "Kullanıcı",
          avatar_url: profile?.avatar_url ?? null,
          stories: [],
          hasUnviewed: false,
        });
      }
      const group = groupMap.get(story.user_id)!;
      group.stories.push(story);
      if (!viewedIds.has(story.id)) {
        group.hasUnviewed = true;
      }
    }

    // Put current user's stories first
    const groups = Array.from(groupMap.values());
    groups.sort((a, b) => {
      if (a.user_id === currentUserId) return -1;
      if (b.user_id === currentUserId) return 1;
      if (a.hasUnviewed && !b.hasUnviewed) return -1;
      if (!a.hasUnviewed && b.hasUnviewed) return 1;
      return 0;
    });

    setStoryGroups(groups);
    setLoading(false);
  }, [currentUserId]);

  useEffect(() => {
    fetchStories();

    const channel = supabase
      .channel("stories-realtime")
      .on("postgres_changes", { event: "*", schema: "public", table: "stories" }, () => {
        fetchStories();
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [fetchStories]);

  const createStory = useCallback(
    async (file: File, caption?: string) => {
      if (!currentUserId) return;

      const ext = file.name.split(".").pop() ?? "jpg";
      const path = `${currentUserId}/${Date.now()}.${ext}`;

      const { error: uploadError } = await supabase.storage
        .from("story-media")
        .upload(path, file);

      if (uploadError) throw uploadError;

      const { data: urlData } = supabase.storage
        .from("story-media")
        .getPublicUrl(path);

      const mediaType = file.type.startsWith("video") ? "video" : "image";

      const { error } = await supabase.from("stories").insert({
        user_id: currentUserId,
        media_url: urlData.publicUrl,
        media_type: mediaType,
        caption: caption || null,
      });

      if (error) throw error;
    },
    [currentUserId]
  );

  const markViewed = useCallback(
    async (storyId: string) => {
      if (!currentUserId) return;
      await supabase
        .from("story_views")
        .upsert(
          { story_id: storyId, viewer_id: currentUserId },
          { onConflict: "story_id,viewer_id" }
        );
    },
    [currentUserId]
  );

  return { storyGroups, loading, createStory, markViewed, refresh: fetchStories };
}

