/**
 * useStreamingText — Reveal a string one character at a time, ChatGPT style.
 *
 * Pure client hook (typewriter). Honours `prefers-reduced-motion` by jumping
 * straight to the full string. Re-streams whenever `text` changes.
 *
 * @param text   the final string
 * @param speed  characters per second (default 55)
 * @param start  when false, holds at empty until flipped (useful for in-view triggers)
 */
import { useEffect, useState } from "react";

export function useStreamingText(text: string, speed = 55, start = true): string {
  const [shown, setShown] = useState(() => {
    if (typeof window === "undefined") return text; // SSR: render full
    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    return reduced ? text : "";
  });

  useEffect(() => {
    if (!start) {
      setShown("");
      return;
    }
    if (typeof window === "undefined") {
      setShown(text);
      return;
    }
    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      setShown(text);
      return;
    }
    setShown("");
    if (!text) return;
    const interval = Math.max(8, Math.floor(1000 / speed));
    let i = 0;
    const id = setInterval(() => {
      i += 1;
      setShown(text.slice(0, i));
      if (i >= text.length) clearInterval(id);
    }, interval);
    return () => clearInterval(id);
  }, [text, speed, start]);

  return shown;
}

