import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface SuggestedCreator {
  user_id: string;
  display_name: string | null;
  avatar_url: string | null;
  kurd_id: string | null;
  follower_count: number;
  is_verified_creator: boolean | null;
  is_premium: boolean | null;
}

/**
 * Suggests top creators (by follower_count) excluding ones the current user
 * already follows and excluding the current user themselves.
 */
export function useSuggestedCreators(currentUserId?: string, limit = 12) {
  const [creators, setCreators] = useState<SuggestedCreator[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      // 1. Get list of users I already follow
      const followingIds = new Set<string>();
      if (currentUserId) {
        const { data: rels } = await supabase
          .from("follows")
          .select("following_id")
          .eq("follower_id", currentUserId);
        (rels || []).forEach((r: any) => followingIds.add(r.following_id));
        followingIds.add(currentUserId); // exclude self
      }

      // 2. Pull top creators by follower_count
      const { data: rows } = await supabase
        .from("profiles")
        .select(
          "user_id, display_name, avatar_url, kurd_id, follower_count, is_verified_creator, is_premium",
        )
        .order("follower_count", { ascending: false })
        .limit(limit + followingIds.size + 5);

      if (cancelled) return;
      const filtered = (rows || []).filter(
        (r: any) => !followingIds.has(r.user_id),
      );
      setCreators(filtered.slice(0, limit) as SuggestedCreator[]);
      setLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [currentUserId, limit]);

  return { creators, loading };
}

