/**
 * useSwipeDownBack — Telegram-style swipe-down-from-the-top gesture.
 *
 * Mirrors `useEdgeSwipeBack` but listens for a vertical drag that begins
 * within the top ~24px of the viewport (i.e. on/near the transparent
 * blurred header of a mini-app). When the user pulls ≥ 80px downward
 * with a mostly-vertical motion, we call `window.history.back()`.
 *
 * Mobile only (skipped on hover-capable pointers). Skips when the active
 * element is an input/textarea/select. Passive listeners — does not block
 * scrolling. Safe to mount globally.
 */
import { useEffect } from "react";

export function useSwipeDownBack() {
  useEffect(() => {
    if (typeof window === "undefined") return;
    if (window.matchMedia?.("(hover: hover)").matches) return; // desktop — skip

    let startX = 0;
    let startY = 0;
    let tracking = false;

    const onStart = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t) return;
      // Only trigger when the gesture starts in the top header strip.
      // env(safe-area-inset-top) is usually ≤ 47px on iPhones; 64px is a
      // safe header-height ceiling.
      if (t.clientY > 64) return;
      const tag = (e.target as HTMLElement | null)?.tagName?.toLowerCase();
      if (tag === "input" || tag === "textarea" || tag === "select") return;
      // Allow pages to opt-out (e.g. drag-handle on a chat list).
      const target = e.target as HTMLElement | null;
      if (target?.closest?.("[data-no-swipe-back]")) return;
      startX = t.clientX;
      startY = t.clientY;
      tracking = true;
    };

    const onEnd = (e: TouchEvent) => {
      if (!tracking) return;
      tracking = false;
      const t = e.changedTouches[0];
      if (!t) return;
      const dy = t.clientY - startY;
      const dx = Math.abs(t.clientX - startX);
      // Mostly vertical, ≥ 80px down.
      if (dy >= 80 && dx < 60) {
        try {
          window.history.back();
        } catch {}
      }
    };

    window.addEventListener("touchstart", onStart, { passive: true });
    window.addEventListener("touchend", onEnd, { passive: true });
    return () => {
      window.removeEventListener("touchstart", onStart);
      window.removeEventListener("touchend", onEnd);
    };
  }, []);
}

