import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

/**
 * Heartbeat-based "live viewers" counter.
 * - Upserts the current user's presence row every 25s.
 * - Counts users seen in the last 60s as currently watching.
 * - Reads count for everyone (no auth required).
 */
export function useTVPresence(targetId: string | null, userId: string | null) {
  const [count, setCount] = useState(0);

  // Heartbeat
  useEffect(() => {
    if (!targetId || !userId) return;
    let cancelled = false;
    const beat = async () => {
      if (cancelled) return;
      await supabase
        .from("tv_viewer_presence")
        .upsert(
          { user_id: userId, target_id: targetId, last_seen_at: new Date().toISOString() },
          { onConflict: "user_id,target_id" },
        );
    };
    beat();
    const t = setInterval(beat, 25_000);
    return () => {
      cancelled = true;
      clearInterval(t);
    };
  }, [targetId, userId]);

  // Polling counter (every 15s)
  useEffect(() => {
    if (!targetId) {
      setCount(0);
      return;
    }
    let cancelled = false;
    const tick = async () => {
      if (cancelled) return;
      const since = new Date(Date.now() - 60_000).toISOString();
      const { count: c } = await supabase
        .from("tv_viewer_presence")
        .select("*", { count: "exact", head: true })
        .eq("target_id", targetId)
        .gte("last_seen_at", since);
      if (!cancelled) setCount(c ?? 0);
    };
    tick();
    const t = setInterval(tick, 15_000);
    return () => {
      cancelled = true;
      clearInterval(t);
    };
  }, [targetId]);

  return count;
}

