/**
 * useTesbihBeatSync — #2 Tesbih Beat Sync.
 *
 * Müzik çalarken `getAmplitude()` (0..1) örneklenir, RMS eşiğini geçen her
 * "beat" anında:
 *   - haptic pulse (`navigator.vibrate`)
 *   - opsiyonel `onBeat()` callback (UI pulse / auto-tap)
 *
 * 8D / Manifesto track'leri için müziğin nabzı zikrin nabzı olur.
 */
import { useEffect, useRef } from "react";
import { useJiyanMusic } from "@/hooks/useJiyanMusic";

interface Opts {
  enabled: boolean;
  threshold?: number; // 0..1
  cooldownMs?: number;
  haptic?: boolean;
  onBeat?: () => void;
}

export function useTesbihBeatSync({
  enabled,
  threshold = 0.55,
  cooldownMs = 240,
  haptic = true,
  onBeat,
}: Opts) {
  const { isPlaying, getAmplitude } = useJiyanMusic();
  const rafRef = useRef<number | null>(null);
  const lastRef = useRef(0);

  useEffect(() => {
    if (!enabled || !isPlaying) return;
    const tick = (ts: number) => {
      rafRef.current = requestAnimationFrame(tick);
      const amp = getAmplitude();
      if (amp >= threshold && ts - lastRef.current > cooldownMs) {
        lastRef.current = ts;
        if (haptic && typeof navigator !== "undefined" && "vibrate" in navigator) {
          try {
            navigator.vibrate(Math.round(10 + amp * 25));
          } catch {
            /* ignore */
          }
        }
        onBeat?.();
      }
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    };
  }, [enabled, isPlaying, getAmplitude, threshold, cooldownMs, haptic, onBeat]);
}

