import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { generateTotpCode, generateTotpSecret, secondsRemainingInWindow } from "@/lib/sovereignCrypto";
import { toast } from "sonner";

export interface TotpRow {
  id: string;
  secret_base32: string;
  is_active: boolean;
  label: string;
  created_at: string;
  last_used_at: string | null;
}

/** Jiyan Authenticator — internal TOTP (RFC 6238). */
export function useTotp() {
  const { user } = useAuth();
  const [row, setRow] = useState<TotpRow | null>(null);
  const [loading, setLoading] = useState(true);
  const [code, setCode] = useState("------");
  const [remaining, setRemaining] = useState(30);

  const refresh = useCallback(async () => {
    if (!user) { setRow(null); setLoading(false); return; }
    setLoading(true);
    const { data } = await supabase
      .from("totp_secrets")
      .select("id, secret_base32, is_active, label, created_at, last_used_at")
      .eq("user_id", user.id)
      .maybeSingle();
    setRow(data ?? null);
    setLoading(false);
  }, [user]);

  useEffect(() => { refresh(); }, [refresh]);

  // 1-second tick to refresh the code + countdown.
  useEffect(() => {
    if (!row?.secret_base32 || !row.is_active) return;
    let cancelled = false;
    const tick = async () => {
      try {
        const next = await generateTotpCode(row.secret_base32);
        if (!cancelled) {
          setCode(next);
          setRemaining(secondsRemainingInWindow());
        }
      } catch {
        if (!cancelled) setCode("------");
      }
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => { cancelled = true; clearInterval(id); };
  }, [row?.secret_base32, row?.is_active]);

  const enable = useCallback(async (): Promise<boolean> => {
    if (!user) { toast.error("Önce giriş yapın"); return false; }
    const secret_base32 = generateTotpSecret();
    const { error } = await supabase
      .from("totp_secrets")
      .upsert(
        { user_id: user.id, secret_base32, is_active: true, label: "Jiyan Authenticator" },
        { onConflict: "user_id" },
      );
    if (error) { toast.error(error.message); return false; }
    toast.success("Jiyan Authenticator aktif");
    await refresh();
    return true;
  }, [user, refresh]);

  const disable = useCallback(async () => {
    if (!user || !row) return;
    const { error } = await supabase
      .from("totp_secrets")
      .update({ is_active: false })
      .eq("user_id", user.id);
    if (error) { toast.error(error.message); return; }
    toast.success("Jiyan Authenticator kapatıldı");
    await refresh();
  }, [user, row, refresh]);

  /** Validate a 6-digit code (used before high-security actions like DC transfers). */
  const validate = useCallback(async (entered: string): Promise<boolean> => {
    if (!row?.secret_base32 || !row.is_active) return false;
    // Allow ±1 step (30s clock skew tolerance)
    const now = Date.now();
    for (const offset of [-30_000, 0, 30_000]) {
      const expected = await generateTotpCode(row.secret_base32, now + offset);
      if (entered === expected) {
        await supabase.from("totp_secrets").update({ last_used_at: new Date().toISOString() }).eq("id", row.id);
        return true;
      }
    }
    return false;
  }, [row]);

  return { row, loading, code, remaining, enable, disable, validate, refresh };
}

