import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { getDeviceFingerprint, getDeviceLabel } from "@/lib/sovereignCrypto";
import { toast } from "sonner";

export interface DeviceRow {
  id: string;
  device_fingerprint: string;
  device_label: string;
  user_agent: string | null;
  is_revoked: boolean;
  approved_at: string | null;
  last_seen_at: string;
  created_at: string;
}

/** Soft device binding — register/refresh the current device, list & revoke others. */
export function useTrustedDevices() {
  const { user } = useAuth();
  const [devices, setDevices] = useState<DeviceRow[]>([]);
  const [currentFp, setCurrentFp] = useState<string>("");
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!user) { setDevices([]); setLoading(false); return; }
    setLoading(true);
    const { data } = await supabase
      .from("trusted_devices")
      .select("id, device_fingerprint, device_label, user_agent, is_revoked, approved_at, last_seen_at, created_at")
      .eq("user_id", user.id)
      .order("last_seen_at", { ascending: false });
    setDevices(data ?? []);
    setLoading(false);
  }, [user]);

  /** Call once after a successful login to record/refresh the device. */
  const registerCurrent = useCallback(async (): Promise<{ isNew: boolean }> => {
    if (!user) return { isNew: false };
    const fp = getDeviceFingerprint();
    setCurrentFp(fp);
    const { data: existing } = await supabase
      .from("trusted_devices")
      .select("id, approved_at")
      .eq("user_id", user.id)
      .eq("device_fingerprint", fp)
      .maybeSingle();
    if (existing) {
      await supabase
        .from("trusted_devices")
        .update({ last_seen_at: new Date().toISOString(), is_revoked: false })
        .eq("id", existing.id);
      return { isNew: !existing.approved_at };
    }
    await supabase.from("trusted_devices").insert({
      user_id: user.id,
      device_fingerprint: fp,
      device_label: getDeviceLabel(),
      user_agent: typeof navigator !== "undefined" ? navigator.userAgent : null,
      approved_at: new Date().toISOString(),
    });
    return { isNew: true };
  }, [user]);

  const revoke = useCallback(async (id: string) => {
    const { error } = await supabase
      .from("trusted_devices")
      .update({ is_revoked: true })
      .eq("id", id);
    if (error) { toast.error(error.message); return; }
    toast.success("Cihaz erişimi iptal edildi");
    await refresh();
  }, [refresh]);

  useEffect(() => {
    refresh();
    if (typeof window !== "undefined") setCurrentFp(getDeviceFingerprint());
  }, [refresh]);

  return { devices, loading, currentFp, refresh, registerCurrent, revoke };
}

