import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

export function useTwoFactor() {
  const { user } = useAuth();
  const [enabled, setEnabled] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!user) {
      setEnabled(false);
      setLoading(false);
      return;
    }

    let cancelled = false;

    (async () => {
      const { data } = await supabase
        .from("two_factor_settings")
        .select("is_enabled")
        .eq("user_id", user.id)
        .maybeSingle();

      if (!cancelled) {
        setEnabled(!!data?.is_enabled);
        setLoading(false);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [user]);

  const setTwoFactorEnabled = async (nextValue: boolean) => {
    if (!user) {
      toast.error("Önce giriş yapın");
      return false;
    }

    setSaving(true);

    const { error } = await supabase
      .from("two_factor_settings")
      .upsert({ user_id: user.id, is_enabled: nextValue, method: "inbox_otp" }, { onConflict: "user_id" });

    setSaving(false);

    if (error) {
      toast.error(error.message);
      return false;
    }

    setEnabled(nextValue);
    toast.success(nextValue ? "2FA aktifleştirildi" : "2FA kapatıldı");
    return true;
  };

  return { enabled, loading: loading || saving, setTwoFactorEnabled };
}

