import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

interface LedgerEntry {
  id: string;
  user_id: string;
  type: string;
  amount: number;
  description: string | null;
  stripe_session_id: string | null;
  reference_id: string | null;
  is_locked: boolean;
  created_at: string;
}

export function useWallet(userId: string | undefined) {
  const [balance, setBalance] = useState<number>(0);
  const [lockedBalance, setLockedBalance] = useState<number>(0);
  const [transactions, setTransactions] = useState<LedgerEntry[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchWallet = useCallback(async () => {
    if (!userId) {
      setLoading(false);
      return;
    }

    const [balanceRes, lockedRes, txRes] = await Promise.all([
      supabase.rpc("get_wallet_balance", { _user_id: userId }),
      supabase.rpc("get_locked_balance", { _user_id: userId }),
      supabase
        .from("wallet_ledger")
        .select("*")
        .eq("user_id", userId)
        .order("created_at", { ascending: false })
        .limit(50),
    ]);

    if (balanceRes.data !== null) setBalance(Number(balanceRes.data));
    if (lockedRes.data !== null) setLockedBalance(Number(lockedRes.data));
    if (txRes.data) setTransactions(txRes.data as unknown as LedgerEntry[]);
    setLoading(false);
  }, [userId]);

  useEffect(() => {
    fetchWallet();
  }, [fetchWallet]);

  return { balance, lockedBalance, transactions, loading, refetch: fetchWallet };
}

