import { useState, useEffect, useCallback } from "react";

type PermissionState = "default" | "granted" | "denied";

export function useWebNotifications() {
  const [permission, setPermission] = useState<PermissionState>("default");
  const supported = typeof window !== "undefined" && "Notification" in window;

  useEffect(() => {
    if (supported) {
      setPermission(Notification.permission as PermissionState);
    }
  }, [supported]);

  const requestPermission = useCallback(async () => {
    if (!supported) return "denied" as PermissionState;
    const result = await Notification.requestPermission();
    setPermission(result as PermissionState);
    return result as PermissionState;
  }, [supported]);

  const showNotification = useCallback(
    (title: string, options?: { body?: string; icon?: string; tag?: string; onClick?: () => void }) => {
      if (!supported || permission !== "granted") return;

      try {
        const notification = new Notification(title, {
          body: options?.body || undefined,
          icon: options?.icon || "/placeholder.svg",
          tag: options?.tag,
          badge: "/placeholder.svg",
          silent: false,
        });

        if (options?.onClick) {
          notification.onclick = () => {
            window.focus();
            options.onClick?.();
            notification.close();
          };
        }

        // Auto-close after 8 seconds
        setTimeout(() => notification.close(), 8000);
      } catch {
        // Fallback: some browsers don't support Notification constructor outside service workers
      }
    },
    [supported, permission]
  );

  return { supported, permission, requestPermission, showNotification };
}

