/**
 * useWidgetPreferences — Faz C.2: Hub Widget grid kullanıcı tercihleri.
 *
 * Kullanıcı Hub'ın widget sayfasında hangi widget'ların görüneceğini, sıra
 * ve boyutunu seçebilir. Veriler `user_widget_preferences` tablosunda
 * RLS-korumalı tutulur. Tablo boşken bütün widget'lar varsayılan olarak
 * görünür (back-compat); ilk add/remove ile kalıcı tercih başlar.
 */
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { HUB_APPS } from "@/lib/hubApps";

export type WidgetType =
  | "deng_latest"
  | "wallet_balance"
  | "phone_recent"
  | "kurd_id"
  | "news_top"
  | "weather"
  | "feed_latest"
  | "mail_inbox"
  | "linguist_progress"
  | "driving_exam"
  | "compass_clock"
  | "now_playing"
  | "ritual_next"
  | "ritual_amel"
  | "app_shortcut";

export type WidgetSize = "small" | "medium" | "large";

export interface WidgetPreference {
  id: string;
  widget_type: WidgetType;
  size: WidgetSize;
  position: number;
  config: Record<string, any>;
}

/** Catalog entry — `appId` set means this is a generic mini-app shortcut tile. */
export interface WidgetCatalogEntry {
  /** Unique key for the customize sheet. For app shortcuts → `app:<id>`. */
  key: string;
  type: WidgetType;
  label: string;
  emoji: string;
  /** When set, render via the generic AppShortcutCard with this app id. */
  appId?: string;
}

const RICH_WIDGETS: WidgetCatalogEntry[] = [
  { key: "deng_latest", type: "deng_latest", label: "Deng Bot", emoji: "🪐" },
  { key: "wallet_balance", type: "wallet_balance", label: "Hazine", emoji: "👑" },
  { key: "phone_recent", type: "phone_recent", label: "Son Aramalar", emoji: "📞" },
  { key: "kurd_id", type: "kurd_id", label: "Kurd-ID", emoji: "🆔" },
  { key: "news_top", type: "news_top", label: "Akış", emoji: "📰" },
  { key: "weather", type: "weather", label: "Hava", emoji: "☁️" },
  { key: "feed_latest", type: "feed_latest", label: "Topluluk", emoji: "✨" },
  { key: "mail_inbox", type: "mail_inbox", label: "E-posta", emoji: "✉️" },
  { key: "linguist_progress", type: "linguist_progress", label: "Linguist", emoji: "🎓" },
  { key: "driving_exam", type: "driving_exam", label: "Ehliyet", emoji: "🚗" },
  { key: "compass_clock", type: "compass_clock", label: "Pusula / Saat", emoji: "🧭" },
  { key: "now_playing", type: "now_playing", label: "Now Playing", emoji: "🎵" },
  { key: "ritual_next", type: "ritual_next", label: "Vakit", emoji: "🌙" },
  { key: "ritual_amel", type: "ritual_amel", label: "Amel Defteri", emoji: "📿" },
];

/** Mini-app shortcut catalog — every HUB app becomes a possible widget tile. */
const APP_SHORTCUT_WIDGETS: WidgetCatalogEntry[] = HUB_APPS.map((a) => ({
  key: `app:${a.id}`,
  type: "app_shortcut" as WidgetType,
  label: a.label,
  emoji: "▦",
  appId: a.id,
}));

/** Full catalog (rich widgets first, then mini-app shortcuts). */
export const ALL_WIDGETS: WidgetCatalogEntry[] = [
  ...RICH_WIDGETS,
  ...APP_SHORTCUT_WIDGETS,
];

/** Returns the catalog key for an installed pref (used to dedupe in the editor). */
export function prefCatalogKey(p: WidgetPreference): string {
  if (p.widget_type === "app_shortcut") {
    const appId = (p.config?.app_id as string) ?? "";
    return `app:${appId}`;
  }
  return p.widget_type;
}

export function useWidgetPreferences() {
  const { user } = useAuth();
  const [prefs, setPrefs] = useState<WidgetPreference[] | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchAll = useCallback(async () => {
    if (!user) {
      setPrefs(null);
      setLoading(false);
      return;
    }
    const { data } = await supabase
      .from("user_widget_preferences")
      .select("id, widget_type, size, position, config")
      .eq("user_id", user.id)
      .order("position", { ascending: true });
    setPrefs((data ?? []) as any);
    setLoading(false);
  }, [user]);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  const add = useCallback(
    async (
      type: WidgetType,
      size: WidgetSize = "medium",
      config: Record<string, any> = {},
    ) => {
      if (!user) return;
      const nextPos = prefs?.length ?? 0;
      const { error } = await supabase.from("user_widget_preferences").insert({
        user_id: user.id,
        widget_type: type,
        size,
        position: nextPos,
        config,
      });
      if (!error) await fetchAll();
    },
    [user, prefs, fetchAll],
  );

  /** Convenience: add a mini-app shortcut tile for a HUB app id. */
  const addAppShortcut = useCallback(
    async (appId: string, size: WidgetSize = "medium") => {
      await add("app_shortcut", size, { app_id: appId });
    },
    [add],
  );

  const remove = useCallback(
    async (id: string) => {
      const { error } = await supabase
        .from("user_widget_preferences")
        .delete()
        .eq("id", id);
      if (!error) await fetchAll();
    },
    [fetchAll],
  );

  /**
   * Reorder — optimistic update for instant drag-and-drop preview.
   * The local `prefs` state is reordered IMMEDIATELY so the underlying
   * UserWidgetGrid (visible behind the customize sheet) reflects the change
   * in real-time. DB writes happen in the background; on failure we re-fetch
   * to restore the truth.
   */
  const reorder = useCallback(
    async (orderedIds: string[]) => {
      if (!user || !prefs) return;
      // 1. Optimistic local reorder
      const byId = new Map(prefs.map((p) => [p.id, p]));
      const next = orderedIds
        .map((id, idx) => {
          const p = byId.get(id);
          return p ? { ...p, position: idx } : null;
        })
        .filter(Boolean) as WidgetPreference[];
      setPrefs(next);

      // 2. Persist (best-effort, no refetch on success — keeps optimistic state)
      try {
        const updates = orderedIds.map((id, idx) =>
          supabase
            .from("user_widget_preferences")
            .update({ position: idx })
            .eq("id", id),
        );
        const results = await Promise.all(updates);
        const failed = results.some((r) => r.error);
        if (failed) await fetchAll();
      } catch {
        await fetchAll();
      }
    },
    [user, prefs, fetchAll],
  );

  const setSize = useCallback(
    async (id: string, size: WidgetSize) => {
      const { error } = await supabase
        .from("user_widget_preferences")
        .update({ size })
        .eq("id", id);
      if (!error) await fetchAll();
    },
    [fetchAll],
  );

  /** Wipe ALL widget tiles for the current user. Optimistic — clears local
   *  state immediately so the Hub springboard reflects the change at once. */
  const clearAll = useCallback(async () => {
    if (!user) return;
    setPrefs([]);
    const { error } = await supabase
      .from("user_widget_preferences")
      .delete()
      .eq("user_id", user.id);
    if (error) await fetchAll();
  }, [user, fetchAll]);

  return { prefs, loading, add, addAppShortcut, remove, reorder, setSize, clearAll, refetch: fetchAll };
}

