/**
 * appLaunchOrigin — module-level "shared element" bridge between a tapped
 * Hub icon and the MiniAppOverlay that opens.
 *
 * Why not framer-motion `layoutId`? Hub icons and the overlay live in totally
 * different React subtrees (Hub is unmounted before overlay route mounts under
 * an Outlet), so a layoutId can't pair them across that gap. Instead, the icon
 * snapshots its bounding rect at tap-time, the overlay reads it on mount, and
 * we animate the overlay from that rect → fullscreen with a snappy spring.
 *
 * Flow:
 *   1. HubAppIcon.handleClick → setLaunchOrigin(appId, rect)
 *   2. Route changes → MiniAppOverlay mounts → consumeLaunchOrigin() returns
 *      the rect (and clears it). Overlay does the icon→fullscreen spring.
 *   3. User swipes down / dismisses → overlay reads `lastIconRectByApp` for
 *      the appId and animates fullscreen→that rect before unmounting.
 */
export interface LaunchOrigin {
  appId: string;
  rect: { x: number; y: number; width: number; height: number };
  ts: number;
}

let pending: LaunchOrigin | null = null;
const lastIconRectByApp = new Map<string, LaunchOrigin["rect"]>();

const STALE_MS = 1500;

export function setLaunchOrigin(appId: string, rect: DOMRect | LaunchOrigin["rect"]) {
  const r = "toJSON" in rect
    ? { x: rect.x, y: rect.y, width: rect.width, height: rect.height }
    : rect;
  pending = { appId, rect: r, ts: Date.now() };
  lastIconRectByApp.set(appId, r);
}

/** Read & clear the pending origin (for the opening animation). */
export function consumeLaunchOrigin(): LaunchOrigin | null {
  const p = pending;
  pending = null;
  if (!p) return null;
  if (Date.now() - p.ts > STALE_MS) return null;
  return p;
}

/** For the closing animation — best-effort, may be null if app was deep-linked. */
export function getIconRect(appId: string | null | undefined): LaunchOrigin["rect"] | null {
  if (!appId) return null;
  return lastIconRectByApp.get(appId) ?? null;
}

export function rememberIconRect(appId: string, rect: DOMRect | LaunchOrigin["rect"]) {
  const r = "toJSON" in rect
    ? { x: rect.x, y: rect.y, width: rect.width, height: rect.height }
    : rect;
  lastIconRectByApp.set(appId, r);
}

