/**
 * callBackground — User preferences for in-call dynamic backgrounds (Pollinations.ai).
 *
 * Persisted to localStorage. Two toggles:
 *   • enabled       — show/hide Pollinations BG behind the call
 *   • lowDataMode   — if true, fetch a smaller (512×768) image and skip auto-refresh
 *
 * Pollinations.ai is a free, no-auth image API: https://pollinations.ai/p/<prompt>
 * We craft a Sovereign-themed prompt and use the user's name as a seed.
 */
import { useSyncExternalStore } from "react";

const KEY = "jiyan.callbg.v1";

export interface CallBgPrefs {
  enabled: boolean;
  lowDataMode: boolean;
}

const DEFAULTS: CallBgPrefs = { enabled: true, lowDataMode: false };

let state: CallBgPrefs = load();
const listeners = new Set<() => void>();

function load(): CallBgPrefs {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return DEFAULTS;
    const parsed = JSON.parse(raw);
    return { ...DEFAULTS, ...parsed };
  } catch {
    return DEFAULTS;
  }
}

function save() {
  try { localStorage.setItem(KEY, JSON.stringify(state)); } catch {/* noop */}
  listeners.forEach((l) => l());
}

export function getCallBgPrefs(): CallBgPrefs { return state; }
export function setCallBgEnabled(v: boolean) { state = { ...state, enabled: v }; save(); }
export function setCallBgLowData(v: boolean) { state = { ...state, lowDataMode: v }; save(); }

export function useCallBgPrefs(): CallBgPrefs {
  return useSyncExternalStore(
    (cb) => { listeners.add(cb); return () => listeners.delete(cb); },
    () => state,
    () => DEFAULTS,
  );
}

/** Build a Pollinations.ai URL for a Sovereign-themed in-call backdrop. */
export function buildPollinationsBg(opts: {
  seed: string;
  lowData: boolean;
  prompt?: string;
}): string {
  const w = opts.lowData ? 512 : 1024;
  const h = opts.lowData ? 768 : 1536;
  const prompt = encodeURIComponent(
    opts.prompt ??
      "sovereign luxury dark gold black abstract aurora kurdistan mountains, cinematic, 8k, ultra detailed",
  );
  const seed = encodeURIComponent(opts.seed.slice(0, 32) || "sovereign");
  return `https://image.pollinations.ai/prompt/${prompt}?width=${w}&height=${h}&seed=${seed}&nologo=true&model=flux`;
}

