/**
 * callMinimize — tiny external store for "is the active call minimized?"
 *
 * Telegram-style: aşağı sürükle → SovereignCallScreen küçülür, FloatingActiveCallPill
 * üstte kalır. Pill'e dokun → tekrar büyütür. Hangup yalnızca kırmızı butonla.
 *
 * Module-level state + useSyncExternalStore — context yeniden render gerektirmez.
 */
import { useSyncExternalStore } from "react";

let minimized = false;
const listeners = new Set<() => void>();

function emit() {
  for (const l of listeners) l();
}

export function minimizeCall() {
  if (minimized) return;
  minimized = true;
  emit();
}

export function expandCall() {
  if (!minimized) return;
  minimized = false;
  emit();
}

export function resetCallMinimize() {
  if (!minimized) return;
  minimized = false;
  emit();
}

export function useCallMinimized(): boolean {
  return useSyncExternalStore(
    (cb) => {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    () => minimized,
    () => false,
  );
}

