/**
 * Egemen Card share token.
 *
 * The QR encodes a base64url JSON payload + a checksum derived from a public
 * salt. This is NOT a cryptographic auth token — it is a tamper-evident,
 * self-contained pointer to a profile so the receiving device can:
 *   - open the correct /profile?e=… URL
 *   - render basic identity (name, +777, KEKA) instantly while the live
 *     record loads, even if the scanner is not logged in
 *   - reject obvious tampering (mismatched checksum)
 *
 * No additional login step is required for the scanner: the public profile
 * route reads the payload and routes to the right user view.
 */

const SALT = "EGEMEN-V1-JIYAN-WORLD-2026"; // public, version-pinned salt

export interface EgemenPayload {
  /** profile handle / username (preferred) or user id */
  u: string;
  /** display name */
  n: string;
  /** +777 Kurd-ID, optional */
  k?: string | null;
  /** KEKA reputation score */
  s: number;
  /** issued-at timestamp (ms) */
  t: number;
  /** version */
  v: 1;
}

/* ── base64url helpers (URL-safe, no padding) ── */

function toBase64Url(input: string): string {
  if (typeof window === "undefined") {
    return Buffer.from(input, "utf8").toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }
  const bytes = new TextEncoder().encode(input);
  let bin = "";
  bytes.forEach((b) => (bin += String.fromCharCode(b)));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromBase64Url(input: string): string {
  const padded = input.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((input.length + 3) % 4);
  if (typeof window === "undefined") {
    return Buffer.from(padded, "base64").toString("utf8");
  }
  const bin = atob(padded);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}

/* ── tiny non-crypto hash (FNV-1a 32-bit) — good enough as a tamper checksum ── */

function fnv1a(str: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = (hash + ((hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24))) >>> 0;
  }
  return hash.toString(36).padStart(7, "0");
}

function sign(payloadJson: string): string {
  return fnv1a(`${SALT}|${payloadJson}`);
}

/** Encode payload → URL-safe `data.sig` token. */
export function encodeEgemenToken(payload: Omit<EgemenPayload, "v" | "t"> & { t?: number }): string {
  const full: EgemenPayload = { v: 1, t: payload.t ?? Date.now(), ...payload };
  const json = JSON.stringify(full);
  const data = toBase64Url(json);
  const sig = sign(json);
  return `${data}.${sig}`;
}

/** Decode token. Returns null if malformed or checksum mismatched. */
export function decodeEgemenToken(token: string | null | undefined): EgemenPayload | null {
  if (!token || typeof token !== "string" || !token.includes(".")) return null;
  try {
    const [data, sig] = token.split(".");
    if (!data || !sig) return null;
    const json = fromBase64Url(data);
    if (sign(json) !== sig) return null;
    const parsed = JSON.parse(json) as EgemenPayload;
    if (parsed.v !== 1 || typeof parsed.u !== "string") return null;
    return parsed;
  } catch {
    return null;
  }
}

/** Build a full shareable URL that opens the correct profile view. */
export function buildEgemenShareUrl(origin: string, payload: Parameters<typeof encodeEgemenToken>[0]): string {
  const token = encodeEgemenToken(payload);
  return `${origin}/profile?e=${token}`;
}

