/**
 * flowLock — global "busy flow" gate.
 *
 * When the user is mid-conversation in /chat or mid-booking flow (mivankas
 * checkout, marketplace order confirm, etc.) we lock destructive UI
 * gestures: jiggle-mode entry, icon reorder, dock reorder, swipe-back.
 *
 * Pages call `useFlowLock(true)` while a sensitive flow is active. Anywhere
 * else can synchronously read `isFlowLocked()` to short-circuit gestures.
 */
import { useEffect } from "react";

const ATTR = "data-flow-busy";

export function isFlowLocked(): boolean {
  if (typeof document === "undefined") return false;
  return document.documentElement.getAttribute(ATTR) === "1";
}

export function useFlowLock(active: boolean) {
  useEffect(() => {
    if (typeof document === "undefined") return;
    if (!active) return;
    const root = document.documentElement;
    const prev = root.getAttribute(ATTR);
    root.setAttribute(ATTR, "1");
    return () => {
      if (prev == null) root.removeAttribute(ATTR);
      else root.setAttribute(ATTR, prev);
    };
  }, [active]);
}

