/**
 * Handle/username display helpers.
 *
 * Old accounts (pre Egemen-handle) auto-generated usernames by stripping the
 * `@` and `.` from the user's email (e.g. `john@gmail.com` → `johngmailcom`).
 * Those strings are ugly and leak provider names. We detect them and fall
 * back to a Sovereign-friendly identifier (display_name or +777 Kurd-ID).
 */

// Catches both full email-derived handles (`miqomilanoicloudcom`) and
// truncated ones (`sarezaozdemirligmail`, `halilvedatgultekingm`,
// `devrimarslanx1221gma`).
//
// Strategy: we anchor on the END of the string and check for either:
//   • a full provider name (gmail, icloud, hotmail, …) optionally followed
//     by a partial TLD (`com`, `co`, `c`); or
//   • a truncated gmail prefix (`gm`, `gma`, `gmai`) at the very end.
const EMAIL_PROVIDER_TAIL =
  /(gmail|googlemail|icloud|hotmail|outlook|live|yahoo|ymail|proton|protonmail|gmx|web|aol|yandex|mailru|qq|163|me)(com|co|c)?$|(gmai|gma|gm)$/i;

/**
 * Returns true if the username looks like an auto-generated email-derived
 * handle (e.g. ends with `gmail`, `gmailco`, `gmailcom`, `icloudcom`, or a
 * truncated `gm`/`gma`/`gmai` tail).
 */
export function isEmailDerivedUsername(username: string | null | undefined): boolean {
  if (!username) return false;
  const u = username.trim().toLowerCase();
  if (!u) return false;
  // Need a real "name part" before the tail; reject very short handles outright.
  if (u.length < 8) return false;
  return EMAIL_PROVIDER_TAIL.test(u);
}

/**
 * Resolve a clean display handle for a user. Priority:
 *   1. clean username  → "@handle"
 *   2. kurd_id         → "+777 1234 5678"
 *   3. display_name
 *   4. fallback "Sovereign"
 */
export function resolveHandle(opts: {
  username?: string | null;
  kurd_id?: string | null;
  display_name?: string | null;
}): string {
  const { username, kurd_id, display_name } = opts;
  if (username && !isEmailDerivedUsername(username)) {
    return `@${username}`;
  }
  if (kurd_id && kurd_id.trim()) return kurd_id;
  if (display_name && display_name.trim()) return display_name;
  return "Sovereign";
}

