/**
 * hicriCalendar — Gregorian ↔ Hijri converter (no external API, fully offline).
 *
 * Uses the well-known Kuwaiti algorithm (accurate to ±1 day for civil dates).
 * Source: https://en.wikipedia.org/wiki/Tabular_Islamic_calendar
 */

const HIJRI_MONTHS_TR = [
  "Muharrem","Safer","Rebîülevvel","Rebîülâhir","Cemâziyelevvel","Cemâziyelâhir",
  "Recep","Şaban","Ramazan","Şevval","Zilkâde","Zilhicce",
];

export function gregorianToHijri(date: Date): { day: number; month: number; year: number; label: string } {
  const day = date.getDate();
  const month = date.getMonth() + 1;
  const year = date.getFullYear();

  const jd = Math.floor((1461 * (year + 4800 + Math.floor((month - 14) / 12))) / 4)
    + Math.floor((367 * (month - 2 - 12 * Math.floor((month - 14) / 12))) / 12)
    - Math.floor((3 * Math.floor((year + 4900 + Math.floor((month - 14) / 12)) / 100)) / 4)
    + day - 32075;

  const l = jd - 1948440 + 10632;
  const n = Math.floor((l - 1) / 10631);
  const l2 = l - 10631 * n + 354;
  const j = Math.floor((10985 - l2) / 5316) * Math.floor((50 * l2) / 17719)
    + Math.floor(l2 / 5670) * Math.floor((43 * l2) / 15238);
  const l3 = l2 - Math.floor((30 - j) / 15) * Math.floor((17719 * j) / 50)
    - Math.floor(j / 16) * Math.floor((15238 * j) / 43) + 29;
  const hMonth = Math.floor((24 * l3) / 709);
  const hDay = l3 - Math.floor((709 * hMonth) / 24);
  const hYear = 30 * n + j - 30;

  return {
    day: hDay,
    month: hMonth,
    year: hYear,
    label: `${hDay} ${HIJRI_MONTHS_TR[hMonth - 1]} ${hYear}`,
  };
}

export function hijriToGregorian(hYear: number, hMonth: number, hDay: number): Date {
  const jd = Math.floor((11 * hYear + 3) / 30)
    + 354 * hYear + 30 * hMonth - Math.floor((hMonth - 1) / 2) + hDay + 1948440 - 385;
  // Convert JD back to Gregorian
  let l = jd + 68569;
  const n = Math.floor((4 * l) / 146097);
  l = l - Math.floor((146097 * n + 3) / 4);
  const i = Math.floor((4000 * (l + 1)) / 1461001);
  l = l - Math.floor((1461 * i) / 4) + 31;
  const j = Math.floor((80 * l) / 2447);
  const day = l - Math.floor((2447 * j) / 80);
  l = Math.floor(j / 11);
  const month = j + 2 - 12 * l;
  const year = 100 * (n - 49) + i + l;
  return new Date(year, month - 1, day);
}

/** Zekat formula — gold nisab method. */
export function calculateZekat(input: {
  cashEUR: number;
  goldGrams: number;
  silverGrams: number;
  receivables: number;
  debts: number;
  goldPriceEURPerGram: number;
}): { wealth: number; nisab: number; zekat: number; obligated: boolean } {
  const wealth = input.cashEUR
    + input.goldGrams * input.goldPriceEURPerGram
    + input.silverGrams * (input.goldPriceEURPerGram / 60) // rough silver ratio
    + input.receivables
    - input.debts;
  // Nisab = 85g gold (Hanafi/Şafi consensus)
  const nisab = 85 * input.goldPriceEURPerGram;
  const obligated = wealth >= nisab;
  const zekat = obligated ? wealth * 0.025 : 0;
  return { wealth, nisab, zekat, obligated };
}

