/** Eski bir id'yi yeni id'ye çevirir; bilinmezse aynı id'yi döner. */
export function resolveAppId(id: string): string {
  return LEGACY_APP_ID_ALIASES[id] ?? id;
}

/** Reverse lookup: route path → appId. Used by overlay to find icon for the
 *  shrink-back-to-icon close animation when the user deep-links into an app. */
export function appIdFromPath(pathname: string): string | null {
  // Match the longest `to` prefix so /chat/123 still maps to "deng" (to:/chat).
  let best: { id: string; len: number } | null = null;
  for (const a of HUB_APPS) {
    if (pathname === a.to || pathname.startsWith(a.to + "/")) {
      if (!best || a.to.length > best.len) best = { id: a.id, len: a.to.length };
    }
  }
  return best?.id ?? null;
}

