/**
 * keepCallAlive — Silent AudioContext oscillator that prevents browser
 * throttling / background tab suspension during an active call. iOS Safari
 * and Chrome aggressively throttle WebRTC + setInterval when the tab is
 * hidden; a tiny inaudible tone keeps the audio graph "in use" and the
 * RTCPeerConnection alive while the user browses other Sovereign apps.
 */
let ctx: AudioContext | null = null;
let osc: OscillatorNode | null = null;
let gain: GainNode | null = null;

export function startCallKeepAlive() {
  if (typeof window === "undefined") return;
  try {
    if (ctx) return;
    const Ctor = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return;
    ctx = new Ctor();
    osc = ctx.createOscillator();
    gain = ctx.createGain();
    gain.gain.value = 0.00001; // effectively silent
    osc.frequency.value = 20;  // sub-audible
    osc.connect(gain).connect(ctx.destination);
    osc.start();
    void ctx.resume();
  } catch {/* noop */}
}

export function stopCallKeepAlive() {
  try { osc?.stop(); } catch {/* noop */}
  try { osc?.disconnect(); } catch {/* noop */}
  try { gain?.disconnect(); } catch {/* noop */}
  try { void ctx?.close(); } catch {/* noop */}
  ctx = null; osc = null; gain = null;
}

