/**
 * Lighthouse.storage uploader (Filecoin/IPFS) — Sovereign media layer for Jiyan OS.
 *
 * Tüm medya (avatar, story, video) IPFS'e yüklenir. Görüntüleme için
 * Cloudflare → Pinata → Lighthouse sırasıyla yüksek hızlı gateway'ler kullanılır
 * (unblockable / hızlı erişim).
 */

export interface LighthouseUploadResult {
  cid: string;
  url: string;          // primary gateway (Cloudflare)
  gateways: string[];   // fallback chain
  size: number;
  name: string;
}

// 200MB upper bound (videos). Server enforces the same cap.
const MAX_BYTES = 200 * 1024 * 1024;

/**
 * High-speed public IPFS gateways. First one wins; client may fall back
 * to the next if a load fails.
 */
export function ipfsGateways(cid: string): string[] {
  return [
    `https://cloudflare-ipfs.com/ipfs/${cid}`,
    `https://gateway.pinata.cloud/ipfs/${cid}`,
    `https://${cid}.ipfs.dweb.link`,
    `https://gateway.lighthouse.storage/ipfs/${cid}`,
  ];
}

/** Primary gateway URL (Cloudflare — fastest globally). */
export function ipfsUrl(cid: string): string {
  return ipfsGateways(cid)[0];
}

export async function uploadToLighthouse(file: File): Promise<LighthouseUploadResult> {
  if (file.size > MAX_BYTES) {
    throw new Error(`File too large: ${(file.size / 1024 / 1024).toFixed(1)}MB (max 200MB)`);
  }
  const fd = new FormData();
  fd.append("file", file);
  const resp = await fetch("/api/public/lighthouse-upload", {
    method: "POST",
    body: fd,
  });
  if (!resp.ok) {
    const txt = await resp.text();
    throw new Error(`Lighthouse upload failed (${resp.status}): ${txt}`);
  }
  const data = (await resp.json()) as { cid: string; size: number; name: string };
  return {
    cid: data.cid,
    url: ipfsUrl(data.cid),
    gateways: ipfsGateways(data.cid),
    size: data.size,
    name: data.name,
  };
}

/**
 * <IPFSImage> / <IPFSVideo> helper: tries gateways in order until one loads.
 * Use as the `src` strategy for img/video tags.
 */
export function resolveIpfs(cidOrUrl: string): string {
  // Already a full URL → return as-is
  if (cidOrUrl.startsWith("http")) return cidOrUrl;
  // Bare CID → primary gateway
  return ipfsUrl(cidOrUrl);
}

/**
 * Publish a small JSON payload (e.g. an encrypted Sovereign Phone Call Intent)
 * to Lighthouse / Filecoin. Returns the CID (acts as the on-chain anchor for
 * the handshake; real-time delivery still rides Supabase Realtime for sub-200ms
 * ringing). Best-effort — never throws into the call flow.
 */
export async function publishIntentToLighthouse(
  payload: Record<string, unknown>,
  name = "jiyan-call-intent.json",
): Promise<{ cid: string; url: string } | null> {
  try {
    const blob = new Blob([JSON.stringify(payload)], { type: "application/json" });
    const file = new File([blob], name, { type: "application/json" });
    const res = await uploadToLighthouse(file);
    return { cid: res.cid, url: res.url };
  } catch (err) {
    console.warn("[lighthouse] intent publish failed", err);
    return null;
  }
}

