// Lightweight WebAudio feedback tones — no external assets
let ctx: AudioContext | null = null;

function getCtx(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (!ctx) {
    const Ctor = (window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext);
    if (!Ctor) return null;
    ctx = new Ctor();
  }
  return ctx;
}

function tone(freq: number, duration: number, type: OscillatorType = "sine", gain = 0.18, when = 0) {
  const c = getCtx();
  if (!c) return;
  const osc = c.createOscillator();
  const g = c.createGain();
  osc.type = type;
  osc.frequency.value = freq;
  g.gain.setValueAtTime(0, c.currentTime + when);
  g.gain.linearRampToValueAtTime(gain, c.currentTime + when + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0001, c.currentTime + when + duration);
  osc.connect(g).connect(c.destination);
  osc.start(c.currentTime + when);
  osc.stop(c.currentTime + when + duration);
}

export const linguistSounds = {
  mastered: () => {
    tone(659.25, 0.12, "sine", 0.18); // E5
    tone(987.77, 0.18, "sine", 0.16, 0.1); // B5
  },
  review: () => {
    tone(329.63, 0.18, "triangle", 0.14); // E4
  },
  flip: () => {
    tone(880, 0.05, "sine", 0.08); // A5 click
  },
  goalReached: () => {
    tone(523.25, 0.12, "sine", 0.2); // C5
    tone(659.25, 0.12, "sine", 0.2, 0.12); // E5
    tone(783.99, 0.18, "sine", 0.2, 0.24); // G5
    tone(1046.5, 0.3, "sine", 0.2, 0.36); // C6
  },
  speak: (text: string, lang = "nl-NL") => {
    if (typeof window === "undefined" || !("speechSynthesis" in window)) return;
    const u = new SpeechSynthesisUtterance(text);
    u.lang = lang;
    u.rate = 0.9;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(u);
  },
};

