  doc.setTextColor(212, 175, 55);
  doc.setFont("helvetica", "bold");
  doc.text("Certificate of Achievement", w / 2, 60, { align: "center" });

  // Body
  doc.setFontSize(12);
  doc.setTextColor(220, 220, 220);
  doc.setFont("helvetica", "normal");
  doc.text("This certifies that", w / 2, 78, { align: "center" });

  doc.setFont("helvetica", "bold");
  doc.setFontSize(28);
  doc.setTextColor(255, 255, 255);
  doc.text(data.recipientName, w / 2, 92, { align: "center" });

  if (data.kurdId) {
    doc.setFontSize(10);
    doc.setTextColor(212, 175, 55);
    doc.setFont("helvetica", "normal");
    doc.text(`KurdID: ${data.kurdId}`, w / 2, 100, { align: "center" });
