  doc.setFontSize(12);
  doc.setTextColor(220, 220, 220);
  doc.text("has successfully completed the level", w / 2, 112, { align: "center" });

  doc.setFont("helvetica", "bold");
  doc.setFontSize(20);
  doc.setTextColor(212, 175, 55);
  doc.text(`${data.language.toUpperCase()} — ${data.level}`, w / 2, 124, { align: "center" });

  doc.setFont("helvetica", "normal");
  doc.setFontSize(11);
  doc.setTextColor(180, 180, 180);
  doc.text(
    "in accordance with the WKO Digital Constitution and the WKO Linguist standard.",
    w / 2,
