  // Footer — date + certificate no
  doc.setFontSize(10);
  doc.setTextColor(155, 89, 182);
  doc.text(`Issued: ${data.issuedAt.toLocaleDateString("en-GB")}`, 30, h - 30);
  doc.text(`Certificate No: ${data.certificateNo}`, w - 30, h - 30, { align: "right" });

