/**
 * musicSources — 100% free, decentralized music data layer.
 *
 * Sources:
 *   • Audius     — sovereign, decentralized streaming network (primary)
 *   • Piped      — privacy YouTube proxy (audio fallback)
 *   • LRCLIB     — synced lyrics (LRC format)
 *
 * No API keys. CORS-friendly. Returns objects compatible with MusicTrack
 * shape used by useJiyanMusic so they can be passed into `play(track)`.
 */
import type { MusicTrack } from "@/hooks/useJiyanMusic";

const AUDIUS_DISCOVERY = "https://api.audius.co";
const PIPED_HOSTS = [
  "https://pipedapi.kavin.rocks",
  "https://pipedapi.adminforge.de",
  "https://pipedapi.leptons.xyz",
];
const LRCLIB = "https://lrclib.net/api";
const APP_NAME = "jiyan";

let _audiusHost: string | null = null;
async function audiusHost(): Promise<string> {
  if (_audiusHost) return _audiusHost;
  try {
    const r = await fetch(AUDIUS_DISCOVERY);
    const j = await r.json();
    const host = (j?.data ?? [])[Math.floor(Math.random() * (j?.data?.length || 1))];
    if (host) {
      _audiusHost = host as string;
      return _audiusHost;
    }
  } catch {}
  _audiusHost = "https://discoveryprovider.audius.co";
  return _audiusHost;
}

function virtualTrack(over: Partial<MusicTrack> & { id: string; title: string; artist: string; audio_url: string }): MusicTrack {
  return {
    id: over.id,
    title: over.title,
    artist: over.artist,
    album: over.album ?? null,
    category: (over.category as MusicTrack["category"]) ?? "general",
    duration_seconds: over.duration_seconds ?? null,
    audio_url: over.audio_url,
    audio_cid: over.audio_cid ?? null,
    cover_url: over.cover_url ?? null,
    is_8d: over.is_8d ?? false,
    language: over.language ?? null,
    tags: over.tags ?? null,
    is_published: true,
    play_count: 0,
    created_at: new Date().toISOString(),
  };
}

/* ─────────────── Audius ─────────────── */

export interface AudiusTrack {
  id: string;
  title: string;
  user: { name: string; handle: string };
  artwork?: { "150x150"?: string; "480x480"?: string; "1000x1000"?: string };
  duration: number;
  permalink?: string;
}

export async function audiusSearch(query: string, limit = 20): Promise<MusicTrack[]> {
  if (!query.trim()) return [];
  try {
    const host = await audiusHost();
    const r = await fetch(
      `${host}/v1/tracks/search?query=${encodeURIComponent(query)}&limit=${limit}&app_name=${APP_NAME}`,
    );
    if (!r.ok) return [];
    const j = await r.json();
    const tracks = (j?.data ?? []) as AudiusTrack[];
    return tracks.map((t) =>
      virtualTrack({
        id: `audius:${t.id}`,
        title: t.title,
        artist: t.user?.name || t.user?.handle || "Unknown",
        duration_seconds: t.duration ?? null,
        audio_url: `${host}/v1/tracks/${t.id}/stream?app_name=${APP_NAME}`,
        cover_url:
          t.artwork?.["1000x1000"] ||
          t.artwork?.["480x480"] ||
          t.artwork?.["150x150"] ||
          null,
        tags: ["audius"],
      }),
    );
  } catch {
    return [];
  }
}

export async function audiusTrending(limit = 20): Promise<MusicTrack[]> {
  try {
    const host = await audiusHost();
    const r = await fetch(`${host}/v1/tracks/trending?limit=${limit}&app_name=${APP_NAME}`);
    if (!r.ok) return [];
    const j = await r.json();
    const tracks = (j?.data ?? []) as AudiusTrack[];
    return tracks.map((t) =>
      virtualTrack({
        id: `audius:${t.id}`,
        title: t.title,
        artist: t.user?.name || t.user?.handle || "Unknown",
        duration_seconds: t.duration ?? null,
        audio_url: `${host}/v1/tracks/${t.id}/stream?app_name=${APP_NAME}`,
        cover_url:
          t.artwork?.["1000x1000"] ||
          t.artwork?.["480x480"] ||
          t.artwork?.["150x150"] ||
          null,
        tags: ["audius", "trending"],
      }),
    );
  } catch {
    return [];
  }
}

/* ─────────────── Piped (YouTube proxy fallback) ─────────────── */

interface PipedSearchItem {
  url?: string; // /watch?v=ID
  title?: string;
  uploaderName?: string;
  duration?: number;
  thumbnail?: string;
}
interface PipedStreamsResp {
  audioStreams?: { url: string; bitrate?: number; mimeType?: string }[];
  title?: string;
  uploader?: string;
  thumbnailUrl?: string;
  duration?: number;
}

async function pipedFetch<T>(path: string): Promise<T | null> {
  for (const host of PIPED_HOSTS) {
    try {
      const r = await fetch(`${host}${path}`);
      if (r.ok) return (await r.json()) as T;
    } catch {}
  }
  return null;
}

export async function pipedSearch(query: string, limit = 12): Promise<MusicTrack[]> {
  const j = await pipedFetch<{ items?: PipedSearchItem[] }>(
    `/search?q=${encodeURIComponent(query)}&filter=music_songs`,
  );
  if (!j?.items) return [];
  const out: MusicTrack[] = [];
  for (const it of j.items.slice(0, limit)) {
    const id = (it.url || "").split("v=")[1]?.split("&")[0];
    if (!id) continue;
    out.push(
      virtualTrack({
        id: `piped:${id}`,
        title: it.title || "—",
        artist: it.uploaderName || "—",
        duration_seconds: it.duration ?? null,
        audio_url: "", // resolved on play
        cover_url: it.thumbnail ?? null,
        tags: ["piped"],
      }),
    );
  }
  return out;
}

/** Resolve a Piped virtual track to a playable audio URL. */
export async function resolvePipedAudio(trackId: string): Promise<string | null> {
  const id = trackId.replace(/^piped:/, "");
  const j = await pipedFetch<PipedStreamsResp>(`/streams/${id}`);
  if (!j?.audioStreams?.length) return null;
  // Pick highest-bitrate audio
  const best = [...j.audioStreams].sort((a, b) => (b.bitrate ?? 0) - (a.bitrate ?? 0))[0];
  return best?.url ?? null;
}

/* ─────────────── Unified search w/ fallback ─────────────── */

export async function searchAllSources(query: string): Promise<MusicTrack[]> {
  const [audius, piped] = await Promise.all([
    audiusSearch(query, 20),
    audius_only_if_short(query) ? pipedSearch(query, 8) : Promise.resolve([]),
  ]);
  // De-dupe by lowercase title|artist
  const seen = new Set<string>();
  const all = [...audius, ...piped];
  return all.filter((t) => {
    const k = `${t.title}|${t.artist}`.toLowerCase();
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

function audius_only_if_short(_q: string) {
  // Always include Piped fallback for richer coverage.
  return true;
}

/* ─────────────── LRCLIB synced lyrics ─────────────── */

export interface SyncedLyric {
  time: number; // seconds
  text: string;
}
export interface LyricsResult {
  plain: string | null;
  synced: SyncedLyric[];
}

function parseLrc(lrc: string): SyncedLyric[] {
  const out: SyncedLyric[] = [];
  const re = /\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?\](.*)/g;
  for (const line of lrc.split("\n")) {
    let m: RegExpExecArray | null;
    re.lastIndex = 0;
    while ((m = re.exec(line))) {
      const t = parseInt(m[1]) * 60 + parseInt(m[2]) + (m[3] ? parseInt(m[3].padEnd(3, "0")) / 1000 : 0);
      out.push({ time: t, text: (m[4] || "").trim() });
    }
  }
  return out.sort((a, b) => a.time - b.time);
}

export async function fetchLyrics(
  artist: string,
  title: string,
  durationSec?: number | null,
): Promise<LyricsResult> {
  try {
    const url = new URL(`${LRCLIB}/get`);
    url.searchParams.set("artist_name", artist);
    url.searchParams.set("track_name", title);
    if (durationSec) url.searchParams.set("duration", String(Math.floor(durationSec)));
    const r = await fetch(url.toString());
    if (r.ok) {
      const j = await r.json();
      return {
        plain: j?.plainLyrics ?? null,
        synced: j?.syncedLyrics ? parseLrc(j.syncedLyrics) : [],
      };
    }
  } catch {}
  // Search fallback
  try {
    const r = await fetch(
      `${LRCLIB}/search?artist_name=${encodeURIComponent(artist)}&track_name=${encodeURIComponent(title)}`,
    );
    if (r.ok) {
      const arr = await r.json();
      const first = Array.isArray(arr) ? arr[0] : null;
      if (first) {
        return {
          plain: first.plainLyrics ?? null,
          synced: first.syncedLyrics ? parseLrc(first.syncedLyrics) : [],
        };
      }
    }
  } catch {}
  return { plain: null, synced: [] };
}

