/**
 * Native runtime helpers — Capacitor detection + haptic engine.
 * Web build'de tüm fonksiyonlar güvenli no-op döner; sadece Android APK içinde
 * gerçek native plugin'ler tetiklenir.
 *
 * Haptic intensity is user-controlled via Settings → Hızlı Kontrol → "Haptik
 * Yoğunluk" and persisted to `jiyan_haptic_intensity_v1` in localStorage so
 * this module can read it synchronously without React.
 */
import { Capacitor } from "@capacitor/core";

export const isNative = (): boolean => Capacitor.isNativePlatform();
export const isAndroid = (): boolean => Capacitor.getPlatform() === "android";
export const isIOS = (): boolean => Capacitor.getPlatform() === "ios";

const HAPTIC_LS_KEY = "jiyan_haptic_intensity_v1";

export type HapticIntensity = "off" | "low" | "medium" | "high";

function readIntensity(): HapticIntensity {
  if (typeof window === "undefined") return "medium";
  try {
    const v = localStorage.getItem(HAPTIC_LS_KEY);
    if (v === "off" || v === "low" || v === "medium" || v === "high") return v;
  } catch {}
  return "medium";
}

/**
 * Pick the actual ImpactStyle to use for a logical strength based on the
 * user's haptic intensity setting. "off" returns null → caller skips.
 */
function resolveImpactStyle(
  logical: "light" | "medium" | "heavy",
): "Light" | "Medium" | "Heavy" | null {
  const it = readIntensity();
  if (it === "off") return null;

  // intensity → strength matrix
  const matrix: Record<
    Exclude<HapticIntensity, "off">,
    Record<"light" | "medium" | "heavy", "Light" | "Medium" | "Heavy">
  > = {
    low:    { light: "Light",  medium: "Light",  heavy: "Medium" },
    medium: { light: "Light",  medium: "Medium", heavy: "Heavy"  },
    high:   { light: "Medium", medium: "Heavy",  heavy: "Heavy"  },
  };
  return matrix[it][logical];
}

/** Scale a web-vibration duration (ms) by the user's intensity. */
function scaleVibration(baseMs: number | number[]): number | number[] | null {
  const it = readIntensity();
  if (it === "off") return null;
  const factor = it === "low" ? 0.5 : it === "medium" ? 1 : 1.6;
  if (Array.isArray(baseMs)) return baseMs.map((n) => Math.max(1, Math.round(n * factor)));
  return Math.max(1, Math.round(baseMs * factor));
}

function webVibrate(pattern: number | number[]) {
  try { (navigator as any).vibrate?.(pattern); } catch {}
}

/**
 * Open URL — Capacitor Browser (in-app) for native, window.open for web.
 */
export async function openExternal(url: string): Promise<void> {
  if (!url) return;
  if (isNative()) {
    try {
      const { Browser } = await import("@capacitor/browser");
      await Browser.open({
        url,
        presentationStyle: "popover",
        toolbarColor: "#000000",
      });
      return;
    } catch (e) {
      console.warn("Capacitor Browser failed, falling back to window.open", e);
    }
  }
  window.open(url, "_blank", "noopener,noreferrer");
}

/** Light haptic tap — sadece native'de çalışır. */
export async function hapticTap(): Promise<void> {
  const style = resolveImpactStyle("light");
  if (!style) return;
  if (!isNative()) {
    const v = scaleVibration(8);
    if (v != null) webVibrate(v);
    return;
  }
  try {
    const { Haptics, ImpactStyle } = await import("@capacitor/haptics");
    await Haptics.impact({ style: ImpactStyle[style] });
  } catch {}
}

/** Medium impact — for entering edit/jiggle modes. */
export async function hapticMedium(): Promise<void> {
  const style = resolveImpactStyle("medium");
  if (!style) return;
  if (!isNative()) {
    const v = scaleVibration(18);
    if (v != null) webVibrate(v);
    return;
  }
  try {
    const { Haptics, ImpactStyle } = await import("@capacitor/haptics");
    await Haptics.impact({ style: ImpactStyle[style] });
  } catch {}
}

/** Heavy impact — strongest, for entering Jiggle Mode. */
export async function hapticHeavy(): Promise<void> {
  const style = resolveImpactStyle("heavy");
  if (!style) return;
  if (!isNative()) {
    const v = scaleVibration([22, 40, 22]);
    if (v != null) webVibrate(v);
    return;
  }
  try {
    const { Haptics, ImpactStyle } = await import("@capacitor/haptics");
    await Haptics.impact({ style: ImpactStyle[style] });
  } catch {}
}

/** Success notification haptic — distinct double-tick for swaps/confirms. */
export async function hapticSuccess(): Promise<void> {
  if (readIntensity() === "off") return;
  if (!isNative()) {
    const v = scaleVibration([12, 30, 28]);
    if (v != null) webVibrate(v);
