/**
 * parseCallCommand — Deng / Phone composer'ında "ara" komutlarını yakalar.
 *
 * Desteklenen pattern'ler (TR/KU/EN, esnek boşluk/format):
 *   "ara +777 1234 5678"
 *   "+777 1234 5678 ara"
 *   "call +777 1234 5678"
 *   "telefon aç +777 99 1792"
 *   "+777 9919 9999 görüntülü ara"
 *
 * Çıktı:
 *   { kurdId: "+777 1234 5678", digits: "12345678", video: boolean } | null
 */
const CALL_VERBS = [
  "ara",
  "call",
  "telefon",
  "phone",
  "dial",
  "bizêre", // KU
  "telefon aç",
  "telefon et",
];
const VIDEO_HINTS = ["görüntülü", "video", "video call", "vîdyo"];

export interface ParsedCallCommand {
  kurdId: string;
  digits: string;
  video: boolean;
  matchedText: string;
}

export function parseCallCommand(input: string): ParsedCallCommand | null {
  if (!input) return null;
  const lower = input.toLowerCase();

  // Bir "ara/call" verb'ü bulunmalı, yoksa Deng'e normal soru olarak gitsin.
  const hasVerb = CALL_VERBS.some((v) => lower.includes(v));
  if (!hasVerb) return null;

  // +777 ile başlayan 8 haneyi yakala (boşluk/tire/parantez tolere)
  let m = input.match(/\+?\s*7{3}[\s\-().]*(\d[\d\s\-().]{6,})/);
  let rawDigits = m ? m[1].replace(/\D/g, "").slice(0, 8) : "";

  // Fallback: "ara 1234 5678" gibi +777 prefix'i olmayan ama 8 hane içeren komut
  if (rawDigits.length !== 8) {
    const allDigits = input.replace(/\D/g, "");
    // 11 hane = 777 + 8 hane (kullanıcı + olmadan yazmış)
    if (allDigits.startsWith("777") && allDigits.length >= 11) {
      rawDigits = allDigits.slice(3, 11);
    } else if (allDigits.length === 8) {
      rawDigits = allDigits;
    }
    if (rawDigits.length !== 8) return null;
    m = m ?? ([input, rawDigits] as any);
  }

  const video = VIDEO_HINTS.some((h) => lower.includes(h));
  const kurdId = `+777 ${rawDigits.slice(0, 4)} ${rawDigits.slice(4)}`;

  return {
    kurdId,
    digits: rawDigits,
    video,
    matchedText: m?.[0] ?? input,
  };
}

/** Kurd-ID görüntü formatı: "+777 1234 5678" */
export function formatKurdIdDigits(digits: string): string {
  const d = digits.replace(/\D/g, "").slice(0, 8);
  if (d.length <= 4) return `+777 ${d}`;
  return `+777 ${d.slice(0, 4)} ${d.slice(4)}`;
}

