/**
 * parseDengCommand — Universal Deng AI command parser.
 *
 * Recognises three families of cross-app commands and returns a typed
 * intent that the overlay/orchestrator can route to the correct mini-app.
 * If nothing matches, returns null and the message is sent to the AI brain.
 *
 *   1. Phone:    "ara +777 1234 5678" / "call +777 ..."
 *   2. Transfer: "50 dc gönder @mikail" / "send 25 DC to +777 1234 5678"
 *   3. Mail:     "mailimi özetle" / "check my mail" / "son mailler"
 */
import { parseCallCommand, type ParsedCallCommand } from "./parseCallCommand";

export type DengIntent =
  | { kind: "call"; data: ParsedCallCommand }
  | {
      kind: "transfer";
      amount: number;
      currency: "DC";
      target: { type: "handle"; handle: string } | { type: "kurdId"; kurdId: string; digits: string };
      note?: string;
    }
  | { kind: "mail_summary"; limit?: number }
  | {
      kind: "music";
      action: "play" | "pause" | "toggle" | "next" | "prev" | "stop" | "search";
      /** Free-text query (title/artist) for "play X" / "search X" actions. */
      query?: string;
      /** Optional category hint: manifesto / meditation / general. */
      category?: "manifesto" | "meditation" | "general";
    }
  | {
      kind: "ritual";
      /** Which ritual surface to open / read. */
      action: "times" | "quran" | "cevsen" | "dua" | "qibla";
      /** Optional surah number when action="quran". */
      surah?: number;
    }
  | null;

const TRANSFER_VERBS = ["gönder", "yolla", "send", "transfer", "öde", "pay", "bişîne"];
const MAIL_VERBS = [
  "mail",
  "maili",
  "mailim",
  "mailimi",
  "inbox",
  "gelen kutu",
  "mesajları",
  "son mailler",
  "check my mail",
];
const MAIL_SUMMARY_HINTS = ["özet", "özetle", "summary", "summarize", "kontrol", "check", "oku", "what's new"];

export function parseDengCommand(input: string): DengIntent {
  const trimmed = input?.trim();
  if (!trimmed) return null;
  const lower = trimmed.toLowerCase();

  // 1. Call (delegate)
  const call = parseCallCommand(trimmed);
  if (call) return { kind: "call", data: call };

  // 2. Transfer — needs an amount + DC + verb + target
  const hasTransferVerb = TRANSFER_VERBS.some((v) => lower.includes(v));
  // amount + dc/diravcash, allow "50 dc", "50dc", "50 DiravCash"
  const amountMatch = trimmed.match(/(\d+(?:[.,]\d+)?)\s*(?:dc|diravcash|d\.c\.)\b/i);
  if (hasTransferVerb && amountMatch) {
    const amount = parseFloat(amountMatch[1].replace(",", "."));
    if (amount > 0) {
      // Target: @handle or +777 NNNN NNNN
      const handleMatch = trimmed.match(/@([a-z0-9_.-]{2,32})/i);
      const kurdMatch = trimmed.match(/\+?\s*7{3}[\s\-().]*(\d[\d\s\-().]{6,})/);
      if (kurdMatch) {
        const digits = kurdMatch[1].replace(/\D/g, "").slice(0, 8);
        if (digits.length === 8) {
          return {
            kind: "transfer",
            amount,
            currency: "DC",
            target: {
              type: "kurdId",
              digits,
              kurdId: `+777 ${digits.slice(0, 4)} ${digits.slice(4)}`,
            },
          };
        }
      }
      if (handleMatch) {
        return {
          kind: "transfer",
          amount,
          currency: "DC",
          target: { type: "handle", handle: handleMatch[1] },
        };
      }
    }
  }

  // 3. Mail summary
  const hasMailVerb = MAIL_VERBS.some((v) => lower.includes(v));
  const hasSummaryHint = MAIL_SUMMARY_HINTS.some((v) => lower.includes(v));
  if (hasMailVerb && (hasSummaryHint || lower.startsWith("mail"))) {
    return { kind: "mail_summary", limit: 5 };
  }

  // 4. Music — play / pause / next / prev / stop / search
  // Tokens (TR + KU + EN): müzik, music, şarkı, song, çal, dinle, oynat,
  // duraklat, durdur, sonraki, geç, önceki, geri, manifesto, meditasyon
  const musicTokens = /(müzi[kg]|music|şarkı|sarki|song|çal|cal|dinle|oynat|stranek|stran)/i;
  const isMusic = musicTokens.test(lower);

  // direct control verbs (work even without explicit "music")
  if (/(\bduraklat|\bduraklatın|\bpause)\b/i.test(lower))
    return { kind: "music", action: "pause" };
  if (/(\bdurdur|\bstop|\bsessiz et|\bkapat müzi[kg])\b/i.test(lower))
    return { kind: "music", action: "stop" };
  if (/(sonraki|sıradaki|geç|skip|next)/i.test(lower) && (isMusic || /şarkı|stran|track|song/i.test(lower)))
    return { kind: "music", action: "next" };
  if (/(önceki|geri|previous|prev)/i.test(lower) && (isMusic || /şarkı|stran|track|song/i.test(lower)))
    return { kind: "music", action: "prev" };
  if (/(devam et|resume|kaldığı yerden)/i.test(lower) && isMusic)
    return { kind: "music", action: "toggle" };

  if (isMusic) {
    // Detect category
    let category: "manifesto" | "meditation" | "general" | undefined;
    if (/manifesto/i.test(lower)) category = "manifesto";
    else if (/medita|meditasyon|sovereign meditation/i.test(lower)) category = "meditation";

    // Extract query after "çal/oynat/play/dinle"
    const playMatch = trimmed.match(
      /(?:çal|cal|oynat|dinle|play|listen to|aç|ac|stranek|stran)[:\s]+(.+?)(?:\s+(?:aç|please|lütfen))?$/i,
    );
    if (playMatch?.[1]) {
      const q = playMatch[1].replace(/[?.!]+$/, "").trim();
      if (q) return { kind: "music", action: "play", query: q, category };
    }

    // "X şarkısını çal" / "X stranek bide"
    const reverseMatch = trimmed.match(/^(.+?)\s+(?:şarkı(?:sı(?:nı)?)?|stran(?:ek)?)/i);
    if (reverseMatch?.[1]) {
      return { kind: "music", action: "play", query: reverseMatch[1].trim(), category };
    }

    // bare "müzik aç" / "music aç" → resume/toggle
    if (/(aç|ac|başlat|baslat|start|open)/i.test(lower) && !playMatch) {
      return { kind: "music", action: "toggle", category };
    }

    // bare "müzik" → toggle
    return { kind: "music", action: "toggle", category };
  }

  // 5. Ritual — namaz vakti, Kur'an, Cevşen, dua, kıble
  if (/(kıble|kible|qibla)/i.test(lower)) return { kind: "ritual", action: "qibla" };
  if (/(namaz vak[ıi]t|ezan vakti|prayer time|vakitler)/i.test(lower))
    return { kind: "ritual", action: "times" };
  if (/(cevşen|cevsen|cawshan)/i.test(lower)) return { kind: "ritual", action: "cevsen" };
  if (/(dua|duâ|prayer|münacat)/i.test(lower) && /(oku|aç|ac|göster|read|open)/i.test(lower))
    return { kind: "ritual", action: "dua" };
  // "kuran oku", "fatiha oku", "yasin oku"
  if (/(kur'?an|qur'?an|kuran)/i.test(lower) && /(oku|aç|ac|göster|read|open)/i.test(lower))
    return { kind: "ritual", action: "quran" };

  return null;
}

