/**
 * passkeyCodec — base64url helpers for WebAuthn payloads.
 *
 * WebAuthn uses ArrayBuffers everywhere and the spec mandates base64url
 * (no padding) when persisting credential ids and public keys. We avoid
 * pulling a heavy library — these helpers are pure standard APIs.
 */

export function bufferToBase64Url(buffer: ArrayBuffer | Uint8Array): string {
  const bytes =
    buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
  let binary = "";
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export function base64UrlToBuffer(value: string): ArrayBuffer {
  const padded = value.replace(/-/g, "+").replace(/_/g, "/");
  const pad = padded.length % 4 === 0 ? "" : "=".repeat(4 - (padded.length % 4));
  const binary = atob(padded + pad);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

export function randomChallenge(byteLength = 32): ArrayBuffer {
  const out = new Uint8Array(new ArrayBuffer(byteLength));
  crypto.getRandomValues(out);
  return out.buffer;
}

