/**
 * Phantom Armor — decoy HTTPS traffic that runs ONLY during an active
 * Sovereign Phone call.
 *
 * Goal: deep-packet inspection on a hostile network sees a noisy stream of
 * normal-looking HTTPS GETs to public endpoints alongside the WebRTC media,
 * making it harder to fingerprint that "this user is on a VoIP call".
 *
 * Constraints:
 *  • Zero work outside an active call (start() / stop() pairing).
 *  • No PII in URLs, no auth headers — just opaque GETs to public CDNs.
 *  • Random jitter so packet cadence does not look like a metronome.
 *  • All requests use AbortController and are fully cancelled on stop().
 */

const DECOY_TARGETS = [
  // Public, no-auth, CORS-safe endpoints. We only care about the network
  // pattern, not the response body — `no-cors` mode is fine.
  "https://www.google.com/generate_204",
  "https://www.gstatic.com/generate_204",
  "https://www.cloudflare.com/cdn-cgi/trace",
  "https://1.1.1.1/cdn-cgi/trace",
  "https://www.apple.com/library/test/success.html",
];

let timer: ReturnType<typeof setTimeout> | null = null;
let controller: AbortController | null = null;
let active = false;

function scheduleNext() {
  if (!active) return;
  // Random 800-2400ms jitter — looks like browser background activity.
  const delay = 800 + Math.floor(Math.random() * 1600);
  timer = setTimeout(tick, delay);
}

async function tick() {
  if (!active || !controller) return;
  const url = DECOY_TARGETS[Math.floor(Math.random() * DECOY_TARGETS.length)];
  try {
    await fetch(url, {
      method: "GET",
      mode: "no-cors",
      cache: "no-store",
      credentials: "omit",
      referrerPolicy: "no-referrer",
      signal: controller.signal,
    });
  } catch {
    // Aborted or network error — both fine, we don't need a response.
  }
  scheduleNext();
}

/** Start decoy traffic. Idempotent. Call when an outgoing/incoming call goes active. */
export function startPhantomArmor() {
  if (active) return;
  active = true;
  controller = new AbortController();
  scheduleNext();
}

/** Stop decoy traffic and cancel any in-flight requests. Idempotent. */
export function stopPhantomArmor() {
  active = false;
  if (timer) {
    clearTimeout(timer);
    timer = null;
  }
  if (controller) {
    try {
      controller.abort();
    } catch {/* noop */}
    controller = null;
  }
}

export function isPhantomArmorActive() {
  return active;
}

