export type LocalPhoneRecentStatus =
  | "Giden Arama"
  | "Yerel Arama"
  | "Gelen Arama"
  | "Cevapsız Arama"
  | "Reddedilen Arama"
  | "Bağlantı Kurulamadı"
  | "İptal Edildi"
  | "Ulaşılamadı";

export interface LocalPhoneRecent {
  id: string;
  kurdId: string;
  status: LocalPhoneRecentStatus;
  createdAt: string;
  video?: boolean;
}

export const PHONE_RECENT_LS_KEY = "jiyan_phone_recent_v1";
export const PHONE_RECENT_EVENT = "jiyan-phone-recent";

export function readLocalPhoneRecent(): LocalPhoneRecent[] {
  if (typeof window === "undefined") return [];
  try {
    const parsed = JSON.parse(localStorage.getItem(PHONE_RECENT_LS_KEY) ?? "[]");
    return Array.isArray(parsed) ? parsed.slice(0, 12) : [];
  } catch {
    return [];
  }
}

export function logLocalOutgoingCall(kurdId: string, video = false, status: LocalPhoneRecentStatus = "Giden Arama") {
  if (typeof window === "undefined") return;
  const entry: LocalPhoneRecent = {
    id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    kurdId,
    status,
    createdAt: new Date().toISOString(),
    video,
  };
  const next = [entry, ...readLocalPhoneRecent()].slice(0, 12);
  try {
    localStorage.setItem(PHONE_RECENT_LS_KEY, JSON.stringify(next));
    window.dispatchEvent(new CustomEvent(PHONE_RECENT_EVENT, { detail: entry }));
  } catch {}
}

