  "ee", "es", "fi", "fo", "fr", "gb", "ge", "gi", "gr", "hr", "hu", "ie",
  "is", "it", "li", "lt", "lu", "lv", "mc", "md", "me", "mk", "mt", "nl",
  "no", "pl", "pt", "ro", "rs", "ru", "se", "si", "sk", "sm", "tr", "ua",
  "va", "xk",
];

function buildLabel(p: PhotonFeature["properties"]): string {
  if (!p) return "";
  const street = [p.street, p.housenumber].filter(Boolean).join(" ").trim();
  const headParts = [p.name, street].filter(Boolean);
  const head = headParts.length > 0 ? Array.from(new Set(headParts)).join(" · ") : null;
  const tail = [p.postcode, p.city ?? p.state, p.country].filter(Boolean).join(", ");
  return [head, tail].filter(Boolean).join(", ");
}

/**
 * Query Photon for address suggestions across Europe.
 *
 * @param query    Free-text search string (≥ 2 chars).
 * @param signal   Optional AbortSignal so callers can cancel pending requests
 *                 when the user keeps typing.
 * @param limit    Number of suggestions to return (default 8, max 15).
 */
export async function fetchEuropeAddressSuggestions(
  query: string,
  signal?: AbortSignal,
  limit = 8,
): Promise<PhotonSuggestion[]> {
  const q = query.trim();
  if (q.length < 2) return [];
  const url = new URL("https://photon.komoot.io/api/");
  url.searchParams.set("q", q);
  url.searchParams.set("limit", String(Math.min(Math.max(limit, 1), 15)));
  url.searchParams.set("lang", "en");

  let res: Response;
  try {
    res = await fetch(url.toString(), { signal });
  } catch (e) {
    // Aborted or offline — return empty so the UI falls back to local matches.
    if ((e as { name?: string })?.name === "AbortError") return [];
    return [];
  }
  if (!res.ok) return [];
  const json = (await res.json().catch(() => null)) as
    | { features?: PhotonFeature[] }
    | null;
  if (!json?.features) return [];

  const seen = new Set<string>();
  const out: PhotonSuggestion[] = [];
  for (const f of json.features) {
    const p = f.properties ?? {};
    const cc = (p.countrycode ?? "").toLowerCase();
    if (cc && !EUROPE_CC.includes(cc)) continue;
    const coords = f.geometry?.coordinates;
    if (!coords || coords.length !== 2) continue;
    const label = buildLabel(p);
    if (!label) continue;
    if (seen.has(label)) continue;
    seen.add(label);
    out.push({
      label,
      countryCode: cc || null,
      city: p.city ?? p.state ?? null,
      lng: coords[0],
      lat: coords[1],
      key: `${p.osm_id ?? label}-${coords[0]}-${coords[1]}`,
    });
    if (out.length >= limit) break;
  }
  return out;
}

