/**
 * quranSources — Sovereign Ritual data layer for Qur'an.
 *
 * Free, key-less, decentralized-friendly endpoints:
 *   • alquran.cloud  — surah list + Arabic + Turkish meal (Diyanet)
 *   • mp3quran.net   — high-quality reciter audio (per-surah mp3 URLs)
 *
 * No API keys, no auth, full CORS, public CDN cached.
 */

export interface SurahSummary {
  number: number;
  name: string;        // Arabic
  englishName: string;
  englishNameTranslation: string;
  numberOfAyahs: number;
  revelationType: "Meccan" | "Medinan";
}

export interface Ayah {
  number: number;
  text: string;
  numberInSurah: number;
}

export interface SurahFull {
  number: number;
  name: string;
  englishName: string;
  ayahs: Ayah[];
  meal: Ayah[]; // Turkish translation, same indexing
}

const BASE = "https://api.alquran.cloud/v1";

let surahCache: SurahSummary[] | null = null;

export async function getSurahList(): Promise<SurahSummary[]> {
  if (surahCache) return surahCache;
  try {
    const r = await fetch(`${BASE}/surah`);
    const j = await r.json();
    surahCache = (j?.data ?? []) as SurahSummary[];
    return surahCache;
  } catch {
    return [];
  }
}

export async function getSurah(number: number): Promise<SurahFull | null> {
  try {
    const [arRes, trRes] = await Promise.all([
      fetch(`${BASE}/surah/${number}/quran-uthmani`),
      fetch(`${BASE}/surah/${number}/tr.diyanet`),
    ]);
    const ar = await arRes.json();
    const tr = await trRes.json();
    const a = ar?.data;
    const t = tr?.data;
    if (!a || !t) return null;
    return {
      number: a.number,
      name: a.name,
      englishName: a.englishName,
      ayahs: a.ayahs as Ayah[],
      meal: t.ayahs as Ayah[],
    };
  } catch {
    return null;
  }
}

/** mp3quran.net reciter — Mishary Rashid Al-Afasy, 128kbps. */
export function getReciterUrl(surahNumber: number): string {
  const padded = String(surahNumber).padStart(3, "0");
  return `https://server8.mp3quran.net/afs/${padded}.mp3`;
}

