/**
 * REBÊR Swarm — Sovereign multi-agent orchestration layer.
 *
 * Five named agents serve the Master. Dengbêj (Orchestrator) routes
 * commands; specialists react. State is in-memory + a small ring buffer
 * of events so the Divan dashboard can show live activity.
 *
 * Primary logic source for every agent decision: the WKO Manifesto
 * (see src/data/manifesto.ts). Agents must consult MANIFESTO_STEPS
 * before mutating user-visible behavior.
 */
import { useSyncExternalStore } from "react";
import { MANIFESTO_ORG, MANIFESTO_VERSION } from "@/data/manifesto";

export type RebearAgentId =
  | "dengbej"
  | "sinemar"
  | "mimar"
  | "pasewan"
  | "zanyar";

export type RebearStatus = "idle" | "working" | "alert";

export interface RebearAgent {
  id: RebearAgentId;
  name: string;
  role: string;
  /** Kurmancî tagline shown under the icon */
  motto: string;
  status: RebearStatus;
  lastActivity?: string;
  lastAt?: number;
}

export interface RebearEvent {
  id: string;
  from: RebearAgentId;
  to?: RebearAgentId;
  kind: "call" | "alert" | "log" | "complete";
  message: string;
  /** WKO Manifesto step number this decision references */
  manifestoStep?: number;
  at: number;
}

const AGENTS: Record<RebearAgentId, RebearAgent> = {
  dengbej: {
    id: "dengbej",
    name: "Dengbêj",
    role: "Orchestrator (Core AI)",
    motto: "Fermana Master vediguhêze.",
    status: "idle",
  },
  sinemar: {
    id: "sinemar",
    name: "Sînemar",
    role: "Media Agent — Jiyan TV/Film & HLS",
    motto: "Ronahî û dengê pêk tîne.",
    status: "idle",
  },
  mimar: {
    id: "mimar",
    name: "Mîmar",
    role: "Architect Agent — UI/UX & Code",
    motto: "Bi rengê zêr ava dike.",
    status: "idle",
  },
  pasewan: {
    id: "pasewan",
    name: "Pasewan",
    role: "Guardian Agent — Security & Jiyan ID",
    motto: "Sînorê me diparêze.",
    status: "idle",
  },
  zanyar: {
    id: "zanyar",
    name: "Zanyar",
    role: "Scholar Agent — WKO Manifesto",
    motto: "Manîfestoyê dixwîne.",
    status: "idle",
  },
};

const EVENT_LIMIT = 60;
let events: RebearEvent[] = [];
const listeners = new Set<() => void>();

function emit() {
  listeners.forEach((l) => l());
}

function subscribe(l: () => void) {
  listeners.add(l);
  return () => listeners.delete(l);
}

function snapshot() {
  return { agents: { ...AGENTS }, events: events.slice() };
}

let cached = snapshot();
function refreshCache() {
  cached = snapshot();
  emit();
}

function pushEvent(e: Omit<RebearEvent, "id" | "at">) {
  const evt: RebearEvent = {
    ...e,
    id: crypto.randomUUID?.() ?? Math.random().toString(36).slice(2),
    at: Date.now(),
  };
  events = [evt, ...events].slice(0, EVENT_LIMIT);
}

function setStatus(
  id: RebearAgentId,
  status: RebearStatus,
  activity?: string,
) {
  AGENTS[id].status = status;
  AGENTS[id].lastActivity = activity ?? AGENTS[id].lastActivity;
  AGENTS[id].lastAt = Date.now();
}

/**
 * Dengbêj relays a Master command to a specialist.
 * Returns a `complete` callback to mark the work done.
 */
export function dengbejCall(
  to: RebearAgentId,
  message: string,
  manifestoStep?: number,
): () => void {
  setStatus("dengbej", "working", `→ ${AGENTS[to].name}: ${message}`);
  setStatus(to, "working", message);
  pushEvent({ from: "dengbej", to, kind: "call", message, manifestoStep });
  refreshCache();
  return () => {
    setStatus(to, "idle", `tamam: ${message}`);
    setStatus("dengbej", "idle", `tamam ← ${AGENTS[to].name}`);
    pushEvent({ from: to, to: "dengbej", kind: "complete", message, manifestoStep });
    refreshCache();
  };
}

/** Specialist raises an alert (e.g., HLS link dead) and Pasewan logs it. */
export function rebearAlert(
  from: RebearAgentId,
  message: string,
  fixOwner: RebearAgentId = "mimar",
  manifestoStep?: number,
) {
  setStatus(from, "alert", message);
  setStatus(fixOwner, "working", `tamîr: ${message}`);
  setStatus("pasewan", "working", `log: ${message}`);
  pushEvent({ from, to: fixOwner, kind: "alert", message, manifestoStep });
  pushEvent({
    from: "pasewan",
    kind: "log",
    message: `[${MANIFESTO_ORG} v${MANIFESTO_VERSION}] ${from} → ${fixOwner}: ${message}`,
    manifestoStep,
  });
  refreshCache();
}

/** Mark an agent idle manually (escape hatch). */
export function rebearReset(id?: RebearAgentId) {
  if (id) setStatus(id, "idle");
  else (Object.keys(AGENTS) as RebearAgentId[]).forEach((k) => setStatus(k, "idle"));
  refreshCache();
}

/** React hook — Divan dashboard subscribes here. */
export function useRebearSwarm() {
  return useSyncExternalStore(subscribe, () => cached, () => cached);
}

export const REBEAR_AGENT_LIST: RebearAgent[] = Object.values(AGENTS);

/* ------------------------------------------------------------------ */
/* HLS Health Watcher — Sînemar → Mîmar auto-flow                     */
/* ------------------------------------------------------------------ */

interface HlsTarget { name: string; url: string }

let hlsTimer: ReturnType<typeof setInterval> | null = null;
const HLS_TARGETS: HlsTarget[] = [];
const failedRecently = new Map<string, number>();

export function registerHlsTarget(t: HlsTarget) {
  if (!HLS_TARGETS.find((x) => x.url === t.url)) HLS_TARGETS.push(t);
}

async function checkHlsOnce(t: HlsTarget) {
  try {
    const ctrl = new AbortController();
    const to = setTimeout(() => ctrl.abort(), 8000);
    const res = await fetch(t.url, { method: "GET", signal: ctrl.signal, cache: "no-store" });
    clearTimeout(to);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    setStatus("sinemar", "idle", `OK: ${t.name}`);
    refreshCache();
    failedRecently.delete(t.url);
  } catch (err: unknown) {
    const last = failedRecently.get(t.url) ?? 0;
    if (Date.now() - last < 5 * 60_000) return;
    failedRecently.set(t.url, Date.now());
    const msg = `HLS düştü — ${t.name}: ${err instanceof Error ? err.message : "fetch error"}`;
    // Manifesto step 7 — audio_waveform_gold (media integrity)
    rebearAlert("sinemar", msg, "mimar", 7);
  }
}

/** Start periodic HLS health check (default 60s). Idempotent, browser-only. */
export function startHlsWatcher(intervalMs = 60_000) {
  if (hlsTimer || typeof window === "undefined") return;
  hlsTimer = setInterval(() => {
    HLS_TARGETS.forEach((t) => void checkHlsOnce(t));
  }, intervalMs);
}

export function stopHlsWatcher() {
  if (hlsTimer) { clearInterval(hlsTimer); hlsTimer = null; }
}

