/**
 * playAdhan — Sovereign "Swiss Safe" ritual chime.
 *
 * Procedural, zero-asset reverent tone for prayer-time alerts. A deep
 * brass-bell ascending arpeggio (D minor maqam) with airy shimmer tail.
 * Fully respects `setSoundEnabled(false)`.
 */
import { isSoundEnabled } from "./systemSounds";

let ctx: AudioContext | null = null;

function ensure(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (ctx) return ctx;
  try {
    const Ctor =
      (window as unknown as { AudioContext?: typeof AudioContext }).AudioContext ||
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return null;
    ctx = new Ctor();
  } catch {
    return null;
  }
  return ctx;
}

/** Deep, reverent 2.4s prayer-time chime (Swiss-safe, no sample assets). */
export function playAdhanChime(): void {
  if (!isSoundEnabled()) return;
  const ac = ensure();
  if (!ac) return;
  if (ac.state === "suspended") ac.resume().catch(() => {});

  const now = ac.currentTime;
  const master = ac.createGain();
  master.gain.value = 0.7;
  master.connect(ac.destination);

  // Bell-like additive partials per note. Maqam-flavored arpeggio.
  const notes = [
    { f: 293.66, t: 0.0 },   // D4
    { f: 369.99, t: 0.45 },  // F#4
    { f: 440.0, t: 0.9 },    // A4
    { f: 587.33, t: 1.35 },  // D5
  ];

  notes.forEach(({ f, t }) => {
    const start = now + t;
    [1, 2, 3.5].forEach((mult, idx) => {
      const o = ac.createOscillator();
      const g = ac.createGain();
      o.type = idx === 0 ? "sine" : "triangle";
      o.frequency.value = f * mult;
      const peak = idx === 0 ? 0.22 : idx === 1 ? 0.08 : 0.04;
      g.gain.setValueAtTime(0.0001, start);
      g.gain.exponentialRampToValueAtTime(peak, start + 0.04);
      g.gain.exponentialRampToValueAtTime(0.0001, start + 1.1);
      o.connect(g).connect(master);
      o.start(start);
      o.stop(start + 1.2);
    });
  });

  // Sub-bass thump under the first note for "weight"
  const sub = ac.createOscillator();
  const sg = ac.createGain();
  sub.type = "sine";
  sub.frequency.setValueAtTime(73, now);
  sub.frequency.exponentialRampToValueAtTime(55, now + 0.6);
  sg.gain.setValueAtTime(0.0001, now);
  sg.gain.exponentialRampToValueAtTime(0.45, now + 0.04);
  sg.gain.exponentialRampToValueAtTime(0.0001, now + 1.6);
  sub.connect(sg).connect(master);
  sub.start(now);
  sub.stop(now + 1.7);

  // Shimmer tail
  try {
    const buf = ac.createBuffer(1, ac.sampleRate * 0.8, ac.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * 0.35;
    const noise = ac.createBufferSource();
    noise.buffer = buf;
    const bp = ac.createBiquadFilter();
    bp.type = "bandpass";
    bp.frequency.setValueAtTime(3500, now + 1.2);
    bp.frequency.exponentialRampToValueAtTime(7000, now + 2.2);
    bp.Q.value = 6;
    const ng = ac.createGain();
    ng.gain.setValueAtTime(0.0001, now + 1.2);
    ng.gain.exponentialRampToValueAtTime(0.05, now + 1.35);
    ng.gain.exponentialRampToValueAtTime(0.0001, now + 2.4);
    noise.connect(bp).connect(ng).connect(master);
    noise.start(now + 1.2);
    noise.stop(now + 2.5);
  } catch {}
}

/** Soft "5-minute warning" — single low gong, no arpeggio. */
export function playRitualWarning(): void {
  if (!isSoundEnabled()) return;
  const ac = ensure();
  if (!ac) return;
  if (ac.state === "suspended") ac.resume().catch(() => {});
  const now = ac.currentTime;
  const o = ac.createOscillator();
  const g = ac.createGain();
  o.type = "sine";
  o.frequency.setValueAtTime(220, now);
  o.frequency.exponentialRampToValueAtTime(165, now + 0.8);
  g.gain.setValueAtTime(0.0001, now);
  g.gain.exponentialRampToValueAtTime(0.3, now + 0.04);
  g.gain.exponentialRampToValueAtTime(0.0001, now + 1.6);
  o.connect(g).connect(ac.destination);
  o.start(now);
  o.stop(now + 1.7);
}

