/**
 * ritualTimes.test — Faz 5: schedule + next-prayer + countdown invariants.
 */
import { describe, it, expect } from "vitest";
import {
  computeRitualTimes,
  findNextPrayer,
  formatHHMM,
  formatCountdown,
  type RitualSchedule,
} from "@/lib/ritualTimes";

const HEWLER = { latitude: 36.19, longitude: 44.0 };

describe("ritualTimes", () => {
  it("computes 6 ordered prayer times for Hewlêr today", () => {
    const sch = computeRitualTimes(HEWLER);
    expect(sch.fajr.getTime()).toBeLessThan(sch.sunrise.getTime());
    expect(sch.sunrise.getTime()).toBeLessThan(sch.dhuhr.getTime());
    expect(sch.dhuhr.getTime()).toBeLessThan(sch.asr.getTime());
    expect(sch.asr.getTime()).toBeLessThan(sch.maghrib.getTime());
    expect(sch.maghrib.getTime()).toBeLessThan(sch.isha.getTime());
  });

  it("findNextPrayer returns dhuhr when called between fajr and dhuhr", () => {
    const today = new Date();
    const sch: RitualSchedule = {
      fajr: new Date(today.setHours(5, 0, 0, 0)),
      sunrise: new Date(new Date().setHours(6, 30, 0, 0)),
      dhuhr: new Date(new Date().setHours(13, 0, 0, 0)),
      asr: new Date(new Date().setHours(16, 0, 0, 0)),
      maghrib: new Date(new Date().setHours(19, 0, 0, 0)),
      isha: new Date(new Date().setHours(20, 30, 0, 0)),
    };
    const now = new Date();
    now.setHours(10, 0, 0, 0);
    const next = findNextPrayer(sch, now);
    expect(next.name).toBe("dhuhr");
    expect(next.msUntil).toBeGreaterThan(0);
  });

  it("findNextPrayer rolls over to tomorrow's fajr after isha", () => {
    const sch: RitualSchedule = {
