/**
 * ritualTimes — Sovereign Ritual time service.
 *
 * Computes daily prayer times offline using Adhan.js (primary) and falls
 * back to the Aladhan public API only on hard failure. MWL is the global
 * default calculation method per Sovereign convention.
 *
 * Also exposes a Hijri date formatter using Intl `islamic-umalqura`
 * calendar (no external dependency, supported in all evergreen browsers).
 */
import {
  CalculationMethod,
  Coordinates,
  PrayerTimes,
  Madhab,
  type CalculationParameters,
} from "adhan";

export type PrayerName = "fajr" | "sunrise" | "dhuhr" | "asr" | "maghrib" | "isha";

export const PRAYER_LABELS_TR: Record<PrayerName, string> = {
  fajr: "İmsak",
  sunrise: "Güneş",
  dhuhr: "Öğle",
  asr: "İkindi",
  maghrib: "Akşam",
  isha: "Yatsı",
};

export const PRAYER_LABELS_KU: Record<PrayerName, string> = {
  fajr: "Spede",
  sunrise: "Roj",
  dhuhr: "Nîvro",
  asr: "Êvar",
  maghrib: "Mexrib",
  isha: "Şev",
};

export type CalcMethodId =
  | "MWL" | "ISNA" | "Egyptian" | "Karachi" | "UmmAlQura"
  | "Dubai" | "MoonsightingCommittee" | "NorthAmerica" | "Kuwait"
  | "Qatar" | "Singapore" | "Tehran" | "Turkey";

function paramsFor(method: CalcMethodId): CalculationParameters {
  switch (method) {
    case "ISNA": return CalculationMethod.NorthAmerica();
    case "Egyptian": return CalculationMethod.Egyptian();
    case "Karachi": return CalculationMethod.Karachi();
    case "UmmAlQura": return CalculationMethod.UmmAlQura();
    case "Dubai": return CalculationMethod.Dubai();
    case "MoonsightingCommittee": return CalculationMethod.MoonsightingCommittee();
    case "NorthAmerica": return CalculationMethod.NorthAmerica();
    case "Kuwait": return CalculationMethod.Kuwait();
    case "Qatar": return CalculationMethod.Qatar();
    case "Singapore": return CalculationMethod.Singapore();
    case "Tehran": return CalculationMethod.Tehran();
    case "Turkey": return CalculationMethod.Turkey();
    case "MWL":
    default:
      return CalculationMethod.MuslimWorldLeague();
  }
}

export interface RitualSchedule {
  fajr: Date;
  sunrise: Date;
  dhuhr: Date;
  asr: Date;
  maghrib: Date;
  isha: Date;
}

export interface RitualOptions {
  latitude: number;
  longitude: number;
  date?: Date;
  method?: CalcMethodId;
  madhab?: "shafi" | "hanafi";
}

export function computeRitualTimes(opts: RitualOptions): RitualSchedule {
  const { latitude, longitude, date = new Date(), method = "MWL", madhab = "shafi" } = opts;
  const params = paramsFor(method);
  params.madhab = madhab === "hanafi" ? Madhab.Hanafi : Madhab.Shafi;
  const pt = new PrayerTimes(new Coordinates(latitude, longitude), date, params);
  return {
    fajr: pt.fajr,
    sunrise: pt.sunrise,
    dhuhr: pt.dhuhr,
    asr: pt.asr,
    maghrib: pt.maghrib,
    isha: pt.isha,
  };
}

/** Aladhan API fallback — used only if Adhan.js throws (extreme latitudes etc.) */
export async function fetchRitualTimesAladhan(
  latitude: number,
  longitude: number,
  date = new Date(),
): Promise<RitualSchedule | null> {
  try {
    const dd = String(date.getDate()).padStart(2, "0");
    const mm = String(date.getMonth() + 1).padStart(2, "0");
    const yyyy = date.getFullYear();
    const url = `https://api.aladhan.com/v1/timings/${dd}-${mm}-${yyyy}?latitude=${latitude}&longitude=${longitude}&method=3`;
    const r = await fetch(url);
    if (!r.ok) return null;
    const j = await r.json();
    const t = j?.data?.timings;
    if (!t) return null;
    const mk = (s: string) => {
      const [h, m] = s.split(":").map((n: string) => parseInt(n, 10));
      const d = new Date(date);
      d.setHours(h, m, 0, 0);
      return d;
    };
    return {
      fajr: mk(t.Fajr),
      sunrise: mk(t.Sunrise),
      dhuhr: mk(t.Dhuhr),
      asr: mk(t.Asr),
      maghrib: mk(t.Maghrib),
      isha: mk(t.Isha),
    };
  } catch {
    return null;
  }
}

export interface NextPrayer {
  name: PrayerName;
  at: Date;
  msUntil: number;
}

const ORDER: PrayerName[] = ["fajr", "sunrise", "dhuhr", "asr", "maghrib", "isha"];

export function findNextPrayer(schedule: RitualSchedule, now = new Date()): NextPrayer {
  for (const name of ORDER) {
    const at = schedule[name];
    if (at.getTime() > now.getTime()) {
      return { name, at, msUntil: at.getTime() - now.getTime() };
    }
  }
  // After Isha → tomorrow's Fajr (caller should recompute for tomorrow ideally)
  const tomorrow = new Date(schedule.fajr);
  tomorrow.setDate(tomorrow.getDate() + 1);
  return { name: "fajr", at: tomorrow, msUntil: tomorrow.getTime() - now.getTime() };
}

export function formatHHMM(d: Date): string {
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}

export function formatCountdown(ms: number): string {
  if (ms <= 0) return "00:00";
  const total = Math.floor(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  if (h > 0) return `${h}s ${String(m).padStart(2, "0")}d`;
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

/** Hijri date via Intl islamic-umalqura calendar. Returns "12 Rebî' II 1447". */
export function formatHijri(date = new Date(), locale = "tr-TR-u-ca-islamic-umalqura"): string {
  try {
    return new Intl.DateTimeFormat(locale, {
      day: "numeric",
      month: "long",
      year: "numeric",
    }).format(date);
  } catch {
    return "";
  }
}

