/**
 * sovereignCodeRouting — Maps a security/verification message to the
 * mini-app screen that should consume the Egemen Kod.
 *
 * The inbox table doesn't carry an explicit `target_app` column, so we
 * infer the destination from the subject + body. This is intentionally
 * permissive: a fallback to the global Authenticator screen is always
 * provided so the user can copy the code and continue manually.
 */

export type CodeAppTarget =
  | "wallet"
  | "id-borsa"
  | "mail"
  | "login"
  | "security"
  | "authenticator";

export interface CodeRoute {
  target: CodeAppTarget;
  /** Tanstack route path (no params interpolation needed). */
  to: string;
  /** Short Turkish CTA label, e.g. "Cüzdan'da Onayla". */
  cta: string;
  /** One-line context for the user, e.g. "DiravCash transferi onayı". */
  context: string;
}

const RULES: Array<{
  match: RegExp;
  build: () => CodeRoute;
}> = [
  {
    match: /(c[üu]zdan|wallet|dirav|transfer|gönderim|tip)/i,
    build: () => ({
      target: "wallet",
      to: "/wallet",
      cta: "Cüzdan'da Onayla",
      context: "DiravCash işlemi onayı bekliyor",
    }),
  },
  {
    match: /(borsa|kurd[- ]?id|numara|marketplace.*id|id.*market)/i,
    build: () => ({
      target: "id-borsa",
      to: "/marketplace",
      cta: "ID Borsa'da Onayla",
      context: "Kurd-ID alımı onayı bekliyor",
    }),
  },
  {
    match: /(mail|gelen kutu|inbox|e-?posta)/i,
    build: () => ({
      target: "mail",
      to: "/inbox",
      cta: "Mail'de Onayla",
      context: "Mail erişim onayı bekliyor",
    }),
  },
  {
    match: /(giri[şs]|login|sign[- ]?in|oturum)/i,
    build: () => ({
      target: "login",
      to: "/login",
      cta: "Giriş'i Tamamla",
      context: "Yeni cihaz giriş onayı bekliyor",
    }),
  },
  {
    match: /(g[üu]venlik|security|cihaz|device|passkey|şifre|recovery)/i,
    build: () => ({
      target: "security",
      to: "/security",
      cta: "Güvenlik Hub'ında Onayla",
      context: "Hesap güvenliği işlemi bekliyor",
    }),
  },
];

/**
 * Resolve which mini-app screen this code belongs to. Falls back to the
 * Authenticator hub so the user always has a sensible next step.
 */
export function resolveCodeRoute(input: {
  subject?: string | null;
  body?: string | null;
}): CodeRoute {
  const haystack = `${input.subject ?? ""} ${input.body ?? ""}`;
  for (const r of RULES) {
    if (r.match.test(haystack)) return r.build();
  }
  return {
    target: "authenticator",
    to: "/authenticator",
    cta: "Authenticator'da Aç",
    context: "Egemen Kod hazır",
  };
}

