/**
 * Sovereign Crypto utilities — runs ENTIRELY in the browser.
 * Plaintext seed words MUST NEVER leave the device.
 *
 * - generateSeedPhrase(): 24 BIP39-style words from a curated wordlist.
 * - hashSeedPhrase(words): SHA-256 hex digest of the canonical phrase.
 * - generateTotpSecret(): 32-char Base32 secret for TOTP.
 * - generateTotpCode(secret, ts?): 6-digit RFC6238 code, 30s window.
 * - secondsRemainingInWindow(ts?): countdown for the current 30s window.
 * - getDeviceFingerprint(): stable per-browser fingerprint stored in localStorage.
 */

// 256-word curated list (subset of BIP39 — small enough to ship inline,
// large enough that 24 words give ~192 bits of entropy).
const WORDS = [
  "abandon","ability","able","about","above","absent","absorb","abstract","absurd","abuse","access","accident","account","accuse","achieve","acid",
  "acoustic","acquire","across","act","action","actor","actress","actual","adapt","add","addict","address","adjust","admit","adult","advance",
