  "away","awesome","awful","awkward","axis","baby","bachelor","bacon","badge","bag","balance","balcony","ball","bamboo","banana","banner",
  "bar","barely","bargain","barrel","base","basic","basket","battle","beach","bean","beauty","because","become","beef","before","begin",
  "behave","behind","believe","below","belt","bench","benefit","best","betray","better","between","beyond","bicycle","bid","bike","bind",
  "biology","bird","birth","bitter","black","blade","blame","blanket","blast","bleak","bless","blind","blood","blossom","blouse","blue",
  "blur","blush","board","boat","body","boil","bomb","bone","bonus","book","boost","border","boring","borrow","boss","bottom",
  "bounce","box","boy","bracket","brain","brand","brass","brave","bread","breeze","brick","bridge","brief","bright","bring","brisk",
  "broccoli","broken","bronze","broom","brother","brown","brush","bubble","buddy","budget","buffalo","build","bulb","bulk","bullet","bundle",
  "bunker","burden","burger","burst","bus","business","busy","butter","buyer","buzz","cabbage","cabin","cable","cactus","cage","cake",
];

// ---------- 24-word seed phrase ---------------------------------------------
export function generateSeedPhrase(): string[] {
  if (typeof crypto === "undefined" || !crypto.getRandomValues) {
    throw new Error("Crypto API yok — bu cihazda anahtar üretilemez.");
  }
  const out: string[] = [];
  const buf = new Uint16Array(24);
  crypto.getRandomValues(buf);
  for (let i = 0; i < 24; i++) {
    out.push(WORDS[buf[i] % WORDS.length]);
  }
  return out;
}

export function canonicalizePhrase(words: string[]): string {
  return words.map((w) => w.trim().toLowerCase()).join(" ");
}

export async function hashSeedPhrase(words: string[]): Promise<string> {
  const data = new TextEncoder().encode(canonicalizePhrase(words));
  const buf = await crypto.subtle.digest("SHA-256", data);
  return [...new Uint8Array(buf)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

// ---------- TOTP (RFC 6238) -------------------------------------------------
const BASE32_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

function base32Decode(input: string): Uint8Array {
  const clean = input.toUpperCase().replace(/=+$/, "").replace(/\s+/g, "");
  let bits = "";
  for (const ch of clean) {
    const idx = BASE32_ALPHABET.indexOf(ch);
    if (idx === -1) continue;
    bits += idx.toString(2).padStart(5, "0");
  }
  const bytes: number[] = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) {
    bytes.push(parseInt(bits.slice(i, i + 8), 2));
  }
  return new Uint8Array(bytes);
}

export function generateTotpSecret(): string {
  const buf = new Uint8Array(20); // 160 bits — RFC6238 recommended
  crypto.getRandomValues(buf);
  let bits = "";
  for (const b of buf) bits += b.toString(2).padStart(8, "0");
  let out = "";
  for (let i = 0; i + 5 <= bits.length; i += 5) {
    out += BASE32_ALPHABET[parseInt(bits.slice(i, i + 5), 2)];
  }
  return out;
}

export async function generateTotpCode(secretBase32: string, timestampMs?: number): Promise<string> {
  const ts = Math.floor((timestampMs ?? Date.now()) / 1000);
  const counter = Math.floor(ts / 30);

  // 8-byte big-endian counter
  const counterBuf = new ArrayBuffer(8);
  const view = new DataView(counterBuf);
  view.setUint32(0, Math.floor(counter / 0x100000000));
  view.setUint32(4, counter >>> 0);

  const keyData = base32Decode(secretBase32);
  const key = await crypto.subtle.importKey(
    "raw",
    keyData.buffer.slice(0) as ArrayBuffer,
    { name: "HMAC", hash: "SHA-1" },
    false,
    ["sign"],
  );
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", key, counterBuf));

  const offset = sig[sig.length - 1] & 0x0f;
  const binary =
    ((sig[offset] & 0x7f) << 24) |
    ((sig[offset + 1] & 0xff) << 16) |
    ((sig[offset + 2] & 0xff) << 8) |
    (sig[offset + 3] & 0xff);
  const code = binary % 1_000_000;
  return code.toString().padStart(6, "0");
}

export function secondsRemainingInWindow(timestampMs?: number): number {
  const ts = Math.floor((timestampMs ?? Date.now()) / 1000);
  return 30 - (ts % 30);
}

// ---------- Device fingerprint (soft binding) -------------------------------
const DEVICE_KEY = "jiyan_device_fp";

export function getDeviceFingerprint(): string {
  if (typeof window === "undefined") return "ssr-unknown";
  let fp = localStorage.getItem(DEVICE_KEY);
  if (fp) return fp;
  const buf = new Uint8Array(16);
  crypto.getRandomValues(buf);
  fp = [...buf].map((b) => b.toString(16).padStart(2, "0")).join("");
  localStorage.setItem(DEVICE_KEY, fp);
  return fp;
}

export function getDeviceLabel(): string {
  if (typeof navigator === "undefined") return "Bilinmeyen Cihaz";
  const ua = navigator.userAgent;
  if (/iPhone/i.test(ua)) return "iPhone";
  if (/iPad/i.test(ua)) return "iPad";
  if (/Android/i.test(ua)) return "Android";
  if (/Macintosh/i.test(ua)) return "Mac";
  if (/Windows/i.test(ua)) return "Windows";
  if (/Linux/i.test(ua)) return "Linux";
  return "Web Cihazı";
}

