/**
 * sovereignRingtone — WhatsApp-grade crystalline ringtone synthesized in
 * realtime via WebAudio. No external asset needed (works offline, no
 * round-trip latency). Mechanical Swiss-watch character: two stacked
 * sine partials + a soft FM bell, gated by a triple-bell rhythm.
 *
 * Plays on a loop from `start()` until `stop()` is called. Designed to be
 * safe to call repeatedly — calling `start()` while already playing is a
 * no-op. Honors the silent switch on iOS Safari (audio is gated by user
 * interaction; the inbound-call screen surfaces a tap-to-unmute fallback).
 */

let ctx: AudioContext | null = null;
let masterGain: GainNode | null = null;
let interval: number | null = null;
let active = false;

function ensureCtx(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (ctx && ctx.state !== "closed") return ctx;
  try {
    const Ctor =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return null;
    ctx = new Ctor();
    masterGain = ctx.createGain();
    masterGain.gain.value = 0.45;
    masterGain.connect(ctx.destination);
    return ctx;
  } catch {
    return null;
  }
}

/** One crystalline "ting" — two sine partials with quick exponential decay. */
function ring(at: number, base = 880) {
  const c = ctx;
  const m = masterGain;
  if (!c || !m) return;

  const partials = [
    { freq: base, gain: 0.35, decay: 0.45 },
    { freq: base * 1.5, gain: 0.18, decay: 0.55 },
    { freq: base * 2.005, gain: 0.09, decay: 0.7 },
  ];
  for (const p of partials) {
    const o = c.createOscillator();
    o.type = "sine";
    o.frequency.setValueAtTime(p.freq, at);
    const g = c.createGain();
    g.gain.setValueAtTime(0.0001, at);
    g.gain.exponentialRampToValueAtTime(p.gain, at + 0.005);
    g.gain.exponentialRampToValueAtTime(0.0001, at + p.decay);
    o.connect(g).connect(m);
    o.start(at);
    o.stop(at + p.decay + 0.05);
  }
}

/** Play a "tri-bell" (3 quick tings) at the given AudioContext time. */
function triBell(at: number) {
  ring(at + 0.0, 988); // B5
  ring(at + 0.18, 1318); // E6
  ring(at + 0.36, 988); // B5
}

export function startSovereignRingtone() {
  if (active) return;
  const c = ensureCtx();
  if (!c) return;
  // Resume context if suspended (autoplay policies).
  if (c.state === "suspended") {
    void c.resume().catch(() => {/* noop */});
  }
  active = true;

  const cycle = () => {
    if (!active || !ctx) return;
    triBell(ctx.currentTime + 0.05);
  };
  cycle();
  interval = window.setInterval(cycle, 1700);
}

export function stopSovereignRingtone() {
  active = false;
  if (interval !== null) {
    window.clearInterval(interval);
    interval = null;
  }
}

export function isRingtoneActive() {
  return active;
}

