/**
 * systemSounds — The Sound of Sovereignty.
 *
 * Procedurally generated, zero-asset Apple-tier system audio via WebAudio.
 * No external files; the AudioContext is lazily created on first user
 * gesture (browser autoplay policy compliant).
 *
 *  • boot()       — 1.5s deep-bass "Shimmer" power-on chime
 *  • tick()       — 12ms haptic-style click for floating bar taps
 *  • powerUp()    — Theme-switch flourish (used by SterkOS Elite activation)
 *
 * All functions silently no-op when audio is muted via `setSoundEnabled(false)`
 * or in SSR.
 */

const LS_KEY = "jiyan_system_sound_v1";

let ctx: AudioContext | null = null;
let masterGain: GainNode | null = null;

function isEnabled(): boolean {
  if (typeof window === "undefined") return false;
  try {
    const v = localStorage.getItem(LS_KEY);
    return v !== "0";
  } catch {
    return true;
  }
}

export function setSoundEnabled(on: boolean): void {
  try {
    localStorage.setItem(LS_KEY, on ? "1" : "0");
  } catch {}
}

export function isSoundEnabled(): boolean {
  return isEnabled();
}

function ensureCtx(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (ctx) return ctx;
  try {
    const Ctor =
      (window as unknown as { AudioContext?: typeof AudioContext })
        .AudioContext ||
      (window as unknown as { webkitAudioContext?: typeof AudioContext })
        .webkitAudioContext;
    if (!Ctor) return null;
    ctx = new Ctor();
    masterGain = ctx.createGain();
    masterGain.gain.value = 0.85;
    masterGain.connect(ctx.destination);
  } catch {
    ctx = null;
  }
  return ctx;
}

/** Apple-style 1.5s shimmer with deep bass thump + airy bell harmonics. */
export function playBootChime(): void {
  if (!isEnabled()) return;
  const ac = ensureCtx();
  if (!ac || !masterGain) return;
  if (ac.state === "suspended") ac.resume().catch(() => {});

  const now = ac.currentTime;

  // Deep bass thump (60→40Hz sine sweep)
  const bass = ac.createOscillator();
  const bassGain = ac.createGain();
  bass.type = "sine";
  bass.frequency.setValueAtTime(60, now);
  bass.frequency.exponentialRampToValueAtTime(40, now + 0.6);
  bassGain.gain.setValueAtTime(0.0001, now);
  bassGain.gain.exponentialRampToValueAtTime(0.55, now + 0.04);
  bassGain.gain.exponentialRampToValueAtTime(0.0001, now + 1.4);
  bass.connect(bassGain).connect(masterGain);
  bass.start(now);
  bass.stop(now + 1.5);

  // Airy shimmer — three detuned sine partials forming a Cmaj7 shimmer
  const partials = [523.25, 659.25, 783.99, 1046.5]; // C5 E5 G5 C6
  partials.forEach((freq, i) => {
    const osc = ac.createOscillator();
    const g = ac.createGain();
    osc.type = "sine";
    osc.frequency.value = freq;
    const start = now + i * 0.05;
    g.gain.setValueAtTime(0.0001, start);
    g.gain.exponentialRampToValueAtTime(0.12, start + 0.08);
    g.gain.exponentialRampToValueAtTime(0.0001, start + 1.2);
    osc.connect(g).connect(masterGain!);
    osc.start(start);
    osc.stop(start + 1.3);
  });

  // Hi-shimmer noise sweep (white-noise burst → bandpass)
  try {
    const buf = ac.createBuffer(1, ac.sampleRate * 0.5, ac.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * 0.4;
    const noise = ac.createBufferSource();
    noise.buffer = buf;
    const bp = ac.createBiquadFilter();
    bp.type = "bandpass";
    bp.frequency.setValueAtTime(2000, now + 0.1);
    bp.frequency.exponentialRampToValueAtTime(8000, now + 1.0);
    bp.Q.value = 8;
    const ng = ac.createGain();
    ng.gain.setValueAtTime(0.0001, now + 0.1);
    ng.gain.exponentialRampToValueAtTime(0.06, now + 0.18);
    ng.gain.exponentialRampToValueAtTime(0.0001, now + 1.1);
    noise.connect(bp).connect(ng).connect(masterGain);
    noise.start(now + 0.1);
    noise.stop(now + 1.2);
  } catch {}
