/**
 * voice-peaks — extract a normalized amplitude waveform from an audio Blob.
 *
 * The result is a fixed-length array of numbers in [0, 1] representing the
 * per-bucket peak amplitude. We persist this alongside the audio file so the
 * receiver can render the 3D waveform instantly without re-decoding the file.
 */

export const VOICE_PEAK_BUCKETS = 48;

/**
 * Decode the blob with the Web Audio API and downsample to N buckets.
 * Falls back to a pseudo-random shimmer if decoding fails (e.g. unsupported
 * codec on older Safari).
 */
export async function extractVoicePeaks(
  blob: Blob,
  buckets = VOICE_PEAK_BUCKETS,
): Promise<number[]> {
  try {
    const arrayBuffer = await blob.arrayBuffer();
    const AudioCtx =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AudioCtx) return fallbackPeaks(buckets);

    const audioCtx = new AudioCtx();
    const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer.slice(0));
    const channel = audioBuffer.getChannelData(0);
    const blockSize = Math.floor(channel.length / buckets);
    if (blockSize === 0) return fallbackPeaks(buckets);

    const peaks: number[] = new Array(buckets);
    let max = 0;
    for (let i = 0; i < buckets; i++) {
      let sum = 0;
      const start = i * blockSize;
      const end = start + blockSize;
      for (let j = start; j < end; j++) {
        sum += Math.abs(channel[j]);
      }
      const avg = sum / blockSize;
      peaks[i] = avg;
      if (avg > max) max = avg;
    }

    // Normalize to [0, 1] with a small floor so silent gaps still render bars.
    const safeMax = max || 1;
    return peaks.map((p) => Math.max(0.08, p / safeMax));
  } catch (err) {
    console.warn("voice-peaks: decode failed, using fallback", err);
    return fallbackPeaks(buckets);
  }
}

function fallbackPeaks(n: number): number[] {
  return Array.from({ length: n }, (_, i) => {
    const t = i / n;
    return 0.25 + Math.abs(Math.sin(t * Math.PI * 4)) * 0.6;
  });
}

