/**
 * wakeLock — Tiny wrapper around the Screen Wake Lock API. Call
 * `acquireWakeLock()` when an active call/media session starts and
 * `releaseWakeLock()` when it ends. Auto-reacquires after the document
 * becomes visible again (the browser releases the lock on tab switch).
 */

type WakeLockSentinel = {
  released: boolean;
  release: () => Promise<void>;
  addEventListener: (type: "release", listener: () => void) => void;
};

let sentinel: WakeLockSentinel | null = null;
let visibilityHandler: (() => void) | null = null;

async function request(): Promise<WakeLockSentinel | null> {
  try {
    const wl = (navigator as unknown as {
      wakeLock?: { request: (type: "screen") => Promise<WakeLockSentinel> };
    }).wakeLock;
    if (!wl) return null;
    return await wl.request("screen");
  } catch {
    return null;
  }
}

export async function acquireWakeLock() {
  if (typeof document === "undefined") return;
  if (sentinel && !sentinel.released) return;
  sentinel = await request();
  if (!visibilityHandler) {
    visibilityHandler = async () => {
      if (document.visibilityState === "visible" && (!sentinel || sentinel.released)) {
        sentinel = await request();
      }
    };
    document.addEventListener("visibilitychange", visibilityHandler);
  }
}

export async function releaseWakeLock() {
  try {
    await sentinel?.release();
  } catch {/* noop */}
  sentinel = null;
  if (visibilityHandler) {
    document.removeEventListener("visibilitychange", visibilityHandler);
    visibilityHandler = null;
  }
}

