// (or other browser extensions) mutates text nodes outside React's control.
// See: https://github.com/facebook/react/issues/11538
const TRANSLATE_PATCH = `
(function() {
  if (typeof Node === 'undefined' || Node.prototype.__lovablePatched) return;
  Node.prototype.__lovablePatched = true;
  const origRemoveChild = Node.prototype.removeChild;
  Node.prototype.removeChild = function(child) {
    if (child.parentNode !== this) {
      if (child.parentNode) { try { return child.parentNode.removeChild(child); } catch(e) {} }
      return child;
    }
    return origRemoveChild.apply(this, arguments);
  };
  const origInsertBefore = Node.prototype.insertBefore;
  Node.prototype.insertBefore = function(newNode, referenceNode) {
    if (referenceNode && referenceNode.parentNode !== this) {
      return origInsertBefore.call(this, newNode, null);
    }
    return origInsertBefore.apply(this, arguments);
  };
})();
`;

function RootShell({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <head>
        <HeadContent />
        <script dangerouslySetInnerHTML={{ __html: TRANSLATE_PATCH }} />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  );
}

function RootComponent() {
  if (typeof window !== "undefined") {
    try {
      const ref = new URLSearchParams(window.location.search).get("ref");
      if (ref) localStorage.setItem("jiyan_ref_code", ref.toUpperCase());
    } catch {}

    // Service Worker — sadece üretim/standalone host, iframe/preview HARİÇ
    try {
      const inIframe = window.self !== window.top;
      const host = window.location.hostname;
      const isPreview =
        host.includes("id-preview--") ||
        host.includes("lovableproject.com") ||
        host === "localhost" ||
        host === "127.0.0.1";
      if ("serviceWorker" in navigator) {
        if (inIframe || isPreview) {
          navigator.serviceWorker.getRegistrations().then((rs) => rs.forEach((r) => r.unregister())).catch(() => {});
        } else {
          window.addEventListener("load", () => {
            navigator.serviceWorker.register("/sw.js", { scope: "/" }).catch(() => {});
          });
        }
      }
    } catch {}
  }
  // Android donanım Geri tuşu — modal kapat / history geri / minimize
  useAndroidBackButton();
  // Standalone Deng AI portal (dengai.app) — hide Jiyan OS chrome.
  // Sovereign Identity (+777 ID), Hazine and Mîvankas data still sync because
  // the same Supabase backend powers both jiyan.world and dengai.app.
  const dengaiOnly = isDengAiHost();
  return (
    <SovereignPhoneProvider>
      <MusicProvider>
        <AppSheetProvider>
          <BootSplash />
          {!dengaiOnly && <AppTabsBar />}
          <Outlet />
          {!dengaiOnly && <MusicMiniPlayer />}
          {!dengaiOnly && <DengSparkHost />}
          {!dengaiOnly && <IpfsVerifiedBadge />}
          <RitualMusicBridgeMount />
        </AppSheetProvider>
      </MusicProvider>
    </SovereignPhoneProvider>
  );
}

