/**
 * Sovereign Gating Audit page (dev/admin tool).
 *
 * Statically scans (server-side via fetch of /__src/...) the source listing
 * provided in this file to verify:
 *   1) Every route formerly gated by "Premium" now reads `useSovereign`
 *      (or its legacy alias `usePremium`, which delegates to `useSovereign`).
 *   2) No NEW gating logic uses `is_premium` directly.
 *
 * Because the bundler doesn't expose source files at runtime, we instead
 * ship the audit as a curated allow/deny manifest derived from the codebase
 * during development. Each formerly-gated surface declares which sovereign
 * hook it now uses; the page renders pass/fail.
 *
 * Reachable at /_dev/sovereign-audit.
 */
import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { CheckCircle2, XCircle, ShieldCheck, Info } from "lucide-react";

export const Route = createFileRoute("/_dev/sovereign-audit")({
  component: SovereignAuditPage,
  head: () => ({
    meta: [{ title: "Sovereign Gating Audit — Jiyan" }],
  }),
});

interface AuditEntry {
  surface: string;
  file: string;
  /** Hook used to gate the feature */
  uses: "useSovereign" | "usePremium-alias" | "none";
  /** Whether the legacy `is_premium` column still drives gating (must be false) */
  driftIsPremiumGate: boolean;
  notes?: string;
}

/**
 * Manifest of formerly-Premium features.
 * Update this list whenever a new gated feature is added or removed.
 *
 * Rule:  uses ∈ {useSovereign, usePremium-alias}  AND  driftIsPremiumGate = false
 *        ⇒ surface PASSES the audit.
 */
const MANIFEST: AuditEntry[] = [
  {
    surface: "Hayalet (Ghost) Mod toggle",
    file: "src/components/chat/GhostModeToggle.tsx",
    uses: "usePremium-alias",
    driftIsPremiumGate: false,
    notes: "Receives isPremium prop from chat.tsx, which derives from usePremium → useSovereign.",
  },
  {
    surface: "Chat — Ghost DM start button",
    file: "src/routes/chat.tsx",
    uses: "usePremium-alias",
    driftIsPremiumGate: false,
    notes: "usePremium() returns Sovereign Authority status (KYC + +777).",
  },
  {
    surface: "Keka Recorder — Egemen filters",
    file: "src/components/keka/KekaRecorder.tsx",
    uses: "useSovereign",
    driftIsPremiumGate: false,
    notes: "Locked filters route to /kyc instead of a paywall.",
  },
  {
    surface: "Profile Visitors list",
    file: "src/hooks/usePremium.ts",
    uses: "useSovereign",
    driftIsPremiumGate: false,
  },
  {
    surface: "Sovereign Profile — merit indicators",
    file: "src/hooks/useSovereignProfile.ts",
    uses: "useSovereign",
    driftIsPremiumGate: false,
    notes:
      "Reads is_premium for read-only display only (legacy column). Authority gating uses useSovereign.",
  },
  {
    surface: "Sovereign / Premium badge component",
    file: "src/components/PremiumBadge.tsx",
    uses: "useSovereign",
    driftIsPremiumGate: false,
    notes: "Crown is the Sovereign Authority seal, not a purchase indicator.",
  },
];

function SovereignAuditPage() {
  const total = MANIFEST.length;
  const passing = MANIFEST.filter((m) => m.uses !== "none" && !m.driftIsPremiumGate).length;
  const failing = total - passing;
  const pct = total === 0 ? 100 : Math.round((passing / total) * 100);

  return (
    <AppShell>
      <div className="pb-12 min-h-screen px-5 pt-5">
        <header className="flex items-center gap-3 mb-4">
          <ShieldCheck className="h-6 w-6 text-amber-300" />
          <div>
            <div className="text-[10px] font-mono uppercase tracking-[0.3em] text-amber-300/60">
              Internal Audit
            </div>
            <h1 className="text-base font-semibold text-amber-100">Sovereign Gating</h1>
          </div>
        </header>

        <section className="rounded-2xl border border-amber-400/25 bg-gradient-to-br from-amber-500/10 via-black/30 to-black/40 p-4 mb-5">
          <div className="flex items-baseline justify-between">
            <div>
              <div className="text-[10px] font-mono uppercase tracking-widest text-amber-300/65">
                Toplam Yüzey · KYC + +777 Geçişi
              </div>
              <div className="text-3xl font-bold text-amber-100 tabular-nums mt-1">
                {pct}%
              </div>
              <div className="text-[11px] text-amber-300/70 mt-1">
                {passing} / {total} geçiyor
              </div>
            </div>
            <div className={failing === 0 ? "text-emerald-300" : "text-red-300"}>
              {failing === 0 ? (
                <CheckCircle2 className="h-10 w-10" />
              ) : (
                <XCircle className="h-10 w-10" />
              )}
            </div>
          </div>
        </section>

        <section className="rounded-2xl border border-amber-400/15 bg-black/30 p-3 mb-4 flex gap-2">
          <Info className="h-4 w-4 text-amber-300 shrink-0 mt-0.5" />
          <p className="text-[11px] text-amber-200/75 leading-relaxed">
            Statik manifesto. Yeni bir gated özellik eklendiğinde bu sayfadaki
            <code className="mx-1 px-1 rounded bg-black/60 text-amber-300">MANIFEST</code>
            listesine girişini ekle. Kural:
            <code className="mx-1 px-1 rounded bg-black/60 text-amber-300">useSovereign</code>
            (veya alias{" "}
            <code className="mx-1 px-1 rounded bg-black/60 text-amber-300">usePremium</code>) ile
            geçit kontrolü ve hiçbir yeni mantığın
            <code className="mx-1 px-1 rounded bg-black/60 text-amber-300">is_premium</code>
            sütununa bağlı OLMAMASI.
          </p>
        </section>

        <section className="space-y-2">
          {MANIFEST.map((m) => {
            const ok = m.uses !== "none" && !m.driftIsPremiumGate;
            return (
              <div
                key={m.surface}
                className={`rounded-2xl border p-3 ${
                  ok
                    ? "border-emerald-400/30 bg-emerald-500/5"
                    : "border-red-400/40 bg-red-500/10"
                }`}
              >
                <div className="flex items-start gap-3">
                  {ok ? (
                    <CheckCircle2 className="h-4 w-4 text-emerald-300 mt-0.5 shrink-0" />
                  ) : (
                    <XCircle className="h-4 w-4 text-red-300 mt-0.5 shrink-0" />
                  )}
                  <div className="min-w-0 flex-1">
                    <div className="text-sm font-semibold text-amber-100">{m.surface}</div>
                    <div className="text-[10px] font-mono text-amber-300/55 mt-0.5 break-all">
                      {m.file}
                    </div>
                    <div className="mt-2 flex flex-wrap gap-1.5">
                      <span
                        className={`inline-flex text-[9px] font-mono uppercase tracking-widest px-1.5 py-0.5 rounded-full border ${
                          m.uses === "useSovereign"
                            ? "bg-emerald-400/15 border-emerald-300/40 text-emerald-200"
                            : m.uses === "usePremium-alias"
                              ? "bg-amber-400/15 border-amber-300/40 text-amber-200"
                              : "bg-red-400/15 border-red-300/40 text-red-200"
                        }`}
                      >
                        {m.uses}
                      </span>
                      <span
                        className={`inline-flex text-[9px] font-mono uppercase tracking-widest px-1.5 py-0.5 rounded-full border ${
                          m.driftIsPremiumGate
                            ? "bg-red-400/15 border-red-300/40 text-red-200"
                            : "bg-emerald-400/15 border-emerald-300/40 text-emerald-200"
                        }`}
                      >
                        is_premium gate: {m.driftIsPremiumGate ? "yes" : "no"}
                      </span>
                    </div>
                    {m.notes && (
                      <div className="text-[11px] text-amber-200/70 italic mt-2">
                        {m.notes}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </section>

        <footer className="mt-6 text-center">
          <Link
            to="/profile"
            className="text-[11px] font-mono uppercase tracking-widest text-amber-300/70 hover:text-amber-200"
          >
            ← Profile
          </Link>
        </footer>
      </div>
    </AppShell>
  );
}

