import { createFileRoute, Link } from "@tanstack/react-router";
import { useEffect, useMemo, useRef, useState } from "react";
import { AppShell } from "@/components/layout/AppShell";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/hooks/useAuth";
import { useLinguistAcademy } from "@/hooks/useLinguistAcademy";
import { TR_NL_DECK, DAILY_GOAL_OPTIONS } from "@/data/linguistFlashcards";
import { AcademyOnboarding } from "@/components/linguist/AcademyOnboarding";
import { Flashcard } from "@/components/linguist/Flashcard";
import { QuizCard } from "@/components/linguist/QuizCard";
import { GoalRing } from "@/components/linguist/GoalRing";
import { WeeklyChart } from "@/components/linguist/WeeklyChart";
import { linguistSounds } from "@/lib/linguistAudio";
import { GraduationCap, Flame, Award, Target, Lock, Play, X, Coins, Sparkles, Layers, ListChecks } from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/academy-linguist")({
  component: AcademyLinguistPage,
  head: () => ({
    meta: [
      { title: "WKO Academy: Linguist | Jiyan.world" },
      {
        name: "description",
        content:
          "Sovereign language academy. Master Dutch with Turkish flashcards, daily streaks, and KurdID-linked rewards.",
      },
    ],
  }),
});

const SESSION_KEY = "wko-linguist-session-start";

function AcademyLinguistPage() {
  const { user } = useAuth();
  const { settings, sessions, cardStates, loading, saveSettings, setCardStatus, recordSession } = useLinguistAcademy();
  const [studying, setStudying] = useState(false);
  const [mode, setMode] = useState<"flashcard" | "quiz">("flashcard");
  const [savingOnboarding, setSavingOnboarding] = useState(false);
  const [deckIdx, setDeckIdx] = useState(0);
  const [quizCorrect, setQuizCorrect] = useState(0);
  const sessionStart = useRef<number | null>(null);
  const sessionMastered = useRef(0);

  // Stats derived from state
  const todayIso = new Date().toISOString().slice(0, 10);
  const todaySession = useMemo(() => sessions.find((s) => s.session_date === todayIso), [sessions, todayIso]);
  const todayMinutes = todaySession?.minutes_studied ?? 0;
  const goal = settings?.daily_goal_minutes ?? 10;
  const streak = settings?.current_streak ?? 0;
  const goalLabel = DAILY_GOAL_OPTIONS.find((o) => o.minutes === goal)?.label;

  const masteredCount = useMemo(
    () => Object.values(cardStates).filter((c) => c.status === "mastered").length,
    [cardStates]
  );
  const nextRewardDays = streak < 7 ? 7 - streak : streak < 14 ? 14 - streak : streak < 30 ? 30 - streak : 0;
  const nextRewardDc = streak < 7 ? 1 : streak < 14 ? 2 : streak < 30 ? 5 : 0;

  // Build the deck order: cards needing review first, then new ones, mastered last
  const deck = useMemo(() => {
    return [...TR_NL_DECK].sort((a, b) => {
      const sa = cardStates[a.id]?.status ?? "new";
      const sb = cardStates[b.id]?.status ?? "new";
      const order = { review: 0, new: 1, learning: 2, mastered: 3 };
      return order[sa] - order[sb];
    });
  }, [cardStates]);

  const currentCard = deck[deckIdx];

  // Start a study session timer
  const beginStudy = (selectedMode: "flashcard" | "quiz") => {
    sessionStart.current = Date.now();
    sessionMastered.current = 0;
    setQuizCorrect(0);
    setDeckIdx(0);
    setMode(selectedMode);
    setStudying(true);
    if (typeof window !== "undefined") {
      sessionStorage.setItem(SESSION_KEY, String(Date.now()));
    }
  };

  // End session and persist minutes
  const endStudy = async (silent = false) => {
    const start = sessionStart.current;
    setStudying(false);
    sessionStart.current = null;
    if (typeof window !== "undefined") sessionStorage.removeItem(SESSION_KEY);
    if (!start) return;
    const mins = Math.max(1, Math.round((Date.now() - start) / 60000));
    const result = await recordSession(mins, sessionMastered.current);
    if (!silent && result && result.success && "streak" in result) {
      if (result.goal_reached && (todaySession?.goal_reached ?? false) === false) {
        linguistSounds.goalReached();
        toast.success(`🎯 Günlük hedef tamamlandı! Streak: ${result.streak} gün`);
      } else {
        toast.success(`+${mins} dk · ${sessionMastered.current} kart ustalaştı`);
      }
      if (result.badge_awarded) {
        toast.success("🎓 Linguist Badge kazandın! (30 gün streak)", { duration: 6000 });
      }
      if (result.milestone_dc > 0) {
        toast.success(`💎 +${result.milestone_dc} DiravCash streak ödülü`);
      }
    }
  };

  // Recover an interrupted session on unmount/page change
  useEffect(() => {
    return () => {
      if (sessionStart.current) {
        // fire and forget
        void endStudy(true);
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleSwipe = (direction: "left" | "right") => {
    if (!currentCard) return;
    const mastered = direction === "right";
    if (mastered) {
      sessionMastered.current += 1;
      linguistSounds.mastered();
    } else {
      linguistSounds.review();
    }
    void setCardStatus(currentCard.id, "nl", mastered);
    if (deckIdx + 1 >= deck.length) {
      void endStudy();
    } else {
      setDeckIdx((i) => i + 1);
    }
  };

  const handleQuizAnswer = (correct: boolean) => {
    if (!currentCard) return;
    if (correct) {
      sessionMastered.current += 1;
      setQuizCorrect((n) => n + 1);
      void setCardStatus(currentCard.id, "nl", true);
    } else {
      void setCardStatus(currentCard.id, "nl", false);
    }
    if (deckIdx + 1 >= deck.length) {
      void endStudy();
    } else {
      setDeckIdx((i) => i + 1);
    }
  };

  // ── Auth gate
  if (!user) {
    return (
      <AppShell>
        <div className="bg-black min-h-screen flex items-center justify-center px-4">
          <Card className="max-w-md w-full bg-zinc-950 border border-[#FFD700]/40 p-8 text-center">
            <Lock className="w-12 h-12 mx-auto text-[#FFD700] mb-4" />
            <h1 className="text-2xl font-bold text-[#FFD700] mb-2">Giriş gerekli</h1>
            <p className="text-zinc-400 text-sm mb-6">
              Academy: Linguist ilerlemeni KurdID profiline bağlar.
            </p>
            <Link to="/login">
              <Button className="w-full bg-[#FFD700] text-black font-semibold hover:bg-[#FFD700]/90">
                Giriş yap
              </Button>
            </Link>
          </Card>
        </div>
      </AppShell>
    );
  }

  if (loading) {
    return (
      <AppShell>
        <div className="bg-black min-h-screen flex items-center justify-center text-zinc-400">
          Academy yükleniyor...
        </div>
      </AppShell>
    );
  }

  // ── Onboarding gate
  if (!settings) {
    return (
      <AppShell>
        <div className="bg-black min-h-screen py-8">
          <AcademyOnboarding
            saving={savingOnboarding}
            onComplete={async (s) => {
              setSavingOnboarding(true);
              const r = await saveSettings(s);
              setSavingOnboarding(false);
              if (!r.success) toast.error(r.error || "Kaydetme hatası");
            }}
          />
        </div>
      </AppShell>
    );
  }

  // ── Study mode
  if (studying && currentCard) {
    return (
      <AppShell>
        <div className="bg-black min-h-screen text-white">
          <div className="max-w-md mx-auto px-4 py-4 space-y-4">
            <div className="flex items-center justify-between">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => void endStudy()}
                className="text-zinc-500 hover:text-white"
              >
                <X className="w-5 h-5" />
              </Button>
              <div className="flex items-center gap-2 text-xs text-zinc-500 tabular-nums">
                <Badge className="bg-zinc-900 border border-zinc-800 text-zinc-400 text-[10px]">
                  {mode === "quiz" ? "QUIZ" : "FLASHCARD"}
                </Badge>
                <span>
                  {deckIdx + 1} / {deck.length}
                </span>
              </div>
              <Badge className="bg-[#9B59B6]/20 text-[#9B59B6] border-0 text-[10px]">
                <Flame className="w-3 h-3 mr-1" /> {streak} gün
              </Badge>
            </div>

            {/* Progress bar */}
            <div className="h-1 w-full rounded-full bg-zinc-900 overflow-hidden">
              <div
                className="h-full bg-gradient-to-r from-[#FFD700] to-[#9B59B6] transition-all duration-300"
                style={{ width: `${((deckIdx + 1) / deck.length) * 100}%` }}
              />
            </div>

            {mode === "flashcard" ? (
              <>
                <Flashcard card={currentCard} onSwipe={handleSwipe} active />
                <div className="grid grid-cols-2 gap-3 pt-2">
                  <Button
                    variant="outline"
                    onClick={() => handleSwipe("left")}
                    className="h-12 border-[#9B59B6] text-[#9B59B6] hover:bg-[#9B59B6]/10 font-semibold"
                  >
                    ↻ Tekrar Et
                  </Button>
                  <Button
                    onClick={() => handleSwipe("right")}
                    className="h-12 bg-[#FFD700] text-black hover:bg-[#FFD700]/90 font-semibold"
                  >
                    ✓ Öğrendim
                  </Button>
                </div>
                <p className="text-center text-[10px] text-zinc-600">
                  Sağa kaydır = ustalaştın · Sola kaydır = tekrar gerekli
                </p>
              </>
            ) : (
              <>
                <QuizCard card={currentCard} pool={deck} onAnswer={handleQuizAnswer} />
                <p className="text-center text-[10px] text-zinc-600">
                  Doğru: <span className="text-[#FFD700] font-bold">{quizCorrect}</span> / {deckIdx + 1}
                </p>
              </>
            )}
          </div>
        </div>
      </AppShell>
    );
  }

  // ── Dashboard
  return (
    <AppShell>
      <div className="bg-black min-h-screen text-white">
        <div className="max-w-3xl mx-auto px-4 py-6 space-y-6">
          {/* Header */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-[#FFD700] to-[#9B59B6] flex items-center justify-center">
                <GraduationCap className="w-7 h-7 text-black" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[#FFD700]">WKO Academy</h1>
                <p className="text-xs text-zinc-500 uppercase tracking-wider">Linguist · Sovereign</p>
              </div>
            </div>
            {streak >= 30 && (
              <Badge className="bg-gradient-to-r from-[#FFD700] to-[#9B59B6] text-black border-0 font-bold">
                🎓 Linguist
              </Badge>
            )}
          </div>

          {/* Daily Goal Ring */}
          <Card className="bg-zinc-950 border-2 border-[#FFD700]/30 p-6 relative overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-br from-[#FFD700]/5 to-[#9B59B6]/10 pointer-events-none" />
            <div className="relative flex flex-col sm:flex-row items-center gap-6">
              <GoalRing value={todayMinutes} goal={goal} size={170} label={goalLabel} />
              <div className="flex-1 text-center sm:text-left">
                <div className="text-xs uppercase tracking-wider text-[#9B59B6] font-bold mb-1">
                  Bugün · 🇹🇷 → 🇳🇱
                </div>
                <h2 className="text-xl font-bold text-white mb-1">
                  {todayMinutes >= goal ? "Hedef tamamlandı! 🎯" : `${goal - todayMinutes} dk kaldı`}
                </h2>
                <p className="text-sm text-zinc-400 mb-4">
                  {todayMinutes >= goal
                    ? "Bugünün streak'i güvende. Tekrar etmeye devam et!"
                    : "Egemen vatandaşlık öğrenmekle başlar."}
                </p>
                <div className="flex flex-col sm:flex-row gap-2">
                  <Button
                    onClick={() => beginStudy("flashcard")}
                    className="bg-[#FFD700] text-black hover:bg-[#FFD700]/90 font-bold h-11 px-5 flex-1"
                  >
                    <Layers className="w-4 h-4 mr-2" /> Flashcard
                  </Button>
                  <Button
