import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { useAuth } from "@/hooks/useAuth";
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { ArrowLeft, GraduationCap, Loader2, Trophy, BookOpen, Scale, Languages, Sparkles, RefreshCw, Coins, CarFront, ChevronRight } from "lucide-react";

export const Route = createFileRoute("/academy")({
  head: () => ({
    meta: [
      { title: "WKO Academy — Jiyan.world" },
      { name: "description", content: "Global education in language, tech and leadership. Earn WKO-certified diplomas." },
    ],
  }),
  component: AcademyPage,
});

interface Course {
  id: string;
  title: string;
  description: string;
  category: string;
  difficulty: string;
  points: number;
  total_lessons: number;
  badge_name: string | null;
  badge_icon: string | null;
}
interface Enrollment {
  course_id: string;
  progress: number;
  completed_at: string | null;
}

const CATEGORY_ICONS: Record<string, any> = { tech: BookOpen, law: Scale, language: Languages };

function AcademyPage() {
  const { user } = useAuth();
  const [courses, setCourses] = useState<Course[]>([]);
  const [enrollments, setEnrollments] = useState<Record<string, Enrollment>>({});
  const [acting, setActing] = useState<string | null>(null);

  const load = async () => {
    const { data: c } = await supabase.from("academy_courses").select("*").order("created_at");
    setCourses((c as any) || []);
    if (user) {
      const { data: e } = await supabase
        .from("academy_enrollments")
        .select("course_id,progress,completed_at")
        .eq("user_id", user.id);
      const map: Record<string, Enrollment> = {};
      (e as any[])?.forEach((row) => (map[row.course_id] = row));
      setEnrollments(map);
    }
  };

  useEffect(() => {
    load();
  }, [user?.id]);

  const enroll = async (courseId: string) => {
    if (!user) return;
    setActing(courseId);
    const { error } = await supabase.from("academy_enrollments").insert({
      user_id: user.id,
      course_id: courseId,
      progress: 0,
    });
    setActing(null);
    if (error) {
      toast.error(error.message);
      return;
    }
    toast.success("Kursa kaydoldun!");
    load();
  };

  const complete = async (courseId: string) => {
    if (!user) return;
    setActing(courseId);
    const { data, error } = await supabase.rpc("complete_academy_course", {
      _user_id: user.id,
      _course_id: courseId,
    });
    setActing(null);
    if (error || !(data as any)?.success) {
      toast.error(error?.message || "Tamamlanamadı");
      return;
    }
    toast.success(`🎉 Mastery Badge kazandın: ${(data as any).badge_name}`);
    load();
  };

  const inProgress = courses.filter((c) => enrollments[c.id] && !enrollments[c.id].completed_at);
  const available = courses.filter((c) => !enrollments[c.id]);
  const completed = courses.filter((c) => enrollments[c.id]?.completed_at);

  const reviewCourse = async (courseId: string) => {
    if (!user) return;
    setActing(courseId);
    const { error } = await supabase.rpc("add_xp", {
      _user_id: user.id,
      _amount: 10,
      _source: `academy_review:${courseId}`,
    });
    setActing(null);
    if (error) {
      toast.error("Tekrar ödülü alınamadı: " + error.message);
      return;
    }
    toast.success("🎓 +10 XP kazandın", { description: "Bilgini taze tuttuğun için teşekkürler!" });
  };

  return (
    <AppShell>
      <div className="min-h-screen bg-[#050505] text-foreground pb-24">
        <div className="sticky top-0 z-30 backdrop-blur-xl bg-black/60 border-b border-white/5 px-4 py-3 flex items-center gap-3">
          <Link to="/dashboard" className="p-2 rounded-lg hover:bg-white/5">
            <ArrowLeft className="w-4 h-4" />
          </Link>
          <div className="flex-1">
            <div className="text-[10px] uppercase tracking-widest opacity-50">Module</div>
            <div className="font-bold flex items-center gap-1.5">
              <GraduationCap className="w-4 h-4 text-purple-400" />
              Jiyan Akademi
            </div>
          </div>
          {completed.length > 0 && (
            <span className="text-[10px] font-bold px-2 py-1 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/30 flex items-center gap-1">
              <Trophy className="w-3 h-3" /> {completed.length}
            </span>
          )}
        </div>

        {/* ─── Öğrenme Yolları — Akademi · Linguist · Ehliyet ─── */}
        <div className="px-4 pt-5">
          <h2 className="text-xs uppercase tracking-widest opacity-50 mb-3">Öğrenme Yolları</h2>
          <div className="grid grid-cols-1 gap-2.5">
            <Link
              to="/linguist"
              className="group flex items-center gap-3 rounded-2xl border border-emerald-400/25 bg-gradient-to-br from-emerald-500/10 via-teal-600/5 to-black p-3.5 active:scale-[0.98] transition-transform"
            >
              <div className="h-11 w-11 rounded-xl bg-emerald-500/15 ring-1 ring-emerald-400/30 flex items-center justify-center shrink-0">
                <Languages className="h-5 w-5 text-emerald-300" strokeWidth={2.2} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-bold text-emerald-100">WKO Linguist</div>
                <div className="text-[11px] text-emerald-200/70 truncate">Kurmancî · Soranî · Zazakî · Hewramî</div>
              </div>
              <ChevronRight className="h-4 w-4 text-emerald-300/60 shrink-0" />
            </Link>

            <Link
              to="/driving-exam"
              className="group flex items-center gap-3 rounded-2xl border border-sky-400/25 bg-gradient-to-br from-sky-500/10 via-blue-600/5 to-black p-3.5 active:scale-[0.98] transition-transform"
            >
              <div className="h-11 w-11 rounded-xl bg-sky-500/15 ring-1 ring-sky-400/30 flex items-center justify-center shrink-0">
                <CarFront className="h-5 w-5 text-sky-300" strokeWidth={2.2} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-bold text-sky-100">Ehliyet Sınavı</div>
                <div className="text-[11px] text-sky-200/70 truncate">CBR standartlarında 1100+ görsel soru</div>
              </div>
              <ChevronRight className="h-4 w-4 text-sky-300/60 shrink-0" />
            </Link>

            <div className="flex items-center gap-3 rounded-2xl border border-purple-400/25 bg-gradient-to-br from-purple-500/10 via-fuchsia-600/5 to-black p-3.5">
              <div className="h-11 w-11 rounded-xl bg-purple-500/15 ring-1 ring-purple-400/30 flex items-center justify-center shrink-0">
                <BookOpen className="h-5 w-5 text-purple-300" strokeWidth={2.2} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-bold text-purple-100">Jiyan Akademi</div>
                <div className="text-[11px] text-purple-200/70 truncate">Aşağıdaki kurslar · sertifikalı diploma</div>
              </div>
            </div>
          </div>
        </div>
        {inProgress.length > 0 && (
          <div className="pt-4">
            <h2 className="text-xs uppercase tracking-widest opacity-50 mb-3 px-4">Continue Learning</h2>
            <div className="flex gap-3 overflow-x-auto px-4 pb-2 scrollbar-hide">
              {inProgress.map((c) => {
                const Icon = CATEGORY_ICONS[c.category] || BookOpen;
                return (
                  <div key={c.id} className="shrink-0 w-64 rounded-2xl bg-gradient-to-br from-purple-500/15 to-indigo-700/15 border border-purple-400/30 p-4">
                    <Icon className="w-6 h-6 text-purple-300 mb-2" />
                    <h3 className="font-bold text-sm">{c.title}</h3>
                    <div className="text-[10px] opacity-60 mt-1">{c.difficulty} · {c.points} pts</div>
                    <div className="h-1.5 bg-white/5 rounded-full mt-3 overflow-hidden">
                      <div className="h-full bg-purple-400" style={{ width: `${enrollments[c.id].progress}%` }} />
                    </div>
                    <button
                      onClick={() => complete(c.id)}
                      disabled={acting === c.id}
                      className="w-full mt-3 py-2 rounded-lg bg-purple-500 hover:bg-purple-600 text-xs font-semibold"
                    >
                      {acting === c.id ? <Loader2 className="w-4 h-4 animate-spin mx-auto" /> : "Tamamla & Badge Al"}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        <div className="pt-6 px-4">
          <h2 className="text-xs uppercase tracking-widest opacity-50 mb-3">Available Courses</h2>
          <div className="space-y-3">
            {available.map((c) => {
              const Icon = CATEGORY_ICONS[c.category] || BookOpen;
              return (
                <div key={c.id} className="rounded-2xl bg-white/[0.03] border border-white/10 p-4 flex gap-3">
                  <div className="w-12 h-12 rounded-xl bg-purple-500/15 flex items-center justify-center shrink-0">
                    <Icon className="w-5 h-5 text-purple-400" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <h3 className="font-bold text-sm">{c.title}</h3>
                      <span className="text-[9px] uppercase tracking-wider px-1.5 py-0.5 rounded bg-white/10 opacity-70">{c.difficulty}</span>
                    </div>
                    <p className="text-xs opacity-60 mt-0.5 line-clamp-2">{c.description}</p>
                    <div className="flex items-center justify-between mt-2">
                      <span className="text-[10px] opacity-60">{c.total_lessons} ders · {c.points} puan · {c.badge_icon} {c.badge_name}</span>
                      <button
                        onClick={() => enroll(c.id)}
                        disabled={acting === c.id}
                        className="text-xs font-semibold px-3 py-1.5 rounded-lg bg-purple-500/20 border border-purple-400/30 text-purple-200 hover:bg-purple-500/30"
                      >
                        {acting === c.id ? <Loader2 className="w-3 h-3 animate-spin" /> : "Kaydol"}
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {available.length === 0 && completed.length > 0 && (
          <div className="pt-6 px-4">
            <div className="rounded-2xl bg-gradient-to-br from-purple-600/20 via-fuchsia-600/15 to-amber-500/15 border border-amber-400/30 p-5 text-center">
              <Sparkles className="w-8 h-8 text-amber-300 mx-auto mb-2" />
              <h3 className="font-bold">Tüm kurslar tamamlandı!</h3>
              <p className="text-xs opacity-70 mt-1 mb-4">
                Daha fazla öğrenmek için WKO Linguist'te yeni diller keşfet veya mevcut kursları tekrar ederek günlük XP kazan.
              </p>
              <Link
                to="/linguist"
                className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-gradient-to-r from-purple-500 to-fuchsia-500 text-sm font-semibold hover:opacity-90"
              >
                <Languages className="w-4 h-4" /> WKO Linguist'i Aç
              </Link>
            </div>
          </div>
        )}

        {completed.length > 0 && (
          <div className="pt-6 px-4">
            <h2 className="text-xs uppercase tracking-widest opacity-50 mb-3">🏆 Mezun Olduğun Kurslar</h2>
            <div className="space-y-2">
              {completed.map((c) => (
                <div key={c.id} className="rounded-xl bg-amber-500/10 border border-amber-400/30 p-3 flex items-center gap-3">
                  <div className="text-3xl">{c.badge_icon}</div>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-semibold truncate">{c.badge_name}</div>
                    <div className="text-[10px] opacity-60 truncate">{c.title}</div>
                  </div>
                  <button
                    onClick={() => reviewCourse(c.id)}
                    disabled={acting === c.id}
                    className="shrink-0 inline-flex items-center gap-1 px-2.5 py-1.5 rounded-lg bg-amber-500/20 border border-amber-400/40 text-amber-200 text-[11px] font-semibold hover:bg-amber-500/30 disabled:opacity-50"
                    title="Bilgini tekrarla ve +0.5 DC kazan"
                  >
                    {acting === c.id ? (
                      <Loader2 className="w-3 h-3 animate-spin" />
                    ) : (
                      <>
                        <RefreshCw className="w-3 h-3" />
                        <Coins className="w-3 h-3" /> +0.5
                      </>
                    )}
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </AppShell>
  );
}

