import { createFileRoute, Link } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { AppShell } from "@/components/layout/AppShell";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { adminSearchHonorLedger, type AdminHonorEntry } from "@/hooks/useHonorLedger";
import { Shield, Search, ChevronLeft, AlertTriangle, FileText } from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/admin/honor-ledger")({
  component: AdminHonorLedgerPage,
  head: () => ({
    meta: [
      { title: "Admin · Honor Ledger Audit — Jiyan" },
      { name: "description", content: "Search and audit community honor entries." },
    ],
  }),
});

function AdminHonorLedgerPage() {
  const { user, loading: authLoading } = useAuth();
  const [isAdmin, setIsAdmin] = useState(false);
  const [checking, setChecking] = useState(true);

  const [userId, setUserId] = useState("");
  const [action, setAction] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [rows, setRows] = useState<AdminHonorEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [offset, setOffset] = useState(0);
  const PAGE_SIZE = 50;

  useEffect(() => {
    if (!user) {
      setChecking(false);
      return;
    }
    supabase
      .from("profiles")
      .select("role")
      .eq("user_id", user.id)
      .single()
      .then(({ data }) => {
        setIsAdmin(data?.role === "admin");
        setChecking(false);
      });
  }, [user]);

  const search = async (nextOffset = 0, append = false) => {
    setLoading(true);
    setError(null);
    const res = await adminSearchHonorLedger({
      userId: userId.trim() || undefined,
      action: action.trim() || undefined,
      from: from ? new Date(from).toISOString() : undefined,
      to: to ? new Date(to).toISOString() : undefined,
      limit: PAGE_SIZE,
      offset: nextOffset,
    });
    setLoading(false);
    if (res.error) {
      setError(res.error);
      toast.error("Sorgu başarısız: " + res.error);
      return;
    }
    setRows((prev) => (append ? [...prev, ...res.rows] : res.rows));
    setOffset(nextOffset + res.rows.length);
  };

  // Initial load
  useEffect(() => {
    if (isAdmin) search(0, false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isAdmin]);

  if (authLoading || checking) {
    return (
      <AppShell>
        <div className="flex items-center justify-center min-h-[60vh]">
          <div className="h-8 w-8 animate-spin rounded-full border-2 border-amber-400 border-t-transparent" />
        </div>
      </AppShell>
    );
  }

  if (!user || !isAdmin) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center px-6 min-h-[60vh] text-center">
          <AlertTriangle className="h-12 w-12 text-amber-400/40 mb-3" />
          <p className="text-sm text-muted-foreground mb-4">
            Bu sayfa yalnızca yöneticiler içindir.
          </p>
          <Link
            to="/profile"
            className="px-4 py-2 rounded-xl bg-amber-400/15 border border-amber-400/40 text-amber-200 text-xs"
          >
            Profile dön
          </Link>
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <div className="pb-12 min-h-screen">
        <header className="px-5 pt-5 pb-3 flex items-center gap-3">
          <Link
            to="/admin"
            className="h-9 w-9 rounded-full border border-amber-400/30 bg-black/40 flex items-center justify-center"
            aria-label="Geri"
          >
            <ChevronLeft className="h-4 w-4 text-amber-300" />
          </Link>
          <div className="flex-1">
            <div className="text-[10px] font-mono uppercase tracking-[0.3em] text-amber-300/60">
              Admin · Audit
            </div>
            <h1 className="text-base font-semibold text-amber-100/95 mt-0.5 flex items-center gap-2">
              <Shield className="h-4 w-4 text-amber-300" />
              Honor Ledger
            </h1>
          </div>
        </header>

        {/* Filters */}
        <section className="px-5">
          <div className="rounded-2xl border border-amber-400/15 bg-black/30 p-3 grid grid-cols-2 gap-2">
            <label className="col-span-2">
              <span className="block text-[10px] font-mono uppercase tracking-widest text-amber-300/55 mb-1">
                User ID (UUID)
              </span>
              <input
                value={userId}
                onChange={(e) => setUserId(e.target.value)}
                placeholder="00000000-0000-0000-0000-000000000000"
                className="w-full rounded-lg bg-black/50 border border-amber-400/20 px-3 py-2 text-xs text-amber-100 placeholder:text-amber-300/30 focus:border-amber-400/60 focus:outline-none font-mono"
              />
            </label>
            <label>
              <span className="block text-[10px] font-mono uppercase tracking-widest text-amber-300/55 mb-1">
                Source / Action
              </span>
              <input
                value={action}
                onChange={(e) => setAction(e.target.value)}
                placeholder="re_contribution"
                className="w-full rounded-lg bg-black/50 border border-amber-400/20 px-3 py-2 text-xs text-amber-100 placeholder:text-amber-300/30 focus:border-amber-400/60 focus:outline-none font-mono"
              />
            </label>
            <div />
            <label>
              <span className="block text-[10px] font-mono uppercase tracking-widest text-amber-300/55 mb-1">
                From
              </span>
              <input
                type="datetime-local"
                value={from}
                onChange={(e) => setFrom(e.target.value)}
                className="w-full rounded-lg bg-black/50 border border-amber-400/20 px-3 py-2 text-xs text-amber-100 focus:border-amber-400/60 focus:outline-none"
              />
            </label>
            <label>
              <span className="block text-[10px] font-mono uppercase tracking-widest text-amber-300/55 mb-1">
                To
              </span>
              <input
                type="datetime-local"
                value={to}
                onChange={(e) => setTo(e.target.value)}
                className="w-full rounded-lg bg-black/50 border border-amber-400/20 px-3 py-2 text-xs text-amber-100 focus:border-amber-400/60 focus:outline-none"
              />
