            >
              <UserCog className="h-4 w-4" />
              Rol Yönetimine Git
            </Link>
            <Link
              to="/dashboard"
              className="flex items-center justify-center gap-2 rounded-xl border border-border bg-surface px-4 py-2.5 text-xs font-medium text-muted-foreground hover:bg-accent transition-colors"
            >
              <ArrowLeft className="h-4 w-4" />
              Panele Dön
            </Link>
          </div>
        </div>
