    );
  }

  return (
    <AppShell>
      <div className="min-h-screen bg-[#050505] pb-24">
        <div className="sticky top-0 z-30 backdrop-blur-xl bg-black/70 border-b border-white/5 px-4 py-3 flex items-center gap-3">
