// ---- Flagged Posts Tab ----
function FlaggedPostsTab({ userId }: { userId: string }) {
  const [flags, setFlags] = useState<FlaggedPost[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchFlags = useCallback(async () => {
    const { data } = await supabase
      .from("post_flags")
      .select("*")
      .eq("status", "pending")
      .order("created_at", { ascending: false })
      .limit(50);

    if (!data) { setLoading(false); return; }

    // Fetch post details
    const postIds = [...new Set(data.map((f: any) => f.post_id))];
    const userIds = [...new Set(data.map((f: any) => f.user_id))];

    const { data: postsData } = await supabase.from("posts").select("*").in("id", postIds);
    const postUserIds = [...new Set((postsData || []).map((p: any) => p.user_id))];
    const [{ data: profiles }, { data: reporters }] = await Promise.all([
      supabase.from("profiles").select("user_id, display_name, avatar_url").in("user_id", postUserIds.length ? postUserIds : ["_"]),
      supabase.from("profiles").select("user_id, display_name").in("user_id", userIds),
    ]);

    const profileMap = new Map(profiles?.map((p: any) => [p.user_id, p]) || []);
    const reporterMap = new Map(reporters?.map((r: any) => [r.user_id, r]) || []);
    const postMap = new Map((postsData || []).map((p: any) => [p.id, { ...p, profile: profileMap.get(p.user_id) }]));

    setFlags(data.map((f: any) => ({
      ...f,
      post: postMap.get(f.post_id),
      reporter: reporterMap.get(f.user_id),
    })));
    setLoading(false);
  }, []);

  useEffect(() => { fetchFlags(); }, [fetchFlags]);

  const handleApprove = async (flagId: string) => {
    await supabase.from("post_flags").update({ status: "approved" }).eq("id", flagId);
    setFlags(prev => prev.filter(f => f.id !== flagId));
    toast.success("Bayrak onaylandı (gönderi bırakıldı)");
  };

  const handleRemovePost = async (flagId: string, postId: string) => {
    await supabase.from("posts").delete().eq("id", postId);
    setFlags(prev => prev.filter(f => f.id !== flagId));
    toast.success("Gönderi silindi");
  };

  if (loading) return <LoadingState />;

  if (flags.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center">
        <CheckCircle className="h-12 w-12 text-neon/30 mb-3" />
        <p className="text-sm text-muted-foreground">Bekleyen bayrak yok</p>
      </div>
    );
  }

  return (
    <div className="space-y-3 px-2 pb-4">
      <p className="text-xs text-muted-foreground px-1">{flags.length} bekleyen bayrak</p>
      {flags.map(flag => (
        <Card key={flag.id} className="p-3 space-y-2 border-destructive/20">
          <div className="flex items-center justify-between">
            <Badge variant="destructive" className="text-[10px]">
              <Flag className="h-2.5 w-2.5 mr-1" /> {flag.reason}
            </Badge>
            <span className="text-[10px] text-muted-foreground">{timeAgo(flag.created_at)}</span>
          </div>

          {flag.reporter && (
            <p className="text-[10px] text-muted-foreground">
              Bildiren: <span className="font-medium text-foreground">{flag.reporter.display_name}</span>
            </p>
          )}

          {flag.post && (
            <div className="bg-muted/50 rounded-lg p-2 space-y-1">
              <div className="flex items-center gap-2">
                <Avatar className="h-6 w-6">
