// ---- All Posts Tab (Spam removal) ----
function AllPostsTab() {
  const [posts, setPosts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");

  const fetchPosts = useCallback(async () => {
    const { data } = await supabase
      .from("posts")
      .select("*")
      .order("created_at", { ascending: false })
      .limit(100);

    if (!data) { setLoading(false); return; }

    const userIds = [...new Set(data.map((p: any) => p.user_id))];
    const { data: profiles } = await supabase
      .from("profiles")
      .select("user_id, display_name, avatar_url")
      .in("user_id", userIds);

    const profileMap = new Map(profiles?.map((p: any) => [p.user_id, p]) || []);
    setPosts(data.map((p: any) => ({ ...p, profile: profileMap.get(p.user_id) })));
    setLoading(false);
  }, []);

  useEffect(() => { fetchPosts(); }, [fetchPosts]);

  const handleDelete = async (postId: string) => {
    await supabase.from("posts").delete().eq("id", postId);
    setPosts(prev => prev.filter(p => p.id !== postId));
    toast.success("Gönderi silindi");
  };

  const filtered = posts.filter(p =>
    !search || (p.content?.toLowerCase().includes(search.toLowerCase()) || p.profile?.display_name?.toLowerCase().includes(search.toLowerCase()))
  );

  if (loading) return <LoadingState />;

  return (
    <div className="space-y-3 px-2 pb-4">
      <Input
        placeholder="Gönderi veya kullanıcı ara..."
        value={search}
        onChange={e => setSearch(e.target.value)}
        className="h-8 text-xs"
      />
      <p className="text-xs text-muted-foreground px-1">{filtered.length} gönderi</p>
      {filtered.slice(0, 30).map(post => (
        <Card key={post.id} className="p-3 space-y-1.5">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Avatar className="h-6 w-6">
                <AvatarImage src={post.profile?.avatar_url || ""} />
                <AvatarFallback className="text-[8px] bg-secondary">
                  {post.profile?.display_name?.charAt(0) || "?"}
                </AvatarFallback>
              </Avatar>
              <span className="text-xs font-medium text-foreground">{post.profile?.display_name || "Anonim"}</span>
              <span className="text-[10px] text-muted-foreground">{timeAgo(post.created_at)}</span>
            </div>
            <Button size="sm" variant="ghost" className="h-7 w-7 p-0 text-destructive hover:bg-destructive/10" onClick={() => handleDelete(post.id)}>
              <Trash2 className="h-3.5 w-3.5" />
            </Button>
          </div>
          {post.content && <p className="text-xs text-muted-foreground line-clamp-2">{post.content}</p>}
          <div className="flex gap-3 text-[10px] text-muted-foreground">
            <span>❤️ {post.like_count}</span>
            <span>💬 {post.comment_count}</span>
            <span>👁 {post.view_count}</span>
          </div>
        </Card>
      ))}
