  );
}

// ---- News Management Tab ----
function NewsManagementTab() {
  const [articles, setArticles] = useState<NewsSource[]>([]);
  const [loading, setLoading] = useState(true);
  const [fetching, setFetching] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    title: "", url: "", source: "", summary: "", content: "", image_url: "",
  });
  const [saving, setSaving] = useState(false);

  const fetchArticles = useCallback(async () => {
    const { data } = await supabase
      .from("news_articles")
      .select("*")
      .order("published_at", { ascending: false })
      .limit(50);
    if (data) setArticles(data as NewsSource[]);
    setLoading(false);
  }, []);

  useEffect(() => { fetchArticles(); }, [fetchArticles]);

  const handleFetchNews = async () => {
    setFetching(true);
    try {
      const { data } = await supabase.functions.invoke("fetch-news");
      toast.success(`${data?.inserted || 0} yeni haber çekildi`);
      fetchArticles();
    } catch {
      toast.error("Haber çekme başarısız");
    }
    setFetching(false);
  };

  const handleDelete = async (id: string) => {
    await supabase.from("news_articles").delete().eq("id", id);
    setArticles(prev => prev.filter(a => a.id !== id));
    toast.success("Haber silindi");
  };

  const resetForm = () => {
    setFormData({ title: "", url: "", source: "", summary: "", content: "", image_url: "" });
    setEditingId(null);
    setShowForm(false);
  };

  const handleEdit = (article: NewsSource) => {
    setFormData({
      title: article.title,
      url: article.url,
      source: article.source,
      summary: article.summary || "",
      content: (article as any).content || "",
      image_url: article.image_url || "",
    });
    setEditingId(article.id);
    setShowForm(true);
  };

  const handleSave = async () => {
    if (!formData.title.trim() || !formData.source.trim()) return;
    setSaving(true);

    const payload = {
      title: formData.title.trim(),
      url: formData.url.trim() || `internal-${Date.now()}`,
      source: formData.source.trim(),
      summary: formData.summary.trim() || null,
      content: formData.content.trim() || null,
      image_url: formData.image_url.trim() || null,
    };

    if (editingId) {
      const { error } = await supabase
        .from("news_articles")
        .update(payload)
        .eq("id", editingId);
      if (error) { toast.error("Güncellenemedi"); setSaving(false); return; }
      toast.success("Haber güncellendi");
    } else {
      const { error } = await supabase
        .from("news_articles")
        .insert(payload);
      if (error) { toast.error("Eklenemedi"); setSaving(false); return; }
      toast.success("Haber eklendi");
    }

    resetForm();
    fetchArticles();
    setSaving(false);
  };

  if (loading) return <LoadingState />;

  return (
    <div className="space-y-3 px-2 pb-4">
      <div className="flex gap-2">
        <Button size="sm" variant="outline" className="text-xs flex-1" onClick={handleFetchNews} disabled={fetching}>
          {fetching ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : <Newspaper className="h-3 w-3 mr-1" />}
          RSS Çek
        </Button>
        <Button size="sm" variant="neon" className="text-xs" onClick={() => { resetForm(); setShowForm(true); }}>
          <Plus className="h-3 w-3 mr-1" /> Yeni Haber
        </Button>
      </div>

      {showForm && (
        <Card className="p-3 space-y-2.5 border-primary/30">
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-semibold text-foreground">
              {editingId ? "✏️ Haber Düzenle" : "📰 Yeni Haber Ekle"}
            </h3>
            <button onClick={resetForm} className="text-muted-foreground hover:text-foreground">
              <X className="h-4 w-4" />
            </button>
          </div>

          <Input
            placeholder="Başlık *"
            value={formData.title}
            onChange={e => setFormData(d => ({ ...d, title: e.target.value }))}
            className="h-8 text-xs"
          />

          <Input
            placeholder="Kaynak (örn: Rudaw, ANF) *"
            value={formData.source}
            onChange={e => setFormData(d => ({ ...d, source: e.target.value }))}
            className="h-8 text-xs"
          />

          <div className="relative">
            <Image className="absolute left-2.5 top-2 h-3.5 w-3.5 text-muted-foreground" />
            <Input
              placeholder="Görsel URL'si"
              value={formData.image_url}
              onChange={e => setFormData(d => ({ ...d, image_url: e.target.value }))}
              className="h-8 text-xs pl-8"
            />
          </div>

          {formData.image_url && (
            <img
              src={formData.image_url}
              alt="Önizleme"
              className="w-full h-28 rounded-lg object-cover border border-border"
              onError={e => (e.currentTarget.style.display = "none")}
            />
          )}

          <Textarea
            placeholder="Özet (kısa açıklama)"
            value={formData.summary}
            onChange={e => setFormData(d => ({ ...d, summary: e.target.value }))}
            className="text-xs min-h-[60px] resize-none"
            rows={2}
          />

          <Textarea
            placeholder="Tam İçerik (haber metni) — dış siteye yönlendirme yerine burada gösterilecek"
            value={formData.content}
            onChange={e => setFormData(d => ({ ...d, content: e.target.value }))}
            className="text-xs min-h-[120px]"
            rows={6}
          />

          <Input
            placeholder="Kaynak URL (opsiyonel, referans için)"
            value={formData.url}
            onChange={e => setFormData(d => ({ ...d, url: e.target.value }))}
            className="h-8 text-xs text-muted-foreground"
          />

          <Button
            size="sm"
            className="w-full text-xs"
            onClick={handleSave}
            disabled={!formData.title.trim() || !formData.source.trim() || saving}
          >
            {saving ? (
              <Loader2 className="h-3 w-3 animate-spin mr-1" />
            ) : (
              <Save className="h-3 w-3 mr-1" />
            )}
            {editingId ? "Güncelle" : "Haber Ekle"}
          </Button>
        </Card>
      )}

      <p className="text-xs text-muted-foreground px-1">{articles.length} haber</p>
      {articles.map(article => (
        <Card key={article.id} className="p-3 space-y-1.5">
          <div className="flex items-start justify-between gap-2">
            {article.image_url && (
              <img src={article.image_url} alt="" className="h-10 w-10 rounded-lg object-cover shrink-0" />
            )}
            <div className="flex-1 min-w-0">
              <p className="text-xs font-medium text-foreground line-clamp-2">{article.title}</p>
              <div className="flex items-center gap-2 mt-1">
                <Badge variant="outline" className="text-[9px]">{article.source}</Badge>
                <span className="text-[10px] text-muted-foreground flex items-center gap-0.5">
                  <Clock className="h-2.5 w-2.5" /> {timeAgo(article.published_at)}
                </span>
                {(article as any).content && (
                  <Badge variant="secondary" className="text-[8px]">İçerik ✓</Badge>
                )}
              </div>
            </div>
            <div className="flex gap-0.5 shrink-0">
              <Button size="sm" variant="ghost" className="h-7 w-7 p-0 text-primary" onClick={() => handleEdit(article)}>
                <Edit className="h-3 w-3" />
              </Button>
              <Button size="sm" variant="ghost" className="h-7 w-7 p-0 text-destructive hover:bg-destructive/10" onClick={() => handleDelete(article.id)}>
                <Trash2 className="h-3.5 w-3.5" />
              </Button>
            </div>
          </div>
        </Card>
      ))}
    </div>
  );
}

function LoadingState() {
  return (
    <div className="flex items-center justify-center py-16">
      <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
    </div>
  );
}

function timeAgo(date: string): string {
  const diff = Date.now() - new Date(date).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "şimdi";
  if (mins < 60) return `${mins}dk`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}sa`;
  const days = Math.floor(hrs / 24);
  return `${days}g`;
}

