import { createFileRoute } from "@tanstack/react-router";

/**
 * POST /api/public/lighthouse-upload
 * Body: multipart/form-data with field "file"
 * Returns: { cid, url, size, name }
 *
 * Uses LIGHTHOUSE_API_KEY (server-only) to upload to Filecoin/IPFS via
 * https://node.lighthouse.storage/api/v0/add
 */
export const Route = createFileRoute("/api/public/lighthouse-upload")({
  server: {
    handlers: {
      POST: async ({ request }) => {
        const apiKey = process.env.LIGHTHOUSE_API_KEY;
        if (!apiKey) {
          return new Response(JSON.stringify({ error: "LIGHTHOUSE_API_KEY not configured" }), {
            status: 500, headers: { "Content-Type": "application/json" },
          });
        }

        const form = await request.formData();
        const file = form.get("file");
        if (!(file instanceof File)) {
          return new Response(JSON.stringify({ error: "file required (multipart)" }), {
            status: 400, headers: { "Content-Type": "application/json" },
          });
        }
        // 200MB cap (videos allowed). Avatars/photos are normally <5MB.
        if (file.size > 200 * 1024 * 1024) {
          return new Response(JSON.stringify({ error: "file too large (max 200MB)" }), {
            status: 413, headers: { "Content-Type": "application/json" },
          });
        }

        // Try multiple Lighthouse endpoints (522s on one are common; SDK
        // also rotates between hosts). First success wins.
        const endpoints = [
          "https://upload.lighthouse.storage/api/v0/add",
          "https://node.lighthouse.storage/api/v0/add",
        ];

        let upstream: Response | null = null;
        let lastErr = "";
        for (const url of endpoints) {
          try {
            const upstreamForm = new FormData();
            upstreamForm.append("file", file, file.name);
            const ctrl = new AbortController();
            const t = setTimeout(() => ctrl.abort(), 90_000);
            const res = await fetch(url, {
              method: "POST",
              headers: { Authorization: `Bearer ${apiKey}` },
              body: upstreamForm,
              signal: ctrl.signal,
            });
            clearTimeout(t);
            if (res.ok) { upstream = res; break; }
            lastErr = `${url} → ${res.status}`;
            console.error("Lighthouse endpoint failed", lastErr);
          } catch (e: any) {
            lastErr = `${url} → ${e?.message ?? "fetch error"}`;
            console.error("Lighthouse endpoint threw", lastErr);
          }
        }

        if (!upstream) {
          return new Response(JSON.stringify({ error: `lighthouse upstream unreachable`, detail: lastErr }), {
            status: 502, headers: { "Content-Type": "application/json" },
          });
        }

        const body = (await upstream.json()) as { Hash: string; Name: string; Size: string };
        const cid = body.Hash;
        return new Response(JSON.stringify({
          cid,
          url: `https://gateway.lighthouse.storage/ipfs/${cid}`,
          size: Number(body.Size ?? file.size),
          name: body.Name ?? file.name,
        }), {
          status: 200, headers: { "Content-Type": "application/json" },
        });
      },
    },
  },
});

