import { createFileRoute } from "@tanstack/react-router";
import { supabaseAdmin } from "@/integrations/supabase/client.server";

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

interface RefreshRequest {
  client_id?: unknown;
  client_secret?: unknown;
  refresh_token?: unknown;
  grant_type?: unknown;
}

export const Route = createFileRoute("/api/public/sso/refresh")({
  server: {
    handlers: {
      OPTIONS: async () => new Response(null, { status: 204, headers: CORS }),
      POST: async ({ request }) => {
        let body: RefreshRequest = {};
        const ct = request.headers.get("content-type") ?? "";
        try {
          if (ct.includes("application/json")) {
            body = (await request.json()) as RefreshRequest;
          } else {
            const fd = await request.formData();
            body = Object.fromEntries(fd.entries()) as RefreshRequest;
          }
        } catch {
          return Response.json({ error: "invalid_request" }, { status: 400, headers: CORS });
        }

        const client_id = typeof body.client_id === "string" ? body.client_id : "";
        const client_secret = typeof body.client_secret === "string" ? body.client_secret : "";
        const refresh_token = typeof body.refresh_token === "string" ? body.refresh_token : "";
        const grant_type = typeof body.grant_type === "string" ? body.grant_type : "refresh_token";

        if (grant_type !== "refresh_token") {
          return Response.json({ error: "unsupported_grant_type" }, { status: 400, headers: CORS });
        }
        if (!client_id || !client_secret || !refresh_token) {
          return Response.json({ error: "invalid_request" }, { status: 400, headers: CORS });
        }

        const { data, error } = await supabaseAdmin.rpc("kurdid_sso_refresh_token", {
          _client_id: client_id,
          _client_secret: client_secret,
          _refresh_token: refresh_token,
        });

        if (error || !data || (Array.isArray(data) && data.length === 0)) {
          return Response.json(
            { error: "invalid_grant", error_description: error?.message ?? "refresh_failed" },
            { status: 400, headers: CORS }
          );
        }

        const row = (Array.isArray(data) ? data[0] : data) as {
          access_token: string;
          refresh_token: string;
          expires_at: string;
          refresh_expires_at: string;
          scopes: string[];
        };

        return Response.json(
          {
            access_token: row.access_token,
            refresh_token: row.refresh_token,
            token_type: "Bearer",
            expires_at: row.expires_at,
            refresh_expires_at: row.refresh_expires_at,
            scope: row.scopes.join(" "),
          },
          { status: 200, headers: { ...CORS, "Cache-Control": "no-store" } }
        );
      },
    },
  },
});

