import { createFileRoute } from "@tanstack/react-router";
import { supabaseAdmin } from "@/integrations/supabase/client.server";

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

interface RevokeRequest {
  client_id?: unknown;
  client_secret?: unknown;
  token?: unknown;
  token_type_hint?: unknown;
}

export const Route = createFileRoute("/api/public/sso/revoke")({
  server: {
    handlers: {
      OPTIONS: async () => new Response(null, { status: 204, headers: CORS }),
      POST: async ({ request }) => {
        let body: RevokeRequest = {};
        const ct = request.headers.get("content-type") ?? "";
        try {
          if (ct.includes("application/json")) {
            body = (await request.json()) as RevokeRequest;
          } else {
            const fd = await request.formData();
            body = Object.fromEntries(fd.entries()) as RevokeRequest;
          }
        } catch {
          return Response.json({ error: "invalid_request" }, { status: 400, headers: CORS });
        }

        const client_id = typeof body.client_id === "string" ? body.client_id : "";
        const client_secret = typeof body.client_secret === "string" ? body.client_secret : "";
        const token = typeof body.token === "string" ? body.token : "";
        const hint = typeof body.token_type_hint === "string" ? body.token_type_hint : "access_token";
        const tokenType = hint === "refresh_token" ? "refresh_token" : "access_token";

        if (!client_id || !client_secret || !token) {
          return Response.json({ error: "invalid_request" }, { status: 400, headers: CORS });
        }

        const { error } = await supabaseAdmin.rpc("kurdid_sso_revoke_token", {
          _client_id: client_id,
          _client_secret: client_secret,
          _token: token,
          _token_type: tokenType,
        });

        if (error) {
          // RFC 7009: only client auth failures should surface; other errors return 200.
          if (error.message?.includes("invalid_client")) {
            return Response.json({ error: "invalid_client" }, { status: 401, headers: CORS });
          }
        }

        // Per RFC 7009 always return 200 on successful revocation
        return new Response(null, { status: 200, headers: { ...CORS, "Cache-Control": "no-store" } });
      },
    },
  },
});

