import { createFileRoute } from "@tanstack/react-router";
import { supabaseAdmin } from "@/integrations/supabase/client.server";

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Authorization, Content-Type",
};

export const Route = createFileRoute("/api/public/sso/userinfo")({
  server: {
    handlers: {
      OPTIONS: async () => new Response(null, { status: 204, headers: CORS }),
      GET: async ({ request }) => {
        const auth = request.headers.get("authorization") ?? "";
        const token = auth.toLowerCase().startsWith("bearer ") ? auth.slice(7).trim() : "";
        if (!token) {
          return Response.json({ error: "invalid_token" }, { status: 401, headers: CORS });
        }

        const { data, error } = await supabaseAdmin.rpc("kurdid_sso_userinfo", {
          _access_token: token,
        });

        if (error || !data || (Array.isArray(data) && data.length === 0)) {
          return Response.json(
            { error: "invalid_token", error_description: error?.message ?? "token_invalid" },
            { status: 401, headers: CORS }
          );
        }

        const row = (Array.isArray(data) ? data[0] : data) as {
          sub: string;
          kurd_id: string | null;
          display_name: string | null;
          username: string | null;
          avatar_url: string | null;
          city: string | null;
          is_kyc_verified: boolean;
          is_constitutional_signatory: boolean;
          scopes: string[];
        };

        return Response.json(
          {
            sub: row.sub,
            kurd_id: row.kurd_id,
            name: row.display_name,
            preferred_username: row.username,
            picture: row.avatar_url,
            city: row.city,
            kyc_verified: row.is_kyc_verified,
            constitutional_signatory: row.is_constitutional_signatory,
            scope: row.scopes.join(" "),
          },
          { status: 200, headers: { ...CORS, "Cache-Control": "no-store" } }
        );
      },
    },
  },
});

