/**
 * GET /api/public/wallet/pkpass?kurdId=+777XXXXXXXX
 *
 * Apple Wallet pass endpoint stub. A real .pkpass requires:
 *   - Apple Developer Pass Type ID + WWDR cert chain
 *   - Server-side signing with PKCS#7 (forge / node-forge in a Node host)
 *
 * Cloudflare Workers cannot run node-forge crypto for full pass signing
 * out of the box, so this endpoint returns a structured 501 with a
 * fallback link the client can use (web pass / share). When the user
 * provisions an Apple Pass Type ID, this handler can be upgraded to
 * stream the signed pass.
 */
import { createFileRoute } from "@tanstack/react-router";

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
} as const;

export const Route = createFileRoute("/api/public/wallet/pkpass")({
  server: {
    handlers: {
      OPTIONS: async () =>
        new Response(null, { status: 204, headers: CORS }),

      GET: async ({ request }) => {
        const url = new URL(request.url);
        const kurdId = (url.searchParams.get("kurdId") ?? "").trim();

        if (!kurdId) {
          return new Response(
            JSON.stringify({ error: "kurdId is required" }),
            {
              status: 400,
              headers: { "Content-Type": "application/json", ...CORS },
            },
          );
        }

        // Pass payload (front-end uses this to render a web fallback card)
        const passJson = {
          formatVersion: 1,
          passTypeIdentifier: "pass.world.jiyan.kurdid",
          organizationName: "Jiyan Sovereign",
          description: "Kurd-ID Sovereign Identity",
          serialNumber: kurdId,
          generic: {
            primaryFields: [
              { key: "id", label: "Kurd-ID", value: kurdId },
            ],
            secondaryFields: [
              { key: "type", label: "Type", value: "Sovereign" },
            ],
            backFields: [
              {
                key: "url",
                label: "Profile",
                value: `https://jiyan.world/u/${encodeURIComponent(kurdId)}`,
              },
            ],
          },
          backgroundColor: "rgb(10, 8, 4)",
          foregroundColor: "rgb(245, 200, 80)",
          labelColor: "rgb(255, 236, 180)",
        };

        return new Response(
          JSON.stringify({
            ok: false,
            reason: "pkpass_signing_not_configured",
            message:
              "Apple Wallet imzalama sertifikası henüz yapılandırılmadı. " +
              "Bu uç nokta hazır — bir Apple Pass Type ID eklendikten sonra " +
              "imzalı .pkpass döndürecek.",
            fallbackUrl: `https://jiyan.world/kurd-id?focus=${encodeURIComponent(kurdId)}`,
            pass: passJson,
          }),
          {
            status: 501,
            headers: {
              "Content-Type": "application/json",
              "Cache-Control": "no-store",
              ...CORS,
            },
          },
        );
      },
    },
  },
});

