import { createFileRoute } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { useState, useRef, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useAudioRooms, AUDIO_CATEGORIES } from "@/hooks/useAudioRooms";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
  Mic, Plus, Play, Pause, Users, Loader2, Radio, Podcast,
  Upload, Trash2, Clock, Headphones, Filter,
} from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/audio-rooms")({
  component: AudioRoomsPage,
  head: () => ({
    meta: [
      { title: "Sesli Odalar – Jiyan Europe" },
      { name: "description", content: "Podcast dinle, sesli oda oluştur ve topluluğunla sohbet et." },
    ],
  }),
});

function AudioRoomsPage() {
  const { user } = useAuth();
  const { rooms, loading, createRoom, joinRoom, deleteRoom } = useAudioRooms(user?.id);
  const [showCreate, setShowCreate] = useState(false);
  const [filterCat, setFilterCat] = useState("all");
  const [filterType, setFilterType] = useState<"all" | "podcast" | "live">("all");

  const filtered = rooms.filter((r) => {
    if (filterCat !== "all" && r.category !== filterCat) return false;
    if (filterType !== "all" && r.room_type !== filterType) return false;
    return true;
  });

  return (
    <AppShell>
      <div className="p-4 pb-24 space-y-4">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-foreground">🎙️ Sesli Odalar</h1>
            <p className="text-xs text-muted-foreground">Podcast & canlı sesli sohbet</p>
          </div>
          {user && (
            <Dialog open={showCreate} onOpenChange={setShowCreate}>
              <DialogTrigger asChild>
                <Button size="sm" className="bg-neon text-neon-foreground hover:bg-neon/90">
                  <Plus className="h-4 w-4 mr-1" /> Oda Oluştur
                </Button>
              </DialogTrigger>
              <DialogContent className="bg-card border-border max-h-[85vh] overflow-y-auto">
                <DialogHeader>
                  <DialogTitle className="text-foreground">Yeni Sesli Oda</DialogTitle>
                  <DialogDescription className="text-muted-foreground text-xs">Podcast yükle veya canlı oda oluştur</DialogDescription>
                </DialogHeader>
                <CreateRoomForm userId={user.id} onCreate={(data) => { createRoom(data); setShowCreate(false); }} />
              </DialogContent>
            </Dialog>
          )}
        </div>

        {/* Filters */}
        <div className="flex gap-2 overflow-x-auto pb-1">
          <Badge
            variant={filterType === "all" ? "default" : "outline"}
            className="cursor-pointer shrink-0"
            onClick={() => setFilterType("all")}
          >
            Tümü
          </Badge>
          <Badge
            variant={filterType === "podcast" ? "default" : "outline"}
            className="cursor-pointer shrink-0"
            onClick={() => setFilterType("podcast")}
          >
            <Podcast className="h-3 w-3 mr-1" /> Podcast
          </Badge>
          <Badge
            variant={filterType === "live" ? "default" : "outline"}
            className="cursor-pointer shrink-0"
            onClick={() => setFilterType("live")}
          >
            <Radio className="h-3 w-3 mr-1" /> Canlı
          </Badge>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-1">
          <Badge variant={filterCat === "all" ? "default" : "outline"} className="cursor-pointer shrink-0" onClick={() => setFilterCat("all")}>
            Tümü
          </Badge>
          {AUDIO_CATEGORIES.map((c) => (
            <Badge key={c.value} variant={filterCat === c.value ? "default" : "outline"} className="cursor-pointer shrink-0" onClick={() => setFilterCat(c.value)}>
              {c.label}
            </Badge>
          ))}
        </div>

        {/* Room list */}
        {loading ? (
          <div className="flex justify-center py-12"><Loader2 className="h-6 w-6 animate-spin text-neon" /></div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-12 text-muted-foreground">
            <Mic className="h-12 w-12 mx-auto mb-3 opacity-30" />
            <p>Henüz sesli oda yok</p>
            <p className="text-xs mt-1">İlk odayı sen oluştur!</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filtered.map((room) => (
              <AudioRoomCard
                key={room.id}
                room={room}
                userId={user?.id}
                onJoin={() => joinRoom(room.id)}
                onDelete={() => deleteRoom(room.id)}
              />
            ))}
          </div>
        )}
      </div>
    </AppShell>
  );
}

/* ─── Room Card ─── */
function AudioRoomCard({ room, userId, onJoin, onDelete }: {
  room: ReturnType<typeof useAudioRooms>["rooms"][0];
  userId?: string;
  onJoin: () => void;
  onDelete: () => void;
}) {
  const [profile, setProfile] = useState<{ display_name: string; avatar_url: string | null } | null>(null);
  const [playing, setPlaying] = useState(false);
  const [participants, setParticipants] = useState(0);
  const audioRef = useRef<HTMLAudioElement>(null);

  useEffect(() => {
    supabase.from("profiles").select("display_name, avatar_url").eq("user_id", room.creator_id).single()
      .then(({ data }) => { if (data) setProfile(data); });
    supabase.from("audio_room_participants").select("id", { count: "exact", head: true }).eq("room_id", room.id)
      .then(({ count }) => setParticipants(count || 0));
  }, [room.creator_id, room.id]);

  const togglePlay = () => {
    if (!audioRef.current || !room.audio_url) return;
    if (playing) { audioRef.current.pause(); }
    else { audioRef.current.play(); onJoin(); }
    setPlaying(!playing);
  };

  const formatDuration = (s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m}:${sec.toString().padStart(2, "0")}`;
  };

  const isCreator = userId === room.creator_id;
  const catLabel = AUDIO_CATEGORIES.find((c) => c.value === room.category)?.label || room.category;

  return (
    <Card className="overflow-hidden border-border bg-card/80 backdrop-blur-sm">
      {room.cover_url && (
        <div className="h-32 w-full bg-muted">
          <img src={room.cover_url} alt={room.title} className="h-full w-full object-cover" />
        </div>
      )}
      <div className="p-4 space-y-3">
        <div className="flex items-start justify-between gap-2">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1">
              {room.is_live && (
                <Badge className="bg-destructive text-destructive-foreground text-[10px] px-1.5 py-0 animate-pulse">
                  <Radio className="h-2.5 w-2.5 mr-0.5" /> CANLI
                </Badge>
              )}
              {room.room_type === "podcast" && (
                <Badge variant="outline" className="text-[10px] px-1.5 py-0">
                  <Podcast className="h-2.5 w-2.5 mr-0.5" /> Podcast
                </Badge>
              )}
              <Badge variant="secondary" className="text-[10px] px-1.5 py-0">{catLabel}</Badge>
            </div>
            <h3 className="font-semibold text-foreground truncate">{room.title}</h3>
            {room.description && (
              <p className="text-xs text-muted-foreground line-clamp-2 mt-0.5">{room.description}</p>
            )}
          </div>

          {/* Play button for podcasts */}
          {room.room_type === "podcast" && room.audio_url && (
            <button onClick={togglePlay} className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-neon text-neon-foreground shadow-lg transition-transform active:scale-95">
              {playing ? <Pause className="h-5 w-5" /> : <Play className="h-5 w-5 ml-0.5" />}
            </button>
          )}
        </div>

        {room.audio_url && <audio ref={audioRef} src={room.audio_url} preload="metadata" onEnded={() => setPlaying(false)} />}

        {/* Meta row */}
        <div className="flex items-center justify-between text-xs text-muted-foreground">
          <div className="flex items-center gap-3">
            {profile && (
              <div className="flex items-center gap-1.5">
                <Avatar className="h-5 w-5">
                  <AvatarImage src={profile.avatar_url || undefined} />
                  <AvatarFallback className="text-[8px] bg-surface">{profile.display_name[0]}</AvatarFallback>
                </Avatar>
                <span className="truncate max-w-[80px]">{profile.display_name}</span>
              </div>
            )}
            <span className="flex items-center gap-0.5"><Users className="h-3 w-3" />{participants}</span>
            {room.duration && <span className="flex items-center gap-0.5"><Clock className="h-3 w-3" />{formatDuration(room.duration)}</span>}
          </div>

          <div className="flex items-center gap-1">
            {room.room_type === "live" && (
              <Button size="sm" variant="outline" className="h-7 text-xs border-neon text-neon" onClick={onJoin}>
                <Headphones className="h-3 w-3 mr-1" /> Katıl
              </Button>
            )}
            {isCreator && (
              <Button size="sm" variant="ghost" className="h-7 w-7 p-0 text-destructive" onClick={onDelete}>
                <Trash2 className="h-3.5 w-3.5" />
              </Button>
            )}
          </div>
        </div>
      </div>
    </Card>
  );
}

/* ─── Create Room Form ─── */
function CreateRoomForm({ userId, onCreate }: {
  userId: string;
  onCreate: (data: Parameters<ReturnType<typeof useAudioRooms>["createRoom"]>[0]) => void;
}) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("general");
  const [roomType, setRoomType] = useState("podcast");
  const [city, setCity] = useState("Arnhem");
  const [uploading, setUploading] = useState(false);
  const [audioUrl, setAudioUrl] = useState("");
  const [audioDuration, setAudioDuration] = useState<number | undefined>();
  const [coverUrl, setCoverUrl] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);
  const coverRef = useRef<HTMLInputElement>(null);

  const handleAudioUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 50 * 1024 * 1024) { toast.error("Dosya 50MB'dan küçük olmalı"); return; }

    setUploading(true);
    const path = `${userId}/audio_${Date.now()}.${file.name.split(".").pop()}`;
    const { error } = await supabase.storage.from("audio-media").upload(path, file, { contentType: file.type });
    if (error) { toast.error("Yükleme başarısız"); setUploading(false); return; }

    const { data: urlData } = supabase.storage.from("audio-media").getPublicUrl(path);
    setAudioUrl(urlData.publicUrl);

    // Get duration
    const audio = new Audio(urlData.publicUrl);
    audio.addEventListener("loadedmetadata", () => {
      setAudioDuration(Math.round(audio.duration));
    });

    setUploading(false);
    toast.success("Ses dosyası yüklendi");
  };

  const handleCoverUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { toast.error("Kapak 5MB'dan küçük olmalı"); return; }

    const path = `${userId}/cover_${Date.now()}.${file.name.split(".").pop()}`;
    const { error } = await supabase.storage.from("audio-media").upload(path, file, { contentType: file.type });
    if (error) { toast.error("Yükleme başarısız"); return; }

    const { data: urlData } = supabase.storage.from("audio-media").getPublicUrl(path);
    setCoverUrl(urlData.publicUrl);
  };

  const handleSubmit = () => {
    if (!title.trim()) { toast.error("Başlık gerekli"); return; }
    if (roomType === "podcast" && !audioUrl) { toast.error("Podcast için ses dosyası yükleyin"); return; }

    onCreate({
      title: title.trim(),
      description: description.trim() || undefined,
      category,
      room_type: roomType,
      city,
      audio_url: audioUrl || undefined,
      cover_url: coverUrl || undefined,
      duration: audioDuration,
    });
  };

  return (
    <div className="space-y-4">
      <div className="flex gap-2">
        <Button
          type="button"
          variant={roomType === "podcast" ? "default" : "outline"}
          className="flex-1"
          onClick={() => setRoomType("podcast")}
        >
          <Podcast className="h-4 w-4 mr-1" /> Podcast
        </Button>
        <Button
          type="button"
          variant={roomType === "live" ? "default" : "outline"}
          className="flex-1"
          onClick={() => setRoomType("live")}
        >
          <Radio className="h-4 w-4 mr-1" /> Canlı Oda
        </Button>
      </div>

      <Input placeholder="Oda başlığı *" value={title} onChange={(e) => setTitle(e.target.value)} className="bg-surface border-border" />
      <Textarea placeholder="Açıklama (isteğe bağlı)" value={description} onChange={(e) => setDescription(e.target.value)} className="bg-surface border-border" rows={2} />

      <div className="grid grid-cols-2 gap-2">
        <Select value={category} onValueChange={setCategory}>
          <SelectTrigger className="bg-surface border-border"><SelectValue /></SelectTrigger>
          <SelectContent>
            {AUDIO_CATEGORIES.map((c) => (
              <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Input placeholder="Şehir" value={city} onChange={(e) => setCity(e.target.value)} className="bg-surface border-border" />
      </div>

      {/* Cover image */}
      <div>
        <input ref={coverRef} type="file" accept="image/*" className="hidden" onChange={handleCoverUpload} />
        {coverUrl ? (
          <div className="relative h-24 rounded-lg overflow-hidden">
            <img src={coverUrl} className="h-full w-full object-cover" alt="cover" />
            <button onClick={() => setCoverUrl("")} className="absolute top-1 right-1 bg-background/80 rounded-full p-1"><Trash2 className="h-3 w-3" /></button>
          </div>
        ) : (
          <Button type="button" variant="outline" className="w-full" onClick={() => coverRef.current?.click()}>
            <Upload className="h-4 w-4 mr-1" /> Kapak Resmi Ekle
          </Button>
        )}
      </div>

      {/* Audio file (for podcast) */}
      {roomType === "podcast" && (
        <div>
          <input ref={fileRef} type="file" accept="audio/*" className="hidden" onChange={handleAudioUpload} />
          {audioUrl ? (
            <div className="flex items-center gap-2 p-2 rounded-lg bg-surface border border-border">
              <Mic className="h-4 w-4 text-neon" />
              <span className="text-xs text-foreground flex-1 truncate">Ses yüklendi</span>
              {audioDuration && <span className="text-xs text-muted-foreground">{Math.floor(audioDuration / 60)}:{(audioDuration % 60).toString().padStart(2, "0")}</span>}
              <button onClick={() => { setAudioUrl(""); setAudioDuration(undefined); }}><Trash2 className="h-3 w-3 text-destructive" /></button>
            </div>
          ) : (
            <Button type="button" variant="outline" className="w-full" onClick={() => fileRef.current?.click()} disabled={uploading}>
              {uploading ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Upload className="h-4 w-4 mr-1" />}
              Ses Dosyası Yükle *
            </Button>
          )}
        </div>
      )}

      {roomType === "live" && (
        <p className="text-xs text-muted-foreground bg-surface p-3 rounded-lg">
          ⚠️ Canlı sesli odalar şu an sadece listeleme modundadır. Gerçek zamanlı ses iletimi yakında eklenecek.
        </p>
      )}

      <Button className="w-full bg-neon text-neon-foreground hover:bg-neon/90" onClick={handleSubmit} disabled={uploading}>
        <Plus className="h-4 w-4 mr-1" /> Oda Oluştur
      </Button>
    </div>
  );
}

