function CreateDealForm({ user, onCreated }: { user: any; onCreated: () => void }) {
  const [title, setTitle] = useState("");
  const [brief, setBrief] = useState("");
  const [category, setCategory] = useState("general");
  const [budget, setBudget] = useState("50");
  const [minFollowers, setMinFollowers] = useState("0");
  const [minViews, setMinViews] = useState("0");
  const [busy, setBusy] = useState(false);

  const submit = async () => {
    if (!user) return toast.error("Önce giriş yap");
    if (!title.trim() || !brief.trim()) return toast.error("Başlık ve brief gerekli");
    const b = Number(budget);
    if (isNaN(b) || b < 5) return toast.error("Min bütçe 5 DC");

    setBusy(true);
    try {
      const res = await createBrandDeal({
        title: title.trim(),
        brief: brief.trim(),
        category,
        budget_dc: b,
        min_followers: Number(minFollowers) || 0,
        min_views: Number(minViews) || 0,
      });
      if (res.success) {
        toast.success("İlan açıldı 🎯");
        setTitle(""); setBrief(""); setBudget("50");
        onCreated();
      } else {
        toast.error(res.error ?? "Hata");
      }
    } catch (e: any) {
      toast.error(e?.message ?? "Hata");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="space-y-3">
      <div>
        <Label htmlFor="title" className="text-xs">Başlık</Label>
        <Input id="title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Örn: 15s ürün tanıtım videosu" maxLength={100} />
      </div>
      <div>
        <Label htmlFor="brief" className="text-xs">Brief</Label>
        <Textarea id="brief" value={brief} onChange={(e) => setBrief(e.target.value)} placeholder="Ne istediğini detaylı anlat…" rows={4} maxLength={1000} />
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div>
          <Label htmlFor="cat" className="text-xs">Kategori</Label>
          <select
            id="cat"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            className="w-full h-10 rounded-md border border-border bg-background px-3 text-sm"
          >
            <option value="general">Genel</option>
            <option value="food">Yemek</option>
            <option value="fashion">Moda</option>
            <option value="tech">Teknoloji</option>
            <option value="education">Eğitim</option>
            <option value="lifestyle">Yaşam</option>
          </select>
        </div>
        <div>
          <Label htmlFor="budget" className="text-xs">Bütçe (DC)</Label>
          <Input id="budget" type="number" min={5} value={budget} onChange={(e) => setBudget(e.target.value)} />
        </div>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div>
          <Label htmlFor="mf" className="text-xs">Min takipçi</Label>
          <Input id="mf" type="number" min={0} value={minFollowers} onChange={(e) => setMinFollowers(e.target.value)} />
        </div>
        <div>
          <Label htmlFor="mv" className="text-xs">Min izlenme/30g</Label>
          <Input id="mv" type="number" min={0} value={minViews} onChange={(e) => setMinViews(e.target.value)} />
        </div>
      </div>
      <p className="text-[10px] text-muted-foreground">
        Bütçen anlaşma yapılana kadar cüzdanında kilitli kalır. Anlaşma sonrası %5 platform komisyonu kesilir, kalan yaratıcıya ödenir.
      </p>
      <Button
        onClick={submit}
        disabled={busy}
        className="w-full bg-gradient-to-r from-amber-400 to-amber-600 text-black font-bold"
      >
        {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : "İlanı Yayınla"}
      </Button>
    </div>
  );
}

function DealDetailDialog({
  deal,
  currentUserId,
  onOpenChange,
  onChanged,
}: {
  deal: BrandDeal | null;
  currentUserId?: string;
  onOpenChange: (o: boolean) => void;
  onChanged: () => void;
}) {
  const [pitch, setPitch] = useState("");
  const [proposed, setProposed] = useState("");
  const [busy, setBusy] = useState(false);
  const isOwner = deal && currentUserId === deal.brand_id;
  const { apps, refresh } = useDealApplications(isOwner ? deal?.id ?? null : null);

  if (!deal) return null;

  const apply = async () => {
    if (!currentUserId) return toast.error("Giriş yap");
    if (!pitch.trim()) return toast.error("Tanıtım metni gerekli");
    const p = Number(proposed);
    if (isNaN(p) || p <= 0 || p > deal.budget_dc) return toast.error(`Teklif 1-${deal.budget_dc} DC arası`);
    setBusy(true);
    try {
      const res = await applyToBrandDeal(deal.id, pitch.trim(), p);
      if (res.success) {
        toast.success("Başvurun gönderildi 📩");
        onOpenChange(false);
        onChanged();
      } else {
        toast.error(res.error ?? "Hata");
      }
    } finally {
      setBusy(false);
    }
  };

  const accept = async (appId: string) => {
    setBusy(true);
    try {
      const res = await acceptDealApplication(appId);
      if (res.success) {
        toast.success(`Anlaşma onaylandı! ${res.net} DC ödendi.`);
        refresh();
        onChanged();
      } else {
        toast.error(res.error ?? "Hata");
      }
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog open={!!deal} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-amber-400 flex items-center gap-2">
            <Briefcase className="h-5 w-5" />
            {deal.title}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-3">
          <div className="rounded-xl bg-amber-500/10 border border-amber-500/20 p-3">
            <p className="text-xs text-amber-300/80 mb-1">{deal.brand?.display_name ?? "İşletme"} · {deal.category}</p>
            <p className="text-sm text-foreground whitespace-pre-wrap">{deal.brief}</p>
          </div>

          <div className="grid grid-cols-3 gap-2 text-center">
            <div className="rounded-lg bg-surface p-2 border border-border">
              <Coins className="h-4 w-4 text-amber-400 mx-auto mb-1" />
              <p className="text-sm font-bold text-amber-300">{deal.budget_dc}</p>
              <p className="text-[9px] text-muted-foreground">DC bütçe</p>
            </div>
            <div className="rounded-lg bg-surface p-2 border border-border">
              <Users className="h-4 w-4 text-muted-foreground mx-auto mb-1" />
              <p className="text-sm font-bold">{deal.min_followers.toLocaleString()}</p>
              <p className="text-[9px] text-muted-foreground">Min takipçi</p>
            </div>
            <div className="rounded-lg bg-surface p-2 border border-border">
              <Eye className="h-4 w-4 text-muted-foreground mx-auto mb-1" />
              <p className="text-sm font-bold">{deal.min_views.toLocaleString()}</p>
              <p className="text-[9px] text-muted-foreground">Min izlenme</p>
            </div>
          </div>

          {isOwner ? (
            <div>
              <p className="text-xs font-bold text-foreground mb-2">Başvurular ({apps.length})</p>
              {apps.length === 0 ? (
                <p className="text-xs text-muted-foreground py-3 text-center">Henüz başvuru yok</p>
              ) : (
                <div className="space-y-2">
                  {apps.map((a) => (
                    <div key={a.id} className="rounded-lg border border-border p-3">
                      <div className="flex items-center gap-2 mb-2">
                        <Avatar className="h-7 w-7">
                          <AvatarImage src={a.creator?.avatar_url ?? undefined} />
                          <AvatarFallback className="text-[10px]">{a.creator?.display_name?.[0] ?? "?"}</AvatarFallback>
                        </Avatar>
                        <div className="flex-1 min-w-0">
                          <p className="text-xs font-bold truncate">{a.creator?.display_name ?? "Anonim"}</p>
                          {a.creator?.kurd_id && <p className="text-[9px] font-mono text-amber-400/70">{a.creator.kurd_id}</p>}
                        </div>
                        <span className="text-amber-300 text-sm font-bold">{a.proposed_dc} DC</span>
                      </div>
                      <p className="text-[11px] text-muted-foreground line-clamp-3">{a.pitch}</p>
                      {a.status === "pending" && deal.status === "open" && (
                        <button
                          onClick={() => accept(a.id)}
                          disabled={busy}
                          className="mt-2 w-full h-9 rounded-lg bg-amber-500 text-black text-xs font-bold flex items-center justify-center gap-1 active:scale-95"
                        >
                          <Check className="h-3.5 w-3.5" /> Bu yaratıcıyı seç
                        </button>
                      )}
                      {a.status === "accepted" && (
                        <p className="mt-2 text-[10px] text-amber-300 font-bold flex items-center gap-1"><Check className="h-3 w-3" /> Onaylandı</p>
                      )}
                      {a.status === "rejected" && (
                        <p className="mt-2 text-[10px] text-muted-foreground flex items-center gap-1"><X className="h-3 w-3" /> Reddedildi</p>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          ) : deal.status === "open" ? (
            <>
              <div>
                <Label className="text-xs">Tanıtım metnin (pitch)</Label>
                <Textarea value={pitch} onChange={(e) => setPitch(e.target.value)} placeholder="Neden seni seçmeli? Örnek içerikler…" rows={3} maxLength={500} />
              </div>
              <div>
                <Label className="text-xs">Teklifin (DC, max {deal.budget_dc})</Label>
                <Input type="number" min={1} max={deal.budget_dc} value={proposed} onChange={(e) => setProposed(e.target.value)} />
              </div>
              <Button onClick={apply} disabled={busy} className="w-full bg-gradient-to-r from-amber-400 to-amber-600 text-black font-bold">
                {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <><Send className="h-4 w-4 mr-1" /> Başvur</>}
              </Button>
            </>
          ) : (
            <p className="text-xs text-center text-muted-foreground py-2">Bu ilan {deal.status === "in_progress" ? "anlaşıldı" : "kapatıldı"}.</p>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

