function ChatPage() {
  const { user, loading: authLoading } = useAuth();
  // Read invite token from URL query (?join=...) without strict typing
  const joinToken = typeof window !== "undefined"
    ? new URLSearchParams(window.location.search).get("join") || undefined
    : undefined;
  const [activeRoomId, setActiveRoomId] = useState<string | null>(null);
  const [locked, setLocked] = useState(false);
  const joinHandledRef = useRef(false);

  useEffect(() => {
    if (typeof window !== "undefined" && localStorage.getItem("jiyan_chat_pin")) {
      setLocked(true);
    }
  }, []);

  // Listen for "open this room" events (e.g. from forum topic clicks)
  useEffect(() => {
    if (typeof window === "undefined") return;
    const handler = (e: Event) => {
      const detail = (e as CustomEvent<{ roomId?: string }>).detail;
      if (detail?.roomId) setActiveRoomId(detail.roomId);
    };
    window.addEventListener("jiyan:open-room", handler);
    return () => window.removeEventListener("jiyan:open-room", handler);
  }, []);

  // Auto-join via invite token (?join=...)
  useEffect(() => {
    if (!joinToken || !user || joinHandledRef.current) return;
    joinHandledRef.current = true;
    (async () => {
      try {
        const result = await joinChatViaToken(joinToken);
        if (result.success && result.room_id) {
          toast.success("Gruba katıldın");
          setActiveRoomId(result.room_id);
        } else {
          toast.error(result.error || "Davet bağlantısı geçersiz");
        }
      } catch {
        toast.error("Davete katılınamadı");
      } finally {
        // strip the token from the URL so refresh doesn't retry
        if (typeof window !== "undefined") {
          const url = new URL(window.location.href);
          url.searchParams.delete("join");
          window.history.replaceState({}, "", url.toString());
        }
      }
    })();
  }, [joinToken, user]);

  if (authLoading) {
    return (
      <AppShell>
        <div className="flex items-center justify-center pt-32">
          <div className="h-8 w-8 animate-spin rounded-full border-2 border-neon border-t-transparent" />
        </div>
      </AppShell>
    );
  }

  if (!user) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center px-4 pt-20 text-center">
          <MessageCircle className="h-12 w-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground text-sm mb-4">Giriş yaparak sohbete başla</p>
          <Button variant="neon" asChild>
            <Link to="/login">Giriş Yap</Link>
          </Button>
        </div>
      </AppShell>
    );
  }

  if (locked) {
    return <ChatLockScreen onUnlock={() => setLocked(false)} />;
  }

  if (activeRoomId) {
    return (
      <AppShell>
        <ChatView roomId={activeRoomId} userId={user.id} onBack={() => setActiveRoomId(null)} />
      </AppShell>
    );
  }

  return (
    <AppShell>
      <ChatList userId={user.id} onSelectRoom={setActiveRoomId} />
    </AppShell>
  );
}

/* ─── Helpers ─── */

function timeAgo(dateStr: string) {
  const now = new Date();
  const d = new Date(dateStr);
  const diff = now.getTime() - d.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "şimdi";
  if (mins < 60) return `${mins}dk`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  const days = Math.floor(hours / 24);
  if (days === 1) return "dün";
  if (days < 7) return `${days}g`;
  return d.toLocaleDateString([], { day: "numeric", month: "short" });
}

