  const { rooms: audioRooms, loading: audioLoading } = useAudioRooms(userId);
  const { storyGroups, createStory, markViewed } = useStories(userId);
  const [searchQuery, setSearchQuery] = useState("");
  const [showSearch, setShowSearch] = useState(false);
  const [activeTab, setActiveTab] = useState<"all" | "direct" | "groups" | "channels" | "events" | "audio" | "contacts">("all");
  const { friends, loading: friendsLoading, addFriend, removeFriend, searchByKurdId, searchByPhone } = useFriends(userId);
  const [contactSearch, setContactSearch] = useState("");
  const [contactResults, setContactResults] = useState<any[]>([]);
  const [contactSearching, setContactSearching] = useState(false);
  const [showCreate, setShowCreate] = useState(false);
  const [showChannelCreate, setShowChannelCreate] = useState(false);
  const [groupName, setGroupName] = useState("");
  const [groupCity, setGroupCity] = useState("Arnhem");
  const [showUserSearch, setShowUserSearch] = useState(false);
  const [userSearchQuery, setUserSearchQuery] = useState("");
  const [userResults, setUserResults] = useState<any[]>([]);
  const [searching, setSearching] = useState(false);
  const [dmProfiles, setDmProfiles] = useState<Record<string, { display_name: string; avatar_url: string | null; is_online: boolean; kurd_id: string | null; username: string | null; is_premium: boolean; last_seen: string | null }>>({});
  const [showFabMenu, setShowFabMenu] = useState(false);

  // Fetch DM partner profiles (with kurd_id, username, premium status)
  useEffect(() => {
    const dmRooms = rooms.filter((r) => r.type === "direct");
    dmRooms.forEach(async (room) => {
      if (dmProfiles[room.id]) return;
      const { data: members } = await supabase
        .from("chat_members")
        .select("user_id")
        .eq("room_id", room.id)
        .neq("user_id", userId);
      if (members && members.length > 0) {
        const { data: profile } = await supabase
          .from("profiles")
          .select("display_name, avatar_url, is_online, kurd_id, username, is_premium, last_seen")
          .eq("user_id", members[0].user_id)
          .single();
        if (profile) {
          setDmProfiles((prev) => ({ ...prev, [room.id]: profile }));
        }
      }
    });
  }, [rooms, userId]);

  const filtered = rooms.filter((r) => {
    const name = r.type === "direct" ? (dmProfiles[r.id]?.display_name || "") : (r.name || "");
    const matchSearch = !searchQuery || name.toLowerCase().includes(searchQuery.toLowerCase());
    const matchTab =
      activeTab === "all" ||
      (activeTab === "groups" && r.type === "group") ||
      (activeTab === "direct" && r.type === "direct") ||
      (activeTab === "channels" && r.type === "channel");
    return matchSearch && matchTab;
  });

  const handleCreateGroup = async () => {
    if (!groupName.trim()) return;
    const room = await createGroupChat(userId, groupName, groupCity);
    await supabase.from("chat_members").update({ role: "admin" }).eq("room_id", room.id).eq("user_id", userId);
    setShowCreate(false);
    setGroupName("");
    refetch();
  };

  const handleUserSearch = async (q: string) => {
    setUserSearchQuery(q);
    if (q.length < 2) { setUserResults([]); return; }
    setSearching(true);
    const results = await searchUsers(q);
    setUserResults(results.filter((u) => u.user_id !== userId));
    setSearching(false);
  };

  const handleStartDM = async (otherUserId: string) => {
    try {
      const room = await createDirectChat(userId, otherUserId);
      onSelectRoom(room.id);
    } catch {
      // fallback
    }
    setShowUserSearch(false);
  };

  const handleStartGhostChat = async (otherUserId: string) => {
    const room = await createGhostChat(userId, otherUserId);
    onSelectRoom(room.id);
    setShowUserSearch(false);
  };

  const getRoomAvatar = (room: typeof rooms[0]) => {
    if (room.type === "direct") {
      const profile = dmProfiles[room.id];
      return (
        <StarAvatar
          src={profile?.avatar_url}
          name={profile?.display_name || "?"}
          size={52}
          online={!!profile?.is_online && !room.is_ghost_mode}
          premium={!!profile?.is_premium}
          tone={room.is_ghost_mode ? "purple" : "gold"}
        />
      );
    }

    if (room.type === "channel") {
      return (
        <StarAvatar
          name={room.name || "K"}
          size={52}
          tone="amber"
        />
      );
    }

    // group
    return (
      <StarAvatar
        name={room.name || "G"}
        size={52}
        tone="gold"
      />
    );
  };

  const getRoomDisplayName = (room: typeof rooms[0]) => {
    if (room.is_ghost_mode) return "Hayalet Sohbet 👻";
    if (room.type === "direct") return dmProfiles[room.id]?.display_name || "Direkt Mesaj";
    return room.name || "Grup";
  };

  const tabs = [
    { key: "all" as const, label: "Tümü" },
    { key: "direct" as const, label: "DM" },
    { key: "groups" as const, label: "Grup" },
    { key: "channels" as const, label: "Kanal" },
    { key: "contacts" as const, label: "Kişiler" },
    { key: "events" as const, label: "Etkinlik" },
    { key: "audio" as const, label: "Sesli" },
  ];

  return (
    <div className="flex flex-col h-[calc(100vh-5rem)]">
      {/* Glassmorphism header — Sovereign Gold on Pitch Black */}
      <div className="sticky top-0 z-30 bg-black/55 backdrop-blur-2xl border-b border-amber-400/15 supports-[backdrop-filter]:bg-black/40">
        <div className="px-4 pt-4 pb-2">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-[9px] font-mono uppercase tracking-[0.32em] text-amber-300/55">
                Egemen · Deng
              </div>
              <h1
                className="mt-0.5 text-[22px] font-black tracking-tight"
                style={{
                  background:
                    "linear-gradient(180deg, #FFE9A8 0%, #D4AF37 55%, #8C6A1B 100%)",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  filter:
                    "drop-shadow(0 1px 0 rgba(80,60,10,0.7)) drop-shadow(0 2px 6px rgba(212,175,55,0.35))",
                  letterSpacing: "-0.02em",
                }}
              >
                Mesajlar
              </h1>
            </div>
            <div className="flex items-center gap-1">
              <Link
                to="/nearby"
                className="h-9 px-2.5 flex items-center gap-1.5 rounded-full border border-amber-400/30 bg-amber-400/10 text-amber-200 hover:bg-amber-400/20 transition-colors"
                aria-label="Yakındaki"
              >
                <MapPin className="h-4 w-4" />
                <span className="text-[11px] font-semibold">Yakındaki</span>
              </Link>
              <button
                onClick={() => setShowSearch(!showSearch)}
                className="h-9 w-9 flex items-center justify-center rounded-full text-amber-200/75 hover:text-amber-100 hover:bg-amber-400/10 transition-colors"
              >
                <Search className="h-[18px] w-[18px]" />
              </button>
            </div>
          </div>

          {/* Search bar */}
          {showSearch && (
            <div className="mt-2 flex items-center gap-2 rounded-xl border border-amber-400/20 bg-black/40 backdrop-blur-xl px-3">
              <Search className="h-4 w-4 text-amber-300/60" />
              <input
                type="text"
                placeholder="İnsanları ara veya sohbetlerde ara..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                autoFocus
                className="h-9 flex-1 bg-transparent text-sm text-amber-100 placeholder:text-amber-300/40 focus:outline-none"
              />
            </div>
          )}
        </div>
      </div>

      {/* Stories bar */}
      {storyGroups.length > 0 && activeTab === "all" && (
        <div className="px-4 border-b border-border/50">
          <StoryBar
            groups={storyGroups}
            currentUserId={userId}
            onCreateStory={createStory}
            onMarkViewed={markViewed}
          />
        </div>
      )}

      {/* Sleek underline tab bar (Telegram/WhatsApp hybrid) */}
      <div className="px-4 border-b border-border/40">
        <div className="flex gap-5 overflow-x-auto scrollbar-none">
          {tabs.map((tab) => {
            const isActive = activeTab === tab.key;
            return (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`relative shrink-0 py-2.5 text-[13px] font-semibold tracking-tight transition-colors ${
                  isActive ? "text-foreground" : "text-muted-foreground hover:text-foreground/80"
                }`}
              >
                {tab.label}
                <span
                  className={`absolute left-0 right-0 -bottom-px h-[2px] rounded-full bg-primary transition-all duration-300 ${
                    isActive ? "opacity-100 scale-x-100" : "opacity-0 scale-x-50"
                  }`}
                />
              </button>
            );
          })}
        </div>
      </div>

      {/* User search overlay */}
      {showUserSearch && (
        <div className="px-4 py-2 border-b border-border/50">
          <div className="rounded-lg bg-muted/50 p-3 space-y-2">
            <div className="flex items-center gap-2">
              <Search className="h-4 w-4 text-muted-foreground" />
              <input
                type="text"
                placeholder="İsim veya Kurd-ID..."
                value={userSearchQuery}
                onChange={(e) => handleUserSearch(e.target.value)}
                autoFocus
                className="h-8 flex-1 bg-transparent text-sm text-foreground placeholder:text-muted-foreground focus:outline-none"
              />
              <button onClick={() => setShowUserSearch(false)} className="text-[10px] text-muted-foreground">İptal</button>
            </div>
            {searching && <p className="text-[10px] text-muted-foreground">Aranıyor...</p>}
            <div className="space-y-0.5 max-h-48 overflow-y-auto">
              {userResults.map((u) => (
                <div key={u.user_id} className="flex items-center gap-2.5 rounded-lg p-2 hover:bg-background/50">
                  <Link
                    to="/sovereign-profile"
                    search={{ u: u.user_id }}
                    className="shrink-0"
                    aria-label={`${u.display_name} profil`}
                  >
                    <StarAvatar
                      src={u.avatar_url}
                      name={u.display_name}
                      size={42}
                      online={u.is_online}
                      premium={u.is_premium}
                      tone="gold"
                    />
                  </Link>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-semibold text-amber-100 truncate">
                      {u.display_name}
                      {u.is_premium && <span className="ml-1 text-gold">👑</span>}
                    </p>
                    <p className="text-[9px] text-amber-300/55">{u.is_online ? "çevrimiçi" : u.kurd_id}</p>
                  </div>
                  <div className="flex gap-1">
                    <button onClick={() => handleStartDM(u.user_id)} className="rounded-md border border-amber-400/35 bg-amber-400/10 px-2.5 py-1 text-[10px] font-semibold text-amber-200 hover:bg-amber-400/20">
                      Mesaj
                    </button>
                    {isPremium && (
                      <button onClick={() => handleStartGhostChat(u.user_id)} className="rounded-md border border-purple-500/35 bg-purple-500/10 px-2 py-1 text-[10px] text-purple-300">
                        <Ghost className="h-3 w-3" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Create group overlay */}
      {showCreate && (
        <div className="px-4 py-2 border-b border-border/50">
          <div className="rounded-lg bg-muted/50 p-3 space-y-2">
            <p className="text-xs font-medium text-foreground">Yeni Grup</p>
            <input
              type="text"
              placeholder="Grup adı..."
              value={groupName}
              onChange={(e) => setGroupName(e.target.value)}
              className="h-9 w-full rounded-md border border-border bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:border-neon"
            />
            <select
              value={groupCity}
              onChange={(e) => setGroupCity(e.target.value)}
              className="h-9 w-full rounded-md border border-border bg-background px-3 text-sm text-foreground focus:outline-none appearance-none"
            >
              {["Arnhem", "Amsterdam", "Rotterdam", "Utrecht", "Den Haag"].map((c) => (
                <option key={c} value={c}>{c}</option>
              ))}
            </select>
            <div className="flex gap-2">
              <Button variant="neon" size="sm" className="flex-1 h-8 text-xs" onClick={handleCreateGroup}>Oluştur</Button>
              <button onClick={() => setShowCreate(false)} className="text-xs text-muted-foreground px-2">İptal</button>
            </div>
            <button
              onClick={() => { setShowChannelCreate(true); setShowCreate(false); }}
              className="flex w-full items-center gap-2 rounded-md p-2 hover:bg-background/50 transition-colors"
            >
              <Megaphone className="h-4 w-4 text-neon" />
              <span className="text-xs font-medium text-foreground">Kanal Oluştur</span>
            </button>
          </div>
        </div>
      )}

      {showChannelCreate && (
        <div className="px-4 py-2 border-b border-border/50">
          <CreateChannelForm
            userId={userId}
            onCreated={() => { setShowChannelCreate(false); refetch(); }}
            onCancel={() => setShowChannelCreate(false)}
          />
        </div>
      )}

      {/* Content area */}
      <div className="flex-1 overflow-y-auto">

        {/* Contacts Tab */}
        {activeTab === "contacts" && (
          <div className="px-4 py-2 space-y-2">
            <div className="flex items-center gap-2 rounded-lg bg-muted/50 px-3">
              <Search className="h-4 w-4 text-muted-foreground" />
              <input
                type="text"
                placeholder="KurdID veya telefon ile ara..."
                value={contactSearch}
                onChange={async (e) => {
                  const q = e.target.value;
                  setContactSearch(q);
                  if (q.length < 2) { setContactResults([]); return; }
                  setContactSearching(true);
                  const results = q.startsWith("+") || /^\d/.test(q)
                    ? await searchByPhone(q)
                    : await searchByKurdId(q);
                  setContactResults(results.filter((r) => r.user_id !== userId));
                  setContactSearching(false);
                }}
                className="h-9 flex-1 bg-transparent text-sm text-foreground placeholder:text-muted-foreground focus:outline-none"
              />
            </div>

            {contactSearch.length >= 2 && (
              <div className="space-y-0.5">
                {contactSearching ? (
                  <p className="text-xs text-muted-foreground text-center py-4">Aranıyor...</p>
                ) : contactResults.length === 0 ? (
                  <p className="text-xs text-muted-foreground text-center py-4">Sonuç bulunamadı</p>
                ) : (
                  contactResults.map((u) => {
                    const isFriend = friends.some((f) => f.user_id === u.user_id);
                    return (
                      <div key={u.user_id} className="flex items-center gap-3 rounded-lg px-3 py-2.5 hover:bg-muted/30 transition-colors">
                        <Avatar className="h-10 w-10">
                          {u.avatar_url ? <AvatarImage src={u.avatar_url} /> : null}
                          <AvatarFallback className="bg-muted text-muted-foreground text-sm font-medium">
                            {u.display_name?.[0]?.toUpperCase() || "?"}
                          </AvatarFallback>
                        </Avatar>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-foreground truncate">{u.display_name}</p>
                          <p className="text-[10px] text-muted-foreground">{u.kurd_id || u.city}</p>
                        </div>
                        {isFriend ? (
                          <button onClick={() => handleStartDM(u.user_id)} className="rounded-md bg-neon/10 px-2.5 py-1 text-[10px] font-medium text-neon">Mesaj</button>
                        ) : (
                          <button onClick={() => addFriend(u.user_id, u)} className="rounded-md bg-neon/10 px-2.5 py-1 text-[10px] font-medium text-neon">
                            <UserPlus className="h-3 w-3 inline mr-1" />Ekle
                          </button>
                        )}
                      </div>
                    );
                  })
                )}
              </div>
            )}

            {(() => {
              const now = Date.now();
              const ACTIVE_WINDOW = 1000 * 60 * 60 * 24 * 3; // 3 days
              const recentlyActive = friends.filter((f) => {
                if (f.is_online) return true;
                if (!f.last_seen) return false;
                return now - new Date(f.last_seen).getTime() < ACTIVE_WINDOW;
              });
              const kurdVerified = friends.filter(
                (f) => f.kurd_id && !recentlyActive.some((r) => r.user_id === f.user_id)
              );
              const needsInvite = friends.filter(
                (f) => !f.kurd_id && !recentlyActive.some((r) => r.user_id === f.user_id)
              );

              const renderRow = (f: typeof friends[0], showInvite = false) => (
                <div key={f.user_id} className="flex items-center gap-3 rounded-xl px-3 py-2.5 hover:bg-muted/20 transition-colors">
                  <div className="relative">
                    <Avatar className="h-11 w-11">
                      {f.avatar_url ? <AvatarImage src={f.avatar_url} /> : null}
                      <AvatarFallback className="bg-muted text-muted-foreground text-sm font-medium">
                        {f.display_name?.[0]?.toUpperCase() || "?"}
                      </AvatarFallback>
                    </Avatar>
                    {f.is_online && <span className="absolute bottom-0 right-0 h-3 w-3 rounded-full border-2 border-background bg-emerald-500" />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-[14px] font-semibold text-foreground truncate tracking-tight">
                      {f.kurd_id || f.display_name}
                    </p>
                    <p className="text-[11px] text-muted-foreground truncate">
                      {f.is_online
                        ? <span className="text-emerald-400 font-medium">çevrimiçi</span>
                        : f.kurd_id
                          ? f.display_name
                          : "@jiyan.world · +777 yok"}
                    </p>
                  </div>
                  {showInvite ? (
                    <button
                      onClick={() => handleStartDM(f.user_id)}
                      className="flex items-center gap-1 rounded-full bg-amber-500/15 px-3 py-1.5 text-[10px] font-bold text-amber-300 ring-1 ring-amber-500/30 active:scale-95 transition-transform"
                    >
                      <UserPlus className="h-3 w-3" />
                      Davet Et
                    </button>
                  ) : (
                    <button
                      onClick={() => handleStartDM(f.user_id)}
                      className="rounded-full bg-muted/60 p-2 text-muted-foreground hover:text-primary transition-colors"
                    >
                      <MessageCircle className="h-[18px] w-[18px]" />
                    </button>
                  )}
                </div>
              );

              return (
                <>
                  {recentlyActive.length > 0 && (
                    <div>
                      <p className="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-[0.12em] text-emerald-400/90 px-2 mb-1.5">
                        <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse" />
                        Recently Active · {recentlyActive.length}
                      </p>
                      <div className="space-y-0.5">{recentlyActive.map((f) => renderRow(f))}</div>
                    </div>
                  )}

                  {kurdVerified.length > 0 && (
                    <div>
                      <p className="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-[0.12em] text-primary/90 px-2 mb-1.5">
                        <span className="text-primary">✓</span>
                        KurdID Verified · {kurdVerified.length}
                      </p>
                      <div className="space-y-0.5">{kurdVerified.map((f) => renderRow(f))}</div>
                    </div>
                  )}

                  {needsInvite.length > 0 && (
                    <div>
                      <p className="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-[0.12em] text-amber-300/90 px-2 mb-1.5">
                        <UserPlus className="h-3 w-3" />
                        Quick Invite · {needsInvite.length}
                      </p>
                      <div className="space-y-0.5">{needsInvite.map((f) => renderRow(f, true))}</div>
                    </div>
                  )}

                  {friends.length === 0 && !friendsLoading && (
                    <div className="text-center py-12">
                      <Users className="h-10 w-10 text-muted-foreground/30 mx-auto mb-3" />
                      <p className="text-sm text-muted-foreground">Henüz arkadaş eklenmemiş</p>
                      <p className="text-[11px] text-muted-foreground/70 mt-1">+777 ID veya telefon ile ara</p>
                    </div>
                  )}
                </>
              );
            })()}

            <Link to="/friends">
              <button className="w-full rounded-xl py-2.5 text-xs font-semibold text-muted-foreground hover:text-foreground transition-colors">
                Rehber & Davet Sistemi →
              </button>
            </Link>
          </div>
        )}

        {/* Events Tab */}
        {activeTab === "events" && (
          <div className="px-4 py-2 space-y-0.5">
            {eventsLoading ? (
              <div className="py-12 text-center text-sm text-muted-foreground">Yükleniyor...</div>
            ) : events.length === 0 ? (
              <div className="py-12 text-center text-sm text-muted-foreground">Yaklaşan etkinlik yok</div>
            ) : (
              events.map((event) => (
                <Link key={event.id} to="/events/$eventId" params={{ eventId: event.id }}>
                  <div className="flex items-center gap-3 rounded-lg px-3 py-3 transition-colors hover:bg-muted/30">
                    <div className="h-11 w-11 rounded-lg bg-neon/10 flex items-center justify-center shrink-0">
                      <Calendar className="h-5 w-5 text-neon" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-foreground truncate">{event.title}</p>
                      <p className="text-[10px] text-muted-foreground flex items-center gap-2">
                        <span>{new Date(event.starts_at).toLocaleDateString("tr-TR", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}</span>
                        {event.location && <span className="flex items-center gap-0.5"><MapPin className="h-2.5 w-2.5" />{event.location}</span>}
                      </p>
                    </div>
                  </div>
                </Link>
              ))
            )}
            <Link to="/events">
              <button className="w-full rounded-lg py-2.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors">
                Tüm Etkinlikleri Gör →
              </button>
            </Link>
          </div>
        )}

        {/* Audio Rooms Tab */}
        {activeTab === "audio" && (
          <div className="px-4 py-2 space-y-0.5">
            {audioLoading ? (
              <div className="py-12 text-center text-sm text-muted-foreground">Yükleniyor...</div>
            ) : audioRooms.length === 0 ? (
              <div className="py-12 text-center text-sm text-muted-foreground">Aktif sesli oda yok</div>
            ) : (
              audioRooms.map((room) => (
                <Link key={room.id} to="/audio-rooms">
                  <div className="flex items-center gap-3 rounded-lg px-3 py-3 transition-colors hover:bg-muted/30">
                    {room.cover_url ? (
                      <img src={room.cover_url} alt="" className="h-11 w-11 rounded-lg object-cover shrink-0" />
                    ) : (
                      <div className="h-11 w-11 rounded-lg bg-neon/10 flex items-center justify-center shrink-0">
                        <Mic className="h-5 w-5 text-neon" />
                      </div>
                    )}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5">
                        <p className="text-sm font-medium text-foreground truncate">{room.title}</p>
                        {room.is_live && (
                          <span className="text-[8px] font-bold text-destructive flex items-center gap-0.5 animate-pulse">
                            <Radio className="h-2 w-2" /> CANLI
                          </span>
                        )}
                      </div>
                      <p className="text-[10px] text-muted-foreground flex items-center gap-2">
                        <span>{room.category}</span>
                        <span>👤 {room.listener_count}</span>
                      </p>
                    </div>
                  </div>
                </Link>
              ))
            )}
            <Link to="/audio-rooms">
              <button className="w-full rounded-lg py-2.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors">
                Tüm Sesli Odaları Gör →
              </button>
            </Link>
          </div>
        )}

        {/* Chat list — Telegram/WhatsApp hybrid */}
        {activeTab !== "events" && activeTab !== "audio" && activeTab !== "contacts" && (
          <div>
            {loading ? (
              <div className="py-12 text-center text-sm text-muted-foreground">Yükleniyor...</div>
            ) : filtered.length === 0 ? (
              <div className="py-12 text-center">
                <MessageCircle className="h-10 w-10 text-muted-foreground/20 mx-auto mb-2" />
                <p className="text-sm text-muted-foreground">Henüz sohbet yok</p>
              </div>
            ) : (
              filtered.map((room) => {
                const dm = dmProfiles[room.id];
                const isDM = room.type === "direct";
                const isChannel = room.type === "channel";
                const isGroup = room.type === "group";
                const unread = room.unread_count ?? 0;
                const hasUnread = unread > 0;

                // Primary identifier: clean @handle, +777 Kurd-ID, or display name
                // (auto-generated email-handles like "miqomilanoicloudcom" are filtered out)
                const primary = room.is_ghost_mode
                  ? "Hayalet Sohbet"
                  : isDM
                    ? resolveHandle({
                        username: dm?.username,
                        kurd_id: dm?.kurd_id,
                        display_name: dm?.display_name,
                      })
                    : (room.name || (isChannel ? "Kanal" : "Grup"));

                // Secondary: display_name for DMs (when distinct), city for groups/channels
                const hasCleanHandle = !!(dm?.username && !isEmailDerivedUsername(dm?.username));
                const secondaryLabel = isDM
                  ? (hasCleanHandle && dm?.display_name ? dm.display_name : (!hasCleanHandle && dm?.kurd_id && dm?.display_name ? dm.display_name : null))
                  : (room.city ? `📍 ${room.city}` : null);

                return (
                  <button
                    key={room.id}
                    className="flex w-full items-center gap-3 px-4 py-3 transition-colors hover:bg-muted/15 active:bg-muted/30"
                    onClick={() => {
                      if (room.is_member === false) return;
                      onSelectRoom(room.id);
                    }}
                  >
                    {/* Avatar with subtle purple glow when unread */}
                    <div className={`relative ${hasUnread ? "rounded-full ring-2 ring-purple-500/60 ring-offset-2 ring-offset-background" : ""}`}>
                      {getRoomAvatar(room)}
                      {/* Type indicator (corner badge for groups/channels) */}
                      {isChannel && (
                        <span className="absolute -bottom-0.5 -right-0.5 flex h-[18px] w-[18px] items-center justify-center rounded-full bg-background ring-2 ring-background">
                          <Megaphone className="h-2.5 w-2.5 text-primary" strokeWidth={2.6} />
                        </span>
                      )}
                      {isGroup && !isChannel && (
                        <span className="absolute -bottom-0.5 -right-0.5 flex h-[18px] w-[18px] items-center justify-center rounded-full bg-background ring-2 ring-background">
                          <Users className="h-2.5 w-2.5 text-emerald-400" strokeWidth={2.6} />
                        </span>
                      )}
                    </div>

                    <div className="flex-1 min-w-0 text-left">
                      <div className="flex items-baseline justify-between gap-2">
                        <div className="flex items-baseline gap-1.5 min-w-0">
                          <span className={`truncate text-[15px] tracking-tight ${hasUnread ? "font-bold text-foreground" : "font-semibold text-foreground"}`}>
                            {primary}
                          </span>
                          {isDM && dm?.is_premium && <span className="text-[10px] text-yellow-400 shrink-0">👑</span>}
                          {secondaryLabel && (
                            <span className="text-[10px] text-muted-foreground/70 truncate font-normal">
                              · {secondaryLabel}
                            </span>
                          )}
                        </div>
                        <span className={`text-[11px] shrink-0 tabular-nums ${hasUnread ? "font-semibold text-purple-400" : "text-muted-foreground"}`}>
                          {room.last_message_time ? timeAgo(room.last_message_time) : ""}
                        </span>
                      </div>
                      <div className="flex items-center justify-between mt-1 gap-2">
                        <p className={`text-[12.5px] truncate pr-2 leading-snug ${hasUnread ? "text-foreground/85 font-medium" : "text-muted-foreground"}`}>
                          {room.is_member === false
                            ? (isChannel ? "Kanala katılmak için tıkla" : "Gruba katılmak için tıkla")
                            : (room.last_message || "Henüz mesaj yok")}
                        </p>
                        {room.is_member === false ? (
                          <button
                            onClick={async (e) => {
                              e.stopPropagation();
                              await supabase.from("chat_members").insert({ room_id: room.id, user_id: userId });
                              refetch();
                            }}
                            className="shrink-0 rounded-full bg-primary/15 px-3 py-1 text-[10px] font-semibold text-primary"
                          >
                            Katıl
                          </button>
                        ) : hasUnread ? (
                          <span className="flex h-[22px] min-w-[22px] items-center justify-center rounded-full bg-purple-500 px-1.5 text-[10px] font-bold text-white shrink-0 shadow-[0_0_12px_rgba(168,85,247,0.6)]">
                            {unread > 99 ? "99+" : unread}
                          </span>
                        ) : null}
                      </div>
                    </div>
                  </button>
                );
              })
            )}
          </div>
        )}
      </div>

      {/* FAB — Popup menu (Yeni Sohbet / Grup / Kanal) */}
      <div className="fixed bottom-24 right-4 z-40 flex flex-col items-end gap-2">
        {showFabMenu && (
          <div className="flex flex-col items-end gap-2 animate-app-rise">
            <button
              onClick={() => { setShowFabMenu(false); setShowUserSearch(true); setShowCreate(false); setShowChannelCreate(false); }}
              className="flex items-center gap-2.5 rounded-full bg-card/95 backdrop-blur-xl pl-3 pr-4 py-2.5 shadow-[0_8px_24px_rgba(0,0,0,0.5)] border border-border/40 active:scale-95 transition-transform"
            >
              <span className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/15">
                <MessageCircle className="h-4 w-4 text-primary" strokeWidth={2.4} />
              </span>
              <span className="text-[13px] font-semibold text-foreground">Yeni Sohbet</span>
            </button>
            <button
              onClick={() => { setShowFabMenu(false); setShowCreate(true); setShowUserSearch(false); setShowChannelCreate(false); }}
              className="flex items-center gap-2.5 rounded-full bg-card/95 backdrop-blur-xl pl-3 pr-4 py-2.5 shadow-[0_8px_24px_rgba(0,0,0,0.5)] border border-border/40 active:scale-95 transition-transform"
            >
              <span className="flex h-8 w-8 items-center justify-center rounded-full bg-emerald-500/15">
                <Users className="h-4 w-4 text-emerald-400" strokeWidth={2.4} />
              </span>
              <span className="text-[13px] font-semibold text-foreground">Yeni Grup</span>
            </button>
            <button
              onClick={() => { setShowFabMenu(false); setShowChannelCreate(true); setShowCreate(false); setShowUserSearch(false); }}
              className="flex items-center gap-2.5 rounded-full bg-card/95 backdrop-blur-xl pl-3 pr-4 py-2.5 shadow-[0_8px_24px_rgba(0,0,0,0.5)] border border-border/40 active:scale-95 transition-transform"
            >
              <span className="flex h-8 w-8 items-center justify-center rounded-full bg-purple-500/15">
                <Megaphone className="h-4 w-4 text-purple-400" strokeWidth={2.4} />
              </span>
              <span className="text-[13px] font-semibold text-foreground">Yeni Kanal</span>
            </button>
          </div>
        )}
        <button
          onClick={() => setShowFabMenu((v) => !v)}
          aria-label={showFabMenu ? "Menüyü kapat" : "Yeni"}
          className={`flex h-14 w-14 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-[0_8px_24px_rgba(168,85,247,0.4)] transition-transform duration-300 ${showFabMenu ? "rotate-45" : ""}`}
        >
          <Plus className="h-6 w-6" strokeWidth={2.6} />
        </button>
      </div>
    </div>
  );
}

/* ─── Chat View (Telegram-style) ─────────────────────────── */

function ChatView({ roomId, userId, onBack }: { roomId: string; userId: string; onBack: () => void }) {
  const { messages, loading, sendMessage, readStatus } = useChatMessages(roomId, userId);
  const { typingUsers, handleTypingInput, stopTyping } = useTypingIndicator(roomId, userId);
  const { isPremium } = usePremium(userId);
  const [input, setInput] = useState("");
  const scrollRef = useRef<HTMLDivElement>(null);
  // Spatial chat refs — drive 3D void parallax + touch-follow gold light
  const stageRef = useRef<HTMLDivElement>(null);
  const scrollOffsetRef = useRef(0);
  const [profiles, setProfiles] = useState<Record<string, { name: string; avatar_url: string | null; is_online: boolean; is_premium?: boolean }>>({});
  // Map user_id → role within this room (admin/moderator/member). Used to render
  // golden crown badges for sovereign creators/admins next to their messages.
  const [memberRoles, setMemberRoles] = useState<Record<string, string>>({});
  const [ghostMode, setGhostMode] = useState(false);
  const [selfDestruct, setSelfDestruct] = useState<number | null>(null);
  const [showSearch, setShowSearch] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [room, setRoom] = useState<{
    name: string | null;
    is_ghost_mode: boolean;
    type: string;
    description: string | null;
    pinned_message_id: string | null;
    created_by?: string | null;
  } | null>(null);
  const [myRole, setMyRole] = useState<string>("member");
  const [pinnedMessage, setPinnedMessage] = useState<{
    id: string;
    content: string;
    sealed_at: string | null;
    senderName: string;
  } | null>(null);
  const [replyTo, setReplyTo] = useState<{ id: string; content: string; senderName: string } | null>(null);
  const [actionMenu, setActionMenu] = useState<{
    msgId: string;
    isMine: boolean;
    canEdit: boolean;
    canSeal: boolean;
    isSealed: boolean;
    content: string;
  } | null>(null);
  const [forwardId, setForwardId] = useState<string | null>(null);
  const [editTarget, setEditTarget] = useState<{ id: string; content: string } | null>(null);
  const [showStickers, setShowStickers] = useState(false);
  const [showMediaPicker, setShowMediaPicker] = useState(false);
  const [memberCount, setMemberCount] = useState(0);
  const [onlineCount, setOnlineCount] = useState(0);
  const [hiddenIds, setHiddenIds] = useState<Set<string>>(new Set());

  // Load per-user "deleted for me" message ids
  useEffect(() => {
    fetchHiddenMessageIds(userId).then(setHiddenIds);
  }, [userId, roomId]);

  const visibleMessages = messages.filter((m) => !hiddenIds.has(m.id));
  const isAdmin = myRole === "admin" || myRole === "moderator";
  const isChannel = room?.type === "channel";
  const canSendInChannel = isChannel ? isAdmin : true;

  const loadPinnedMessage = async (msgId: string) => {
    const { data: msg } = await supabase
      .from("chat_messages")
      .select("id, content, sealed_at, sender_id")
      .eq("id", msgId)
      .single();
    if (!msg) return;
    const { data: senderProfile } = await supabase
      .from("profiles")
      .select("display_name")
      .eq("user_id", msg.sender_id)
      .single();
    setPinnedMessage({
      id: msg.id,
      content: msg.content,
      sealed_at: msg.sealed_at,
      senderName: senderProfile?.display_name || "Kullanıcı",
    });
  };

  useEffect(() => {
    supabase
      .from("chat_rooms")
      .select("name, is_ghost_mode, type, description, pinned_message_id, created_by")
      .eq("id", roomId)
      .single()
      .then(({ data }) => {
        if (data) {
          setRoom(data);
          if (data.is_ghost_mode) setGhostMode(true);
          if (data.pinned_message_id) {
            loadPinnedMessage(data.pinned_message_id);
          }
        }
      });

    supabase
      .from("chat_members")
      .select("role")
      .eq("room_id", roomId)
      .eq("user_id", userId)
      .single()
      .then(({ data }) => {
        if (data) setMyRole(data.role);
      });

    // Fetch member list with roles so we can paint admin/moderator crowns
    // next to messages from group leadership.
    supabase
      .from("chat_members")
      .select("user_id, role")
      .eq("room_id", roomId)
      .then(async ({ data: members }) => {
        if (!members) return;
        setMemberCount(members.length);
        const roleMap: Record<string, string> = {};
        members.forEach((m) => { roleMap[m.user_id] = m.role; });
        setMemberRoles(roleMap);
        const userIds = members.map((m) => m.user_id);
        const { data: onlineProfiles } = await supabase
          .from("profiles")
          .select("user_id, is_online")
          .in("user_id", userIds)
          .eq("is_online", true);
        setOnlineCount(onlineProfiles?.length || 0);
      });
  }, [roomId, userId]);

  useEffect(() => {
    const senderIds = [...new Set(messages.map((m) => m.sender_id))];
    const missing = senderIds.filter((id) => !profiles[id]);
    if (missing.length === 0) return;

    supabase
      .from("profiles")
      .select("user_id, display_name, avatar_url, is_online, is_premium")
      .in("user_id", missing)
      .then(({ data }) => {
        if (data) {
          const map = { ...profiles };
          data.forEach((p) => { map[p.user_id] = { name: p.display_name, avatar_url: p.avatar_url, is_online: p.is_online, is_premium: p.is_premium }; });
          setProfiles(map);
        }
      });
  }, [messages]);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const msg = replyTo ? `↩️ ${replyTo.senderName}: ${replyTo.content}\n\n${input}` : input;
    setInput("");
    setReplyTo(null);
    stopTyping();
    await sendMessage(msg, {
      selfDestructSeconds: selfDestruct,
      isGhost: ghostMode,
    });
  };

  const handlePinMessage = async (messageId: string) => {
    await supabase.from("chat_rooms").update({ pinned_message_id: messageId }).eq("id", roomId);
    await loadPinnedMessage(messageId);
    setRoom((prev) => prev ? { ...prev, pinned_message_id: messageId } : prev);
  };

  const handleUnpinMessage = async () => {
    await supabase.from("chat_rooms").update({ pinned_message_id: null }).eq("id", roomId);
    setPinnedMessage(null);
    setRoom((prev) => prev ? { ...prev, pinned_message_id: null } : prev);
  };

  const handleSealMessage = async (messageId: string) => {
    try {
      const result = await sealChatMessage(messageId);
      if (result.sealed) {
        toast.success("Mühürlendi · Honor +5");
        await loadPinnedMessage(messageId);
        setRoom((prev) => prev ? { ...prev, pinned_message_id: messageId } : prev);
      } else {
        toast.success("Mühür kaldırıldı");
        setPinnedMessage(null);
        setRoom((prev) => prev ? { ...prev, pinned_message_id: null } : prev);
      }
    } catch (e) {
      toast.error((e as Error).message || "Mühürlenemedi");
    }
  };

  const openActionsFor = (msg: { id: string; sender_id: string; content: string; created_at: string; is_sealed?: boolean }) => {
    if (isChannel && !isAdmin) return;
    const isMine = msg.sender_id === userId;
    const ageMs = Date.now() - new Date(msg.created_at).getTime();
    const canEdit = isMine && ageMs < 24 * 60 * 60 * 1000;
    const canSeal = isMine || isAdmin || (room?.created_by === userId);
    setActionMenu({
      msgId: msg.id,
      isMine,
      canEdit,
      canSeal,
      isSealed: !!msg.is_sealed,
      content: msg.content || "",
    });
  };

  const handleDeleteMessage = async (msgId: string) => {
    const { error } = await supabase.rpc("soft_delete_message", { _message_id: msgId });
    if (error) toast.error(error.message);
    else toast.success("Mesaj silindi");
  };

  const typingNames = typingUsers
    .map((uid) => profiles[uid]?.name || "Birisi")
    .slice(0, 3);

  const typingText = typingNames.length === 1
    ? `${typingNames[0]} yazıyor...`
    : typingNames.length > 1
      ? `${typingNames.join(", ")} yazıyor...`
      : null;

  const getMessageStatus = (msg: { id: string; sender_id: string }) => {
    if (msg.sender_id !== userId) return null;
    const readers = readStatus[msg.id];
    if (readers && readers.length > 0) {
      return <CheckCheck className="h-3.5 w-3.5 text-blue-400" />;
    }
    return <CheckCheck className="h-3.5 w-3.5 text-muted-foreground/40" />;
  };

  const roomTitle = room?.is_ghost_mode
    ? "Hayalet Sohbet 👻"
    : room?.name || (room?.type === "direct" ? Object.values(profiles).find((p) => p.name)?.name || "Sohbet" : "Sohbet");

  const getSubtitle = () => {
    if (room?.is_ghost_mode) return "Anonim mesajlar";
    if (typingText) return typingText;
    if (room?.type === "direct") {
      const otherProfile = Object.entries(profiles).find(([id]) => id !== userId)?.[1];
      if (otherProfile?.is_online) return "çevrimiçi";
      return "çevrimdışı";
    }
    if (room?.type === "group" || room?.type === "channel") {
      return `${memberCount} üye${onlineCount > 0 ? `, ${onlineCount} çevrimiçi` : ""}`;
    }
    return room?.description || "";
  };

  if (showSettings && (room?.type === "group" || room?.type === "channel")) {
    return (
      <GroupSettings
        roomId={roomId}
        userId={userId}
        isAdmin={isAdmin}
        onClose={() => setShowSettings(false)}
        onRoomUpdated={() => {
          supabase
            .from("chat_rooms")
            .select("name, is_ghost_mode, type, description, pinned_message_id")
            .eq("id", roomId)
            .single()
            .then(({ data }) => { if (data) setRoom(data); });
        }}
        onRoomGone={onBack}
      />
    );
  }

  return (
    <div ref={stageRef} className="relative flex h-[calc(100vh-5rem)] flex-col bg-black overflow-hidden">
      {/* Sovereign 3D ambient layer (deep-space void + gold particles) */}
      <SovereignChatVoid scrollRef={scrollOffsetRef} />
      <TouchGoldLight targetRef={stageRef} />
      <ReactionBurstLayer />
      {/* Header — clean Telegram style */}
      <div className="flex items-center gap-3 px-3 py-2.5 border-b border-border/50">
        <button onClick={onBack} className="text-muted-foreground hover:text-foreground p-1">
          <ArrowLeft className="h-5 w-5" />
        </button>
        <button
          type="button"
          onClick={() => {
            if (room?.type === "group" || room?.type === "channel") setShowSettings(true);
          }}
          className="flex-1 min-w-0 text-left -mx-1 px-1 py-0.5 rounded-md transition active:bg-muted/30"
        >
          <div className="flex items-center gap-1.5">
            {isChannel && <Megaphone className="h-3.5 w-3.5 text-neon shrink-0" />}
            <h2 className={`text-[15px] font-semibold truncate ${room?.is_ghost_mode ? "text-purple-400" : "text-foreground"}`}>
              {roomTitle}
            </h2>
          </div>
          <p className={`text-[11px] truncate ${
            typingText ? "text-neon" :
            room?.is_ghost_mode ? "text-purple-400/60" :
            getSubtitle() === "çevrimiçi" ? "text-emerald-500" :
            "text-muted-foreground"
          }`}>
            {getSubtitle()}
          </p>
        </button>
        <div className="flex items-center gap-0.5">
          {!isChannel && (
            <GhostModeToggle enabled={ghostMode} isPremium={isPremium} onToggle={() => setGhostMode(!ghostMode)} />
          )}
          <button onClick={() => setShowSearch(!showSearch)} className="h-8 w-8 flex items-center justify-center rounded-full text-muted-foreground hover:text-foreground">
            <Search className="h-4 w-4" />
          </button>
          {(room?.type === "group" || room?.type === "channel") && (
            <button onClick={() => setShowSettings(true)} className="h-8 w-8 flex items-center justify-center rounded-full text-muted-foreground hover:text-foreground">
              <Settings className="h-4 w-4" />
            </button>
          )}
        </div>
      </div>

      {showSearch && <ChatSearchBar roomId={roomId} onClose={() => setShowSearch(false)} />}

      {pinnedMessage && (
        <PinnedMessageBar
          content={pinnedMessage.content}
          senderName={pinnedMessage.senderName}
          sealedAt={pinnedMessage.sealed_at}
          isAdmin={isAdmin}
          onUnpin={handleUnpinMessage}
        />
      )}

      {selfDestruct && (
        <div className="flex items-center justify-center gap-2 bg-orange-500/10 px-4 py-1 border-b border-orange-500/20">
          <Timer className="h-3 w-3 text-orange-400" />
          <span className="text-[10px] font-medium text-orange-400">
            {selfDestruct < 60 ? `${selfDestruct}sn` : selfDestruct < 3600 ? `${selfDestruct / 60}dk` : `${selfDestruct / 3600}sa`} sonra silinecek
          </span>
        </div>
      )}

      {ghostMode && !room?.is_ghost_mode && (
        <div className="flex items-center justify-center gap-2 bg-purple-500/10 px-4 py-1 border-b border-purple-500/20">
          <Ghost className="h-3 w-3 text-purple-400" />
          <span className="text-[10px] font-medium text-purple-400">Hayalet mod aktif</span>
        </div>
      )}

      <MessageActionsMenu
        open={!!actionMenu}
        isMine={!!actionMenu?.isMine}
        canEdit={!!actionMenu?.canEdit}
        canSeal={!!actionMenu?.canSeal}
        isSealed={!!actionMenu?.isSealed}
        onClose={() => setActionMenu(null)}
        onReply={() => {
          if (!actionMenu) return;
          const msg = messages.find((m) => m.id === actionMenu.msgId);
          if (!msg) return;
          const senderName = msg.sender_id === userId ? "Sen" : (profiles[msg.sender_id]?.name || "Kullanıcı");
          setReplyTo({ id: msg.id, content: (msg.content || "").slice(0, 80), senderName });
        }}
        onForward={() => actionMenu && setForwardId(actionMenu.msgId)}
        onEdit={() => actionMenu && setEditTarget({ id: actionMenu.msgId, content: actionMenu.content })}
        onDelete={() => actionMenu && handleDeleteMessage(actionMenu.msgId)}
        onDeleteForMe={async () => {
          if (!actionMenu) return;
          try {
            await hideMessageForMe(actionMenu.msgId);
            setHiddenIds((prev) => new Set(prev).add(actionMenu.msgId));
            toast.success("Senin için gizlendi");
          } catch (e) {
            toast.error((e as Error).message || "Gizlenemedi");
          }
        }}
        onSeal={() => actionMenu && handleSealMessage(actionMenu.msgId)}
        onCopy={() => {
          if (actionMenu?.content) {
            navigator.clipboard?.writeText(actionMenu.content);
            toast.success("Kopyalandı");
          }
        }}
      />

      <ForwardDialog
        open={!!forwardId}
        messageId={forwardId}
        userId={userId}
        onClose={() => setForwardId(null)}
      />

      <EditMessageDialog
        open={!!editTarget}
        messageId={editTarget?.id || null}
        initialContent={editTarget?.content || ""}
        onClose={() => setEditTarget(null)}
      />

      {/* Messages — Sovereign spatial stage with perspective + parallax */}
      <div
        className="flex-1 overflow-y-auto px-3 py-3 space-y-1.5 chat-spatial-stage relative z-[2]"
        onScroll={(e) => { scrollOffsetRef.current = e.currentTarget.scrollTop; }}
      >
        {loading ? (
          <p className="text-center text-xs text-muted-foreground py-8">Yükleniyor...</p>
        ) : visibleMessages.length === 0 ? (
          <div className="flex flex-col items-center pt-16">
            <div className="h-14 w-14 rounded-full bg-muted/30 flex items-center justify-center mb-3">
              {isChannel ? (
                <Megaphone className="h-7 w-7 text-neon/50" />
              ) : room?.is_ghost_mode ? (
                <Ghost className="h-7 w-7 text-purple-400/50" />
              ) : (
                <MessageCircle className="h-7 w-7 text-muted-foreground/30" />
              )}
            </div>
            <p className="text-xs text-muted-foreground">
              {isChannel ? "Henüz yayın yok" : "Merhaba de! 👋"}
            </p>
          </div>
        ) : (
          visibleMessages.map((msg, idx) => {
            const isMe = msg.sender_id === userId;
            const isGhostMsg = msg.is_ghost;
            const hasSelfDestruct = !!msg.self_destruct_at;
            const senderProfile = profiles[msg.sender_id];
            // Time-tunnel: older messages (lower idx) recede slightly into Z
            const distFromEnd = visibleMessages.length - 1 - idx;
            const tz = -Math.min(distFromEnd * 1.4, 60);
            const op = Math.max(0.55, 1 - distFromEnd * 0.012);

            return (
              <div
                key={msg.id}
                className="chat-spatial-msg"
                style={{ transform: `translateZ(${tz}px)`, opacity: op }}
              >
                <SwipeToReply
                  isMe={isMe}
                  disabled={isChannel}
                  onReply={() => {
                    setReplyTo({
                      id: msg.id,
                      content: msg.content?.slice(0, 80) || (msg.message_type === "audio" ? "🎤 Sesli mesaj" : "📎 Medya"),
                      senderName: isMe ? "Sen" : (senderProfile?.name || "Kullanıcı"),
                    });
                  }}
                >
                <div
                  className={`flex ${isChannel ? "justify-start" : isMe ? "justify-end" : "justify-start"}`}
                  onContextMenu={(e) => { e.preventDefault(); openActionsFor(msg); }}
                >
                  {!isMe && !isChannel && (
                    <Link
                      to="/sovereign-profile"
                      search={{ u: msg.sender_id } as never}
                      className="mr-1.5 mt-auto shrink-0 active:scale-90 transition-transform"
                      aria-label={`${senderProfile?.name ?? "Kullanıcı"} profilini aç`}
                    >
                      <GoldStarAvatar
                        src={senderProfile?.avatar_url}
                        name={isGhostMsg ? "👻" : (senderProfile?.name ?? "?")}
                        size={32}
                        online={!!senderProfile?.is_online && !isGhostMsg}
                        premium={!!senderProfile?.is_premium}
                        tone={isGhostMsg ? "purple" : (memberRoles[msg.sender_id] === "admin" ? "amber" : "gold")}
                      />
                    </Link>
                  )}
                  <Deng3DBubble isMe={isMe} isChannel={isChannel} isGhost={isGhostMsg}>
                    {(!isMe || isChannel) && (
                      <Link
                        to="/sovereign-profile"
                        search={{ u: msg.sender_id } as never}
                        className={`flex items-center gap-1 text-[10px] font-semibold mb-0.5 hover:underline ${isGhostMsg ? "text-purple-400" : "text-amber-300"}`}
                      >
                        {isGhostMsg ? "Anonim 👻" : senderProfile?.name || "Kullanıcı"}
                        {!isGhostMsg && memberRoles[msg.sender_id] === "admin" && (
                          <span title="Yönetici" className="text-amber-300">👑</span>
                        )}
                        {!isGhostMsg && memberRoles[msg.sender_id] === "moderator" && (
                          <span title="Moderatör" className="text-emerald-300 text-[9px]">★</span>
                        )}
                      </Link>
                    )}
                    {/* Text-only messages → Deng3DText (parses ***SLAM***, **LOUD**, *gentle*, _ink_, ~~wavy~~). */}
                    {(!msg.message_type || msg.message_type === "text") && !msg.media_url ? (
                      <Deng3DText content={msg.content} isMe={isMe} />
                    ) : (
                      <MediaMessageBubble
                        messageType={msg.message_type || "text"}
                        mediaUrl={msg.media_url}
                        fileName={msg.file_name}
                        fileSize={msg.file_size}
                        content={msg.content}
                        isMe={isMe}
                        voicePeaks={(msg as { voice_peaks?: number[] | null }).voice_peaks ?? null}
                        voiceDurationMs={(msg as { voice_duration_ms?: number | null }).voice_duration_ms ?? null}
                      />
                    )}
                    {!isMe && msg.content && <TranslateButton text={msg.content} />}
                    <div className="flex items-center justify-end gap-1 mt-0.5">
                      {hasSelfDestruct && <Timer className="h-2.5 w-2.5 text-orange-400" />}
                      {isGhostMsg && !isMe && <Ghost className="h-2.5 w-2.5 text-purple-400/60" />}
                      <p className={`text-[9px] ${
                        isChannel ? "text-muted-foreground"
                          : isMe ? (isGhostMsg ? "text-purple-400/60" : "text-[#1a1003]/70")
                            : "text-amber-200/60"
                      }`}>
                        {new Date(msg.created_at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
                      </p>
                      {getMessageStatus(msg)}
                    </div>
                    <MessageReactions messageId={msg.id} userId={userId} />
                  </Deng3DBubble>
                </div>
                </SwipeToReply>
              </div>
            );
          })
        )}

        {typingText && (
          <div className="flex items-center gap-2 px-1">
            <div className="flex gap-0.5">
              <span className="h-1.5 w-1.5 rounded-full bg-neon animate-bounce" style={{ animationDelay: "0ms" }} />
              <span className="h-1.5 w-1.5 rounded-full bg-neon animate-bounce" style={{ animationDelay: "150ms" }} />
              <span className="h-1.5 w-1.5 rounded-full bg-neon animate-bounce" style={{ animationDelay: "300ms" }} />
            </div>
            <span className="text-[10px] text-muted-foreground">{typingText}</span>
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      {/* Media picker */}
      {showMediaPicker && canSendInChannel && (
        <div className="border-t border-border/50 px-3 py-2">
          <ChatMediaUpload
            userId={userId}
            roomId={roomId}
            onMediaSent={(mediaUrl, messageType, fileName, fileSize) => {
              sendMessage(fileName, {
                selfDestructSeconds: selfDestruct,
                isGhost: ghostMode,
                messageType,
                mediaUrl,
                fileName,
                fileSize,
              });
              setShowMediaPicker(false);
            }}
            onClose={() => setShowMediaPicker(false)}
          />
        </div>
      )}

      {/* Reply preview */}
      {replyTo && (
        <div className="flex items-center gap-2 border-t border-border/50 bg-muted/20 px-4 py-2">
          <div className="w-0.5 h-8 rounded-full bg-neon shrink-0" />
          <div className="flex-1 min-w-0">
            <p className="text-[10px] font-medium text-neon">{replyTo.senderName}</p>
            <p className="text-[11px] text-muted-foreground truncate">{replyTo.content}</p>
          </div>
          <button onClick={() => setReplyTo(null)} className="shrink-0 text-muted-foreground hover:text-foreground p-1">
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* Input — clean Telegram style */}
      {canSendInChannel ? (
        <div className={`relative border-t border-border/50 px-3 py-2 ${replyTo ? "border-t-0" : ""}`}>
          <StickerPicker
            open={showStickers}
            onClose={() => setShowStickers(false)}
            onPick={(emoji) => {
              sendMessage(emoji, { selfDestructSeconds: selfDestruct, isGhost: ghostMode });
            }}
          />
          <div className="flex items-center gap-1.5">
            {!isChannel && <SelfDestructPicker value={selfDestruct} onChange={setSelfDestruct} />}
            <button
              onClick={() => { setShowMediaPicker(!showMediaPicker); setShowStickers(false); }}
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-muted-foreground hover:text-foreground transition-colors"
              aria-label="Medya"
            >
              <Paperclip className="h-[18px] w-[18px]" />
            </button>
            <button
              onClick={() => { setShowStickers((v) => !v); setShowMediaPicker(false); }}
              className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full transition-colors ${showStickers ? "text-primary bg-primary/10" : "text-muted-foreground hover:text-foreground"}`}
              aria-label="Sticker"
            >
              <Smile className="h-[18px] w-[18px]" />
            </button>
            <Deng3DEmojiPicker
              onPick={(emoji) => setInput((v) => v + emoji)}
            />
            <input
              type="text"
              value={input}
              onChange={(e) => {
                setInput(e.target.value);
                handleTypingInput();
              }}
              onKeyDown={(e) => e.key === "Enter" && handleSend()}
              placeholder={isChannel ? "Yayın gönder..." : ghostMode ? "Anonim mesaj..." : "Mesaj yaz..."}
              className={`h-9 flex-1 rounded-full border px-4 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none transition-colors ${
                ghostMode
                  ? "border-purple-500/30 bg-purple-500/5 focus:border-purple-500"
                  : "border-border/50 bg-muted/30 focus:border-neon/50"
              }`}
            />
            {input.trim() ? (
              <button
                onClick={handleSend}
                className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full active:scale-95 transition-all ${
                  ghostMode ? "bg-purple-500 text-white" : "bg-neon text-neon-foreground"
                }`}
              >
                <Send className="h-4 w-4" />
              </button>
            ) : (
              <VoiceRecorder
                userId={userId}
                roomId={roomId}
                onVoiceSent={(mediaUrl, _duration, fileName, fileSize, peaks, durationMs) => {
                  sendMessage(fileName, {
                    selfDestructSeconds: selfDestruct,
                    isGhost: ghostMode,
                    messageType: "audio",
                    mediaUrl,
                    fileName,
                    fileSize,
                    voicePeaks: peaks,
                    voiceDurationMs: durationMs,
                  });
                }}
              />
            )}
          </div>
        </div>
      ) : (
        <div className="border-t border-border/50 px-4 py-3 text-center">
          <p className="text-xs text-muted-foreground">Yalnızca yöneticiler gönderi paylaşabilir</p>
        </div>
      )}
    </div>
  );
}

