import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { useAuth } from "@/hooks/useAuth";
import { useConstitution } from "@/hooks/useConstitution";
import { ConstitutionOnboarding } from "@/components/identity/ConstitutionOnboarding";
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { Vote, Scroll, Lightbulb, Shield, Loader2, ChevronUp, Lock, Sparkles, ArrowLeft } from "lucide-react";

export const Route = createFileRoute("/congress")({
  head: () => ({
    meta: [
      { title: "WKO Congress — Global Decision-Making" },
      { name: "description", content: "Active referendums, WKO Charter articles and citizen proposals." },
    ],
  }),
  component: CongressPage,
});

interface Referendum {
  id: string;
  title: string;
  description: string;
  category: string;
  ends_at: string;
  yes_count: number;
  no_count: number;
  abstain_count: number;
}
interface Law {
  id: string;
  article_no: string;
  title: string;
  legal_text: string;
  simplified_text: string;
}
interface Proposal {
  id: string;
  title: string;
  content: string;
  support_count: number;
  user_id: string;
  created_at: string;
}

function CongressPage() {
  const { user } = useAuth();
  const { signed } = useConstitution();
  const [showSign, setShowSign] = useState(false);
  const [refs, setRefs] = useState<Referendum[]>([]);
  const [laws, setLaws] = useState<Law[]>([]);
  const [proposals, setProposals] = useState<Proposal[]>([]);
  const [myVotes, setMyVotes] = useState<Record<string, string>>({});
  const [voting, setVoting] = useState<string | null>(null);
  const [encrypting, setEncrypting] = useState<{ choice: string; hash: string } | null>(null);
  const [supports, setSupports] = useState<Set<string>>(new Set());
  const [participation, setParticipation] = useState(0);

  // Proposal form
  const [pTitle, setPTitle] = useState("");
  const [pContent, setPContent] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const loadAll = async () => {
    const [r, l, p, totalUsers, signedCountRpc] = await Promise.all([
      supabase.from("referendums").select("*").eq("status", "active").order("ends_at"),
      supabase.from("official_laws").select("*").order("article_no"),
      supabase.from("proposals").select("*").order("support_count", { ascending: false }).limit(20),
      supabase.from("profiles").select("user_id", { count: "exact", head: true }),
      supabase.rpc("get_constitution_signature_count"),
    ]);
    setRefs((r.data as any) || []);
    setLaws((l.data as any) || []);
    setProposals((p.data as any) || []);
    const signedCount = Number(signedCountRpc.data ?? 0);
    if (totalUsers.count && signedCount) {
      setParticipation(Math.round((signedCount / totalUsers.count) * 100));
    }

    if (user) {
      const [v, s] = await Promise.all([
        supabase.from("referendum_votes").select("referendum_id,choice").eq("user_id", user.id),
        supabase.from("proposal_supports").select("proposal_id").eq("user_id", user.id),
      ]);
      const map: Record<string, string> = {};
      (v.data as any[])?.forEach((row) => (map[row.referendum_id] = row.choice));
      setMyVotes(map);
      setSupports(new Set((s.data as any[])?.map((x) => x.proposal_id) || []));
    }
  };

  useEffect(() => {
    loadAll();
  }, [user?.id]);

  const handleVote = async (refId: string, choice: "yes" | "no" | "abstain") => {
    if (!user) {
      toast.error("Giriş yap");
      return;
    }
    if (!signed) {
      setShowSign(true);
      return;
    }
    setVoting(refId);
    const { data, error } = await supabase.rpc("cast_referendum_vote", {
      _user_id: user.id,
      _referendum_id: refId,
      _choice: choice,
    });
    setVoting(null);
    if (error || !(data as any)?.success) {
      toast.error((data as any)?.error || error?.message || "Oy kullanılamadı");
      return;
    }
    setEncrypting({ choice, hash: (data as any).vote_hash });
    setTimeout(() => setEncrypting(null), 3500);
    loadAll();
  };

  const handleSupport = async (id: string) => {
    if (!user) return;
    if (!signed) { setShowSign(true); return; }
    const { data } = await supabase.rpc("toggle_proposal_support", {
      _user_id: user.id,
      _proposal_id: id,
    });
    if (!(data as any)?.success) {
      toast.error((data as any)?.error || "Desteklenemedi");
      return;
    }
    loadAll();
  };

  const submitProposal = async () => {
    if (!user || !pTitle || !pContent) return;
    if (!signed) { setShowSign(true); return; }
    setSubmitting(true);
    const { error } = await supabase.from("proposals").insert({
      user_id: user.id,
      title: pTitle,
      content: pContent,
    });
    setSubmitting(false);
    if (error) {
      toast.error(error.message);
      return;
    }
    toast.success("Öneri sunuldu!");
    setPTitle("");
    setPContent("");
    loadAll();
  };

  return (
    <AppShell>
      <div className="min-h-screen bg-[#050505] text-foreground pb-24">
        {/* Header */}
        <div className="sticky top-0 z-30 backdrop-blur-xl bg-black/60 border-b border-white/5 px-4 py-3 flex items-center gap-3">
          <Link to="/dashboard" className="p-2 rounded-lg hover:bg-white/5">
            <ArrowLeft className="w-4 h-4" />
          </Link>
          <div className="flex-1">
            <div className="text-[10px] uppercase tracking-widest opacity-50">Module</div>
            <div className="font-bold flex items-center gap-1.5">
              <Shield className="w-4 h-4 text-blue-400" />
              Jiyan Congress
            </div>
          </div>
          {signed && (
            <span className="text-[10px] font-bold px-2 py-1 rounded-full bg-green-500/20 text-green-300 border border-green-500/30">
              ✓ SIGNED
            </span>
          )}
        </div>

        {/* Participation gauge */}
        <div className="px-4 pt-4">
          <div className="rounded-2xl bg-gradient-to-br from-blue-500/10 to-indigo-700/10 border border-blue-400/20 p-4">
            <div className="flex items-center justify-between mb-2">
              <div>
                <div className="text-[10px] uppercase tracking-widest opacity-60">National Participation</div>
                <div className="text-3xl font-bold mt-1">{participation}%</div>
              </div>
              <div className="text-right">
                <div className="text-xs opacity-60">WKO citizens signed</div>
              </div>
            </div>
            <div className="h-2 bg-white/5 rounded-full overflow-hidden">
              <div
                className="h-full bg-gradient-to-r from-blue-400 to-indigo-500 transition-all duration-1000"
                style={{ width: `${participation}%` }}
              />
            </div>
          </div>
        </div>

        <Tabs defaultValue="referendums" className="px-4 pt-4">
          <TabsList className="grid grid-cols-3 bg-white/5">
            <TabsTrigger value="referendums" className="text-xs">
              <Vote className="w-3.5 h-3.5 mr-1" />Active
            </TabsTrigger>
            <TabsTrigger value="laws" className="text-xs">
              <Scroll className="w-3.5 h-3.5 mr-1" />Laws
            </TabsTrigger>
            <TabsTrigger value="proposals" className="text-xs">
              <Lightbulb className="w-3.5 h-3.5 mr-1" />Propose
            </TabsTrigger>
          </TabsList>

          {/* REFERENDUMS */}
          <TabsContent value="referendums" className="space-y-3 mt-4">
            {refs.length === 0 && <div className="text-center text-sm opacity-60 py-8">Aktif referandum yok</div>}
            {refs.map((r) => {
              const total = r.yes_count + r.no_count + r.abstain_count;
              const yesPct = total > 0 ? Math.round((r.yes_count / total) * 100) : 0;
              const myVote = myVotes[r.id];
              const daysLeft = Math.max(0, Math.ceil((new Date(r.ends_at).getTime() - Date.now()) / 86400000));
              return (
                <div key={r.id} className="rounded-2xl bg-white/[0.03] border border-white/10 p-4">
                  <div className="flex items-start justify-between gap-2 mb-2">
                    <div className="flex-1 min-w-0">
                      <div className="text-[10px] uppercase opacity-60 tracking-widest">{r.category} · {daysLeft}g kaldı</div>
                      <h3 className="font-bold text-sm mt-0.5">{r.title}</h3>
                    </div>
                  </div>
                  <p className="text-xs opacity-70 mb-3">{r.description}</p>

                  <div className="h-2 bg-white/5 rounded-full overflow-hidden mb-1 flex">
                    <div className="bg-green-500 transition-all" style={{ width: `${yesPct}%` }} />
                    <div className="bg-red-500" style={{ width: `${total > 0 ? (r.no_count / total) * 100 : 0}%` }} />
                    <div className="bg-gray-500" style={{ width: `${total > 0 ? (r.abstain_count / total) * 100 : 0}%` }} />
                  </div>
                  <div className="flex justify-between text-[10px] opacity-60 mb-3">
                    <span>✓ {r.yes_count}</span>
                    <span>✗ {r.no_count}</span>
                    <span>− {r.abstain_count}</span>
                    <span>Toplam: {total}</span>
                  </div>

                  {myVote ? (
                    <div className="text-center text-xs py-2 rounded-lg bg-green-500/10 border border-green-500/20 text-green-300">
                      🔒 Oyun şifrelendi: <strong>{myVote.toUpperCase()}</strong>
                    </div>
                  ) : (
                    <div className="grid grid-cols-3 gap-2">
                      <button
                        onClick={() => handleVote(r.id, "yes")}
                        disabled={voting === r.id}
                        className="py-2 rounded-lg bg-green-500/10 border border-green-500/30 text-green-300 text-xs font-semibold hover:bg-green-500/20 disabled:opacity-50"
                      >
                        {voting === r.id ? <Loader2 className="w-4 h-4 animate-spin mx-auto" /> : "✓ Evet"}
                      </button>
                      <button
                        onClick={() => handleVote(r.id, "no")}
                        disabled={voting === r.id}
                        className="py-2 rounded-lg bg-red-500/10 border border-red-500/30 text-red-300 text-xs font-semibold hover:bg-red-500/20 disabled:opacity-50"
                      >
                        ✗ Hayır
                      </button>
                      <button
                        onClick={() => handleVote(r.id, "abstain")}
                        disabled={voting === r.id}
                        className="py-2 rounded-lg bg-gray-500/10 border border-gray-500/30 text-gray-300 text-xs font-semibold hover:bg-gray-500/20 disabled:opacity-50"
                      >
                        − Çekimser
                      </button>
                    </div>
                  )}
                </div>
              );
            })}
          </TabsContent>

          {/* LAWS */}
          <TabsContent value="laws" className="space-y-3 mt-4">
            {laws.map((l) => (
              <div key={l.id} className="rounded-2xl bg-white/[0.03] border border-white/10 p-4">
                <div className="flex items-center gap-2 mb-2">
                  <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-blue-500/20 text-blue-300 border border-blue-500/30">
                    {l.article_no}
                  </span>
                  <h3 className="font-bold text-sm">{l.title}</h3>
                </div>
                <details className="text-xs">
                  <summary className="cursor-pointer text-blue-300 hover:text-blue-200">📖 Hukuki metin</summary>
                  <p className="mt-2 opacity-70 leading-relaxed">{l.legal_text}</p>
                </details>
                <div className="mt-3 p-3 rounded-lg bg-white/[0.02] border border-white/5">
                  <div className="text-[10px] uppercase opacity-50 mb-1">Vatandaşa Özet</div>
                  <p className="text-xs">{l.simplified_text}</p>
                </div>
              </div>
            ))}
          </TabsContent>

          {/* PROPOSALS */}
          <TabsContent value="proposals" className="space-y-3 mt-4">
            <div className="rounded-2xl bg-white/[0.03] border border-white/10 p-4">
              <h3 className="font-bold text-sm mb-3 flex items-center gap-2">
                <Sparkles className="w-4 h-4 text-amber-400" /> Yeni Öneri Sun
              </h3>
              <Input
                placeholder="Önerinin başlığı"
                value={pTitle}
                onChange={(e) => setPTitle(e.target.value)}
                className="mb-2 bg-black/30"
                maxLength={120}
              />
              <Textarea
                placeholder="Önerinin detayı (max 1000 karakter)"
                value={pContent}
                onChange={(e) => setPContent(e.target.value)}
                className="bg-black/30 min-h-[100px]"
                maxLength={1000}
              />
              <Button
                onClick={submitProposal}
                disabled={submitting || !pTitle || !pContent}
                className="w-full mt-3 bg-blue-600 hover:bg-blue-700"
              >
