import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { useCampaigns, useCreateCampaign, useContribute } from "@/hooks/useCrowdfund";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Heart, Plus, Target, Users, ArrowLeft, Sparkles } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import type { Campaign } from "@/hooks/useCrowdfund";

export const Route = createFileRoute("/crowdfunding")({
  component: CrowdfundPage,
  head: () => ({
    meta: [
      { title: "Topluluk Fonlama – Jiyan Europe" },
      { name: "description", content: "Toplum projelerini DiravCash ile destekle." },
    ],
  }),
});

function CrowdfundPage() {
  const { t } = useTranslation();
  const { user } = useAuth();
  const { campaigns, loading, refresh } = useCampaigns();
  const { create, creating } = useCreateCampaign();
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [desc, setDesc] = useState("");
  const [goal, setGoal] = useState("");

  const handleCreate = async () => {
    const result = await create({ title, description: desc, goal_amount: parseFloat(goal) || 0 });
    if (result) {
      setTitle(""); setDesc(""); setGoal(""); setOpen(false);
      refresh();
    }
  };

  return (
    <AppShell>
      <div className="px-4 pt-6 pb-8">
        <div className="flex items-center gap-3 mb-4">
          <Link to="/" className="text-muted-foreground hover:text-foreground">
            <ArrowLeft className="h-5 w-5" />
          </Link>
          <div className="flex-1">
            <h1 className="text-xl font-bold text-foreground flex items-center gap-2">
              <Heart className="h-5 w-5 text-rose-400" />
              {t("crowdfund.title")}
            </h1>
            <p className="text-xs text-muted-foreground">{t("crowdfund.subtitle")}</p>
          </div>
        </div>

        {user && (
          <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
              <Button variant="neon" className="w-full mb-6">
                <Plus className="h-4 w-4 mr-1" />
                {t("crowdfund.create")}
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader><DialogTitle>{t("crowdfund.create")}</DialogTitle></DialogHeader>
              <div className="space-y-3">
                <div>
                  <Label>Başlık</Label>
                  <Input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Örn: Erbil çocuk hastanesi" maxLength={100} />
                </div>
                <div>
                  <Label>Açıklama</Label>
                  <Textarea value={desc} onChange={(e) => setDesc(e.target.value)} placeholder="Projenizi anlatın..." maxLength={500} />
                </div>
                <div>
                  <Label>{t("crowdfund.goal")} (DC)</Label>
                  <Input type="number" min="1" value={goal} onChange={(e) => setGoal(e.target.value)} />
                </div>
                <Button variant="neon" className="w-full" onClick={handleCreate} disabled={creating}>
                  {creating ? "Oluşturuluyor..." : t("crowdfund.create")}
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        )}

        {loading ? (
          <div className="flex justify-center pt-12">
            <div className="h-8 w-8 animate-spin rounded-full border-2 border-neon border-t-transparent" />
          </div>
        ) : campaigns.length === 0 ? (
          <div className="text-center py-16">
            <Sparkles className="h-12 w-12 text-muted-foreground mx-auto mb-3 opacity-50" />
            <p className="text-sm text-muted-foreground">{t("crowdfund.noActive")}</p>
          </div>
        ) : (
          <div className="space-y-3">
            {campaigns.map((c) => <CampaignCard key={c.id} campaign={c} onRefresh={refresh} />)}
          </div>
        )}
      </div>
    </AppShell>
  );
}

function CampaignCard({ campaign, onRefresh }: { campaign: Campaign; onRefresh: () => void }) {
  const { t } = useTranslation();
  const { user } = useAuth();
  const { contribute, contributing } = useContribute();
  const [open, setOpen] = useState(false);
  const [amount, setAmount] = useState("5");
  const [message, setMessage] = useState("");
  const [anon, setAnon] = useState(false);

  const pct = Math.min(100, (campaign.raised_amount / campaign.goal_amount) * 100);
  const isOwn = user?.id === campaign.creator_id;

  const handleContribute = async () => {
    const ok = await contribute(campaign.id, parseFloat(amount) || 0, message || undefined, anon);
    if (ok) { setOpen(false); setMessage(""); onRefresh(); }
  };

  return (
    <div className="rounded-2xl border border-border bg-surface/40 p-4 backdrop-blur-sm">
      {campaign.cover_url && (
        <img src={campaign.cover_url} alt={campaign.title} className="w-full h-40 object-cover rounded-xl mb-3" loading="lazy" />
      )}
      <h3 className="text-sm font-bold text-foreground mb-1">{campaign.title}</h3>
      <p className="text-xs text-muted-foreground mb-3 line-clamp-2">{campaign.description}</p>

      <div className="mb-2">
        <div className="h-2 rounded-full bg-muted overflow-hidden">
          <div className="h-full bg-gradient-to-r from-neon to-gold transition-all" style={{ width: `${pct}%` }} />
        </div>
      </div>

      <div className="flex items-center justify-between text-xs mb-3">
        <span className="text-foreground"><Target className="inline h-3 w-3 mr-1" />{campaign.raised_amount} / {campaign.goal_amount} DC</span>
        <span className="text-muted-foreground"><Users className="inline h-3 w-3 mr-1" />{campaign.contributor_count} {t("crowdfund.contributors")}</span>
      </div>

      {!isOwn && user && (
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger asChild>
            <Button variant="neon" size="sm" className="w-full">
              <Heart className="h-3 w-3 mr-1" />
              {t("crowdfund.contribute")}
            </Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader><DialogTitle>{campaign.title}</DialogTitle></DialogHeader>
            <div className="space-y-3">
              <div>
                <Label>{t("crowdfund.amount")}</Label>
                <Input type="number" min="1" value={amount} onChange={(e) => setAmount(e.target.value)} />
                <div className="flex gap-2 mt-2">
                  {[5, 10, 25, 50].map((a) => (
                    <button key={a} type="button" onClick={() => setAmount(String(a))}
                      className="flex-1 rounded-lg border border-border px-2 py-1 text-xs hover:border-neon">
                      {a} DC
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <Label>{t("crowdfund.leaveMessage")}</Label>
                <Textarea value={message} onChange={(e) => setMessage(e.target.value)} maxLength={200} />
              </div>
              <label className="flex items-center gap-2 text-xs text-muted-foreground">
                <input type="checkbox" checked={anon} onChange={(e) => setAnon(e.target.checked)} />
                {t("crowdfund.anonymous")}
              </label>
              <Button variant="neon" className="w-full" onClick={handleContribute} disabled={contributing}>
                {contributing ? "Gönderiliyor..." : `${amount} DC ${t("crowdfund.contribute")}`}
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      )}
      {isOwn && (
        <p className="text-center text-[10px] text-muted-foreground italic">Bu sizin kampanyanız</p>
      )}
    </div>
  );
}

