      {
        name: "description",
        content:
          "Deng — Jiyan'ın sesi. Sovereign Intelligence beyniyle çalışan iOS 18 cam arayüzü.",
      },
      { property: "og:title", content: "Deng" },
      {
        property: "og:description",
        content: "iOS 18 floating glass dock · Jiyan Sovereign Intelligence · theme-aware bubbles.",
      },
    ],
  }),
  component: DengPage,
});

interface ChatTurn {
  id: string;
  side: "user" | "deng";
  text: string;
  source?: "voice" | "text";
  ts?: number;
}

const DENG_URL = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/deng-ai`;

function DengPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { placeCall } = useSovereignPhone();
  const [text, setText] = React.useState("");
  const [turns, setTurns] = React.useState<ChatTurn[]>([]);
  const [thinking, setThinking] = React.useState(false);
  const [listening, setListening] = React.useState(false);
  const [voiceMode, setVoiceMode] = React.useState(true);
  const [voiceWithVideo, setVoiceWithVideo] = React.useState(false);
  const [voiceVideoStream, setVoiceVideoStream] = React.useState<MediaStream | null>(null);
  const scrollerRef = React.useRef<HTMLDivElement>(null);
  const recogRef = React.useRef<any>(null);

  const [openMail, setOpenMail] = React.useState(false);
  const [openSettings, setOpenSettings] = React.useState(false);
  const [openDeng, setOpenDeng] = React.useState(false);
  const [openInfo, setOpenInfo] = React.useState(false);
  const [openAddPanel, setOpenAddPanel] = React.useState(false);
  const [openToolbox, setOpenToolbox] = React.useState(false);
  const [openHistory, setOpenHistory] = React.useState(false);
  const [webSearch, setWebSearch] = React.useState(false);
  const [chatStyle, setChatStyle] = React.useState<"professional" | "creative" | "communal">("professional");
  const [activeAgent, setActiveAgent] = React.useState<string | null>(null);
  // Attachments queued for next send (images become multi-modal, others go as filename)
  type Attachment = { id: string; name: string; kind: "image" | "file"; dataUrl?: string };
  const [attachments, setAttachments] = React.useState<Attachment[]>([]);
  const fileInputRef = React.useRef<HTMLInputElement>(null);
  const cameraInputRef = React.useRef<HTMLInputElement>(null);
  const photoInputRef = React.useRef<HTMLInputElement>(null);

  // Append voice-mode transcript turns into the unified session log.
  const handleVoiceTurn = React.useCallback((t: DengTranscriptTurn) => {
    setTurns((prev) => [
      ...prev,
      { id: crypto.randomUUID(), side: t.side, text: t.text, source: t.source, ts: t.ts },
    ]);
  }, []);

  // Gesture-preserving entry into video voice mode (iOS Safari requires the
  // getUserMedia call to live inside the click handler — not behind an effect).
  const openVideoVoiceMode = React.useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" } });
      setVoiceVideoStream(stream);
      setVoiceWithVideo(true);
      setVoiceMode(true);
    } catch (err: any) {
      const denied = err?.name === "NotAllowedError" || err?.name === "SecurityError";
      const notFound = err?.name === "NotFoundError";
      toast.warning(
        denied
          ? "🎥 Kamera izni reddedildi"
          : notFound
            ? "🎥 Kamera bulunamadı"
            : "🎥 Kameraya erişilemedi",
        {
          description: denied
            ? "Görüntülü konuşma açılamadı. Tarayıcı/sistem ayarlarından kamera iznini açabilirsin. Sesli moda geçiyoruz."
            : "Görüntü açılamadı. Sesli moda geçiyoruz.",
          duration: 6000,
        },
      );
      setVoiceVideoStream(null);
      setVoiceWithVideo(false);
      setVoiceMode(true);
    }
  }, []);

  const readAsDataUrl = (f: File) =>
    new Promise<string>((resolve, reject) => {
      const r = new FileReader();
      r.onload = () => resolve(String(r.result));
      r.onerror = () => reject(r.error);
      r.readAsDataURL(f);
    });

  const handleAttach = async (f: File, kind: "image" | "file") => {
    try {
      if (kind === "image") {
        if (f.size > 8 * 1024 * 1024) {
          toast.error("Görsel 8MB'den büyük olamaz");
          return;
        }
        const dataUrl = await readAsDataUrl(f);
        setAttachments((a) => [...a, { id: crypto.randomUUID(), name: f.name, kind, dataUrl }]);
      } else {
        setAttachments((a) => [...a, { id: crypto.randomUUID(), name: f.name, kind }]);
      }
      setOpenAddPanel(false);
      toast.success(kind === "image" ? "Görsel hazır" : "Dosya hazır");
    } catch (e) {
      console.error(e);
      toast.error("Dosya okunamadı");
    }
  };

  const greetingName = React.useMemo(() => {
    const meta: any = user?.user_metadata ?? {};
    return (
      meta.display_name || meta.full_name || meta.name ||
      (user?.email ? user.email.split("@")[0] : "Master")
    );
  }, [user]);

  // Üstten aşağı swipe → sayfayı kapat (ana ekrana dön)
  // Sadece scroller en üstteyken tetiklenir, böylece normal scroll bozulmaz.
  const swipeStartY = React.useRef<number | null>(null);
  const swipeStartScroll = React.useRef<number>(0);
  const handlePageTouchStart = (e: React.TouchEvent) => {
    swipeStartY.current = e.touches[0].clientY;
    swipeStartScroll.current = window.scrollY || document.documentElement.scrollTop || 0;
  };
  const handlePageTouchEnd = (e: React.TouchEvent) => {
    if (swipeStartY.current == null) return;
    const dy = e.changedTouches[0].clientY - swipeStartY.current;
    if (swipeStartScroll.current <= 4 && dy > 120) {
      navigate({ to: "/" });
    }
    swipeStartY.current = null;
  };

  // Pull-to-refresh: sohbeti temizler
  const { pullDistance, refreshing, threshold } = usePullToRefresh({
    onRefresh: async () => {
      setTurns([]);
      setText("");
      setThinking(false);
      try { recogRef.current?.stop(); } catch {}
      setListening(false);
      toast.success("Deng sıfırlandı");
    },
  });

  React.useEffect(() => {
    scrollerRef.current?.scrollTo({
      top: scrollerRef.current.scrollHeight,
      behavior: "smooth",
    });
  }, [turns, thinking]);

  const ask = React.useCallback(
    async (input: string) => {
      const trimmed = input.trim();
      if ((!trimmed && attachments.length === 0) || thinking) return;

      // ─── Sovereign Phone köprüsü ─────────────────────────────────
      // Kullanıcı "ara +777 1234 5678" / "call +777 …" gibi yazdıysa
      // Skip Sovereign Intelligence routing — go straight to placeCall. The
      // olarak Deng "📞 Aranıyor: +777 …" balonu basar.
      const cmd = parseCallCommand(trimmed);
      if (cmd) {
        setText("");
        const userTurn: ChatTurn = {
          id: crypto.randomUUID(),
          side: "user",
          text: trimmed,
        };
        const dengId = crypto.randomUUID();
        setTurns((t) => [
          ...t,
          userTurn,
          { id: dengId, side: "deng", text: `📞 Aranıyor: ${cmd.kurdId}…` },
        ]);

        logLocalOutgoingCall(cmd.kurdId, cmd.video, "Giden Arama");
        const peer = await lookupByKurdId(cmd.kurdId);
        if (!peer?.user_id) {
          setTurns((prev) =>
            prev.map((t) =>
              t.id === dengId
                ? { ...t, text: `📞 ${cmd.kurdId} Sovereign ağda kayıtlı değil. Sadece +777 yurttaşları aranabilir.` }
                : t,
            ),
          );
          return;
        }
        const res = await placeCall(peer.user_id, cmd.video);
        if (!res.ok) {
          setTurns((prev) =>
            prev.map((t) =>
              t.id === dengId
                ? { ...t, text: `📞 Şifreli hat açılamadı: ${res.reason ?? "bilinmeyen hata"}` }
                : t,
            ),
          );
          return;
        }
        // Phone aktif çağrı overlay'ini global SovereignCallScreen açar.
        // Kullanıcıya Phone app'ine yönlendirme önerisini de bot mesajına ekle.
        setTurns((prev) =>
          prev.map((t) =>
            t.id === dengId
              ? {
                  ...t,
                  text: `📞 ${cmd.video ? "Görüntülü arama" : "Sesli arama"} başlatıldı: ${cmd.kurdId}\n\n_Çağrı ekranı tam ekran açıldı; kapatmak için aşağı kaydır._`,
                }
              : t,
          ),
        );
        return;
      }
      // ────────────────────────────────────────────────────────────

      setText("");
      const localAttachments = attachments;
      setAttachments([]);
      const attachLabel = localAttachments.length
        ? localAttachments.map((a) => `[${a.kind === "image" ? "🖼️" : "📎"} ${a.name}]`).join(" ")
        : "";
      const displayText = [trimmed, attachLabel].filter(Boolean).join("\n");
      const userTurn: ChatTurn = {
        id: crypto.randomUUID(),
        side: "user",
        text: displayText,
        source: "text",
        ts: Date.now(),
      };
      const dengId = crypto.randomUUID();
      setTurns((t) => [...t, userTurn, { id: dengId, side: "deng", text: "", source: "text", ts: Date.now() }]);
      setThinking(true);

      try {
        // Build multimodal content if there are images
        const hasImages = localAttachments.some((a) => a.kind === "image" && a.dataUrl);
        let lastUserContent: any;
        if (hasImages) {
          const parts: any[] = [{ type: "text", text: trimmed || "Bu görseli analiz et." }];
          for (const a of localAttachments) {
            if (a.kind === "image" && a.dataUrl) {
              parts.push({ type: "image_url", image_url: { url: a.dataUrl } });
            } else {
              parts.push({ type: "text", text: `(Ek dosya: ${a.name})` });
            }
          }
          lastUserContent = parts;
        } else {
          lastUserContent = displayText;
        }

        const history = [
          ...turns.map((t) => ({
            role: t.side === "user" ? "user" : "assistant",
            content: t.text,
          })),
          { role: "user", content: lastUserContent },
        ];

        const resp = await fetch(DENG_URL, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}`,
          },
          body: JSON.stringify({ messages: history }),
        });

        if (!resp.ok || !resp.body) {
          const err = await resp.text().catch(() => "");
          throw new Error(err || `HTTP ${resp.status}`);
        }

        const reader = resp.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";
        let acc = "";

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });
          let idx;
          while ((idx = buffer.indexOf("\n")) !== -1) {
            let line = buffer.slice(0, idx);
            buffer = buffer.slice(idx + 1);
            if (line.endsWith("\r")) line = line.slice(0, -1);
            if (!line.startsWith("data: ")) continue;
            const json = line.slice(6).trim();
            if (json === "[DONE]") continue;
            try {
              const parsed = JSON.parse(json);
              const delta = parsed.choices?.[0]?.delta?.content;
              if (delta) {
                acc += delta;
                if (thinking) setThinking(false);
                setTurns((prev) =>
                  prev.map((t) => (t.id === dengId ? { ...t, text: acc } : t)),
                );
              }
            } catch {
              buffer = line + "\n" + buffer;
              break;
            }
          }
        }
      } catch (e) {
        console.error(e);
        setTurns((prev) =>
          prev.map((t) =>
            t.id === dengId
              ? {
                  ...t,
                  text: "❌ Şu an Deng beynine ulaşamıyorum. Birazdan tekrar dene.",
                }
              : t,
          ),
        );
      } finally {
        setThinking(false);
      }
    },
    [thinking, turns, placeCall, attachments],
  );

  const speakLast = React.useCallback(async () => {
    const last = [...turns].reverse().find((t) => t.side === "deng" && t.text);
    if (!last) return;
    const r = await VoiceService.synthesize({ text: last.text, lang: "tr" });
    if (r.audioUrl) {
      const a = new Audio(r.audioUrl);
      try {
        await a.play();
      } catch {}
    }
  }, [turns]);

  // ─── Sesli mod (Web Speech API) ──────────────────────────────
  const startListening = React.useCallback(() => {
    const SR =
      (window as any).SpeechRecognition ||
      (window as any).webkitSpeechRecognition;
    if (!SR) {
      toast.error("Bu cihaz/tarayıcı sesli komutu desteklemiyor");
      return;
    }
    try {
      const r = new SR();
      r.lang = "tr-TR";
      r.continuous = false;
      r.interimResults = true;
      r.onresult = (e: any) => {
        let s = "";
        for (let i = e.resultIndex; i < e.results.length; i++) {
          s += e.results[i][0].transcript;
        }
        setText(s);
        if (e.results[e.results.length - 1].isFinal) {
          setListening(false);
          ask(s);
        }
      };
      r.onend = () => setListening(false);
      r.onerror = (ev: any) => {
        setListening(false);
        if (ev?.error === "not-allowed") {
          toast.error("Mikrofon izni reddedildi");
        } else if (ev?.error === "no-speech") {
          toast("Ses algılanmadı, tekrar dene");
        }
      };
      recogRef.current = r;
      setListening(true);
      r.start();
    } catch (e) {
      setListening(false);
      toast.error("Sesli mod başlatılamadı");
    }
  }, [ask]);

  const stopListening = React.useCallback(() => {
    try { recogRef.current?.stop(); } catch {}
    setListening(false);
  }, []);

  React.useEffect(() => {
    return () => {
      try { recogRef.current?.stop(); } catch {}
    };
  }, []);

  return (
    <div
      className="relative min-h-screen overflow-x-hidden bg-background pb-40 text-foreground"
      onTouchStart={handlePageTouchStart}
      onTouchEnd={handlePageTouchEnd}
    >
      <PullToRefreshIndicator
        pullDistance={pullDistance}
        refreshing={refreshing}
        threshold={threshold}
      />
      {/* Soft theme-color top glow (no yellow) */}
      <div
        className="pointer-events-none absolute inset-x-0 top-0 h-64 opacity-40"
        style={{
          background:
            "radial-gradient(ellipse at 50% 0%, hsl(var(--primary) / 0.25), transparent 60%)",
        }}
      />

      {/* Sovereign Intelligence header — golden serif on black */}
      <header
        className="relative px-6 text-center"
        style={{ paddingTop: "calc(env(safe-area-inset-top, 0px) + 24px)" }}
      >
        <h1
          className="text-2xl font-semibold tracking-[0.32em] text-amber-300"
          style={{ fontFamily: "'Cinzel', serif" }}
        >
          DENG AI
        </h1>
        <p className="mt-1 text-[10px] uppercase tracking-[0.42em] text-amber-200/55">
          Sovereign Intelligence
        </p>

        {/* Unified transcript history (text + voice) */}
        <button
          type="button"
          onClick={() => setOpenHistory(true)}
          aria-label="Konuşma geçmişi"
          className="absolute right-4 top-[calc(env(safe-area-inset-top,0px)+24px)] flex h-10 items-center gap-1.5 rounded-full border border-amber-300/30 bg-amber-300/10 px-3 text-[11px] font-medium text-amber-200 backdrop-blur-xl active:scale-95"
        >
          <History className="h-3.5 w-3.5" />
          Geçmiş
          {turns.length > 0 && (
            <span className="ml-0.5 rounded-full bg-amber-300/25 px-1.5 text-[10px]">{turns.length}</span>
          )}
        </button>
      </header>

      {/* Chat */}
      <section
        ref={scrollerRef}
        className="space-y-3 px-4 pt-6"
        style={{ minHeight: "calc(100vh - 360px)" }}
      >
        {turns.length === 0 && !thinking && (
          <DengWelcome
            name={greetingName}
            onPick={(prompt) => {
              setText(prompt);
              setTimeout(() => ask(prompt), 30);
            }}
          />
        )}
        {turns.map((t) =>
          t.text || t.side === "user" ? (
            <GlassBubble key={t.id} side={t.side}>
              {t.text}
            </GlassBubble>
          ) : null,
        )}
        {thinking && (
          <GlassBubble side="deng">
            <ThinkingDots />
          </GlassBubble>
        )}
      </section>

      {/* ChatGPT-style composer with + (Add panel) and Toolbox */}
      <section className="fixed inset-x-0 bottom-[96px] z-30 px-3">
        <div className="mx-auto max-w-2xl">
          {(activeAgent || webSearch || chatStyle !== "professional") && (
            <div className="mb-2 flex flex-wrap gap-1.5 px-2">
              {activeAgent && (
                <ActiveChip
                  label={`REBÊR · ${activeAgent}`}
                  onClear={() => setActiveAgent(null)}
                />
              )}
              {webSearch && (
                <ActiveChip
                  label="🌐 Web Search"
                  onClear={() => setWebSearch(false)}
                />
              )}
              {chatStyle !== "professional" && (
                <ActiveChip
                  label={`Style · ${chatStyle}`}
                  onClear={() => setChatStyle("professional")}
                />
              )}
            </div>
          )}
          {attachments.length > 0 && (
            <div className="mb-2 flex flex-wrap gap-1.5 px-2">
              {attachments.map((a) => (
                <span
                  key={a.id}
                  className="inline-flex items-center gap-1.5 rounded-full border border-amber-300/30 bg-amber-300/10 px-2 py-1 text-[11px] text-amber-100"
                >
                  {a.kind === "image" && a.dataUrl ? (
                    <img src={a.dataUrl} alt="" className="h-5 w-5 rounded object-cover" />
                  ) : a.kind === "image" ? (
                    <ImageIcon className="h-3 w-3" />
                  ) : (
                    <Paperclip className="h-3 w-3" />
                  )}
                  <span className="max-w-[120px] truncate">{a.name}</span>
                  <button
                    type="button"
                    onClick={() =>
                      setAttachments((prev) => prev.filter((x) => x.id !== a.id))
                    }
                    aria-label="Kaldır"
                    className="opacity-70 hover:opacity-100"
                  >
                    <XIcon className="h-3 w-3" />
                  </button>
                </span>
              ))}
            </div>
          )}
          <div className="flex items-end gap-1.5 rounded-[28px] border border-white/10 bg-background/80 px-2 py-2 shadow-[0_8px_32px_-12px_rgba(0,0,0,0.6)] backdrop-blur-2xl">
            <Button
              type="button"
              size="icon"
              variant="ghost"
              onClick={() => setOpenAddPanel(true)}
              aria-label="Ekle"
              className="h-9 w-9 shrink-0 rounded-full hover:bg-white/10"
            >
              <Plus className="h-5 w-5" />
            </Button>
            <Textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  ask(text);
                }
              }}
              placeholder={listening ? "Dinleniyor…" : "Deng AI'a sor"}
              rows={1}
              className="min-h-[40px] max-h-40 resize-none border-0 bg-transparent px-1 py-2 text-base focus-visible:ring-0"
            />
            <Button
              type="button"
              size="icon"
              variant="ghost"
              onClick={() => setOpenToolbox(true)}
              aria-label="Toolbox · REBÊR Agents"
              className="relative h-9 w-9 shrink-0 rounded-full hover:bg-white/10"
            >
              <Wrench className="h-4 w-4" />
              {activeAgent && (
                <span
                  className="absolute -right-0.5 -top-0.5 h-2 w-2 rounded-full bg-amber-400"
                  style={{ boxShadow: "0 0 6px rgba(251,191,36,0.9)" }}
                />
              )}
            </Button>
            {text.trim() || attachments.length > 0 ? (
              <Button
                type="button"
                size="icon"
                onClick={() => ask(text)}
                disabled={thinking}
                aria-label="Gönder"
                className="h-9 w-9 shrink-0 rounded-full bg-foreground text-background hover:bg-foreground/90"
              >
                <Send className="h-4 w-4" />
              </Button>
            ) : (
              <>
                <Button
                  type="button"
                  size="icon"
                  variant="ghost"
                  onClick={() => { void openVideoVoiceMode(); }}
                  aria-label="Görüntülü sohbet"
                  className="h-9 w-9 shrink-0 rounded-full hover:bg-white/10"
                >
                  <VideoIcon className="h-4 w-4" />
                </Button>
                <Button
                  type="button"
                  size="icon"
                  variant="ghost"
                  onClick={() => {
                    setVoiceVideoStream(null);
                    setVoiceWithVideo(false);
                    setVoiceMode(true);
                  }}
                  aria-label="Sesli sohbet"
                  className="h-9 w-9 shrink-0 rounded-full bg-foreground text-background hover:bg-foreground/90"
                >
                  <AudioLines className="h-4 w-4" />
                </Button>
              </>
            )}
          </div>
        </div>
      </section>

      {/* Hidden file inputs for Add panel */}
      <input
        ref={cameraInputRef}
        type="file"
        accept="image/*"
        capture="environment"
        className="hidden"
        onChange={(e) => {
          const f = e.target.files?.[0];
          if (f) handleAttach(f, "image");
          e.target.value = "";
        }}
      />
      <input
        ref={photoInputRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={(e) => {
          const f = e.target.files?.[0];
          if (f) handleAttach(f, "image");
          e.target.value = "";
        }}
      />
      <input
        ref={fileInputRef}
        type="file"
        className="hidden"
        onChange={(e) => {
          const f = e.target.files?.[0];
          if (f) handleAttach(f, f.type.startsWith("image/") ? "image" : "file");
          e.target.value = "";
        }}
      />

      {/* Add Panel — Claude style */}
      <IOSBottomSheet open={openAddPanel} onOpenChange={setOpenAddPanel} title="Ekle">
        <div className="space-y-4">
          <div className="grid grid-cols-3 gap-2">
            <AddTile icon={<Camera className="h-5 w-5" />} label="Kamera" onClick={() => cameraInputRef.current?.click()} />
            <AddTile icon={<ImageIcon className="h-5 w-5" />} label="Fotoğraflar" onClick={() => photoInputRef.current?.click()} />
            <AddTile icon={<Paperclip className="h-5 w-5" />} label="Dosya" onClick={() => fileInputRef.current?.click()} />
          </div>
          <ToggleRow
            icon={<Globe className="h-4 w-4" />}
            label="Web'de Ara"
            sub="Yanıtları güncel web bilgisiyle zenginleştir"
            on={webSearch}
            onChange={setWebSearch}
          />
          <div className="rounded-2xl border border-white/10 bg-white/5 p-3">
            <div className="mb-2 flex items-center gap-2 text-sm font-medium">
              <Palette className="h-4 w-4" /> Style
            </div>
            <div className="flex gap-2">
              {(["professional", "creative", "communal"] as const).map((s) => (
                <button
                  key={s}
                  type="button"
                  onClick={() => setChatStyle(s)}
                  className={`flex-1 rounded-xl border px-2 py-2 text-xs capitalize transition ${
                    chatStyle === s
                      ? "border-amber-300/60 bg-amber-300/10 text-amber-200"
                      : "border-white/10 bg-white/5 text-muted-foreground hover:bg-white/10"
                  }`}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        </div>
      </IOSBottomSheet>

      {/* Toolbox — REBÊR Agents */}
      <IOSBottomSheet open={openToolbox} onOpenChange={setOpenToolbox} title="REBÊR Toolbox">
        <p className="mb-3 text-sm text-muted-foreground">
          Bir uzman ajanı manuel olarak seç. Yanıtlar onun perspektifinden gelir.
        </p>
        <div className="grid grid-cols-2 gap-2">
          {[
            { id: "Dengbêj", desc: "Hikâye, şiir, dengbêjlik" },
            { id: "Mîmar", desc: "Mimari, tasarım, plan" },
            { id: "Zanyar", desc: "Manifesto, analiz" },
            { id: "Hekîm", desc: "Sağlık ve şifa" },
            { id: "Lojîstîk", desc: "Görev, plan, takvim" },
            { id: "Ronak", desc: "Eğitim ve dil" },
          ].map((a) => (
            <button
              key={a.id}
              type="button"
              onClick={() => {
                setActiveAgent(a.id === activeAgent ? null : a.id);
                setOpenToolbox(false);
              }}
              className={`group relative overflow-hidden rounded-2xl border p-3 text-left transition ${
                activeAgent === a.id
                  ? "border-amber-300/60 bg-amber-300/10"
                  : "border-white/10 bg-white/5 hover:bg-white/10"
              }`}
            >
              <div className="flex items-center gap-2 text-sm font-medium">
                <span
                  className="inline-block h-2 w-2 rounded-full bg-amber-300"
                  style={{
                    boxShadow: "0 0 8px rgba(251,191,36,0.85)",
                    animation: activeAgent === a.id ? "deng-pulse 1.4s ease-in-out infinite" : undefined,
                  }}
                />
                {a.id}
              </div>
              <div className="mt-1 text-[11px] text-muted-foreground">{a.desc}</div>
            </button>
          ))}
        </div>
      </IOSBottomSheet>

      <IOSBottomSheet open={openDeng} onOpenChange={setOpenDeng} title="Quick Ask">
        <p className="mb-3 text-sm text-muted-foreground">
          Hızlı bir soru — Deng anında yanıtlasın.
        </p>
        <div className="flex flex-col gap-2">
          <Textarea
            placeholder="Yaz…"
            rows={4}
            id="deng-quick"
            className="rounded-2xl"
          />
          <Button
            className="rounded-2xl bg-primary text-primary-foreground"
            onClick={() => {
              const el = document.getElementById("deng-quick") as HTMLTextAreaElement | null;
              if (el?.value) {
                ask(el.value);
                setOpenDeng(false);
              }
            }}
          >
            Ask Deng
          </Button>
        </div>
      </IOSBottomSheet>

      <IOSBottomSheet open={openMail} onOpenChange={setOpenMail} title="Deng Bot">
        <DengBotInbox />
      </IOSBottomSheet>

      <IOSBottomSheet open={openSettings} onOpenChange={setOpenSettings} title="Settings">
        <div className="space-y-3 text-sm">
          <div className="rounded-2xl border border-white/10 bg-white/5 p-3">
            <div className="font-medium">AI brain</div>
            <div className="text-xs text-muted-foreground">
              Active: <span className="font-medium text-primary">Jiyan Sovereign Intelligence</span>
            </div>
          </div>
          <div className="rounded-2xl border border-white/10 bg-white/5 p-3">
            <div className="font-medium">Dock customization</div>
            <div className="text-xs text-muted-foreground">
              Long-press any dock icon to enter Jiggle Mode and swap apps.
            </div>
          </div>
        </div>
      </IOSBottomSheet>

      <IOSBottomSheet open={openInfo} onOpenChange={setOpenInfo} title="SterkOS Elite">
        <p className="text-sm text-muted-foreground">
          iOS 18 floating glass dock · 90vh bottom sheets · Jiyan Sovereign Intelligence · theme-aware glass bubbles.
        </p>
      </IOSBottomSheet>

      {/* ChatGPT-tarzı tam ekran sesli sohbet */}
      <DengVoiceMode
        open={voiceMode}
        initialVideo={voiceWithVideo}
        initialVideoStream={voiceVideoStream}
        onTurn={handleVoiceTurn}
        onOpenHistory={() => setOpenHistory(true)}
        onClose={() => {
          setVoiceMode(false);
          setVoiceWithVideo(false);
          setVoiceVideoStream(null);
        }}
        onFallbackToText={() => {
          setVoiceMode(false);
          setVoiceWithVideo(false);
          setVoiceVideoStream(null);
        }}
      />

      {/* Unified transcript history — text + voice in one place */}
      <IOSBottomSheet open={openHistory} onOpenChange={setOpenHistory} title="Konuşma Geçmişi">
        <DengTranscriptHistory
          turns={turns}
          onClear={() => {
            setTurns([]);
            setOpenHistory(false);
            toast.success("Geçmiş temizlendi");
          }}
        />
      </IOSBottomSheet>
    </div>
  );
}

function ThinkingDots() {
  return (
