function DengTranscriptHistory({
  turns,
  onClear,
}: {
  turns: ChatTurn[];
  onClear: () => void;
}) {
  if (turns.length === 0) {
    return (
      <p className="text-sm text-muted-foreground">
        Bu oturumda henüz konuşma yok. Yazılı veya sesli mesaj attıkça hepsi
        burada birikip tek ekrandan geri dönüp görüntülenebilir olacak.
      </p>
    );
  }
  const fmt = (ts?: number) =>
    ts ? new Date(ts).toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" }) : "";
  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <p className="text-xs uppercase tracking-[0.18em] text-muted-foreground">
          {turns.length} mesaj · oturum
