          Temizle
        </button>
      </div>
      <div className="max-h-[70vh] space-y-2 overflow-y-auto pr-1">
        {turns.map((t) => (
          <div
            key={t.id}
            className={`rounded-2xl border px-3 py-2 text-sm ${
              t.side === "user"
                ? "border-amber-300/30 bg-amber-300/5 text-foreground"
                : "border-primary/20 bg-primary/[0.06] text-foreground/90"
            }`}
          >
            <div className="mb-0.5 flex items-center gap-2 text-[10px] uppercase tracking-[0.18em] text-muted-foreground">
              <span>{t.side === "user" ? "Sen" : "Deng"}</span>
              <span className="rounded-full bg-white/5 px-1.5 py-0.5">
                {t.source === "voice" ? "🎙️ sesli" : "⌨️ yazılı"}
              </span>
              <span className="ml-auto">{fmt(t.ts)}</span>
            </div>
            <div className="whitespace-pre-wrap leading-relaxed">{t.text}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

