import { createFileRoute, Link } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { AppShell } from "@/components/layout/AppShell";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Plus, Copy, Trash2, Shield, CheckCircle2, ExternalLink, Code2 } from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/developers/sso")({
  component: DevelopersSso,
  head: () => ({
    meta: [{ title: "Kurd-ID Login — Developer Portal" }],
  }),
});

interface SsoApp {
  id: string;
  client_id: string;
  app_name: string;
  app_description: string;
  logo_url: string | null;
  homepage_url: string | null;
  redirect_uris: string[];
  scopes: string[];
  is_verified: boolean;
  is_active: boolean;
  created_at: string;
}

function DevelopersSso() {
  const { user } = useAuth();
  const [apps, setApps] = useState<SsoApp[]>([]);
  const [loading, setLoading] = useState(true);
  const [createOpen, setCreateOpen] = useState(false);
  const [secretShown, setSecretShown] = useState<{ client_id: string; client_secret: string } | null>(null);

  const [form, setForm] = useState({
    app_name: "",
    app_description: "",
    homepage_url: "",
    logo_url: "",
    redirect_uris: "",
  });

  const load = async () => {
    if (!user) return;
    setLoading(true);
    const { data, error } = await supabase
      .from("kurdid_sso_apps")
      .select("*")
      .order("created_at", { ascending: false });
    if (error) toast.error(error.message);
    setApps((data ?? []) as SsoApp[]);
    setLoading(false);
  };

  useEffect(() => {
    void load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  const handleCreate = async () => {
    const uris = form.redirect_uris
      .split(/[\n,]/)
      .map((s) => s.trim())
      .filter(Boolean);
    if (uris.length === 0) {
      toast.error("En az 1 redirect URI girin");
      return;
    }
    if (!form.app_name.trim()) {
      toast.error("Uygulama adı gerekli");
      return;
    }
    const { data, error } = await supabase.rpc("kurdid_sso_register_app", {
      _app_name: form.app_name.trim(),
      _app_description: form.app_description.trim(),
      _logo_url: form.logo_url.trim() || undefined,
      _homepage_url: form.homepage_url.trim() || undefined,
      _redirect_uris: uris,
      _scopes: ["openid", "profile", "kurd_id"],
    });
    if (error || !data || data.length === 0) {
      toast.error(error?.message ?? "Kayıt başarısız");
      return;
    }
    const row = data[0] as { client_id: string; client_secret: string };
    setSecretShown({ client_id: row.client_id, client_secret: row.client_secret });
    setCreateOpen(false);
    setForm({ app_name: "", app_description: "", homepage_url: "", logo_url: "", redirect_uris: "" });
    void load();
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Bu uygulamayı sil? Tüm aktif oturumlar iptal edilecek.")) return;
    const { error } = await supabase.from("kurdid_sso_apps").delete().eq("id", id);
    if (error) {
      toast.error(error.message);
      return;
    }
    toast.success("Uygulama silindi");
    void load();
  };

  const copy = (s: string) => {
    navigator.clipboard.writeText(s);
    toast.success("Panoya kopyalandı");
  };

  return (
    <AppShell>
      <div className="container mx-auto max-w-3xl px-4 py-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold">Kurd-ID Login Bot</h1>
            <p className="text-sm text-muted-foreground">3. parti uygulamalarınızı kaydedin</p>
          </div>
          <Dialog open={createOpen} onOpenChange={setCreateOpen}>
            <DialogTrigger asChild>
              <Button>
                <Plus className="mr-1 h-4 w-4" /> Yeni
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Yeni SSO uygulaması</DialogTitle>
              </DialogHeader>
              <div className="space-y-3">
                <div>
                  <Label>Uygulama adı *</Label>
                  <Input value={form.app_name} onChange={(e) => setForm({ ...form, app_name: e.target.value })} placeholder="Örn: Kürdistan Forum" />
                </div>
                <div>
                  <Label>Açıklama</Label>
                  <Textarea value={form.app_description} onChange={(e) => setForm({ ...form, app_description: e.target.value })} rows={2} />
                </div>
                <div>
                  <Label>Anasayfa URL</Label>
                  <Input value={form.homepage_url} onChange={(e) => setForm({ ...form, homepage_url: e.target.value })} placeholder="https://example.com" />
                </div>
                <div>
                  <Label>Logo URL</Label>
                  <Input value={form.logo_url} onChange={(e) => setForm({ ...form, logo_url: e.target.value })} placeholder="https://example.com/logo.png" />
                </div>
                <div>
                  <Label>Redirect URI'ler * (her satıra bir tane)</Label>
                  <Textarea
                    value={form.redirect_uris}
                    onChange={(e) => setForm({ ...form, redirect_uris: e.target.value })}
                    rows={3}
                    placeholder="https://example.com/auth/callback"
                  />
                </div>
                <Button className="w-full" onClick={handleCreate}>
                  Oluştur
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>

        {/* Newly issued secret — show ONCE */}
        {secretShown && (
          <Card className="mt-4 border-primary/40 bg-primary/5 p-4">
            <div className="flex items-start gap-2">
              <CheckCircle2 className="mt-0.5 h-5 w-5 text-primary" />
              <div className="flex-1 space-y-3">
                <div>
                  <div className="text-sm font-semibold">Uygulama oluşturuldu!</div>
                  <p className="text-xs text-muted-foreground">
                    <strong>client_secret</strong> sadece şimdi gösterilir. Güvenli bir yere kaydet.
                  </p>
                </div>
                <div>
                  <Label className="text-xs">client_id</Label>
                  <div className="flex gap-1">
                    <code className="flex-1 truncate rounded bg-muted px-2 py-1 text-xs">{secretShown.client_id}</code>
                    <Button size="icon" variant="ghost" onClick={() => copy(secretShown.client_id)}>
                      <Copy className="h-3 w-3" />
                    </Button>
                  </div>
                </div>
                <div>
                  <Label className="text-xs">client_secret</Label>
                  <div className="flex gap-1">
                    <code className="flex-1 truncate rounded bg-muted px-2 py-1 text-xs">{secretShown.client_secret}</code>
                    <Button size="icon" variant="ghost" onClick={() => copy(secretShown.client_secret)}>
                      <Copy className="h-3 w-3" />
                    </Button>
                  </div>
                </div>
                <Button size="sm" variant="outline" onClick={() => setSecretShown(null)}>
                  Kaydettim, kapat
                </Button>
              </div>
            </div>
          </Card>
        )}

        {/* Integration docs */}
        <Card className="mt-4 p-4">
          <div className="flex items-start gap-2">
            <Code2 className="mt-0.5 h-5 w-5 text-primary" />
            <div className="flex-1 text-sm">
              <div className="font-semibold">Entegrasyon</div>
              <ol className="mt-2 list-inside list-decimal space-y-1 text-xs text-muted-foreground">
                <li>
                  Kullanıcıyı yönlendir:{" "}
                  <code className="rounded bg-muted px-1">{window.location.origin}/sso/authorize?client_id=...&redirect_uri=...&state=...</code>
                </li>
                <li>
                  Callback'te <code>?code=...</code> al
                </li>
                <li>
                  Token al: <code>POST {window.location.origin}/api/public/sso/token</code> → <code>access_token</code> + <code>refresh_token</code>
                </li>
                <li>
                  Profil al: <code>GET {window.location.origin}/api/public/sso/userinfo</code> (Bearer token)
                </li>
                <li>
                  Token yenile: <code>POST {window.location.origin}/api/public/sso/refresh</code> (refresh_token ile, 1 saatte bir)
                </li>
                <li>
                  Token iptal et: <code>POST {window.location.origin}/api/public/sso/revoke</code> (RFC 7009)
                </li>
              </ol>

              <div className="mt-3 rounded-lg border border-border bg-muted/40 p-2">
                <div className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
                  "Login with Kurd-ID" butonu (kopyala-yapıştır)
                </div>
                <pre className="overflow-x-auto text-[10px] leading-relaxed text-foreground">
{`<a href="${window.location.origin}/sso/authorize?client_id=YOUR_CLIENT_ID&redirect_uri=https://yoursite.com/callback&scope=openid profile kurd_id&state=RANDOM" style="display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:12px;background:#facc15;color:#000;font-weight:600;text-decoration:none">
  🛡️ Login with Kurd-ID
</a>`}
                </pre>
              </div>
            </div>
          </div>
        </Card>

        {/* App list */}
        <div className="mt-6 space-y-3">
          {loading ? (
            <p className="text-sm text-muted-foreground">Yükleniyor…</p>
          ) : apps.length === 0 ? (
            <Card className="p-8 text-center text-sm text-muted-foreground">
              <Shield className="mx-auto mb-2 h-8 w-8 opacity-50" />
              Henüz uygulama yok
            </Card>
          ) : (
            apps.map((a) => (
              <Card key={a.id} className="p-4">
                <div className="flex items-start gap-3">
                  {a.logo_url ? (
                    <img src={a.logo_url} alt="" className="h-10 w-10 rounded-lg object-cover" />
                  ) : (
                    <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
                      <Shield className="h-5 w-5 text-primary" />
                    </div>
                  )}
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                      <h3 className="truncate font-semibold">{a.app_name}</h3>
                      {a.is_verified && <CheckCircle2 className="h-4 w-4 text-primary" />}
                    </div>
                    <div className="mt-1 flex items-center gap-1">
                      <code className="truncate rounded bg-muted px-1 py-0.5 text-[10px]">{a.client_id}</code>
                      <Button size="icon" variant="ghost" className="h-6 w-6" onClick={() => copy(a.client_id)}>
                        <Copy className="h-3 w-3" />
                      </Button>
                    </div>
                    <div className="mt-2 flex flex-wrap gap-1">
                      {a.scopes.map((s) => (
                        <span key={s} className="rounded bg-muted px-1.5 py-0.5 text-[10px]">
                          {s}
                        </span>
                      ))}
                    </div>
                  </div>
                  <div className="flex flex-col gap-1">
                    {a.homepage_url && (
                      <Button asChild size="icon" variant="ghost" className="h-7 w-7">
                        <a href={a.homepage_url} target="_blank" rel="noreferrer">
                          <ExternalLink className="h-3 w-3" />
                        </a>
                      </Button>
                    )}
                    <Button size="icon" variant="ghost" className="h-7 w-7 text-destructive" onClick={() => handleDelete(a.id)}>
                      <Trash2 className="h-3 w-3" />
                    </Button>
                  </div>
                </div>
              </Card>
            ))
          )}
        </div>

        <div className="mt-6 text-center">
          <Link to="/kurd-id" className="text-xs text-muted-foreground underline">
            ← Kurd-ID kartına dön
          </Link>
        </div>
      </div>
    </AppShell>
  );
}

