  const {
    questions,
    loading,
    stats,
    fetchQuestions,
    recordAnswer,
    createExamSession,
    finishExamSession,
    fetchStats,
    generateAIQuestions,
  } = useDrivingExam();

  const [view, setView] = useState<AppView>("menu");
  const [country, setCountry] = useState("NL");
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [correctCount, setCorrectCount] = useState(0);
  const [totalAnswered, setTotalAnswered] = useState(0);
  const [examSessionId, setExamSessionId] = useState<string | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);
  const [generating, setGenerating] = useState(false);
  const [isExamMode, setIsExamMode] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const currentQuestion: DrivingQuestion | undefined = questions[currentIndex];

  // Exam timer
  useEffect(() => {
    if (!isExamMode || timeLeft <= 0) return;
    timerRef.current = setInterval(() => {
      setTimeLeft((t) => {
        if (t <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          finishExam();
          return 0;
        }
        return t - 1;
      });
    }, 1000);
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isExamMode, timeLeft > 0]);

  const resetQuiz = () => {
    setCurrentIndex(0);
    setCorrectCount(0);
    setTotalAnswered(0);
    setSelectedAnswer(null);
    setShowExplanation(false);
    setIsExamMode(false);
    setSelectedCategory(null);
  };

  const startCategoryPractice = async (category: string) => {
    resetQuiz();
    setSelectedCategory(category);
    await fetchQuestions({ country, category, limit: 50 });
    setView("practice");
  };

  const startMode = async (mode: string) => {
    resetQuiz();
    if (mode === "random") {
      await fetchQuestions({ country, limit: 50 });
      setView("practice");
    } else if (mode === "hard") {
      await fetchQuestions({ country, difficulty: "hard", limit: 50 });
      setView("practice");
    } else if (mode === "weak") {
      if (stats.weakCategories.length > 0) {
        await fetchQuestions({ country, category: stats.weakCategories[0], limit: 50 });
      } else {
        await fetchQuestions({ country, limit: 50 });
      }
      setView("practice");
    } else if (mode === "full-exam") {
      await startFullExam();
    }
  };

  const startFullExam = async () => {
    if (!user) {
      toast.error("Sınav için giriş yapın");
      return;
    }
    resetQuiz();
    setIsExamMode(true);
    const qs = await fetchQuestions({ country, limit: 40 });
    if (qs.length < 10) {
      toast.error("Yeterli soru yok. AI ile soru oluşturun.");
      setView("menu");
      return;
    }
    const session = await createExamSession(country, Math.min(qs.length, 40));
    if (session) setExamSessionId(session.id);
    setTimeLeft(40 * 60);
    setView("exam");
  };

  const handleAnswer = (answer: string) => {
    if (selectedAnswer) return;
    setSelectedAnswer(answer);
    setShowExplanation(true);
    const isCorrect = answer === currentQuestion?.correct_answer;
    if (isCorrect) setCorrectCount((c) => c + 1);
    setTotalAnswered((t) => t + 1);
    if (user && currentQuestion) recordAnswer(currentQuestion.id, isCorrect);
  };

  const handleNext = () => {
    const limit = isExamMode ? Math.min(questions.length, 40) : questions.length;
    if (currentIndex + 1 >= limit) {
      if (isExamMode) finishExam();
      else setView("result");
      return;
    }
    setCurrentIndex((i) => i + 1);
    setSelectedAnswer(null);
    setShowExplanation(false);
  };

  const finishExam = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current);
    if (examSessionId) finishExamSession(examSessionId, correctCount, totalAnswered || 1);
    fetchStats();
    setView("result");
  }, [examSessionId, correctCount, totalAnswered, finishExamSession, fetchStats]);

  const handleGenerateAI = async () => {
    if (!user) { toast.error("Giriş yapın"); return; }
    setGenerating(true);
    const result = await generateAIQuestions(country, 10);
    setGenerating(false);
    if (result.length > 0) toast.success(`${result.length} yeni soru oluşturuldu!`);
    else toast.error("Soru oluşturulamadı");
  };

  const formatTime = (s: number) => `${Math.floor(s / 60)}:${(s % 60).toString().padStart(2, "0")}`;

  const countries = [
    { code: "NL", name: "Hollanda", flag: "🇳🇱" },
    { code: "DE", name: "Almanya", flag: "🇩🇪" },
    { code: "FR", name: "Fransa", flag: "🇫🇷" },
    { code: "SE", name: "İsveç", flag: "🇸🇪" },
  ];

  // ========== MENU ==========
  if (view === "menu") {
    return (
      <AppShell>
        <div className="px-4 pt-4 pb-24 space-y-5">
          {/* Header */}
          <div className="text-center space-y-2">
            <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-neon/10">
              <Car className="h-7 w-7 text-neon" />
            </div>
            <h1 className="text-xl font-bold text-foreground">Ehliyet Sınavı</h1>
            <p className="text-xs text-muted-foreground">AB Ehliyet Teorisi Hazırlık • 1500+ Soru</p>
          </div>

          {/* Country selector */}
          <div className="flex gap-2 justify-center">
            {countries.map((c) => (
              <button
                key={c.code}
                onClick={() => setCountry(c.code)}
                className={`flex items-center gap-1.5 rounded-full px-3 py-2 text-xs font-medium border transition-all ${
                  country === c.code
                    ? "border-neon bg-neon/10 text-foreground"
                    : "border-border bg-surface text-muted-foreground hover:border-neon/30"
                }`}
              >
                <span className="text-base">{c.flag}</span>
                {c.name}
              </button>
            ))}
          </div>

          {/* Stats quick bar */}
          {user && stats.totalAnswered > 0 && (
            <button onClick={() => setView("stats")} className="w-full">
              <div className="flex items-center gap-3 rounded-xl border border-border bg-surface px-4 py-3">
                <div className="flex-1">
                  <Progress value={stats.readinessScore} className="h-2" />
                </div>
                <span className="text-xs font-bold text-neon">{stats.readinessScore}%</span>
                <span className="text-[10px] text-muted-foreground">hazır</span>
                <BarChart3 className="h-4 w-4 text-muted-foreground" />
              </div>
            </button>
          )}

          {/* Exam Categories Grid */}
          <div className="space-y-2">
            <h2 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Konulara Göre Alıştırma</h2>
            <div className="grid grid-cols-2 gap-2">
              {EXAM_CATEGORIES.map((cat) => (
                <button
                  key={cat.id}
                  onClick={() => startCategoryPractice(cat.id)}
                  disabled={loading}
                  className="flex items-center gap-3 rounded-xl border border-border bg-surface p-3.5 text-left transition-all hover:border-neon/30 active:scale-[0.98]"
                >
                  <span className="text-2xl">{cat.emoji}</span>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-semibold text-foreground truncate">{cat.label}</p>
                  </div>
                </button>
              ))}
            </div>
          </div>

          {/* Exam Modes */}
          <div className="space-y-2">
            <h2 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Sınav Modları</h2>
            <div className="space-y-2">
              {EXAM_MODES.map((mode) => {
                const Icon = mode.icon;
                return (
                  <button
                    key={mode.id}
                    onClick={() => startMode(mode.id)}
                    disabled={loading}
                    className={`w-full flex items-center gap-3 rounded-xl border p-3.5 text-left transition-all active:scale-[0.99] ${mode.color}`}
                  >
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-background/50">
                      <Icon className="h-5 w-5" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-semibold">{mode.label}</p>
                      <p className="text-[11px] opacity-70">{mode.desc}</p>
                    </div>
                    <ChevronRight className="h-4 w-4 opacity-50" />
                  </button>
                );
              })}
            </div>
          </div>

          {/* AI Generate */}
          <div className="rounded-xl border border-gold/20 bg-gold/5 p-4">
            <div className="flex items-center gap-3 mb-3">
              <Sparkles className="h-5 w-5 text-gold" />
              <div>
                <p className="text-sm font-semibold text-foreground">AI Soru Üretici</p>
                <p className="text-[10px] text-muted-foreground">Yapay zeka ile yeni sorular oluşturun</p>
              </div>
            </div>
            <Button
              variant="outline"
              className="w-full gap-2 border-gold/30 hover:bg-gold/10"
              onClick={handleGenerateAI}
              disabled={generating || !user}
            >
              {generating ? <RefreshCw className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4 text-gold" />}
              {generating ? "Üretiliyor..." : `${countries.find(c => c.code === country)?.name} için 10 Soru Oluştur`}
            </Button>
          </div>
        </div>
      </AppShell>
    );
  }

  // ========== STATS ==========
  if (view === "stats") {
    return (
      <AppShell>
        <div className="px-4 pt-4 pb-24 space-y-4">
          <div className="flex items-center gap-3">
            <button onClick={() => setView("menu")} className="flex h-9 w-9 items-center justify-center rounded-xl bg-surface border border-border">
              <ArrowLeft className="h-4 w-4 text-foreground" />
            </button>
            <h1 className="text-lg font-bold text-foreground">İstatistikler</h1>
          </div>

          <div className="rounded-2xl border border-border bg-surface p-5 space-y-4">
            <div className="text-center">
              <p className="text-5xl font-bold text-neon">{stats.readinessScore}%</p>
              <p className="text-sm text-muted-foreground mt-1">Sınav Hazırlık Skoru</p>
              <Progress value={stats.readinessScore} className="mt-3 h-3" />
            </div>

            <div className="grid grid-cols-2 gap-3 pt-2">
              {[
                { label: "Toplam Çözülen", value: stats.totalAnswered, color: "text-foreground" },
                { label: "Başarı Oranı", value: `${stats.successRate}%`, color: "text-neon" },
                { label: "Doğru", value: stats.correctAnswers, color: "text-neon" },
                { label: "Yanlış", value: stats.totalAnswered - stats.correctAnswers, color: "text-destructive" },
              ].map((s) => (
                <div key={s.label} className="rounded-xl border border-border p-3 text-center">
                  <p className={`text-2xl font-bold ${s.color}`}>{s.value}</p>
                  <p className="text-xs text-muted-foreground">{s.label}</p>
                </div>
              ))}
            </div>

            {stats.weakCategories.length > 0 && (
              <div className="pt-2">
                <p className="text-xs font-medium text-muted-foreground mb-2">Zayıf Kategoriler</p>
                <div className="flex flex-wrap gap-2">
                  {stats.weakCategories.map((cat) => {
                    const catInfo = EXAM_CATEGORIES.find(c => c.id === cat);
                    return (
                      <button
                        key={cat}
                        onClick={() => startCategoryPractice(cat)}
                        className="flex items-center gap-1.5 rounded-full bg-destructive/10 px-3 py-1.5 text-xs text-destructive font-medium hover:bg-destructive/20 transition-colors"
                      >
                        {catInfo?.emoji} {catInfo?.label || cat}
                        <ChevronRight className="h-3 w-3" />
                      </button>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        </div>
      </AppShell>
    );
  }

  // ========== RESULT ==========
  if (view === "result") {
    const rate = totalAnswered > 0 ? Math.round((correctCount / totalAnswered) * 100) : 0;
    const passed = rate >= 70;

    return (
      <AppShell>
        <div className="px-4 pt-8 pb-24 flex flex-col items-center text-center space-y-6">
          <div className={`flex h-24 w-24 items-center justify-center rounded-full ${passed ? "bg-neon/15" : "bg-destructive/15"}`}>
            {passed ? <Trophy className="h-12 w-12 text-neon" /> : <XCircle className="h-12 w-12 text-destructive" />}
          </div>

          <div>
            <h1 className="text-2xl font-bold text-foreground">{passed ? "Tebrikler! 🎉" : "Tekrar Deneyin 💪"}</h1>
            <p className="text-sm text-muted-foreground mt-1">
              {passed ? "Sınavı başarıyla geçtiniz!" : "Biraz daha pratik yapmanız gerekiyor."}
            </p>
          </div>

          <div className="grid grid-cols-3 gap-4 w-full max-w-xs">
            <div className="rounded-xl border border-border bg-surface p-3">
              <p className="text-2xl font-bold text-foreground">{totalAnswered}</p>
              <p className="text-[10px] text-muted-foreground">Soru</p>
            </div>
            <div className="rounded-xl border border-border bg-surface p-3">
              <p className="text-2xl font-bold text-neon">{correctCount}</p>
              <p className="text-[10px] text-muted-foreground">Doğru</p>
            </div>
            <div className="rounded-xl border border-border bg-surface p-3">
              <p className={`text-2xl font-bold ${passed ? "text-neon" : "text-destructive"}`}>{rate}%</p>
              <p className="text-[10px] text-muted-foreground">Başarı</p>
            </div>
          </div>

          <Progress value={rate} className="w-full max-w-xs h-3" />

          <div className="flex gap-3 w-full max-w-xs">
            <Button variant="outline" className="flex-1" onClick={() => { resetQuiz(); setView("menu"); }}>
              <ArrowLeft className="h-4 w-4 mr-1" /> Menü
            </Button>
            <Button variant="neon" className="flex-1" onClick={() => { resetQuiz(); setView("menu"); }}>
              <RefreshCw className="h-4 w-4 mr-1" /> Tekrar
            </Button>
          </div>
        </div>
      </AppShell>
    );
  }

  // ========== QUESTION VIEW ==========
  const examLimit = isExamMode ? Math.min(questions.length, 40) : questions.length;
  const progressPct = examLimit > 0 ? ((currentIndex + 1) / examLimit) * 100 : 0;

  if (!currentQuestion) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center pt-32 gap-4 px-4">
          {loading ? (
            <div className="h-8 w-8 animate-spin rounded-full border-2 border-neon border-t-transparent" />
          ) : (
            <>
              <Brain className="h-12 w-12 text-muted-foreground" />
              <p className="text-sm text-muted-foreground text-center">Bu kategori için soru bulunamadı.</p>
              <Button variant="neon" onClick={() => { resetQuiz(); setView("menu"); }}>Menüye Dön</Button>
            </>
          )}
        </div>
      </AppShell>
    );
  }

  const catInfo = EXAM_CATEGORIES.find(c => c.id === currentQuestion.category);

  const categoryColors: Record<string, string> = {
    priority: "bg-red-500",
    signs: "bg-blue-500",
    speed: "bg-orange-500",
    parking: "bg-cyan-500",
    hazard: "bg-yellow-500",
    rules: "bg-green-500",
  };

  return (
    <AppShell>
      <div className="pb-24">
        {/* Top bar */}
        <div className="flex items-center justify-between px-4 py-2 bg-surface border-b border-border">
          <button onClick={() => { resetQuiz(); setView("menu"); }} className="flex items-center gap-1.5 rounded-lg bg-neon/10 px-3 py-2 text-xs font-bold text-neon">
            <ArrowLeft className="h-4 w-4" /> GERİ
          </button>
          <div className="flex items-center gap-2">
            {isExamMode && (
              <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${
                timeLeft < 300 ? "bg-destructive/15 text-destructive" : "bg-neon/15 text-neon"
              }`}>
                ⏱ {formatTime(timeLeft)}
              </span>
            )}
          </div>
          <div className="flex items-center gap-2">
            {isExamMode && (
              <button onClick={finishExam} className="rounded-lg bg-destructive/10 px-3 py-2 text-xs text-destructive font-bold">
                <Flag className="inline h-3 w-3 mr-1" />BİTİR
              </button>
            )}
          </div>
        </div>

        {/* Category header bar - CBR style */}
        <div className={`${categoryColors[currentQuestion.category] || "bg-primary"} px-4 py-2 text-center`}>
          <span className="text-sm font-bold text-white uppercase tracking-wider">
            {catInfo?.emoji} {catInfo?.label || currentQuestion.category}
          </span>
        </div>

        {/* Video or Image - CBR style */}
        {currentQuestion.video_url ? (
          <VideoQuestionPlayer
            videoUrl={currentQuestion.video_url}
            category={currentQuestion.category}
            autoPlay={true}
          />
        ) : currentQuestion.image_url ? (
          <div className="relative">
            {currentQuestion.category === "hazard" && (
              <div className="absolute top-2 right-2 z-10 bg-destructive/90 rounded-full px-3 py-1 flex items-center gap-1.5">
                <span className="relative flex h-2 w-2">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-2 w-2 bg-white"></span>
                </span>
                <span className="text-[10px] font-bold text-white uppercase tracking-wider">TEHLİKE</span>
              </div>
            )}
            <img
              src={currentQuestion.image_url}
              alt="Trafik senaryosu"
              className="w-full h-56 object-cover bg-background"
              loading="lazy"
              onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }}
            />
          </div>
        ) : null}

        <div className="px-4 pt-3 space-y-3">
          {/* Progress + counter */}
          <div className="flex items-center gap-3">
            <Progress value={progressPct} className="flex-1 h-2" />
            <span className="text-xs font-bold text-muted-foreground whitespace-nowrap">{currentIndex + 1} / {examLimit}</span>
          </div>

          {/* Difficulty + exam badges */}
          <div className="flex gap-2">
            <span className={`rounded-full px-2.5 py-0.5 text-[10px] font-medium ${
              currentQuestion.difficulty === "easy" ? "bg-neon/10 text-neon"
              : currentQuestion.difficulty === "hard" ? "bg-destructive/10 text-destructive"
              : "bg-gold/10 text-gold"
            }`}>
              {currentQuestion.difficulty === "easy" ? "Kolay" : currentQuestion.difficulty === "hard" ? "Zor" : "Orta"}
            </span>
            {isExamMode && (
              <span className="rounded-full bg-destructive/10 px-2.5 py-0.5 text-[10px] font-medium text-destructive">
                🔴 SINAV
              </span>
            )}
          </div>

          {/* Question */}
          <div className="rounded-xl border border-border bg-surface p-4">
            <p className="text-sm font-semibold text-foreground leading-relaxed">{currentQuestion.question_text}</p>
          </div>

          {/* Options */}
          <div className="space-y-2">
            {currentQuestion.options.map((option, i) => {
              const letter = String.fromCharCode(65 + i);
              const isSelected = selectedAnswer === letter;
              const isCorrect = letter === currentQuestion.correct_answer;
              const revealed = showExplanation;

              let borderCls = "border-border";
              let bgCls = "bg-surface";
              if (revealed && isCorrect) { borderCls = "border-neon"; bgCls = "bg-neon/10"; }
              else if (revealed && isSelected && !isCorrect) { borderCls = "border-destructive"; bgCls = "bg-destructive/10"; }

              return (
                <button
                  key={i}
                  onClick={() => handleAnswer(letter)}
                  disabled={!!selectedAnswer}
                  className={`w-full flex items-center gap-3 rounded-xl border ${borderCls} ${bgCls} p-3.5 text-left transition-all active:scale-[0.99]`}
                >
                  <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full border text-xs font-bold ${
                    revealed && isCorrect ? "border-neon bg-neon text-neon-foreground"
                    : revealed && isSelected && !isCorrect ? "border-destructive bg-destructive text-destructive-foreground"
                    : "border-border text-muted-foreground"
                  }`}>
                    {revealed && isCorrect ? <CheckCircle className="h-4 w-4" />
                     : revealed && isSelected && !isCorrect ? <XCircle className="h-4 w-4" />
                     : letter}
                  </span>
                  <span className="text-sm text-foreground flex-1">{option.replace(/^[A-D]\)\s*/, "")}</span>
                </button>
              );
            })}
          </div>

          {/* Explanation */}
          {showExplanation && currentQuestion.explanation && (
            <div className="rounded-xl border border-neon/20 bg-neon/5 p-4">
              <div className="flex items-center gap-2 mb-2">
                <Brain className="h-4 w-4 text-neon" />
                <span className="text-xs font-semibold text-neon">Açıklama</span>
              </div>
              <p className="text-xs text-foreground leading-relaxed">{currentQuestion.explanation}</p>
            </div>
          )}

          {/* Navigation arrows - CBR style */}
          {showExplanation && (
            <div className="flex justify-center gap-4 pt-2">
              <Button variant="neon" size="lg" className="w-full gap-2" onClick={handleNext}>
                {currentIndex + 1 >= examLimit ? "Sonuçları Gör" : "Sonraki Soru"}
                <ChevronRight className="h-5 w-5" />
              </Button>
            </div>
          )}

          {/* Score bar */}
          <div className="flex justify-center gap-6 text-xs text-muted-foreground pb-2">
            <span className="flex items-center gap-1.5"><CheckCircle className="h-3.5 w-3.5 text-neon" /> {correctCount} Doğru</span>
            <span className="flex items-center gap-1.5"><XCircle className="h-3.5 w-3.5 text-destructive" /> {totalAnswered - correctCount} Yanlış</span>
          </div>
        </div>
      </div>
    </AppShell>
  );
}

