/**
 * /e-devlet/congress — KYC-gated deep link to the Congress experience.
 * Shareable URL that respects the same server-trusted gate as /e-devlet.
 */
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect } from "react";
import { SovereignGate } from "@/components/sovereign/SovereignGate";
import { MuhrTransition } from "@/components/sovereign/MuhrSeal";

export const Route = createFileRoute("/e-devlet/congress")({
  head: () => ({
    meta: [
      { title: "Kongre — E-Devlet · Jiyan" },
      { name: "description", content: "WKO Halk Kongresi — referandumlar, yasalar, öneriler. Mühürlü erişim." },
      { property: "og:title", content: "Kongre — E-Devlet" },
      { property: "og:description", content: "Halk oylamaları ve yasa önerileri. Mühürlü erişim." },
    ],
  }),
  component: CongressGateRoute,
});

function CongressGateRoute() {
  return (
    <SovereignGate documentLabel="Kongre">
      <MuhrAndRedirect to="/congress" label="Kongre açılıyor" />
    </SovereignGate>
  );
}

function MuhrAndRedirect({ to, label }: { to: string; label: string }) {
  const navigate = useNavigate();
  useEffect(() => {
    const t = window.setTimeout(() => navigate({ to }), 900);
    return () => window.clearTimeout(t);
  }, [navigate, to]);
  return <MuhrTransition active label={label} />;
}

