// Unified Dashboard
// ───────────────────────────────────────────────────────────────────────────────

type SectionKey = "kongre" | "anayasa" | "manifesto" | "whitepaper" | "kyc";
type TopTab = "ozet" | "belgeler" | "civat";

function EDevletDashboard() {
  const access = useEDevletAccess();
  const { user } = useAuth();
  const { data: sovProfile } = useSovereignProfile(user?.id);
  const { isStaff, isAdmin, roles: staffRoles } = useStaffAccess();
