// ── Kongre ────────────────────────────────────────────────────────────────────
function KongreScroll({ open, onOpenFull }: { open: boolean; onOpenFull: () => void }) {
  const [stats, setStats] = useState<{
    activeRefs: number;
    totalProposals: number;
    signers: number;
  } | null>(null);

  useEffect(() => {
    if (!open || stats) return;
    let cancelled = false;
    (async () => {
      try {
        const [refs, proposals, signers] = await Promise.all([
          supabase.from("referendums").select("id", { count: "exact", head: true }).eq("status", "active"),
          supabase.from("proposals").select("id", { count: "exact", head: true }),
          supabase.rpc("get_constitution_signature_count"),
        ]);
        if (cancelled) return;
        setStats({
          activeRefs: refs.count ?? 0,
          totalProposals: proposals.count ?? 0,
          signers: Number(signers.data ?? 0),
        });
      } catch {
        if (!cancelled) setStats({ activeRefs: 0, totalProposals: 0, signers: 0 });
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, stats]);

  return (
    <ScrollShell
      open={open}
      header={
        <ScrollHeader
          icon={Vote}
          title="Kongre"
          subtitle="Halk oylamaları · referandumlar · yasa önerileri"
          open={open}
        />
      }
    >
      <div className="grid grid-cols-3 gap-2 mb-4">
        <Stat label="Aktif Oylama" value={stats?.activeRefs ?? "—"} />
        <Stat label="Öneri" value={stats?.totalProposals ?? "—"} />
        <Stat label="İmzacı" value={stats?.signers ?? "—"} />
      </div>
      <p className="text-[12px] text-amber-100/70 leading-relaxed mb-4">
        Aktif referandumlara katıl, yeni yasa öneri sun ve topluluk oylamalarına oy ver.
        Her egemenin <span className="text-amber-200 font-semibold">tek bir oyu</span> vardır.
      </p>
      <button
        onClick={onOpenFull}
        className="group relative w-full h-11 rounded-xl bg-gradient-to-r from-amber-500 to-yellow-300 text-black font-bold text-sm flex items-center justify-center gap-2 shadow-[0_6px_18px_-6px_rgba(245,158,11,0.6)] active:scale-[0.98] transition overflow-hidden"
      >
        <Vote className="h-4 w-4" />
        Kongre'ye Mühürlü Giriş
        <ArrowRight className="h-4 w-4" />
      </button>
    </ScrollShell>
  );
}

