function KycScroll({
  open,
  access,
  onOpenFull,
}: {
  open: boolean;
  access: ReturnType<typeof useEDevletAccess>;
  onOpenFull: () => void;
}) {
  const stage = access.stage;
  const stageMeta =
    stage === "verified"
      ? { icon: CheckCircle2, label: "Doğrulanmış", color: "text-emerald-300", bg: "bg-emerald-400/15 border-emerald-400/40" }
      : stage === "pending"
        ? { icon: Clock, label: "İncelemede", color: "text-amber-300", bg: "bg-amber-400/15 border-amber-400/40" }
        : stage === "rejected"
          ? { icon: XCircle, label: "Reddedildi", color: "text-red-300", bg: "bg-red-400/15 border-red-400/40" }
          : { icon: Fingerprint, label: "Başvuru Bekleniyor", color: "text-amber-200/80", bg: "bg-white/5 border-white/15" };
  const StageIcon = stageMeta.icon;
  const cta =
    stage === "verified" ? "KYC Detayları" :
    stage === "pending" ? "Durumu Görüntüle" :
    stage === "rejected" ? "Tekrar Başvur" : "KYC Başlat";

  return (
    <ScrollShell
      open={open}
      header={
        <ScrollHeader
          icon={Fingerprint}
          title="KYC — Kimlik Doğrulama"
          subtitle="Egemen statüsü için zorunlu — biometrik + belge"
          open={open}
        />
      }
    >
      <div className={cn("flex items-center gap-3 rounded-xl border px-3 py-3 mb-4", stageMeta.bg)}>
        <StageIcon className={cn("h-5 w-5 flex-shrink-0", stageMeta.color)} />
        <div className="flex-1 min-w-0">
          <p className={cn("text-sm font-bold", stageMeta.color)}>{stageMeta.label}</p>
          {access.kurdId && (
            <p className="text-[11px] font-mono text-amber-100/70 mt-0.5">+777 {access.kurdId}</p>
          )}
          {stage === "rejected" && access.rejectionReason && (
            <p className="text-[11px] text-red-200/80 mt-1 leading-snug">{access.rejectionReason}</p>
          )}
        </div>
      </div>
      <p className="text-[12px] text-amber-100/70 leading-relaxed mb-4">
        KYC, Egemen Devlet'in temelidir. Doğrulanmış vatandaşlar Pazar, Hazine,
        Civat ve Sovereign Space'e tam erişim kazanır.
