import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect } from "react";
import { SovereignGate } from "@/components/sovereign/SovereignGate";
import { MuhrTransition } from "@/components/sovereign/MuhrSeal";

export const Route = createFileRoute("/e-devlet/whitepaper")({
  head: () => ({
    meta: [
      { title: "Teknik Belge — E-Devlet · Jiyan" },
      { name: "description", content: "WKO Stratejik Çerçevesi ve Ekonomik Mimarisi. Mühürlü erişim." },
      { property: "og:title", content: "Teknik Belge — E-Devlet" },
      { property: "og:description", content: "Stratejik çerçeve ve ekonomik mimari. Mühürlü erişim." },
    ],
  }),
  component: WhitepaperGateRoute,
});

function WhitepaperGateRoute() {
  return (
    <SovereignGate documentLabel="Teknik Belge">
      <MuhrAndRedirect to="/whitepaper" />
    </SovereignGate>
  );
}

function MuhrAndRedirect({ to }: { to: string }) {
  const navigate = useNavigate();
  useEffect(() => {
    const t = window.setTimeout(() => navigate({ to }), 900);
    return () => window.clearTimeout(t);
  }, [navigate, to]);
  return <MuhrTransition active label="Teknik Belge açılıyor" />;
}

