import { Textarea } from "@/components/ui/textarea";
import {
  CalendarDays, MapPin, Clock, Users, ArrowLeft, Check, Star,
  Bell, BellOff, Share2, Loader2, ExternalLink, MessageCircle, Send, Trash2,
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";

export const Route = createFileRoute("/events/$eventId")({
  component: EventDetailPage,
  head: () => ({
    meta: [
      { title: "Etkinlik Detayı – Jiyan Europe" },
      { name: "description", content: "Etkinlik detayları, katılımcılar ve konum bilgisi." },
    ],
  }),
});

interface Attendee {
  user_id: string;
  status: string;
  display_name: string;
  avatar_url: string | null;
}

function EventDetailPage() {
  const { eventId } = Route.useParams();
  const { user } = useAuth();
  const { events, loading, rsvpEvent, removeRsvp, getUserRsvp } = useEvents(user?.id);
  const [attendees, setAttendees] = useState<Attendee[]>([]);
  const [loadingAttendees, setLoadingAttendees] = useState(true);
  const [rsvpLoading, setRsvpLoading] = useState(false);

  const event = events.find((e) => e.id === eventId);
  const userRsvp = getUserRsvp(eventId);
  const [remind, setRemind] = useState(userRsvp?.remind_before ?? false);

  useEffect(() => {
    setRemind(userRsvp?.remind_before ?? false);
  }, [userRsvp?.remind_before]);

  useEffect(() => {
    async function fetchAttendees() {
      const { data } = await supabase
        .from("event_rsvps")
        .select("user_id, status")
        .eq("event_id", eventId);

      if (!data || data.length === 0) {
        setAttendees([]);
        setLoadingAttendees(false);
        return;
      }

      const userIds = data.map((r) => r.user_id);
      const { data: profiles } = await supabase
        .from("profiles")
        .select("user_id, display_name, avatar_url")
        .in("user_id", userIds);

      const merged: Attendee[] = data.map((r) => {
        const p = profiles?.find((pr) => pr.user_id === r.user_id);
        return {
          user_id: r.user_id,
          status: r.status,
          display_name: p?.display_name ?? "Kullanıcı",
          avatar_url: p?.avatar_url ?? null,
        };
      });

      setAttendees(merged);
      setLoadingAttendees(false);
    }

    fetchAttendees();
  }, [eventId, events]);

  const handleRsvp = async (status: "going" | "interested") => {
    if (!user) { toast.error("Giriş yapmalısınız"); return; }
    setRsvpLoading(true);
    try {
      if (userRsvp?.status === status) {
        await removeRsvp(eventId);
        toast.info("Katılım iptal edildi");
      } else {
        await rsvpEvent(eventId, status, remind);
        toast.success(status === "going" ? "Katılıyorsun! 🎉" : "İlgileniyorsun!");
      }
    } catch {
      toast.error("İşlem başarısız");
    } finally {
      setRsvpLoading(false);
    }
  };

  const toggleRemind = async () => {
    if (!user || !userRsvp) return;
    const newRemind = !remind;
    setRemind(newRemind);
    await rsvpEvent(eventId, userRsvp.status as "going" | "interested", newRemind);
    toast.success(newRemind ? "Hatırlatma açıldı" : "Hatırlatma kapatıldı");
  };

  const handleShare = async () => {
    const url = window.location.href;
    if (navigator.share) {
      await navigator.share({ title: event?.title, url });
    } else {
      await navigator.clipboard.writeText(url);
      toast.success("Link kopyalandı!");
    }
  };

  if (loading) {
    return (
      <AppShell>
        <div className="flex justify-center py-24">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </div>
      </AppShell>
