  }

  if (!event) {
    return (
      <AppShell>
        <div className="px-4 pt-6 text-center">
          <CalendarDays className="h-16 w-16 mx-auto text-muted-foreground/30 mb-4" />
          <h2 className="text-lg font-semibold text-foreground mb-2">Etkinlik bulunamadı</h2>
          <p className="text-sm text-muted-foreground mb-4">Bu etkinlik kaldırılmış veya süresi dolmuş olabilir.</p>
          <Link to="/events">
