  const mapUrl = `https://www.google.com/maps/search/?api=1&query=${mapQuery}`;
  const embedMapUrl = `https://maps.google.com/maps?q=${mapQuery}&t=&z=14&ie=UTF8&iwloc=&output=embed`;

  return (
    <AppShell>
      <div className="pb-6">
        {/* Header image */}
        {event.image_url ? (
          <div className="relative">
            <img src={event.image_url} alt={event.title} className="w-full h-48 object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-background/80 to-transparent" />
            <div className="absolute top-3 left-3">
              <Link to="/events">
                <Button size="sm" variant="glass" className="gap-1 h-8">
                  <ArrowLeft className="h-4 w-4" /> Geri
                </Button>
              </Link>
            </div>
            <div className="absolute top-3 right-3">
              <Button size="sm" variant="glass" className="h-8 w-8 p-0" onClick={handleShare}>
                <Share2 className="h-4 w-4" />
              </Button>
            </div>
          </div>
        ) : (
          <div className="px-4 pt-4 flex items-center justify-between">
            <Link to="/events">
              <Button size="sm" variant="ghost" className="gap-1">
                <ArrowLeft className="h-4 w-4" /> Geri
              </Button>
            </Link>
            <Button size="sm" variant="ghost" className="h-8 w-8 p-0" onClick={handleShare}>
              <Share2 className="h-4 w-4" />
            </Button>
          </div>
        )}

        <div className="px-4 pt-4 space-y-4">
          {/* Title & category */}
          <div>
            <div className="flex items-start gap-2 mb-1">
              <Badge variant="outline" className="text-[10px] shrink-0">{catLabel}</Badge>
            </div>
            <h1 className="text-xl font-bold text-foreground">{event.title}</h1>
          </div>

          {/* Date & time */}
          <Card className="p-3">
            <div className="flex items-center gap-3">
              <div className="flex flex-col items-center min-w-[48px] rounded-lg bg-neon/10 p-2">
                <span className="text-[10px] font-bold text-neon">
                  {date.toLocaleString("tr-TR", { month: "short" }).toUpperCase()}
                </span>
                <span className="text-xl font-bold text-foreground leading-none">{date.getDate()}</span>
              </div>
              <div className="flex-1">
                <p className="text-sm font-medium text-foreground capitalize">{dateStr}</p>
                <p className="text-xs text-muted-foreground flex items-center gap-1 mt-0.5">
                  <Clock className="h-3 w-3" />
                  {timeStr}{endTimeStr ? ` – ${endTimeStr}` : ""}
                </p>
              </div>
            </div>
          </Card>

          {/* Location */}
          <Card className="p-3">
            <div className="flex items-start gap-3">
              <MapPin className="h-5 w-5 text-neon mt-0.5 shrink-0" />
