                {event.location && (
                  <p className="text-sm font-medium text-foreground">{event.location}</p>
                )}
                <p className="text-xs text-muted-foreground">{event.city}</p>
                <a
                  href={mapUrl}
                  target="_blank"
                  rel="noopener noreferrer"
