// ---- Comments Section ----
interface CommentWithProfile {
  id: string;
  user_id: string;
  content: string;
  created_at: string;
  display_name: string;
  avatar_url: string | null;
}

function EventComments({ eventId, userId }: { eventId: string; userId?: string }) {
  const [comments, setComments] = useState<CommentWithProfile[]>([]);
  const [loading, setLoading] = useState(true);
  const [text, setText] = useState("");
  const [sending, setSending] = useState(false);

  const fetchComments = useCallback(async () => {
    const { data } = await supabase
      .from("event_comments")
      .select("id, user_id, content, created_at")
      .eq("event_id", eventId)
      .order("created_at", { ascending: true });

    if (!data || data.length === 0) {
      setComments([]);
      setLoading(false);
      return;
    }

    const userIds = [...new Set(data.map((c) => c.user_id))];
    const { data: profiles } = await supabase
      .from("profiles")
      .select("user_id, display_name, avatar_url")
      .in("user_id", userIds);

    const merged: CommentWithProfile[] = data.map((c) => {
      const p = profiles?.find((pr) => pr.user_id === c.user_id);
      return {
        ...c,
        display_name: p?.display_name ?? "Kullanıcı",
        avatar_url: p?.avatar_url ?? null,
      };
    });

    setComments(merged);
    setLoading(false);
  }, [eventId]);

  useEffect(() => {
    fetchComments();

    const channel = supabase
      .channel(`event-comments-${eventId}`)
      .on("postgres_changes", {
        event: "*",
        schema: "public",
        table: "event_comments",
        filter: `event_id=eq.${eventId}`,
      }, () => {
        fetchComments();
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [fetchComments, eventId]);

  const handleSend = async () => {
    if (!userId) { toast.error("Giriş yapmalısınız"); return; }
    const trimmed = text.trim();
    if (!trimmed) return;
    setSending(true);
    try {
      const { error } = await supabase.from("event_comments").insert({
        event_id: eventId,
        user_id: userId,
        content: trimmed,
      } as any);
      if (error) throw error;
      setText("");
    } catch {
      toast.error("Yorum gönderilemedi");
    } finally {
      setSending(false);
    }
  };

  const handleDelete = async (commentId: string) => {
    await supabase.from("event_comments").delete().eq("id", commentId);
  };

  const timeAgo = (dateStr: string) => {
    const diff = Date.now() - new Date(dateStr).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return "az önce";
    if (mins < 60) return `${mins}dk`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return `${hrs}sa`;
    return `${Math.floor(hrs / 24)}g`;
  };

  return (
    <div>
      <h2 className="text-sm font-semibold text-foreground mb-3 flex items-center gap-2">
        <MessageCircle className="h-4 w-4" />
        Tartışma
        {comments.length > 0 && (
          <span className="text-muted-foreground font-normal text-xs">({comments.length})</span>
        )}
      </h2>

      {/* Comment input */}
      {userId ? (
        <div className="flex gap-2 mb-4">
          <Textarea
            placeholder="Yorum yaz..."
            value={text}
            onChange={(e) => setText(e.target.value)}
            className="min-h-[40px] max-h-[100px] resize-none text-sm"
            maxLength={500}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                handleSend();
              }
            }}
          />
          <Button
            size="sm"
            className="shrink-0 h-10 w-10 p-0 gradient-neon text-neon-foreground"
            disabled={sending || !text.trim()}
            onClick={handleSend}
          >
            {sending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
          </Button>
        </div>
      ) : (
        <p className="text-xs text-muted-foreground mb-4">Yorum yapmak için giriş yapın.</p>
      )}

      {/* Comments list */}
      {loading ? (
        <div className="flex justify-center py-4">
          <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
        </div>
      ) : comments.length === 0 ? (
        <p className="text-sm text-muted-foreground text-center py-4">
          Henüz yorum yok. İlk yorumu sen yaz!
        </p>
      ) : (
        <div className="space-y-3">
          {comments.map((c) => (
            <div key={c.id} className="flex gap-2.5">
              <Avatar className="h-8 w-8 shrink-0 mt-0.5">
                {c.avatar_url ? (
                  <img src={c.avatar_url} alt={c.display_name} className="h-full w-full object-cover" />
                ) : (
                  <AvatarFallback className="text-[10px] bg-muted">
                    {c.display_name.slice(0, 2).toUpperCase()}
                  </AvatarFallback>
                )}
              </Avatar>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-semibold text-foreground">{c.display_name}</span>
                  <span className="text-[10px] text-muted-foreground">{timeAgo(c.created_at)}</span>
                  {userId === c.user_id && (
                    <Button
                      size="sm"
                      variant="ghost"
                      className="h-5 w-5 p-0 ml-auto text-muted-foreground hover:text-destructive"
                      onClick={() => handleDelete(c.id)}
                    >
                      <Trash2 className="h-3 w-3" />
                    </Button>
                  )}
                </div>
                <p className="text-sm text-foreground/90 mt-0.5 whitespace-pre-wrap break-words">{c.content}</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

