import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { useState, useMemo } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useEvents, EVENT_CATEGORIES } from "@/hooks/useEvents";
import { useExternalEvents, type ExternalEvent } from "@/hooks/useExternalEvents";
import { EventCalendarView } from "@/components/events/EventCalendarView";
import { EventMapView } from "@/components/events/EventMapView";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger
} from "@/components/ui/dialog";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from "@/components/ui/select";
import {
  CalendarDays, MapPin, Clock, Users, Plus, Check, Star,
  Bell, BellOff, Loader2, ImagePlus, X, List, Map, Calendar,
  TrendingUp, Flame, Timer, Share2, UserPlus, ExternalLink, Music, Globe,
  Download, Sparkles
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { useNavigate } from "@tanstack/react-router";
import { RitualDayStrip } from "@/components/ritual/RitualDayStrip";

export const Route = createFileRoute("/events")({
  component: EventsPage,
  head: () => ({
    meta: [
      { title: "Etkinlikler – Jiyan Europe" },
      { name: "description", content: "Kürt topluluk etkinlikleri, konserler, festivaller ve buluşmalar." },
    ],
  }),
});

type ViewMode = "list" | "calendar" | "map";
type TimeFilter = "all" | "today" | "weekend" | "week" | "month";

function EventsPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const { events, loading, createEvent, rsvpEvent, removeRsvp, getUserRsvp, getRsvpCounts } = useEvents(user?.id);
  const { events: externalEvents, loading: externalLoading } = useExternalEvents();
  const [showCreate, setShowCreate] = useState(false);
  const [filterCat, setFilterCat] = useState<string>("all");
  const [viewMode, setViewMode] = useState<ViewMode>("list");
  const [timeFilter, setTimeFilter] = useState<TimeFilter>("all");
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);

  // Time filtering
  const timeFiltered = useMemo(() => {
    const now = new Date();
    return events.filter((e) => {
      const d = new Date(e.starts_at);
      switch (timeFilter) {
        case "today":
          return d.toDateString() === now.toDateString();
        case "weekend": {
          // Friday 18:00 → Sunday 23:59 of upcoming weekend
          const day = now.getDay(); // 0 Sun .. 6 Sat
          const friday = new Date(now);
          const daysUntilFri = (5 - day + 7) % 7;
          friday.setDate(now.getDate() + daysUntilFri);
          friday.setHours(18, 0, 0, 0);
          const sundayEnd = new Date(friday);
          sundayEnd.setDate(friday.getDate() + 2);
          sundayEnd.setHours(23, 59, 59, 999);
          return d >= now && d <= sundayEnd && d >= friday;
        }
        case "week": {
          const weekFromNow = new Date(now);
          weekFromNow.setDate(weekFromNow.getDate() + 7);
          return d >= now && d <= weekFromNow;
        }
        case "month": {
          const monthFromNow = new Date(now);
          monthFromNow.setMonth(monthFromNow.getMonth() + 1);
          return d >= now && d <= monthFromNow;
        }
        default:
          return true;
      }
    });
  }, [events, timeFilter]);

  // Category filtering
  const filtered = useMemo(() => {
    let result = timeFiltered;
    if (filterCat !== "all") {
      result = result.filter((e) => e.category === filterCat);
    }
    if (selectedDate) {
      result = result.filter((e) => {
        const d = new Date(e.starts_at);
        return d.toDateString() === selectedDate.toDateString();
      });
    }
    return result;
  }, [timeFiltered, filterCat, selectedDate]);

  // Trending events (most RSVPs)
  const trending = useMemo(() => {
    return [...events]
      .filter((e) => new Date(e.starts_at) > new Date())
      .sort((a, b) => getRsvpCounts(b.id).going - getRsvpCounts(a.id).going)
      .slice(0, 5);
  }, [events, getRsvpCounts]);

  // Countdown for next event
  const nextEvent = events[0];
  const countdown = useMemo(() => {
    if (!nextEvent) return null;
    const diff = new Date(nextEvent.starts_at).getTime() - Date.now();
    if (diff <= 0) return null;
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    return { days, hours, event: nextEvent };
  }, [nextEvent]);

  const handleSelectMapEvent = (event: any) => {
    navigate({ to: "/events/$eventId", params: { eventId: event.id } });
  };

  return (
    <AppShell>
      <div className="px-4 pt-5 pb-24 space-y-4">
        {/* Hero Header */}
        <div className="relative overflow-hidden rounded-2xl border border-neon/20 bg-gradient-to-br from-neon/10 via-background to-gold/5 p-4">
          <div className="pointer-events-none absolute -right-8 -top-8 h-28 w-28 rounded-full bg-neon/15 blur-3xl" />
          <div className="pointer-events-none absolute -left-6 -bottom-6 h-20 w-20 rounded-full bg-gold/10 blur-2xl" />
          <div className="relative flex items-start justify-between gap-3">
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-1.5 mb-1">
                <Sparkles className="h-3.5 w-3.5 text-gold" />
                <span className="text-[10px] font-semibold text-gold uppercase tracking-wider">Topluluk</span>
              </div>
              <h1 className="text-2xl font-bold text-foreground leading-tight">Etkinlikler</h1>
              <p className="text-[11px] text-muted-foreground mt-1">
                {events.length} yaklaşan · konser, festival, buluşma & seminer
              </p>
            </div>
            {user && (
              <Dialog open={showCreate} onOpenChange={setShowCreate}>
                <DialogTrigger asChild>
                  <Button size="sm" className="gap-1 bg-neon text-neon-foreground hover:bg-neon/90 h-9 text-xs shrink-0 shadow-lg shadow-neon/20">
                    <Plus className="h-3.5 w-3.5" /> Etkinlik
                  </Button>
                </DialogTrigger>
                <DialogContent className="max-w-md max-h-[85vh] overflow-y-auto">
                  <DialogHeader>
                    <DialogTitle>Etkinlik Oluştur</DialogTitle>
                  </DialogHeader>
                  <CreateEventForm
                    onSubmit={async (data) => {
                      await createEvent(data);
                      setShowCreate(false);
                      toast.success("Etkinlik oluşturuldu!");
                    }}
                  />
                </DialogContent>
              </Dialog>
            )}
          </div>
        </div>

        {/* Ritual Day Strip — today's prayer times integrated into the agenda */}
        <RitualDayStrip />

        {/* Countdown Banner */}
        {countdown && (
          <div className="relative overflow-hidden rounded-2xl border border-neon/20 bg-gradient-to-r from-neon/5 via-neon/10 to-accent/30 p-4">
            <div className="pointer-events-none absolute -right-6 -top-6 h-20 w-20 rounded-full bg-neon/10 blur-2xl" />
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-2">
                <Timer className="h-5 w-5 text-neon" />
                <div>
                  <p className="text-[10px] text-muted-foreground uppercase tracking-wider">Sonraki Etkinlik</p>
                  <p className="text-sm font-bold text-foreground truncate max-w-[160px]">{countdown.event.title}</p>
                </div>
              </div>
              <div className="ml-auto flex gap-2">
                <div className="flex flex-col items-center rounded-lg bg-neon/15 px-3 py-1.5">
                  <span className="text-lg font-bold text-neon leading-none">{countdown.days}</span>
                  <span className="text-[8px] text-muted-foreground">GÜN</span>
                </div>
                <div className="flex flex-col items-center rounded-lg bg-neon/15 px-3 py-1.5">
                  <span className="text-lg font-bold text-neon leading-none">{countdown.hours}</span>
                  <span className="text-[8px] text-muted-foreground">SAAT</span>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* View Mode Tabs */}
        <div className="flex gap-1 rounded-xl bg-surface p-1 border border-border">
          {([
            { key: "list" as ViewMode, icon: List, label: "Liste" },
            { key: "calendar" as ViewMode, icon: Calendar, label: "Takvim" },
            { key: "map" as ViewMode, icon: Map, label: "Harita" },
          ]).map(({ key, icon: Icon, label }) => (
            <button
              key={key}
              onClick={() => { setViewMode(key); setSelectedDate(null); }}
              className={`flex-1 flex items-center justify-center gap-1.5 rounded-lg py-2 text-xs font-semibold transition-all ${
                viewMode === key
                  ? "bg-neon text-neon-foreground"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              <Icon className="h-3.5 w-3.5" />
              {label}
            </button>
          ))}
        </div>

        {/* Time Filters */}
        <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-none">
          {([
            { key: "all" as TimeFilter, label: "Tümü", icon: "📅" },
            { key: "today" as TimeFilter, label: "Bugün", icon: "🔥" },
            { key: "weekend" as TimeFilter, label: "Hafta Sonu", icon: "🎉" },
            { key: "week" as TimeFilter, label: "Bu Hafta", icon: "📆" },
            { key: "month" as TimeFilter, label: "Bu Ay", icon: "🗓️" },
          ]).map(({ key, label, icon }) => (
            <button
              key={key}
              onClick={() => { setTimeFilter(key); setSelectedDate(null); }}
              className={`shrink-0 flex items-center gap-1.5 rounded-xl px-3 py-1.5 text-[11px] font-medium transition-all ${
                timeFilter === key
                  ? "bg-neon/15 text-neon border border-neon/30"
                  : "bg-surface text-muted-foreground border border-border hover:text-foreground"
              }`}
            >
              <span>{icon}</span>
              {label}
            </button>
          ))}
        </div>

        {/* Category Filter */}
        <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-none">
          <Badge
            variant={filterCat === "all" ? "default" : "outline"}
            className="cursor-pointer whitespace-nowrap text-[10px]"
            onClick={() => setFilterCat("all")}
          >
            Tümü
          </Badge>
          {EVENT_CATEGORIES.map((cat) => (
            <Badge
              key={cat.value}
              variant={filterCat === cat.value ? "default" : "outline"}
              className="cursor-pointer whitespace-nowrap text-[10px]"
              onClick={() => setFilterCat(cat.value)}
            >
              {cat.label}
            </Badge>
          ))}
        </div>

        {/* Trending Section */}
        {viewMode === "list" && trending.length > 0 && timeFilter === "all" && filterCat === "all" && !selectedDate && (
          <div>
            <div className="flex items-center gap-2 mb-2">
              <Flame className="h-4 w-4 text-gold" />
              <h2 className="text-sm font-bold text-foreground">Trend Etkinlikler</h2>
            </div>
            <div className="flex gap-2.5 overflow-x-auto pb-2 scrollbar-none">
              {trending.map((event) => {
                const date = new Date(event.starts_at);
                const day = date.getDate();
                const month = date.toLocaleString("tr-TR", { month: "short" });
                return (
                  <Link
                    key={event.id}
                    to="/events/$eventId"
                    params={{ eventId: event.id }}
                    className="shrink-0 w-48 rounded-xl border border-border bg-surface overflow-hidden hover:border-neon/30 transition-all"
                  >
                    {event.image_url ? (
                      <img src={event.image_url} alt="" className="w-full h-24 object-cover" />
                    ) : (
                      <div className="w-full h-24 bg-gradient-to-br from-neon/10 to-accent flex items-center justify-center">
                        <CalendarDays className="h-8 w-8 text-neon/30" />
                      </div>
                    )}
                    <div className="p-2.5">
                      <div className="flex items-center gap-1.5 mb-1">
                        <span className="text-[9px] font-bold text-neon uppercase">{month} {day}</span>
                        <span className="text-[9px] text-muted-foreground">· {event.city}</span>
                      </div>
                      <p className="text-xs font-semibold text-foreground truncate">{event.title}</p>
                    </div>
                  </Link>
                );
              })}
            </div>
          </div>
        )}

        {/* Main Content by View Mode */}
        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
          </div>
        ) : viewMode === "calendar" ? (
          <div className="space-y-3">
            <EventCalendarView
              events={timeFiltered}
              onSelectDate={setSelectedDate}
              selectedDate={selectedDate}
            />
            {selectedDate && (
              <div className="space-y-2">
                <p className="text-xs font-semibold text-foreground">
                  {selectedDate.toLocaleDateString("tr-TR", { weekday: "long", day: "numeric", month: "long" })}
                </p>
                {filtered.length === 0 ? (
                  <p className="text-xs text-muted-foreground text-center py-4">Bu tarihte etkinlik yok</p>
                ) : (
                  filtered.map((event) => (
                    <EventCard
                      key={event.id}
                      event={event}
                      userId={user?.id}
                      userRsvp={getUserRsvp(event.id)}
                      counts={getRsvpCounts(event.id)}
                      onRsvp={rsvpEvent}
                      onRemoveRsvp={removeRsvp}
                    />
                  ))
                )}
              </div>
            )}
          </div>
        ) : viewMode === "map" ? (
          <EventMapView events={filtered} onSelectEvent={handleSelectMapEvent} />
        ) : (
          /* List View */
          <div className="space-y-3">
            {filtered.length === 0 ? (
              <div className="text-center py-12">
                <CalendarDays className="h-12 w-12 mx-auto text-muted-foreground/40 mb-3" />
                <p className="text-muted-foreground text-sm">Etkinlik bulunamadı</p>
                {user && (
                  <Button size="sm" variant="outline" className="mt-3" onClick={() => setShowCreate(true)}>
                    İlk etkinliği oluştur
                  </Button>
                )}
              </div>
            ) : (
              filtered.map((event) => (
                <EventCard
                  key={event.id}
                  event={event}
                  userId={user?.id}
                  userRsvp={getUserRsvp(event.id)}
                  counts={getRsvpCounts(event.id)}
                  onRsvp={rsvpEvent}
                  onRemoveRsvp={removeRsvp}
                />
              ))
            )}
          </div>
        )}

        {/* External Events — Kurdish, Turkish, Arab */}
        {viewMode === "list" && (
          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <Globe className="h-4 w-4 text-gold" />
              <h2 className="text-sm font-bold text-foreground">Kürt · Türk · Arap Etkinlikleri</h2>
              <Badge variant="outline" className="text-[8px] ml-auto">
                <Music className="h-2.5 w-2.5 mr-0.5" /> Konserler & Festivaller
              </Badge>
            </div>

            {externalLoading ? (
              <div className="flex justify-center py-6">
                <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
              </div>
            ) : externalEvents.length === 0 ? (
              <p className="text-xs text-muted-foreground text-center py-4">Şu an dış etkinlik bulunamadı</p>
            ) : (
              <div className="space-y-2">
                {externalEvents.map((ext) => (
                  <ExternalEventCard key={ext.id} event={ext} />
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </AppShell>
  );
}

// ---- Event Card (Professional redesign) ----
function EventCard({
  event,
  userId,
  userRsvp,
  counts,
  onRsvp,
  onRemoveRsvp,
}: {
  event: ReturnType<typeof useEvents>["events"][0];
  userId: string | undefined;
  userRsvp: ReturnType<ReturnType<typeof useEvents>["getUserRsvp"]>;
  counts: { going: number; interested: number };
  onRsvp: (eventId: string, status: "going" | "interested", remind?: boolean) => Promise<void>;
  onRemoveRsvp: (eventId: string) => Promise<void>;
}) {
  const [loading, setLoading] = useState(false);
  const [remind, setRemind] = useState(userRsvp?.remind_before ?? false);

  const date = new Date(event.starts_at);
  const day = date.getDate();
  const month = date.toLocaleString("tr-TR", { month: "short" }).toUpperCase();
  const time = date.toLocaleString("tr-TR", { hour: "2-digit", minute: "2-digit" });
  const weekday = date.toLocaleString("tr-TR", { weekday: "short" });
  const catLabel = EVENT_CATEGORIES.find((c) => c.value === event.category)?.label ?? event.category;

  const capacityPct = event.max_attendees
    ? Math.min(100, Math.round((counts.going / event.max_attendees) * 100))
    : 0;
  const isAlmostFull = event.max_attendees ? counts.going / event.max_attendees >= 0.8 : false;

  const handleRsvp = async (e: React.MouseEvent, status: "going" | "interested") => {
    e.preventDefault();
    e.stopPropagation();
    if (!userId) { toast.error("Giriş yapmalısınız"); return; }
    setLoading(true);
    try {
      if (userRsvp?.status === status) {
        await onRemoveRsvp(event.id);
        toast.info("Katılım iptal edildi");
      } else {
        await onRsvp(event.id, status, remind);
        toast.success(status === "going" ? "Katılıyorsun! 🎉" : "İlgileniyorsun!");
      }
    } catch {
      toast.error("İşlem başarısız");
    } finally {
      setLoading(false);
    }
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const url = `${window.location.origin}/events/${event.id}`;
    if (navigator.share) {
      await navigator.share({ title: event.title, url });
    } else {
      await navigator.clipboard.writeText(url);
      toast.success("Link kopyalandı!");
    }
  };

  const handleAddToCalendar = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const fmt = (d: Date) =>
      d.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
    const start = new Date(event.starts_at);
    const end = event.ends_at ? new Date(event.ends_at) : new Date(start.getTime() + 2 * 60 * 60 * 1000);
    const ics = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "PRODID:-//Jiyan Europe//Events//TR",
      "BEGIN:VEVENT",
      `UID:${event.id}@jiyan.world`,
      `DTSTAMP:${fmt(new Date())}`,
      `DTSTART:${fmt(start)}`,
      `DTEND:${fmt(end)}`,
      `SUMMARY:${event.title.replace(/[\r\n,;]/g, " ")}`,
      `LOCATION:${(event.location ? event.location + ", " : "") + event.city}`,
      `DESCRIPTION:${(event.description ?? "").replace(/[\r\n]/g, " ").slice(0, 300)}`,
      `URL:${window.location.origin}/events/${event.id}`,
      "END:VEVENT",
      "END:VCALENDAR",
    ].join("\r\n");
    const blob = new Blob([ics], { type: "text/calendar;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${event.title.replace(/[^\w\s-]/g, "").slice(0, 40) || "event"}.ics`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    toast.success("Takvime eklendi");
  };

  return (
    <Link to="/events/$eventId" params={{ eventId: event.id }} className="block">
      <Card className="overflow-hidden hover:border-neon/30 transition-all">
        {event.image_url && (
          <div className="relative">
            <img src={event.image_url} alt={event.title} className="w-full h-36 object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-background/60 to-transparent" />
            <Badge className="absolute top-2 right-2 text-[9px] bg-background/70 backdrop-blur-sm border-none">
              {catLabel}
            </Badge>
          </div>
        )}
        <div className="p-3">
          <div className="flex gap-3">
            {/* Date block */}
            <div className="flex flex-col items-center min-w-[44px] rounded-xl bg-neon/10 p-2">
              <span className="text-[9px] font-bold text-neon">{month}</span>
              <span className="text-lg font-bold text-foreground leading-none">{day}</span>
              <span className="text-[9px] text-muted-foreground capitalize">{weekday}</span>
            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-start justify-between gap-2">
                <h3 className="font-semibold text-sm text-foreground line-clamp-1">{event.title}</h3>
                {!event.image_url && (
                  <Badge variant="outline" className="text-[9px] shrink-0">{catLabel}</Badge>
                )}
              </div>

              {event.description && (
                <p className="text-[11px] text-muted-foreground mt-1 line-clamp-2">{event.description}</p>
              )}

              <div className="flex flex-wrap gap-2.5 mt-2 text-[10px] text-muted-foreground">
                <span className="flex items-center gap-1">
                  <Clock className="h-3 w-3" /> {time}
                </span>
                {event.location && (
                  <span className="flex items-center gap-1">
                    <MapPin className="h-3 w-3" /> {event.location}
                  </span>
                )}
                <span className="flex items-center gap-1">
                  <MapPin className="h-3 w-3 text-neon" /> {event.city}
                </span>
                <span className="flex items-center gap-1">
                  <Users className="h-3 w-3" />
                  {counts.going} katılıyor
                  {counts.interested > 0 && ` · ${counts.interested} ilgili`}
                </span>
              </div>

              {/* Capacity progress */}
              {event.max_attendees && (
                <div className="mt-2">
                  <div className="flex items-center justify-between text-[9px] mb-1">
                    <span className="text-muted-foreground">Kapasite</span>
                    <span className={isAlmostFull ? "text-gold font-semibold" : "text-muted-foreground"}>
                      {counts.going}/{event.max_attendees} {isAlmostFull && "· Az kaldı!"}
                    </span>
                  </div>
                  <div className="h-1 rounded-full bg-muted overflow-hidden">
                    <div
                      className={`h-full transition-all ${isAlmostFull ? "bg-gold" : "bg-neon"}`}
                      style={{ width: `${capacityPct}%` }}
                    />
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Action buttons */}
          <div className="flex items-center gap-2 mt-3 pt-3 border-t border-border">
            <Button
              size="sm"
              variant={userRsvp?.status === "going" ? "default" : "outline"}
              className={`flex-1 text-[11px] gap-1 h-8 ${userRsvp?.status === "going" ? "bg-neon text-neon-foreground hover:bg-neon/90" : ""}`}
              disabled={loading}
              onClick={(e) => handleRsvp(e, "going")}
            >
              <Check className="h-3 w-3" />
              Katılıyorum
            </Button>
            <Button
              size="sm"
              variant={userRsvp?.status === "interested" ? "default" : "outline"}
              className={`flex-1 text-[11px] gap-1 h-8 ${userRsvp?.status === "interested" ? "bg-gold/20 text-gold border-gold/30" : ""}`}
              disabled={loading}
              onClick={(e) => handleRsvp(e, "interested")}
            >
