function CreateEventForm({ onSubmit }: { onSubmit: (data: any) => Promise<void> }) {
  const { user } = useAuth();
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [location, setLocation] = useState("");
  const [city, setCity] = useState("Arnhem");
  const [category, setCategory] = useState("general");
  const [startsAt, setStartsAt] = useState("");
  const [endsAt, setEndsAt] = useState("");
  const [maxAttendees, setMaxAttendees] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { toast.error("Dosya boyutu en fazla 5MB"); return; }
    if (!file.type.startsWith("image/")) { toast.error("Sadece resim dosyaları"); return; }
    setImageFile(file);
    setImagePreview(URL.createObjectURL(file));
  };

  const removeImage = () => {
    setImageFile(null);
    if (imagePreview) URL.revokeObjectURL(imagePreview);
    setImagePreview(null);
  };

  const uploadImage = async (): Promise<string | undefined> => {
    if (!imageFile || !user) return undefined;
    const ext = imageFile.name.split(".").pop();
    const path = `${user.id}/${Date.now()}.${ext}`;
    const { error } = await supabase.storage.from("event-media").upload(path, imageFile);
    if (error) throw error;
    const { data } = supabase.storage.from("event-media").getPublicUrl(path);
    return data.publicUrl;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !startsAt) { toast.error("Başlık ve tarih zorunludur"); return; }
    setSubmitting(true);
    try {
      const image_url = await uploadImage();
      await onSubmit({
        title: title.trim(),
        description: description.trim() || undefined,
        location: location.trim() || undefined,
        city,
        category,
        starts_at: new Date(startsAt).toISOString(),
        ends_at: endsAt ? new Date(endsAt).toISOString() : undefined,
        max_attendees: maxAttendees ? parseInt(maxAttendees) : undefined,
        image_url,
      });
    } catch {
      toast.error("Etkinlik oluşturulamadı");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-3">
      {imagePreview ? (
        <div className="relative rounded-lg overflow-hidden">
          <img src={imagePreview} alt="Önizleme" className="w-full h-32 object-cover rounded-lg" />
          <Button type="button" size="sm" variant="destructive" className="absolute top-1 right-1 h-6 w-6 p-0 rounded-full" onClick={removeImage}>
            <X className="h-3 w-3" />
          </Button>
        </div>
      ) : (
        <label className="flex items-center justify-center gap-2 h-24 border-2 border-dashed border-border rounded-lg cursor-pointer hover:border-primary/50 transition-colors">
          <ImagePlus className="h-5 w-5 text-muted-foreground" />
          <span className="text-sm text-muted-foreground">Kapak fotoğrafı ekle</span>
          <input type="file" accept="image/*" className="hidden" onChange={handleImageChange} />
        </label>
      )}
      <Input placeholder="Etkinlik başlığı *" value={title} onChange={(e) => setTitle(e.target.value)} maxLength={100} required />
      <Textarea placeholder="Açıklama" value={description} onChange={(e) => setDescription(e.target.value)} className="min-h-[60px] resize-none" maxLength={500} />
      <div className="grid grid-cols-2 gap-2">
        <Input placeholder="Konum" value={location} onChange={(e) => setLocation(e.target.value)} maxLength={100} />
        <Select value={city} onValueChange={setCity}>
          <SelectTrigger><SelectValue /></SelectTrigger>
          <SelectContent>
            {["Arnhem", "Amsterdam", "Rotterdam", "Den Haag", "Utrecht", "Eindhoven", "Berlin", "Hamburg", "München", "Stockholm"].map((c) => (
              <SelectItem key={c} value={c}>{c}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <Select value={category} onValueChange={setCategory}>
        <SelectTrigger><SelectValue /></SelectTrigger>
        <SelectContent>
          {EVENT_CATEGORIES.map((cat) => (
            <SelectItem key={cat.value} value={cat.value}>{cat.label}</SelectItem>
          ))}
        </SelectContent>
      </Select>
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="text-[11px] text-muted-foreground mb-1 block">Başlangıç *</label>
          <Input type="datetime-local" value={startsAt} onChange={(e) => setStartsAt(e.target.value)} required />
        </div>
        <div>
          <label className="text-[11px] text-muted-foreground mb-1 block">Bitiş</label>
          <Input type="datetime-local" value={endsAt} onChange={(e) => setEndsAt(e.target.value)} />
        </div>
      </div>
      <Input type="number" placeholder="Maks katılımcı (opsiyonel)" value={maxAttendees} onChange={(e) => setMaxAttendees(e.target.value)} min={1} />
      <Button type="submit" className="w-full bg-neon text-neon-foreground hover:bg-neon/90" disabled={submitting}>
        {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : "Etkinlik Oluştur"}
      </Button>
    </form>
  );
}

