// ---- Trend Score ----
function calcTrendScore(item: { like_count?: number; comment_count?: number; repost_count?: number; view_count?: number; created_at?: string; published_at?: string }) {
  const time = item.created_at || item.published_at || new Date().toISOString();
  const hoursAgo = (Date.now() - new Date(time).getTime()) / 3600000;
  const raw =
    ((item.like_count || 0) * 2) +
    ((item.comment_count || 0) * 3) +
    ((item.repost_count || 0) * 4) +
    ((item.view_count || 0) * 0.1);
  return Math.max(0, raw - hoursAgo);
}

// ---- Hashtag extraction ----
function extractHashtags(posts: Post[]): { tag: string; count: number }[] {
  const map = new Map<string, number>();
  for (const p of posts) {
    if (!p.content) continue;
    const tags = p.content.match(/#\w+/g);
    if (tags) tags.forEach(t => map.set(t.toLowerCase(), (map.get(t.toLowerCase()) || 0) + 1));
  }
  return Array.from(map.entries())
    .map(([tag, count]) => ({ tag, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 10);
}

