    const file = e.target.files?.[0];
    if (!file || !user) return;
    setUploading(true);
    const ext = file.name.split(".").pop();
    const path = `${user.id}/${Date.now()}.${ext}`;
    const { error } = await supabase.storage.from("chat-media").upload(path, file);
    if (error) { toast.error("Yükleme başarısız"); setUploading(false); return; }
    const { data: urlData } = supabase.storage.from("chat-media").getPublicUrl(path);
    setPostImage(urlData.publicUrl);
    setUploading(false);
  };

  // Filter posts by following when "Takipte" mode active
  const filteredPosts = useMemo(() => {
    if (topMode !== "following") return posts;
    return posts.filter((p: any) => followingIds.has(p.user_id));
  }, [posts, topMode, followingIds]);

  const showFollowingEmpty =
    topMode === "following" && !postsLoading && filteredPosts.length === 0;

  return (
    <AppShell>
      {/* TikTok-style sticky top bar */}
      <div className="sticky top-0 z-30 bg-background/85 backdrop-blur-xl border-b border-border/40">
        <div className="px-4 pt-3 pb-2">
          <TopTabs
            tabs={[
              { value: "following", label: "Takipte" },
              { value: "foryou", label: "Sizin İçin" },
              { value: "explore", label: "Keşfet" },
            ]}
            value={topMode}
            onChange={(v: TopTabValue) => {
              if (v === "explore") {
                navigate({ to: "/explore" });
                return;
              }
              setTopMode(v as "following" | "foryou");
            }}
            variant="light"
          />
        </div>
      </div>

      {/* Trending Topics */}
      {trending.length > 0 && (
        <div className="px-4 pt-3 pb-2">
          <div className="flex items-center gap-1.5 mb-1.5">
            <Flame className="h-3.5 w-3.5 text-destructive" />
            <span className="text-xs font-semibold text-foreground">Trend</span>
          </div>
          <div className="flex gap-1.5 overflow-x-auto pb-1 scrollbar-none">
            {trending.map(t => (
              <Badge key={t.tag} variant="secondary" className="shrink-0 text-[10px] gap-1 cursor-pointer hover:bg-accent">
                {t.tag} <span className="text-muted-foreground">{t.count}</span>
              </Badge>
            ))}
          </div>
        </div>
      )}

      {/* Stories */}
      <div className="border-b border-border">
        <StoryBar
          groups={storyGroups}
          currentUserId={user?.id}
          onCreateStory={createStory}
          onMarkViewed={markViewed}
        />
      </div>

      <Tabs defaultValue="all" className="px-2">
        <TabsList className="w-full grid grid-cols-4 mb-3">
          <TabsTrigger value="all" className="text-xs gap-1"><TrendingUp className="h-3 w-3" /> Tümü</TabsTrigger>
          <TabsTrigger value="news" className="text-xs gap-1"><Newspaper className="h-3 w-3" /> Haber</TabsTrigger>
          <TabsTrigger value="posts" className="text-xs gap-1"><Users className="h-3 w-3" /> Post</TabsTrigger>
          <TabsTrigger value="kurdpedia" className="text-xs gap-1"><BookOpen className="h-3 w-3" /> Kurdpedia</TabsTrigger>
        </TabsList>

        {/* Compose */}
        {user && (
          <div className="mx-2 mb-3">
            <Card className="p-3">
              <Textarea
                placeholder="Ne düşünüyorsun? #hashtag ekle"
                value={newPost}
                onChange={e => setNewPost(e.target.value)}
                className="min-h-[60px] resize-none border-0 bg-transparent p-0 focus-visible:ring-0"
                maxLength={500}
              />
              {postImage && (
                <div className="relative mt-2">
                  <img src={postImage} alt="preview" className="rounded-lg max-h-32 object-cover" />
                  <button onClick={() => setPostImage(null)} className="absolute top-1 right-1 bg-background/80 rounded-full p-0.5">
                    <X className="h-3 w-3" />
                  </button>
                </div>
              )}
              <div className="flex justify-between items-center mt-2">
                <div className="flex items-center gap-2">
                  <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
                  <button onClick={() => fileRef.current?.click()} disabled={uploading} className="text-muted-foreground hover:text-primary transition-colors">
                    {uploading ? <Loader2 className="h-4 w-4 animate-spin" /> : <ImagePlus className="h-4 w-4" />}
                  </button>
                  <Hash className="h-4 w-4 text-muted-foreground" />
                  <span className="text-xs text-muted-foreground">{newPost.length}/500</span>
                </div>
                <Button size="sm" variant="neon" onClick={handlePost} disabled={posting || !newPost.trim()}>
                  {posting ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : <Send className="h-3 w-3 mr-1" />}
                  Paylaş
                </Button>
              </div>
            </Card>
