}

// ---- Smart Feed (Trend-ranked, mixed) ----
function SmartFeed({ posts, news, kurdpedia, loading, onLike, onRepost, onView, userId, activeComment, setActiveComment, boostedPostIds }: any) {
  const [visibleCount, setVisibleCount] = useState(15);
  const loaderRef = useRef<HTMLDivElement>(null);

  type FeedItem = { type: "post" | "news" | "kurdpedia"; data: any; score: number };

  const items: FeedItem[] = [
    ...posts.map((p: any) => ({ type: "post" as const, data: p, score: (p.trendScore || calcTrendScore(p)) + (boostedPostIds?.has(p.id) ? 50 : 0) })),
    ...news.map((n: any) => ({ type: "news" as const, data: n, score: calcTrendScore(n) + 5 })),
    ...kurdpedia.map((k: any) => ({ type: "kurdpedia" as const, data: k, score: calcTrendScore(k) + 2 })),
  ].sort((a, b) => b.score - a.score);

  // Infinite scroll
  useEffect(() => {
    if (!loaderRef.current) return;
    const observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && visibleCount < items.length) {
        setVisibleCount(prev => Math.min(prev + 10, items.length));
      }
    }, { threshold: 0.1 });
    observer.observe(loaderRef.current);
    return () => observer.disconnect();
  }, [visibleCount, items.length]);

  if (loading) return <FeedSkeleton />;
  if (items.length === 0) return <EmptyFeed />;

  return (
    <div className="space-y-3 px-2 pb-4">
      {items.slice(0, visibleCount).map((item, idx) => {
        if (item.type === "news") return <NewsCard key={`n-${item.data.id}`} article={item.data} />;
        if (item.type === "kurdpedia") return <KurdpediaCard key={`k-${item.data.id}`} article={item.data} />;
        return (
          <PostCard
            key={`p-${item.data.id}`}
            post={item.data}
            onLike={onLike}
            onRepost={onRepost}
            onView={onView}
            userId={userId}
            activeComment={activeComment}
            setActiveComment={setActiveComment}
            isTrending={idx < 3 && (item.data.trendScore || 0) > 10}
            isBoosted={boostedPostIds?.has(item.data.id)}
          />
        );
      })}
      {visibleCount < items.length && (
        <div ref={loaderRef} className="flex justify-center py-4">
          <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
        </div>
      )}
    </div>
  );
}

// ---- Post Card ----
function PostCard({ post, onLike, onRepost, onView, userId, activeComment, setActiveComment, isTrending = false, isBoosted = false }: any) {
  const cardRef = useRef<HTMLDivElement>(null);
  const viewed = useRef(false);

  const handleFlag = async () => {
    if (!userId) { toast.error("Giriş yapmalısınız"); return; }
    const { error } = await supabase.from("post_flags").insert({ post_id: post.id, user_id: userId, reason: "spam" });
    if (error?.code === "23505") { toast.info("Zaten bildirdiniz"); return; }
    if (error) { toast.error("Bildirme başarısız"); return; }
    toast.success("Gönderi bildirildi");
  };

  // Track view on intersection
  useEffect(() => {
    if (!cardRef.current || viewed.current) return;
    const observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting) {
        viewed.current = true;
        onView?.(post.id);
        observer.disconnect();
      }
    }, { threshold: 0.5 });
    observer.observe(cardRef.current);
    return () => observer.disconnect();
  }, [post.id, onView]);

  const handleShare = async () => {
    const url = typeof window !== "undefined" ? window.location.origin + "/feed" : "";
    if (typeof navigator !== "undefined" && navigator.share) {
      try { await navigator.share({ title: "Jiyan Europe", url }); } catch { /* cancelled */ }
    } else {
      if (typeof navigator !== "undefined") navigator.clipboard.writeText(url);
      toast.success("Link kopyalandı");
    }
  };

  return (
    <Card ref={cardRef} className={`p-3 space-y-2 transition-all ${isTrending ? "border-destructive/30 shadow-[0_0_15px_oklch(0.6_0.24_27/0.15)]" : ""} ${isBoosted ? "border-neon/40 shadow-[0_0_15px_oklch(0.7_0.2_150/0.15)]" : ""}`}>
      {isBoosted && (
        <div className="flex items-center gap-1 text-[10px] font-semibold text-neon">
          <Rocket className="h-3 w-3" /> Boost Edildi
        </div>
      )}
      {isTrending && !isBoosted && (
        <div className="flex items-center gap-1 text-[10px] font-semibold text-destructive">
          <Zap className="h-3 w-3" /> Trend Gönderi
        </div>
      )}
      <div className="flex items-center gap-2">
        <Avatar className="h-9 w-9">
          <AvatarImage src={post.profile?.avatar_url || ""} />
          <AvatarFallback className="bg-secondary text-xs">
            {post.profile?.display_name?.charAt(0) || "?"}
          </AvatarFallback>
        </Avatar>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-semibold text-foreground truncate">
            {post.profile?.display_name || "Anonim"}
            {post.profile?.kurd_id && <span className="text-neon ml-1 text-[10px] font-normal">{post.profile.kurd_id}</span>}
          </p>
          <p className="text-[10px] text-muted-foreground flex items-center gap-1">
            <Clock className="h-2.5 w-2.5" />
            {timeAgo(post.created_at)}
          </p>
        </div>
      </div>

      {post.content && <p className="text-sm text-foreground whitespace-pre-wrap leading-relaxed">{renderHashtags(post.content)}</p>}
      {post.image_url && <img src={post.image_url} alt="" className="rounded-lg w-full max-h-72 object-cover" loading="lazy" />}

      <div className="flex items-center gap-1 pt-1 border-t border-border/50">
        <button aria-label={post.liked_by_me ? "Beğeniyi kaldır" : "Beğen"} onClick={() => onLike(post.id)} className="flex items-center gap-1 text-xs text-muted-foreground hover:text-destructive transition-colors px-2 py-1.5 rounded-md hover:bg-destructive/10">
          <Heart className={`h-4 w-4 transition-all ${post.liked_by_me ? "fill-destructive text-destructive scale-110" : ""}`} />
          {post.like_count > 0 && <span>{post.like_count}</span>}
        </button>
        <button aria-label="Yorum yap" onClick={() => setActiveComment(activeComment === post.id ? null : post.id)} className="flex items-center gap-1 text-xs text-muted-foreground hover:text-primary transition-colors px-2 py-1.5 rounded-md hover:bg-primary/10">
          <MessageCircle className="h-4 w-4" />
          {post.comment_count > 0 && <span>{post.comment_count}</span>}
        </button>
        <button aria-label="Repost" onClick={() => { onRepost(post.id); toast.success("Repost yapıldı!"); }} className="flex items-center gap-1 text-xs text-muted-foreground hover:text-neon transition-colors px-2 py-1.5 rounded-md hover:bg-neon/10">
          <Repeat2 className="h-4 w-4" />
          {post.repost_count > 0 && <span>{post.repost_count}</span>}
        </button>
        <div aria-label={`${post.view_count || 0} görüntülenme`} className="flex items-center gap-1 text-[10px] text-muted-foreground/50 ml-auto">
          <Eye className="h-3 w-3" /> {post.view_count || 0}
        </div>
        {userId && post.user_id !== userId && (
          <TipDialog
            senderId={userId}
            receiverId={post.user_id}
            receiverName={post.profile?.display_name || "Kullanıcı"}
            trigger={
              <button className="text-gold hover:text-gold/80 transition-colors px-2 py-1.5 rounded-md hover:bg-gold/10 text-xs font-medium">
                💰
              </button>
            }
          />
        )}
        {userId && post.user_id === userId && !isBoosted && (
          <BoostButton userId={userId} targetType="post" targetId={post.id} isBoosted={isBoosted} />
        )}
        <button aria-label="Paylaş" onClick={handleShare} className="text-muted-foreground hover:text-foreground transition-colors px-2 py-1.5 rounded-md hover:bg-accent">
          <Share2 className="h-4 w-4" />
        </button>
        <button aria-label="Şikayet et" onClick={handleFlag} className="text-muted-foreground hover:text-destructive transition-colors px-1.5 py-1.5 rounded-md hover:bg-destructive/10">
          <Flag className="h-3.5 w-3.5" />
        </button>
      </div>

      {activeComment === post.id && <CommentSection postId={post.id} userId={userId} />}
    </Card>
  );
}

