function NewsFeed({ articles, loading }: { articles: NewsArticle[]; loading: boolean }) {
  if (loading) return <FeedSkeleton />;
  if (articles.length === 0) return <EmptyFeed message="Henüz haber yok" />;
  return <div className="space-y-3 px-2 pb-4">{articles.map(a => <NewsCard key={a.id} article={a} />)}</div>;
}

function PostsFeed({ posts, loading, onLike, onRepost, onView, userId, activeComment, setActiveComment, boostedPostIds }: any) {
  if (loading) return <FeedSkeleton />;
  if (posts.length === 0) return <EmptyFeed message="Henüz gönderi yok" />;
  const sorted = [...posts].sort((a: Post, b: Post) => {
    const aBoost = boostedPostIds?.has(a.id) ? 50 : 0;
    const bBoost = boostedPostIds?.has(b.id) ? 50 : 0;
    return ((b.trendScore || 0) + bBoost) - ((a.trendScore || 0) + aBoost);
  });
  return (
    <div className="space-y-3 px-2 pb-4">
      {sorted.map((p: Post, idx: number) => (
        <PostCard key={p.id} post={p} onLike={onLike} onRepost={onRepost} onView={onView} userId={userId} activeComment={activeComment} setActiveComment={setActiveComment} isTrending={idx < 2 && (p.trendScore || 0) > 10} isBoosted={boostedPostIds?.has(p.id)} />
      ))}
    </div>
  );
}



function KurdpediaFeed({ articles, loading }: { articles: KurdpediaArticle[]; loading: boolean }) {
  const [search, setSearch] = useState("");
  const [catFilter, setCatFilter] = useState<KurdpediaCategory>("all");
  const [showAI, setShowAI] = useState(false);
  const [aiQuery, setAiQuery] = useState("");
  const [aiAnswer, setAiAnswer] = useState("");
  const [aiLoading, setAiLoading] = useState(false);

  if (loading) return <FeedSkeleton />;

  const categoryLabels: Record<string, string> = {
    history: "📜 Tarih", culture: "🎭 Kültür", figures: "👤 Kişiler", places: "📍 Yerler",
  };

  const filtered = articles.filter(a => {
    const matchSearch = !search || a.title.toLowerCase().includes(search.toLowerCase()) || a.content.toLowerCase().includes(search.toLowerCase());
    const matchCat = catFilter === "all" || a.category === catFilter;
    return matchSearch && matchCat;
  });

  const handleAI = async () => {
    if (!aiQuery.trim()) return;
    setAiLoading(true);
    setAiAnswer("");
    try {
      const res = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/kurdpedia-ai`, {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}` },
        body: JSON.stringify({ question: aiQuery.trim() }),
      });
      const data = await res.json();
      setAiAnswer(data.answer || "Yanıt alınamadı.");
    } catch {
      setAiAnswer("Bir hata oluştu, tekrar deneyin.");
    }
    setAiLoading(false);
  };

  return (
    <div className="space-y-3 px-2 pb-4">
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
        <Input placeholder="Makale ara..." value={search} onChange={e => setSearch(e.target.value)} className="pl-9 h-9 text-sm" />
      </div>

      <div className="flex gap-1.5 overflow-x-auto pb-1 scrollbar-none">
        <Button size="sm" variant={catFilter === "all" ? "default" : "outline"} className="text-xs h-7 shrink-0" onClick={() => setCatFilter("all")}>Tümü</Button>
        {CATEGORIES.map(cat => (
          <Button key={cat} size="sm" variant={catFilter === cat ? "default" : "outline"} className="text-xs h-7 shrink-0" onClick={() => setCatFilter(cat)}>
            {categoryLabels[cat] || cat}
          </Button>
        ))}
      </div>

      <Card className="p-3">
        <button onClick={() => setShowAI(!showAI)} className="flex items-center gap-2 w-full text-left">
          <Bot className="h-5 w-5 text-neon" />
          <span className="text-sm font-semibold text-foreground flex-1">Kurdpedia AI</span>
          <span className="text-[10px] text-muted-foreground">{showAI ? "Kapat" : "Sor"}</span>
        </button>
        {showAI && (
          <div className="mt-3 space-y-2">
            <p className="text-xs text-muted-foreground">Kürt tarihi, kültürü ve coğrafyası hakkında sorular sor</p>
            <div className="flex gap-2">
              <Input value={aiQuery} onChange={e => setAiQuery(e.target.value)} placeholder="Örn: Newroz nedir?" className="h-8 text-xs" onKeyDown={e => e.key === "Enter" && handleAI()} />
              <Button size="sm" onClick={handleAI} disabled={aiLoading || !aiQuery.trim()} className="shrink-0">
                {aiLoading ? <Loader2 className="h-3 w-3 animate-spin" /> : <Send className="h-3 w-3" />}
              </Button>
            </div>
            {aiAnswer && (
              <div className="bg-secondary/50 rounded-lg p-3 text-xs text-foreground whitespace-pre-wrap">{aiAnswer}</div>
            )}
          </div>
        )}
      </Card>

      {filtered.length === 0 ? (
        <EmptyFeed message="Sonuç bulunamadı" />
      ) : (
        filtered.map(a => <KurdpediaCard key={a.id} article={a} />)
      )}
    </div>
  );
}

// ---- Helpers ----
function FeedSkeleton() {
  return (
    <div className="space-y-3 px-2">
      {[1, 2, 3].map(i => (
        <Card key={i} className="p-4 animate-pulse">
          <div className="flex items-center gap-2 mb-3">
            <div className="h-9 w-9 rounded-full bg-muted" />
            <div className="space-y-1 flex-1">
              <div className="h-3 w-24 bg-muted rounded" />
              <div className="h-2 w-16 bg-muted rounded" />
            </div>
          </div>
          <div className="h-4 w-full bg-muted rounded mb-2" />
          <div className="h-4 w-3/4 bg-muted rounded" />
        </Card>
      ))}
    </div>
  );
}

function EmptyFeed({ message = "Feed boş" }: { message?: string }) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <Newspaper className="h-12 w-12 text-muted-foreground/30 mb-3" />
      <p className="text-sm text-muted-foreground">{message}</p>
    </div>
  );
}

function timeAgo(date: string): string {
  const diff = Date.now() - new Date(date).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "şimdi";
  if (mins < 60) return `${mins}dk`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}sa`;
  const days = Math.floor(hrs / 24);
  return `${days}g`;
}

function renderHashtags(text: string) {
  return text.split(/(#\w+)/g).map((part, i) =>
    part.startsWith("#") ? (
      <span key={i} className="text-neon font-semibold">{part}</span>
    ) : part
  );
}

