import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/hooks/useAuth";
import { useFriends } from "@/hooks/useFriends";
import { useState, useCallback, useEffect } from "react";
import {
  Search,
  UserPlus,
  UserMinus,
  MessageCircle,
  QrCode,
  Phone,
  Hash,
  Share2,
  Copy,
  Check,
  MapPin,
  Contact,
  Users,
  ExternalLink,
} from "lucide-react";
import { QRCodeSVG } from "qrcode.react";
import { createDirectChat } from "@/hooks/useChat";
import { TipDialog } from "@/components/wallet/TipDialog";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

export const Route = createFileRoute("/friends")({
  component: FriendsPage,
  head: () => ({
    meta: [
      { title: "Contacts – Jiyan Europe" },
      { name: "description", content: "Find and add friends on Jiyan Europe." },
    ],
  }),
});

interface ContactResult {
  name: string;
  phone: string;
  profile?: {
    user_id: string;
    display_name: string;
    kurd_id: string | null;
    city: string;
    is_online: boolean;
    avatar_url: string | null;
  } | null;
}

function FriendsPage() {
  const { user } = useAuth();
  const { friends, loading, addFriend, removeFriend, searchByKurdId, searchByPhone } = useFriends(user?.id);
  const [activeTab, setActiveTab] = useState<"contacts" | "friends" | "search" | "qr">("contacts");
  const [searchMode, setSearchMode] = useState<"kurdid" | "phone">("kurdid");
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [searchLoading, setSearchLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [contacts, setContacts] = useState<ContactResult[]>([]);
  const [contactsLoading, setContactsLoading] = useState(false);
  const [contactsSynced, setContactsSynced] = useState(false);

  const [supportsContactPicker, setSupportsContactPicker] = useState(false);

  useEffect(() => {
    setSupportsContactPicker(typeof window !== "undefined" && "contacts" in navigator && "ContactsManager" in window);
  }, []);

  const syncContacts = useCallback(async () => {
    if (!user) return;
    setContactsLoading(true);
    try {
      if (supportsContactPicker) {
        const contactsApi = (navigator as any).contacts;
        const selected = await contactsApi.select(["name", "tel"], { multiple: true });
        const phoneNumbers: { name: string; phone: string }[] = selected
          .filter((c: any) => c.tel && c.tel.length > 0)
          .map((c: any) => ({ name: c.name?.[0] || "Unknown", phone: c.tel[0] }));

        if (phoneNumbers.length === 0) {
          toast.info("Hiç kişi seçilmedi");
          setContactsLoading(false);
          return;
        }

        const { data: matchedProfiles } = await supabase
          .from("profiles")
          .select("user_id, display_name, kurd_id, city, is_online, avatar_url, phone_number")
          .not("phone_number", "is", null);

        const results: ContactResult[] = phoneNumbers.map((contact) => {
          const normalized = contact.phone.replace(/[\s\-\(\)]/g, "");
          const matched = matchedProfiles?.find((p) => {
            const pNorm = p.phone_number?.replace(/[\s\-\(\)]/g, "") || "";
            return pNorm === normalized || pNorm.endsWith(normalized.slice(-9)) || normalized.endsWith(pNorm.slice(-9));
          });
          return {
            name: contact.name,
            phone: contact.phone,
            profile: matched && matched.user_id !== user.id
              ? { user_id: matched.user_id, display_name: matched.display_name, kurd_id: matched.kurd_id, city: matched.city, is_online: matched.is_online, avatar_url: matched.avatar_url }
              : null,
          };
        });

        results.sort((a, b) => {
          if (a.profile && !b.profile) return -1;
          if (!a.profile && b.profile) return 1;
          return a.name.localeCompare(b.name);
        });

        setContacts(results);
        setContactsSynced(true);
        toast.success(`${results.length} kişi tarandı, ${results.filter((r) => r.profile).length} kullanıcı bulundu`);
      } else {
        toast.info("Bu tarayıcı rehber erişimini desteklemiyor. Manuel arama yapabilirsiniz.");
      }
    } catch (err: any) {
      if (err.name !== "AbortError") {
        toast.error("Rehber erişimi başarısız");
      }
    }
    setContactsLoading(false);
  }, [user, supportsContactPicker]);

  if (!user) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center px-4 pt-20 text-center">
          <UserPlus className="h-12 w-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground text-sm mb-4">Sign in to find friends</p>
          <Button variant="neon" asChild>
            <Link to="/login">Sign In</Link>
          </Button>
        </div>
      </AppShell>
    );
  }

  const friendIds = new Set(friends.map((f) => f.user_id));
  const profileUrl = typeof window !== "undefined" ? `${window.location.origin}/friends?add=${user.id}` : "";

  const handleInvite = (contact: ContactResult) => {
    const text = encodeURIComponent(`Jiyan Europe'a katıl! 🌍\n${profileUrl}`);
    const phone = contact.phone.replace(/[\s\-\(\)]/g, "");
    window.open(`https://wa.me/${phone}?text=${text}`, "_blank");
  };

  const handleSMSInvite = (contact: ContactResult) => {
    const text = encodeURIComponent(`Jiyan Europe'a katıl! ${profileUrl}`);
    const phone = contact.phone.replace(/[\s\-\(\)]/g, "");
    window.open(`sms:${phone}?body=${text}`, "_blank");
  };

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setSearchLoading(true);
    const results = searchMode === "kurdid" ? await searchByKurdId(searchQuery) : await searchByPhone(searchQuery);
    setSearchResults(results.filter((r) => r.user_id !== user.id));
    setSearchLoading(false);
  };

  const handleAdd = async (friendId: string) => {
    setActionLoading(friendId);
    const profile = searchResults.find((r) => r.user_id === friendId) || contacts.find((c) => c.profile?.user_id === friendId)?.profile;
    await addFriend(friendId, profile);
    setActionLoading(null);
  };

  const handleRemove = async (friendId: string) => {
    setActionLoading(friendId);
    await removeFriend(friendId);
    setActionLoading(null);
  };

  const handleStartChat = async (friendId: string) => {
    try {
      await createDirectChat(user.id, friendId);
    } catch { /* room might already exist */ }
    window.location.href = "/chat";
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(profileUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShareWhatsApp = () => {
    window.open(`https://wa.me/?text=${encodeURIComponent(`Jiyan Europe'da beni ekle: ${profileUrl}`)}`, "_blank");
  };

  const handleShareTelegram = () => {
    window.open(`https://t.me/share/url?url=${encodeURIComponent(profileUrl)}&text=${encodeURIComponent("Jiyan Europe'da beni ekle!")}`, "_blank");
  };

  const onTheApp = contacts.filter((c) => c.profile);
  const notOnTheApp = contacts.filter((c) => !c.profile);

  return (
    <AppShell>
      <div className="px-4 pt-6">
        <div className="flex items-center justify-between">
          <h1 className="text-xl font-bold text-foreground">Contacts</h1>
          <span className="text-xs text-muted-foreground">{friends.length} friends</span>
        </div>

        {/* Tabs */}
        <div className="mt-3 flex gap-1 rounded-xl bg-surface p-1">
          {([
            { key: "contacts" as const, label: "Rehber", icon: Contact },
            { key: "friends" as const, label: "Friends", icon: Users },
            { key: "search" as const, label: "Ara", icon: Search },
            { key: "qr" as const, label: "QR", icon: QrCode },
          ]).map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`flex flex-1 items-center justify-center gap-1 rounded-lg py-2 text-xs font-medium transition-all ${
                  activeTab === tab.key ? "bg-neon text-neon-foreground" : "text-muted-foreground hover:text-foreground"
                }`}
              >
                <Icon className="h-3 w-3" />
                {tab.label}
              </button>
            );
          })}
        </div>

        {/* Contacts Tab */}
        {activeTab === "contacts" && (
          <div className="mt-4 pb-4">
            {!contactsSynced ? (
              <div className="flex flex-col items-center py-12 text-center">
                <div className="flex h-16 w-16 items-center justify-center rounded-full bg-neon/10 mb-4">
                  <Contact className="h-8 w-8 text-neon" />
                </div>
                <h3 className="text-sm font-semibold text-foreground mb-1">Rehberini Senkronize Et</h3>
                <p className="text-xs text-muted-foreground mb-4 max-w-[250px]">
                  {supportsContactPicker
                    ? "Rehberindeki kişilerin Jiyan Europe'da olup olmadığını öğren"
                    : "Bu tarayıcı rehber erişimini desteklemiyor. Arama sekmesinden manuel olarak arkadaş bulabilirsin."}
                </p>
                {supportsContactPicker ? (
                  <Button variant="neon" onClick={syncContacts} disabled={contactsLoading}>
                    {contactsLoading ? "Taranıyor..." : "📱 Rehberi Tara"}
                  </Button>
                ) : (
                  <div className="space-y-2 w-full">
                    <Button variant="neon" className="w-full" onClick={() => setActiveTab("search")}>
                      <Search className="h-4 w-4 mr-1" /> Manuel Arama
                    </Button>
                    <Button variant="outline" className="w-full" onClick={handleShareWhatsApp}>
                      💬 WhatsApp ile Davet Et
                    </Button>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-4">
                <Button variant="outline" size="sm" onClick={syncContacts} disabled={contactsLoading} className="w-full">
                  {contactsLoading ? "Taranıyor..." : "🔄 Yeniden Tara"}
                </Button>

                {onTheApp.length > 0 && (
                  <div>
                    <p className="text-xs font-semibold text-neon mb-2 flex items-center gap-1">
                      <span className="h-2 w-2 rounded-full bg-neon" />
                      Jiyan Europe'da ({onTheApp.length})
                    </p>
                    <div className="space-y-2">
                      {onTheApp.map((contact, i) => {
                        const isFriend = friendIds.has(contact.profile!.user_id);
                        return (
                          <div key={i} className="flex items-center gap-3 rounded-xl border border-neon/20 bg-neon/5 p-3">
                            <div className="relative">
                              <div className="flex h-11 w-11 items-center justify-center rounded-full bg-accent text-lg border border-border">
                                {contact.profile?.avatar_url ? (
                                  <img src={contact.profile.avatar_url} alt="" className="h-full w-full rounded-full object-cover" />
                                ) : "👤"}
                              </div>
                              <div className={`absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full border-2 border-surface ${contact.profile?.is_online ? "bg-neon" : "bg-muted-foreground"}`} />
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className="truncate text-sm font-semibold text-foreground">{contact.profile!.display_name}</p>
                              <p className="text-[10px] text-muted-foreground truncate">{contact.name} • {contact.profile!.kurd_id}</p>
                            </div>
                            <div className="flex gap-1">
                              {isFriend ? (
                                <button onClick={() => handleStartChat(contact.profile!.user_id)} className="flex h-8 items-center gap-1 rounded-lg bg-neon/10 px-2 text-neon hover:bg-neon/20 transition-all">
                                  <MessageCircle className="h-3.5 w-3.5" />
                                  <span className="text-[10px] font-medium">Chat</span>
                                </button>
                              ) : (
                                <Button variant="neon" size="sm" onClick={() => handleAdd(contact.profile!.user_id)} disabled={actionLoading === contact.profile!.user_id}>
                                  <UserPlus className="h-3.5 w-3.5 mr-1" />
                                  <span className="text-[10px]">Ekle</span>
                                </Button>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}

                {notOnTheApp.length > 0 && (
                  <div>
                    <p className="text-xs font-semibold text-muted-foreground mb-2 flex items-center gap-1">
                      <span className="h-2 w-2 rounded-full bg-muted-foreground" />
                      Henüz Katılmamış ({notOnTheApp.length})
                    </p>
                    <div className="space-y-2">
                      {notOnTheApp.map((contact, i) => (
                        <div key={i} className="flex items-center gap-3 rounded-xl border border-border bg-surface p-3">
                          <div className="flex h-11 w-11 items-center justify-center rounded-full bg-muted text-lg border border-border">👤</div>
                          <div className="flex-1 min-w-0">
                            <p className="truncate text-sm font-medium text-foreground">{contact.name}</p>
                            <p className="text-[10px] text-muted-foreground">{contact.phone}</p>
                          </div>
                          <div className="flex gap-1">
                            <button onClick={() => handleInvite(contact)} className="flex h-8 items-center gap-1 rounded-lg bg-neon/10 px-2 text-neon hover:bg-neon/20 transition-all">
                              <ExternalLink className="h-3 w-3" />
                              <span className="text-[10px] font-medium">Davet</span>
                            </button>
                            <button onClick={() => handleSMSInvite(contact)} className="flex h-8 items-center gap-1 rounded-lg bg-accent px-2 text-muted-foreground hover:text-foreground transition-all">
                              <Phone className="h-3 w-3" />
                              <span className="text-[10px] font-medium">SMS</span>
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* Friends list */}
        {activeTab === "friends" && (
          <div className="mt-4 space-y-2 pb-4">
            {loading ? (
              <div className="py-12 text-center text-sm text-muted-foreground">Loading...</div>
            ) : friends.length === 0 ? (
              <div className="py-12 text-center">
                <UserPlus className="mx-auto h-10 w-10 text-muted-foreground mb-3" />
                <p className="text-sm text-muted-foreground">No friends yet</p>
                <Button variant="neon" size="sm" className="mt-3" onClick={() => setActiveTab("search")}>Find Friends</Button>
              </div>
            ) : (
              friends.map((friend) => (
                <div key={friend.user_id} className="flex items-center gap-3 rounded-xl border border-border bg-surface p-3">
                  <div className="relative">
                    <div className="flex h-11 w-11 items-center justify-center rounded-full bg-accent text-lg border border-border">👤</div>
                    <div className={`absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full border-2 border-surface ${friend.is_online ? "bg-neon" : "bg-muted-foreground"}`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="truncate text-sm font-semibold text-foreground">{friend.display_name}</p>
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] text-muted-foreground">{friend.kurd_id}</span>
                      <div className="flex items-center gap-0.5">
                        <MapPin className="h-2.5 w-2.5 text-muted-foreground" />
                        <span className="text-[10px] text-muted-foreground">{friend.city}</span>
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-1">
                    <TipDialog senderId={user.id} receiverId={friend.user_id} receiverName={friend.display_name} trigger={
                      <button className="flex h-8 w-8 items-center justify-center rounded-lg bg-gold/10 text-gold hover:bg-gold/20 transition-all"><span className="text-sm">💰</span></button>
                    } />
                    <button onClick={() => handleStartChat(friend.user_id)} className="flex h-8 w-8 items-center justify-center rounded-lg bg-neon/10 text-neon hover:bg-neon/20 transition-all">
                      <MessageCircle className="h-4 w-4" />
                    </button>
                    <button onClick={() => handleRemove(friend.user_id)} disabled={actionLoading === friend.user_id} className="flex h-8 w-8 items-center justify-center rounded-lg bg-destructive/10 text-destructive hover:bg-destructive/20 transition-all disabled:opacity-50">
                      <UserMinus className="h-4 w-4" />
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {/* Search / Add */}
        {activeTab === "search" && (
          <div className="mt-4 pb-4">
            <div className="flex gap-2 mb-3">
              <button onClick={() => { setSearchMode("kurdid"); setSearchResults([]); setSearchQuery(""); }} className={`flex flex-1 items-center justify-center gap-1.5 rounded-xl py-2.5 text-xs font-medium transition-all ${searchMode === "kurdid" ? "bg-neon/10 border border-neon/30 text-neon" : "bg-surface border border-border text-muted-foreground"}`}>
                <Hash className="h-3.5 w-3.5" /> KurdID
              </button>
              <button onClick={() => { setSearchMode("phone"); setSearchResults([]); setSearchQuery(""); }} className={`flex flex-1 items-center justify-center gap-1.5 rounded-xl py-2.5 text-xs font-medium transition-all ${searchMode === "phone" ? "bg-neon/10 border border-neon/30 text-neon" : "bg-surface border border-border text-muted-foreground"}`}>
                <Phone className="h-3.5 w-3.5" /> Phone
              </button>
            </div>
            <div className="flex gap-2">
              <div className="flex flex-1 items-center gap-2 rounded-xl border border-border bg-surface px-3">
                <Search className="h-4 w-4 text-muted-foreground" />
                <input type="text" placeholder={searchMode === "kurdid" ? "+KRD..." : "Phone number..."} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === "Enter" && handleSearch()} className="h-10 flex-1 bg-transparent text-sm text-foreground placeholder:text-muted-foreground focus:outline-none" />
              </div>
              <Button variant="neon" size="default" onClick={handleSearch} disabled={searchLoading}>{searchLoading ? "..." : "Ara"}</Button>
            </div>
            <div className="mt-4 space-y-2">
              {searchResults.length === 0 && !searchLoading && searchQuery && (
                <div className="py-8 text-center text-sm text-muted-foreground">Kullanıcı bulunamadı</div>
              )}
              {searchResults.map((profile) => {
                const isFriend = friendIds.has(profile.user_id);
                return (
                  <div key={profile.user_id} className="flex items-center gap-3 rounded-xl border border-border bg-surface p-3">
                    <div className="relative">
                      <div className="flex h-11 w-11 items-center justify-center rounded-full bg-accent text-lg border border-border">👤</div>
                      <div className={`absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full border-2 border-surface ${profile.is_online ? "bg-neon" : "bg-muted-foreground"}`} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="truncate text-sm font-semibold text-foreground">{profile.display_name}</p>
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] text-muted-foreground">{profile.kurd_id}</span>
                        <div className="flex items-center gap-0.5">
                          <MapPin className="h-2.5 w-2.5 text-muted-foreground" />
                          <span className="text-[10px] text-muted-foreground">{profile.city}</span>
                        </div>
                      </div>
                    </div>
                    {isFriend ? (
                      <span className="rounded-lg bg-neon/10 px-2 py-1 text-[10px] font-medium text-neon">✓ Friend</span>
                    ) : (
                      <Button variant="neon" size="sm" onClick={() => handleAdd(profile.user_id)} disabled={actionLoading === profile.user_id}>
                        <UserPlus className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* QR Code & Share */}
        {activeTab === "qr" && (
          <div className="mt-4 pb-4">
            <div className="flex flex-col items-center rounded-2xl border border-border bg-surface p-6">
              <div className="rounded-2xl bg-foreground p-4">
                <QRCodeSVG value={profileUrl} size={180} bgColor="hsl(0 0% 100%)" fgColor="hsl(0 0% 0%)" level="M" includeMargin={false} />
              </div>
              <p className="mt-3 text-sm font-semibold text-foreground">QR Kodu Tarat</p>
              <p className="mt-1 text-xs text-muted-foreground">Jiyan Europe'da bağlanmak için bu QR kodu paylaş</p>
            </div>
