              <button onClick={handleShareTelegram} className="flex w-full items-center gap-3 rounded-xl border border-border bg-surface p-3 transition-all hover:bg-accent active:scale-[0.99]">
                <div className="flex h-9 w-9 items-center justify-center rounded-full bg-accent"><span className="text-lg">✈️</span></div>
                <div className="flex-1 text-left">
                  <p className="text-sm font-medium text-foreground">Telegram</p>
                  <p className="text-[10px] text-muted-foreground">Telegram ile paylaş</p>
                </div>
              </button>
              {typeof navigator !== "undefined" && "share" in navigator && (
                <button onClick={() => navigator.share({ title: "Jiyan Europe", text: "Beni ekle!", url: profileUrl })} className="flex w-full items-center gap-3 rounded-xl border border-border bg-surface p-3 transition-all hover:bg-accent active:scale-[0.99]">
                  <div className="flex h-9 w-9 items-center justify-center rounded-full bg-gold/10"><Share2 className="h-4 w-4 text-gold" /></div>
                  <div className="flex-1 text-left">
                    <p className="text-sm font-medium text-foreground">Diğer Seçenekler</p>
                    <p className="text-[10px] text-muted-foreground">Diğer uygulamalar ile paylaş</p>
                  </div>
                </button>
              )}
            </div>
          </div>
        )}
      </div>
    </AppShell>
  );
}

