import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { Music2, ArrowLeft, Loader2, CheckCircle2, XCircle } from "lucide-react";
import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

export const Route = createFileRoute("/games/dengbej")({
  component: DengbejQuiz,
  head: () => ({
    meta: [
      { title: "Dengbêj Quiz – Jiyan Games" },
      { name: "description", content: "Kürt müziği, tarihi ve kültürü hakkında 10 soruluk quiz!" },
    ],
  }),
});

type Question = {
  id: string;
  question: string;
  options: string[];
  correct_answer: string;
  explanation: string | null;
  category: string;
};

const QUIZ_LENGTH = 10;

function DengbejQuiz() {
  const { user } = useAuth();
  const [questions, setQuestions] = useState<Question[]>([]);
  const [idx, setIdx] = useState(0);
  const [selected, setSelected] = useState<string | null>(null);
  const [showResult, setShowResult] = useState(false);
  const [score, setScore] = useState(0);
  const [done, setDone] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      const { data } = await supabase
        .from("dengbej_questions")
        .select("*")
        .limit(50);
      if (data) {
        const shuffled = [...data].sort(() => Math.random() - 0.5).slice(0, QUIZ_LENGTH);
        setQuestions(shuffled.map((q) => ({
          ...q,
          options: Array.isArray(q.options) ? q.options as string[] : JSON.parse(q.options as string),
        })));
      }
      setLoading(false);
    })();
  }, []);

  const current = questions[idx];

  const handleAnswer = (option: string) => {
    if (showResult) return;
    setSelected(option);
    setShowResult(true);
    if (option === current.correct_answer) {
      setScore((s) => s + 1);
    }
  };

  const next = async () => {
    if (idx + 1 >= questions.length) {
      setDone(true);
      const dc = score >= 8 ? 5 : score >= 5 ? 2 : score >= 3 ? 1 : 0;
      if (user) {
        await supabase.from("game_scores").insert({
          user_id: user.id, game_code: "dengbej",
          score: score * 10, dc_earned: dc,
        });
      }
      if (dc > 0) toast.success(`+${dc} DC kazandın!`);
    } else {
      setIdx((i) => i + 1);
      setSelected(null);
      setShowResult(false);
    }
  };

  if (loading) {
    return (
      <AppShell>
        <div className="flex items-center justify-center min-h-screen">
          <Loader2 className="h-8 w-8 animate-spin text-violet-500" />
        </div>
      </AppShell>
    );
  }

  if (questions.length === 0) {
    return (
      <AppShell>
        <div className="px-4 pt-6 text-center">
          <p className="text-sm text-muted-foreground">Soru bulunamadı.</p>
          <Link to="/games"><Button className="mt-4">Geri Dön</Button></Link>
        </div>
      </AppShell>
    );
  }

  if (done) {
    const dc = score >= 8 ? 5 : score >= 5 ? 2 : score >= 3 ? 1 : 0;
    return (
      <AppShell>
        <div className="bg-gradient-to-b from-violet-950 to-black min-h-screen px-4 pt-10">
          <div className="rounded-3xl bg-gradient-to-br from-violet-600/30 to-purple-900/40 border border-violet-500/40 p-6 text-center">
            <Music2 className="h-16 w-16 text-violet-300 mx-auto mb-3" />
            <p className="text-sm text-white/70">Quiz tamamlandı!</p>
            <p className="text-4xl font-extrabold text-white my-2">{score}/{questions.length}</p>
            <p className="text-base font-bold text-amber-400 mb-4">+{dc} DC</p>
            <Link to="/games">
              <Button className="w-full bg-violet-600 hover:bg-violet-700">Hub'a Dön</Button>
            </Link>
          </div>
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <div className="bg-gradient-to-b from-violet-950 via-purple-950 to-black min-h-screen">
        <div className="px-4 pt-6 pb-4">
          <Link to="/games" className="flex items-center gap-1 text-sm text-white/70 mb-4">
            <ArrowLeft className="h-4 w-4" /> Jiyan Games
          </Link>

          <div className="flex items-center justify-between mb-4">
            <h1 className="text-lg font-bold text-white flex items-center gap-2">
              <Music2 className="h-5 w-5 text-violet-300" /> Dengbêj Quiz
            </h1>
            <span className="text-xs text-white/70">{idx + 1}/{questions.length}</span>
          </div>

          {/* Progress */}
          <div className="h-1.5 rounded-full bg-white/10 mb-5 overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-violet-500 to-fuchsia-500 transition-all"
              style={{ width: `${((idx + 1) / questions.length) * 100}%` }}
            />
          </div>

          <div className="rounded-2xl bg-black/40 border border-violet-500/20 p-4 mb-4">
            <span className="inline-block rounded-full bg-violet-500/20 px-2 py-0.5 text-[10px] font-bold text-violet-300 uppercase tracking-wider mb-2">
              {current.category}
            </span>
            <p className="text-base font-semibold text-white leading-snug">{current.question}</p>
          </div>

          <div className="space-y-2">
            {current.options.map((opt) => {
              const isCorrect = opt === current.correct_answer;
              const isSelected = opt === selected;
              let cls = "bg-white/5 border-white/10 text-white hover:bg-white/10";
              if (showResult && isCorrect) cls = "bg-green-600/30 border-green-500/60 text-green-100";
              else if (showResult && isSelected) cls = "bg-red-600/30 border-red-500/60 text-red-100";
              return (
                <button
                  key={opt}
                  onClick={() => handleAnswer(opt)}
                  disabled={showResult}
                  className={`w-full rounded-xl border-2 p-3 text-left text-sm font-medium transition ${cls} disabled:cursor-default`}
                >
                  <div className="flex items-center justify-between">
                    <span>{opt}</span>
                    {showResult && isCorrect && <CheckCircle2 className="h-4 w-4 text-green-300" />}
                    {showResult && isSelected && !isCorrect && <XCircle className="h-4 w-4 text-red-300" />}
                  </div>
                </button>
              );
            })}
          </div>

          {showResult && (
            <>
              {current.explanation && (
                <div className="mt-3 rounded-xl bg-violet-500/10 border border-violet-500/30 p-3">
                  <p className="text-xs text-violet-200 leading-relaxed">💡 {current.explanation}</p>
                </div>
              )}
              <Button onClick={next} className="w-full mt-3 bg-violet-600 hover:bg-violet-700">
                {idx + 1 >= questions.length ? "Sonucu Gör" : "Sonraki Soru →"}
              </Button>
            </>
          )}
        </div>
      </div>
    </AppShell>
  );
}

