import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { Activity, ArrowLeft } from "lucide-react";
import { useState, useEffect, useRef } from "react";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

export const Route = createFileRoute("/games/halay")({
  component: HalayGame,
  head: () => ({
    meta: [
      { title: "Halay Ritim – Jiyan Games" },
      { name: "description", content: "Govend ritmine uygun zamanda dokun, kombo yap!" },
    ],
  }),
});

const BEAT_INTERVAL = 700; // ms — Halay tempo
const TOTAL_BEATS = 30;
const TIMING_WINDOW = 200; // ms ± for "hit"

type Beat = { id: number; spawnAt: number; hit: boolean | null };

function HalayGame() {
  const { user } = useAuth();
  const [phase, setPhase] = useState<"idle" | "playing" | "done">("idle");
  const [beats, setBeats] = useState<Beat[]>([]);
  const [score, setScore] = useState(0);
  const [combo, setCombo] = useState(0);
  const [bestCombo, setBestCombo] = useState(0);
  const [activeBeat, setActiveBeat] = useState<number | null>(null);
  const startTime = useRef<number>(0);
  const beatIdx = useRef<number>(0);

  useEffect(() => {
    if (phase !== "playing") return;
    startTime.current = Date.now();
    beatIdx.current = 0;
    setBeats([]);

    const spawnInterval = setInterval(() => {
      if (beatIdx.current >= TOTAL_BEATS) {
        clearInterval(spawnInterval);
        setTimeout(() => setPhase("done"), 1500);
        return;
      }
      const beat: Beat = { id: beatIdx.current, spawnAt: Date.now(), hit: null };
      setBeats((bs) => [...bs, beat]);
      setActiveBeat(beat.id);
      beatIdx.current++;

      // Auto-miss after window
      setTimeout(() => {
        setBeats((bs) => bs.map((b) => b.id === beat.id && b.hit === null ? { ...b, hit: false } : b));
        setActiveBeat((curr) => curr === beat.id ? null : curr);
      }, TIMING_WINDOW * 2);
    }, BEAT_INTERVAL);

    return () => clearInterval(spawnInterval);
  }, [phase]);

  useEffect(() => {
    if (phase === "done" && user) {
      const dc = score >= 25 ? 5 : score >= 15 ? 2 : score >= 8 ? 1 : 0;
      supabase.from("game_scores").insert({
        user_id: user.id, game_code: "halay",
        score, dc_earned: dc,
        metadata: { best_combo: bestCombo },
      }).then(() => {
        if (dc > 0) toast.success(`🪘 +${dc} DC · Best combo: ${bestCombo}`);
      });
    }
  }, [phase, user, score, bestCombo]);

  const handleTap = () => {
    if (phase !== "playing" || activeBeat === null) {
      // miss tap
      setCombo(0);
      return;
    }
    setBeats((bs) => bs.map((b) => b.id === activeBeat ? { ...b, hit: true } : b));
    setScore((s) => s + 1);
    setCombo((c) => {
      const next = c + 1;
      setBestCombo((bc) => Math.max(bc, next));
      return next;
    });
    setActiveBeat(null);
  };

  const start = () => {
    setScore(0); setCombo(0); setBestCombo(0); setBeats([]);
    setPhase("playing");
  };

  return (
    <AppShell>
      <div className="bg-gradient-to-b from-pink-950 via-rose-950 to-black min-h-screen">
        <div className="px-4 pt-6 pb-4">
          <Link to="/games" className="flex items-center gap-1 text-sm text-white/70 mb-4">
            <ArrowLeft className="h-4 w-4" /> Jiyan Games
          </Link>

          <div className="text-center mb-4">
            <h1 className="text-2xl font-extrabold text-white tracking-tight flex items-center justify-center gap-2">
              <Activity className="h-6 w-6 text-pink-400" /> Halay Ritim
            </h1>
            <p className="text-xs text-white/70 mt-1">Govend ritmine uygun dokun · BETA</p>
          </div>

          {phase === "idle" && (
            <>
              <div className="rounded-2xl bg-black/40 border border-pink-500/30 p-5 mb-4 text-center">
                <Activity className="h-16 w-16 text-pink-400 mx-auto mb-3" />
                <p className="text-sm text-white/90 font-semibold mb-2">Govenda Şer</p>
                <p className="text-[11px] text-white/60 leading-relaxed">
                  Daire büyüdüğünde tam zamanında dokun. {TOTAL_BEATS} vuruş · Kombo yaparsan DC kazanırsın.
                </p>
              </div>
              <Button onClick={start} size="lg" className="w-full bg-gradient-to-r from-pink-500 to-rose-600 text-white font-bold">
                Başla
              </Button>
            </>
          )}

          {phase === "playing" && (
            <>
              <div className="flex items-center justify-between mb-4">
                <div className="rounded-xl bg-black/40 border border-white/10 px-3 py-2">
                  <p className="text-[10px] text-white/60">Skor</p>
                  <p className="text-lg font-bold text-white">{score}/{TOTAL_BEATS}</p>
                </div>
                <div className="rounded-xl bg-black/40 border border-pink-500/30 px-3 py-2 text-right">
                  <p className="text-[10px] text-pink-300">Kombo</p>
                  <p className="text-lg font-bold text-pink-400">{combo}🔥</p>
                </div>
              </div>

              <button
                onClick={handleTap}
                onTouchStart={(e) => { e.preventDefault(); handleTap(); }}
                className="relative w-full aspect-square rounded-3xl bg-gradient-to-br from-pink-900/40 to-rose-900/40 border-2 border-pink-500/30 flex items-center justify-center overflow-hidden"
                style={{ touchAction: "manipulation" }}
              >
                {activeBeat !== null && (
                  <div
                    key={activeBeat}
                    className="absolute h-32 w-32 rounded-full bg-pink-500/40 ring-4 ring-pink-300 animate-ping"
                  />
                )}
                <div className="relative h-24 w-24 rounded-full bg-gradient-to-br from-pink-500 to-rose-700 flex items-center justify-center shadow-[0_0_40px_rgba(236,72,153,0.6)]">
                  <Activity className="h-10 w-10 text-white" strokeWidth={2.5} />
                </div>
              </button>

              <p className="text-center text-xs text-white/60 mt-3">Daire çıkınca dokun!</p>
            </>
          )}

          {phase === "done" && (
            <div className="rounded-3xl bg-gradient-to-br from-pink-600/20 to-rose-900/40 border border-pink-500/40 p-6 text-center">
              <Activity className="h-16 w-16 text-pink-400 mx-auto mb-3" />
              <p className="text-sm text-white/70 mb-1">Govend bitti!</p>
              <p className="text-4xl font-extrabold text-white">{score}/{TOTAL_BEATS}</p>
              <p className="text-sm text-pink-300 mt-1">En iyi kombo: {bestCombo}🔥</p>
              <div className="flex gap-2 mt-4">
                <Button onClick={start} variant="outline" className="flex-1 border-pink-500/40 text-white hover:bg-pink-500/20">
                  Tekrar
                </Button>
                <Link to="/games" className="flex-1">
                  <Button variant="outline" className="w-full border-white/20 text-white hover:bg-white/10">Hub</Button>
                </Link>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppShell>
  );
}

