import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { Flame, ArrowLeft, Trophy } from "lucide-react";
import { useState, useEffect, useRef } from "react";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

export const Route = createFileRoute("/games/newroz")({
  component: NewrozGame,
  head: () => ({
    meta: [
      { title: "Newroz Ateşi – Jiyan Games" },
      { name: "description", content: "Tap-to-win Newroz ateş oyunu. Hızlı dokun, alev yükselt, DiravCash kazan!" },
    ],
  }),
});

const GAME_DURATION = 30; // seconds
const DC_PER_100_TAPS = 1;

function NewrozGame() {
  const { user } = useAuth();
  const [phase, setPhase] = useState<"idle" | "playing" | "done">("idle");
  const [taps, setTaps] = useState(0);
  const [timeLeft, setTimeLeft] = useState(GAME_DURATION);
  const [topScores, setTopScores] = useState<Array<{ score: number; user_id: string; display_name?: string }>>([]);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const fetchLeaderboard = async () => {
    const { data } = await supabase
      .from("game_scores")
      .select("score, user_id")
      .eq("game_code", "newroz")
      .order("score", { ascending: false })
      .limit(5);
    if (data) {
      const ids = data.map((r) => r.user_id);
      const { data: profs } = await supabase
        .from("profiles")
        .select("user_id, display_name")
        .in("user_id", ids);
      const nameMap: Record<string, string> = {};
      profs?.forEach((p) => { nameMap[p.user_id] = p.display_name; });
      setTopScores(data.map((r) => ({ ...r, display_name: nameMap[r.user_id] || "Anonim" })));
    }
  };

  useEffect(() => {
    fetchLeaderboard();
  }, []);

  useEffect(() => {
    if (phase !== "playing") return;
    timerRef.current = setInterval(() => {
      setTimeLeft((t) => {
        if (t <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          setPhase("done");
          return 0;
        }
        return t - 1;
      });
    }, 1000);
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [phase]);

  useEffect(() => {
    if (phase === "done" && user && taps > 0) {
      const dcEarned = Math.floor(taps / 100) * DC_PER_100_TAPS;
      supabase.from("game_scores").insert({
        user_id: user.id,
        game_code: "newroz",
        score: taps,
        dc_earned: dcEarned,
      }).then(() => {
        if (dcEarned > 0) {
          toast.success(`🔥 ${taps} tap! +${dcEarned} DC kazandın`);
        }
        fetchLeaderboard();
      });
    }
  }, [phase, user, taps]);

  const start = () => {
    setTaps(0);
    setTimeLeft(GAME_DURATION);
    setPhase("playing");
  };

  const tap = () => {
    if (phase === "playing") setTaps((t) => t + 1);
  };

  // Flame size scales with taps
  const flameScale = 1 + Math.min(taps / 200, 2.5);
  const dcEarned = Math.floor(taps / 100) * DC_PER_100_TAPS;

  return (
    <AppShell>
      <div className="bg-gradient-to-b from-orange-950 via-red-950 to-black min-h-screen">
        <div className="px-4 pt-6 pb-4">
          <Link to="/games" className="flex items-center gap-1 text-sm text-white/70 mb-4">
            <ArrowLeft className="h-4 w-4" /> Jiyan Games
          </Link>

          <div className="text-center mb-4">
            <h1 className="text-2xl font-extrabold text-white tracking-tight">🔥 Newroz Ateşi</h1>
            <p className="text-xs text-white/70 mt-1">Hızlı dokun, alev yükselt, DC kazan!</p>
          </div>

          {phase === "idle" && (
            <>
              <div className="rounded-2xl bg-black/40 border border-orange-500/30 p-5 mb-4 text-center">
                <Flame className="h-16 w-16 text-orange-400 mx-auto mb-3" />
                <p className="text-sm text-white/90 font-semibold mb-2">Kawa'nın efsanesini yaşat</p>
                <p className="text-[11px] text-white/60 leading-relaxed">
                  30 saniye içinde mümkün olduğunca hızlı dokun. Her 100 dokunuş = 1 DC kazanırsın.
                  Zalim Dehak'a karşı ateşi büyüt!
                </p>
              </div>
              <Button onClick={start} size="lg" className="w-full bg-gradient-to-r from-orange-500 to-red-600 hover:from-orange-600 hover:to-red-700 text-white font-bold">
                <Flame className="h-4 w-4 mr-2" /> Ateşi Yak
              </Button>

              {topScores.length > 0 && (
                <div className="mt-6">
                  <p className="text-xs font-semibold text-amber-300 mb-2 flex items-center gap-1">
                    <Trophy className="h-3 w-3" /> Top 5 Kawa
                  </p>
                  <div className="space-y-1.5">
                    {topScores.map((s, i) => (
                      <div key={i} className="flex items-center justify-between rounded-lg bg-black/30 border border-white/5 px-3 py-2">
                        <span className="text-xs text-white/80">#{i + 1} {s.display_name}</span>
                        <span className="text-xs font-bold text-orange-400">{s.score} 🔥</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </>
          )}

          {phase === "playing" && (
            <>
              <div className="flex items-center justify-between mb-4">
                <div className="rounded-xl bg-black/40 border border-white/10 px-3 py-2">
                  <p className="text-[10px] text-white/60">Süre</p>
                  <p className="text-lg font-bold text-white">{timeLeft}s</p>
                </div>
                <div className="rounded-xl bg-black/40 border border-white/10 px-3 py-2 text-right">
                  <p className="text-[10px] text-white/60">Tap</p>
                  <p className="text-lg font-bold text-orange-400">{taps}</p>
                </div>
              </div>

              <button
                onClick={tap}
                onTouchStart={(e) => { e.preventDefault(); tap(); }}
                className="relative w-full aspect-square rounded-3xl bg-gradient-to-br from-orange-600/40 to-red-900/40 border-2 border-orange-500/40 flex items-center justify-center select-none active:bg-orange-500/30 transition-colors"
                style={{ touchAction: "manipulation" }}
              >
                <Flame
                  className="text-orange-400 drop-shadow-[0_0_30px_rgba(251,146,60,0.8)] transition-transform duration-100"
                  style={{ transform: `scale(${flameScale})`, height: "120px", width: "120px" }}
                  strokeWidth={2}
                />
                <span className="absolute bottom-4 text-xs text-white/70 font-medium">Hızlı dokun!</span>
              </button>

              <p className="text-center text-xs text-amber-300 mt-3">
                Şu ana kadar: {dcEarned} DC kazandın
              </p>
            </>
          )}

          {phase === "done" && (
            <div className="rounded-3xl bg-gradient-to-br from-orange-600/20 to-red-900/40 border border-orange-500/40 p-6 text-center">
              <Flame className="h-16 w-16 text-orange-400 mx-auto mb-3 drop-shadow-[0_0_20px_rgba(251,146,60,0.8)]" />
              <p className="text-sm text-white/70 mb-1">Süre doldu!</p>
              <p className="text-4xl font-extrabold text-white mb-1">{taps} 🔥</p>
              <p className="text-base font-bold text-amber-400 mb-4">+{dcEarned} DC kazandın</p>
              <div className="flex gap-2">
                <Button onClick={start} variant="outline" className="flex-1 border-orange-500/40 text-white hover:bg-orange-500/20">
                  Tekrar Oyna
                </Button>
                <Link to="/games" className="flex-1">
                  <Button variant="outline" className="w-full border-white/20 text-white hover:bg-white/10">
                    Hub'a Dön
                  </Button>
                </Link>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppShell>
  );
}

