import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

export const Route = createFileRoute("/games/wordle")({
  component: WordleGame,
  head: () => ({
    meta: [
      { title: "Kürtçe Wordle – Jiyan Games" },
      { name: "description", content: "Günlük 5 harfli Kurmancî kelimeyi 6 denemede tahmin et!" },
    ],
  }),
});

const MAX_GUESSES = 6;
const WORD_LENGTH = 5;

type LetterState = "correct" | "present" | "absent" | "empty";

function WordleGame() {
  const { user } = useAuth();
  const [target, setTarget] = useState<string>("");
  const [meaning, setMeaning] = useState<string>("");
  const [guesses, setGuesses] = useState<string[]>([]);
  const [current, setCurrent] = useState("");
  const [status, setStatus] = useState<"playing" | "won" | "lost">("playing");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      const today = new Date().toISOString().split("T")[0];
      const { data } = await supabase
        .from("wordle_daily_words")
        .select("word, meaning_tr")
        .eq("active_date", today)
        .maybeSingle();
      if (data) {
        setTarget(data.word.toUpperCase());
        setMeaning(data.meaning_tr || "");
      } else {
        // fallback
        setTarget("JIYAN");
        setMeaning("Yaşam");
      }
      setLoading(false);
    })();
  }, []);

  const submitGuess = async () => {
    if (current.length !== WORD_LENGTH) {
      toast.error(`${WORD_LENGTH} harf gir`);
      return;
    }
    const next = [...guesses, current.toUpperCase()];
    setGuesses(next);
    setCurrent("");

    if (current.toUpperCase() === target) {
      setStatus("won");
      const score = (MAX_GUESSES - next.length + 1) * 100;
      const dc = next.length <= 3 ? 5 : next.length <= 5 ? 2 : 1;
      if (user) {
        await supabase.from("game_scores").insert({
          user_id: user.id, game_code: "wordle", score, dc_earned: dc,
          metadata: { word: target, attempts: next.length },
        });
      }
      toast.success(`🎉 Doğru! +${dc} DC`);
    } else if (next.length >= MAX_GUESSES) {
      setStatus("lost");
      toast.error(`Doğru kelime: ${target}`);
    }
  };

  const evalLetter = (letter: string, idx: number, word: string): LetterState => {
    if (target[idx] === letter) return "correct";
    if (target.includes(letter)) return "present";
    return "absent";
  };

  const stateColor = (s: LetterState) => {
    switch (s) {
      case "correct": return "bg-green-600 border-green-700 text-white";
      case "present": return "bg-amber-500 border-amber-600 text-white";
      case "absent": return "bg-zinc-700 border-zinc-800 text-white/70";
      default: return "bg-transparent border-white/20 text-white";
    }
  };

  const KEYS = [
    "QWERTYUIOP".split(""),
    "ASDFGHJKL".split(""),
    ["ENTER", ..."ZXCVBNM".split(""), "DEL"],
  ];

  const pressKey = (k: string) => {
    if (status !== "playing") return;
    if (k === "ENTER") return submitGuess();
    if (k === "DEL") return setCurrent((c) => c.slice(0, -1));
    if (current.length < WORD_LENGTH) setCurrent((c) => c + k);
  };

  if (loading) {
    return (
      <AppShell>
        <div className="flex items-center justify-center min-h-screen">
          <Loader2 className="h-8 w-8 animate-spin text-emerald-500" />
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <div className="bg-gradient-to-b from-emerald-950 via-green-950 to-black min-h-screen">
        <div className="px-4 pt-6 pb-4">
          <Link to="/games" className="flex items-center gap-1 text-sm text-white/70 mb-4">
            <ArrowLeft className="h-4 w-4" /> Jiyan Games
          </Link>

          <div className="text-center mb-4">
            <h1 className="text-2xl font-extrabold text-white tracking-tight flex items-center justify-center gap-2">
              <Type className="h-6 w-6 text-emerald-400" /> Kürtçe Wordle
            </h1>
            <p className="text-xs text-white/70 mt-1">Günlük Kurmancî · 6 deneme</p>
          </div>

          {/* Grid */}
          <div className="space-y-1.5 mb-4">
            {Array.from({ length: MAX_GUESSES }).map((_, rowIdx) => {
              const word = guesses[rowIdx] || (rowIdx === guesses.length ? current.padEnd(WORD_LENGTH) : "".padEnd(WORD_LENGTH));
              const isSubmitted = rowIdx < guesses.length;
              return (
                <div key={rowIdx} className="flex gap-1.5 justify-center">
                  {Array.from({ length: WORD_LENGTH }).map((_, colIdx) => {
                    const letter = word[colIdx]?.trim() || "";
                    const state: LetterState = isSubmitted && letter ? evalLetter(letter, colIdx, guesses[rowIdx]) : "empty";
                    return (
                      <div
                        key={colIdx}
                        className={`h-12 w-12 rounded-lg border-2 ${stateColor(state)} flex items-center justify-center font-bold text-lg uppercase`}
                      >
                        {letter}
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>

          {status === "won" && (
            <div className="rounded-xl bg-green-600/20 border border-green-500/40 p-3 mb-3 text-center">
              <p className="text-sm font-bold text-green-300">🎉 Doğru: {target}</p>
              {meaning && <p className="text-xs text-white/70 mt-1">Anlamı: {meaning}</p>}
            </div>
          )}
          {status === "lost" && (
            <div className="rounded-xl bg-red-600/20 border border-red-500/40 p-3 mb-3 text-center">
              <p className="text-sm font-bold text-red-300">Doğru cevap: {target}</p>
              {meaning && <p className="text-xs text-white/70 mt-1">Anlamı: {meaning}</p>}
            </div>
          )}

          {/* Keyboard */}
          {status === "playing" && (
            <div className="space-y-1.5">
              {KEYS.map((row, ri) => (
                <div key={ri} className="flex gap-1 justify-center">
                  {row.map((k) => (
                    <button
                      key={k}
                      onClick={() => pressKey(k)}
                      className={`${k.length > 1 ? "px-3 text-[10px]" : "w-8"} h-11 rounded-md bg-white/10 hover:bg-white/20 border border-white/10 text-white font-bold uppercase active:scale-95 transition`}
                    >
                      {k === "DEL" ? "⌫" : k}
                    </button>
                  ))}
                </div>
              ))}
            </div>
          )}

          {status !== "playing" && (
            <Link to="/games">
              <Button className="w-full mt-3 bg-emerald-600 hover:bg-emerald-700">Hub'a Dön</Button>
            </Link>
          )}
        </div>
      </div>
    </AppShell>
  );
}

