/**
 * /gorunum — High-end 'Görünüm' (Theme) mini-app.
 *
 * Features:
 *  • 3D rotating carousel preview of all four Sovereign themes
 *      (Sovereign Obsidian / Royal Gold 3D / Sovereign Glass / Stellar Symbol)
 *  • Liquid-morph ripple transition when a new theme is committed
 *  • Gyroscope-driven parallax tilt on the active preview card
 *  • Customisation sliders: Icon Size · Surface Transparency ·
 *      Gold Intensity · Background Depth
 *
 * The carousel uses CSS `transform-style: preserve-3d` and a slow
 * Y-axis rotation; tilting the device adds a small Rx/Ry layer so
 * highlights move across the gold surfaces as the phone moves.
 */
import { createFileRoute, Link } from "@tanstack/react-router";
import { useEffect, useRef, useState } from "react";
import {
  ChevronLeft,
  Check,
  Sparkles,
  Layers,
  Star,
  Hexagon,
  Sliders,
  RotateCw,
  PaintBucket,
} from "lucide-react";
import { Slider } from "@/components/ui/slider";
import { useHubTheme } from "@/hooks/useHubTheme";
import { useHubPreferences } from "@/hooks/useHubPreferences";
import {
  HUB_THEMES,
  HUB_THEME_ORDER,
  HUB_PRESETS,
  type HubPreset,
  type HubThemeId,
  type HubThemeTokens,
} from "@/lib/hubTheme";
import { hapticTap } from "@/lib/native";
import { Zap } from "lucide-react";

export const Route = createFileRoute("/gorunum")({
  component: GorunumPage,
  head: () => ({
    meta: [
      { title: "Görünüm — Sovereign OS" },
      {
        name: "description",
        content:
          "Dört premium 3D temayı önizle, Altın Yoğunluğu ve Arka Plan Derinliğini ayarla.",
      },
    ],
  }),
});

function GorunumPage() {
  const { theme, themeId, setThemeId } = useHubTheme();
  const {
    prefs,
    setIconScale,
    setTileTransparency,
    setGoldIntensity,
    setBackgroundDepth,
  } = useHubPreferences();

  const [activeIdx, setActiveIdx] = useState<number>(() =>
    Math.max(0, HUB_THEME_ORDER.indexOf(themeId)),
  );
  const [morph, setMorph] = useState<{
    key: number;
    x: number;
    y: number;
    color: string;
  } | null>(null);

  // Keep carousel in sync if theme is changed elsewhere.
  useEffect(() => {
    const idx = HUB_THEME_ORDER.indexOf(themeId);
    if (idx >= 0 && idx !== activeIdx) setActiveIdx(idx);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [themeId]);

  const commit = (id: HubThemeId, originX = window.innerWidth / 2, originY = 220) => {
    if (id === themeId) return;
    const t = HUB_THEMES[id as keyof typeof HUB_THEMES];
    hapticTap();
    setMorph({ key: Date.now(), x: originX, y: originY, color: t.accent });
    setThemeId(id);
    setTimeout(() => setMorph(null), 900);
  };

  const applyPreset = (
    preset: HubPreset,
    originX = window.innerWidth / 2,
    originY = 180,
  ) => {
    const t = HUB_THEMES[preset.themeId as keyof typeof HUB_THEMES];
    hapticTap();
    setMorph({ key: Date.now(), x: originX, y: originY, color: t.accent });
    if (preset.themeId !== themeId) setThemeId(preset.themeId);
    setIconScale(preset.iconScale);
    setTileTransparency(preset.tileTransparency);
    setGoldIntensity(preset.goldIntensity);
    setBackgroundDepth(preset.backgroundDepth);
    setTimeout(() => setMorph(null), 900);
  };

  const activePresetId = HUB_PRESETS.find(
    (p) =>
      p.themeId === themeId &&
      Math.abs(p.iconScale - prefs.iconScale) < 0.03 &&
      Math.abs(p.tileTransparency - prefs.tileTransparency) < 0.03 &&
      Math.abs(p.goldIntensity - prefs.goldIntensity) < 0.03 &&
      Math.abs(p.backgroundDepth - prefs.backgroundDepth) < 0.03,
  )?.id;

  return (
    <div
      className="relative min-h-screen w-full overflow-x-hidden"
      style={{ background: theme.pageBg, color: theme.textPrimary }}
    >
      {/* Liquid-morph wash on theme change */}
      {morph && (
        <div
          key={morph.key}
          aria-hidden
          className="pointer-events-none fixed inset-0 z-50 animate-hub-liquid-morph"
          style={
            {
              background: `radial-gradient(circle at ${morph.x}px ${morph.y}px, ${morph.color} 0%, ${morph.color}55 30%, transparent 70%)`,
              "--lm-x": `${morph.x}px`,
              "--lm-y": `${morph.y}px`,
              mixBlendMode: "screen",
            } as React.CSSProperties
          }
        />
      )}

      <header className="sticky top-0 z-10 flex items-center gap-2 px-4 pt-4 pb-3 backdrop-blur-md"
        style={{ background: "linear-gradient(180deg, rgba(0,0,0,0.55), transparent)" }}>
        <Link
          to="/"
          onClick={() => hapticTap()}
          className="h-9 w-9 flex items-center justify-center rounded-full active:scale-95"
          style={{ background: theme.surfaceBg, border: theme.border }}
          aria-label="Hub'a dön"
        >
          <ChevronLeft className="h-4 w-4" style={{ color: theme.iconColor }} />
        </Link>
        <div className="flex-1 min-w-0">
          <div
            className="text-[10px] uppercase tracking-[0.22em]"
            style={{ color: theme.textMuted }}
          >
            Sovereign OS · Theme Studio
          </div>
          <h1
            className="text-lg font-semibold tracking-tight truncate"
            style={{ color: theme.textPrimary }}
          >
            Görünüm
          </h1>
        </div>
        <Sparkles className="h-4 w-4" style={{ color: theme.accent }} />
      </header>

      <main className="px-5 pb-24 space-y-7 pt-2">
        {/* ─── 3D Carousel preview ──────────────────────────────────── */}
        <section>
          <SectionLabel theme={theme} icon={<RotateCw className="h-3 w-3" />}>
            3D Tema Önizlemesi
          </SectionLabel>
          <ThemeCarousel
            activeIdx={activeIdx}
            onIndexChange={setActiveIdx}
            onCommit={(id, e) => {
              const rect =
                e?.currentTarget instanceof HTMLElement
                  ? e.currentTarget.getBoundingClientRect()
                  : null;
              const x = rect ? rect.left + rect.width / 2 : window.innerWidth / 2;
              const y = rect ? rect.top + rect.height / 2 : 240;
              commit(id, x, y);
            }}
            currentId={themeId}
          />
        </section>

        {/* ─── One-tap presets ──────────────────────────────────────── */}
        <section>
          <SectionLabel theme={theme} icon={<Zap className="h-3 w-3" />}>
            Tek dokunuşla
          </SectionLabel>
          <div
            className="flex gap-2.5 overflow-x-auto pb-1 -mx-1 px-1 scrollbar-hide snap-x snap-mandatory"
            data-testid="hub-presets"
          >
            {HUB_PRESETS.map((preset) => (
              <PresetChip
                key={preset.id}
                preset={preset}
                active={activePresetId === preset.id}
                onPick={(e: React.MouseEvent) => applyPreset(preset, e?.clientX, e?.clientY)}
              />
            ))}
          </div>
        </section>

        {/* ─── Theme grid (quick pick) ──────────────────────────────── */}
        <section>
          <SectionLabel theme={theme} icon={<PaintBucket className="h-3 w-3" />}>
            Tema
          </SectionLabel>
          <div className="grid grid-cols-2 gap-3">
            {HUB_THEME_ORDER.map((id) => (
              <ThemeChip
                key={id}
                id={id}
                active={themeId === id}
                onPick={(e) => commit(id, e?.clientX, e?.clientY)}
              />
            ))}
          </div>
        </section>

        {/* ─── Customisation sliders ────────────────────────────────── */}
        <section
          className="rounded-3xl p-5 space-y-5"
          style={{
            background: theme.surfaceBgStrong,
            border: theme.border,
            boxShadow: theme.heroShadow,
            backdropFilter: "blur(18px)",
            WebkitBackdropFilter: "blur(18px)",
          }}
        >
          <div className="flex items-center gap-2">
            <Sliders className="h-4 w-4" style={{ color: theme.accent }} />
            <h2
              className="text-sm font-semibold tracking-tight"
              style={{ color: theme.textPrimary }}
            >
              Özelleştirme
            </h2>
          </div>

          <SliderRow
            theme={theme}
            title="İkon boyutu"
            value={`${Math.round(prefs.iconScale * 100)}%`}
            min={0.85}
            max={1.25}
            step={0.05}
            current={prefs.iconScale}
            onChange={setIconScale}
          />
          <SliderRow
            theme={theme}
            title="Yüzey şeffaflığı"
            value={`${Math.round(prefs.tileTransparency * 100)}%`}
            min={0.4}
            max={1}
            step={0.05}
            current={prefs.tileTransparency}
            onChange={setTileTransparency}
          />
          <SliderRow
            theme={theme}
            title="Altın yoğunluğu"
            value={`${Math.round(prefs.goldIntensity * 100)}%`}
            min={0.4}
            max={1.4}
            step={0.05}
            current={prefs.goldIntensity}
            onChange={setGoldIntensity}
          />
          <SliderRow
            theme={theme}
            title="Arka plan derinliği"
            value={`${Math.round(prefs.backgroundDepth * 100)}%`}
            min={0}
            max={1}
            step={0.05}
            current={prefs.backgroundDepth}
            onChange={setBackgroundDepth}
          />
        </section>

        <p
          className="text-center text-[11px] tracking-wide"
          style={{ color: theme.textFaint }}
        >
          Telefonu eğin · ışık altın yüzeylerde gezinir
        </p>
      </main>
    </div>
  );
}

// ────────────────────────────────────────────────────────────────────
// Section helpers
// ────────────────────────────────────────────────────────────────────
function SectionLabel({
  children,
  theme,
  icon,
}: {
  children: React.ReactNode;
  theme: HubThemeTokens;
  icon?: React.ReactNode;
}) {
  return (
    <div
      className="flex items-center gap-1.5 text-[10px] uppercase tracking-[0.24em] mb-3 px-1"
      style={{ color: theme.textMuted }}
    >
      {icon}
      {children}
    </div>
  );
}

function SliderRow({
  theme,
  title,
  value,
  min,
  max,
  step,
  current,
  onChange,
}: {
  theme: HubThemeTokens;
  title: string;
  value: string;
  min: number;
  max: number;
  step: number;
  current: number;
  onChange: (v: number) => void;
}) {
  return (
    <div>
      <div className="flex items-center justify-between">
        <div
          className="text-sm font-medium"
          style={{ color: theme.textPrimary }}
        >
          {title}
        </div>
        <div
          className="text-xs tabular-nums"
          style={{ color: theme.textMuted }}
        >
          {value}
        </div>
      </div>
      <Slider
        value={[current]}
        min={min}
        max={max}
        step={step}
        onValueChange={(v) => onChange(v[0])}
        className="mt-2.5"
      />
    </div>
  );
}

// ────────────────────────────────────────────────────────────────────
// 3D Carousel — rotating gold cards with gyroscope parallax
// ────────────────────────────────────────────────────────────────────
interface CarouselProps {
  activeIdx: number;
  onIndexChange: (i: number) => void;
  onCommit: (id: HubThemeId, e?: React.MouseEvent | React.TouchEvent) => void;
  currentId: HubThemeId;
}

function ThemeCarousel({
  activeIdx,
  onIndexChange,
  onCommit,
  currentId,
}: CarouselProps) {
  const tiltRef = useRef({ rx: 0, ry: 0 });
  const [tilt, setTilt] = useState({ rx: 0, ry: 0 });

  // Gyroscope-driven parallax
  useEffect(() => {
    if (typeof window === "undefined") return;
    if (!("DeviceOrientationEvent" in window)) return;
    const onOrient = (e: DeviceOrientationEvent) => {
      const beta = (e.beta ?? 0) - 35; // 35° resting tilt
      const gamma = e.gamma ?? 0;
      const ry = Math.max(-12, Math.min(12, gamma * 0.18));
      const rx = Math.max(-10, Math.min(10, -beta * 0.12));
      tiltRef.current = { rx, ry };
      setTilt({ rx, ry });
    };
    window.addEventListener("deviceorientation", onOrient, true);
    return () =>
      window.removeEventListener("deviceorientation", onOrient, true);
  }, []);

  // Touch / drag swipe to advance
  const startXRef = useRef<number | null>(null);
  const onTouchStart = (e: React.TouchEvent) => {
    startXRef.current = e.touches[0]?.clientX ?? null;
  };
  const onTouchEnd = (e: React.TouchEvent) => {
    if (startXRef.current == null) return;
    const dx = (e.changedTouches[0]?.clientX ?? 0) - startXRef.current;
    startXRef.current = null;
    if (Math.abs(dx) < 35) return;
    const dir = dx < 0 ? 1 : -1;
    const next = (activeIdx + dir + HUB_THEME_ORDER.length) % HUB_THEME_ORDER.length;
    hapticTap();
    onIndexChange(next);
  };

  return (
    <div
      className="relative h-[300px] select-none"
      onTouchStart={onTouchStart}
      onTouchEnd={onTouchEnd}
      style={{ perspective: "1200px" }}
    >
      <div
        className="relative h-full w-full"
        style={{
          transformStyle: "preserve-3d",
          transition: "transform 600ms cubic-bezier(0.22, 1, 0.36, 1)",
          transform: `translateZ(-260px) rotateY(${
            -activeIdx * (360 / HUB_THEME_ORDER.length)
          }deg) rotateX(${tilt.rx}deg)`,
        }}
      >
        {HUB_THEME_ORDER.map((id, i) => {
          const angle = i * (360 / HUB_THEME_ORDER.length);
          const isActive = i === activeIdx;
          return (
            <div
              key={id}
              className="absolute inset-0 mx-auto"
              style={{
                width: 220,
                left: "50%",
                marginLeft: -110,
                transform: `rotateY(${angle}deg) translateZ(260px) rotateY(${tilt.ry * 0.4}deg)`,
                transformStyle: "preserve-3d",
                opacity: isActive ? 1 : 0.55,
                transition: "opacity 400ms",
              }}
            >
              <ThemePreviewCard
                themeId={id}
                isCurrent={currentId === id}
                isActive={isActive}
                onTap={(e) => {
                  if (!isActive) {
                    onIndexChange(i);
                    return;
                  }
                  onCommit(id, e);
                }}
              />
            </div>
          );
        })}
      </div>

      {/* Dot indicator */}
      <div className="absolute bottom-0 left-0 right-0 flex justify-center gap-1.5">
        {HUB_THEME_ORDER.map((_, i) => (
          <span
            key={i}
            className="h-1.5 rounded-full transition-all"
            style={{
              width: i === activeIdx ? 22 : 6,
              background:
                i === activeIdx
                  ? "linear-gradient(90deg, #FFE9A8, #D4AF37)"
                  : "rgba(212,175,55,0.35)",
            }}
          />
        ))}
      </div>
    </div>
  );
}

function ThemePreviewCard({
  themeId,
  isCurrent,
  isActive,
  onTap,
}: {
  themeId: HubThemeId;
  isCurrent: boolean;
  isActive: boolean;
  onTap: (e: React.MouseEvent) => void;
}) {
  const t = HUB_THEMES[themeId as keyof typeof HUB_THEMES];
  const Icon = themeIcon(themeId);
  return (
    <button
      type="button"
      onClick={onTap}
      data-testid={`theme-preview-${themeId}`}
      className="relative h-[280px] w-full rounded-[28px] overflow-hidden text-left active:scale-[0.97] transition-transform"
      style={{
        background: t.pageBg,
        border: isCurrent ? "1.5px solid rgba(255,236,180,0.95)" : t.borderStrong,
        boxShadow: isActive ? t.heroShadow : t.tileShadow,
      }}
    >
      {/* Atmosphere layer */}
      <PreviewAtmosphere theme={t} />

      {/* Top-left brand */}
      <div className="absolute top-3 left-3 flex items-center gap-1.5">
        <Icon className="h-3.5 w-3.5" style={{ color: t.accent }} />
        <span
          className="text-[10px] uppercase tracking-[0.18em] font-semibold"
          style={{ color: t.textPrimary, textShadow: "0 1px 2px rgba(0,0,0,0.7)" }}
        >
          Sovereign
        </span>
      </div>

      {/* Mock 4×4 of squircle icons */}
      <div className="absolute inset-x-4 top-12 grid grid-cols-4 gap-2">
        {Array.from({ length: 8 }).map((_, i) => (
          <span
            key={i}
            className="h-7 w-7 rounded-[10px]"
            style={{
              background: t.iconTileGradient,
              border: t.border,
              boxShadow: t.tileShadow,
            }}
          />
        ))}
      </div>

      {/* Mock widget */}
      <div
        className="absolute left-4 right-4 bottom-12 rounded-2xl p-2.5"
        style={{
          background: t.surfaceBg,
          border: t.border,
          backdropFilter: "blur(10px)",
          WebkitBackdropFilter: "blur(10px)",
        }}
      >
        <div
          className="text-[9px] uppercase tracking-[0.18em]"
          style={{ color: t.textFaint }}
        >
          Hazine
        </div>
        <div
          className="text-base font-semibold tabular-nums"
          style={{ color: t.textPrimary }}
        >
          ₶ 12.480
        </div>
      </div>

      {/* Footer label */}
      <div className="absolute bottom-2 left-3 right-3 flex items-center justify-between">
        <span
          className="text-[12px] font-semibold"
          style={{
            color: t.textPrimary,
            textShadow: "0 1px 2px rgba(0,0,0,0.85)",
          }}
        >
          {t.label}
        </span>
        {isCurrent && (
          <span
            className="h-5 w-5 rounded-full flex items-center justify-center"
            style={{ background: t.pillBg }}
          >
            <Check className="h-3 w-3" style={{ color: t.pillText }} />
          </span>
        )}
      </div>

      {/* Active gloss highlight (top-down) */}
      {isActive && (
        <span
          aria-hidden
          className="pointer-events-none absolute inset-x-0 top-0 h-1/3 rounded-t-[28px]"
          style={{
            background:
              "linear-gradient(180deg, rgba(255,255,255,0.16), transparent)",
          }}
        />
      )}
    </button>
  );
}

function themeIcon(id: HubThemeId) {
  switch (id) {
    case "sovereign-obsidian":
      return Hexagon;
    case "royal-gold-3d":
      return Sparkles;
    case "sovereign-glass":
      return Layers;
    case "stellar-symbol":
      return Star;
    default:
      return Hexagon;
  }
}

/**
 * Per-theme atmosphere layer used inside the carousel preview.
 * Mirrors `theme.atmosphere` so each card actually feels different.
 */
function PreviewAtmosphere({ theme }: { theme: HubThemeTokens }) {
  if (theme.atmosphere === "particles") {
    return (
      <div aria-hidden className="pointer-events-none absolute inset-0">
        <span
          className="absolute"
          style={{
            inset: "-30%",
            background: theme.nebula1,
            filter: "blur(24px)",
          }}
        />
        {Array.from({ length: 14 }).map((_, i) => (
          <span
            key={i}
            className="absolute rounded-full"
            style={{
              width: 2 + Math.random() * 3,
              height: 2 + Math.random() * 3,
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
              background: theme.particle,
              opacity: 0.65 + Math.random() * 0.3,
            }}
          />
        ))}
      </div>
    );
  }
  if (theme.atmosphere === "frost") {
    return (
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "radial-gradient(120% 90% at 50% 0%, rgba(255,255,255,0.10), transparent 60%)",
          backdropFilter: "blur(8px)",
          WebkitBackdropFilter: "blur(8px)",
        }}
      />
    );
  }
  if (theme.atmosphere === "stellar") {
    return (
      <div aria-hidden className="pointer-events-none absolute inset-0 overflow-hidden">
        <span
          className="absolute"
          style={{
            inset: "-20%",
            background: theme.nebula1,
            filter: "blur(28px)",
          }}
        />
        {/* 21-ray star core */}
        <svg
          aria-hidden
          viewBox="-50 -50 100 100"
          className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2"
          style={{
            width: 180,
            height: 180,
            opacity: 0.55,
            animation: "hub-star-pulse 6s ease-in-out infinite",
          }}
        >
          {Array.from({ length: 21 }).map((_, i) => {
            const a = (i / 21) * Math.PI * 2;
            return (
              <line
                key={i}
                x1={0}
                y1={0}
                x2={Math.cos(a) * 44}
                y2={Math.sin(a) * 44}
                stroke="url(#starGold)"
                strokeWidth={1.4}
                strokeLinecap="round"
              />
            );
          })}
          <defs>
            <linearGradient id="starGold" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="#FFE9A8" />
              <stop offset="100%" stopColor="#D4AF37" />
            </linearGradient>
          </defs>
        </svg>
      </div>
    );
  }
  // Default — sovereign-obsidian: soft gold halo only
  return (
    <div aria-hidden className="pointer-events-none absolute inset-0">
      <span
        className="absolute"
        style={{
          inset: "-25%",
          background: theme.nebula1,
          filter: "blur(34px)",
          opacity: 0.9,
        }}
      />
    </div>
  );
}

// ────────────────────────────────────────────────────────────────────
// Quick-pick chip for the bottom theme grid
// ────────────────────────────────────────────────────────────────────
function ThemeChip({
  id,
  active,
  onPick,
}: {
  id: HubThemeId;
  active: boolean;
  onPick: (e: React.MouseEvent) => void;
}) {
  const t = HUB_THEMES[id as keyof typeof HUB_THEMES];
  const Icon = themeIcon(id);
  return (
    <button
      type="button"
      onClick={onPick}
      data-testid={`theme-chip-${id}`}
      className="relative aspect-[5/3] rounded-2xl overflow-hidden p-3 text-left active:scale-[0.97] transition-transform"
      style={{
        background: t.pageBg,
        border: active
          ? "1.5px solid rgba(255,236,180,0.9)"
          : t.border,
        boxShadow: active ? t.heroShadow : t.tileShadow,
      }}
    >
      <PreviewAtmosphere theme={t} />
      <div className="relative flex flex-col gap-1.5">
        <Icon className="h-4 w-4" style={{ color: t.accent }} />
        <div
          className="text-[12px] font-semibold leading-tight"
          style={{ color: t.textPrimary, textShadow: "0 1px 2px rgba(0,0,0,0.7)" }}
        >
          {t.label}
        </div>
        <div
          className="text-[10px] leading-tight"
          style={{ color: t.textMuted }}
        >
          {t.tagline}
        </div>
      </div>
      {active && (
        <span
          className="absolute top-2 right-2 h-5 w-5 rounded-full flex items-center justify-center"
          style={{ background: t.pillBg }}
        >
          <Check className="h-3 w-3" style={{ color: t.pillText }} />
        </span>
      )}
    </button>
  );
}

// ────────────────────────────────────────────────────────────────────
// One-tap preset chip — luxury gold pill with active checkmark
// ────────────────────────────────────────────────────────────────────
function PresetChip({
  preset,
  active,
  onPick,
}: {
  preset: HubPreset;
  active: boolean;
  onPick: (e: React.MouseEvent) => void;
}) {
  const t = HUB_THEMES[preset.themeId as keyof typeof HUB_THEMES];
  return (
    <button
      type="button"
      onClick={onPick}
      data-testid={`hub-preset-${preset.id}`}
      className="relative shrink-0 snap-start rounded-2xl px-4 py-3 text-left active:scale-[0.96] transition-transform min-w-[160px]"
      style={{
        background: active ? t.surfaceBgStrong : t.surfaceBg,
        border: active ? "1.5px solid rgba(255,236,180,0.95)" : t.border,
        boxShadow: active ? t.heroShadow : t.tileShadow,
        backdropFilter: "blur(14px)",
        WebkitBackdropFilter: "blur(14px)",
      }}
    >
      <div className="flex items-center gap-2">
        <span
          aria-hidden
          className="h-2.5 w-2.5 rounded-full"
          style={{
            background: t.pillBg,
            boxShadow: `0 0 8px ${t.accent}`,
          }}
        />
        <span
          className="text-[13px] font-semibold tracking-tight"
          style={{ color: t.textPrimary }}
        >
          {preset.label}
        </span>
        {active && (
          <Check
            className="h-3.5 w-3.5 ml-auto"
            style={{ color: t.accent }}
          />
        )}
      </div>
      <p
        className="mt-1 text-[11px] leading-tight"
        style={{ color: t.textMuted }}
      >
        {preset.tagline}
      </p>
    </button>
  );
}

