        </section>

        {/* AI Chat for this country */}
        <section>
          <h2 className="text-sm font-semibold text-foreground mb-2">🤖 {info.name} AI Asistanı</h2>
          <AsylumAIChat country={info.code} countryName={info.name} />
        </section>
      </div>
    </AppShell>
  );
}

