import { createFileRoute } from "@tanstack/react-router";
import { createClient } from "@supabase/supabase-js";

/**
 * Cron-tetikli endpoint: her ayın 1'inde önceki ayın yaratıcı fonu havuzunu
 * uygunluk eşiğini geçen yaratıcılara dağıtır (10K takipçi & 100K izlenme).
 *
 * pg_cron tarafından `Authorization: Bearer <anon-key>` ile çağrılır.
 */
export const Route = createFileRoute("/hooks/distribute-creator-fund")({
  server: {
    handlers: {
      POST: async ({ request }) => {
        const authHeader = request.headers.get("authorization");
        const token = authHeader?.replace("Bearer ", "");
        if (!token) {
          return new Response(JSON.stringify({ error: "Missing authorization" }), {
            status: 401,
            headers: { "Content-Type": "application/json" },
          });
        }

        const supabase = createClient(
          import.meta.env.VITE_SUPABASE_URL!,
          token,
          { auth: { autoRefreshToken: false, persistSession: false } },
        );

        const { data, error } = await supabase.rpc("distribute_creator_fund" as any);
        if (error) {
          console.error("distribute_creator_fund failed:", error);
          return new Response(
            JSON.stringify({ success: false, error: error.message }),
            { status: 500, headers: { "Content-Type": "application/json" } },
          );
        }

        return new Response(
          JSON.stringify({ success: true, result: data, ranAt: new Date().toISOString() }),
          { headers: { "Content-Type": "application/json" } },
        );
      },
    },
  },
});

