/**
 * /inbox — Sovereign Mail (Gmail-style mini-app)
 *
 * Folders: Inbox / Starred / Sent / Drafts / Sistem / Archived / Trash.
 * Premium "Royal Gold & Obsidian" theme with glassmorphism, swipe-able
 * actions on each row, full-screen detail view with Reply / Star / Archive
 * / Trash, and an auto-saving Compose sheet.
 *
 * The Sovereign code grid stays — tapping it copies the Egemen Kod and
 * routes to the relevant mini-app (Wallet, ID Borsa, etc.).
 */
import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { useMemo, useState } from "react";
import { AppShell } from "@/components/layout/AppShell";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/hooks/useAuth";
import { useMail, type MailFolder, type MailMessage } from "@/hooks/useMail";
import { MailSidebar } from "@/components/mail/MailSidebar";
import { ComposeSheet } from "@/components/mail/ComposeSheet";
import { resolveCodeRoute } from "@/lib/sovereignCodeRouting";
import {
  ArrowLeft,
  ArrowRight,
  Archive,
  ArchiveRestore,
  CheckCheck,
  Copy,
  Mail,
  MailOpen,
  Pencil,
  Reply,
  Search,
  Send as SendIcon,
  Shield,
  ShieldCheck,
  Star,
  StarOff,
  Trash2,
  User,
  X,
} from "lucide-react";
import { toast } from "sonner";

interface InboxSearch {
  compose?: number;
}

export const Route = createFileRoute("/inbox")({
  component: InboxPage,
  validateSearch: (search: Record<string, unknown>): InboxSearch => ({
    compose: search.compose === 1 || search.compose === "1" ? 1 : undefined,
  }),
  head: () => ({
    meta: [
      { title: "Sovereign Mail – Jiyan Europe" },
      { name: "description", content: "Egemen e-posta — gelen kutusu, taslaklar, arşiv, sistem güvenlik bildirimleri." },
    ],
  }),
});

function InboxPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const mail = useMail(user?.id);
  const { compose: composeFlag } = Route.useSearch();

  const [folder, setFolder] = useState<MailFolder>("inbox");
  const [query, setQuery] = useState("");
  const [openId, setOpenId] = useState<string | null>(null);
  const [compose, setCompose] = useState<
    | null
    | {
        id?: string;
        recipient?: string;
        subject?: string;
        body?: string;
      }
  >(composeFlag ? {} : null);

  const list = useMemo(() => {
    if (!user) return [];
    const base = mail.filterFolder(folder);
    if (!query.trim()) return base;
    const q = query.toLowerCase();
    return base.filter(
      (m) =>
        m.subject.toLowerCase().includes(q) ||
        m.body.toLowerCase().includes(q) ||
        (m.reference_code ?? "").toLowerCase().includes(q),
    );
  }, [mail, folder, query, user]);

  const open = openId ? mail.messages.find((m) => m.id === openId) ?? null : null;
  const isOwnSent = !!user && !!open && open.sender_id === user.id;

  if (!user) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center px-4 pt-20 text-center">
          <Mail className="mb-4 h-12 w-12 text-amber-300/70" />
          <h2 className="mb-1.5 text-lg font-semibold text-amber-100">Sovereign Mail · Kurtarma Modu</h2>
          <p className="mb-5 max-w-xs text-[12.5px] leading-relaxed text-amber-200/70">
            Misafir oturumdayken kutuyu görüntülemek mümkün değildir. Şifre kurtarma
            bağlantısı için <Link to="/security" className="underline text-amber-200">Güvenlik Merkezi</Link>'ni kullanın
            veya giriş yapın.
          </p>
          <Button variant="neon" asChild>
            <Link to="/login">Jiyan ID ile Giriş Yap</Link>
          </Button>
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <div className="px-4 pt-5 pb-24">
        {/* Header */}
        <div className="mb-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Link to="/profile" className="text-muted-foreground" aria-label="Geri">
              <ArrowLeft className="h-5 w-5" />
            </Link>
            <h1 className="bg-gradient-to-r from-amber-200 via-yellow-100 to-amber-300 bg-clip-text text-xl font-bold text-transparent">
              Sovereign Mail
            </h1>
            {mail.counts.inboxUnread > 0 && (
              <span className="flex h-5 min-w-5 items-center justify-center rounded-full bg-amber-400 px-1.5 text-[10px] font-extrabold text-black">
                {mail.counts.inboxUnread}
              </span>
            )}
          </div>
          <div className="flex items-center gap-2">
            {folder === "inbox" && mail.counts.inboxUnread > 0 && (
              <button
                onClick={mail.markAllInboxRead}
                className="flex items-center gap-1 text-[11px] text-amber-200/80 hover:text-amber-200"
              >
                <CheckCheck className="h-3.5 w-3.5" /> Tümünü oku
              </button>
            )}
            <Button
              size="sm"
              onClick={() => setCompose({})}
              className="bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-500 font-semibold text-black shadow-[0_2px_14px_rgba(245,200,80,0.4)]"
            >
              <Pencil className="mr-1 h-3.5 w-3.5" /> Yaz
            </Button>
          </div>
        </div>

        {/* Search */}
        <div className="relative mb-3">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Mesajlarda ara..."
            className="h-10 w-full rounded-full border border-amber-400/15 bg-surface/70 pl-10 pr-10 text-sm text-foreground placeholder:text-muted-foreground backdrop-blur focus:border-amber-400/50 focus:outline-none"
          />
          {query && (
            <button
              onClick={() => setQuery("")}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground"
              aria-label="Aramayı temizle"
            >
              <X className="h-4 w-4" />
            </button>
          )}
        </div>

        {/* Folder rail */}
        <MailSidebar
          active={folder}
          onChange={(f) => {
            setFolder(f);
            setOpenId(null);
          }}
          badges={{
            inbox: mail.counts.inboxUnread,
            drafts: mail.counts.drafts,
            starred: mail.counts.starred,
          }}
        />

        {/* List */}
        <div className="mt-2">
          {mail.loading ? (
            <p className="py-12 text-center text-sm text-muted-foreground">Yükleniyor...</p>
          ) : list.length === 0 ? (
            <EmptyState folder={folder} />
          ) : (
            <ul className="space-y-1">
              {list.map((m) => (
                <MailRow
                  key={m.id}
                  m={m}
                  ownId={user.id}
                  folder={folder}
                  onOpen={() => {
                    if (m.is_draft && m.sender_id === user.id) {
                      setCompose({
                        id: m.id,
                        subject: m.subject,
                        body: m.body,
                      });
                      return;
                    }
                    setOpenId(m.id);
                    if (!m.is_read) mail.markAsRead(m.id);
                  }}
                  onStar={() => mail.toggleStar(m)}
                  onArchive={() =>
                    folder === "archived" ? mail.unarchive(m.id) : mail.archive(m.id)
                  }
                  onTrash={() =>
                    folder === "trash" ? mail.deletePermanent(m.id) : mail.trash(m.id)
                  }
                />
              ))}
            </ul>
          )}
        </div>

        {/* Detail overlay */}
        {open && (
          <MailDetail
            m={open}
            isOwnSent={!!isOwnSent}
            onClose={() => setOpenId(null)}
            onStar={() => mail.toggleStar(open)}
            onArchive={() => {
              mail.archive(open.id);
              setOpenId(null);
            }}
            onTrash={() => {
              if (open.is_trashed) mail.deletePermanent(open.id);
              else mail.trash(open.id);
              setOpenId(null);
            }}
            onRestore={() => {
              mail.restoreFromTrash(open.id);
            }}
            onReply={() => {
              setCompose({
                recipient: "", // resolve via UI — sender_id is a uuid, not a handle
                subject: open.subject.startsWith("Re:") ? open.subject : `Re: ${open.subject}`,
                body: `\n\n— ${new Date(open.created_at).toLocaleString()} —\n${open.body}`,
              });
              setOpenId(null);
            }}
            onCodeTap={async (code) => {
              const route = resolveCodeRoute({ subject: open.subject, body: open.body });
              try {
                await navigator.clipboard.writeText(code);
              } catch {
                /* ignore */
              }
              toast.success("Egemen Kod kopyalandı", { description: route.cta });
              navigate({ to: route.to, search: { code, fromInbox: 1 } as any });
            }}
          />
        )}

        {/* Compose */}
        {compose && (
          <ComposeSheet
            initial={compose}
            onClose={() => setCompose(null)}
            onSend={async (r, s, b) => {
              await mail.send(r, s, b);
            }}
            onSaveDraft={(d) => mail.saveDraft(d)}
            onDiscardDraft={(id) => mail.deletePermanent(id)}
          />
        )}
      </div>
    </AppShell>
  );
}

// ---------------------------------------------------------------- subcomponents

function EmptyState({ folder }: { folder: MailFolder }) {
  const map: Record<MailFolder, { title: string; sub: string }> = {
    inbox: { title: "Gelen kutusu temiz", sub: "Yeni mesaj geldiğinde burada görünecek." },
