function MailRow({
  m,
  ownId,
  folder,
  onOpen,
  onStar,
  onArchive,
  onTrash,
}: {
  m: MailMessage;
  ownId: string;
  folder: MailFolder;
  onOpen: () => void;
  onStar: () => void;
  onArchive: () => void;
