      >
        <div
          className={[
            "mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-full",
            m.message_type === "verification"
              ? "bg-gradient-to-br from-amber-400/30 to-amber-600/20 ring-1 ring-amber-400/40"
