          ) : isSystem ? (
            <ShieldCheck className="h-4 w-4 text-amber-300" />
          ) : (
            <User className="h-4 w-4 text-primary" />
          )}
        </div>

        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
