              }`}
            >
              {showSent && "→ "}
              {m.subject || "(Konusuz)"}
              {m.is_draft && (
                <span className="ml-2 text-[10px] uppercase tracking-wider text-amber-300/80">
                  Taslak
                </span>
              )}
            </p>
            {isSystem && (
              <span className="shrink-0 rounded-full bg-gradient-to-r from-amber-400 to-yellow-300 px-1.5 py-0.5 text-[8px] font-extrabold uppercase tracking-wider text-black">
