                {resolveCodeRoute({ subject: m.subject, body: m.body }).cta}
                <ArrowRight className="h-2.5 w-2.5" />
              </span>
            )}
          </div>
        </div>

        {/* Inline action cluster — visible on tap target's right side */}
        <div className="ml-1 flex shrink-0 flex-col items-center gap-2 opacity-50 transition-opacity group-hover:opacity-100">
