          >
            <Trash2 className="h-4 w-4" />
          </button>
        </div>
      </button>
    </li>
  );
}

function MailDetail({
  m,
  isOwnSent,
  onClose,
  onStar,
  onArchive,
  onTrash,
  onRestore,
  onReply,
  onCodeTap,
}: {
  m: MailMessage;
  isOwnSent: boolean;
  onClose: () => void;
  onStar: () => void;
  onArchive: () => void;
  onTrash: () => void;
  onRestore: () => void;
  onReply: () => void;
  onCodeTap: (code: string) => void;
}) {
  const isSystem = m.message_type === "system" || m.message_type === "verification";
  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-background/95 backdrop-blur-xl">
      <div className="flex items-center gap-3 border-b border-amber-400/10 px-4 py-3">
