            {isSystem ? "Jiyan System" : isOwnSent ? "Sen → Alıcı" : "Kullanıcı"} ·{" "}
            {new Date(m.created_at).toLocaleString()}
          </p>
        </div>
        <button onClick={onStar} aria-label="Yıldızla" className="text-amber-300">
          {m.is_starred ? (
            <Star className="h-5 w-5 fill-amber-300" />
          ) : (
            <Star className="h-5 w-5" />
          )}
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4">
        <p className="whitespace-pre-wrap text-sm leading-relaxed text-foreground">{m.body}</p>

        {m.reference_code && (
          <SovereignCodeCard
            code={m.reference_code}
            subject={m.subject}
            body={m.body}
            onTap={() => onCodeTap(m.reference_code!)}
          />
        )}
      </div>

      {/* Action bar */}
      <div className="flex items-center justify-around border-t border-amber-400/10 px-2 py-2">
