import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { HubScreen } from "@/components/hub/HubScreen";
import { DiscoveryApp } from "@/components/discovery/DiscoveryApp";
import { isDengAiHost } from "@/lib/dengaiHost";

export const Route = createFileRoute("/")({
  component: IndexPage,
  head: () => ({
    meta: [
      { title: "Jiyan — Sovereign OS" },
      {
        name: "description",
        content:
          "Stêrka Geş'e dokun, egemen ekosistemi keşfet. Kimlik, posta, sohbet, oyun — tek bir altın yüzeyde.",
      },
    ],
  }),
});

const DISCOVERY_SESSION_KEY = "jiyan_discovery_seen_v1";

/**
 * `/` — Sovereign OS root.
 *
 *  • First visit per session → 3D Discovery Mini-App (interactive intro).
 *  • All subsequent visits → Hub (Guest-First).
 *
 * The Discovery experience marks itself "seen" via sessionStorage on completion
 * or skip; the Hub then takes over for the remainder of the session.
 */
function IndexPage() {
  const { user, loading } = useAuth();
  const navigate = useNavigate();
  const [decided, setDecided] = useState<"discovery" | "hub" | "dengai" | null>(null);

  useEffect(() => {
    if (typeof window === "undefined") {
      setDecided("hub");
      return;
    }
    // Standalone dengai.app portal — boot directly into /chat (Deng AI landing).
    if (isDengAiHost()) {
      setDecided("dengai");
      navigate({ to: "/chat", replace: true });
      return;
    }
    let inIframe = false;
    try {
      inIframe = window.self !== window.top;
    } catch {
      inIframe = true;
    }
    let seen = !!user;
    try {
      seen = seen || !!sessionStorage.getItem(DISCOVERY_SESSION_KEY);
    } catch {
      /* storage blocked → treat as seen so Hub still loads */
      seen = true;
    }
    // Skip Discovery in Lovable preview iframes (developer experience) and
    // on repeat visits in the same session.
    setDecided(inIframe || seen ? "hub" : "discovery");
  }, [user]);

  if (loading || decided === null || decided === "dengai") {
    return (
      <div className="flex min-h-screen items-center justify-center bg-black">
        <div className="h-8 w-8 animate-spin rounded-full border-2 border-amber-300 border-t-transparent" />
      </div>
    );
  }

  if (decided === "discovery") {
    return <DiscoveryApp />;
  }

  return <HubScreen />;
}

