          </div>
          <CreateJobDialog open={open} onOpenChange={setOpen} onCreated={refresh} />
        </div>

        <div className="flex gap-2">
          <Input placeholder="Şehir filtrele" value={city} onChange={(e) => setCity(e.target.value)} className="flex-1" />
          <Select value={cat} onValueChange={setCat}>
            <SelectTrigger className="w-32"><SelectValue /></SelectTrigger>
            <SelectContent>
              {CATEGORIES.map((c) => <SelectItem key={c} value={c}>{c === "all" ? "Tümü" : c}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        {loading && <p className="text-sm text-muted-foreground">Yükleniyor…</p>}
        {!loading && jobs.length === 0 && (
          <div className="rounded-2xl border border-dashed border-border/40 p-8 text-center">
            <p className="text-sm text-muted-foreground">Henüz açık ilan yok. İlk ilanı sen aç!</p>
          </div>
        )}

        <div className="space-y-3">
          {jobs.map((j) => (
            <Link
              key={j.id}
              to="/jobs/$jobId"
              params={{ jobId: j.id }}
              className="block rounded-2xl border border-border/20 bg-surface/40 p-4 backdrop-blur-md transition-all hover:border-neon/30 active:scale-[0.99]"
            >
              <div className="flex items-start justify-between gap-2 mb-2">
                <h3 className="text-sm font-semibold text-foreground line-clamp-1">{j.title}</h3>
                {j.urgency === "urgent" && (
                  <span className="text-[10px] px-2 py-0.5 rounded-full bg-destructive/20 text-destructive border border-destructive/30">ACİL</span>
                )}
              </div>
              <p className="text-xs text-muted-foreground line-clamp-2 mb-2">{j.description}</p>
              <div className="flex items-center gap-3 text-[11px] text-muted-foreground">
                <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{j.city}</span>
                <span className="flex items-center gap-1 capitalize">{j.category}</span>
                {j.budget && <span className="flex items-center gap-1 text-neon font-medium"><Coins className="h-3 w-3" />{j.budget} DC</span>}
                <span className="flex items-center gap-1 ml-auto"><Clock className="h-3 w-3" />{new Date(j.created_at).toLocaleDateString("tr-TR")}</span>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </AppShell>
  );
}

function CreateJobDialog({ open, onOpenChange, onCreated }: { open: boolean; onOpenChange: (o: boolean) => void; onCreated: () => void }) {
  const [form, setForm] = useState({ title: "", description: "", category: "general", city: "Arnhem", budget: "", urgency: "normal" });
  const [loading, setLoading] = useState(false);

  const submit = async () => {
    if (!form.title || !form.description) return;
    setLoading(true);
    const res = await createJobRequest({
      title: form.title,
      description: form.description,
      category: form.category,
      city: form.city,
      budget: form.budget ? Number(form.budget) : undefined,
      urgency: form.urgency,
    });
    setLoading(false);
    if (res) {
      onCreated();
      onOpenChange(false);
      setForm({ title: "", description: "", category: "general", city: "Arnhem", budget: "", urgency: "normal" });
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogTrigger asChild>
        <Button variant="neon" size="sm"><Plus className="h-4 w-4" />İlan Aç</Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Yeni İş İlanı</DialogTitle>
          <DialogDescription>Sağlayıcılar teklif verecek, en uygunu seçeceksiniz.</DialogDescription>
        </DialogHeader>
        <div className="space-y-3">
          <Input placeholder="Başlık (örn: Salon boyama)" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} />
          <Textarea placeholder="Detaylı açıklama" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} rows={4} />
          <div className="grid grid-cols-2 gap-2">
            <Select value={form.category} onValueChange={(v) => setForm({ ...form, category: v })}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {CATEGORIES.filter(c => c !== "all").map((c) => <SelectItem key={c} value={c}>{c}</SelectItem>)}
              </SelectContent>
            </Select>
            <Input placeholder="Şehir" value={form.city} onChange={(e) => setForm({ ...form, city: e.target.value })} />
          </div>
          <div className="grid grid-cols-2 gap-2">
            <Input type="number" placeholder="Bütçe (DC)" value={form.budget} onChange={(e) => setForm({ ...form, budget: e.target.value })} />
            <Select value={form.urgency} onValueChange={(v) => setForm({ ...form, urgency: v })}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="normal">Normal</SelectItem>
                <SelectItem value="urgent">Acil</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
        <DialogFooter>
          <Button variant="neon" disabled={loading} onClick={submit}>Yayınla</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

