/**
 * /joogle — Web3 Sovereign Browser Mini-App.
 *
 * In-app browsing experience: opens external web pages inside a sandboxed
 * iframe inside the Hub instead of redirecting the user away. Users can
 * type a URL or DuckDuckGo query, navigate back/forward/refresh, and
 * bookmark pages locally (web3-style sovereign browsing — no tracking).
 *
 * Note: many sites (Google, banks, X, Instagram) refuse iframe embedding
 * via X-Frame-Options / CSP headers. When detected, we surface a friendly
 * "Bu site iframe içinde açılamıyor" notice with an option to copy the
 * link. This is by design — Joogle never silently redirects out of the app.
 */
import { useEffect, useRef, useState } from "react";
import { createFileRoute } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import {
  ArrowLeft,
  ArrowRight,
  RotateCw,
  Home,
  Star,
  Search,
  Shield,
  X,
  Globe,
  Sparkles,
  ExternalLink,
  Loader2,
} from "lucide-react";
import { hapticTap } from "@/lib/native";
import { useJoogleSearch, type JoogleSource } from "@/hooks/useJoogleSearch";

export const Route = createFileRoute("/joogle")({
  component: JooglePage,
  head: () => ({
    meta: [
      { title: "Joogle — Web3 Sovereign Browser" },
      {
        name: "description",
        content:
          "Web3 sovereign browser. Tüm web siteleri tek dokunuşla Jiyan Hub içinde açılır — yönlendirme yok, takip yok.",
      },
    ],
  }),
});

const HOME_URL = "about:home";
const SOVEREIGN_URL = "about:joogle"; // sovereign search results view
const BOOKMARK_KEY = "joogle_bookmarks_v1";

interface Bookmark {
  url: string;
  title: string;
}

const QUICK_LINKS: Array<{ url: string; title: string; sovereign?: boolean; query?: string }> = [
  { url: "sovereign:wikipedia", title: "Wikipedia", sovereign: true, query: "site:wikipedia.org" },
  { url: "sovereign:duckduckgo", title: "DuckDuckGo", sovereign: true, query: "" },
  { url: "sovereign:jiyan", title: "Jiyan.world", sovereign: true, query: "site:jiyan.world OR site:rudaw.net OR site:anfkurdi.com" },
  { url: "https://etherscan.io", title: "Etherscan" },
  { url: "https://opensea.io", title: "OpenSea" },
  { url: "https://app.uniswap.org", title: "Uniswap" },
];

/** Returns "url" for direct iframe nav, "query" for sovereign search, "home" for home. */
function classifyInput(input: string): { kind: "url" | "query" | "home"; value: string } {
  const v = input.trim();
  if (!v) return { kind: "home", value: HOME_URL };
  if (v === HOME_URL) return { kind: "home", value: HOME_URL };
  if (/^https?:\/\//i.test(v)) return { kind: "url", value: v };
  // bare domain (example.com, sub.example.co.uk) — no spaces
  if (!v.includes(" ") && /^[\w-]+(\.[\w-]+)+(\/.*)?$/.test(v)) {
    return { kind: "url", value: `https://${v}` };
  }
  // anything else → sovereign search
  return { kind: "query", value: v };
}

function JooglePage() {
  const [history, setHistory] = useState<string[]>([HOME_URL]);
  const [cursor, setCursor] = useState(0);
  const [omnibox, setOmnibox] = useState("");
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [loadError, setLoadError] = useState(false);
  const [loading, setLoading] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement | null>(null);
  const joogle = useJoogleSearch();

  const url = history[cursor];
  const isHome = url === HOME_URL;
  const isSovereign = url === SOVEREIGN_URL;
  const sovereignActive = isSovereign || joogle.loading;

  useEffect(() => {
    try {
      const raw = localStorage.getItem(BOOKMARK_KEY);
      if (raw) setBookmarks(JSON.parse(raw));
    } catch {
      /* ignore */
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem(BOOKMARK_KEY, JSON.stringify(bookmarks));
    } catch {
      /* ignore */
    }
  }, [bookmarks]);

  useEffect(() => {
    if (isHome) setOmnibox("");
    else if (isSovereign) setOmnibox(joogle.result?.query ?? "");
    else setOmnibox(url);
    setLoadError(false);
    if (!isHome && !isSovereign) {
      setLoading(true);
      const t = window.setTimeout(() => {
        if (loading) setLoadError(true);
        setLoading(false);
      }, 6000);
      return () => window.clearTimeout(t);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [url]);

  const pushUrl = (next: string) => {
    if (next === url) return;
    const newHistory = history.slice(0, cursor + 1);
    newHistory.push(next);
    setHistory(newHistory);
    setCursor(newHistory.length - 1);
  };

  const navigate = (rawUrl: string) => {
    const cls = classifyInput(rawUrl);
    hapticTap();
    if (cls.kind === "home") { pushUrl(HOME_URL); return; }
    if (cls.kind === "url") {
      if (cls.value === url) {
        iframeRef.current?.contentWindow?.location.reload();
        return;
      }
      pushUrl(cls.value);
      return;
    }
    // sovereign query
    pushUrl(SOVEREIGN_URL);
    joogle.search(cls.value);
  };

  const goBack = () => {
    if (cursor > 0) {
      setCursor(cursor - 1);
      hapticTap();
    }
  };
  const goForward = () => {
    if (cursor < history.length - 1) {
      setCursor(cursor + 1);
      hapticTap();
    }
  };
  const refresh = () => {
    hapticTap();
    if (isHome) return;
    if (isSovereign) {
      if (joogle.result?.query) joogle.search(joogle.result.query);
      return;
    }
    setLoading(true);
    setLoadError(false);
    iframeRef.current?.contentWindow?.location.reload();
    const u = url;
    setHistory((h) => h.slice(0, cursor).concat([u + "#r" + Date.now()]));
    setCursor(cursor);
  };
  const goHome = () => {
    navigate(HOME_URL);
  };

  const openQuickLink = (q: typeof QUICK_LINKS[number]) => {
    if (q.sovereign) {
      // Use the title as the seed query so users see Joogle act on it
      navigate(q.query && q.query.length > 0 ? `${q.title} ${q.query}` : q.title);
    } else {
      navigate(q.url);
    }
  };

  const toggleBookmark = () => {
    if (isHome) return;
    hapticTap();
    const exists = bookmarks.find((b) => b.url === url);
    if (exists) {
      setBookmarks(bookmarks.filter((b) => b.url !== url));
    } else {
      let title = url;
      try {
        title = new URL(url).hostname;
      } catch {
        /* ignore */
      }
      setBookmarks([{ url, title }, ...bookmarks].slice(0, 24));
    }
  };

  const isBookmarked = !isHome && bookmarks.some((b) => b.url === url);

  return (
    <AppShell>
      <div className="min-h-screen bg-black text-amber-100">
        {/* ── Top: gold-trimmed omnibox ───────────────────────── */}
        <div
          className="sticky top-0 z-30 px-3 pt-3 pb-2 backdrop-blur-xl"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,14,2,0.95), rgba(8,5,0,0.85))",
            borderBottom: "0.5px solid rgba(212,175,55,0.35)",
          }}
        >
          <div className="flex items-center gap-1.5">
            <button
              onClick={goBack}
              disabled={cursor === 0}
              className="h-9 w-9 rounded-full grid place-items-center disabled:opacity-30 active:scale-95 transition"
              style={{ background: "rgba(212,175,55,0.08)" }}
              aria-label="Geri"
            >
              <ArrowLeft className="h-4 w-4 text-amber-300" />
            </button>
            <button
              onClick={goForward}
              disabled={cursor >= history.length - 1}
              className="h-9 w-9 rounded-full grid place-items-center disabled:opacity-30 active:scale-95 transition"
              style={{ background: "rgba(212,175,55,0.08)" }}
              aria-label="İleri"
            >
              <ArrowRight className="h-4 w-4 text-amber-300" />
            </button>

            <form
              onSubmit={(e) => {
                e.preventDefault();
                navigate(omnibox);
              }}
              className="flex-1 flex items-center rounded-full px-3 py-1.5 transition-shadow"
              style={{
                background: sovereignActive
                  ? "rgba(250,204,21,0.14)"
                  : "rgba(212,175,55,0.1)",
                border: sovereignActive
                  ? "0.5px solid rgba(250,204,21,0.75)"
                  : "0.5px solid rgba(212,175,55,0.45)",
                boxShadow: sovereignActive
                  ? "inset 0 1px 0 rgba(255,234,170,0.25), 0 0 0 2px rgba(250,204,21,0.18), 0 0 22px rgba(250,204,21,0.45)"
                  : "inset 0 1px 0 rgba(255,234,170,0.15)",
              }}
            >
              {sovereignActive ? (
                <span
                  className="mr-1.5 text-[10px] font-bold tracking-widest"
                  style={{ color: "#facc15", textShadow: "0 0 8px rgba(250,204,21,0.7)" }}
                  aria-label="Sovereign 777"
                >
                  777
                </span>
              ) : (
                <Shield className="h-3.5 w-3.5 mr-1.5 text-amber-400/70" />
              )}
              <input
                value={omnibox}
                onChange={(e) => setOmnibox(e.target.value)}
                placeholder={sovereignActive ? "Joogle dipirse…" : "Ara veya URL gir…"}
                className="flex-1 bg-transparent text-sm outline-none text-amber-100 placeholder:text-amber-100/40"
                inputMode="search"
                autoCapitalize="off"
                autoCorrect="off"
                spellCheck={false}
              />
              {omnibox && (
                <button
                  type="button"
                  onClick={() => setOmnibox("")}
                  className="ml-1 p-0.5 opacity-60"
                  aria-label="Temizle"
                >
                  <X className="h-3.5 w-3.5" />
                </button>
              )}
            </form>

            <button
              onClick={refresh}
              className="h-9 w-9 rounded-full grid place-items-center active:scale-95 transition"
              style={{ background: "rgba(212,175,55,0.08)" }}
              aria-label="Yenile"
            >
              <RotateCw
                className={`h-4 w-4 text-amber-300 ${(loading || joogle.loading) ? "animate-spin" : ""}`}
              />
            </button>
          </div>
        </div>

        {/* ── Body ─────────────────────────────────────────────── */}
        {isHome ? (
          <HomeStartPage
            bookmarks={bookmarks}
            onOpen={navigate}
            onOpenQuickLink={openQuickLink}
            onRemoveBookmark={(u) =>
              setBookmarks(bookmarks.filter((b) => b.url !== u))
            }
          />
        ) : isSovereign ? (
          <SovereignResults
            loading={joogle.loading}
            error={joogle.error}
            query={joogle.result?.query ?? ""}
            answer={joogle.result?.answer ?? ""}
            sources={joogle.result?.sources ?? []}
            onOpenSource={(u: string) => navigate(u)}
          />
        ) : loadError ? (
          <BlockedNotice url={url} onRetry={refresh} onHome={goHome} />
        ) : (
          <div className="relative" style={{ height: "calc(100vh - 124px)" }}>
            <iframe
              ref={iframeRef}
              key={url}
              src={url.replace(/#r\d+$/, "")}
              title="Joogle Browser"
              className="absolute inset-0 w-full h-full bg-white"
              sandbox="allow-scripts allow-forms allow-popups allow-same-origin allow-presentation"
              referrerPolicy="no-referrer"
              onLoad={() => {
                setLoading(false);
                setLoadError(false);
              }}
              onError={() => {
                setLoading(false);
                setLoadError(true);
              }}
            />
            {loading && (
              <div className="absolute inset-x-0 top-0 h-0.5 overflow-hidden">
                <div
                  className="h-full w-1/3 animate-pulse"
                  style={{
                    background:
                      "linear-gradient(90deg, transparent, #d4af37, transparent)",
                  }}
                />
              </div>
            )}
          </div>
        )}

        {/* ── Bottom action bar ────────────────────────────────── */}
        <div
          className="sticky bottom-0 z-30 px-4 py-3 flex items-center justify-around backdrop-blur-xl"
          style={{
            background:
              "linear-gradient(0deg, rgba(20,14,2,0.95), rgba(8,5,0,0.7))",
            borderTop: "0.5px solid rgba(212,175,55,0.35)",
            paddingBottom: "calc(12px + env(safe-area-inset-bottom, 0px))",
          }}
        >
          <button
            onClick={goHome}
            className="flex flex-col items-center gap-0.5 active:scale-95"
            aria-label="Ana sayfa"
          >
            <Home
              className="h-5 w-5"
              style={{ color: isHome ? "#facc15" : "rgba(252,211,77,0.6)" }}
            />
            <span className="text-[10px] text-amber-200/70">Ana Sayfa</span>
          </button>
          <button
            onClick={toggleBookmark}
            disabled={isHome}
            className="flex flex-col items-center gap-0.5 active:scale-95 disabled:opacity-30"
            aria-label="Yer imi"
          >
            <Star
              className="h-5 w-5"
              fill={isBookmarked ? "#facc15" : "transparent"}
              style={{ color: isBookmarked ? "#facc15" : "rgba(252,211,77,0.6)" }}
            />
            <span className="text-[10px] text-amber-200/70">Yer İmi</span>
          </button>
          <button
            onClick={() => {
              hapticTap();
              navigate("https://duckduckgo.com");
            }}
            className="flex flex-col items-center gap-0.5 active:scale-95"
            aria-label="Ara"
          >
            <Search className="h-5 w-5 text-amber-300/70" />
            <span className="text-[10px] text-amber-200/70">Ara</span>
          </button>
        </div>
      </div>
    </AppShell>
  );
}

/* ──────────────────────────────────────────────────────────── */

function HomeStartPage({
  bookmarks,
  onOpen,
  onOpenQuickLink,
  onRemoveBookmark,
}: {
  bookmarks: Bookmark[];
  onOpen: (url: string) => void;
  onOpenQuickLink: (q: typeof QUICK_LINKS[number]) => void;
  onRemoveBookmark: (url: string) => void;
}) {
  return (
    <div className="px-5 pt-8 pb-32">
      {/* Hero */}
      <div className="text-center mb-8">
        <div
          className="mx-auto h-16 w-16 rounded-2xl grid place-items-center mb-3"
          style={{
            background:
              "radial-gradient(120% 100% at 0% 0%, rgba(212,175,55,0.5) 0%, rgba(120,90,20,0.25) 28%, rgba(8,6,2,0.96) 70%, #050300 100%)",
            border: "0.5px solid rgba(212,175,55,0.55)",
            boxShadow:
              "0 12px 32px -10px rgba(212,175,55,0.45), inset 0 1px 0 rgba(255,234,170,0.3)",
          }}
        >
          <Globe className="h-8 w-8 text-amber-300" strokeWidth={1.6} />
        </div>
        <h1
          className="text-2xl font-semibold tracking-tight"
          style={{
            background:
              "linear-gradient(180deg, #fde68a 0%, #d4af37 60%, #92760f 100%)",
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
          }}
        >
          Joogle
        </h1>
        <p className="text-xs text-amber-100/60 mt-1">
          Sovereign Search · Kurmancî pêşîn · Bê şopandin · 777
        </p>
      </div>

      {/* Quick links */}
      <h2 className="text-[11px] uppercase tracking-[0.22em] text-amber-200/50 mb-3">
        Hızlı Erişim
      </h2>
      <div className="grid grid-cols-3 gap-3 mb-8">
        {QUICK_LINKS.map((q) => (
          <button
            key={q.url}
            onClick={() => (q.sovereign ? onOpenQuickLink(q) : onOpen(q.url))}
            className="flex flex-col items-center gap-1.5 active:scale-95 transition relative"
          >
            <span
              className="h-14 w-14 rounded-2xl grid place-items-center relative"
              style={{
                background:
                  "radial-gradient(120% 100% at 0% 0%, rgba(212,175,55,0.32) 0%, rgba(120,90,20,0.18) 28%, rgba(8,6,2,0.96) 70%, #050300 100%)",
                border: q.sovereign
                  ? "0.5px solid rgba(250,204,21,0.7)"
                  : "0.5px solid rgba(212,175,55,0.45)",
                boxShadow: q.sovereign
                  ? "inset 0 1px 0 rgba(255,234,170,0.3), 0 0 18px rgba(250,204,21,0.35)"
                  : "inset 0 1px 0 rgba(255,234,170,0.25), 0 6px 16px -8px rgba(0,0,0,0.8)",
              }}
            >
              <span className="text-amber-200 text-base font-semibold">
                {q.title.charAt(0)}
              </span>
              {q.sovereign && (
                <span
                  className="absolute -top-1 -right-1 text-[8px] font-bold px-1 rounded-full"
                  style={{ background: "#facc15", color: "#000" }}
                >
                  777
                </span>
              )}
            </span>
            <span className="text-[10px] text-amber-100/80 text-center">
              {q.title}
            </span>
          </button>
        ))}
      </div>

      {/* Bookmarks */}
      {bookmarks.length > 0 && (
        <>
          <h2 className="text-[11px] uppercase tracking-[0.22em] text-amber-200/50 mb-3">
            Yer İmleri
          </h2>
          <div className="space-y-2">
            {bookmarks.map((b) => (
              <div
                key={b.url}
                className="flex items-center gap-3 rounded-2xl px-3 py-2.5"
                style={{
                  background: "rgba(212,175,55,0.06)",
                  border: "0.5px solid rgba(212,175,55,0.25)",
                }}
              >
                <Star
                  className="h-4 w-4 text-amber-300 flex-shrink-0"
                  fill="#facc15"
                />
                <button
                  onClick={() => onOpen(b.url)}
                  className="flex-1 text-left min-w-0"
                >
                  <div className="text-sm text-amber-100 truncate">
                    {b.title}
                  </div>
                  <div className="text-[10px] text-amber-100/50 truncate">
                    {b.url}
                  </div>
                </button>
                <button
                  onClick={() => onRemoveBookmark(b.url)}
                  className="p-1.5 opacity-50 active:scale-95"
