      ) : (
        <div className="grid grid-cols-3 gap-0.5 p-0.5">
          {videos.map((v) => (
            <Link
              key={v.id}
              to="/keka"
              search={{ v: v.id } as never}
              className="relative aspect-[9/14] bg-zinc-900 overflow-hidden active:opacity-70"
