import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useMemo, useRef, useState } from "react";
import { ArrowLeft, Plus, Sparkles, Volume2, VolumeX } from "lucide-react";
import { toast } from "sonner";
import { z } from "zod";
import { fallback, zodValidator } from "@tanstack/zod-adapter";
import { useAuth } from "@/hooks/useAuth";
import {
  fetchUserBookmarkedIds,
  fetchUserLikedIds,
  kekaRecordView,
  kekaSendTip,
  kekaToggleBookmark,
  kekaToggleLike,
  useKekaFeed,
  type KekaFeedMode,
  type KekaVideo,
} from "@/hooks/useKeka";
import { useKekaEnergy } from "@/hooks/useKekaEnergy";
import { KekaSlide } from "@/components/keka/KekaSlide";
import { KekaTipDialog } from "@/components/keka/KekaTipDialog";
import { KekaRecorder } from "@/components/keka/KekaRecorder";
import { KekaCommentsSheet } from "@/components/keka/KekaCommentsSheet";
import { KekaReportSheet } from "@/components/keka/KekaReportSheet";
import { KekaShareSheet } from "@/components/keka/KekaShareSheet";
import { GoldRain } from "@/components/keka/GoldRain";
import { EnergyBar } from "@/components/keka/EnergyBar";
import { KekaLoader } from "@/components/keka/KekaLoader";
import { TopTabs, type TopTabValue } from "@/components/layout/TopTabs";
import { SuggestedCreatorsList } from "@/components/social/SuggestedCreatorsList";

const kekaSearchSchema = z.object({
  v: fallback(z.string().optional(), undefined),
});

export const Route = createFileRoute("/keka")({
  component: KekaPage,
  validateSearch: zodValidator(kekaSearchSchema),
  head: () => ({
    meta: [
      { title: "KEKA — Kaydır, İzle ve DiravCash Kazan" },
      {
        name: "description",
        content:
          "KEKA Flow: Jiyan'ın resmi kısa video mini uygulaması. İzle, beğen, tip gönder ve KEKA puanı kazan.",
      },
      { property: "og:title", content: "KEKA — Swipe to Earn" },
      {
        property: "og:description",
        content: "Jiyan WKO ekosisteminde dikey video keşfi.",
      },
    ],
  }),
});

function KekaPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const search = Route.useSearch();
  const deepLinkVideoId = search.v;
  const [feedMode, setFeedMode] = useState<KekaFeedMode>("foryou");
  const { videos, loading, refetch } = useKekaFeed(40, feedMode);

  const [activeIndex, setActiveIndex] = useState(0);
  // Browser autoplay policy requires muted=true for guaranteed autoplay.
  // First tap on the slide will un-mute (handled by onToggleMute).
  const [muted, setMuted] = useState(true);
  const [likedIds, setLikedIds] = useState<Set<string>>(new Set());
  const [bookmarkedIds, setBookmarkedIds] = useState<Set<string>>(new Set());
  const [tipFor, setTipFor] = useState<KekaVideo | null>(null);
  const [commentsFor, setCommentsFor] = useState<string | null>(null);
  const [reportFor, setReportFor] = useState<KekaVideo | null>(null);
  const [shareFor, setShareFor] = useState<KekaVideo | null>(null);
  const [showRecorder, setShowRecorder] = useState(false);
  const [pointsBurst, setPointsBurst] = useState<{ pts: number; key: number } | null>(null);
  const [goldRain, setGoldRain] = useState<{ amount: 1 | 5 | 10; key: number } | null>(null);
  const deepLinkScrolledRef = useRef(false);
  const viewedEnergySpentRef = useRef<Set<string>>(new Set());

  const containerRef = useRef<HTMLDivElement>(null);
  const slideRefs = useRef<Array<HTMLElement | null>>([]);

  // Sovereign Energy
  const { energy, msUntilRefill, consume } = useKekaEnergy(user?.id);

  // ── Swipe-down gesture (return to dashboard) ─────────────────────
  useEffect(() => {
    const root = containerRef.current;
    if (!root) return;
    let startY = 0;
    let startScrollTop = 0;
    let active = false;
    const onStart = (e: TouchEvent) => {
      startY = e.touches[0].clientY;
      startScrollTop = root.scrollTop;
      active = true;
    };
    const onMove = (e: TouchEvent) => {
      if (!active) return;
      const dy = e.touches[0].clientY - startY;
      if (startScrollTop <= 0 && dy > 120) {
        active = false;
        navigate({ to: "/explore" });
      }
    };
    const onEnd = () => { active = false; };
    root.addEventListener("touchstart", onStart, { passive: true });
    root.addEventListener("touchmove", onMove, { passive: true });
    root.addEventListener("touchend", onEnd, { passive: true });
    return () => {
      root.removeEventListener("touchstart", onStart);
      root.removeEventListener("touchmove", onMove);
      root.removeEventListener("touchend", onEnd);
    };
  }, [navigate, videos.length]);

  // Hide global bottom nav while in KEKA Flow
  useEffect(() => {
    document.body.dataset.hideBottomNav = "1";
    return () => {
      delete document.body.dataset.hideBottomNav;
    };
  }, []);

  // Load liked + bookmarked state
  useEffect(() => {
    if (!user || videos.length === 0) return;
    const ids = videos.map((v) => v.id);
    fetchUserLikedIds(user.id, ids).then(setLikedIds).catch(() => {});
    fetchUserBookmarkedIds(user.id, ids).then(setBookmarkedIds).catch(() => {});
  }, [user, videos]);

  // Snap-scroll observer
  useEffect(() => {
    const root = containerRef.current;
    if (!root) return;
    const observer = new IntersectionObserver(
      (entries) => {
        let best: IntersectionObserverEntry | null = null;
        for (const e of entries) {
          if (e.isIntersecting && (!best || e.intersectionRatio > best.intersectionRatio)) {
            best = e;
          }
        }
        if (best) {
          const idx = Number((best.target as HTMLElement).dataset.idx);
          if (!Number.isNaN(idx)) setActiveIndex(idx);
        }
      },
      { root, threshold: [0.6] },
    );
    slideRefs.current.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [videos.length]);

  // Deep-link: scroll to ?v=<videoId> once feed loads
  useEffect(() => {
    if (!deepLinkVideoId || deepLinkScrolledRef.current || videos.length === 0) return;
    const idx = videos.findIndex((v) => v.id === deepLinkVideoId);
    if (idx < 0) return;
    deepLinkScrolledRef.current = true;
    // Wait for slide refs to mount
    requestAnimationFrame(() => {
      const el = slideRefs.current[idx];
      if (el) {
        el.scrollIntoView({ behavior: "auto", block: "start" });
        setActiveIndex(idx);
      }
    });
  }, [deepLinkVideoId, videos]);

  const visibleSet = useMemo(() => {
    const s = new Set<number>();
    [activeIndex - 1, activeIndex, activeIndex + 1, activeIndex + 2].forEach((i) => {
      if (i >= 0 && i < videos.length) s.add(i);
    });
    return s;
  }, [activeIndex, videos.length]);

  const handleViewed = async (videoId: string) => {
    if (!user) return;
    // Spend WATCH energy once per video per session (silent if depleted)
    if (!viewedEnergySpentRef.current.has(videoId)) {
      viewedEnergySpentRef.current.add(videoId);
      consume("WATCH").catch(() => {});
    }
    try {
      const res = await kekaRecordView(videoId);
      if (res?.awarded) {
        setPointsBurst({ pts: res.points_added, key: Date.now() });
        toast.success(`+${res.points_added} KEKA Puanı 🎉`, {
          description: `Toplam: ${res.total_points} puan`,
        });
      }
    } catch {
      // silent — not user-facing
    }
  };

  const handleLike = async (video: KekaVideo) => {
    if (!user) {
      toast.error("Beğeni için giriş yap");
      return;
    }
    // optimistic
    setLikedIds((prev) => {
      const n = new Set(prev);
      if (n.has(video.id)) n.delete(video.id);
      else n.add(video.id);
      return n;
    });
    try {
      await kekaToggleLike(video.id);
      refetch();
    } catch {
      // revert
      setLikedIds((prev) => {
        const n = new Set(prev);
        if (n.has(video.id)) n.delete(video.id);
        else n.add(video.id);
        return n;
      });
      toast.error("Beğeni kaydedilemedi");
    }
  };

  const handleSendTip = async (amount: 1 | 5 | 10) => {
    if (!user || !tipFor) return;
    try {
      const res = await kekaSendTip(tipFor.id, amount);
      if (res?.success) {
        toast.success(`${amount} DC tip gönderildi 💛`);
        setGoldRain({ amount, key: Date.now() });
        setTipFor(null);
        refetch();
      } else {
        toast.error(res?.error ?? "Tip gönderilemedi");
      }
    } catch (e: any) {
      toast.error(e?.message ?? "Tip gönderilemedi");
    }
  };

  const handleBookmark = async (video: KekaVideo) => {
    if (!user) {
      toast.error("Kaydetmek için giriş yap");
      return;
    }
    // optimistic
    const wasBookmarked = bookmarkedIds.has(video.id);
    setBookmarkedIds((prev) => {
      const n = new Set(prev);
      if (wasBookmarked) n.delete(video.id);
      else n.add(video.id);
      return n;
    });
    try {
      const res = await kekaToggleBookmark(video.id);
      if (res?.success) {
        toast.success(res.bookmarked ? "Kaydedildi 🔖" : "Kayıttan çıkarıldı");
      }
    } catch {
      // revert
      setBookmarkedIds((prev) => {
        const n = new Set(prev);
        if (wasBookmarked) n.add(video.id);
        else n.delete(video.id);
        return n;
      });
      toast.error("Kaydedilemedi");
    }
  };

  const handleShare = (video: KekaVideo) => {
    setShareFor(video);
  };

  return (
    <div className="fixed inset-0 z-40 bg-black">
      {/* Top-left back arrow */}
      <button
        onClick={() => navigate({ to: "/" })}
        className="absolute top-3 left-3 z-30 h-10 w-10 rounded-full bg-black/40 backdrop-blur border border-white/15 flex items-center justify-center text-white active:scale-90 transition"
        aria-label="Geri dön"
      >
        <ArrowLeft className="h-5 w-5" />
      </button>

      {/* Top-center TikTok-style tabs */}
      <div className="absolute top-3 left-14 right-24 z-30 h-10 flex items-center">
        <TopTabs
          tabs={[
            { value: "following", label: "Takipte" },
            { value: "foryou", label: "Sizin İçin" },
            { value: "explore", label: "Keşfet" },
          ]}
          value={feedMode === "following" ? "following" : feedMode === "foryou" ? "foryou" : "explore"}
          onChange={(v: TopTabValue) => {
            // "Keşfet" navigates to apps hub for now
            if (v === "explore") {
              navigate({ to: "/explore" });
              return;
            }
            setFeedMode(v as KekaFeedMode);
          }}
          variant="dark"
        />
      </div>

      {/* Top-right mute toggle */}
      <button
        onClick={() => setMuted((m) => !m)}
        className="absolute top-3 right-3 z-30 h-10 w-10 rounded-full bg-black/40 backdrop-blur border border-white/15 flex items-center justify-center text-white active:scale-90 transition"
        aria-label={muted ? "Sesi aç" : "Sesi kapat"}
      >
        {muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}
      </button>

      {/* Sovereign Energy bar — sol üst, top tabs ile çakışmaz */}
      <div className="absolute top-16 left-3 z-30">
        <EnergyBar energy={energy} msUntilRefill={msUntilRefill} />
      </div>

      {/* Floating Create button — alt-ORTA, action rail ile çakışmaz */}
      <button
        onClick={async () => {
          if (!user) {
            toast.error("Önce giriş yapmalısın");
            return;
          }
          if (energy < 10) {
            toast.error("Sovereign enerjin yetersiz", {
              description: `Kayıt için 10 enerji gerek (mevcut: ${energy}). Enerji 24 saatte bir tam dolar.`,
            });
            return;
          }
          const res = await consume("RECORD");
          if (!res.ok) {
            toast.error("Enerji düşürülemedi", {
              description: "Birazdan tekrar dene.",
            });
            return;
          }
          setShowRecorder(true);
        }}
        className="absolute bottom-5 left-1/2 -translate-x-1/2 z-30 h-14 w-14 rounded-full bg-gradient-to-br from-amber-300 via-amber-500 to-amber-700 text-black flex items-center justify-center shadow-[0_0_28px_rgba(255,215,0,0.65)] active:scale-90 transition border-2 border-white/80"
        aria-label="Yeni KEKA çek"
      >
        <Plus className="h-7 w-7" strokeWidth={2.8} />
      </button>

      {/* KEKA Points burst */}
      {pointsBurst && (
        <PointsBurst key={pointsBurst.key} amount={pointsBurst.pts} onDone={() => setPointsBurst(null)} />
      )}

      {/* Gold rain on tip */}
      {goldRain && (
        <GoldRain key={goldRain.key} amount={goldRain.amount} onDone={() => setGoldRain(null)} />
      )}

      {/* Feed */}
      {loading ? (
        <KekaLoader />
      ) : videos.length === 0 ? (
        feedMode === "following" ? (
          <div className="h-full flex flex-col items-center justify-center px-2 pt-20 pb-24 overflow-y-auto">
            <SuggestedCreatorsList
              currentUserId={user?.id}
              variant="dark"
              title="Takipte boş"
              subtitle="Aşağıdaki yaratıcıları takip et, akışın canlansın."
            />
          </div>
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-center px-8">
            <Sparkles className="h-12 w-12 text-amber-300/70 mb-3" />
            <h2 className="text-lg font-bold text-white">KEKA Flow boş</h2>
            <p className="text-sm text-white/55 mt-1 max-w-xs">
              İlk KEKA'yı sen yayınla. 15 saniye, dikey, sınırsız hayal gücü.
            </p>
            <button
              onClick={() => {
                if (!user) {
                  toast.error("Önce giriş yapmalısın");
                  return;
                }
                setShowRecorder(true);
              }}
              className="mt-6 h-12 px-6 rounded-full bg-gradient-to-r from-amber-400 to-amber-600 text-black font-bold text-sm flex items-center gap-2 active:scale-95 transition"
            >
              <Plus className="h-4 w-4" />
              İlk videoyu çek
            </button>
          </div>
        )
      ) : (
        <div
          ref={containerRef}
          className="h-full w-full overflow-y-auto snap-y snap-mandatory overscroll-contain scrollbar-none"
          style={{ scrollbarWidth: "none" }}
        >
          {videos.map((video, idx) => {
            const visible = visibleSet.has(idx);
            return (
              <div
                key={video.id}
                ref={(el) => {
                  slideRefs.current[idx] = el;
                }}
                data-idx={idx}
              >
                {visible ? (
                  <KekaSlide
                    video={video}
                    active={idx === activeIndex}
                    muted={muted}
                    liked={likedIds.has(video.id)}
                    bookmarked={bookmarkedIds.has(video.id)}
                    onBookmark={() => handleBookmark(video)}
                    onToggleMute={() => setMuted((m) => !m)}
                    onLike={() => handleLike(video)}
                    onTip={() => {
                      if (!user) {
                        toast.error("Tip için giriş yap");
                        return;
                      }
                      setTipFor(video);
                    }}
                    onShare={() => handleShare(video)}
                    onComment={() => {
                      if (!user) {
                        toast.error("Yorum için giriş yap");
                        return;
                      }
                      setCommentsFor(video.id);
                    }}
                    onReport={() => setReportFor(video)}
                    onViewed={handleViewed}
                  />
                ) : (
                  <section className="h-[100dvh] w-full snap-start snap-always bg-black" />
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Tip dialog */}
      <KekaTipDialog
        open={tipFor !== null}
        onOpenChange={(o) => !o && setTipFor(null)}
        creatorName={tipFor?.profile?.display_name ?? "Yaratıcı"}
        onSend={handleSendTip}
      />

      {/* Comments sheet */}
      <KekaCommentsSheet
        open={commentsFor !== null}
        videoId={commentsFor}
        onOpenChange={(o) => !o && setCommentsFor(null)}
        onCountChange={() => refetch()}
      />

      {/* Recorder */}
      {user && (
        <KekaRecorder
          open={showRecorder}
          userId={user.id}
          onClose={() => setShowRecorder(false)}
          onUploaded={refetch}
        />
      )}

      {/* Share sheet */}
      <KekaShareSheet
        open={shareFor !== null}
        onOpenChange={(o) => !o && setShareFor(null)}
        videoId={shareFor?.id ?? ""}
        caption={shareFor?.caption}
        authorName={shareFor?.profile?.display_name ?? undefined}
      />

      {/* Report sheet */}
      <KekaReportSheet
        open={reportFor !== null}
        videoId={reportFor?.id ?? null}
        videoOwnerId={reportFor?.user_id ?? null}
        videoOwnerName={reportFor?.profile?.display_name}
        onOpenChange={(o) => !o && setReportFor(null)}
        onActionComplete={refetch}
      />
    </div>
  );
}

function PointsBurst({ amount, onDone }: { amount: number; onDone: () => void }) {
  useEffect(() => {
    const t = setTimeout(onDone, 1400);
    return () => clearTimeout(t);
  }, [onDone]);
  return (
    <div className="pointer-events-none absolute inset-0 z-40 flex items-center justify-center">
      <div className="relative">
        <div className="absolute -inset-16 rounded-full bg-amber-400/20 blur-3xl animate-ping" />
        <div className="relative px-5 py-3 rounded-full bg-gradient-to-r from-amber-400 to-amber-600 text-black font-extrabold text-2xl shadow-[0_0_32px_rgba(255,215,0,0.7)]">
          +{amount} KP
        </div>
      </div>
    </div>
  );
}

