    numberGlow: "drop-shadow(0_0_10px_oklch(0.6_0.2_240/0.5))",
    gradient: "from-[oklch(0.15_0.03_240)] via-[oklch(0.13_0.02_250)] to-[oklch(0.11_0.02_260)]",
