} as const;

function isLegendaryNumber(kurdId: string | null): string | null {
  if (!kurdId) return null;
  const num = kurdId.replace(/\s/g, "").replace("+777", "");
  if (num === "00000001") return "🏆 #1 Legendary Owner";
  if (num === "00000003") return "🔥 #3 Rare Collector";
  if (num === "00000005") return "💎 #5 Ultra Rare";
  return null;
}

function KurdIdCard() {
  const { user, loading } = useAuth();
  const [profile, setProfile] = useState<ProfileData | null>(null);
  const [tab, setTab] = useState<"card" | "market">("card");

  const fetchProfile = useCallback(() => {
    if (!user) return;
    supabase
      .from("profiles")
      .select("display_name, kurd_id, kurd_id_tier, city, avatar_url, is_premium, role, created_at")
      .eq("user_id", user.id)
      .single()
      .then(({ data }) => {
        if (data) setProfile(data as ProfileData);
      });
  }, [user]);

  useEffect(() => { fetchProfile(); }, [fetchProfile]);

  const profileUrl = typeof window !== "undefined" ? `${window.location.origin}/profile` : "https://jiyan.eu";

  const shareCard = async () => {
    const tierLabel = profile?.kurd_id_tier ? TIER_CONFIG[profile.kurd_id_tier as keyof typeof TIER_CONFIG]?.label : "STANDART";
    const text = `🪪 Jiyan Europe Kurd-ID\n${profile?.display_name}\n${profile?.kurd_id}\nTier: ${tierLabel}\n${profileUrl}`;
    if (navigator.share) {
      try { await navigator.share({ title: "Kurd-ID Kartım", text }); } catch {}
    } else {
      await navigator.clipboard.writeText(text);
      toast.success("Kart bilgileri kopyalandı!");
    }
  };

  const memberSince = profile?.created_at
    ? new Date(profile.created_at).toLocaleDateString("tr-TR", { month: "short", year: "numeric" })
    : "";

  if (loading) {
    return (
      <AppShell>
        <div className="flex items-center justify-center pt-32">
          <div className="h-8 w-8 animate-spin rounded-full border-2 border-neon border-t-transparent" />
        </div>
      </AppShell>
    );
  }

  if (!user) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center gap-4 pt-32 px-4">
          <p className="text-muted-foreground">Kurd-ID kartını görmek için giriş yap</p>
          <Button variant="neon" asChild><Link to="/login">Giriş Yap</Link></Button>
        </div>
      </AppShell>
    );
  }

  const tier = (profile?.kurd_id_tier as keyof typeof TIER_CONFIG) || "normal";
  const config = TIER_CONFIG[tier];
  const TierIcon = config.icon;
  const legendary = isLegendaryNumber(profile?.kurd_id ?? null);

  return (
    <AppShell>
      <div className="px-4 pt-4 pb-8">
        {/* Header */}
        <div className="flex items-center gap-3 mb-3">
          <Link to="/profile" className="flex h-9 w-9 items-center justify-center rounded-full bg-surface border border-border">
            <ArrowLeft className="h-4 w-4 text-foreground" />
          </Link>
          <div className="flex-1 min-w-0">
            <h1 className="text-lg font-bold text-foreground">KurdID Sovereign</h1>
            <p className="text-xs text-muted-foreground">WKO Identity · ID Borsa</p>
          </div>
          {/* Persistent Login Bot quick-link — always visible at top of Kurd-ID page */}
          <Link
            to="/developers/sso"
            aria-label="Kurd-ID Login Bot — Developer Portal"
            className="flex items-center gap-1.5 rounded-full border border-neon/40 bg-neon/10 px-3 py-1.5 text-[11px] font-semibold text-neon hover:bg-neon/15 active:scale-[0.97] transition-all"
          >
            🤖 <span className="hidden xs:inline">Login</span> Bot
          </Link>
        </div>

        {/* Tabs */}
        <div className="flex gap-2 mb-5">
          <button
            onClick={() => setTab("card")}
            className={`flex-1 flex items-center justify-center gap-2 rounded-xl py-2.5 text-sm font-medium border transition-colors ${tab === "card" ? "bg-neon/15 border-neon/40 text-neon" : "border-border text-muted-foreground"}`}
          >
            🪪 My Card
          </button>
          <button
            onClick={() => setTab("market")}
            className={`flex-1 flex items-center justify-center gap-2 rounded-xl py-2.5 text-sm font-medium border transition-colors ${tab === "market" ? "bg-gold/15 border-gold/40 text-gold" : "border-border text-muted-foreground"}`}
          >
            <Store className="h-4 w-4" /> WKO ID Borsa
          </button>
        </div>

        {tab === "market" ? (
          <NumberMarketplace
            userId={user?.id}
            userKurdId={profile?.kurd_id ?? null}
            userTier={tier}
            onPurchase={fetchProfile}
          />
        ) : (
          <>
            {/* Card */}
            <div className={`relative mx-auto max-w-sm overflow-hidden rounded-3xl border ${config.cardBorder} ${config.glowClass}`}>
              <div className={`relative bg-gradient-to-br ${config.gradient} p-6`}>
                {/* Background Pattern */}
                <div className="pointer-events-none absolute inset-0 opacity-[0.03]">
                  <div className="absolute inset-0" style={{
                    backgroundImage: `repeating-linear-gradient(45deg, transparent, transparent 20px, currentColor 20px, currentColor 21px)`,
                  }} />
                </div>

                {/* Top Row */}
                <div className="relative flex items-center justify-between mb-5">
                  <div className="flex items-center gap-2">
                    <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-neon/15 border border-neon/30">
                      <span className="text-sm font-bold text-neon">J</span>
                    </div>
                    <div>
                      <p className="text-[10px] font-semibold tracking-widest text-neon/80 uppercase">Jiyan.world</p>
                      <p className="text-[8px] text-muted-foreground tracking-wider">WKO SOVEREIGN ID</p>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <div className={`flex items-center gap-1 rounded-full ${config.bgColor} ${config.borderColor} border px-2 py-0.5`}>
                      <TierIcon className={`h-3 w-3 ${config.color}`} />
                      <span className={`text-[9px] font-bold ${config.color}`}>{config.label}</span>
                    </div>
                    {profile?.is_premium && (
                      <div className="flex items-center gap-1 rounded-full bg-gold/15 border border-gold/30 px-2 py-0.5">
                        <Crown className="h-2.5 w-2.5 text-gold" />
                        <span className="text-[8px] font-semibold text-gold">VIP</span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Avatar & Info */}
                <div className="relative flex items-start gap-4 mb-5">
                  <div className="relative shrink-0">
                    <div className={`h-20 w-20 rounded-2xl border-2 ${config.borderColor} overflow-hidden bg-surface shadow-lg`}>
                      {profile?.avatar_url ? (
                        <img src={profile.avatar_url} alt="" className="h-full w-full object-cover" />
                      ) : (
                        <div className="flex h-full w-full items-center justify-center text-3xl bg-gradient-to-br from-neon/10 to-gold/10">👤</div>
                      )}
                    </div>
                    <div className={`absolute -bottom-1 -right-1 flex h-5 w-5 items-center justify-center rounded-full border-2 border-background ${tier === "ultra_premium" ? "bg-purple-500" : tier === "premium" ? "bg-blue-500" : "bg-neon"}`}>
                      <CheckCircle className="h-3 w-3 text-white" />
