                </div>

                {/* Legendary Badge */}
                {legendary && (
                  <div className="relative mb-3 rounded-xl bg-gradient-to-r from-yellow-500/10 via-orange-500/10 to-yellow-500/10 border border-yellow-500/30 p-2.5 text-center animate-pulse">
                    <p className="text-sm font-bold text-yellow-400">{legendary}</p>
                  </div>
                )}

                {/* Kurd-ID Number */}
                <div className="relative rounded-2xl bg-[oklch(0.08_0.02_260)] border border-border/30 p-4 mb-4">
                  <div className="flex items-center justify-between mb-1">
                    <p className="text-[9px] font-medium tracking-widest text-muted-foreground/60 uppercase">WKO Sovereign Number</p>
                    <span className="text-[9px] text-muted-foreground/40">{config.badge} {config.rarity}</span>
                  </div>
                  <p
                    className={`text-2xl font-mono font-bold tracking-[0.12em] ${config.numberColor}`}
                    style={{ filter: config.numberGlow }}
                  >
                    {profile?.kurd_id || "+777 0000 0000"}
                  </p>
                </div>

                {/* QR Code */}
                <div className="relative flex items-center gap-4">
                  <div className="rounded-xl bg-white p-2.5 shadow-lg">
                    <QRCodeSVG
                      value={profileUrl}
                      size={76}
                      bgColor="#ffffff"
                      fgColor="#000000"
                      level="M"
                    />
                  </div>
                  <div className="flex-1 space-y-1.5">
                    <p className="text-[9px] text-muted-foreground/60 leading-tight">
                      Scan QR to view profile or check in at WKO events.
                    </p>
                    <div className="h-px bg-border/30" />
                    <div className="flex items-center gap-1">
                      <div className={`h-1.5 w-1.5 rounded-full animate-pulse ${tier === "ultra_premium" ? "bg-purple-400" : tier === "premium" ? "bg-blue-400" : "bg-neon"}`} />
                      <p className={`text-[9px] font-medium ${config.color} opacity-80`}>WKO Verified Citizen</p>
                    </div>
                  </div>
                </div>

                {/* Accent line */}
                <div className={`mt-5 h-1 rounded-full bg-gradient-to-r ${config.accentLine} opacity-50`} />
              </div>
            </div>

            {/* Actions */}
            <div className="mt-6 flex gap-3 max-w-sm mx-auto">
              <Button variant="neon" className="flex-1" onClick={shareCard}>
                <Share2 className="h-4 w-4 mr-2" /> Paylaş
              </Button>
              <Button variant="outline" className="flex-1" onClick={() => toast.info("Ekran görüntüsü alarak kartınızı kaydedebilirsiniz")}>
                <Download className="h-4 w-4 mr-2" /> Kaydet
              </Button>
            </div>

            {/* Tier Info */}
            <div className="mt-6 max-w-sm mx-auto space-y-3">
              <div className="rounded-xl border border-border bg-surface p-4">
                <h3 className="text-sm font-semibold text-foreground mb-3">📊 Numara Seviyeleri</h3>
                <div className="space-y-2.5">
                  {([
                    { tier: "ultra_premium", pct: "10%", desc: "Simetrik & nadir seri", ex: "+777 1234 1234" },
                    { tier: "premium", pct: "20%", desc: "Düzenli pattern seri", ex: "+777 5600 5672" },
                    { tier: "normal", pct: "70%", desc: "Standart rastgele seri", ex: "+777 4821 9034" },
                  ] as const).map((t) => {
                    const tc = TIER_CONFIG[t.tier];
                    const TIcon = tc.icon;
                    return (
                      <div key={t.tier} className={`flex items-start gap-3 rounded-lg p-2.5 ${tier === t.tier ? `${tc.bgColor} border ${tc.borderColor}` : "bg-background/50"}`}>
                        <TIcon className={`h-4 w-4 mt-0.5 ${tc.color}`} />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <span className={`text-xs font-semibold ${tc.color}`}>{tc.label}</span>
                            <span className="text-[10px] text-muted-foreground">({t.pct})</span>
                            {tier === t.tier && <span className="text-[9px] bg-neon/20 text-neon px-1.5 py-0.5 rounded-full font-medium">SENİN</span>}
                          </div>
                          <p className="text-[11px] text-muted-foreground mt-0.5">{t.desc}</p>
                          <p className="text-[10px] font-mono text-muted-foreground/50 mt-0.5">Örn: {t.ex}</p>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              <div className="rounded-xl border border-border bg-surface p-4">
                <h3 className="text-sm font-semibold text-foreground mb-2">🏆 Özel Seri Numaralar</h3>
                <p className="text-xs text-muted-foreground mb-2">Efsanevi tek seferlik numaralar:</p>
                <div className="space-y-1.5">
                  {[
                    { id: "+777 0000 0001", label: "#1 Legendary Owner" },
                    { id: "+777 0000 0003", label: "#3 Rare Collector" },
                    { id: "+777 0000 0005", label: "#5 Ultra Rare" },
                  ].map((s) => (
                    <div key={s.id} className="flex items-center gap-2 text-xs">
                      <span className="font-mono text-yellow-400/80">{s.id}</span>
                      <span className="text-muted-foreground">→ {s.label}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="rounded-xl border border-border bg-surface p-4">
                <h3 className="text-sm font-semibold text-foreground mb-2">🎫 Etkinlik Girişi</h3>
                <p className="text-xs text-muted-foreground leading-relaxed">
                  QR kodunuzu etkinlik girişinde taratarak hızlı check-in yapabilirsiniz.
                </p>
              </div>
            </div>
          </>
        )}
      </div>
    </AppShell>
  );
}

