import { createFileRoute, Link } from "@tanstack/react-router";
import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { ArrowLeft, Share2, Calendar, User, BookOpen, Copy, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import type { KurdpediaArticle } from "@/hooks/useKurdpedia";

export const Route = createFileRoute("/kurdpedia/$articleId")({
  head: () => ({
    meta: [
      { title: "Kurdpedia — Jiyan Europe" },
      { name: "description", content: "Kürt tarihi ve kültürü hakkında detaylı makale" },
    ],
  }),
  component: KurdpediaDetailPage,
});

const categoryLabels: Record<string, string> = {
  history: "Tarih",
  culture: "Kültür",
  figures: "Önemli Kişiler",
  places: "Yerler",
  general: "Genel",
};

function KurdpediaDetailPage() {
  const { articleId } = Route.useParams();
  const [article, setArticle] = useState<KurdpediaArticle | null>(null);
  const [loading, setLoading] = useState(true);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    supabase
      .from("kurdpedia_articles")
      .select("*")
      .eq("id", articleId)
      .eq("is_published", true)
      .single()
      .then(({ data }) => {
        if (data) setArticle(data as KurdpediaArticle);
        setLoading(false);
      });
  }, [articleId]);

  const shareUrl = typeof window !== "undefined" ? window.location.href : "";

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl);
      setCopied(true);
      toast.success("Link kopyalandı!");
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error("Kopyalanamadı");
    }
  };

  const handleShare = async () => {
    if (navigator.share && article) {
      try {
        await navigator.share({ title: article.title, url: shareUrl });
      } catch { /* cancelled */ }
    } else {
      handleCopyLink();
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background p-4 space-y-4">
        <Skeleton className="h-8 w-32" />
        <Skeleton className="h-48 w-full rounded-xl" />
        <Skeleton className="h-6 w-3/4" />
        <Skeleton className="h-4 w-full" />
        <Skeleton className="h-4 w-full" />
        <Skeleton className="h-4 w-2/3" />
      </div>
    );
  }

  if (!article) {
    return (
      <div className="min-h-screen bg-background flex flex-col items-center justify-center gap-4 p-4">
        <BookOpen className="h-16 w-16 text-muted-foreground" />
        <h1 className="text-xl font-bold text-foreground">Makale bulunamadı</h1>
        <Link to="/feed">
          <Button variant="outline">Geri Dön</Button>
        </Link>
      </div>
    );
  }

  const date = new Date(article.created_at).toLocaleDateString("tr-TR", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });

  return (
    <div className="min-h-screen bg-background pb-24">
      {/* Header */}
      <div className="sticky top-0 z-30 bg-background/80 backdrop-blur-lg border-b border-border px-4 py-3 flex items-center justify-between">
        <Link to="/feed">
          <Button variant="ghost" size="icon">
            <ArrowLeft className="h-5 w-5" />
          </Button>
        </Link>
        <span className="font-semibold text-foreground text-sm truncate max-w-[200px]">Kurdpedia</span>
        <Button variant="ghost" size="icon" onClick={handleShare}>
          <Share2 className="h-5 w-5" />
        </Button>
      </div>

      {/* Hero Image */}
      {article.image_url && (
        <div className="w-full aspect-video relative overflow-hidden">
          <img
            src={article.image_url}
            alt={article.title}
            className="w-full h-full object-cover"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-background/80 to-transparent" />
        </div>
      )}

      {/* Content */}
      <div className="px-4 py-5 space-y-4">
        <div className="flex items-center gap-2">
          <Badge variant="secondary">
            {categoryLabels[article.category] || article.category}
          </Badge>
          <span className="text-xs text-muted-foreground flex items-center gap-1">
            <Calendar className="h-3 w-3" /> {date}
          </span>
        </div>

        <h1 className="text-2xl font-bold text-foreground leading-tight">
          {article.title}
        </h1>

        {article.author_id && (
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <User className="h-4 w-4" />
            <span>Yazar</span>
          </div>
        )}

        <article className="prose prose-sm max-w-none text-foreground/90 leading-relaxed whitespace-pre-wrap">
          {article.content}
        </article>
      </div>

      {/* Share Bar */}
      <div className="fixed bottom-20 left-0 right-0 px-4 pb-2">
        <div className="bg-card/90 backdrop-blur-lg border border-border rounded-xl p-3 flex gap-2">
          <Button className="flex-1" variant="outline" onClick={handleCopyLink}>
            {copied ? <Check className="h-4 w-4 mr-2" /> : <Copy className="h-4 w-4 mr-2" />}
            {copied ? "Kopyalandı" : "Linki Kopyala"}
          </Button>
          <Button className="flex-1" onClick={handleShare}>
            <Share2 className="h-4 w-4 mr-2" />
            Paylaş
          </Button>
        </div>
      </div>
    </div>
  );
}

