          ) : (
            filtered.map((a) => (
              <Link
                key={a.id}
                to="/kurdpedia/$articleId"
                params={{ articleId: a.id }}
                className="block rounded-2xl border border-white/10 bg-white/[0.03] p-4 transition-all hover:border-cyan-400/30 hover:bg-white/[0.06] active:scale-[0.99]"
              >
                <div className="flex gap-3">
                  {a.image_url && (
                    <img
                      src={a.image_url}
                      alt=""
                      className="h-16 w-16 rounded-xl object-cover shrink-0"
                    />
                  )}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-[10px] uppercase tracking-wider rounded-full bg-cyan-500/15 text-cyan-300 px-2 py-0.5">
                        {categoryLabels[a.category] || a.category}
                      </span>
                    </div>
                    <h3 className="text-sm font-semibold text-foreground line-clamp-1">
                      {a.title}
                    </h3>
                    <p className="text-xs text-muted-foreground line-clamp-2 mt-1">
                      {a.content.slice(0, 120)}
                    </p>
                    <div className="flex items-center gap-1 mt-2 text-[10px] text-muted-foreground">
                      <Calendar className="h-3 w-3" />
                      {new Date(a.created_at).toLocaleDateString("tr-TR")}
                    </div>
                  </div>
                </div>
              </Link>
            ))
          )}
        </div>
      </div>
    </AppShell>
  );
}

