import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import {
  ArrowLeft, Shield, CheckCircle, Upload, FileText,
  Camera, User, AlertTriangle, Loader2, XCircle, Clock,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";

export const Route = createFileRoute("/kyc")({
  component: KycPage,
  head: () => ({
    meta: [
      { title: "Doğrulama & KYC – Jiyan.world" },
      { name: "description", content: "WKO Sovereign Identity için kimliğinizi doğrulayın." },
    ],
  }),
});

type DocType = "passport" | "id_card" | "driving_license";
type ExistingStatus = "pending" | "approved" | "rejected" | null;

function KycPage() {
  const { user } = useAuth();
  const [step, setStep] = useState(0);
  const [submitting, setSubmitting] = useState(false);
  const [existing, setExisting] = useState<ExistingStatus>(null);
  const [rejectionReason, setRejectionReason] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  // Form state
  const [fullName, setFullName] = useState("");
  const [dob, setDob] = useState("");
  const [docType, setDocType] = useState<DocType>("passport");
  const [docFile, setDocFile] = useState<File | null>(null);
  const [selfieFile, setSelfieFile] = useState<File | null>(null);

  const docInputRef = useRef<HTMLInputElement>(null);
  const selfieInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!user) { setLoading(false); return; }
    (async () => {
      const { data } = await supabase
        .from("kyc_requests")
        .select("status, rejection_reason")
        .eq("user_id", user.id)
        .order("submitted_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (data) {
        setExisting(data.status as ExistingStatus);
        setRejectionReason(data.rejection_reason);
      }
      setLoading(false);
    })();
  }, [user]);

  if (!user) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center px-4 pt-20 text-center">
          <Shield className="h-12 w-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground text-sm mb-4">Doğrulama için giriş yapın</p>
          <Button variant="neon" asChild><Link to="/login">Giriş Yap</Link></Button>
        </div>
      </AppShell>
    );
  }

  const validateFile = (f: File) => {
    if (f.size > 10 * 1024 * 1024) { toast.error("Dosya 10MB'dan büyük olamaz"); return false; }
    const ok = ["image/jpeg","image/jpg","image/png","image/webp","application/pdf"];
    if (!ok.includes(f.type)) { toast.error("Sadece JPG, PNG, WEBP veya PDF"); return false; }
    return true;
  };

  const uploadFile = async (file: File, kind: "document" | "selfie") => {
    const ext = file.name.split(".").pop() || "jpg";
    const path = `${user.id}/${kind}-${Date.now()}.${ext}`;
    const { error } = await supabase.storage.from("kyc-documents").upload(path, file, {
      cacheControl: "3600",
      upsert: false,
      contentType: file.type,
    });
    if (error) throw error;
    return path;
  };

  const handleSubmit = async () => {
    if (!fullName.trim() || fullName.trim().length < 3) { toast.error("Geçerli ad soyad girin"); setStep(0); return; }
    if (!dob) { toast.error("Doğum tarihi gerekli"); setStep(0); return; }
    if (!docFile) { toast.error("Kimlik belgesi yükleyin"); setStep(1); return; }
    if (!selfieFile) { toast.error("Selfie yükleyin"); setStep(2); return; }

    setSubmitting(true);
    try {
      const [docPath, selfiePath] = await Promise.all([
        uploadFile(docFile, "document"),
        uploadFile(selfieFile, "selfie"),
      ]);
      const { data, error } = await supabase.rpc("submit_kyc_request", {
        _full_name: fullName.trim(),
        _date_of_birth: dob,
        _document_type: docType,
        _document_url: docPath,
        _selfie_url: selfiePath,
      });
      if (error) throw error;
      const result = data as { success: boolean; error?: string };
      if (!result.success) { toast.error(result.error || "Gönderim başarısız"); return; }
      toast.success("Doğrulama talebiniz alındı! 24-48 saat içinde sonuçlanacaktır.");
      setExisting("pending");
    } catch (e: any) {
      toast.error(e?.message || "Bir hata oluştu");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <AppShell>
        <div className="flex items-center justify-center pt-20">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </div>
      </AppShell>
    );
  }

  // Status screens
  if (existing === "pending" || existing === "approved") {
    const approved = existing === "approved";
    return (
      <AppShell>
        <div className="px-4 pt-6 pb-8">
          <div className="flex items-center gap-3 mb-6">
            <Link to="/profile" className="text-muted-foreground hover:text-foreground">
              <ArrowLeft className="h-5 w-5" />
            </Link>
            <h1 className="text-xl font-bold text-foreground">Doğrulama & KYC</h1>
          </div>
          <div className={`rounded-2xl border p-6 text-center ${approved ? "border-emerald-500/30 bg-emerald-500/5" : "border-gold/30 bg-gold/5"}`}>
            {approved ? (
              <CheckCircle className="h-10 w-10 text-emerald-400 mx-auto mb-2" />
            ) : (
              <Clock className="h-10 w-10 text-gold mx-auto mb-2" />
            )}
            <h3 className="text-base font-semibold text-foreground">
              {approved ? "Hesabınız Doğrulandı ✓" : "İnceleniyor..."}
            </h3>
            <p className="mt-2 text-xs text-muted-foreground">
              {approved
                ? "WKO Sovereign rozetiniz aktif. Profilinizde doğrulanmış olarak görüneceksiniz."
                : "Belgeleriniz inceleniyor. 24-48 saat içinde bildirim alacaksınız."}
            </p>
          </div>
        </div>
      </AppShell>
    );
  }

  const steps = [
    { icon: User, label: "Kişisel Bilgiler", desc: "Adınız, doğum tarihiniz" },
    { icon: FileText, label: "Kimlik Belgesi", desc: "Pasaport veya kimlik kartı" },
    { icon: Camera, label: "Selfie Doğrulama", desc: "Yüzünüzü doğrulayın" },
  ];

  const canAdvance = (i: number) => {
    if (i === 0) return fullName.trim().length >= 3 && !!dob;
    if (i === 1) return !!docFile;
    if (i === 2) return !!selfieFile;
    return false;
  };

  return (
    <AppShell>
      <div className="px-4 pt-6 pb-8">
        <div className="flex items-center gap-3 mb-6">
          <Link to="/profile" className="text-muted-foreground hover:text-foreground">
            <ArrowLeft className="h-5 w-5" />
          </Link>
          <h1 className="text-xl font-bold text-foreground">Doğrulama & KYC</h1>
        </div>

        {existing === "rejected" && (
          <div className="rounded-2xl border border-rose-500/30 bg-rose-500/5 p-4 mb-4">
            <div className="flex items-start gap-2">
              <XCircle className="h-4 w-4 text-rose-400 mt-0.5 shrink-0" />
              <div>
                <p className="text-xs font-semibold text-rose-200">Önceki talep reddedildi</p>
                {rejectionReason && <p className="text-[11px] text-rose-200/70 mt-1">{rejectionReason}</p>}
                <p className="text-[11px] text-muted-foreground mt-1">Lütfen bilgileri düzeltip tekrar gönderin.</p>
              </div>
            </div>
          </div>
        )}

        <div className="rounded-2xl border border-neon/30 bg-neon/5 p-4 mb-6">
          <div className="flex items-start gap-3">
            <Shield className="h-5 w-5 text-neon shrink-0 mt-0.5" />
            <div>
              <h3 className="text-sm font-semibold text-foreground">Neden doğrulama?</h3>
              <p className="text-xs text-muted-foreground mt-1 leading-relaxed">
                Doğrulanmış hesaplar WKO Sovereign rozetini alır, daha güvenilir görünür ve daha yüksek limitlere sahip olur.
              </p>
            </div>
          </div>
        </div>

        <div className="space-y-3">
          {steps.map((s, i) => {
            const Icon = s.icon;
            const isCompleted = i < step;
            const isCurrent = i === step;
            return (
              <div
                key={i}
                className={`rounded-xl border p-4 transition-all ${
                  isCompleted ? "border-neon/30 bg-neon/5"
                    : isCurrent ? "border-neon/50 bg-surface"
                    : "border-border bg-surface opacity-50"
                }`}
              >
                <div className="flex items-center gap-3">
                  <div className={`flex h-10 w-10 items-center justify-center rounded-full ${isCompleted ? "bg-neon/10" : "bg-accent"}`}>
                    {isCompleted ? <CheckCircle className="h-5 w-5 text-neon" />
                      : <Icon className={`h-5 w-5 ${isCurrent ? "text-neon" : "text-muted-foreground"}`} />}
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-semibold text-foreground">{s.label}</p>
                    <p className="text-[11px] text-muted-foreground">{s.desc}</p>
                  </div>
                  {isCompleted && <span className="text-[10px] font-medium text-neon">✓</span>}
                </div>

                {isCurrent && (
                  <div className="mt-3">
                    {i === 0 && (
                      <div className="space-y-2">
                        <input
                          value={fullName}
                          onChange={(e) => setFullName(e.target.value)}
                          placeholder="Ad Soyad"
                          className="h-10 w-full rounded-lg border border-border bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus:border-neon focus:outline-none"
                        />
                        <input
                          type="date"
                          value={dob}
                          onChange={(e) => setDob(e.target.value)}
                          max={new Date().toISOString().split("T")[0]}
                          className="h-10 w-full rounded-lg border border-border bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus:border-neon focus:outline-none"
                        />
                      </div>
                    )}
                    {i === 1 && (
                      <div className="space-y-2">
                        <select
                          value={docType}
                          onChange={(e) => setDocType(e.target.value as DocType)}
                          className="h-10 w-full rounded-lg border border-border bg-background px-3 text-sm text-foreground focus:border-neon focus:outline-none"
                        >
                          <option value="passport">Pasaport</option>
                          <option value="id_card">Kimlik Kartı</option>
                          <option value="driving_license">Ehliyet</option>
                        </select>
                        <input
                          ref={docInputRef}
                          type="file"
                          accept="image/jpeg,image/png,image/webp,application/pdf"
                          className="hidden"
                          onChange={(e) => {
                            const f = e.target.files?.[0];
                            if (f && validateFile(f)) setDocFile(f);
                          }}
                        />
                        <button
                          type="button"
                          onClick={() => docInputRef.current?.click()}
                          className="flex w-full flex-col items-center gap-2 rounded-lg border-2 border-dashed border-border bg-accent/50 p-6 hover:border-neon/50 transition-colors"
                        >
                          <Upload className="h-8 w-8 text-muted-foreground" />
                          <p className="text-xs text-foreground">
                            {docFile ? docFile.name : "Kimlik belgenizi yükleyin"}
                          </p>
                          <p className="text-[10px] text-muted-foreground">JPG, PNG, WEBP veya PDF (max 10MB)</p>
                        </button>
                      </div>
                    )}
                    {i === 2 && (
                      <div className="space-y-2">
                        <input
                          ref={selfieInputRef}
                          type="file"
                          accept="image/jpeg,image/png,image/webp"
                          capture="user"
                          className="hidden"
                          onChange={(e) => {
                            const f = e.target.files?.[0];
                            if (f && validateFile(f)) setSelfieFile(f);
                          }}
                        />
                        <button
                          type="button"
                          onClick={() => selfieInputRef.current?.click()}
                          className="flex w-full flex-col items-center gap-2 rounded-lg border-2 border-dashed border-border bg-accent/50 p-6 hover:border-neon/50 transition-colors"
                        >
                          <Camera className="h-8 w-8 text-muted-foreground" />
                          <p className="text-xs text-foreground">
                            {selfieFile ? selfieFile.name : "Selfie çekin veya yükleyin"}
                          </p>
                          <p className="text-[10px] text-muted-foreground">Yüzünüz net görünmeli</p>
                        </button>
                      </div>
                    )}
                    <Button
                      variant="neon"
                      size="sm"
                      className="mt-3 w-full"
                      disabled={!canAdvance(i) || submitting}
                      onClick={() => i === 2 ? handleSubmit() : setStep(step + 1)}
                    >
                      {submitting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
                      {i === 2 ? (submitting ? "Yükleniyor..." : "Doğrulamayı Gönder") : "Devam Et"}
                    </Button>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="mt-6 flex items-start gap-2 px-1">
          <AlertTriangle className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
          <p className="text-[10px] text-muted-foreground leading-relaxed">
            Belgeleriniz Global WKO Privacy Protocols altında şifrelenir ve sadece doğrulama için kullanılır.
          </p>
        </div>
      </div>
    </AppShell>
  );
}

