import { createFileRoute, Link } from "@tanstack/react-router";
import { useState, useMemo, useEffect, useRef } from "react";
import { AppShell } from "@/components/layout/AppShell";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { useAuth } from "@/hooks/useAuth";
import { useLinguist } from "@/hooks/useLinguist";
import { useLinguistAcademy } from "@/hooks/useLinguistAcademy";
import { LINGUIST_COURSES, getCourse, type Language, type Lesson, isLevelMilestone } from "@/data/linguistContent";
import { TR_NL_DECK } from "@/data/linguistFlashcards";
import { LinguistLessonPlayer } from "@/components/linguist/LinguistLessonPlayer";
import { LinguistConsentScreen } from "@/components/linguist/LinguistConsentScreen";
import { Flashcard } from "@/components/linguist/Flashcard";
import { WeeklyChart } from "@/components/linguist/WeeklyChart";
import { GoalRing } from "@/components/linguist/GoalRing";
import { downloadCertificate } from "@/lib/linguistCertificate";
import { supabase } from "@/integrations/supabase/client";
import { BookOpen, Trophy, Sparkles, Download, Wallet, Lock, GraduationCap, Globe2, Flame, Target, Layers, Shuffle, Bot } from "lucide-react";
import { toast } from "sonner";
import { LevelBadges } from "@/components/linguist/LevelBadges";
import { DengPracticeTab } from "@/components/linguist/DengPracticeTab";
import { RoadmapCards, type RoadmapStepKey } from "@/components/linguist/RoadmapCards";
import { QuickQuizCard } from "@/components/linguist/QuickQuizCard";
import { LanguagePickerSheet } from "@/components/linguist/LanguagePickerSheet";
import { SovereignBridgeCard } from "@/components/linguist/SovereignBridgeCard";
import { MirrorModeCard } from "@/components/linguist/MirrorModeCard";
import { StorySeedCard } from "@/components/linguist/StorySeedCard";
import { WhisperStreakCard } from "@/components/linguist/WhisperStreakCard";
import { useLanguagePair } from "@/hooks/useLanguagePair";

export const Route = createFileRoute("/linguist")({
  component: LinguistPage,
  head: () => ({
    meta: [
      { title: "WKO Linguist – Learn 4 Languages | Jiyan.world" },
      { name: "description", content: "Duolingo-style language learning with Kurdish, Turkish, Dutch & English. Earn XP, DiravCash and verifiable WKO certificates." },
    ],
  }),
});

function LinguistPage() {
  const { user } = useAuth();
  const { pair, ready: pairReady, save: savePair, isFirstRun } = useLanguagePair();
  const nativeLang: Language = pair?.native ?? "tr";
  const [language, setLanguage] = useState<Language>(pair?.target ?? "ku");
  // Keep target in sync when pair resolves
  useEffect(() => { if (pair?.target) setLanguage(pair.target); }, [pair?.target]);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [consentLoading, setConsentLoading] = useState(false);
  const { progress, certificates, hasConsent, loading, grantConsent, completeLesson, issueCertificate } = useLinguist();
  const { settings, sessions, cardStates, loading: academyLoading, saveSettings, setCardStatus, recordSession } = useLinguistAcademy();

  const dailyGoal = settings?.daily_goal_minutes ?? 10;
  const todayIso = new Date().toISOString().slice(0, 10);
  const todaySession = sessions.find((s) => s.session_date === todayIso);
  const minutesToday = todaySession?.minutes_studied ?? 0;
  const masteredCount = useMemo(
    () => Object.values(cardStates).filter((c) => c.status === "mastered").length,
    [cardStates],
  );

  // Roadmap step "reflect" is a manual seal — others auto-derive from real activity.
  const [reflectSealed, setReflectSealed] = useState(false);
  const [practiceTouched, setPracticeTouched] = useState(false);
  const [quizCorrect, setQuizCorrect] = useState(0); // counts toward warmup
  const [todayMethod, setTodayMethod] = useState<string | undefined>(undefined);
  const roadmapProgress: Record<RoadmapStepKey, number> = useMemo(() => {
    // Warmup: 1 minute on app OR 4 quick-quiz answers
    const warmupFromTime = minutesToday >= 1 ? 100 : Math.min(100, minutesToday * 100);
    const warmupFromQuiz = Math.min(100, quizCorrect * 25); // 4 correct = 100%
    const warmup = Math.max(warmupFromTime, warmupFromQuiz);
    const drill = Math.min(100, masteredCount * 25); // 4 cards = 100%
    const practice = practiceTouched ? 100 : 0;
    const reflect = reflectSealed ? 100 : 0;
    return { warmup, drill, practice, reflect };
  }, [minutesToday, masteredCount, practiceTouched, reflectSealed, quizCorrect]);

  // Sürekli oturum sayacı: sayfa açıkken her 60 sn'de 1 dk + master sayısı kaydedilir
  const sessionStartRef = useRef<number>(Date.now());
  const lastFlushedMinRef = useRef<number>(0);
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(async () => {
      const elapsedMin = Math.floor((Date.now() - sessionStartRef.current) / 60000);
      const delta = elapsedMin - lastFlushedMinRef.current;
      if (delta < 1) return;
      lastFlushedMinRef.current = elapsedMin;
      const r = await recordSession(delta, 0);
      if (
        r &&
        "goal_reached" in r &&
        r.goal_reached &&
        minutesToday + delta >= dailyGoal &&
        minutesToday < dailyGoal
      ) {
        toast.success(`🎯 Günlük hedef tamamlandı! · ${r.streak} gün streak`);
      }
    }, 60_000);
    return () => clearInterval(interval);
  }, [user, recordSession, dailyGoal, minutesToday]);

  const course = useMemo(() => getCourse(language), [language]);
  const completedIds = useMemo(
    () => new Set(progress.filter((p) => p.language === language).map((p) => p.lesson_id)),
    [progress, language]
  );
  const totalXp = useMemo(() => progress.reduce((s, p) => s + p.xp_earned, 0), [progress]);
  const totalDc = useMemo(() => progress.reduce((s, p) => s + Number(p.dc_earned ?? 0), 0), [progress]);

  const lessonsByCategory = useMemo(() => {
    return {
      core: course.lessons.filter((l) => l.category === "core"),
      sovereign: course.lessons.filter((l) => l.category === "sovereign"),
      constitution: course.lessons.filter((l) => l.category === "constitution"),
    };
  }, [course]);

  if (!user) {
    return (
      <AppShell>
        <div className="bg-black min-h-screen flex items-center justify-center px-4">
          <Card className="max-w-md w-full bg-zinc-950 border border-[hsl(var(--linguist-gold))]/40 p-8 text-center">
            <Lock className="w-12 h-12 mx-auto text-[hsl(var(--linguist-gold))] mb-4" />
            <h1 className="text-2xl font-bold text-[hsl(var(--linguist-gold))] mb-2">Sign in required</h1>
            <p className="text-zinc-400 text-sm mb-6">WKO Linguist links progress to your KurdID.</p>
            <Link to="/login">
              <Button className="w-full bg-[hsl(var(--linguist-gold))] text-black font-semibold hover:bg-[hsl(var(--linguist-gold))]/90">Sign in</Button>
            </Link>
          </Card>
        </div>
      </AppShell>
    );
  }

  if (loading) {
    return (
      <AppShell>
        <div className="bg-black min-h-screen flex items-center justify-center text-zinc-400">Loading WKO Linguist...</div>
      </AppShell>
    );
  }

  if (hasConsent === false) {
    return (
      <AppShell>
        <div className="bg-black min-h-screen py-8">
          <LinguistConsentScreen
            loading={consentLoading}
            onAccept={async () => {
              setConsentLoading(true);
              const r = await grantConsent();
              setConsentLoading(false);
              if (!r.success) toast.error(r.error || "Consent failed");
            }}
            onDecline={() => {
              window.history.back();
            }}
          />
        </div>
      </AppShell>
    );
  }

  if (activeLesson) {
    return (
      <AppShell>
        <div className="bg-black min-h-screen py-6 px-4">
          <div className="max-w-2xl mx-auto">
            <LinguistLessonPlayer
              lesson={activeLesson}
              course={course}
              onExit={() => setActiveLesson(null)}
              onComplete={async (score) => {
                const milestone = isLevelMilestone(course, activeLesson, completedIds);
                const result = await completeLesson(language, activeLesson.level, activeLesson.id, score, activeLesson.xp, milestone);
                if (result && result.success && "xp" in result) {
                  if (!result.already_completed) {
                    toast.success(`+${result.xp ?? activeLesson.xp} XP${result.dc ? ` · +${result.dc} DC` : ""}`);
                  }
                  if (milestone) {
                    const cert = await issueCertificate(language, activeLesson.level);
                    if (cert && cert.success && "certificate_no" in cert) {
                      toast.success(`🏆 ${activeLesson.level} certificate issued!`);
                    }
                  }
                }
              }}
            />
          </div>
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      {/* First-run language picker (covers screen until both langs chosen) */}
      <LanguagePickerSheet
        open={pairReady && isFirstRun}
        initialNative="tr"
        initialTarget="ku"
        onConfirm={({ native, target }) => {
          savePair({ native, target });
          setLanguage(target);
          toast.success(`✓ ${native.toUpperCase()} → ${target.toUpperCase()}`);
        }}
      />
      <div className="bg-black min-h-screen text-white">
        <div className="max-w-3xl mx-auto px-4 py-6 space-y-6">
          {/* Header */}
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-[hsl(var(--linguist-gold))] to-[hsl(var(--linguist-purple))] flex items-center justify-center">
              <GraduationCap className="w-7 h-7 text-black" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[hsl(var(--linguist-gold))]">WKO Linguist</h1>
              <p className="text-xs text-zinc-500">Sovereign language education</p>
            </div>
          </div>

          {/* Stats */}
          <div className="grid grid-cols-3 gap-3">
            <Card className="bg-zinc-950 border-[hsl(var(--linguist-gold))]/30 p-3 text-center">
              <Sparkles className="w-4 h-4 text-[hsl(var(--linguist-gold))] mx-auto mb-1" />
              <div className="text-xl font-bold text-white">{totalXp}</div>
              <div className="text-[10px] text-zinc-500 uppercase tracking-wider">Academy XP</div>
            </Card>
            <Card className="bg-zinc-950 border-[hsl(var(--linguist-purple))]/30 p-3 text-center">
              <Trophy className="w-4 h-4 text-[hsl(var(--linguist-purple))] mx-auto mb-1" />
              <div className="text-xl font-bold text-white">{totalDc.toFixed(1)}</div>
              <div className="text-[10px] text-zinc-500 uppercase tracking-wider">DiravCash</div>
            </Card>
            <Card className="bg-zinc-950 border-[hsl(var(--linguist-gold))]/30 p-3 text-center">
              <BookOpen className="w-4 h-4 text-[hsl(var(--linguist-gold))] mx-auto mb-1" />
              <div className="text-xl font-bold text-white">{certificates.length}</div>
              <div className="text-[10px] text-zinc-500 uppercase tracking-wider">Certificates</div>
            </Card>
          </div>

          {/* ─── Level + Badges ─── */}
          <LevelBadges
            totalXp={totalXp}
            streak={settings?.current_streak ?? 0}
            mastered={masteredCount}
            certificates={certificates.length}
            languagesUsed={new Set(progress.map((p) => p.language)).size}
          />

          {/* ─── 5-Minute Roadmap (4 cards · daily-rotating method) ─── */}
          <RoadmapCards
            progress={roadmapProgress}
            onMethodResolved={setTodayMethod}
            onStepClick={(k) => {
              if (k === "reflect") {
                setReflectSealed(true);
                toast.success("🔖 Yansıma mühürlendi · +1 streak boost");
                void recordSession(1, 0);
              } else if (k === "practice") {
                document
                  .getElementById("deng-practice-anchor")
                  ?.scrollIntoView({ behavior: "smooth", block: "start" });
              } else if (k === "drill") {
                document
                  .getElementById("flashcard-anchor")
                  ?.scrollIntoView({ behavior: "smooth", block: "start" });
              } else if (k === "warmup") {
                document
                  .getElementById("quickquiz-anchor")
                  ?.scrollIntoView({ behavior: "smooth", block: "start" });
              }
            }}
          />

          {/* ─── 4-Question Quick Quiz (warmup) ─── */}
          <div id="quickquiz-anchor" />
          <QuickQuizCard
            language={language}
            onCorrect={() => setQuizCorrect((c) => c + 1)}
          />

          {/* ─── Daily Goal + Weekly Plan ─── */}
          <Card className="bg-zinc-950 border border-[hsl(var(--linguist-gold))]/30 p-4">
            <div className="flex items-center gap-2 mb-4">
              <Target className="w-4 h-4 text-[hsl(var(--linguist-gold))]" />
              <span className="text-sm font-semibold text-zinc-200">Günlük Hedef · Haftalık Plan</span>
              {settings && settings.current_streak > 0 && (
                <Badge className="ml-auto bg-orange-500/15 text-orange-400 border-0 text-[10px] gap-1">
                  <Flame className="w-3 h-3" /> {settings.current_streak} gün
                </Badge>
              )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-[auto_1fr] gap-5 items-center">
              <div className="flex justify-center">
                <GoalRing
                  value={minutesToday}
                  goal={dailyGoal}
                  size={150}
                  label={minutesToday >= dailyGoal ? "Tamamlandı" : "Bugün"}
                />
              </div>
              <div className="space-y-3">
                <WeeklyChart sessions={sessions} goal={dailyGoal} />
                <div>
                  <div className="text-[10px] uppercase tracking-wider text-zinc-500 mb-1.5">
                    Günlük süre hedefi
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {[5, 10, 15, 20, 30, 45, 60].map((m) => (
                      <button
                        key={m}
                        type="button"
                        disabled={academyLoading}
                        onClick={async () => {
                          const r = await saveSettings({ daily_goal_minutes: m });
                          if (r.success) toast.success(`Hedef güncellendi: ${m} dk/gün`);
                        }}
                        className={`px-2.5 py-1 rounded-md border text-xs font-semibold transition-all ${
                          dailyGoal === m
                            ? "border-[hsl(var(--linguist-gold))] bg-[hsl(var(--linguist-gold))]/15 text-[hsl(var(--linguist-gold))]"
                            : "border-zinc-800 text-zinc-400 hover:border-zinc-600"
                        }`}
                      >
                        {m} dk
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </Card>

          {/* ─── Flashcard Deck (TR ↔ NL) ─── */}
          <div id="flashcard-anchor" />
          <FlashcardDeck
            mastered={masteredCount}
            cardStates={cardStates}
            onSwipe={async (card, mastered) => {
              await setCardStatus(card.id, "nl", mastered);
              if (mastered) {
                await recordSession(0, 1);
                toast.success(`✓ ${card.dutch}`);
              }
