/* ───────────── Flashcard Deck ───────────── */
import type { Flashcard as FlashcardType } from "@/data/linguistFlashcards";
import type { FlashcardState } from "@/hooks/useLinguistAcademy";

function FlashcardDeck({
  mastered,
  cardStates,
  onSwipe,
}: {
  mastered: number;
  cardStates: Record<string, FlashcardState>;
  onSwipe: (card: FlashcardType, mastered: boolean) => Promise<void> | void;
}) {
  const [category, setCategory] = useState<"all" | FlashcardType["category"]>("all");
  const [index, setIndex] = useState(0);
  const [shuffleSeed, setShuffleSeed] = useState(0);

  /**
   * Smart prioritization:
   *  1. Cards marked "review" (recently wrong) — highest priority
   *  2. "new" / unseen cards
   *  3. "learning" — being practiced
   *  4. "mastered" — last
   * Within each bucket, cards seen the LEAST repetitions come first.
   * Shuffle seed adds light randomness within ties.
   */
  const deck = useMemo(() => {
    const filtered =
      category === "all" ? TR_NL_DECK : TR_NL_DECK.filter((c) => c.category === category);
    const priority: Record<string, number> = {
      review: 0,
      new: 1,
      learning: 2,
      mastered: 3,
    };
    // Stable random per shuffleSeed
    const rand = (id: string) => {
      let h = shuffleSeed;
      for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) | 0;
      return ((h >>> 0) % 1000) / 1000;
    };
    return [...filtered].sort((a, b) => {
      const sa = cardStates[a.id]?.status ?? "new";
      const sb = cardStates[b.id]?.status ?? "new";
      const pa = priority[sa] ?? 1;
      const pb = priority[sb] ?? 1;
      if (pa !== pb) return pa - pb;
      const ra = cardStates[a.id]?.repetitions ?? 0;
      const rb = cardStates[b.id]?.repetitions ?? 0;
      if (ra !== rb) return ra - rb;
      return rand(a.id) - rand(b.id);
    });
  }, [category, cardStates, shuffleSeed]);

  useEffect(() => {
    setIndex(0);
  }, [category, shuffleSeed]);

  const card = deck[index];
  const total = deck.length;

  return (
    <Card className="bg-zinc-950 border border-[hsl(var(--linguist-purple))]/30 p-4">
      <div className="flex items-center gap-2 mb-3">
        <Layers className="w-4 h-4 text-[hsl(var(--linguist-purple))]" />
        <span className="text-sm font-semibold text-zinc-200">Kart Destesi · TR ↔ NL</span>
        <button
          type="button"
          onClick={() => setShuffleSeed((s) => s + 1 + Math.floor(Math.random() * 9999))}
          className="ml-auto rounded-md p-1 text-[hsl(var(--linguist-purple))] hover:bg-[hsl(var(--linguist-purple))]/15 transition"
          aria-label="Karıştır"
          title="Karıştır"
        >
          <Shuffle className="w-3.5 h-3.5" />
        </button>
        <Badge className="bg-emerald-500/15 text-emerald-400 border-0 text-[10px]">
          {mastered}/{TR_NL_DECK.length} öğrenildi
        </Badge>
      </div>

      <div className="flex gap-1.5 mb-3">
        {(["all", "core", "civic", "constitution"] as const).map((c) => (
          <button
            key={c}
            type="button"
            onClick={() => setCategory(c)}
            className={`px-2.5 py-1 rounded-md border text-[11px] font-semibold capitalize transition-all ${
              category === c
                ? "border-[hsl(var(--linguist-purple))] bg-[hsl(var(--linguist-purple))]/15 text-[hsl(var(--linguist-purple))]"
                : "border-zinc-800 text-zinc-400 hover:border-zinc-600"
            }`}
          >
            {c === "all" ? "Tümü" : c}
          </button>
        ))}
      </div>

      {card ? (
        <>
          <div className="text-[10px] text-zinc-500 text-center mb-2">
            {index + 1} / {total} · sola kaydır = tekrar · sağa = öğrenildi
          </div>
          <Flashcard
            card={card}
            active
            onSwipe={async (dir) => {
              const learned = dir === "right";
              await onSwipe(card, learned);
              setIndex((i) => Math.min(i + 1, total));
            }}
          />
          {index >= total - 1 && (
            <div className="text-center text-xs text-emerald-400 mt-3">
              🎉 Bu kategori tamamlandı — yenisini seç!
            </div>
          )}
        </>
      ) : (
        <div className="text-center text-zinc-500 py-8 text-sm">Kart yok.</div>
      )}
    </Card>
  );
}

