type LoginSearch = { redirect?: string };

export const Route = createFileRoute("/login")({
  component: LoginPage,
  validateSearch: (s: Record<string, unknown>): LoginSearch => ({
    redirect: typeof s.redirect === "string" ? s.redirect : undefined,
  }),
  head: () => ({
    meta: [
      { title: "Sign In – Jiyan Europe" },
      { name: "description", content: "Sign in to Jiyan Europe marketplace." },
    ],
  }),
});

function LoginPage() {
  const { signIn, signUp, user, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const search = Route.useSearch();
  const ssoRedirect = search.redirect && search.redirect.startsWith("/sso/authorize") ? search.redirect : null;

  const [showSeal, setShowSeal] = useState(false);
  const [sealData, setSealData] = useState<{ name: string; avatarUrl: string | null } | null>(null);
  const { registerCurrent } = useTrustedDevices();

  const goAfterAuth = async () => {
    // Register current device (soft binding) and play Sovereign Seal once
    try {
      await registerCurrent();
      const { data: prof } = await supabase
        .from("profiles")
        .select("display_name, avatar_url")
        .eq("user_id", (await supabase.auth.getUser()).data.user?.id ?? "")
        .maybeSingle();
      setSealData({ name: prof?.display_name ?? "Sovereign", avatarUrl: prof?.avatar_url ?? null });
      setShowSeal(true);
      await new Promise((r) => setTimeout(r, 2300));
    } catch {}

    return goAfterAuthInner();
  };

  const goAfterAuthInner = async () => {
    // Only SSO authorization is KYC-gated. Normal app login must open the Hub
    // immediately; otherwise mobile users land on a stale login/KYC screen and
    // browser Back appears to be the only way into the app.
    try {
      const { data } = await supabase.rpc("get_my_kyc_status");
      const row = Array.isArray(data) && data.length > 0 ? data[0] : null;
      const isApproved = row?.kyc_status === "approved";
      if (!isApproved && ssoRedirect) {
        const next = search.redirect && search.redirect.startsWith("/") ? search.redirect : "/";
        // Stash so /kyc can redirect once KYC is completed/approved
        try { sessionStorage.setItem("jiyan_post_kyc_redirect", next); } catch {}
        navigate({ to: "/kyc", replace: true });
        return;
      }
    } catch {
      // If KYC check fails for any reason, fall through to the normal redirect
    }

    if (search.redirect) {
      if (search.redirect.startsWith("/")) {
        window.location.replace(search.redirect);
        return;
      }
    }
    navigate({ to: "/", replace: true });
  };

  const [isSignUp, setIsSignUp] = useState(false);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  // Verification state
  const [needsVerification, setNeedsVerification] = useState(false);
  const [verificationCode, setVerificationCode] = useState("");
  const [verifiedUserId, setVerifiedUserId] = useState<string | null>(null);
  const [verified, setVerified] = useState(false);

  // Premium UX state
  const [showBiometric, setShowBiometric] = useState(false);
  const [showCeremony, setShowCeremony] = useState(false);
  const [ceremonyData, setCeremonyData] = useState<{ name: string; kurdId: string } | null>(null);
  const { verify: verifyBiometric, supported: biometricSupported } = useBiometric();
  const autoPromptedRef = useRef(false);
  const [biometricEnabled, setBiometricEnabled] = useState(false);

  // Kurd-ID lookup panel state
  const [showKurdIdPanel, setShowKurdIdPanel] = useState(false);
  const [kurdIdInput, setKurdIdInput] = useState("");
  const [kurdIdError, setKurdIdError] = useState("");
  const [kurdIdLookingUp, setKurdIdLookingUp] = useState(false);
  const [kurdIdMatch, setKurdIdMatch] = useState<{ username: string; display_name: string; avatar_url: string | null; auth_provider: string } | null>(null);

  // Visibility tracking — show a floating shortcut whenever the primary
  // Kurd-ID button scrolls out of the viewport so it's always reachable.
  const kurdIdButtonRef = useRef<HTMLButtonElement>(null);
  const [kurdIdButtonVisible, setKurdIdButtonVisible] = useState(true);

  // Recovery affordances
  const [showSeedRecovery, setShowSeedRecovery] = useState(false);
  const [forgotLoading, setForgotLoading] = useState(false);

  // Gmail-style multi-step e-posta akışı (signin/signup/forgot). Tüm
  // "Kullanıcı adı + şifre" / "Hesap oluştur" CTA'ları bu modal'ı açar —
  // ana sayfa Apple-temiz 3 buton görünümünde kalır.
  const [emailAuth, setEmailAuth] = useState<{ open: boolean; mode: "signin" | "signup" }>({
    open: false,
    mode: "signin",
  });
  const openEmailAuth = (mode: "signin" | "signup" = "signin") => setEmailAuth({ open: true, mode });

  // ── Unified Sovereign Entry ────────────────────────────────────────
  // The single golden "Jiyan ID ile Giriş Yap" button drives this state.
  // Routing logic: 1) try silent passkey 2) trusted device → biometric
  // 3) fall back to the SovereignSheet (Kurd-ID / Google / Apple / Şifre).
  const [showSovereignSheet, setShowSovereignSheet] = useState(false);
  const [showJiyanIdSheet, setShowJiyanIdSheet] = useState(false);
  const [showFaceIDSuccess, setShowFaceIDSuccess] = useState(false);
  const [sovereignBusy, setSovereignBusy] = useState(false);
  const { isSupported: passkeySupported, hasPasskeys, authenticate: authPasskey } = usePasskeys();

  // FaceID success → after burst plays, run goAfterAuth
  useEffect(() => {
    if (!showFaceIDSuccess) return;
    const t = setTimeout(() => {
      setShowFaceIDSuccess(false);
      void goAfterAuth();
    }, 1100);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showFaceIDSuccess]);

  useEffect(() => {
    if (authLoading || !user) return;
    const isOAuthReturn =
      typeof window !== "undefined" &&
      (window.location.search.includes("code=") || window.location.hash.includes("access_token"));
    if (!isOAuthReturn) return;
    try {
      sessionStorage.setItem("jiyan_discovery_seen_v1", "1");
      sessionStorage.setItem("jiyan_boot_splash_seen_v1", "1");
      localStorage.setItem("jiyan_tour_completed_v1", "1");
    } catch {}
    void goAfterAuth();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authLoading, user]);

  const handleForgotPassword = async () => {
    setError("");
    setSuccess("");
    if (!username.trim()) {
      setError("Önce kullanıcı adını gir, sonra 'Şifremi Unuttum'a bas");
      const el = document.getElementById("login-username") as HTMLInputElement | null;
      el?.focus();
      return;
    }
    setForgotLoading(true);
    try {
      const { error: resetErr } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: `${window.location.origin}/reset-password`,
      });
      if (resetErr) throw resetErr;
      // Faz B: Kullanıcı bir sonraki girişte Deng Support inbox'ında da
      // şifre sıfırlama bilgilendirmesini görecek (sistem bot trigger).
      setSuccess(
        `Şifre sıfırlama bağlantısı gönderildi. Deng → Mail (Bot Inbox) sekmesinden de takip edebilirsin.`
      );
    } catch (e: any) {
      setError(e.message || "Bağlantı gönderilemedi");
    } finally {
      setForgotLoading(false);
    }
  };

  useEffect(() => {
    const el = kurdIdButtonRef.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    const obs = new IntersectionObserver(
      ([entry]) => setKurdIdButtonVisible(entry.isIntersecting),
      { threshold: 0.4 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  const openKurdIdPanel = () => {
    setError("");
    setSuccess("");
    setKurdIdError("");
    setKurdIdMatch(null);
    setShowKurdIdPanel(true);
    setIsSignUp(false);
    setTimeout(() => {
      const el = document.getElementById("kurd-id-input") as HTMLInputElement | null;
      if (el) {
        el.scrollIntoView({ behavior: "smooth", block: "center" });
        el.focus();
      }
    }, 100);
