  // Apple-style: auto-prompt biometric on mount if enabled & user already authenticated
  useEffect(() => {
    const flag = readBiometricFlag();
    setBiometricEnabled(flag.enabled);
    if (autoPromptedRef.current) return;
    if (!flag.enabled) return;
    if (!user) return; // Need a session to fast-jump to dashboard
    if (flag.userId && flag.userId !== user.id) return;
