   * + has registered Yaşam Anahtarı), then biometric if a trusted device
   * binding exists, then opens the SovereignSheet for everything else.
   * Always finishes with the FaceID-style success animation.
   */
  const handleSovereignEntry = async () => {
    setError("");
    setSuccess("");

    // 1) Already authed + has passkey → silent step-up, then jump.
    if (user && hasPasskeys && passkeySupported) {
      setSovereignBusy(true);
      try {
        const ok = await authPasskey(15);
        if (ok) {
          setShowFaceIDSuccess(true);
          return;
        }
      } finally {
        setSovereignBusy(false);
      }
    }

    // 2) Already authed + biometric enrolled → fast Face/Touch unlock.
    if (user && biometricEnabled) {
      setShowBiometric(true);
      return;
    }

    // 3) No silent path — open the Google-style Jiyan ID sheet.
    setShowJiyanIdSheet(true);
  };

  /** JiyanIdSheet "Sonraki" — identifier'ı parse edip uygun akışa yönlendir. */
  const handleJiyanIdNext = (raw: string) => {
    const id = raw.trim();
    if (!id) return;
    setShowJiyanIdSheet(false);

    // +777 1234 5678 → Kurd-ID lookup paneli
    if (/^\+?777/.test(id) || /^\d{4}\s?\d{4}$/.test(id.replace(/\s/g, ""))) {
      setKurdIdInput(id.replace(/^\+?777/, "").trim());
      openKurdIdPanel();
      return;
    }
    // @jiyan.world veya kullanıcı adı → şifre formuna yönlendir
    const uname = id.replace(/@jiyan\.world$/i, "").replace(/^@/, "");
    setUsername(uname);
    focusCredentials();
  };


  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    if (!username.trim()) {
      setError("Kullanıcı adı gerekli");
      return;
    }
    if (isSignUp && !acceptedTerms) {
      setError("Devam etmek için Kullanım Koşullarını ve Gizlilik Politikasını kabul etmelisiniz");
      return;
    }
    setLoading(true);

    try {
      if (isSignUp) {
        const result = await signUp(email, password, displayName || username);
        const userId = result.user?.id;
        if (userId) {
          // Record GDPR-required legal acceptance
          try {
            await supabase.from("terms_acceptances").insert([
              { user_id: userId, document_type: "terms" },
              { user_id: userId, document_type: "privacy" },
            ]);
          } catch {}

          // Redeem referral code if present in URL
          try {
            const refCode = new URLSearchParams(window.location.search).get("ref")
              || localStorage.getItem("jiyan_ref_code");
            if (refCode) {
              await supabase.rpc("redeem_referral", { _referred_id: userId, _code: refCode });
              localStorage.removeItem("jiyan_ref_code");
            }
          } catch {}

          // Fetch the auto-generated Kurd-ID for the cinematic reveal
          let kurdId = "0000 0000";
          try {
            const { data: profile } = await supabase
              .from("profiles")
              .select("kurd_id")
              .eq("user_id", userId)
              .single();
            if (profile?.kurd_id) kurdId = profile.kurd_id;
          } catch {}

          // Trigger cinematic Sovereign Identity ceremony
          setCeremonyData({ name: displayName || username, kurdId });
          setShowCeremony(true);
          return;
        }
      } else {
        const result = await signIn(email, password);
        const userId = result.user?.id;
        if (userId) {
          const { data: profile } = await supabase
            .from("profiles")
            .select("is_verified")
            .eq("user_id", userId)
            .single();

          if (profile?.is_verified) {
            await goAfterAuth();
            return;
          }
          try {
            await supabase.rpc("send_verification_code", {
              _user_id: userId,
              _purpose: "login",
            });
          } catch {}
          setVerifiedUserId(userId);
          setNeedsVerification(true);
        }
      }
    } catch (err: any) {
      const msg = err.message || "Bir hata oluştu";
      if (msg.includes("Invalid login")) {
        setError("E-posta veya şifre hatalı");
      } else if (msg.includes("already registered")) {
        setError("Bu kullanıcı adı zaten kayıtlı");
      } else {
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  // Eski inline form kaldırıldı — artık Gmail-style EmailAuthFlow modal'ı açılır.
  const focusCredentials = (mode: "signin" | "signup" = "signin") => {
    openEmailAuth(mode);
  };

  const handleBiometricLogin = async () => {
    setError("");
    setShowBiometric(true);
  };

  const handleBiometricComplete = async () => {
    setShowBiometric(false);
    if (biometricEnabled && biometricSupported && user) {
      const ok = await verifyBiometric();
      if (!ok) {
        setError("Biyometrik doğrulama başarısız — Şifre ile Giriş Yapın");
        return;
      }
    }
    if (user) {
      await goAfterAuth();
      return;
    }
    setSuccess("Biyometrik doğrulama tamamlandı — kimlik bilgilerinizi girin");
    focusCredentials();
  };

  const handleCorporateLogin = () => {
    setError("");
    setIsSignUp(false);
    setSuccess("Kurumsal/Diplomatik giriş — @jiyan.world hesabınızla devam edin");
    focusCredentials();
  };

  const handleVerify = async () => {
    if (!verifiedUserId || verificationCode.length !== 6) return;
    setLoading(true);
    setError("");

    try {
      const { data, error: rpcError } = await supabase.rpc("verify_code", {
        _user_id: verifiedUserId,
        _code: verificationCode,
        _purpose: isSignUp ? "signup" : "login",
      });

      if (rpcError) throw rpcError;
      const result = data as any;
      if (!result.success) {
        setError(result.error || "Doğrulama başarısız");
        return;
      }

      setVerified(true);
      setSuccess("Hesabınız doğrulandı! ✅");
      setTimeout(() => navigate({ to: "/" }), 1500);
    } catch (err: any) {
      setError(err.message || "Doğrulama hatası");
    } finally {
      setLoading(false);
    }
  };

  const handleResendCode = async () => {
    if (!verifiedUserId) return;
    setLoading(true);
    try {
      await supabase.rpc("send_verification_code", {
        _user_id: verifiedUserId,
        _purpose: isSignUp ? "signup" : "login",
      });
      setSuccess("Yeni kod gönderildi!");
    } catch {
      setError("Kod gönderilemedi");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    setError("");
    const result = await lovable.auth.signInWithOAuth("google", {
      redirect_uri: typeof window !== "undefined" ? window.location.origin : undefined,
    });
    if (result.error) {
      setError(result.error instanceof Error ? result.error.message : "Google ile giriş başarısız");
    }
    if (result.redirected) return;
  };

  const handleAppleSignIn = async () => {
    setError("");
    const result = await lovable.auth.signInWithOAuth("apple", {
      redirect_uri: typeof window !== "undefined" ? window.location.origin : undefined,
    });
    if (result.error) {
      setError(result.error instanceof Error ? result.error.message : "Apple ile giriş başarısız");
    }
    if (result.redirected) return;
  };

  // Verification screen
  if (needsVerification && !verified) {
    return (
      <AppShell>
        <div className="px-4 pt-6">
          <div className="flex flex-col items-center mb-6 mt-8">
            <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-neon/10 mb-4">
              <Shield className="h-8 w-8 text-neon" />
            </div>
            <h1 className="text-xl font-bold text-foreground">Hesap Doğrulama</h1>
            <p className="mt-2 text-sm text-muted-foreground text-center max-w-[280px]">
              Gelen kutunuza 6 haneli bir doğrulama kodu gönderdik. Kodu aşağıya girin.
            </p>
          </div>

          <div className="flex justify-center gap-2 mb-6">
            {Array.from({ length: 6 }).map((_, i) => (
              <input
                key={i}
                type="text"
                inputMode="numeric"
                maxLength={1}
                value={verificationCode[i] || ""}
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/, "");
                  const newCode = verificationCode.split("");
                  newCode[i] = val;
                  setVerificationCode(newCode.join(""));
                  if (val && i < 5) {
                    const next = e.target.nextElementSibling as HTMLInputElement;
                    next?.focus();
                  }
                }}
                onKeyDown={(e) => {
                  if (e.key === "Backspace" && !verificationCode[i] && i > 0) {
                    const prev = (e.target as HTMLInputElement).previousElementSibling as HTMLInputElement;
                    prev?.focus();
                  }
                }}
                className="h-12 w-10 rounded-xl border border-border bg-surface text-center text-lg font-bold text-foreground focus:border-neon focus:outline-none focus:ring-1 focus:ring-neon"
              />
            ))}
          </div>

          {error && (
            <p className="rounded-lg bg-destructive/10 px-3 py-2 text-xs text-destructive mb-3">{error}</p>
          )}
          {success && (
            <p className="rounded-lg bg-neon/10 px-3 py-2 text-xs text-neon mb-3">{success}</p>
          )}

          <Button
            variant="neon"
            size="lg"
            className="w-full"
            disabled={loading || verificationCode.length !== 6}
            onClick={handleVerify}
          >
            {loading ? "Doğrulanıyor..." : "Doğrula"}
          </Button>

          <div className="mt-4 flex items-center justify-between">
            <button onClick={handleResendCode} className="text-xs text-neon hover:underline" disabled={loading}>
              Kodu tekrar gönder
            </button>
            <Link to="/inbox" className="text-xs text-muted-foreground hover:text-neon">
              Gelen Kutusu →
            </Link>
          </div>
        </div>
      </AppShell>
    );
  }

  // Verified success
  if (verified) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center px-4 pt-20">
          <CheckCircle className="h-16 w-16 text-neon mb-4" />
          <h1 className="text-xl font-bold text-foreground">Doğrulandı!</h1>
          <p className="text-sm text-muted-foreground mt-2">Yönlendiriliyorsunuz...</p>
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <BiometricScanner
        open={showBiometric}
        mode="face"
        onCancel={() => setShowBiometric(false)}
        onComplete={handleBiometricComplete}
      />
      {ceremonyData && (
        <SovereignIdentityCeremony
          open={showCeremony}
          displayName={ceremonyData.name}
          kurdId={ceremonyData.kurdId}
          onClose={() => { setShowCeremony(false); void goAfterAuth(); }}
        />
      )}
      {showSeal && sealData && (
        <SovereignSeal
          avatarUrl={sealData.avatarUrl}
          displayName={sealData.name}
          onComplete={() => setShowSeal(false)}
        />
      )}

      <SeedRecoveryDialog open={showSeedRecovery} onOpenChange={setShowSeedRecovery} />

      {/* FaceID-style success — plays after a silent passkey win */}
      <FaceIDSuccess open={showFaceIDSuccess} />

      {/* SovereignSheet — secondary methods (Kurd-ID, Google, Apple, Şifre) */}
      <SovereignSheet
        open={showSovereignSheet}
        onClose={() => setShowSovereignSheet(false)}
        title="Sovereign Giriş"
        subtitle="Egemen kimliğinle bir yöntem seç"
      >
        <button
          onClick={() => { setShowSovereignSheet(false); openKurdIdPanel(); }}
          className="group relative flex h-14 w-full items-center justify-center gap-3 rounded-2xl bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-400 text-sm font-bold text-black shadow-[0_4px_24px_rgba(255,200,60,0.35)] ring-1 ring-amber-500/50 transition-all active:scale-[0.98]"
        >
          <ShieldCheck className="h-5 w-5" strokeWidth={2.4} />
          Kurd-ID Numaran ile Giriş
          <span className="absolute right-4 text-[10px] font-extrabold uppercase tracking-wider text-amber-900">+777</span>
        </button>

        {biometricEnabled && (
          <button
            onClick={() => { setShowSovereignSheet(false); handleBiometricLogin(); }}
            className="flex h-12 w-full items-center justify-center gap-3 rounded-2xl bg-gradient-to-r from-yellow-300 via-amber-200 to-yellow-300 text-sm font-semibold text-black ring-1 ring-yellow-500/40 transition-all active:scale-[0.98]"
          >
            <ScanFace className="h-5 w-5" strokeWidth={2.2} />
            FaceID / Parmak İzi
          </button>
        )}

        <button
          onClick={() => { setShowSovereignSheet(false); handleGoogleSignIn(); }}
          className="flex h-12 w-full items-center justify-center gap-3 rounded-2xl border border-amber-400/20 bg-black/40 text-sm font-medium text-amber-100 hover:bg-black/60 transition-all active:scale-[0.99]"
        >
          <svg className="h-5 w-5" viewBox="0 0 24 24">
            <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4" />
            <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
            <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
            <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
          </svg>
          Google ile devam et
        </button>

        <button
          onClick={() => { setShowSovereignSheet(false); handleAppleSignIn(); }}
          className="flex h-12 w-full items-center justify-center gap-3 rounded-2xl bg-black border border-white/10 text-sm font-medium text-white hover:bg-white/5 transition-all active:scale-[0.99]"
        >
          <svg className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor">
            <path d="M17.05 20.28c-.98.95-2.05.8-3.08.35-1.09-.46-2.09-.48-3.24 0-1.44.62-2.2.44-3.06-.35C2.79 15.25 3.51 7.59 9.05 7.31c1.35.07 2.29.74 3.08.8 1.18-.24 2.31-.93 3.57-.84 1.51.12 2.65.72 3.4 1.8-3.12 1.87-2.38 5.98.48 7.13-.57 1.5-1.31 2.99-2.54 4.09zM12.03 7.25c-.15-2.23 1.66-4.07 3.74-4.25.29 2.58-2.34 4.5-3.74 4.25z"/>
          </svg>
          Apple ile devam et
        </button>

        <button
          onClick={() => { setShowSovereignSheet(false); focusCredentials(); }}
          className="flex h-12 w-full items-center justify-center gap-2 rounded-2xl border border-amber-400/15 bg-transparent text-xs font-medium text-amber-200/70 hover:bg-amber-400/5 transition-all"
        >
          <Mail className="h-4 w-4" />
          Kullanıcı adı + şifre
        </button>

        <button
          onClick={() => { setShowSovereignSheet(false); setShowSeedRecovery(true); }}
          className="flex h-11 w-full items-center justify-center gap-2 rounded-2xl border border-amber-400/15 bg-transparent text-[11px] font-medium text-amber-200/60 hover:text-amber-100 transition-all"
        >
          <Key className="h-3.5 w-3.5" />
          Yaşam Anahtarı (24 kelime) ile Kurtarma
        </button>

        <button
          onClick={() => { setShowSovereignSheet(false); handleCorporateLogin(); }}
          className="flex h-11 w-full items-center justify-center gap-2 rounded-2xl border border-yellow-500/20 bg-gradient-to-r from-yellow-500/5 to-amber-500/5 text-[11px] font-medium text-yellow-300 hover:from-yellow-500/15 transition-all"
        >
          <Briefcase className="h-3.5 w-3.5" />
          Corporate / Diplomatic Login
          <span className="text-[9px] opacity-60">@jiyan.world</span>
        </button>
      </SovereignSheet>

      {/* Google-style Jiyan ID sheet — primary fallback for the gold button */}
      <JiyanIdSheet
        open={showJiyanIdSheet}
        onClose={() => setShowJiyanIdSheet(false)}
        onNext={handleJiyanIdNext}
        onCreate={() => {
          setShowJiyanIdSheet(false);
          openEmailAuth("signup");
        }}
        onRecovery={() => {
          setShowJiyanIdSheet(false);
          setShowSeedRecovery(true);
        }}
        onForgotEmail={() => {
          setShowJiyanIdSheet(false);
          navigate({ to: "/recovery" });
        }}
        onForgotKurdId={() => {
          setShowJiyanIdSheet(false);
          navigate({ to: "/recovery" });
        }}
      />



      {/* Floating Kurd-ID shortcut — appears whenever the primary button
          scrolls out of view, guaranteeing the Kurd-ID CTA is always reachable
          regardless of viewport size or scroll position. */}
      {!kurdIdButtonVisible && !showKurdIdPanel && (
        <button
          onClick={openKurdIdPanel}
          aria-label="Kurd-ID ile giriş yap"
          className="fixed bottom-6 right-4 z-40 flex h-12 items-center gap-2 rounded-full bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-400 px-4 text-xs font-bold text-black shadow-[0_6px_24px_rgba(255,200,60,0.55)] ring-1 ring-amber-500/50 transition-all hover:scale-[1.02] active:scale-[0.98] animate-in fade-in slide-in-from-bottom-4"
        >
          <ShieldCheck className="h-4 w-4" strokeWidth={2.4} />
          Kurd-ID Giriş
          <span className="text-[9px] font-extrabold uppercase tracking-wider text-amber-900">
            +777
          </span>
        </button>
      )}

      <div className="px-4 pt-6">
        <Link to="/" className="flex items-center gap-1 text-sm text-muted-foreground mb-4">
          <ArrowLeft className="h-4 w-4" /> Geri
        </Link>

        {/* SSO context banner — when user came from /sso/authorize */}
        {ssoRedirect && (
          <div className="mb-4 flex items-start gap-2 rounded-xl border border-primary/30 bg-primary/10 p-3">
            <Shield className="mt-0.5 h-4 w-4 flex-shrink-0 text-primary" />
            <div className="text-xs">
              <div className="font-semibold text-foreground">Kurd-ID ile devam ediyorsun</div>
              <div className="mt-0.5 text-muted-foreground">
                Giriş yaptıktan sonra 3. parti uygulamaya yönlendirileceksin.
              </div>
            </div>
          </div>
        )}

        {/* Wordmark — bespoke editorial identity */}
        <div className="relative flex flex-col items-center mb-8 mt-2">
          <div className="absolute -top-6 h-px w-16 bg-gradient-to-r from-transparent via-neon/60 to-transparent" />
          <h1 className="text-[44px] leading-none font-light tracking-[-0.04em] text-foreground">
            Jiyan
          </h1>
          <div className="mt-3 flex items-center gap-2">
            <span className="h-px w-6 bg-border" />
            <p className="text-[10px] font-medium uppercase tracking-[0.32em] text-muted-foreground">
              {ssoRedirect ? "Kurd-ID Login" : isSignUp ? "Sovereign Identity" : "+777 · One Identity"}
            </p>
            <span className="h-px w-6 bg-border" />
          </div>
          <p className="mt-3 max-w-[260px] text-center text-[10.5px] leading-relaxed text-amber-200/55">
            Google · Apple · @jiyan.world · Kurd-ID — hepsi tek <span className="text-amber-200/85 font-semibold">+777</span> kimliğine açılır.
          </p>
        </div>

        {/* ─────────────────────────────────────────────────────────────
            SOVEREIGN ENTRY — Apple-tier unified container
            One frosted-glass card holding 3 stacked actions:
              1) Jiyan ID +777 (primary 3D gold)
              2) Google ile Devam Et
              3) Apple ile Devam Et
            All resolve to the SAME +777 Sovereign Identity (Identity Bridge).
            "Diğer giriş yöntemleri" reveals Kurd-ID, passkey, şifre, kurumsal.
        ───────────────────────────────────────────────────────────── */}
        <div
          className="rounded-[28px] p-4 mb-4 space-y-2.5"
          style={{
            background:
              "linear-gradient(180deg, rgba(22,16,3,0.65) 0%, rgba(6,4,0,0.55) 100%)",
            border: "1px solid rgba(212,175,55,0.28)",
            backdropFilter: "blur(22px) saturate(140%)",
            WebkitBackdropFilter: "blur(22px) saturate(140%)",
            boxShadow:
              "0 20px 60px -20px rgba(0,0,0,0.85), inset 0 1px 0 rgba(253,230,138,0.14), 0 0 50px -25px rgba(245,205,83,0.30)",
          }}
        >
          {/* PRIMARY — 3D Golden Jiyan ID button (+777) */}
          <button
            ref={kurdIdButtonRef}
            onClick={handleSovereignEntry}
            disabled={sovereignBusy}
            aria-label="Jiyan ID ile Giriş Yap"
            className="group relative flex h-16 min-h-[44px] w-full items-center justify-center gap-3 rounded-[22px] bg-gradient-to-br from-amber-300 via-yellow-200 to-amber-500 text-[15px] font-bold text-black shadow-[0_8px_40px_rgba(255,200,60,0.45),inset_0_1px_0_rgba(255,255,255,0.55)] ring-1 ring-amber-500/60 transition-all active:scale-[0.985] overflow-hidden disabled:opacity-70"
          >
            <span className="pointer-events-none absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
            <Sparkles className="h-5 w-5" strokeWidth={2.4} />
            {sovereignBusy ? "Doğrulanıyor..." : "Jiyan ID ile Giriş Yap"}
            <span className="absolute right-5 text-[10px] font-extrabold uppercase tracking-wider text-amber-900/80">
              +777
            </span>
          </button>

          {/* GOOGLE */}
          <button
            onClick={handleGoogleSignIn}
            aria-label="Google ile Devam Et"
            className="flex h-12 w-full items-center justify-center gap-3 rounded-2xl border border-amber-400/20 bg-black/55 text-sm font-medium text-amber-50 hover:bg-black/70 transition-all active:scale-[0.99]"
          >
            <svg className="h-5 w-5" viewBox="0 0 24 24">
              <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4" />
              <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
              <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
              <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
            </svg>
            Google ile Devam Et
          </button>

          {/* APPLE */}
          <button
            onClick={handleAppleSignIn}
            aria-label="Apple ile Devam Et"
            className="flex h-12 w-full items-center justify-center gap-3 rounded-2xl bg-black border border-white/10 text-sm font-medium text-white hover:bg-white/5 transition-all active:scale-[0.99]"
          >
