              {kurdIdMatch && (
                <div className="mt-2 space-y-2">
                  <div className="flex items-center gap-2.5 rounded-lg border border-neon/30 bg-neon/10 p-2">
                    <div className="h-8 w-8 rounded-full overflow-hidden bg-surface flex-shrink-0">
                      {kurdIdMatch.avatar_url ? (
                        <img src={kurdIdMatch.avatar_url} alt="" className="h-full w-full object-cover" />
                      ) : (
                        <div className="flex h-full w-full items-center justify-center text-xs">👤</div>
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-xs font-semibold text-foreground truncate">
                        ✓ {kurdIdMatch.display_name}
                      </div>
                      <div className="text-[10px] font-mono text-muted-foreground truncate">
                        @{kurdIdMatch.username}
                      </div>
                    </div>
                    <CheckCircle className="h-4 w-4 text-neon flex-shrink-0" />
                  </div>
                  {/* Auth-provider hint: tells the user which login method this Kurd-ID was created with */}
                  <p className="text-[10px] text-muted-foreground px-1">
                    {kurdIdMatch.auth_provider === "google" && "Bu hesap Google ile oluşturulmuş — Google ile devam et."}
                    {kurdIdMatch.auth_provider === "apple" && "Bu hesap Apple ile oluşturulmuş — Apple ile devam et."}
                    {(kurdIdMatch.auth_provider === "email" || !["google", "apple"].includes(kurdIdMatch.auth_provider)) &&
                      "Bu hesap şifre ile oluşturulmuş — şifreni gir."}
                  </p>
                </div>
              )}
            </div>

            {/* Action: branches based on auth provider */}
            {kurdIdMatch?.auth_provider === "google" ? (
              <button
                onClick={handleGoogleSignIn}
                className="flex h-12 w-full items-center justify-center gap-3 rounded-xl border border-border bg-surface text-sm font-medium text-foreground transition-all hover:bg-accent active:scale-[0.99]"
              >
                <svg className="h-5 w-5" viewBox="0 0 24 24">
                  <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4" />
                  <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                  <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
                  <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
                </svg>
