                className="flex h-12 w-full items-center justify-center gap-3 rounded-xl bg-black border border-white/10 text-sm font-medium text-white transition-all hover:bg-white/5 active:scale-[0.99]"
              >
                <svg className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M17.05 20.28c-.98.95-2.05.8-3.08.35-1.09-.46-2.09-.48-3.24 0-1.44.62-2.2.44-3.06-.35C2.79 15.25 3.51 7.59 9.05 7.31c1.35.07 2.29.74 3.08.8 1.18-.24 2.31-.93 3.57-.84 1.51.12 2.65.72 3.4 1.8-3.12 1.87-2.38 5.98.48 7.13-.57 1.5-1.31 2.99-2.54 4.09zM12.03 7.25c-.15-2.23 1.66-4.07 3.74-4.25.29 2.58-2.34 4.5-3.74 4.25z" />
                </svg>
                Apple ile Devam Et
              </button>
            ) : (
              <Button
                variant="neon"
                size="lg"
                className="w-full"
                disabled={kurdIdLookingUp || kurdIdInput.replace(/\s/g, "").length !== 8}
                onClick={async () => {
                  setKurdIdError("");
                  setKurdIdMatch(null);
                  const digits = kurdIdInput.replace(/\s/g, "");
                  if (digits.length !== 8) {
                    setKurdIdError("Geçersiz format — +777 sonrası 8 hane girmelisin");
                    return;
                  }
                  const formatted = `+777 ${digits.slice(0, 4)} ${digits.slice(4)}`;
                  setKurdIdLookingUp(true);
                  try {
                    const { data, error: rpcError } = await supabase.rpc("kurdid_public_lookup", {
                      _kurd_id: formatted,
                    });
                    if (rpcError) throw rpcError;
                    const row = Array.isArray(data) && data.length > 0 ? data[0] : null;
                    if (!row || !row.username) {
                      setKurdIdError("Bu Kurd-ID'ye ait kayıtlı bir hesap bulunamadı.");
                      return;
                    }
                    setKurdIdMatch({
                      username: row.username,
                      display_name: row.display_name || row.username,
                      avatar_url: row.avatar_url,
                      auth_provider: row.auth_provider || "email",
                    });
                    setUsername(row.username);
                    // Email accounts → focus password field after match
                    if (!row.auth_provider || row.auth_provider === "email") {
                      setTimeout(() => {
                        const pw = document.querySelector<HTMLInputElement>('input[type="password"]');
                        if (pw) {
                          pw.scrollIntoView({ behavior: "smooth", block: "center" });
                          pw.focus();
                        }
                      }, 150);
                    }
                  } catch (err: any) {
                    setKurdIdError(err.message || "Kurd-ID sorgulanamadı, lütfen tekrar dene.");
                  } finally {
                    setKurdIdLookingUp(false);
                  }
                }}
              >
                {kurdIdLookingUp ? "Aranıyor..." : kurdIdMatch ? "Şifreni Gir →" : "Kurd-ID'yi Doğrula"}
              </Button>
            )}
          </div>
        )}

        {/* Global error/success surface — OAuth or sheet-driven errors. */}
        {(error || success) && (
          <div className="mt-3 space-y-1.5">
            {error && (
              <p className="rounded-lg bg-destructive/10 px-3 py-2 text-xs text-destructive">{error}</p>
            )}
            {success && (
              <p className="rounded-lg bg-neon/10 px-3 py-2 text-xs text-neon">{success}</p>
            )}
          </div>
        )}

        {/* Gmail-style multi-step e-posta giriş/kayıt akışı. */}
        <EmailAuthFlow
          open={emailAuth.open}
          initialMode={emailAuth.mode}
          onClose={() => setEmailAuth((s) => ({ ...s, open: false }))}
          onSuccess={async (uid, mode) => {
            setEmailAuth((s) => ({ ...s, open: false }));
            if (mode === "signup") {
              // Redeem referral if present
              try {
                const refCode =
                  new URLSearchParams(window.location.search).get("ref") ||
                  localStorage.getItem("jiyan_ref_code");
                if (refCode) {
                  await supabase.rpc("redeem_referral", { _referred_id: uid, _code: refCode });
                  localStorage.removeItem("jiyan_ref_code");
                }
              } catch {}
              let kurdId = "0000 0000";
              try {
                const { data: profile } = await supabase
                  .from("profiles")
                  .select("kurd_id, display_name")
                  .eq("user_id", uid)
                  .single();
                if (profile?.kurd_id) kurdId = profile.kurd_id;
                setCeremonyData({ name: profile?.display_name || "Sovereign", kurdId });
                setShowCeremony(true);
              } catch {
                await goAfterAuth();
              }
            } else {
              await goAfterAuth();
            }
          }}
        />


        {/* GDPR / WKO Compliance Footer */}
        <div className="mt-8 mb-4 flex flex-col items-center gap-1.5">
          <div className="flex items-center gap-2 rounded-full border border-border bg-card/50 px-3 py-1.5">
            <Shield className="h-3 w-3 text-green-400" />
            <span className="text-[10px] font-medium uppercase tracking-wider text-muted-foreground">
              Global WKO Privacy Protocols · GDPR-Level
            </span>
          </div>
          <p className="text-[9px] text-muted-foreground/60">
            © 2026 World Kurdism Organization. Tüm Hakları Saklıdır.
          </p>
        </div>
      </div>
    </AppShell>
  );
}

