import { createFileRoute, Link } from "@tanstack/react-router";
import { useEffect, useMemo, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import {
  ChevronDown,
  Pause,
  Play,
  Volume2,
  ArrowLeft,
  RotateCcw,
  ShieldCheck,
  Sparkles,
} from "lucide-react";
import { toast } from "sonner";
import {
  MANIFESTO_STEPS,
  MANIFESTO_THEME,
  MANIFESTO_VERSION,
  MANIFESTO_ORG,
} from "@/data/manifesto";
import { ManifestoVisualEffect } from "@/components/manifesto/VisualEffect";
import { CircularWaveform } from "@/components/manifesto/CircularWaveform";
