import { TemburAtmosphere } from "@/components/manifesto/TemburAtmosphere";
import { SealCeremony } from "@/components/manifesto/SealCeremony";
import { SubtitleStrip } from "@/components/manifesto/SubtitleStrip";
import {
  SoundscapeSettings,
  loadSoundscapePrefs,
  type SoundscapePrefs,
} from "@/components/manifesto/SoundscapeSettings";
import { SovereignStar } from "@/components/keka/SovereignStar";
import { useDengbejTTS } from "@/hooks/useDengbejTTS";
import { useManifestoSeal } from "@/hooks/useManifestoSeal";
import { useAuth } from "@/hooks/useAuth";

export const Route = createFileRoute("/manifesto")({
  component: ManifestoPage,
  head: () => ({
    meta: [
      { title: "WKO Sovereignty Doctrine — 10 Articles of Post-Territorial Sovereignty" },
      {
        name: "description",
        content:
          "The World Kurdish Organization Sovereignty Doctrine — 10 articles: Sovereign ID, DiravCash, Digital Civat, Jiyan, KEKA, Dengbêjism and more. Listen, read and seal.",
      },
      { property: "og:title", content: "WKO Sovereignty Doctrine" },
      {
        property: "og:description",
        content: "Ten articles of post-territorial sovereignty. Read, listen, seal.",
      },
      { property: "og:type", content: "website" },
      { name: "theme-color", content: MANIFESTO_THEME },
    ],
  }),
});

function ManifestoPage() {
  const { t, i18n } = useTranslation();
  const lang = i18n.language?.split("-")[0] ?? "tr";
  const { user } = useAuth();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const sectionRefs = useRef<Array<HTMLElement | null>>([]);
  const [activeStep, setActiveStep] = useState(0);
  const [ambientOn, setAmbientOn] = useState(false);
  const [showSealCeremony, setShowSealCeremony] = useState(false);
  const [soundscape, setSoundscape] = useState<SoundscapePrefs>(() => loadSoundscapePrefs());
  const {
    speak,
    stop,
    status,
    activeKey,
    subtitle,
    progress,
    currentTime,
    duration,
    setSettings,
  } = useDengbejTTS();
  const { isSealed, seal, loading: sealing } = useManifestoSeal();

  // Push the latest soundscape prefs into the TTS engine so the next playback
  // (and the live haptic loop) honours the chosen intensity / haptic switch.
  useEffect(() => {
    setSettings({ intensity: soundscape.intensity, hapticEnabled: soundscape.hapticEnabled });
  }, [soundscape, setSettings]);

  // Track which slide is in view via IntersectionObserver
  useEffect(() => {
    const root = containerRef.current;
    if (!root) return;
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) {
          const idx = Number((visible.target as HTMLElement).dataset.step ?? "0");
          setActiveStep(idx);
        }
      },
      { root, threshold: [0.5, 0.75] },
    );
    sectionRefs.current.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, []);

  // Activate ambient kaval after first scroll into article 1+
  useEffect(() => {
    if (activeStep > 0 && !ambientOn) setAmbientOn(true);
  }, [activeStep, ambientOn]);

  const goTo = (i: number) => {
    sectionRefs.current[i]?.scrollIntoView({ behavior: "smooth" });
  };

  const handleSeal = async () => {
    if (!user) {
      toast.error(t("manifesto.sealLoginRequired"));
      return;
    }
    if (isSealed) {
      toast.info(t("manifesto.sealAlready"));
      setShowSealCeremony(true);
      return;
    }
    const result = await seal();
    if (result.ok) {
      setShowSealCeremony(true);
      toast.success(t("manifesto.sealSuccess"));
    } else if (result.error === "already_sealed") {
      setShowSealCeremony(true);
    } else {
      toast.error(result.error ?? "Error");
    }
  };

  const isPlaying = status === "playing" || status === "loading";

  // Resolve current step's dengbej text for waveform header (purely UX context)
  const currentStepInfo = useMemo(() => {
    if (activeStep < 1 || activeStep > 10) return null;
    return {
      step: activeStep,
      title: t(`manifesto.steps.${activeStep}.title`),
    };
  }, [activeStep, t]);

  return (
    <div className="manifesto-root fixed inset-0 bg-[#0a0705] text-amber-50">
      {/* Ambient kaval drone — quiet bed, only after first article. Scales with intensity. */}
      <AmbientKaval
        active={ambientOn && activeStep >= 1 && activeStep <= 10 && !isPlaying}
        gain={0.05 + soundscape.intensity * 0.18}
      />

      {/* Tembûr + distant wind atmosphere — swells UNDER the dengbêj voice. */}
      <TemburAtmosphere active={isPlaying} gain={0.06 + soundscape.intensity * 0.32} />

      {/* Antique sepia + noise overlay (whole screen) */}
      <div className="manifesto-sepia-overlay pointer-events-none absolute inset-0 z-30" aria-hidden="true" />
      <div className="manifesto-noise-overlay pointer-events-none absolute inset-0 z-30 opacity-[0.07] mix-blend-overlay" aria-hidden="true" />
      <div className="manifesto-vignette pointer-events-none absolute inset-0 z-30" aria-hidden="true" />

      {/* Top bar */}
      <header className="absolute top-0 left-0 right-0 z-40 flex items-center justify-between px-4 py-3 bg-gradient-to-b from-black/80 via-black/40 to-transparent">
        <Link
          to="/"
          className="flex items-center gap-2 text-amber-200 hover:text-amber-100 transition-colors text-sm font-bold"
        >
          <ArrowLeft className="h-4 w-4" />
          <span className="hidden sm:inline">Jiyan.World</span>
        </Link>
        <div className="flex items-center gap-2">
          <SovereignStar size={22} />
          <div className="flex flex-col leading-tight">
            <span className="text-[10px] uppercase tracking-[0.3em] text-amber-300/80 font-bold">
              WKO · v{MANIFESTO_VERSION}
            </span>
          </div>
        </div>
        <div className="text-[11px] tabular-nums text-amber-200/70 font-bold">
          {String(activeStep).padStart(2, "0")} <span className="opacity-50">/ 10</span>
        </div>
      </header>

      {/* Progress dots */}
      <nav
        aria-label="Manifesto articles"
        className="absolute right-3 top-1/2 -translate-y-1/2 z-40 flex flex-col gap-2"
      >
        {[0, ...MANIFESTO_STEPS.map((s) => s.step)].map((i) => (
          <button
            key={i}
            onClick={() => goTo(i)}
            aria-label={`Article ${i}`}
            className={`block rounded-full transition-all duration-300 ${
              activeStep === i
                ? "h-6 w-1.5 bg-amber-300 shadow-[0_0_8px_rgba(255,200,80,0.8)]"
                : "h-1.5 w-1.5 bg-amber-200/30 hover:bg-amber-200/60"
            }`}
          />
        ))}
      </nav>

      {/* Snap-scroll container */}
      <div
        ref={containerRef}
        className="manifesto-snap h-full w-full overflow-y-auto"
      >
        {/* Intro slide */}
        <section
          data-step="0"
          ref={(el) => {
            sectionRefs.current[0] = el;
          }}
          className="manifesto-snap-section relative flex h-screen w-full items-center justify-center px-6"
        >
          <div className="absolute inset-0">
            <ManifestoVisualEffect effect="global_network_glow" />
          </div>
          <div className="relative z-10 max-w-md text-center">
            <SovereignStar size={88} glow className="mx-auto mb-6" />
            <p className="text-[10px] font-bold uppercase tracking-[0.4em] text-amber-300/80">
              {MANIFESTO_ORG}
            </p>
            <h1 className="mt-3 text-4xl sm:text-5xl font-black tracking-tight text-glow-gold">
              {t("manifesto.title")}
            </h1>
            <p className="mt-4 text-base text-amber-100/85 font-medium">
              {t("manifesto.subtitle")}
            </p>
            <p className="mt-6 text-sm text-amber-200/70 italic">
              "{t("manifesto.intro")}"
            </p>
            <button
              onClick={() => goTo(1)}
              className="mt-10 inline-flex items-center gap-2 rounded-full border border-amber-300/40 bg-amber-300/10 px-6 py-3 text-sm font-bold uppercase tracking-widest text-amber-100 transition-all hover:bg-amber-300/20 hover:border-amber-300/70 active:scale-95"
            >
              {t("manifesto.scrollHint")}
              <ChevronDown className="h-4 w-4 animate-bounce" />
            </button>
            <p className="mt-8 text-[10px] font-bold uppercase tracking-[0.3em] text-amber-200/40">
              {t("manifesto.publishedBy")}
            </p>
          </div>
        </section>

        {/* 10 articles */}
        {MANIFESTO_STEPS.map(({ step, visual_effect }) => {
          const key = `step-${step}`;
          const isActive = activeStep === step;
          const isPlayingThis =
            activeKey === key && (status === "playing" || status === "loading");
          const dengbej = t(`manifesto.steps.${step}.dengbej`);
          const summary = t(`manifesto.steps.${step}.summary`);
          const isLast = step === 10;
          return (
            <section
              key={step}
              data-step={step}
              ref={(el) => {
                sectionRefs.current[step] = el;
              }}
              className="manifesto-snap-section relative flex h-screen w-full items-center justify-center px-5"
            >
              {/* Background visual effect */}
              <div
                className={`absolute inset-0 transition-opacity duration-700 ${
                  isActive ? "opacity-100" : "opacity-30"
                }`}
              >
                <ManifestoVisualEffect effect={visual_effect} />
                <div className="absolute inset-0 bg-gradient-to-t from-black via-black/55 to-black/20" />
              </div>

              {/* Card */}
              <div
                className={`relative z-10 w-full max-w-md rounded-3xl border border-amber-300/25 bg-black/55 backdrop-blur-xl p-6 sm:p-8 shadow-[0_20px_60px_-20px_rgba(212,175,55,0.6)] transition-all duration-700 ${
                  isActive ? "translate-y-0 opacity-100" : "translate-y-4 opacity-80"
                }`}
              >
                <div className="flex items-center justify-between">
                  <span className="text-[10px] font-black uppercase tracking-[0.35em] text-amber-300/90">
                    {t("manifesto.doctrineLabel")} · {t("manifesto.stepLabel")}{" "}
                    {String(step).padStart(2, "0")}
                    <span className="opacity-50"> {t("manifesto.ofTotal")}</span>
                  </span>
                  <SovereignStar size={26} />
                </div>
                <h2 className="mt-4 text-2xl sm:text-3xl font-black tracking-tight text-glow-gold leading-tight">
                  {t(`manifesto.steps.${step}.title`)}
                </h2>
                <p className="mt-2 text-xs sm:text-sm font-bold uppercase tracking-widest text-amber-300/85">
                  {t(`manifesto.steps.${step}.subtitle`)}
                </p>
                <div className="my-4 h-px w-12 bg-gradient-to-r from-amber-300 to-transparent" />
                <p className="text-[13px] sm:text-sm text-amber-50/95 leading-relaxed">
                  {t(`manifesto.steps.${step}.summary`)}
                </p>

                {/* Dengbej quote */}
                <blockquote className="mt-4 rounded-2xl border border-amber-200/15 bg-amber-300/[0.04] p-4">
                  <p className="text-[13px] leading-relaxed text-amber-100/85 italic">
                    "{dengbej}"
                  </p>
                </blockquote>

                {/* TTS button */}
                <button
                  onClick={() => speak(summary, key, lang, dengbej)}
                  disabled={status === "loading" && activeKey !== key}
                  className={`mt-4 group flex w-full items-center justify-center gap-2 rounded-full border px-5 py-3 text-sm font-bold uppercase tracking-widest transition-all active:scale-95 ${
                    isPlayingThis
                      ? "border-amber-200 bg-amber-300/30 text-amber-50 shadow-[0_0_24px_rgba(255,200,80,0.5)]"
                      : "border-amber-300/40 bg-amber-300/10 text-amber-100 hover:bg-amber-300/20 hover:border-amber-300/70"
                  }`}
                >
                  {isPlayingThis ? (
                    <>
                      <Pause className="h-4 w-4" />
                      {t("manifesto.ctaPause")}
                    </>
                  ) : status === "loading" && activeKey === key ? (
                    <>
                      <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-amber-200 border-t-transparent" />
                      ...
                    </>
                  ) : (
                    <>
                      <Volume2 className="h-4 w-4" />
                      {t("manifesto.ctaListen")}
                    </>
                  )}
                </button>

                {/* Seal button on last article */}
                {isLast && (
                  <button
                    onClick={handleSeal}
                    disabled={sealing}
                    className={`mt-3 group relative flex w-full items-center justify-center gap-2 rounded-full px-5 py-3.5 text-sm font-black uppercase tracking-widest text-black transition-all active:scale-95 overflow-hidden ${
                      isSealed
                        ? "bg-gradient-to-r from-emerald-300 via-amber-300 to-emerald-300"
                        : "bg-gradient-to-r from-amber-200 via-amber-400 to-amber-600 shadow-[0_0_30px_rgba(212,175,55,0.7)] animate-seal-glow"
                    }`}
                  >
                    {sealing ? (
                      <>
                        <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-black border-t-transparent" />
                        {t("manifesto.ctaSealing")}
                      </>
                    ) : isSealed ? (
                      <>
                        <ShieldCheck className="h-4 w-4" />
                        {t("manifesto.ctaSealed")}
                      </>
                    ) : (
                      <>
                        <Sparkles className="h-4 w-4" />
                        {t("manifesto.ctaSeal")}
                      </>
                    )}
                  </button>
                )}

                {/* Nav buttons */}
                <div className="mt-3 flex justify-between text-xs font-bold uppercase tracking-widest">
                  <button
                    onClick={() => goTo(step - 1)}
                    className="text-amber-200/60 hover:text-amber-100 transition-colors"
                  >
                    ← {t("manifesto.ctaPrev")}
                  </button>
                  <button
                    onClick={() => goTo(step + 1 > 10 ? 0 : step + 1)}
                    className="text-amber-200/60 hover:text-amber-100 transition-colors"
                  >
                    {step === 10 ? (
                      <span className="inline-flex items-center gap-1">
                        <RotateCcw className="h-3 w-3" />
                        {t("manifesto.ctaRestart")}
                      </span>
                    ) : (
                      <>
                        {t("manifesto.ctaNext")} →
                      </>
                    )}
                  </button>
                </div>
              </div>
            </section>
          );
        })}

        {/* Final CTA slide */}
        <section
          data-step={11}
          ref={(el) => {
            sectionRefs.current[11] = el;
          }}
          className="manifesto-snap-section relative flex h-screen w-full items-center justify-center px-6"
        >
          <div className="absolute inset-0">
            <ManifestoVisualEffect effect="vault_opening_light" />
            <div className="absolute inset-0 bg-gradient-to-t from-black via-black/60 to-black/30" />
          </div>
          <div className="relative z-10 max-w-md text-center">
            <SovereignStar size={72} glow className="mx-auto" />
            <p className="mt-6 text-2xl sm:text-3xl font-black tracking-tight text-glow-gold leading-tight">
              {t("manifesto.footer")}
            </p>
            <Link
              to="/login"
              className="mt-8 inline-flex items-center gap-2 rounded-full bg-gradient-to-r from-amber-200 via-amber-400 to-amber-600 px-7 py-3.5 text-sm font-black uppercase tracking-widest text-black shadow-[0_0_30px_rgba(212,175,55,0.6)] transition-all hover:scale-105 active:scale-95"
            >
              <Play className="h-4 w-4 fill-black" />
              {t("manifesto.ctaLanding")}
            </Link>
            <button
              onClick={() => goTo(0)}
              className="mt-4 block w-full text-xs font-bold uppercase tracking-widest text-amber-200/60 hover:text-amber-100 transition-colors"
            >
              <RotateCcw className="inline h-3 w-3 mr-1" />
              {t("manifesto.ctaRestart")}
            </button>
          </div>
        </section>
      </div>

      {/* Floating Circular Waveform — visible while TTS plays */}
      {isPlaying && currentStepInfo && (
        <div className="fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-30 pointer-events-none">
          <CircularWaveform active size={Math.min(360, typeof window !== "undefined" ? window.innerWidth * 0.7 : 280)} />
        </div>
      )}

      {/* Synchronised subtitle strip + progress bar (visible while TTS plays). */}
      <SubtitleStrip
        text={subtitle}
        progress={progress}
        currentTime={currentTime}
        duration={duration}
        visible={isPlaying}
      />

      {/* Soundscape intensity + haptic toggle */}
      <SoundscapeSettings prefs={soundscape} onChange={setSoundscape} />

      {/* Stop button when audio active — sits below the subtitle card. */}
      {status === "playing" && (
        <button
          onClick={stop}
          className="fixed bottom-6 left-1/2 -translate-x-1/2 z-40 flex items-center gap-2 rounded-full bg-amber-300 px-5 py-2.5 text-xs font-black uppercase tracking-widest text-black shadow-[0_0_24px_rgba(255,200,80,0.7)] animate-pulse"
        >
          <Pause className="h-3.5 w-3.5" />
          {t("manifesto.ctaPause")}
        </button>
      )}

      {/* Seal Ceremony modal */}
      <SealCeremony open={showSealCeremony} onClose={() => setShowSealCeremony(false)} />
    </div>
  );
}

