import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { CategoryGrid } from "@/components/home/CategoryGrid";
import { FeaturedServices } from "@/components/home/FeaturedServices";
import { Search, Star, MapPin, Clock, MessageCircle, Phone, ShieldCheck, Crown, Zap, Plus, Send, ChevronRight, Briefcase, ArrowRight, Sparkles } from "lucide-react";
import { useState, useMemo } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useMarketplace, useAvailableProviders, useJobRequests, useSmartSuggestions, createJobRequest, submitBid, aiSearch } from "@/hooks/useMarketplace";
import { createDirectChat } from "@/hooks/useChat";
import { useNavigate } from "@tanstack/react-router";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { AIMatchmaker } from "@/components/marketplace/AIMatchmaker";

const categoryEmojis: Record<string, string> = {
  cleaning: "🧹", plumbing: "🔧", painting: "🎨", barber: "💈",
  electric: "⚡", moving: "🚚", catering: "🍖", tutoring: "📚", general: "🔧",
};
const categoryLabels: Record<string, string> = {
  all: "Tümü", cleaning: "Temizlik", plumbing: "Tesisat", painting: "Boyama",
  electric: "Elektrik", moving: "Nakliyat", barber: "Kuaför", catering: "Catering", tutoring: "Eğitim",
};
const categories = ["all", "cleaning", "plumbing", "painting", "electric", "moving", "barber", "catering", "tutoring"];

export const Route = createFileRoute("/marketplace")({
  component: MarketplacePage,
  head: () => ({
    meta: [
      { title: "Pazar Yeri – Jiyan Europe" },
      { name: "description", content: "Yerel hizmet sağlayıcılarını bulun, anlık müsaitliği görün ve iş ilanı gönderin." },
    ],
  }),
});

function MarketplacePage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState("all");
  const [activeTab, setActiveTab] = useState<"services" | "jobs">("services");
  const [showJobForm, setShowJobForm] = useState(false);
  const [aiSearching, setAiSearching] = useState(false);
  const [aiResults, setAiResults] = useState<any[] | null>(null);

  const filters = useMemo(() => ({
    category: activeCategory,
    search: searchQuery || undefined,
  }), [activeCategory, searchQuery]);

  const { services, loading } = useMarketplace(filters);
  const { providers: availableProviders, loading: availLoading } = useAvailableProviders();
  const { jobs, loading: jobsLoading, refetch: refetchJobs } = useJobRequests(user?.id);
  const { suggestions } = useSmartSuggestions();

  // Category stats
  const categoryStats = useMemo(() => {
    const stats: Record<string, { active: number; available: number; avgPrice: number }> = {};
    services.forEach(s => {
      if (!stats[s.category]) stats[s.category] = { active: 0, available: 0, avgPrice: 0 };
      stats[s.category].active++;
      if (s.is_available) stats[s.category].available++;
      stats[s.category].avgPrice += s.price;
    });
    Object.values(stats).forEach(s => { if (s.active > 0) s.avgPrice = Math.round(s.avgPrice / s.active); });
    return stats;
  }, [services]);

  const handleAiSearch = async () => {
    if (!searchQuery.trim()) return;
    setAiSearching(true);
    try {
      const result = await aiSearch(searchQuery);
      setAiResults(result.services || []);
      toast.success(`${result.services?.length || 0} sonuç bulundu`);
    } catch {
      toast.error("Arama başarısız");
    }
    setAiSearching(false);
  };

  const handleChat = async (providerId: string) => {
    if (!user) { toast.error("Giriş yapın"); return; }
    try {
      const room = await createDirectChat(user.id, providerId);
      navigate({ to: "/chat" });
    } catch { toast.error("Sohbet oluşturulamadı"); }
  };

  const displayServices = aiResults || services;

  return (
    <AppShell>
      <div className="px-4 pt-6 pb-24 space-y-4">
        {/* Header */}
        <div className="flex items-center justify-between">
          <h1 className="text-xl font-bold text-foreground">Pazar Yeri</h1>
          {user && (
            <Button size="sm" className="gap-1 bg-neon text-neon-foreground hover:bg-neon/90" onClick={() => setShowJobForm(true)}>
              <Plus className="h-3.5 w-3.5" /> İş İlanı
            </Button>
          )}
        </div>

        {/* Pazaryeri 2.0 — Escrow + Açık Artırma */}
        <Link
          to="/jobs"
          className="block rounded-2xl border border-neon/30 bg-gradient-to-r from-neon/10 via-neon/5 to-transparent p-4 transition-all hover:border-neon/50 active:scale-[0.99]"
        >
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-neon/15">
              <Briefcase className="h-5 w-5 text-neon" />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="text-sm font-semibold text-foreground flex items-center gap-1.5">
                İş İlanları & Teklifler <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-neon/20 text-neon">YENİ</span>
              </h3>
              <p className="text-[11px] text-muted-foreground mt-0.5">Açık artırma · Escrow ile güvenli ödeme</p>
            </div>
            <ChevronRight className="h-4 w-4 text-neon/60 shrink-0" />
          </div>
        </Link>

        {/* Marka Anlaşmaları — Yaratıcılar için sponsorlu içerik pazarı */}
        <Link
          to="/brand-deals"
          className="block rounded-2xl border border-amber-400/30 bg-gradient-to-r from-amber-400/15 via-amber-400/5 to-transparent p-4 transition-all hover:border-amber-400/50 active:scale-[0.99]"
        >
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-amber-400/15">
              <Sparkles className="h-5 w-5 text-amber-300" />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="text-sm font-semibold text-foreground flex items-center gap-1.5">
                Marka Anlaşmaları <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-amber-400/20 text-amber-200">YARATICI</span>
              </h3>
              <p className="text-[11px] text-muted-foreground mt-0.5">İşletmeler ilan açar · Yaratıcılar başvurur · DC ile öder</p>
            </div>
            <ChevronRight className="h-4 w-4 text-amber-300/60 shrink-0" />
          </div>
        </Link>

        {/* Category Grid */}
        <CategoryGrid />

        {/* Featured Services */}
        <FeaturedServices />

        {/* AI Smart Search */}
        <div className="flex gap-2">
          <div className="flex flex-1 items-center gap-2 rounded-xl border border-border bg-surface px-3">
            <Sparkles className="h-4 w-4 text-neon" />
            <input
              type="text"
              placeholder="Örn: yakınımdaki tesisatçı, ucuz temizlikçi..."
              value={searchQuery}
              onChange={(e) => { setSearchQuery(e.target.value); setAiResults(null); }}
              onKeyDown={(e) => e.key === "Enter" && handleAiSearch()}
              className="h-10 flex-1 bg-transparent text-sm text-foreground placeholder:text-muted-foreground focus:outline-none"
            />
          </div>
          <button
            onClick={handleAiSearch}
            disabled={aiSearching}
            className="flex h-10 w-10 items-center justify-center rounded-xl border border-neon/30 bg-neon/10 text-neon transition-all hover:bg-neon/20 disabled:opacity-50"
          >
            <Search className="h-4 w-4" />
          </button>
        </div>

        {/* Smart Suggestions */}
        {suggestions.length > 0 && (
          <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-none">
            {suggestions.map((s, i) => (
              <button
                key={i}
                onClick={() => { if (s.category) setActiveCategory(s.category); }}
                className="shrink-0 flex items-center gap-2 rounded-xl border border-neon/20 bg-neon/5 px-3 py-2 transition-all hover:bg-neon/10"
              >
                <span className="text-base">{s.icon}</span>
                <span className="text-[11px] font-medium text-foreground whitespace-nowrap">{s.text}</span>
              </button>
            ))}
          </div>
        )}

        {/* AI Matchmaker */}
        <AIMatchmaker />

        {/* Tabs */}
        <div className="flex gap-1 rounded-xl bg-surface p-1">
          {(["services", "jobs"] as const).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 rounded-lg py-2 text-xs font-semibold transition-all ${
                activeTab === tab ? "bg-neon text-neon-foreground" : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {tab === "services" ? "🛠️ Hizmetler" : "📋 İş İlanları"}
            </button>
          ))}
        </div>

        {activeTab === "services" ? (
          <>
            {/* Categories */}
            <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-none">
              {categories.map((cat) => {
                const stats = categoryStats[cat];
                return (
                  <button
                    key={cat}
                    onClick={() => { setActiveCategory(cat); setAiResults(null); }}
                    className={`shrink-0 rounded-xl px-3 py-2 text-xs font-medium transition-all ${
                      activeCategory === cat
                        ? "bg-neon text-neon-foreground glow-neon"
                        : "bg-surface text-muted-foreground border border-border hover:text-foreground"
                    }`}
                  >
                    <div className="flex items-center gap-1.5">
                      <span>{categoryEmojis[cat] || "📦"}</span>
                      <span>{categoryLabels[cat]}</span>
                    </div>
                    {cat !== "all" && stats && (
                      <div className="flex items-center gap-1 mt-0.5 text-[9px] opacity-70">
                        <span>{stats.active} aktif</span>
                        {stats.available > 0 && <span className="text-neon">• {stats.available} müsait</span>}
                      </div>
                    )}
                  </button>
                );
              })}
            </div>

            {/* Live Available Section */}
            {!availLoading && availableProviders.length > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-2">
                  <span className="h-2 w-2 rounded-full bg-neon animate-pulse" />
                  <h2 className="text-sm font-bold text-foreground">Hemen Müsait</h2>
                  <span className="text-[10px] text-muted-foreground">({availableProviders.length})</span>
                </div>
                <div className="flex gap-2.5 overflow-x-auto pb-2 scrollbar-none">
                  {availableProviders.map((s) => (
                    <div key={s.id} className="shrink-0 w-44 rounded-xl border border-neon/20 bg-surface p-3 transition-all hover:border-neon/40">
                      <div className="flex items-center gap-2">
                        <div className="relative">
                          {s.provider?.avatar_url ? (
                            <img src={s.provider.avatar_url} alt="" className="h-10 w-10 rounded-full object-cover" />
                          ) : (
                            <div className="h-10 w-10 rounded-full bg-accent flex items-center justify-center text-sm font-bold text-foreground">
                              {s.provider?.display_name?.charAt(0) || "?"}
                            </div>
                          )}
                          <span className="absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full bg-neon border-2 border-surface" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1">
                            <span className="text-xs font-semibold text-foreground truncate">{s.provider?.display_name}</span>
                            {s.provider?.is_verified && <ShieldCheck className="h-3 w-3 text-neon shrink-0" />}
                          </div>
                          <span className="text-[10px] text-muted-foreground">{categoryLabels[s.category]}</span>
                        </div>
                      </div>
                      <div className="flex items-center gap-2 mt-2 text-[10px]">
                        <div className="flex items-center gap-0.5">
                          <Star className="h-2.5 w-2.5 fill-gold text-gold" />
                          <span className="text-gold font-medium">{s.rating ?? "–"}</span>
                        </div>
                        <span className="text-muted-foreground">•</span>
                        <span className="text-muted-foreground">{s.city}</span>
                      </div>
                      <div className="flex gap-1.5 mt-2">
                        <button onClick={() => handleChat(s.provider_id)} className="flex-1 flex items-center justify-center gap-1 rounded-lg bg-neon/10 py-1.5 text-[10px] font-medium text-neon hover:bg-neon/20">
                          <MessageCircle className="h-3 w-3" /> Sohbet
                        </button>
                        <Link to="/services/$serviceId" params={{ serviceId: s.id }} className="flex-1 flex items-center justify-center gap-1 rounded-lg bg-neon py-1.5 text-[10px] font-medium text-neon-foreground hover:bg-neon/90">
                          <Zap className="h-3 w-3" /> Kirala
                        </Link>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Service List */}
            <div className="space-y-2.5">
              {loading || aiSearching ? (
                <div className="py-12 text-center text-sm text-muted-foreground">
                  {aiSearching ? "🤖 AI araması yapılıyor..." : "Yükleniyor..."}
                </div>
              ) : displayServices.length === 0 ? (
                <div className="py-12 text-center text-sm text-muted-foreground">
                  Hizmet bulunamadı. İlk siz ekleyin!
                </div>
              ) : (
                displayServices.map((service: any) => (
                  <ServiceCard key={service.id} service={service} onChat={handleChat} />
                ))
              )}
            </div>
          </>
        ) : (
          /* Job Requests Tab */
          <div className="space-y-2.5">
            {jobsLoading ? (
              <div className="py-12 text-center text-sm text-muted-foreground">Yükleniyor...</div>
            ) : jobs.length === 0 ? (
              <div className="py-12 text-center space-y-3">
                <Briefcase className="h-10 w-10 mx-auto text-muted-foreground" />
                <p className="text-sm text-muted-foreground">Henüz iş ilanı yok</p>
                {user && (
                  <Button size="sm" className="bg-neon text-neon-foreground" onClick={() => setShowJobForm(true)}>
                    <Plus className="h-3.5 w-3.5 mr-1" /> İlk İlanı Gönder
                  </Button>
                )}
              </div>
            ) : (
              jobs.map((job) => (
                <JobCard key={job.id} job={job} userId={user?.id} onBidSubmit={refetchJobs} />
              ))
            )}
          </div>
        )}

        {/* Job Request Form Dialog */}
        <JobRequestDialog open={showJobForm} onClose={() => setShowJobForm(false)} userId={user?.id} onCreated={refetchJobs} />
      </div>
    </AppShell>
  );
}

function ServiceCard({ service, onChat }: { service: any; onChat: (id: string) => void }) {
  return (
    <div className="rounded-xl border border-border bg-surface p-3 transition-all hover:border-neon/30">
      <div className="flex gap-3">
        <div className="relative">
          {service.provider?.avatar_url ? (
            <img src={service.provider.avatar_url} alt="" className="h-14 w-14 rounded-xl object-cover" />
          ) : (
            <div className="h-14 w-14 rounded-xl bg-accent flex items-center justify-center text-xl">
              {categoryEmojis[service.category] || "🔧"}
            </div>
          )}
          {service.is_available && (
            <span className="absolute -top-1 -right-1 h-3 w-3 rounded-full bg-neon border-2 border-surface" />
          )}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5">
            <h3 className="text-sm font-semibold text-foreground truncate">{service.title}</h3>
            {service.provider?.is_premium && <Crown className="h-3.5 w-3.5 fill-gold text-gold shrink-0" />}
            {service.provider?.is_verified && <ShieldCheck className="h-3.5 w-3.5 text-neon shrink-0" />}
          </div>
          <p className="text-[11px] text-muted-foreground truncate">{service.provider?.display_name || "Anonim"}</p>
          <div className="flex items-center gap-2 mt-1 flex-wrap">
            <div className="flex items-center gap-0.5">
              <Star className="h-3 w-3 fill-gold text-gold" />
              <span className="text-[10px] font-medium text-gold">{service.rating ?? "Yeni"}</span>
              {(service.review_count ?? 0) > 0 && (
                <span className="text-[10px] text-muted-foreground">({service.review_count})</span>
              )}
            </div>
            <div className="flex items-center gap-0.5">
              <MapPin className="h-3 w-3 text-muted-foreground" />
              <span className="text-[10px] text-muted-foreground">{service.city}</span>
            </div>
            <div className="flex items-center gap-0.5">
              <Clock className="h-3 w-3 text-muted-foreground" />
              <span className="text-[10px] text-muted-foreground">{service.response_time_minutes || 30}dk yanıt</span>
            </div>
            {service.completed_jobs > 0 && (
              <span className="text-[10px] text-neon font-medium">{service.completed_jobs} iş tamamlandı</span>
            )}
          </div>
        </div>
        <div className="text-right shrink-0">
          <span className="text-sm font-bold text-neon">€{service.price}</span>
