      onBidSubmit();
    } catch { toast.error("Teklif gönderilemedi"); }
    setSubmitting(false);
  };

  const urgencyColors: Record<string, string> = {
    urgent: "text-destructive bg-destructive/10 border-destructive/30",
    normal: "text-muted-foreground bg-accent border-border",
