    <div className="rounded-xl border border-border bg-surface p-3 space-y-2">
      <div className="flex items-start justify-between">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="text-sm font-semibold text-foreground truncate">{job.title}</h3>
            <span className={`shrink-0 rounded-full px-2 py-0.5 text-[9px] font-medium border ${urgencyColors[job.urgency] || urgencyColors.normal}`}>
              {job.urgency === "urgent" ? "🔴 Acil" : "Normal"}
            </span>
          </div>
          <p className="text-[11px] text-muted-foreground line-clamp-2 mt-0.5">{job.description}</p>
        </div>
        {job.budget && (
          <span className="text-sm font-bold text-neon shrink-0 ml-2">€{job.budget}</span>
        )}
      </div>
      <div className="flex items-center gap-3 text-[10px] text-muted-foreground">
        <span>{categoryEmojis[job.category]} {categoryLabels[job.category]}</span>
        <span><MapPin className="h-2.5 w-2.5 inline" /> {job.city}</span>
        <span className="text-neon font-medium">{job.bid_count || 0} teklif</span>
      </div>
      {userId && userId !== job.user_id && (
        <>
          {!showBid ? (
            <Button size="sm" variant="outline" className="w-full border-neon/30 text-neon hover:bg-neon/10" onClick={() => setShowBid(true)}>
              <Send className="h-3.5 w-3.5 mr-1" /> Teklif Gönder
            </Button>
          ) : (
            <div className="space-y-2 rounded-lg border border-neon/20 bg-neon/5 p-2.5">
              <Input type="number" placeholder="Fiyat (€)" value={bidPrice} onChange={e => setBidPrice(e.target.value)} className="h-8 text-xs" />
              <Textarea placeholder="Mesajınız..." value={bidMsg} onChange={e => setBidMsg(e.target.value)} className="min-h-[50px] text-xs" />
              <div className="flex gap-2">
                <Button size="sm" variant="ghost" className="flex-1 text-xs" onClick={() => setShowBid(false)}>İptal</Button>
                <Button size="sm" className="flex-1 bg-neon text-neon-foreground text-xs" onClick={handleSubmitBid} disabled={submitting}>
                  {submitting ? "..." : "Gönder"}
                </Button>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

function JobRequestDialog({ open, onClose, userId, onCreated }: { open: boolean; onClose: () => void; userId?: string; onCreated: () => void }) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("general");
  const [budget, setBudget] = useState("");
  const [urgency, setUrgency] = useState("normal");
  const [city, setCity] = useState("Arnhem");
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!userId || !title.trim()) return;
    setSubmitting(true);
    try {
      await createJobRequest(userId, {
        title: title.trim(),
        description: description.trim(),
        category,
        budget: budget ? Number(budget) : undefined,
        urgency,
        city,
      });
      toast.success("İş ilanınız yayınlandı!");
      setTitle(""); setDescription(""); setBudget("");
      onClose();
      onCreated();
    } catch { toast.error("İlan oluşturulamadı"); }
    setSubmitting(false);
  };

  return (
    <Dialog open={open} onOpenChange={(o) => { if (!o) onClose(); }}>
      <DialogContent className="bg-surface border-border max-w-sm">
