        </DialogHeader>
        <div className="space-y-3">
          <Input placeholder="Ne arıyorsunuz? Örn: Acil tesisatçı" value={title} onChange={e => setTitle(e.target.value)} className="text-sm" />
          <Textarea placeholder="Detaylı açıklama..." value={description} onChange={e => setDescription(e.target.value)} className="min-h-[70px] text-sm" />
          <div className="grid grid-cols-2 gap-2">
            <select value={category} onChange={e => setCategory(e.target.value)} className="h-9 rounded-md border border-input bg-transparent px-2 text-sm text-foreground">
              {categories.filter(c => c !== "all").map(c => (
                <option key={c} value={c}>{categoryLabels[c]}</option>
              ))}
            </select>
            <Input type="number" placeholder="Bütçe (€)" value={budget} onChange={e => setBudget(e.target.value)} className="text-sm" />
          </div>
          <div className="grid grid-cols-2 gap-2">
            <select value={urgency} onChange={e => setUrgency(e.target.value)} className="h-9 rounded-md border border-input bg-transparent px-2 text-sm text-foreground">
              <option value="normal">Normal</option>
              <option value="urgent">🔴 Acil</option>
            </select>
            <Input placeholder="Şehir" value={city} onChange={e => setCity(e.target.value)} className="text-sm" />
          </div>
          <Button className="w-full bg-neon text-neon-foreground hover:bg-neon/90" onClick={handleSubmit} disabled={submitting || !title.trim()}>
            {submitting ? "Gönderiliyor..." : "İlanı Yayınla"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

