const MIVANKAS_NOTIF_TYPES = [
  "mivankas_request",
  "mivankas_accepted",
  "mivankas_declined",
  "mivankas_cancelled",
  "mivankas_completed",
];

// Shareable deep-link tab — /mivankas?tab=ride opens directly on the Ride filter.
const TAB_VALUES = ["all", "ride", "home", "sofra", "xezine"] as const;
type SahaTab = (typeof TAB_VALUES)[number];

const sahaSearchSchema = z.object({
  tab: fallback(z.enum(TAB_VALUES), "all").default("all"),
  q: fallback(z.string().max(120), "").default(""),
});

// LocalStorage seed for the listings list — instant render when offline / flaky.
const SAHA_CACHE_KEY = "saha:last-listings:v1";

export const Route = createFileRoute("/mivankas")({
  validateSearch: zodValidator(sahaSearchSchema),
  head: () => ({
    meta: [
      { title: "Saha — Onur Ekonomisi · Sovereign Map" },
      {
        name: "description",
        content:
          "Para değil itibar. Ride, Home, Sofra ve Xezîne — Egemenler arasında peer-to-peer paylaşım.",
      },
    ],
  }),
  component: MivankasPage,
});

// Category tabs are owned by the bottom sheet now (Uber-minimal header).

function MivankasPage() {
  const { user, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const search = Route.useSearch();
  // URL is the source of truth — deep links + back button restore tab/query.
  const category: MivankasCategory | "all" = search.tab as SahaTab;
  const query = search.q;

  const setCategory = (next: MivankasCategory | "all") => {
    navigate({
      to: "/mivankas",
      search: { tab: next, q: query },
      replace: true,
    });
  };
  const setQuery = (next: string) => {
    navigate({
      to: "/mivankas",
      search: { tab: category, q: next },
      replace: true,
    });
  };

  const [activeListing, setActiveListing] = useState<MivankasListing | null>(null);
  const [bookingsOpen, setBookingsOpen] = useState(false);
  const [destinationOpen, setDestinationOpen] = useState(false);
  const [serviceSheetOpen, setServiceSheetOpen] = useState(false);
  const [pendingDestination, setPendingDestination] = useState<{
    listing: MivankasListing;
    distanceKm: number | null;
  } | null>(null);
  const [selfLocation, setSelfLocation] = useState<{ lat: number; lng: number } | null>(null);
  /** Discovery radius (km) — controlled by the slider in NearbyDriversSheet.
   *  Applied to nearby map pins for non-Ride categories (Ev / Sofra / Xezîne)
   *  and to the driver list. Ride pins always show globally because moving
   *  cars matter outside the radius too. */
  const [radiusKm, setRadiusKm] = useState<number>(7);
  const [sealBooking, setSealBooking] = useState<MivankasBooking | null>(null);
  const [detailBooking, setDetailBooking] = useState<MivankasBooking | null>(null);

  // Lock home-screen jiggle / dock reorder while user is mid-booking flow.
  useFlowLock(
    !!sealBooking || !!detailBooking || !!activeListing || serviceSheetOpen || destinationOpen,
  );

  const [bookingNotifs, setBookingNotifs] = useState<
    Array<{
      id: string;
      type: string;
      title: string;
      body: string | null;
      reference_id: string | null;
      is_read: boolean;
      created_at: string;
    }>
  >([]);

  const { listings, loading, refresh } = useMivankasListings({ category, query });
  const { bookings, refresh: refreshBookings } = useMivankasMyBookings(user?.id);
  const { requestBooking, updateBookingStatus, sealDeal } = useMivankasActions(
    user?.id,
  );
  const { balance, refetch: refetchWallet } = useWallet(user?.id);
  const edevlet = useEDevletAccess();
  // Recent destinations chip-row removed — minimalist single-bar header.

  // Hydrate from localStorage cache so the user sees content instantly when
  // offline / on a flaky network. Replaced once fresh `listings` arrive.
  const [cachedListings, setCachedListings] = useState<MivankasListing[]>([]);
  useEffect(() => {
    try {
      const raw = localStorage.getItem(SAHA_CACHE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw) as MivankasListing[];
        if (Array.isArray(parsed)) setCachedListings(parsed);
      }
    } catch {
      /* corrupt cache — ignore */
    }
  }, []);
  useEffect(() => {
    if (!listings || listings.length === 0) return;
    try {
      localStorage.setItem(
        SAHA_CACHE_KEY,
        JSON.stringify(listings.slice(0, 60)),
      );
    } catch {
      /* quota / private mode — ignore */
    }
  }, [listings]);

  useEffect(() => {
    if (!authLoading && !user) navigate({ to: "/login" });
  }, [authLoading, user, navigate]);

  // Fetch + realtime-subscribe to mivankas-related notifications
  useEffect(() => {
    if (!user) return;
    const fetchNotifs = async () => {
      const { data } = await supabase
        .from("notifications")
        .select("id,type,title,body,reference_id,is_read,created_at")
        .eq("user_id", user.id)
        .in("type", MIVANKAS_NOTIF_TYPES)
        .order("created_at", { ascending: false })
        .limit(30);
      if (data) {
        setBookingNotifs(
          data as Array<{
            id: string;
            type: string;
            title: string;
            body: string | null;
            reference_id: string | null;
            is_read: boolean;
            created_at: string;
          }>,
        );
      }
    };
    fetchNotifs();

    const channel = supabase
      .channel(`mivankas_notif:${user.id}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "notifications",
          filter: `user_id=eq.${user.id}`,
        },
        (payload) => {
          const n = payload.new as { type: string };
          if (MIVANKAS_NOTIF_TYPES.includes(n.type)) {
            fetchNotifs();
            refreshBookings();
          }
        },
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, refreshBookings]);

  // Realtime: subscribe directly to mivankas_bookings UPDATEs so the
  // pending → accepted → active → completed tracker animates instantly,
  // even before any notification row is inserted.
  useEffect(() => {
    if (!user) return;
    const ch = supabase
      .channel(`mivankas_bookings:live:${user.id}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "mivankas_bookings",
          filter: `host_id=eq.${user.id}`,
        },
        () => refreshBookings(),
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "mivankas_bookings",
          filter: `guest_id=eq.${user.id}`,
        },
        () => refreshBookings(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(ch);
    };
  }, [user, refreshBookings]);

  const unreadNotifCount = bookingNotifs.filter((n) => !n.is_read).length;
  const pendingHostCount = useMemo(
    () =>
      bookings.filter((b) => b.status === "pending" && b.host_id === user?.id).length,
    [bookings, user?.id],
  );
  const totalBadge = pendingHostCount + unreadNotifCount;

  // Mark mivankas notifications read when the panel opens
  useEffect(() => {
    if (!bookingsOpen || !user || unreadNotifCount === 0) return;
    supabase
      .from("notifications")
      .update({ is_read: true })
      .eq("user_id", user.id)
      .in("type", MIVANKAS_NOTIF_TYPES)
      .eq("is_read", false)
      .then(() => {
        setBookingNotifs((prev) => prev.map((n) => ({ ...n, is_read: true })));
      });
  }, [bookingsOpen, user, unreadNotifCount]);

  // Stale-while-revalidate: while the live query is loading and we have nothing
  // yet, fall back to the localStorage cache so the map / carousel stay populated.
  const visibleListings = useMemo(() => {
    if (listings && listings.length > 0) return listings;
    if (loading && cachedListings.length > 0) return cachedListings;
    return listings;
  }, [listings, loading, cachedListings]);

  /** Listings filtered by the current radius slider — applied to map pins for
   *  the *static* categories (Ev / Sofra / Xezîne). Ride is always shown so
   *  drivers moving toward the rider remain visible even outside the radius.
   *  Listings without coordinates always pass (we can't measure distance).
   */
  const radiusFilteredListings = useMemo(() => {
    if (!selfLocation) return visibleListings;
    return visibleListings.filter((l) => {
      if (l.category === "ride") return true;
      if (l.latitude == null || l.longitude == null) return true;
      return haversineKm(selfLocation, { lat: l.latitude, lng: l.longitude }) <= radiusKm;
    });
  }, [visibleListings, selfLocation, radiusKm]);

  const sealReceiver = useMemo(() => {
    if (!sealBooking || !user) return { id: "", name: "" };
    const isHost = sealBooking.host_id === user.id;
    const otherId = isHost ? sealBooking.guest_id : sealBooking.host_id;
    const name = isHost ? "Misafir" : sealBooking.listing?.host_id ? "Host" : "Egemen";
    return { id: otherId, name };
  }, [sealBooking, user]);

  if (authLoading || !user) {
    return (
      <div className="fixed inset-0 bg-[#070709] flex items-center justify-center z-[60]">
        <div className="w-10 h-10 rounded-full border-2 border-amber-400/30 border-t-amber-400 animate-spin" />
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-50 bg-[#070709] text-foreground overflow-hidden">
      {/* Back button removed — Telegram-style global swipe gestures
          (left-edge swipe / pull-down from top) handle close. */}
      {/* === MAP LAYER (full viewport) === */}
      <div className="absolute inset-0">
        <MivankasMap
          listings={radiusFilteredListings}
          onMarkerClick={(l) => setActiveListing(l)}
          onSelfLocation={(lat, lng) => setSelfLocation({ lat, lng })}
          routePreview={
            pendingDestination?.listing.latitude != null &&
            pendingDestination?.listing.longitude != null
              ? {
                  lat: pendingDestination.listing.latitude,
                  lng: pendingDestination.listing.longitude,
                }
              : null
          }
        />
      </div>

      {/* === Subtle top vignette only — keep map breathing === */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-x-0 top-0 h-32 z-[300]"
        style={{
          background:
            "linear-gradient(180deg, rgba(7,7,9,0.55) 0%, rgba(7,7,9,0) 100%)",
        }}
      />

      {/* === HEADER — Single minimalist glass search bar (Uber/Airbnb pure).
            Left padding leaves room for the global FloatingBackButton (44px
            + 12px gutter) so the two never collide on small screens. === */}
      <header
        className="absolute top-0 left-0 right-0 z-[400] safe-top pointer-events-none"
        style={{ paddingTop: "max(env(safe-area-inset-top), 0.75rem)" }}
      >
        <div className="pl-[68px] pr-4 pt-2 pointer-events-auto">
          <button
            type="button"
            onClick={() => setDestinationOpen(true)}
            className="w-full flex items-center gap-3 h-12 px-4 rounded-2xl bg-black/55 backdrop-blur-xl border border-white/10 text-left active:scale-[0.99] transition shadow-[0_4px_20px_rgba(0,0,0,0.35)]"
            aria-label="Nereye?"
          >
            <Search className="w-[18px] h-[18px] text-white/70 shrink-0" />
            <span className="flex-1 min-w-0 text-[14px] font-medium text-white/90 truncate">
              {query ? query : "Nereye? — Where to?"}
            </span>
            {query && (
              <span
                role="button"
                tabIndex={0}
                onClick={(e) => {
                  e.stopPropagation();
                  setQuery("");
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
