                <X className="w-4 h-4" />
              </span>
            )}
          </button>
        </div>
      </header>

      {/* === Floating inbox — only visible when there's something to show === */}
      {totalBadge > 0 && (
        <button
          onClick={() => setBookingsOpen(true)}
          className="absolute z-[400] right-4 h-11 w-11 rounded-full bg-black/65 backdrop-blur-xl border border-amber-400/30 flex items-center justify-center active:scale-95 transition shadow-[0_4px_16px_rgba(0,0,0,0.4)]"
          style={{ top: "calc(env(safe-area-inset-top) + 4.25rem)" }}
          aria-label="Talepler"
        >
          <Inbox className="w-[18px] h-[18px] text-amber-300" />
          <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 rounded-full bg-amber-400 text-[10px] font-bold text-black flex items-center justify-center ring-2 ring-[#070709]">
            {totalBadge > 9 ? "9+" : totalBadge}
          </span>
        </button>
