      {/* === Loading shimmer === */}
      {loading && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[350]">
          <div className="rounded-full bg-black/70 backdrop-blur-xl border border-amber-400/30 px-4 py-2 flex items-center gap-2 shadow-xl">
            <div className="h-3 w-3 rounded-full border-2 border-amber-300/30 border-t-amber-300 animate-spin" />
            <span className="text-[10px] font-mono uppercase tracking-widest text-amber-200">
