            </span>
          </div>
        </div>
      )}

      {/* === Empty state (no listings) === */}
      {!loading && visibleListings.length === 0 && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[350] w-[80%] max-w-xs">
          <div className="rounded-2xl bg-black/75 backdrop-blur-xl border border-amber-400/25 p-4 text-center shadow-[0_8px_30px_rgba(0,0,0,0.6)]">
            <div className="mx-auto w-10 h-10 rounded-full bg-amber-400/15 border border-amber-300/40 flex items-center justify-center mb-2">
              <MapPin className="w-4 h-4 text-amber-300" />
