          const note = payment === "cash" ? "[PAY:CASH]" : "[PAY:DC]";
          const id = await requestBooking(l, note);
          if (id) {
            refreshBookings();
            setPendingDestination(null);
            setBookingsOpen(true); // Surface the live tracker immediately
          }
          return id;
        }}
        onMessage={async (l) => {
          if (!user) return;
          const roomId = await createDirectChat(user.id, l.host_id);
          if (roomId) {
            navigate({ to: "/chat", search: { room: roomId } as never });
