          setPendingDestination(null);
          navigate({ to: "/kyc" });
        }}
      />

      {/* Legacy tier picker kept available for advanced flows but no longer
          opened from the nearby list. Wired off — see QuickBookingSheet. */}
      <ServiceCategorySheet
        open={serviceSheetOpen}
        onOpenChange={setServiceSheetOpen}
        destination=""
        approxDistanceKm={null}
        kycVerified={edevlet.isVerified}
        onConfirm={() => setServiceSheetOpen(false)}
        onOpenKyc={() => {
          setServiceSheetOpen(false);
          navigate({ to: "/kyc" });
        }}
      />

      {/* === Tap-to-expand booking detail drawer ===
          Shows listing, price, ETA, Stripe lock state, plus one-tap chat
          and a cancel-with-reason flow. Reason is persisted to
          mivankas_bookings.host_response prefixed with [CANCEL_REASON]. */}
      <BookingDetailsDrawer
        open={!!detailBooking}
        onOpenChange={(v) => !v && setDetailBooking(null)}
        booking={detailBooking}
        currentUserId={user.id}
        distanceKm={
          detailBooking?.listing && selfLocation &&
          detailBooking.listing.latitude != null &&
          detailBooking.listing.longitude != null
            ? haversineKm(selfLocation, {
                lat: detailBooking.listing.latitude,
                lng: detailBooking.listing.longitude,
              })
            : null
        }
        priceDc={Math.max(
          5,
          Math.round((detailBooking?.listing?.capacity ?? 1) * 12),
        )}
        onOpenChat={async (b) => {
          const otherId = b.host_id === user.id ? b.guest_id : b.host_id;
          try {
            const { id } = await createDirectChat(user.id, otherId);
            setDetailBooking(null);
            setBookingsOpen(false);
            navigate({ to: "/chat", search: { room: id } as never });
          } catch {
            // toast handled inside helper; nothing to do
          }
        }}
        onCancel={async (b, reason) => {
          const isHost = b.host_id === user.id;
          const newStatus = isHost ? "declined" : "cancelled";
          const { error } = await supabase
            .from("mivankas_bookings")
            .update({
              status: newStatus,
              host_response: `[CANCEL_REASON] ${reason}`,
            })
            .eq("id", b.id);
          if (error) return false;
          await refreshBookings();
          return true;
        }}
      />

      {/* Local toaster so we don't depend on AppShell here */}
      <Toaster position="top-center" richColors />
    </div>
  );
}

/** Haversine distance (km) — duplicated tiny helper to avoid importing the whole search sheet. */
function haversineKm(a: { lat: number; lng: number }, b: { lat: number; lng: number }) {
  const R = 6371;
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
  const lat1 = (a.lat * Math.PI) / 180;
  const lat2 = (b.lat * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.sin(dLng / 2) ** 2 * Math.cos(lat1) * Math.cos(lat2);
  return 2 * R * Math.asin(Math.sqrt(h));
}

