              style={{
                background: "rgba(10,7,1,0.55)",
                border: "0.75px solid rgba(212,175,55,0.18)",
                color: "rgba(255,233,168,0.55)",
              }}
            >
              {synced.length > 0 ? (
                synced.slice(Math.max(0, activeLyricIdx - 2), activeLyricIdx + 5).map((l, i) => {
                  const realIdx = Math.max(0, activeLyricIdx - 2) + i;
                  const active = realIdx === activeLyricIdx;
                  return (
                    <div
                      key={`${l.time}-${i}`}
                      style={{
                        color: active ? "#FFE9A8" : "rgba(255,233,168,0.45)",
                        fontWeight: active ? 600 : 400,
                        transition: "color .25s",
                      }}
                    >
                      {l.text || "♪"}
                    </div>
                  );
                })
              ) : (
                <div className="whitespace-pre-line text-xs">{plainLyrics}</div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Decentralized search (Audius + Piped + LRCLIB) */}
      <div
        className="flex items-center gap-2 rounded-full px-3 py-2"
        style={{
          background: "rgba(20,14,4,0.7)",
          border: "0.75px solid rgba(212,175,55,0.35)",
        }}
      >
        <Search className="h-4 w-4" style={{ color: "#d4af37" }} />
        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Audius + Piped'da ara…"
          className="flex-1 bg-transparent outline-none text-sm placeholder:text-amber-200/40"
          style={{ color: "#FFE9A8" }}
        />
        {searching && <Loader2 className="h-4 w-4 animate-spin text-amber-300" />}
        <Globe className="h-3.5 w-3.5 opacity-60" style={{ color: "#FFE9A8" }} />
      </div>

      {/* Trending strip (Audius) — only when no query */}
      {!results && trending.length > 0 && (
        <div className="space-y-2">
          <div className="text-[10px] uppercase tracking-[0.22em]" style={{ color: "rgba(255,233,168,0.6)" }}>
            Audius · Trending
          </div>
          <div className="flex gap-3 overflow-x-auto -mx-1 px-1 no-scrollbar">
            {trending.map((t) => (
              <button
                key={t.id}
                onClick={() => void play(t, trending)}
                className="flex-shrink-0 w-28 text-left"
              >
                <div className="h-28 w-28 rounded-xl overflow-hidden bg-amber-950/40 grid place-items-center mb-1.5">
                  {t.cover_url ? (
                    <img src={t.cover_url} alt="" className="h-full w-full object-cover" />
                  ) : (
                    <Music2 className="h-6 w-6 text-amber-400" />
                  )}
                </div>
                <div className="truncate text-xs" style={{ color: "#FFE9A8" }}>{t.title}</div>
                <div className="truncate text-[10px]" style={{ color: "rgba(255,233,168,0.55)" }}>{t.artist}</div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Smart keyword chips */}
      {!results && (
        <div className="flex gap-2 overflow-x-auto -mx-1 px-1 no-scrollbar">
          {SMART_KEYWORDS.map((k) => (
            <button
              key={k.label}
              onClick={() => setQ(k.query)}
              className="flex-shrink-0 px-3 py-1.5 rounded-full text-xs flex items-center gap-1.5"
              style={{
                background: "rgba(212,175,55,0.08)",
                color: "#FFE9A8",
                border: "0.75px solid rgba(212,175,55,0.25)",
              }}
            >
              <span>{k.emoji}</span>
              <span>{k.label}</span>
            </button>
          ))}
        </div>
      )}

      {/* Curated playlists (Spotify-style) */}
      {!results && (
        <section className="space-y-2">
          <div className="flex items-center gap-2">
            <Flame className="h-3.5 w-3.5" style={{ color: "#d4af37" }} />
            <div className="text-[10px] uppercase tracking-[0.22em]" style={{ color: "rgba(255,233,168,0.7)" }}>
              Kürtçe Listeler
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            {CURATED_LISTS.map((l) => (
              <button
                key={l.id}
                onClick={() => void openCurated(l)}
                className="relative aspect-[16/10] rounded-2xl overflow-hidden text-left p-3 flex flex-col justify-end"
                style={{
                  background: l.gradient,
                  border: "0.75px solid rgba(212,175,55,0.35)",
                  boxShadow: "0 12px 30px -16px rgba(0,0,0,0.7)",
                }}
              >
                <Crown className="absolute top-2 right-2 h-3.5 w-3.5 opacity-70" style={{ color: "#FFE9A8" }} />
                <div className="text-sm font-semibold leading-tight" style={{ color: "#FFE9A8" }}>
                  {l.title}
                </div>
                <div className="text-[10px] mt-0.5" style={{ color: "rgba(255,233,168,0.7)" }}>
                  {l.subtitle}
                </div>
              </button>
            ))}
          </div>
        </section>
      )}

      {/* Category cards (library) */}
      {!results && (
        <section className="space-y-2">
          <div className="flex items-center gap-2">
            <Sparkle className="h-3.5 w-3.5" style={{ color: "#d4af37" }} />
            <div className="text-[10px] uppercase tracking-[0.22em]" style={{ color: "rgba(255,233,168,0.7)" }}>
              Kütüphane
            </div>
          </div>
          <div className="grid grid-cols-3 gap-2">
            {CATEGORY_CARDS.map((c) => {
              const active = cat === c.id;
              return (
                <button
                  key={c.id}
                  onClick={() => setCat(c.id)}
                  className="relative aspect-square rounded-2xl overflow-hidden flex flex-col items-center justify-center"
                  style={{
                    background: c.gradient,
                    border: active
                      ? "1.25px solid #d4af37"
                      : "0.75px solid rgba(212,175,55,0.25)",
                    boxShadow: active ? "0 0 0 2px rgba(212,175,55,0.35)" : "none",
                  }}
                >
                  <div className="text-2xl">{c.emoji}</div>
                  <div className="text-[11px] font-medium mt-1" style={{ color: "#FFE9A8" }}>
                    {c.label}
                  </div>
                </button>
              );
            })}
          </div>
        </section>
      )}

      {/* Curated list bottom sheet */}
      {openList && (
        <div
          className="fixed inset-0 z-[90] flex items-end"
          style={{ background: "rgba(0,0,0,0.55)" }}
          onClick={() => setOpenList(null)}
        >
          <div
            className="w-full max-h-[82vh] rounded-t-3xl overflow-hidden flex flex-col"
            style={{
              background: "linear-gradient(180deg,#1a1100,#08050a)",
              border: "0.75px solid rgba(212,175,55,0.35)",
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <div
              className="p-4 pb-3 relative"
              style={{ background: openList.gradient }}
            >
              <div className="absolute top-1.5 left-1/2 -translate-x-1/2 h-1 w-10 rounded-full bg-amber-200/60" />
              <div className="text-lg font-semibold" style={{ color: "#FFE9A8" }}>{openList.title}</div>
              <div className="text-[11px]" style={{ color: "rgba(255,233,168,0.75)" }}>{openList.subtitle}</div>
            </div>
            <div className="flex-1 overflow-y-auto p-3 space-y-2">
              {openListLoading ? (
                <div className="grid place-items-center py-10 text-amber-300">
                  <Loader2 className="h-5 w-5 animate-spin" />
                </div>
              ) : openListTracks.length === 0 ? (
                <div className="text-center text-sm py-8" style={{ color: "rgba(255,233,168,0.6)" }}>
                  Şu an sonuç yok.
                </div>
              ) : (
                openListTracks.map((t) => (
                  <button
                    key={t.id}
                    onClick={() => { void play(t, openListTracks); setOpenList(null); }}
                    className="w-full flex items-center gap-3 rounded-xl p-2 text-left"
                    style={{ background: "rgba(20,14,4,0.55)", border: "0.75px solid rgba(212,175,55,0.15)" }}
                  >
                    <div className="h-11 w-11 rounded-lg overflow-hidden bg-amber-950/50 flex-shrink-0">
                      {t.cover_url ? (
                        <img src={t.cover_url} alt="" className="h-full w-full object-cover" />
                      ) : (
                        <Headphones className="h-4 w-4 text-amber-400 m-auto mt-3.5" />
                      )}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="truncate text-sm" style={{ color: "#FFE9A8" }}>{t.title}</div>
                      <div className="truncate text-[11px]" style={{ color: "rgba(255,233,168,0.6)" }}>{t.artist}</div>
                    </div>
                    <Play className="h-4 w-4 text-amber-300/80" />
                  </button>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {/* track list */}
      {loading && !results ? (
        <div className="grid place-items-center py-12 text-amber-300">
          <Loader2 className="h-5 w-5 animate-spin" />
        </div>
      ) : displayList.length === 0 ? (
        <div
          className="rounded-2xl p-6 text-center text-sm"
          style={{
            background: "rgba(20,14,4,0.6)",
            border: "0.75px solid rgba(212,175,55,0.25)",
            color: "rgba(255,233,168,0.7)",
          }}
        >
          <Sparkles className="h-5 w-5 mx-auto mb-2 text-amber-400" />
          {results ? "Sonuç yok." : "Bu kategoride henüz şarkı yok."}
        </div>
      ) : (
        <ul className="space-y-2">
          {displayList.map((t) => {
            const active = track?.id === t.id;
            return (
              <li key={t.id} className="relative pr-9">
                <button
                  onClick={() => void onSelect(t)}
                  className="w-full flex items-center gap-3 rounded-xl p-2.5 text-left"
                  style={{
                    background: active
                      ? "rgba(212,175,55,0.18)"
                      : "rgba(20,14,4,0.55)",
                    border: active
                      ? "0.75px solid rgba(212,175,55,0.55)"
                      : "0.75px solid rgba(212,175,55,0.15)",
                  }}
                >
                  <div className="relative h-11 w-11 rounded-lg overflow-hidden bg-amber-950/50 grid place-items-center flex-shrink-0">
                    {t.cover_url ? (
                      <img
                        src={t.cover_url}
                        alt=""
                        className="h-full w-full object-cover"
                      />
                    ) : (
                      <Headphones className="h-4 w-4 text-amber-400" />
                    )}
                  </div>
                  <div className="min-w-0 flex-1">
                    <div
                      className="truncate text-sm font-medium"
                      style={{ color: "#FFE9A8" }}
                    >
                      {t.title}
                    </div>
                    <div
                      className="truncate text-[11px]"
                      style={{ color: "rgba(255,233,168,0.6)" }}
                    >
                      {t.artist}
                      {t.is_8d && (
                        <span className="ml-2 text-amber-300">· 8D</span>
                      )}
                    </div>
                  </div>
                  {active && isPlaying ? (
                    <Pause className="h-4 w-4 text-amber-300" />
                  ) : (
                    <Play className="h-4 w-4 text-amber-300/80" />
                  )}
                </button>
                <button
                  onClick={(e) => { e.stopPropagation(); void toggleFav(t); }}
                  className="absolute right-2 top-1/2 -translate-y-1/2 h-8 w-8 grid place-items-center rounded-full"
                  style={{ color: isFavorite(t.id) ? "#ff5c7a" : "rgba(255,233,168,0.55)" }}
                  aria-label={isFavorite(t.id) ? "Favorilerden çıkar" : "Favorilere ekle"}
                >
                  <Heart className={`h-3.5 w-3.5 ${isFavorite(t.id) ? "fill-current" : ""}`} />
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

