import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { useAuth } from "@/hooks/useAuth";
import { useNearby } from "@/hooks/useNearby";
import { Button } from "@/components/ui/button";
import {
  MapPin, Users, MessageSquare, CalendarDays, RefreshCw, Shield,
  Crown, BadgeCheck, ArrowLeft, AlertCircle,
} from "lucide-react";
import { useState, useEffect } from "react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { createDirectChat } from "@/hooks/useChat";

export const Route = createFileRoute("/nearby")({
  component: NearbyPage,
  head: () => ({
    meta: [
      { title: "Yakındaki – WKO Sovereign Network" },
      { name: "description", content: "Çevrendeki Kürt vatandaşları, gruplar ve etkinlikleri keşfet." },
    ],
  }),
});

function NearbyPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [profileCity, setProfileCity] = useState<string | null>(null);
  const [isSharing, setIsSharing] = useState<boolean | null>(null);
  const [tab, setTab] = useState<"people" | "groups" | "events">("people");

  useEffect(() => {
    if (!user?.id) return;
    supabase.from("profiles").select("city, location_sharing_enabled")
      .eq("user_id", user.id).maybeSingle()
      .then(({ data }) => {
        setProfileCity(data?.city || null);
        setIsSharing(!!data?.location_sharing_enabled);
      });
  }, [user?.id]);

  const nearby = useNearby(profileCity);

  if (!user) {
    return (
      <AppShell>
        <div className="px-4 pt-20 text-center">
          <MapPin className="h-12 w-12 text-muted-foreground mx-auto mb-3" />
          <p className="text-sm text-muted-foreground mb-4">Yakındaki özelliği için giriş yapmalısın</p>
          <Button asChild><Link to="/login">Giriş Yap</Link></Button>
        </div>
      </AppShell>
    );
  }

  const handleShare = async () => {
    const r = await nearby.shareMyLocation();
    if (r.success) {
      setIsSharing(true);
      toast.success("Konumun paylaşıldı — yakındaki Heval'lar artık seni görebilir");
    } else {
      toast.error(r.error || "Konum paylaşılamadı");
    }
  };

  const handleStopShare = async () => {
    await nearby.stopSharing();
    setIsSharing(false);
    toast.success("Konum paylaşımı durduruldu");
  };

  const handleStartDM = async (otherId: string) => {
    try {
      const { id } = await createDirectChat(user.id, otherId);
      navigate({ to: "/chat", search: { room: id } as any });
    } catch (e: any) {
      toast.error(e.message || "Sohbet başlatılamadı");
    }
  };

  const handleJoinGroup = async (roomId: string) => {
    const { error } = await supabase.from("chat_members")
      .insert({ room_id: roomId, user_id: user.id });
    if (error && !error.message.includes("duplicate")) {
      toast.error("Gruba katılınamadı");
      return;
    }
    toast.success("Gruba katıldın");
    navigate({ to: "/chat", search: { room: roomId } as any });
  };

  return (
    <AppShell>
      <div className="px-4 pt-6 pb-24">
        {/* Header */}
        <div className="flex items-center gap-3 mb-4">
          <Link to="/explore" className="text-muted-foreground"><ArrowLeft className="h-5 w-5" /></Link>
          <div className="flex-1">
            <h1 className="text-xl font-bold text-foreground flex items-center gap-2">
              <MapPin className="h-5 w-5 text-primary" /> Yakındaki
            </h1>
            <p className="text-[11px] text-muted-foreground">Sovereign network around you</p>
          </div>
          <button
            onClick={() => nearby.refresh()}
            className="h-9 w-9 rounded-full bg-surface flex items-center justify-center"
            aria-label="Yenile"
          >
            <RefreshCw className={`h-4 w-4 ${nearby.loading ? "animate-spin" : ""}`} />
          </button>
        </div>

        {/* Permission / Sharing card */}
        {nearby.permissionDenied && !nearby.coords && (
          <div className="mb-4 rounded-xl border border-destructive/30 bg-destructive/5 p-3 flex gap-2 items-start">
            <AlertCircle className="h-4 w-4 text-destructive mt-0.5 shrink-0" />
            <div className="flex-1 text-xs">
              <p className="font-semibold text-foreground mb-1">Konum izni kapalı</p>
              <p className="text-muted-foreground mb-2">Şehir bazlı keşif kullanılıyor. GPS ile daha doğru sonuçlar için izin ver.</p>
              <Button size="sm" variant="outline" onClick={nearby.requestLocation}>İzin Ver</Button>
            </div>
          </div>
        )}

        {nearby.coords && isSharing === false && (
          <div className="mb-4 rounded-xl border border-primary/30 bg-gradient-to-br from-primary/10 to-primary/5 p-3">
            <div className="flex items-center gap-2 mb-2">
              <Shield className="h-4 w-4 text-primary" />
              <p className="text-sm font-semibold text-foreground">Sovereign Görünürlük</p>
            </div>
            <p className="text-xs text-muted-foreground mb-3">
              Konumunu paylaşırsan yakındaki Heval'lar seni keşfedebilir. İstediğin an kapatabilirsin.
            </p>
            <Button size="sm" onClick={handleShare} disabled={nearby.sharing} className="w-full">
              {nearby.sharing ? "Paylaşılıyor..." : "Konumumu Paylaş"}
            </Button>
          </div>
        )}

        {isSharing && (
          <div className="mb-4 rounded-xl border border-primary/30 bg-primary/5 p-2.5 flex items-center justify-between">
            <div className="flex items-center gap-2 text-xs">
              <span className="h-2 w-2 rounded-full bg-primary animate-pulse" />
              <span className="text-foreground font-medium">Konumun aktif paylaşılıyor</span>
            </div>
            <button onClick={handleStopShare} className="text-[11px] text-muted-foreground hover:text-foreground">
              Durdur
            </button>
          </div>
        )}

        {/* Radius slider — only when GPS available */}
        {nearby.coords && (
          <div className="mb-4 rounded-xl bg-surface p-3">
            <div className="flex justify-between text-xs mb-2">
              <span className="text-muted-foreground">Yarıçap</span>
              <span className="text-foreground font-semibold">{nearby.radiusKm} km</span>
            </div>
            <input
              type="range" min={5} max={100} step={5}
              value={nearby.radiusKm}
              onChange={(e) => nearby.setRadiusKm(Number(e.target.value))}
              className="w-full accent-primary"
            />
          </div>
        )}

        {/* Tabs */}
        <div className="flex gap-1 mb-4 rounded-xl bg-surface p-1">
          {([
            { k: "people", label: "Kişiler", icon: Users, count: nearby.users.length },
            { k: "groups", label: "Gruplar", icon: MessageSquare, count: nearby.groups.length },
            { k: "events", label: "Etkinlik", icon: CalendarDays, count: nearby.events.length },
          ] as const).map((t) => (
            <button
              key={t.k}
              onClick={() => setTab(t.k)}
              className={`flex-1 flex items-center justify-center gap-1.5 rounded-lg px-2 py-2 text-xs font-medium transition ${
                tab === t.k ? "bg-primary text-primary-foreground" : "text-muted-foreground"
              }`}
            >
              <t.icon className="h-3.5 w-3.5" />
              {t.label}
              {t.count > 0 && <span className="text-[9px] opacity-80">({t.count})</span>}
            </button>
          ))}
        </div>

        {/* Lists */}
        {tab === "people" && (
          <PeopleList
            users={nearby.users}
            loading={nearby.loading}
            hasGps={!!nearby.coords}
            onMessage={handleStartDM}
          />
        )}
        {tab === "groups" && (
          <GroupsList groups={nearby.groups} loading={nearby.loading} onJoin={handleJoinGroup} />
        )}
        {tab === "events" && (
          <EventsList events={nearby.events} loading={nearby.loading} hasGps={!!nearby.coords} />
        )}
      </div>
    </AppShell>
  );
}

function PeopleList({ users, loading, hasGps, onMessage }: {
  users: ReturnType<typeof useNearby>["users"]; loading: boolean; hasGps: boolean; onMessage: (id: string) => void;
}) {
  if (!hasGps) return <EmptyState icon={MapPin} title="GPS gerekli" body="Yakındaki kişileri görmek için konum iznine ihtiyacımız var." />;
  if (loading) return <p className="py-8 text-center text-sm text-muted-foreground">Yükleniyor...</p>;
  if (users.length === 0) return <EmptyState icon={Users} title="Yakında kimse yok" body="Yarıçapı genişletmeyi dene veya konum paylaşımını aç." />;
  return (
    <div className="space-y-2">
      {users.map((u) => (
        <div key={u.user_id} className="flex items-center gap-3 rounded-xl bg-card border border-border p-3">
          <Link to="/profile" search={{ user: u.user_id } as any} className="shrink-0">
            <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center overflow-hidden">
              {u.avatar_url ? (
                <img src={u.avatar_url} alt={u.display_name} className="h-full w-full object-cover" />
              ) : (
                <span className="text-base font-semibold text-primary">{u.display_name.charAt(0).toUpperCase()}</span>
              )}
            </div>
          </Link>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5">
              <p className="text-sm font-semibold text-foreground truncate">{u.display_name}</p>
              {u.is_premium && <Crown className="h-3 w-3 text-primary shrink-0" />}
              {u.is_verified && <BadgeCheck className="h-3 w-3 text-primary shrink-0" />}
            </div>
            <p className="text-[11px] text-muted-foreground truncate">
              {u.kurd_id || u.username || ""} · {u.distance_km < 1 ? "<1 km" : `${u.distance_km.toFixed(1)} km`} {u.city ? `· ${u.city}` : ""}
            </p>
          </div>
          <Button size="sm" variant="outline" onClick={() => onMessage(u.user_id)}>
            <MessageSquare className="h-3.5 w-3.5 mr-1" /> Mesaj
          </Button>
        </div>
      ))}
    </div>
  );
}

function GroupsList({ groups, loading, onJoin }: {
  groups: ReturnType<typeof useNearby>["groups"]; loading: boolean; onJoin: (id: string) => void;
}) {
  if (loading) return <p className="py-8 text-center text-sm text-muted-foreground">Yükleniyor...</p>;
  if (groups.length === 0) return <EmptyState icon={MessageSquare} title="Yakında grup yok" body="Şehrindeki ilk grubu sen oluştur!" />;
  return (
    <div className="space-y-2">
      {groups.map((g) => (
        <div key={g.room_id} className="flex items-center gap-3 rounded-xl bg-card border border-border p-3">
          <div className="h-12 w-12 rounded-xl bg-primary/15 flex items-center justify-center text-lg shrink-0">
            {g.type === "channel" ? "📢" : "💬"}
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-semibold text-foreground truncate">{g.name || "(Adsız)"}</p>
            <p className="text-[11px] text-muted-foreground truncate">
              {g.member_count} üye {g.city ? `· ${g.city}` : ""}
            </p>
            {g.description && <p className="text-[10px] text-muted-foreground line-clamp-1">{g.description}</p>}
          </div>
          <Button size="sm" onClick={() => onJoin(g.room_id)}>Katıl</Button>
        </div>
      ))}
    </div>
  );
}

function EventsList({ events, loading, hasGps }: {
  events: ReturnType<typeof useNearby>["events"]; loading: boolean; hasGps: boolean;
}) {
  if (!hasGps) return <EmptyState icon={MapPin} title="GPS gerekli" body="Yakındaki etkinlikler için konum izni ver." />;
  if (loading) return <p className="py-8 text-center text-sm text-muted-foreground">Yükleniyor...</p>;
  if (events.length === 0) return <EmptyState icon={CalendarDays} title="Yakında etkinlik yok" body="Çevrende planlanmış etkinlik yok." />;
  return (
    <div className="space-y-2">
      {events.map((e) => (
        <Link key={e.event_id} to="/events/$eventId" params={{ eventId: e.event_id }} className="block rounded-xl bg-card border border-border p-3">
          <p className="text-sm font-semibold text-foreground line-clamp-1">{e.title}</p>
          <p className="text-[11px] text-muted-foreground mt-0.5">
            {new Date(e.starts_at).toLocaleString()} · {e.location || e.city}
            {e.distance_km != null && ` · ${e.distance_km.toFixed(1)} km`}
          </p>
        </Link>
      ))}
    </div>
  );
}

function EmptyState({ icon: Icon, title, body }: { icon: any; title: string; body: string }) {
  return (
    <div className="py-12 text-center">
      <Icon className="h-10 w-10 text-muted-foreground/30 mx-auto mb-2" />
      <p className="text-sm font-semibold text-foreground">{title}</p>
      <p className="text-xs text-muted-foreground mt-1 max-w-xs mx-auto">{body}</p>
    </div>
  );
}

