import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { ArrowLeft, Newspaper, Send, Trash2, Clock, MessageCircle, Share2, BookOpen } from "lucide-react";
import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";
import type { NewsArticle } from "@/hooks/useNews";

interface NewsComment {
  id: string;
  content: string;
  created_at: string;
  user_id: string;
  profile?: { display_name: string; avatar_url: string | null };
}

export const Route = createFileRoute("/news/$articleId")({
  component: NewsDetailPage,
  head: () => ({
    meta: [
      { title: "Haber Detayı – Jiyan Europe" },
      { name: "description", content: "Kurdistan haberleri ve topluluk tartışmaları." },
    ],
  }),
});

function NewsDetailPage() {
  const { articleId } = Route.useParams();
  const { user } = useAuth();
  const [article, setArticle] = useState<NewsArticle | null>(null);
  const [comments, setComments] = useState<NewsComment[]>([]);
  const [newComment, setNewComment] = useState("");
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);

  const fetchArticle = useCallback(async () => {
    const { data } = await supabase
      .from("news_articles")
      .select("*")
      .eq("id", articleId)
      .single();
    if (data) setArticle(data as NewsArticle);
    setLoading(false);
  }, [articleId]);

  const fetchComments = useCallback(async () => {
    const { data } = await supabase
      .from("news_comments" as any)
      .select("*")
      .eq("news_article_id", articleId)
      .order("created_at", { ascending: true });

    if (data) {
      const userIds = [...new Set((data as any[]).map((c: any) => c.user_id))];
      const { data: profiles } = await supabase
        .from("profiles")
        .select("user_id, display_name, avatar_url")
        .in("user_id", userIds);

      const profileMap = new Map(profiles?.map((p) => [p.user_id, p]) || []);
      setComments(
        (data as any[]).map((c: any) => ({
          ...c,
          profile: profileMap.get(c.user_id),
        }))
      );
    }
  }, [articleId]);

  useEffect(() => {
    fetchArticle();
    fetchComments();
  }, [fetchArticle, fetchComments]);

  const handleSendComment = async () => {
    if (!newComment.trim() || !user) return;
    setSending(true);
    const { error } = await supabase
      .from("news_comments" as any)
      .insert({ news_article_id: articleId, user_id: user.id, content: newComment.trim() } as any);

    if (error) {
      toast.error("Yorum gönderilemedi");
    } else {
      setNewComment("");
      fetchComments();
    }
    setSending(false);
  };

  const handleDeleteComment = async (commentId: string) => {
    await supabase.from("news_comments" as any).delete().eq("id", commentId);
    fetchComments();
  };

  const handleShare = async () => {
    const url = typeof window !== "undefined" ? window.location.href : "";
    try {
      if (typeof navigator !== "undefined" && navigator.clipboard) {
        await navigator.clipboard.writeText(url);
        toast.success("Link kopyalandı");
      }
    } catch {
      toast.info("Link kopyalanamadı");
    }
  };

  if (loading) {
    return (
      <AppShell>
        <div className="flex items-center justify-center py-20">
          <div className="h-6 w-6 animate-spin rounded-full border-2 border-neon border-t-transparent" />
        </div>
      </AppShell>
    );
  }

  if (!article) {
    return (
      <AppShell>
        <div className="px-4 pt-6 text-center">
          <p className="text-muted-foreground">Haber bulunamadı</p>
          <Link to="/feed" className="text-neon text-sm mt-2 inline-block">← Feed'e Dön</Link>
        </div>
      </AppShell>
    );
  }

  const date = new Date(article.published_at);
  const formattedDate = date.toLocaleDateString("tr-TR", { day: "numeric", month: "long", year: "numeric" });
  const formattedTime = date.toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" });

  // Determine the main content to show
  const mainContent = article.content || article.summary || null;

  return (
    <AppShell>
      <div className="pb-24">
        {/* Header */}
        <div className="sticky top-0 z-20 bg-background/95 backdrop-blur-sm border-b border-border px-4 py-3">
          <div className="flex items-center gap-3">
            <Link to="/feed" className="flex h-8 w-8 items-center justify-center rounded-lg bg-surface border border-border">
              <ArrowLeft className="h-4 w-4 text-foreground" />
            </Link>
            <h1 className="text-sm font-bold text-foreground truncate flex-1">Haber</h1>
            <button
              onClick={handleShare}
              className="flex h-8 items-center gap-1 rounded-lg bg-neon/10 px-2.5 text-[10px] font-medium text-neon"
            >
              <Share2 className="h-3 w-3" /> Paylaş
            </button>
          </div>
        </div>

        {/* Hero Image */}
        {article.image_url ? (
          <div className="relative w-full">
            <img
              src={article.image_url}
              alt={article.title}
              className="w-full h-56 object-cover"
              loading="eager"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-background via-background/20 to-transparent" />
            <div className="absolute bottom-0 left-0 right-0 px-4 pb-4">
              <h2 className="text-lg font-bold text-foreground leading-tight drop-shadow-lg">{article.title}</h2>
            </div>
          </div>
        ) : (
          <div className="relative w-full h-40 bg-gradient-to-br from-neon/10 via-accent to-gold/10 flex items-center justify-center">
            <Newspaper className="h-16 w-16 text-muted-foreground/20" />
            <div className="absolute bottom-0 left-0 right-0 px-4 pb-4">
              <h2 className="text-lg font-bold text-foreground leading-tight">{article.title}</h2>
            </div>
          </div>
        )}

        {/* Meta Info */}
        <div className="px-4 pt-3 pb-2">
          <div className="flex items-center gap-3 flex-wrap">
            <span className="rounded-full bg-neon/10 px-3 py-1 text-[11px] font-semibold text-neon">
              {article.source}
            </span>
            <div className="flex items-center gap-1 text-[11px] text-muted-foreground">
              <Clock className="h-3 w-3" />
              <span>{formattedDate} • {formattedTime}</span>
            </div>
          </div>
        </div>

        {/* Divider */}
        <div className="mx-4 border-t border-border" />

        {/* Article Content */}
        <div className="px-4 pt-4 pb-2">
          {article.summary && article.content && (
            <p className="text-sm font-medium text-foreground/90 mb-4 leading-relaxed italic border-l-2 border-neon pl-3">
              {article.summary}
            </p>
          )}

          {mainContent && (
            <div className="text-[14px] text-foreground/85 leading-[1.75] whitespace-pre-line">
              {article.content || article.summary}
            </div>
          )}

          {!mainContent && (
            <div className="flex flex-col items-center py-8 text-center">
              <BookOpen className="h-10 w-10 text-muted-foreground/30 mb-2" />
              <p className="text-sm text-muted-foreground">Detaylı içerik henüz mevcut değil.</p>
            </div>
          )}
        </div>

        {/* Source Attribution */}
        <div className="px-4 py-3">
          <div className="flex items-center gap-3 rounded-xl border border-border bg-surface px-4 py-3">
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-neon/10">
              <Newspaper className="h-4 w-4 text-neon" />
            </div>
            <div className="min-w-0 flex-1">
              <p className="text-[10px] text-muted-foreground">Kaynak</p>
              <p className="text-sm font-medium text-foreground">{article.source}</p>
            </div>
          </div>
        </div>

        {/* Comments Section */}
        <div className="px-4 pt-2 pb-4">
          <div className="border-t border-border pt-4">
            <div className="flex items-center gap-1.5 mb-3">
              <MessageCircle className="h-4 w-4 text-neon" />
              <h3 className="text-sm font-bold text-foreground">Tartışma ({comments.length})</h3>
            </div>

            {comments.length === 0 ? (
              <p className="text-xs text-muted-foreground text-center py-4">
                Henüz yorum yok. İlk yorumu sen yap!
              </p>
            ) : (
              <div className="space-y-3">
                {comments.map((comment) => {
                  const commentDate = new Date(comment.created_at);
                  const ago = Math.floor((Date.now() - commentDate.getTime()) / 60000);
                  const agoLabel = ago < 1 ? "Az önce" : ago < 60 ? `${ago}dk` : ago < 1440 ? `${Math.floor(ago / 60)}s` : `${Math.floor(ago / 1440)}g`;

                  return (
                    <div key={comment.id} className="flex gap-2.5 rounded-xl border border-border bg-surface p-2.5">
                      <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-accent overflow-hidden">
                        {comment.profile?.avatar_url ? (
                          <img src={comment.profile.avatar_url} alt="" className="h-8 w-8 rounded-full object-cover" />
                        ) : (
                          <span className="text-xs font-bold text-muted-foreground">
                            {(comment.profile?.display_name || "?")[0].toUpperCase()}
                          </span>
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-[11px] font-semibold text-foreground">
                            {comment.profile?.display_name || "Anonim"}
                          </span>
                          <span className="text-[9px] text-muted-foreground">{agoLabel}</span>
                          {user?.id === comment.user_id && (
                            <button
                              onClick={() => handleDeleteComment(comment.id)}
                              className="ml-auto text-muted-foreground hover:text-destructive"
                            >
                              <Trash2 className="h-3 w-3" />
                            </button>
                          )}
                        </div>
                        <p className="text-xs text-foreground/80 mt-0.5">{comment.content}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Comment Input */}
        {user ? (
          <div className="fixed bottom-16 left-0 right-0 border-t border-border bg-background px-4 py-2.5">
            <div className="flex gap-2">
              <input
                type="text"
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSendComment()}
                placeholder="Yorumunu yaz..."
                className="flex-1 rounded-xl border border-border bg-surface px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:border-neon/50"
              />
              <button
                onClick={handleSendComment}
                disabled={!newComment.trim() || sending}
                className="flex h-9 w-9 items-center justify-center rounded-xl bg-neon text-neon-foreground disabled:opacity-50"
              >
                <Send className="h-4 w-4" />
              </button>
            </div>
          </div>
        ) : (
          <div className="px-4 pb-4 text-center">
            <Link to="/login" className="text-xs text-neon font-medium">Yorum yapmak için giriş yap →</Link>
          </div>
        )}
      </div>
    </AppShell>
  );
}

