import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { useState, useMemo, useCallback } from "react";
import { useNews, useSavedNews, useFavoriteSources, NEWS_SOURCES } from "@/hooks/useNews";
import { useAuth } from "@/hooks/useAuth";
import { Bookmark, BookmarkCheck, RefreshCw, Star, Newspaper, Search, ArrowLeft, Tv } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { tr } from "date-fns/locale";
import { JiyanTVTab } from "@/components/tv/JiyanTVTab";
import { usePullToRefresh } from "@/hooks/usePullToRefresh";
import { PullToRefreshIndicator } from "@/components/PullToRefreshIndicator";

export const Route = createFileRoute("/news/")({
  component: NewsHub,
  head: () => ({
    meta: [
      { title: "Jiyan News – Kürt ve Avrupa Haberleri" },
      { name: "description", content: "Rudaw, ANF ve Kurdistan24'ten anlık Kürt haberleri. Kişiselleştirilmiş haber akışı." },
    ],
  }),
});

type Tab = "all" | "favorites" | "saved";
type Section = "news" | "tv";

function NewsHub() {
  const { user } = useAuth();
  const [section, setSection] = useState<Section>("news");
  const [tab, setTab] = useState<Tab>("all");
  const [activeSource, setActiveSource] = useState<string | null>(null);
  const [search, setSearch] = useState("");

  const { articles, loading, refresh } = useNews({
    source: activeSource ?? undefined,
    favoritesOnly: tab === "favorites",
    userId: user?.id,
  });
  const { savedIds, savedArticles, toggleSave } = useSavedNews(user?.id);
  const { favorites, toggleFavorite } = useFavoriteSources(user?.id);
  const [refreshing, setRefreshing] = useState(false);

  const list = useMemo(() => {
    const base = tab === "saved" ? savedArticles : articles;
    if (!search.trim()) return base;
    const q = search.toLowerCase();
    return base.filter((a) => a.title.toLowerCase().includes(q) || a.summary?.toLowerCase().includes(q));
  }, [tab, savedArticles, articles, search]);

  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    await refresh();
    setRefreshing(false);
  }, [refresh]);

  // Pull-to-refresh — yalnızca News sekmesi aktifken
  const { pullDistance, refreshing: pullRefreshing, threshold } = usePullToRefresh({
    onRefresh: handleRefresh,
    enabled: section === "news",
  });

  return (
    <AppShell>
      <PullToRefreshIndicator
        pullDistance={pullDistance}
        refreshing={pullRefreshing}
        threshold={threshold}
      />
      <div className="bg-black min-h-screen text-foreground">
        {/* Header */}
        <div className="sticky top-0 z-20 bg-black/90 backdrop-blur-xl border-b border-white/5">
          <div className="px-4 pt-5 pb-3">
            <div className="flex items-center justify-between mb-3">
              <Link to="/explore" className="flex items-center gap-2 text-muted-foreground hover:text-foreground">
                <ArrowLeft className="h-4 w-4" />
                <span className="text-xs">Apps</span>
              </Link>
              <button
                onClick={handleRefresh}
                disabled={refreshing}
                className="flex items-center gap-1.5 rounded-full border border-white/10 bg-white/5 px-3 py-1.5 text-[11px] font-medium hover:bg-white/10 disabled:opacity-50"
              >
                <RefreshCw className={`h-3 w-3 ${refreshing ? "animate-spin" : ""}`} />
                Yenile
              </button>
            </div>
            <div className="flex items-center gap-2">
              <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-rose-500 via-red-600 to-orange-600 ring-1 ring-white/15">
                <Newspaper className="h-4 w-4 text-white" strokeWidth={2.5} />
              </div>
              <div>
                <h1 className="text-lg font-bold tracking-tight">Jiyan News</h1>
                <p className="text-[10px] text-muted-foreground">Kürt & Avrupa medyası · Canlı akış</p>
              </div>
            </div>

            {/* Section tabs: Haberler / Jiyan TV */}
            <div className="mt-3 flex gap-1 rounded-xl bg-white/5 border border-white/10 p-1">
              <button
                onClick={() => setSection("news")}
                className={`flex-1 flex items-center justify-center gap-1.5 rounded-lg py-1.5 text-[11px] font-bold transition-all ${
                  section === "news"
                    ? "bg-white text-black shadow-sm"
                    : "text-white/60 hover:text-white"
                }`}
              >
                <Newspaper className="h-3.5 w-3.5" /> Haberler
              </button>
              <button
                onClick={() => setSection("tv")}
                className={`flex-1 flex items-center justify-center gap-1.5 rounded-lg py-1.5 text-[11px] font-bold transition-all ${
                  section === "tv"
                    ? "bg-gradient-to-r from-amber-400 to-orange-500 text-black shadow-sm shadow-amber-500/30"
                    : "text-white/60 hover:text-white"
                }`}
              >
                <Tv className="h-3.5 w-3.5" /> Jiyan TV
                <span className="ml-0.5 text-[8px] font-extrabold px-1 py-0.5 rounded bg-red-500 text-white tracking-wider">LIVE</span>
              </button>
            </div>

            {section === "news" && (
              <>
                {/* Search */}
                <div className="mt-3 flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.04] px-3">
                  <Search className="h-3.5 w-3.5 text-muted-foreground" />
                  <input
                    type="text"
                    placeholder="Haber ara..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    className="h-9 flex-1 bg-transparent text-sm placeholder:text-muted-foreground focus:outline-none"
                  />
                </div>
              </>
            )}

            {section === "news" && (
              <>
                {/* Tabs */}
                <div className="mt-3 flex gap-1.5 -mx-4 px-4 overflow-x-auto scrollbar-hide">
                  {([
                    { id: "all", label: "Tümü" },
                    { id: "favorites", label: "Favorilerim" },
                    { id: "saved", label: `Kaydedilen (${savedIds.size})` },
                  ] as { id: Tab; label: string }[]).map((t) => (
                    <button
                      key={t.id}
                      onClick={() => setTab(t.id)}
                      className={`whitespace-nowrap rounded-full px-3 py-1.5 text-[11px] font-semibold transition-colors ${
                        tab === t.id ? "bg-primary text-primary-foreground" : "bg-white/5 text-muted-foreground hover:bg-white/10"
                      }`}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>

                {/* Source chips */}
                {tab !== "saved" && (
                  <div className="mt-2 flex gap-1.5 -mx-4 px-4 overflow-x-auto scrollbar-hide">
                    <button
                      onClick={() => setActiveSource(null)}
                      className={`whitespace-nowrap rounded-full border px-2.5 py-1 text-[10px] font-medium ${
                        activeSource === null ? "border-primary/50 bg-primary/10 text-primary" : "border-white/10 bg-transparent text-muted-foreground"
                      }`}
                    >
                      Tüm Kaynaklar
                    </button>
                    {NEWS_SOURCES.map((s) => (
                      <div key={s} className="flex items-center gap-1">
                        <button
                          onClick={() => setActiveSource(activeSource === s ? null : s)}
                          className={`whitespace-nowrap rounded-full border px-2.5 py-1 text-[10px] font-medium ${
                            activeSource === s ? "border-primary/50 bg-primary/10 text-primary" : "border-white/10 bg-transparent text-muted-foreground"
                          }`}
                        >
                          {s}
                        </button>
                        {user && (
                          <button
                            onClick={() => toggleFavorite(s)}
                            className="flex h-6 w-6 items-center justify-center rounded-full hover:bg-white/5"
                            aria-label={`${s} favori`}
                          >
                            <Star
                              className={`h-3 w-3 ${favorites.has(s) ? "fill-amber-400 text-amber-400" : "text-muted-foreground"}`}
                            />
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </>
            )}
          </div>
        </div>

        {section === "tv" ? (
          <div className="px-4 py-4">
            <JiyanTVTab />
          </div>
        ) : (
          /* News List */
          <div className="px-4 py-4 space-y-3">
            {loading && list.length === 0 ? (
              <div className="space-y-3">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="h-28 animate-pulse rounded-2xl bg-white/5" />
                ))}
              </div>
            ) : list.length === 0 ? (
              <div className="text-center py-16 text-sm text-muted-foreground">
                {tab === "saved" ? "Henüz haber kaydetmediniz." : tab === "favorites" ? "Önce favori kaynak ekleyin." : "Haber bulunamadı."}
              </div>
            ) : (
              list.map((article) => {
                const isSaved = savedIds.has(article.id);
                return (
                  <article
                    key={article.id}
                    className="group overflow-hidden rounded-2xl border border-white/10 bg-white/[0.03] hover:bg-white/[0.06] transition-colors"
                  >
                    <div className="flex gap-3 p-3">
                      {article.image_url && (
                        <div className="relative h-20 w-20 flex-shrink-0 overflow-hidden rounded-xl bg-white/5">
                          <img
                            src={article.image_url}
                            alt={article.title}
                            loading="lazy"
                            className="h-full w-full object-cover"
                          />
                        </div>
                      )}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="rounded-full bg-primary/15 px-1.5 py-[1px] text-[9px] font-bold text-primary uppercase tracking-wide">
                            {article.source}
                          </span>
                          <span className="text-[10px] text-muted-foreground">
                            {formatDistanceToNow(new Date(article.published_at), { addSuffix: true, locale: tr })}
                          </span>
                        </div>
                        <h3 className="text-[13px] font-semibold leading-snug line-clamp-2">{article.title}</h3>
                        {article.summary && (
                          <p className="mt-1 text-[11px] text-muted-foreground line-clamp-2">{article.summary}</p>
                        )}
                        <div className="mt-2 flex items-center justify-between">
