/**
 * Notifications — unified timeline.
 *
 * All system notifications live in the `notifications` table with a `type`
 * column. Rather than building a separate inbox per source, we group the
 * existing types into 5 user-facing tabs:
 *
 *   • Tümü     — everything
 *   • Mesajlar — type === "message"
 *   • Sosyal   — friend / follow / keka_like / keka_comment
 *   • Sipariş  — booking / mivankas_* / order_*
 *   • Sistem   — kyc / system / premium / payout / *_admin
 *
 * Tabs are derived client-side from the same query so we don't duplicate
 * realtime channels. Unknown types fall into "Sistem" by default.
 */
import { useMemo, useState } from "react";
import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { useAuth } from "@/hooks/useAuth";
import { useNotifications } from "@/hooks/useNotifications";
import {
  Bell,
  Check,
  CheckCheck,
  MessageSquare,
  Users,
  ShoppingBag,
  Settings,
  Sparkles,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export const Route = createFileRoute("/notifications")({
  component: NotificationsPage,
  head: () => ({
    meta: [
      { title: "Bildirimler – Jiyan Europe" },
      { name: "description", content: "Tüm bildirimlerin tek bir yerde." },
    ],
  }),
});

type TabKey = "all" | "messages" | "social" | "orders" | "system";

const TABS: { key: TabKey; label: string; Icon: typeof Bell }[] = [
  { key: "all", label: "Tümü", Icon: Sparkles },
  { key: "messages", label: "Mesaj", Icon: MessageSquare },
  { key: "social", label: "Sosyal", Icon: Users },
  { key: "orders", label: "Sipariş", Icon: ShoppingBag },
  { key: "system", label: "Sistem", Icon: Settings },
];

function categoryOf(type: string): TabKey {
  if (type === "message") return "messages";
  if (
    type === "friend" ||
    type === "follow" ||
    type.startsWith("keka_") ||
    type === "mention" ||
    type === "tip"
  ) {
    return "social";
  }
  if (
    type === "booking" ||
    type.startsWith("mivankas_") ||
    type.startsWith("order") ||
    type === "payout" ||
    type === "escrow"
  ) {
    return "orders";
  }
  return "system";
}

function iconFor(category: TabKey) {
  switch (category) {
    case "messages":
      return MessageSquare;
    case "social":
      return Users;
    case "orders":
      return ShoppingBag;
    case "system":
      return Settings;
    default:
      return Bell;
  }
}

function NotificationsPage() {
  const { user } = useAuth();
  const { notifications, loading, unreadCount, markAsRead, markAllRead } =
    useNotifications(user?.id);
  const [tab, setTab] = useState<TabKey>("all");

  const counts = useMemo(() => {
    const c: Record<TabKey, number> = {
      all: 0,
      messages: 0,
      social: 0,
      orders: 0,
      system: 0,
    };
    for (const n of notifications) {
      if (n.is_read) continue;
      const cat = categoryOf(n.type);
      c.all += 1;
      c[cat] += 1;
    }
    return c;
  }, [notifications]);

  const filtered = useMemo(() => {
    if (tab === "all") return notifications;
    return notifications.filter((n) => categoryOf(n.type) === tab);
  }, [notifications, tab]);

  if (!user) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center px-4 pt-20 text-center">
          <Bell className="h-12 w-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground text-sm mb-4">
            Bildirimleri görmek için giriş yap
          </p>
          <Button variant="neon" asChild>
            <Link to="/login">Giriş Yap</Link>
          </Button>
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <div className="px-4 pt-6">
        <div className="flex items-center justify-between">
          <h1 className="text-xl font-bold text-foreground">Bildirimler</h1>
          {unreadCount > 0 && (
            <button
              onClick={markAllRead}
              className="flex items-center gap-1 text-xs text-neon"
            >
              <CheckCheck className="h-3.5 w-3.5" /> Tümünü okundu işaretle
            </button>
          )}
        </div>

        {/* Tab strip */}
        <div className="mt-4 -mx-4 px-4 overflow-x-auto scrollbar-hide">
          <div className="flex gap-2 pb-1 min-w-max">
            {TABS.map(({ key, label, Icon }) => {
              const active = tab === key;
              const badge = counts[key];
              return (
                <button
                  key={key}
                  onClick={() => setTab(key)}
                  className={cn(
                    "flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-medium transition-all border",
                    active
                      ? "bg-neon/15 text-neon border-neon/40 shadow-[0_0_12px_hsl(var(--neon)/0.3)]"
                      : "bg-surface/40 text-muted-foreground border-border/30 hover:text-foreground"
                  )}
                >
                  <Icon className="h-3.5 w-3.5" />
                  {label}
                  {badge > 0 && (
                    <span
                      className={cn(
                        "ml-0.5 inline-flex h-4 min-w-4 items-center justify-center rounded-full px-1 text-[9px] font-bold",
                        active
                          ? "bg-neon text-background"
                          : "bg-foreground/20 text-foreground"
                      )}
                    >
                      {badge > 99 ? "99+" : badge}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        </div>

        <div className="mt-4 space-y-1 pb-4">
          {loading ? (
            <p className="py-12 text-center text-sm text-muted-foreground">
              Yükleniyor...
            </p>
          ) : filtered.length === 0 ? (
            <div className="py-12 text-center">
              <Bell className="h-10 w-10 text-muted-foreground/30 mx-auto mb-2" />
              <p className="text-sm text-muted-foreground">
                {tab === "all"
                  ? "Henüz bildirim yok"
                  : "Bu kategoride bildirim yok"}
              </p>
            </div>
          ) : (
            filtered.map((n) => {
              const cat = categoryOf(n.type);
              const Icon = iconFor(cat);
              return (
                <button
                  key={n.id}
                  onClick={() => !n.is_read && markAsRead(n.id)}
                  className={cn(
                    "flex w-full items-start gap-3 rounded-xl p-3 text-left transition-all",
                    n.is_read
                      ? "opacity-60"
                      : "bg-neon/5 border border-neon/10"
                  )}
                >
                  <div
                    className={cn(
                      "mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full",
                      n.is_read ? "bg-accent" : "bg-neon/10"
                    )}
                  >
                    <Icon
                      className={cn(
                        "h-3.5 w-3.5",
                        n.is_read ? "text-muted-foreground" : "text-neon"
                      )}
                    />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-foreground">
                      {n.title}
                    </p>
                    {n.body && (
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {n.body}
                      </p>
                    )}
                    <p className="text-[9px] text-muted-foreground mt-1">
                      {new Date(n.created_at).toLocaleString()}
                    </p>
                  </div>
                  {!n.is_read && (
                    <Check className="h-4 w-4 text-neon shrink-0 mt-1" />
                  )}
                </button>
              );
            })
          )}
        </div>
      </div>
    </AppShell>
  );
}

