/**
 * /phone — Sovereign Phone (iPhone-style minimalist).
 * 3 sekme: Aramalar · Kişiler · Klavye.
 * Arama butonunda güçlü haptic + scale + ripple geri bildirimi.
 * Açılışta mikrofon izni otomatik istenir; reddedilirse her seferinde
 * "Sovereign Security" uyarısı gösterilir.
 */
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useMemo, useState, useCallback, useRef } from "react";
import { Phone, Video, Delete, Search, Clock, User, Grid3x3, ArrowUpRight, ArrowDownLeft, PhoneMissed, Plus } from "lucide-react";
import { lookupByKurdId, useSovereignPhone } from "@/hooks/useSovereignPhone";
import { useSovereignProfile } from "@/hooks/useSovereignProfile";
import { useAuth } from "@/hooks/useAuth";
import { hapticTap, hapticSuccess, hapticHeavy } from "@/lib/native";
import { toast } from "sonner";
import { logLocalOutgoingCall, readLocalPhoneRecent, PHONE_RECENT_EVENT, type LocalPhoneRecent } from "@/lib/phoneRecent";
import { supabase } from "@/integrations/supabase/client";

export const Route = createFileRoute("/phone")({
  component: PhonePage,
  head: () => ({
    meta: [
      { title: "Telefon — Jiyan" },
      { name: "description", content: "Sovereign Phone +777 — Kurd-ID üzerinden uçtan uca şifreli arama." },
    ],
  }),
});

type Tab = "recents" | "contacts" | "keypad";

function formatKurdId(digits: string): string {
  const d = digits.replace(/\D/g, "").slice(0, 8);
  if (d.length <= 4) return `+777 ${d}`;
  return `+777 ${d.slice(0, 4)} ${d.slice(4)}`;
}

function timeAgo(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return "şimdi";
  if (m < 60) return `${m} dk`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h} sa`;
  const d = Math.floor(h / 24);
  if (d === 1) return "Dün";
  return `${d} gün`;
}

function PhonePage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { data: profile } = useSovereignProfile(user?.id);
  const { placeCall, requestAudioAccess } = useSovereignPhone();
  const [tab, setTab] = useState<Tab>("keypad");
  const [digits, setDigits] = useState("");
  const [busy, setBusy] = useState(false);
  const [callPulse, setCallPulse] = useState(false);
  const [recents, setRecents] = useState<LocalPhoneRecent[]>(() => readLocalPhoneRecent());

  const dialDigits = useMemo(() => digits.replace(/\D/g, "").slice(0, 8), [digits]);
  const display = useMemo(() => formatKurdId(dialDigits), [dialDigits]);
  const canCall = dialDigits.length === 8;
  const myId = profile?.kurdId ?? "+777 ···· ····";

  const [micGranted, setMicGranted] = useState<boolean | null>(null);

  // Mikrofon izni: her açılışta otomatik iste, reddedilirse "Sovereign Security" uyarısı
  useEffect(() => {
    let cancelled = false;
    (async () => {
      // Pre-check permission state (Chrome/Edge support — Safari throws, ignore)
      try {
        if (typeof navigator !== "undefined" && navigator.permissions) {
          const status = await navigator.permissions.query({ name: "microphone" as PermissionName });
          if (status.state === "denied") {
            if (!cancelled) {
              setMicGranted(false);
              toast.error("🛡️ Sovereign Security", {
                description: "Şifreli +777 araması için mikrofon engellenmiş. Tarayıcı ayarlarından izin ver.",
                duration: 8000,
                style: { background: "linear-gradient(135deg,#1a1208,#2a1a08)", border: "1px solid #d4af37", color: "#f5d57a" },
              });
            }
            return;
          }
        }
      } catch { /* Safari */ }
      const res = await requestAudioAccess(false);
      if (cancelled) return;
      setMicGranted(res.ok);
      if (!res.ok) {
        toast.error("🛡️ Sovereign Security", {
          description: "Şifreli +777 araması için mikrofon erişimi gerekiyor. İzin vermek için tekrar dene.",
          duration: 6000,
          style: { background: "linear-gradient(135deg,#1a1208,#2a1a08)", border: "1px solid #d4af37", color: "#f5d57a" },
          action: {
            label: "İzin ver",
            onClick: () => { void requestAudioAccess(false).then((r) => setMicGranted(r.ok)); },
          },
        });
      }
    })();
    return () => { cancelled = true; };
  }, [requestAudioAccess]);

  // Son aramalar canlı sync
  useEffect(() => {
    const onUpdate = () => setRecents(readLocalPhoneRecent());
    window.addEventListener(PHONE_RECENT_EVENT, onUpdate);
    window.addEventListener("storage", onUpdate);
    return () => {
      window.removeEventListener(PHONE_RECENT_EVENT, onUpdate);
      window.removeEventListener("storage", onUpdate);
    };
  }, []);

  const press = (k: string) => {
    void hapticTap();
    if (k === "back") {
      setDigits((d) => d.slice(0, -1));
      return;
    }
    if (!/^\d$/.test(k) || dialDigits.length >= 8) return;
    setDigits((d) => (d + k).replace(/\D/g, "").slice(0, 8));
  };

  // Donanım klavyesi desteği (keypad sekmesi aktifken).
  // Sanal klavye agresif açılmasın diye DOM input kullanmıyoruz; sadece
  // window seviyesinde klavye olaylarını dinliyoruz.
  useEffect(() => {
    if (tab !== "keypad") return;
    const onKey = (e: KeyboardEvent) => {
      // Form alanlarında yazıyorsa karışma.
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || (t as HTMLElement).isContentEditable)) return;
      if (/^[0-9]$/.test(e.key)) {
        e.preventDefault();
        press(e.key);
      } else if (e.key === "Backspace") {
        e.preventDefault();
        press("back");
      } else if (e.key === "Enter" && dialDigits.length === 8 && !busy) {
        e.preventDefault();
        void startCallRef.current?.(false);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tab, dialDigits.length, busy]);

  // Forward-ref to startCall (defined below) so the keydown handler can
  // trigger Enter-to-dial without a circular dep.
  const startCallRef = useRef<((video: boolean, fromKurdId?: string) => unknown) | null>(null);

  // notifyUnreachable kaldırıldı — artık startCall içindeki adım toast'ları
  // bulunamayan +777 yurttaşları için "Yerel ara" fallback'ini sunuyor.

  const startCall = useCallback(
    async (video: boolean, fromKurdId?: string) => {
      const targetDigits = fromKurdId
        ? fromKurdId.replace(/\D/g, "").slice(-8)
        : dialDigits;
      if (targetDigits.length !== 8 || busy) return;

      const kurdId = `+777 ${targetDigits.slice(0, 4)} ${targetDigits.slice(4)}`;
      const tel = kurdId.replace(/\s+/g, "");

      // Tek bir altın temalı toast — adım adım güncellenir.
      const TOAST_ID = `phone-call-${Date.now()}`;
      const goldStyle = {
        background: "linear-gradient(135deg,#1a1208,#2a1a08)",
        border: "1px solid #d4af37",
        color: "#f5d57a",
      } as const;

      // Güçlü görsel + haptic geri bildirim
      void hapticHeavy();
      setCallPulse(true);
      window.setTimeout(() => setCallPulse(false), 900);

      setBusy(true);
      try {
        // Adım 1 — Sinyal hazırlanıyor
        toast.loading("📡 Sovereign sinyal hazırlanıyor…", {
          id: TOAST_ID,
          description: kurdId,
          style: goldStyle,
        });

        // Anında ledger / widget log
        logLocalOutgoingCall(kurdId, video, "Giden Arama");

        if (profile?.kurdId && profile.kurdId.replace(/\s+/g, "") === kurdId.replace(/\s+/g, "")) {
          toast.error("Kendi numaranı arayamazsın", { id: TOAST_ID, style: goldStyle });
          return;
        }

        // Adım 2 — Mikrofon ön-kontrolü (kullanıcı jesti içinde)
        toast.loading("🎙️ Mikrofon doğrulanıyor…", {
          id: TOAST_ID,
          description: kurdId,
          style: goldStyle,
        });
        try {
          const probe = await navigator.mediaDevices.getUserMedia({ audio: true });
          probe.getTracks().forEach((t) => t.stop());
        } catch (err: any) {
          logLocalOutgoingCall(kurdId, video, "Bağlantı Kurulamadı");
          if (err?.name === "NotAllowedError") {
            toast.error("🛡️ Sovereign Security · Mikrofon izni reddedildi", {
              id: TOAST_ID,
              style: goldStyle,
            });
          } else {
            toast.error("Mikrofon erişimi başarısız: " + (err?.message ?? "bilinmeyen"), {
              id: TOAST_ID,
              style: goldStyle,
            });
          }
          return;
        }

        // Adım 3 — Yurttaş aranıyor
        toast.loading("🔎 +777 yurttaşı aranıyor…", {
          id: TOAST_ID,
          description: kurdId,
          style: goldStyle,
        });
        const resolved = await lookupByKurdId(kurdId);
        if (!resolved) {
          // Sovereign-only: GSM dialer'a fallback YOK. Sadece +777 ağındaki
          // yurttaşlar aranabilir.
          logLocalOutgoingCall(kurdId, false, "Ulaşılamadı");
          toast.error(`${kurdId} Sovereign ağda kayıtlı değil`, {
            id: TOAST_ID,
            duration: 4500,
            style: goldStyle,
          });
          return;
        }

        // Adım 4 — P2P bağlantısı kuruluyor
        toast.loading("🔐 Şifreli P2P hat kuruluyor…", {
          id: TOAST_ID,
          description: kurdId,
          style: goldStyle,
        });
        const res = await placeCall(resolved.user_id, video);
        if (!res.ok) {
          logLocalOutgoingCall(kurdId, false, "Bağlantı Kurulamadı");
          toast.error((res.reason ?? "Sovereign hat kurulamadı"), {
            id: TOAST_ID,
            duration: 5000,
            style: goldStyle,
          });
        } else {
          void hapticSuccess();
          toast.success(`📞 ${kurdId} aranıyor…`, { id: TOAST_ID, style: goldStyle });
