          id: TOAST_ID,
          style: goldStyle,
        });
      } finally {
        setBusy(false);
      }
    },
    [dialDigits, busy, profile, placeCall],
  );

  // Bağla: keydown handler artık aktüel startCall'ı çağırabilir.
  useEffect(() => {
    startCallRef.current = startCall;
  }, [startCall]);

  return (
    <div
      className="flex flex-col"
      style={{
        // Tam ekran: status bar safe-area + iOS home indicator safe-area.
        height: "100dvh",
        paddingTop: "env(safe-area-inset-top, 0px)",
