      {/* Content — kalan tüm dikey alanı doldurur */}
      <div className="flex-1 flex flex-col overflow-hidden min-h-0">
        {tab === "recents" && <RecentsList recents={recents} onCall={(kid) => startCall(false, kid)} />}
        {tab === "contacts" && <ContactsList onCall={(kid) => startCall(false, kid)} />}
        {tab === "keypad" && (
          <KeypadView
            display={display}
            dialDigits={dialDigits}
            canCall={canCall}
            busy={busy}
            callPulse={callPulse}
            onPress={press}
            onCall={() => startCall(false)}
            onVideo={() => startCall(true)}
