          className="mx-auto flex items-center justify-around rounded-full"
          style={{
            background: "rgba(18,14,4,0.92)",
            backdropFilter: "blur(24px) saturate(180%)",
            WebkitBackdropFilter: "blur(24px) saturate(180%)",
            border: "0.5px solid rgba(212,175,55,0.22)",
            padding: "8px 10px",
            maxWidth: 420,
            boxShadow:
              "0 -10px 30px rgba(0,0,0,0.45), inset 0 1px 0 rgba(253,230,138,0.08)",
          }}
        >
          <TabBtn active={tab === "recents"} onClick={() => { void hapticTap(); setTab("recents"); }} icon={<Clock className="h-5 w-5" />} label="Aramalar" />
          <TabBtn active={tab === "contacts"} onClick={() => { void hapticTap(); setTab("contacts"); }} icon={<User className="h-5 w-5" />} label="Kişiler" />
          <TabBtn active={tab === "keypad"} onClick={() => { void hapticTap(); setTab("keypad"); }} icon={<Grid3x3 className="h-5 w-5" />} label="Klavye" />
          <button
            type="button"
            onClick={() => navigate({ to: "/" })}
