}

function TabBtn({ active, onClick, icon, label }: { active: boolean; onClick: () => void; icon: React.ReactNode; label: string }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="flex flex-col items-center gap-0.5 px-3 py-1.5 rounded-full transition-all active:scale-95"
      style={{
        background: active
          ? "linear-gradient(180deg,rgba(212,175,55,0.22),rgba(212,175,55,0.12))"
          : "transparent",
        border: active ? "0.5px solid rgba(212,175,55,0.45)" : "0.5px solid transparent",
        color: active ? "#FDE68A" : "rgba(255,255,255,0.55)",
      }}
    >
      {icon}
      <span className="text-[10px] font-medium leading-none mt-0.5">{label}</span>
    </button>
  );
}

/* ───────────────────────── Keypad ───────────────────────── */

function KeypadView({
  display,
  dialDigits,
  canCall,
  busy,
  callPulse,
  onPress,
  onCall,
  onVideo,
}: {
  display: string;
  dialDigits: string;
  canCall: boolean;
  busy: boolean;
  callPulse: boolean;
  onPress: (k: string) => void;
  onCall: () => void;
  onVideo: () => void;
}) {
  const keys: Array<[string, string]> = [
    ["1", ""], ["2", "ABC"], ["3", "DEF"],
    ["4", "GHI"], ["5", "JKL"], ["6", "MNO"],
    ["7", "PQRS"], ["8", "TUV"], ["9", "WXYZ"],
    ["*", ""], ["0", "+"], ["#", ""],
  ];

  return (
    <>
      {/* Display — kompakt, üstte sabit, dialer'a yakın */}
      <div className="px-6 pt-4 pb-2 shrink-0">
        <div className="text-center w-full">
          <div
            className="text-[34px] font-light tracking-wider tabular-nums truncate"
            style={{ color: "#fff", minHeight: 40, lineHeight: 1.1 }}
          >
            {dialDigits.length > 0 ? display : <span className="text-white/15">+777 ____ ____</span>}
          </div>
          <div
            className={`text-[10px] uppercase tracking-[0.3em] mt-1.5 font-semibold transition-colors ${
              canCall ? "text-[#FDE68A]" : "text-white/30"
            }`}
          >
            {busy ? "Sovereign Sinyal aranıyor…" : `${dialDigits.length} / 8 hane`}
          </div>
        </div>
      </div>

      {/* Dialer — kalan dikey alanı paylaş */}
      <div className="flex-1 flex flex-col justify-center px-6 min-h-0">
        <div className="grid grid-cols-3 gap-x-5 gap-y-2.5 max-w-[320px] mx-auto w-full">
          {keys.map(([k, sub]) => (
            <button
              key={k}
              type="button"
              onClick={() => onPress(k)}
              className="aspect-square w-full rounded-full flex flex-col items-center justify-center active:scale-90 transition-all mx-auto select-none"
              style={{
                background: "rgba(44,44,46,0.85)",
                maxHeight: 68,
                maxWidth: 68,
                boxShadow: "inset 0 1px 0 rgba(255,255,255,0.06), 0 1px 2px rgba(0,0,0,0.4)",
              }}
            >
              <span className="text-[28px] font-light leading-none text-white">{k}</span>
              {sub && (
                <span className="text-[9px] tracking-[0.2em] mt-0.5 text-white/55 font-semibold">
                  {sub}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Action row — Video · Call · Backspace */}
      <div className="px-6 pt-2 pb-1 shrink-0">
        <div className="flex items-center justify-between max-w-[320px] mx-auto w-full relative">
          <button
            type="button"
            onClick={onVideo}
            disabled={!canCall || busy}
            className="h-12 w-12 rounded-full flex items-center justify-center active:scale-90 disabled:opacity-25 transition-all"
            style={{
              background: "rgba(44,44,46,0.85)",
              border: "0.5px solid rgba(255,255,255,0.06)",
            }}
            aria-label="Görüntülü ara"
          >
            <Video className="h-5 w-5 text-white" />
          </button>

          {/* WhatsApp-tarzı büyük breathing call button */}
          <button
            type="button"
            onClick={onCall}
            disabled={!canCall || busy}
            className="relative h-[68px] w-[68px] rounded-full flex items-center justify-center disabled:opacity-30 transition-all"
            style={{
              background: callPulse || busy
                ? "radial-gradient(circle at 30% 28%,#ffe5a8 0%,#f5d57a 35%,#d4af37 70%,#a8801f 100%)"
                : "radial-gradient(circle at 30% 28%,#54e07a 0%,#1FBF55 50%,#0e8a3a 100%)",
              transform: callPulse ? "scale(1.12)" : "scale(1)",
              boxShadow: callPulse || busy
                ? "0 0 0 10px rgba(212,175,55,0.18), 0 0 0 20px rgba(212,175,55,0.08), 0 14px 32px rgba(212,175,55,0.55), inset 0 -6px 12px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,234,170,0.45)"
                : canCall
                  ? "0 0 0 8px rgba(31,191,85,0.12), 0 8px 24px rgba(31,191,85,0.45), inset 0 -6px 12px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,255,255,0.2)"
                  : "0 4px 12px rgba(0,0,0,0.5), inset 0 -4px 8px rgba(0,0,0,0.3)",
              animation: canCall && !busy && !callPulse
                ? "phone-breathe 2.2s ease-in-out infinite"
                : undefined,
            }}
            aria-label="Ara"
          >
            {(callPulse || busy) && (
              <span
                className="absolute inset-0 rounded-full pointer-events-none"
                style={{
                  animation: busy ? "phone-pulse 1.4s ease-out infinite" : "phone-ripple 0.9s ease-out",
                  border: "2px solid rgba(245,213,122,0.75)",
                }}
              />
            )}
            <Phone className="h-7 w-7 text-white drop-shadow-[0_2px_3px_rgba(0,0,0,0.4)]" fill="currentColor" />
          </button>

          {/* Backspace — sürekli görünür, rakam yokken devre dışı (iPhone tarzı) */}
          <button
            type="button"
            onClick={() => onPress("back")}
            disabled={dialDigits.length === 0}
            className="h-12 w-12 rounded-full flex items-center justify-center active:scale-90 transition-all"
            style={{
              background: dialDigits.length > 0 ? "rgba(44,44,46,0.85)" : "transparent",
              border: dialDigits.length > 0 ? "0.5px solid rgba(255,255,255,0.06)" : "0.5px solid transparent",
              opacity: dialDigits.length > 0 ? 1 : 0.25,
            }}
            aria-label="Sil"
          >
            <Delete className="h-5 w-5 text-white" />
          </button>
        </div>
      </div>

      <style>{`
        @keyframes phone-ripple {
          0% { transform: scale(1); opacity: 0.9; }
          100% { transform: scale(2.4); opacity: 0; }
        }
        @keyframes phone-pulse {
          0% { transform: scale(1); opacity: 0.85; }
          70% { transform: scale(1.55); opacity: 0; }
          100% { transform: scale(1.55); opacity: 0; }
        }
        @keyframes phone-breathe {
          0%, 100% { box-shadow: 0 0 0 8px rgba(31,191,85,0.12), 0 8px 24px rgba(31,191,85,0.45), inset 0 -6px 12px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,255,255,0.2); }
          50%      { box-shadow: 0 0 0 14px rgba(31,191,85,0.18), 0 12px 32px rgba(31,191,85,0.6),  inset 0 -6px 12px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,255,255,0.2); }
        }
      `}</style>
    </>
  );
}

/* ───────────────────────── Recents ───────────────────────── */

function RecentsList({ recents, onCall }: { recents: LocalPhoneRecent[]; onCall: (kurdId: string) => void }) {
  if (recents.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center px-6">
        <div className="text-center">
          <Clock className="h-10 w-10 text-white/20 mx-auto mb-3" />
          <div className="text-white/40 text-sm">Henüz arama yok</div>
          <div className="text-white/25 text-xs mt-1">Klavyeden bir +777 numara ara</div>
        </div>
      </div>
    );
  }
  return (
    <div className="flex-1 overflow-y-auto px-4 pb-4">
      {recents.map((r) => {
        const missed =
          r.status === "Yerel Arama" ||
          r.status === "Cevapsız Arama" ||
          r.status === "Reddedilen Arama" ||
          r.status === "Bağlantı Kurulamadı" ||
          r.status === "İptal Edildi" ||
          r.status === "Ulaşılamadı";
        const incoming = r.status === "Gelen Arama";
        return (
          <button
            key={r.id}
            type="button"
            onClick={() => onCall(r.kurdId)}
            className="w-full flex items-center gap-3 py-3 border-b border-white/5 active:bg-white/5 rounded-lg px-2 -mx-2 text-left"
          >
            <div className="h-11 w-11 rounded-full flex items-center justify-center" style={{ background: "rgba(58,58,60,0.85)" }}>
              {missed ? (
                <PhoneMissed className="h-5 w-5 text-red-400" />
              ) : incoming ? (
                <ArrowDownLeft className="h-5 w-5 text-emerald-400" />
              ) : (
                <ArrowUpRight className="h-5 w-5 text-[#0A84FF]" />
              )}
            </div>
            <div className="flex-1 min-w-0">
              <div className={`font-medium truncate ${missed ? "text-red-400" : "text-white"}`}>{r.kurdId}</div>
              <div className="text-[12px] text-white/45 flex items-center gap-1.5">
                {r.video ? <Video className="h-3 w-3" /> : <ArrowUpRight className="h-3 w-3" />}
                <span>{r.status}</span>
              </div>
            </div>
            <div className="text-[12px] text-white/40 tabular-nums">{timeAgo(r.createdAt)}</div>
          </button>
        );
      })}
    </div>
  );
}

/* ───────────────────────── Contacts ───────────────────────── */

interface ContactRow {
  user_id: string;
  display_name: string | null;
  kurd_id: string | null;
  avatar_url: string | null;
}

function ContactsList({ onCall }: { onCall: (kurdId: string) => void }) {
  const [q, setQ] = useState("");
  const [rows, setRows] = useState<ContactRow[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from("profiles")
        .select("user_id, display_name, kurd_id, avatar_url")
        .not("kurd_id", "is", null)
        .order("display_name", { ascending: true })
        .limit(200);
      if (!cancelled) {
        setRows((data ?? []) as any);
        setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, []);

  const filtered = useMemo(() => {
    if (!q.trim()) return rows;
    const lower = q.toLowerCase();
    return rows.filter(
      (r) =>
        (r.display_name ?? "").toLowerCase().includes(lower) ||
        (r.kurd_id ?? "").includes(q),
    );
  }, [q, rows]);

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      <div className="px-4 pb-2">
        <div className="flex items-center gap-2 rounded-xl px-3 py-2" style={{ background: "rgba(44,44,46,0.85)" }}>
          <Search className="h-4 w-4 text-white/40" />
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Ara"
            className="flex-1 bg-transparent text-white placeholder:text-white/35 text-sm outline-none"
          />
        </div>
      </div>
      <div className="flex-1 overflow-y-auto px-4 pb-4">
        {loading && <div className="text-white/40 text-sm text-center py-8">Yükleniyor…</div>}
        {!loading && filtered.length === 0 && (
          <div className="text-white/40 text-sm text-center py-8">Kişi bulunamadı</div>
        )}
        {filtered.map((r) => {
          const initial = (r.display_name ?? "?").trim().charAt(0).toUpperCase();
          return (
            <button
              key={r.user_id}
              type="button"
              onClick={() => r.kurd_id && onCall(r.kurd_id)}
              className="w-full flex items-center gap-3 py-3 border-b border-white/5 active:bg-white/5 rounded-lg px-2 -mx-2 text-left"
            >
              <div className="h-11 w-11 rounded-full flex items-center justify-center overflow-hidden" style={{ background: "rgba(58,58,60,0.85)" }}>
                {r.avatar_url ? (
                  <img src={r.avatar_url} alt="" className="h-full w-full object-cover" />
                ) : (
                  <span className="text-white/80 font-medium">{initial}</span>
                )}
              </div>
              <div className="flex-1 min-w-0">
                <div className="font-medium text-white truncate">{r.display_name ?? "Anonim"}</div>
                <div className="text-[12px] text-white/45 tabular-nums">{r.kurd_id}</div>
              </div>
              <Phone className="h-4 w-4 text-[#0A84FF]" />
            </button>
          );
        })}
      </div>
    </div>
  );
}

