    setSaving(true);
    const { error } = await supabase.from("profiles").update({
      display_name: displayName.trim() || "Kullanıcı",
      username: username.trim() || null,
      city,
      phone_number: phone.trim() || null,
      bio: bio.trim() || null,
    }).eq("user_id", user.id);

    if (error) {
      toast.error("Güncelleme başarısız");
