/* ── Reusable Sub-Components ────────────────────────── */

function GlassCard({ children }: { children: React.ReactNode }) {
  return (
    <div className="rounded-2xl border border-border/30 bg-card/60 backdrop-blur-xl p-4 shadow-sm">
      {children}
    </div>
  );
}

function SectionTitle({ icon: Icon, title }: { icon: React.ComponentType<{ className?: string }>; title: string }) {
  return (
    <div className="flex items-center gap-2 mb-2.5">
      <Icon className="h-4 w-4 text-neon" />
      <h2 className="text-sm font-semibold text-foreground">{title}</h2>
    </div>
  );
}

function EditField({ icon: Icon, label, value, onChange, placeholder }: {
  icon: React.ComponentType<{ className?: string }>; label: string; value: string;
  onChange: (v: string) => void; placeholder?: string;
}) {
  return (
    <div>
      <label className="flex items-center gap-2 text-xs font-medium text-muted-foreground mb-1.5">
        <Icon className="h-3 w-3" /> {label}
      </label>
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="h-11 w-full rounded-xl border border-border/50 bg-background/50 px-4 text-sm text-foreground placeholder:text-muted-foreground focus:border-neon/50 focus:ring-1 focus:ring-neon/20 focus:outline-none transition-all"
      />
    </div>
  );
}

function PrivacyToggle({ icon: Icon, label, description, checked, onChange }: {
  icon: React.ComponentType<{ className?: string }>; label: string; description: string;
  checked: boolean; onChange: (v: boolean) => void;
}) {
  return (
    <div className="flex items-center justify-between gap-3">
      <div className="flex items-start gap-3">
        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-muted/50 mt-0.5">
          <Icon className="h-4 w-4 text-muted-foreground" />
        </div>
        <div>
          <p className="text-sm font-medium text-foreground">{label}</p>
          <p className="text-[11px] text-muted-foreground leading-tight mt-0.5">{description}</p>
        </div>
      </div>
      <Switch checked={checked} onCheckedChange={onChange} />
    </div>
  );
}

