 * - vault    → scrolls to Xezîne Vault (DiravCash)
 * - doors    → scrolls to "My Open Doors"
 * - xezine   → scrolls to Xezîne Inventory
 * - services → opens the Hizmetler bottom tab
 * - keka     → opens the Keka bottom tab
 * - fund     → opens the Fon bottom tab
 */
const PROFILE_TABS = ["vault", "doors", "xezine", "services", "keka", "fund"] as const;
type ProfileTab = (typeof PROFILE_TABS)[number];

type ProfileSearch = { e?: string; tab?: ProfileTab };

export const Route = createFileRoute("/profile")({
  component: SovereignProfilePage,
  validateSearch: (search: Record<string, unknown>): ProfileSearch => {
    const out: ProfileSearch = {};
    if (typeof search.e === "string") out.e = search.e;
    if (typeof search.tab === "string" && (PROFILE_TABS as readonly string[]).includes(search.tab)) {
      out.tab = search.tab as ProfileTab;
    }
    return out;
  },
  head: () => ({
    meta: [
      { title: "Sovereign Profile · Egemen — Jiyan" },
      {
        name: "description",
        content:
          "Honor is the only currency that never devalues. View your Sovereign ID, KEKA reputation, Xezîne vault and open doors.",
      },
    ],
  }),
});

const HAKEM_THRESHOLD = 500;

function vibrate(pattern: number | number[]) {
  if (typeof navigator !== "undefined" && "vibrate" in navigator) {
    try {
      (navigator as Navigator & { vibrate?: (p: number | number[]) => boolean }).vibrate?.(
        pattern,
      );
    } catch {
      /* ignore */
    }
  }
}

function SovereignProfilePage() {
  const { user, loading: authLoading } = useAuth();
  const { data, loading, refresh: refreshProfile } = useSovereignProfile(user?.id);
  const { byCategory, xezineList, toggleActive } = useMyOpenDoors(user?.id);
  const search = Route.useSearch();

  const scannedCard: EgemenPayload | null = useMemo(
    () => decodeEgemenToken(search.e),
    [search.e],
  );
  const isViewingScannedCard =
    !!scannedCard && (!user || scannedCard.u !== (data?.username ?? user.id));

  const [shareOpen, setShareOpen] = useState(false);
