/* ───────────── Sub-components ───────────── */

function SectionTitle({ label, sub }: { label: string; sub: string }) {
  return (
    <div>
      <div className="text-[10px] font-mono uppercase tracking-[0.3em] text-amber-300/60">
        {sub}
      </div>
      <h2 className="text-sm font-semibold text-amber-100/95 mt-0.5">{label}</h2>
    </div>
  );
}

function HonorMetric({
  icon,
  label,
  sublabel,
  value,
  primary,
}: {
  icon: React.ReactNode;
  label: string;
  sublabel: string;
  value: number;
  primary?: boolean;
}) {
  return (
    <div
      className={`flex flex-col items-center rounded-2xl border backdrop-blur-md p-3 transition-all ${
        primary
          ? "border-amber-400/35 bg-gradient-to-br from-amber-500/12 via-black/30 to-black/40"
          : "border-amber-400/15 bg-black/35"
      }`}
    >
      <div
        className={`h-9 w-9 rounded-xl flex items-center justify-center mb-2 ${
          primary
            ? "bg-amber-400/20 text-amber-200 border border-amber-300/40"
            : "bg-white/5 text-amber-300/80 border border-amber-400/15"
        }`}
      >
        {icon}
      </div>
      <span className="text-xl font-bold text-amber-100 tabular-nums">
        {value.toLocaleString("en-US")}
      </span>
      <span className="text-[9px] font-mono uppercase tracking-widest text-amber-300/55 mt-1">
        {label}
      </span>
      <span className="text-[9px] text-amber-200/40 mt-0.5">{sublabel}</span>
    </div>
  );
}

function StatusSeal({
  icon,
  label,
  active,
}: {
  icon: React.ReactNode;
  label: string;
  active: boolean;
}) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full border text-[9px] font-bold uppercase tracking-widest ${
        active
          ? "bg-amber-400/15 border-amber-300/45 text-amber-200 shadow-[0_0_12px_-4px_rgba(212,175,55,0.5)]"
          : "bg-white/5 border-white/10 text-white/35"
      }`}
    >
      {icon}
      {label}
    </span>
  );
}

function DoorToggle({
  category,
  icon,
  label,
  listing,
  onToggle,
}: {
  category: MivankasCategory;
  icon: React.ReactNode;
  label: string;
  listing: { id: string; is_active: boolean; title: string } | null;
  onToggle: (id: string, next: boolean) => Promise<boolean>;
}) {
  const isOn = !!listing?.is_active;
  return (
    <div
      className={`flex items-center justify-between rounded-2xl border px-3.5 py-3 transition-all ${
        isOn
          ? "border-amber-400/40 bg-gradient-to-r from-amber-500/10 via-black/30 to-black/40"
          : "border-amber-400/12 bg-black/35"
      }`}
    >
      <div className="flex items-center gap-3">
        <div
          className={`h-9 w-9 rounded-xl flex items-center justify-center transition ${
            isOn
              ? "bg-amber-400/20 text-amber-200 border border-amber-300/40"
              : "bg-white/5 text-amber-300/60 border border-amber-400/15"
          }`}
        >
          {icon}
        </div>
        <div className="min-w-0">
          <div className="text-sm font-semibold text-amber-100/95 leading-tight">
            {label}
          </div>
          <div className="text-[10px] text-amber-300/50 truncate max-w-[170px]">
            {listing ? listing.title : "İlan henüz oluşturulmamış"}
          </div>
        </div>
      </div>
      {listing ? (
        <button
          type="button"
          role="switch"
          aria-checked={isOn}
          onClick={() => onToggle(listing.id, !isOn)}
          className={`relative h-7 w-12 rounded-full transition-all duration-200 ${
            isOn
              ? "bg-amber-400/80 shadow-[0_0_18px_rgba(212,175,55,0.55)]"
              : "bg-white/10"
          }`}
        >
          <span
            className={`absolute top-0.5 h-6 w-6 rounded-full bg-black transition-transform duration-200 ${
              isOn ? "translate-x-5" : "translate-x-0.5"
            }`}
          />
        </button>
      ) : (
        <Link
          to="/mivankas"
          className="text-[10px] font-mono uppercase tracking-widest text-amber-300/70 hover:text-amber-200 transition px-2 py-1 rounded-md border border-amber-400/25"
          aria-label={`Create ${category} listing`}
        >
          + Aç
        </Link>
      )}
    </div>
  );
}

function ActionTile({
  to,
  icon: Icon,
  label,
}: {
  to: "/create-service" | "/orders" | "/mivankas" | "/settings";
  icon: typeof Plus;
  label: string;
}) {
  return (
    <Link
      to={to}
      onClick={() => vibrate(8)}
      className="group flex flex-col items-center justify-center gap-1.5 py-3 rounded-2xl border border-amber-400/20 bg-gradient-to-b from-amber-500/[0.06] via-black/40 to-black/50 hover:border-amber-400/45 transition active:scale-95"
    >
      <Icon className="h-5 w-5 text-amber-300" strokeWidth={1.6} />
      <span className="text-[10px] font-semibold tracking-wide text-amber-100/85">
        {label}
      </span>
    </Link>
  );
}

function SealMedallion({
  label,
  sublabel,
  active,
}: {
  label: string;
  sublabel: string;
  active: boolean;
}) {
  return (
    <div
      aria-hidden={!active}
      className={`relative h-16 w-16 rounded-full flex flex-col items-center justify-center border-2 transition ${
        active
          ? "border-amber-300/70 bg-gradient-to-br from-amber-500/25 via-amber-700/20 to-black/60 shadow-[0_0_22px_-6px_rgba(244,200,74,0.7)]"
          : "border-white/10 bg-black/30 opacity-40"
      }`}
    >
      {/* outer scallop ring */}
      <div
        className={`absolute inset-0.5 rounded-full border border-dashed pointer-events-none ${
          active ? "border-amber-200/40" : "border-white/10"
        }`}
      />
      <span
        className={`text-[8px] font-black uppercase tracking-[0.15em] leading-none ${
          active ? "text-amber-100" : "text-white/40"
        }`}
      >
        {label}
      </span>
      <span
        className={`mt-0.5 text-[7px] font-mono uppercase tracking-[0.12em] leading-none ${
          active ? "text-amber-200/80" : "text-white/30"
        }`}
      >
        {sublabel}
      </span>
    </div>
  );
}

function ModuleLink({
  to,
  icon: Icon,
  label,
  badge,
  highlight,
}: {
  to: "/inbox" | "/notifications" | "/kurd-id" | "/kyc" | "/admin" | "/help" | "/sos-evidence" | "/orders";
  icon: typeof Plus;
  label: string;
  badge?: number;
  highlight?: boolean;
}) {
  return (
    <Link
      to={to}
      onClick={() => vibrate(6)}
      className="group flex flex-col items-center gap-1 active:scale-95 transition-transform"
    >
      <div
        className={`relative h-11 w-11 rounded-xl border flex items-center justify-center transition ${
          highlight
            ? "border-amber-300/60 bg-amber-400/15"
            : "border-amber-400/15 bg-black/35 group-hover:border-amber-400/40"
        }`}
      >
        <Icon className="h-4 w-4 text-amber-300/85" />
        {badge !== undefined && badge > 0 && (
          <span className="absolute -top-1 -right-1 h-4 min-w-4 px-1 rounded-full bg-amber-400 text-[9px] font-black text-black flex items-center justify-center">
            {badge > 9 ? "9+" : badge}
          </span>
        )}
      </div>
      <span className="text-[9px] font-mono uppercase tracking-widest text-amber-200/60">
        {label}
      </span>
    </Link>
  );
}

