/**
 * /recovery — Sovereign Recovery Portal.
 *
 * Standalone route accessible BEFORE login — independent of the Apps Hub
 * and Deng inbox. Two recovery channels:
 *
 *  1. Life Key (24 words) — instant bypass: paste your seed phrase, we
 *     verify the hash via `verify_recovery_phrase` RPC, and on success
 *     route the user to /reset-password to set a fresh credential.
 *  2. External Email OTP — sends a Supabase password-reset link to your
 *     EXTERNAL backup email (NEVER to the internal Deng inbox).
 *
 * The Loop Breaker: this page never depends on a session, never queries
 * the user's profile, and never opens the Hub.
 */
import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { useState } from "react";
import { ArrowLeft, KeyRound, Mail, ShieldCheck, Sparkles } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { hashSeedPhrase } from "@/lib/sovereignCrypto";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

export const Route = createFileRoute("/recovery")({
  component: RecoveryPage,
  head: () => ({
    meta: [
      { title: "Sovereign Recovery — Jiyan World" },
      {
