/**
 * /reset-password — public route reached from the password-reset email.
 *
 * Supabase delivers a recovery hash in the URL fragment. The session is
 * exchanged automatically by the auth client; we just present a form and
 * call `updateUser({ password })`.
 */
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Lock, Eye, EyeOff, ShieldCheck } from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/reset-password")({
  component: ResetPasswordPage,
  head: () => ({
    meta: [
      { title: "Şifre Sıfırla – Jiyan Europe" },
      { name: "description", content: "Yeni Jiyan ID şifrenizi belirleyin." },
    ],
  }),
});

function ResetPasswordPage() {
  const navigate = useNavigate();
  const [ready, setReady] = useState(false);
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [show, setShow] = useState(false);
  const [saving, setSaving] = useState(false);

  // Supabase parses the recovery hash automatically. We simply wait for
  // an authenticated session before allowing the form.
  useEffect(() => {
    let cancelled = false;
    supabase.auth.getSession().then(({ data }) => {
      if (cancelled) return;
      if (data.session) setReady(true);
    });
    const { data: sub } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === "PASSWORD_RECOVERY" || (event === "SIGNED_IN" && session)) {
        setReady(true);
      }
    });
    return () => {
      cancelled = true;
      sub.subscription.unsubscribe();
    };
  }, []);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password.length < 8) {
      toast.error("En az 8 karakter olmalı");
      return;
    }
    if (password !== confirm) {
      toast.error("Şifreler eşleşmiyor");
      return;
    }
    setSaving(true);
    try {
      const { error } = await supabase.auth.updateUser({ password });
      if (error) throw error;
      toast.success("Şifre güncellendi", { description: "Yeni şifrenle giriş yapabilirsin." });
      navigate({ to: "/" });
    } catch (err: any) {
      toast.error(err?.message ?? "Şifre güncellenemedi");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="relative flex min-h-screen items-center justify-center bg-background px-5">
      {/* Ambient gold glow */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_top,rgba(245,200,80,0.12),transparent_60%)]"
      />

      <div className="relative z-10 w-full max-w-sm">
        <div className="mb-6 flex flex-col items-center text-center">
          <div className="mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-br from-amber-400/30 to-amber-600/15 ring-1 ring-amber-400/40 shadow-[0_4px_28px_rgba(245,200,80,0.25)]">
            <ShieldCheck className="h-7 w-7 text-amber-300" />
          </div>
          <h1 className="bg-gradient-to-r from-amber-200 via-yellow-100 to-amber-300 bg-clip-text text-2xl font-bold text-transparent">
            Şifreni Yenile
          </h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Yeni Jiyan ID şifrenizi belirleyin.
          </p>
        </div>

        {!ready ? (
          <div className="rounded-2xl border border-amber-400/15 bg-surface/70 p-5 text-center text-sm text-muted-foreground backdrop-blur">
            Bağlantı doğrulanıyor...
          </div>
        ) : (
          <form
            onSubmit={submit}
            className="space-y-4 rounded-2xl border border-amber-400/15 bg-surface/70 p-5 backdrop-blur"
          >
            <PasswordField
              value={password}
              onChange={setPassword}
              placeholder="Yeni şifre (en az 8 karakter)"
              show={show}
              setShow={setShow}
            />
            <PasswordField
              value={confirm}
              onChange={setConfirm}
              placeholder="Yeni şifre (tekrar)"
              show={show}
              setShow={setShow}
              hideToggle
            />

            <Button
              type="submit"
              disabled={saving}
              className="h-12 w-full bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-500 text-base font-semibold text-black shadow-[0_4px_24px_rgba(245,200,80,0.4)] hover:shadow-[0_6px_32px_rgba(245,200,80,0.55)]"
            >
              {saving ? "Güncelleniyor..." : "Şifreyi Güncelle"}
            </Button>

            <p className="text-center text-[11px] leading-relaxed text-muted-foreground">
              Bu bağlantıyı sen istemediysen, hesabın güvende. Yeni şifre belirlemediğin
              sürece eski şifren geçerli kalır.
            </p>
          </form>
        )}
      </div>
    </div>
  );
}

function PasswordField({
  value,
  onChange,
  placeholder,
  show,
  setShow,
  hideToggle,
}: {
  value: string;
  onChange: (v: string) => void;
  placeholder: string;
  show: boolean;
  setShow: (v: boolean) => void;
  hideToggle?: boolean;
}) {
  return (
    <div className="relative">
      <Lock className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
      <input
        type={show ? "text" : "password"}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="h-12 w-full rounded-xl border border-amber-400/20 bg-background/60 pl-10 pr-10 text-sm text-foreground placeholder:text-muted-foreground focus:border-amber-400/60 focus:outline-none"
        required
        minLength={8}
      />
      {!hideToggle && (
        <button
          type="button"
          onClick={() => setShow(!show)}
          className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
          aria-label={show ? "Şifreyi gizle" : "Şifreyi göster"}
        >
          {show ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
        </button>
      )}
    </div>
  );
}

