function SurahReader({ number, onBack }: { number: number; onBack: () => void }) {
  const [surah, setSurah] = useState<SurahFull | null>(null);
  const [playing, setPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    setSurah(null);
    getSurah(number).then(setSurah);
  }, [number]);

  useEffect(() => {
    if (!audioRef.current) {
      audioRef.current = new Audio(getReciterUrl(number));
      audioRef.current.addEventListener("ended", () => setPlaying(false));
    } else {
      audioRef.current.src = getReciterUrl(number);
    }
    return () => {
      audioRef.current?.pause();
      setPlaying(false);
    };
  }, [number]);

  const toggle = () => {
    if (!audioRef.current) return;
    if (playing) {
      audioRef.current.pause();
      setPlaying(false);
    } else {
      audioRef.current.play().catch(() => {});
      setPlaying(true);
    }
  };

  if (!surah) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="h-5 w-5 animate-spin opacity-60" />
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <button
          onClick={onBack}
          className="flex items-center gap-1 text-[12px]"
          style={{ color: "rgba(212,175,55,0.85)" }}
        >
          <ChevronRight className="h-3.5 w-3.5 rotate-180" />
          Sureler
        </button>
        <button
          onClick={toggle}
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[11px]"
          style={{
            background: playing ? "rgba(212,175,55,0.25)" : "rgba(212,175,55,0.1)",
            border: "1px solid rgba(212,175,55,0.4)",
            color: "#FFF6D9",
          }}
        >
          {playing ? <Pause className="h-3 w-3" /> : <Play className="h-3 w-3" />}
          {playing ? "Duraklat" : "Dinle"}
        </button>
      </div>
      <GoldCard>
        <div className="text-center pb-3">
          <div
            className="text-2xl"
            style={{ fontFamily: "'Amiri', serif", color: "#FFE89A" }}
          >
            {surah.name}
          </div>
          <div className="text-[10px]" style={{ color: "rgba(245,230,184,0.55)" }}>
            {surah.englishName} · {surah.ayahs.length} ayet
          </div>
        </div>
      </GoldCard>
      {surah.ayahs.map((a, i) => (
        <GoldCard key={a.number}>
          <div className="flex items-start justify-between gap-3">
            <div
              className="flex h-6 w-6 items-center justify-center rounded-full text-[10px] tabular-nums flex-shrink-0"
              style={{
                background: "rgba(212,175,55,0.1)",
                border: "1px solid rgba(212,175,55,0.3)",
