/* ─────────────────── Tesbih Panel ─────────────────── */

const TESBIH_PHRASES = [
  { ar: "سُبْحَانَ ٱللَّٰهِ", tr: "Subhanallah" },
  { ar: "ٱلْحَمْدُ لِلَّٰهِ", tr: "Elhamdülillah" },
  { ar: "ٱللَّٰهُ أَكْبَرُ", tr: "Allahu Ekber" },
  { ar: "لَا إِلَٰهَ إِلَّا ٱللَّٰهُ", tr: "La ilahe illallah" },
];

function TesbihPanel() {
  const { today, log } = useAmelLog();
  const [count, setCount] = useState(0);
  const [phraseIdx, setPhraseIdx] = useState(0);
  const [beatSync, setBeatSync] = useState(false);
  const [pulseTs, setPulseTs] = useState(0);
  const [globalTotal, setGlobalTotal] = useState<number>(0);
  const phrase = TESBIH_PHRASES[phraseIdx];
  const target = 33;
  const progress = Math.min(count / target, 1);

  // #6 Live Dhikr Room — global counter realtime + reconnect retry
  const [connStatus, setConnStatus] = useState<"connecting" | "live" | "offline">("connecting");
  useEffect(() => {
    let mounted = true;
    let ch: ReturnType<typeof supabase.channel> | null = null;
    let retryTimer: number | null = null;
    let attempts = 0;

    const loadTotal = () => {
      void supabase.from("global_tesbih").select("zikir,total").then(({ data }) => {
        if (!mounted) return;
        const sum = ((data as Array<{ total: number }> | null) ?? []).reduce(
          (a, x) => a + Number(x.total ?? 0),
          0,
        );
        setGlobalTotal(sum);
      });
    };

    const connect = () => {
      setConnStatus("connecting");
      ch = supabase
        .channel(`tesbih-live-${Date.now()}`)
        .on(
          "postgres_changes",
          { event: "UPDATE", schema: "public", table: "global_tesbih" },
          (p) => {
            const old = (p.old as { total?: number } | null)?.total ?? 0;
            const next = (p.new as { total?: number } | null)?.total ?? 0;
            const delta = Math.max(0, next - old);
            if (delta > 0) {
              setGlobalTotal((g) => g + delta);
              setPulseTs(Date.now());
            }
          },
        )
        .subscribe((s) => {
          if (!mounted) return;
          if (s === "SUBSCRIBED") {
            setConnStatus("live");
            attempts = 0;
            loadTotal();
          } else if (s === "CHANNEL_ERROR" || s === "TIMED_OUT" || s === "CLOSED") {
            setConnStatus("offline");
            // exponential backoff reconnect (1s,2s,4s,8s, max 15s)
            const delay = Math.min(15000, 1000 * 2 ** attempts);
            attempts += 1;
            if (ch) void supabase.removeChannel(ch);
            ch = null;
            retryTimer = window.setTimeout(() => mounted && connect(), delay);
          }
        });
    };

    loadTotal();
    connect();
    // Refresh total when tab regains focus
    const onVis = () => { if (document.visibilityState === "visible") loadTotal(); };
    document.addEventListener("visibilitychange", onVis);

    return () => {
      mounted = false;
      document.removeEventListener("visibilitychange", onVis);
      if (retryTimer) clearTimeout(retryTimer);
      if (ch) void supabase.removeChannel(ch);
    };
  }, []);

  const tap = () => {
    const next = count + 1;
    setCount(next);
    if (typeof navigator !== "undefined" && "vibrate" in navigator) {
      navigator.vibrate?.(next % target === 0 ? [12, 40, 12] : 8);
    }
    if (next % target === 0) {
      log("tesbih", target);
      setPhraseIdx((i) => (i + 1) % TESBIH_PHRASES.length);
    }
    // contribute to global counter
    void supabase.rpc("increment_global_tesbih", {
      _zikir: phrase.tr,
      _by: 1,
    });
  };

  // #2 Beat Sync — müzik nabzına eşitle
  useTesbihBeatSync({ enabled: beatSync, onBeat: tap });

  const reset = () => setCount(0);

  return (
    <div className="space-y-4">
      <GoldCard>
        <div
          className="text-[9px] uppercase text-center"
          style={{ color: "rgba(212,175,55,0.7)", letterSpacing: "0.32em" }}
        >
          Dijital Zikir · Bugün {today.tesbih}
        </div>
        <div
          className="mt-2 text-center text-2xl"
          style={{ fontFamily: "'Amiri', serif", color: "#FFE89A" }}
          dir="rtl"
        >
          {phrase.ar}
        </div>
        <div
          className="text-center text-[11px] mt-1"
          style={{ color: "rgba(245,230,184,0.7)" }}
        >
          {phrase.tr}
        </div>
        <div className="mt-3 flex items-center justify-between gap-2 px-1">
          <div
            className="flex items-center gap-1.5 text-[10px] tabular-nums"
            style={{ color: "rgba(245,230,184,0.7)" }}
            title={
              connStatus === "live" ? "Canlı bağlantı"
              : connStatus === "connecting" ? "Bağlanılıyor…"
              : "Çevrimdışı — yeniden bağlanılıyor"
            }
          >
            <span
              className="inline-block h-1.5 w-1.5 rounded-full"
              style={{
                background: connStatus === "live" ? "#FFE89A" : connStatus === "connecting" ? "#D4AF37" : "#8B1E2F",
                boxShadow: Date.now() - pulseTs < 600
                  ? "0 0 14px #FFE89A, 0 0 28px rgba(255,215,90,0.6)"
                  : connStatus === "connecting" ? "0 0 6px #D4AF37" : "none",
                transition: "box-shadow 600ms ease, background 200ms ease",
                animation: connStatus === "connecting" ? "pulse 1.4s ease-in-out infinite" : undefined,
              }}
            />
            Cemaat: <span style={{
              color: "#FFE89A",
              textShadow: Date.now() - pulseTs < 600 ? "0 0 8px rgba(255,215,90,0.7)" : "none",
              transition: "text-shadow 600ms ease",
            }}>{globalTotal.toLocaleString()}</span>
            {connStatus === "offline" && <span style={{ color: "#8B1E2F" }}>· offline</span>}
          </div>
          <button
            type="button"
            onClick={() => setBeatSync((v) => !v)}
            className="text-[10px] uppercase tracking-[0.2em] px-2 py-1 rounded-full"
            style={{
              border: `1px solid ${beatSync ? "#FFE89A" : "rgba(212,175,55,0.3)"}`,
              color: beatSync ? "#FFE89A" : "rgba(245,230,184,0.6)",
              background: beatSync ? "rgba(212,175,55,0.12)" : "transparent",
            }}
            aria-pressed={beatSync}
          >
            ♪ Beat
          </button>
        </div>
      </GoldCard>

      <button
        onClick={tap}
        className="relative mx-auto block rounded-full active:scale-[0.97] transition-transform"
        style={{
          width: 240,
          height: 240,
          background:
            "radial-gradient(circle at 30% 30%, rgba(255,232,154,0.25), rgba(212,175,55,0.08) 60%, rgba(10,7,2,0.9) 100%)",
          border: "1px solid rgba(212,175,55,0.5)",
          boxShadow:
            "0 0 60px rgba(212,175,55,0.25), inset 0 0 40px rgba(255,232,154,0.08)",
        }}
        aria-label="Tesbih çek"
      >
        {/* progress ring */}
        <svg
          className="absolute inset-0"
          width="240"
          height="240"
          style={{ transform: "rotate(-90deg)" }}
        >
          <circle
            cx="120"
            cy="120"
            r="112"
            fill="none"
            stroke="rgba(212,175,55,0.15)"
            strokeWidth="2"
          />
          <circle
            cx="120"
            cy="120"
            r="112"
            fill="none"
            stroke="#FFE89A"
            strokeWidth="2"
            strokeDasharray={`${2 * Math.PI * 112}`}
            strokeDashoffset={`${2 * Math.PI * 112 * (1 - progress)}`}
            strokeLinecap="round"
            style={{ transition: "stroke-dashoffset 200ms ease" }}
          />
        </svg>
        <div
          className="relative text-5xl tabular-nums"
          style={{
            fontFamily: "'Cinzel', Inter",
            fontWeight: 200,
            color: "#FFF6D9",
            textShadow: "0 0 20px rgba(212,175,55,0.4)",
          }}
        >
          {count % target}
        </div>
        <div
          className="relative mt-2 text-[10px]"
          style={{ color: "rgba(245,230,184,0.55)", letterSpacing: "0.2em" }}
        >
          / {target}
        </div>
      </button>

      <div className="flex justify-center gap-2">
        <button
          onClick={reset}
          className="flex items-center gap-1.5 px-4 py-2 rounded-full text-[11px]"
          style={{
            background: "rgba(10,7,2,0.7)",
            border: "1px solid rgba(212,175,55,0.3)",
            color: "rgba(245,230,184,0.85)",
          }}
        >
          <RotateCcw className="h-3 w-3" />
          Sıfırla
        </button>
      </div>
    </div>
  );
}

