          style={{
            background: "rgba(0,0,0,0.4)",
            border: "1px solid rgba(212,175,55,0.25)",
            color: "#FFF6D9",
            fontFamily: "Inter",
          }}
        />
        <div className="mt-2 flex items-center justify-between">
          <div className="text-[10px]" style={{ color: "rgba(245,230,184,0.5)" }}>
            {text.length}/500
          </div>
          <button
            onClick={submit}
            disabled={posting || text.trim().length < 4 || !user}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[11px] disabled:opacity-40"
            style={{
              background: "linear-gradient(180deg, rgba(212,175,55,0.28), rgba(212,175,55,0.10))",
              border: "1px solid rgba(212,175,55,0.5)",
              color: "#FFF6D9",
