      {loading && (
        <div className="flex items-center justify-center py-6">
          <Loader2 className="h-4 w-4 animate-spin" style={{ color: "#D4AF37" }} />
        </div>
      )}

      {!loading && duas.length === 0 && (
        <div
          className="text-center py-8 text-[11px]"
          style={{ color: "rgba(245,230,184,0.5)" }}
        >
          Henüz dua yok. İlk paylaşan ol.
        </div>
      )}

      {duas.map((d) => {
        const mine = user?.id === d.author_id;
        const said = amened.has(d.id);
        return (
          <GoldCard key={d.id}>
            <div
              className="text-[13px] leading-relaxed whitespace-pre-wrap"
              style={{ color: "#FFF6D9" }}
            >
              {d.body}
            </div>
            <div className="mt-3 flex items-center justify-between">
              <div className="text-[10px]" style={{ color: "rgba(245,230,184,0.45)" }}>
                Anonim kardeş · {timeAgo(d.created_at)}
              </div>
              <div className="flex items-center gap-2">
                {mine && (
                  <button
                    onClick={async () => {
                      await supabase.from("dua_requests").delete().eq("id", d.id);
                    }}
                    className="p-1.5 rounded-lg"
                    style={{
                      border: "1px solid rgba(255,107,107,0.3)",
                      color: "rgba(255,107,107,0.8)",
                    }}
                    aria-label="Sil"
                  >
                    <Trash2 className="h-3 w-3" />
                  </button>
                )}
                <button
                  onClick={() => amen(d.id)}
                  disabled={said || mine}
                  className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-[11px] disabled:opacity-60"
                  style={{
                    background: said
                      ? "linear-gradient(180deg, rgba(212,175,55,0.30), rgba(212,175,55,0.12))"
                      : "rgba(212,175,55,0.08)",
                    border: "1px solid rgba(212,175,55,0.45)",
                    color: "#FFF6D9",
                  }}
                >
                  <HeartHandshake className="h-3 w-3" />
                  Âmin · {d.amen_count}
                </button>
              </div>
            </div>
          </GoldCard>
        );
      })}
    </div>
  );
}

function timeAgo(iso: string): string {
  const diff = (Date.now() - new Date(iso).getTime()) / 1000;
  if (diff < 60) return "şimdi";
  if (diff < 3600) return `${Math.floor(diff / 60)} dk`;
  if (diff < 86400) return `${Math.floor(diff / 3600)} sa`;
  return `${Math.floor(diff / 86400)} gün`;
}

