/**
 * /security — Egemen Güvenlik (Sovereign Security) hub.
 *
 * Single dashboard that surfaces the security triangle:
 *   • Active Sessions (Cihazlar)
 *   • Yaşam Anahtarı (passkey) status + register/revoke
 *   • Last login method, device, and verification window
 *   • Authenticator quick-link
 */
import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { ArrowLeft, ShieldCheck, KeyRound, Smartphone, Clock, Plus, ShieldOff, Fingerprint } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { useSovereignAuth } from "@/hooks/useSovereignAuth";
import { usePasskeys } from "@/hooks/usePasskeys";
import { SessionsList } from "@/components/security/SessionsList";
import { GuestRecoveryCard } from "@/components/security/GuestRecoveryCard";
import { Button } from "@/components/ui/button";
import { formatDistanceToNow } from "date-fns";

export const Route = createFileRoute("/security")({
  component: SecurityHubPage,
  head: () => ({
    meta: [
      { title: "Egemen Güvenlik – Jiyan" },
      { name: "description", content: "Cihazlar, Yaşam Anahtarı ve son giriş aktivitesi tek panelde." },
    ],
  }),
});

function SecurityHubPage() {
  const { user } = useAuth();
  const { state, isSovereignVerified, remainingSeconds } = useSovereignAuth();
  const { passkeys, hasPasskeys, isSupported, busy, register, revoke } = usePasskeys();
  const isGuest = !user;

  const minutes = Math.ceil(remainingSeconds / 60);

  // Guest mode: show only password recovery + a Login CTA. Hide passkey
  // and session panels (they require a session anyway).
  if (isGuest) {
    return (
      <AppShell>
        <div className="px-4 pt-4 pb-24 space-y-4">
          <Link to="/" className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground">
            <ArrowLeft className="h-3.5 w-3.5" /> Hub
          </Link>
          <div className="rounded-3xl border border-amber-400/30 bg-gradient-to-br from-amber-500/10 via-black/50 to-amber-600/5 p-5">
            <div className="flex items-center gap-2 mb-3">
              <ShieldCheck className="h-5 w-5 text-amber-300" />
              <h1 className="text-sm font-bold text-amber-100 tracking-wide uppercase">Güvenlik Merkezi</h1>
            </div>
            <p className="text-[12px] text-amber-200/70 leading-relaxed">
              Misafir oturumdasınız. Tam güvenlik paneline erişmek için Egemen Kimliğinizle giriş yapın
              ya da aşağıdan şifrenizi sıfırlayın.
            </p>
            <Link to="/login" className="mt-4 block">
              <Button className="w-full bg-amber-500 hover:bg-amber-400 text-black">
                <ShieldCheck className="h-4 w-4 mr-1.5" /> Jiyan ID ile Giriş
              </Button>
            </Link>
          </div>

          <GuestRecoveryCard />
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <div className="px-4 pt-4 pb-24 space-y-4">
        <Link to="/settings" className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground">
          <ArrowLeft className="h-3.5 w-3.5" /> Ayarlar
        </Link>

        {/* Sovereign verification status */}
        <div className="rounded-3xl border border-amber-400/30 bg-gradient-to-br from-amber-500/10 via-black/50 to-amber-600/5 p-5">
          <div className="flex items-center gap-2 mb-3">
            <ShieldCheck className={`h-5 w-5 ${isSovereignVerified ? "text-amber-300" : "text-amber-200/40"}`} />
            <h1 className="text-sm font-bold text-amber-100 tracking-wide uppercase">Egemen Güvenlik</h1>
          </div>
          <div className="space-y-1">
            <p className={`text-2xl font-semibold ${isSovereignVerified ? "text-amber-100" : "text-foreground/70"}`}>
              {isSovereignVerified ? `Aktif · ${minutes} dk` : "Doğrulama gerekli"}
            </p>
            <p className="text-[11px] text-amber-200/55">
              {state.lastMethod
                ? `Son yöntem: ${state.lastMethod.toUpperCase()}${state.lastDeviceLabel ? ` · ${state.lastDeviceLabel}` : ""}`
                : "Henüz Authenticator ile doğrulanmadınız."}
            </p>
            {state.verifiedAt && (
              <p className="text-[10px] text-amber-200/40 flex items-center gap-1">
                <Clock className="h-3 w-3" /> {formatDistanceToNow(new Date(state.verifiedAt), { addSuffix: true })}
              </p>
            )}
          </div>
          <div className="mt-4 flex gap-2">
            <Link to="/authenticator" className="flex-1">
              <Button variant="default" size="sm" className="w-full bg-amber-500 hover:bg-amber-400 text-black">
                <Fingerprint className="h-4 w-4 mr-1.5" /> Authenticator
              </Button>
            </Link>
          </div>
        </div>

        {/* Yaşam Anahtarı */}
        <div className="rounded-2xl border border-border bg-surface/40 p-4 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <KeyRound className="h-4 w-4 text-amber-300" />
              <h2 className="text-sm font-semibold text-foreground">Yaşam Anahtarı</h2>
            </div>
            {hasPasskeys && <span className="text-[9px] uppercase tracking-wider text-emerald-300">Aktif</span>}
          </div>
          <p className="text-[11px] text-muted-foreground">
            Cihazınızın FaceID / TouchID / Windows Hello sensörüyle şifresiz giriş yapın.
          </p>

          {!isSupported ? (
            <p className="text-[11px] text-rose-300">Bu cihaz Yaşam Anahtarı'nı desteklemiyor.</p>
          ) : passkeys.length === 0 ? (
            <Button size="sm" disabled={busy} onClick={() => register()} className="w-full">
              <Plus className="h-3.5 w-3.5 mr-1" /> {busy ? "Kaydediliyor…" : "Yaşam Anahtarı Ekle"}
            </Button>
          ) : (
            <div className="space-y-2">
              {passkeys.map((p) => (
                <div key={p.id} className="flex items-center gap-3 rounded-xl border border-amber-400/20 bg-black/30 px-3 py-2">
                  <Smartphone className="h-4 w-4 text-amber-300" />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm text-foreground truncate">{p.device_label}</p>
                    <p className="text-[10px] text-muted-foreground">
                      {p.last_used_at
                        ? `Son: ${formatDistanceToNow(new Date(p.last_used_at), { addSuffix: true })}`
                        : `Eklendi: ${formatDistanceToNow(new Date(p.created_at), { addSuffix: true })}`}
                    </p>
                  </div>
                  <Button variant="ghost" size="sm" onClick={() => revoke(p.id)} aria-label="İptal">
                    <ShieldOff className="h-4 w-4 text-rose-300" />
                  </Button>
                </div>
              ))}
              <Button size="sm" variant="outline" disabled={busy} onClick={() => register()} className="w-full">
                <Plus className="h-3.5 w-3.5 mr-1" /> Başka Cihaz Ekle
              </Button>
            </div>
          )}
        </div>

        {/* Active sessions */}
        <div className="rounded-2xl border border-border bg-surface/40 p-4">
          <div className="flex items-center gap-2 mb-3">
            <Smartphone className="h-4 w-4 text-foreground" />
            <h2 className="text-sm font-semibold text-foreground">Aktif Cihazlar</h2>
          </div>
          <SessionsList />
        </div>
      </div>
    </AppShell>
  );
}

