  const [submitting, setSubmitting] = useState(false);
  const [bookingNote, setBookingNote] = useState("");
  const [showBooking, setShowBooking] = useState(false);

  useEffect(() => {
    const fetch = async () => {
      const { data } = await supabase
        .from("services")
        .select("*")
        .eq("id", serviceId)
        .single();
      if (data) {
        setService(data);
        const { data: prof } = await supabase
          .from("profiles")
          .select("display_name, avatar_url, kurd_id, city, is_online")
          .eq("user_id", data.provider_id)
          .single();
        if (prof) setProvider(prof as ProviderProfile);
      }
      setLoading(false);
    };
    fetch();
  }, [serviceId]);

  const handleContact = async () => {
    if (!user || !service) return;
    try {
      const room = await createDirectChat(user.id, service.provider_id);
      navigate({ to: "/chat" });
