          <Button variant="neon" asChild><Link to="/explore" search={{}}>Browse Services</Link></Button>
        </div>
      </AppShell>
    );
  }

  const isOwner = user?.id === service.provider_id;

  return (
    <AppShell>
      <div className="px-4 pt-4 pb-8">
        <Link to="/explore" search={{}} className="flex items-center gap-1 text-sm text-muted-foreground mb-4">
          <ArrowLeft className="h-4 w-4" /> Back
        </Link>

        {/* Hero */}
        <div className="rounded-2xl border border-border bg-surface p-5">
          <div className="flex items-start gap-4">
            <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-xl bg-accent text-3xl">
              {categoryEmojis[service.category] || "🔧"}
            </div>
            <div className="flex-1 min-w-0">
              <h1 className="text-lg font-bold text-foreground">{service.title}</h1>
              <span className="mt-0.5 inline-block rounded-full bg-neon/10 px-2 py-0.5 text-[10px] font-medium text-neon capitalize">
                {service.category}
              </span>
              <div className="mt-1 flex items-center gap-3">
                <div className="flex items-center gap-0.5">
                  <Star className="h-3.5 w-3.5 fill-gold text-gold" />
                  <span className="text-xs font-medium text-gold">{Number(service.rating || 0).toFixed(1)}</span>
                  <span className="text-[10px] text-muted-foreground">({service.review_count || 0})</span>
                </div>
                <div className="flex items-center gap-0.5">
                  <MapPin className="h-3.5 w-3.5 text-muted-foreground" />
                  <span className="text-xs text-muted-foreground">{service.city}</span>
                </div>
              </div>
            </div>
            <span className="text-xl font-bold text-neon">€{Number(service.price).toFixed(0)}</span>
          </div>

          {service.description && (
            <p className="mt-4 text-sm text-muted-foreground leading-relaxed">{service.description}</p>
          )}
        </div>

        {/* Provider */}
        {provider && (
          <div className="mt-3 rounded-2xl border border-border bg-surface p-4">
            <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2">Provider</h3>
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-full bg-accent text-lg border border-border">
                {provider.avatar_url ? (
                  <img src={provider.avatar_url} className="h-10 w-10 rounded-full object-cover" alt="" />
                ) : "👤"}
              </div>
              <div className="flex-1">
                <p className="text-sm font-semibold text-foreground">{provider.display_name}</p>
                <p className="text-[10px] text-muted-foreground">{provider.kurd_id} · {provider.city}</p>
              </div>
              <span className={`h-2.5 w-2.5 rounded-full ${provider.is_online ? "bg-neon" : "bg-muted-foreground/30"}`} />
            </div>
          </div>
        )}

        {/* Action buttons */}
        {!isOwner && user && (
          <div className="mt-3 flex gap-2">
            <Button variant="neon" className="flex-1" onClick={handleContact}>
              <MessageCircle className="h-4 w-4 mr-1" /> İletişime Geç
            </Button>
            <Button variant="outline" className="flex-1" onClick={() => setShowBooking(!showBooking)}>
              <ShoppingCart className="h-4 w-4 mr-1" /> Rezervasyon
            </Button>
          </div>
        )}

        {!user && (
          <Button variant="neon" className="mt-3 w-full" asChild>
            <Link to="/login">Sign in to contact or book</Link>
          </Button>
        )}

        {/* Booking form */}
        {showBooking && (
          <div className="mt-3 rounded-2xl border border-border bg-surface p-4 space-y-3">
            <h3 className="text-sm font-semibold text-foreground">Book this service — €{Number(service.price).toFixed(0)}</h3>
            <textarea
              placeholder="Add a note (optional)..."
              value={bookingNote}
              onChange={(e) => setBookingNote(e.target.value)}
              className="h-20 w-full rounded-lg border border-border bg-background px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:border-neon resize-none"
            />
            <Button variant="neon" className="w-full" onClick={handleBook} disabled={submitting}>
              {submitting ? "Processing..." : "Confirm Booking"}
            </Button>
          </div>
        )}

        {/* Reviews */}
        <div className="mt-4">
          <h3 className="text-sm font-semibold text-foreground mb-3">
            Reviews ({reviews.length})
          </h3>

          {/* Add review */}
          {user && !isOwner && (
            <div className="rounded-xl border border-border bg-surface p-3 mb-3 space-y-2">
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map((s) => (
                  <button key={s} aria-label={`${s} yıldız`} onClick={() => setReviewRating(s)}>
                    <Star className={`h-5 w-5 ${s <= reviewRating ? "fill-gold text-gold" : "text-muted-foreground/30"}`} />
                  </button>
                ))}
              </div>
              <div className="flex gap-2">
                <input
                  type="text"
                  placeholder="Write a review..."
                  value={reviewComment}
                  onChange={(e) => setReviewComment(e.target.value)}
                  className="h-9 flex-1 rounded-lg border border-border bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:border-neon"
                />
                <button aria-label="Yorum gönder" onClick={handleReview} disabled={submitting} className="flex h-9 w-9 items-center justify-center rounded-lg bg-neon text-neon-foreground">
                  <Send className="h-4 w-4" />
                </button>
              </div>
            </div>
          )}

          {reviewsLoading ? (
            <p className="text-xs text-muted-foreground">Loading reviews...</p>
          ) : reviews.length === 0 ? (
            <p className="text-xs text-muted-foreground py-4 text-center">No reviews yet</p>
          ) : (
            <div className="space-y-2">
              {reviews.map((r) => (
                <div key={r.id} className="rounded-xl border border-border bg-surface p-3">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-medium text-foreground">{r.reviewer_name}</span>
                    <div className="flex gap-0.5">
                      {[1, 2, 3, 4, 5].map((s) => (
                        <Star key={s} className={`h-3 w-3 ${s <= r.rating ? "fill-gold text-gold" : "text-muted-foreground/20"}`} />
                      ))}
                    </div>
                  </div>
                  {r.comment && <p className="mt-1 text-xs text-muted-foreground">{r.comment}</p>}
                  <p className="mt-1 text-[9px] text-muted-foreground">
                    {new Date(r.created_at).toLocaleDateString()}
                  </p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </AppShell>
  );
}

