/**
 * Settings → Authorized Apps
 *
 * Lists every 3rd-party site that the citizen has connected with their Kurd-ID.
 * One-click revoke per app + per-app audit log drawer.
 */
import { createFileRoute, Link } from "@tanstack/react-router";
import { useEffect, useState, useCallback } from "react";
import { AppShell } from "@/components/layout/AppShell";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { ArrowLeft, ShieldCheck, ExternalLink, Trash2, History, BadgeCheck, X, Globe } from "lucide-react";
import { Button } from "@/components/ui/button";

export const Route = createFileRoute("/settings/authorized-apps")({
  component: AuthorizedAppsPage,
  head: () => ({
    meta: [
      { title: "Yetkili Uygulamalar – Jiyan Europe" },
      { name: "description", content: "Kurd-ID ile bağladığın uygulamaları yönet." },
    ],
  }),
});

interface AppRow {
  app_id: string;
  client_id: string;
  app_name: string;
  app_description: string | null;
  logo_url: string | null;
  homepage_url: string | null;
  is_verified: boolean;
  scopes: string[];
  granted_at: string | null;
  last_used_at: string | null;
  active_grant_count: number;
  is_revoked: boolean;
}

interface AuditRow {
  id: string;
  app_id: string;
  app_name: string;
  logo_url: string | null;
  action: string;
  scopes: string[];
  metadata: Record<string, unknown> | null;
  created_at: string;
}

const ACTION_META: Record<string, { label: string; color: string }> = {
  granted: { label: "İzin verildi", color: "text-emerald-300 bg-emerald-500/10 border-emerald-500/30" },
  exchanged: { label: "Token alındı", color: "text-blue-300 bg-blue-500/10 border-blue-500/30" },
  refreshed: { label: "Yenilendi", color: "text-amber-300 bg-amber-500/10 border-amber-500/30" },
  userinfo: { label: "Profil okundu", color: "text-muted-foreground bg-muted/30 border-border" },
  revoked: { label: "Bağlantı kesildi", color: "text-rose-300 bg-rose-500/10 border-rose-500/30" },
};

function fmtDate(iso: string | null): string {
  if (!iso) return "—";
  try {
    return new Date(iso).toLocaleString("tr-TR", {
      day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit",
    });
  } catch { return iso; }
}

function AuthorizedAppsPage() {
  const { user, loading } = useAuth();
  const [apps, setApps] = useState<AppRow[]>([]);
  const [loadingApps, setLoadingApps] = useState(true);
  const [revoking, setRevoking] = useState<string | null>(null);
  const [auditAppId, setAuditAppId] = useState<string | null>(null);
  const [audit, setAudit] = useState<AuditRow[]>([]);
  const [loadingAudit, setLoadingAudit] = useState(false);

  const loadApps = useCallback(async () => {
    if (!user) return;
    setLoadingApps(true);
    const { data, error } = await supabase.rpc("kurdid_sso_list_user_apps");
    if (error) {
      toast.error(error.message || "Uygulamalar yüklenemedi");
      setApps([]);
    } else {
      setApps((data ?? []) as AppRow[]);
    }
    setLoadingApps(false);
  }, [user]);

  useEffect(() => { void loadApps(); }, [loadApps]);

  const handleRevoke = async (app: AppRow) => {
    if (!confirm(`"${app.app_name}" uygulamasının erişimini iptal etmek istediğine emin misin?`)) return;
    setRevoking(app.app_id);
    const { error } = await supabase.rpc("kurdid_sso_user_revoke_app", { _app_id: app.app_id });
    setRevoking(null);
    if (error) {
      toast.error(error.message || "İptal başarısız");
      return;
    }
    toast.success(`${app.app_name} bağlantısı kesildi`);
    void loadApps();
  };

  const openAudit = async (appId: string) => {
    setAuditAppId(appId);
    setLoadingAudit(true);
    const { data, error } = await supabase.rpc("kurdid_sso_user_audit_log", { _app_id: appId, _limit: 100 });
    setLoadingAudit(false);
    if (error) {
      toast.error(error.message || "Geçmiş yüklenemedi");
      setAudit([]);
      return;
    }
    setAudit((data ?? []) as AuditRow[]);
  };

  if (loading) {
    return (
      <AppShell>
        <div className="flex items-center justify-center pt-32">
          <div className="h-8 w-8 animate-spin rounded-full border-2 border-neon border-t-transparent" />
        </div>
      </AppShell>
    );
  }

  if (!user) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center px-4 pt-20 text-center">
          <p className="text-muted-foreground text-sm mb-4">Bu sayfa için giriş yapın</p>
          <Button variant="neon" asChild><Link to="/login">Giriş Yap</Link></Button>
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <div className="px-4 pt-6 pb-8">
        {/* Header */}
        <div className="flex items-center gap-3 mb-6">
          <Link to="/settings" className="text-muted-foreground hover:text-foreground">
            <ArrowLeft className="h-5 w-5" />
          </Link>
          <div className="flex-1">
            <h1 className="text-xl font-bold text-foreground">Yetkili Uygulamalar</h1>
            <p className="text-[11px] text-muted-foreground">Kurd-ID ile bağladığın 3. parti uygulamalar</p>
          </div>
          <Link
            to="/settings/sso-audit"
            className="flex items-center gap-1 rounded-full border border-border bg-surface px-3 py-1.5 text-[11px] text-muted-foreground hover:text-foreground"
          >
            <History className="h-3.5 w-3.5" /> Tüm Geçmiş
          </Link>
        </div>

        {/* Empty / loading states */}
        {loadingApps ? (
          <div className="flex items-center justify-center py-20">
            <div className="h-6 w-6 animate-spin rounded-full border-2 border-neon border-t-transparent" />
          </div>
        ) : apps.length === 0 ? (
          <div className="flex flex-col items-center justify-center rounded-2xl border border-dashed border-border bg-surface/40 px-6 py-12 text-center">
            <ShieldCheck className="h-10 w-10 text-muted-foreground mb-3" />
            <p className="text-sm font-medium text-foreground">Henüz bağlı uygulama yok</p>
            <p className="mt-1 text-xs text-muted-foreground max-w-[260px]">
              Bir 3. parti site "Login with Kurd-ID" butonuna bastığında onayladığın uygulamalar burada listelenir.
            </p>
            <Link
              to="/developers/sso"
              className="mt-4 inline-flex items-center gap-1.5 rounded-lg bg-primary/15 px-3 py-2 text-xs font-medium text-primary hover:bg-primary/25"
            >
              Geliştirici Portalı →
            </Link>
          </div>
        ) : (
          <div className="space-y-3">
            {apps.map((app) => (
              <div
                key={app.app_id}
                className={`relative overflow-hidden rounded-2xl border bg-card/60 p-4 transition-all ${
                  app.is_revoked ? "border-border opacity-60" : "border-primary/20 hover:border-primary/40"
                }`}
              >
                <div className="flex items-start gap-3">
                  {/* Logo */}
                  <div className="flex h-12 w-12 flex-shrink-0 items-center justify-center overflow-hidden rounded-xl bg-muted">
                    {app.logo_url ? (
                      <img src={app.logo_url} alt={app.app_name} className="h-full w-full object-cover" />
                    ) : (
                      <Globe className="h-6 w-6 text-muted-foreground" />
                    )}
                  </div>

                  {/* Info */}
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-1.5">
                      <h3 className="truncate text-sm font-semibold text-foreground">{app.app_name}</h3>
                      {app.is_verified && (
                        <BadgeCheck className="h-3.5 w-3.5 flex-shrink-0 text-blue-400" />
                      )}
                      {app.is_revoked && (
                        <span className="rounded-full bg-rose-500/15 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider text-rose-300">
                          İptal
                        </span>
                      )}
                    </div>
                    {app.app_description && (
                      <p className="mt-0.5 line-clamp-1 text-[11px] text-muted-foreground">{app.app_description}</p>
                    )}
                    <p className="mt-1 text-[10px] text-muted-foreground/70">
                      Son kullanım: {fmtDate(app.last_used_at)} · İlk izin: {fmtDate(app.granted_at)}
                    </p>

                    {/* Scopes */}
                    {app.scopes.length > 0 && (
                      <div className="mt-2 flex flex-wrap gap-1">
                        {app.scopes.map((s) => (
                          <span key={s} className="rounded-md border border-border bg-muted/40 px-1.5 py-0.5 text-[9px] font-medium text-muted-foreground">
                            {s}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                {/* Actions */}
                <div className="mt-3 flex items-center gap-2">
                  <button
                    onClick={() => openAudit(app.app_id)}
                    className="flex items-center gap-1 rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[11px] font-medium text-muted-foreground hover:text-foreground"
                  >
                    <History className="h-3 w-3" /> Geçmiş
                  </button>
                  {app.homepage_url && (
                    <a
                      href={app.homepage_url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-1 rounded-lg border border-border bg-surface px-2.5 py-1.5 text-[11px] font-medium text-muted-foreground hover:text-foreground"
                    >
                      <ExternalLink className="h-3 w-3" /> Aç
                    </a>
                  )}
                  <div className="flex-1" />
                  {!app.is_revoked && (
                    <button
                      onClick={() => handleRevoke(app)}
                      disabled={revoking === app.app_id}
                      className="flex items-center gap-1 rounded-lg border border-rose-500/30 bg-rose-500/10 px-3 py-1.5 text-[11px] font-semibold text-rose-300 transition-all hover:bg-rose-500/20 active:scale-95 disabled:opacity-50"
                    >
                      <Trash2 className="h-3 w-3" />
                      {revoking === app.app_id ? "İptal ediliyor..." : "Erişimi İptal Et"}
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Audit drawer */}
      {auditAppId && (
        <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/60 backdrop-blur-sm" onClick={() => setAuditAppId(null)}>
          <div
            className="max-h-[80vh] w-full max-w-md overflow-y-auto rounded-t-3xl border border-border bg-card p-5"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="mb-4 flex items-center justify-between">
              <h2 className="text-base font-bold text-foreground">Erişim Geçmişi</h2>
              <button onClick={() => setAuditAppId(null)} className="rounded-full p-1 text-muted-foreground hover:bg-muted hover:text-foreground">
                <X className="h-4 w-4" />
              </button>
            </div>

            {loadingAudit ? (
              <div className="flex items-center justify-center py-10">
                <div className="h-5 w-5 animate-spin rounded-full border-2 border-neon border-t-transparent" />
              </div>
            ) : audit.length === 0 ? (
              <p className="py-8 text-center text-xs text-muted-foreground">Bu uygulama için kayıt yok</p>
            ) : (
              <ul className="space-y-2">
                {audit.map((row) => {
                  const meta = ACTION_META[row.action] ?? { label: row.action, color: "text-muted-foreground bg-muted/30 border-border" };
                  return (
                    <li key={row.id} className={`flex items-start gap-3 rounded-xl border bg-card/40 p-3 ${meta.color}`}>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-2">
                          <span className="text-[11px] font-semibold uppercase tracking-wider">{meta.label}</span>
                        </div>
                        <p className="mt-0.5 text-[10px] opacity-80">{fmtDate(row.created_at)}</p>
                        {row.scopes.length > 0 && (
                          <div className="mt-1.5 flex flex-wrap gap-1">
                            {row.scopes.map((s) => (
                              <span key={s} className="rounded bg-background/40 px-1 py-0.5 text-[9px]">
                                {s}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>
                    </li>
                  );
                })}
              </ul>
            )}
          </div>
        </div>
      )}
    </AppShell>
  );
}

