                    </div>
                    <p className="mt-0.5 text-[10px] opacity-70">{fmtDate(row.created_at)}</p>
                    {row.scopes.length > 0 && (
                      <div className="mt-1.5 flex flex-wrap gap-1">
                        {row.scopes.map((s) => (
                          <span key={s} className="rounded bg-background/40 px-1 py-0.5 text-[9px]">
                            {s}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </AppShell>
  );
}

