/**
 * /settings — Unified "Sovereign Settings & Comms" hub.
 *
 * Apple-style consolidated panel with 4 glass-card groups:
 *   1) Identity   — Profile, Edit, Kurd-ID
 *   2) Comms      — Sovereign Mail (with unread badge), Chat, Phone privacy
 *   3) Security   — 2FA / TOTP, Yaşam Anahtarı, Authorized sessions, recovery
 *   4) Legal/Sys  — KYC, Privacy protocols, App Library gates, Terms
 *
 * Pitch black + 24K gold + glassmorphism, with status indicators per row
 * ("Safe" shield vs pulsing rose dot). Drag-down refreshes data. Compose
 * shortcut for mail. Every existing piece (SovereignSecurityCard,
 * JiyanAuthenticator, SessionsList, GuestRecoveryCard) is composed in.
 */
import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
