  const [signingOut, setSigningOut] = useState(false);

  // Pull-to-refresh: refresh profile + mail when the user pulls down.
  useEffect(() => {
    let startY = 0;
    const onTouchStart = (e: TouchEvent) => {
      if (window.scrollY === 0) startY = e.touches[0].clientY;
