        {/* Görünüm & Tema — quick access to the unified theme picker */}
        <SovereignSettingsGroup title="Görünüm · Tema" caption="Tüm widget, mini-app ve çekmece eşzamanlı bu temayı kullanır.">
          <SovereignSettingRow
