import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useRef, useState } from "react";
import { AppShell } from "@/components/layout/AppShell";
import { useAuth } from "@/hooks/useAuth";
import { useSosEvidence } from "@/hooks/useSosEvidence";
import {
  ChevronLeft,
  ShieldAlert,
  Download,
  Upload,
  FileVideo,
  FileImage,
  FileAudio,
  File as FileIcon,
  MapPin,
  Trash2,
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

export const Route = createFileRoute("/sos-evidence")({
  head: () => ({
    meta: [
      { title: "SOS Evidence Vault — Sovereign Kanıt Kasası" },
      {
        name: "description",
        content:
          "Acil durum kanıtlarınızı şifreli kasada saklayın ve zaman damgalı bir paket olarak indirin.",
      },
    ],
  }),
  component: SosEvidencePage,
});

function fmtBytes(n: number) {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 * 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  return `${(n / 1024 / 1024 / 1024).toFixed(2)} GB`;
}

function iconFor(ct: string) {
  if (ct.startsWith("image/")) return FileImage;
  if (ct.startsWith("video/")) return FileVideo;
  if (ct.startsWith("audio/")) return FileAudio;
  return FileIcon;
}

function SosEvidencePage() {
  const { user, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const fileRef = useRef<HTMLInputElement>(null);
  const [coords, setCoords] = useState<{ lat: number | null; lon: number | null }>({
    lat: null,
    lon: null,
  });
  const { files, loading, exporting, uploading, totalBytes, exportBundle, uploadEvidence, refresh } =
    useSosEvidence(user?.id);

  useEffect(() => {
    if (!authLoading && !user) navigate({ to: "/login" });
  }, [authLoading, user, navigate]);

  // Best-effort capture of current location for incoming uploads
  useEffect(() => {
    if (typeof navigator === "undefined" || !navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(
      (pos) => setCoords({ lat: pos.coords.latitude, lon: pos.coords.longitude }),
      () => {
        /* user declined */
      },
      { maximumAge: 60_000, timeout: 5_000 },
    );
  }, []);

  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    await uploadEvidence(file, { latitude: coords.lat, longitude: coords.lon });
    if (fileRef.current) fileRef.current.value = "";
  };

  const handleDelete = async (id: string, path: string) => {
    if (!confirm("Bu kanıt silinsin mi?")) return;
    await supabase.storage.from("sos-evidence").remove([path]);
    const { error } = await supabase.from("sos_evidence_files").delete().eq("id", id);
    if (error) {
      toast.error("Silinemedi: " + error.message);
      return;
    }
    toast.success("Silindi");
    refresh();
  };

  if (authLoading || !user) {
    return (
      <AppShell>
        <div className="min-h-screen bg-[#0A0A0A] flex items-center justify-center">
          <div className="w-10 h-10 rounded-full border-2 border-amber-400/30 border-t-amber-400 animate-spin" />
        </div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <div className="min-h-screen bg-[#0A0A0A] text-foreground sovereign-grain pb-24">
        {/* Header */}
        <div className="sticky top-0 z-30 backdrop-blur-xl bg-[#0A0A0A]/85 border-b border-red-500/20 px-4 py-3">
          <div className="flex items-center gap-2.5">
            <button
              onClick={() => navigate({ to: "/dashboard" })}
              className="w-9 h-9 rounded-full bg-white/5 border border-white/10 flex items-center justify-center"
              aria-label="Geri"
            >
              <ChevronLeft className="w-4 h-4 text-amber-300" />
            </button>
            <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-red-500/30 to-red-700/20 border border-red-400/40 flex items-center justify-center">
              <ShieldAlert className="w-4 h-4 text-red-300" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-[8px] font-mono uppercase tracking-[0.25em] text-red-300/80">
                Sovereign · Encrypted
              </div>
              <div className="text-[12px] font-bold uppercase tracking-widest text-amber-100">
                SOS Evidence Vault
              </div>
            </div>
          </div>
        </div>

        {/* Stats + actions */}
        <div className="px-4 pt-4 space-y-3">
          <div className="rounded-xl border border-amber-400/20 bg-white/[0.03] p-3">
            <div className="flex items-center justify-between">
              <div>
                <div className="text-[9px] font-mono uppercase tracking-widest text-amber-300/70">
                  Kasadaki Kanıt
                </div>
                <div className="text-2xl font-black text-amber-100 tabular-nums">
                  {files.length}
                </div>
              </div>
              <div className="text-right">
                <div className="text-[9px] font-mono uppercase tracking-widest text-amber-300/70">
                  Toplam Boyut
                </div>
                <div className="text-sm font-bold text-amber-300 tabular-nums">
                  {fmtBytes(totalBytes)}
                </div>
              </div>
            </div>
            {coords.lat !== null && (
              <div className="mt-2 flex items-center gap-1 text-[10px] text-amber-200/80">
                <MapPin className="w-3 h-3" />
                {coords.lat.toFixed(4)}, {coords.lon?.toFixed(4)}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={() => fileRef.current?.click()}
              disabled={uploading}
              className="flex items-center justify-center gap-2 px-3 py-3 rounded-xl bg-white/5 border border-amber-400/30 text-amber-100 font-bold text-[12px] active:scale-95 disabled:opacity-50"
            >
              <Upload className="w-4 h-4" />
              {uploading ? "Yükleniyor…" : "Kanıt Ekle"}
            </button>
            <button
              onClick={exportBundle}
              disabled={exporting || files.length === 0}
              className="flex items-center justify-center gap-2 px-3 py-3 rounded-xl bg-gradient-to-br from-amber-300 to-amber-500 text-black font-bold text-[12px] active:scale-95 disabled:opacity-50"
            >
              <Download className="w-4 h-4" />
              {exporting ? "Hazırlanıyor…" : "Paketi İndir"}
            </button>
          </div>
          <input
            ref={fileRef}
            type="file"
            accept="image/*,video/*,audio/*,application/pdf"
            onChange={handleFile}
            className="hidden"
          />
        </div>

        {/* List */}
        <div className="px-4 pt-4">
          <div className="text-[9px] font-mono uppercase tracking-[0.25em] text-amber-300/70 mb-2">
            Kanıt Listesi
          </div>
          {loading && (
            <div className="text-center py-8">
              <div className="w-8 h-8 mx-auto rounded-full border-2 border-amber-400/30 border-t-amber-400 animate-spin" />
            </div>
          )}
          {!loading && files.length === 0 && (
            <div className="rounded-xl border border-white/10 bg-white/[0.02] p-6 text-center text-[11px] opacity-60">
              Henüz kanıt yok. SOS sırasında yakalanan kayıtlar buraya gelir.
            </div>
          )}
          <div className="space-y-1.5">
            {files.map((f) => {
              const Icon = iconFor(f.content_type);
              return (
                <div
                  key={f.id}
                  className="flex items-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] px-2.5 py-2"
                >
                  <div className="w-8 h-8 rounded-md bg-amber-400/10 border border-amber-400/25 flex items-center justify-center shrink-0">
                    <Icon className="w-4 h-4 text-amber-300" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="text-[12px] font-bold text-amber-100 truncate">
                      {f.file_name}
                    </div>
                    <div className="text-[9px] font-mono opacity-60 flex items-center gap-2">
                      <span>{new Date(f.captured_at).toLocaleString()}</span>
                      <span>·</span>
                      <span>{fmtBytes(f.size_bytes)}</span>
                      {f.latitude !== null && (
                        <>
                          <span>·</span>
                          <MapPin className="w-2.5 h-2.5" />
                          <span>
                            {f.latitude.toFixed(3)},{f.longitude?.toFixed(3)}
                          </span>
                        </>
                      )}
                    </div>
                  </div>
                  <button
                    onClick={() => handleDelete(f.id, f.storage_path)}
                    className="w-8 h-8 rounded-md bg-white/5 border border-white/10 flex items-center justify-center text-red-300 active:scale-90"
                    aria-label="Sil"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </AppShell>
  );
}

