import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { z } from "zod";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Loader2, Shield, CheckCircle2, AlertTriangle, LogIn } from "lucide-react";
import { toast } from "sonner";

const searchSchema = z.object({
  client_id: z.string().min(1),
  redirect_uri: z.string().url(),
  scope: z.string().optional(),
  state: z.string().optional(),
});

export const Route = createFileRoute("/sso/authorize")({
  validateSearch: searchSchema,
  component: SsoAuthorizePage,
  head: () => ({
    meta: [{ title: "Kurd-ID Login — Authorize" }],
  }),
});

const SCOPE_LABELS: Record<string, { label: string; desc: string }> = {
  openid: { label: "Identity", desc: "Confirm you are a Sovereign citizen" },
  profile: { label: "Profile", desc: "Display name, avatar, city" },
  kurd_id: { label: "Kurd-ID Number", desc: "Your +777 Kurd-ID handle" },
  email: { label: "Email", desc: "Your registered email address" },
  kyc: { label: "KYC Status", desc: "Whether your identity is verified" },
};

interface AppMeta {
  id: string;
  client_id: string;
  app_name: string;
  app_description: string;
  logo_url: string | null;
  homepage_url: string | null;
  redirect_uris: string[];
  scopes: string[];
  is_verified: boolean;
}

function SsoAuthorizePage() {
  const search = Route.useSearch();
  const navigate = useNavigate();
  const { user, loading: authLoading } = useAuth();
  const [app, setApp] = useState<AppMeta | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [authorizing, setAuthorizing] = useState(false);

  const requestedScopes = (search.scope ?? "openid profile kurd_id")
    .split(/[\s,]+/)
    .filter(Boolean);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const { data, error: e } = await supabase.rpc("kurdid_sso_get_app_public", {
        _client_id: search.client_id,
      });
      if (cancelled) return;
      if (e || !data || data.length === 0) {
        setError("Bilinmeyen veya devre dışı uygulama");
      } else {
        const a = data[0] as AppMeta;
        if (!a.redirect_uris.includes(search.redirect_uri)) {
          setError("Geçersiz redirect_uri — uygulama sahibi ile iletişime geçin");
        } else {
          setApp(a);
        }
      }
      setLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [search.client_id, search.redirect_uri]);

  const handleApprove = async () => {
    if (!app) return;
    setAuthorizing(true);
    const { data, error: e } = await supabase.rpc("kurdid_sso_authorize", {
      _client_id: app.client_id,
      _redirect_uri: search.redirect_uri,
      _scopes: requestedScopes,
    });
    if (e || !data || data.length === 0) {
      toast.error("Yetkilendirme başarısız");
      setAuthorizing(false);
      return;
    }
    const code = (data[0] as { auth_code: string }).auth_code;
    const url = new URL(search.redirect_uri);
    url.searchParams.set("code", code);
    if (search.state) url.searchParams.set("state", search.state);
    window.location.replace(url.toString());
  };

  const handleDeny = () => {
    const url = new URL(search.redirect_uri);
    url.searchParams.set("error", "access_denied");
    if (search.state) url.searchParams.set("state", search.state);
    window.location.replace(url.toString());
  };

  if (authLoading || loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background p-4">
        <Card className="max-w-md p-6 text-center">
          <AlertTriangle className="mx-auto h-12 w-12 text-destructive" />
          <h1 className="mt-4 text-xl font-semibold">Hata</h1>
          <p className="mt-2 text-sm text-muted-foreground">{error}</p>
        </Card>
      </div>
    );
  }

  if (!user) {
    const next = window.location.pathname + window.location.search;
    return (
      <div className="flex min-h-screen items-center justify-center bg-background p-4">
        <Card className="max-w-md p-6 text-center">
          <Shield className="mx-auto h-12 w-12 text-primary" />
          <h1 className="mt-4 text-xl font-semibold">Kurd-ID ile devam et</h1>
          <p className="mt-2 text-sm text-muted-foreground">
            <span className="font-semibold text-foreground">{app?.app_name}</span> uygulamasına giriş yapmak için önce Kurd-ID hesabınıza giriş yapmalısınız.
          </p>
          <Button
            className="mt-6 w-full"
            onClick={() => navigate({ to: "/login", search: { redirect: next } as never })}
          >
            <LogIn className="mr-2 h-4 w-4" />
            Kurd-ID ile Giriş Yap
          </Button>
        </Card>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-background p-4">
      <Card className="w-full max-w-md overflow-hidden">
        <div className="bg-gradient-to-br from-primary/15 via-primary/5 to-transparent p-6 text-center">
          <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-2xl bg-background/60 backdrop-blur">
            {app?.logo_url ? (
              <img src={app.logo_url} alt={app.app_name} className="h-12 w-12 rounded-xl object-cover" />
            ) : (
              <Shield className="h-8 w-8 text-primary" />
            )}
          </div>
          <h1 className="mt-3 text-xl font-bold">{app?.app_name}</h1>
          {app?.is_verified && (
            <div className="mt-1 inline-flex items-center gap-1 text-xs text-primary">
              <CheckCircle2 className="h-3 w-3" /> Doğrulanmış uygulama
            </div>
          )}
          {app?.app_description && (
            <p className="mt-2 text-sm text-muted-foreground">{app.app_description}</p>
          )}
        </div>

        <div className="p-6">
          <p className="text-sm">
            <span className="font-semibold">{app?.app_name}</span> aşağıdaki bilgilere erişmek istiyor:
          </p>

          <ul className="mt-4 space-y-3">
            {requestedScopes.map((s: string) => {
              const meta = SCOPE_LABELS[s] ?? { label: s, desc: "Özel kapsam" };
              return (
                <li key={s} className="flex items-start gap-3 rounded-lg border border-border/50 bg-card/50 p-3">
                  <CheckCircle2 className="mt-0.5 h-4 w-4 flex-shrink-0 text-primary" />
                  <div>
                    <div className="text-sm font-medium">{meta.label}</div>
                    <div className="text-xs text-muted-foreground">{meta.desc}</div>
                  </div>
                </li>
              );
            })}
          </ul>

          <p className="mt-4 text-xs text-muted-foreground">
            Yönlendirileceğiniz adres:{" "}
            <code className="rounded bg-muted px-1 py-0.5 text-[10px]">{new URL(search.redirect_uri).host}</code>
          </p>

          <div className="mt-6 grid grid-cols-2 gap-3">
            <Button variant="outline" onClick={handleDeny} disabled={authorizing}>
              Reddet
            </Button>
            <Button onClick={handleApprove} disabled={authorizing}>
              {authorizing ? <Loader2 className="h-4 w-4 animate-spin" /> : "Yetkilendir"}
            </Button>
          </div>
        </div>
      </Card>
    </div>
  );
}

