import { createFileRoute, Link } from "@tanstack/react-router";
import { AppShell } from "@/components/layout/AppShell";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/hooks/useAuth";
import { useWallet } from "@/hooks/useWallet";

import { useDcRate } from "@/hooks/useDcRate";
import { ArrowDownLeft, ArrowUpRight, Shield, MessageCircle, Flame, Trophy, Package, Lock, Unlock, Send, QrCode, TrendingUp, TrendingDown, Minus } from "lucide-react";
import { useState, useCallback, useEffect } from "react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { SendByKurdId } from "@/components/wallet/SendByKurdId";
import { QrScanToPay } from "@/components/wallet/QrScanToPay";
import { TransactionSuccess } from "@/components/wallet/TransactionSuccess";


const topUpOptions = [50, 100, 250, 500];

type WalletTab = "wallet" | "mystery" | "streak" | "leaderboard";

export const Route = createFileRoute("/wallet")({
  component: WalletPage,
  head: () => ({
    meta: [
      { title: "DiravCash Wallet – Jiyan Europe" },
      { name: "description", content: "Manage your DiravCash wallet. Top up via Stripe and pay for services." },
    ],
  }),
});

function WalletPage() {
  const { user } = useAuth();
  const { balance, lockedBalance, transactions, loading, refetch } = useWallet(user?.id);

  const { rate, trend } = useDcRate();
  const [selectedAmount, setSelectedAmount] = useState<number | null>(null);
  const [activeTab, setActiveTab] = useState<WalletTab>("wallet");
  const [boxOpening, setBoxOpening] = useState(false);
  const [boxResult, setBoxResult] = useState<{ reward_label: string; reward_type: string } | null>(null);
  const [streakData, setStreakData] = useState<{ streak: number; bonus: number; already_claimed: boolean } | null>(null);
  const [streakLoading, setStreakLoading] = useState(false);
  const [unlocking, setUnlocking] = useState(false);
  const [leaderboard, setLeaderboard] = useState<Array<{ user_id: string; display_name: string; avatar_url: string | null; total_spent: number; badge_count: number }>>([]);
  const [leaderboardLoading, setLeaderboardLoading] = useState(false);
  const [showSend, setShowSend] = useState(false);
  const [showQr, setShowQr] = useState(false);
  const [successData, setSuccessData] = useState<{ amount: number; recipient: string } | null>(null);

  const handleTransferSuccess = (amount: number, recipient: string) => {
    setShowSend(false);
    setSuccessData({ amount, recipient });
    refetch();
  };

  const claimDailyLogin = useCallback(async () => {
    if (!user?.id) return;
    setStreakLoading(true);
    const { data, error } = await supabase.rpc("claim_daily_login", { _user_id: user.id });
    if (error) {
      toast.error("Günlük bonus alınamadı");
    } else {
      const result = data as unknown as { streak: number; bonus: number; already_claimed: boolean };
      setStreakData(result);
      if (!result.already_claimed) {
        toast.success(`🔥 ${result.streak}. gün streak! +${result.bonus} DC kazandın!`);
        refetch();
      }
    }
    setStreakLoading(false);
  }, [user?.id, refetch]);

  const openMysteryBox = useCallback(async () => {
    if (!user?.id || boxOpening) return;
    setBoxOpening(true);
    setBoxResult(null);
    const { data, error } = await supabase.rpc("open_mystery_box", { _user_id: user.id });
    if (error) {
      toast.error("Kutu açılamadı");
    } else {
      const result = data as unknown as { success: boolean; error?: string; reward_label: string; reward_type: string };
      if (!result.success) {
        toast.error(result.error || "Yetersiz bakiye");
      } else {
        setBoxResult({ reward_label: result.reward_label, reward_type: result.reward_type });
        toast.success(`🎁 ${result.reward_label}`);
        refetch();
      }
    }
    setBoxOpening(false);
  }, [user?.id, boxOpening, refetch]);

  const fetchLeaderboard = useCallback(async () => {
    setLeaderboardLoading(true);
    const { data } = await supabase.rpc("get_dc_leaderboard");
    if (data) setLeaderboard(data as unknown as typeof leaderboard);
    setLeaderboardLoading(false);
  }, []);

  const unlockBalance = useCallback(async () => {
    if (!user?.id || unlocking) return;
    setUnlocking(true);
    const { data, error } = await supabase.rpc("unlock_weekly_balance", { _user_id: user.id });
    if (error) {
      toast.error("Açma işlemi başarısız");
    } else {
      const result = data as unknown as { success: boolean; error?: string; unlocked?: number; remaining_locked?: number; next_unlock?: string };
      if (!result.success) {
        if (result.next_unlock) {
          const next = new Date(result.next_unlock);
          toast.error(`${result.error} — Sonraki: ${next.toLocaleDateString("tr-TR")}`);
        } else {
          toast.error(result.error || "Hata");
        }
      } else {
        toast.success(`🔓 ${result.unlocked} DC açıldı! Kalan kilitli: ${result.remaining_locked} DC`);
        refetch();
      }
    }
    setUnlocking(false);
  }, [user?.id, unlocking, refetch]);

  useEffect(() => {
    if (activeTab === "leaderboard") fetchLeaderboard();
  }, [activeTab, fetchLeaderboard]);

  useEffect(() => {
    if (activeTab === "streak" && user?.id && !streakData) {
      // Just load streak info without claiming
      supabase
        .from("daily_login_streaks")
        .select("*")
        .eq("user_id", user.id)
        .maybeSingle()
        .then(({ data }) => {
          if (data) {
            const today = new Date().toISOString().split("T")[0];
            setStreakData({
              streak: data.current_streak as number,
              bonus: 0,
              already_claimed: data.last_login_date === today,
            });
          }
        });
    }
  }, [activeTab, user?.id, streakData]);

  if (!user) {
    return (
      <AppShell>
        <div className="flex flex-col items-center justify-center px-4 pt-20 text-center">
          <MessageCircle className="h-12 w-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground text-sm mb-4">
            Cüzdanına erişmek için giriş yap
          </p>
          <Button variant="neon" asChild>
            <Link to="/login">Giriş Yap</Link>
          </Button>
        </div>
      </AppShell>
    );
  }

  const tabs: { id: WalletTab; label: string; icon: React.ReactNode }[] = [
    { id: "wallet", label: "Cüzdan", icon: <Shield className="h-4 w-4" /> },
    { id: "mystery", label: "Kutu", icon: <Package className="h-4 w-4" /> },
    { id: "streak", label: "Streak", icon: <Flame className="h-4 w-4" /> },
    { id: "leaderboard", label: "Sıralama", icon: <Trophy className="h-4 w-4" /> },
  ];

  const eurValue = (balance + lockedBalance) * rate;
  const TrendIcon = trend === "up" ? TrendingUp : trend === "down" ? TrendingDown : Minus;

  return (
    <AppShell>
      {showSend && user && (
        <SendByKurdId
          senderId={user.id}
          onSuccess={handleTransferSuccess}
          onClose={() => setShowSend(false)}
        />
      )}
      {showQr && (
        <QrScanToPay
          onClose={() => setShowQr(false)}
          onScanned={(detected) => {
            setShowQr(false);
            toast.success(`QR detected: ${detected}`);
            setShowSend(true);
          }}
        />
      )}
      {successData && (
        <TransactionSuccess
          amount={successData.amount}
          recipient={successData.recipient}
          onClose={() => setSuccessData(null)}
        />
      )}
      <div className="px-4 pt-4">
        {/* Balance card — banking grade */}
        <div className="relative overflow-hidden rounded-3xl border border-gold/30 bg-gradient-to-br from-surface via-surface to-gold/5 p-5 shadow-[0_8px_30px_rgba(0,0,0,0.25)]">
          <div className="pointer-events-none absolute -right-10 -top-10 h-32 w-32 rounded-full bg-gold/10 blur-3xl" />
          <div className="pointer-events-none absolute -bottom-10 -left-10 h-32 w-32 rounded-full bg-neon/10 blur-3xl" />
          <div className="relative">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Available Balance</p>
                <h2 className="mt-0.5 text-3xl font-bold text-gold text-glow-gold tabular-nums">
                  {loading ? "..." : `DC ${balance.toFixed(2)}`}
                </h2>
                <p className="mt-1 text-[11px] text-muted-foreground tabular-nums">
                  ≈ €{eurValue.toFixed(2)}
                </p>
              </div>
              <div className="flex flex-col items-end gap-1.5">
                <div className="flex items-center gap-1 rounded-lg bg-neon/10 px-2 py-1">
                  <Shield className="h-3 w-3 text-neon" />
                  <span className="text-[10px] font-semibold text-neon">Secured</span>
                </div>
                <div className={`flex items-center gap-1 rounded-lg px-2 py-1 ${
                  trend === "up" ? "bg-green-500/10 text-green-400" :
                  trend === "down" ? "bg-red-500/10 text-red-400" :
                  "bg-secondary text-muted-foreground"
                }`}>
                  <TrendIcon className="h-3 w-3" />
                  <span className="text-[10px] font-mono font-semibold">DC/€ {rate.toFixed(4)}</span>
                </div>
              </div>
            </div>

            {/* Locked balance row */}
            {lockedBalance > 0 && (
              <div className="mt-3 flex items-center justify-between rounded-xl bg-accent/50 border border-border px-3 py-2">
                <div className="flex items-center gap-2">
                  <Lock className="h-3.5 w-3.5 text-muted-foreground" />
                  <div>
                    <p className="text-[11px] font-medium text-muted-foreground">Locked</p>
                    <p className="text-sm font-bold text-foreground tabular-nums">{lockedBalance.toFixed(2)} DC</p>
                  </div>
                </div>
                <button
                  onClick={unlockBalance}
                  disabled={unlocking}
                  className="flex items-center gap-1 rounded-lg bg-gold/10 border border-gold/30 px-2.5 py-1.5 text-[11px] font-semibold text-gold hover:bg-gold/20 transition-all disabled:opacity-50"
                >
                  <Unlock className="h-3 w-3" />
                  {unlocking ? "..." : "Unlock 20%"}
                </button>
              </div>
            )}

            {/* Banking-grade action row */}
            <div className="mt-4 grid grid-cols-2 gap-2">
              <button
                onClick={() => setShowSend(true)}
                className="group relative flex items-center justify-center gap-2 overflow-hidden rounded-xl border border-primary/40 bg-primary/10 py-3 text-sm font-bold text-primary transition-all hover:bg-primary/20 hover:shadow-[0_0_24px_rgba(59,130,246,0.4)] active:scale-95"
              >
                <Send className="h-4 w-4" />
                Send via +777
              </button>
              <button
                onClick={() => setShowQr(true)}
                className="group relative flex items-center justify-center gap-2 overflow-hidden rounded-xl border border-gold/40 bg-gold/10 py-3 text-sm font-bold text-gold transition-all hover:bg-gold/20 hover:shadow-[0_0_24px_rgba(212,175,55,0.4)] active:scale-95"
              >
                <QrCode className="h-4 w-4" />
                QR Scan to Pay
              </button>
            </div>
          </div>
        </div>


        {/* Tabs */}
        <div className="mt-4 flex gap-1 overflow-x-auto rounded-xl bg-surface border border-border p-1">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex flex-1 items-center justify-center gap-1.5 rounded-lg px-2 py-2 text-xs font-semibold transition-all whitespace-nowrap ${
                activeTab === tab.id
                  ? "bg-neon/10 text-neon"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {tab.icon}
              {tab.label}
            </button>
          ))}
        </div>

        {/* Tab content */}
        <div className="mt-4 pb-24">
          {activeTab === "wallet" && (
            <>
              {/* Top-up */}
              <h3 className="text-sm font-semibold text-foreground">Stripe ile Yükle</h3>
