                {topUpOptions.map((amount) => (
                  <button
                    key={amount}
                    onClick={() => setSelectedAmount(amount)}
                    className={`rounded-xl border py-3 text-center text-sm font-semibold transition-all active:scale-95 ${
                      selectedAmount === amount
                        ? "border-neon bg-neon/10 text-neon"
                        : "border-border bg-surface text-foreground hover:border-neon/30 hover:bg-accent"
                    }`}
                  >
                    €{amount}
                  </button>
                ))}
              </div>
              <Button
                variant="neon"
                size="lg"
                className="mt-3 w-full"
                disabled={!selectedAmount}
                onClick={() => {
                  toast.success(`€${selectedAmount} yükleme talebi oluşturuldu!`);
                  setSelectedAmount(null);
                }}
