                  <p>• Günlük harcama limiti: <span className="text-foreground font-medium">500 DC</span></p>
                  <p>• Mystery Box günlük limit: <span className="text-foreground font-medium">10 kutu</span></p>
                  <p>• Kazanımlar kilitli gelir, haftalık %20 açılır</p>
                  <p>• Stripe yüklemeleri anında kullanılabilir</p>
                  <p>• Self-transfer engeli aktif</p>
                </div>
              </div>
              <h3 className="mb-3 mt-6 text-sm font-semibold text-foreground">İşlem Geçmişi</h3>
              <div className="space-y-2">
                {loading ? (
                  <div className="py-8 text-center text-sm text-muted-foreground">Yükleniyor...</div>
                ) : transactions.length === 0 ? (
                  <div className="py-8 text-center text-sm text-muted-foreground">
                    Henüz işlem yok. Cüzdanını yükleyerek başla!
                  </div>
                ) : (
                  transactions.map((tx) => {
                    const isCredit = tx.type === "topup" || tx.type === "refund";
                    return (
                      <div key={tx.id} className="flex items-center gap-3 rounded-xl border border-border bg-surface p-3">
                        <div className={`flex h-9 w-9 items-center justify-center rounded-full ${isCredit ? "bg-neon/10" : "bg-accent"}`}>
                          {isCredit ? <ArrowDownLeft className="h-4 w-4 text-neon" /> : <ArrowUpRight className="h-4 w-4 text-muted-foreground" />}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1">
                            <p className="truncate text-xs font-medium text-foreground">{tx.description || tx.type}</p>
                            {tx.is_locked && <Lock className="h-3 w-3 text-muted-foreground flex-shrink-0" />}
                          </div>
                          <p className="text-[10px] text-muted-foreground">{new Date(tx.created_at).toLocaleDateString()}</p>
                        </div>
                        <p className={`text-sm font-semibold ${isCredit ? (tx.is_locked ? "text-muted-foreground" : "text-neon") : "text-foreground"}`}>
                          {isCredit ? "+" : "-"}DC {Math.abs(tx.amount).toFixed(2)}
                        </p>
                      </div>
                    );
                  })
                )}
              </div>
            </>
          )}

          {activeTab === "mystery" && (
            <div className="flex flex-col items-center text-center">
              <div className="relative mt-4">
                <div className={`text-8xl transition-transform duration-500 ${boxOpening ? "animate-bounce" : ""}`}>
                  🎁
                </div>
                {boxResult && (
                  <div className="absolute -top-2 -right-2 rounded-full bg-gold/20 px-2 py-1 text-xs font-bold text-gold animate-pulse">
                    ÖDÜLLENDİN!
                  </div>
                )}
              </div>

              <h3 className="mt-4 text-lg font-bold text-foreground">Mystery Box</h3>
              <p className="mt-1 text-xs text-muted-foreground">1 DC ile aç, sürpriz ödül kazan!</p>

              {boxResult && (
                <div className="mt-4 w-full rounded-xl border border-gold/30 bg-gold/5 p-4">
                  <p className="text-2xl">{boxResult.reward_label}</p>
                </div>
