                  <div className="flex justify-between"><span>⭐ DC Bonus 5</span><span className="text-foreground">%30</span></div>
                  <div className="flex justify-between"><span>⭐ DC Bonus 15</span><span className="text-foreground">%15</span></div>
                  <div className="flex justify-between"><span>🌟 Nadir Rozet</span><span className="text-foreground">%10</span></div>
                  <div className="flex justify-between"><span>👑 Egemen Mührü</span><span className="text-neon font-semibold">%5</span></div>
                </div>
              </div>

              <Button
                variant="neon"
                size="lg"
                className="mt-4 w-full"
                disabled={boxOpening || balance < 1}
                onClick={openMysteryBox}
              >
                {boxOpening ? "Açılıyor..." : "🎁 1 DC ile Aç"}
              </Button>
              {balance < 1 && (
                <p className="mt-2 text-[10px] text-destructive">Yetersiz bakiye</p>
              )}
              <p className="mt-2 text-[10px] text-muted-foreground">Günlük limit: 10 kutu</p>
            </div>
          )}

          {activeTab === "streak" && (
            <div className="flex flex-col items-center text-center">
              <div className="mt-4 text-7xl">
                {streakData && streakData.streak >= 7 ? "🔥" : "☀️"}
              </div>

              <h3 className="mt-4 text-lg font-bold text-foreground">Günlük Giriş Bonusu</h3>
              <p className="mt-1 text-xs text-muted-foreground">Her gün giriş yap, streak'ini koru!</p>

              {streakData && (
                <div className="mt-4 w-full grid grid-cols-2 gap-3">
                  <div className="rounded-xl border border-border bg-surface p-4">
                    <p className="text-3xl font-bold text-gold">{streakData.streak}</p>
                    <p className="text-[10px] text-muted-foreground">Gün Streak</p>
                  </div>
                  <div className="rounded-xl border border-border bg-surface p-4">
                    <p className="text-3xl font-bold text-neon">+{Math.min(streakData.streak, 5)}</p>
                    <p className="text-[10px] text-muted-foreground">Günlük DC</p>
                  </div>
                </div>
              )}

              <div className="mt-4 w-full rounded-xl border border-border bg-surface p-3">
                <p className="text-xs font-semibold text-foreground mb-2">Streak Ödülleri</p>
                <div className="space-y-1.5 text-[11px] text-muted-foreground">
                  <div className="flex justify-between"><span>1. gün</span><span className="text-foreground">+1 DC</span></div>
                  <div className="flex justify-between"><span>2. gün</span><span className="text-foreground">+2 DC</span></div>
                  <div className="flex justify-between"><span>3-5. gün</span><span className="text-foreground">+3-5 DC</span></div>
                  <div className="flex justify-between"><span>7. gün bonusu</span><span className="text-neon font-semibold">+15 DC</span></div>
                </div>
              </div>

              <Button
                variant="neon"
                size="lg"
                className="mt-4 w-full"
                disabled={streakLoading || (streakData?.already_claimed ?? false)}
                onClick={claimDailyLogin}
              >
                {streakLoading
                  ? "Yükleniyor..."
                  : streakData?.already_claimed
                    ? "✅ Bugün Toplandı"
                    : "☀️ Günlük Bonusu Topla"}
              </Button>
            </div>
          )}

          {activeTab === "leaderboard" && (
            <div>
              <h3 className="text-sm font-semibold text-foreground mb-3">🏆 Haftalık Sıralama</h3>
              {leaderboardLoading ? (
                <div className="py-8 text-center text-sm text-muted-foreground">Yükleniyor...</div>
              ) : leaderboard.length === 0 ? (
                <div className="py-8 text-center text-sm text-muted-foreground">
                  Henüz sıralama verisi yok
                </div>
              ) : (
                <div className="space-y-2">
                  {leaderboard.map((entry, i) => {
                    const medal = i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : `${i + 1}`;
                    return (
                      <div key={entry.user_id} className="flex items-center gap-3 rounded-xl border border-border bg-surface p-3">
                        <span className="w-8 text-center text-lg font-bold">{medal}</span>
                        <div className="flex h-9 w-9 items-center justify-center rounded-full bg-accent overflow-hidden">
                          {entry.avatar_url ? (
                            <img src={entry.avatar_url} alt="" className="h-full w-full object-cover" />
                          ) : (
                            <span className="text-xs font-bold text-foreground">{entry.display_name?.[0]}</span>
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="truncate text-xs font-medium text-foreground">{entry.display_name}</p>
                          <p className="text-[10px] text-muted-foreground">{entry.badge_count} rozet</p>
                        </div>
                        <p className="text-sm font-bold text-gold">{entry.total_spent} DC</p>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </AppShell>
  );
}

