// VoiceService — modular TTS service for Deng (Coqui-ready).
//
// Provider order:
//   1. Coqui TTS (if VITE_COQUI_TTS_URL is set)
//   2. Lovable AI Gateway via the existing `dengbej-tts` edge function
//   3. Browser SpeechSynthesis (offline fallback)
//
// The Coqui endpoint is read from `import.meta.env.VITE_COQUI_TTS_URL` so it
// can be swapped without code changes. Optional auth via VITE_COQUI_TTS_KEY.
//
// Returned shape is always { audioUrl, provider } where audioUrl may be a
// blob: URL (Coqui/Lovable) or null when we fell back to SpeechSynthesis.

import { supabase } from "@/integrations/supabase/client";

export type TtsProvider = "coqui" | "lovable" | "browser";

export interface SynthesizeOptions {
  text: string;
  voice?: string;       // provider-specific voice id
  lang?: "kmr" | "ckb" | "tr" | "en";
  speakerId?: string;   // Coqui XTTS speaker reference
}

export interface SynthesizeResult {
  audioUrl: string | null;
  provider: TtsProvider;
  fallback: boolean;
}

const COQUI_URL = (import.meta.env.VITE_COQUI_TTS_URL as string | undefined)?.trim();
const COQUI_KEY = (import.meta.env.VITE_COQUI_TTS_KEY as string | undefined)?.trim();

async function tryCoqui(opts: SynthesizeOptions): Promise<SynthesizeResult | null> {
  if (!COQUI_URL) return null;
  try {
    const headers: Record<string, string> = { "Content-Type": "application/json" };
    if (COQUI_KEY) headers["Authorization"] = `Bearer ${COQUI_KEY}`;

    const res = await fetch(COQUI_URL, {
      method: "POST",
      headers,
      body: JSON.stringify({
        text: opts.text,
        language: opts.lang ?? "kmr",
        speaker_id: opts.speakerId,
        voice: opts.voice,
      }),
    });
    if (!res.ok) return null;
    const blob = await res.blob();
    return {
      audioUrl: URL.createObjectURL(blob),
      provider: "coqui",
      fallback: false,
    };
  } catch (e) {
    console.warn("[VoiceService] Coqui failed, falling back", e);
    return null;
  }
}

async function tryLovable(opts: SynthesizeOptions): Promise<SynthesizeResult | null> {
  try {
    const { data, error } = await supabase.functions.invoke("dengbej-tts", {
      body: {
        text: opts.text,
        voice: opts.voice ?? "onyx",
        lang: opts.lang ?? "tr",
      },
    });
    if (error) return null;

    // Edge function returns either an audio buffer (Response) or a JSON
    // `{ fallback: true }` object. supabase-js will give us the parsed JSON
    // when content-type is application/json, otherwise a Blob.
    if (data instanceof Blob) {
      return {
        audioUrl: URL.createObjectURL(data),
        provider: "lovable",
        fallback: false,
      };
    }
    if (data && typeof data === "object" && "fallback" in (data as object)) {
      return null;
    }
    return null;
  } catch (e) {
    console.warn("[VoiceService] Lovable TTS failed", e);
    return null;
  }
}

function browserFallback(opts: SynthesizeOptions): SynthesizeResult {
  if (typeof window === "undefined" || !("speechSynthesis" in window)) {
    return { audioUrl: null, provider: "browser", fallback: true };
  }
  const utter = new SpeechSynthesisUtterance(opts.text);
  utter.lang = opts.lang === "tr" ? "tr-TR" : "en-US";
  utter.rate = 0.9;
  window.speechSynthesis.cancel();
  window.speechSynthesis.speak(utter);
  return { audioUrl: null, provider: "browser", fallback: true };
}

export const VoiceService = {
  /** Active provider that will be tried first (for UI badges). */
  preferredProvider: (): TtsProvider => (COQUI_URL ? "coqui" : "lovable"),

  /** Synthesize text. Always resolves — never throws. */
  async synthesize(opts: SynthesizeOptions): Promise<SynthesizeResult> {
    return (
      (await tryCoqui(opts)) ||
      (await tryLovable(opts)) ||
      browserFallback(opts)
    );
  },

  /** Release a previously created blob URL. */
  revoke(url: string | null) {
    if (url && url.startsWith("blob:")) URL.revokeObjectURL(url);
  },
};

