.deng3d-emoji-only:hover { animation: deng3d-spin 1.6s linear infinite; }

/* Emoji picker orb */
.deng3d-orb {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
