.deng3d-orb:active { transform: scale(0.92); }

/* Tapback chip */
.deng3d-tapback {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px 6px 2px 4px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(40, 30, 8, 0.95), rgba(8, 6, 2, 0.95));
  border: 1px solid rgba(212, 175, 55, 0.45);
  box-shadow:
    inset 0 1px 0 rgba(255, 233, 168, 0.25),
    0 2px 6px rgba(0, 0, 0, 0.5);
