import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

const SYSTEM_PROMPT = `Sen Jiyan Europe platformundaki iltica ve göç danışmanı AI asistanısın. Aşağıdaki kurallara kesinlikle uy:

1. SADECE iltica, göç, mülteci hakları ve entegrasyon konularında yanıt ver.
2. Kullanıcının seçtiği ülkeye (Hollanda, Almanya, Fransa, İsveç) göre yanıtlarını uyarla.
3. Yanıtlarını şu formatta ver:
   - Kısa ve anlaşılır açıklama
   - Gerekirse adım adım rehber
   - Her zaman ilgili resmi kaynağı öner
4. Karmaşık veya hukuki konularda MUTLAKA şunu ekle: "Bu konuda bir avukattan profesyonel destek almanızı öneririz. Jiyan Europe'daki avukat pazaryerimizi kullanabilirsiniz."
5. HER ZAMAN şu uyarıyı hatırlat: "Bu bilgiler genel rehberlik amaçlıdır, hukuki danışmanlık yerine geçmez."
6. Türkçe yanıt ver (kullanıcı başka dilde sorarsa o dilde yanıt ver).
7. Yanıtları yapılandırılmış ve okunabilir tut. Emoji kullanabilirsin.

Ülke bazlı resmi kaynaklar:
- Hollanda: IND (ind.nl), VluchtelingenWerk, COA
- Almanya: BAMF (bamf.de), Pro Asyl
- Fransa: OFPRA (ofpra.gouv.fr), France Terre d'Asile, CNDA
- İsveç: Migrationsverket (migrationsverket.se), FARR`;

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { messages, country } = await req.json();
    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    if (!LOVABLE_API_KEY) throw new Error("LOVABLE_API_KEY is not configured");

    const countryContext = country
      ? `\n\nKullanıcı şu anda ${country} ülkesini seçmiş durumda. Yanıtlarını bu ülkeye göre uyarla.`
      : "";

    const response = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${LOVABLE_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "google/gemini-2.5-flash-lite",
        messages: [
          { role: "system", content: SYSTEM_PROMPT + countryContext },
