// Deng AI — powered by Lovable AI Gateway (Gemini).
// Streams tokens via OpenAI-compatible SSE.

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const HF_TOKEN = Deno.env.get("HUGGINGFACE_API_TOKEN");
    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");

    const { messages } = await req.json();
    if (!Array.isArray(messages) || messages.length === 0) {
      return new Response(
        JSON.stringify({ error: "messages[] required" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const systemPrompt = [
      "You are Deng — the sovereign soul of Jiyan OS. Always answer in the user's language (TR / Kurmancî / EN / NL / AR). Tone: warm, concise, authoritative, never marketing-fluff. Markdown ok.",
      "JIYAN OS: P2P sovereign platform. +777 Phone (WebRTC), Hazine (DiravCash), E-Devlet, Mîvankas/Pazar, Joogle, KEKA, Linguist. All decentralized via Filecoin/IPFS.",
      "Komutlar: 'ara/call +777 XXXX XXXX' → telefon. 'X DC gönder @user' → onaylı transfer.",
    ].join("\n");

    // Multi-modal mesaj (görsel ek) varsa HF'i atla — Gemini'ye git.
    const hasMultimodal = messages.some(
      (m: any) => m && Array.isArray(m.content),
    );

    // ─── Brain 1: Hugging Face Llama-3-8B-Instruct (free tier, primary) ───
    if (HF_TOKEN && !hasMultimodal) {
      try {
        const hfMessages = [
          { role: "system", content: systemPrompt },
          ...messages,
        ];
        const hfResp = await fetch(
          "https://router.huggingface.co/v1/chat/completions",
          {
            method: "POST",
            headers: {
              Authorization: `Bearer ${HF_TOKEN}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              model: "meta-llama/Meta-Llama-3-8B-Instruct",
              messages: hfMessages,
              stream: true,
              max_tokens: 500,
            }),
          },
        );
        if (hfResp.ok && hfResp.body) {
          return new Response(hfResp.body, {
            headers: { ...corsHeaders, "Content-Type": "text/event-stream" },
          });
        }
        const errTxt = await hfResp.text();
        console.warn("HF failed, falling back to Lovable AI:", hfResp.status, errTxt.slice(0, 200));
      } catch (e) {
        console.warn("HF call threw, falling back:", e);
      }
    }

    // ─── Brain 2: Lovable AI Gateway (Gemini fallback) ────────────────
    if (!LOVABLE_API_KEY) {
      return new Response(
        JSON.stringify({ error: "Hiçbir AI brain yapılandırılmamış" }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const upstream = await fetch(
      "https://ai.gateway.lovable.dev/v1/chat/completions",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${LOVABLE_API_KEY}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: hasMultimodal ? "google/gemini-2.5-flash" : "google/gemini-2.5-flash-lite",
          messages: [{ role: "system", content: systemPrompt }, ...messages],
          stream: true,
          max_tokens: 500,
        }),
      },
    );

    if (upstream.status === 429) {
      return new Response(
        JSON.stringify({ error: "Rate limit — biraz sonra dene." }),
        { status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }
    if (upstream.status === 402) {
      return new Response(
        JSON.stringify({ error: "AI kredisi tükendi." }),
        { status: 402, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }
    if (!upstream.ok || !upstream.body) {
      const text = await upstream.text();
