// Dengbêj TTS — narrates manifesto/quote text in the voice of a legendary
// Kurdish dengbêj (Şivan Perver-like): deep, elderly, resonant, ceremonial.
//
// We use OpenAI gpt-4o-mini-tts via the Lovable AI Gateway. The model accepts
// an `instructions` field for voice steering — we use it to push the voice
// toward an elderly, weighty, sacred tone. If the gateway/model is
// unavailable, we return `{ fallback: true }` so the client gracefully
// degrades to the browser SpeechSynthesis API.

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

const DENGBEJ_INSTRUCTIONS = `Voice persona: an elderly, legendary Kurdish Dengbêj — deep, resonant, weathered male voice in his late 60s. Picture Şivan Perver reciting a sacred doctrine.
Tone: solemn, ceremonial, mournful, proud. Like a grandfather addressing a thousand-year-old assembly.
Pacing: slow and deliberate. Lengthen vowels at the end of phrases. Pause between ideas as if catching breath.
Delivery: chest-resonant, slight tremor on long notes (vibrato of the throat), never theatrical. Speak as if every word is carved into stone.
Emotion: historical weight, collective memory, dignified sorrow turning into hope.
Volume: medium-low — let the gravity carry, do not shout.`;

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { text, voice = "onyx", lang = "tr", quote } = await req.json();
    if (!text || typeof text !== "string") {
      return new Response(JSON.stringify({ error: "missing_text" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    if (!LOVABLE_API_KEY) {
      return new Response(
        JSON.stringify({ fallback: true, reason: "no_api_key" }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // If a sacred quote is provided, recite it FIRST with a long pause, then the body.
    // The "..." gives gpt-4o-mini-tts a natural breath beat.
    const fullScript = quote && typeof quote === "string"
      ? `${quote.trim()} ... ... ${text.trim()}`
      : text.trim();

    const ttsRes = await fetch("https://ai.gateway.lovable.dev/v1/audio/speech", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${LOVABLE_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "openai/gpt-4o-mini-tts",
        voice, // onyx = deepest preset
        input: fullScript,
        instructions: DENGBEJ_INSTRUCTIONS,
        response_format: "mp3",
        speed: 0.82, // slower → more ceremonial gravitas
      }),
    });

    if (!ttsRes.ok) {
      const errText = await ttsRes.text();
      console.error("[dengbej-tts] gateway error", ttsRes.status, errText);
      return new Response(
        JSON.stringify({
          fallback: true,
          reason: "tts_unavailable",
          status: ttsRes.status,
          lang,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const audioBuffer = await ttsRes.arrayBuffer();
    return new Response(audioBuffer, {
      headers: {
        ...corsHeaders,
        "Content-Type": "audio/mpeg",
        "Cache-Control": "public, max-age=86400",
      },
    });
  } catch (err) {
    console.error("[dengbej-tts] error", err);
    return new Response(
      JSON.stringify({
        fallback: true,
        reason: "exception",
        message: err instanceof Error ? err.message : String(err),
      }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }
});

