// Ticketmaster Discovery API (free tier: 5000 calls/day)
const TM_BASE = "https://app.ticketmaster.com/discovery/v2/events.json";

// Search keywords for Kurdish, Turkish, Arab events
const SEARCH_KEYWORDS = [
  "Kurdish concert",
  "Kurdish music",
  "Kürt",
  "Turkish concert",
  "Türk müzik",
  "Arab concert",
  "Arabic music",
  "Sivan Perwer",
  "Ahmet Kaya",
  "Fairuz",
  "Dengbej",
  "Newroz",
  "Kurdish festival",
  "Arabesque",
  "Oud",
  "Darbuka",
];

// European country codes
const EU_COUNTRIES = ["NL", "DE", "FR", "SE", "GB", "BE", "AT", "DK", "NO", "CH"];

interface ExternalEvent {
  id: string;
  name: string;
  date: string;
  time?: string;
  venue?: string;
  city?: string;
  country?: string;
  image_url?: string;
  url?: string;
  source: string;
  category?: string;
  price_range?: string;
}

async function fetchTicketmasterEvents(apiKey: string): Promise<ExternalEvent[]> {
  const events: ExternalEvent[] = [];

  // Pick a subset of keywords to stay within rate limits
  const keywords = SEARCH_KEYWORDS.slice(0, 6);

  for (const keyword of keywords) {
    for (const country of EU_COUNTRIES.slice(0, 4)) {
      try {
        const params = new URLSearchParams({
          apikey: apiKey,
          keyword,
          countryCode: country,
          size: "10",
          sort: "date,asc",
          classificationName: "music",
        });

        const res = await fetch(`${TM_BASE}?${params}`);
        if (!res.ok) continue;

        const data = await res.json();
        const embedded = data?._embedded?.events;
        if (!embedded) continue;

        for (const ev of embedded) {
          const existing = events.find(e => e.id === `tm-${ev.id}`);
          if (existing) continue;

          events.push({
            id: `tm-${ev.id}`,
            name: ev.name,
            date: ev.dates?.start?.localDate ?? "",
            time: ev.dates?.start?.localTime,
            venue: ev._embedded?.venues?.[0]?.name,
            city: ev._embedded?.venues?.[0]?.city?.name,
            country: ev._embedded?.venues?.[0]?.country?.countryCode,
            image_url: ev.images?.find((img: any) => img.ratio === "16_9" && img.width > 500)?.url
              ?? ev.images?.[0]?.url,
            url: ev.url,
            source: "Ticketmaster",
            category: ev.classifications?.[0]?.genre?.name,
            price_range: ev.priceRanges
              ? `€${ev.priceRanges[0].min} - €${ev.priceRanges[0].max}`
              : undefined,
          });
        }
      } catch {
        // Skip failed requests
      }
    }
  }

  // Sort by date
  events.sort((a, b) => a.date.localeCompare(b.date));

  // Return only upcoming events
  const today = new Date().toISOString().slice(0, 10);
  return events.filter(e => e.date >= today).slice(0, 30);
}

