  { url: 'https://news.google.com/rss/search?q=kurdistan&hl=de&gl=DE&ceid=DE:de', source: 'Google News DE' },
];

function decodeEntities(s: string): string {
  return s
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'");
}

function extractText(xml: string, tag: string): string {
  const regex = new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
  const match = xml.match(regex);
  return decodeEntities((match?.[1] || match?.[2] || '').trim());
}

function extractImage(itemXml: string): string | null {
  const mediaMatch = itemXml.match(/url=["']([^"']+\.(jpg|jpeg|png|webp|gif)[^"']*)/i);
  if (mediaMatch) return mediaMatch[1];
  const encMatch = itemXml.match(/<enclosure[^>]+url=["']([^"']+)["']/i);
  if (encMatch) return encMatch[1];
  const imgMatch = itemXml.match(/<img[^>]+src=["']([^"']+)["']/i);
  if (imgMatch) return imgMatch[1];
  return null;
}

function parseRSS(xml: string): RSSItem[] {
  const items: RSSItem[] = [];
  const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(xml)) !== null) {
    const itemXml = match[1];
    const title = extractText(itemXml, 'title');
    const link = extractText(itemXml, 'link');
    if (!title || !link) continue;
    items.push({
      title,
      link,
      description: extractText(itemXml, 'description')?.replace(/<[^>]+>/g, '').slice(0, 300),
      pubDate: extractText(itemXml, 'pubDate'),
      image: extractImage(itemXml) ?? undefined,
    });
  }
  return items;
}

// Fetch full article content from the source page
async function fetchArticleContent(url: string): Promise<{ content: string | null; image: string | null }> {
  try {
    const res = await fetch(url, {
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; JiyanEurope/1.0)' },
      signal: AbortSignal.timeout(8000),
      redirect: 'follow',
    });
    if (!res.ok) return { content: null, image: null };
    const html = await res.text();

    let content = '';
    let image: string | null = null;

    const articlePatterns = [
      /<article[^>]*>([\s\S]*?)<\/article>/i,
      /<div[^>]*class="[^"]*article[_-]?(?:body|content|text)[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
      /<div[^>]*class="[^"]*entry[_-]?content[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
      /<div[^>]*class="[^"]*post[_-]?content[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
      /<div[^>]*class="[^"]*news[_-]?(?:body|content|detail)[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
      /<div[^>]*class="[^"]*field[_-]?body[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    ];

    for (const pattern of articlePatterns) {
      const match = html.match(pattern);
      if (match?.[1]) {
        content = match[1];
        break;
      }
    }

    if (!content) {
      const paragraphs: string[] = [];
      const pRegex = /<p[^>]*>([\s\S]*?)<\/p>/gi;
      let pMatch;
      while ((pMatch = pRegex.exec(html)) !== null) {
        const text = pMatch[1].replace(/<[^>]+>/g, '').trim();
        if (text.length > 30) paragraphs.push(text);
      }
      if (paragraphs.length > 0) {
        content = paragraphs.join('\n\n');
      }
    } else {
      content = content
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/p>/gi, '\n\n')
        .replace(/<\/h[1-6]>/gi, '\n\n')
        .replace(/<[^>]+>/g, '')
        .replace(/&nbsp;/g, ' ')
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'")
        .replace(/\n{3,}/g, '\n\n')
        .trim();
    }

    const ogImage = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i);
    if (ogImage) image = ogImage[1];

    if (content.length > 5000) content = content.slice(0, 5000);

    return { content: content || null, image };
  } catch {
    return { content: null, image: null };
  }
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const { createClient } = await import('https://esm.sh/@supabase/supabase-js@2');
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
    );

    let totalInserted = 0;
    const perFeedStats: Record<string, { fetched: number; inserted: number; error?: string }> = {};

    // Fetch all feeds in parallel for speed
    const feedResults = await Promise.allSettled(
      RSS_FEEDS.map(async (feed) => {
        const res = await fetch(feed.url, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (compatible; JiyanEurope/1.0; +https://jiyan.world)',
            'Accept': 'application/rss+xml, application/xml, text/xml, */*',
          },
          signal: AbortSignal.timeout(12000),
          redirect: 'follow',
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const xml = await res.text();
        return { feed, items: parseRSS(xml) };
      })
    );

    for (let i = 0; i < feedResults.length; i++) {
      const result = feedResults[i];
      const feed = RSS_FEEDS[i];

      if (result.status === 'rejected') {
        console.log(`Failed to fetch ${feed.source} (${feed.url}):`, result.reason?.message || result.reason);
        perFeedStats[feed.source] = { fetched: 0, inserted: 0, error: String(result.reason?.message || result.reason) };
        continue;
      }

      const { items } = result.value;
      perFeedStats[feed.source] = perFeedStats[feed.source] || { fetched: 0, inserted: 0 };
      perFeedStats[feed.source].fetched += items.length;

      // Take top 8 per feed; fetch full article in parallel batches
      const top = items.slice(0, 8);
      const enriched = await Promise.allSettled(
        top.map(async (item) => {
          const { content: fullContent, image: ogImage } = await fetchArticleContent(item.link);
          return { item, fullContent, ogImage };
        })
      );

      for (const r of enriched) {
        if (r.status !== 'fulfilled') continue;
        const { item, fullContent, ogImage } = r.value;

        const articleData: Record<string, unknown> = {
          url: item.link,
          title: item.title,
          image_url: item.image || ogImage || null,
          source: feed.source,
          summary: item.description || null,
          content: fullContent || null,
          published_at: item.pubDate ? new Date(item.pubDate).toISOString() : new Date().toISOString(),
        };

        const { error } = await supabase.from('news_articles').upsert(
          articleData,
          { onConflict: 'url', ignoreDuplicates: false }
        );

        if (!error) {
          totalInserted++;
          perFeedStats[feed.source].inserted++;
        } else {
          console.error(`Insert error for ${feed.source}:`, error.message);
        }
      }
    }

    return new Response(
      JSON.stringify({ success: true, inserted: totalInserted, sources: perFeedStats }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('News fetch error:', error);
    return new Response(
      JSON.stringify({ success: false, error: String(error) }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

