// Joogle — Sovereign Search Agent
// 1) Retrieves results from public SearXNG instances (no Google API, no tracking)
// 2) Boosts Kurdish-priority sources (Wikipedia ku/ckb, Rudaw, ANF Kurdî, K24, Jiyan.world)
// 3) Synthesizes a Kurmancî-first answer via Replicate DeepSeek-V3
// 4) Returns { answer, sources[] } so the UI renders inside Jiyan cards (no redirect)
//
// Privacy: We strip the user's IP (we never forward it), we send no cookies,
// we use a generic UA, and we do not log queries.

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

// Public SearXNG instances supporting JSON output. We try in order until one works.
const SEARXNG_INSTANCES = [
  "https://searx.be",
  "https://priv.au",
  "https://search.inetol.net",
  "https://baresearch.org",
  "https://search.hbubli.cc",
  "https://opnxng.com",
];

// Domains we boost / mark as Kurdish-priority sources
const KURDISH_DOMAINS = [
  "ku.wikipedia.org", "ckb.wikipedia.org", "kmr.wikipedia.org",
  "rudaw.net", "anfkurdi.com", "anfdeutsch.com", "kurdistan24.net", "k24.net",
  "jiyan.world", "kurdishinstitute.eu", "institutkurde.org", "nlka.net",
  "amidakurd.net", "diyarname.com", "jinnews.com.tr",
];

interface SourceCard {
  title: string;
  url: string;
  snippet: string;
  domain: string;
  kurdish: boolean;
}

function toCard(title: string, url: string, snippet: string): SourceCard | null {
  if (!url) return null;
  let domain = "";
  try { domain = new URL(url).hostname.replace(/^www\./, ""); } catch { return null; }
  const kurdish = KURDISH_DOMAINS.some((d) => domain.endsWith(d));
  return {
    title: (title || domain).trim(),
    url,
    snippet: (snippet || "").trim().slice(0, 280),
    domain,
    kurdish,
  };
}

async function searxngSearch(query: string, lang: string): Promise<SourceCard[]> {
  const params = new URLSearchParams({
    q: query, format: "json", language: lang, safesearch: "0",
  });
  for (const base of SEARXNG_INSTANCES) {
    try {
      const res = await fetch(`${base}/search?${params.toString()}`, {
        headers: {
          "Accept": "application/json",
          "User-Agent": "Mozilla/5.0 (compatible; JoogleAgent/1.0)",
        },
        signal: AbortSignal.timeout(6000),
      });
      if (!res.ok) continue;
      const ct = res.headers.get("content-type") ?? "";
      if (!ct.includes("json")) continue;
      const json = await res.json();
      const items = (json.results ?? []) as Array<{ title?: string; url?: string; content?: string }>;
      if (!items.length) continue;
      return items.slice(0, 12)
        .map((r) => toCard(r.title ?? "", r.url ?? "", r.content ?? ""))
        .filter((c): c is SourceCard => c !== null);
    } catch (e) {
      console.warn("searxng failed", base, (e as Error).message);
    }
  }
  return [];
}

/** DuckDuckGo HTML scrape — no API key, returns links + snippets. */
async function duckduckgoSearch(query: string): Promise<SourceCard[]> {
  try {
    const res = await fetch(`https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}`, {
      headers: {
        "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36",
        "Accept": "text/html",
      },
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) return [];
    const html = await res.text();
    const cards: SourceCard[] = [];
    // Parse result blocks: <a class="result__a" href="...">TITLE</a> ... <a class="result__snippet">SNIPPET</a>
    const blockRe = /<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>[\s\S]*?(?:class="result__snippet"[^>]*>([\s\S]*?)<\/a>)?/g;
    let m: RegExpExecArray | null;
    while ((m = blockRe.exec(html)) !== null && cards.length < 12) {
      let url = m[1];
      // DDG wraps links: //duckduckgo.com/l/?uddg=ENCODED&...
      const uddg = url.match(/[?&]uddg=([^&]+)/);
      if (uddg) url = decodeURIComponent(uddg[1]);
      if (url.startsWith("//")) url = "https:" + url;
      const title = m[2].replace(/<[^>]+>/g, "").trim();
      const snippet = (m[3] ?? "").replace(/<[^>]+>/g, "").trim();
      const card = toCard(title, url, snippet);
      if (card) cards.push(card);
    }
    return cards;
  } catch (e) {
    console.warn("ddg failed", (e as Error).message);
    return [];
  }
}

/** Wikipedia REST search — guaranteed fallback. */
async function wikipediaSearch(query: string, lang: string): Promise<SourceCard[]> {
  const langs = lang === "tr" ? ["ku", "tr", "en"] : lang === "ar" ? ["ckb", "ar", "en"] : ["ku", "en"];
  const out: SourceCard[] = [];
  for (const wl of langs) {
    try {
      const res = await fetch(
        `https://${wl}.wikipedia.org/w/api.php?action=query&list=search&format=json&origin=*&srlimit=4&srsearch=${encodeURIComponent(query)}`,
        { signal: AbortSignal.timeout(5000) },
      );
      if (!res.ok) continue;
      const json = await res.json();
      const hits = (json?.query?.search ?? []) as Array<{ title: string; snippet: string }>;
      for (const h of hits) {
        const url = `https://${wl}.wikipedia.org/wiki/${encodeURIComponent(h.title.replace(/ /g, "_"))}`;
        const snippet = h.snippet.replace(/<[^>]+>/g, "");
        const card = toCard(h.title, url, snippet);
        if (card) out.push(card);
      }
    } catch (e) {
      console.warn("wiki failed", wl, (e as Error).message);
    }
  }
  return out;
}

async function retrieve(query: string, lang: string): Promise<SourceCard[]> {
  // Run all retrievers in parallel; merge & dedupe
  const [sx, ddg, wiki] = await Promise.all([
    searxngSearch(query, lang),
    duckduckgoSearch(query),
    wikipediaSearch(query, lang),
  ]);
  const merged = [...sx, ...ddg, ...wiki];
  const seen = new Set<string>();
  const unique: SourceCard[] = [];
  for (const c of merged) {
    if (seen.has(c.url)) continue;
    seen.add(c.url);
    unique.push(c);
  }
  // Boost Kurdish-priority sources to the top
  unique.sort((a, b) => Number(b.kurdish) - Number(a.kurdish));
  return unique.slice(0, 8);
}

const SYSTEM_PROMPT = `Tu Jiyan AI yî — motora lêgerînê ya serbixwe ya "Joogle".
Pêşî bide çavkaniyên kurdî. Bersivê bi Kurmancî bide (heke pirs bi tirkî/erebî/îngilîzî be, bi heman zimanî bersiv bide).
Berhevoka kurt (3-6 risteyên zelal) çêbike — markdown bi kar bîne, agahiyan bi awayekî dorpîçkirî veguhêze.
Çavkaniyan bi formata [1], [2] referans bide. Tu sansurê nakî, lê ji propagandayê dûr disekinî. Maks 350 token.`;

async function synthesize(query: string, sources: SourceCard[]): Promise<ReadableStream> {
  const REPLICATE_API_KEY = Deno.env.get("REPLICATE_API_KEY");

  const ctx = sources.map((s, i) =>
    `[${i + 1}] ${s.title} (${s.domain})${s.kurdish ? " [çavkaniya kurdî]" : ""}\n${s.snippet}`
  ).join("\n\n");

  const userBlock = `Pirs: ${query}\n\nEncamên lêgerînê:\n${ctx}\n\nLi gor van çavkaniyan bersiveke kurt û rast amade bike. Çavkaniyan bi [1], [2]... referans bike.`;

  const prompt = `<|system|>\n${SYSTEM_PROMPT}\n<|user|>\n${userBlock}\n<|assistant|>\n`;

  // Try Replicate DeepSeek-V3 first; on any failure, fall back to Lovable AI Gateway.
  if (REPLICATE_API_KEY) {
    try {
      return await synthesizeReplicate(prompt, sources, REPLICATE_API_KEY);
    } catch (e) {
      console.warn("Replicate synth failed, falling back to Lovable AI:", e instanceof Error ? e.message : e);
    }
  }
  return synthesizeLovableAI(userBlock, sources);
}

async function synthesizeLovableAI(userBlock: string, sources: SourceCard[]): Promise<ReadableStream> {
  const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
  if (!LOVABLE_API_KEY) throw new Error("No synthesis backend available");

  const upstream = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${LOVABLE_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: "google/gemini-2.5-flash",
      stream: true,
      messages: [
        { role: "system", content: SYSTEM_PROMPT },
        { role: "user", content: userBlock },
      ],
    }),
  });
  if (!upstream.ok || !upstream.body) {
    const t = await upstream.text().catch(() => "");
    throw new Error(`Lovable AI failed ${upstream.status}: ${t}`);
  }

  const reader = upstream.body.getReader();
  const decoder = new TextDecoder();
  const encoder = new TextEncoder();

  return new ReadableStream({
    async start(controller) {
      controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: "sources", sources })}\n\n`));
      let buf = "";
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          buf += decoder.decode(value, { stream: true });
          let nl;
          while ((nl = buf.indexOf("\n")) !== -1) {
            const line = buf.slice(0, nl).replace(/\r$/, "");
            buf = buf.slice(nl + 1);
            if (!line.startsWith("data: ")) continue;
            const data = line.slice(6).trim();
            if (data === "[DONE]") {
              controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: "done" })}\n\n`));
              controller.close();
              return;
            }
            try {
              const json = JSON.parse(data);
              const delta = json.choices?.[0]?.delta?.content;
              if (delta) {
                controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: "delta", text: delta })}\n\n`));
              }
            } catch { /* ignore parse errors */ }
          }
        }
        controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: "done" })}\n\n`));
        controller.close();
      } catch (e) {
        console.error("lovable-ai stream error", e);
        controller.error(e);
      }
    },
  });
}

async function synthesizeReplicate(prompt: string, sources: SourceCard[], REPLICATE_API_KEY: string): Promise<ReadableStream> {

  const create = await fetch(
    `https://api.replicate.com/v1/models/deepseek-ai/deepseek-v3/predictions`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${REPLICATE_API_KEY}`,
        "Content-Type": "application/json",
        Prefer: "wait=1",
      },
      body: JSON.stringify({
        stream: true,
        input: { prompt, max_tokens: 350, temperature: 0.5, top_p: 0.9 },
      }),
    },
  );

  if (!create.ok) {
    const t = await create.text();
    throw new Error(`Replicate create failed ${create.status}: ${t}`);
  }
  const prediction = await create.json();
  const streamUrl: string | undefined = prediction.urls?.stream;
  if (!streamUrl) throw new Error("No stream URL");

  const upstream = await fetch(streamUrl, { headers: { Accept: "text/event-stream" } });
  if (!upstream.ok || !upstream.body) throw new Error("Stream connect failed");

  const reader = upstream.body.getReader();
  const decoder = new TextDecoder();
  const encoder = new TextEncoder();

  return new ReadableStream({
    async start(controller) {
      // First, emit the sources as a JSON metadata frame
      controller.enqueue(encoder.encode(
        `data: ${JSON.stringify({ type: "sources", sources })}\n\n`,
      ));

      let buf = "";
      let eventName = "output";
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          buf += decoder.decode(value, { stream: true });
          let nl;
          while ((nl = buf.indexOf("\n")) !== -1) {
            const line = buf.slice(0, nl).replace(/\r$/, "");
            buf = buf.slice(nl + 1);
            if (line.startsWith("event: ")) { eventName = line.slice(7).trim(); continue; }
            if (line.startsWith("data: ")) {
              const data = line.slice(6);
              if (eventName === "output" && data) {
                controller.enqueue(encoder.encode(
                  `data: ${JSON.stringify({ type: "delta", text: data })}\n\n`,
                ));
              } else if (eventName === "done") {
                controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: "done" })}\n\n`));
                controller.close();
                return;
              }
            }
          }
        }
        controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: "done" })}\n\n`));
        controller.close();
      } catch (e) {
        console.error("synthesize stream error", e);
        controller.error(e);
      }
    },
  });
}

function detectLang(q: string): string {
  if (/[ç̧ğıİöşüÇĞŞÜ]/.test(q)) return "tr";
  if (/[ا-ي]/.test(q)) return "ar";
  // Default: try Kurmancî/English broad index
  return "en";
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { query } = await req.json();
    if (!query || typeof query !== "string" || query.trim().length < 2) {
      return new Response(JSON.stringify({ error: "Query too short" }), {
        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    const q = query.trim().slice(0, 240);

    const sources = await retrieve(q, detectLang(q));
    if (sources.length === 0) {
      return new Response(JSON.stringify({ error: "No results from sovereign index" }), {
        status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

