import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { query, city, type } = await req.json();
    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    if (!LOVABLE_API_KEY) throw new Error("LOVABLE_API_KEY not configured");

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    if (type === "search") {
      // AI-powered search: parse intent from natural language
      const response = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${LOVABLE_API_KEY}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: "google/gemini-2.5-flash-lite",
          messages: [
            {
              role: "system",
              content: `You parse user service search queries in Turkish/Kurdish/Dutch/German/English. Extract: category (one of: cleaning, plumbing, painting, electric, moving, barber, catering, tutoring, general), urgency (urgent/normal), max_price (number or null). Return JSON only: {"category":"...","urgency":"...","max_price":null}`,
            },
            { role: "user", content: query },
          ],
          tools: [
            {
              type: "function",
              function: {
                name: "parse_search",
                description: "Parse search intent",
                parameters: {
                  type: "object",
                  properties: {
                    category: { type: "string", enum: ["cleaning", "plumbing", "painting", "electric", "moving", "barber", "catering", "tutoring", "general"] },
                    urgency: { type: "string", enum: ["urgent", "normal"] },
                    max_price: { type: "number", nullable: true },
                  },
                  required: ["category", "urgency"],
                  additionalProperties: false,
                },
              },
            },
          ],
          tool_choice: { type: "function", function: { name: "parse_search" } },
        }),
      });

      if (!response.ok) {
        const t = await response.text();
        console.error("AI error:", response.status, t);
        return new Response(JSON.stringify({ error: "AI error" }), {
          status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      const aiData = await response.json();
      const toolCall = aiData.choices?.[0]?.message?.tool_calls?.[0];
      let parsed = { category: "general", urgency: "normal", max_price: null as number | null };
      if (toolCall?.function?.arguments) {
        try { parsed = JSON.parse(toolCall.function.arguments); } catch {}
      }

      // Query services based on parsed intent
      let q = supabase.from("services").select("*").eq("is_active", true);
      if (parsed.category !== "general") q = q.eq("category", parsed.category);
      if (city) q = q.eq("city", city);
      if (parsed.max_price) q = q.lte("price", parsed.max_price);
      if (parsed.urgency === "urgent") q = q.eq("is_available", true);
      q = q.order("rating", { ascending: false }).limit(20);

      const { data: services } = await q;
      return new Response(JSON.stringify({ parsed, services: services || [] }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (type === "suggestions") {
      // Get smart suggestions based on city activity
      const { data: availableServices } = await supabase
        .from("services")
        .select("category, city, is_available, rating")
        .eq("is_active", true)
        .eq("city", city || "Arnhem")
        .limit(100);

      const available = (availableServices || []).filter(s => s.is_available);
      const categoryCount: Record<string, number> = {};
      const urgentCount: Record<string, number> = {};

      for (const s of availableServices || []) {
        categoryCount[s.category] = (categoryCount[s.category] || 0) + 1;
      }
      for (const s of available) {
        urgentCount[s.category] = (urgentCount[s.category] || 0) + 1;
      }

      const suggestions = [];

      if (available.length > 0) {
        const topCat = Object.entries(urgentCount).sort((a, b) => b[1] - a[1])[0];
        if (topCat) {
          suggestions.push({
            icon: "🔥",
            text: `Yakınınızda ${topCat[1]} ${topCat[0]} mevcut`,
            type: "available",
            category: topCat[0],
          });
        }
      }

      const topRated = (availableServices || []).filter(s => (s.rating || 0) >= 4.5);
      if (topRated.length > 0) {
        suggestions.push({
          icon: "⭐",
          text: `Bugünün en yüksek puanlı ${topRated.length} hizmeti`,
          type: "top_rated",
        });
      }

      if (available.length > 0) {
        suggestions.push({
          icon: "⚡",
          text: `${available.length} hizmet şu an müsait`,
          type: "urgent",
        });
      }

      return new Response(JSON.stringify({ suggestions }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    return new Response(JSON.stringify({ error: "Unknown type" }), {
      status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    console.error("marketplace-ai error:", e);
    return new Response(JSON.stringify({ error: e instanceof Error ? e.message : "Unknown" }), {
      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

