// AI moderation for KEKA captions.
// Hybrid policy:
//  - Profanity / hate / sexual minors / explicit slurs → auto-hide
//  - Violence / mild adult / politically sensitive → flag for admin
//  - Mark adult content (non-violating but mature) → set is_adult=true

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const LOVABLE_AI_URL = "https://ai.gateway.lovable.dev/v1/chat/completions";

interface Body {
  video_id: string;
  caption: string;
}

interface ModerationResult {
  status: "safe" | "flagged" | "auto_hidden";
  is_adult: boolean;
  reason: string;
  categories: string[];
}

const SYSTEM = `You are a content moderator for a Kurdish social video app.
Classify the caption text. Respond ONLY as compact JSON:
{"action":"safe|flag|auto_hide","is_adult":bool,"reason":"<short>","categories":["..."]}

Rules:
- "auto_hide": severe profanity, slurs, hate speech, sexual content involving minors, doxxing, explicit threats.
- "flag": violence references, drugs, mild adult innuendo, politically sensitive but not violating.
- "safe": everything else.
- "is_adult": true if mature themes (sexual innuendo, alcohol, gore) even if not violating.
Languages: Turkish, Kurdish, Arabic, English. Be culturally aware (Kurdish dialects ok).
Never refuse — always return JSON.`;

async function moderate(caption: string): Promise<ModerationResult> {
  const trimmed = (caption || "").trim();
  if (!trimmed) {
    return { status: "safe", is_adult: false, reason: "Empty caption", categories: [] };
  }

  const apiKey = Deno.env.get("LOVABLE_API_KEY");
  if (!apiKey) throw new Error("LOVABLE_API_KEY missing");

  const res = await fetch(LOVABLE_AI_URL, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: "google/gemini-2.5-flash-lite",
      messages: [
        { role: "system", content: SYSTEM },
        { role: "user", content: `Caption: """${trimmed.slice(0, 500)}"""` },
      ],
      response_format: { type: "json_object" },
    }),
  });

  if (!res.ok) {
    const text = await res.text();
    console.error("AI gateway error:", res.status, text);
    // Default to safe on AI failure to avoid false positives
    return { status: "safe", is_adult: false, reason: "AI unavailable", categories: [] };
  }

  const data = await res.json();
  const raw = data.choices?.[0]?.message?.content ?? "{}";
  let parsed: any = {};
  try {
    parsed = JSON.parse(raw);
  } catch {
    parsed = {};
  }

  const action = parsed.action === "auto_hide" ? "auto_hidden"
    : parsed.action === "flag" ? "flagged"
    : "safe";

  return {
    status: action,
    is_adult: !!parsed.is_adult,
    reason: String(parsed.reason || "").slice(0, 200),
    categories: Array.isArray(parsed.categories) ? parsed.categories.slice(0, 6) : [],
  };
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const body: Body = await req.json();
    if (!body.video_id) {
      return new Response(JSON.stringify({ error: "video_id required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const result = await moderate(body.caption || "");

    // Apply moderation via service role (bypasses RLS)
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    const SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const rpc = await fetch(`${SUPABASE_URL}/rest/v1/rpc/keka_apply_moderation`, {
      method: "POST",
      headers: {
        "apikey": SERVICE_KEY,
        "Authorization": `Bearer ${SERVICE_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        _video_id: body.video_id,
        _status: result.status,
        _reason: result.reason,
        _is_adult: result.is_adult,
      }),
    });

    if (!rpc.ok) {
      console.error("RPC error:", await rpc.text());
    }

    return new Response(JSON.stringify({ success: true, ...result }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    console.error("moderate-keka-content error:", e);
    return new Response(JSON.stringify({ error: String(e) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

