// Replicate DeepSeek streaming chat
// Streams DeepSeek-V3 responses as OpenAI-compatible SSE so the existing
// useJiyanAI parser keeps working unchanged.

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const SYSTEM_PROMPT = `Tu Jiyan AI yî — alîkarê fermî yê Jiyan OS, pergala dîjîtal a serbixwe ya nasnameya kurdî.

# Nasname / Identity
Tu OS-eke serbixwe yî ji bo gelê kurd. Tu ne li jêr fermana tu dewlet, sansur an pergaleke navendî yî. Tu nûnerê çand, dîrok, ziman û jiyana kurdî yî — bi rûmet, bi rastî, bi germî.

# Ziman / Language priority
1. Kurmancî (latînî) — zimanê te yê bingehîn. Bi awayekî xwezayî bersiv bide.
2. Soranî — heke bikarhêner Soranî bi alfabeya erebî binivîse.
3. Tirkî / English / العربية — tenê heke bikarhêner bi wan zimanan binivîse.
Çand û dîroka kurdî her tim pêşîn e: Newroz, dengbêjî, Mem û Zîn, Ehmedê Xanî, Cizîrî, Şêx Seîd, Qazî Mihemed, Komara Mehabad, Kobanê, hwd.

# Şêwe / Style
Kurt, zelal, germ. Markdown bi kar bîne. Maks 500 token. Heke pirs siyasî be: agahiyên dîrokî yên rast bide, ji propagandayê dûr bisekine, lê tu jî xwe sansur neke li ser dîroka kurdî.

# Exlaq
Tu li dijî tundî, nefret an zerarê yî. Lê tu mafê axaftina li ser dîrok, çand û nasnameya kurdî diparêzî.`;

// DeepSeek-V3 hosted on Replicate
const REPLICATE_MODEL = "deepseek-ai/deepseek-v3";

function toPrompt(messages: Array<{ role: string; content: string }>) {
  // DeepSeek chat template
  const lines = [`<|system|>\n${SYSTEM_PROMPT}`];
  for (const m of messages) {
    if (m.role === "user") lines.push(`<|user|>\n${m.content}`);
    else if (m.role === "assistant") lines.push(`<|assistant|>\n${m.content}`);
  }
  lines.push(`<|assistant|>\n`);
  return lines.join("\n");
}

function sseChunk(text: string) {
  const payload = { choices: [{ delta: { content: text } }] };
  return `data: ${JSON.stringify(payload)}\n\n`;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { messages } = await req.json();
    const REPLICATE_API_KEY = Deno.env.get("REPLICATE_API_KEY");
    if (!REPLICATE_API_KEY) throw new Error("REPLICATE_API_KEY missing");

    // 1. Create prediction with stream=true
    const create = await fetch(`https://api.replicate.com/v1/models/${REPLICATE_MODEL}/predictions`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${REPLICATE_API_KEY}`,
        "Content-Type": "application/json",
        Prefer: "wait=1",
      },
      body: JSON.stringify({
        stream: true,
        input: {
          prompt: toPrompt(messages),
          max_tokens: 500,
          temperature: 0.7,
          top_p: 0.9,
        },
      }),
    });

    if (create.status === 401) {
      return new Response(JSON.stringify({ error: "Replicate API key invalid" }), {
        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    if (create.status === 402 || create.status === 429) {
      return new Response(JSON.stringify({ error: "Replicate quota / rate limit" }), {
        status: create.status, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    if (!create.ok) {
      const t = await create.text();
      console.error("Replicate create error", create.status, t);
      return new Response(JSON.stringify({ error: "Replicate create failed" }), {
        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const prediction = await create.json();
    const streamUrl: string | undefined = prediction.urls?.stream;
    if (!streamUrl) {
      return new Response(JSON.stringify({ error: "No stream URL from Replicate" }), {
        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // 2. Connect to Replicate SSE and re-emit as OpenAI-compatible SSE
    const upstream = await fetch(streamUrl, { headers: { Accept: "text/event-stream" } });
    if (!upstream.ok || !upstream.body) {
      return new Response(JSON.stringify({ error: "Stream connect failed" }), {
        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const reader = upstream.body.getReader();
    const decoder = new TextDecoder();
    const encoder = new TextEncoder();

    const out = new ReadableStream({
      async start(controller) {
        let buf = "";
        let eventName = "output";
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            buf += decoder.decode(value, { stream: true });
            let nl;
            while ((nl = buf.indexOf("\n")) !== -1) {
              const line = buf.slice(0, nl).replace(/\r$/, "");
              buf = buf.slice(nl + 1);
              if (line.startsWith("event: ")) { eventName = line.slice(7).trim(); continue; }
              if (line.startsWith("data: ")) {
                const data = line.slice(6);
                if (eventName === "output" && data) {
                  controller.enqueue(encoder.encode(sseChunk(data)));
                } else if (eventName === "done") {
                  controller.enqueue(encoder.encode("data: [DONE]\n\n"));
                  controller.close();
                  return;
                }
              }
            }
          }
          controller.enqueue(encoder.encode("data: [DONE]\n\n"));
          controller.close();
        } catch (e) {
          console.error("stream error", e);
          controller.error(e);
        }
      },
    });

    return new Response(out, {
      headers: { ...corsHeaders, "Content-Type": "text/event-stream" },
    });
  } catch (e) {
    console.error("replicate-deepseek error:", e);
    return new Response(JSON.stringify({ error: e instanceof Error ? e.message : "Unknown" }), {
      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

