const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { audioUrl, translateTo } = await req.json();

    if (!audioUrl || typeof audioUrl !== "string") {
      return new Response(JSON.stringify({ error: "audioUrl required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // SSRF protection: only allow https URLs from the project's Supabase storage origin
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
    let parsed: URL;
    try {
      parsed = new URL(audioUrl);
    } catch {
      return new Response(JSON.stringify({ error: "Invalid audioUrl" }), {
        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    const allowedHost = SUPABASE_URL ? new URL(SUPABASE_URL).host : "";
    const isAllowed =
      parsed.protocol === "https:" &&
      allowedHost &&
      parsed.host === allowedHost &&
      parsed.pathname.startsWith("/storage/v1/object/");
    if (!isAllowed) {
      return new Response(JSON.stringify({ error: "audioUrl must be a Supabase storage URL" }), {
        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    if (!LOVABLE_API_KEY) throw new Error("LOVABLE_API_KEY not configured");

    // Download audio and convert to base64
    console.log("Fetching audio from:", audioUrl);
    const audioResp = await fetch(audioUrl, {
      headers: { "Accept": "*/*" },
    });
    console.log("Audio fetch status:", audioResp.status);
    if (!audioResp.ok) throw new Error(`Failed to fetch audio file: ${audioResp.status} ${audioResp.statusText}`);

    const audioBuffer = await audioResp.arrayBuffer();
    const uint8 = new Uint8Array(audioBuffer);

    // Chunked base64 encoding to avoid stack overflow
    let binary = "";
    const chunkSize = 8192;
    for (let i = 0; i < uint8.length; i += chunkSize) {
      binary += String.fromCharCode(...uint8.slice(i, i + chunkSize));
    }
    const base64Audio = btoa(binary);

    // Detect content type
    const contentType = audioResp.headers.get("content-type") || "audio/webm";

    const langMap: Record<string, string> = {
      TR: "Turkish", KU: "Kurdish (Kurmanji)", AR: "Arabic",
      EN: "English", DE: "German", FR: "French", NL: "Dutch", SE: "Swedish",
    };

    const translateInstruction = translateTo
      ? ` Then translate the transcription to ${langMap[translateTo] || translateTo}. Return in this format:\n\nOriginal: [transcribed text]\nTranslation: [translated text]`
      : " Return ONLY the transcribed text, nothing else.";

    const response = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${LOVABLE_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "google/gemini-2.5-flash",
        messages: [
          {
            role: "system",
            content: `You are a transcription assistant. Transcribe the audio message accurately. Detect the language automatically.${translateInstruction}`,
          },
          {
            role: "user",
            content: [
              {
                type: "input_audio",
                input_audio: {
                  data: base64Audio,
                  format: contentType.includes("webm") ? "webm" : contentType.includes("ogg") ? "ogg" : "wav",
                },
              },
              {
                type: "text",
                text: "Transcribe this voice message.",
              },
            ],
          },
        ],
      }),
    });

    if (!response.ok) {
      if (response.status === 429) {
        return new Response(JSON.stringify({ error: "Rate limit exceeded" }), {
          status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      if (response.status === 402) {
        return new Response(JSON.stringify({ error: "Credits exhausted" }), {
          status: 402, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      const errText = await response.text();
      console.error("AI gateway error:", response.status, errText);
      throw new Error(`AI gateway error: ${response.status}`);
    }

    const data = await response.json();
    const result = data.choices?.[0]?.message?.content?.trim() || "";

    // Parse result
    let transcript = result;
    let translation = null;

    if (translateTo && result.includes("Translation:")) {
      const parts = result.split("Translation:");
      transcript = parts[0].replace("Original:", "").trim();
      translation = parts[1].trim();
    }

    return new Response(JSON.stringify({ transcript, translation, translateTo }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    console.error("transcribe error:", e);
    return new Response(JSON.stringify({ error: e instanceof Error ? e.message : "Unknown error" }), {
      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

